    ('88888888-0000-0000-0000-000000005702', HIL, 'dso2.v57@example.invalid', 'V57 DSO Two', 'dso'),
    ('88888888-0000-0000-0000-000000005703', WES, 'dso.wes.v57@example.invalid', 'V57 DSO Westville', 'dso'),
    ('88888888-0000-0000-0000-000000005704', v_union, 'pdso.v57@example.invalid', 'V57 Provincial DSO', 'dso'),
    ('88888888-0000-0000-0000-000000005705', V57, 'teacher.v57@example.invalid', 'V57 Teacher', 'coach'),
    ('88888888-0000-0000-0000-000000005706', NULL, 'support.v57@example.invalid', 'V57 Support', 'platformadmin'),
    ('88888888-0000-0000-0000-000000005707', '57570000-0000-0000-0000-000000000002', 'teacher2.v57@example.invalid', 'V57 Far Teacher', 'coach'),
    ('88888888-0000-0000-0000-000000005708', '57570000-0000-0000-0000-000000000003', 'dso.far.v57@example.invalid', 'V57 Far DSO', 'dso'),
    ('88888888-0000-0000-0000-000000005709', '57570000-0000-0000-0000-000000000003', 'teacher3.v57@example.invalid', 'V57 Far Teacher Two', 'coach'),
    ('88888888-0000-0000-0000-000000005710', '57570000-0000-0000-0000-000000000003', 'dso2.far.v57@example.invalid', 'V57 Far DSO Two', 'dso');
  INSERT INTO role_assignment (person_id, role, school_id, team_code) VALUES
    ('88888888-0000-0000-0000-000000005702', 'dso', HIL, NULL),
    ('88888888-0000-0000-0000-000000005703', 'dso', WES, NULL),
    ('88888888-0000-0000-0000-000000005704', 'dso', v_union, NULL),
    ('88888888-0000-0000-0000-000000005705', 'coach', V57, '1XI'),
    ('88888888-0000-0000-0000-000000005707', 'coach', '57570000-0000-0000-0000-000000000002', '1XI'),
    ('88888888-0000-0000-0000-000000005708', 'dso', '57570000-0000-0000-0000-000000000003', NULL),
    ('88888888-0000-0000-0000-000000005709', 'coach', '57570000-0000-0000-0000-000000000003', '1XI'),
    ('88888888-0000-0000-0000-000000005710', 'dso', '57570000-0000-0000-0000-000000000003', NULL);
  RETURN v_union;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Where a concern went, by its reference: the holding institution's code,
-- what it is about, and whether it is unheld. The claim is about the row,
-- which no reader's policy could tell from a hidden one.
CREATE OR REPLACE FUNCTION _route_57(p_ref text) RETURNS text AS $$
  SELECT format('%s/%s/%s', t.code, c.about_kind, c.unheld::text)
    FROM safeguarding_concern c JOIN school t ON t.id = c.tenant_id WHERE c.reference = p_ref
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _concern_57(p_ref text) RETURNS uuid AS $$
  SELECT c.id FROM safeguarding_concern c WHERE c.reference = p_ref
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The two clocks and a share's end need time to pass; the record's own
-- triggers refuse the edit, so they are stepped round for one statement.
CREATE OR REPLACE FUNCTION _age_concern_57(p_id uuid, p_hours integer) RETURNS void AS $$
BEGIN
  ALTER TABLE safeguarding_concern DISABLE TRIGGER safeguarding_concern_fixed;
  UPDATE safeguarding_concern SET raised_at = now() - make_interval(hours => p_hours) WHERE id = p_id;
  ALTER TABLE safeguarding_concern ENABLE TRIGGER safeguarding_concern_fixed;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _expire_share_57(p_id uuid) RETURNS void AS $$
BEGIN
  ALTER TABLE safeguarding_share DISABLE TRIGGER safeguarding_share_append_only;
  UPDATE safeguarding_share SET shared_at = now() - interval '2 hours', open_until = now() - interval '1 minute' WHERE id = p_id;
  ALTER TABLE safeguarding_share ENABLE TRIGGER safeguarding_share_append_only;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- SG-9: a notice to one person, as the system writes one. 'ok' or 'refused'.
CREATE OR REPLACE FUNCTION _notice_57(p_person uuid, p_kind text) RETURNS text AS $$
BEGIN
  INSERT INTO notification (school_id, scope_level, kind, title, body, recipient_id)
    VALUES ('11111111-1111-1111-1111-111111111111', 'school', p_kind, 'Verify 057', 'Verify 057', p_person);
  RETURN 'ok';
EXCEPTION WHEN check_violation THEN
  RETURN 'refused';
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The owner's key with the capability row granted back, and taken away again:
-- the platform-wide cut, on its own.
CREATE OR REPLACE FUNCTION _owner_grant_57(p_on boolean) RETURNS void AS $$
BEGIN
  IF p_on THEN
    INSERT INTO role_capability (role, capability) VALUES ('superadmin', 'safeguarding.concern.read') ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM role_capability WHERE role = 'superadmin' AND capability LIKE 'safeguarding.%';
  END IF;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A support session as `dso`, which support_access_begin() refuses to issue:
-- written by the owner as that function would have, for an account with NO
-- platform-wide assignment, so the support cut is tested on its own. p_end
-- ends it again (the assignment stays live), which is the control.
CREATE OR REPLACE FUNCTION _support_dso_57(p_end boolean) RETURNS void AS $$
DECLARE v_asg uuid;
BEGIN
  IF p_end THEN
    UPDATE support_access SET ended_at = now(), ended_by = actor_id
     WHERE actor_id = '88888888-0000-0000-0000-000000005706' AND ended_at IS NULL;
    RETURN;
  END IF;
  INSERT INTO role_assignment (person_id, role, school_id, active, valid_from, expires_at)
    VALUES ('88888888-0000-0000-0000-000000005706', 'dso', '11111111-1111-1111-1111-111111111111', true, current_date, now() + interval '1 hour')
    RETURNING id INTO v_asg;
  INSERT INTO support_access (actor_id, school_id, role, reason, assignment_id, expires_at)
    VALUES ('88888888-0000-0000-0000-000000005706', '11111111-1111-1111-1111-111111111111', 'dso',
            'Verify 057: a session support may not be issued', v_asg, now() + interval '1 hour');
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/59 (section 37). Two fixtures for the signed-out read path, written as
-- the owner: Hilton 1XI v Westville 1XI (both on SCRBRD, live) and Hilton 1XI
-- v Kearsney College (not on SCRBRD, finished, its names typed). Five boys of
-- their own, so nothing earlier sections did to the seed's consents can
-- decide an answer here: one to consent, one to consent and mark, one with
-- nothing recorded, one fourteen or so playing up in the 1st XI (names off
-- for his own age group), and a Westville boy who consents while Westville
-- has not published. Each consenting boy has a verified guardian of his own.
-- Returns the ids, by name.
CREATE OR REPLACE FUNCTION _seed_59() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  SCORER uuid := '88888888-0000-0000-0000-000000000006';
  ids jsonb := '{}';
  r record;
  v_p uuid; v_u uuid; v_a uuid; m_on uuid; m_off uuid;
  s int := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('named',  'Andile Named',     HIL, 17, true),
      ('marked', 'Brandon Marked',   HIL, 17, true),
      ('none',   'Craig Nothing',    HIL, 16, false),
      ('up',     'Dumisani Playsup', HIL, 13, true),
      ('wes',    'Ethan Westville',  WES, 17, true)) AS v(k, nm, school, age, consent)
  LOOP
    INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
    VALUES (r.school, '1XI', r.nm, split_part(r.nm, ' ', 2), 90 + s, 'batter',
            current_date - make_interval(years => r.age) - interval '40 days')
    RETURNING id INTO v_p;
    s := s + 1;
    ids := ids || jsonb_build_object(r.k, v_p);
    IF r.consent THEN
      INSERT INTO app_user (school_id, email, name, role)
      VALUES (r.school, 'guardian59.' || r.k || '@example.invalid', 'Parent ' || r.k, 'guardian') RETURNING id INTO v_u;
      INSERT INTO role_assignment (person_id, role, school_id) VALUES (v_u, 'guardian', r.school) RETURNING id INTO v_a;
      INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                      consent_state, consent_version, consent_at, created_by, valid_from)
      VALUES (v_a, v_p, 'parent', 'verified', v_u, now() - interval '30 days', 'granted', 'popia-2026-01',
              now() - interval '30 days', v_u, current_date - 30);
      ids := ids || jsonb_build_object('g_' || r.k, v_u);
    END IF;
  END LOOP;

  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', WES, '1XI', 'Westville Boys'' High 1XI', now() - interval '1 hour', 'cricket', 'T10', 10, 'live')
  RETURNING id INTO m_on;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', 'Kearsney College 1XI', now() - interval '3 days', 'cricket', 'T5', 5, 'complete')
  RETURNING id INTO m_off;
  ids := ids || jsonb_build_object('m_on', m_on, 'm_off', m_off);

  -- M_ON: the squads (four Hilton boys and a typed one; the Westville boy),
  -- two deliveries, a Law 41 suspension, a retirement "hurt".
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq,
                          client_ts, kind, payload, ball_type, value, striker_id, non_striker_id, bowler_id, seg, dismissal)
  VALUES
    (m_on, HIL, 1, 1, 0, SCORER, 'v59', 'v59-on-1', 1, now(), 'innings_start', jsonb_build_object(
       'battingTeam', '1XI', 'bowlingTeam', 'Westville Boys'' High 1XI', 'overs', 10, 'twelfthMan', 'Twelfth Fiftynine',
       'captureProfile', 'full',
       'squad', jsonb_build_array(jsonb_build_object('id', ids->>'named', 'name', 'Andile Named'),
                                  jsonb_build_object('id', ids->>'marked', 'name', 'Brandon Marked'),
                                  jsonb_build_object('id', ids->>'none', 'name', 'Craig Nothing'),
                                  jsonb_build_object('id', ids->>'up', 'name', 'Dumisani Playsup'),
                                  jsonb_build_object('id', 'Typed Fiftynine', 'name', 'Typed Fiftynine')),
       'bowlingSquad', jsonb_build_array(jsonb_build_object('id', ids->>'wes', 'name', 'Ethan Westville'))),
     NULL, NULL, NULL, NULL, NULL, NULL, NULL),
    (m_on, HIL, 2, 1, 0, SCORER, 'v59', 'v59-on-2', 2, now(), 'batters', '{}', NULL, NULL,
       (ids->>'named')::uuid, (ids->>'marked')::uuid, NULL, NULL, NULL),
    (m_on, HIL, 3, 1, 0, SCORER, 'v59', 'v59-on-3', 3, now(), 'bowler', '{}', NULL, NULL, NULL, NULL, (ids->>'wes')::uuid, NULL, NULL),
    (m_on, HIL, 4, 1, 0, SCORER, 'v59', 'v59-on-4', 4, now(), 'ball', '{"shot": "drive"}', 'run', 4,
       (ids->>'named')::uuid, (ids->>'marked')::uuid, (ids->>'wes')::uuid, 9, NULL),
    (m_on, HIL, 5, 1, 0, SCORER, 'v59', 'v59-on-5', 5, now(), 'ball', jsonb_build_object('fielder', 'Typed Fiftynine'), 'W', 0,
       (ids->>'named')::uuid, (ids->>'marked')::uuid, (ids->>'wes')::uuid, NULL, 'caught'),
    (m_on, HIL, 6, 1, 0, SCORER, 'v59', 'v59-on-6', 6, now(), 'bowler_suspended',
       '{"reason": "dangerous_bowling", "scope": "innings"}', NULL, NULL, NULL, NULL, (ids->>'wes')::uuid, NULL, NULL),
    (m_on, HIL, 7, 1, 0, SCORER, 'v59', 'v59-on-7', 7, now(), 'retire',
       jsonb_build_object('batter', ids->>'marked', 'reason', 'hurt'), NULL, NULL, NULL, NULL, NULL, NULL, NULL);

  -- M_OFF: Hilton against typed names.
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq,
                          client_ts, kind, payload, ball_type, value, striker_id, bowler_id)
  VALUES
    (m_off, HIL, 1, 1, 0, SCORER, 'v59', 'v59-off-1', 1, now(), 'innings_start', jsonb_build_object(
       'battingTeam', '1XI', 'bowlingTeam', 'Kearsney College 1XI', 'overs', 5,
       'squad', jsonb_build_array(jsonb_build_object('id', ids->>'named', 'name', 'Andile Named')),
       'bowlingSquad', jsonb_build_array('Kearsney Bowlerone')), NULL, NULL, NULL, NULL),
    (m_off, HIL, 2, 1, 0, SCORER, 'v59', 'v59-off-2', 2, now(), 'ball', '{"bowler": "Kearsney Bowlerone"}', 'run', 1,
       (ids->>'named')::uuid, NULL);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/60 (section 38). SCRBRD-110 phase 1: the nets band and the consent.
-- Written as the owner and rolled back. Four U15A boys of their own at
-- Hilton, so nothing earlier sections did to the seed's people can decide an
-- answer here: a bowler (16) with no health consent, a boy about to turn
-- eighteen, a boy for the constructed EWMA series and one more. Their own
-- coach, a coach of another side, a physio, a strength-and-conditioning
-- coach, a team-mate, an office, a platform account for support, the
-- bowler's own account (self-access), the turning boy's account, and two
-- parents: the turning boy's (her link is made in the section, through
-- guardian_link_establish(), so it ends where that function ends it: open
-- while he is at school, since db/62) and one of the fourth boy. A training
-- session today, a match the bowler bowled in two days ago (thirteen deliveries: twelve legal and a
-- wide), and a hamstring on his record with a physio's note.
-- workload_monitoring is NOT granted here: the section proves the switch first.
CREATE OR REPLACE FUNCTION _seed_60() RETURNS jsonb AS $$
DECLARE
  HIL    uuid := '11111111-1111-1111-1111-111111111111';
  SCORER uuid := '88888888-0000-0000-0000-000000000006';
  ids    jsonb := '{}';
  r      record;
  v_u    uuid; v_a uuid; v_p uuid; v_m uuid; v_t uuid;
  s      int := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('bowler',  'Bongani Bowlsixty',     16, 'F'),
      ('turning', 'Themba Turnseighteen',  17, 'F'),
      ('ewma',    'Ewan Ewmasixty',        15, 'F'),
      ('other',   'Oscar Othersixty',      15, 'M')) AS v(k, nm, age, style)
  LOOP
    INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born, bowling_style)
    VALUES (HIL, 'U15A', r.nm, split_part(r.nm, ' ', 2), 60 + s, 'bowler',
            (current_date - make_interval(years => r.age) - interval '40 days')::date, r.style)
    RETURNING id INTO v_p;
    s := s + 1;
    ids := ids || jsonb_build_object('p_' || r.k, v_p);
  END LOOP;

  FOR r IN SELECT * FROM (VALUES
      ('coach',  'coach',         'U15A', false),
      ('coach2', 'coach',         'U16A', false),
      ('physio', 'medical',       NULL,   false),
      ('fit',    'fitness',       NULL,   false),
      ('mate',   'player',        'U15A', false),
      ('office', 'schooladmin',   NULL,   false),
      ('plat',   'platformadmin', NULL,   true),
      ('mum',    'guardian',      NULL,   false),
      ('mum2',   'guardian',      NULL,   false),
      ('boy',    'selfaccess',    NULL,   false),
      ('turner', 'selfaccess',    NULL,   false)) AS v(k, role, team, platform)
  LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (CASE WHEN r.platform THEN NULL ELSE HIL END, 'v60.' || r.k || '@example.invalid', 'V60 ' || r.k, r.role)
    RETURNING id INTO v_u;
    -- The turning boy's mother is appointed by guardian_link_establish() in
    -- the section; the rest hold their role now.
    IF r.k <> 'mum' THEN
      INSERT INTO role_assignment (person_id, role, school_id, team_code)
      VALUES (v_u, r.role, CASE WHEN r.platform THEN NULL ELSE HIL END, r.team)
      RETURNING id INTO v_a;
      ids := ids || jsonb_build_object('a_' || r.k, v_a);
    END IF;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
  END LOOP;
  -- The bowler's own account plays in the side as well, as R Pillay's does.
  INSERT INTO role_assignment (person_id, role, school_id, team_code)
  VALUES ((ids->>'u_boy')::uuid, 'player', HIL, 'U15A');

  -- Who each subject-scoped assignment is about. Verified by the office, the
  -- terms agreed; a parent's link ends at his majority, as
  -- guardian_link_establish() writes it today.
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, valid_until)
  VALUES
    ((ids->>'a_boy')::uuid,    (ids->>'p_bowler')::uuid,  'self',   'verified', (ids->>'u_office')::uuid, now(), 'granted',
     'popia-2026-01', now(), (ids->>'u_office')::uuid, current_date - 30, NULL),
    ((ids->>'a_turner')::uuid, (ids->>'p_turning')::uuid, 'self',   'verified', (ids->>'u_office')::uuid, now(), 'granted',
     'popia-2026-01', now(), (ids->>'u_office')::uuid, current_date - 30, NULL),
    ((ids->>'a_mum2')::uuid,   (ids->>'p_other')::uuid,   'parent', 'verified', (ids->>'u_office')::uuid, now(), 'granted',
     'popia-2026-01', now(), (ids->>'u_office')::uuid, current_date - 30,
     majority_on((SELECT born FROM player WHERE id = (ids->>'p_other')::uuid)));

  -- Today's nets, at six in the morning.
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type)
  VALUES (HIL, 'U15A', 'Seamers at the nets', (sa_today()::timestamp + interval '6 hours') AT TIME ZONE 'Africa/Johannesburg',
          60, 'bowling')
  RETURNING id INTO v_t;
  ids := ids || jsonb_build_object('ts', v_t);

  -- Two days ago: a match the log scored, and two overs from the bowler, with
  -- a wide in the first.
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Sixty College U15A', ((sa_today() - 2)::timestamp + interval '10 hours') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'complete')
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('m', v_m, 'm_on', sa_today() - 2);
  FOR s IN 1..13 LOOP
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                            client_seq, client_ts, kind, ball_type, value, bowler_id, striker_id)
    VALUES (v_m, HIL, s, 0, 0, SCORER, 'v60', 'v60-' || s, s, now(), 'ball',
            CASE WHEN s = 3 THEN 'Wd' ELSE 'run' END, CASE WHEN s = 3 THEN 1 ELSE 0 END,
            (ids->>'p_bowler')::uuid, (ids->>'p_other')::uuid);
  END LOOP;

  -- A hamstring, with the physio's note on it.
  INSERT INTO injury (school_id, player_id, injury_type, severity, date_injured, phase, restricted, notes, physio)
  VALUES (HIL, (ids->>'p_bowler')::uuid, 'Hamstring strain', 'minor', current_date - 20, 'cleared', false,
          'Grade 1; eccentric programme, review in two weeks', 'V60 physio');
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The module switch for Hilton, as the platform would grant it.
CREATE OR REPLACE FUNCTION _v60_grant(p_on boolean) RETURNS void AS $$
  INSERT INTO feature_grant (key, school_id, granted, note)
  VALUES ('workload_monitoring', '11111111-1111-1111-1111-111111111111', p_on, 'verify db/60')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = excluded.granted;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- health_consent_live() and health_retention_due() are the database's own in
-- this phase (not the application's), so the section asks through these.
CREATE OR REPLACE FUNCTION _v60_live(p uuid) RETURNS boolean AS $$ SELECT health_consent_live(p) $$
  LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v60_due(p uuid) RETURNS date AS $$ SELECT health_retention_due(p) $$
  LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- load_day is not the application's either (db/60): one boy's day, as its owner reads it.
CREATE OR REPLACE FUNCTION _v60_day(p uuid, d date) RETURNS SETOF load_day AS $$
  SELECT * FROM load_day WHERE player_id = p AND on_date = d $$
  LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Wind a boy's whole history back so that TODAY is his eighteenth birthday:
-- his date of birth, his parents' links (dated as guardian_link_establish()
-- dated them) and every consent recorded about him move back together, so
-- a "yes" given at seventeen is still a yes given while he was a child.
CREATE OR REPLACE FUNCTION _v60_turn_eighteen(p uuid) RETURNS void AS $$
DECLARE d int;
BEGIN
  SELECT majority_on(born) - current_date INTO d FROM player WHERE id = p;
  UPDATE player SET born = born - d WHERE id = p;
  UPDATE assignment_subject SET valid_from = valid_from - d, valid_until = valid_until - d,
                                verified_at = verified_at - make_interval(days => d), consent_at = consent_at - make_interval(days => d)
   WHERE player_id = p AND relationship IS DISTINCT FROM 'self';
  UPDATE health_monitoring_consent SET given_on = given_on - d, form_date = form_date - d,
                                       recorded_at = recorded_at - make_interval(days => d)
   WHERE player_id = p;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What phase 0 (db/62) does to an enrolled pupil's parent: her link stays
-- open. Section 38 held it open by hand before db/62 landed; it now asks
-- whether db/62 left it so.
CREATE OR REPLACE FUNCTION _v38_link_open(p uuid, mum uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM assignment_subject s JOIN role_assignment a ON a.id = s.assignment_id
                  WHERE s.player_id = p AND a.person_id = mum AND a.role = 'guardian' AND s.valid_until IS NULL)
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- THE DAY, AT ANY HOUR (db/122 §4). A move the trigger dates itself is dated
-- sa_today(), Johannesburg's day; a link's liveness is still read on the
-- session's day (current_date: Q7, left for its own file). From 22:00 to
-- 24:00 UTC the first is a day ahead. These helpers stage a leaving, a return
-- and a move on the session's day, the day the link tests read, and never
-- before the day the membership they close was opened (which may be
-- sa_today()'s), so the constraint that a side is left after it is joined
-- holds at every hour and the assertions read one day throughout.
-- He leaves the school system (his last school membership closes today), and comes back.
CREATE OR REPLACE FUNCTION _v60_leave(p uuid) RETURNS void AS $$
  UPDATE team_membership SET left_on = greatest(current_date, joined_on) WHERE player_id = p AND left_on IS NULL;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v60_rejoin(p uuid) RETURNS void AS $$
  INSERT INTO team_membership (player_id, school_id, sport, team_code, joined_on, reason)
  SELECT id, school_id, 'cricket', team_code,
         greatest(current_date, (SELECT max(m.left_on) FROM team_membership m WHERE m.player_id = p)), 'moved'
    FROM player WHERE id = p;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The constructed series, recorded by his coach on the days named (days
-- ago, band), through the table's own stamp.
CREATE OR REPLACE FUNCTION _v60_series(p uuid, coach uuid) RETURNS void AS $$
DECLARE r record;
BEGIN
  PERFORM set_config('app.user_id', coach::text, true);
  FOR r IN SELECT * FROM (VALUES (40, '24_36'), (27, '24_36'), (20, '24_36'), (13, '24_36'),
                                 (6, '36plus'), (3, '36plus'), (1, '36plus'), (0, '12_24')) AS v(ago, band) LOOP
    INSERT INTO load_entry (player_id, kind, on_date, band, rpe, minutes)
    VALUES (p, 'nets', sa_today() - r.ago, r.band, 6, 40);
  END LOOP;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The same EWMA the other way: the recursion the design describes, seeded at
-- zero ninety days back, one day at a time — against load_summary()'s closed
-- form.
CREATE OR REPLACE FUNCTION _v60_ewma(p uuid, OUT acute numeric, OUT chronic numeric) AS $$
  WITH RECURSIVE days AS (
    SELECT g AS k, (sa_today() - 89 + g) AS d FROM generate_series(0, 89) g),
  series AS (
    SELECT days.k, coalesce((SELECT sum(l.units) FROM load_day l
                              WHERE l.player_id = p AND l.sport_code = 'cricket' AND l.on_date = days.d), 0)::numeric AS u
      FROM days),
  ew AS (
    SELECT s.k, 0.25 * s.u AS a, (2.0 / 29) * s.u AS c FROM series s WHERE s.k = 0
    UNION ALL
    SELECT s.k, 0.25 * s.u + 0.75 * ew.a, (2.0 / 29) * s.u + (27.0 / 29) * ew.c
      FROM ew JOIN series s ON s.k = ew.k + 1)
  SELECT a, c FROM ew WHERE k = 89
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/61 (section 39). Playing conditions per competition, phase 1
-- (SCRBRD-114). A festival Hilton organises (Hilton 1XI entered), and five
-- fixtures in it or beside it, dated from the South African today: a T20 on
-- day +3, a One-Day Declaration on day +7, a T20 on day +8, a Two-Day
-- friendly on day +3, and a T20 friendly scored "before db/61" — a no-ball
-- then a bowled, and no document — for the seed-wide comparison to be able
-- to go red. Returns the ids, by name.
CREATE OR REPLACE FUNCTION _seed_61() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  SCORER uuid := '88888888-0000-0000-0000-000000000006';
  c uuid; ids jsonb := '{}'; m uuid; r record;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, age_group, level)
  VALUES (HIL, 'Verify 061 Festival', 'festival', 'T20', '1XI', 'school') RETURNING id INTO c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, HIL, '1XI', 'Hilton 1st XI');
  ids := ids || jsonb_build_object('c', c);
  FOR r IN SELECT * FROM (VALUES
      ('t20',  c,    3, 'T20', 20::smallint),
      ('decl', c,    7, 'One-Day Declaration', 100::smallint),
      ('late', c,    8, 'T20', 20::smallint),
      ('fr',   NULL, 3, 'Two-Day', 80::smallint),
      ('old',  NULL, -9, 'T20', 20::smallint)) AS v(k, comp, days, fmt, ov)
  LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, competition_id)
    VALUES (HIL, '1XI', 'Verify 061 ' || r.k, ((sa_today() + r.days)::timestamp + interval '10 hours') AT TIME ZONE 'Africa/Johannesburg',
            'cricket', r.fmt, r.ov, CASE WHEN r.k = 'old' THEN 'complete' ELSE 'scheduled' END, r.comp)
    RETURNING id INTO m;
    ids := ids || jsonb_build_object(r.k, m);
  END LOOP;
  PERFORM _log_61((ids->>'old')::uuid);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A no-ball, then the striker bowled, written as the owner (as db/54's proof
-- writes): the two deliveries every free-hit question turns on.
CREATE OR REPLACE FUNCTION _log_61(p_match uuid) RETURNS void AS $$
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq,
                          client_ts, kind, ball_type, value, striker_id, non_striker_id, bowler_id, dismissal, payload)
  SELECT p_match, '11111111-1111-1111-1111-111111111111', x.k, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-061',
         'v61:' || p_match || ':' || x.k, x.k, now(), 'ball', x.bt, 0,
         'aaaaaaaa-0000-0000-0000-000000000001', 'aaaaaaaa-0000-0000-0000-000000000002',
         'aaaaaaaa-0000-0000-0000-000000000003', x.dis, '{}'::jsonb
    FROM (VALUES (1, 'Nb', NULL), (2, 'W', 'bowled')) AS x(k, bt, dis)
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- An owner's statement, for the claims that are about the schema itself (a
-- CHECK, a trigger) and not about who may reach it: the SQLSTATE, or 'ok'.
CREATE OR REPLACE FUNCTION _owner_61(p_sql text) RETURNS text AS $$
BEGIN
  EXECUTE p_sql;
  RETURN 'ok';
EXCEPTION WHEN others THEN RETURN SQLSTATE;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Every figure the SQL readers keep about every scored innings, as one
-- string: the live score, the handover's count, the balls each bowler's
-- overs hold, and each delivery's free hit. Read as the owner: the claim is
-- about the whole log.
CREATE OR REPLACE FUNCTION _figures_61() RETURNS text AS $$
  SELECT string_agg(format('%s/%s %s %s %s %s', l.match_id, l.innings, row(l.runs, l.wickets, l.legal_balls)::text,
                           (SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded(l.match_id, l.innings::smallint) f),
                           (SELECT sum(o.legal_balls) FROM bowler_over o WHERE o.match_id = l.match_id AND o.innings = l.innings),
                           (SELECT count(*) FILTER (WHERE ball_on_free_hit(b.match_id, b.innings, b.seq)) FROM ball_event b
                             WHERE b.match_id = l.match_id AND b.innings = l.innings)), ' ' ORDER BY l.match_id, l.innings)
    FROM match_live_score l
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Give every scored match with no document one (p_mode 'resolved': what the
-- resolver would have fixed; 'flipped': the other free hit), or take those
-- rows away again ('none'). The rows it writes are marked (fixed_by NULL,
-- sources {"verify": 61}) so 'none' removes exactly them.
CREATE OR REPLACE FUNCTION _seed_rows_61(p_mode text) RETURNS integer AS $$
DECLARE n integer := 0; r record; d jsonb;
BEGIN
  DELETE FROM match_conditions WHERE sources = '{"verify": 61}'::jsonb;
  IF p_mode = 'none' THEN RETURN 0; END IF;
  FOR r IN SELECT m.id, m.format FROM match m
            WHERE EXISTS (SELECT 1 FROM ball_event b WHERE b.match_id = m.id)
              AND NOT EXISTS (SELECT 1 FROM match_conditions c WHERE c.match_id = m.id) LOOP
    SELECT c.doc INTO d FROM match_conditions_compute(r.id) c;
    IF p_mode = 'flipped' THEN
      d := jsonb_set(d, '{play,format.free_hit}', to_jsonb(NOT free_hits_apply(r.format)));
    END IF;
    INSERT INTO match_conditions (match_id, doc, sources, doc_hash) VALUES (r.id, d, '{"verify": 61}', '');
    n := n + 1;
  END LOOP;
  RETURN n;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/62 (section 40). SCRBRD-110 phase 0: the guardian link past eighteen,
-- and SCRBRD-083 §6.3 (option C) on top of it. Written as the owner and
-- rolled back. Hilton boys of their own, so nothing earlier sections did to
-- the seed's people can decide an answer here:
--   pupil  17, 1XI — two parents; turns eighteen at school
--   adult  17, 1XI — turns eighteen at school, then leaves
--   minor  16, 1XI — leaves as a minor, comes back, leaves, turns eighteen
--   late   17, 1XI — out of the school system when his link is made, then enrols
--   grown  18 and four months, 1XI — no link, and none can be made
--   club   17, at a CLUB (kind 'club') — not the school system
--   rpupil, rclub, radult — the same three cases through the other door: a
--          parent's role_request, granted by the office (decide_role_request())
-- A club, its office, Hilton's office, the pupil's own account, and one
-- parent each (two for the pupil). Links are made in the section, through
-- guardian_link_establish() and guardian_link_verify(), as the offices.
CREATE OR REPLACE FUNCTION _seed_62() RETURNS jsonb AS $$
DECLARE
  HIL  uuid := '11111111-1111-1111-1111-111111111111';
  CLUB uuid;
  ids  jsonb := '{}';
  r    record;
  v_u  uuid; v_a uuid; v_p uuid;
  s    int := 0;
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V62C', 'Verify Sixty-Two Cricket Club', 'club', 'KwaZulu-Natal')
  RETURNING id INTO CLUB;
  ids := ids || jsonb_build_object('club', CLUB);

  FOR r IN SELECT * FROM (VALUES
      ('pupil', 'Pieter Pupilsixtytwo', 17, 40, 'hil'),
      ('adult', 'Andile Adultsixtytwo', 17, 60, 'hil'),
      ('minor', 'Mike Minorsixtytwo',   16, 40, 'hil'),
      ('late',  'Liam Latesixtytwo',    17, 40, 'hil'),
      ('grown', 'Gary Grownsixtytwo',   18, 120, 'hil'),
      ('club',  'Craig Clubsixtytwo',   17, 40, 'club'),
      ('rpupil', 'Ryan Requestpupil',   17, 40, 'hil'),
      ('rclub',  'Rory Requestclub',    17, 40, 'club'),
      ('radult', 'Riaan Requestadult',  18, 120, 'hil')) AS v(k, nm, age, days, at)
  LOOP
    INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
    VALUES (CASE r.at WHEN 'hil' THEN HIL ELSE CLUB END, '1XI', r.nm, split_part(r.nm, ' ', 2), 620 + s, 'batter',
            (current_date - make_interval(years => r.age) - make_interval(days => r.days))::date)
    RETURNING id INTO v_p;
    s := s + 1;
    ids := ids || jsonb_build_object('p_' || r.k, v_p);
  END LOOP;

  FOR r IN SELECT * FROM (VALUES
      ('office',  'schooladmin', 'hil',  'schooladmin'),
      ('coffice', 'schooladmin', 'club', 'schooladmin'),
      ('mum',     NULL,          'hil',  'guardian'),
      ('dad',     NULL,          'hil',  'guardian'),
      ('amum',    NULL,          'hil',  'guardian'),
      ('mmum',    NULL,          'hil',  'guardian'),
      ('lmum',    NULL,          'hil',  'guardian'),
      ('gmum',    NULL,          'hil',  'guardian'),
      ('cmum',    NULL,          'club', 'guardian'),
      ('rmum',    NULL,          'hil',  'guardian'),
      ('rcmum',   NULL,          'club', 'guardian'),
      ('ramum',   NULL,          'hil',  'guardian'),
      ('self',    'selfaccess',  'hil',  'player')) AS v(k, role, at, urole)
  LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (CASE r.at WHEN 'hil' THEN HIL ELSE CLUB END, 'v62.' || r.k || '@example.invalid', 'V62 ' || r.k, r.urole)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    IF r.role IS NOT NULL THEN
      INSERT INTO role_assignment (person_id, role, school_id)
      VALUES (v_u, r.role, CASE r.at WHEN 'hil' THEN HIL ELSE CLUB END)
      RETURNING id INTO v_a;
      ids := ids || jsonb_build_object('a_' || r.k, v_a);
    END IF;
  END LOOP;
  -- The pupil's own account: his verified link to himself.
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES ((ids->>'a_self')::uuid, (ids->>'p_pupil')::uuid, 'self', 'verified', (ids->>'u_office')::uuid, now(),
          'granted', 'popia-2026-01', now(), (ids->>'u_office')::uuid, current_date - 30);
  -- Three parents who asked through onboarding, each naming the child: the
  -- office will grant them through decide_role_request(), the other door.
  FOR r IN SELECT * FROM (VALUES ('rpupil', 'rmum', 'hil'), ('rclub', 'rcmum', 'club'), ('radult', 'ramum', 'hil')) AS v(p, u, at) LOOP
    INSERT INTO role_request (person_id, role, school_id, player_id, note)
    VALUES ((ids->>('u_' || r.u))::uuid, 'guardian', CASE r.at WHEN 'hil' THEN HIL ELSE CLUB END,
            (ids->>('p_' || r.p))::uuid, 'verify db/62: I am his parent')
    RETURNING id INTO v_a;
    ids := ids || jsonb_build_object('r_' || r.p, v_a);
  END LOOP;
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/62's two triggers are deferred to the end of the transaction, and this
-- file ends in ROLLBACK, so section 40 fires them where the claim needs them
-- — on exactly the statements the application's transaction would commit.
CREATE OR REPLACE FUNCTION _v62_fire() RETURNS void AS $$
BEGIN
  SET CONSTRAINTS team_membership_closes_guardian_links, team_membership_opens_guardian_links IMMEDIATE;
  SET CONSTRAINTS team_membership_closes_guardian_links, team_membership_opens_guardian_links DEFERRED;
END $$ LANGUAGE plpgsql;

-- Wind a boy's whole history back d days: his date of birth, his parents'
-- links, both consents recorded about him and his memberships' start move
-- back together — so a "yes" given at seventeen is still a yes given while
-- he was a child, and a link that was to end on his birthday ends d days
-- sooner. A closed membership's left_on is not moved: the day he left is the
-- day it happened.
CREATE OR REPLACE FUNCTION _v62_older(p uuid, d int) RETURNS void AS $$
BEGIN
  UPDATE player SET born = born - d WHERE id = p;
  UPDATE assignment_subject SET valid_from = valid_from - d, valid_until = valid_until - d,
                                verified_at = verified_at - make_interval(days => d), consent_at = consent_at - make_interval(days => d)
   WHERE player_id = p AND relationship IS DISTINCT FROM 'self';
  UPDATE health_monitoring_consent SET given_on = given_on - d, ended_on = ended_on - d, form_date = form_date - d,
                                       recorded_at = recorded_at - make_interval(days => d), ended_at = ended_at - make_interval(days => d)
   WHERE player_id = p;
  UPDATE public_name_consent SET given_on = given_on - d, ended_on = ended_on - d, form_date = form_date - d,
                                 recorded_at = recorded_at - make_interval(days => d), ended_at = ended_at - make_interval(days => d)
   WHERE player_id = p;
  UPDATE team_membership SET joined_on = joined_on - d WHERE player_id = p;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- ...by as many days as make TODAY his eighteenth birthday.
CREATE OR REPLACE FUNCTION _v62_turn_eighteen(p uuid) RETURNS void AS $$
  SELECT _v62_older(p, (SELECT majority_on(born) - current_date FROM player WHERE id = p))
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A move between sides, as the move route makes one: player.team_code, and
-- db/08's history trigger closes the old membership and opens the new.
-- Dated on the session's day, never before his open side began (see THE
-- DAY, AT ANY HOUR, above _v60_leave), as the route dates a move it is given
-- a day for.
CREATE OR REPLACE FUNCTION _v62_move(p uuid, team text) RETURNS void AS $$
BEGIN
  PERFORM set_config('app.effective_on',
    greatest(current_date, (SELECT max(m.joined_on) FROM team_membership m WHERE m.player_id = p AND m.left_on IS NULL))::text, true);
  UPDATE player SET team_code = team WHERE id = p;
  PERFORM set_config('app.effective_on', '', true);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One guardian's link to one child, as the owner reads it: ended or open, and to when.
CREATE OR REPLACE FUNCTION _v62_link(p uuid, mum uuid, OUT open boolean, OUT until date) AS $$
  SELECT s.valid_until IS NULL, s.valid_until FROM assignment_subject s
    JOIN role_assignment a ON a.id = s.assignment_id AND a.role = 'guardian'
   WHERE s.player_id = p AND a.person_id = mum
   ORDER BY s.created_at DESC, s.id LIMIT 1
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/63 (section 41). SCRBRD-120 phase 1: the scorebook importer. Three
-- Hilton 1st XI fixtures two days ago (the import, the submitter's own, the
-- abandoned one) and one at Westville, whose school is not granted the
-- module; the module granted to Hilton. Written as the owner.
CREATE OR REPLACE FUNCTION _seed_63() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  ids jsonb := '{}'; m uuid; r record;
BEGIN
  INSERT INTO feature_grant (key, school_id, granted, note) VALUES ('scorebook_import', HIL, true, 'verify 063')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = true;
  FOR r IN SELECT * FROM (VALUES ('m', HIL), ('m2', HIL), ('m3', HIL), ('mw', WES)) AS v(k, s) LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
    VALUES (r.s, '1XI', 'Verify 063 ' || r.k, now() - interval '2 days', 'cricket', 'T20', 20, 'scheduled')
    RETURNING id INTO m;
    ids := ids || jsonb_build_object(r.k, m);
  END LOOP;
  -- A Hilton 1st XI fixture in the pilot's league (its organiser an external
  -- body), which the league's administrator confirms.
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '1XI', 'Verify 063 ml', now() - interval '2 days', 'cricket', 'T20', 20, 'scheduled', '99999999-0000-0000-0000-000000000001')
  RETURNING id INTO m;
  ids := ids || jsonb_build_object('ml', m);
  -- A league run by Westville, and its administrator, appointed at Westville:
  -- he manages that league and not the pilot's (competition_conditions_manager()).
  INSERT INTO competition (id, school_id, name, comp_type, format, age_group, gender, level)
  VALUES ('99999999-0000-0000-0000-0000000063c0', WES, 'Verify 063 Westville League', 'league', 'T20', '1XI', 'boys', 'school')
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO app_user (id, school_id, email, name, role)
  VALUES ('88888888-0000-0000-0000-0000000063c0', WES, 'verify063.wesleague@example.invalid', 'Verify 063 Westville League Admin', 'competitionadmin')
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO role_assignment (person_id, role, school_id, team_code)
  SELECT '88888888-0000-0000-0000-0000000063c0', 'competitionadmin', WES, NULL
   WHERE NOT EXISTS (SELECT 1 FROM role_assignment WHERE person_id = '88888888-0000-0000-0000-0000000063c0');
  -- A Hilton fixture in Westville's league (the side entered first).
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name)
  SELECT '99999999-0000-0000-0000-0000000063c0', HIL, '1XI', 'Hilton 1st XI'
   WHERE NOT EXISTS (SELECT 1 FROM competition_entrant WHERE competition_id = '99999999-0000-0000-0000-0000000063c0');
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '1XI', 'Verify 063 mwl', now() - interval '2 days', 'cricket', 'T20', 20, 'scheduled', '99999999-0000-0000-0000-0000000063c0')
  RETURNING id INTO m;
  ids := ids || jsonb_build_object('mwl', m);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A confirmed import's photos past the window: confirmed_at a month back,
-- as the table's owner (a confirmed import does not change, by its guard).
CREATE OR REPLACE FUNCTION _age_63(p_import uuid) RETURNS void AS $$
BEGIN
  ALTER TABLE scorebook_import DISABLE TRIGGER scorebook_import_guard;
  UPDATE scorebook_import SET confirmed_at = confirmed_at - interval '31 days' WHERE id = p_import;
  ALTER TABLE scorebook_import ENABLE TRIGGER scorebook_import_guard;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the owner sees of an import's world: its events' keys in order, its
-- page reads on access_log, and the delivery readers' rows for its match.
CREATE OR REPLACE FUNCTION _log_63(p_match uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(b.idempotency_key, ',' ORDER BY b.seq), '') FROM ball_event b WHERE b.match_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _reads_63(p_import uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(l.person_id || ':' || array_to_string(l.fields, ','), ' ' ORDER BY l.person_id, l.fields), '')
    FROM access_log l WHERE l.resource = 'scorebook_page' AND p_import = ANY (l.record_ids)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _deliveries_63(p_match uuid) RETURNS bigint AS $$
  SELECT (SELECT count(*) FROM bowler_over o WHERE o.match_id = p_match)
       + (SELECT count(*) FROM bowler_spell s WHERE s.match_id = p_match)
       + (SELECT count(*) FROM milestone_notice n WHERE n.match_id = p_match)
       + (SELECT count(*) FROM public_shot_sectors(p_match))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- What scorebook_caller_may() tells the caller, as five letters (w c r a m,
-- a dash for each no; the module as '.' when it is off for one who may).
-- Not a definer: it runs as whoever calls it.
CREATE OR REPLACE FUNCTION _may_63(p_match uuid) RETURNS text AS $$
  SELECT CASE WHEN c.may_write THEN 'w' ELSE '-' END || CASE WHEN c.may_confirm THEN 'c' ELSE '-' END
      || CASE WHEN c.may_read THEN 'r' ELSE '-' END || CASE WHEN c.may_audit THEN 'a' ELSE '-' END
      || CASE WHEN c.module THEN 'm' WHEN c.may_write OR c.may_confirm OR c.may_read OR c.may_audit THEN '.' ELSE '-' END
    FROM scorebook_caller_may(p_match) c
$$ LANGUAGE sql STABLE SET search_path = pg_catalog, public, pg_temp;
-- The player ids scorebook_import_names() answers the caller, in order; and
-- the actors scorebook_import_actors() names, as id:name. Not definers.
CREATE OR REPLACE FUNCTION _owner_name_63(p_player uuid) RETURNS text AS $$
  SELECT full_name FROM player WHERE id = p_player
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _names_63(p_import uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(n.player_id::text, ',' ORDER BY n.player_id), '') FROM scorebook_import_names(p_import) n
$$ LANGUAGE sql STABLE SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _actors_63(p_import uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(a.actor_id || ':' || a.name, ',' ORDER BY a.actor_id), '') FROM scorebook_import_actors(p_import) a
$$ LANGUAGE sql STABLE SET search_path = pg_catalog, public, pg_temp;
-- A person's name, past RLS.
CREATE OR REPLACE FUNCTION _user_name_63(p_user uuid) RETURNS text AS $$
  SELECT name FROM app_user WHERE id = p_user
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Make a person a pupil for a moment (a player assignment), or not.
CREATE OR REPLACE FUNCTION _pupil_63(p_user uuid, p_on boolean) RETURNS void AS $$
BEGIN
  IF p_on THEN
    INSERT INTO role_assignment (person_id, role, school_id, team_code)
    VALUES (p_user, 'player', '11111111-1111-1111-1111-111111111111', '1XI');
  ELSE
    DELETE FROM role_assignment WHERE person_id = p_user AND role = 'player';
  END IF;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _publish_63(p_match uuid) RETURNS void AS $$
  INSERT INTO fixture_publication (match_id, side, school_id, team_code, published, set_by)
  VALUES (p_match, 'home', '11111111-1111-1111-1111-111111111111', '1XI', true, '88888888-0000-0000-0000-000000000007')
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/66 (section 44). SCRBRD-120 phase 4, the reader: two Hilton 1st XI
-- fixtures two days ago, the module granted to Hilton and the reader not.
-- Written as the owner, as the platform's grant is.
CREATE OR REPLACE FUNCTION _seed_66() RETURNS jsonb AS $$
DECLARE HIL uuid := '11111111-1111-1111-1111-111111111111'; ids jsonb := '{}'; m uuid; k text;
BEGIN
  INSERT INTO feature_grant (key, school_id, granted, note) VALUES ('scorebook_import', HIL, true, 'verify 066')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = true;
  DELETE FROM feature_grant WHERE key = 'scorebook_reader';
  FOREACH k IN ARRAY ARRAY['m', 'm2'] LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
    VALUES (HIL, '1XI', 'Verify 066 ' || k, now() - interval '2 days', 'cricket', 'T20', 20, 'scheduled')
    RETURNING id INTO m;
    ids := ids || jsonb_build_object(k, m);
  END LOOP;
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The platform's grant of the reader to one school, or its revocation; and
-- the platform-wide default, on or off.
CREATE OR REPLACE FUNCTION _grant_66(p_school uuid, p_on boolean) RETURNS void AS $$
  INSERT INTO feature_grant (key, school_id, granted, note) VALUES ('scorebook_reader', p_school, p_on, 'verify 066')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = p_on
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _default_66(p_on boolean) RETURNS void AS $$
  UPDATE feature_flag SET enabled = p_on, locked = p_on WHERE key = 'scorebook_reader'
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A read begun ten minutes ago (a crashed API).
CREATE OR REPLACE FUNCTION _stale_66(p_import uuid) RETURNS void AS $$
  UPDATE scorebook_import SET reading_since = now() - interval '10 minutes' WHERE id = p_import
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The import as the owner reads it: state, where a read would go back to,
-- who is reading, the processing record, the read cells.
CREATE OR REPLACE FUNCTION _import_66(p_import uuid) RETURNS scorebook_import AS $$
  SELECT * FROM scorebook_import WHERE id = p_import
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The access_log rows that say a page went to the reader, as person:page.
CREATE OR REPLACE FUNCTION _sent_66(p_import uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(l.person_id || ':' || l.fields[1], ' ' ORDER BY l.fields[1], l.occurred_at), '')
    FROM access_log l WHERE l.resource = 'scorebook_page' AND p_import = ANY (l.record_ids) AND 'to:reader' = ANY (l.fields)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/64 (section 42). A Hilton 1XI fixture played four hundred days ago, so
-- its season is not the one its import is committed in, with the module on;
-- and two boys of the 1XI whose only record will be the book's.
CREATE OR REPLACE FUNCTION _seed_64() RETURNS uuid AS $$
DECLARE m uuid;
BEGIN
  INSERT INTO feature_grant (key, school_id, granted, note)
  VALUES ('scorebook_import', '11111111-1111-1111-1111-111111111111', true, 'verify 064')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = true;
  INSERT INTO player (id, school_id, team_code, full_name, born) VALUES
    ('aaaaaaaa-0000-0000-0000-0000000064a0', '11111111-1111-1111-1111-111111111111', '1XI', 'Verify 064 Batter', '2009-02-01'),
    ('aaaaaaaa-0000-0000-0000-0000000064b0', '11111111-1111-1111-1111-111111111111', '1XI', 'Verify 064 Bowler', '2009-02-01')
  ON CONFLICT DO NOTHING;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES ('11111111-1111-1111-1111-111111111111', '1XI', 'Verify 064', now() - interval '400 days', 'cricket', 'T20', 20, 'scheduled')
  RETURNING id INTO m;
  RETURN m;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: whether any player row carries a name the scorer typed.
CREATE OR REPLACE FUNCTION _typed_players_64() RETURNS bigint AS $$
  SELECT count(*) FROM player WHERE full_name LIKE 'Opp %'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/65 (section 43). Two Hilton 1XI fixtures at Gordon Sherwood Oval, T20
-- of 20 overs: one ten days ahead (on the hour), one three days past.
CREATE OR REPLACE FUNCTION _seed_65() RETURNS jsonb AS $$
DECLARE m uuid; mp uuid;
BEGIN
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES ('11111111-1111-1111-1111-111111111111', '1XI', 'Verify 065', date_trunc('hour', now()) + interval '10 days',
          'cricket', 'T20', 20, 'scheduled', 'ffffffff-0000-0000-0000-000000000001')
  RETURNING id INTO m;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES ('11111111-1111-1111-1111-111111111111', '1XI', 'Verify 065 past', date_trunc('hour', now()) - interval '3 days',
          'cricket', 'T20', 20, 'scheduled', 'ffffffff-0000-0000-0000-000000000001')
  RETURNING id INTO mp;
  RETURN jsonb_build_object('m', m, 'past', mp);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: every ask-again notice about a fixture, as recipient/player/kind,
-- sorted; and how many there are.
CREATE OR REPLACE FUNCTION _notices_65(p_match uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(n.recipient_id || '/' || n.subject_person_id || '/' || n.kind, ' '
                             ORDER BY n.recipient_id || '/' || n.subject_person_id || '/' || n.kind), '')
    FROM notification n WHERE n.subject_id = p_match AND n.required_capability = 'availability.read'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _notice_count_65(p_match uuid) RETURNS bigint AS $$
  SELECT count(*) FROM notification n WHERE n.subject_id = p_match AND n.required_capability = 'availability.read'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Whether a person's newest guardian link to a child is live today, past RLS.
CREATE OR REPLACE FUNCTION _link_live_65(p_player uuid, p_person uuid) RETURNS boolean AS $$
  SELECT coalesce(bool_or(s.verification_state = 'verified' AND a.active
                          AND (s.valid_until IS NULL OR s.valid_until > current_date)), false)
    FROM assignment_subject s JOIN role_assignment a ON a.id = s.assignment_id AND a.role = 'guardian'
   WHERE s.player_id = p_player AND a.person_id = p_person
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Each answer the CALLER can read for a fixture, as the last digit of the
-- boy's id and its effective status. Not a definer.
CREATE OR REPLACE FUNCTION _eff_65(p_match uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(right(a.player_id::text, 1) || '=' || availability_effective(a, m), ' ' ORDER BY a.player_id), '')
    FROM match_availability a JOIN match m ON m.id = a.match_id WHERE a.match_id = p_match
$$ LANGUAGE sql STABLE SET search_path = pg_catalog, public, pg_temp;

-- db/67 (section 45). SCRBRD-123 phase 2: a league with no organising school
-- (its manager is the platform-wide competitionadmin), Hilton's and
-- Westville's 1st XIs entered, and at Hilton a field and a pitch not yet on
-- it. Written as the owner, as a seed would.
CREATE OR REPLACE FUNCTION _seed_67() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  c uuid; eh uuid; ew uuid; f uuid; p uuid; hc uuid; hs uuid;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, age_group, gender, level)
  VALUES (NULL, 'Verify 067 League', 'league', 'T20', '1XI', 'boys', 'school') RETURNING id INTO c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, HIL, '1XI', 'Hilton 1st XI') RETURNING id INTO eh;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, WES, '1XI', 'Westville 1st XI') RETURNING id INTO ew;
  INSERT INTO ground (school_id, name) VALUES (HIL, 'Verify 067 Field') RETURNING id INTO f;
  INSERT INTO ground (school_id, name) VALUES (HIL, 'Verify 067 Pitch') RETURNING id INTO p;
  -- A competition administrator appointed at Westville (Westville's leagues).
  INSERT INTO app_user (id, school_id, email, name, role)
  VALUES ('88888888-0000-0000-0000-0000000067c0', WES, 'verify067.wesleague@example.invalid', 'Verify 067 Westville League Admin', 'competitionadmin')
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO role_assignment (person_id, role, school_id, team_code)
  SELECT '88888888-0000-0000-0000-0000000067c0', 'competitionadmin', WES, NULL
   WHERE NOT EXISTS (SELECT 1 FROM role_assignment WHERE person_id = '88888888-0000-0000-0000-0000000067c0');
  -- A cup Hilton organises for its own sides, with a version in force today
  -- carrying one cited figure: a source Westville's administrator cannot read.
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 067 Hilton Cup', 'knockout', 'T20', 'school') RETURNING id INTO hc;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (hc, HIL, 'U15A', 'Hilton U15A');
  INSERT INTO condition_set (competition_id, version, title, effective_from, created_by)
  VALUES (hc, 1, 'Verify 067 Cup conditions', sa_today() - 10, '88888888-0000-0000-0000-000000000022') RETURNING id INTO hs;
  INSERT INTO condition_value (set_id, key, value, status, source_document, source_clause, source_date, entered_by)
  VALUES (hs, 'points.win', '3', 'confirmed', 'Verify 067 Cup Rules', '4.2', sa_today() - 20, '88888888-0000-0000-0000-000000000022');
  UPDATE condition_set SET status = 'published', published_by = created_by, published_at = now() WHERE id = hs;
  RETURN jsonb_build_object('comp', c, 'eh', eh, 'ew', ew, 'field', f, 'pitch', p, 'hcup', hc);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: a competition's matches and items, as "matches/items".
CREATE OR REPLACE FUNCTION _made_67(p_comp uuid) RETURNS text AS $$
  SELECT (SELECT count(*) FROM match WHERE competition_id = p_comp) || '/' || (SELECT count(*) FROM fixture_plan_item WHERE competition_id = p_comp)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: an entrant's status.
CREATE OR REPLACE FUNCTION _status_67(p_entrant uuid) RETURNS text AS $$
  SELECT status FROM competition_entrant WHERE id = p_entrant
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: whether any match at all has this opponent label (a refused
-- insert must leave none).
CREATE OR REPLACE FUNCTION _any_match_67(p_label text) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM match WHERE opponent = p_label)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/68 (section 46). Two Hilton 1XI fixtures with the same deliveries, the
-- opposition batting (typed names), Hilton's …03 bowling the first over and
-- …04 the second. In the first the
-- keepers are named: …02 keeps, and mid-over hands the gloves to …01; a
-- keeper row naming …05 is undone. The squad names them "V68 Two", "V68
-- One" and "V68 Five". The second has no keeper row: the log as it was
-- before SCRBRD-126. packages/scoring/test/keeper.test.mjs (group E)
-- folds this same log and holds the fold to the figures §46 reads.
--   seq 1 start · 2 keeper …02 · 3 caught "V68 Two" (his, by name) · 4 a
--   no-ball · 5 stumped (saved by the free hit) · 6 keeper …01, mid-over ·
--   7 stumped, nobody named (…01's) · 8 caught by …01's id (his) · 9 caught
--   "V68 Two" (not as keeper) · 10 run out "V68 One" (no keeper's) · 11
--   keeper …05 · 12 the void of 11 · 13 stumped "V68 One" (…01's).
-- Written as the owner, one row per statement, as the write path writes.
CREATE OR REPLACE FUNCTION _seed_68() RETURNS jsonb AS $$
DECLARE m uuid; mp uuid; r record; k text;
  K1 text := 'aaaaaaaa-0000-0000-0000-000000000002';
  K2 text := 'aaaaaaaa-0000-0000-0000-000000000001';
  F1 text := 'aaaaaaaa-0000-0000-0000-000000000005';
  BW uuid := 'aaaaaaaa-0000-0000-0000-000000000003';
  B2 uuid := 'aaaaaaaa-0000-0000-0000-000000000004';   -- bowls the second over
  squad jsonb := jsonb_build_array(jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000002', 'name', 'V68 Two'),
                                   jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000001', 'name', 'V68 One'),
                                   jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000005', 'name', 'V68 Five'));
BEGIN
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES ('11111111-1111-1111-1111-111111111111', '1XI', 'Verify 068 keepers', now() - interval '3 days', 'cricket', 'T20', 20, 'complete')
  RETURNING id INTO m;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES ('11111111-1111-1111-1111-111111111111', '1XI', 'Verify 068 plain', now() - interval '3 days', 'cricket', 'T20', 20, 'complete')
  RETURNING id INTO mp;
  FOR r IN
    SELECT mm, x.*
      FROM unnest(ARRAY[m, mp]) AS mm
     CROSS JOIN (VALUES
       (1,  'innings_start', NULL, NULL::int, NULL, jsonb_build_object('battingTeam', 'Verify 068', 'bowlingTeam', 'Hilton 1XI', 'squad', '[]'::jsonb, 'bowlingSquad', squad)),
       (2,  'keeper', NULL, NULL, NULL, jsonb_build_object('keeper', K1)),
       (3,  'ball', 'W', 0, 'caught',  '{"fielder":"V68 Two","striker":"Opp A"}'::jsonb),
       (4,  'ball', 'Nb', 1, NULL,     '{"striker":"Opp B"}'::jsonb),
       (5,  'ball', 'W', 0, 'stumped', '{"striker":"Opp B"}'::jsonb),
       (6,  'keeper', NULL, NULL, NULL, jsonb_build_object('keeper', K2)),
       (7,  'ball', 'W', 0, 'stumped', '{"striker":"Opp B"}'::jsonb),
       (8,  'ball', 'W', 0, 'caught',  jsonb_build_object('fielder', K2, 'striker', 'Opp C')),
       (9,  'ball', 'W', 0, 'caught',  '{"fielder":"V68 Two","striker":"Opp D"}'::jsonb),
       (10, 'ball', 'W', 1, 'run_out', '{"fielder":"V68 One","striker":"Opp E"}'::jsonb),
       (11, 'keeper', NULL, NULL, NULL, jsonb_build_object('keeper', F1)),
       (12, 'void', NULL, NULL, NULL, '{}'::jsonb),
       (13, 'ball', 'W', 0, 'stumped', '{"fielder":"V68 One","striker":"Opp F"}'::jsonb)
     ) AS x(seq, kind, bt, v, dis, payload)
     WHERE mm = m OR x.kind NOT IN ('keeper', 'void')
     ORDER BY mm, x.seq
  LOOP
    k := 'v68:' || r.mm || ':' || r.seq;
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                            client_seq, client_ts, kind, ball_type, value, bowler_id, dismissal, payload)
    VALUES (r.mm, '11111111-1111-1111-1111-111111111111', r.seq, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-068',
            k, r.seq, '2026-09-15 10:00+02', r.kind, r.bt, r.v, CASE WHEN r.kind = 'ball' AND r.seq = 13 THEN B2 WHEN r.kind = 'ball' THEN BW END, r.dis,
            CASE WHEN r.kind = 'void' THEN jsonb_build_object('target', 'v68:' || r.mm || ':11') ELSE r.payload END);
  END LOOP;
  RETURN jsonb_build_object('m', m, 'plain', mp);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- ── SCRBRD-114 phase 3a (db/69, section 47): results and the table ──
-- A league Hilton organises, "Verify 069 League", with four sides: Hilton
-- 1XI (A) and 2XI (C), Westville 1XI (B) and 2XI (D). Version 1 of its
-- conditions (in force from 28 September) confirms the pilot's four figures
-- — win 4, tie 2, no result 2, loss 0 — and over-rate penalties in points;
-- version 2 (from 8 October) makes a win 5. Seven matches, each with the
-- document its first event would fix, dated explicitly (3 October 2026, the
-- 4th Edition; M7 on 10 October):
--   M1 A v B   A 60/0 (20 ov); B 61/0 in 14.3 overs (87 balls): B by 10 wkts
--   M2 C v D   C 100 all out in 17 overs (102 balls, squad of three); D 50/0 (20): C by 50 runs
--   M3 A v D   revised to 12 overs: A 46 all out in 8 (48 balls); D 47/0 off 38 balls with two wides: D by 10 wkts
--   M4 C v B   B (away) bats first 60/0; C 60/0: tie
--   M5 C v D   C 30/0; D 0/0 off 6, sealed abandoned: no result
--   M6 A v B   abandoned before a ball
--   M7 D v A   (10 October, version 2) D 30/0; A 0/0: D by 30 runs
-- and a Hilton 1XI friendly, F (6 off an over; the visitors 0), and a second
-- league organised by Westville, "Verify 069 Typed", with no conditions and a
-- ladder the schools typed. An amendment to void M1's last single (B's
-- winning run) waits, filed by the scorer.
CREATE OR REPLACE FUNCTION _ev_69(p_match uuid, p_inn smallint, p_kind text, p_bt text, p_v integer, p_dis text, p_payload jsonb, p_n integer DEFAULT 1)
RETURNS integer AS $$
DECLARE v_seq integer; k integer; v_school uuid;
BEGIN
  SELECT m.school_id INTO v_school FROM match m WHERE m.id = p_match;
  FOR k IN 1..p_n LOOP
    SELECT coalesce(max(b.seq), 0) + 1 INTO v_seq FROM ball_event b WHERE b.match_id = p_match;
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                            client_seq, client_ts, kind, ball_type, value, dismissal, payload)
    VALUES (p_match, v_school, v_seq, 1, p_inn, '88888888-0000-0000-0000-000000000006', 'verify-069',
            'v69:' || p_match || ':' || v_seq, v_seq, '2026-10-03 10:00+02'::timestamptz + v_seq * interval '20 seconds',
            p_kind, p_bt, p_v, p_dis, p_payload);
  END LOOP;
  RETURN v_seq;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _seed_69() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OWNR uuid := '88888888-0000-0000-0000-000000000022';
  c uuid; c2 uuid; v1 uuid; v2 uuid; ea uuid; eb uuid; ec uuid; ed uuid; e2a uuid; e2b uuid; e2c uuid;
  m1 uuid; m2 uuid; m3 uuid; m4 uuid; m5 uuid; m6 uuid; m7 uuid; f uuid;
  sq11 jsonb := (SELECT jsonb_agg(jsonb_build_object('id', 'V69 P' || g, 'name', 'V69 P' || g)) FROM generate_series(1, 11) g);
  sq3 jsonb := (SELECT jsonb_agg(jsonb_build_object('id', 'V69 Q' || g, 'name', 'V69 Q' || g)) FROM generate_series(1, 3) g);
  lab text; k text; last_b1 integer; amend uuid;
  -- an innings_start payload
  st jsonb;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 069 League', 'league', 'T20', 'school') RETURNING id INTO c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, HIL, '1XI', 'Verify 069 Hilton 1st XI') RETURNING id INTO ea;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, WES, '1XI', 'Verify 069 Westville 1st XI') RETURNING id INTO eb;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, HIL, '2XI', 'Verify 069 Hilton 2nd XI') RETURNING id INTO ec;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, WES, '2XI', 'Verify 069 Westville 2nd XI') RETURNING id INTO ed;
  INSERT INTO condition_set (competition_id, version, title, effective_from, created_by) VALUES (c, 1, 'Verify 069 v1', '2026-09-28', OWNR) RETURNING id INTO v1;
  INSERT INTO condition_value (set_id, key, value, status, source_document, source_clause, source_date, entered_by)
  SELECT v1, x.k, x.v, 'confirmed', 'Pilot league decision, Kameel', '8.3a', '2026-09-30', OWNR
    FROM (VALUES ('points.win', '4'::jsonb), ('points.tie', '2'), ('points.no_result', '2'), ('points.loss', '0'),
                 ('over_rate.kind', '"points"')) AS x(k, v);
  UPDATE condition_set SET status = 'published', published_by = OWNR, published_at = '2026-09-27 12:00+02' WHERE id = v1;
  INSERT INTO condition_set (competition_id, version, title, effective_from, created_by, supersedes) VALUES (c, 2, 'Verify 069 v2', '2026-10-08', OWNR, v1) RETURNING id INTO v2;
  INSERT INTO condition_value (set_id, key, value, status, source_document, source_clause, source_date, entered_by)
  SELECT v2, x.k, x.v, 'confirmed', 'Pilot league decision, Kameel', '8.3a', '2026-10-01', OWNR
    FROM (VALUES ('points.win', '5'::jsonb), ('points.tie', '2'), ('points.no_result', '2'), ('points.loss', '0'),
                 ('over_rate.kind', '"points"')) AS x(k, v);
  UPDATE condition_set SET status = 'published', published_by = OWNR, published_at = '2026-10-01 12:00+02' WHERE id = v2;

  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (HIL, '1XI', WES, '1XI', 'x', '2026-10-03 10:00+02', 'cricket', 'T20', 20, 'complete', c) RETURNING id INTO m1;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (HIL, '2XI', WES, '2XI', 'x', '2026-10-03 10:00+02', 'cricket', 'T20', 20, 'complete', c) RETURNING id INTO m2;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (HIL, '1XI', WES, '2XI', 'x', '2026-10-03 13:00+02', 'cricket', 'T20', 20, 'complete', c) RETURNING id INTO m3;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (HIL, '2XI', WES, '1XI', 'x', '2026-10-03 13:00+02', 'cricket', 'T20', 20, 'complete', c) RETURNING id INTO m4;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (HIL, '2XI', WES, '2XI', 'x', '2026-10-03 15:00+02', 'cricket', 'T20', 20, 'complete', c) RETURNING id INTO m5;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (HIL, '1XI', WES, '1XI', 'x', '2026-10-03 15:00+02', 'cricket', 'T20', 20, 'abandoned', c) RETURNING id INTO m6;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id) VALUES
    (WES, '2XI', HIL, '1XI', 'x', '2026-10-10 10:00+02', 'cricket', 'T20', 20, 'complete', c) RETURNING id INTO m7;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '1XI', 'Verify 069 Friendly', '2026-10-03 10:00+02', 'cricket', 'T20', 20, 'complete') RETURNING id INTO f;
  -- Each match's document, as its first event fixes it.
  INSERT INTO match_conditions (match_id, set_id, set_version, doc, sources, doc_hash)
  SELECT x.m, r.set_id, r.set_version, r.doc, r.sources, ''
    FROM unnest(ARRAY[m1, m2, m3, m4, m5, m6, m7, f]) AS x(m), LATERAL match_conditions_compute(x.m) r;

  -- M1: A 60/0, sealed; B chases 61: 26 dots, 61 singles.
  SELECT opponent INTO lab FROM match WHERE id = m1;
  PERFORM _ev_69(m1, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', lab, 'squad', sq11, 'overs', 20));
  PERFORM _ev_69(m1, 0::smallint, 'ball', 'run', 1, NULL, '{}', 60);
  PERFORM _ev_69(m1, 0::smallint, 'ball', 'run', 0, NULL, '{}', 60);
  PERFORM _ev_69(m1, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":60,"wickets":0,"balls":120}}');
  PERFORM _ev_69(m1, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', lab, 'bowlingTeam', '1XI', 'squad', sq11, 'overs', 20, 'target', 61));
  PERFORM _ev_69(m1, 1::smallint, 'ball', 'run', 0, NULL, '{}', 26);
  last_b1 := _ev_69(m1, 1::smallint, 'ball', 'run', 1, NULL, '{}', 61);
  PERFORM _ev_69(m1, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":61,"wickets":0,"balls":87}}');
  INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
  VALUES (m1, HIL, 'v69:' || m1 || ':' || last_b1, 'Verify 069: the winning single was a dead ball', '88888888-0000-0000-0000-000000000006')
  RETURNING id INTO amend;

  -- M2: C 100 all out off 102 (a squad of three); D 50/0 off 120.
  SELECT opponent INTO lab FROM match WHERE id = m2;
  PERFORM _ev_69(m2, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '2XI', 'bowlingTeam', lab, 'squad', sq3, 'overs', 20));
  PERFORM _ev_69(m2, 0::smallint, 'ball', 'run', 1, NULL, '{}', 100);
  PERFORM _ev_69(m2, 0::smallint, 'ball', 'W', 0, 'bowled', '{}', 2);
  PERFORM _ev_69(m2, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"all_out","confirmed":{"runs":100,"wickets":2,"balls":102}}');
  PERFORM _ev_69(m2, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', lab, 'bowlingTeam', '2XI', 'squad', sq11, 'overs', 20, 'target', 101));
  PERFORM _ev_69(m2, 1::smallint, 'ball', 'run', 1, NULL, '{}', 50);
  PERFORM _ev_69(m2, 1::smallint, 'ball', 'run', 0, NULL, '{}', 70);
  PERFORM _ev_69(m2, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":50,"wickets":0,"balls":120}}');

  -- M3: revised to 12 overs. A 46 all out off 48; D 47/0 off 38, two wides.
  SELECT opponent INTO lab FROM match WHERE id = m3;
  PERFORM _ev_69(m3, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', lab, 'squad', sq3, 'overs', 20));
  PERFORM _ev_69(m3, 0::smallint, 'revision', NULL, NULL, NULL, '{"overs":12,"reason":"rain"}');
  PERFORM _ev_69(m3, 0::smallint, 'ball', 'run', 1, NULL, '{}', 46);
  PERFORM _ev_69(m3, 0::smallint, 'ball', 'W', 0, 'bowled', '{}', 2);
  PERFORM _ev_69(m3, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"all_out","confirmed":{"runs":46,"wickets":2,"balls":48}}');
  PERFORM _ev_69(m3, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', lab, 'bowlingTeam', '1XI', 'squad', sq11, 'overs', 20, 'target', 47));
  PERFORM _ev_69(m3, 1::smallint, 'revision', NULL, NULL, NULL, '{"overs":12,"target":47,"reason":"rain"}');
  PERFORM _ev_69(m3, 1::smallint, 'ball', 'Wd', 0, NULL, '{}', 2);
  PERFORM _ev_69(m3, 1::smallint, 'ball', 'run', 2, NULL, '{}', 7);
  PERFORM _ev_69(m3, 1::smallint, 'ball', 'run', 1, NULL, '{}', 31);
  PERFORM _ev_69(m3, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":47,"wickets":0,"balls":38}}');

  -- M4: B, the visitors, bat first 60/0; C 60/0: a tie.
  SELECT opponent INTO lab FROM match WHERE id = m4;
  PERFORM _ev_69(m4, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', lab, 'bowlingTeam', '2XI', 'squad', sq11, 'overs', 20));
  PERFORM _ev_69(m4, 0::smallint, 'ball', 'run', 1, NULL, '{}', 60);
  PERFORM _ev_69(m4, 0::smallint, 'ball', 'run', 0, NULL, '{}', 60);
  PERFORM _ev_69(m4, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":60,"wickets":0,"balls":120}}');
  PERFORM _ev_69(m4, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '2XI', 'bowlingTeam', lab, 'squad', sq11, 'overs', 20, 'target', 61));
  PERFORM _ev_69(m4, 1::smallint, 'ball', 'run', 1, NULL, '{}', 60);
  PERFORM _ev_69(m4, 1::smallint, 'ball', 'run', 0, NULL, '{}', 60);
  PERFORM _ev_69(m4, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":60,"wickets":0,"balls":120}}');

  -- M5: C 30/0; the chase called off after an over: no result.
  SELECT opponent INTO lab FROM match WHERE id = m5;
  PERFORM _ev_69(m5, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '2XI', 'bowlingTeam', lab, 'squad', sq11, 'overs', 20));
  PERFORM _ev_69(m5, 0::smallint, 'ball', 'run', 1, NULL, '{}', 30);
  PERFORM _ev_69(m5, 0::smallint, 'ball', 'run', 0, NULL, '{}', 90);
  PERFORM _ev_69(m5, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":30,"wickets":0,"balls":120}}');
  PERFORM _ev_69(m5, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', lab, 'bowlingTeam', '2XI', 'squad', sq11, 'overs', 20, 'target', 31));
  PERFORM _ev_69(m5, 1::smallint, 'ball', 'run', 0, NULL, '{}', 6);
  PERFORM _ev_69(m5, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"abandoned","confirmed":{"runs":0,"wickets":0,"balls":6}}');

  -- M7 (10 October): D 30/0; A 0/0.
  SELECT opponent INTO lab FROM match WHERE id = m7;
  PERFORM _ev_69(m7, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '2XI', 'bowlingTeam', lab, 'squad', sq11, 'overs', 20));
  PERFORM _ev_69(m7, 0::smallint, 'ball', 'run', 1, NULL, '{}', 30);
  PERFORM _ev_69(m7, 0::smallint, 'ball', 'run', 0, NULL, '{}', 90);
  PERFORM _ev_69(m7, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":30,"wickets":0,"balls":120}}');
  PERFORM _ev_69(m7, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', lab, 'bowlingTeam', '2XI', 'squad', sq11, 'overs', 20, 'target', 31));
  PERFORM _ev_69(m7, 1::smallint, 'ball', 'run', 0, NULL, '{}', 120);
  PERFORM _ev_69(m7, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":0,"wickets":0,"balls":120}}');

  -- F: Hilton 6 off an over; the visitors 0 off theirs.
  PERFORM _ev_69(f, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Verify 069 Friendly', 'squad', sq11, 'overs', 1));
  PERFORM _ev_69(f, 0::smallint, 'ball', 'run', 1, NULL, '{}', 6);
  PERFORM _ev_69(f, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', 'Verify 069 Friendly', 'bowlingTeam', '1XI', 'squad', sq11, 'overs', 1, 'target', 7));
  PERFORM _ev_69(f, 1::smallint, 'ball', 'run', 0, NULL, '{}', 6);

  -- The typed ladder: a Westville league with no conditions, three sides,
  -- two of them level on everything.
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (WES, 'Verify 069 Typed', 'league', 'T20', 'school') RETURNING id INTO c2;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name, played, won, lost, drawn, no_result, points, net_run_rate)
  VALUES (c2, WES, '1XI', 'Verify 069 Typed One', 2, 1, 1, 0, 0, 4, 0.500) RETURNING id INTO e2a;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name, played, won, lost, drawn, no_result, points, net_run_rate)
  VALUES (c2, HIL, '1XI', 'Verify 069 Typed Two', 2, 1, 1, 0, 0, 4, 0.500) RETURNING id INTO e2b;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name, played, won, lost, drawn, no_result, points, net_run_rate)
  VALUES (c2, WES, '2XI', 'Verify 069 Typed Three', 2, 0, 2, 0, 0, 0, -1.000) RETURNING id INTO e2c;

  RETURN jsonb_build_object('c', c, 'c2', c2, 'v1', v1, 'v2', v2, 'a', ea, 'b', eb, 'cc', ec, 'd', ed,
    'm1', m1, 'm2', m2, 'm3', m3, 'm4', m4, 'm5', m5, 'm6', m6, 'm7', m7, 'f', f, 'amend', amend, 'last_b1', 'v69:' || m1 || ':' || last_b1);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: a competition's table as "code=played,won,lost,tied,nr,points,rank" by
-- entrant (A, B, C, D), and the run figures "rf/bf/ra/ba".
CREATE OR REPLACE FUNCTION _table_69(p_comp uuid, p_ids jsonb) RETURNS text AS $$
  SELECT string_agg(x.code || '=' || concat_ws(',', s.played, s.won, s.lost, s.tied, s.no_result, s.points, s.rank), ' ' ORDER BY x.code)
    FROM (VALUES ('A', (p_ids->>'a')::uuid), ('B', (p_ids->>'b')::uuid), ('C', (p_ids->>'cc')::uuid), ('D', (p_ids->>'d')::uuid)) AS x(code, e)
    JOIN competition_standing_rows(p_comp) s ON s.entrant_id = x.e
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: a match's frozen document, for the re-fix's assertions.
CREATE OR REPLACE FUNCTION _doc_69(p_match uuid) RETURNS jsonb AS $$
  SELECT jsonb_build_object('doc', c.doc, 'before', c.table_doc_before, 'by', c.table_refixed_by, 'reason', c.table_refixed_reason,
                            'set', c.set_id, 'sources', c.sources)
    FROM match_conditions c WHERE c.match_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: the amendment's audit line.
CREATE OR REPLACE FUNCTION _audit_69(p_match uuid) RETURNS jsonb AS $$
  SELECT a.detail FROM scoring_audit a WHERE a.match_id = p_match AND a.event = 'amendment_approved' ORDER BY a.id DESC LIMIT 1
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: publish one side of a fixture, and a competition's page.
CREATE OR REPLACE FUNCTION _publish_69(p_match uuid, p_comp uuid) RETURNS void AS $$
  INSERT INTO fixture_publication (match_id, side, school_id, team_code, published, set_by)
  SELECT m.id, 'home', m.school_id, m.team_code, true, '88888888-0000-0000-0000-000000000022' FROM match m WHERE m.id = p_match;
  INSERT INTO competition_publication (competition_id, published, set_by)
  VALUES (p_comp, true, '88888888-0000-0000-0000-000000000022');
$$ LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- ┌── db/70 (section 48). SCRBRD-124 phase 1: parent lift clubs ─────────
-- A world of its own, so nothing an earlier section revoked or moved can
-- decide what this one proves: at Hilton a U15A side with five boys and
-- their families — Jono (the driver's son), Ben (two guardians), Carl, Dan
-- (seventeen, an account of his own), Ed (eighteen and at school, an account
-- of his own; both hold the side's player assignment, as every pupil does) —
-- a U14A boy (Finn) whose mother has no child on the side, a
-- Westville U15A boy and his mother, the side's coach, the office, the
-- transport coordinator and a principal. Three fixtures, each with an
-- explicit day: the U15A v Westville's U15A ten days ahead (M), one twelve
-- days ahead that will be called off (MV), and two tomorrow (MT at ten, MA
-- at two), inside the day window for numbers. Written as the owner, as a seed would. Every name
-- here is invented.
CREATE OR REPLACE FUNCTION _seed_70() RETURNS jsonb AS $$
DECLARE
  HIL    uuid := '11111111-1111-1111-1111-111111111111';
  WES    uuid := '22222222-2222-2222-2222-222222222222';
  GROUND uuid := 'ffffffff-0000-0000-0000-000000000001';
  ids    jsonb := '{}';
  r      record;
  v_u uuid; v_a uuid; v_p uuid; v_m uuid;
  s      int := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('jono', 'Jono Liftseventy', 15,  10, 'hil', 'U15A'),
      ('ben',  'Ben Liftseventy',  15,  20, 'hil', 'U15A'),
      ('carl', 'Carl Liftseventy', 15,  30, 'hil', 'U15A'),
      ('dan',  'Dan Liftseventy',  17,  40, 'hil', 'U15A'),
      ('ed',   'Ed Liftseventy',   18,  40, 'hil', 'U15A'),
      ('finn', 'Finn Liftseventy', 14,  10, 'hil', 'U14A'),
      ('wes',  'Wes Liftseventy',  15,  10, 'wes', 'U15A'),
      ('pat',  'Pat Liftseventy',  15,  50, 'hil', 'U15A')) AS v(k, nm, age, days, at, team)
  LOOP
    INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
    VALUES (CASE r.at WHEN 'hil' THEN HIL ELSE WES END, r.team, r.nm, split_part(r.nm, ' ', 2), 700 + s, 'batter',
            (current_date - make_interval(years => r.age) - make_interval(days => r.days))::date)
    RETURNING id INTO v_p;
    s := s + 1;
    ids := ids || jsonb_build_object('p_' || r.k, v_p);
  END LOOP;

  FOR r IN SELECT * FROM (VALUES
      ('office', 'schooladmin',          'hil', NULL,   'schooladmin', NULL),
      ('tco',    'transportcoordinator', 'hil', NULL,   'transportcoordinator', NULL),
      ('head',   'principal',            'hil', NULL,   'principal', NULL),
      ('coach',  'coach',                'hil', 'U15A', 'coach', NULL),
      ('dmum',   'guardian',             'hil', NULL,   'guardian', 'jono'),
      ('bmum',   'guardian',             'hil', NULL,   'guardian', 'ben'),
      ('bdad',   'guardian',             'hil', NULL,   'guardian', 'ben'),
      ('cmum',   'guardian',             'hil', NULL,   'guardian', 'carl'),
      ('dnmum',  'guardian',             'hil', NULL,   'guardian', 'dan'),
      ('emum',   'guardian',             'hil', NULL,   'guardian', 'ed'),
      ('fmum',   'guardian',             'hil', NULL,   'guardian', 'finn'),
      ('wmum',   'guardian',             'wes', NULL,   'guardian', 'wes'),
      ('pmum',   'guardian',             'hil', NULL,   'guardian', 'pat'),
      ('dan',    'selfaccess',           'hil', NULL,   'player',   'dan'),
      ('ed',     'selfaccess',           'hil', NULL,   'player',   'ed')) AS v(k, role, at, team, urole, child)
  LOOP
    INSERT INTO app_user (school_id, email, name, role, player_id)
    VALUES (CASE r.at WHEN 'hil' THEN HIL ELSE WES END, 'v70.' || r.k || '@example.invalid', 'V70 ' || initcap(r.k), r.urole,
            CASE WHEN r.role = 'selfaccess' THEN (ids->>('p_' || r.child))::uuid END)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    INSERT INTO role_assignment (person_id, role, school_id, team_code)
    VALUES (v_u, r.role, CASE r.at WHEN 'hil' THEN HIL ELSE WES END, r.team)
    RETURNING id INTO v_a;
    ids := ids || jsonb_build_object('a_' || r.k, v_a);
    IF r.child IS NOT NULL THEN
      INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                      consent_state, consent_version, consent_at, created_by, valid_from)
      VALUES (v_a, (ids->>('p_' || r.child))::uuid, CASE r.role WHEN 'selfaccess' THEN 'self' ELSE 'parent' END,
              'verified', (ids->>'u_office')::uuid, now(), 'granted', 'popia-2026-01', now(),
              (ids->>'u_office')::uuid, current_date - 30);
    END IF;
  END LOOP;

  -- Dan and Ed are pupils of the side, as every pupil is.
  INSERT INTO role_assignment (person_id, role, school_id, team_code)
  SELECT (ids->>k)::uuid, 'player', HIL, 'U15A' FROM unnest(ARRAY['u_dan', 'u_ed']) k;

  -- Pat's mother's link is verified and her consent to processing is not yet
  -- recorded: lifts wait on it (Kameel, 2026-10-01).
  UPDATE assignment_subject SET consent_state = 'pending', consent_version = NULL, consent_at = NULL
   WHERE assignment_id = (ids->>'a_pmum')::uuid;

  -- Who to ring. The driver's own number is on her son's card; it is the one
  -- she names on her declaration.
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES ((ids->>'p_jono')::uuid, 1, 'D Liftseventy', 'mother', '+27 82 070 0001') RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('c_jono', v_a);
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES ((ids->>'p_ben')::uuid, 1, 'B Liftseventy', 'mother', '+27 82 070 0002') RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('c_ben', v_a);
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES ((ids->>'p_carl')::uuid, 1, 'C Liftseventy', 'mother', '+27 82 070 0003');

  -- The fixtures, each on an explicit day at an explicit hour, Johannesburg time.
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id, away_school_id, away_team_code)
  VALUES (HIL, 'U15A', 'Verify 070', ((current_date + 10)::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled', GROUND, WES, 'U15A')
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('m', v_m, 'm_start', (SELECT starts_at FROM match WHERE id = v_m));
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, 'U15A', 'Verify 070 off', ((current_date + 12)::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled', GROUND)
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('mv', v_m, 'mv_start', (SELECT starts_at FROM match WHERE id = v_m));
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, 'U15A', 'Verify 070 tomorrow', ((current_date + 1)::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled', GROUND)
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('mt', v_m);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, 'U15A', 'Verify 070 afternoon', ((current_date + 1)::timestamp + time '14:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled', GROUND)
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('ma', v_m, 'ma_start', (SELECT starts_at FROM match WHERE id = v_m));
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The platform's key, for one school: granted or taken back.
CREATE OR REPLACE FUNCTION _v70_grant(p_school uuid, p_on boolean) RETURNS void AS $$
  INSERT INTO feature_grant (key, school_id, granted, note) VALUES ('lift_club', p_school, p_on, 'verify db/70')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = excluded.granted
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/70's link triggers are deferred, as db/62's are; fire them here.
-- Each by name, and only those that exist, so a falsification that drops one
-- reads as the assertion it breaks rather than as an error here.
CREATE OR REPLACE FUNCTION _v70_fire() RETURNS void AS $$
DECLARE t text;
BEGIN
  FOR t IN SELECT tgname FROM pg_trigger
            WHERE tgname IN ('lift_link_changed', 'lift_guardian_changed', 'lift_team_changed') AND tgconstraint <> 0 LOOP
    EXECUTE format('SET CONSTRAINTS %I IMMEDIATE', t);
    EXECUTE format('SET CONSTRAINTS %I DEFERRED', t);
  END LOOP;
END $$ LANGUAGE plpgsql;

-- An offer and a seat as they are, past RLS.
CREATE OR REPLACE FUNCTION _v70_offer(p uuid) RETURNS lift_offer AS $$ SELECT * FROM lift_offer WHERE id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v70_seat(p uuid) RETURNS lift_seat AS $$ SELECT * FROM lift_seat WHERE id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A seat's derived status, past RLS.
CREATE OR REPLACE FUNCTION _v70_status(p uuid) RETURNS text AS $$ SELECT lift_seat_status(s) FROM lift_seat s WHERE s.id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The lift notices about a fixture: "recipient:title-word" for each, sorted, past RLS.
CREATE OR REPLACE FUNCTION _v70_notices(p_match uuid, p_title text DEFAULT NULL) RETURNS text AS $$
  SELECT coalesce(string_agg(n.recipient_id::text, ' ' ORDER BY n.recipient_id::text), '')
    FROM notification n WHERE n.kind = 'lift' AND n.subject_id = p_match AND (p_title IS NULL OR n.title = p_title)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v70_notice_count(p_to uuid, p_title text DEFAULT NULL) RETURNS bigint AS $$
  SELECT count(*) FROM notification n WHERE n.kind = 'lift' AND n.recipient_id = p_to AND (p_title IS NULL OR n.title = p_title)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The lift notices: kind 'lift', and the 'system' ones a boy of eighteen at
-- school is sent about a lift (SG-9).
CREATE OR REPLACE FUNCTION _v70_is_lift_notice(n notification) RETURNS boolean AS $$
  SELECT n.kind = 'lift'
      OR (n.kind = 'system' AND n.subject_kind = 'match' AND n.subject_id IN (SELECT match_id FROM lift_offer))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Lift notices whose body names a person: any player's full name or any account's name.
CREATE OR REPLACE FUNCTION _v70_named_notices() RETURNS bigint AS $$
  SELECT count(*) FROM notification n
   WHERE _v70_is_lift_notice(n)
     AND (EXISTS (SELECT 1 FROM player p WHERE position(p.full_name IN n.body) > 0)
          OR EXISTS (SELECT 1 FROM app_user u WHERE length(u.name) > 3 AND position(u.name IN n.body) > 0))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Lift notices addressed to a pupil — but the boy of eighteen's own, as
-- 'system', about himself through his own self link.
CREATE OR REPLACE FUNCTION _v70_pupil_notices() RETURNS bigint AS $$
  SELECT count(*) FROM notification n
   WHERE _v70_is_lift_notice(n) AND lift_is_pupil(n.recipient_id)
     AND NOT (n.kind = 'system' AND NOT lift_is_minor(n.subject_person_id)
              AND EXISTS (SELECT 1 FROM role_assignment a JOIN assignment_subject g ON g.assignment_id = a.id
                           WHERE a.person_id = n.recipient_id AND a.role = 'selfaccess'
                             AND g.relationship = 'self' AND g.player_id = n.subject_person_id))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Every lift notice to one person, of either kind, past RLS.
CREATE OR REPLACE FUNCTION _v70_lift_notices_to(p_to uuid) RETURNS bigint AS $$
  SELECT count(*) FROM notification n WHERE n.recipient_id = p_to AND _v70_is_lift_notice(n)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The access log's rows for a lift read, past RLS.
CREATE OR REPLACE FUNCTION _v70_logged(p_resource text, p_offer uuid, p_person uuid DEFAULT NULL) RETURNS bigint AS $$
  SELECT count(*) FROM access_log l
   WHERE l.resource = p_resource AND p_offer = ANY (l.record_ids) AND (p_person IS NULL OR l.person_id = p_person)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The three CSA checks for a person at a school, current.
CREATE OR REPLACE FUNCTION _v70_clear(p_person uuid, p_school uuid) RETURNS void AS $$
  INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
  SELECT p_person, p_school, k, 'V70-' || k, current_date - 30, current_date + 600
    FROM unnest(ARRAY['police_clearance', 'child_protection', 'sexual_offences_register']) k
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A boy moved to another side, as the move route makes it (db/08's history trigger).
CREATE OR REPLACE FUNCTION _v70_move(p uuid, team text) RETURNS void AS $$
  UPDATE player SET team_code = team WHERE id = p;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A guardian's link to a boy revoked by the office, today.
CREATE OR REPLACE FUNCTION _v70_end_link(p uuid, mum uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET verification_state = 'revoked', valid_until = greatest(current_date, s.valid_from)
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = mum AND s.player_id = p AND s.valid_until IS NULL;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A fixture moved, or called off, as the fixture route does it.
CREATE OR REPLACE FUNCTION _v70_fixture(p uuid, p_by interval, p_status text DEFAULT NULL) RETURNS void AS $$
  UPDATE match SET starts_at = starts_at + p_by, status = coalesce(p_status, status) WHERE id = p;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A boy's live seats, past RLS.
CREATE OR REPLACE FUNCTION _v70_seats_of(p uuid) RETURNS SETOF lift_seat AS $$
  SELECT * FROM lift_seat WHERE player_id = p AND state IN ('requested', 'invited', 'confirmed')
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The office records a guardian's consent to processing, as its route does.
CREATE OR REPLACE FUNCTION _v70_consent(p uuid, mum uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET consent_state = 'granted', consent_version = 'popia-2026-01', consent_at = now()
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = mum AND s.player_id = p;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An older brother at school, linked as his younger brother's guardian (p_on),
-- or that assignment ended (not p_on).
CREATE OR REPLACE FUNCTION _v70_brother(p_person uuid, p_player uuid, p_on boolean) RETURNS void AS $$
DECLARE v_a uuid;
BEGIN
  IF p_on THEN
    INSERT INTO role_assignment (person_id, role, school_id)
    VALUES (p_person, 'guardian', (SELECT school_id FROM player WHERE id = p_player)) RETURNING id INTO v_a;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, valid_from)
    VALUES (v_a, p_player, 'sibling', 'verified', p_person, now(), 'granted', 'popia-2026-01', now(), current_date - 1);
  ELSE
    UPDATE role_assignment SET active = false, revoked_at = now()
     WHERE person_id = p_person AND role = 'guardian' AND active;
  END IF;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/70 (section 48) ──────────────────────────────────────────────

-- ┌── SCRBRD-114 phase 3b (db/71, section 50): the super over ──────────
-- A Hilton cup, "Verify 071 Cup", whose matches carry a cup's document
-- (one innings a side, a tie goes to a super over), and a Hilton league,
-- "Verify 071 League" (win 4 / tie 2 / no result 2 / loss 0, confirmed; no
-- tie-break: a tie stands). Every match Hilton 1XI v Westville 1XI on
-- 3 October 2026 (the 4th Edition), one over a side, our boys by id:
-- J Whitfield (…01) and T Bekker (…02) bat, S Naidoo (…03) bowls, M Cele
-- (…04) keeps; Westville's K Botha (bbbb…02) bats and D Mkhize (bbbb…01)
-- bowls; everyone else a typed name. Each match is the same tie:
--   innings 0  Hilton: Whitfield 4 1 0 2 6 1 = 14 off Mkhize, sealed
--   innings 1  Westville chasing 15: Botha 6 6 1 1 0 0 = 14 off Naidoo, sealed
-- and _so_71() appends the super over each one is about:
--   K1  Westville 8/1 (Botha 6 1, caught Cele off Naidoo; W3 1 0 0); Hilton
--       chasing 9: Whitfield 4, bowled Mkhize; Bekker 4 1 — won, by Hilton
--   K2  Westville 6 1, five to the fielding side (time wasting), 1 0 0 0 = 8;
--       Hilton open on the five: Whitfield 1 1 1 1 = 9 — won, by Hilton
--   K3  Westville bowled, bowled: 0/2 off two balls, all out; Hilton a dot
--       ball and the light goes: sealed abandoned — incomplete
--   K4  none: the organiser's award decides it
--   K5  the super over opened: Westville's first ball, on the broadcast board
--   L1  (the league) Westville 8, Hilton 9 — written directly, as the write
--       path refuses a super over the document does not provide (D10)
CREATE OR REPLACE FUNCTION _ev_71(p_match uuid, p_inn smallint, p_kind text, p_bt text, p_v integer, p_dis text,
                                  p_payload jsonb, p_striker uuid DEFAULT NULL, p_bowler uuid DEFAULT NULL)
RETURNS integer AS $$
DECLARE v_seq integer;
BEGIN
  SELECT coalesce(max(b.seq), 0) + 1 INTO v_seq FROM ball_event b WHERE b.match_id = p_match;
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                          client_seq, client_ts, kind, ball_type, value, dismissal, payload, striker_id, bowler_id)
  VALUES (p_match, '11111111-1111-1111-1111-111111111111', v_seq, 1, p_inn, '88888888-0000-0000-0000-000000000006', 'verify-071',
          'v71:' || p_match || ':' || v_seq, v_seq, '2026-10-03 10:00+02'::timestamptz + v_seq * interval '20 seconds',
          p_kind, p_bt, p_v, p_dis, coalesce(p_payload, '{}'::jsonb), p_striker, p_bowler);
  RETURN v_seq;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The squads, as the pad writes them: our boys by id, the rest by name.
CREATE OR REPLACE FUNCTION _sq_71(p_side text) RETURNS jsonb AS $$
  SELECT CASE p_side
    WHEN 'H' THEN jsonb_build_array(jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000001', 'name', 'J Whitfield'),
                                    jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000002', 'name', 'T Bekker'),
                                    jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000003', 'name', 'S Naidoo'),
                                    jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000004', 'name', 'M Cele'))
                  || (SELECT jsonb_agg(jsonb_build_object('id', 'H' || g, 'name', 'H' || g)) FROM generate_series(5, 11) g)
    ELSE jsonb_build_array(jsonb_build_object('id', 'bbbbbbbb-0000-0000-0000-000000000002', 'name', 'K Botha'),
                           jsonb_build_object('id', 'bbbbbbbb-0000-0000-0000-000000000001', 'name', 'D Mkhize'))
         || (SELECT jsonb_agg(jsonb_build_object('id', 'W' || g, 'name', 'W' || g)) FROM generate_series(3, 11) g) END
$$ LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _seed_71() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OWNR uuid := '88888888-0000-0000-0000-000000000022';
  WHIT uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
  NAID uuid := 'aaaaaaaa-0000-0000-0000-000000000003';
  BOTHA uuid := 'bbbbbbbb-0000-0000-0000-000000000002';
  MKHI uuid := 'bbbbbbbb-0000-0000-0000-000000000001';
  cup uuid; lg uuid; v1 uuid; m uuid; out jsonb := '{}';
  cupdoc jsonb := '{"v":1,"play":{"format.kind":"limited","format.innings_per_side":1,"result.tie_break":"super_over"},"table":{},"sheet":{}}';
  lab text; v integer;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 071 Cup', 'knockout', 'T20', 'school') RETURNING id INTO cup;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES
    (cup, HIL, '1XI', 'Verify 071 Hilton 1st XI'), (cup, WES, '1XI', 'Verify 071 Westville 1st XI');
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 071 League', 'league', 'T20', 'school') RETURNING id INTO lg;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES
    (lg, HIL, '1XI', 'Verify 071 Hilton 1st XI'), (lg, WES, '1XI', 'Verify 071 Westville 1st XI');
  INSERT INTO condition_set (competition_id, version, title, effective_from, created_by) VALUES (lg, 1, 'Verify 071 v1', '2026-09-28', OWNR) RETURNING id INTO v1;
  INSERT INTO condition_value (set_id, key, value, status, source_document, source_clause, source_date, entered_by)
  SELECT v1, x.k, x.v, 'confirmed', 'Pilot league decision, Kameel', '8.3a', '2026-09-30', OWNR
    FROM (VALUES ('points.win', '4'::jsonb), ('points.tie', '2'), ('points.no_result', '2'), ('points.loss', '0')) AS x(k, v);
  UPDATE condition_set SET status = 'published', published_by = OWNR, published_at = '2026-09-27 12:00+02' WHERE id = v1;
  out := jsonb_build_object('cup', cup, 'league', lg);

  FOREACH lab IN ARRAY ARRAY['k1', 'k2', 'k3', 'k4', 'k5', 'l1'] LOOP
    INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
    VALUES (HIL, '1XI', WES, '1XI', 'Westville 1XI', '2026-10-03 10:00+02', 'cricket', 'T20', 1, 'live',
            CASE WHEN lab = 'l1' THEN lg ELSE cup END)
    RETURNING id INTO m;
    IF lab = 'l1' THEN
      INSERT INTO match_conditions (match_id, set_id, set_version, doc, sources, doc_hash)
      SELECT m, r.set_id, r.set_version, r.doc, r.sources, '' FROM match_conditions_compute(m) r;
    ELSE
      INSERT INTO match_conditions (match_id, doc, sources, doc_hash) VALUES (m, cupdoc, '{}', '');
    END IF;
    PERFORM _ev_71(m, 0::smallint, 'innings_start', NULL, NULL, NULL,
                   jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Westville 1XI', 'squad', _sq_71('H'), 'bowlingSquad', _sq_71('W'), 'overs', 1));
    FOREACH v IN ARRAY ARRAY[4, 1, 0, 2, 6, 1] LOOP
      PERFORM _ev_71(m, 0::smallint, 'ball', 'run', v, NULL, NULL, WHIT, MKHI);
    END LOOP;
    PERFORM _ev_71(m, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":14,"wickets":0,"balls":6}}');
    PERFORM _ev_71(m, 1::smallint, 'innings_start', NULL, NULL, NULL,
                   jsonb_build_object('battingTeam', 'Westville 1XI', 'bowlingTeam', '1XI', 'squad', _sq_71('W'), 'bowlingSquad', _sq_71('H'), 'overs', 1, 'target', 15));
    FOREACH v IN ARRAY ARRAY[6, 6, 1, 1, 0, 0] LOOP
      PERFORM _ev_71(m, 1::smallint, 'ball', 'run', v, NULL, NULL, BOTHA, NAID);
    END LOOP;
    PERFORM _ev_71(m, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":14,"wickets":0,"balls":6}}');
    out := out || jsonb_build_object(lab, m);
    IF lab = 'k5' THEN
      INSERT INTO match_broadcast (match_id, school_id, published, published_by) VALUES (m, HIL, true, OWNR);
    END IF;
  END LOOP;
  RETURN out;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The super over each match is about (above). Written as the pad writes it:
-- the pair's innings_starts carry superOver 1, the second its target.
CREATE OR REPLACE FUNCTION _so_71(p_match uuid, p_variant text) RETURNS void AS $$
DECLARE
  WHIT uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
  BEKK uuid := 'aaaaaaaa-0000-0000-0000-000000000002';
  NAID uuid := 'aaaaaaaa-0000-0000-0000-000000000003';
  CELE text := 'aaaaaaaa-0000-0000-0000-000000000004';
  BOTHA uuid := 'bbbbbbbb-0000-0000-0000-000000000002';
  MKHI uuid := 'bbbbbbbb-0000-0000-0000-000000000001';
  v integer;
BEGIN
  PERFORM _ev_71(p_match, 2::smallint, 'innings_start', NULL, NULL, NULL,
                 jsonb_build_object('battingTeam', 'Westville 1XI', 'bowlingTeam', '1XI', 'squad', _sq_71('W'), 'bowlingSquad', _sq_71('H'), 'overs', 1, 'superOver', 1));
  PERFORM _ev_71(p_match, 2::smallint, 'keeper', NULL, NULL, NULL, jsonb_build_object('keeper', CELE));
  IF p_variant = 'k5' THEN
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'run', 1, NULL, NULL, BOTHA, NAID);
    RETURN;
  END IF;
  IF p_variant = 'k3' THEN
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'W', 0, 'bowled', NULL, BOTHA, NAID);
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'W', 0, 'bowled', '{"striker":"W3"}', NULL, NAID);
    PERFORM _ev_71(p_match, 2::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"all_out","confirmed":{"runs":0,"wickets":2,"balls":2}}');
    PERFORM _ev_71(p_match, 3::smallint, 'innings_start', NULL, NULL, NULL,
                   jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Westville 1XI', 'squad', _sq_71('H'), 'bowlingSquad', _sq_71('W'), 'overs', 1, 'target', 1, 'superOver', 1));
    PERFORM _ev_71(p_match, 3::smallint, 'ball', 'run', 0, NULL, NULL, WHIT, MKHI);
    PERFORM _ev_71(p_match, 3::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"abandoned","confirmed":{"runs":0,"wickets":0,"balls":1}}');
    RETURN;
  END IF;
  PERFORM _ev_71(p_match, 2::smallint, 'ball', 'run', 6, NULL, NULL, BOTHA, NAID);
  PERFORM _ev_71(p_match, 2::smallint, 'ball', 'run', 1, NULL, NULL, BOTHA, NAID);
  IF p_variant = 'k2' THEN
    PERFORM _ev_71(p_match, 2::smallint, 'penalty', NULL, NULL, NULL, '{"runs":5,"toBattingTeam":false,"reason":"time_wasting"}');
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'run', 1, NULL, NULL, BOTHA, NAID);
  ELSE
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'W', 0, 'caught', jsonb_build_object('fielder', CELE), BOTHA, NAID);
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'run', 1, NULL, '{"striker":"W3"}', NULL, NAID);
  END IF;
  -- Six balls in all: K2's penalty is no delivery, K1's wicket is one.
  FOREACH v IN ARRAY CASE WHEN p_variant = 'k2' THEN ARRAY[0, 0, 0] ELSE ARRAY[0, 0] END LOOP
    PERFORM _ev_71(p_match, 2::smallint, 'ball', 'run', v, NULL, '{"striker":"W3"}', NULL, NAID);
  END LOOP;
  PERFORM _ev_71(p_match, 2::smallint, 'innings_end', NULL, NULL, NULL,
                 CASE WHEN p_variant = 'k2' THEN '{"reason":"overs_complete","confirmed":{"runs":8,"wickets":0,"balls":6}}'
                      ELSE '{"reason":"overs_complete","confirmed":{"runs":8,"wickets":1,"balls":6}}' END::jsonb);
  PERFORM _ev_71(p_match, 3::smallint, 'innings_start', NULL, NULL, NULL,
                 jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Westville 1XI', 'squad', _sq_71('H'), 'bowlingSquad', _sq_71('W'), 'overs', 1, 'target', 9, 'superOver', 1));
  IF p_variant = 'k2' THEN
    FOREACH v IN ARRAY ARRAY[1, 1, 1, 1] LOOP
      PERFORM _ev_71(p_match, 3::smallint, 'ball', 'run', v, NULL, NULL, WHIT, MKHI);
    END LOOP;
    PERFORM _ev_71(p_match, 3::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":9,"wickets":0,"balls":4}}');
  ELSE
    PERFORM _ev_71(p_match, 3::smallint, 'ball', 'run', 4, NULL, NULL, WHIT, MKHI);
    PERFORM _ev_71(p_match, 3::smallint, 'ball', 'W', 0, 'bowled', NULL, WHIT, MKHI);
    PERFORM _ev_71(p_match, 3::smallint, 'ball', 'run', 4, NULL, NULL, BEKK, MKHI);
    PERFORM _ev_71(p_match, 3::smallint, 'ball', 'run', 1, NULL, NULL, BEKK, MKHI);
    PERFORM _ev_71(p_match, 3::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":9,"wickets":1,"balls":4}}');
  END IF;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Every career figure of our three boys and the keeper in one match, and
-- their lifetimes, as the reader may see them: one line, compared before
-- and after a super over is appended (db/64's (typed) proof shape).
CREATE OR REPLACE FUNCTION _careers_71(p_match uuid) RETURNS text AS $$
  SELECT concat_ws(' | ',
    (SELECT string_agg(concat_ws(',', x.player_id, x.innings, x.runs, x.balls_faced, x.out), ';' ORDER BY x.player_id, x.innings)
       FROM player_innings x WHERE x.match_id = p_match),
    (SELECT string_agg(concat_ws(',', x.player_id, x.matches, x.runs, x.balls_faced, x.fours, x.sixes), ';' ORDER BY x.player_id)
       FROM player_batting_career x WHERE x.player_id IN ('aaaaaaaa-0000-0000-0000-000000000001', 'aaaaaaaa-0000-0000-0000-000000000002')),
    (SELECT string_agg(concat_ws(',', x.player_id, x.season, x.runs, x.balls_faced), ';' ORDER BY x.player_id, x.season)
       FROM player_batting_by_season x WHERE x.player_id IN ('aaaaaaaa-0000-0000-0000-000000000001', 'aaaaaaaa-0000-0000-0000-000000000002')),
    (SELECT row(s.*)::text FROM player_batting_since('aaaaaaaa-0000-0000-0000-000000000001', NULL) s),
    (SELECT row(s.*)::text FROM player_batting_since('aaaaaaaa-0000-0000-0000-000000000002', NULL) s),
    (SELECT string_agg(concat_ws(',', x.player_id, x.matches, x.runs_conceded, x.legal_balls, x.wickets), ';' ORDER BY x.player_id)
       FROM player_bowling_career x WHERE x.player_id = 'aaaaaaaa-0000-0000-0000-000000000003'),
    (SELECT string_agg(concat_ws(',', x.season, x.runs_conceded, x.legal_balls, x.wickets), ';' ORDER BY x.season)
       FROM player_bowling_by_season x WHERE x.player_id = 'aaaaaaaa-0000-0000-0000-000000000003'),
    (SELECT row(s.*)::text FROM player_bowling_since('aaaaaaaa-0000-0000-0000-000000000003', NULL) s),
    (SELECT string_agg(concat_ws(',', x.innings, x.wickets, x.runs_conceded), ';' ORDER BY x.innings)
       FROM bowler_innings_figures x WHERE x.match_id = p_match AND x.player_id = 'aaaaaaaa-0000-0000-0000-000000000003'),
    (SELECT string_agg(concat_ws(',', x.dismissal, x.wickets), ';' ORDER BY x.dismissal)
       FROM player_wicket_breakdown x WHERE x.player_id = 'aaaaaaaa-0000-0000-0000-000000000003'),
    (SELECT string_agg(concat_ws(',', x.player_id, x.dismissals), ';' ORDER BY x.player_id)
       FROM player_dismissals x WHERE x.player_id IN ('aaaaaaaa-0000-0000-0000-000000000001', 'aaaaaaaa-0000-0000-0000-000000000002')),
    (SELECT string_agg(concat_ws(',', x.player_id, x.season, x.dismissals), ';' ORDER BY x.player_id, x.season)
       FROM player_dismissals_by_season x WHERE x.player_id = 'aaaaaaaa-0000-0000-0000-000000000001'),
    player_dismissals_since('aaaaaaaa-0000-0000-0000-000000000001', NULL)::text,
    (SELECT string_agg(concat_ws(',', x.dismissal, x.dismissals), ';' ORDER BY x.dismissal)
       FROM player_dismissal_breakdown x WHERE x.player_id = 'aaaaaaaa-0000-0000-0000-000000000001'),
    (SELECT string_agg(concat_ws(',', x.matches, x.innings_kept, x.catches, x.stumpings), ';')
       FROM player_keeping_career x WHERE x.player_id = 'aaaaaaaa-0000-0000-0000-000000000004'),
    (SELECT count(*)::text FROM keeper_dismissal x WHERE x.match_id = p_match),
    (SELECT count(*)::text FROM bowler_hat_trick x WHERE x.match_id = p_match))
$$ LANGUAGE sql STABLE SET search_path = pg_catalog, public, pg_temp;
-- A boy's match deliveries on a day, as load_day counts them (the owner's
-- read: load_day is not the application's to select).
CREATE OR REPLACE FUNCTION _load_71(p_player uuid, p_on date) RETURNS integer AS $$
  SELECT x.match_units FROM load_day x WHERE x.player_id = p_player AND x.on_date = p_on
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/71 (section 50) ──────────────────────────────────────────────

-- ┌── SCRBRD-114 phase 3c (db/72, section 51): knockout progression ────
-- A Hilton cup, "Verify 072 Cup", four entrants: Hilton 1XI and 2XI,
-- Westville 1XI and 2XI. Two semi-finals on 3 October 2026, each one over a
-- side, complete:
--   U1  Hilton 1XI 14; Westville 1XI 10 chasing 15 — Hilton 1XI by 4 runs
--   U2  Hilton 2XI 6;  Westville 2XI 7 chasing 7  — Westville 2XI by 9 wickets
--       (its last ball the winning single: seq 15)
--   U3  Hilton 1XI v Westville 2XI, never played: no winner
-- and the final, D: Hilton 1XI v Westville 2XI on 10 October, made as the
-- planner's publish makes it, its two rows recorded in §51.
CREATE OR REPLACE FUNCTION _seed_72() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  c uuid; u1 uuid; u2 uuid; u3 uuid; d uuid; v integer;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 072 Cup', 'knockout', 'T20', 'school') RETURNING id INTO c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES
    (c, HIL, '1XI', 'Verify 072 Hilton 1st XI'), (c, WES, '1XI', 'Verify 072 Westville 1st XI'),
    (c, HIL, '2XI', 'Verify 072 Hilton 2nd XI'), (c, WES, '2XI', 'Verify 072 Westville 2nd XI');
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '1XI', WES, '1XI', 'x', '2026-10-03 10:00+02', 'cricket', 'T20', 1, 'complete', c) RETURNING id INTO u1;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '2XI', WES, '2XI', 'x', '2026-10-03 13:00+02', 'cricket', 'T20', 1, 'complete', c) RETURNING id INTO u2;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '1XI', WES, '2XI', 'x', '2026-10-03 15:00+02', 'cricket', 'T20', 1, 'scheduled', c) RETURNING id INTO u3;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '1XI', WES, '2XI', 'x', '2026-10-10 10:00+02', 'cricket', 'T20', 1, 'scheduled', c) RETURNING id INTO d;
  -- U1: Hilton 1XI 14; Westville 1XI 10 chasing 15.
  PERFORM _ev_71(u1, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Westville 1XI', 'overs', 1));
  FOREACH v IN ARRAY ARRAY[4, 1, 0, 2, 6, 1] LOOP PERFORM _ev_71(u1, 0::smallint, 'ball', 'run', v, NULL, NULL); END LOOP;
  PERFORM _ev_71(u1, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":14,"wickets":0,"balls":6}}');
  PERFORM _ev_71(u1, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', 'Westville 1XI', 'bowlingTeam', '1XI', 'overs', 1, 'target', 15));
  FOREACH v IN ARRAY ARRAY[4, 4, 1, 1, 0, 0] LOOP PERFORM _ev_71(u1, 1::smallint, 'ball', 'run', v, NULL, NULL); END LOOP;
  PERFORM _ev_71(u1, 1::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":10,"wickets":0,"balls":6}}');
  -- U2: Hilton 2XI 6; Westville 2XI 7 chasing 7, the single at seq 15 reaching it.
  PERFORM _ev_71(u2, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '2XI', 'bowlingTeam', 'Westville 2XI', 'overs', 1));
  FOREACH v IN ARRAY ARRAY[1, 1, 1, 1, 1, 1] LOOP PERFORM _ev_71(u2, 0::smallint, 'ball', 'run', v, NULL, NULL); END LOOP;
  PERFORM _ev_71(u2, 0::smallint, 'innings_end', NULL, NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":6,"wickets":0,"balls":6}}');
  PERFORM _ev_71(u2, 1::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', 'Westville 2XI', 'bowlingTeam', '2XI', 'overs', 1, 'target', 7));
  FOREACH v IN ARRAY ARRAY[6, 0, 0, 0, 0, 1] LOOP PERFORM _ev_71(u2, 1::smallint, 'ball', 'run', v, NULL, NULL); END LOOP;
  RETURN jsonb_build_object('c', c, 'u1', u1, 'u2', u2, 'u3', u3, 'd', d);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- An approved correction, as scoring_amendment_decide() writes one: a void
-- of the event at p_seq, appended to the log.
CREATE OR REPLACE FUNCTION _void_72(p_match uuid, p_seq integer) RETURNS void AS $$
  SELECT _ev_71(p_match, (SELECT b.innings FROM ball_event b WHERE b.match_id = p_match AND b.seq = p_seq), 'void', NULL, NULL, NULL,
                jsonb_build_object('target', 'v71:' || p_match || ':' || p_seq));
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A match's two sides, and the knockout notices about it, as the owner reads them.
CREATE OR REPLACE FUNCTION _sides_72(p_match uuid) RETURNS text AS $$
  SELECT CASE m.school_id WHEN '11111111-1111-1111-1111-111111111111' THEN 'HIL' ELSE 'WES' END || ' ' || m.team_code || ' v '
      || CASE m.away_school_id WHEN '11111111-1111-1111-1111-111111111111' THEN 'HIL' ELSE 'WES' END || ' ' || m.away_team_code
    FROM match m WHERE m.id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _notices_72(p_match uuid) RETURNS integer AS $$
  SELECT count(*)::integer FROM notification n WHERE n.subject_kind = 'match' AND n.subject_id = p_match AND n.kind = 'fixture'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A row, as the owner reads it.
CREATE OR REPLACE FUNCTION _row_72(p_match uuid, p_side text) RETURNS match_progression AS $$
  SELECT * FROM match_progression p WHERE p.match_id = p_match AND p.side = p_side
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/72 (section 51) ──────────────────────────────────────────────

-- ┌── db/73 (section 52). SCRBRD-130 R1: rain — interruptions, par, NRR ──
-- A league Hilton organises, "Verify 073 Rain", Hilton 1XI (A) against
-- Westville 1XI (B), its version 1 (from 1 October) confirming win 4, tie 2,
-- no result 2, loss 0 and target.method dls_standard. Every match on
-- 10 October 2026, each with the document its first event would fix:
--   L1  A 24/0 (12 balls); B chasing 25 reach 14/1 off 9, rain, terminated;
--       the umpires' par 18: A by 4 runs (DLS)
--   L2  A 24/0; B 6/0 off 6, rain; the umpires cut the chase to 1 over and
--       the target to 10, play resumes and the over is done: A by 3 runs (DLS)
--   L3  A 24/0; B 25/0 off 7: B by 10 wickets — no revision
-- and Hilton friendlies under the platform's default method (the umpires'
-- revision): F1 the chase terminated at 15/0 off 9 level with a par of 15 (a
-- tie), F2 above a par of 13 (won), F3 terminated with no par (no result),
-- F4 as F2 under a document asking two overs a side (no result: one over
-- faced), F5 a first innings stopped at 0.5 and not resumed. P and W are
-- the same six balls to named boys, W with a stop and a resumption in the
-- middle (careers). Every name here is invented.
CREATE OR REPLACE FUNCTION _ev_73(p_match uuid, p_inn smallint, p_kind text, p_bt text, p_v integer, p_payload jsonb,
                                  p_striker uuid DEFAULT NULL, p_bowler uuid DEFAULT NULL, p_n integer DEFAULT 1)
RETURNS integer AS $$
DECLARE v_seq integer; k integer; v_school uuid;
BEGIN
  SELECT m.school_id INTO v_school FROM match m WHERE m.id = p_match;
  FOR k IN 1..p_n LOOP
    SELECT coalesce(max(b.seq), 0) + 1 INTO v_seq FROM ball_event b WHERE b.match_id = p_match;
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                            client_seq, client_ts, kind, ball_type, value, dismissal, striker_id, bowler_id, payload)
    VALUES (p_match, v_school, v_seq, 1, p_inn, '88888888-0000-0000-0000-000000000006', 'verify-073',
            'v73:' || p_match || ':' || v_seq, v_seq, '2026-10-10 10:00+02'::timestamptz + v_seq * interval '20 seconds',
            p_kind, p_bt, p_v, CASE WHEN p_bt = 'W' THEN 'bowled' END, p_striker, p_bowler, p_payload);
  END LOOP;
  RETURN v_seq;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A's 24 off two overs, sealed; then the chase's innings_start.
CREATE OR REPLACE FUNCTION _first24_73(p_match uuid, p_overs integer, p_target integer) RETURNS void AS $$
DECLARE lab text; sq jsonb := (SELECT jsonb_agg(jsonb_build_object('id', 'V73 P' || g, 'name', 'V73 P' || g)) FROM generate_series(1, 11) g);
BEGIN
  SELECT coalesce(m.opponent, 'x') INTO lab FROM match m WHERE m.id = p_match;
  PERFORM _ev_73(p_match, 0::smallint, 'innings_start', NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', lab, 'squad', sq, 'overs', 2));
  PERFORM _ev_73(p_match, 0::smallint, 'ball', 'run', 2, '{}', NULL, NULL, 12);
  PERFORM _ev_73(p_match, 0::smallint, 'innings_end', NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":24,"wickets":0,"balls":12}}');
  PERFORM _ev_73(p_match, 1::smallint, 'innings_start', NULL, NULL,
                 jsonb_build_object('battingTeam', lab, 'bowlingTeam', '1XI', 'squad', sq, 'overs', p_overs, 'target', p_target));
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _seed_73() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OWNR uuid := '88888888-0000-0000-0000-000000000022';
  P1 uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
  P2 uuid := 'aaaaaaaa-0000-0000-0000-000000000002';
  BW uuid := 'bbbbbbbb-0000-0000-0000-000000000001';
  c uuid; v1 uuid; ea uuid; eb uuid;
  l1 uuid; l2 uuid; l3 uuid; f1 uuid; f2 uuid; f3 uuid; f4 uuid; f5 uuid; mp uuid; mw uuid; x uuid;
  so uuid;   -- the super over after a DLS tie (db/71 merged, 2026-10-01)
  T timestamptz := '2026-10-10 10:00+02';
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 073 Rain', 'league', 'T20', 'school') RETURNING id INTO c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, HIL, '1XI', 'Verify 073 Hilton 1st XI') RETURNING id INTO ea;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES (c, WES, '1XI', 'Verify 073 Westville 1st XI') RETURNING id INTO eb;
  INSERT INTO condition_set (competition_id, version, title, effective_from, created_by) VALUES (c, 1, 'Verify 073 v1', '2026-10-01', OWNR) RETURNING id INTO v1;
  INSERT INTO condition_value (set_id, key, value, status, source_document, source_clause, source_date, entered_by)
  SELECT v1, y.k, y.v, 'confirmed', 'Verify 073 league rules', '4.1', '2026-10-01', OWNR
    FROM (VALUES ('points.win', '4'::jsonb), ('points.tie', '2'), ('points.no_result', '2'), ('points.loss', '0'),
                 ('target.method', '"dls_standard"')) AS y(k, v);
  UPDATE condition_set SET status = 'published', published_by = OWNR, published_at = '2026-09-30 12:00+02' WHERE id = v1;

  FOREACH x IN ARRAY ARRAY[gen_random_uuid(), gen_random_uuid(), gen_random_uuid()] LOOP
    INSERT INTO match (id, school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
    VALUES (x, HIL, '1XI', WES, '1XI', 'Westville 1XI', T, 'cricket', 'T20', 2, 'complete', c);
    IF l1 IS NULL THEN l1 := x; ELSIF l2 IS NULL THEN l2 := x; ELSE l3 := x; END IF;
  END LOOP;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Friendly', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Friendly', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO f2;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Friendly', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO f3;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Friendly', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO f4;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Friendly', T, 'cricket', 'T20', 2, 'live') RETURNING id INTO f5;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Careers', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO mp;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Careers', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO mw;
  INSERT INTO match_conditions (match_id, set_id, set_version, doc, sources, doc_hash)
  SELECT y.m, r.set_id, r.set_version, r.doc, r.sources, ''
    FROM unnest(ARRAY[l1, l2, l3, f1, f2, f3, f5]) AS y(m), LATERAL match_conditions_compute(y.m) r;
  INSERT INTO match_conditions (match_id, doc, sources, doc_hash)
  VALUES (f4, '{"v": 1, "play": {"result.min_overs_per_side": 2, "target.method": "dls_standard"}, "table": {}, "sheet": {}}', '{}', '');

  -- L1: B 14/1 off 9, rain, the par 18, terminated.
  PERFORM _first24_73(l1, 2, 25);
  PERFORM _ev_73(l1, 1::smallint, 'ball', 'run', 2, '{}', NULL, NULL, 6);
  PERFORM _ev_73(l1, 1::smallint, 'ball', 'run', 1, '{}');
  PERFORM _ev_73(l1, 1::smallint, 'ball', 'W', 0, '{}');
  PERFORM _ev_73(l1, 1::smallint, 'ball', 'run', 1, '{}');
  PERFORM _ev_73(l1, 1::smallint, 'play_stopped', NULL, NULL, '{"reason":"rain"}');
  PERFORM _ev_73(l1, 1::smallint, 'revision', NULL, NULL, '{"overs":null,"target":null,"reason":"rain","par":18}');
  PERFORM _ev_73(l1, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"abandoned","confirmed":{"runs":14,"wickets":1,"balls":9}}');
  -- L2: B 6/0 off 6, rain; cut to 1 over, target 10; resumed; the over done.
  PERFORM _first24_73(l2, 2, 25);
  PERFORM _ev_73(l2, 1::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 6);
  PERFORM _ev_73(l2, 1::smallint, 'play_stopped', NULL, NULL, '{"reason":"rain"}');
  PERFORM _ev_73(l2, 1::smallint, 'revision', NULL, NULL, '{"overs":1,"target":10,"reason":"rain"}');
  PERFORM _ev_73(l2, 1::smallint, 'play_resumed', NULL, NULL, '{}');
  PERFORM _ev_73(l2, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":6,"wickets":0,"balls":6}}');
  -- L3: B 25/0 off 7, no revision.
  PERFORM _first24_73(l3, 2, 25);
  PERFORM _ev_73(l3, 1::smallint, 'ball', 'run', 4, '{}', NULL, NULL, 6);
  PERFORM _ev_73(l3, 1::smallint, 'ball', 'run', 1, '{}');
  PERFORM _ev_73(l3, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":25,"wickets":0,"balls":7}}');
  -- F1–F4: 15/0 off 9, rain, then each its own ending.
  FOREACH x IN ARRAY ARRAY[f1, f2, f3, f4] LOOP
    PERFORM _first24_73(x, 2, 25);
    PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 2, '{}', NULL, NULL, 6);
    PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 3);
    PERFORM _ev_73(x, 1::smallint, 'play_stopped', NULL, NULL,
                   CASE WHEN x = f1 THEN '{"reason":"rain","note":"covers on: a private note","at":1791622800000}'::jsonb ELSE '{"reason":"bad_light"}'::jsonb END);
    IF x <> f3 THEN
      PERFORM _ev_73(x, 1::smallint, 'revision', NULL, NULL, jsonb_build_object('overs', NULL, 'target', NULL, 'reason', 'rain', 'par', CASE WHEN x = f1 THEN 15 ELSE 13 END));
    END IF;
    PERFORM _ev_73(x, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"abandoned","confirmed":{"runs":15,"wickets":0,"balls":9}}');
  END LOOP;
  -- F5: a first innings stopped at 0.5, not resumed.
  PERFORM _ev_73(f5, 0::smallint, 'innings_start', NULL, NULL, '{"battingTeam":"1XI","bowlingTeam":"Verify 073 Friendly","overs":2}');
  PERFORM _ev_73(f5, 0::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 5);
  PERFORM _ev_73(f5, 0::smallint, 'play_stopped', NULL, NULL, '{"reason":"wet_ground"}');
  -- P and W: 1 4 0 2 6 1 to two Hilton boys off a Westville bowler; W stops after the third.
  FOREACH x IN ARRAY ARRAY[mp, mw] LOOP
    PERFORM _ev_73(x, 0::smallint, 'innings_start', NULL, NULL, '{"battingTeam":"1XI","bowlingTeam":"Verify 073 Careers","overs":2}');
    PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 1, '{}', P1, BW);
    PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 4, '{}', P2, BW);
    PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 0, '{}', P2, BW);
    IF x = mw THEN
      PERFORM _ev_73(x, 0::smallint, 'play_stopped', NULL, NULL, '{"reason":"rain"}');
      PERFORM _ev_73(x, 0::smallint, 'play_resumed', NULL, NULL, '{}');
    END IF;
    PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 2, '{}', P2, BW);
    PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 6, '{}', P2, BW);
    PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 1, '{}', P2, BW);
  END LOOP;
  -- SO: F1's tie on the umpires' par (15/0 off 9, par 15) under a document
  -- whose tie goes to a super over (db/71) and whose method is DLS; the
  -- super over: the visitors 6 off the over, Hilton chasing 7 reach 8.
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES (HIL, '1XI', 'Verify 073 Friendly', T, 'cricket', 'T20', 2, 'complete') RETURNING id INTO so;
  INSERT INTO match_conditions (match_id, doc, sources, doc_hash)
  VALUES (so, '{"v": 1, "play": {"format.kind": "limited", "format.innings_per_side": 1, "result.tie_break": "super_over", "target.method": "dls_standard"}, "table": {}, "sheet": {}}', '{}', '');
  PERFORM _first24_73(so, 2, 25);
  PERFORM _ev_73(so, 1::smallint, 'ball', 'run', 2, '{}', NULL, NULL, 6);
  PERFORM _ev_73(so, 1::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 3);
  PERFORM _ev_73(so, 1::smallint, 'play_stopped', NULL, NULL, '{"reason":"rain"}');
  PERFORM _ev_73(so, 1::smallint, 'revision', NULL, NULL, '{"overs":null,"target":null,"reason":"rain","par":15}');
  PERFORM _ev_73(so, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"abandoned","confirmed":{"runs":15,"wickets":0,"balls":9}}');
  PERFORM _ev_73(so, 2::smallint, 'innings_start', NULL, NULL, '{"battingTeam":"Verify 073 Friendly","bowlingTeam":"1XI","overs":1,"superOver":1}');
  PERFORM _ev_73(so, 2::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 6);
  PERFORM _ev_73(so, 2::smallint, 'innings_end', NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":6,"wickets":0,"balls":6}}');
  PERFORM _ev_73(so, 3::smallint, 'innings_start', NULL, NULL, '{"battingTeam":"1XI","bowlingTeam":"Verify 073 Friendly","overs":1,"target":7,"superOver":1}');
  PERFORM _ev_73(so, 3::smallint, 'ball', 'run', 4, '{}', NULL, NULL, 2);
  PERFORM _ev_73(so, 3::smallint, 'innings_end', NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":8,"wickets":0,"balls":2}}');
  RETURN jsonb_build_object('c', c, 'a', ea, 'b', eb, 'l1', l1, 'l2', l2, 'l3', l3,
                            'f1', f1, 'f2', f2, 'f3', f3, 'f4', f4, 'f5', f5, 'p', mp, 'w', mw, 'so', so);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Past RLS: publish a fixture's home side (the signed-out log reads it).
CREATE OR REPLACE FUNCTION _publish_73(p_match uuid) RETURNS void AS $$
  INSERT INTO fixture_publication (match_id, side, school_id, team_code, published, set_by)
  SELECT m.id, 'home', m.school_id, m.team_code, true, '88888888-0000-0000-0000-000000000022' FROM match m WHERE m.id = p_match;
$$ LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/73 (section 52) ──────────────────────────────────────────────

-- ┌── db/74 (section 53). SCRBRD-130 R3: venue par ───────────────────────
-- At Hilton a field, "Verify 074 Field" (F), with a pitch on it, "Verify 074
-- Oval B" (P), and a ground of its own, "Verify 074 Other" (X). Twenty-over
-- U15 first innings (Hilton U15A batting first), each a friendly, every one
-- dated explicitly and the match complete:
--   counted   F 2026-10-01 100 · F 2026-10-02 120 (its chase made 200: a
--             second innings) · P 2025-10-03 140 · F 2024-10-04 160 ·
--             F 2026-10-05 150 all out in 18.4, from a scorebook
--   excluded  F 2026-10-06 90, the innings cut from 25 to 20 by the umpires ·
--             F 2026-10-07 40, terminated by rain · F 2026-10-08 250 in a
--             50-over match · F 2023-10-09 300, a fourth season back ·
--             F 2026-10-10 60 by the U14A · X 2026-10-11 200 at another ground
-- So at F (or P) for 20 overs, U15, on 31 October 2026: n 5, par
-- round(670 ÷ 5) = 134, median 140, range 100–160, seasons 2024–2026, one
-- from a book; F's own four mean 132.5 → 133, P's one 140. A year on
-- (31 October 2027) the 2024 innings ages out: 4, insufficient. M2 (the
-- 120) is played against Westville's 1XI, whose coach reads its par (the
-- band is the home side's code: U15).
CREATE OR REPLACE FUNCTION _inn_74(p_match uuid, p_inn smallint, p_bat text, p_bowl text, p_overs integer, p_runs integer, p_balls integer,
                                   p_extra jsonb DEFAULT NULL) RETURNS void AS $$
DECLARE v_school uuid; v_seq integer;
  sq jsonb := (SELECT jsonb_agg(jsonb_build_object('id', 'V74 ' || p_bat || ' ' || g, 'name', 'V74 ' || p_bat || ' ' || g)) FROM generate_series(1, 11) g);
BEGIN
  SELECT m.school_id INTO v_school FROM match m WHERE m.id = p_match;
  SELECT coalesce(max(b.seq), 0) INTO v_seq FROM ball_event b WHERE b.match_id = p_match;
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                          client_seq, client_ts, kind, payload)
  VALUES (p_match, v_school, v_seq + 1, 1, p_inn, '88888888-0000-0000-0000-000000000006', 'verify-074', 'v74:' || p_match || ':' || (v_seq + 1),
          v_seq + 1, '2026-10-01 10:00+02', 'innings_start',
          jsonb_build_object('battingTeam', p_bat, 'bowlingTeam', p_bowl, 'squad', sq, 'overs', p_overs) || coalesce(p_extra, '{}'::jsonb));
  -- p_balls legal balls carrying p_runs: sixes, what is left over, then dots.
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                          client_seq, client_ts, kind, ball_type, value, payload)
  SELECT p_match, v_school, v_seq + 1 + g, 1, p_inn, '88888888-0000-0000-0000-000000000006', 'verify-074',
         'v74:' || p_match || ':' || (v_seq + 1 + g), v_seq + 1 + g, '2026-10-01 10:00+02', 'ball', 'run',
         CASE WHEN g <= p_runs / 6 THEN 6 WHEN g = p_runs / 6 + 1 THEN p_runs % 6 ELSE 0 END, '{}'::jsonb
    FROM generate_series(1, p_balls) g;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _seed_74() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  f uuid; p uuid; x uuid; m uuid; m2 uuid; mx uuid; imp uuid := gen_random_uuid(); v_seq integer;
  r record;
BEGIN
  INSERT INTO ground (school_id, name) VALUES (HIL, 'Verify 074 Field') RETURNING id INTO f;
  INSERT INTO ground (school_id, name, parent_id) VALUES (HIL, 'Verify 074 Oval B', f) RETURNING id INTO p;
  INSERT INTO ground (school_id, name) VALUES (HIL, 'Verify 074 Other') RETURNING id INTO x;
  FOR r IN SELECT * FROM (VALUES
      ('2026-10-01', f, 'U15A', 20, 100, 120, 'plain'),
      ('2026-10-02', f, 'U15A', 20, 120, 120, 'chase'),
      ('2025-10-03', p, 'U15A', 20, 140, 120, 'plain'),
      ('2024-10-04', f, 'U15A', 20, 160, 120, 'plain'),
      ('2026-10-05', f, 'U15A', 20, 150, 112, 'book'),
      ('2026-10-06', f, 'U15A', 25,  90, 120, 'revised'),
      ('2026-10-07', f, 'U15A', 20,  40,  30, 'terminated'),
      ('2026-10-08', f, 'U15A', 50, 250, 300, 'plain'),
      ('2023-10-09', f, 'U15A', 20, 300, 120, 'plain'),
      ('2026-10-10', f, 'U14A', 20,  60, 120, 'plain'),
      ('2026-10-11', x, 'U15A', 20, 200, 120, 'plain')) AS y(d, g, team, overs, runs, balls, how)
  LOOP
    INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, ground_id)
    VALUES (HIL, r.team, CASE WHEN r.how = 'chase' THEN WES END, CASE WHEN r.how = 'chase' THEN '1XI' END, 'Verify 074 Visitors',
            (r.d || ' 10:00+02')::timestamptz, 'cricket', CASE WHEN r.overs = 50 THEN 'One-Day' ELSE 'T20' END,
            CASE WHEN r.how = 'revised' THEN 25 ELSE r.overs END, 'complete', r.g)
    RETURNING id INTO m;
    IF r.how = 'chase' THEN m2 := m; END IF;
    IF r.g = x THEN mx := m; END IF;
    IF r.how = 'book' THEN
      -- A scorebook's innings: the commit's door (db/63) as the owner, its import named.
      PERFORM _inn_74(m, 0::smallint, r.team, 'Verify 074 Visitors', 20, 0, 0);
      PERFORM set_config('scrbrd.scorebook_commit', imp::text, true);
      SELECT coalesce(max(b.seq), 0) + 1 INTO v_seq FROM ball_event b WHERE b.match_id = m;
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                              client_seq, client_ts, kind, payload)
      VALUES (m, HIL, v_seq, 1, 0, '88888888-0000-0000-0000-000000000006', 'scorebook:' || imp, 'v74:' || m || ':book',
              v_seq, '2026-10-05 10:00+02', 'innings_summary',
              jsonb_build_object('card', jsonb_build_object('v', 1, 'innings', 0, 'battingSide', 'home', 'batting', '[]'::jsonb,
                                   'didNotBat', '[]'::jsonb, 'bowling', '[]'::jsonb, 'fallOfWickets', '[]'::jsonb, 'unreconciled', NULL,
                                   'extras', jsonb_build_object('byes', NULL, 'legByes', NULL, 'wides', NULL, 'noBalls', NULL, 'penalty', NULL),
                                   'total', 150, 'wickets', 10, 'overs', '18.4', 'endReason', 'all_out'),
                                 'typed', '{}'::jsonb, 'source', jsonb_build_object('kind', 'scorebook', 'import', imp)));
      PERFORM set_config('scrbrd.scorebook_commit', '', true);
    ELSE
      PERFORM _inn_74(m, 0::smallint, r.team, 'Verify 074 Visitors', r.overs, r.runs, r.balls);
    END IF;
    IF r.how = 'revised' THEN
      -- The umpires cut the innings from 25 to 20: its allotment is then the
      -- grain's, and only the revision excludes it.
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                              client_seq, client_ts, kind, payload)
      VALUES (m, HIL, 1000, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-074', 'v74:' || m || ':rev', 1000,
              '2026-10-06 10:00+02', 'revision', '{"overs": 20, "reason": "rain"}');
    END IF;
    IF r.how = 'terminated' THEN
      SELECT coalesce(max(b.seq), 0) INTO v_seq FROM ball_event b WHERE b.match_id = m;
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key,
                              client_seq, client_ts, kind, payload)
      VALUES (m, HIL, v_seq + 1, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-074', 'v74:' || m || ':stop', v_seq + 1,
              '2026-10-07 10:00+02', 'play_stopped', '{"reason": "rain"}'),
             (m, HIL, v_seq + 2, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-074', 'v74:' || m || ':seal', v_seq + 2,
              '2026-10-07 10:00+02', 'innings_end', '{"reason": "abandoned", "confirmed": {"runs": 40, "wickets": 0, "balls": 30}}');
    END IF;
    IF r.how = 'chase' THEN
      PERFORM _inn_74(m, 1::smallint, 'Verify 074 Visitors', r.team, 20, 200, 120, '{"target": 121}');
    END IF;
  END LOOP;
  RETURN jsonb_build_object('f', f, 'p', p, 'x', x, 'm2', m2, 'mx', mx);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/74 (section 53) ──────────────────────────────────────────────

-- ┌── db/75 (section 54). SCRBRD-130 R2: the DLS table ─────────────────
-- D5: no resource value is ever written here. The cells are the design's
-- synthetic generator, dls.mjs syntheticTable() for a 300-ball innings,
-- round(1000 × b × (10 − w) ÷ 3000) half up, computed — never listed. A
-- patch {"b,w": tenths} changes a cell, {"b,w": null} drops it.
CREATE OR REPLACE FUNCTION _synth_75(p_grain text, p_patch jsonb DEFAULT '{}') RETURNS jsonb AS $$
  SELECT jsonb_agg(jsonb_build_array(b, w, coalesce(p_patch -> (b || ',' || w), to_jsonb((2000 * b * (10 - w) + 3000) / 6000)))
                   ORDER BY b, w)
    FROM generate_series(0, 300, CASE p_grain WHEN 'over' THEN 6 ELSE 1 END) b, generate_series(0, 9) w
   WHERE p_patch -> (b || ',' || w) IS DISTINCT FROM 'null'::jsonb
$$ LANGUAGE sql IMMUTABLE;

-- A table's provenance for the loader, under a title and version of the test's.
CREATE OR REPLACE FUNCTION _meta_75(p_title text, p_version integer, p_grain text) RETURNS jsonb AS $$
  SELECT jsonb_build_object('title', p_title, 'version', p_version, 'grain', p_grain, 'maxBalls', 300,
                            'sourcePublisher', 'Verify 075', 'sourceDocument', 'Verify 075 generator', 'sourceEditionDate', '2026-10-01',
                            'permissionNote', 'Verify 075: synthetic, rolled back, nobody''s permission needed')
$$ LANGUAGE sql IMMUTABLE;

-- Past RLS and the grants, as the owner: run one statement and answer 'ok'
-- or the constraint that refused it.
CREATE OR REPLACE FUNCTION _try_75(p_sql text) RETURNS text AS $$
DECLARE v_con text;
BEGIN
  EXECUTE p_sql;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN coalesce(nullif(v_con, ''), SQLSTATE);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Fix a match: freeze its document from the resolver, as db/61's fixing does.
CREATE OR REPLACE FUNCTION _freeze_75(p_match uuid) RETURNS jsonb AS $$
  INSERT INTO match_conditions (match_id, set_id, set_version, doc, sources, doc_hash)
  SELECT p_match, r.set_id, r.set_version, r.doc, r.sources, '' FROM match_conditions_compute(p_match) r
  RETURNING jsonb_build_object('doc', doc, 'sources', sources);
$$ LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Three Hilton friendlies, unfixed (m0, m1, m2), and a draft version of a
-- league's conditions (v) to try to name the table in.
CREATE OR REPLACE FUNCTION _seed_75() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OWNR uuid := '88888888-0000-0000-0000-000000000022';
  c uuid; v uuid; m0 uuid; m1 uuid; m2 uuid;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 075 League', 'league', 'T20', 'school') RETURNING id INTO c;
  INSERT INTO condition_set (competition_id, version, title, effective_from, created_by) VALUES (c, 1, 'Verify 075 v1', '2026-10-01', OWNR) RETURNING id INTO v;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', 'Verify 075 Friendly', '2026-10-20 10:00+02', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m0;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', 'Verify 075 Friendly', '2026-10-21 10:00+02', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m1;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', 'Verify 075 Friendly', '2026-10-22 10:00+02', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m2;
  RETURN jsonb_build_object('c', c, 'v', v, 'm0', m0, 'm1', m1, 'm2', m2);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/75 (section 54) ──────────────────────────────────────────────

-- ┌── db/76 (section 55). SCRBRD-124 phase 2: the day ─────────────────
-- A world of its own, as section 48's is: at Hilton a U17A side — Kai (the
-- driver's son), Lou (two guardians), Max, Ned, Pip, Ole (eighteen and at
-- school, an account of his own) and Tom (seventeen, an account of his own;
-- both hold the side's player assignment) — a U17B boy (Rex) and his mother,
-- a Westville mother, the U17A's coach and the U17B's, the office, the
-- transport coordinator and a principal. Fixtures on explicit days at
-- explicit hours, Johannesburg time: four tomorrow (MT at ten, MW at two, MX
-- at four, MU at noon), one ten days ahead (MF), and two played long ago for
-- the purge — three years and ten days ago (MP, due), and three years less
-- ten days ago (MQ, not). Written as the owner, as a seed would. Every name
-- here is invented.
CREATE OR REPLACE FUNCTION _seed_76() RETURNS jsonb AS $$
DECLARE
  HIL    uuid := '11111111-1111-1111-1111-111111111111';
  WES    uuid := '22222222-2222-2222-2222-222222222222';
  GROUND uuid := 'ffffffff-0000-0000-0000-000000000001';
  ids    jsonb := '{}';
  r      record;
  v_u uuid; v_a uuid; v_p uuid; v_m uuid;
  s      int := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('kai', 'Kai Liftseventysix', 15, 10, 'hil', 'U17A'),
      ('lou', 'Lou Liftseventysix', 15, 20, 'hil', 'U17A'),
      ('max', 'Max Liftseventysix', 15, 30, 'hil', 'U17A'),
      ('ned', 'Ned Liftseventysix', 16, 40, 'hil', 'U17A'),
      ('pip', 'Pip Liftseventysix', 16, 50, 'hil', 'U17A'),
      ('ole', 'Ole Liftseventysix', 18, 40, 'hil', 'U17A'),
      ('tom', 'Tom Liftseventysix', 17, 40, 'hil', 'U17A'),
      ('rex', 'Rex Liftseventysix', 16, 10, 'hil', 'U17B'),
      ('wes', 'Wes Liftseventysix', 16, 10, 'wes', 'U17A')) AS v(k, nm, age, days, at, team)
  LOOP
    INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
    VALUES (CASE r.at WHEN 'hil' THEN HIL ELSE WES END, r.team, r.nm, split_part(r.nm, ' ', 2), 760 + s, 'batter',
            (current_date - make_interval(years => r.age) - make_interval(days => r.days))::date)
    RETURNING id INTO v_p;
    s := s + 1;
    ids := ids || jsonb_build_object('p_' || r.k, v_p);
  END LOOP;

  FOR r IN SELECT * FROM (VALUES
      ('office', 'schooladmin',          'hil', NULL,   'schooladmin', NULL),
      ('tco',    'transportcoordinator', 'hil', NULL,   'transportcoordinator', NULL),
      ('head',   'principal',            'hil', NULL,   'principal', NULL),
      ('coach',  'coach',                'hil', 'U17A', 'coach', NULL),
      ('bcoach', 'coach',                'hil', 'U17B', 'coach', NULL),
      ('dmum',   'guardian',             'hil', NULL,   'guardian', 'kai'),
      ('lmum',   'guardian',             'hil', NULL,   'guardian', 'lou'),
      ('ldad',   'guardian',             'hil', NULL,   'guardian', 'lou'),
      ('mmum',   'guardian',             'hil', NULL,   'guardian', 'max'),
      ('mdad',   'guardian',             'hil', NULL,   'guardian', 'max'),
      ('nmum',   'guardian',             'hil', NULL,   'guardian', 'ned'),
      ('pmum',   'guardian',             'hil', NULL,   'guardian', 'pip'),
      ('omum',   'guardian',             'hil', NULL,   'guardian', 'ole'),
      ('tmum',   'guardian',             'hil', NULL,   'guardian', 'tom'),
      ('rmum',   'guardian',             'hil', NULL,   'guardian', 'rex'),
      ('wmum',   'guardian',             'wes', NULL,   'guardian', 'wes'),
      ('ole',    'selfaccess',           'hil', NULL,   'player',   'ole'),
      ('tom',    'selfaccess',           'hil', NULL,   'player',   'tom')) AS v(k, role, at, team, urole, child)
  LOOP
    INSERT INTO app_user (school_id, email, name, role, player_id)
    VALUES (CASE r.at WHEN 'hil' THEN HIL ELSE WES END, 'v76.' || r.k || '@example.invalid', 'V76 ' || initcap(r.k), r.urole,
            CASE WHEN r.role = 'selfaccess' THEN (ids->>('p_' || r.child))::uuid END)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    INSERT INTO role_assignment (person_id, role, school_id, team_code)
    VALUES (v_u, r.role, CASE r.at WHEN 'hil' THEN HIL ELSE WES END, r.team)
    RETURNING id INTO v_a;
    ids := ids || jsonb_build_object('a_' || r.k, v_a);
    IF r.child IS NOT NULL THEN
      INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                      consent_state, consent_version, consent_at, created_by, valid_from)
      VALUES (v_a, (ids->>('p_' || r.child))::uuid, CASE r.role WHEN 'selfaccess' THEN 'self' ELSE 'parent' END,
              'verified', (ids->>'u_office')::uuid, now(), 'granted', 'popia-2026-01', now(),
              (ids->>'u_office')::uuid, current_date - 30);
    END IF;
  END LOOP;
  INSERT INTO role_assignment (person_id, role, school_id, team_code)
  SELECT (ids->>k)::uuid, 'player', HIL, 'U17A' FROM unnest(ARRAY['u_ole', 'u_tom']) k;

  -- The driver's own number, on her son's card: the one she names.
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES ((ids->>'p_kai')::uuid, 1, 'D Liftseventysix', 'mother', '+27 82 076 0001') RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('c_kai', v_a);
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES ((ids->>'p_lou')::uuid, 1, 'L Liftseventysix', 'mother', '+27 82 076 0002');

  FOR r IN SELECT * FROM (VALUES
      ('mt', 1, time '10:00', 'scheduled', 'Verify 076 morning'),
      ('mu', 1, time '12:00', 'scheduled', 'Verify 076 noon'),
      ('mw', 1, time '14:00', 'scheduled', 'Verify 076 afternoon'),
      ('mx', 1, time '16:00', 'scheduled', 'Verify 076 evening'),
      ('mf', 10, time '09:00', 'scheduled', 'Verify 076 later')) AS v(k, days, at, st, opp)
  LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
    VALUES (HIL, 'U17A', r.opp, ((current_date + r.days)::timestamp + r.at) AT TIME ZONE 'Africa/Johannesburg',
            'cricket', 'T20', 20, r.st, GROUND)
    RETURNING id INTO v_m;
    ids := ids || jsonb_build_object(r.k, v_m, r.k || '_start', (SELECT starts_at FROM match WHERE id = v_m));
  END LOOP;
  -- Long ago, played: three years and ten days (due), and three years less ten days (not).
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, 'U17A', 'Verify 076 long ago', ((current_date - interval '3 years' - interval '10 days')::date::timestamp + time '09:00')
          AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'complete', GROUND)
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('mp', v_m, 'mp_start', (SELECT starts_at FROM match WHERE id = v_m));
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, 'U17A', 'Verify 076 not so long ago', ((current_date - interval '3 years' + interval '10 days')::date::timestamp + time '09:00')
          AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'complete', GROUND)
  RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('mq', v_m);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/70's and db/76's deferred link triggers, fired now.
CREATE OR REPLACE FUNCTION _v76_fire() RETURNS void AS $$
DECLARE t text;
BEGIN
  FOR t IN SELECT tgname FROM pg_trigger
            WHERE tgname IN ('lift_link_changed', 'lift_guardian_changed', 'lift_team_changed') AND tgconstraint <> 0 LOOP
    EXECUTE format('SET CONSTRAINTS %I IMMEDIATE', t);
    EXECUTE format('SET CONSTRAINTS %I DEFERRED', t);
  END LOOP;
END $$ LANGUAGE plpgsql;

-- An offer and a seat as they are, past RLS.
CREATE OR REPLACE FUNCTION _v76_offer(p uuid) RETURNS lift_offer AS $$ SELECT * FROM lift_offer WHERE id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v76_seat(p uuid) RETURNS lift_seat AS $$ SELECT * FROM lift_seat WHERE id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v76_status(p uuid) RETURNS text AS $$ SELECT lift_seat_status(s) FROM lift_seat s WHERE s.id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The seat of a boy on an offer, past RLS.
CREATE OR REPLACE FUNCTION _v76_seat_of(p_offer uuid, p_player uuid) RETURNS uuid AS $$
  SELECT id FROM lift_seat WHERE offer_id = p_offer AND player_id = p_player ORDER BY created_at DESC LIMIT 1
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Lift notices (kind 'lift', or a boy of eighteen's 'system' one) to one
-- person, by title, past RLS.
CREATE OR REPLACE FUNCTION _v76_told(p_to uuid, p_title text) RETURNS bigint AS $$
  SELECT count(*) FROM notification n
   WHERE n.recipient_id = p_to AND n.title = p_title AND n.kind IN ('lift', 'system') AND n.subject_kind = 'match'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- ...on one fixture.
CREATE OR REPLACE FUNCTION _v76_told_on(p_to uuid, p_title text, p_match uuid) RETURNS bigint AS $$
  SELECT count(*) FROM notification n
   WHERE n.recipient_id = p_to AND n.title = p_title AND n.kind IN ('lift', 'system') AND n.subject_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- ...and to anybody, by title, about one boy.
CREATE OR REPLACE FUNCTION _v76_told_about(p_about uuid, p_title text) RETURNS bigint AS $$
  SELECT count(*) FROM notification n
   WHERE n.subject_person_id = p_about AND n.title = p_title AND n.kind IN ('lift', 'system')
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The access log's rows for a lift read, past RLS.
CREATE OR REPLACE FUNCTION _v76_logged(p_resource text, p_offer uuid, p_person uuid DEFAULT NULL) RETURNS bigint AS $$
  SELECT count(*) FROM access_log l
   WHERE l.resource = p_resource AND p_offer = ANY (l.record_ids) AND (p_person IS NULL OR l.person_id = p_person)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The platform's key for one school, granted.
CREATE OR REPLACE FUNCTION _v76_grant(p_school uuid, p_on boolean) RETURNS void AS $$
  INSERT INTO feature_grant (key, school_id, granted, note) VALUES ('lift_club', p_school, p_on, 'verify db/76')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = excluded.granted
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An offer's meeting moved, as the owner (the clock moved under it, for the watch).
CREATE OR REPLACE FUNCTION _v76_meet(p_offer uuid, p_at timestamptz) RETURNS void AS $$
  UPDATE lift_offer SET meet_at = p_at WHERE id = p_offer
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A lift already under way, as the owner records it: left an hour ago with
-- these boys in; one of them handed over p_ago ago.
CREATE OR REPLACE FUNCTION _v76_under_way(p_offer uuid, p_in uuid[], p_handed uuid, p_ago interval) RETURNS void AS $$
BEGIN
  UPDATE lift_offer SET departed_at = now() - interval '1 hour', state = 'closed' WHERE id = p_offer;
  UPDATE lift_seat SET boarded_at = now() - interval '70 minutes' WHERE offer_id = p_offer AND player_id = ANY (p_in);
  UPDATE lift_seat SET handed_over_at = now() - p_ago, handover_kind = 'received'
   WHERE offer_id = p_offer AND player_id = p_handed;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A boy handed over p_ago ago, as the owner records it (the clock, for the watch).
CREATE OR REPLACE FUNCTION _v76_handed(p_seat uuid, p_ago interval) RETURNS void AS $$
  UPDATE lift_seat SET boarded_at = coalesce(boarded_at, now() - p_ago - interval '1 hour'),
                       handed_over_at = now() - p_ago, handover_kind = 'received' WHERE id = p_seat
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Try, as the owner, to end a lift past the functions: did the row guard refuse?
CREATE OR REPLACE FUNCTION _v76_force_end(p_offer uuid) RETURNS boolean AS $$
BEGIN
  UPDATE lift_offer SET state = 'cancelled', cancel_kind = 'school', cancelled_at = now() WHERE id = p_offer;
  UPDATE lift_offer SET state = 'open', cancel_kind = NULL, cancelled_at = NULL WHERE id = p_offer;
  RETURN false;
EXCEPTION WHEN check_violation THEN RETURN true;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- ...or to take a boy in the car off his seat.
CREATE OR REPLACE FUNCTION _v76_force_unseat(p_seat uuid) RETURNS boolean AS $$
BEGIN
  UPDATE lift_seat SET state = 'void', ended_at = now() WHERE id = p_seat;
  RETURN false;
EXCEPTION WHEN check_violation THEN RETURN true;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A fixture moved, as the fixture route does it.
CREATE OR REPLACE FUNCTION _v76_fixture(p uuid, p_by interval) RETURNS void AS $$
  UPDATE match SET starts_at = starts_at + p_by WHERE id = p;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A guardian's link to a boy revoked by the office, today.
CREATE OR REPLACE FUNCTION _v76_end_link(p uuid, mum uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET verification_state = 'revoked', valid_until = greatest(current_date, s.valid_from)
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = mum AND s.player_id = p AND s.valid_until IS NULL;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A guardian's assignment revoked by the office.
CREATE OR REPLACE FUNCTION _v76_revoke(p_person uuid) RETURNS void AS $$
  UPDATE role_assignment SET active = false, revoked_at = now() WHERE person_id = p_person AND role = 'guardian' AND active;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A lift of long ago, as it was left: two boys on it, done. And a
-- declaration that ended a year and five days ago, and one 300 days ago.
CREATE OR REPLACE FUNCTION _v76_old_lift(p_match uuid, p_driver uuid, p_boys uuid[], p_mums uuid[]) RETURNS uuid AS $$
DECLARE v_o uuid; i int; l record;
BEGIN
  INSERT INTO lift_offer (school_id, match_id, team_code, leg, driver_id, declaration_id, seats, meet_kind, meet_at, fixture_starts_at)
  SELECT m.school_id, m.id, m.team_code, 'out', p_driver,
         (SELECT d.id FROM lift_driver_declaration d WHERE d.person_id = p_driver ORDER BY d.declared_at DESC LIMIT 1),
         3, 'school', m.starts_at - interval '90 minutes', m.starts_at
    FROM match m WHERE m.id = p_match
  RETURNING id INTO v_o;
  FOR i IN 1 .. cardinality(p_boys) LOOP
    SELECT g.assignment_id, g.id INTO l FROM assignment_subject g JOIN role_assignment a ON a.id = g.assignment_id
     WHERE a.person_id = p_mums[i] AND g.player_id = p_boys[i] LIMIT 1;
    INSERT INTO lift_seat (offer_id, school_id, match_id, team_code, leg, player_id, consent_by, guardian_assignment_id,
                           guardian_link_id, requested_by, guardian_ok_version, driver_ok_version, state)
    VALUES (v_o, NULL, NULL, NULL, NULL, p_boys[i], 'guardian', l.assignment_id, l.id, p_mums[i], 1, 1, 'confirmed');
  END LOOP;
  UPDATE lift_offer SET state = 'done' WHERE id = v_o;
  UPDATE lift_seat SET state = 'done' WHERE offer_id = v_o;
  RETURN v_o;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v76_old_declaration(p_person uuid, p_ended_days_ago integer) RETURNS uuid AS $$
  INSERT INTO lift_driver_declaration (person_id, school_id, vehicle_description, registration, seats, licence_held, insured,
                                       roadworthy, belts, code_acknowledged, policy_version, declared_at, expires_on)
  VALUES (p_person, '11111111-1111-1111-1111-111111111111', 'white Polo', 'NP 760', 2, true, true, true, true, true, 1,
          now() - make_interval(days => p_ended_days_ago + 365), current_date - p_ended_days_ago)
  RETURNING id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Rows past RLS: does this lift, this declaration, this seat still exist?
CREATE OR REPLACE FUNCTION _v76_exists(p uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM lift_offer WHERE id = p) OR EXISTS (SELECT 1 FROM lift_seat WHERE id = p)
      OR EXISTS (SELECT 1 FROM lift_driver_declaration WHERE id = p)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v76_seats_on(p uuid) RETURNS bigint AS $$ SELECT count(*) FROM lift_seat WHERE offer_id = p $$
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v76_purge_log(p_school uuid, p_season text) RETURNS lift_purge_log AS $$
  SELECT * FROM lift_purge_log WHERE school_id = p_school AND season = p_season
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- How many adults hold transport.lift.oversee at a school, as db/76 counts them.
CREATE OR REPLACE FUNCTION _v76_overseers(p_school uuid) RETURNS bigint AS $$
  SELECT count(*) FROM lift_staff(p_school, NULL, 'transport.lift.oversee')
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/76 (section 55) ──────────────────────────────────────────────

-- ┌── db/77 (section 56): ending a role (SCRBRD-132 C1) ──────────────
-- Its own world, as the owner: people at Hilton in the roles the section
-- ends and is refused, one child with one verified parent and one pending,
-- and an owner's key held by somebody new. Every date explicit.
CREATE OR REPLACE FUNCTION _seed_77() RETURNS jsonb AS $$
DECLARE
  HIL  uuid := '11111111-1111-1111-1111-111111111111';
  ids  jsonb := '{}'::jsonb;
  r    record;
  v_u  uuid;
  v_a  uuid;
  v_p  uuid;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
  VALUES (HIL, 'U15A', 'Kid Endseventyseven', 'Endseventyseven', 777, 'batter',
          (current_date - interval '14 years' - interval '40 days')::date)
  RETURNING id INTO v_p;
  ids := ids || jsonb_build_object('p_kid', v_p);

  FOR r IN SELECT * FROM (VALUES
      ('office', 'schooladmin',   true,  'schooladmin'),
      ('head',   'principal',     true,  'principal'),
      ('dso',    'dso',           true,  'dso'),
      ('dsob',   'dso',           true,  'dso'),
      ('medic',  'medical',       true,  'medical'),
      ('plat',   'platformadmin', false, 'platformadmin'),
      ('own',    'superadmin',    false, 'superadmin'),
      ('mum',    'guardian',      true,  'guardian'),
      ('dad',    'guardian',      true,  'guardian')) AS v(k, role, at_school, urole)
  LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (CASE WHEN r.at_school THEN HIL END, 'v77.' || r.k || '@example.invalid', 'V77 ' || initcap(r.k), r.urole)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    INSERT INTO role_assignment (person_id, role, school_id, valid_from)
    VALUES (v_u, r.role, CASE WHEN r.at_school THEN HIL END, current_date - 30)
    RETURNING id INTO v_a;
    ids := ids || jsonb_build_object('a_' || r.k, v_a);
  END LOOP;

  -- The principal is also a DSO, and holds the office's key besides.
  INSERT INTO role_assignment (person_id, role, school_id, valid_from)
  VALUES ((ids->>'u_head')::uuid, 'dso', HIL, current_date - 30) RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('a_head_dso', v_a);
  INSERT INTO role_assignment (person_id, role, school_id, valid_from)
  VALUES ((ids->>'u_head')::uuid, 'schooladmin', HIL, current_date - 30) RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('a_head_office', v_a);
  -- The owner's key also coaches a side.
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
  VALUES ((ids->>'u_own')::uuid, 'coach', HIL, 'U15A', current_date - 30) RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('a_own_coach', v_a);
  -- Two keys at two schools: Hilton's office, and Westville's principal. A
  -- principal may appoint medical staff; an office may not.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (HIL, 'v77.twokeys@example.invalid', 'V77 Twokeys', 'schooladmin') RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('u_two', v_u);
  INSERT INTO role_assignment (person_id, role, school_id, valid_from)
  VALUES (v_u, 'schooladmin', HIL, current_date - 30), (v_u, 'principal', '22222222-2222-2222-2222-222222222222', current_date - 30);

  -- Mum's link is verified; Dad's waits for the office.
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES ((ids->>'a_mum')::uuid, v_p, 'parent', 'verified', (ids->>'u_office')::uuid, now(),
          'granted', 'popia-2026-01', now(), (ids->>'u_office')::uuid, current_date - 30);
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, created_by, valid_from)
  VALUES ((ids->>'a_dad')::uuid, v_p, 'parent', (ids->>'u_office')::uuid, current_date - 30);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The rows as the owner reads them, past RLS: the claims are about the record.
CREATE OR REPLACE FUNCTION _v77_assignment(p uuid) RETURNS role_assignment AS $$
  SELECT * FROM role_assignment WHERE id = p
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v77_ending(p uuid) RETURNS role_assignment_ending AS $$
  SELECT * FROM role_assignment_ending WHERE assignment_id = p
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v77_notice(p uuid) RETURNS notification AS $$
  SELECT * FROM notification WHERE id = p
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v77_link(p_assignment uuid) RETURNS assignment_subject AS $$
  SELECT * FROM assignment_subject WHERE assignment_id = p_assignment ORDER BY created_at DESC LIMIT 1
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v77_live_links(p_player uuid) RETURNS integer AS $$
  SELECT live_links FROM player_guardian_status WHERE player_id = p_player
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An open concern about the school's leadership, naming this person (db/57).
CREATE OR REPLACE FUNCTION _v77_concern(p_school uuid, p_person uuid) RETURNS uuid AS $$
  INSERT INTO safeguarding_concern (reference, tenant_id, school_id, about_kind, subject_person_id,
                                    nature, certainty, account)
  VALUES ('SG-V77A-0077', p_school, p_school, 'leadership', p_person,
          '{other}', 'suspicion', 'A concern raised for db/99 section 56 only.')
  RETURNING id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/77 (section 56) ──────────────────────────────────────────────

-- db/78 (section 57). Two Hilton 1XI fixtures against a typed side, written
-- as the owner, each with the same log: the squad; a four placed as a point
-- with every placement field the pad records (contact, trajectory, zone,
-- capture profile, the bowler's approach); a sector-era four; a ball with
-- nothing recorded; a penalty row carrying a stray shot and seg (a kind that
-- is not a ball). Only `pub` will be published. Returns the ids.
CREATE OR REPLACE FUNCTION _seed_78() RETURNS jsonb AS $$
DECLARE
  HIL    uuid := '11111111-1111-1111-1111-111111111111';
  SCORER uuid := '88888888-0000-0000-0000-000000000006';
  v_pub  uuid; v_un uuid; m uuid;
BEGIN
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '1XI', 'Verify Seventyeight College 1XI', now() - interval '1 hour', 'cricket', 'T20', 20, 'live') RETURNING id INTO v_pub;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '1XI', 'Verify Seventyeight College 1XI', now() - interval '1 hour', 'cricket', 'T20', 20, 'live') RETURNING id INTO v_un;
  FOREACH m IN ARRAY ARRAY[v_pub, v_un] LOOP
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq,
                            client_ts, kind, ball_type, value, shot, contact, trajectory, seg, zone, theta, radius,
                            placement_source, placement_null, close_position, capture_profile, payload)
    VALUES
      (m, HIL, 1, 1, 0, SCORER, 'v78', 'v78-' || m || '-1', 1, now(), 'innings_start', NULL, NULL, NULL, NULL, NULL, NULL, NULL,
       NULL, NULL, NULL, NULL, NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Verify Seventyeight College 1XI',
         'overs', 20, 'squad', jsonb_build_array(jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000001', 'name', 'Seed One'),
                                                 jsonb_build_object('id', 'aaaaaaaa-0000-0000-0000-000000000002', 'name', 'Seed Two')),
         'bowlingSquad', jsonb_build_array('Typed Seventyeight'))),
      (m, HIL, 2, 1, 0, SCORER, 'v78', 'v78-' || m || '-2', 2, now(), 'ball', 'run', 4, 'drive', 'middle', 'ground', 8, 'boundary',
       235, 0.35, 'point', NULL, NULL, 'full', '{"bowlerApproach": "over", "bowler": "Typed Seventyeight"}'),
      (m, HIL, 3, 1, 0, SCORER, 'v78', 'v78-' || m || '-3', 3, now(), 'ball', 'run', 4, 'drive', NULL, NULL, 3, 'boundary',
       NULL, NULL, 'sector', NULL, NULL, NULL, '{"bowler": "Typed Seventyeight"}'),
      (m, HIL, 4, 1, 0, SCORER, 'v78', 'v78-' || m || '-4', 4, now(), 'ball', 'run', 0, NULL, NULL, NULL, NULL, NULL,
       NULL, NULL, NULL, 'skipped', NULL, 'quick', '{"bowler": "Typed Seventyeight"}'),
      (m, HIL, 5, 1, 0, SCORER, 'v78', 'v78-' || m || '-5', 5, now(), 'penalty', NULL, NULL, 'pull', NULL, NULL, 5, NULL,
       NULL, NULL, NULL, NULL, NULL, NULL, '{"runs": 5, "toBattingTeam": true, "reason": "helmet_struck"}');
  END LOOP;
  RETURN jsonb_build_object('pub', v_pub, 'un', v_un);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/78 (section 57) ──────────────────────────────────────────────

-- ┌── db/79 (section 58): the audit log, read (SCRBRD-132 B2) ─────────
-- Its own world, as the owner. Readers: Hilton's office (audit.read and the
-- office's key), Westville's office, Hilton's DSO (audit.read without the
-- office's key) and a Hilton coach (no audit.read). Two children, both made
-- up for this section: a pupil with an account (a player row and a player
-- assignment) and a leaver whose only player assignment has ended. And the
-- rows, at known instants on 1 January 2000: at Hilton, the pupil reading his
-- own record, the office reading the pupil's account, a safeguarding read,
-- the leaver's role ended with a reason that names him in full, the pupil
-- taking a scoring pen, the pupil's scorer duty suspended; at Westville, a
-- read and an ended role. Returns the ids.
CREATE OR REPLACE FUNCTION _seed_79() RETURNS jsonb AS $$
DECLARE
  HIL  uuid := '11111111-1111-1111-1111-111111111111';
  WES  uuid := '22222222-2222-2222-2222-222222222222';
  -- Far in the past, so a window on it holds these rows and nothing a real
  -- school wrote: the verify bundle runs against production too.
  T0   timestamptz := timestamptz '2000-01-01 10:00:00+02';
  ids  jsonb := '{}'::jsonb;
  r    record;
  v_u  uuid; v_a uuid; v_p uuid; v_m uuid; v_d uuid;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('office', 'schooladmin', HIL),
      ('wes',    'schooladmin', WES),
      ('dso',    'dso',         HIL),
      ('coach',  'coach',       HIL)) AS v(k, role, school)
  LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (r.school, 'v79.' || r.k || '@example.invalid', 'V79 ' || initcap(r.k), r.role)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
    VALUES (v_u, r.role, r.school, CASE WHEN r.role = 'coach' THEN 'U15A' END, current_date - 30);
  END LOOP;

  -- The pupil: a player row, an account that is that player, a live player
  -- assignment and a scorer's assignment for one fixture.
  INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
  VALUES (HIL, 'U15A', 'Verify Seventynine Pupil', 'Pupil', 779, 'batter',
          (current_date - interval '14 years' - interval '79 days')::date)
  RETURNING id INTO v_p;
  INSERT INTO app_user (school_id, email, name, role, player_id)
  VALUES (HIL, 'v79.pupil@example.invalid', 'Verify Seventynine Pupil', 'player', v_p) RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('p_pupil', v_p, 'u_pupil', v_u);
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
  VALUES (v_u, 'player', HIL, 'U15A', current_date - 30);

  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Section Fiftyeight College U15A', T0, 'cricket', 'T20', 20, 'live') RETURNING id INTO v_m;
  ids := ids || jsonb_build_object('m', v_m);
  INSERT INTO role_assignment (person_id, role, school_id, fixture_id, valid_from)
  VALUES (v_u, 'scorer', HIL, v_m, current_date - 30) RETURNING id INTO v_a;
  INSERT INTO match_official (match_id, school_id, duty, person_name, person_id)
  VALUES (v_m, HIL, 'scorer', 'Verify Seventynine Pupil', v_u) RETURNING id INTO v_d;
  INSERT INTO duty_suspension (duty_id, assignment_id, school_id, suspended_at, suspended_by, reason)
  VALUES (v_d, v_a, HIL, T0 + interval '5 minutes', (ids->>'u_office')::uuid,
          'Suspended for db/99 section 58: Verify Seventynine Pupil missed the briefing.');
  INSERT INTO scoring_audit (match_id, school_id, event, actor_id, epoch, at)
  VALUES (v_m, HIL, 'claim', v_u, 1, T0 + interval '4 minutes');

  -- The leaver: no player row of his own here, and his player role ended.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (HIL, 'v79.leaver@example.invalid', 'Verify Seventynine Leaver', 'player') RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('u_leaver', v_u);
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from, active)
  VALUES (v_u, 'player', HIL, 'U15A', current_date - 300, false) RETURNING id INTO v_a;
  INSERT INTO role_assignment_ending (assignment_id, person_id, role, school_id, team_code, reason, ended_by, ended_at)
  VALUES (v_a, v_u, 'player', HIL, 'U15A',
          'Verify Seventynine Leaver left the school at the end of term.', (ids->>'u_office')::uuid, T0 + interval '3 minutes');

  -- The reads, as log_restricted_read() would have filed them.
  INSERT INTO access_log (school_id, person_id, resource, record_ids, record_count, fields, occurred_at) VALUES
    (HIL, (ids->>'u_pupil')::uuid, 'players', ARRAY[v_p], 1, '{born}', T0 + interval '1 minute'),
    (HIL, (ids->>'u_office')::uuid, 'users', ARRAY[(ids->>'u_pupil')::uuid], 1, '{email}', T0 + interval '2 minutes'),
    (HIL, (ids->>'u_dso')::uuid, 'safeguarding_concern', ARRAY[gen_random_uuid()], 1, '{account,reporter}', T0 + interval '6 minutes'),
    (WES, (ids->>'u_wes')::uuid, 'players', ARRAY[gen_random_uuid(), gen_random_uuid()], 2, '{born}', T0 + interval '7 minutes');

  -- Westville's own ended role.
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from, active)
  VALUES ((ids->>'u_wes')::uuid, 'coach', WES, '1XI', current_date - 300, false) RETURNING id INTO v_a;
  INSERT INTO role_assignment_ending (assignment_id, person_id, role, school_id, team_code, reason, ended_by, ended_at)
  VALUES (v_a, (ids->>'u_wes')::uuid, 'coach', WES, '1XI', 'Westville''s own ending, for section 58.', (ids->>'u_wes')::uuid,
          T0 + interval '8 minutes');
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- How many reads of the audit log are on the record for this person at this
-- school, as the owner counts them (access_log is not the caller's to count).
CREATE OR REPLACE FUNCTION _v79_reads(p_person uuid, p_school uuid) RETURNS integer AS $$
  SELECT count(*)::int FROM access_log
   WHERE resource = 'audit_log' AND person_id = p_person AND school_id IS NOT DISTINCT FROM p_school
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- ...and how many of those name this child among the records they disclosed.
CREATE OR REPLACE FUNCTION _v79_reads_naming(p_person uuid, p_child uuid) RETURNS integer AS $$
  SELECT count(*)::int FROM access_log
   WHERE resource = 'audit_log' AND person_id = p_person AND record_ids @> ARRAY[p_child]
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/79 (section 58) ──────────────────────────────────────────────

-- ┌── db/80 (section 59): the audit log shows roles granted (SCRBRD-132 B2) ─
-- Its own world, as the owner, at a school of its own (Verify 080), so every
-- grant there is one of these and nothing else in this file reaches it. Each
-- appointment is made as the session db/01's stamp reads (app.user_id), so
-- created_by is who made it: the office and the principal arrive as a seed
-- does (nobody), the DSO is appointed by the principal, the coach, the pupil
-- and the leaver by the office. The leaver's player role is then ended. A
-- support hour at the school (an assignment and its support_access row, as
-- support_access_begin() writes them) is the support kind's, not a grant.
-- And one Hilton office, to read Verify 080 from outside. Returns the ids.
CREATE OR REPLACE FUNCTION _seed_80() RETURNS jsonb AS $$
DECLARE
  HIL  uuid := '11111111-1111-1111-1111-111111111111';
  V80  uuid := '80800000-0000-0000-0000-000000000080';
  ids  jsonb := jsonb_build_object('school', '80800000-0000-0000-0000-000000000080');
  r    record;
  v_u  uuid; v_a uuid; v_p uuid;
BEGIN
  INSERT INTO school (id, code, name) VALUES (V80, 'verify-080', 'Verify 080');
  FOR r IN SELECT * FROM (VALUES
      ('office',    'schooladmin', V80,  NULL,   NULL),
      ('principal', 'principal',   V80,  NULL,   NULL),
      ('dso',       'dso',         V80,  NULL,   'principal'),
      ('coach',     'coach',       V80,  'U15A', 'office'),
      ('hil',       'schooladmin', HIL,  NULL,   NULL)) AS v(k, role, school, team, granter)
  LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (r.school, 'v80.' || r.k || '@example.invalid', 'V80 ' || initcap(r.k), r.role)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    PERFORM set_config('app.user_id', coalesce(ids->>('u_' || r.granter), ''), true);
    INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
    VALUES (v_u, r.role, r.school, r.team, current_date - 30) RETURNING id INTO v_a;
    ids := ids || jsonb_build_object('a_' || r.k, v_a);
  END LOOP;

  -- The pupil: a player row, an account that is that player, his player role
  -- granted by the office.
  INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
  VALUES (V80, 'U15A', 'Verify Eighty Pupil', 'Pupil', 780, 'batter',
          (current_date - interval '14 years' - interval '80 days')::date)
  RETURNING id INTO v_p;
  INSERT INTO app_user (school_id, email, name, role, player_id)
  VALUES (V80, 'v80.pupil@example.invalid', 'Verify Eighty Pupil', 'player', v_p) RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('p_pupil', v_p, 'u_pupil', v_u);
  PERFORM set_config('app.user_id', ids->>'u_office', true);
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
  VALUES (v_u, 'player', V80, 'U15A', current_date - 30) RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('a_pupil', v_a);

  -- The leaver: his player role granted by the office, and ended by it.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (V80, 'v80.leaver@example.invalid', 'Verify Eighty Leaver', 'player') RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('u_leaver', v_u);
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
  VALUES (v_u, 'player', V80, 'U15A', current_date - 300) RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('a_leaver', v_a);
  UPDATE role_assignment SET active = false WHERE id = v_a;
  INSERT INTO role_assignment_ending (assignment_id, person_id, role, school_id, team_code, reason, ended_by)
  VALUES (v_a, v_u, 'player', V80, 'U15A',
          'Verify Eighty Leaver left Verify 080 for section 59.', (ids->>'u_office')::uuid);

  -- A support hour: its assignment is made by the support person, as
  -- support_access_begin() makes it, and its row is the support kind's.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (HIL, 'v80.support@example.invalid', 'V80 Support', 'platformadmin') RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('u_support', v_u);
  PERFORM set_config('app.user_id', v_u::text, true);
  INSERT INTO role_assignment (person_id, role, school_id, active, valid_from, expires_at)
  VALUES (v_u, 'schooladmin', V80, true, current_date, now() + interval '1 hour') RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('a_support', v_a);
  INSERT INTO support_access (actor_id, school_id, role, reason, assignment_id, expires_at)
  VALUES (v_u, V80, 'schooladmin', 'Section 59 support hour at Verify 080.', v_a, now() + interval '1 hour')
  RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('s_support', v_a);

  PERFORM set_config('app.user_id', '', true);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/80 (section 59) ──────────────────────────────────────────────
-- ┌── db/81 (section 60): sign-up with Google, an account with no school (SCRBRD-140) ──
-- Its own world, as the owner: Hilton's and Westville's offices, the
-- platform, an owner's key, a parent with one verified link, three pupils
-- (a minor whose family has not consented, a minor whose family has, and one
-- of eighteen whose has not), an inactive account and a departed teacher
-- whose only role has ended. Every child invented; every date explicit.
CREATE OR REPLACE FUNCTION _seed_81() RETURNS jsonb AS $$
DECLARE
  HIL  uuid := '11111111-1111-1111-1111-111111111111';
  WES  uuid := '22222222-2222-2222-2222-222222222222';
  ids  jsonb := '{}'::jsonb;
  r    record;
  v_u  uuid;
  v_a  uuid;
  v_p  uuid;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('office', 'schooladmin',   HIL),
      ('wes',    'schooladmin',   WES),
      ('plat',   'platformadmin', NULL::uuid),
      ('own',    'superadmin',    NULL::uuid),
      ('ownhil', 'superadmin',    NULL::uuid),
      ('parent', 'guardian',      HIL),
      ('ended',  'coach',         HIL),
      ('head',   'principal',     HIL),
      ('dso',    'dso',           HIL),
      ('coach',  'coach',         HIL),
      ('dos',    'directorofsport', HIL)) AS v(k, role, school)
  LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (r.school, 'v81.' || r.k || '@example.invalid', 'V81 ' || initcap(r.k), r.role)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u);
    INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from)
    VALUES (v_u, r.role, r.school, CASE WHEN r.role = 'coach' THEN 'U15A' END, current_date - 30)
    RETURNING id INTO v_a;
    ids := ids || jsonb_build_object('a_' || r.k, v_a);
  END LOOP;
  -- A second owner's key, whose ACCOUNT is filed at Hilton: Hilton's office
  -- may issue it a code (login_code_issue() asks only user.invite there), but
  -- may not confirm a Google sign-in onto it.
  UPDATE app_user SET school_id = HIL WHERE id = (ids->>'u_ownhil')::uuid;
  -- The departed teacher: his one role ended, nothing live.
  UPDATE role_assignment SET active = false WHERE id = (ids->>'a_ended')::uuid;

  -- The parent's child, a minor, verified by the office.
  INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
  VALUES (HIL, NULL, 'Kid Eightyone', 'Eightyone', 810, 'batter', (current_date - interval '13 years')::date)
  RETURNING id INTO v_p;
  ids := ids || jsonb_build_object('p_kid', v_p);
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, created_by, valid_from)
  VALUES ((ids->>'a_parent')::uuid, v_p, 'parent', 'verified', (ids->>'u_office')::uuid, now(),
          'pending', (ids->>'u_office')::uuid, current_date - 30);

  -- Three pupils, each enrolled with his own record: his roster link and a
  -- verified `self` link, consent as named.
  FOR r IN SELECT * FROM (VALUES
      ('minor',  14, 'pending'),
      ('pupil',  15, 'granted'),
      ('adult',  19, 'pending')) AS v(k, age, consent)
  LOOP
    INSERT INTO player (school_id, team_code, full_name, surname, squad_no, playing_role, born)
    VALUES (HIL, NULL, 'Pupil ' || initcap(r.k) || 'eightyone', initcap(r.k) || 'eightyone', 811, 'bowler',
            (current_date - make_interval(years => r.age) - interval '20 days')::date)
    RETURNING id INTO v_p;
    INSERT INTO app_user (school_id, email, name, role, player_id)
    VALUES (HIL, 'v81.' || r.k || '@example.invalid', 'V81 ' || initcap(r.k), 'player', v_p)
    RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || r.k, v_u, 'p_' || r.k, v_p);
    INSERT INTO role_assignment (person_id, role, school_id, valid_from)
    VALUES (v_u, 'selfaccess', HIL, current_date - 30) RETURNING id INTO v_a;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (v_a, v_p, 'self', 'verified', (ids->>'u_office')::uuid, now(),
            r.consent, CASE WHEN r.consent = 'granted' THEN 'popia-2026-01' END,
            CASE WHEN r.consent = 'granted' THEN now() END, (ids->>'u_office')::uuid, current_date - 30);
  END LOOP;

  -- Deactivated by the office, holding nothing.
  INSERT INTO app_user (school_id, email, name, role, active)
  VALUES (HIL, 'v81.gone@example.invalid', 'V81 Gone', 'coach', false) RETURNING id INTO v_u;
  ids := ids || jsonb_build_object('u_gone', v_u);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The rows as the owner reads them, past RLS: the claims are about the record.
CREATE OR REPLACE FUNCTION _v81_identity(p_uid text) RETURNS auth_identity AS $$
  SELECT * FROM auth_identity WHERE provider = 'google.com' AND provider_uid = p_uid
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v81_open_claims(p_uid text) RETURNS integer AS $$
  SELECT count(*)::int FROM pending_claim WHERE provider = 'google.com' AND provider_uid = p_uid AND resolved_at IS NULL
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v81_claim(p_uid text) RETURNS pending_claim AS $$
  SELECT * FROM pending_claim WHERE provider = 'google.com' AND provider_uid = p_uid ORDER BY requested_at DESC LIMIT 1
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v81_user(p uuid) RETURNS app_user AS $$
  SELECT * FROM app_user WHERE id = p
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v81_deactivate(p uuid) RETURNS void AS $$
  UPDATE app_user SET active = false WHERE id = p
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v81_log(p_resource text, p_user uuid) RETURNS integer AS $$
  SELECT count(*)::int FROM access_log WHERE resource = p_resource AND p_user = ANY (record_ids)
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/81 (section 60) ──────────────────────────────────────────────
-- ┌── db/82 (section 61): listing on the home page, the live read (SCRBRD-142) ──
-- Seven fixtures written as the owner, six of them today at noon in South
-- Africa, each a row of the design's §1.4 table or one beside it. Nothing is
-- published or listed here: the section does that as the schools' own
-- publishers. f1 is live, at a ground, with two innings in its log (Hilton
-- batting first) so the score carries its side. Returns the ids.
CREATE OR REPLACE FUNCTION _seed_82() RETURNS jsonb AS $$
DECLARE
  HIL    uuid := '11111111-1111-1111-1111-111111111111';
  WES    uuid := '22222222-2222-2222-2222-222222222222';
  SCORER uuid := '88888888-0000-0000-0000-000000000006';
  GROUND uuid := 'ffffffff-0000-0000-0000-000000000001';   -- Gordon Sherwood Oval
  noon   timestamptz := (sa_today()::timestamp + interval '12 hours') AT TIME ZONE 'Africa/Johannesburg';
  ids    jsonb := '{}';
  m      uuid;
BEGIN
  -- f1 · Hilton at home to a typed side; Hilton publishes and lists (row 1)
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, '1XI', 'Verify Eightytwo College 1XI', noon, 'cricket', 'T20', 20, 'live', GROUND) RETURNING id INTO m;
  ids := ids || jsonb_build_object('f1', m);
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq,
                          client_ts, kind, ball_type, value, payload)
  VALUES
    (m, HIL, 1, 1, 0, SCORER, 'v82', 'v82-' || m || '-1', 1, now(), 'innings_start', NULL, NULL,
     '{"battingTeam": "1XI", "bowlingTeam": "Verify Eightytwo College 1XI", "overs": 20}'),
    (m, HIL, 2, 1, 0, SCORER, 'v82', 'v82-' || m || '-2', 2, now(), 'ball', 'run', 4, '{"bowler": "Typed Eightytwo"}'),
    (m, HIL, 3, 1, 1, SCORER, 'v82', 'v82-' || m || '-3', 3, now(), 'innings_start', NULL, NULL,
     '{"battingTeam": "Verify Eightytwo College 1XI", "bowlingTeam": "1XI", "overs": 20, "target": 5}'),
    (m, HIL, 4, 1, 1, SCORER, 'v82', 'v82-' || m || '-4', 4, now(), 'ball', 'run', 1, '{"striker": "Typed Batter"}');
  -- f2 · Hilton v Westville; both publish; Hilton lists, Westville does not (row 2)
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, ground_id)
  VALUES (HIL, '2XI', WES, '2XI', 'Westville Boys'' High 2XI', noon + interval '1 hour', 'cricket', 'T20', 20, 'scheduled', GROUND)
  RETURNING id INTO m;
  ids := ids || jsonb_build_object('f2', m);
  -- f3 · Westville at home to Hilton; only Hilton (away) publishes; Hilton lists (row 3)
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (WES, 'U15A', HIL, 'U15A', 'Hilton College U15A', noon - interval '2 hours', 'cricket', 'T20', 20, 'complete')
  RETURNING id INTO m;
  ids := ids || jsonb_build_object('f3', m);
  -- f4 · Westville at home to a typed side; Westville publishes; nobody lists (row 4)
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (WES, '1XI', 'Verify Eightytwo Academy 1XI', noon, 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m;
  ids := ids || jsonb_build_object('f4', m);
  -- f5 · Hilton at home, Hilton lists, nobody publishes (row 5)
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U14A', 'Verify Eightytwo School U14A', noon, 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m;
  ids := ids || jsonb_build_object('f5', m);
  -- f6 · Westville at home to Hilton; only Westville publishes; Hilton (away) lists
  --      but has published nothing of its own
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (WES, 'U16A', HIL, 'U16A', 'Hilton College U16A', noon, 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m;
  ids := ids || jsonb_build_object('f6', m);
  -- f7 · Hilton yesterday; published and listed: nothing from yesterday (D13)
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U13A', 'Verify Eightytwo Prep U13A', noon - interval '1 day', 'cricket', 'T20', 20, 'complete') RETURNING id INTO m;
  ids := ids || jsonb_build_object('f7', m);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/82 (section 61) ──────────────────────────────────────────────

-- ┌── db/83 (section 62) ──────────────────────────────────────────────
-- A known-as for one Hilton pupil (T Bekker), as the owner writes it, so the
-- scan has a nickname to find. Rolled back with everything else.
CREATE OR REPLACE FUNCTION _seed_83() RETURNS void AS $$
  UPDATE player SET known_as = 'Bekks' WHERE id = 'aaaaaaaa-0000-0000-0000-000000000002';
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/83 (section 62) ──────────────────────────────────────────────

-- ┌── db/84 (section 63) ──────────────────────────────────────────────
-- Two fixtures, as the owner: Hilton at home to Westville (both sides are
-- schools on SCRBRD), and Hilton at home to a typed side. Returns the ids.
CREATE OR REPLACE FUNCTION _seed_84() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  ids jsonb := '{}';
  m   uuid;
BEGIN
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', WES, '1XI', 'Westville Boys'' High 1XI', now() + interval '5 days', 'cricket', 'T20', 20, 'scheduled')
  RETURNING id INTO m;
  ids := ids || jsonb_build_object('both', m);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', 'Verify Eightyfour College 1XI', now() + interval '6 days', 'cricket', 'T20', 20, 'scheduled')
  RETURNING id INTO m;
  ids := ids || jsonb_build_object('typed', m);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A squad row written as the OWNER: no route, no row-level policy, only the
-- triggers. Answers 'ok', or the SQLSTATE and the sentence the database said.
CREATE OR REPLACE FUNCTION _v84_pick(p_match uuid, p_player uuid, p_side text, p_withdrawn boolean DEFAULT false) RETURNS text AS $$
BEGIN
  INSERT INTO match_squad (match_id, player_id, side, withdrawn) VALUES (p_match, p_player, p_side, p_withdrawn)
  ON CONFLICT (match_id, player_id) DO UPDATE SET side = EXCLUDED.side, withdrawn = EXCLUDED.withdrawn;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE || ': ' || SQLERRM;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The BEFORE row triggers on match_squad, in the order Postgres fires them.
CREATE OR REPLACE FUNCTION _v84_squad_trigger_order() RETURNS text[] AS $$
  SELECT array_agg(t.tgname::text ORDER BY t.tgname COLLATE "C") FROM pg_trigger t
   WHERE t.tgrelid = 'match_squad'::regclass AND NOT t.tgisinternal AND t.tgenabled <> 'D'
     AND (t.tgtype & 1) = 1 AND (t.tgtype & 2) = 2
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A post's byline, changed as the owner (db/12's ON DELETE SET NULL is this).
CREATE OR REPLACE FUNCTION _v84_set_author(p_post uuid, p_author uuid) RETURNS text AS $$
BEGIN
  UPDATE news_post SET author_id = p_author WHERE id = p_post;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE || ': ' || SQLERRM;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A request as the owner reads it, past RLS. jsonb, so a database without
-- the column answers NULL for it rather than failing to compile.
CREATE OR REPLACE FUNCTION _v84_request(p_id uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(r) FROM role_request r WHERE r.id = p_id
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v84_user_by_email(p_email text) RETURNS uuid AS $$
  SELECT id FROM app_user WHERE lower(email) = lower(p_email)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/84 (section 63) ──────────────────────────────────────────────

-- ┌── db/85 (section 64) ──────────────────────────────────────────────
-- Become somebody the way the API does (app_session_begin), as the caller —
-- not a definer — answering 'ok:<app_user_id()>' or the SQLSTATE and the
-- sentence. A refusal rolls back its own subtransaction, identity included.
CREATE OR REPLACE FUNCTION _v85_begin(p_user uuid, p_device text, p_session uuid, p_epoch integer, p_pad uuid DEFAULT NULL) RETURNS text AS $$
BEGIN
  PERFORM app_session_begin(p_user, p_device, p_session, p_epoch, p_pad);
  RETURN 'ok:' || coalesce(app_user_id()::text, '') || ':' || coalesce(app_device_id(), '');
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE || ': ' || SQLERRM;
END $$ LANGUAGE plpgsql;
-- What the owner sees of an account's sessions, past the no-privilege tables.
CREATE OR REPLACE FUNCTION _v85_state(p_user uuid) RETURNS jsonb AS $$
  SELECT jsonb_build_object(
    'epoch',  coalesce((SELECT e.epoch FROM auth_epoch e WHERE e.user_id = p_user), 0),
    'reason', (SELECT e.reason FROM auth_epoch e WHERE e.user_id = p_user),
    'by',     (SELECT e.bumped_by FROM auth_epoch e WHERE e.user_id = p_user),
    'active', (SELECT u.active FROM app_user u WHERE u.id = p_user),
    'live',   (SELECT count(*) FROM auth_session s WHERE s.user_id = p_user AND s.revoked_at IS NULL))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The plain-UPDATE door, as the owner: no route, no function, only the trigger.
CREATE OR REPLACE FUNCTION _v85_set_active(p_user uuid, p_active boolean) RETURNS void AS $$
  UPDATE app_user SET active = p_active WHERE id = p_user
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A Google sign-in on an account, as the owner.
CREATE OR REPLACE FUNCTION _v85_identity(p_user uuid) RETURNS uuid AS $$
  INSERT INTO auth_identity (user_id, provider, provider_uid, email_at_link, linked_how)
  VALUES (p_user, 'google.com', 'v85-' || gen_random_uuid(), 'v85.walk@example.invalid', 'self_added')
  RETURNING id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A live pad credential for (person, device) on a fixture of its own.
CREATE OR REPLACE FUNCTION _v85_pad(p_user uuid, p_device text) RETURNS uuid AS $$
DECLARE m uuid; c uuid;
BEGIN
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES ('11111111-1111-1111-1111-111111111111', '1XI', 'Verify Eightyfive College 1XI', now() + interval '5 days', 'cricket', 'T20', 20, 'scheduled')
  RETURNING id INTO m;
  INSERT INTO pad_resume_credential (id_hash, user_id, device_id, match_id, school_id, public_jwk, jkt, expires_at)
  VALUES (encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex'), p_user, p_device, m, match_school(m),
          '{"kty":"EC","crv":"P-256","x":"MKBCTNIcKUSDii11ySs3526iDZ8AiTo7Tu6KPAqv7D4","y":"4Etl6SRW2YiLUrN5vfvVHuhp7x8PxltmWWlbbM4IFyM"}',
          repeat('A', 43), now() + interval '1 hour')
  RETURNING id INTO c;
  RETURN c;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v85_pad_reason(p_id uuid) RETURNS text AS $$
  SELECT coalesce(revoked_reason, 'live') FROM pad_resume_credential WHERE id = p_id
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Whether the application role may touch a table or a function, as an answer.
CREATE OR REPLACE FUNCTION _v85_try(p_sql text) RETURNS text AS $$
BEGIN
  EXECUTE p_sql;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE;
END $$ LANGUAGE plpgsql;
-- └── db/85 (section 64) ──────────────────────────────────────────────

-- ┌── db/86 (section 65): a platform role belongs to no school ────────
-- An account with no school and no role, for an appointment to name.
CREATE OR REPLACE FUNCTION _v86_person(p_key text) RETURNS uuid AS $$
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (NULL, 'v86.' || p_key || '@example.invalid', 'V86 ' || initcap(p_key), 'none') RETURNING id
$$ LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An appointment written as whoever calls it: through role_assignment_write,
-- as the application writes one. 'ok', or the SQLSTATE and the constraint
-- (or the message, when no constraint was named).
CREATE OR REPLACE FUNCTION _v86_insert(p_person uuid, p_role text, p_school uuid) RETURNS text AS $$
DECLARE v_con text;
BEGIN
  INSERT INTO role_assignment (person_id, role, school_id) VALUES (p_person, p_role, p_school);
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN SQLSTATE || ':' || coalesce(nullif(v_con, ''), SQLERRM);
END $$ LANGUAGE plpgsql;
-- The same, as the table's owner, past every policy: the seed's door,
-- tools/bootstrap.mjs's, and the SQL Editor's. Live or already ended.
CREATE OR REPLACE FUNCTION _v86_appoint(p_person uuid, p_role text, p_school uuid, p_active boolean DEFAULT true) RETURNS text AS $$
DECLARE v_con text;
BEGIN
  INSERT INTO role_assignment (person_id, role, school_id, active) VALUES (p_person, p_role, p_school, p_active);
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN SQLSTATE || ':' || coalesce(nullif(v_con, ''), SQLERRM);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- What an address left behind: accounts / requests / appointments.
CREATE OR REPLACE FUNCTION _v86_left(p_email text) RETURNS text AS $$
  SELECT (SELECT count(*) FROM app_user u WHERE lower(u.email) = lower(p_email)) || '/'
      || (SELECT count(*) FROM role_request r JOIN app_user u ON u.id = r.person_id WHERE lower(u.email) = lower(p_email)) || '/'
      || (SELECT count(*) FROM role_assignment a JOIN app_user u ON u.id = a.person_id WHERE lower(u.email) = lower(p_email))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A request's state, and how many appointments a person holds at a school.
