-- ┌── db/96 (section 76). The plan to the side: a team post tagged to a fixture
-- Two Hilton sides (U15A, U15B) and Westville's U15A, invented here: the seed
-- has no U15 side at either school, and the design's other school (Kearsney)
-- is not in the seed, so Westville stands in for it. On U15A: a captain and a
-- team-mate named on the sheet, a boy on the roster and not on it, their
-- guardian (verified and consented, as the seed's are: a boy is selected only
-- once registered), the coach, the team manager and the assistant coach. On
-- U15B: a boy and his guardian. At Westville: the U15A coach and a boy. Three
-- fixtures: U15A at home to Westville U15A (the plan's), U15A against a
-- school SCRBRD does not host, and U15B's. As the owner; every name is
-- invented.
CREATE OR REPLACE FUNCTION _v96_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  ids jsonb; v_cap uuid; v_mate uuid; v_res uuid; v_b uuid; v_w uuid; f1 uuid; f2 uuid; f3 uuid; r record;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify NinetySix Captain', 961, 'batter', U15) RETURNING id INTO v_cap;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify NinetySix Mate', 962, 'bowler', U15) RETURNING id INTO v_mate;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify NinetySix Reserve', 963, 'bowler', U15) RETURNING id INTO v_res;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15B', 'Verify NinetySix Bside', 964, 'batter', U15) RETURNING id INTO v_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, 'U15A', 'Verify NinetySix Westville', 965, 'batter', U15) RETURNING id INTO v_w;
  ids := _v71_people('v96', ARRAY[
    ARRAY['coach',      'coach',          HIL::text, 'U15A', ''],
    ARRAY['manager',    'teammanager',    HIL::text, 'U15A', ''],
    ARRAY['assistant',  'assistantcoach', HIL::text, 'U15A', ''],
    ARRAY['captain',    'player',         HIL::text, 'U15A', v_cap::text],
    ARRAY['mate',       'player',         HIL::text, 'U15A', v_mate::text],
    ARRAY['reserve',    'player',         HIL::text, 'U15A', v_res::text],
    ARRAY['guardian',   'guardian',       HIL::text, '',     ''],
    ARRAY['bboy',       'player',         HIL::text, 'U15B', v_b::text],
    ARRAY['bparent',    'guardian',       HIL::text, '',     ''],
    ARRAY['wescoach',   'coach',          WES::text, 'U15A', ''],
    ARRAY['wesboy',     'player',         WES::text, 'U15A', v_w::text],
    ARRAY['follower',   'spectator',      HIL::text, '',     ''],
    ARRAY['finance',    'finance',        HIL::text, '',     ''],
    ARRAY['director',   'directorofsport', HIL::text, '',    '']]);
  -- The guardian is the captain's and the team-mate's; the other is the
  -- U15B boy's. Verified by the office and consented. A follower (spectator)
-- and the school's finance office hold news.read school-wide and read no
-- side; the director of sport reads every side.
  FOR r IN SELECT a.id AS aid, x.p FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'guardian')::uuid, v_cap), ((ids->>'guardian')::uuid, v_mate),
                                  ((ids->>'bparent')::uuid, v_b)) AS x(person, p)
            WHERE a.person_id = x.person LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, 'parent', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', WES, 'U15A', 'Westville U15A', ((sa_today() + 2)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Verify NinetySix Visitors', ((sa_today() + 9)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f2;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15B', 'Verify NinetySix B Visitors', ((sa_today() + 2)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f3;
  -- The sheet: the captain and the team-mate; the reserve is on the roster only.
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES (f1, v_cap, 'home', 1), (f1, v_mate, 'home', 2);
  RETURN ids || jsonb_build_object('p_cap', v_cap, 'p_mate', v_mate, 'p_res', v_res, 'p_b', v_b, 'p_w', v_w,
                                   'f1', f1, 'f2', f2, 'f3', f3);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Every notification anywhere that names a pupil as its recipient and is not
-- the system's own, as the owner counts them: SG-9 says none.
CREATE OR REPLACE FUNCTION _v96_pupil_recipients() RETURNS integer AS $$
  SELECT count(*)::int FROM notification n
   WHERE n.recipient_id IS NOT NULL AND n.kind IS DISTINCT FROM 'system' AND person_is_pupil(n.recipient_id)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Every notification about one plan (its notice, and the "withdrawn" notices
-- about it), as the owner reads them: the recipients and children they name.
CREATE OR REPLACE FUNCTION _v96_named(p_post uuid) RETURNS text AS $$
  SELECT count(*)::text || ' rows, ' || count(n.recipient_id)::text || ' to somebody, '
         || count(n.subject_person_id)::text || ' about somebody'
    FROM notification n
   WHERE (n.subject_kind = 'news' AND n.subject_id = p_post)
      OR n.retracts_id IN (SELECT x.id FROM notification x WHERE x.subject_kind = 'news' AND x.subject_id = p_post)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/96 (section 76) ──────────────────────────────────────────────
-- ┌── db/97 (section 75). The ball log follows the fixture: the away side reads its match
-- docs/design/SCRBRD-136-137_away_visibility.md §9. Everything below is
-- invented for the proof: a third school standing in for the design's
-- Kearsney (neither side), one side at each of Hilton and Westville (16XI),
-- a U15 quick on each (the design's "K Naidoo" at Hilton and "D Erasmus" at
-- Westville), a pupil with self-access and a guardian at each, and the
-- readers the policy is about. Three fixtures today: Hilton at home to
-- Westville, Westville at home to Hilton, and Hilton against a school not on
-- the platform. Written as the owner.

-- Overs of the log for one innings: six legal balls each, bowled by p_overs[i]
-- (NULL: a bowler SCRBRD holds no row for) to p_striker, each with a measured
-- point so the striker's wheel has something to draw.
CREATE OR REPLACE FUNCTION _v97_bowl(p_match uuid, p_scorer uuid, p_innings int, p_striker uuid, p_overs uuid[])
RETURNS void AS $$
DECLARE i int; j int; s int;
BEGIN
  s := coalesce((SELECT max(seq) FROM ball_event WHERE match_id = p_match), 0);
  FOR i IN 1..coalesce(array_length(p_overs, 1), 0) LOOP
    FOR j IN 1..6 LOOP
      s := s + 1;
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value, bowler_id, striker_id,
                              theta, radius, placement_source, capture_profile)
      SELECT p_match, m.school_id, s, 0, p_innings, p_scorer, 'v97-pad', 'v97-' || p_match || '-' || s, s, now(),
             'ball', 'run', 1, p_overs[i], p_striker, (s * 37) % 360, 0.5, 'point', 'full'
        FROM match m WHERE m.id = p_match;
    END LOOP;
  END LOOP;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the rule says a reader may read of a fixture's log, asked as the
-- owner with app_can() directly (the policy's two branches, spelled out
-- apart from it), beside the whole log: so the section can hold the policy
-- to the rule, and the host branch alone to what the old policy answered.
CREATE OR REPLACE FUNCTION _v97_rule(p_match uuid, OUT host int, OUT away int, OUT either int, OUT total int) AS $$
  SELECT count(*) FILTER (WHERE h)::int, count(*) FILTER (WHERE a)::int, count(*) FILTER (WHERE h OR a)::int, count(*)::int
    FROM (SELECT app_can('fixture.read', b.school_id, match_team(b.match_id), NULL, b.match_id) AS h,
                 coalesce(app_can('fixture.read', m.away_school_id, m.away_team_code, NULL, b.match_id), false) AS a
            FROM ball_event b JOIN match m ON m.id = b.match_id
           WHERE b.match_id = p_match) x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The API's bowling_spells and player_shot_points, as the caller (invoker,
-- not a definer): services/api/read/read-api.mjs's texts, column for column
-- where the section reads them, so the per-boy gates are proved as they run.
CREATE OR REPLACE FUNCTION _v97_spells(p_match uuid)
RETURNS TABLE (bowler_id uuid, overs int, age_band text, pace boolean, max_overs_per_spell smallint,
               max_overs_per_day smallint, over_spell_limit boolean, breach_recorded boolean) AS $$
  SELECT s.bowler_id, s.overs::int, d.age_band, d.pace, d.max_overs_per_spell, d.max_overs_per_day,
         (CASE WHEN w.may THEN d.max_overs_per_spell IS NOT NULL AND s.overs > d.max_overs_per_spell END),
         EXISTS (SELECT 1 FROM bowling_breach x
                  WHERE x.match_id = s.match_id AND x.innings = s.innings
                    AND x.bowler_id = s.bowler_id AND x.kind = 'spell' AND x.key = s.first_over)
    FROM bowler_spell s
    JOIN player p ON p.id = s.bowler_id
    CROSS JOIN LATERAL (SELECT app_can('player.workload.read', p.school_id, p.team_code, p.id,
                                       '00000000-0000-0000-0000-000000000000'::uuid) AS may) w
    LEFT JOIN LATERAL bowling_directive_for(s.bowler_id) d ON w.may
   WHERE s.match_id = p_match
$$ LANGUAGE sql STABLE;
CREATE OR REPLACE FUNCTION _v97_wheel(p_player uuid) RETURNS int AS $$
  SELECT count(*)::int
    FROM ball_event_career b
    JOIN match m ON m.id = b.match_id
   WHERE b.striker_id = p_player
     AND EXISTS (SELECT 1 FROM player p WHERE p.id = p_player)
     AND b.kind = 'ball'
     AND (b.theta IS NOT NULL OR b.seg IS NOT NULL)
$$ LANGUAGE sql STABLE;

-- The pad's tables for one fixture, as the owner counts them.
CREATE OR REPLACE FUNCTION _v97_pad_rows(p_match uuid) RETURNS text AS $$
  SELECT concat_ws('/', (SELECT count(*) FROM scoring_session WHERE match_id = p_match),
                        (SELECT count(*) FROM ball_event_quarantine WHERE match_id = p_match),
                        (SELECT count(*) FROM scoring_audit WHERE match_id = p_match))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _v97_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';   -- verifies the links, as the seed's do
  U15 date := make_date(extract(year FROM sa_today())::int - 16, 10, 1);
  KRS uuid; ids jsonb; v_a uuid;
  h_quick uuid; w_quick uuid; h_bat uuid; w_bat uuid; fh uuid; fw uuid; fn uuid;
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V97K', 'Verify NinetySeven College', 'school', 'KwaZulu-Natal')
  RETURNING id INTO KRS;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born, bowling_style) VALUES
    (HIL, '16XI', 'Verify NinetySeven Home Quick', 971, 'bowler', U15, 'F') RETURNING id INTO h_quick;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born, bowling_style) VALUES
    (WES, '16XI', 'Verify NinetySeven Away Quick', 972, 'bowler', U15, 'F') RETURNING id INTO w_quick;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify NinetySeven Home Bat', 973, 'batter', U15) RETURNING id INTO h_bat;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '16XI', 'Verify NinetySeven Away Bat', 974, 'batter', U15) RETURNING id INTO w_bat;
  ids := _v71_people('v97', ARRAY[
    ARRAY['hilcoach',    'coach',      HIL::text, '16XI', ''],
    ARRAY['hil2coach',   'coach',      HIL::text, '15XI', ''],
    ARRAY['hilscorer',   'scorer',     HIL::text, '',     ''],
    ARRAY['hilspec',     'spectator',  HIL::text, '',     ''],
    ARRAY['hilpupil',    'player',     HIL::text, '16XI', h_bat::text],
    ARRAY['hilguardian', 'guardian',   HIL::text, '',     ''],
    ARRAY['wescoach',    'coach',      WES::text, '16XI', ''],
    ARRAY['wesscorer',   'scorer',     WES::text, '',     ''],
    ARRAY['wesspec',     'spectator',  WES::text, '',     ''],
    ARRAY['wespupil',    'player',     WES::text, '16XI', w_bat::text],
    ARRAY['wesguardian', 'guardian',   WES::text, '',     ''],
    ARRAY['kcoach',      'coach',      KRS::text, '16XI', ''],
    ARRAY['kspec',       'spectator',  KRS::text, '',     '']]);
  -- Each pupil also holds self-access over his own record, as R Pillay does.
  INSERT INTO role_assignment (person_id, role, school_id)
  VALUES ((ids->>'hilpupil')::uuid, 'selfaccess', HIL), ((ids->>'wespupil')::uuid, 'selfaccess', WES);
  -- The guardians' links to the pupils and the pupils' to themselves:
  -- verified by the office and consented, as the seed's are.
  FOR v_a IN SELECT a.id FROM role_assignment a
              WHERE a.person_id IN ((ids->>'hilpupil')::uuid, (ids->>'wespupil')::uuid,
                                    (ids->>'hilguardian')::uuid, (ids->>'wesguardian')::uuid)
                AND a.role IN ('guardian', 'selfaccess') LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    SELECT v_a, CASE WHEN a.school_id = HIL THEN h_bat ELSE w_bat END,
           CASE WHEN a.role = 'guardian' THEN 'parent' ELSE 'self' END, 'verified', OFFICE, now(),
           'granted', 'popia-2026-01', now(), OFFICE, current_date - 1
      FROM role_assignment a WHERE a.id = v_a;
  END LOOP;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '16XI', WES, '16XI', 'Verify NinetySeven Westville', (sa_today()::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'live') RETURNING id INTO fh;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (WES, '16XI', HIL, '16XI', 'Verify NinetySeven Hilton', (sa_today()::timestamp + time '14:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'live') RETURNING id INTO fw;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '16XI', 'Verify NinetySeven Elsewhere', (sa_today()::timestamp + time '06:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'live') RETURNING id INTO fn;
  -- At Hilton: Westville's quick bowls three to Hilton's bat (one spell, alternate
  -- overs from one end), then Hilton's quick two to Westville's bat.
  PERFORM _v97_bowl(fh, (ids->>'hilscorer')::uuid, 0, h_bat, ARRAY[w_quick, NULL, w_quick, NULL, w_quick]::uuid[]);
  PERFORM _v97_bowl(fh, (ids->>'hilscorer')::uuid, 1, w_bat, ARRAY[h_quick, NULL, h_quick]::uuid[]);
  -- At Westville, the afternoon: Hilton's quick two to Westville's bat, then
  -- Westville's quick four to Hilton's bat. His day: seven, two matches.
  PERFORM _v97_bowl(fw, (ids->>'wesscorer')::uuid, 0, w_bat, ARRAY[h_quick, NULL, h_quick]::uuid[]);
  PERFORM _v97_bowl(fw, (ids->>'wesscorer')::uuid, 1, h_bat, ARRAY[w_quick, NULL, w_quick, NULL, w_quick, NULL, w_quick]::uuid[]);
  -- Against a school not on the platform: one over of Hilton's quick.
  PERFORM _v97_bowl(fn, (ids->>'hilscorer')::uuid, 0, NULL, ARRAY[h_quick]::uuid[]);
  -- The pad's tables at Hilton's fixture: Westville's scorer holding the
  -- token (so a refused write below is refused for the school, not for want
  -- of a token), a held ball and the audit row of the claim.
  INSERT INTO scoring_session (match_id, school_id, state, epoch, holder_user_id, holder_device, lease_until)
  VALUES (fh, HIL, 'active', 0, (ids->>'wesscorer')::uuid, 'v97-away-pad', now() + interval '1 hour');
  INSERT INTO ball_event_quarantine (match_id, school_id, submitted_epoch, current_epoch, scorer_user_id, device_id, idempotency_key, body, fingerprint)
  VALUES (fh, HIL, 0, 0, (ids->>'hilscorer')::uuid, 'v97-pad', 'v97-held-' || fh, '{}'::jsonb, 'v97-fingerprint');
  INSERT INTO scoring_audit (match_id, school_id, event, actor_id, epoch)
  VALUES (fh, HIL, 'claim', (ids->>'hilscorer')::uuid, 0);
  RETURN ids || jsonb_build_object('krs', KRS, 'h_quick', h_quick, 'w_quick', w_quick, 'h_bat', h_bat, 'w_bat', w_bat,
                                   'fh', fh, 'fw', fw, 'fn', fn);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/97 (section 75) ──────────────────────────────────────────────

-- ┌── db/100 (section 77). A parent reads the ball log of his child's side's matches
-- Kameel's decision of 2026-10-14. Everything below is invented for the
-- proof: two sides at Hilton (13XI, and 14XI whose boy plays up into 13XI once),
-- one at Westville (13XI, the same code at another school), a third school,
-- four boys and the guardians the policy is about. Six fixtures today, each
-- with its own number of balls so a count says which ones a reader read.
-- Written as the owner.

-- A guardian link as the office makes it: verified, consented, started
-- yesterday; p_state and p_until say otherwise for the ended and the pending.
CREATE OR REPLACE FUNCTION _v100_link(p_person uuid, p_school uuid, p_player uuid,
                                      p_state text DEFAULT 'verified', p_until date DEFAULT NULL)
RETURNS void AS $$
DECLARE v_a uuid;
BEGIN
  SELECT a.id INTO v_a FROM role_assignment a
   WHERE a.person_id = p_person AND a.role = 'guardian' AND a.school_id = p_school AND a.active;
  IF v_a IS NULL THEN
    INSERT INTO role_assignment (person_id, role, school_id) VALUES (p_person, 'guardian', p_school)
    RETURNING id INTO v_a;
  END IF;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, valid_until)
  VALUES (v_a, p_player, 'parent', p_state, '88888888-0000-0000-0000-00000000000c',
          CASE WHEN p_state = 'verified' THEN now() END, 'granted', 'popia-2026-01', now(),
          '88888888-0000-0000-0000-00000000000c', current_date - 30,
          coalesce(p_until, (SELECT majority_on(p.born) FROM player p WHERE p.id = p_player)));
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A fixture's whole log, as the owner counts it: "every ball" is this many.
CREATE OR REPLACE FUNCTION _v100_owner_balls(p_match uuid) RETURNS int AS $$
  SELECT count(*)::int FROM ball_event WHERE match_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _v100_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  U15 date := make_date(extract(year FROM sa_today())::int - 16, 10, 1);
  KRS uuid; ids jsonb; v_s uuid;
  c_a uuid; c_b uuid; c_w uuid; c_e uuid; c_q uuid;
  f1 uuid; f2 uuid; f3 uuid; f4 uuid; f5 uuid; f6 uuid;
  T timestamptz := (sa_today()::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg';
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V100K', 'Verify Hundred College', 'school', 'KwaZulu-Natal')
  RETURNING id INTO KRS;
  -- A: Hilton's 13XI. B: Hilton's 14XI, who plays up into 13XI at f1. W:
  -- Westville's 13XI (the same team code at another school). E: Hilton's 13XI,
  -- whose guardian's link has ended. Q: Hilton's 13XI quick, no family here.
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born, bowling_style) VALUES
    (HIL, '13XI', 'Verify Hundred Home Bat', 1001, 'allrounder', U15, 'F') RETURNING id INTO c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '14XI', 'Verify Hundred Younger Bat', 1002, 'batter', U15) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '13XI', 'Verify Hundred Away Bat', 1003, 'batter', U15) RETURNING id INTO c_w;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '13XI', 'Verify Hundred Ended Bat', 1004, 'batter', U15) RETURNING id INTO c_e;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born, bowling_style) VALUES
    (HIL, '13XI', 'Verify Hundred Home Quick', 1005, 'bowler', U15, 'F') RETURNING id INTO c_q;
  ids := _v71_people('v100', ARRAY[
    ARRAY['g1',       'guardian',  HIL::text, '',    ''],    -- A's
    ARRAY['g2',       'guardian',  HIL::text, '',    ''],    -- B's at Hilton and W's at Westville
    ARRAY['g3',       'guardian',  HIL::text, '',    ''],    -- E's, ended yesterday
    ARRAY['g4',       'guardian',  HIL::text, '',    ''],    -- A's too, never verified
    ARRAY['g5',       'guardian',  HIL::text, '',    ''],    -- B's alone
    ARRAY['gq',       'guardian',  HIL::text, '',    ''],    -- Q's, never signed in as
    ARRAY['coacha',   'coach',     HIL::text, '13XI', ''],
    ARRAY['coachb',   'coach',     HIL::text, '14XI', ''],
    ARRAY['scorer',   'scorer',    HIL::text, '',    ''],
    ARRAY['spec',     'spectator', HIL::text, '',    ''],
    ARRAY['pupilb',   'player',    HIL::text, '14XI', c_b::text],
    ARRAY['wescoach', 'coach',     WES::text, '13XI', ''],
    ARRAY['wesscorer','scorer',    WES::text, '',    ''],
    ARRAY['kcoach',   'coach',     KRS::text, '13XI', '']]);
  -- _v71_people wrote each guardian an assignment naming nobody; the links
  -- hang off it, as guardian_link_establish() reuses one per school.
  PERFORM _v100_link((ids->>'g1')::uuid, HIL, c_a);
  PERFORM _v100_link((ids->>'g2')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'g2')::uuid, WES, c_w);
  PERFORM _v100_link((ids->>'g5')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'g3')::uuid, HIL, c_e, 'verified', current_date);
  PERFORM _v100_link((ids->>'g4')::uuid, HIL, c_a, 'pending');
  -- Q is registered to play (the sheet refuses a boy who is not).
  PERFORM _v100_link((ids->>'gq')::uuid, HIL, c_q);
  -- B signs in as a pupil of 14XI, with self-access over his own record as
  -- R Pillay has: the link names him, and holds no fixture.read.
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'pupilb')::uuid, 'selfaccess', HIL)
  RETURNING id INTO v_s;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_s, c_b, 'self', 'verified', '88888888-0000-0000-0000-00000000000c', now(), 'granted', 'popia-2026-01', now(),
          '88888888-0000-0000-0000-00000000000c', current_date - 1);
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '13XI', WES, '13XI', 'Verify Hundred Westville', T, 'cricket', 'T20', 20, 'live') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (WES, '13XI', HIL, '13XI', 'Verify Hundred Hilton', T + interval '5 hours', 'cricket', 'T20', 20, 'live') RETURNING id INTO f2;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '14XI', 'Verify Hundred Younger XI', T, 'cricket', 'T20', 20, 'live') RETURNING id INTO f3;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '13XI', 'Verify Hundred Elsewhere', T - interval '2 hours', 'cricket', 'T20', 20, 'live') RETURNING id INTO f4;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (KRS, '13XI', 'Verify Hundred Neither', T, 'cricket', 'T20', 20, 'live') RETURNING id INTO f5;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (WES, '14XI', 'Verify Hundred Westville Seconds', T, 'cricket', 'T20', 20, 'live') RETURNING id INTO f6;
  -- The sheets. B plays up for 13XI at f1 (Hilton's home side); he was
  -- picked for f4 and withdrawn. W is on Westville's side at f1.
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    (f1, c_a, 'home', 1), (f1, c_b, 'home', 2), (f1, c_q, 'home', 11), (f1, c_w, 'away', 1);
  INSERT INTO match_squad (match_id, player_id, side, batting_no, withdrawn) VALUES (f4, c_b, 'home', 3, true);
  -- The balls. f1: A one over and B one over in Hilton's innings, then Q
  -- one to W in Westville's (18). f2: W two overs, then A two
  -- with Q bowling one of them (24). f3: B one over (6). f4: A five overs,
  -- then A bowls one (36). f5: two overs at the third school (12). f6: three
  -- at Westville's seconds (18).
  PERFORM _v97_bowl(f1, (ids->>'scorer')::uuid, 0, c_a, ARRAY[NULL]::uuid[]);
  PERFORM _v97_bowl(f1, (ids->>'scorer')::uuid, 0, c_b, ARRAY[NULL]::uuid[]);
  PERFORM _v97_bowl(f1, (ids->>'scorer')::uuid, 1, c_w, ARRAY[c_q]::uuid[]);
  PERFORM _v97_bowl(f2, (ids->>'wesscorer')::uuid, 0, c_w, ARRAY[NULL, NULL]::uuid[]);
  PERFORM _v97_bowl(f2, (ids->>'wesscorer')::uuid, 1, c_a, ARRAY[c_q, NULL]::uuid[]);
  PERFORM _v97_bowl(f3, (ids->>'scorer')::uuid, 0, c_b, ARRAY[NULL]::uuid[]);
  PERFORM _v97_bowl(f4, (ids->>'scorer')::uuid, 0, c_a, ARRAY[NULL, NULL, NULL, NULL, NULL]::uuid[]);
  PERFORM _v97_bowl(f4, (ids->>'scorer')::uuid, 1, NULL, ARRAY[c_a]::uuid[]);
  PERFORM _v97_bowl(f5, (ids->>'scorer')::uuid, 0, NULL, ARRAY[NULL, NULL]::uuid[]);
  PERFORM _v97_bowl(f6, (ids->>'wesscorer')::uuid, 0, NULL, ARRAY[NULL, NULL, NULL]::uuid[]);
  -- The pad's tables at f1: a session, a held ball and an audit row.
  INSERT INTO scoring_session (match_id, school_id, state, epoch, holder_user_id, holder_device, lease_until)
  VALUES (f1, HIL, 'active', 0, (ids->>'scorer')::uuid, 'v100-pad', now() + interval '1 hour');
  INSERT INTO ball_event_quarantine (match_id, school_id, submitted_epoch, current_epoch, scorer_user_id, device_id, idempotency_key, body, fingerprint)
  VALUES (f1, HIL, 0, 0, (ids->>'scorer')::uuid, 'v100-pad', 'v100-held-' || f1, '{}'::jsonb, 'v100-fingerprint');
  INSERT INTO scoring_audit (match_id, school_id, event, actor_id, epoch)
  VALUES (f1, HIL, 'claim', (ids->>'scorer')::uuid, 0);
  RETURN ids || jsonb_build_object('krs', KRS, 'a', c_a, 'b', c_b, 'w', c_w, 'e', c_e, 'q', c_q,
                                   'f1', f1, 'f2', f2, 'f3', f3, 'f4', f4, 'f5', f5, 'f6', f6);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Ending a link as the office would, mid-section: the next read is refused.
CREATE OR REPLACE FUNCTION _v100_end_link(p_person uuid, p_player uuid) RETURNS void AS $$
  UPDATE assignment_subject g SET valid_until = current_date
    FROM role_assignment a
   WHERE a.id = g.assignment_id AND a.person_id = p_person AND g.player_id = p_player
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/100 (section 77) ──────────────────────────────────────────────
-- ┌── db/101 (section 78). News to the side: a team post, and the team sheet
-- Hilton's U15A, U15B and U14A and Westville's U15A and U14A, invented here,
-- with a boy on each and his guardian (verified and consented, as the seed's
-- are: a boy is selected only once registered). Hilton U15A at home to
-- Westville U15A (f1), and against a school SCRBRD does not host (f2). f1's
-- sheet: at the home end a U15A boy and a U14A boy playing up; at the away
-- end a Westville U15A boy and a Westville U14A boy playing up. The other
-- U14A boy is on no sheet. The U15A coach, team manager and assistant coach,
-- the U14A coach, the director of sport, and five school-wide roles that hold
-- news.read and read no side (a follower, finance, sponsorship, a driver,
-- facilities). Westville's U15A coach. As the owner; every name is invented.
CREATE OR REPLACE FUNCTION _v101_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE  uuid := '88888888-0000-0000-0000-00000000000c';   -- Hilton's office verifies Hilton's links
  WOFFICE uuid := '88888888-0000-0000-0000-00000000000d';   -- Westville's, Westville's
  U15 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  U14 date := make_date(extract(year FROM sa_today())::int - 13, 3, 1);
  ids jsonb; v_a uuid; v_up uuid; v_14 uuid; v_b uuid; v_w uuid; v_wup uuid; f1 uuid; f2 uuid; r record;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify OneOhOne Opener', 1011, 'batter', U15) RETURNING id INTO v_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U14A', 'Verify OneOhOne Climber', 1012, 'bowler', U14) RETURNING id INTO v_up;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U14A', 'Verify OneOhOne Stayer', 1013, 'bowler', U14) RETURNING id INTO v_14;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15B', 'Verify OneOhOne Bside', 1014, 'batter', U15) RETURNING id INTO v_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, 'U15A', 'Verify OneOhOne Visitor', 1015, 'batter', U15) RETURNING id INTO v_w;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, 'U14A', 'Verify OneOhOne Visiting Climber', 1016, 'bowler', U14) RETURNING id INTO v_wup;
  ids := _v71_people('v101', ARRAY[
    ARRAY['coach',       'coach',           HIL::text, 'U15A', ''],
    ARRAY['manager',     'teammanager',     HIL::text, 'U15A', ''],
    ARRAY['assistant',   'assistantcoach',  HIL::text, 'U15A', ''],
    ARRAY['u14coach',    'coach',           HIL::text, 'U14A', ''],
    ARRAY['director',    'directorofsport', HIL::text, '',     ''],
    ARRAY['aboy',        'player',          HIL::text, 'U15A', v_a::text],
    ARRAY['upboy',       'player',          HIL::text, 'U14A', v_up::text],
    ARRAY['u14boy',      'player',          HIL::text, 'U14A', v_14::text],
    ARRAY['bboy',        'player',          HIL::text, 'U15B', v_b::text],
    ARRAY['aparent',     'guardian',        HIL::text, '',     ''],
    ARRAY['upparent',    'guardian',        HIL::text, '',     ''],
    ARRAY['u14parent',   'guardian',        HIL::text, '',     ''],
    ARRAY['bparent',     'guardian',        HIL::text, '',     ''],
    ARRAY['follower',    'spectator',       HIL::text, '',     ''],
    ARRAY['finance',     'finance',         HIL::text, '',     ''],
    ARRAY['sponsorship', 'sponsorship',     HIL::text, '',     ''],
    ARRAY['driver',      'driver',          HIL::text, '',     ''],
    ARRAY['facilities',  'facilities',      HIL::text, '',     ''],
    ARRAY['wescoach',    'coach',           WES::text, 'U15A', ''],
    ARRAY['wesboy',      'player',          WES::text, 'U15A', v_w::text],
    ARRAY['wesup',       'player',          WES::text, 'U14A', v_wup::text],
    ARRAY['wesparent',   'guardian',        WES::text, '',     ''],
    ARRAY['wesupparent', 'guardian',        WES::text, '',     '']]);
  -- Each guardian is one boy's, verified by his school's office and consented.
  FOR r IN SELECT a.id AS aid, x.p, x.verifier FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'aparent')::uuid, v_a, OFFICE), ((ids->>'upparent')::uuid, v_up, OFFICE),
                                  ((ids->>'u14parent')::uuid, v_14, OFFICE), ((ids->>'bparent')::uuid, v_b, OFFICE),
                                  ((ids->>'wesparent')::uuid, v_w, WOFFICE),
                                  ((ids->>'wesupparent')::uuid, v_wup, WOFFICE)) AS x(person, p, verifier)
            WHERE a.person_id = x.person LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, 'parent', 'verified', r.verifier, now(), 'granted', 'popia-2026-01', now(), r.verifier, current_date - 1);
  END LOOP;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', WES, 'U15A', 'Westville U15A', ((sa_today() + 3)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Verify OneOhOne Visitors', ((sa_today() + 10)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f2;
  -- f1's sheet, both ends: a boy of the side and a boy playing up at each.
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    (f1, v_a, 'home', 1), (f1, v_up, 'home', 2), (f1, v_w, 'away', 1), (f1, v_wup, 'away', 2);
  RETURN ids || jsonb_build_object('p_a', v_a, 'p_up', v_up, 'p_14', v_14, 'p_b', v_b, 'p_w', v_w, 'p_wup', v_wup,
                                   'f1', f1, 'f2', f2);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Take a boy off a sheet by deleting his row, as the owner: no person may
-- delete a squad row (db/09 has no DELETE policy; the API withdraws).
CREATE OR REPLACE FUNCTION _v101_unsheet(p_match uuid, p_player uuid) RETURNS integer AS $$
  WITH d AS (DELETE FROM match_squad WHERE match_id = p_match AND player_id = p_player RETURNING 1)
  SELECT count(*)::int FROM d
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/101 (section 78) ─────────────────────────────────────────────

-- ┌── db/102 (section 79). Who a module was hidden from is the school's to read
-- Invented people, one per reader the policy is about, and four suppressions:
-- Skills hidden from one Hilton coach (N1) and Training from another (N2),
-- each with a reason; Leagues hidden from the whole of Hilton (S1); Skills
-- hidden from a Westville coach (W1). The pupil and the parent are enrolled
-- (the parent's link is verified, as the seed's are), so a row they do not
-- read is the policy refusing them, not an account that reads nothing.
CREATE OR REPLACE FUNCTION _v102_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  ids jsonb; v_boy uuid; v_a uuid; n1 uuid; n2 uuid; s1 uuid; w1 uuid;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneOhTwo Boy', 1021, 'batter', make_date(extract(year FROM sa_today())::int - 15, 3, 1))
  RETURNING id INTO v_boy;
  ids := _v71_people('v102', ARRAY[
    ARRAY['manager',    'schooladmin', HIL::text, '',    ''],
    ARRAY['named',      'coach',       HIL::text, '1XI', ''],
    ARRAY['colleague',  'coach',       HIL::text, '3XI', ''],
    ARRAY['teacher',    'coach',       HIL::text, '2XI', ''],
    ARRAY['parent',     'guardian',    HIL::text, '',    ''],
    ARRAY['pupil',      'player',      HIL::text, '1XI', v_boy::text],
    ARRAY['spectator',  'spectator',   HIL::text, '',    ''],
    ARRAY['wesmanager', 'schooladmin', WES::text, '',    ''],
    ARRAY['wesnamed',   'coach',       WES::text, '1XI', '']]);
  SELECT a.id INTO v_a FROM role_assignment a WHERE a.person_id = (ids->>'parent')::uuid;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, v_boy, 'parent', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  INSERT INTO feature_suppression (key, school_id, person_id, reason, hidden_by)
  VALUES ('skills', HIL, (ids->>'named')::uuid, 'v102: pending a review of his conduct', (ids->>'manager')::uuid)
  RETURNING id INTO n1;
  INSERT INTO feature_suppression (key, school_id, person_id, reason, hidden_by)
  VALUES ('training', HIL, (ids->>'colleague')::uuid, 'v102: on leave', (ids->>'manager')::uuid)
  RETURNING id INTO n2;
  INSERT INTO feature_suppression (key, school_id, person_id, reason, hidden_by)
  VALUES ('leagues', HIL, NULL, 'v102: not running leagues this term', (ids->>'manager')::uuid)
  RETURNING id INTO s1;
  INSERT INTO feature_suppression (key, school_id, person_id, reason, hidden_by)
  VALUES ('skills', WES, (ids->>'wesnamed')::uuid, 'v102: Westville''s own note', (ids->>'wesmanager')::uuid)
  RETURNING id INTO w1;
  RETURN ids || jsonb_build_object('boy', v_boy, 'n1', n1, 'n2', n2, 's1', s1, 'w1', w1);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/102 (section 79) ─────────────────────────────────────────────
-- ┌── db/109 (section 86). Account lifecycle slice 3: a child's links, and the reason for an ending
-- Written as the owner, the way the system's own definers write, each the
-- one thing an assertion needs.
--
-- The stage: three Hilton boys (Boy, 15, U15A; Two, 14, U14A; Old, 19 and
-- still at school, 1XI), the office, the director of sport, a coach, three
-- guardians (Mum and Dad of Boy; Gran and Dad of Two; Aunt of Old) and
-- Westville's office. Mum's links carry everything a revocation takes with
-- it: a public-name "yes" and a health-monitoring "yes" given ten days ago
-- through her link, and a seat she asked for on Dad's lift tomorrow. Boy has
-- an emergency contact. The seed's DSO (N Dube) is the DSO, and an open
-- concern names Boy.
CREATE OR REPLACE FUNCTION _v109_link(p_person uuid, p_player uuid) RETURNS uuid AS $$
DECLARE a uuid; l uuid;
BEGIN
  SELECT r.id INTO a FROM role_assignment r WHERE r.person_id = p_person AND r.role = 'guardian' AND r.active LIMIT 1;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (a, p_player, 'parent', 'verified', '88888888-0000-0000-0000-00000000000c', now() - interval '20 days',
          'granted', 'popia-2026-01', now() - interval '20 days', '88888888-0000-0000-0000-00000000000c', current_date - 30)
  RETURNING id INTO l;
  RETURN l;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _v109_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  ids jsonb; v_boy uuid; v_two uuid; v_old uuid; l uuid; a uuid; v_m uuid; v_d uuid; v_o uuid; v_s uuid; v_c uuid; v_p uuid;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify OneOhNine Boy', 1091, 'batter', make_date(extract(year FROM sa_today())::int - 15, 3, 1))
  RETURNING id INTO v_boy;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U14A', 'Verify OneOhNine Two', 1092, 'bowler', make_date(extract(year FROM sa_today())::int - 14, 3, 1))
  RETURNING id INTO v_two;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneOhNine Old', 1093, 'batter', make_date(extract(year FROM sa_today())::int - 19, 3, 1))
  RETURNING id INTO v_old;
  ids := _v71_people('v109', ARRAY[
    ARRAY['office',    'schooladmin',     HIL::text, '',     ''],
    ARRAY['dos',       'directorofsport', HIL::text, '',     ''],
    ARRAY['coach',     'coach',           HIL::text, 'U15A', ''],
    ARRAY['mum',       'guardian',        HIL::text, '',     ''],
    ARRAY['dad',       'guardian',        HIL::text, '',     ''],
    ARRAY['gran',      'guardian',        HIL::text, '',     ''],
    ARRAY['aunt',      'guardian',        HIL::text, '',     ''],
    ARRAY['uncle',     'guardian',        HIL::text, '',     ''],
    ARRAY['wesoffice', 'schooladmin',     WES::text, '',     '']]);
  -- A platform administrator: one platform-wide assignment, no school.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (NULL, 'v109.platform@example.invalid', 'V109 Platform', 'platformadmin') RETURNING id INTO v_p;
  INSERT INTO role_assignment (person_id, role, school_id) VALUES (v_p, 'platformadmin', NULL);
  ids := ids || jsonb_build_object('platform', v_p);
  -- An owner's key: a platform-wide superadmin, guardian.link.manage everywhere.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (NULL, 'v109.owner@example.invalid', 'V109 Owner', 'superadmin') RETURNING id INTO v_p;
  INSERT INTO role_assignment (person_id, role, school_id) VALUES (v_p, 'superadmin', NULL);
  ids := ids || jsonb_build_object('owner', v_p);
  ids := ids || jsonb_build_object('boy', v_boy, 'two', v_two, 'old', v_old,
    'l_mum',  _v109_link((ids->>'mum')::uuid,  v_boy),
    'l_dad',  _v109_link((ids->>'dad')::uuid,  v_boy),
    'l_gran', _v109_link((ids->>'gran')::uuid, v_two),
    'l_dad2', _v109_link((ids->>'dad')::uuid,  v_two),
    'l_old',  _v109_link((ids->>'aunt')::uuid, v_old),
    'l_uncle', _v109_link((ids->>'uncle')::uuid, v_two));
  l := (ids->>'l_mum')::uuid;
  SELECT g.assignment_id INTO a FROM assignment_subject g WHERE g.id = l;
  -- What goes with her link (D14).
  INSERT INTO public_name_consent (player_id, given_by, giver_assignment_id, giver_link_id, version, given_on, recorded_by)
  VALUES (v_boy, 'guardian', a, l, 'popia-2026-01', current_date - 10, OFFICE);
  INSERT INTO health_monitoring_consent (player_id, given_by, giver_assignment_id, giver_link_id, version, given_on, recorded_by)
  VALUES (v_boy, 'guardian', a, l, 'v109', current_date - 10, OFFICE);
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES (v_boy, 1, 'V109 Mum', 'mother', '+27 82 109 0001') RETURNING id INTO v_c;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Verify OneOhNine XI', ((current_date + 3)::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled')
  RETURNING id INTO v_m;
  INSERT INTO lift_driver_declaration (person_id, school_id, vehicle_description, registration, seats, licence_held,
                                       insured, roadworthy, belts, code_acknowledged, policy_version, expires_on)
  VALUES ((ids->>'dad')::uuid, HIL, 'Silver hatchback', 'V109 GP', 3, true, true, true, true, true, 1, current_date + 300)
  RETURNING id INTO v_d;
  INSERT INTO lift_offer (school_id, match_id, team_code, leg, driver_id, declaration_id, seats, meet_kind, meet_at,
                          fixture_starts_at)
  VALUES (HIL, v_m, 'U15A', 'out', (ids->>'dad')::uuid, v_d, 3, 'school',
          ((current_date + 3)::timestamp + time '07:30') AT TIME ZONE 'Africa/Johannesburg', now())
  RETURNING id INTO v_o;
  INSERT INTO lift_seat (offer_id, school_id, match_id, team_code, leg, player_id, consent_by, guardian_assignment_id,
                         guardian_link_id, requested_by, state)
  VALUES (v_o, HIL, v_m, 'U15A', 'out', v_boy, 'guardian', a, l, (ids->>'mum')::uuid, 'requested')
  RETURNING id INTO v_s;
  INSERT INTO safeguarding_concern (reference, tenant_id, school_id, about_kind, subject_player_id,
                                    nature, certainty, account)
  VALUES ('SG-V109-0109', HIL, HIL, 'child', v_boy, '{neglect}', 'suspicion', 'A concern raised for db/99 section 86 only.')
  RETURNING id INTO v_c;
  RETURN ids || jsonb_build_object('seat', v_s, 'concern', v_c);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- guardian_link_revoke() as the CALLER, its refusal as text ('ok' when it
-- ended the link), or the SQLSTATE of whatever raised instead of answering.
-- Not a definer.
CREATE OR REPLACE FUNCTION _v109_revoke(p_link uuid, p_kind text, p_reason text) RETURNS text AS $$
DECLARE v text;
BEGIN
  SELECT coalesce(o.reason, 'ok') INTO v FROM guardian_link_revoke(p_link, p_kind, p_reason) o;
  RETURN v;
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE;
END $$ LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp;

-- The ending row of one link, whole, as the owner reads it.
CREATE OR REPLACE FUNCTION _v109_ending(p_link uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(e) FROM guardian_link_ending e WHERE e.link_id = p_link
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- One link, whole, as the owner reads it.
CREATE OR REPLACE FUNCTION _v109_link_row(p_link uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(g) FROM assignment_subject g WHERE g.id = p_link
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A notice, whole, past RLS.
CREATE OR REPLACE FUNCTION _v109_notice(p_id uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(n) FROM notification n WHERE n.id = p_id
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Health consent, the one gate every health read asks (db/60), past RLS.
CREATE OR REPLACE FUNCTION _v109_health(p_player uuid) RETURNS boolean AS $$
  SELECT health_consent_live(p_player)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The public-name facts (db/47, db/62), as the public read path asks them.
CREATE OR REPLACE FUNCTION _v109_facts(p_player uuid) RETURNS jsonb AS $$
  SELECT public_name_facts(p_player)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A boy leaves the school system today (his open membership closes), or
-- comes back (a new one opens), and db/62's deferred triggers are fired.
CREATE OR REPLACE FUNCTION _v109_leave(p_player uuid) RETURNS void AS $$
BEGIN
  -- The session's day, never before the side began (THE DAY, AT ANY HOUR).
  UPDATE team_membership SET left_on = greatest(current_date, joined_on) WHERE player_id = p_player AND left_on IS NULL;
  SET CONSTRAINTS team_membership_closes_guardian_links, team_membership_opens_guardian_links IMMEDIATE;
  SET CONSTRAINTS team_membership_closes_guardian_links, team_membership_opens_guardian_links DEFERRED;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v109_return(p_player uuid) RETURNS void AS $$
BEGIN
  INSERT INTO team_membership (player_id, school_id, sport, team_code, joined_on, reason)
  SELECT p.id, p.school_id, 'cricket', p.team_code,
         greatest(current_date, (SELECT max(m.left_on) FROM team_membership m WHERE m.player_id = p_player)), 'moved'
    FROM player p WHERE p.id = p_player;
  SET CONSTRAINTS team_membership_closes_guardian_links, team_membership_opens_guardian_links IMMEDIATE;
  SET CONSTRAINTS team_membership_closes_guardian_links, team_membership_opens_guardian_links DEFERRED;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The day a boy last left his side, as the owner reads it.
CREATE OR REPLACE FUNCTION _v109_left_on(p_player uuid) RETURNS date AS $$
  SELECT max(m.left_on) FROM team_membership m WHERE m.player_id = p_player
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- How many contacts a boy has, past RLS (D14: they stay).
CREATE OR REPLACE FUNCTION _v109_contacts(p_player uuid) RETURNS integer AS $$
  SELECT count(*)::int FROM emergency_contact WHERE player_id = p_player AND active
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The access log's child_links reads of one child, past RLS.
CREATE OR REPLACE FUNCTION _v109_logged(p_player uuid) RETURNS integer AS $$
  SELECT count(*)::int FROM access_log WHERE resource = 'child_links' AND p_player = ANY (record_ids)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Disable an account as the owner would (Q13), and its guardian role's id.
CREATE OR REPLACE FUNCTION _v109_disable(p_user uuid) RETURNS void AS $$
  UPDATE app_user SET active = false WHERE id = p_user
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v109_role(p_user uuid) RETURNS uuid AS $$
  SELECT id FROM role_assignment WHERE person_id = p_user AND role = 'guardian' AND active LIMIT 1
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A second role for a person (and its end), as the office's grant writes one.
CREATE OR REPLACE FUNCTION _v109_grant(p_user uuid, p_role text) RETURNS uuid AS $$
  INSERT INTO role_assignment (person_id, role, school_id)
  VALUES (p_user, p_role, '11111111-1111-1111-1111-111111111111') RETURNING id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v109_ungrant(p_id uuid) RETURNS void AS $$
  UPDATE role_assignment SET active = false WHERE id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/109 (section 86) ─────────────────────────────────────────────

-- ┌── db/103 (section 80). The plan's byline: who wrote the side's plan
-- Its own sides, so §76's plans and readers do not meet it: Hilton's 10XI
-- (the plan's side) and 11XI (another side), and Westville's 10XI. On 10XI:
-- a captain named on the sheet, a boy on the roster and not on it, the
-- captain's guardian (verified and consented), the coach and the team
-- manager. On 11XI: its coach, a boy and his guardian, and a second boy
-- who plays up, named on 10XI's sheet for the fixture, with his own
-- guardian (db/101's team sheet). At Westville: the 10XI coach and a boy. A follower (spectator) and the finance office, who
-- hold news.read school-wide and read no side; and an account with no
-- assignment at all. Two fixtures: 10XI at home to Westville's 10XI (the
-- plan's, and Westville's plan's from the away end), and 11XI's. As the
-- owner; every name is invented, and the staff read as "V103 Coach" and so on.
CREATE OR REPLACE FUNCTION _v103_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  ids jsonb; v_cap uuid; v_res uuid; v_b uuid; v_up uuid; v_w uuid; v_s uuid; f1 uuid; f2 uuid; r record;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '10XI', 'Verify OneOhThree Captain', 1031, 'batter', U15) RETURNING id INTO v_cap;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '10XI', 'Verify OneOhThree Reserve', 1032, 'bowler', U15) RETURNING id INTO v_res;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '11XI', 'Verify OneOhThree Bside', 1033, 'batter', U15) RETURNING id INTO v_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '11XI', 'Verify OneOhThree Playsup', 1035, 'bowler', U15) RETURNING id INTO v_up;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '10XI', 'Verify OneOhThree Westville', 1034, 'batter', U15) RETURNING id INTO v_w;
  ids := _v71_people('v103', ARRAY[
    ARRAY['coach',      'coach',          HIL::text, '10XI', ''],
    ARRAY['manager',    'teammanager',    HIL::text, '10XI', ''],
    ARRAY['captain',    'player',         HIL::text, '10XI', v_cap::text],
    ARRAY['reserve',    'player',         HIL::text, '10XI', v_res::text],
    ARRAY['guardian',   'guardian',       HIL::text, '',     ''],
    ARRAY['bcoach',     'coach',          HIL::text, '11XI', ''],
    ARRAY['bboy',       'player',         HIL::text, '11XI', v_b::text],
    ARRAY['bparent',    'guardian',       HIL::text, '',     ''],
    ARRAY['upboy',      'player',         HIL::text, '11XI', v_up::text],
    ARRAY['upparent',   'guardian',       HIL::text, '',     ''],
    ARRAY['wescoach',   'coach',          WES::text, '10XI', ''],
    ARRAY['wesboy',     'player',         WES::text, '10XI', v_w::text],
    ARRAY['follower',   'spectator',      HIL::text, '',     ''],
    ARRAY['finance',    'finance',        HIL::text, '',     '']]);
  -- Somebody signed in who holds nothing anywhere.
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (HIL, 'v103.stranger@example.invalid', 'V103 Stranger', 'spectator') RETURNING id INTO v_s;
  FOR r IN SELECT a.id AS aid, x.p FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'guardian')::uuid, v_cap), ((ids->>'bparent')::uuid, v_b),
                                  ((ids->>'upparent')::uuid, v_up)) AS x(person, p)
            WHERE a.person_id = x.person LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, 'parent', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '10XI', WES, '10XI', 'Westville 10XI', ((sa_today() + 2)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '11XI', 'Verify OneOhThree Visitors', ((sa_today() + 2)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f2;
  -- The sheet: the captain, and the 11XI boy playing up; the reserve is on the roster only.
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES (f1, v_cap, 'home', 1), (f1, v_up, 'home', 2);
  RETURN ids || jsonb_build_object('stranger', v_s, 'f1', f1, 'f2', f2, 'p_up', v_up);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Withdraw a boy from a fixture's sheet, as the API does (withdrawn = true,
-- the row kept), as the owner: the coach's own write is the API's, proved by
-- its walks, and this section is about what the byline does once he is off.
CREATE OR REPLACE FUNCTION _v103_off_sheet(p_match uuid, p_player uuid) RETURNS integer AS $$
  WITH d AS (UPDATE match_squad SET withdrawn = true WHERE match_id = p_match AND player_id = p_player AND NOT withdrawn RETURNING 1)
  SELECT count(*)::int FROM d
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/103 (section 80) ─────────────────────────────────────────────

-- ┌── db/104 (section 81). Corrections to a coach's judgement, and the coaching point
-- One invented Hilton side (20XI) with the boy the judgements are about
-- (Subject) and a team-mate (Mate, who holds the captaincy honour and his own
-- `player` account), a Westville boy on the same fixture's sheet, and one
-- person per reader AH-D3 names: two coaches of the side, the assistant, the
-- team manager, the director of sport, the principal, the analyst, the physio,
-- the scorer, the boy himself twice (his `player` account and his
-- `selfaccess`), his parent (verified and consented, as the seed's are),
-- Westville's coach of the side, a platform administrator (who begins a
-- support session below) and the owner's key (a platform-wide assignment).
-- Every name is invented.
CREATE OR REPLACE FUNCTION _v104_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  ids jsonb; v_s uuid; v_m uuid; v_w uuid; f1 uuid; r record; v_u uuid; k text;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '20XI', 'Verify OneOhFour Subject', 1041, 'batter', U15) RETURNING id INTO v_s;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '20XI', 'Verify OneOhFour Mate', 1042, 'bowler', U15) RETURNING id INTO v_m;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '20XI', 'Verify OneOhFour Visitor', 1043, 'batter', U15) RETURNING id INTO v_w;
  ids := _v71_people('v104', ARRAY[
    ARRAY['coach',     'coach',           HIL::text, '20XI', ''],
    ARRAY['coach2',    'coach',           HIL::text, '20XI', ''],
    ARRAY['assistant', 'assistantcoach',  HIL::text, '20XI', ''],
    ARRAY['manager',   'teammanager',     HIL::text, '20XI', ''],
    ARRAY['director',  'directorofsport', HIL::text, '',     ''],
    ARRAY['principal', 'principal',       HIL::text, '',     ''],
    ARRAY['analyst',   'analyst',         HIL::text, '',     ''],
    ARRAY['medical',   'medical',         HIL::text, '',     ''],
    ARRAY['scorer',    'scorer',          HIL::text, '',     ''],
    ARRAY['boy',       'player',          HIL::text, '20XI', v_s::text],
    ARRAY['self',      'selfaccess',      HIL::text, '',     v_s::text],
    ARRAY['captain',   'player',          HIL::text, '20XI', v_m::text],
    ARRAY['parent',    'guardian',        HIL::text, '',     ''],
    ARRAY['mateparent','guardian',        HIL::text, '',     ''],
    ARRAY['wesparent', 'guardian',        WES::text, '',     ''],
    ARRAY['wescoach',  'coach',           WES::text, '20XI', '']]);
  -- The boy's own file and each boy's parent's link: verified by his school's
  -- office and consented (a boy is on a sheet only once registered).
  FOR r IN SELECT a.id AS aid, a.role, x.p, x.verifier FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'self')::uuid, v_s, OFFICE), ((ids->>'parent')::uuid, v_s, OFFICE),
                                  ((ids->>'mateparent')::uuid, v_m, OFFICE),
                                  ((ids->>'wesparent')::uuid, v_w, '88888888-0000-0000-0000-00000000000d'::uuid))
                          AS x(person, p, verifier)
            WHERE a.person_id = x.person LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, CASE r.role WHEN 'selfaccess' THEN 'self' ELSE 'parent' END, 'verified', r.verifier, now(),
            'granted', 'popia-2026-01', now(), r.verifier, current_date - 1);
  END LOOP;
  -- The team-mate holds the captaincy: an honour, which adds no capability.
  INSERT INTO honour (player_id, school_id, team_code, kind, season_id)
  VALUES (v_m, HIL, '20XI', 'captain', (SELECT s.id FROM season_for(sa_today(), 'school') s LIMIT 1));
  -- Two platform people: no school, as the seed's are.
  FOREACH k IN ARRAY ARRAY['plat', 'owner'] LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (HIL, 'v104.' || k || '@example.invalid', 'V104 ' || initcap(k),
            CASE k WHEN 'plat' THEN 'platformadmin' ELSE 'superadmin' END)
    RETURNING id INTO v_u;
    INSERT INTO role_assignment (person_id, role, school_id, team_code)
    VALUES (v_u, CASE k WHEN 'plat' THEN 'platformadmin' ELSE 'superadmin' END, NULL, NULL);
    ids := ids || jsonb_build_object(k, v_u);
  END LOOP;
  -- A fixture with the boy, the team-mate and the visitor on its sheet.
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '20XI', WES, '20XI', 'Westville 20XI', ((sa_today() - 2)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'complete') RETURNING id INTO f1;
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    (f1, v_s, 'home', 1), (f1, v_m, 'home', 2), (f1, v_w, 'away', 1);
  RETURN ids || jsonb_build_object('subject', v_s, 'mate', v_m, 'visitor', v_w, 'f1', f1);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Run one statement as whoever is calling, under row security, and say how
-- it ended: 'ok', or its SQLSTATE. Not a definer: the point is the caller's
-- own policies.
CREATE OR REPLACE FUNCTION _v104_try(p_sql text) RETURNS text AS $$
BEGIN
  EXECUTE p_sql;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE;
END $$ LANGUAGE plpgsql;

-- A row as the owner reads it, past row security: the claim is about what is
-- STORED (who assessed, who withdrew), not about what a reader may see.
CREATE OR REPLACE FUNCTION _v104_skill(p_id uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(s) FROM player_skill s WHERE s.id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v104_note(p_id uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(n) FROM development_note n WHERE n.id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/104 (section 81) ─────────────────────────────────────────────

-- ┌── db/105 (section 82). The development loop: a target, the side's plan, the register
-- One invented Hilton side (U19E) and another (U19F). On U19E: the boy the
-- loop is about (Subject) and a team-mate (Mate, who holds the captaincy),
-- each with ONE account holding `player` for the side and `selfaccess` for
-- himself, as the seed's R Pillay does; the coach, the assistant, the team
-- manager. School-wide: the director of sport, the principal, the analyst.
-- The boy's parent (verified, consented). U19F's coach; Westville's coach of a
-- U19E; a platform administrator for the support session. The Subject joined
-- U19E sixty days ago, was rated twenty days ago (againstPace 7) and ten days
-- ago (againstPace 9, footwork 10); U19E held sessions twelve, eight, six,
-- four and two days ago, one three days ago that was cancelled and one in two
-- days. The register: he was present eight days ago, late six days ago,
-- absent four days ago; nobody took one two days ago; the Mate's row eight
-- days ago was written `injured` before db/105 (as the owner). A retired
-- Hilton drill, a Westville drill, and a note about the Mate. Every name is
-- invented.
CREATE OR REPLACE FUNCTION _v105_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  ids jsonb; v_s uuid; v_m uuid; r record; v_u uuid; k text; d int;
  sess jsonb := '{}'; v_t uuid; v_retired uuid; v_wesdrill uuid; v_matenote uuid; v_k20 uuid; v_k10 uuid;
BEGIN
  PERFORM set_config('app.effective_on', (current_date - 60)::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U19E', 'Verify OneOhFive Subject', 1051, 'batter', U15) RETURNING id INTO v_s;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U19E', 'Verify OneOhFive Mate', 1052, 'bowler', U15) RETURNING id INTO v_m;
  PERFORM set_config('app.effective_on', '', true);
  ids := _v71_people('v105', ARRAY[
    ARRAY['coach',      'coach',           HIL::text, 'U19E', ''],
    ARRAY['assistant',  'assistantcoach',  HIL::text, 'U19E', ''],
    ARRAY['manager',    'teammanager',     HIL::text, 'U19E', ''],
    ARRAY['director',   'directorofsport', HIL::text, '',     ''],
    ARRAY['principal',  'principal',       HIL::text, '',     ''],
    ARRAY['analyst',    'analyst',         HIL::text, '',     ''],
    ARRAY['self',       'player',          HIL::text, 'U19E', v_s::text],
    ARRAY['mate',       'player',          HIL::text, 'U19E', v_m::text],
    ARRAY['parent',     'guardian',        HIL::text, '',     ''],
    ARRAY['othercoach', 'coach',           HIL::text, 'U19F', ''],
    ARRAY['wescoach',   'coach',           WES::text, 'U19E', '']]);
  -- Each boy's second assignment, about himself; the parent's link.
  INSERT INTO role_assignment (person_id, role, school_id)
  VALUES ((ids->>'self')::uuid, 'selfaccess', HIL), ((ids->>'mate')::uuid, 'selfaccess', HIL);
  FOR r IN SELECT a.id AS aid, a.role, x.p FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'self')::uuid, v_s), ((ids->>'mate')::uuid, v_m),
                                  ((ids->>'parent')::uuid, v_s)) AS x(person, p)
            WHERE a.person_id = x.person AND a.role IN ('selfaccess', 'guardian') LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, CASE r.role WHEN 'selfaccess' THEN 'self' ELSE 'parent' END, 'verified', OFFICE, now(),
            'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO honour (player_id, school_id, team_code, kind, season_id)
  VALUES (v_m, HIL, 'U19E', 'captain', (SELECT s.id FROM season_for(sa_today(), 'school') s LIMIT 1));
  INSERT INTO app_user (school_id, email, name, role)
  VALUES (HIL, 'v105.plat@example.invalid', 'V105 Plat', 'platformadmin') RETURNING id INTO v_u;
  INSERT INTO role_assignment (person_id, role, school_id, team_code) VALUES (v_u, 'platformadmin', NULL, NULL);
  ids := ids || jsonb_build_object('plat', v_u);

  -- His scores: two looks at batting, the coach's.
  INSERT INTO player_skill (player_id, assessed_on, assessed_by, category, metric, score)
  VALUES (v_s, current_date - 20, (ids->>'coach')::uuid, 'technical', 'againstPace', 7) RETURNING id INTO v_k20;
  INSERT INTO player_skill (player_id, assessed_on, assessed_by, category, metric, score)
  VALUES (v_s, current_date - 10, (ids->>'coach')::uuid, 'technical', 'againstPace', 9) RETURNING id INTO v_k10;
  INSERT INTO player_skill (player_id, assessed_on, assessed_by, category, metric, score)
  VALUES (v_s, current_date - 10, (ids->>'coach')::uuid, 'technical', 'footwork', 10);

  -- The side's sessions, at four in the afternoon.
  FOREACH d IN ARRAY ARRAY[-12, -8, -6, -4, -3, -2, 2] LOOP
    INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type, cancelled)
    VALUES (HIL, 'U19E', 'Verify 105 nets ' || d, ((current_date + d)::timestamp + time '16:00') AT TIME ZONE 'Africa/Johannesburg',
            90, 'batting', d = -3)
    RETURNING id INTO v_t;
    sess := sess || jsonb_build_object('d' || abs(d) || CASE WHEN d > 0 THEN 'ahead' ELSE '' END, v_t);
  END LOOP;
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type)
  VALUES (HIL, 'U19F', 'Verify 105 other side', ((current_date - 5)::timestamp + time '16:00') AT TIME ZONE 'Africa/Johannesburg',
          60, 'fielding') RETURNING id INTO v_t;
  sess := sess || jsonb_build_object('other', v_t);
  INSERT INTO training_attendance (session_id, player_id, status) VALUES
    ((sess->>'d8')::uuid, v_s, 'present'), ((sess->>'d6')::uuid, v_s, 'late'), ((sess->>'d4')::uuid, v_s, 'absent'),
    ((sess->>'d8')::uuid, v_m, 'injured');

  INSERT INTO drill (school_id, name, category, duration_min, retired)
  VALUES (HIL, 'Verify 105 retired drill', 'batting', 20, true) RETURNING id INTO v_retired;
  INSERT INTO drill (school_id, name, category, duration_min)
  VALUES (WES, 'Verify 105 Westville drill', 'batting', 20) RETURNING id INTO v_wesdrill;
  INSERT INTO development_note (player_id, school_id, author_id, body)
  VALUES (v_m, HIL, (ids->>'coach')::uuid, 'Verify 105: a note about the team-mate.') RETURNING id INTO v_matenote;

  RETURN ids || sess || jsonb_build_object(
    'p_subject', v_s, 'p_mate', v_m, 'k20', v_k20, 'k10', v_k10,
    'throwdowns', (SELECT id FROM drill WHERE school_id IS NULL AND name = 'Throw-downs'),
    'shortpitch', (SELECT id FROM drill WHERE school_id IS NULL AND name = 'Short-pitch defence'),
    'retired', v_retired, 'wesdrill', v_wesdrill, 'matenote', v_matenote);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- When the boy joined his current side, moved as the owner: "a move" without
-- moving him, to show the window starts at it.
CREATE OR REPLACE FUNCTION _v105_joined(p_player uuid, p_on date) RETURNS void AS $$
  UPDATE team_membership SET joined_on = p_on WHERE player_id = p_player AND left_on IS NULL;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A target as the owner reads it, past row security.
CREATE OR REPLACE FUNCTION _v105_target(p_id uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(t) FROM development_target t WHERE t.id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/105 (section 82) ─────────────────────────────────────────────

-- ┌── db/106 (section 83). REACH R-A: a family reads its side's fixtures
-- Invented, as the owner; every name is a placeholder. Hilton's 6XI, 7XI and
-- 8XI and Westville's 6XI and 8XI, a third school's 6XI. Boys: A (Hilton
-- 6XI), UP (Hilton 7XI, on f1's sheet playing up for the 6XI, withdrawn from
-- f5's), B (Hilton 8XI), W (Westville 6XI), E (Hilton 6XI), N (Hilton 9XI).
-- Fixtures: f1 Hilton 6XI v Westville 6XI at Hilton; f2 the return at
-- Westville; f3 Hilton 7XI; f4 and f5 Hilton 6XI's next two, against schools
-- not on the platform (A on f4's sheet; UP picked for f5 and withdrawn); f6
-- Hilton 8XI; f7 the third school's 6XI; f8 Westville 8XI. Trips: t1 and t1b
-- (two Hilton buses to f1; t1 driven by GDRIVER, t1b's notes name a boy),
-- t2 (Westville's bus to f2), t3, t4, t6 (Hilton's, t6's notes name B), t8
-- (Westville's to f8). Training: s6, s7, s8 at Hilton, sw at Westville. The
-- toss, an umpire and the weather at f1, f2 and f6; fixture_publication rows
-- for f1's two ends and f6's.
CREATE OR REPLACE FUNCTION _v106_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  KRS uuid; ids jsonb; v_s uuid; v_stranger uuid;
  c_a uuid; c_up uuid; c_b uuid; c_w uuid; c_e uuid; c_n uuid; c_m uuid;
  f1 uuid; f2 uuid; f3 uuid; f4 uuid; f5 uuid; f6 uuid; f7 uuid; f8 uuid;
  t1 uuid; t1b uuid; t2 uuid; t3 uuid; t4 uuid; t6 uuid; t8 uuid;
  s6 uuid; s7 uuid; s8 uuid; sw uuid;
  D timestamp := (sa_today() + 2)::timestamp + time '09:30';
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V106K', 'Verify OneOhSix College', 'school', 'KwaZulu-Natal')
  RETURNING id INTO KRS;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '6XI', 'Verify OneOhSix Opener', 1061, 'batter', U15) RETURNING id INTO c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '7XI', 'Verify OneOhSix Climber', 1062, 'bowler', U15) RETURNING id INTO c_up;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '8XI', 'Verify OneOhSix Eighth', 1063, 'batter', U15) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '6XI', 'Verify OneOhSix Visitor', 1064, 'batter', U15) RETURNING id INTO c_w;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '6XI', 'Verify OneOhSix Ended', 1065, 'batter', U15) RETURNING id INTO c_e;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '9XI', 'Verify OneOhSix Teamless', 1066, 'batter', U15) RETURNING id INTO c_n;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '7XI', 'Verify OneOhSix Mate', 1067, 'batter', U15) RETURNING id INTO c_m;
  ids := _v71_people('v106', ARRAY[
    ARRAY['g1',       'guardian',    HIL::text, '',    ''],    -- A's, one child
    ARRAY['g2',       'guardian',    HIL::text, '',    ''],    -- B's at Hilton and W's at Westville
    ARRAY['gup',      'guardian',    HIL::text, '',    ''],    -- UP's, who plays up
    ARRAY['g3',       'guardian',    HIL::text, '',    ''],    -- E's, the link ended today
    ARRAY['g4',       'guardian',    HIL::text, '',    ''],    -- A's too, never verified
    ARRAY['g5',       'guardian',    HIL::text, '',    ''],    -- A's too, revoked
    ARRAY['wesg',     'guardian',    WES::text, '',    ''],    -- W's alone, the away family
    ARRAY['gdriver',  'guardian',    HIL::text, '',    ''],    -- B's, and a Hilton driver
    ARRAY['aboy',     'player',      HIL::text, '6XI', c_a::text],
    ARRAY['upboy',    'player',      HIL::text, '7XI', c_up::text],
    ARRAY['upmate',   'player',      HIL::text, '7XI', c_m::text],     -- UP's team-mate, on no sheet
    ARRAY['coach6',   'coach',       HIL::text, '6XI', ''],
    ARRAY['coach7',   'coach',       HIL::text, '7XI', ''],
    ARRAY['spec',     'spectator',   HIL::text, '',    ''],    -- school-wide follower
    ARRAY['spec6',    'spectator',   HIL::text, '6XI', ''],    -- scoped by the office to the 6XI
    ARRAY['office',   'schooladmin', HIL::text, '',    ''],
    ARRAY['wescoach', 'coach',       WES::text, '6XI', '']]);
  -- R-D's case, a pupil whose `player` row has no team, is no longer staged
  -- here: since db/108 (§85) no live such row can be written (the CHECK
  -- role_assignment_player_team_scoped), so §85 holds that case, not §83.
  -- (Wave 3 integration: db/106 and db/108 were built side by side.)
  PERFORM _v100_link((ids->>'g1')::uuid, HIL, c_a);
  PERFORM _v100_link((ids->>'g2')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'g2')::uuid, WES, c_w);
  PERFORM _v100_link((ids->>'gup')::uuid, HIL, c_up);
  PERFORM _v100_link((ids->>'g3')::uuid, HIL, c_e, 'verified', current_date);
  PERFORM _v100_link((ids->>'g4')::uuid, HIL, c_a, 'pending');
  PERFORM _v100_link((ids->>'g5')::uuid, HIL, c_a, 'revoked');
  PERFORM _v100_link((ids->>'wesg')::uuid, WES, c_w);
  PERFORM _v100_link((ids->>'gdriver')::uuid, HIL, c_b);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'gdriver')::uuid, 'driver', HIL);
  -- The two pupils each hold self-access naming themselves, as R Pillay does.
  FOR v_s, v_stranger IN SELECT x.person, x.boy FROM (VALUES ((ids->>'aboy')::uuid, c_a), ((ids->>'upboy')::uuid, c_up)) x(person, boy) LOOP
    INSERT INTO role_assignment (person_id, role, school_id) VALUES (v_s, 'selfaccess', HIL) RETURNING id INTO v_s;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (v_s, v_stranger, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v106.stranger@example.invalid', 'V106 Stranger', 'spectator')
  RETURNING id INTO v_stranger;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '6XI', WES, '6XI', 'Verify OneOhSix Westville', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (WES, '6XI', HIL, '6XI', 'Verify OneOhSix Hilton', (D + interval '7 days') AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f2;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '7XI', 'Verify OneOhSix Sevens', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f3;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '6XI', 'Verify OneOhSix Next', (D + interval '14 days') AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f4;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '6XI', 'Verify OneOhSix After', (D + interval '21 days') AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f5;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, '8XI', 'Verify OneOhSix Eights', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f6;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (KRS, '6XI', 'Verify OneOhSix Neither', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f7;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (WES, '8XI', 'Verify OneOhSix Westville Eights', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f8;
  -- The sheets. UP plays up for the 6XI at f1 and was withdrawn from f5.
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    (f1, c_a, 'home', 1), (f1, c_up, 'home', 2), (f1, c_w, 'away', 1), (f4, c_a, 'home', 1);
  INSERT INTO match_squad (match_id, player_id, side, batting_no, withdrawn) VALUES (f5, c_up, 'home', 3, true);
  -- The buses: each written by the school whose bus it is (the host's).
  INSERT INTO trip (match_id, school_id, driver_id, pickup, notes) VALUES
    (f1, HIL, (ids->>'gdriver')::uuid, 'V106 main gate', 'V106 first bus') RETURNING id INTO t1;
  INSERT INTO trip (match_id, school_id, pickup, notes) VALUES
    (f1, HIL, 'V106 chapel', 'V106 collect the Opener at the chapel') RETURNING id INTO t1b;
  INSERT INTO trip (match_id, school_id, pickup, notes) VALUES (f2, WES, 'V106 Westville gate', 'V106 Westville bus') RETURNING id INTO t2;
  INSERT INTO trip (match_id, school_id, pickup) VALUES (f3, HIL, 'V106 sevens') RETURNING id INTO t3;
  INSERT INTO trip (match_id, school_id, pickup) VALUES (f4, HIL, 'V106 next') RETURNING id INTO t4;
  INSERT INTO trip (match_id, school_id, pickup, notes) VALUES (f6, HIL, 'V106 eights', 'V106 the Eighth rides in front') RETURNING id INTO t6;
  INSERT INTO trip (match_id, school_id, pickup) VALUES (f8, WES, 'V106 Westville eights') RETURNING id INTO t8;
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type) VALUES
    (HIL, '6XI', 'V106 sixes nets', D AT TIME ZONE 'Africa/Johannesburg', 60, 'batting') RETURNING id INTO s6;
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type) VALUES
    (HIL, '7XI', 'V106 sevens nets', D AT TIME ZONE 'Africa/Johannesburg', 60, 'batting') RETURNING id INTO s7;
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type) VALUES
    (HIL, '8XI', 'V106 eights nets', D AT TIME ZONE 'Africa/Johannesburg', 60, 'batting') RETURNING id INTO s8;
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type) VALUES
    (WES, '6XI', 'V106 Westville nets', D AT TIME ZONE 'Africa/Johannesburg', 60, 'batting') RETURNING id INTO sw;
  -- The facts around three fixtures, each written at its host.
  INSERT INTO match_toss (match_id, school_id, won_by, decision) VALUES (f1, HIL, 'home', 'bat'), (f2, WES, 'away', 'bowl'), (f6, HIL, 'home', 'bat');
  INSERT INTO match_official (match_id, school_id, duty, person_name) VALUES
    (f1, HIL, 'umpire', 'V106 Umpire One'), (f2, WES, 'umpire', 'V106 Umpire Two'), (f6, HIL, 'umpire', 'V106 Umpire Six');
  INSERT INTO match_weather (match_id, condition) VALUES (f1, 'sunny'), (f2, 'cloudy'), (f6, 'sunny');
  INSERT INTO fixture_publication (match_id, side, school_id, team_code, published, set_by) VALUES
    (f1, 'home', HIL, '6XI', true, OFFICE), (f1, 'away', WES, '6XI', true, '88888888-0000-0000-0000-00000000000d'),
    (f6, 'home', HIL, '8XI', false, OFFICE);
  RETURN ids || jsonb_build_object('krs', KRS, 'stranger', v_stranger,
    'a', c_a, 'up', c_up, 'b', c_b, 'w', c_w, 'e', c_e, 'n', c_n, 'm', c_m,
    'f1', f1, 'f2', f2, 'f3', f3, 'f4', f4, 'f5', f5, 'f6', f6, 'f7', f7, 'f8', f8,
    't1', t1, 't1b', t1b, 't2', t2, 't3', t3, 't4', t4, 't6', t6, 't8', t8,
    's6', s6, 's7', s7, 's8', s8, 'sw', sw);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The stage's name for an id ('f1', 't1b', …), for reading a set as words.
CREATE OR REPLACE FUNCTION _v106_label(z jsonb, p uuid) RETURNS text AS $$
  SELECT min(key) FROM jsonb_each_text(z) WHERE value = p::text
$$ LANGUAGE sql IMMUTABLE;

-- The reader is himself on this fixture's sheet, not withdrawn, at his own
-- school's end, and holds the capability about himself at his own side
-- (db/106 (e), spelled out apart from it), as the owner.
CREATE OR REPLACE FUNCTION _v106_self_sheet(p_cap text, p_match uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM match m
                   JOIN match_squad ms ON ms.match_id = m.id AND NOT ms.withdrawn
                   JOIN player p ON p.id = ms.player_id
                  WHERE m.id = p_match
                    AND p.school_id = CASE WHEN ms.side = 'away' THEN m.away_school_id ELSE m.school_id END
                    AND (EXISTS (SELECT 1 FROM app_user u WHERE u.id = app_user_id() AND u.player_id = p.id)
                         OR EXISTS (SELECT 1 FROM role_assignment a JOIN assignment_subject g ON g.assignment_id = a.id
                                     WHERE a.person_id = app_user_id() AND a.role = 'selfaccess' AND a.active
                                       AND g.player_id = p.id AND g.verification_state = 'verified'
                                       AND g.valid_from <= current_date
                                       AND (g.valid_until IS NULL OR g.valid_until > current_date)))
                    AND app_can(p_cap, p.school_id, p.team_code, p.id, m.id))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- §2.5's text, spelled out apart from the build: every boy on the side,
-- every boy on the sheet (header (b)'s filters, which proof 1 needs). As the
-- owner, about the caller app.user_id names.
CREATE OR REPLACE FUNCTION _v106_lit_side(p_cap text, p_school uuid, p_team text, p_fixture uuid) RETURNS boolean AS $$
  SELECT app_can(p_cap, p_school, p_team, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, p_fixture)
      OR EXISTS (SELECT 1 FROM player p WHERE p.school_id = p_school AND p.team_code = p_team
                    AND app_can(p_cap, p_school, p_team, p.id, p_fixture))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_lit_fixture(p_cap text, p_match uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM match m WHERE m.id = p_match AND (
       _v106_lit_side(p_cap, m.school_id, m.team_code, m.id)
    OR (m.away_school_id IS NOT NULL AND _v106_lit_side(p_cap, m.away_school_id, m.away_team_code, m.id))
    OR EXISTS (SELECT 1 FROM match_squad ms JOIN player p ON p.id = ms.player_id
                WHERE ms.match_id = m.id AND NOT ms.withdrawn
                  AND p.school_id = CASE WHEN ms.side = 'away' THEN m.away_school_id ELSE m.school_id END
                  AND app_can(p_cap,
                              CASE WHEN ms.side = 'away' THEN m.away_school_id ELSE m.school_id END,
                              CASE WHEN ms.side = 'away' THEN m.away_team_code ELSE m.team_code END,
                              ms.player_id, m.id))
    -- Kameel, 2026-10-15: the boy himself on the sheet, asked at his own side
    OR _v106_self_sheet(p_cap, m.id)))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What db/09 and db/39 asked before this file, as the owner about the caller:
-- the all-zeros person at both anchors (match), the host's (trip, the
-- satellites), the session's side (training).
CREATE OR REPLACE FUNCTION _v106_old_match(p_match uuid) RETURNS boolean AS $$
  SELECT app_can('fixture.read', m.school_id, m.team_code, '00000000-0000-0000-0000-000000000000'::uuid, m.id)
      OR app_can('fixture.read', m.away_school_id, m.away_team_code, '00000000-0000-0000-0000-000000000000'::uuid, m.id)
    FROM match m WHERE m.id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_old_trip(p_trip uuid) RETURNS boolean AS $$
  SELECT app_can('transport.read', m.school_id, m.team_code, '00000000-0000-0000-0000-000000000000'::uuid, m.id)
         AND _v106_old_match(m.id)   -- db/09 read the anchors through match under the caller's own RLS
    FROM trip t JOIN match m ON m.id = t.match_id WHERE t.id = p_trip
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_old_training(p_session uuid) RETURNS boolean AS $$
  SELECT app_can('team.read', s.school_id, s.team_code, '00000000-0000-0000-0000-000000000000'::uuid,
                 '00000000-0000-0000-0000-000000000000'::uuid)
    FROM training_session s WHERE s.id = p_session
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The whole population, as the owner: every person holding an active
-- assignment; the fixtures that have a ball; every plan's side; the people
-- whose every active assignment is a guardian's.
CREATE OR REPLACE FUNCTION _v106_people() RETURNS uuid[] AS $$
  SELECT array_agg(DISTINCT person_id) FROM role_assignment WHERE active
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_guardians_only() RETURNS uuid[] AS $$
  SELECT array_agg(person_id) FROM (SELECT person_id FROM role_assignment WHERE active
                                     GROUP BY person_id HAVING bool_and(role = 'guardian')) g
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_ball_matches() RETURNS uuid[] AS $$
  SELECT coalesce(array_agg(DISTINCT match_id), '{}') FROM ball_event
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_all_matches() RETURNS uuid[] AS $$
  SELECT coalesce(array_agg(id), '{}') FROM match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_plans() RETURNS TABLE (fixture uuid, school uuid, team text) AS $$
  SELECT DISTINCT n.fixture_id, n.school_id, n.team_code FROM news_post n
   WHERE n.kind = 'plan' AND n.scope = 'team' AND n.fixture_id IS NOT NULL
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_sides() RETURNS TABLE (school uuid, team text) AS $$
  SELECT DISTINCT school_id, team_code FROM training_session
  UNION SELECT DISTINCT school_id, team_code FROM player WHERE team_code IS NOT NULL
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- §5 item 2: app_can() asked with NULL and with all-f answers alike, at both
-- ends of a fixture, as the owner about the caller.
CREATE OR REPLACE FUNCTION _v106_spelling(p_cap text, p_match uuid) RETURNS boolean AS $$
  SELECT bool_and(app_can(p_cap, e.s, e.t, NULL, m.id)
                  IS NOT DISTINCT FROM app_can(p_cap, e.s, e.t, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, m.id))
    FROM match m, LATERAL (VALUES (m.school_id, m.team_code), (m.away_school_id, m.away_team_code)) e(s, t)
   WHERE m.id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Every trip (with its end's team, the host's, as trip_read asks), every
-- session and every fixture with a toss, as the owner.
CREATE OR REPLACE FUNCTION _v106_trips() RETURNS TABLE (id uuid, match_id uuid, school_id uuid, team_code text, driver_id uuid) AS $$
  SELECT t.id, t.match_id, t.school_id, m.team_code, t.driver_id FROM trip t JOIN match m ON m.id = t.match_id
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_sessions() RETURNS TABLE (id uuid, school_id uuid, team_code text) AS $$
  SELECT id, school_id, team_code FROM training_session
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v106_toss_matches() RETURNS uuid[] AS $$
  SELECT coalesce(array_agg(match_id), '{}') FROM match_toss
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Branch (1) alone at either end, as the owner about the caller: what an
-- assignment naming nobody gives.
CREATE OR REPLACE FUNCTION _v106_unnamed(p_cap text, p_match uuid) RETURNS boolean AS $$
  SELECT app_can(p_cap, m.school_id, m.team_code, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, m.id)
      OR (m.away_school_id IS NOT NULL
          AND app_can(p_cap, m.away_school_id, m.away_team_code, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, m.id))
    FROM match m WHERE m.id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The seed's own fixtures (98_seed_pilot.sql's 77777777-… ids), as the owner.
CREATE OR REPLACE FUNCTION _v106_seed_matches() RETURNS uuid[] AS $$
  SELECT coalesce(array_agg(id), '{}') FROM match WHERE id::text LIKE '77777777-%'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Take a boy off a sheet as a coach does (withdrawn), as the owner.
CREATE OR REPLACE FUNCTION _v106_withdraw(p_match uuid, p_player uuid) RETURNS integer AS $$
  WITH d AS (UPDATE match_squad SET withdrawn = true WHERE match_id = p_match AND player_id = p_player AND NOT withdrawn RETURNING 1)
  SELECT count(*)::int FROM d
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/106 (section 83) ─────────────────────────────────────────────


-- ┌── db/107 (section 84). The officials register and the grant notes, closed
-- Invented people, one per reader the policies are about, each enrolled (the
-- parents' links verified, as the seed's are), so a row they do not read is
-- the policy refusing them, not an account that reads nothing. Three
-- officials: an adult umpire on no account (U1), a PUPIL who scores and is
-- on the register linked to his own account (S1: PUBLIC_DATA §5a, the child
-- this table can hold), and an umpire linked to the account of a Hilton
-- follower (C1: the appoint route's conflict flag; a role the principal reads
-- and the coach does not). The keeper is a competition
-- administrator (officiating.registry.manage, platform-wide). The opposition
-- feature is granted at Hilton and revoked at Westville, each with a note.
CREATE OR REPLACE FUNCTION _v107_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  WOFFICE uuid := '88888888-0000-0000-0000-00000000000d';
  ids jsonb; v_boy uuid; v_sboy uuid; v_wboy uuid; v_a uuid;
  u1 uuid; s1 uuid; c1 uuid; m uuid; v_sborn date;
BEGIN
  v_sborn := make_date(extract(year FROM sa_today())::int - 15, 4, 2);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneOhSeven Boy', 1071, 'batter', make_date(extract(year FROM sa_today())::int - 15, 3, 1))
  RETURNING id INTO v_boy;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneOhSeven Scorer', 1072, 'batter', v_sborn)
  RETURNING id INTO v_sboy;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '1XI', 'Verify OneOhSeven Westville Boy', 1073, 'batter', make_date(extract(year FROM sa_today())::int - 15, 5, 1))
  RETURNING id INTO v_wboy;
  ids := _v71_people('v107', ARRAY[
    ARRAY['pupil',     'player',           HIL::text, '1XI', v_boy::text],
    ARRAY['scorer',    'player',           HIL::text, '1XI', v_sboy::text],
    ARRAY['parent',    'guardian',         HIL::text, '',    ''],
    ARRAY['coach',     'coach',            HIL::text, '1XI', ''],
    ARRAY['principal', 'principal',        HIL::text, '',    ''],
    ARRAY['office',    'schooladmin',      HIL::text, '',    ''],
    ARRAY['wesoffice', 'schooladmin',      WES::text, '',    ''],
    ARRAY['wesparent', 'guardian',         WES::text, '',    ''],
    ARRAY['linked',    'spectator',        HIL::text, '',    '']]);
  -- The register's keeper belongs to no school (_v71_people writes one).
  INSERT INTO app_user (email, name, role) VALUES ('v107.keeper@example.invalid', 'V107 Keeper', 'competitionadmin')
  RETURNING id INTO v_a;
  INSERT INTO role_assignment (person_id, role, school_id, team_code) VALUES (v_a, 'competitionadmin', NULL, NULL);
  ids := ids || jsonb_build_object('keeper', v_a);
  FOR v_a IN SELECT a.id FROM role_assignment a WHERE a.person_id IN ((ids->>'parent')::uuid, (ids->>'wesparent')::uuid) LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    SELECT v_a, CASE WHEN a.person_id = (ids->>'parent')::uuid THEN v_boy ELSE v_wboy END, 'parent', 'verified',
           CASE WHEN a.person_id = (ids->>'parent')::uuid THEN OFFICE ELSE WOFFICE END, now(), 'granted', 'popia-2026-01', now(),
           CASE WHEN a.person_id = (ids->>'parent')::uuid THEN OFFICE ELSE WOFFICE END, current_date - 1
      FROM role_assignment a WHERE a.id = v_a;
  END LOOP;
  -- An account with no school and no assignment: signed in, enrolled nowhere.
  INSERT INTO app_user (email, name, role) VALUES ('v107.drifter@example.invalid', 'V107 Drifter', 'spectator')
  RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('drifter', v_a);

  INSERT INTO official (full_name, born, id_number, email, phone, panel) VALUES
    ('Verify OneOhSeven Umpire', '1980-01-01', '8001015000080', 'v107.umpire@example.invalid', '+27 82 555 1071', 'V107 Umpires')
  RETURNING id INTO u1;
  INSERT INTO official (full_name, born, id_number, email, phone, panel, person_id) VALUES
    ('Verify OneOhSeven Scorer', v_sborn, to_char(v_sborn, 'YYMMDD') || '5000081', 'v107.scorer@example.invalid',
     '+27 82 555 1072', 'V107 Scorers', (ids->>'scorer')::uuid)
  RETURNING id INTO s1;
  INSERT INTO official (full_name, born, id_number, email, phone, panel, person_id) VALUES
    ('Verify OneOhSeven Linked Umpire', '1978-02-02', '7802025000082', 'v107.linkedump@example.invalid',
     '+27 82 555 1073', 'V107 Umpires', (ids->>'linked')::uuid)
  RETURNING id INTO c1;
  INSERT INTO official_accreditation (official_id, level, issued_by, valid_from, valid_until) VALUES
    (u1, 'level1', 'V107', current_date - 100, current_date + 100),
    (s1, 'club',   'V107', current_date - 10,  NULL);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '1XI', 'Verify OneOhSeven XI', ((sa_today() + 5)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m;

  INSERT INTO feature_grant (key, school_id, granted, note) VALUES
    ('opposition', HIL, true,  'v107: Hilton plan note'),
    ('opposition', WES, false, 'v107: Westville plan note')
  ON CONFLICT (key, school_id) DO UPDATE SET granted = EXCLUDED.granted, note = EXCLUDED.note;

  RETURN ids || jsonb_build_object('boy', v_boy, 'sboy', v_sboy, 'u1', u1, 's1', s1, 'c1', c1, 'm', m,
                                   'n_officials', (SELECT count(*) FROM official));
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What a reader would have been told before db/107: the appoint route's own
-- conflict test, run under the caller's row security with the person named.
-- The person is passed in because the caller can no longer read it; the
-- role_assignment rows are read as the CALLER (SECURITY INVOKER).
CREATE OR REPLACE FUNCTION _v107_conflict_before(p_person uuid, p_match uuid) RETURNS boolean AS $$
  SELECT p_person IS NOT NULL AND EXISTS (
           SELECT 1 FROM role_assignment ra
            WHERE ra.person_id = p_person AND ra.active
              AND ra.school_id = match_school(p_match)
              AND (ra.valid_until IS NULL OR ra.valid_until > current_date))
$$ LANGUAGE sql STABLE;
-- └── db/107 (section 84) ─────────────────────────────────────────────

-- ┌── db/108 (section 85). A pupil is a pupil of a side
-- Two Hilton boys, one on a side (U15A) and one on none, and a third and
-- fourth for enrolment; accounts that ask for a `player` role, and the
-- requests, written as the owner (a request is the asker's own INSERT; the
-- decision is the office's, below, as the office).
CREATE OR REPLACE FUNCTION _v108_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  ids jsonb; v_placed uuid; v_unplaced uuid; v_e1 uuid; v_e2 uuid; v_u uuid; k text; r jsonb := '{}';
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify OneOhEight Placed',   1081, 'batter', make_date(extract(year FROM sa_today())::int - 14, 3, 1))
  RETURNING id INTO v_placed;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, NULL,   'Verify OneOhEight Unplaced', 1082, 'batter', make_date(extract(year FROM sa_today())::int - 14, 4, 1))
  RETURNING id INTO v_unplaced;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U14A', 'Verify OneOhEight Enrolled', 1083, 'batter', make_date(extract(year FROM sa_today())::int - 13, 3, 1))
  RETURNING id INTO v_e1;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, NULL,   'Verify OneOhEight Unenrolled', 1084, 'batter', make_date(extract(year FROM sa_today())::int - 13, 4, 1))
  RETURNING id INTO v_e2;
  ids := _v71_people('v108', ARRAY[ARRAY['office', 'schooladmin', HIL::text, '', '']]);
  -- The askers: accounts at Hilton with no assignment yet, one per request.
  FOREACH k IN ARRAY ARRAY['r1', 'r2', 'r3', 'r4', 'r5', 'direct'] LOOP
    INSERT INTO app_user (school_id, email, name, role)
    VALUES (HIL, 'v108.' || k || '@example.invalid', 'V108 ' || upper(k), 'player') RETURNING id INTO v_u;
    ids := ids || jsonb_build_object('u_' || k, v_u);
  END LOOP;
  -- r1: names the placed boy and no team; r2: the unplaced boy and no team;
  -- r3: no boy and no team; r4: the unplaced boy and a team the asker names;
  -- r5: the unplaced boy and no team, the decider names one.
  INSERT INTO role_request (person_id, role, school_id, team_code, player_id) VALUES
    ((ids->>'u_r1')::uuid, 'player', HIL, NULL,  v_placed)   RETURNING id INTO v_u; r := r || jsonb_build_object('r1', v_u);
  INSERT INTO role_request (person_id, role, school_id, team_code, player_id) VALUES
    ((ids->>'u_r2')::uuid, 'player', HIL, NULL,  v_unplaced) RETURNING id INTO v_u; r := r || jsonb_build_object('r2', v_u);
  INSERT INTO role_request (person_id, role, school_id, team_code, player_id) VALUES
    ((ids->>'u_r3')::uuid, 'player', HIL, NULL,  NULL)       RETURNING id INTO v_u; r := r || jsonb_build_object('r3', v_u);
  INSERT INTO role_request (person_id, role, school_id, team_code, player_id) VALUES
    ((ids->>'u_r4')::uuid, 'player', HIL, '2XI', v_unplaced) RETURNING id INTO v_u; r := r || jsonb_build_object('r4', v_u);
  INSERT INTO role_request (person_id, role, school_id, team_code, player_id) VALUES
    ((ids->>'u_r5')::uuid, 'player', HIL, NULL,  v_unplaced) RETURNING id INTO v_u; r := r || jsonb_build_object('r5', v_u);
  RETURN ids || r || jsonb_build_object('placed', v_placed, 'unplaced', v_unplaced, 'e1', v_e1, 'e2', v_e2);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A write as the OWNER, which no policy stands in front of: only the CHECK.
-- Answers the SQLSTATE and the constraint it named, or 'ok' and the new id.
CREATE OR REPLACE FUNCTION _v108_raw(p_person uuid, p_team text, p_active boolean) RETURNS text AS $$
DECLARE v_id uuid; v_con text;
BEGIN
  INSERT INTO role_assignment (person_id, role, school_id, team_code, active, revoked_at)
  VALUES (p_person, 'player', '11111111-1111-1111-1111-111111111111', p_team, p_active,
          CASE WHEN p_active THEN NULL ELSE now() END)
  RETURNING id INTO v_id;
  RETURN 'ok:' || v_id;
EXCEPTION WHEN check_violation THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN '23514:' || coalesce(nullif(v_con, ''), SQLERRM);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Reactivate an ended row as the owner. db/01's trigger refuses; the CHECK
-- is the floor under it. Answers what refused.
CREATE OR REPLACE FUNCTION _v108_reactivate(p_id uuid) RETURNS text AS $$
DECLARE v_con text;
BEGIN
  UPDATE role_assignment SET active = true, revoked_at = NULL, revoked_by = NULL WHERE id = p_id;
  RETURN 'ok';
EXCEPTION WHEN check_violation THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN '23514:' || coalesce(nullif(v_con, ''), SQLERRM);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Facts about the whole table, as the owner.
CREATE OR REPLACE FUNCTION _v108_fact(p_what text, p_id uuid DEFAULT NULL) RETURNS text AS $$
  SELECT CASE p_what
    WHEN 'teamless_live' THEN (SELECT count(*)::text FROM role_assignment WHERE role = 'player' AND team_code IS NULL AND active)
    WHEN 'team_of' THEN (SELECT coalesce(team_code, '(none)') FROM role_assignment WHERE id = p_id)
    WHEN 'held' THEN (SELECT coalesce(string_agg(role || '@' || coalesce(team_code, '-'), ',' ORDER BY role), '')
                        FROM role_assignment WHERE person_id = p_id AND active)
    WHEN 'request' THEN (SELECT state || ':' || coalesce(team_code, '-') FROM role_request WHERE id = p_id)
    WHEN 'account' THEN (SELECT count(*)::text FROM app_user WHERE lower(email) = 'v108.enrol2@example.invalid')
  END
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/108 (section 85) ─────────────────────────────────────────────
-- ┌── db/110 (section 87). The coach's draft plan: changed, and thrown away
-- Its own side, Hilton's 12XI, so no other section's plans meet it: its
-- coach (the author), a second coach of the side, the team manager, a boy
-- on it and his guardian (verified and consented). Two fixtures, 12XI at
-- home to visitors SCRBRD does not host. As the owner; every name invented.
CREATE OR REPLACE FUNCTION _v110_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  ids jsonb; v_p uuid; f1 uuid; f2 uuid; r record;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '12XI', 'Verify OneTen Captain', 1101, 'batter', U15) RETURNING id INTO v_p;
  ids := _v71_people('v110', ARRAY[
    ARRAY['coach',    'coach',       HIL::text, '12XI', ''],
    ARRAY['coach2',   'coach',       HIL::text, '12XI', ''],
    ARRAY['manager',  'teammanager', HIL::text, '12XI', ''],
    ARRAY['captain',  'player',      HIL::text, '12XI', v_p::text],
    ARRAY['guardian', 'guardian',    HIL::text, '',     '']]);
  FOR r IN SELECT a.id AS aid FROM role_assignment a WHERE a.person_id = (ids->>'guardian')::uuid LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, v_p, 'parent', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '12XI', 'Verify OneTen Visitors', ((sa_today() + 3)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f1;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '12XI', 'Verify OneTen Second Visitors', ((sa_today() + 10)::timestamp + time '09:30') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO f2;
  RETURN ids || jsonb_build_object('f1', f1, 'f2', f2);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A plan's words changed through a door that is not db/12's update policy:
-- as the owner, with whoever the session says is asking (app.user_id). What
-- a later definer would be. Answers ok, or the constraint that refused.
CREATE OR REPLACE FUNCTION _v110_door_edit(p_post uuid, p_body text) RETURNS text AS $$
DECLARE v_con text;
BEGIN
  UPDATE news_post SET body = p_body WHERE id = p_post;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN coalesce(nullif(v_con, ''), SQLSTATE);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One post as the owner sees it: there or not, its words, and its date.
CREATE OR REPLACE FUNCTION _v110_row(p_post uuid) RETURNS text AS $$
  SELECT coalesce((SELECT concat_ws(' | ', n.kind, n.body, n.urgency, (n.published_at IS NOT NULL), (n.first_sent_at IS NOT NULL))
                     FROM news_post n WHERE n.id = p_post), 'gone')
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The words each sending of one post went out with, oldest first: its
-- notices (not the "withdrawn" ones), each with whether it was retracted.
CREATE OR REPLACE FUNCTION _v110_versions(p_post uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(x.body || CASE WHEN x.retracted_at IS NOT NULL THEN ' (retracted)' ELSE ' (live)' END,
                             ' / ' ORDER BY x.published_at, (x.retracted_at IS NULL), x.id), '')
    FROM notification x
   WHERE x.kind = 'notice' AND x.subject_kind = 'news' AND x.subject_id = p_post AND x.retracts_id IS NULL
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/110 (section 87) ─────────────────────────────────────────────
-- ┌── db/111 (section 88). The physio's injury record, its reviews and her worklist
-- Its own sides, so no other section's injuries meet it: Hilton's 12XI (the
-- boy, a team-mate, a boy whose mother is a physio, and a boy who leaves),
-- Hilton's 20XI (another side), Westville's 12XI, and a boy rested for
-- another reason. The school's staff
-- each in one role: three physios (one a mother of a 12XI boy, one with a
-- guardian claim on the boy still pending), the 12XI coach, assistant and
-- manager, the 20XI coach, the director of sport, the principal, the office,
-- the fitness coach, a scorer and a follower; a granted enquiry about the boy
-- (the status tier alone); the boy's parent; the boy and his team-mate, each
-- with his own self link; and Westville's physio. The seed's DSO, platform
-- administrator and owner's key are used as they are. As the owner; every
-- name is invented.
CREATE OR REPLACE FUNCTION _v111_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  ids jsonb; v_boy uuid; v_mate uuid; v_rest uuid; v_own uuid; v_leaver uuid; v_side uuid; v_wes uuid; v_a uuid; r record;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '12XI', 'Verify OneEleven Quick', 1111, 'bowler', U15) RETURNING id INTO v_boy;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '12XI', 'Verify OneEleven Mate', 1112, 'batter', U15) RETURNING id INTO v_mate;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '12XI', 'Verify OneEleven Physioson', 1113, 'batter', U15) RETURNING id INTO v_own;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '12XI', 'Verify OneEleven Leaver', 1114, 'bowler', U15) RETURNING id INTO v_leaver;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '20XI', 'Verify OneEleven Otherside', 1115, 'bowler', U15) RETURNING id INTO v_side;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '12XI', 'Verify OneEleven Westville', 1116, 'bowler', U15) RETURNING id INTO v_wes;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '12XI', 'Verify OneEleven Rested', 1117, 'batter', U15) RETURNING id INTO v_rest;
  ids := _v71_people('v111', ARRAY[
    ARRAY['physio',     'medical',         HIL::text, '',     ''],
    ARRAY['mumphysio',  'medical',         HIL::text, '',     ''],
    ARRAY['claimphysio','medical',         HIL::text, '',     ''],
    ARRAY['coach',      'coach',           HIL::text, '12XI', ''],
    ARRAY['assistant',  'assistantcoach',  HIL::text, '12XI', ''],
    ARRAY['manager',    'teammanager',     HIL::text, '12XI', ''],
    ARRAY['coach20',    'coach',           HIL::text, '20XI', ''],
    ARRAY['director',   'directorofsport', HIL::text, '',     ''],
    ARRAY['principal',  'principal',       HIL::text, '',     ''],
    ARRAY['office',     'schooladmin',     HIL::text, '',     ''],
    ARRAY['fitness',    'fitness',         HIL::text, '',     ''],
    ARRAY['scorer',     'scorer',          HIL::text, '',     ''],
    ARRAY['follower',   'spectator',       HIL::text, '',     ''],
    ARRAY['enquirer',   'enquiry',         HIL::text, '',     ''],
    ARRAY['parent',     'guardian',        HIL::text, '',     ''],
    ARRAY['boy',        'player',          HIL::text, '12XI', v_boy::text],
    ARRAY['mate',       'player',          HIL::text, '12XI', v_mate::text],
    ARRAY['wesphysio',  'medical',         WES::text, '',     '']]);
  -- The links: the parent's to the boy, the enquiry's to the boy (verified);
  -- the mother-physio's to her son (verified); the claiming physio's to the
  -- boy (pending: the office has not checked it).
  FOR r IN SELECT a.id AS aid, x.p, x.rel, x.state FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'parent')::uuid,   v_boy, 'parent', 'verified'),
                                  ((ids->>'enquirer')::uuid, v_boy, 'enquiry', 'verified')) AS x(person, p, rel, state)
            WHERE a.person_id = x.person LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, r.rel, r.state, OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'mumphysio')::uuid, 'guardian', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, v_own, 'parent', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'claimphysio')::uuid, 'guardian', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, created_by, valid_from)
  VALUES (v_a, v_boy, 'parent', 'pending', OFFICE, current_date - 1);
  -- Each boy's own file, as the seed's pupil has his.
  FOR r IN SELECT x.person, x.p FROM (VALUES ((ids->>'boy')::uuid, v_boy), ((ids->>'mate')::uuid, v_mate)) AS x(person, p) LOOP
    INSERT INTO role_assignment (person_id, role, school_id) VALUES (r.person, 'selfaccess', HIL) RETURNING id INTO v_a;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (v_a, r.p, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  RETURN ids || jsonb_build_object('p_boy', v_boy, 'p_mate', v_mate, 'p_own', v_own, 'p_leaver', v_leaver,
                                   'p_side', v_side, 'p_wes', v_wes, 'p_rest', v_rest);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One injury row as the owner reads it, past every mask.
CREATE OR REPLACE FUNCTION _v111_injury(p_id uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(i) FROM injury i WHERE i.id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An injury's reviews, oldest first, as the owner reads them.
CREATE OR REPLACE FUNCTION _v111_reviews(p_injury uuid) RETURNS jsonb AS $$
  SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.reviewed_at, r.id), '[]') FROM injury_review r WHERE r.injury_id = p_injury
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v111_fitness(p_player uuid) RETURNS text AS $$
  SELECT p.fitness FROM player p WHERE p.id = p_player
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v111_set_fitness(p_player uuid, p_fitness text) RETURNS void AS $$
  UPDATE player SET fitness = p_fitness WHERE id = p_player
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The titles of the 'injury' notices about one injury, in title order (one
-- transaction stamps them all with one now()).
CREATE OR REPLACE FUNCTION _v111_notices(p_injury uuid) RETURNS text[] AS $$
  SELECT coalesce(array_agg(n.title ORDER BY n.title), '{}')
    FROM notification n WHERE n.kind = 'injury' AND n.subject_id = p_injury
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The safeguarding notices at a school, as the owner counts them.
CREATE OR REPLACE FUNCTION _v111_sg_count(p_school uuid) RETURNS integer AS $$
  SELECT count(*)::int FROM notification n WHERE n.kind = 'safeguarding' AND n.school_id = p_school
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An owner's edit of an injury, as a record already on file would be
-- corrected: the clock moved for the worklist, or severity raised for SG-12.
CREATE OR REPLACE FUNCTION _v111_edit(p_id uuid, p_next date, p_rtw date) RETURNS void AS $$
  UPDATE injury SET next_review_on = p_next, rtw_date = p_rtw WHERE id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v111_serious(p_id uuid, p_severity text, p_emergency boolean) RETURNS void AS $$
  UPDATE injury SET severity = p_severity, emergency_services = p_emergency WHERE id = p_id
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A review an hour ahead of the clock, as a device with a bad clock would
-- have written it (the owner's insert; the door refuses to follow it).
CREATE OR REPLACE FUNCTION _v111_future_review(p_injury uuid) RETURNS void AS $$
  INSERT INTO injury_review (school_id, player_id, injury_id, reviewed_at, reviewed_by, phase_after,
                             restricted_after, rtw_date_after, next_review_on)
  -- clock_timestamp(), not now(): the verify is one transaction, and one that
  -- waited an hour on the cluster's GRANT lock read now() + 1 hour as past.
  SELECT i.school_id, i.player_id, i.id, clock_timestamp() + interval '1 hour', i.recorded_by, i.phase, i.restricted,
         i.rtw_date, i.next_review_on
    FROM injury i WHERE i.id = p_injury
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A review naming one boy's injury and another boy: the key must refuse it,
-- even to the owner. Returns the SQLSTATE, or 'none'.
CREATE OR REPLACE FUNCTION _v111_mismatch(p_injury uuid, p_other uuid) RETURNS text AS $$
BEGIN
  INSERT INTO injury_review (school_id, player_id, injury_id, reviewed_by, phase_after, restricted_after, next_review_on)
  SELECT i.school_id, p_other, i.id, i.recorded_by, 'rehab', true, sa_today() + 7 FROM injury i WHERE i.id = p_injury;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN RETURN SQLSTATE;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A boy leaves the school today: his open membership closes.
CREATE OR REPLACE FUNCTION _v111_leave(p_player uuid) RETURNS integer AS $$
  WITH d AS (UPDATE team_membership SET left_on = sa_today() WHERE player_id = p_player AND left_on IS NULL RETURNING 1)
  SELECT count(*)::int FROM d
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The Injuries module hidden from one person at Hilton, and shown again.
CREATE OR REPLACE FUNCTION _v111_hide(p_person uuid, p_hide boolean) RETURNS void AS $$
BEGIN
  IF p_hide THEN
    INSERT INTO feature_suppression (key, school_id, person_id, reason, hidden_by)
    VALUES ('injuries', '11111111-1111-1111-1111-111111111111', p_person, 'v111: module off for this physio',
            '88888888-0000-0000-0000-00000000000c');
  ELSE
    UPDATE feature_suppression SET lifted_at = now(), lifted_by = '88888888-0000-0000-0000-00000000000c'
     WHERE key = 'injuries' AND person_id = p_person AND lifted_at IS NULL;
  END IF;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- An injury already serious when db/111 ran: severe, and no DSO stamp, as a
-- row written before the trigger existed would be. The trigger is held off
-- for this one insert, inside the rolled-back transaction.
CREATE OR REPLACE FUNCTION _v111_legacy_severe(p_player uuid) RETURNS uuid AS $$
DECLARE v_id uuid;
BEGIN
  ALTER TABLE injury DISABLE TRIGGER injury_serious_watch;
  INSERT INTO injury (school_id, player_id, injury_type, severity, date_injured, restricted)
  SELECT p.school_id, p.id, 'Old fracture', 'severe', sa_today() - 30, true FROM player p WHERE p.id = p_player
  RETURNING id INTO v_id;
  ALTER TABLE injury ENABLE TRIGGER injury_serious_watch;
  RETURN v_id;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- injury_retention_due() is the database's own (not the application's).
CREATE OR REPLACE FUNCTION _v111_due(p_player uuid) RETURNS date AS $$ SELECT injury_retention_due(p_player) $$
  LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/111 (section 88) ─────────────────────────────────────────────

-- ┌── db/112 (section 89). A moved pupil follows his new side; the boy playing up reads his match's balls
-- Its own sides, so no other section's rows meet it: Hilton's U14E (the side
-- the boys start on), U15E (the side the movers go to) and U16E (the older
-- side one boy plays up into, home at Hilton twice and away at Westville
-- once). The boys, each with his own account (app_user.player_id) holding a
-- `player` role on U14E, as the office grants one:
--   mb   the mover, who also holds self-access naming himself (as R Pillay
--        does), and whose mother (g) is linked to him
--   sb   a mover whose account names him only through a verified self-access
--        link (no app_user.player_id)
--   nb   moved to no side
--   up   plays up: on the sheet of U16E's f16a (home) and f16w (away), not of
--        f16b; his mother (gup) is linked to him
--   wd   was on f16a's sheet, withdrawn; his mother (gwd) is linked to him
--   tm   up's team-mate, on no sheet
--   pb   a boy whose would-be account (pa) is linked by a self-access claim
--        still PENDING: not his account yet
--   t1   a boy whose account (two) is also another boy, t2, by self-access:
--        an account with no one side to follow
-- Fixtures f14 (U14E), f15 (U15E), f16a, f16b, f16w, each with balls; nets
-- s14, s15; a plan to each of U14E (p14, for f14) and U15E (p15, for f15),
-- each from its side's coach. As the owner; every name is invented.
CREATE OR REPLACE FUNCTION _v112_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U14 date := make_date(extract(year FROM sa_today())::int - 13, 3, 1);
  D timestamp := (sa_today() + 3)::timestamp + time '10:00';
  ids jsonb; z jsonb := '{}'; k text; b text; st text; v_id uuid; v_a uuid;
  i int := 0;
BEGIN
  FOREACH k IN ARRAY ARRAY['mb', 'sb', 'nb', 'up', 'wd', 'tm', 'pb', 't1', 't2'] LOOP
    i := i + 1;
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
      (HIL, 'U14E', 'Verify OneOneTwo ' || initcap(k), 1120 + i, 'batter', U14) RETURNING id INTO v_id;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  ids := _v71_people('v112', ARRAY[
    ARRAY['u_mb',    'player',      HIL::text, 'U14E', z->>'mb'],
    ARRAY['u_sb',    'player',      HIL::text, 'U14E', ''],
    ARRAY['u_nb',    'player',      HIL::text, 'U14E', z->>'nb'],
    ARRAY['u_up',    'player',      HIL::text, 'U14E', z->>'up'],
    ARRAY['u_wd',    'player',      HIL::text, 'U14E', z->>'wd'],
    ARRAY['u_tm',    'player',      HIL::text, 'U14E', z->>'tm'],
    ARRAY['u_pa',    'player',      HIL::text, 'U14E', ''],
    ARRAY['u_two',   'player',      HIL::text, 'U14E', z->>'t1'],
    ARRAY['g',       'guardian',    HIL::text, '',     ''],
    ARRAY['gup',     'guardian',    HIL::text, '',     ''],
    ARRAY['gwd',     'guardian',    HIL::text, '',     ''],
    ARRAY['office',  'schooladmin', HIL::text, '',     ''],
    ARRAY['coach14', 'coach',       HIL::text, 'U14E', ''],
    ARRAY['coach15', 'coach',       HIL::text, 'U15E', '']]);
  -- The links the office makes: the three mothers', and the self-access
  -- links (mb's, sb's and two's verified; pa's pending).
  PERFORM _v100_link((ids->>'g')::uuid, HIL, (z->>'mb')::uuid);
  PERFORM _v100_link((ids->>'gup')::uuid, HIL, (z->>'up')::uuid);
  PERFORM _v100_link((ids->>'gwd')::uuid, HIL, (z->>'wd')::uuid);
  FOR k, b, st IN SELECT x.who, x.boy, x.state FROM (VALUES ('u_mb', 'mb', 'verified'), ('u_sb', 'sb', 'verified'),
                                                              ('u_two', 't2', 'verified'), ('u_pa', 'pb', 'pending')) x(who, boy, state) LOOP
    INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>k)::uuid, 'selfaccess', HIL) RETURNING id INTO v_a;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (v_a, (z->>b)::uuid, 'self', st, OFFICE, CASE WHEN st = 'verified' THEN now() END,
            'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, 'U14E', 'Verify OneOneTwo Fourteens', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
  z := z || jsonb_build_object('f14', v_id);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, 'U15E', 'Verify OneOneTwo Fifteens', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
  z := z || jsonb_build_object('f15', v_id);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, 'U16E', 'Verify OneOneTwo Sixteens', D AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
  z := z || jsonb_build_object('f16a', v_id);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (HIL, 'U16E', 'Verify OneOneTwo Sixteens Again', (D + interval '7 days') AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
  z := z || jsonb_build_object('f16b', v_id);
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status) VALUES
    (WES, 'U16E', HIL, 'U16E', 'Verify OneOneTwo Hilton', (D + interval '14 days') AT TIME ZONE 'Africa/Johannesburg', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
  z := z || jsonb_build_object('f16w', v_id);
  -- The sheets: up on f16a (home) and f16w (away); wd on f16a, then withdrawn.
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    ((z->>'f16a')::uuid, (z->>'up')::uuid, 'home', 1), ((z->>'f16w')::uuid, (z->>'up')::uuid, 'away', 1),
    ((z->>'f16a')::uuid, (z->>'wd')::uuid, 'home', 2);
  UPDATE match_squad SET withdrawn = true WHERE match_id = (z->>'f16a')::uuid AND player_id = (z->>'wd')::uuid;
  -- Balls on every fixture, a different number each (6, 12, 18, 24, 30).
  PERFORM _v71_bowl((z->>'f14')::uuid,  OFFICE, ARRAY[NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f15')::uuid,  OFFICE, ARRAY[NULL, NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f16a')::uuid, OFFICE, ARRAY[NULL, NULL, NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f16b')::uuid, OFFICE, ARRAY[NULL, NULL, NULL, NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f16w')::uuid, OFFICE, ARRAY[NULL, NULL, NULL, NULL, NULL]::uuid[]);
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type) VALUES
    (HIL, 'U14E', 'V112 fourteens nets', D AT TIME ZONE 'Africa/Johannesburg', 60, 'batting') RETURNING id INTO v_id;
  z := z || jsonb_build_object('s14', v_id);
  INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type) VALUES
    (HIL, 'U15E', 'V112 fifteens nets', D AT TIME ZONE 'Africa/Johannesburg', 60, 'batting') RETURNING id INTO v_id;
  z := z || jsonb_build_object('s15', v_id);
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, 'U14E', 'plan', (z->>'f14')::uuid, 'V112 fourteens plan', 'V112 meet at the nets', now() - interval '1 minute',
          (ids->>'coach14')::uuid) RETURNING id INTO v_id;
  z := z || jsonb_build_object('p14', v_id);
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, 'U15E', 'plan', (z->>'f15')::uuid, 'V112 fifteens plan', 'V112 meet at the pavilion', now() - interval '1 minute',
          (ids->>'coach15')::uuid) RETURNING id INTO v_id;
  z := z || jsonb_build_object('p15', v_id);
  RETURN ids || z;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the caller reads of the stage, under his own row security (a plain
-- invoker): "fixtures [..] training [..] plans [..] balls [..]", each by the
-- stage's labels, sorted. Balls are the fixtures he reads a ball of.
CREATE OR REPLACE FUNCTION _v112_reads(z jsonb) RETURNS text AS $$
  SELECT format('fixtures [%s] training [%s] plans [%s] balls [%s]',
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '')
       FROM (SELECT _v106_label(z, m.id) l FROM match m
              WHERE m.id::text IN (z->>'f14', z->>'f15', z->>'f16a', z->>'f16b', z->>'f16w')) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '')
       FROM (SELECT _v106_label(z, s.id) l FROM training_session s WHERE s.id::text IN (z->>'s14', z->>'s15')) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '')
       FROM (SELECT _v106_label(z, n.id) l FROM news_post n WHERE n.id::text IN (z->>'p14', z->>'p15')) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '')
       FROM (SELECT DISTINCT _v106_label(z, b.match_id) l FROM ball_event b
              WHERE b.match_id::text IN (z->>'f14', z->>'f15', z->>'f16a', z->>'f16b', z->>'f16w')) x))
$$ LANGUAGE sql STABLE;

-- How many balls of one fixture the caller reads, under his row security.
CREATE OR REPLACE FUNCTION _v112_balls(p_match uuid) RETURNS int AS $$
  SELECT count(*)::int FROM ball_event WHERE match_id = p_match
$$ LANGUAGE sql STABLE;

-- A person's `player` rows, as the owner: "TEAM:ended" then "TEAM:live",
-- each by side, e.g. 'U14E:ended U15E:live'. (Every row here is made in the
-- verifier's one transaction, so created_at cannot order them.)
CREATE OR REPLACE FUNCTION _v112_roles(p_person uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(coalesce(team_code, '-') || ':' || CASE WHEN active THEN 'live' ELSE 'ended' END,
                             ' ' ORDER BY active, team_code), '')
    FROM role_assignment WHERE person_id = p_person AND role = 'player'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Everything about a person's assignments that a carry must leave alone:
-- every row but his `player` rows, and every link on them, as one digest.
CREATE OR REPLACE FUNCTION _v112_others(p_person uuid) RETURNS text AS $$
  SELECT md5(coalesce(string_agg(concat_ws('|', a.id, a.role, a.school_id, a.team_code, a.active, a.revoked_at, a.created_at,
                                           g.player_id, g.verification_state, g.valid_from, g.valid_until),
                                 ';' ORDER BY a.id, g.player_id), ''))
    FROM role_assignment a LEFT JOIN assignment_subject g ON g.assignment_id = a.id
   WHERE a.person_id = p_person AND a.role <> 'player'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Facts, as the owner.
CREATE OR REPLACE FUNCTION _v112_fact(p_what text, p_id uuid DEFAULT NULL) RETURNS text AS $$
  SELECT CASE p_what
    -- a person's ended `player` rows: who ended each, and that its time is stamped
    WHEN 'ended_by' THEN (SELECT string_agg(coalesce(revoked_by::text, '-') || CASE WHEN revoked_at IS NULL THEN ':unstamped' ELSE '' END,
                                            ' ' ORDER BY created_at)
                            FROM role_assignment WHERE person_id = p_id AND role = 'player' AND NOT active)
    -- a person's live `player` rows: who made each
    WHEN 'made_by' THEN (SELECT string_agg(coalesce(created_by::text, '-'), ' ' ORDER BY created_at)
                           FROM role_assignment WHERE person_id = p_id AND role = 'player' AND active)
    WHEN 'side' THEN (SELECT coalesce(team_code, '(none)') FROM player WHERE id = p_id)
    WHEN 'open_membership' THEN (SELECT coalesce(string_agg(team_code, ','), '(none)') FROM team_membership
                                  WHERE player_id = p_id AND sport = 'cricket' AND left_on IS NULL)
    WHEN 'teamless_live' THEN (SELECT count(*)::text FROM role_assignment WHERE role = 'player' AND team_code IS NULL AND active)
    WHEN 'disagree' THEN (SELECT count(*)::text FROM player_assignment_disagreements())
    -- the boys whose accounts' rows disagree, by id, and by name and sides
    WHEN 'disagree_boys' THEN (SELECT coalesce(string_agg(DISTINCT d.player_id::text, ',' ORDER BY d.player_id::text), '')
                                 FROM player_assignment_disagreements() d)
    WHEN 'disagree_names' THEN (SELECT coalesce(string_agg(DISTINCT p.full_name || ' (' || coalesce(d.player_team, 'no side')
                                                           || ', role on ' || d.assignment_team || ')', '; '), '')
                                  FROM player_assignment_disagreements() d JOIN player p ON p.id = d.player_id)
    WHEN 'owner_balls' THEN (SELECT count(*)::text FROM ball_event WHERE match_id = p_id)
    WHEN 'seed_live' THEN (SELECT string_agg(id::text || ':' || team_code, ' ' ORDER BY id) FROM role_assignment
                            WHERE role = 'player' AND active AND id::text LIKE 'a5510000-%')
    WHEN 'all_assignments' THEN (SELECT md5(string_agg(concat_ws('|', id, person_id, role, team_code, active, revoked_at), ';' ORDER BY id))
                                   FROM role_assignment)
    -- db/128 moved its day to sa_today(); read back on db/92's clock.
    WHEN 'grant_md5' THEN (SELECT md5(replace(replace(prosrc, 'sa_today()', 'current_date'),
          '  -- db/108: a pupil is a pupil OF A SIDE (role_assignment_player_team_scoped).' || chr(10)
       || '  -- No side named by the request or the decider: his own side on the roster,' || chr(10)
       || '  -- at this school. None there either: refused by name, before anything is' || chr(10)
       || '  -- written, as a coach with no side is.' || chr(10)
       || '  IF r.role = ''player'' AND v_team IS NULL THEN' || chr(10)
       || '    SELECT p.team_code INTO v_team FROM player p WHERE p.id = v_player AND p.school_id = r.school_id;' || chr(10)
       || '    IF v_team IS NULL THEN' || chr(10)
       || '      RETURN QUERY SELECT false, ''team_required'', NULL::uuid; RETURN;' || chr(10)
       || '    END IF;' || chr(10)
       || '  END IF;' || chr(10), ''))
       FROM pg_proc WHERE oid = to_regprocedure('role_request_grant_as(uuid,uuid,text,uuid,text)'))
    WHEN 'child_md5' THEN (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('my_child_fixtures()'))
  END
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A move made before this file: the side written with the carry switched off,
-- so the assignment is left where it was, as every move before db/112 left
-- it. As the owner.
CREATE OR REPLACE FUNCTION _v112_move_untracked(p_player uuid, p_team text) RETURNS void AS $$
BEGIN
  ALTER TABLE player DISABLE TRIGGER player_assignment_follows_side;
  UPDATE player SET team_code = p_team WHERE id = p_player;
  ALTER TABLE player ENABLE TRIGGER player_assignment_follows_side;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A live `player` row written straight onto the table at a side, as an
-- office did by hand before db/112. As the owner.
CREATE OR REPLACE FUNCTION _v112_grant(p_person uuid, p_team text) RETURNS void AS $$
  INSERT INTO role_assignment (person_id, role, school_id, team_code)
  VALUES (p_person, 'player', '11111111-1111-1111-1111-111111111111', p_team)
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/112's one-time correction, run again. As the owner: what it did, per
-- boy, {"<player id>": "ended:opened"}.
CREATE OR REPLACE FUNCTION _v112_correct() RETURNS jsonb AS $$
  SELECT coalesce(jsonb_object_agg(player_id::text, ended || ':' || opened), '{}')
    FROM player_assignment_correct()
$$ LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- db/100's three branches of ball_event_read, spelled out apart from the
-- policy, about the caller app.user_id names, for one fixture: does he read
-- a ball of it by one of them? p_child is my_child_fixtures() as he calls
-- it, taken once per person. As the owner.
CREATE OR REPLACE FUNCTION _v112_db100(p_match uuid, p_child uuid[]) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM (SELECT DISTINCT b.school_id FROM ball_event b WHERE b.match_id = p_match) s
                  WHERE app_can('fixture.read', s.school_id, match_team(p_match), NULL, p_match))
      OR (EXISTS (SELECT 1 FROM ball_event b WHERE b.match_id = p_match)
          AND (EXISTS (SELECT 1 FROM match m WHERE m.id = p_match AND m.away_school_id IS NOT NULL
                          AND app_can('fixture.read', m.away_school_id, m.away_team_code, NULL, p_match))
               OR p_match = ANY (p_child)))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/112 (section 89) ─────────────────────────────────────────────
-- ┌── db/113 (section 90). A correction takes back what it falsified
-- A Hilton side of its own (U19F): a batter who reaches a fifty on a six
-- (D Erasmus's case), a partner whose fifty stands, a U13 pace bowler who
-- goes past his spell, an Open bowler with a hat-trick to be made by a
-- correction; the readers the notices reach and the ones they must not.
-- Written as the owner, the way the scorer's pad and the amendment route
-- reach ball_event (their own paths are the walks'); every read in the
-- section is a person's, through scrbrd_app under RLS.
CREATE OR REPLACE FUNCTION _v113_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U16 date := make_date(extract(year FROM sa_today())::int - 16, 3, 1);
  U13 date := make_date(extract(year FROM sa_today())::int - 12, 3, 1);
  OPEN date := make_date(extract(year FROM sa_today())::int - 19, 3, 1);
  ids jsonb; v_bat uuid; v_par uuid; v_q uuid; v_h uuid; v_m uuid; r record;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U19F', 'Verify OneThirteen Opener', 1131, 'batter', U16) RETURNING id INTO v_bat;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U19F', 'Verify OneThirteen Partner', 1132, 'batter', U16) RETURNING id INTO v_par;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born, bowling_style) VALUES
    (HIL, 'U19F', 'Verify OneThirteen Quick', 1133, 'bowler', U13, 'F') RETURNING id INTO v_q;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born, bowling_style) VALUES
    (HIL, 'U19F', 'Verify OneThirteen Hattrick', 1134, 'bowler', OPEN, 'F') RETURNING id INTO v_h;
  ids := _v71_people('v113', ARRAY[
    ARRAY['coach',     'coach',     HIL::text, 'U19F', ''],
    ARRAY['scorer',    'scorer',    HIL::text, '',     ''],
    ARRAY['boy',       'player',    HIL::text, 'U19F', v_bat::text],
    ARRAY['parent',    'guardian',  HIL::text, '',     ''],
    ARRAY['pparent',   'guardian',  HIL::text, '',     ''],
    ARRAY['wescoach',  'coach',     WES::text, 'U19F', ''],
    ARRAY['follower',  'spectator', HIL::text, '',     '']]);
  FOR r IN SELECT a.id AS aid, x.p FROM role_assignment a,
                  LATERAL (VALUES ((ids->>'parent')::uuid, v_bat), ((ids->>'pparent')::uuid, v_par)) AS x(person, p)
            WHERE a.person_id = x.person LOOP
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (r.aid, r.p, 'parent', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U19F', 'Verify OneThirteen Visitors', (sa_today()::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'live')
  RETURNING id INTO v_m;
  RETURN ids || jsonb_build_object('bat', v_bat, 'par', v_par, 'quick', v_q, 'hat', v_h, 'match', v_m);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One event at the end of the match's log, as the pad appends one. Returns
-- its key. A void names its target in the payload, as the pad and the
-- amendment route both write it.
CREATE OR REPLACE FUNCTION _v113_ev(p_match uuid, p_innings smallint, p_kind text, p_type text, p_value integer,
                                    p_striker uuid, p_bowler uuid, p_dismissal text DEFAULT NULL, p_target text DEFAULT NULL)
RETURNS text AS $$
DECLARE s integer; k text;
BEGIN
  s := coalesce((SELECT max(seq) FROM ball_event WHERE match_id = p_match), 0) + 1;
  k := 'v113-' || p_match || '-' || s;
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                          idempotency_key, client_seq, client_ts, kind, ball_type, value,
                          striker_id, bowler_id, dismissal, payload)
  SELECT p_match, m.school_id, s, 0, p_innings, (SELECT id FROM app_user WHERE email = 'v113.scorer@example.invalid'),
         'v113-pad', k, s, now(), p_kind, p_type, p_value, p_striker, p_bowler, p_dismissal,
         CASE WHEN p_kind = 'void' THEN jsonb_build_object('target', p_target) ELSE '{}'::jsonb END
    FROM match m WHERE m.id = p_match;
  RETURN k;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What was written about one boy, as the owner reads it (what RLS would not
-- say): every notification whose subject he is, oldest first, whole.
CREATE OR REPLACE FUNCTION _v113_about(p_player uuid) RETURNS jsonb AS $$
  SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.published_at, n.retracts_id NULLS FIRST, n.id), '[]'::jsonb)
    FROM notification n WHERE n.subject_person_id = p_player
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One mark's row, or one breach's, as the owner reads it.
CREATE OR REPLACE FUNCTION _v113_mark(p_player uuid, p_kind text, p_match uuid) RETURNS jsonb AS $$
  SELECT to_jsonb(mn) FROM milestone_notice mn WHERE mn.player_id = p_player AND mn.kind = p_kind AND mn.match_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v113_breaches(p_player uuid) RETURNS jsonb AS $$
  SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.noticed_at, b.kind), '[]'::jsonb) FROM bowling_breach b WHERE b.bowler_id = p_player
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/113 (section 90) ─────────────────────────────────────────────


-- ┌── db/114 (section 91). When a result becomes official
-- Two Hilton sides of their own (U17F for a friendly against Westville's
-- U17F; U17E, U17D, U17C in a league of their own with no organising school)
-- and the people who stand behind a result, dispute it, or must not: two
-- directors of sport, a principal, a league organiser, a scorer, a man who is
-- both a scorer and a director of sport (two hats, D5's case), a coach and a
-- follower. Written as the owner, the way the pad, the amendment route and
-- the hold reach the log; every read and every door in the section is a
-- person's, through scrbrd_app under RLS.
CREATE OR REPLACE FUNCTION _v114_person(p_tag text, p_role text, p_school uuid, p_team text) RETURNS uuid AS $$
DECLARE v_u uuid;
BEGIN
  INSERT INTO app_user (school_id, email, name, role, teams)
  VALUES (p_school, 'v114.' || p_tag || '@example.invalid', 'V114 ' || initcap(p_tag), p_role,
          CASE WHEN p_team IS NULL THEN '{}'::text[] ELSE ARRAY[p_team] END)
  RETURNING id INTO v_u;
  INSERT INTO role_assignment (person_id, role, school_id, team_code) VALUES (v_u, p_role, p_school, p_team);
  RETURN v_u;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One event at the end of a match's log, as the pad appends one. Returns its key.
CREATE OR REPLACE FUNCTION _v114_ev(p_match uuid, p_innings smallint, p_kind text, p_type text, p_value integer,
                                    p_payload jsonb, p_scorer uuid) RETURNS text AS $$
DECLARE s integer; k text;
BEGIN
  s := coalesce((SELECT max(seq) FROM ball_event WHERE match_id = p_match), 0) + 1;
  k := 'v114-' || p_match || '-' || s;
  INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                          idempotency_key, client_seq, client_ts, kind, ball_type, value, payload)
  SELECT p_match, m.school_id, s, 0, p_innings, p_scorer, 'v114-pad', k, s, now(), p_kind, p_type, p_value,
         coalesce(p_payload, '{}'::jsonb)
    FROM match m WHERE m.id = p_match;
  RETURN k;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One innings of one over, sealed by the scorer: the innings' start (an
-- eleven, one over, a target for the chase), six balls of the runs given, and
-- the seal reading back the log's own figures (sealRefusal(), db/69).
-- Returns the keys of the six balls.
CREATE OR REPLACE FUNCTION _v114_innings(p_match uuid, p_innings smallint, p_bat text, p_bowl text, p_runs integer[],
                                         p_target integer, p_scorer uuid, p_seal boolean DEFAULT true) RETURNS text[] AS $$
DECLARE v_keys text[] := '{}'; r integer; v_sq jsonb;
BEGIN
  SELECT jsonb_agg(jsonb_build_object('id', 'v114-' || p_bat || '-' || g, 'name', p_bat || ' ' || g)) INTO v_sq
    FROM generate_series(1, 11) g;
  PERFORM _v114_ev(p_match, p_innings, 'innings_start', NULL, NULL,
    jsonb_build_object('battingTeam', p_bat, 'teamKey', p_bat, 'bowlingTeam', p_bowl, 'squad', v_sq, 'overs', 1)
      || CASE WHEN p_target IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('target', p_target) END, p_scorer);
  FOREACH r IN ARRAY p_runs LOOP
    v_keys := v_keys || _v114_ev(p_match, p_innings, 'ball', 'run', r, NULL, p_scorer);
  END LOOP;
  IF p_seal THEN
    PERFORM _v114_ev(p_match, p_innings, 'innings_end', NULL, NULL,
      jsonb_build_object('reason', CASE WHEN p_target IS NOT NULL AND (SELECT sum(x) FROM unnest(p_runs) x) >= p_target
                                        THEN 'target_reached' ELSE 'overs_complete' END,
                         'confirmed', jsonb_build_object('runs', (SELECT sum(x) FROM unnest(p_runs) x), 'wickets', 0,
                                                         'balls', cardinality(p_runs))), p_scorer);
  END IF;
  RETURN v_keys;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _v114_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  v_t0 timestamptz := (sa_today()::timestamp + time '09:00') AT TIME ZONE 'Africa/Johannesburg';
  ids jsonb := '{}';
  v_c uuid; m uuid; k text; t text;
BEGIN
  ids := ids || jsonb_build_object(
    'hdos',    _v114_person('hdos',    'directorofsport', HIL, NULL),
    'hprin',   _v114_person('hprin',   'principal',       HIL, NULL),
    'wdos',    _v114_person('wdos',    'directorofsport', WES, NULL),
    'scorer',  _v114_person('scorer',  'scorer',          HIL, NULL),
    'twohats', _v114_person('twohats', 'scorer',          HIL, NULL),
    'org',     _v114_person('org',     'competitionadmin', NULL, NULL),
    'coach',   _v114_person('coach',   'coach',           HIL, 'U17F'),
    'follower', _v114_person('follower', 'spectator',     HIL, NULL),
    'wescoach', _v114_person('wescoach', 'coach',         WES, 'U17F'),
    'outsider', _v114_person('outsider', 'coach',         WES, 'U14A'),
    'horg',    _v114_person('horg',    'competitionadmin', HIL, NULL));
  -- Two hats: the same person is a director of sport too (Sarah's case).
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'twohats')::uuid, 'directorofsport', HIL);

  -- A league with no organising school, as the seed's is: its organiser is a
  -- platform-wide competitionadmin. Its four sides entered.
  INSERT INTO competition (school_id, name, comp_type, format, level)
  VALUES (NULL, 'Verify OneFourteen League', 'league', 'T20', 'school') RETURNING id INTO v_c;
  FOREACH t IN ARRAY ARRAY['U17E', 'U17D', 'U17C', 'U17B'] LOOP
    INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name)
    VALUES (v_c, HIL, t, 'V114 Hilton ' || t), (v_c, WES, t, 'V114 Westville ' || t);
  END LOOP;
  INSERT INTO competition_publication (competition_id, published, set_by) VALUES (v_c, true, (ids->>'org')::uuid);
  ids := ids || jsonb_build_object('comp', v_c);

  -- F: the friendly. L: the league's (the organiser confirms). L2: a league
  -- fixture whose document says home_school; L3: either_school. T: a friendly
  -- the two-hatted man scored. U: complete, its innings never sealed. A:
  -- abandoned before a ball.
  FOR k, t IN SELECT * FROM (VALUES ('F', 'U17F'), ('L', 'U17E'), ('L2', 'U17D'), ('L3', 'U17C'), ('T', 'U16E'), ('U', 'U16D'), ('A', 'U16C')) x(k, t) LOOP
    INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status,
                       competition_id)
    VALUES (HIL, t, WES, t, 'x', v_t0, 'cricket', 'T20', 1, 'live', CASE WHEN k LIKE 'L%' THEN v_c END)
    RETURNING id INTO m;
    ids := ids || jsonb_build_object(k, m);
  END LOOP;
  -- The two league documents that name who confirms (D4), fixed before the first ball.
  INSERT INTO match_conditions (match_id, doc, sources, doc_hash) VALUES
    ((ids->>'L2')::uuid, '{"play": {}, "table": {"results.confirmed_by": "home_school", "results.dispute_days": 3}, "sheet": {}}', '{}', ''),
    ((ids->>'L3')::uuid, '{"play": {}, "table": {"results.confirmed_by": "either_school"}, "sheet": {}}', '{}', '');

  -- Every played match: Hilton 6 off the over, Westville 0 chasing 7, both sealed.
  FOR k IN SELECT unnest(ARRAY['F', 'L', 'L2', 'L3', 'T', 'U']) LOOP
    m := (ids->>k)::uuid;
    t := (SELECT team_code FROM match WHERE id = m);
    PERFORM _v114_innings(m, 0::smallint, t, 'Westville ' || t, ARRAY[1, 1, 1, 1, 1, 1], NULL,
                          (ids->>CASE WHEN k = 'T' THEN 'twohats' ELSE 'scorer' END)::uuid, k <> 'U');
    PERFORM _v114_innings(m, 1::smallint, 'Westville ' || t, t, ARRAY[0, 0, 0, 0, 0, 0], 7,
                          (ids->>CASE WHEN k = 'T' THEN 'twohats' ELSE 'scorer' END)::uuid, k <> 'U');
  END LOOP;
  UPDATE match SET status = 'complete' WHERE id IN ((ids->>'L')::uuid, (ids->>'L2')::uuid, (ids->>'L3')::uuid,
                                                   (ids->>'T')::uuid, (ids->>'U')::uuid);
  UPDATE match SET status = 'abandoned' WHERE id = (ids->>'A')::uuid;
  -- H: a league Hilton itself organises (competition.school_id = Hilton),
  -- Hilton U15E v Westville U15E, played and complete; its administrator is
  -- 'horg', a competitionadmin at Hilton (the security review's case).
  INSERT INTO competition (school_id, name, comp_type, format, level)
  VALUES (HIL, 'Verify OneFourteen Hilton Cup', 'league', 'T20', 'school') RETURNING id INTO v_c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name)
  VALUES (v_c, HIL, 'U15E', 'V114 Hilton U15E'), (v_c, WES, 'U15E', 'V114 Westville U15E');
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, 'U15E', WES, 'U15E', 'x', v_t0, 'cricket', 'T20', 1, 'live', v_c) RETURNING id INTO m;
  ids := ids || jsonb_build_object('H', m, 'hcomp', v_c);
  PERFORM _v114_innings(m, 0::smallint, 'U15E', 'Westville U15E', ARRAY[1, 1, 1, 1, 1, 1], NULL, (ids->>'scorer')::uuid);
  PERFORM _v114_innings(m, 1::smallint, 'Westville U15E', 'U15E', ARRAY[0, 0, 0, 0, 0, 0], 7, (ids->>'scorer')::uuid);
  -- FG: a friendly, both innings sealed, then a pad void after the first seal
  -- whose payload forges an amendment approved by Hilton's director.
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15D', WES, 'U15D', 'x', v_t0, 'cricket', 'T20', 1, 'live') RETURNING id INTO m;
  ids := ids || jsonb_build_object('FG', m);
  k := (_v114_innings(m, 0::smallint, 'U15D', 'Westville U15D', ARRAY[1, 1, 1, 1, 1, 1], NULL, (ids->>'scorer')::uuid))[1];
  PERFORM _v114_innings(m, 1::smallint, 'Westville U15D', 'U15D', ARRAY[0, 0, 0, 0, 0, 0], 7, (ids->>'scorer')::uuid);
  PERFORM _v114_ev(m, 0::smallint, 'void', NULL, NULL,
    jsonb_build_object('target', k, 'amendment', gen_random_uuid(), 'approved_by', ids->>'hdos'), (ids->>'scorer')::uuid);
  -- BS: a friendly whose first innings carries a seal that never stood (it
  -- reads back 99 runs) and nothing after it.
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15C', WES, 'U15C', 'x', v_t0, 'cricket', 'T20', 1, 'live') RETURNING id INTO m;
  ids := ids || jsonb_build_object('BS', m);
  PERFORM _v114_innings(m, 0::smallint, 'U15C', 'Westville U15C', ARRAY[1, 1, 1, 1, 1, 1], NULL, (ids->>'scorer')::uuid, false);
  PERFORM _v114_ev(m, 0::smallint, 'innings_end', NULL, NULL,
    '{"reason": "overs_complete", "confirmed": {"runs": 99, "wickets": 0, "balls": 6}}'::jsonb, (ids->>'scorer')::uuid);
  PERFORM _v114_innings(m, 1::smallint, 'Westville U15C', 'U15C', ARRAY[0, 0, 0, 0, 0, 0], 7, (ids->>'scorer')::uuid);
  UPDATE match SET status = 'complete' WHERE id IN ((ids->>'H')::uuid, (ids->>'FG')::uuid, (ids->>'BS')::uuid);

  -- Both sides of F published: the signed-out page serves it.
  INSERT INTO fixture_publication (match_id, side, school_id, team_code, published, set_by)
  VALUES ((ids->>'F')::uuid, 'home', HIL, 'U17F', true, (ids->>'hdos')::uuid);
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The owner's hands: a match's status, a correction filed (the scorer's first
-- signature), a held ball and its rejection, a decision withdrawn.
CREATE OR REPLACE FUNCTION _v114_status(p_match uuid, p_status text) RETURNS void AS $$
  UPDATE match SET status = p_status WHERE id = p_match;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v114_request(p_match uuid, p_target text, p_by uuid) RETURNS uuid AS $$
  INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
  SELECT p_match, m.school_id, p_target, 'Verify 114: the ball was a dot', p_by FROM match m WHERE m.id = p_match
  RETURNING id;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v114_hold(p_match uuid, p_by uuid, p_resolve boolean) RETURNS void AS $$
BEGIN
  IF p_resolve THEN
    UPDATE ball_event_quarantine SET resolved_at = now(), resolution = 'rejected' WHERE match_id = p_match AND resolved_at IS NULL;
  ELSE
    INSERT INTO ball_event_quarantine (match_id, school_id, submitted_epoch, current_epoch, scorer_user_id, device_id,
                                       idempotency_key, body, fingerprint)
    SELECT p_match, m.school_id, 1, 2, p_by, 'v114-late', 'v114-late-' || p_match, '{}'::jsonb, md5('v114-late-' || p_match)
      FROM match m WHERE m.id = p_match;
  END IF;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A confirmation made eight days old, its window shut: the guard refuses any
-- change to a row, so it is set aside for one statement, as the owner, inside
-- the verify's own transaction (which rolls back).
CREATE OR REPLACE FUNCTION _v114_age(p_id uuid) RETURNS void AS $$
BEGIN
  ALTER TABLE match_result_confirmation DISABLE TRIGGER match_result_confirmation_guard;
  UPDATE match_result_confirmation SET confirmed_at = confirmed_at - interval '8 days',
         window_closes_at = now() - interval '1 minute' WHERE id = p_id;
  ALTER TABLE match_result_confirmation ENABLE TRIGGER match_result_confirmation_guard;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What was written, as the owner reads it (what RLS would not say).
CREATE OR REPLACE FUNCTION _v114_rows(p_match uuid) RETURNS jsonb AS $$
  SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.confirmed_at, c.id), '[]'::jsonb)
    FROM match_result_confirmation c WHERE c.match_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v114_notes(p_match uuid) RETURNS jsonb AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'school', n.school_id, 'team', n.team_code, 'scope', n.scope_level,
                                               'urgency', n.urgency, 'title', n.title, 'body', n.body, 'cap', n.required_capability,
                                               'retracted', n.retraction_kind, 'retracts', n.retracts_id, 'person', n.subject_person_id,
                                               'recipient', n.recipient_id,
                                               'live', n.expires_at > now())
                            ORDER BY n.published_at, n.id), '[]'::jsonb)
    FROM notification n WHERE n.subject_kind = 'match' AND n.subject_id = p_match AND n.kind = 'fixture'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Is this person a hand on the match's log (D5), as the owner asks it?
CREATE OR REPLACE FUNCTION _v114_hand(p_match uuid, p_user uuid) RETURNS text AS $$
  SELECT result_hand_on_log(p_match, p_user)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v114_fact(p_match uuid) RETURNS jsonb AS $$
  SELECT jsonb_build_object('head', match_head_seq(p_match),
                            'hash', (SELECT r.result_hash FROM match_result_compute(p_match) r),
                            'state', (SELECT o.state FROM match_official_core(p_match) o),
                            'verified', match_verified(p_match), 'seals', match_seals_stand(p_match))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/114 (section 91) ─────────────────────────────────────────────

-- ┌── db/115 (section 92). REACH R-B: a family's consents are the family's
-- Invented, as the owner; every name is a placeholder. Boys: A and M, team-
-- mates on Hilton's 18XI, each a pupil with his own `player` role and self-
-- access link, each with a guardian; B on Hilton's 19XI; W on Westville's
-- 18XI (the same team code at another school), with a guardian. A third
-- school X, on the platform with nobody at it. Passport consents: A → WES,
-- M → WES, A → X, and M → X withdrawn. Scouting decisions: A granted, M
-- withdrawn, B granted, W granted. The readers, one assignment each.
CREATE OR REPLACE FUNCTION _v115_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  X uuid; ids jsonb; v_a uuid; c_a uuid; c_m uuid; c_b uuid; c_w uuid; k text;
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V115X', 'Verify OneFifteen College', 'school', 'KwaZulu-Natal')
  RETURNING id INTO X;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '18XI', 'Verify OneFifteen Able',  1151, 'batter', U15) RETURNING id INTO c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '18XI', 'Verify OneFifteen Mate',  1152, 'bowler', U15) RETURNING id INTO c_m;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '19XI', 'Verify OneFifteen Other', 1153, 'batter', U15) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (WES, '18XI', 'Verify OneFifteen Wes',   1154, 'batter', U15) RETURNING id INTO c_w;
  ids := _v71_people('v115', ARRAY[
    ARRAY['ga',           'guardian',        HIL::text, '',     ''],   -- A's
    ARRAY['gm',           'guardian',        HIL::text, '',     ''],   -- M's
    ARRAY['aboy',         'player',          HIL::text, '18XI', c_a::text],
    ARRAY['mboy',         'player',          HIL::text, '18XI', c_m::text],
    ARRAY['coach18',      'coach',           HIL::text, '18XI', ''],
    ARRAY['asst18',       'assistantcoach',  HIL::text, '18XI', ''],
    ARRAY['manager18',    'teammanager',     HIL::text, '18XI', ''],
    ARRAY['coach19',      'coach',           HIL::text, '19XI', ''],
    ARRAY['dos',          'directorofsport', HIL::text, '',     ''],
    ARRAY['office',       'schooladmin',     HIL::text, '',     ''],
    ARRAY['principal',    'principal',       HIL::text, '',     ''],
    ARRAY['scorer',       'scorer',          HIL::text, '',     ''],
    ARRAY['medical',      'medical',         HIL::text, '',     ''],
    ARRAY['analyst',      'analyst',         HIL::text, '',     ''],
    ARRAY['scout',        'scout',           HIL::text, '',     ''],
    ARRAY['spec',         'spectator',       HIL::text, '',     ''],
    ARRAY['wesoffice',    'schooladmin',     WES::text, '',     ''],
    ARRAY['wesprincipal', 'principal',       WES::text, '',     ''],
    ARRAY['wescoach',     'coach',           WES::text, '18XI', ''],
    ARRAY['wesdos',       'directorofsport', WES::text, '',     ''],
    ARRAY['wesg',         'guardian',        WES::text, '',     ''],   -- W's: a parent at the receiving school
    ARRAY['wesmate',      'player',          WES::text, '18XI', '']]); -- W's team-mate, a pupil there
  PERFORM _v100_link((ids->>'ga')::uuid, HIL, c_a);
  PERFORM _v100_link((ids->>'gm')::uuid, HIL, c_m);
  PERFORM _v100_link((ids->>'wesg')::uuid, WES, c_w);
  -- Each pupil also holds self-access over his own record, as R Pillay does.
  FOREACH k IN ARRAY ARRAY['aboy', 'mboy'] LOOP
    INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>k)::uuid, 'selfaccess', HIL)
    RETURNING id INTO v_a;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (v_a, CASE k WHEN 'aboy' THEN c_a ELSE c_m END, 'self', 'verified', OFFICE, now(),
            'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  END LOOP;
  INSERT INTO passport_consent (player_id, to_school_id) VALUES (c_a, WES), (c_m, WES), (c_a, X), (c_m, X);
  -- Each given by the boy's guardian, as her grant stamps it: since db/122 a
  -- consent is in force only while the link of the person who gave it is live.
  UPDATE passport_consent SET granted_by = CASE player_id WHEN c_a THEN (ids->>'ga')::uuid ELSE (ids->>'gm')::uuid END
   WHERE player_id IN (c_a, c_m);
  UPDATE passport_consent SET withdrawn_at = now() WHERE player_id = c_m AND to_school_id = X;
  INSERT INTO player_scouting_consent (player_id, consent_state) VALUES
    (c_a, 'granted'), (c_m, 'withdrawn'), (c_b, 'granted'), (c_w, 'granted');
  RETURN ids || jsonb_build_object('A', c_a, 'M', c_m, 'B', c_b, 'W', c_w, 'X', X);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the CALLER reads of the staged rows, under his own row security (these
-- two are invoker functions, so the policies stand in front of them), as one
-- sorted line: a passport consent as boy>school, '(w)' when withdrawn; a
-- scouting decision as the boy, '(w)' when withdrawn.
CREATE OR REPLACE FUNCTION _v115_passport(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t), '') FROM (
    SELECT CASE c.player_id WHEN (y->>'A')::uuid THEN 'A' WHEN (y->>'M')::uuid THEN 'M' ELSE '?' END
           || '>' || CASE c.to_school_id WHEN '22222222-2222-2222-2222-222222222222'::uuid THEN 'WES'
                                         WHEN (y->>'X')::uuid THEN 'X' ELSE '?' END
           || CASE WHEN c.withdrawn_at IS NOT NULL THEN '(w)' ELSE '' END AS t
      FROM passport_consent c
     WHERE c.player_id IN ((y->>'A')::uuid, (y->>'M')::uuid, (y->>'B')::uuid, (y->>'W')::uuid)) s
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION _v115_scouting(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t), '') FROM (
    SELECT CASE c.player_id WHEN (y->>'A')::uuid THEN 'A' WHEN (y->>'M')::uuid THEN 'M'
                            WHEN (y->>'B')::uuid THEN 'B' WHEN (y->>'W')::uuid THEN 'W' END
           || CASE WHEN c.consent_state = 'withdrawn' THEN '(w)' ELSE '' END AS t
      FROM player_scouting_consent c
     WHERE c.player_id IN ((y->>'A')::uuid, (y->>'M')::uuid, (y->>'B')::uuid, (y->>'W')::uuid)) s
$$ LANGUAGE sql STABLE;
-- └── db/115 (section 92) ─────────────────────────────────────────────
-- ┌── db/116 (section 93). Who reads a child's data (READERS_child_data,
-- decided by Kameel on 21 Oct 2026). The world, as the owner:
--   Hilton boys on 16XI: d (departs, with an injury), h (on Hilton's sheet
--     at f), k (15XI, on no sheet), t (thirteen, his own account), y (eleven,
--     his own account), e (nineteen, at school, his own account);
--   Westville boys on 16XI: a (on Westville's sheet at f), p (a pupil who
--     scores Hilton's match f, fixture-scoped);
--   f: Hilton 16XI v Westville 16XI today, in competition C, which the
--     seed's league account (platform-wide) organises; g: Hilton 16XI in ten
--     days, in no competition;
--   the reasons Q2 keeps from audit.read: an account disabled, a role
--     ended, a ball amendment, a staff register row;
--   three conduct records: r1 on h at f, r2 on a at f, r3 on h at g;
--   two trips: today's on f, a later one on g, and a cancelled one on f;
--   emergency contacts for h and k; an honour for h.
CREATE OR REPLACE FUNCTION _v116_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  U_LEAGUE uuid := '88888888-0000-0000-0000-000000000021';
  yr  int := extract(year FROM sa_today())::int;
  ids jsonb; o jsonb := '{}'; v uuid; v_s uuid; v_c uuid; v_f uuid; v_g uuid; k text;
BEGIN
  PERFORM set_config('app.effective_on', '', true);
  -- The boys.
  FOREACH k IN ARRAY ARRAY['d', 'h', 'k', 't', 'y', 'e'] LOOP
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
    VALUES (HIL, CASE k WHEN 'k' THEN '15XI' ELSE '16XI' END, 'Verify OneSixteen ' || upper(k), 1160, 'batter',
            CASE k WHEN 'y' THEN make_date(yr - 11, 1, 1) WHEN 't' THEN make_date(yr - 13, 1, 1)
                   WHEN 'e' THEN make_date(yr - 19, 1, 1) ELSE make_date(yr - 15, 1, 1) END)
    RETURNING id INTO v;
    o := o || jsonb_build_object(k, v);
  END LOOP;
  FOREACH k IN ARRAY ARRAY['a', 'p'] LOOP
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
    VALUES (WES, '16XI', 'Verify OneSixteen ' || upper(k), 1161, 'batter', make_date(yr - 15, 1, 1))
    RETURNING id INTO v;
    o := o || jsonb_build_object(k, v);
  END LOOP;
  ids := _v71_people('v116', ARRAY[
    ARRAY['office',    'schooladmin',          HIL::text, '',     ''],
    ARRAY['head',      'principal',            HIL::text, '',     ''],
    ARRAY['dso',       'dso',                  HIL::text, '',     ''],
    ARRAY['wesdso',    'dso',                  WES::text, '',     ''],
    ARRAY['physio',    'medical',              HIL::text, '',     ''],
    ARRAY['coach',     'coach',                HIL::text, '16XI', ''],
    ARRAY['coach15',   'coach',                HIL::text, '15XI', ''],
    ARRAY['parent',    'guardian',             HIL::text, '',     ''],
    ARRAY['wesparent', 'guardian',             WES::text, '',     ''],
    ARRAY['coord',     'transportcoordinator', HIL::text, '',     ''],
    ARRAY['sports',    'sportsadmin',          HIL::text, '',     ''],
    ARRAY['wesleague', 'competitionadmin',     WES::text, '',     ''],
    ARRAY['wescoach',  'coach',                WES::text, '16XI', ''],
    ARRAY['scorer',    'scorer',               HIL::text, '',     ''],
    ARRAY['pupil',     'player',               WES::text, '16XI', o->>'p'],
    ARRAY['teen',      'player',               HIL::text, '16XI', o->>'t'],
    ARRAY['young',     'player',               HIL::text, '16XI', o->>'y'],
    ARRAY['adult',     'player',               HIL::text, '16XI', o->>'e']]);
  ids := ids || o;
  -- Links: the parent answers for d, h and t; the Westville parent for a and p.
  PERFORM _v100_link((ids->>'parent')::uuid, HIL, (ids->>'d')::uuid);
  PERFORM _v100_link((ids->>'parent')::uuid, HIL, (ids->>'h')::uuid);
  PERFORM _v100_link((ids->>'parent')::uuid, HIL, (ids->>'t')::uuid);
  PERFORM _v100_link((ids->>'wesparent')::uuid, WES, (ids->>'a')::uuid);
  PERFORM _v100_link((ids->>'wesparent')::uuid, WES, (ids->>'p')::uuid);
  -- Each pupil with an account reads his own record through a self link.
  FOREACH k IN ARRAY ARRAY['teen:t', 'young:y', 'adult:e'] LOOP
    INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>split_part(k, ':', 1))::uuid, 'selfaccess', HIL)
    RETURNING id INTO v_s;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from)
    VALUES (v_s, (ids->>split_part(k, ':', 2))::uuid, 'self', 'verified', '88888888-0000-0000-0000-00000000000c', now(),
            'granted', 'popia-2026-01', now(), '88888888-0000-0000-0000-00000000000c', current_date - 1);
  END LOOP;

  -- The competition, its fixture, and one in no competition.
  INSERT INTO competition (school_id, name, comp_type, format, age_group, gender, level, season_id)
  VALUES (NULL, 'Verify OneSixteen League', 'league', 'T20', '1XI', 'boys', 'school', season_named('2026', 'school'))
  RETURNING id INTO v_c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES
    (v_c, HIL, '16XI', 'Hilton 16'), (v_c, WES, '16XI', 'Westville 16');
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
  VALUES (HIL, '16XI', WES, '16XI', 'Verify OneSixteen Westville', (sa_today()::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled', v_c)
  RETURNING id INTO v_f;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '16XI', 'Verify OneSixteen Elsewhere', (sa_today()::timestamp + interval '10 days' + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled')
  RETURNING id INTO v_g;
  ids := ids || jsonb_build_object('c', v_c, 'f', v_f, 'g', v_g);
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    (v_f, (ids->>'h')::uuid, 'home', 1), (v_f, (ids->>'a')::uuid, 'away', 1);
  -- The pupil scores Hilton's match f, and an adult the same match.
  INSERT INTO role_assignment (person_id, role, school_id, fixture_id) VALUES ((ids->>'pupil')::uuid, 'scorer', HIL, v_f);
  UPDATE role_assignment SET fixture_id = v_f WHERE person_id = (ids->>'scorer')::uuid AND role = 'scorer';

  -- Q2: the reasons.
  INSERT INTO account_status_change (user_id, school_id, active, reason, changed_by)
  VALUES ((ids->>'coach')::uuid, HIL, false, 'v116: disabled while a complaint is heard', (ids->>'office')::uuid)
  RETURNING id INTO v; ids := ids || jsonb_build_object('status', v);
  INSERT INTO role_assignment (person_id, role, school_id, team_code, active, revoked_at)
  VALUES ((ids->>'coach')::uuid, 'teammanager', HIL, '16XI', false, now()) RETURNING id INTO v;
  INSERT INTO role_assignment_ending (assignment_id, person_id, role, school_id, team_code, reason, ended_by)
  VALUES (v, (ids->>'coach')::uuid, 'teammanager', HIL, '16XI', 'v116: ended after a disciplinary hearing', (ids->>'office')::uuid);
  ids := ids || jsonb_build_object('ended', v);
  INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
  VALUES (v_f, HIL, 'v116-target', 'v116: four runs to the wrong batter', (ids->>'scorer')::uuid)
  RETURNING id INTO v; ids := ids || jsonb_build_object('amend', v);
  INSERT INTO school_register (school_id, email, name, role, team_code, valid_until, uploaded_by, upload_id)
  VALUES (HIL, 'v116.listed@example.invalid', 'V116 Listed', 'coach', '16XI', current_date + 30,
          (ids->>'office')::uuid, gen_random_uuid())
  RETURNING id INTO v; ids := ids || jsonb_build_object('register', v);

  -- Q3: d's injury.
  INSERT INTO injury (school_id, player_id, injury_type, severity, date_injured, phase, notes)
  VALUES (HIL, (ids->>'d')::uuid, 'Verify OneSixteen hamstring', 'moderate', current_date - 3, 'rehab', 'v116 clinical note')
  RETURNING id INTO v; ids := ids || jsonb_build_object('injury', v);
  -- ...and the physio's review of it (db/111), with her clinical note.
  INSERT INTO injury_review (school_id, player_id, injury_id, reviewed_by, phase_after, restricted_after,
                             next_review_on, note)
  VALUES (HIL, (ids->>'d')::uuid, v, (ids->>'physio')::uuid, 'rehab', true, current_date + 7, 'v116 review note')
  RETURNING id INTO v; ids := ids || jsonb_build_object('review', v);

  -- Q10: the conduct records, as the umpire would file them (the author is the session's).
  PERFORM set_config('app.user_id', (ids->>'head')::text, true);
  INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
  VALUES ((ids->>'h')::uuid, HIL, v_f, (ids->>'head')::uuid, 'v116: dissent at f') RETURNING id INTO v;
  ids := ids || jsonb_build_object('r1', v);
  INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
  VALUES ((ids->>'a')::uuid, WES, v_f, (ids->>'head')::uuid, 'v116: dissent at f, the other side') RETURNING id INTO v;
  ids := ids || jsonb_build_object('r2', v);
  INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
  VALUES ((ids->>'h')::uuid, HIL, v_g, (ids->>'head')::uuid, 'v116: at a match in no competition') RETURNING id INTO v;
  ids := ids || jsonb_build_object('r3', v);
  PERFORM set_config('app.user_id', '', true);

  -- Q12: the trips and the numbers.
  INSERT INTO trip (match_id, school_id, depart_at, return_at, pickup)
  VALUES (v_f, HIL, now() - interval '1 hour', now() + interval '1 hour', 'v116: today') RETURNING id INTO v;
  ids := ids || jsonb_build_object('trip_today', v);
  INSERT INTO trip (match_id, school_id, depart_at, pickup)
  VALUES (v_g, HIL, (sa_today()::timestamp + interval '10 days' + time '08:00') AT TIME ZONE 'Africa/Johannesburg', 'v116: later')
  RETURNING id INTO v; ids := ids || jsonb_build_object('trip_later', v);
  INSERT INTO trip (match_id, school_id, depart_at, pickup, cancelled_at)
  VALUES (v_f, HIL, now() - interval '1 hour', 'v116: cancelled', now()) RETURNING id INTO v;
  ids := ids || jsonb_build_object('trip_cancelled', v);
  INSERT INTO emergency_contact (player_id, priority, name, relationship, phone)
  VALUES ((ids->>'h')::uuid, 1, 'V116 Mother', 'mother', '+27 82 116 0001'),
         ((ids->>'k')::uuid, 1, 'V116 Father', 'father', '+27 82 116 0002');

  -- Q13: what a fixture-scoped read would have reached.
  INSERT INTO honour (player_id, school_id, team_code, kind, season_id)
  VALUES ((ids->>'h')::uuid, HIL, '16XI', 'captain', (SELECT s.id FROM season_for(sa_today(), 'school') s LIMIT 1));

  -- Q16: t's ID number on file (13 digits; the format is the only rule).
  UPDATE player SET id_number = to_char(make_date(yr - 13, 1, 1), 'YYMMDD') || '5116084' WHERE id = (ids->>'t')::uuid;

  -- A1: his coach's rating of him, and his family's consent naming Westville.
  INSERT INTO player_skill (player_id, assessed_on, assessed_by, category, metric, score)
  VALUES ((ids->>'h')::uuid, current_date - 5, (ids->>'coach')::uuid, 'technical', 'againstPace', 11);
  INSERT INTO passport_consent (player_id, to_school_id, granted_by)
  VALUES ((ids->>'h')::uuid, WES, (ids->>'parent')::uuid);
  -- db/08's trigger stamps the giver from the session (nobody, here): his
  -- parent, as her grant would (db/122: a consent with no giver opens nothing).
  UPDATE passport_consent SET granted_by = (ids->>'parent')::uuid WHERE player_id = (ids->>'h')::uuid AND to_school_id = WES;
  RETURN ids;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Move a boy as the office's move route would (the membership trigger closes
-- and opens his rows), as the owner, dated today.
CREATE OR REPLACE FUNCTION _v116_move(p_player uuid, p_team text) RETURNS void AS $$
BEGIN
  PERFORM set_config('app.effective_on', '', true);
  UPDATE player SET team_code = p_team WHERE id = p_player;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Facts the reader may not see, as the owner.
CREATE OR REPLACE FUNCTION _v116_fact(p_what text, p_a uuid DEFAULT NULL, p_b uuid DEFAULT NULL) RETURNS text AS $$
  SELECT CASE p_what
    -- How many access_log rows a person wrote under a resource at a school, and whom they named.
    WHEN 'logged' THEN (SELECT count(*)::text || ':' || coalesce(string_agg(DISTINCT x::text, ',' ORDER BY x::text), '')
                          FROM access_log l LEFT JOIN LATERAL unnest(l.record_ids) x ON true
                         WHERE l.person_id = p_a AND l.school_id = p_b AND l.resource = 'competition_discipline_records')
    WHEN 'side_logged' THEN (SELECT count(*)::text FROM access_log l
                              WHERE l.person_id = p_a AND l.resource = 'side_discipline_records' AND p_b = ANY (l.record_ids))
    -- Where a person's latest concern went: its holder, its school, its child.
    WHEN 'concern_of' THEN (SELECT c.tenant_id::text || ':' || c.school_id::text || ':' || coalesce(c.subject_player_id::text, '-')
                              FROM safeguarding_concern c
                              JOIN safeguarding_concern_reporter r ON r.concern_id = c.id
                             WHERE r.reporter_id = p_a ORDER BY c.raised_at DESC LIMIT 1)
    -- The notice the reporter's own school was given: its words.
    WHEN 'told' THEN (SELECT n.title || ' | ' || n.body || ' | ' || n.required_capability
                        FROM notification n WHERE n.school_id = p_a AND n.kind = 'safeguarding'
                         AND n.title = 'A concern raised about a child at another school'
                       ORDER BY n.published_at DESC LIMIT 1)
    -- A notice's life, in days.
    WHEN 'life' THEN (SELECT extract(day FROM (n.expires_at - n.published_at))::int::text
                        FROM notification n WHERE n.recipient_id = p_a AND n.kind = 'compromise'
                       ORDER BY n.published_at DESC LIMIT 1)
  END
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A notice of any kind to one person, as the system writes one: 'ok', or the
-- SQLSTATE and the constraint that refused it.
CREATE OR REPLACE FUNCTION _v116_notice(p_person uuid, p_kind text) RETURNS text AS $$
DECLARE v_con text;
BEGIN
  INSERT INTO notification (school_id, scope_level, kind, urgency, title, body, required_capability, recipient_id)
  VALUES ('11111111-1111-1111-1111-111111111111', 'school', p_kind, 'medium', 'Verify 116', 'Verify 116', 'news.read', p_person);
  RETURN 'ok';
EXCEPTION WHEN check_violation THEN
  GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
  RETURN '23514:' || coalesce(nullif(v_con, ''), 'trigger');
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/116 (section 93) ─────────────────────────────────────────────
-- ┌── db/117 (section 94). The dated side: a family keeps the season of the
-- side a boy was on (SR-2), and the move voids his seats on it (SR-4).
-- Invented, as the owner; every name a placeholder. Hilton's 15XI, 19XI and
-- 14XI; the labels call them 41, 42 and 43 (f41a is a 15XI fixture, f42a a
-- 19XI one, f43a a 14XI one), and so do the readers (coach41, coach42). Boys: A (14XI from t-90, 15XI from t-60; the section moves him to the
-- 19XI from t-10: three membership rows), C (joined the 19XI at t-10: the
-- newcomer), M (15XI from t-60, never moved). t is today. Fixtures, by day:
-- f43a (14XI, t-100: before A's first row), f43b (14XI, t-75), f41a (15XI,
-- t-30), f41w (Westville's 15XI v Hilton's 15XI at Westville, t-25), f41d and
-- f42d (each side's on t-10, the move's own day), f42a (19XI, t-30), f41n and
-- f42n (t+5), f41s (15XI, t+12, A on its home sheet). Buses to f41a, f41n,
-- f42a. Nets s41a, s42a (t-30), s42d (t-10), s41n, s42n (t+3). Posts: team
-- posts n41a, n42a (published t-30), n41n, n42n (published now); plans p41a
-- (f41a's) and p41n (f41n's). Balls on f41a (6), f42a (12), f41n (18). A lift
-- driven by M's mother to f41n with seats for A (asked by A's mother) and M,
-- and one to f41s with a seat for A.
CREATE OR REPLACE FUNCTION _v117_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  t date := sa_today();
  -- The office's move is a person's write, so it may not reach before this
  -- season's start (db/117's floor): t-10, or the season's start if that is
  -- later (1 to 10 January). Every row "on the move's day" follows it.
  M date := greatest((SELECT s.starts_on FROM season_for(sa_today(), 'school') s), t - 10);
  -- A day after the move's day and already past, for the past lift: t-5,
  -- else yesterday, else (1 or 2 January: no such day) the move's day.
  P date;
  ids jsonb; z jsonb := '{}'; v_id uuid; v_a uuid; v_d uuid; v_o uuid; l record;
  c_a uuid; c_c uuid; c_m uuid;
  k text; tm text; dd int; aw boolean;
BEGIN
  P := CASE WHEN t - 5 > M THEN t - 5 WHEN t - 1 > M THEN t - 1 ELSE M END;
  -- A: 14XI from t-90, then 15XI from t-60, each dated as the move route dates it.
  PERFORM set_config('app.effective_on', (t - 90)::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '14XI', 'Verify OneOneSeven Mover', 1171, 'batter', U15) RETURNING id INTO c_a;
  PERFORM set_config('app.effective_on', (t - 60)::text, true);
  UPDATE player SET team_code = '15XI' WHERE id = c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '15XI', 'Verify OneOneSeven Stayer', 1172, 'batter', U15) RETURNING id INTO c_m;
  PERFORM set_config('app.effective_on', (t - 10)::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '19XI', 'Verify OneOneSeven Newcomer', 1173, 'batter', U15) RETURNING id INTO c_c;
  PERFORM set_config('app.effective_on', '', true);
  ids := _v71_people('v117', ARRAY[
    ARRAY['g',       'guardian',    HIL::text, '',     ''],     -- A's mother
    ARRAY['gc',      'guardian',    HIL::text, '',     ''],     -- C's, the newcomer's
    ARRAY['gm',      'guardian',    HIL::text, '',     ''],     -- M's, and the lift's driver
    ARRAY['aboy',    'player',      HIL::text, '15XI', c_a::text],
    ARRAY['mboy',    'player',      HIL::text, '15XI', c_m::text],   -- M himself: a team-mate who never moved
    ARRAY['cboy',    'player',      HIL::text, '19XI', c_c::text],   -- C himself: joined the 19XI at t-10
    ARRAY['coach41', 'coach',       HIL::text, '15XI', ''],
    ARRAY['coach42', 'coach',       HIL::text, '19XI', ''],
    ARRAY['spec',    'spectator',   HIL::text, '',     ''],
    ARRAY['office',  'schooladmin', HIL::text, '',     '']]);
  PERFORM _v100_link((ids->>'g')::uuid, HIL, c_a);
  PERFORM _v100_link((ids->>'gc')::uuid, HIL, c_c);
  PERFORM _v100_link((ids->>'gm')::uuid, HIL, c_m);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'aboy')::uuid, 'selfaccess', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, c_a, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  z := jsonb_build_object('a', c_a, 'c', c_c, 'm', c_m);
  -- The fixtures, each at 10:00 in Johannesburg on its day.
  FOR k, tm, dd, aw IN SELECT * FROM (VALUES
      ('f43a', '14XI', -100, false), ('f43b', '14XI', -75, false), ('f41a', '15XI', -30, false),
      ('f41w', '15XI', -25, true),   ('f41d', '15XI', M - t, false), ('f42d', '19XI', M - t, false),
      ('f42a', '19XI', -30, false),  ('f41n', '15XI', 5, false),   ('f42n', '19XI', 5, false),
      ('f41s', '15XI', 12, false)) x LOOP
    IF aw THEN
      INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
      VALUES (WES, tm, HIL, tm, 'Verify OneOneSeven Hilton', ((t + dd)::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
              'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
    ELSE
      INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
      VALUES (HIL, tm, 'Verify OneOneSeven ' || k, ((t + dd)::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
              'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
    END IF;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES ((z->>'f41s')::uuid, c_a, 'home', 1);
  PERFORM _v71_bowl((z->>'f41a')::uuid, OFFICE, ARRAY[NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f42a')::uuid, OFFICE, ARRAY[NULL, NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f41n')::uuid, OFFICE, ARRAY[NULL, NULL, NULL]::uuid[]);
  FOR k IN SELECT unnest(ARRAY['f41a', 'f41n', 'f42a']) LOOP
    INSERT INTO trip (match_id, school_id, pickup, notes) VALUES ((z->>k)::uuid, HIL, 'V117 gate', 'V117 bus to ' || k)
    RETURNING id INTO v_id;
    z := z || jsonb_build_object('t' || substr(k, 2), v_id);
  END LOOP;
  FOR k, tm, dd IN SELECT * FROM (VALUES ('s41a', '15XI', -30), ('s42a', '19XI', -30), ('s42d', '19XI', M - t),
                                         ('s41n', '15XI', 3), ('s42n', '19XI', 3)) x LOOP
    INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type)
    VALUES (HIL, tm, 'V117 ' || k, ((t + dd)::timestamp + time '15:00') AT TIME ZONE 'Africa/Johannesburg', 60, 'batting')
    RETURNING id INTO v_id;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  FOR k, tm, dd IN SELECT * FROM (VALUES ('n41a', '15XI', -30), ('n42a', '19XI', -30), ('n41n', '15XI', 0), ('n42n', '19XI', 0)) x LOOP
    INSERT INTO news_post (scope, school_id, team_code, kind, title, body, published_at, author_id)
    VALUES ('team', HIL, tm, 'post', 'V117 ' || k, 'V117 a word to the side',
            CASE WHEN dd = 0 THEN now() - interval '1 minute' ELSE ((t + dd)::timestamp + time '12:00') AT TIME ZONE 'Africa/Johannesburg' END,
            (ids->>(CASE tm WHEN '15XI' THEN 'coach41' ELSE 'coach42' END))::uuid)
    RETURNING id INTO v_id;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, '15XI', 'plan', (z->>'f41a')::uuid, 'V117 p41a', 'V117 meet at the nets',
          ((t - 31)::timestamp + time '12:00') AT TIME ZONE 'Africa/Johannesburg', (ids->>'coach41')::uuid) RETURNING id INTO v_id;
  z := z || jsonb_build_object('p41a', v_id);
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, '15XI', 'plan', (z->>'f41n')::uuid, 'V117 p41n', 'V117 meet at the pavilion',
          now() - interval '1 minute', (ids->>'coach41')::uuid) RETURNING id INTO v_id;
  z := z || jsonb_build_object('p41n', v_id);
  -- Two plans that are not out: d41a for f41a never sent (a draft), w41a
  -- for f41w (the away end is his side's) sent and withdrawn (db/91's withdraw sets published_at back to null;
  -- db/110 keeps first_sent_at). Both dated inside A's time on the 15XI, and
  -- both written as their author: the database stamps a draft's author from
  -- the person signed in.
  PERFORM set_config('app.user_id', ids->>'coach41', true);
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, '15XI', 'plan', (z->>'f41a')::uuid, 'V117 d41a', 'V117 a draft', NULL, (ids->>'coach41')::uuid)
  RETURNING id INTO v_id;
  z := z || jsonb_build_object('d41a', v_id);
  -- Sent and withdrawn by its author, as db/91's doors do it (a person's acts).
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, '15XI', 'plan', (z->>'f41w')::uuid, 'V117 w41a', 'V117 withdrawn',
          ((t - 27)::timestamp + time '12:00') AT TIME ZONE 'Africa/Johannesburg', (ids->>'coach41')::uuid) RETURNING id INTO v_id;
  UPDATE news_post SET published_at = NULL WHERE id = v_id;
  PERFORM set_config('app.user_id', '', true);
  z := z || jsonb_build_object('w41a', v_id);
  -- A 15XI fixture already played, after the move's day (P): its lift's
  -- seat for A stays as it was (a backdated move does not rewrite the past).
  -- Labelled x41p, so the read strings above do not carry it.
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '15XI', 'Verify OneOneSeven x41p', (P::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
  z := z || jsonb_build_object('x41p', v_id);
  -- The lifts: M's mother drives to f41n (A's seat, asked by A's mother, and
  -- M's), to f41s (A's seat: he is on its sheet) and to x41p (past).
  INSERT INTO lift_driver_declaration (person_id, school_id, vehicle_description, registration, seats, licence_held,
                                       insured, roadworthy, belts, code_acknowledged, policy_version, expires_on)
  VALUES ((ids->>'gm')::uuid, HIL, 'V117 blue estate', 'V117 GP', 3, true, true, true, true, true, 1, current_date + 300)
  RETURNING id INTO v_d;
  FOR k IN SELECT unnest(ARRAY['f41n', 'f41s', 'x41p']) LOOP
    INSERT INTO lift_offer (school_id, match_id, team_code, leg, driver_id, declaration_id, seats, meet_kind, meet_at, fixture_starts_at)
    SELECT HIL, m.id, '15XI', 'out', (ids->>'gm')::uuid, v_d, 3, 'school', m.starts_at - interval '90 minutes', m.starts_at
      FROM match m WHERE m.id = (z->>k)::uuid
    RETURNING id INTO v_o;
    z := z || jsonb_build_object('o' || substr(k, 2), v_o);
    SELECT g.assignment_id, g.id INTO l FROM assignment_subject g JOIN role_assignment a ON a.id = g.assignment_id
     WHERE a.person_id = (ids->>'g')::uuid AND g.player_id = c_a;
    INSERT INTO lift_seat (offer_id, school_id, match_id, team_code, leg, player_id, consent_by, guardian_assignment_id,
                           guardian_link_id, requested_by, state)
    VALUES (v_o, NULL, NULL, NULL, NULL, c_a, 'guardian', l.assignment_id, l.id, (ids->>'g')::uuid, 'requested')
    RETURNING id INTO v_id;
    z := z || jsonb_build_object('seat_a_' || substr(k, 2), v_id);
  END LOOP;
  SELECT g.assignment_id, g.id INTO l FROM assignment_subject g JOIN role_assignment a ON a.id = g.assignment_id
   WHERE a.person_id = (ids->>'gm')::uuid AND g.player_id = c_m;
  INSERT INTO lift_seat (offer_id, school_id, match_id, team_code, leg, player_id, consent_by, guardian_assignment_id,
                         guardian_link_id, requested_by, state)
  VALUES ((z->>'o41n')::uuid, NULL, NULL, NULL, NULL, c_m, 'guardian', l.assignment_id, l.id, (ids->>'gm')::uuid, 'requested')
  RETURNING id INTO v_id;
  z := z || jsonb_build_object('seat_m_41n', v_id, 'day_move', M::text);
  RETURN ids || z;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the caller reads of the stage, under his own row security: each
-- table by the stage's labels, sorted. Each table is asked for the stage's ids
-- as `= ANY (array of uuid)`: that comparison is leakproof, so the planner may
-- probe the index under the table's row security rather than run the policy
-- over every row (by §94, every earlier section's rows: 5,000 balls). The
-- answer is the same; only the plan changes.
CREATE OR REPLACE FUNCTION _v117_reads(z jsonb) RETURNS text AS $$
  SELECT format('fixtures [%s] trips [%s] training [%s] posts [%s] balls [%s]',
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, m.id) l FROM match m
       WHERE m.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^f4'))) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, v.id) l FROM trip v
       WHERE v.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^t4'))) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, s.id) l FROM training_session s
       WHERE s.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^s4'))) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, n.id) l FROM news_post n
       WHERE n.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^[np]4'))) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT DISTINCT _v106_label(z, b.match_id) l FROM ball_event b
       WHERE b.match_id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^f4'))) x))
$$ LANGUAGE sql STABLE;

-- §2.10's rule, spelled out apart from the build, with side_on(): every boy
-- who was on the side on the row's day (not only the boys the caller's links
-- name), and the boy himself (spelled apart from my_own_boy()) asked at his
-- own side. As the owner, about the caller app.user_id names.
CREATE OR REPLACE FUNCTION _v117_self(p_player uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM app_user u WHERE u.id = app_user_id() AND u.player_id = p_player)
      OR EXISTS (SELECT 1 FROM role_assignment a JOIN assignment_subject g ON g.assignment_id = a.id
                  WHERE a.person_id = app_user_id() AND a.role = 'selfaccess' AND a.active
                    AND (a.valid_from IS NULL OR a.valid_from <= current_date)
                    AND (a.valid_until IS NULL OR a.valid_until > current_date)
                    AND (a.expires_at IS NULL OR a.expires_at > now())
                    AND g.player_id = p_player AND g.verification_state = 'verified'
                    AND g.valid_from <= current_date AND (g.valid_until IS NULL OR g.valid_until > current_date))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The boys asked are those with any membership row on the side at the school
-- (the join): side_on() still decides the day, and a boy never on the side
-- answers nothing from it, so the answer is the same as asking every boy at
-- the school; it only spares side_on() for the rest (by §94, some 130 boys
-- at Hilton for every fixture and session asked).
-- Branch (1) since db/129: as before, except a pupil's own `player` row at
-- the side reads it only on a day his boy was on it (a reader with no boy at
-- the school is not dated; another assignment's reach stands).
CREATE OR REPLACE FUNCTION _v117_lit_side(p_cap text, p_school uuid, p_team text, p_fixture uuid, p_on date) RETURNS boolean AS $$
  SELECT (app_can(p_cap, p_school, p_team, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, p_fixture)
          AND (NOT EXISTS (SELECT 1 FROM role_assignment a
                            WHERE a.person_id = app_user_id() AND a.role = 'player' AND a.active
                              AND a.school_id = p_school AND a.team_code = p_team)
               OR NOT EXISTS (SELECT 1 FROM player p WHERE p.school_id = p_school AND _v117_self(p.id))
               OR EXISTS (SELECT 1 FROM player p
                            JOIN team_membership tm ON tm.player_id = p.id AND tm.school_id = p_school
                                                   AND tm.team_code = p_team AND tm.sport = 'cricket'
                           WHERE p.school_id = p_school AND _v117_self(p.id)
                             AND tm.joined_on <= p_on AND (tm.left_on IS NULL OR tm.left_on >= p_on))
               OR app_can_but_player(p_cap, p_school, p_team, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, p_fixture)))
      OR EXISTS (SELECT 1 FROM player p
                   JOIN (SELECT DISTINCT tm.player_id FROM team_membership tm
                          WHERE tm.school_id = p_school AND tm.team_code = p_team) c ON c.player_id = p.id
                  WHERE p.school_id = p_school AND p_team IN (SELECT side_on(p.id, p_school, p_on))
                    AND app_can(p_cap, p_school, p_team, p.id, p_fixture))
      OR EXISTS (SELECT 1 FROM player p
                   JOIN (SELECT DISTINCT tm.player_id FROM team_membership tm
                          WHERE tm.school_id = p_school AND tm.team_code = p_team) c ON c.player_id = p.id
                  WHERE p.school_id = p_school AND p_team IN (SELECT side_on(p.id, p_school, p_on))
                    AND _v117_self(p.id) AND app_can(p_cap, p.school_id, p.team_code, p.id, p_fixture))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v117_lit_fixture(p_cap text, p_match uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM match m WHERE m.id = p_match AND (
       _v117_lit_side(p_cap, m.school_id, m.team_code, m.id, sa_date(m.starts_at))
    OR (m.away_school_id IS NOT NULL AND _v117_lit_side(p_cap, m.away_school_id, m.away_team_code, m.id, sa_date(m.starts_at)))
    OR EXISTS (SELECT 1 FROM match_squad ms JOIN player p ON p.id = ms.player_id
                WHERE ms.match_id = m.id AND NOT ms.withdrawn
                  AND p.school_id = CASE WHEN ms.side = 'away' THEN m.away_school_id ELSE m.school_id END
                  AND app_can(p_cap,
                              CASE WHEN ms.side = 'away' THEN m.away_school_id ELSE m.school_id END,
                              CASE WHEN ms.side = 'away' THEN m.away_team_code ELSE m.team_code END,
                              ms.player_id, m.id))
    OR _v106_self_sheet(p_cap, m.id)))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Facts, as the owner.
CREATE OR REPLACE FUNCTION _v117_fact(p_what text, p_id uuid DEFAULT NULL) RETURNS text AS $$
  SELECT CASE p_what
    -- a boy's membership rows, oldest first, days from today: "14XI:-90..-60"
    WHEN 'rows' THEN (SELECT string_agg(format('%s:%s..%s', team_code, joined_on - sa_today(), coalesce((left_on - sa_today())::text, '')),
                                        ' ' ORDER BY joined_on, coalesce(left_on, 'infinity'::date), id)
                        FROM team_membership WHERE player_id = p_id)
    -- a boy's school now
    WHEN 'school' THEN (SELECT school_id::text FROM player WHERE id = p_id)
    -- a seat's state, and who ended it
    WHEN 'seat' THEN (SELECT state || ':' || coalesce(ended_by::text, '-') FROM lift_seat WHERE id = p_id)
    -- lift notices to one person: their titles, sorted
    WHEN 'lift_notices' THEN (SELECT coalesce(string_agg(title, ' / ' ORDER BY title), '')
                                FROM notification WHERE recipient_id = p_id AND kind IN ('lift', 'system') AND subject_kind = 'match')
    -- everything about a boy that is not about a side: his links and his consents
    WHEN 'about_him' THEN (SELECT md5(concat(
                             (SELECT string_agg(concat_ws('|', g.id, g.assignment_id, g.verification_state, g.valid_from, g.valid_until,
                                                          g.consent_state, g.consent_version), ';' ORDER BY g.id)
                                FROM assignment_subject g WHERE g.player_id = p_id),
                             (SELECT string_agg(to_jsonb(c)::text, ';' ORDER BY c.id) FROM public_name_consent c WHERE c.player_id = p_id),
                             (SELECT string_agg(to_jsonb(c)::text, ';' ORDER BY c.id) FROM health_monitoring_consent c WHERE c.player_id = p_id))))
  END
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Every session and every team post, with its day, as the owner.
CREATE OR REPLACE FUNCTION _v117_sessions() RETURNS TABLE (id uuid, school_id uuid, team_code text, day date) AS $$
  SELECT id, school_id, team_code, sa_date(starts_at) FROM training_session
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A boy written by the owner with nobody signed in, dated (the seed's way).
CREATE OR REPLACE FUNCTION _v117_owner_joins(p_on date) RETURNS uuid AS $$
DECLARE v uuid; v_user text := current_setting('app.user_id', true);
BEGIN
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.effective_on', p_on::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
  VALUES ('11111111-1111-1111-1111-111111111111', '15XI', 'Verify OneOneSeven Seeded', 1179, 'batter',
          make_date(extract(year FROM sa_today())::int - 15, 3, 1)) RETURNING id INTO v;
  PERFORM set_config('app.effective_on', '', true);
  PERFORM set_config('app.user_id', coalesce(v_user, ''), true);
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- What player_leave() will do to his roles at the school he leaves
-- (ACCOUNT_LIFECYCLE; not built): end his own live `player` roles there.
CREATE OR REPLACE FUNCTION _v117_end_player_roles(p_person uuid, p_school uuid) RETURNS void AS $$
  UPDATE role_assignment SET active = false
   WHERE person_id = p_person AND school_id = p_school AND role = 'player' AND active
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A move to another school (answer 2, Kameel 22 Oct 2026), dated, as the
-- owner: the office of one school cannot write a boy into another.
CREATE OR REPLACE FUNCTION _v117_move_school(p_player uuid, p_school uuid, p_team text, p_on date) RETURNS void AS $$
BEGIN
  PERFORM set_config('app.effective_on', p_on::text, true);
  UPDATE player SET school_id = p_school, team_code = p_team WHERE id = p_player;
  PERFORM set_config('app.effective_on', '', true);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v117_posts() RETURNS TABLE (id uuid, school uuid, team text, day date) AS $$
  SELECT n.id, n.school_id, n.team_code, news_post_day(n.kind, n.fixture_id, n.published_at)
    FROM news_post n WHERE n.scope = 'team'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The people §94 (literal) and (shape) ask, by a set rule rather than every
-- person the file has staged by then (some 430 at §94, which made the two
-- loops the bulk of the whole verify's time). Read as the owner:
--   (a) everyone this section stages (the moved boy, his mother, the
--       newcomer's and the stayer's families and the boys themselves, both
--       coaches, the spectator, the office);
--   (b) one holder of every class of live assignment the stage holds none
--       of, a class being its role and whether it names a boy: a seed account
--       where one holds it, else the lowest id (so with (a) every role is
--       asked, by both branches (1) and (2));
--   (c) everyone whose live assignment names, or whose own account is, a boy
--       with a dated history (more than one membership row, or a closed one:
--       a boy whose side a day can change, from any section) on a side one of
--       the compared fixtures belongs to (_v117_dated_on_rows(): the stage's
--       and the seed's), so a person whose answer on those rows a day can
--       change.
-- Everyone else holds assignments of a class (b) already asks, about boys
-- whose side on the compared rows no day changes; §83 and §89 ask every
-- person the same policy-against-helper questions under db/117's live
-- definitions.
CREATE OR REPLACE FUNCTION _v117_dated_on_rows(z jsonb) RETURNS uuid[] AS $$
  WITH rx AS (SELECT m.school_id AS s, m.team_code AS t FROM match m
               WHERE m.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^f4') || _v106_seed_matches())
              UNION
              SELECT m.away_school_id, m.away_team_code FROM match m
               WHERE m.away_school_id IS NOT NULL
                 AND m.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^f4') || _v106_seed_matches())),
       dated AS (SELECT m.player_id FROM team_membership m GROUP BY m.player_id
                  HAVING count(*) > 1 OR bool_or(m.left_on IS NOT NULL))
  SELECT coalesce(array_agg(DISTINCT m.player_id), '{}') FROM team_membership m JOIN rx ON rx.s = m.school_id AND rx.t = m.team_code
   WHERE m.player_id IN (SELECT player_id FROM dated)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION _v117_people(z jsonb) RETURNS uuid[] AS $$
  WITH a AS (SELECT r.id, r.person_id, r.role,
                    EXISTS (SELECT 1 FROM assignment_subject g WHERE g.assignment_id = r.id) AS named
               FROM role_assignment r WHERE r.active),
       dated AS (SELECT unnest(_v117_dated_on_rows(z)) AS player_id)
  SELECT coalesce(array_agg(p ORDER BY p), '{}') FROM (
    SELECT a.person_id AS p FROM a WHERE a.person_id IN (SELECT value::uuid FROM jsonb_each_text(z)
                                                          WHERE value ~ '^[0-9a-f]{8}-[0-9a-f]{4}-')
    UNION
    (SELECT DISTINCT ON (a.role, a.named) a.person_id FROM a
      WHERE (a.role, a.named) NOT IN (SELECT s.role, s.named FROM a s
                                       WHERE s.person_id IN (SELECT value::uuid FROM jsonb_each_text(z)
                                                              WHERE value ~ '^[0-9a-f]{8}-[0-9a-f]{4}-'))
      ORDER BY a.role, a.named, (a.person_id::text NOT LIKE '88888888-%'), a.person_id::text)
    UNION
    SELECT a.person_id FROM a JOIN assignment_subject g ON g.assignment_id = a.id
     WHERE g.player_id IN (SELECT player_id FROM dated)
    UNION
    SELECT u.id FROM app_user u WHERE u.player_id IN (SELECT player_id FROM dated) AND u.id IN (SELECT person_id FROM a)
  ) x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Fresh planner statistics at §94's start, after its stage. The verify is one transaction,
-- so the tables hold every earlier section's rows (5,000 balls, 190 fixtures,
-- 430 people) on statistics last gathered at the seed; the loops' plans,
-- built on those, cost about five times what the same loops cost on the same
-- rows analysed (measured 28 Oct 2026). ANALYZE counts this transaction's
-- own rows, and its statistics roll back with everything else at the end.
-- It changes no answer, only the plans. The owner's: scrbrd_app may not.
CREATE OR REPLACE FUNCTION _v117_fresh_stats() RETURNS void AS $$
BEGIN
  ANALYZE match, match_squad, player, team_membership, role_assignment, assignment_subject, app_user,
          ball_event, trip, training_session, news_post, lift_offer, lift_seat;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- How many of _v117_people()'s come by (c) from outside the stage: the
-- earlier sections' moved boys on the compared sides, and their families.
CREATE OR REPLACE FUNCTION _v117_people_dated_beyond(z jsonb) RETURNS int AS $$
  SELECT count(*)::int FROM unnest(_v117_people(z)) p
   WHERE p::text NOT IN (SELECT value FROM jsonb_each_text(z))
     AND (EXISTS (SELECT 1 FROM role_assignment r JOIN assignment_subject g ON g.assignment_id = r.id
                   WHERE r.active AND r.person_id = p AND g.player_id = ANY (_v117_dated_on_rows(z)))
          OR EXISTS (SELECT 1 FROM app_user u WHERE u.id = p AND u.player_id = ANY (_v117_dated_on_rows(z))))
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/117 (section 94) ─────────────────────────────────────────────
-- ┌── db/118 (section 95) ──────────────────────────────────────────────
-- A stored surname that is not in the boy's full name, as the owner writes
-- it, so the scan is seen to read the column itself. Rolled back with
-- everything else.
CREATE OR REPLACE FUNCTION _seed_118_surname(p_player uuid, p_surname text) RETURNS void AS $$
  UPDATE player SET surname = p_surname WHERE id = p_player;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A full name written with punctuation in it ("Zungu, S", "Mary-Anne ...").
CREATE OR REPLACE FUNCTION _seed_118_name(p_player uuid, p_full_name text) RETURNS void AS $$
  UPDATE player SET full_name = p_full_name WHERE id = p_player;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- A fixture tomorrow between two schools, as the office would write it.
CREATE OR REPLACE FUNCTION _seed_118_fixture(p_home uuid, p_away uuid) RETURNS void AS $$
  INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (p_home, '1XI', p_away, '1XI', 'Verify 118 opponents', now() + interval '1 day', 'cricket', 'T20', 20, 'scheduled');
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Kameel, 28 Oct 2026 ("Only its own competitions: refuse a platform-wide
-- caller"): a league at each school, each organising one competition, and a
-- third competition nobody organises. One Hilton-Westville fixture in each,
-- and a conduct record from each: Hilton's league fixture carries one about
-- a Hilton boy and one about a Westville boy, so its read is logged at both.
CREATE OR REPLACE FUNCTION _seed_118_league() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  P_H uuid := 'aaaaaaaa-0000-0000-0000-000000000005';   -- R Pillay, Hilton
  P_W uuid := 'bbbbbbbb-0000-0000-0000-000000000001';   -- D Mkhize, Westville
  V_BY uuid := '88888888-0000-0000-0000-00000000000c';   -- the office files them
  ids jsonb; c uuid; f uuid; v uuid; k text;
BEGIN
  ids := _v71_people('v118', ARRAY[
    ARRAY['hilleague', 'competitionadmin', HIL::text, '', ''],
    ARRAY['wesleague', 'competitionadmin', WES::text, '', '']]);
  FOREACH k IN ARRAY ARRAY['hil', 'wes', 'none'] LOOP
    INSERT INTO competition (school_id, name, comp_type, format, level)
    VALUES (CASE k WHEN 'hil' THEN HIL WHEN 'wes' THEN WES END, 'Verify 118 League ' || k, 'league', 'T20', 'school')
    RETURNING id INTO c;
    INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name) VALUES
      (c, HIL, '1XI', 'Hilton 1'), (c, WES, '1XI', 'Westville 1');
    INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, starts_at, sport, format, overs, status, competition_id)
    VALUES (CASE k WHEN 'wes' THEN WES ELSE HIL END, '1XI', CASE k WHEN 'wes' THEN HIL ELSE WES END, '1XI',
            'Verify 118 league fixture ' || k, now() - interval '2 days', 'cricket', 'T20', 20, 'scheduled', c)
    RETURNING id INTO f;
    INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
    VALUES (P_H, HIL, f, V_BY, 'v118: dissent at the ' || k || ' league fixture') RETURNING id INTO v;
    ids := ids || jsonb_build_object('c_' || k, c, 'r_' || k, v);
  END LOOP;
  INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
  VALUES (P_W, WES, (SELECT m.id FROM match m WHERE m.competition_id = (ids->>'c_hil')::uuid), V_BY,
          'v118: dissent at the hil league fixture, the other side') RETURNING id INTO v;
  RETURN ids || jsonb_build_object('r_hil_w', v);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- The support sessions a person still holds, wound past their hour (as
-- _expire_support() does one), so a later case asks him as himself and not
-- as the role a session lent him.
CREATE OR REPLACE FUNCTION _seed_118_end_support(p_actor uuid) RETURNS void AS $$
  SELECT _expire_support(s.id) FROM support_access s WHERE s.actor_id = p_actor;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/118 (section 95) ─────────────────────────────────────────────
-- ┌── db/119 (section 96). is_family_of() reads a live link, never on a pad
-- Invented, as the owner; every name is a placeholder. Boy F on Hilton's
-- 16XI with his own `player` role and self-access link. His guardians, one
-- each: `live`; `ended` (her assignment's valid_until today, so ended);
-- `expired` (her assignment's expires_at passed); `early` (her link begins
-- tomorrow); `linkend` (her link's valid_until today: db/62's close). `mum`,
-- a physio at Hilton (`medical`) with a live guardian link to F. `coach`, the
-- 16XI's coach (team.select over F: db/116's staff arm of passport_open()). A
-- school X with nobody at it. One passport consent F → Westville, F's
-- scouting decision (granted), and one honour of his (a passport line).
CREATE OR REPLACE FUNCTION _v119_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  X uuid; F uuid; v_a uuid; ids jsonb; k text;
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V119X', 'Verify OneNineteen College', 'school', 'KwaZulu-Natal')
  RETURNING id INTO X;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify OneNineteen Fam', 1191, 'batter', U15) RETURNING id INTO F;
  ids := _v71_people('v119', ARRAY[
    ARRAY['live',    'guardian', HIL::text, '',     ''],
    ARRAY['ended',   'guardian', HIL::text, '',     ''],
    ARRAY['expired', 'guardian', HIL::text, '',     ''],
    ARRAY['early',   'guardian', HIL::text, '',     ''],
    ARRAY['linkend', 'guardian', HIL::text, '',     ''],
    ARRAY['fboy',    'player',   HIL::text, '16XI', F::text],
    ARRAY['mum',     'medical',  HIL::text, '',     ''],
    ARRAY['coach',   'coach',    HIL::text, '16XI', '']]);
  FOREACH k IN ARRAY ARRAY['live', 'ended', 'expired', 'early', 'linkend', 'mum'] LOOP
    PERFORM _v100_link((ids->>k)::uuid, HIL, F);
  END LOOP;
  UPDATE role_assignment SET valid_until = current_date
   WHERE person_id = (ids->>'ended')::uuid AND role = 'guardian';
  UPDATE role_assignment SET expires_at = now() - interval '1 second'
   WHERE person_id = (ids->>'expired')::uuid AND role = 'guardian';
  UPDATE assignment_subject s SET valid_from = current_date + 1
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = (ids->>'early')::uuid AND s.player_id = F;
  UPDATE assignment_subject s SET valid_until = current_date
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = (ids->>'linkend')::uuid AND s.player_id = F;
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'fboy')::uuid, 'selfaccess', HIL)
  RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, F, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES (F, WES);
  INSERT INTO player_scouting_consent (player_id, consent_state) VALUES (F, 'granted');
  -- One honour, so an open passport() has a line to give.
  INSERT INTO honour (player_id, school_id, team_code, kind, season_id)
  VALUES (F, HIL, '16XI', 'captain', (SELECT s.id FROM season_for(sa_today(), 'school') s LIMIT 1));
  RETURN ids || jsonb_build_object('F', F, 'X', X);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The mother-physio's link to F ends today, as db/62's close ends one.
CREATE OR REPLACE FUNCTION _v119_end_link(p_person uuid, p_player uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET valid_until = current_date
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- F's passport consents as the owner reads them: school, '(w)' when withdrawn.
CREATE OR REPLACE FUNCTION _v119_owner_passport(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t), '') FROM (
    SELECT CASE c.to_school_id WHEN '22222222-2222-2222-2222-222222222222'::uuid THEN 'WES'
                               WHEN (y->>'X')::uuid THEN 'X' ELSE '?' END
           || CASE WHEN c.withdrawn_at IS NOT NULL THEN '(w)' ELSE '' END AS t
      FROM passport_consent c WHERE c.player_id = (y->>'F')::uuid) s
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The same, as the CALLER reads it under his own row security (an invoker).
CREATE OR REPLACE FUNCTION _v119_passport(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t), '') FROM (
    SELECT CASE c.to_school_id WHEN '22222222-2222-2222-2222-222222222222'::uuid THEN 'WES'
                               WHEN (y->>'X')::uuid THEN 'X' ELSE '?' END
           || CASE WHEN c.withdrawn_at IS NOT NULL THEN '(w)' ELSE '' END AS t
      FROM passport_consent c WHERE c.player_id = (y->>'F')::uuid) s
$$ LANGUAGE sql STABLE;

-- F's scouting decision as the caller reads it ('' when he reads none).
CREATE OR REPLACE FUNCTION _v119_scouting(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(c.consent_state, ','), '') FROM player_scouting_consent c WHERE c.player_id = (y->>'F')::uuid
$$ LANGUAGE sql STABLE;

-- The caller names school X for F; 'written' or 'refused'.
CREATE OR REPLACE FUNCTION _v119_name_x(y jsonb) RETURNS text AS $$
BEGIN
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'F')::uuid, (y->>'X')::uuid);
  RETURN 'written';
EXCEPTION WHEN insufficient_privilege THEN RETURN 'refused';
END $$ LANGUAGE plpgsql;

-- The caller withdraws F's consent naming p_school: how many rows moved.
CREATE OR REPLACE FUNCTION _v119_withdraw(y jsonb, p_school uuid) RETURNS int AS $$
DECLARE n int;
BEGIN
  UPDATE passport_consent SET withdrawn_at = now()
   WHERE player_id = (y->>'F')::uuid AND to_school_id = p_school AND withdrawn_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
EXCEPTION WHEN insufficient_privilege THEN RETURN -1;
END $$ LANGUAGE plpgsql;
-- └── db/119 (section 96) ─────────────────────────────────────────────
-- ┌── db/120 (section 97). NOTIFICATIONS S4: push switched off, own rows only.
-- Invented, as the owner. Two Hilton boys on the 18XI, A and B, each with his
-- own guardian (ga, gb); a second guardian of A (gend), whose link will end
-- by its date while his assignment stays live; a pupil whose account is A's
-- own record (so person_is_pupil() is true for him); the side's coach. One medium
-- recognition notice about A, addressed to ga, as the family's sealed notice
-- is (D7).
CREATE OR REPLACE FUNCTION _v120_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  ids jsonb; c_a uuid; c_b uuid; n uuid;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '18XI', 'Verify OneTwenty Able', 1201, 'batter', U15) RETURNING id INTO c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '18XI', 'Verify OneTwenty Bold', 1202, 'bowler', U15) RETURNING id INTO c_b;
  ids := _v71_people('v120', ARRAY[
    ARRAY['ga',    'guardian', HIL::text, '',     ''],
    ARRAY['gb',    'guardian', HIL::text, '',     ''],
    ARRAY['gend',  'guardian', HIL::text, '',     ''],
    ARRAY['pupil', 'player',   HIL::text, '18XI', c_a::text],
    ARRAY['coach', 'coach',    HIL::text, '18XI', '']]);
  PERFORM _v100_link((ids->>'ga')::uuid, HIL, c_a);
  PERFORM _v100_link((ids->>'gb')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'gend')::uuid, HIL, c_a);
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body,
                            required_capability, subject_person_id, recipient_id)
  VALUES (HIL, '18XI', 'team', 'recognition', 'medium', 'Verify 120', 'Verify 120: a fifty',
          'news.read', c_a, (ids->>'ga')::uuid)
  RETURNING id INTO n;
  RETURN ids || jsonb_build_object('A', c_a, 'B', c_b, 'N', n);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the caller is offered, as one line: kind, @A or @B for a child, (off).
CREATE OR REPLACE FUNCTION _v120_choices(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(c.kind
           || CASE c.subject_player_id WHEN (y->>'A')::uuid THEN '@A' WHEN (y->>'B')::uuid THEN '@B'
                                       ELSE CASE WHEN c.subject_player_id IS NULL THEN '' ELSE '@?' END END
           || CASE WHEN c.push THEN '' ELSE '(off)' END, ','), '')
    FROM my_alert_choices() c
$$ LANGUAGE sql STABLE;

-- The link of p_person's to p_player ends by its date: valid_until yesterday,
-- as db/62's close or the office's dated end leaves it. Not _revoke(): his
-- assignment stays active and live.
CREATE OR REPLACE FUNCTION _v120_end_link(p_person uuid, p_player uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET valid_until = current_date - 1
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/120 (section 97) ─────────────────────────────────────────────
