         (CASE WHEN g IN (16, 29) THEN 1 WHEN g = 30 THEN 2 ELSE 4 END)::smallint,
         CASE WHEN g BETWEEN 17 AND 29 THEN V_E ELSE V_D END,
         CASE WHEN g BETWEEN 17 AND 29 THEN V_D ELSE V_E END, V_F, '{}'::jsonb
    FROM generate_series(4, 30) g
   ORDER BY 3;
  INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
  VALUES (M2, HIL, 'v121b:29', 'Verify 121: E''s single was a dead ball', '88888888-0000-0000-0000-000000000006')
  RETURNING id INTO am2;
  RETURN jsonb_build_object('m', M, 'a', V_A, 'b', V_B, 'c', V_C, 'am', am,
                            'm2', M2, 'd', V_D, 'e', V_E, 'am2', am2);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A match's milestone notices, as the owner reads them: "<who> <kind>
-- <live|retracted> <the notification's body>" for each, in order.
CREATE OR REPLACE FUNCTION _v121_notices(p_match uuid, p_names jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(coalesce(p_names ->> mn.player_id::text, '?') || ' ' || mn.kind || ' '
                             || CASE WHEN mn.retracted_at IS NULL THEN 'live' ELSE 'retracted' END
                             || CASE WHEN n.id IS NULL THEN '' WHEN n.retracted_at IS NULL THEN ' (notice up)' ELSE ' (notice down)' END
                             || ': ' || coalesce(n.body, '-'),
                             '; ' ORDER BY coalesce(p_names ->> mn.player_id::text, '?'), mn.kind), '')
    FROM milestone_notice mn LEFT JOIN notification n ON n.id = mn.notice_id
   WHERE mn.match_id = p_match
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The review's B2: tools/sql/laws121-precheck.sql's query, word for word
-- between its markers (rejudge.test.mjs holds the two the same).
CREATE OR REPLACE FUNCTION _v121_precheck()
RETURNS TABLE (match_id uuid, fixture_date date, school text, side text, now_stands integer, now_saved integer) AS $$
-- precheck:begin
WITH w AS (
  -- A bowler's dismissal on a delivery, in a match whose format gives free
  -- hits: the dismissals a free hit saves (dismissal_stands_on_free_hit()).
  SELECT x.match_id,
         -- The old rule (db/54): the last earlier live delivery of the innings
         -- that was not a wide was a no-ball, of any kind.
         coalesce((SELECT p.ball_type IS NOT DISTINCT FROM 'Nb'
                     FROM ball_event_live p
                    WHERE p.match_id = x.match_id AND p.innings = x.innings AND p.seq < x.seq
                      AND p.kind = 'ball' AND p.ball_type IS DISTINCT FROM 'Wd'
                    ORDER BY p.seq DESC LIMIT 1), false) AS old_free_hit,
         -- The new (db/121): the last earlier live delivery of the innings that
         -- counts in the over or earns a free hit (a no-ball of nbType
         -- front_foot, or of none recorded) was a no-ball.
         coalesce((SELECT p.ball_type IS NOT DISTINCT FROM 'Nb'
                     FROM ball_event_live p
                    WHERE p.match_id = x.match_id AND p.innings = x.innings AND p.seq < x.seq
                      AND p.kind = 'ball'
                      AND (ball_counts_in_over(p.ball_type, p.payload)
                           OR (p.ball_type = 'Nb' AND coalesce(p.payload ->> 'nbType', 'front_foot') = 'front_foot'))
                    ORDER BY p.seq DESC LIMIT 1), false) AS new_free_hit
    FROM ball_event_live x
   WHERE x.kind = 'ball'
     AND ball_is_wicket(x.ball_type, x.dismissal)
     AND NOT dismissal_stands_on_free_hit(x.dismissal)
     AND match_free_hits_apply(x.match_id)
)
SELECT w.match_id,
       (m.starts_at AT TIME ZONE 'Africa/Johannesburg')::date               AS fixture_date,
       s.code                                                               AS school,
       m.team_code                                                          AS side,
       count(*) FILTER (WHERE w.old_free_hit AND NOT w.new_free_hit)::int   AS now_stands,
       count(*) FILTER (WHERE w.new_free_hit AND NOT w.old_free_hit)::int   AS now_saved
  FROM w
  JOIN match m  ON m.id = w.match_id
  JOIN school s ON s.id = m.school_id
 WHERE w.old_free_hit <> w.new_free_hit
 GROUP BY w.match_id, m.starts_at, s.code, m.team_code
 ORDER BY 2, 3, 4, 1
-- precheck:end
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/121 (section 98) ─────────────────────────────────────────────
-- ┌── db/122 (section 99). Kameel's four decisions of 29 Oct 2026
-- Invented, as the owner; every name is a placeholder.
--   C, a Hilton 16XI boy, with two guardians (mum, dad) and his own account
--     (cboy: player and self-access); a Westville coach and office, who open
--     his passport once his family names Westville; a Westville parent, who
--     is nothing to him; Hilton's 16XI coach and office; school X, whose
--     office will be named on a consent with no giver on record.
--   S, a Hilton 16XI boy who has bowled an over in each of three past
--     fixtures (scouting_evidence_threshold() is 3), with a guardian (sg) who
--     will say yes to scouts; an accredited scout at Hilton.
--   E, a Hilton 1XI pupil of eighteen (so a sign-in may be written to his
--     account, db/81's trigger), whose account (epupil) holds only `player`,
--     a role the director of sport may grant: so she passes db/81's office
--     rule over it. eadult, a Hilton coach, the adult beside him. Each has an
--     open Google claim, a linked sign-in and a pending request for the
--     scorer's role. dos, Hilton's director of sport.
--   Y, a Hilton 1XI pupil of eighteen with his own account (yboy: player and
--     self-access, his own link consented) and a guardian (yg) whose link is
--     live until the section ends it.
--   The particle boys: six at Hilton whose names carry a two-letter
--     particle, the first of them "Al de Wet".
--   D, a Hilton 13XI boy since t-30, with a guardian (gd) who asked for his
--     seat on a lift that another 13XI boy's guardian (drv) offers to a 13XI
--     fixture: later today (SAST) when it is before noon in Johannesburg,
--     tomorrow when it is after.
--   After the read-through (db/122 §1d): school Q, whose coach (qcoach) will
--     be named on a consent C gave himself at fifteen before db/122; and gp,
--     a third guardian of C whose verified link carries no processing consent.
CREATE OR REPLACE FUNCTION _v122_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  t date := sa_today();
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  ADULT date := (sa_today() - interval '18 years 2 months')::date;
  h int := extract(hour FROM now() AT TIME ZONE 'Africa/Johannesburg')::int;
  X uuid; c_c uuid; c_s uuid; c_e uuid; c_d uuid; c_d2 uuid; c_y uuid; v uuid; v_a uuid; v_d uuid; v_o uuid; l record;
  ids jsonb; z jsonb := '{}'; k text; i int; nm text;
BEGIN
  INSERT INTO school (code, name, kind, province) VALUES ('V122X', 'Verify OneTwentyTwo College', 'school', 'KwaZulu-Natal')
  RETURNING id INTO X;
  INSERT INTO school (code, name, kind, province) VALUES ('V122Z', 'Verify OneTwentyTwo Academy', 'school', 'KwaZulu-Natal')
  RETURNING id INTO v;
  z := z || jsonb_build_object('Z', v);
  INSERT INTO school (code, name, kind, province) VALUES ('V122Q', 'Verify OneTwentyTwo High', 'school', 'KwaZulu-Natal')
  RETURNING id INTO v;
  z := z || jsonb_build_object('Q', v);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify OneTwentyTwo Consent', 1221, 'batter', U15) RETURNING id INTO c_c;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify OneTwentyTwo Scouted', 1222, 'bowler', U15) RETURNING id INTO c_s;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyTwo Elder', 1223, 'batter', ADULT) RETURNING id INTO c_e;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyTwo Grown', 1240, 'bowler', ADULT) RETURNING id INTO c_y;
  PERFORM set_config('app.effective_on', (t - 30)::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '13XI', 'Verify OneTwentyTwo Mover', 1224, 'batter', make_date(extract(year FROM t)::int - 13, 3, 1)) RETURNING id INTO c_d;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '13XI', 'Verify OneTwentyTwo Stayer', 1225, 'batter', make_date(extract(year FROM t)::int - 13, 3, 1)) RETURNING id INTO c_d2;
  PERFORM set_config('app.effective_on', '', true);
  ids := _v71_people('v122', ARRAY[
    ARRAY['mum',       'guardian',        HIL::text, '',     ''],
    ARRAY['dad',       'guardian',        HIL::text, '',     ''],
    ARRAY['cboy',      'player',          HIL::text, '16XI', c_c::text],
    ARRAY['wescoach',  'coach',           WES::text, '16XI', ''],
    ARRAY['wesoffice', 'schooladmin',     WES::text, '',     ''],
    ARRAY['wesparent', 'guardian',        WES::text, '',     ''],
    ARRAY['hcoach',    'coach',           HIL::text, '16XI', ''],
    ARRAY['hoffice',   'schooladmin',     HIL::text, '',     ''],
    ARRAY['xoffice',   'schooladmin',     X::text,   '',     ''],
    ARRAY['sg',        'guardian',        HIL::text, '',     ''],
    ARRAY['scout',     'scout',           HIL::text, '',     ''],
    ARRAY['epupil',    'player',          HIL::text, '1XI',  c_e::text],
    ARRAY['eadult',    'coach',           HIL::text, '1XI',  ''],
    ARRAY['dos',       'directorofsport', HIL::text, '',     ''],
    ARRAY['gd',        'guardian',        HIL::text, '',     ''],
    ARRAY['drv',       'guardian',        HIL::text, '',     ''],
    ARRAY['yboy',      'player',          HIL::text, '1XI',  c_y::text],
    ARRAY['yg',        'guardian',        HIL::text, '',     ''],
    ARRAY['qcoach',    'coach',           z->>'Q',   '16XI', ''],
    ARRAY['gp',        'guardian',        HIL::text, '',     '']]);
  PERFORM _v100_link((ids->>'mum')::uuid, HIL, c_c);
  PERFORM _v100_link((ids->>'dad')::uuid, HIL, c_c);
  PERFORM _v100_link((ids->>'sg')::uuid, HIL, c_s);
  PERFORM _v100_link((ids->>'gd')::uuid, HIL, c_d);
  PERFORM _v100_link((ids->>'drv')::uuid, HIL, c_d2);
  -- gp's link to C is verified and his processing consent is not on record.
  PERFORM _v100_link((ids->>'gp')::uuid, HIL, c_c);
  UPDATE assignment_subject g SET consent_state = 'pending', consent_version = NULL, consent_at = NULL
    FROM role_assignment a WHERE a.id = g.assignment_id AND a.person_id = (ids->>'gp')::uuid AND g.player_id = c_c;
  -- Y is eighteen, so db/62 would close his guardian's link today; it is
  -- staged open for thirty days, and the section ends it.
  PERFORM _v100_link((ids->>'yg')::uuid, HIL, c_y, 'verified', current_date + 30);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'yboy')::uuid, 'selfaccess', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, c_y, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'cboy')::uuid, 'selfaccess', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, c_c, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, current_date - 1);
  -- One honour, so an open passport() has a line to give.
  INSERT INTO honour (player_id, school_id, team_code, kind, season_id)
  VALUES (c_c, HIL, '16XI', 'captain', (SELECT s.id FROM season_for(sa_today(), 'school') s LIMIT 1));
  -- A consent naming school X that no giver is on record for (the owner wrote it).
  INSERT INTO passport_consent (player_id, to_school_id) VALUES (c_c, X) RETURNING id INTO v;
  z := z || jsonb_build_object('pc_x', v);
  -- S's body of work: an over in each of three fixtures already played.
  FOR i IN 1..3 LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
    VALUES (HIL, '16XI', 'Verify OneTwentyTwo ' || i, now() - make_interval(days => 20 + i), 'cricket', 'T20', 20, 'scheduled')
    RETURNING id INTO v;
    PERFORM _v71_bowl(v, OFFICE, ARRAY[c_s]);
  END LOOP;
  INSERT INTO scout_accreditation (person_id, organisation, scout_role, verification_status, verified_by, verified_at)
  VALUES ((ids->>'scout')::uuid, 'Verify 122 Union', 'regional_selector', 'verified', OFFICE, now());
  -- The two accounts' claims, sign-ins and requests.
  FOREACH k IN ARRAY ARRAY['epupil', 'eadult'] LOOP
    INSERT INTO pending_claim (provider, provider_uid, email, user_id)
    VALUES ('google.com', 'v122-claim-' || k, 'v122.' || k || '.claim@example.invalid', (ids->>k)::uuid) RETURNING id INTO v;
    z := z || jsonb_build_object('claim_' || k, v);
    INSERT INTO auth_identity (user_id, provider, provider_uid, email_at_link, linked_how, linked_by)
    VALUES ((ids->>k)::uuid, 'google.com', 'v122-link-' || k, 'v122.' || k || '.link@example.invalid', 'office_confirmed', OFFICE);
    INSERT INTO role_request (person_id, role, school_id, note) VALUES ((ids->>k)::uuid, 'scorer', HIL, 'v122') RETURNING id INTO v;
    z := z || jsonb_build_object('req_' || k, v);
  END LOOP;
  -- The particle boys.
  i := 0;
  FOREACH nm IN ARRAY ARRAY['Al de Wet', 'Bo du Toit', 'Ek le Roux', 'Ux la Grange', 'Oz da Silva', 'Yi di Marco'] LOOP
    i := i + 1;
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
      (HIL, '16XI', nm, 1225 + i, 'batter', U15);
  END LOOP;
  -- D's lift: a 13XI fixture, later today (SAST) before noon, tomorrow after.
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, '13XI', 'Verify OneTwentyTwo lift', CASE WHEN h < 12 THEN now() + interval '1 hour' ELSE now() + interval '24 hours' END,
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v;
  z := z || jsonb_build_object('f_lift', v);
  INSERT INTO lift_driver_declaration (person_id, school_id, vehicle_description, registration, seats, licence_held,
                                       insured, roadworthy, belts, code_acknowledged, policy_version, expires_on)
  VALUES ((ids->>'drv')::uuid, HIL, 'V122 red hatch', 'V122 GP', 3, true, true, true, true, true, 1, current_date + 300)
  RETURNING id INTO v_d;
  INSERT INTO lift_offer (school_id, match_id, team_code, leg, driver_id, declaration_id, seats, meet_kind, meet_at, fixture_starts_at)
  SELECT HIL, m.id, '13XI', 'out', (ids->>'drv')::uuid, v_d, 3, 'school', m.starts_at - interval '30 minutes', m.starts_at
    FROM match m WHERE m.id = v
  RETURNING id INTO v_o;
  SELECT g.assignment_id, g.id INTO l FROM assignment_subject g JOIN role_assignment a ON a.id = g.assignment_id
   WHERE a.person_id = (ids->>'gd')::uuid AND g.player_id = c_d;
  INSERT INTO lift_seat (offer_id, school_id, match_id, team_code, leg, player_id, consent_by, guardian_assignment_id,
                         guardian_link_id, requested_by, state)
  VALUES (v_o, NULL, NULL, NULL, NULL, c_d, 'guardian', l.assignment_id, l.id, (ids->>'gd')::uuid, 'requested')
  RETURNING id INTO v;
  RETURN ids || z || jsonb_build_object('C', c_c, 'S', c_s, 'E', c_e, 'D', c_d, 'Y', c_y, 'X', X, 'seat', v, 'h', h);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The facts the readers may not see, as the owner: C's passport consents as
-- school(giver)[(w)]; D's memberships as side:joined..left, days from today
-- (SAST); the seat's state.
CREATE OR REPLACE FUNCTION _v122_fact(p_what text, y jsonb) RETURNS text AS $$
  SELECT CASE p_what
    WHEN 'consents' THEN (SELECT coalesce(string_agg(q.t, ',' ORDER BY q.t), '') FROM (
           SELECT CASE c.to_school_id WHEN '22222222-2222-2222-2222-222222222222'::uuid THEN 'WES' WHEN (y->>'X')::uuid THEN 'X'
                                      WHEN (y->>'Q')::uuid THEN 'Q' ELSE '?' END
                  || '(' || coalesce((SELECT e.k FROM jsonb_each_text(y) e(k, val) WHERE e.val = c.granted_by::text LIMIT 1), '-') || ')'
                  || CASE WHEN c.withdrawn_at IS NOT NULL
                          THEN '(w:' || coalesce((SELECT e.k FROM jsonb_each_text(y) e(k, val) WHERE e.val = c.withdrawn_by::text LIMIT 1), '-') || ')'
                          ELSE '' END AS t
             FROM passport_consent c WHERE c.player_id = (y->>'C')::uuid) q)
    WHEN 'rows' THEN (SELECT coalesce(string_agg(m.team_code || ':' || (m.joined_on - sa_today()) || '..'
                                                 || coalesce((m.left_on - sa_today())::text, ''), ' '
                                                 ORDER BY m.joined_on, m.created_at), '')
                        FROM team_membership m WHERE m.player_id = (y->>'D')::uuid)
    WHEN 'seat' THEN (SELECT s.state FROM lift_seat s WHERE s.id = (y->>'seat')::uuid)
    -- Y's scouting rows: state:giver.
    WHEN 'scouting' THEN (SELECT coalesce(string_agg(c.consent_state || ':'
             || coalesce((SELECT e.k FROM jsonb_each_text(y) e(k, val) WHERE e.val = c.decided_by::text LIMIT 1), '-'), ','), '')
                            FROM player_scouting_consent c WHERE c.player_id = (y->>'Y')::uuid)
  END
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Move a boy with no effective_on, as the office's route does with the box
-- left empty, in a session whose own day is not Johannesburg's: the time zone
-- is set for the one statement and put back.
CREATE OR REPLACE FUNCTION _v122_move(p_player uuid, p_team text, p_tz text) RETURNS text AS $$
DECLARE v_tz text := current_setting('TimeZone'); v_day text;
BEGIN
  PERFORM set_config('TimeZone', p_tz, true);
  v_day := current_date::text;
  PERFORM set_config('app.effective_on', '', true);
  PERFORM set_config('app.user_id', '88888888-0000-0000-0000-00000000000c', true);
  UPDATE player SET team_code = p_team WHERE id = p_player;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('TimeZone', v_tz, true);
  RETURN v_day;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The caller's read of C's passport consents, under his own row security.
CREATE OR REPLACE FUNCTION _v122_reads(y jsonb) RETURNS int AS $$
  SELECT count(*)::int FROM passport_consent c WHERE c.player_id = (y->>'C')::uuid
$$ LANGUAGE sql STABLE;

-- After the read-through (db/122 §1d), as the owner.
-- A consent C named for himself at fifteen, as db/08 let him before db/122:
-- school Q, granted by his own account.
CREATE OR REPLACE FUNCTION _v122_self_consent(y jsonb) RETURNS uuid AS $$
DECLARE v uuid;
BEGIN
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'C')::uuid, (y->>'Q')::uuid) RETURNING id INTO v;
  UPDATE passport_consent SET granted_by = (y->>'cboy')::uuid WHERE id = v;
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A guardian's ended link to a boy granted afresh, as guardian_link_establish()
-- (db/62) grants it: a new subject row on her existing assignment. Written
-- with clock_timestamp(), so it is younger than every consent this one
-- transaction wrote (now() stands still inside it).
CREATE OR REPLACE FUNCTION _v122_relink(p_person uuid, p_player uuid) RETURNS void AS $$
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, created_at)
  SELECT a.id, p_player, 'parent', 'verified', '88888888-0000-0000-0000-00000000000c', now(),
         'granted', 'popia-2026-01', now(), '88888888-0000-0000-0000-00000000000c', clock_timestamp()
    FROM role_assignment a WHERE a.person_id = p_person AND a.role = 'guardian' AND a.active
   LIMIT 1;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The office corrects the end instead: the link granted afresh is ended, and
-- the one that gave the consent is re-opened, in place.
CREATE OR REPLACE FUNCTION _v122_correct(p_person uuid, p_player uuid) RETURNS void AS $$
BEGIN
  UPDATE assignment_subject s SET valid_until = current_date
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player
     AND s.created_at > now();
  UPDATE assignment_subject s SET valid_until = NULL
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player
     AND s.created_at <= now();
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- E's two claims, as the owner reads them: account:how, '-' while open.
CREATE OR REPLACE FUNCTION _v122_claims(y jsonb) RETURNS text AS $$
  SELECT string_agg(k || ':' || coalesce((SELECT c.resolved_how FROM pending_claim c WHERE c.id = (y->>('claim_' || k))::uuid), '-'), ',' ORDER BY k)
    FROM unnest(ARRAY['eadult', 'epupil']) k
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/122 (section 99) ─────────────────────────────────────────────
-- ┌── db/123 (section 100). REACH R-E: notices follow the side.
-- Invented, as the owner. Three Hilton boys, A and C on U15A and B on U13B,
-- each with his own guardian (ga, gc, gb); A's and B's own accounts (pupil,
-- pupilb); the U15A and U13B coaches. Five notices at Hilton:
--   S  "U15A team sheet published"  fixture, fixture.read, U15A, no child
--   T  "U15A training moved"        notice, training, news.read, U15A, no child
--   K  a fifty for A                recognition, news.read, U15A, child A
--   R  for ga alone                 system, news.read, U15A, recipient ga
--   W  the whole school             system, news.read, no team
-- Kameel's decisions of 29 Oct (db/123's header):
--   1. U, a U14A boy (his account upboy, his guardian gu), on the home sheet
--      of MU, a U15A fixture; MO is another U15A fixture he is not on.
--      SU "Result reopened" about MU and SO about MO: fixture, fixture.read,
--      U15A, no child.
--   2. V (his account vboy, his guardian gv), on the U16B from t-60 and
--      moved to the U17B at t-10. OB, a U16B notice published at t-30 (while
--      he was on it); OA, a U16B notice published now (after); NB, a U17B
--      notice published at t-30 (before he joined it). Each a training notice.
CREATE OR REPLACE FUNCTION _v123_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  U13 date := make_date(extract(year FROM sa_today())::int - 13, 3, 1);
  U14 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  t   date := sa_today();
  ids jsonb; c_a uuid; c_b uuid; c_c uuid; v_s uuid; v_t uuid; v_k uuid; v_r uuid; v_w uuid;
  c_u uuid; c_v uuid; m_u uuid; m_o uuid; z jsonb := '{}'; k text; tm text; dd int; v_id uuid;
BEGIN
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify OneTwentyThree Able', 1231, 'batter', U15) RETURNING id INTO c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U13B', 'Verify OneTwentyThree Bold', 1232, 'bowler', U13) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15A', 'Verify OneTwentyThree Calm', 1233, 'bowler', U15) RETURNING id INTO c_c;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U14A', 'Verify OneTwentyThree Upward', 1234, 'batter', U14) RETURNING id INTO c_u;
  -- V joins the U16B at t-60, dated as the move route dates it.
  PERFORM set_config('app.effective_on', (t - 60)::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U16B', 'Verify OneTwentyThree Mover', 1235, 'batter', U15) RETURNING id INTO c_v;
  PERFORM set_config('app.effective_on', '', true);
  ids := _v71_people('v123', ARRAY[
    ARRAY['ga',     'guardian', HIL::text, '',     ''],
    ARRAY['gb',     'guardian', HIL::text, '',     ''],
    ARRAY['gc',     'guardian', HIL::text, '',     ''],
    ARRAY['pupil',  'player',   HIL::text, 'U15A', c_a::text],
    ARRAY['pupilb', 'player',   HIL::text, 'U13B', c_b::text],
    ARRAY['coach',  'coach',    HIL::text, 'U15A', ''],
    ARRAY['coachb', 'coach',    HIL::text, 'U13B', ''],
    ARRAY['gu',     'guardian', HIL::text, '',     ''],
    ARRAY['upboy',  'player',   HIL::text, 'U14A', c_u::text],
    ARRAY['gv',     'guardian', HIL::text, '',     ''],
    ARRAY['vboy',   'player',   HIL::text, 'U16B', c_v::text]]);
  PERFORM _v100_link((ids->>'gu')::uuid, HIL, c_u);
  PERFORM _v100_link((ids->>'gv')::uuid, HIL, c_v);
  -- V moves to the U17B at t-10 (db/112 carries his player role with him).
  PERFORM set_config('app.effective_on', (t - 10)::text, true);
  UPDATE player SET team_code = 'U17B' WHERE id = c_v;
  PERFORM set_config('app.effective_on', '', true);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Verify OneTwentyThree MU', ((t + 3)::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m_u;
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
  VALUES (HIL, 'U15A', 'Verify OneTwentyThree MO', ((t + 4)::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
          'cricket', 'T20', 20, 'scheduled') RETURNING id INTO m_o;
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES (m_u, c_u, 'home', 1);
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability,
                            subject_kind, subject_id)
  VALUES (HIL, 'U15A', 'team', 'fixture', 'medium', 'Result reopened · MU', 'Verify 123: MU reopened', 'fixture.read', 'match', m_u)
  RETURNING id INTO v_id;
  z := z || jsonb_build_object('SU', v_id);
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability,
                            subject_kind, subject_id)
  VALUES (HIL, 'U15A', 'team', 'fixture', 'medium', 'Result reopened · MO', 'Verify 123: MO reopened', 'fixture.read', 'match', m_o)
  RETURNING id INTO v_id;
  z := z || jsonb_build_object('SO', v_id);
  FOR k, tm, dd IN SELECT * FROM (VALUES ('OB', 'U16B', -30), ('OA', 'U16B', 0), ('NB', 'U17B', -30)) x LOOP
    INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability,
                              subject_kind, published_at, expires_at)
    VALUES (HIL, tm, 'team', 'notice', 'low', 'Verify 123 ' || k, 'Verify 123: nets moved', 'news.read', 'training',
            CASE WHEN dd = 0 THEN now() - interval '1 minute'
                 ELSE ((t + dd)::timestamp + time '12:00') AT TIME ZONE 'Africa/Johannesburg' END,
            now() + interval '30 days')
    RETURNING id INTO v_id;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  PERFORM _v100_link((ids->>'ga')::uuid, HIL, c_a);
  PERFORM _v100_link((ids->>'gb')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'gc')::uuid, HIL, c_c);
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability)
  VALUES (HIL, 'U15A', 'team', 'fixture', 'medium', 'U15A team sheet published', 'Verify 123: the sheet for Saturday',
          'fixture.read')
  RETURNING id INTO v_s;
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability, subject_kind)
  VALUES (HIL, 'U15A', 'team', 'notice', 'low', 'U15A training moved', 'Verify 123: nets at four', 'news.read', 'training')
  RETURNING id INTO v_t;
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability, subject_person_id)
  VALUES (HIL, 'U15A', 'team', 'recognition', 'low', 'Verify 123: a fifty', 'Verify 123: a fifty', 'news.read', c_a)
  RETURNING id INTO v_k;
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability, recipient_id)
  VALUES (HIL, 'U15A', 'team', 'system', 'medium', 'Verify 123: for you', 'Verify 123: for ga alone', 'news.read',
          (ids->>'ga')::uuid)
  RETURNING id INTO v_r;
  INSERT INTO notification (school_id, team_code, scope_level, kind, urgency, title, body, required_capability)
  VALUES (HIL, NULL, 'school', 'system', 'low', 'Verify 123: the school', 'Verify 123: to everyone', 'news.read')
  RETURNING id INTO v_w;
  RETURN ids || z || jsonb_build_object('A', c_a, 'B', c_b, 'C', c_c, 'U', c_u, 'V', c_v,
                                         'S', v_s, 'T', v_t, 'K', v_k, 'R', v_r, 'W', v_w);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- How many of p_keys' notices (S, T, K, R, W, SU, SO, OB, OA, NB) the caller reads, through the
-- table and through my_notifications (the screen's read), as one line.
CREATE OR REPLACE FUNCTION _v123_reads(y jsonb, p_keys text[]) RETURNS text AS $$
  SELECT (SELECT count(*) FROM notification n WHERE n.id IN (SELECT (y->>k)::uuid FROM unnest(p_keys) k))
         || '/' ||
         (SELECT count(*) FROM my_notifications m WHERE m.id IN (SELECT (y->>k)::uuid FROM unnest(p_keys) k))
$$ LANGUAGE sql STABLE;

-- After the read-through (29 Oct 2026). For the caller: the notices among
-- p_keys that notification_read_side admits and db/09's notification_read,
-- as it stands in the database (its qual, read from pg_policy), does not.
-- Each 'key:reader' (p_who) when so; '' when db/09 admits all of them.
CREATE OR REPLACE FUNCTION _v123_only_side_read(y jsonb, p_keys text[], p_who text) RETURNS text AS $$
DECLARE k text; v_side boolean; v_db09 boolean; out text := '';
BEGIN
  FOREACH k IN ARRAY p_keys LOOP
    SELECT notice_side_read(n.required_capability, n.school_id, n.team_code, n.kind, n.subject_kind,
                            n.subject_id, n.subject_person_id, n.recipient_id, n.published_at)
      INTO v_side FROM notification n WHERE n.id = (y->>k)::uuid;
    EXECUTE format('SELECT %s FROM notification WHERE id = $1',
                   (SELECT pg_get_expr(p.polqual, p.polrelid) FROM pg_policy p
                     WHERE p.polrelid = 'notification'::regclass AND p.polname = 'notification_read'))
      INTO v_db09 USING (y->>k)::uuid;
    IF v_side AND NOT coalesce(v_db09, false) THEN
      out := out || CASE WHEN out = '' THEN '' ELSE ',' END || k || ':' || p_who;
    END IF;
  END LOOP;
  RETURN out;
END $$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- OB withdrawn by the school office, as a post's withdrawal takes a notice
-- back (db/89), now: after V's move off the U16B. The retraction's id.
CREATE OR REPLACE FUNCTION _v123_retract(y jsonb) RETURNS uuid AS $$
DECLARE v uuid;
BEGIN
  PERFORM set_config('app.user_id', '88888888-0000-0000-0000-00000000000c', true);
  v := notification_retract((y->>'OB')::uuid, 'withdrawn', true);
  PERFORM set_config('app.user_id', '', true);
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/123 (section 100) ─────────────────────────────────────────────
-- ┌── db/124 (section 101). The union passport (Kameel, 29 Oct 2026)
-- Invented, as the owner; every name is a placeholder.
--   B, a Hilton 16XI boy of fifteen, with two guardians (mum, dad) and his
--     own account (bself: player and self-access); one honour, so an open
--     passport() has a line to give. B2, a Hilton 16XI boy whose guardian
--     (ofam) is nothing to B.
--   U, the KwaZulu-Natal union (Hilton's province: school_union(Hilton)),
--     found or made; OU, a union of another province; F, the federation (CSA
--     Schools), found or made.
--   At U: sel, a union selector; org, a competition organiser (today's union
--     account); uoffice, its school administrator (guardian.link.manage
--     there, which db/122's named-school arm would have let in); sel2, a
--     union selector who also holds a platform-wide organiser's assignment.
--   At OU: osel, a union selector. At F: fsel, a union selector.
-- After the red-team (db/124 §6, Kameel 30 Oct 2026):
--   selcoach, a union selector at U who is also a Hilton 16XI coach (B's);
--     selpar, a union selector at U who is also B's guardian (Q2);
--   uhead, U's principal, who appoints himself its selector (Q7);
--   C, a club (kind 'club'), and coffice, its school administrator
--     (guardian.link.manage there), for Q4.
CREATE OR REPLACE FUNCTION _v124_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  U uuid; OU uuid; F uuid; C uuid; c_b uuid; c_b2 uuid; v_a uuid; ids jsonb;
BEGIN
  SELECT s.id INTO U FROM school s WHERE s.kind = 'union' AND lower(btrim(s.province)) = 'kwazulu-natal' AND s.archived_at IS NULL;
  IF U IS NULL THEN
    INSERT INTO school (code, name, kind, province) VALUES ('V124U', 'Verify OneTwentyFour KZN Union', 'union', 'KwaZulu-Natal')
    RETURNING id INTO U;
  END IF;
  INSERT INTO school (code, name, kind, province) VALUES ('V124OU', 'Verify OneTwentyFour Far Union', 'union', 'Verify 124 Province')
  RETURNING id INTO OU;
  SELECT s.id INTO F FROM school s WHERE s.kind = 'federation';
  IF F IS NULL THEN
    INSERT INTO school (code, name, kind) VALUES ('V124F', 'Verify OneTwentyFour CSA Schools', 'federation') RETURNING id INTO F;
  END IF;
  INSERT INTO school (code, name, kind) VALUES ('V124C', 'Verify OneTwentyFour Club', 'club') RETURNING id INTO C;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify OneTwentyFour Boy', 1241, 'batter', U15) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify OneTwentyFour Other', 1242, 'bowler', U15) RETURNING id INTO c_b2;
  ids := _v71_people('v124', ARRAY[
    ARRAY['mum',     'guardian',         HIL::text, '',     ''],
    ARRAY['dad',     'guardian',         HIL::text, '',     ''],
    ARRAY['ofam',    'guardian',         HIL::text, '',     ''],
    ARRAY['bself',   'player',           HIL::text, '16XI', c_b::text],
    ARRAY['sel',     'unionselector',    U::text,   '',     ''],
    ARRAY['sel2',    'unionselector',    U::text,   '',     ''],
    ARRAY['org',     'competitionadmin', U::text,   '',     ''],
    ARRAY['uoffice', 'schooladmin',      U::text,   '',     ''],
    ARRAY['osel',    'unionselector',    OU::text,  '',     ''],
    ARRAY['fsel',    'unionselector',    F::text,   '',     ''],
    ARRAY['selcoach', 'coach',           HIL::text, '16XI', ''],
    ARRAY['selpar',  'guardian',         HIL::text, '',     ''],
    ARRAY['uhead',   'principal',        U::text,   '',     ''],
    ARRAY['coffice', 'schooladmin',      C::text,   '',     '']]);
  -- Each of the two also holds the union's selector role (Q2).
  INSERT INTO role_assignment (person_id, role, school_id) VALUES
    ((ids->>'selcoach')::uuid, 'unionselector', U), ((ids->>'selpar')::uuid, 'unionselector', U);
  -- sel2 also holds the league account's platform-wide organiser's role.
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'sel2')::uuid, 'competitionadmin', NULL);
  PERFORM _v100_link((ids->>'mum')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'dad')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'ofam')::uuid, HIL, c_b2);
  PERFORM _v100_link((ids->>'selpar')::uuid, HIL, c_b);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'bself')::uuid, 'selfaccess', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, c_b, 'self', 'verified', '88888888-0000-0000-0000-00000000000c', now(), 'granted', 'popia-2026-01', now(),
          '88888888-0000-0000-0000-00000000000c', current_date - 1);
  INSERT INTO honour (player_id, school_id, team_code, kind, season_id)
  VALUES (c_b, HIL, '16XI', 'captain', (SELECT s.id FROM season_for(sa_today(), 'school') s LIMIT 1));
  RETURN ids || jsonb_build_object('B', c_b, 'B2', c_b2, 'U', U, 'OU', OU, 'F', F, 'C', C);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- passport_open() as the owner: since db/124 §6 Q1 it is no door of the
-- application's, so the sections ask it through this. It is a definer, and
-- reads the caller from app.user_id either way, so the answer is the same.
CREATE OR REPLACE FUNCTION _passport_open(p_player uuid) RETURNS boolean AS $$
  SELECT passport_open(p_player)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A consent naming p_org written as the owner in his mother's name, past the
-- insert policy: what a row already on a live database looks like (Q4).
CREATE OR REPLACE FUNCTION _v124_consent_as_owner(y jsonb, p_org uuid) RETURNS uuid AS $$
DECLARE v uuid;
BEGIN
  PERFORM set_config('app.user_id', y->>'mum', true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'B')::uuid, p_org) RETURNING id INTO v;
  PERFORM set_config('app.user_id', '', true);
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The account-lifecycle design renames or anonymises an account (Q3): done
-- here as the owner, to one account.
CREATE OR REPLACE FUNCTION _v124_rename(p_user uuid, p_name text) RETURNS void AS $$
  UPDATE app_user SET name = p_name WHERE id = p_user;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- One boy's union read log as the owner reads it: name (role):what, in order.
CREATE OR REPLACE FUNCTION _v124_reads_of(p_player uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(r.reader_name || ' (' || r.reader_role || '):' || r.what, ',' ORDER BY r.read_at, r.what), '')
    FROM passport_union_read r WHERE r.player_id = p_player
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The union read log, as the owner reads it: reader:what, in order, for B.
CREATE OR REPLACE FUNCTION _v124_log(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(coalesce((SELECT e.k FROM jsonb_each_text(y) e(k, val) WHERE e.val = r.reader_id::text LIMIT 1), '?')
                             || ':' || r.what
                             || '@' || CASE r.org_id WHEN (y->>'U')::uuid THEN 'U' WHEN (y->>'F')::uuid THEN 'F' ELSE '?' END,
                             ',' ORDER BY r.read_at, r.what), '')
    FROM passport_union_read r WHERE r.player_id = (y->>'B')::uuid
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- And the access-log rows at his school the union reads wrote.
CREATE OR REPLACE FUNCTION _v124_access(y jsonb) RETURNS int AS $$
  SELECT count(*)::int FROM access_log a
   WHERE a.resource = 'passport_union' AND (y->>'B')::uuid = ANY (a.record_ids)
     AND a.school_id = '11111111-1111-1111-1111-111111111111'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A consent naming the far union that the insert policy would refuse,
-- written as the owner in his mother's name (the stamp trigger names her):
-- the read arm must still ask whether the union is his.
CREATE OR REPLACE FUNCTION _v124_far_consent(y jsonb) RETURNS uuid AS $$
DECLARE v uuid;
BEGIN
  PERFORM set_config('app.user_id', y->>'mum', true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'B')::uuid, (y->>'OU')::uuid) RETURNING id INTO v;
  PERFORM set_config('app.user_id', '', true);
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Where a union selector may be appointed, as the owner tries it: each
-- attempt in its own subtransaction, 'refused' or 'ok'.
CREATE OR REPLACE FUNCTION _v124_scope(y jsonb) RETURNS text AS $$
DECLARE k text; v text := ''; v_u uuid := (y->>'mum')::uuid;
BEGIN
  FOREACH k IN ARRAY ARRAY['school', 'team', 'platform', 'union'] LOOP
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id, team_code)
      VALUES (v_u, 'unionselector',
              CASE k WHEN 'school' THEN '11111111-1111-1111-1111-111111111111'::uuid WHEN 'platform' THEN NULL ELSE (y->>'U')::uuid END,
              CASE k WHEN 'team' THEN '1XI' END);
      v := v || k || ':ok,';
      RAISE EXCEPTION 'v124_undo';
    EXCEPTION
      WHEN check_violation THEN v := v || k || ':refused,';
      WHEN raise_exception THEN NULL;
    END;
  END LOOP;
  RETURN rtrim(v, ',');
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- §101's second part (db/124 §5, Kameel 30 Oct 2026), as the owner:
--   E, a Hilton 1XI boy eighteen today, whose own account (eself: player and
--     self-access, both from four years ago) named his union three years ago,
--     at fifteen, before db/122 shut that door (written here past the writer
--     policy, as the owner, in his name, and dated back).
--   R, a Hilton 16XI boy of nineteen, at Hilton from three years ago, whose
--     guardian (rg, linked from three years ago) named his union two years
--     ago. _v124_away() then has him leave eighteen months ago, at seventeen,
--     as the move route would (his membership closed, and db/62's close on
--     leaving: his link ends on his eighteenth birthday, a year ago);
--     _v124_back() has him return today (a new membership, and db/62's
--     reopening in place). The deferred triggers that call those two would
--     fire only at commit, and this file rolls back, so they are called here.
-- The people and their links are made HERE, as the owner, before the
-- sections run, and not in the section: setting aside role_assignment's date
-- stamp is an ALTER TABLE, which Postgres refuses once earlier sections have
-- left deferred trigger events pending on the table. Their ids wait in a
-- transaction-local setting for _v124_stage5().
CREATE OR REPLACE FUNCTION _v124_prelinks() RETURNS void AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  t date := sa_today();
  c_e uuid; c_e2 uuid; c_e3 uuid; c_r uuid; v_a uuid; v_s text; ids jsonb;
BEGIN
  PERFORM set_config('app.user_id', '', true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyFour Elder', 1243, 'batter', (t - interval '18 years 1 month')::date) RETURNING id INTO c_e;
  -- N2: E2 is eighteen today, his birthday itself; E3 is eighteen tomorrow.
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyFour Birthday', 1245, 'batter', (t - interval '18 years')::date) RETURNING id INTO c_e2;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyFour Eve', 1246, 'batter', ((t - interval '18 years')::date + 1)) RETURNING id INTO c_e3;
  PERFORM set_config('app.effective_on', (t - interval '3 years')::date::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '16XI', 'Verify OneTwentyFour Returner', 1244, 'bowler', (t - interval '19 years 2 months')::date) RETURNING id INTO c_r;
  PERFORM set_config('app.effective_on', '', true);
  ids := _v71_people('v124b', ARRAY[
    ARRAY['eself',  'player',   HIL::text, '1XI', c_e::text],
    ARRAY['e2self', 'player',   HIL::text, '1XI', c_e2::text],
    ARRAY['e3self', 'player',   HIL::text, '1XI', c_e3::text]]);
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v124b.rg@example.invalid', 'V124B Rg', 'guardian')
  RETURNING id INTO v_a;
  ids := ids || jsonb_build_object('rg', v_a, 'E', c_e, 'E2', c_e2, 'E3', c_e3, 'R', c_r);
  -- The two links are dated back, so a consent dated back is no older than
  -- them (db/122 Q4). An appointment's own date is stamped by its trigger
  -- (db/01: who and when are not the writer's to say), so it is set aside
  -- for these two rows, as the owner, and put back.
  ALTER TABLE role_assignment DISABLE TRIGGER role_assignment_granter;
  -- E's own link, from four years ago.
  INSERT INTO role_assignment (person_id, role, school_id, created_at, created_by)
  VALUES ((ids->>'eself')::uuid, 'selfaccess', HIL, now() - interval '4 years', OFFICE) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, created_at)
  VALUES (v_a, c_e, 'self', 'verified', OFFICE, now() - interval '4 years', 'granted', 'popia-2026-01', now() - interval '4 years',
          OFFICE, (t - interval '4 years')::date, now() - interval '4 years');
  -- E2's and E3's own links, from four years ago too.
  FOREACH v_s IN ARRAY ARRAY['E2', 'E3'] LOOP
    INSERT INTO role_assignment (person_id, role, school_id, created_at, created_by)
    VALUES ((ids->>(lower(v_s) || 'self'))::uuid, 'selfaccess', HIL, now() - interval '4 years', OFFICE) RETURNING id INTO v_a;
    INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                    consent_state, consent_version, consent_at, created_by, valid_from, created_at)
    VALUES (v_a, (ids->>v_s)::uuid, 'self', 'verified', OFFICE, now() - interval '4 years', 'granted', 'popia-2026-01',
            now() - interval '4 years', OFFICE, (t - interval '4 years')::date, now() - interval '4 years');
  END LOOP;
  -- R's guardian's link, from three years ago, open (he is at school).
  INSERT INTO role_assignment (person_id, role, school_id, created_at, created_by)
  VALUES ((ids->>'rg')::uuid, 'guardian', HIL, now() - interval '3 years', OFFICE) RETURNING id INTO v_a;
  ALTER TABLE role_assignment ENABLE TRIGGER role_assignment_granter;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, valid_until, created_at)
  VALUES (v_a, c_r, 'parent', 'verified', OFFICE, now() - interval '3 years', 'granted', 'popia-2026-01', now() - interval '3 years',
          OFFICE, (t - interval '3 years')::date, NULL, now() - interval '3 years');
  PERFORM set_config('v124.pre', ids::text, true);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
DO $v124$ BEGIN PERFORM _v124_prelinks(); END $v124$;

-- E names his union at fifteen; R's guardian names it two years ago: each
-- consent written as the owner in the giver's name, and dated back.
CREATE OR REPLACE FUNCTION _v124_stage5(y jsonb) RETURNS jsonb AS $$
DECLARE ids jsonb := current_setting('v124.pre')::jsonb; v_pe uuid; v_pr uuid; v_pe3 uuid;
BEGIN
  PERFORM set_config('app.user_id', ids->>'eself', true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((ids->>'E')::uuid, (y->>'U')::uuid) RETURNING id INTO v_pe;
  PERFORM set_config('app.user_id', ids->>'rg', true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((ids->>'R')::uuid, (y->>'U')::uuid) RETURNING id INTO v_pr;
  -- N2: E3 names his union himself today, the day before his eighteenth
  -- birthday (past the writer policy, which would refuse him).
  PERFORM set_config('app.user_id', ids->>'e3self', true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((ids->>'E3')::uuid, (y->>'U')::uuid) RETURNING id INTO v_pe3;
  PERFORM set_config('app.user_id', '', true);
  UPDATE passport_consent SET granted_at = now() - interval '3 years' WHERE id = v_pe;
  UPDATE passport_consent SET granted_at = now() - interval '2 years' WHERE id = v_pr;
  RETURN ids || jsonb_build_object('pc_e', v_pe, 'pc_r', v_pr, 'pc_e3', v_pe3);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- R leaves eighteen months ago, at seventeen: the move closes his
-- membership, and db/62 dates his guardians' links to the later of that day
-- and his eighteenth birthday.
CREATE OR REPLACE FUNCTION _v124_away(y jsonb) RETURNS text AS $$
DECLARE v_left date := sa_today() - 548;
BEGIN
  PERFORM set_config('app.user_id', '', true);
  UPDATE team_membership SET left_on = v_left WHERE player_id = (y->>'R')::uuid AND left_on IS NULL;
  PERFORM guardian_links_close_on_leaving((y->>'R')::uuid, v_left);
  RETURN (SELECT string_agg(coalesce((s.valid_until - sa_today())::text, 'open'), ',') FROM assignment_subject s
           WHERE s.player_id = (y->>'R')::uuid);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- R comes back today: a new membership at Hilton, and db/62's reopening.
CREATE OR REPLACE FUNCTION _v124_back(y jsonb) RETURNS text AS $$
BEGIN
  PERFORM set_config('app.user_id', '', true);
  INSERT INTO team_membership (player_id, school_id, team_code, joined_on, reason)
  VALUES ((y->>'R')::uuid, '11111111-1111-1111-1111-111111111111', '16XI', sa_today(), 'joined');
  PERFORM guardian_links_reopen_at_school((y->>'R')::uuid);
  RETURN (SELECT string_agg(coalesce((s.valid_until - sa_today())::text, 'open'), ',') FROM assignment_subject s
           WHERE s.player_id = (y->>'R')::uuid);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The office corrects a guardian's end date in place (db/122 §1d Q4): the
-- same link, live again.
CREATE OR REPLACE FUNCTION _v124_correct(p_person uuid, p_player uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET valid_until = NULL
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/124 (section 101) ─────────────────────────────────────────────
-- ┌── db/125 (section 102). The union selector's list (Kameel, 30 Oct 2026)
-- Invented, as the owner; every name is a placeholder.
--   U, the KwaZulu-Natal union and F, the federation (CSA Schools), found or
--     made as section 101 does; OU, a union of another province.
--   SA and SB, two KwaZulu-Natal schools of its own; FAR, a school in OU's
--     province. HIL and WES are the seed's.
--   At SA: PA (U15A, "Kilo"), PD (U15A, "Echo"), PA2 (U15B, "Lima") and PN
--     (U14A, "Mike"); at SB: PB (U15A, "Oscar") and PC (U16A, "Papa"); at
--     FAR: PX (U15A, "Xray"). Each of fifteen, with a guardian of his own
--     (ga, gd, ga2, gn, gb, gc, gx); PA also with his own account (paself:
--     player and self-access).
--   sel, a union selector at U; fsel, one at CSA Schools; both, one at U and
--     at CSA Schools (two assignments); org, a competition organiser at U;
--     plat, a selector at U who also holds a platform-wide organiser's
--     assignment; sup, a selector at U in a support session at U; selcoach,
--     a selector at U who coaches SA's U15A; selpar, a selector at U who is
--     PA's guardian; scout, an accredited scout at SA and SB, with three
--     fixtures of overs each for PA and PD (SA) and PB (SB); aoffice, SA's
--     school administrator.
--   For the seams audit's call 1 (Kameel, 30 Oct 2026, 21:53 SAST): G, a
--     Hilton 1XI boy who turned eighteen a month ago, still at school, and
--     gg, his guardian on a link open from a year ago (made by
--     _v125_prelinks(), before the sections, as section 101's are).
-- The consents are named in the section, each by his own family.
CREATE OR REPLACE FUNCTION _v125_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  WES uuid := '22222222-2222-2222-2222-222222222222';
  U15 date := make_date(extract(year FROM sa_today())::int - 15, 3, 1);
  U uuid; OU uuid; F uuid; SA uuid; SB uuid; FAR uuid;
  c_a uuid; c_d uuid; c_a2 uuid; c_n uuid; c_b uuid; c_c uuid; c_x uuid; v_a uuid; ids jsonb; i int;
BEGIN
  PERFORM set_config('app.user_id', '', true);
  SELECT s.id INTO U FROM school s WHERE s.kind = 'union' AND lower(btrim(s.province)) = 'kwazulu-natal' AND s.archived_at IS NULL;
  IF U IS NULL THEN
    INSERT INTO school (code, name, kind, province) VALUES ('V125U', 'Verify OneTwentyFive KZN Union', 'union', 'KwaZulu-Natal')
    RETURNING id INTO U;
  END IF;
  SELECT s.id INTO F FROM school s WHERE s.kind = 'federation';
  IF F IS NULL THEN
    INSERT INTO school (code, name, kind) VALUES ('V125F', 'Verify OneTwentyFive CSA Schools', 'federation') RETURNING id INTO F;
  END IF;
  INSERT INTO school (code, name, kind, province) VALUES ('V125OU', 'Verify OneTwentyFive Far Union', 'union', 'Verify 125 Province')
  RETURNING id INTO OU;
  INSERT INTO school (code, name, kind, province) VALUES ('V125A', 'Verify OneTwentyFive Alpha School', 'school', 'KwaZulu-Natal')
  RETURNING id INTO SA;
  INSERT INTO school (code, name, kind, province) VALUES ('V125B', 'Verify OneTwentyFive Bravo School', 'school', 'KwaZulu-Natal')
  RETURNING id INTO SB;
  INSERT INTO school (code, name, kind, province) VALUES ('V125X', 'Verify OneTwentyFive Far School', 'school', 'Verify 125 Province')
  RETURNING id INTO FAR;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (SA, 'U15A', 'Verify OneTwentyFive Kilo', 1251, 'batter', U15) RETURNING id INTO c_a;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (SA, 'U15A', 'Verify OneTwentyFive Echo', 1252, 'bowler', U15) RETURNING id INTO c_d;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (SA, 'U15B', 'Verify OneTwentyFive Lima', 1253, 'batter', U15) RETURNING id INTO c_a2;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (SA, 'U14A', 'Verify OneTwentyFive Mike', 1254, 'batter', U15) RETURNING id INTO c_n;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (SB, 'U15A', 'Verify OneTwentyFive Oscar', 1255, 'batter', U15) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (SB, 'U16A', 'Verify OneTwentyFive Papa', 1256, 'bowler', U15) RETURNING id INTO c_c;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (FAR, 'U15A', 'Verify OneTwentyFive Xray', 1257, 'batter', U15) RETURNING id INTO c_x;
  ids := _v71_people('v125', ARRAY[
    ARRAY['ga',       'guardian',         SA::text,  '',     ''],
    ARRAY['gd',       'guardian',         SA::text,  '',     ''],
    ARRAY['ga2',      'guardian',         SA::text,  '',     ''],
    ARRAY['gn',       'guardian',         SA::text,  '',     ''],
    ARRAY['gb',       'guardian',         SB::text,  '',     ''],
    ARRAY['gc',       'guardian',         SB::text,  '',     ''],
    ARRAY['gx',       'guardian',         FAR::text, '',     ''],
    ARRAY['paself',   'player',           SA::text,  'U15A', c_a::text],
    ARRAY['sel',      'unionselector',    U::text,   '',     ''],
    ARRAY['fsel',     'unionselector',    F::text,   '',     ''],
    ARRAY['both',     'unionselector',    U::text,   '',     ''],
    ARRAY['org',      'competitionadmin', U::text,   '',     ''],
    ARRAY['plat',     'unionselector',    U::text,   '',     ''],
    ARRAY['sup',      'unionselector',    U::text,   '',     ''],
    ARRAY['selcoach', 'coach',            SA::text,  'U15A', ''],
    ARRAY['selpar',   'guardian',         SA::text,  '',     '']]);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES
    ((ids->>'both')::uuid, 'unionselector', F),
    ((ids->>'selcoach')::uuid, 'unionselector', U),
    ((ids->>'selpar')::uuid, 'unionselector', U);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'plat')::uuid, 'competitionadmin', NULL);
  -- The scout reads at both schools; the office is SA's.
  ids := ids || _v71_people('v125', ARRAY[
    ARRAY['scout',   'scout',       SA::text, '', ''],
    ARRAY['aoffice', 'schooladmin', SA::text, '', '']]);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'scout')::uuid, 'scout', SB);
  INSERT INTO scout_accreditation (person_id, organisation, scout_role, verification_status, verified_by, verified_at)
  VALUES ((ids->>'scout')::uuid, 'Verify 125 Union', 'regional_selector', 'verified', '88888888-0000-0000-0000-00000000000c', now());
  -- A body of work for PA and PD (an over each in three fixtures at SA) and
  -- PB (three at SB), so a scout's yes shows them.
  FOR i IN 1..3 LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
    VALUES (SA, 'U15A', 'Verify OneTwentyFive ' || i, now() - make_interval(days => 20 + i), 'cricket', 'T20', 20, 'scheduled')
    RETURNING id INTO v_a;
    PERFORM _v71_bowl(v_a, '88888888-0000-0000-0000-00000000000c', ARRAY[c_a, c_d]);
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
    VALUES (SB, 'U15A', 'Verify OneTwentyFive B' || i, now() - make_interval(days => 20 + i), 'cricket', 'T20', 20, 'scheduled')
    RETURNING id INTO v_a;
    PERFORM _v71_bowl(v_a, '88888888-0000-0000-0000-00000000000c', ARRAY[c_b]);
  END LOOP;
  -- sup's support hour at U, written as support_access_begin() would.
  INSERT INTO role_assignment (person_id, role, school_id, active, valid_from, expires_at)
  VALUES ((ids->>'sup')::uuid, 'schooladmin', U, true, current_date, now() + interval '1 hour') RETURNING id INTO v_a;
  INSERT INTO support_access (actor_id, school_id, role, reason, assignment_id, expires_at)
  VALUES ((ids->>'sup')::uuid, U, 'schooladmin', 'Verify 125: a support hour at the union', v_a, now() + interval '1 hour');
  PERFORM _v100_link((ids->>'ga')::uuid,  SA,  c_a);
  PERFORM _v100_link((ids->>'gd')::uuid,  SA,  c_d);
  PERFORM _v100_link((ids->>'ga2')::uuid, SA,  c_a2);
  PERFORM _v100_link((ids->>'gn')::uuid,  SA,  c_n);
  PERFORM _v100_link((ids->>'gb')::uuid,  SB,  c_b);
  PERFORM _v100_link((ids->>'gc')::uuid,  SB,  c_c);
  PERFORM _v100_link((ids->>'gx')::uuid,  FAR, c_x);
  PERFORM _v100_link((ids->>'selpar')::uuid, SA, c_a);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'paself')::uuid, 'selfaccess', SA) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, c_a, 'self', 'verified', '88888888-0000-0000-0000-00000000000c', now(), 'granted', 'popia-2026-01', now(),
          '88888888-0000-0000-0000-00000000000c', current_date - 1);
  RETURN ids || jsonb_build_object('U', U, 'OU', OU, 'F', F, 'SA', SA, 'SB', SB, 'FAR', FAR, 'HIL', HIL, 'WES', WES,
                                   'PA', c_a, 'PD', c_d, 'PA2', c_a2, 'PN', c_n, 'PB', c_b, 'PC', c_c, 'PX', c_x,
                                   'Uname', (SELECT s.name FROM school s WHERE s.id = U))
             || current_setting('v125.pre')::jsonb;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The key y gives an id, or '?'.
CREATE OR REPLACE FUNCTION _v125_key(y jsonb, p_id uuid) RETURNS text AS $$
  SELECT coalesce((SELECT e.k FROM jsonb_each_text(y) e(k, val) WHERE e.val = p_id::text ORDER BY e.k COLLATE "C" LIMIT 1), '?')
$$ LANGUAGE sql STABLE;

-- The caller's list, as the application asks it: key@institution, in the
-- list's own order. Run as the caller (not a definer), so it is the
-- application's call under the caller's app.user_id.
CREATE OR REPLACE FUNCTION _v125_list(y jsonb, p_org uuid, p_school uuid, p_age text, p_q text DEFAULT NULL) RETURNS text AS $$
  SELECT coalesce(string_agg(_v125_key(y, l.player_id) || '@' || _v125_key(y, l.org_id), ',' ORDER BY l.n), '')
    FROM passport_union_list(p_org, p_school, p_age, p_q) WITH ORDINALITY
         AS l(player_id, name, school_name, team_code, org_id, consent_id, n)
$$ LANGUAGE sql VOLATILE;

-- The institutions and the schools the caller is offered: keys, in order;
-- an id y does not know is left out of the schools (other sections' schools).
CREATE OR REPLACE FUNCTION _v125_orgs(y jsonb) RETURNS text AS $$
  SELECT coalesce(string_agg(_v125_key(y, o.org_id), ',' ORDER BY o.n), '')
    FROM passport_union_orgs() WITH ORDINALITY AS o(org_id, name, kind, n)
$$ LANGUAGE sql STABLE;
CREATE OR REPLACE FUNCTION _v125_schools(y jsonb, p_org uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(_v125_key(y, s.school_id), ',' ORDER BY s.n) FILTER (WHERE _v125_key(y, s.school_id) <> '?'), '')
    FROM passport_union_schools(p_org) WITH ORDINALITY AS s(school_id, name, n)
$$ LANGUAGE sql STABLE;

-- What the owner reads in the log of the caller's lists: key@institution per
-- 'list' row, sorted; and its access-log rows: school:keys+, sorted.
CREATE OR REPLACE FUNCTION _v125_reads(y jsonb, p_reader uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t COLLATE "C"), '') FROM (
    SELECT _v125_key(y, r.player_id) || '@' || _v125_key(y, r.org_id) AS t
      FROM passport_union_read r WHERE r.reader_id = p_reader AND r.what = 'list') x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v125_who(p_reader uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t COLLATE "C"), '') FROM (
    SELECT DISTINCT r.reader_name || ' (' || r.reader_role || ')' AS t
      FROM passport_union_read r WHERE r.reader_id = p_reader AND r.what = 'list') x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v125_consents(p_reader uuid) RETURNS uuid[] AS $$
  SELECT coalesce(array_agg(r.consent_id ORDER BY r.consent_id), '{}')
    FROM passport_union_read r WHERE r.reader_id = p_reader AND r.what = 'list'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
CREATE OR REPLACE FUNCTION _v125_access(y jsonb, p_reader uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t COLLATE "C"), '') FROM (
    SELECT _v125_key(y, a.school_id) || ':'
           || (SELECT string_agg(_v125_key(y, i), '+' ORDER BY _v125_key(y, i) COLLATE "C") FROM unnest(a.record_ids) i) AS t
      FROM access_log a
     WHERE a.person_id = p_reader AND a.resource = 'passport_union' AND a.fields = ARRAY['list']) x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Every list row and list access row, whoever wrote them: "nothing logged".
CREATE OR REPLACE FUNCTION _v125_total() RETURNS text AS $$
  SELECT (SELECT count(*) FROM passport_union_read r WHERE r.what = 'list')::text || '/'
      || (SELECT count(*) FROM access_log a WHERE a.resource = 'passport_union' AND a.fields = ARRAY['list'])::text
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- One boy's 'list' rows, as the owner counts them.
CREATE OR REPLACE FUNCTION _v125_rows_of(p_player uuid) RETURNS int AS $$
  SELECT count(*)::int FROM passport_union_read r WHERE r.player_id = p_player AND r.what = 'list'
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- (a)'s cross-check, written out independently of db/125: the boys with an
-- in-force consent (db/124's test) to p_org, at which p_reader holds a live
-- union selector's appointment, through the same filters.
CREATE OR REPLACE FUNCTION _v125_direct(p_reader uuid, p_org uuid, p_school uuid, p_age text) RETURNS int AS $$
  SELECT count(DISTINCT p.id)::int
    FROM player p
    JOIN passport_consent c ON c.player_id = p.id
    JOIN school o ON o.id = c.to_school_id
   WHERE o.id = p_org AND c.withdrawn_at IS NULL
     AND consent_giver_live(c.granted_by, c.player_id, c.granted_at)
     AND o.archived_at IS NULL
     AND ((o.kind = 'union' AND o.id = school_union(p.school_id))
          OR (o.kind = 'federation' AND o.id = school_federation()))
     AND (p_school IS NULL OR p.school_id = p_school)
     AND (p_age IS NULL OR left(p.team_code, 3) = p_age)
     AND EXISTS (SELECT 1 FROM role_assignment a
                  WHERE a.person_id = p_reader AND a.role = 'unionselector' AND a.school_id = o.id AND a.active)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- passport_union_consent() as the owner, for the caller in app.user_id: the
-- consent the passport would log under (D4).
CREATE OR REPLACE FUNCTION _v125_union_consent(p_player uuid) RETURNS uuid AS $$
  SELECT passport_union_consent(p_player)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A consent made later than it was: one minute ahead, so the other is the
-- earlier (D4). Its giver's link is older than both.
CREATE OR REPLACE FUNCTION _v125_later(p_consent uuid) RETURNS void AS $$
  UPDATE passport_consent SET granted_at = now() + interval '1 minute' WHERE id = p_consent;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A guardian's link that ended yesterday (SAST), as the office's end date writes it.
CREATE OR REPLACE FUNCTION _v125_ended_yesterday(p_person uuid, p_player uuid) RETURNS void AS $$
  UPDATE assignment_subject s SET valid_until = sa_today() - 1
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player;
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- PX's guardian names a union not his (U), written as the owner in his name,
-- past the insert policy, which would refuse it: the list must ask too.
CREATE OR REPLACE FUNCTION _v125_far_consent(y jsonb) RETURNS uuid AS $$
DECLARE v uuid;
BEGIN
  PERFORM set_config('app.user_id', y->>'gx', true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PX')::uuid, (y->>'U')::uuid) RETURNING id INTO v;
  PERFORM set_config('app.user_id', '', true);
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- G and his guardian's link, from a year ago, as the owner: setting aside
-- role_assignment's date stamp is an ALTER TABLE, refused once sections have
-- left deferred trigger events pending, so this runs before them (as
-- section 101's _v124_prelinks() does). Ids wait in v125.pre.
CREATE OR REPLACE FUNCTION _v125_prelinks() RETURNS void AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  t date := sa_today();
  c_g uuid; v_u uuid; v_a uuid;
BEGIN
  PERFORM set_config('app.user_id', '', true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyFive Golf', 1258, 'batter', (t - interval '18 years 1 month')::date) RETURNING id INTO c_g;
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v125.gg@example.invalid', 'V125 Gg', 'guardian')
  RETURNING id INTO v_u;
  ALTER TABLE role_assignment DISABLE TRIGGER role_assignment_granter;
  INSERT INTO role_assignment (person_id, role, school_id, created_at, created_by)
  VALUES (v_u, 'guardian', HIL, now() - interval '1 year', OFFICE) RETURNING id INTO v_a;
  ALTER TABLE role_assignment ENABLE TRIGGER role_assignment_granter;
  -- Open past his birthday: he is at school (db/62).
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, valid_until, created_at)
  VALUES (v_a, c_g, 'parent', 'verified', OFFICE, now() - interval '1 year', 'granted', 'popia-2026-01', now() - interval '1 year',
          OFFICE, (t - interval '1 year')::date, NULL, now() - interval '1 year');
  PERFORM set_config('v125.pre', jsonb_build_object('G', c_g, 'gg', v_u)::text, true);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
DO $v125$ BEGIN PERFORM _v125_prelinks(); END $v125$;

-- A passport consent in p_giver's name, written as the owner past the write
-- policy, and dated p_at: what a row given on that day looks like.
CREATE OR REPLACE FUNCTION _v125_consent_as(p_giver uuid, p_player uuid, p_org uuid, p_at timestamptz) RETURNS uuid AS $$
DECLARE v uuid;
BEGIN
  PERFORM set_config('app.user_id', p_giver::text, true);
  INSERT INTO passport_consent (player_id, to_school_id) VALUES (p_player, p_org) RETURNING id INTO v;
  PERFORM set_config('app.user_id', '', true);
  UPDATE passport_consent SET granted_at = p_at WHERE id = v;
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A guardian withdraws processing consent on her link (db/00's
-- assignment_subject.consent_state), as the owner records it.
CREATE OR REPLACE FUNCTION _v125_processing_withdrawn(p_person uuid, p_player uuid) RETURNS int AS $$
DECLARE v int;
BEGIN
  UPDATE assignment_subject s SET consent_state = 'withdrawn'
    FROM role_assignment a
   WHERE a.id = s.assignment_id AND a.person_id = p_person AND a.role = 'guardian' AND s.player_id = p_player;
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The scout's access-log rows, as the owner reads them: school:keys+, sorted.
CREATE OR REPLACE FUNCTION _v125_scout_access(y jsonb, p_reader uuid) RETURNS text AS $$
  SELECT coalesce(string_agg(t, ',' ORDER BY t COLLATE "C"), '') FROM (
    SELECT _v125_key(y, a.school_id) || ':'
           || (SELECT string_agg(_v125_key(y, i), '+' ORDER BY _v125_key(y, i) COLLATE "C") FROM unnest(a.record_ids) i) AS t
      FROM access_log a
     WHERE a.person_id = p_reader AND a.resource = 'scouting_candidates' AND a.fields = ARRAY['full_name']) x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/125 (section 102) ─────────────────────────────────────────────

-- ┌── db/127 (section 104). RECOGNITION R3: the fixture class (Q1–Q3)
-- _v127_stage(): Hilton's three competitions, one of each comp_type, its
-- 1st XI entered in each, and the fixtures section 104 reads, each with a
-- log written as the owner (_first24_73() and _ev_73(), db/73's):
--   fr  a friendly, won in the chase              friendly / none
--   lg  the league's, the same                    competitive / none
--   ko  the knockout's, the same                  competitive / none
--   fe  the festival's, the same                  festival / none
--   ab  the league's, abandoned, nothing bowled   competitive / abandoned
--   nr  the festival's, complete, the chase never finished   festival / no_result
--   at  a friendly, the chase terminated above the umpires' par   friendly / adjusted_target
--   wo  the knockout's, a walkover before a ball  competitive / decided_off_field
--   aw  the knockout's, tied, an award naming who goes through   competitive / none
--   lv  the league's, the first innings under way competitive / none yet
CREATE OR REPLACE FUNCTION _v127_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  DEC uuid := '88888888-0000-0000-0000-000000000006';
  T timestamptz := '2026-10-17 10:00+02';
  lg_c uuid; ko_c uuid; fe_c uuid; c uuid;
  y jsonb := '{}'; k text; x uuid;
BEGIN
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 127 League', 'league', 'T20', 'school') RETURNING id INTO lg_c;
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 127 Cup', 'knockout', 'T20', 'school') RETURNING id INTO ko_c;
  INSERT INTO competition (school_id, name, comp_type, format, level) VALUES (HIL, 'Verify 127 Festival', 'festival', 'T20', 'school') RETURNING id INTO fe_c;
  INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name)
  SELECT z, HIL, '1XI', 'Verify 127 Hilton 1st XI' FROM unnest(ARRAY[lg_c, ko_c, fe_c]) z;
  FOR k, c IN SELECT * FROM (VALUES ('fr', NULL::uuid), ('lg', lg_c), ('ko', ko_c), ('fe', fe_c), ('ab', lg_c), ('nr', fe_c),
                                    ('at', NULL), ('wo', ko_c), ('aw', ko_c), ('lv', lg_c)) v LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, competition_id)
    VALUES (HIL, '1XI', 'Verify 127 ' || k, T, 'cricket', 'T20', 2,
            CASE k WHEN 'ab' THEN 'abandoned' WHEN 'wo' THEN 'scheduled' WHEN 'lv' THEN 'live' ELSE 'complete' END, c)
    RETURNING id INTO x;
    y := y || jsonb_build_object(k, x, 'c_' || k, c);
    IF k IN ('fr', 'lg', 'ko', 'fe', 'nr', 'at', 'aw') THEN
      INSERT INTO match_conditions (match_id, set_id, set_version, doc, sources, doc_hash)
      SELECT x, r.set_id, r.set_version, r.doc, r.sources, '' FROM match_conditions_compute(x) r;
      -- The home side's 24 off two overs, sealed; the chase's innings begun.
      PERFORM _first24_73(x, 2, 25);
    END IF;
    IF k IN ('fr', 'lg', 'ko', 'fe') THEN
      -- The chase: 25 off 7, the target reached.
      PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 4, '{}', NULL, NULL, 6);
      PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 1, '{}');
      PERFORM _ev_73(x, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"target_reached","confirmed":{"runs":25,"wickets":0,"balls":7}}');
    ELSIF k = 'nr' THEN
      -- The chase: 6 off 6, and nothing more; the match marked complete.
      PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 6);
    ELSIF k = 'at' THEN
      -- The chase: 15 off 9, rain, the umpires' par 13, terminated: won by 2 on par.
      PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 2, '{}', NULL, NULL, 6);
      PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 3);
      PERFORM _ev_73(x, 1::smallint, 'play_stopped', NULL, NULL, '{"reason":"rain"}');
      PERFORM _ev_73(x, 1::smallint, 'revision', NULL, NULL, '{"overs":null,"target":null,"reason":"rain","par":13}');
      PERFORM _ev_73(x, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"abandoned","confirmed":{"runs":15,"wickets":0,"balls":9}}');
    ELSIF k = 'aw' THEN
      -- The chase: 24 off 12, all its overs: a tie; the organiser names who goes through.
      PERFORM _ev_73(x, 1::smallint, 'ball', 'run', 2, '{}', NULL, NULL, 12);
      PERFORM _ev_73(x, 1::smallint, 'innings_end', NULL, NULL, '{"reason":"overs_complete","confirmed":{"runs":24,"wickets":0,"balls":12}}');
      INSERT INTO match_result_decision (match_id, kind, side, reason, overrides_play, decided_by)
      VALUES (x, 'awarded', 'home', 'Verify 127: fewer wickets lost in the tie, under the cup''s rules', false, DEC);
    ELSIF k = 'wo' THEN
      INSERT INTO match_result_decision (match_id, kind, side, reason, overrides_play, decided_by)
      VALUES (x, 'walkover', 'home', 'Verify 127: the visitors did not arrive', false, DEC);
    ELSIF k = 'lv' THEN
      PERFORM _ev_73(x, 0::smallint, 'innings_start', NULL, NULL, '{"battingTeam":"1XI","bowlingTeam":"Verify 127 lv","overs":2}');
      PERFORM _ev_73(x, 0::smallint, 'ball', 'run', 1, '{}', NULL, NULL, 3);
    END IF;
  END LOOP;
  RETURN y;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- fixture_class() as its owner reads it: "class/reason", "-" for none.
CREATE OR REPLACE FUNCTION _v127_class(p_match uuid) RETURNS text AS $$
  SELECT f.fixture_class || '/' || coalesce(f.no_board, '-') FROM fixture_class(p_match) f
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- match_result_compute()'s outcome and play's, as the owner reads them.
CREATE OR REPLACE FUNCTION _v127_outcome(p_match uuid) RETURNS text AS $$
  SELECT r.outcome || '/' || r.play_outcome || '/' || r.decision_applied FROM match_result_compute(p_match) r
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The standing decision on a match withdrawn, with its note, as the owner.
CREATE OR REPLACE FUNCTION _v127_withdraw(p_match uuid) RETURNS void AS $$
  UPDATE match_result_decision
     SET withdrawn_at = now(), withdrawn_by = '88888888-0000-0000-0000-000000000006',
         withdrawn_note = 'Verify 127: entered against the wrong fixture'
   WHERE match_id = p_match AND withdrawn_at IS NULL
$$ LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- A competition written as the owner, with the type given: 'ok', or the
-- constraint that refused it. Nothing it writes outlives the call.
CREATE OR REPLACE FUNCTION _v127_comp(p_type text, p_update uuid DEFAULT NULL) RETURNS text AS $$
DECLARE v_c text;
BEGIN
  BEGIN
    IF p_update IS NULL THEN
      INSERT INTO competition (school_id, name, comp_type, format, level)
      VALUES ('11111111-1111-1111-1111-111111111111', 'Verify 127 Probe', p_type, 'T20', 'school');
    ELSE
      UPDATE competition SET comp_type = p_type WHERE id = p_update;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'P0127', MESSAGE = 'ok';
  EXCEPTION
    WHEN check_violation THEN GET STACKED DIAGNOSTICS v_c = CONSTRAINT_NAME; RETURN v_c;
    WHEN SQLSTATE 'P0127' THEN RETURN 'ok';
  END;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/127 (section 104) ─────────────────────────────────────────────

-- ┌── db/128 (section 105). The SA day (Season rollover, the quiet-week item)
-- A pinned clock. now() cannot move inside one transaction, and sa_today()
-- is the one door every body db/128 re-emitted reads the day by, so it is
-- re-created, as the owner, to read the instant in v128.at (now() when that
-- is empty), and put back as it was (its definition kept in v128.sa_today).
-- Re-created once, before any probe below runs: a SQL body another body
-- inlined is cached with it for the transaction, so the pin moves by the
-- setting, never by a second re-creation. The session runs at UTC, so
-- current_date is the UTC day of both pinned instants: what a body still on
-- current_date would read at that moment.
CREATE OR REPLACE FUNCTION _v128_clock(p_at timestamptz) RETURNS date AS $$
BEGIN
  IF coalesce(current_setting('v128.sa_today', true), '') = '' THEN
    PERFORM set_config('v128.sa_today', pg_get_functiondef('sa_today()'::regprocedure), true);
    CREATE OR REPLACE FUNCTION public.sa_today() RETURNS date LANGUAGE sql STABLE AS
      $f$ SELECT (coalesce(nullif(current_setting('v128.at', true), '')::timestamptz, now()) AT TIME ZONE 'Africa/Johannesburg')::date $f$;
  END IF;
  IF p_at IS NULL THEN
    EXECUTE current_setting('v128.sa_today');
    PERFORM set_config('v128.sa_today', '', true);
  END IF;
  PERFORM set_config('v128.at', coalesce(p_at::text, ''), true);
  RETURN sa_today();
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- Break is_family_of() back to the database's day (db/119's clock), or mend
-- it to db/128's, as the owner: the guard section 105 must be seen to catch.
CREATE OR REPLACE FUNCTION _v128_break(p_broken boolean) RETURNS text AS $$
DECLARE v_def text := pg_get_functiondef('is_family_of(uuid)'::regprocedure);
BEGIN
  IF p_broken THEN
    EXECUTE replace(v_def, 'sa_today()', 'current_date');
  ELSE
    EXECUTE regexp_replace(v_def, '\mcurrent_date\M', 'sa_today()', 'g');
  END IF;
  RETURN md5(regexp_replace(btrim((SELECT prosrc FROM pg_proc WHERE oid = 'is_family_of(uuid)'::regprocedure)), '\s+', ' ', 'g'));
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The people and links whose days end or begin at N+1 (N: the UTC day the
-- run starts on), written as the owner in the office's name when section 105
-- starts, so no section before it sees them.
--   uE  a 1XI coach whose appointment ends N+1;  uS  one whose begins N+1
--   gE  K's guardian, the link ending N+1;       gS  K's guardian from N+1
--   K   a boy of thirteen; M  a boy eighteen on N+1
--   uE's police clearance expires on N
CREATE OR REPLACE FUNCTION _v128_setup() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  n date := (now() AT TIME ZONE 'UTC')::date;
  v_k uuid; v_m uuid; v_ue uuid; v_us uuid; v_ge uuid; v_gs uuid; v_a uuid; v_le uuid; v_ls uuid;
BEGIN
  PERFORM set_config('app.user_id', OFFICE::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyEight Kilo', 1281, 'batter', (n - interval '13 years 2 months')::date) RETURNING id INTO v_k;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, '1XI', 'Verify OneTwentyEight Mike', 1282, 'batter', (n + 1 - interval '18 years')::date) RETURNING id INTO v_m;
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v128.ue@example.invalid', 'V128 Ue', 'coach') RETURNING id INTO v_ue;
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v128.us@example.invalid', 'V128 Us', 'coach') RETURNING id INTO v_us;
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v128.ge@example.invalid', 'V128 Ge', 'guardian') RETURNING id INTO v_ge;
  INSERT INTO app_user (school_id, email, name, role) VALUES (HIL, 'v128.gs@example.invalid', 'V128 Gs', 'guardian') RETURNING id INTO v_gs;
  INSERT INTO role_assignment (person_id, role, school_id, team_code, valid_from, valid_until)
  VALUES (v_ue, 'coach', HIL, '1XI', n - 300, n + 1),
         (v_us, 'coach', HIL, '1XI', n + 1, NULL);
  INSERT INTO role_assignment (person_id, role, school_id) VALUES (v_ge, 'guardian', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, valid_until, created_at)
  VALUES (v_a, v_k, 'parent', 'verified', OFFICE, now() - interval '1 year', 'granted', 'popia-2026-01', now() - interval '1 year',
          OFFICE, n - 300, n + 1, now() - interval '1 year') RETURNING id INTO v_le;
  INSERT INTO role_assignment (person_id, role, school_id) VALUES (v_gs, 'guardian', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from, valid_until, created_at)
  VALUES (v_a, v_k, 'parent', 'verified', OFFICE, now() - interval '1 year', 'granted', 'popia-2026-01', now() - interval '1 year',
          OFFICE, n + 1, NULL, now() - interval '1 year') RETURNING id INTO v_ls;
  INSERT INTO adult_clearance (person_id, school_id, kind, issued_on, expires_on, verified_by)
  VALUES (v_ue, HIL, 'police_clearance', n - 100, n, OFFICE);
  PERFORM set_config('app.user_id', '', true);
  RETURN jsonb_build_object('n', n, 'K', v_k, 'M', v_m, 'ue', v_ue, 'us', v_us, 'ge', v_ge, 'gs', v_gs, 'le', v_le, 'ls', v_ls);
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the bodies the application may not call answer, as the owner, in one
-- line (t/f for each, in this order):
--   person_live_at uE,uS · lift_live_link gE,gS · public_name_live_link gE,gS ·
--   health_giver_link_live gE,gS · lift_link_is_live gE,gS ·
--   uE's clearance · M a minor (player_guardian_status) · the day a link is
--   stamped with when its writer names none (assignment_subject's default)
CREATE OR REPLACE FUNCTION _v128_owner_facts(y jsonb) RETURNS text AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  b text := ''; v_stamp date; v_a uuid;
BEGIN
  b := b || CASE WHEN person_live_at((y->>'ue')::uuid, HIL, ARRAY['coach']) THEN 't' ELSE 'f' END
         || CASE WHEN person_live_at((y->>'us')::uuid, HIL, ARRAY['coach']) THEN 't' ELSE 'f' END || ' '
         || CASE WHEN EXISTS (SELECT 1 FROM lift_live_link((y->>'ge')::uuid, (y->>'K')::uuid, 'guardian')) THEN 't' ELSE 'f' END
         || CASE WHEN EXISTS (SELECT 1 FROM lift_live_link((y->>'gs')::uuid, (y->>'K')::uuid, 'guardian')) THEN 't' ELSE 'f' END || ' '
         || CASE WHEN EXISTS (SELECT 1 FROM public_name_live_link((y->>'ge')::uuid, (y->>'K')::uuid, 'guardian')) THEN 't' ELSE 'f' END
         || CASE WHEN EXISTS (SELECT 1 FROM public_name_live_link((y->>'gs')::uuid, (y->>'K')::uuid, 'guardian')) THEN 't' ELSE 'f' END || ' '
         || CASE WHEN health_giver_link_live((y->>'le')::uuid) THEN 't' ELSE 'f' END
         || CASE WHEN health_giver_link_live((y->>'ls')::uuid) THEN 't' ELSE 'f' END || ' '
         || CASE WHEN lift_link_is_live((y->>'le')::uuid) THEN 't' ELSE 'f' END
         || CASE WHEN lift_link_is_live((y->>'ls')::uuid) THEN 't' ELSE 'f' END || ' '
         || coalesce((SELECT c.status FROM clearance_status((y->>'ue')::uuid, HIL, 'police_clearance') c LIMIT 1), '-') || ' '
         || coalesce((SELECT CASE WHEN g.is_minor THEN 'minor' ELSE 'adult' END FROM player_guardian_status g
                       WHERE g.player_id = (y->>'M')::uuid), '-');
  -- The stamp: a link written with no valid_from, read back and taken away.
  SELECT s.assignment_id INTO v_a FROM assignment_subject s WHERE s.id = (y->>'ls')::uuid;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, created_by)
  VALUES (v_a, (y->>'M')::uuid, 'parent', 'pending', OFFICE) RETURNING valid_from INTO v_stamp;
  DELETE FROM assignment_subject WHERE assignment_id = v_a AND player_id = (y->>'M')::uuid;
  RETURN b || ' ' || CASE v_stamp WHEN (y->>'n')::date THEN 'N' WHEN (y->>'n')::date + 1 THEN 'N+1' ELSE v_stamp::text END;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- What the four read for themselves, as the application (pairs):
--   uE, uS: app_holds('availability.read'), app_can() at his 1XI
--   gE, gS: is_family_of(K), app_can() on K's emergency details (his link)
-- Invoker: each read runs under the caller's own session.
CREATE OR REPLACE FUNCTION _v128_app(y jsonb) RETURNS text AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  b text := ''; u text;
BEGIN
  FOREACH u IN ARRAY ARRAY['ue', 'us'] LOOP
    PERFORM set_config('app.user_id', y->>u, true);
    b := b || CASE WHEN app_holds('availability.read') THEN 't' ELSE 'f' END
           || CASE WHEN app_can('availability.read', HIL, '1XI', NULL, NULL) THEN 't' ELSE 'f' END || ' ';
  END LOOP;
  FOREACH u IN ARRAY ARRAY['ge', 'gs'] LOOP
    PERFORM set_config('app.user_id', y->>u, true);
    b := b || CASE WHEN is_family_of((y->>'K')::uuid) THEN 't' ELSE 'f' END
           || CASE WHEN app_can('player.emergency.read', HIL, NULL, (y->>'K')::uuid, NULL) THEN 't' ELSE 'f' END || ' ';
  END LOOP;
  PERFORM set_config('app.user_id', '', true);
  RETURN btrim(b);
END $$ LANGUAGE plpgsql;
-- └── db/128 (section 105) ─────────────────────────────────────────────

-- ┌── db/129 (section 106). The moved boy's own reach is dated: his `player`
-- assignment reads his side only from the day he joined it (Season rollover,
-- S2's last slice; D1, Q2). Invented, as the owner; every name a
-- placeholder. Hilton's U15F (the side he leaves, the design's "U14A";
-- labels say 23) and U16F (the side he joins, "U15A"; labels say 24). Boys: B
-- (U15F from t-90; the section moves him to the U16F on M, t-10 or this
-- season's start), T (U16F from t-90, never moved) and C (joined the U16F on
-- M: the newcomer of Q2, and the scorer named to f24c). t is today.
-- Fixtures, by day: f23a (U15F, t-30), f23n (U15F, t+5); f24a (U16F, t-30),
-- f24c (U16F, t-25: C is its scorer), f24u (U16F, t-20: B on its home sheet,
-- playing up), f24d (U16F, M: the move's day), f24n (U16F, t+5). A toss, T on the home sheet, balls and a bus on f24a and
-- f24n. Nets s24a (t-30) and s24n (t+3), each with a drill and T's
-- attendance. Team posts n24a (published t-30) and n24n (now); a plan p24a
-- for f24a.
CREATE OR REPLACE FUNCTION _v129_stage() RETURNS jsonb AS $$
DECLARE
  HIL uuid := '11111111-1111-1111-1111-111111111111';
  OFFICE uuid := '88888888-0000-0000-0000-00000000000c';
  U14 date := make_date(extract(year FROM sa_today())::int - 14, 3, 1);
  t date := sa_today();
  M date := greatest((SELECT s.starts_on FROM season_for(sa_today(), 'school') s), t - 10);
  ids jsonb; z jsonb := '{}'; v_id uuid; v_a uuid; v_drill uuid; c_b uuid; c_t uuid; c_c uuid;
  k text; tm text; dd int;
BEGIN
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.effective_on', (t - 90)::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U15F', 'Verify OneTwoNine Mover', 1291, 'batter', U14) RETURNING id INTO c_b;
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U16F', 'Verify OneTwoNine Stayer', 1292, 'batter', U14) RETURNING id INTO c_t;
  PERFORM set_config('app.effective_on', M::text, true);
  INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born) VALUES
    (HIL, 'U16F', 'Verify OneTwoNine Newcomer', 1293, 'batter', U14) RETURNING id INTO c_c;
  PERFORM set_config('app.effective_on', '', true);
  ids := _v71_people('v129', ARRAY[
    ARRAY['bboy',    'player',      HIL::text, 'U15F', c_b::text],   -- B himself
    ARRAY['tboy',    'player',      HIL::text, 'U16F', c_t::text],   -- T himself: never moved
    ARRAY['cboy',    'player',      HIL::text, 'U16F', c_c::text],   -- C himself: joined on M
    ARRAY['coach24', 'coach',       HIL::text, 'U16F', ''],
    ARRAY['spec',    'spectator',   HIL::text, '',     ''],
    ARRAY['office',  'schooladmin', HIL::text, '',     ''],
    ARRAY['gb',      'guardian',    HIL::text, '',     ''],     -- B's mother: a boy on a sheet is registered
    ARRAY['gt',      'guardian',    HIL::text, '',     '']]);   -- T's
  PERFORM _v100_link((ids->>'gb')::uuid, HIL, c_b);
  PERFORM _v100_link((ids->>'gt')::uuid, HIL, c_t);
  -- Every pupil holds his self-access link beside `player` (roles.mjs).
  INSERT INTO role_assignment (person_id, role, school_id) VALUES ((ids->>'bboy')::uuid, 'selfaccess', HIL) RETURNING id INTO v_a;
  INSERT INTO assignment_subject (assignment_id, player_id, relationship, verification_state, verified_by, verified_at,
                                  consent_state, consent_version, consent_at, created_by, valid_from)
  VALUES (v_a, c_b, 'self', 'verified', OFFICE, now(), 'granted', 'popia-2026-01', now(), OFFICE, sa_today() - 1);
  z := jsonb_build_object('pb', c_b, 'pt', c_t, 'pc', c_c, 'day_move', M::text);
  FOR k, tm, dd IN SELECT * FROM (VALUES
      ('f23a', 'U15F', -30), ('f23n', 'U15F', 5), ('f24a', 'U16F', -30), ('f24c', 'U16F', -25),
      ('f24u', 'U16F', -20), ('f24d', 'U16F', M - t), ('f24n', 'U16F', 5)) x LOOP
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status)
    VALUES (HIL, tm, 'Verify OneTwoNine ' || k, ((t + dd)::timestamp + time '10:00') AT TIME ZONE 'Africa/Johannesburg',
            'cricket', 'T20', 20, 'scheduled') RETURNING id INTO v_id;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  -- C scores f24c: a pupil scorer, named to that one fixture (a scorer's
  -- row at a fixture also reads its side's rows with no fixture: its nets
  -- and posts, as app_can() has always answered).
  INSERT INTO role_assignment (person_id, role, school_id, team_code, fixture_id)
  VALUES ((ids->>'cboy')::uuid, 'scorer', HIL, 'U16F', (z->>'f24c')::uuid);
  INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES
    ((z->>'f24u')::uuid, c_b, 'home', 1), ((z->>'f24a')::uuid, c_t, 'home', 1), ((z->>'f24n')::uuid, c_t, 'home', 1);
  INSERT INTO match_toss (match_id, school_id, won_by, decision) VALUES
    ((z->>'f24a')::uuid, HIL, 'home', 'bat'), ((z->>'f24n')::uuid, HIL, 'home', 'bowl');
  PERFORM _v71_bowl((z->>'f24a')::uuid, OFFICE, ARRAY[NULL]::uuid[]);
  PERFORM _v71_bowl((z->>'f24n')::uuid, OFFICE, ARRAY[NULL]::uuid[]);
  FOR k IN SELECT unnest(ARRAY['f24a', 'f24n']) LOOP
    INSERT INTO trip (match_id, school_id, pickup, notes) VALUES ((z->>k)::uuid, HIL, 'V129 gate', 'V129 bus to ' || k)
    RETURNING id INTO v_id;
    z := z || jsonb_build_object('t' || substr(k, 2), v_id);
  END LOOP;
  INSERT INTO drill (school_id, name, category, duration_min) VALUES (HIL, 'V129 throwdowns', 'batting', 20) RETURNING id INTO v_drill;
  FOR k, dd IN SELECT * FROM (VALUES ('s24a', -30), ('s24n', 3)) x LOOP
    INSERT INTO training_session (school_id, team_code, title, starts_at, duration_min, session_type)
    VALUES (HIL, 'U16F', 'V129 ' || k, ((t + dd)::timestamp + time '15:00') AT TIME ZONE 'Africa/Johannesburg', 60, 'batting')
    RETURNING id INTO v_id;
    INSERT INTO training_session_drill (session_id, drill_id, position, minutes) VALUES (v_id, v_drill, 1, 20);
    INSERT INTO training_attendance (session_id, player_id, status) VALUES (v_id, c_t, 'present');
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  FOR k, dd IN SELECT * FROM (VALUES ('n24a', -30), ('n24n', 0)) x LOOP
    INSERT INTO news_post (scope, school_id, team_code, kind, title, body, published_at, author_id)
    VALUES ('team', HIL, 'U16F', 'post', 'V129 ' || k, 'V129 a word to the side',
            CASE WHEN dd = 0 THEN now() - interval '1 minute' ELSE ((t + dd)::timestamp + time '12:00') AT TIME ZONE 'Africa/Johannesburg' END,
            (ids->>'coach24')::uuid)
    RETURNING id INTO v_id;
    z := z || jsonb_build_object(k, v_id);
  END LOOP;
  INSERT INTO news_post (scope, school_id, team_code, kind, fixture_id, title, body, published_at, author_id)
  VALUES ('team', HIL, 'U16F', 'plan', (z->>'f24a')::uuid, 'V129 p24a', 'V129 meet at the nets',
          ((t - 31)::timestamp + time '12:00') AT TIME ZONE 'Africa/Johannesburg', (ids->>'coach24')::uuid) RETURNING id INTO v_id;
  z := z || jsonb_build_object('p24a', v_id);
  RETURN ids || z;
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- What the caller reads of the stage, under his own row security, by label,
-- sorted (COLLATE "C"): the fixtures, the toss, the sheet (fixture/boy), the
-- log, the buses, the nets, their drills and attendance, the posts and plan.
CREATE OR REPLACE FUNCTION _v129_reads(z jsonb) RETURNS text AS $$
  WITH f AS (SELECT array_agg(value::uuid) a FROM jsonb_each_text(z) WHERE key ~ '^f2'),
       s AS (SELECT array_agg(value::uuid) a FROM jsonb_each_text(z) WHERE key ~ '^s2')
  SELECT format('fixtures [%s] toss [%s] sheet [%s] balls [%s] trips [%s] nets [%s] drills [%s] att [%s] posts [%s]',
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, m.id) l FROM match m, f WHERE m.id = ANY (f.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, v.match_id) l FROM match_toss v, f WHERE v.match_id = ANY (f.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, v.match_id) || '/' || _v106_label(z, v.player_id) l
                                                               FROM match_squad v, f WHERE v.match_id = ANY (f.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT DISTINCT _v106_label(z, b.match_id) l FROM ball_event b, f WHERE b.match_id = ANY (f.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, v.id) l FROM trip v
                                                               WHERE v.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^t2'))) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, v.id) l FROM training_session v, s WHERE v.id = ANY (s.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, v.session_id) l FROM training_session_drill v, s WHERE v.session_id = ANY (s.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, v.session_id) l FROM training_attendance v, s WHERE v.session_id = ANY (s.a)) x),
    (SELECT coalesce(string_agg(l, ' ' ORDER BY l COLLATE "C"), '') FROM (SELECT _v106_label(z, n.id) l FROM news_post n
                                                               WHERE n.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^[np]2'))) x))
$$ LANGUAGE sql STABLE;

-- Over the stage and the seed's fixtures: what the caller reads of each
-- table, as one sorted list of ids (COLLATE "C"), for the narrow-only
-- comparison over everyone.
CREATE OR REPLACE FUNCTION _v129_ids(z jsonb) RETURNS text AS $$
  WITH f AS (SELECT array_agg(value::uuid) || _v106_seed_matches() a FROM jsonb_each_text(z) WHERE key ~ '^f2'),
       s AS (SELECT array_agg(value::uuid) a FROM jsonb_each_text(z) WHERE key ~ '^s2')
  SELECT coalesce(string_agg(x, ' ' ORDER BY x COLLATE "C"), '') FROM (
    SELECT 'm' || m.id FROM match m, f WHERE m.id = ANY (f.a)
    UNION ALL SELECT 'q' || v.match_id || v.player_id FROM match_squad v, f WHERE v.match_id = ANY (f.a)
    UNION ALL SELECT 'x' || v.match_id FROM match_toss v, f WHERE v.match_id = ANY (f.a)
    UNION ALL SELECT DISTINCT 'b' || b.match_id FROM ball_event b, f WHERE b.match_id = ANY (f.a)
    UNION ALL SELECT 't' || v.id FROM trip v, f WHERE v.match_id = ANY (f.a)
    UNION ALL SELECT 's' || v.id FROM training_session v, s WHERE v.id = ANY (s.a)
    UNION ALL SELECT 'd' || v.session_id FROM training_session_drill v, s WHERE v.session_id = ANY (s.a)
    UNION ALL SELECT 'a' || v.session_id || v.player_id FROM training_attendance v, s WHERE v.session_id = ANY (s.a)
    UNION ALL SELECT 'n' || n.id FROM news_post n
               WHERE n.id = ANY (ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^[np]2'))) y(x)
$$ LANGUAGE sql STABLE;

-- The people the narrow-only comparison asks, as the owner: everyone holding
-- a live `player` assignment (every pupil any section has staged, and the
-- seed's), and one holder of every other class of live assignment (its role
-- and whether it names a boy), a seed account where one holds it.
CREATE OR REPLACE FUNCTION _v129_people() RETURNS uuid[] AS $$
  WITH a AS (SELECT r.person_id, r.role, EXISTS (SELECT 1 FROM assignment_subject g WHERE g.assignment_id = r.id) AS named
               FROM role_assignment r WHERE r.active)
  SELECT coalesce(array_agg(DISTINCT p), '{}') FROM (
    SELECT person_id AS p FROM a WHERE role = 'player'
    UNION
    (SELECT DISTINCT ON (role, named) person_id FROM a WHERE role <> 'player'
      ORDER BY role, named, (person_id::text NOT LIKE '88888888-%'), person_id::text COLLATE "C")) x
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- Whether a person holds a live `player` assignment, as the owner.
CREATE OR REPLACE FUNCTION _v129_holds_player(p_person uuid) RETURNS boolean AS $$
  SELECT EXISTS (SELECT 1 FROM role_assignment WHERE person_id = p_person AND role = 'player' AND active)
$$ LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;

-- The break: pupil_side_on() answering true (the gap db/129 closed), and
-- put back, as the owner. Returns the two bodies' md5, so the section sees
-- that each was changed and then restored.
CREATE OR REPLACE FUNCTION _v129_break(p_broken boolean) RETURNS text AS $$
DECLARE f text;
BEGIN
  FOREACH f IN ARRAY ARRAY['pupil_side_on(text,uuid,text,uuid,uuid,date)', 'pupil_side_on(text,uuid,text,uuid,uuid)'] LOOP
    IF p_broken THEN
      EXECUTE replace(pg_get_functiondef(f::regprocedure), 'SELECT NOT EXISTS (SELECT 1 FROM role_assignment a',
                                                            'SELECT true OR NOT EXISTS (SELECT 1 FROM role_assignment a');
    ELSE
      EXECUTE replace(pg_get_functiondef(f::regprocedure), 'SELECT true OR NOT EXISTS (SELECT 1 FROM role_assignment a',
                                                            'SELECT NOT EXISTS (SELECT 1 FROM role_assignment a');
    END IF;
  END LOOP;
  RETURN (SELECT string_agg(md5(prosrc), ' ' ORDER BY oid::regprocedure::text COLLATE "C") FROM pg_proc WHERE proname = 'pupil_side_on');
END $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp;
-- └── db/129 (section 106) ─────────────────────────────────────────────

-- From here on we are the unprivileged application role, so every read below
-- is subject to RLS exactly as it would be through the API.
SET ROLE scrbrd_app;

-- Surface the closing NOTICE. Without this the file sets client_min_messages
-- to warning and a fully green run prints nothing at all, which is
-- indistinguishable from a run that silently did no work.
SET client_min_messages = notice;

DO $$
DECLARE
  HIL       uuid := '11111111-1111-1111-1111-111111111111';
  WES       uuid := '22222222-2222-2222-2222-222222222222';
  U_COACH   uuid := '88888888-0000-0000-0000-000000000004';  -- coach of 1XI
  U_PARENT  uuid := '88888888-0000-0000-0000-000000000005';  -- guardian of R Pillay
  U_MEDICAL uuid := '88888888-0000-0000-0000-000000000003';
  U_SCOUT   uuid := '88888888-0000-0000-0000-000000000002';
  U_SCORER  uuid := '88888888-0000-0000-0000-000000000006';
  U_SARAH   uuid := '88888888-0000-0000-0000-000000000007';  -- 4 assignments, 2 schools
  U_PLAT    uuid := '88888888-0000-0000-0000-000000000014';  -- platformadmin, no school
  U_OWNER   uuid := '88888888-0000-0000-0000-000000000022';  -- superadmin, every capability
  -- For the newsfeed. NOT U_COACH: section 8 revokes his assignments to prove
  -- revocation narrows, and this file is one transaction, so he holds nothing
  -- by the time the news block runs.
  U_COACH2  uuid := '88888888-0000-0000-0000-00000000000a';  -- 2XI coach: team tier only
  U_MEDIC   uuid := '88888888-0000-0000-0000-000000000003';  -- news.read, no publish tier
  O_UMPIRE  uuid;                                            -- seeded into the register below
  v_born    date;
  v_level   text;
  P_INJURED uuid := 'aaaaaaaa-0000-0000-0000-000000000005';  -- R Pillay, 1XI
  P_U16B    uuid := 'aaaaaaaa-0000-0000-0000-000000000006';  -- K Dlamini, U16B
  P_WES     uuid := 'bbbbbbbb-0000-0000-0000-000000000001';  -- D Mkhize, Westville
  P_WES2    uuid := 'bbbbbbbb-0000-0000-0000-000000000002';  -- K Botha, Westville
  -- The falsifying principal for the notification capability gate. It is a
  -- real spectator: the user seeded as spectator@example.invalid holds a
  -- PLAYER assignment. (The player bundle held medical.status.read until
  -- db/55; it holds no medical tier now, but a spectator is still the plainer
  -- principal for "news.read and nothing medical".)
  U_WATCHER uuid := '88888888-0000-0000-0000-000000000008';
  -- Seeded as spectator@example.invalid, but the ASSIGNMENT is role `player`
  -- at Hilton — a pupil. The one principal that separates the availability
  -- tier from the nature tier.
  U_PUPIL   uuid := '88888888-0000-0000-0000-000000000001';
  -- R Pillay: the injured 1XI player, with an account and a self-access
  -- assignment naming their own player row.
  U_SELF    uuid := '88888888-0000-0000-0000-000000000009';
  P_OTHER   uuid := 'aaaaaaaa-0000-0000-0000-000000000002';  -- T Bekker, also injured
  I_OWN     uuid := 'cccccccc-0000-0000-0000-000000000001';  -- R Pillay's injury, 1XI
  I_U16B    uuid := 'cccccccc-0000-0000-0000-000000000003';  -- K Dlamini's injury, U16B
  -- The majority fixtures. S Naidoo is seeded past eighteen ON PURPOSE (see
  -- 98_seed_pilot.sql), so his guardian link is the one that has already
  -- ended. B Khumalo is U13A with no guardian link at all, which leaves him
  -- free to be linked and re-linked by the assertions below without
  -- disturbing anything else the file asserts.
  U_REGISTRAR uuid := '88888888-0000-0000-0000-00000000000c';  -- holds guardian.link.manage
  U_NAIDOO  uuid := '88888888-0000-0000-0000-000000000012';  -- parent of an adult
  U_BURSAR  uuid := '88888888-0000-0000-0000-000000000015';  -- holds no guardian assignment
  P_ADULT   uuid := 'aaaaaaaa-0000-0000-0000-000000000003';  -- S Naidoo, eighteen
  P_U13     uuid := 'aaaaaaaa-0000-0000-0000-000000000013';  -- B Khumalo, unlinked
  v_ok      boolean;
  v_reason  text;
  S_ID      uuid;         -- a support session (SCRBRD-012)
  S_EXP     timestamptz;
  -- The disciplinary record (SCRBRD-053) — the accounts this file did not
  -- already name. The six grants on discipline.read/write are four distinct
  -- scope shapes: school-scoped, subject-scoped (a pupil's own), one-fixture
  -- (an umpire's appointment) and no-school-at-all (platform-wide).
  U_HEAD_M  uuid := '88888888-0000-0000-0000-000000000016';  -- principal, Hilton
  U_LEAGUE  uuid := '88888888-0000-0000-0000-000000000021';  -- competitionadmin, NO school
  U_UMPIRE  uuid := '88888888-0000-0000-0000-000000000023';  -- official, ONE fixture
  U_WES_ADM uuid := '88888888-0000-0000-0000-00000000000d';  -- schooladmin, Westville
  M_STOOD   uuid := '77777777-0000-0000-0000-000000000004';  -- the match he umpired
  M_OTHER   uuid := '77777777-0000-0000-0000-000000000002';  -- one he did not
  D_ID      uuid;
  -- SCRBRD-059: a match nothing else here scores, so the section owns its session.
  M_HANDOVER uuid := '77777777-0000-0000-0000-000000000003';
  v_epoch   integer;
  v_code    text;
  v_state   text;
  -- SCRBRD-034: the two appointments seeded above, and what a handover needs.
  O_SCORER  uuid := 'd0730000-0000-0000-0000-000000000001';
  O_STOOD   uuid := 'd0730000-0000-0000-0000-000000000002';
  v_until   timestamptz;
  v_runs    int;
  v_wkts    int;
  v_balls   int;
  A_ID      uuid;

  -- SCRBRD-034: the duty, its fixture, its scorer, and the assignment linked.
  U_DUTY    uuid := '88888888-0000-0000-0000-00000000034a';
  M_DUTY    uuid := '77777777-0000-0000-0000-00000000034a';
  D_DUTY    uuid := '0d000000-0000-0000-0000-00000000034a';
  D_DUTY2   uuid := '0d000000-0000-0000-0000-00000000034b';  -- same fixture, never linked
  A_DUTY    uuid;
  n int;
BEGIN
  -- ── 1. Nobody is anybody by default ────────────────────────────
  PERFORM set_config('app.user_id', '', true);
  SELECT count(*) INTO n FROM player;
  PERFORM _assert(n = 0, 'an unidentified session can read players');
  SELECT count(*) INTO n FROM match;
  PERFORM _assert(n = 0, 'an unidentified session can read matches');

  -- ── 2. The roster: rows widen to the school, columns do not ────
  -- A coach used to see only their own squad, full stop. That made the
  -- access-request workflow unusable — you cannot ask about a player you
  -- cannot see exists — and made it impossible to be told a boy in the band
  -- below is ageing up.
  --
  -- So ROW visibility widens to the whole school, and COLUMN visibility does
  -- not. The boundary did not disappear; it moved to where it belongs.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM player WHERE team_code = '1XI';
  PERFORM _assert(n > 0, 'coach sees none of their own team');
  SELECT count(*) INTO n FROM player WHERE team_code <> '1XI';
  PERFORM _assert(n > 0, 'coach cannot see the rest of the school roster');

  -- The tenant boundary is untouched, and this is the assertion that matters
  -- most about the widening: a roster is school-wide, never platform-wide.
  SELECT count(*) INTO n FROM player WHERE school_id = WES;
  PERFORM _assert(n = 0, 'coach reaches across the tenant boundary');

  -- Columns still answer to the team. Age is roster-tier and readable across
  -- the school — a coach considering a trial needs it, and so does anyone
  -- avoiding a fifteen-year-old in a U13 side.
  SELECT count(*) INTO n FROM player_masked WHERE team_code <> '1XI' AND born IS NOT NULL;
  PERFORM _assert(n > 0, 'age is not readable across the roster — trials and eligibility both need it');
  -- Everything else is not.
  SELECT count(*) INTO n FROM player_masked WHERE team_code <> '1XI' AND address IS NOT NULL;
  PERFORM _assert(n = 0, 'a coach reads the home address of a child in another side');
  SELECT count(*) INTO n FROM player_masked WHERE team_code <> '1XI' AND guardian IS NOT NULL;
  PERFORM _assert(n = 0, 'a coach reads the guardian details of a child in another side');
  SELECT count(*) INTO n FROM player_masked WHERE id_number IS NOT NULL;
  PERFORM _assert(n = 0, 'a coach reads a national ID number');

  -- And the roster does not become a way around the request workflow: seeing
  -- that a child exists is not seeing whether they are fit to play.
  SELECT count(*) INTO n FROM injury_masked i
    JOIN player p ON p.id = i.player_id WHERE p.team_code <> '1XI';
  PERFORM _assert(n = 0, 'the roster leaked another side''s medical information');

  -- The §36 case: an AGGREGATE must obey the same scope as a row read. It
  -- still does — what changed is the scope, not the rule. A coach's count is
  -- now their SCHOOL, because the roster made the rows visible, and it must
  -- still stop dead at the tenant boundary.
  --
  -- This assertion previously compared against their own team, and the roster
  -- turned it red. That is the assertion working: a widening that no test
  -- notices is a widening nobody reviewed.
  SELECT count(*) INTO n FROM player;
  PERFORM _assert(n = (SELECT count(*) FROM player WHERE school_id = HIL),
                  'coach total count exceeds their school');
  -- And the school is not the platform: Westville's players are outside it,
  -- which the tenant assertion above already proved by row and this proves by
  -- count. An aggregate leaks as surely as a row.
  -- Derived from the fixture rather than a literal: the seed grows, and a
  -- hardcoded 6 turns red the next time somebody adds a player, which trains
  -- people to edit the number instead of reading the assertion.
  PERFORM _assert(n = (SELECT count(*) FROM player WHERE school_id = HIL),
                  'the coach''s count is not every Hilton player');
  PERFORM _assert(n > (SELECT count(*) FROM player WHERE school_id = HIL AND team_code = '1XI'),
                  'the roster is no wider than the coach''s own side');

  -- ── 3. The coach of the side holds an OVERVIEW, not the full record ──
  -- ADR 0002 (decided): a coach reads the nature tier — what the injury is,
  -- how severe, when he is expected back — for the children they coach, and
  -- not the physio's clinical write-up. What keeps the nature tier itself
  -- safe is SCOPE, not tier: a coach assignment must name a team, and the
  -- injury policy anchors through player.team_code, so the reach is their
  -- own current squad and stops there. Every assertion in this block is
  -- about that boundary, plus the one tier that stays shut regardless of it.
  SELECT count(*) INTO n FROM injury;
  PERFORM _assert(n > 0, 'coach cannot see that a player is unavailable');
  SELECT count(*) INTO n FROM injury_masked WHERE notes IS NOT NULL;
  PERFORM _assert(n = 0, 'coach reads the clinical notes — ADR 0002 keeps those with the physio');
  SELECT count(*) INTO n FROM injury_masked WHERE physio IS NOT NULL;
  PERFORM _assert(n = 0, 'coach sees who is treating their own player — not part of the overview');
  SELECT count(*) INTO n FROM injury_masked WHERE rtw_date IS NOT NULL;
  PERFORM _assert(n > 0, 'return-to-play date wrongly masked from the coach');

  -- The line that matters now that the nature tier is open to them: their
  -- OWN side.
  --
  -- Addressed by injury id, NOT by joining to player and filtering on
  -- team_code. That join was the first version of this assertion and it could
  -- not fail: the coach's player policy already drops a U16B player, so the
  -- join removed the row whatever the injury policy said. It was testing the
  -- wrong policy, and widening the injury team anchor to ANY_SCOPE — which
  -- really does hand the coach all three injuries — left it green.
  SELECT count(*) INTO n FROM injury_masked WHERE id = I_U16B;
  PERFORM _assert(n = 0, 'a coach reads an injury outside the side they coach');
  SELECT count(*) INTO n FROM injury_masked WHERE id = I_U16B AND injury_type IS NOT NULL;
  PERFORM _assert(n = 0, 'a coach reads the nature of an injury outside the side they coach');
  -- …while their own side's nature is there, so this is a boundary and not a
  -- blanket refusal.
  SELECT count(*) INTO n FROM injury_masked WHERE id = I_OWN AND injury_type IS NOT NULL;
  PERFORM _assert(n = 1, 'a coach cannot read the nature of an injury for a player they coach');
  -- And the clinical notes are shut on their OWN side too — not merely at
  -- the team boundary above, which a details-tier grant could satisfy on its
  -- own and leave this hole open.
  SELECT count(*) INTO n FROM injury_masked WHERE id = I_OWN AND notes IS NOT NULL;
  PERFORM _assert(n = 0, 'a coach reads the clinical notes for a player they coach');

  -- The coach picks a side, so they need to know it is a hamstring and how bad.
  SELECT count(*) INTO n FROM injury_masked WHERE injury_type IS NOT NULL;
  PERFORM _assert(n > 0, 'coach cannot read what the injury is — they cannot manage a load');
  SELECT count(*) INTO n FROM injury_masked WHERE severity IS NOT NULL;
  PERFORM _assert(n > 0, 'coach cannot read how severe an injury is');

  PERFORM _as(U_MEDICAL);
  SELECT count(*) INTO n FROM injury_masked WHERE notes IS NOT NULL;
  PERFORM _assert(n > 0, 'medical staff cannot read clinical notes');

  -- ── 3b. A pupil reads no team-mate's injury at all (K3, db/55) ────
  -- It used to be "who is out, not what is wrong": the player bundle held
  -- medical.status.read, so a pupil read every team-mate's date_injured,
  -- rtw_date and restricted. CSA p52: a child's medical needs are "not in
  -- general view to other ... children". db/55 withdrew it; the row itself is
  -- now out of his reach, at every tier. (Section 33 has the rest of K3.)
  PERFORM _as(U_PUPIL);
  SELECT count(*) INTO n FROM injury_masked;
  PERFORM _assert(n = 0, 'a pupil reads a team-mate''s injury row — that he is out, and until when (K3)');
  SELECT count(*) INTO n FROM injury;
  PERFORM _assert(n = 0, 'a pupil reads the injury table under his player assignment (K3)');

  -- A parent needs to know what is wrong with their OWN child. Their
  -- assignment names that child, so the capability reaches no further — the
  -- same row, read by the same policy, answers differently for them than for
  -- the pupil above.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM injury_masked WHERE injury_type IS NOT NULL;
  PERFORM _assert(n = 1, 'a guardian cannot read what is wrong with their own child');

  -- ── 3c. Your own file ──────────────────────────────────────────
  -- A pupil holds `player` for the things that are about the team, and that
  -- assignment reaches every team mate — so it cannot carry the capabilities
  -- that read a medical record. Self-access is its own assignment, named in
  -- assignment_subject as being about exactly one person, and the model's
  -- central rule does the rest: a capability applies only within the scope of
  -- the assignment granting it.
  PERFORM _as(U_SELF);

  -- Their own record, in full — nature AND the physiotherapy notes. A person
  -- reading their own health record is not a disclosure.
  SELECT count(*) INTO n FROM injury_masked
   WHERE player_id = P_INJURED AND injury_type IS NOT NULL;
  PERFORM _assert(n = 1, 'a player cannot read what is wrong with themselves');
  SELECT count(*) INTO n FROM injury_masked
   WHERE player_id = P_INJURED AND notes IS NOT NULL;
  PERFORM _assert(n = 1, 'a player cannot read their own clinical notes');
  SELECT count(*) INTO n FROM injury_masked
   WHERE player_id = P_INJURED AND physio IS NOT NULL;
  PERFORM _assert(n = 1, 'a player cannot see who is treating them');

  -- And nobody else's. This is the assertion the second seeded injury exists
  -- for: with one injury in the fixture, "reads their own" and "reads
  -- everything" are the same answer.
  SELECT count(*) INTO n FROM injury_masked
   WHERE player_id = P_OTHER AND injury_type IS NOT NULL;
  PERFORM _assert(n = 0, 'self-access reads another player''s diagnosis');
  SELECT count(*) INTO n FROM injury_masked
   WHERE player_id = P_OTHER AND notes IS NOT NULL;
  PERFORM _assert(n = 0, 'self-access reads another player''s clinical notes');

  -- Nor that the other player is out at all. Their separate `player`
  -- assignment reaches the side, and since db/55 (K3, CSA p52) it carries no
  -- medical tier, so the row itself is out of reach: the two assignments do
  -- different jobs at different scopes, in the same session, and only the
  -- one naming him reads an injury.
  SELECT count(*) INTO n FROM injury_masked WHERE player_id = P_OTHER;
  PERFORM _assert(n = 0, 'a player sees that a team mate is unavailable (K3)');

  -- Their own PII, likewise: their date of birth is theirs.
  SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED AND born IS NOT NULL;
  PERFORM _assert(n = 1, 'a player cannot read their own date of birth');
  SELECT count(*) INTO n FROM player_masked WHERE id = P_OTHER AND born IS NOT NULL;
  PERFORM _assert(n = 0, 'self-access leaks a team mate''s date of birth');

  -- ── 3d. A coach reaches the team they coach, not the school ────
  -- A NULL team_code widens to every team in the school. Right for a head of
  -- sport, wrong for a coach: a coach reaches a player's medical information
  -- because they coach that player's CURRENT side. Enforced as a constraint
  -- rather than a convention, so it cannot be got wrong when an assignment is
  -- created at half past four on a Friday.
  -- Asserted on the constraint itself rather than by attempting an insert:
  -- scrbrd_app cannot write role_assignment anyway, so an insert here would be
  -- refused for the wrong reason and the assertion would pass while the
  -- constraint was missing.
  SELECT count(*) INTO n
    FROM pg_constraint
   WHERE conrelid = 'role_assignment'::regclass
     AND conname  = 'assignment_team_scoped';
  PERFORM _assert(n = 1, 'the constraint keeping a coach inside their own team is missing');

  SELECT count(*) INTO n
    FROM pg_get_constraintdef(
           (SELECT oid FROM pg_constraint
             WHERE conrelid = 'role_assignment'::regclass
               AND conname = 'assignment_team_scoped')) AS d(def)
   WHERE d.def LIKE '%coach%' AND d.def LIKE '%team_code IS NOT NULL%';
  PERFORM _assert(n = 1, 'the constraint exists but does not cover coaches');

  -- And nothing in the data slipped through before it existed.
  SELECT count(*) INTO n FROM role_assignment
   WHERE role IN ('coach','assistantcoach','teammanager') AND team_code IS NULL;
  PERFORM _assert(n = 0, 'a coach assignment with no team is present in the data');

  -- ── 4. A minor's PII ───────────────────────────────────────────
  PERFORM _as(U_COACH);
  -- A coach picking a U13 side who cannot see an age cannot avoid putting a
  -- fifteen-year-old in it. Age is operational information for anyone who
  -- selects a team, so it has its own capability and they hold it.
  SELECT count(*) INTO n FROM player_masked WHERE born IS NOT NULL;
  PERFORM _assert(n > 0, 'coach cannot read a date of birth — they cannot check eligibility');
  -- And the tier above it is still shut. The ID number is the most dangerous
  -- field about a child in this schema: issued once, never changed, useful to
  -- a fraudster for life. The school office holds it and nobody else.
  SELECT count(*) INTO n FROM player_masked WHERE id_number IS NOT NULL;
  PERFORM _assert(n = 0, 'coach can read a minor''s national ID number');
  SELECT count(*) INTO n FROM player_masked WHERE guardian IS NOT NULL;
  PERFORM _assert(n = 0, 'coach can read guardian details');
  SELECT count(*) INTO n FROM player_masked WHERE address IS NOT NULL;
  PERFORM _assert(n = 0, 'coach can read a minor''s home address');
  SELECT count(*) INTO n FROM player_masked WHERE full_name IS NOT NULL;
  PERFORM _assert(n > 0, 'over-masking: coach cannot read player names');

  PERFORM _as(U_SCOUT);
  SELECT count(*) INTO n FROM player_masked WHERE born IS NOT NULL;
  PERFORM _assert(n = 0, 'scout can read a minor date of birth');

  -- ── 5. A guardian reaches their own children and no further ────
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM player WHERE id <> P_INJURED;
  PERFORM _assert(n = 0, 'guardian sees children who are not theirs');
  SELECT count(*) INTO n FROM player WHERE id = P_INJURED;
  PERFORM _assert(n = 1, 'guardian cannot see their own child');
  SELECT count(*) INTO n FROM injury WHERE player_id <> P_INJURED;
  PERFORM _assert(n = 0, 'guardian sees another child injury');
  -- A guardian may read their own child's PII, unlike the coach above.
  SELECT count(*) INTO n FROM player_masked WHERE born IS NOT NULL;
  PERFORM _assert(n = 1, 'guardian cannot read their own child date of birth');
  -- …and the clinical detail behind it, for their own child. A parent reading
  -- their child's physiotherapy report is the ordinary case, not an exception
  -- — the school would hand them the same letter. Their assignment names that
  -- child, so it goes no further, which the row count above already proved.
  SELECT count(*) INTO n FROM injury_masked WHERE notes IS NOT NULL;
  PERFORM _assert(n = 1, 'a guardian cannot read their own child''s clinical notes');

  -- ── 6. Sarah: four assignments across two institutions ─────────
  -- The case the previous single-role, single-school session could not
  -- express at all.
  PERFORM _as(U_SARAH);
  -- Director of Sport reaches every Hilton player…
  -- Every Hilton player, including the U16B side she does not coach and the
  -- 1XI side she has no assignment over: Director of Sport is school-scoped.
  -- Counted against the fixture, not a literal, for the same reason as the
  -- coach's roster above: the seed grows, and a hardcoded number trains people
  -- to edit the count rather than read the claim.
  -- Asserted on NAMED players rather than a count. The count version compared
  -- a query against itself — both sides run under the same policy, so it was
  -- true for every input including one where she saw nobody.
  --
  -- She coaches U16B and is Director of Sport. So: the U16B player she coaches,
  -- AND a 1XI player she has no assignment over, both reachable — which is the
  -- actual claim, that the school-scoped role reaches past the team-scoped one.
  SELECT count(*) INTO n FROM player WHERE id = P_U16B;
  PERFORM _assert(n = 1, 'Director of Sport cannot see the side she coaches');
  SELECT count(*) INTO n FROM player WHERE id = P_INJURED;
  PERFORM _assert(n = 1, 'Director of Sport does not reach a team she does not coach');
  -- …and guardianship reaches exactly one child at the OTHER school…
  SELECT count(*) INTO n FROM player WHERE school_id = WES;
  PERFORM _assert(n = 1, 'cross-school guardian scope is wrong');
  SELECT count(*) INTO n FROM player WHERE id = P_WES;
  PERFORM _assert(n = 1, 'Sarah cannot see her Westville child');
  -- …and NOT the other Westville players. This is the union bug: staff
  -- authority at Hilton must not travel to Westville with her.
  SELECT count(*) INTO n FROM player WHERE id = P_WES2;
  PERFORM _assert(n = 0, 'staff authority leaked across the tenant boundary');

  -- Her Hilton coaching assignment must not widen the Westville relationship.
  SELECT count(*) INTO n FROM injury WHERE school_id = WES;
  PERFORM _assert(n = 0, 'Sarah sees Westville injuries');

  -- ── 7. Scoring one match is not standing squad access ──────────
  PERFORM _as(U_SCORER);
  SELECT count(*) INTO n FROM match;
  PERFORM _assert(n > 0, 'scorer cannot see fixtures');
  SELECT count(*) INTO n FROM injury;
  PERFORM _assert(n = 0, 'scorer can read injuries');
  SELECT count(*) INTO n FROM player_masked WHERE born IS NOT NULL;
  PERFORM _assert(n = 0, 'scorer can read a minor date of birth');

  -- ── 8. Writes are refused, not silently dropped ────────────────
  PERFORM _as(U_SCOUT);
  BEGIN
    INSERT INTO player (id, school_id, team_code, full_name)
    VALUES (gen_random_uuid(), HIL, '1XI', 'Injected');
    PERFORM _assert(false, 'scout INSERT into player succeeded');
  EXCEPTION WHEN insufficient_privilege OR check_violation THEN NULL;
  END;

  PERFORM _as(U_COACH);
  BEGIN
    UPDATE player SET full_name = 'Renamed' WHERE school_id = WES;
    PERFORM _assert((SELECT count(*) FROM player WHERE full_name = 'Renamed') = 0,
                    'coach updated a row in another school');
  EXCEPTION WHEN insufficient_privilege OR check_violation THEN NULL;
  END;

  -- ── 9. Views do not smuggle rows past the policies ─────────────
  -- A view runs with the permissions of its OWNER unless it says otherwise,
  -- and the owner of these owns the tables underneath them — so row-level
  -- security was evaluated as a role that bypasses it, and player_masked
  -- returned EVERY player at EVERY school to anyone who could select from it.
  -- Through the one object the read path is REQUIRED to use for personal
  -- information, and invisibly: the leaked rows were still column-masked, so
  -- each one looked exactly right.
  -- (It asks for security_invoker=true: a view altered to security_invoker=false
  -- once read as passing, because the option's NAME was all that was asked.)
  PERFORM _assert(
    (SELECT bool_and(coalesce('security_invoker=true' = ANY (reloptions), false))
       FROM pg_class WHERE relkind = 'v' AND relnamespace = 'public'::regnamespace),
    'a view in public runs as its owner and bypasses row-level security');

  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM player_masked WHERE school_id = WES;
  PERFORM _assert(n = 0, 'the masked view leaks another school''s players');
  -- The view and the table it wraps must agree about WHICH rows exist; they
  -- may only disagree about which columns are readable.
  PERFORM _assert(
    (SELECT count(*) FROM player_masked) = (SELECT count(*) FROM player),
    'player_masked and player disagree about which rows exist');

  PERFORM _as(U_SCOUT);
  PERFORM _assert((SELECT count(*) FROM injury_masked) = (SELECT count(*) FROM injury),
                  'injury_masked and injury disagree about which rows exist');

  -- ── 10. The four tables that had no policy at all ──────────────
  -- school, app_user, ground and match_squad ran with row-level security
  -- switched OFF. Nothing was misconfigured; they were simply never listed,
  -- and an unlisted table is wide open rather than closed. These assertions
  -- exist so that a table dropping out of the policy source is a failing
  -- test rather than a silent disclosure.
  PERFORM _assert(
    (SELECT bool_and(relrowsecurity) FROM pg_class
      WHERE relnamespace = 'public'::regnamespace AND relkind = 'r'),
    'some table in public has row-level security disabled');

  -- app_user was a cross-tenant directory: every name and email, one login.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM app_user WHERE school_id = WES;
  PERFORM _assert(n = 0, 'coach can read users at another school');
  SELECT count(*) INTO n FROM app_user WHERE id = U_COACH;
  PERFORM _assert(n = 1, 'a person cannot read their own user record');

  -- ...and it stays closed for someone whose role does not include user.read.
  PERFORM _as(U_SCORER);
  SELECT count(*) INTO n FROM app_user WHERE id <> U_SCORER;
  PERFORM _assert(n = 0, 'scorer can read other user records');

  -- school: the tenant list. Attached schools only.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM school WHERE id = WES;
  PERFORM _assert(n = 0, 'coach can enumerate another tenant');
  SELECT count(*) INTO n FROM school WHERE id = HIL;
  PERFORM _assert(n = 1, 'coach cannot see their own school');
  -- Sarah is a guardian at Westville as well, so she legitimately sees both.
  PERFORM _as(U_SARAH);
  SELECT count(*) INTO n FROM school;
  PERFORM _assert(n = 2, 'a guardian at two schools cannot see both');

  -- match_squad: a list of named minors, anchored through its match.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM match_squad;
  PERFORM _assert(n > 0, 'coach cannot read their own team sheet');

  -- A scorer must be able to name a striker, so they read the squad too.
  PERFORM _as(U_SCORER);
  SELECT count(*) INTO n FROM match_squad;
  PERFORM _assert(n > 0, 'scorer cannot read the squad they are scoring');

  -- The sharpest case: a guardian's assignment lists their children, so the
  -- person anchor narrows a whole team sheet down to the one row that is
  -- theirs. Same table, same query, one row.
  --
  -- Asked as "no row but their own child's", not "exactly one row": the child
  -- may be on more than one team sheet (a database that has run the contacts
  -- walk has him on several), and every one of those is rightly the
  -- guardian's to see. Counting rows made the check depend on how many
  -- fixtures the boy was picked for; counting OTHER boys' rows is the leak.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM match_squad WHERE player_id <> P_INJURED;
  PERFORM _assert(n = 0, 'guardian sees another child on the team sheet');
  SELECT count(*) INTO n FROM match_squad WHERE player_id = P_INJURED;
  PERFORM _assert(n >= 1, 'guardian cannot see their own child on the team sheet');

  -- The ANY_SCOPE regression. A fixture names no person, so a guardian's
  -- child list has nothing to constrain — and before app_can() could say
  -- "this dimension does not apply", every guardian was denied every fixture.
  -- A parent could not see when their own child was playing.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM match;
  PERFORM _assert(n > 0, 'guardian cannot see any fixture');
  -- ...and since db/106 (REACH-D1, "the side only") only her child's side's:
  -- R Pillay's 1XI at either end, or a fixture whose sheet names him. This
  -- read n > 0 alone while match_read asked with the all-zeros person, which
  -- for a guardian is every fixture at her school (the seed's U16B one too).
  SELECT count(*) INTO n FROM match m
   WHERE NOT ((m.school_id = HIL AND m.team_code = '1XI') OR (m.away_school_id = HIL AND m.away_team_code = '1XI')
              OR EXISTS (SELECT 1 FROM match_squad s WHERE s.match_id = m.id AND s.player_id = P_INJURED AND NOT s.withdrawn));
  PERFORM _assert(n = 0, format('guardian sees %s fixture(s) of a side her child is not on (db/106)', n));
  PERFORM _as(U_OWNER);
  SELECT count(*) INTO n FROM match WHERE school_id = HIL AND team_code = 'U16B';
  PERFORM _assert(n > 0, 'the seed has no U16B fixture, so the guardian''s side-only read above proves nothing');
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM match WHERE school_id = WES;
  PERFORM _assert(n = 0, 'guardian sees fixtures at a school they are not attached to');

  -- ground: not sensitive, but scoped like everything else.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM ground WHERE school_id = WES;
  PERFORM _assert(n = 0, 'coach can read another school''s grounds');

  -- ── 10b. An injury alerts the circle of care, and only them ────
  -- A trigger on `injury` publishes a notice declaring medical.nature.read and
  -- naming the player it is about. Nobody is listed as a recipient anywhere:
  -- the audience falls out of the capability model, and these assertions are
  -- how we know it lands where you would want it to.
  -- Counted against the fixture rather than a fixed number, so adding an
  -- injury to the seed cannot quietly make these pass for the wrong reason.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND required_capability = 'medical.nature.read';
  PERFORM _assert(
    n = (SELECT count(*) FROM injury i JOIN player p ON p.id = i.player_id
          WHERE p.team_code = '1XI'),
    'the coach was not alerted to exactly their own side''s injuries');
  -- Specifically: not the U16B one.
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND subject_person_id = P_U16B;
  PERFORM _assert(n = 0, 'a coach was alerted about a player in another side');

  PERFORM _as(U_MEDICAL);
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND required_capability = 'medical.nature.read';
  PERFORM _assert(n = (SELECT count(*) FROM injury), 'medical staff were not alerted to every injury');

  -- The parent of ONE child. Their assignment names that child, so the person
  -- anchor on the notice has something to fail against — without it, a notice
  -- is about nobody in particular and every guardian in the team receives an
  -- alert about somebody else's child.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND subject_person_id = P_INJURED;
  PERFORM _assert(n = 1, 'the guardian was not alerted about their own child');
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND subject_person_id = P_OTHER;
  PERFORM _assert(n = 0, 'a guardian was alerted about somebody else''s child');

  -- The player themselves, through self-access.
  PERFORM _as(U_SELF);
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND subject_person_id = P_INJURED
     AND required_capability = 'medical.nature.read';
  PERFORM _assert(n = 1, 'a player was not told about their own injury');
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND subject_person_id = P_OTHER;
  PERFORM _assert(n = 0, 'self-access received an alert about a team mate');

  -- And NOT a team mate, at either tier. The player bundle holds no medical
  -- tier since db/55 (K3), so neither the nature-tier alert nor the
  -- status-tier availability notice reaches another pupil. The tier decides
  -- the audience.
  PERFORM _as(U_PUPIL);
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND required_capability = 'medical.nature.read';
  PERFORM _assert(n = 0, 'a team mate was alerted to what is wrong with a player');
  SELECT count(*) INTO n FROM notification
   WHERE kind = 'injury' AND required_capability = 'medical.status.read';
  PERFORM _assert(n = 0, 'a team mate was told the player is unavailable (K3)');

  -- A spectator holds neither.
  PERFORM _as(U_WATCHER);
  SELECT count(*) INTO n FROM notification WHERE kind = 'injury';
  PERFORM _assert(n = 0, 'a spectator received an injury alert');

  -- ── 10c. A fifteen-year-old cannot be picked for a U13 side ────
  -- "U13" means thirteen AND UNDER. Getting this wrong is a safeguarding
  -- failure before it is a competitive one, so it is enforced by a trigger
  -- rather than by whichever screen happens to be writing the squad.
  --
  -- Asserted as the OWNER, deliberately: the trigger is the subject here, and
  -- running as scrbrd_app would have the row-level policy refuse the write
  -- first, which would pass this block for the wrong reason.
  PERFORM _as(U_COACH);

  SELECT count(*) INTO n FROM pg_trigger
   WHERE tgrelid = 'match_squad'::regclass AND tgname = 'match_squad_is_age_eligible';
  PERFORM _assert(n = 1, 'the age-eligibility trigger is missing from match_squad');

  SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace nsp ON nsp.oid = p.pronamespace
   WHERE nsp.nspname = 'public' AND p.proname = 'match_squad_age_eligible' AND p.prosecdef;
  PERFORM _assert(n = 1,
    'the eligibility check is not SECURITY DEFINER — it cannot read a masked date of birth');

  -- ── 10b. A minor with no verified guardian is not selected ─────
  -- §12.2. The rule is enforced at selection because that is where a school
  -- ACTS on a child's data, and it reads a DERIVED state rather than a flag:
  -- a child is registered, or is not, according to the links that exist now.
  SELECT count(*) INTO n FROM pg_trigger
   WHERE tgrelid = 'match_squad'::regclass AND tgname = 'match_squad_is_registered';
  PERFORM _assert(n = 1, 'the registration trigger is missing from match_squad');

  SELECT count(*) INTO n FROM pg_views WHERE schemaname = 'public'
     AND viewname = 'player_guardian_status';
  PERFORM _assert(n = 1, 'player_guardian_status is missing');

  -- A view runs as its OWNER unless told otherwise, and this one reads
  -- `player`. Without security_invoker the office would see every child at
  -- every school through it.
  SELECT count(*) INTO n FROM pg_class
   WHERE relname = 'player_guardian_status'
     AND reloptions @> ARRAY['security_invoker=true'];
  PERFORM _assert(n = 1, 'player_guardian_status is not security_invoker');

  -- The link table has a read policy and NO write policy at all: every write
  -- goes through a SECURITY DEFINER function that checks its own authority.
  SELECT count(*) INTO n FROM pg_policy
   WHERE polrelid = 'assignment_subject'::regclass AND polcmd <> 'r';
  PERFORM _assert(n = 0, 'assignment_subject has a write policy — links must go through the functions');

  -- ── 11. The programme tables ───────────────────────────────────
  -- Five areas that existed in the product and not in the database, so the
  -- browser was deciding all of them. Each assertion below is a decision that
  -- used to be made in JavaScript.

  -- training_session is a noticeboard fact, scoped to the team it is for.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM training_session;
  PERFORM _assert(n = 1, '1XI coach should see exactly their own team''s session');
  SELECT count(*) INTO n FROM training_session WHERE team_code = 'U16B';
  PERFORM _assert(n = 0, '1XI coach can read a U16B training session');

  -- The register is the sensitive half, and it is governed separately. A
  -- guardian holds player.profile.read but their assignment reaches only their
  -- own children, so they get the row for R Pillay and not the one for
  -- J Whitfield — from the same table, in the same session.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM training_attendance;
  PERFORM _assert(n = 1, 'guardian should see exactly their own child''s attendance row');
  SELECT count(*) INTO n FROM training_attendance WHERE player_id = P_INJURED;
  PERFORM _assert(n = 1, 'guardian cannot see their own child''s attendance');

  -- A guardian may read the SESSION while reading only one row of the
  -- REGISTER. That asymmetry is the entire reason the two are separate tables.
  -- Since db/106 (REACH-D1) the session is her child's side's alone
  -- (side_reach('team.read')): this read n > 1 while training_session_read
  -- asked with the all-zeros person, which gave her every side's nets at the
  -- school, the U16B's included.
  SELECT count(*) INTO n FROM training_session WHERE school_id = HIL AND team_code = '1XI';
  PERFORM _assert(n >= 1, 'guardian should still see her child''s side''s training schedule itself');
  SELECT count(*) INTO n FROM training_session WHERE NOT (school_id = HIL AND team_code = '1XI');
  PERFORM _assert(n = 0, format('guardian sees %s training session(s) of a side her child is not on (db/106)', n));
  PERFORM _as(U_OWNER);
  SELECT count(*) INTO n FROM training_session WHERE school_id = HIL AND team_code <> '1XI';
  PERFORM _assert(n > 0, 'the seed has no other side''s session, so the guardian''s side-only read above proves nothing');
  PERFORM _as(U_PARENT);

  -- player_skill: a coach's assessment of a named child. The guardian holds no
  -- player.development.read at all, so this is empty for them — a parent reads
  -- their child's profile and availability, not a coaching judgement of them.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM player_skill;
  PERFORM _assert(n = 0, 'guardian can read development assessments');

  -- Asserted as the PROPERTY rather than as a count. This read `n = 2`, which
  -- was true of the seed on the day it was written and stopped being true when
  -- the seed gained two more attribute rows for the same 1XI boy — so a
  -- verifier meant to catch a scope leak failed for a reason that had nothing
  -- to do with scope, and the only way to keep it passing was to keep editing
  -- a number. What it is actually for is: every row this coach can see belongs
  -- to a team they coach, and there is at least one, so an empty result cannot
  -- pass for a clean one.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM player_skill;
  PERFORM _assert(n > 0, '1XI coach sees no assessments at all');
  SELECT count(*) INTO n
    FROM player_skill s JOIN player p ON p.id = s.player_id
   WHERE p.team_code <> '1XI';
  PERFORM _assert(n = 0, '1XI coach should see their own squad''s assessments only');
  SELECT count(*) INTO n FROM player_skill WHERE player_id = P_U16B;
  PERFORM _assert(n = 0, '1XI coach can read a U16B player''s assessment');

  -- ── 11b. A notification is not permission ──────────────────────
  -- The one that matters most. news.read is a floor capability; if it were the
  -- only gate, the feed would be a side channel around every policy above.
  -- Each row declares the capability its SUBJECT MATTER requires and the
  -- policy demands both, in the same scope.

  -- The player-role principal holds news.read and NOT medical.status.read.
  PERFORM _as(U_WATCHER);
  SELECT count(*) INTO n FROM notification WHERE id = '40170000-0000-0000-0000-000000000001';
  PERFORM _assert(n = 1, 'a general school notice did not reach someone holding news.read');
  SELECT count(*) INTO n FROM notification WHERE id = '40170000-0000-0000-0000-000000000002';
  PERFORM _assert(n = 0,
    'a MEDICAL notice reached a principal with no medical.status.read — the notification feed is a way around RLS');

  -- The medical officer holds both, school-wide.
  PERFORM _as(U_MEDICAL);
  SELECT count(*) INTO n FROM notification WHERE id = '40170000-0000-0000-0000-000000000002';
  PERFORM _assert(n = 1, 'the medical officer cannot read a medical notice');

  -- Scope still applies on top of the capability: the 1XI coach holds
  -- medical.status.read and reads the 1XI medical notice, but must not
  -- receive the U16B team notice even though it only requires news.read.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM notification WHERE id = '40170000-0000-0000-0000-000000000002';
  PERFORM _assert(n = 1, '1XI coach cannot read their own team''s medical notice');
  SELECT count(*) INTO n FROM notification WHERE id = '40170000-0000-0000-0000-000000000003';
  PERFORM _assert(n = 0, '1XI coach received a U16B team notice');

  -- A school-wide notice carries team_code NULL. A NULL on a resource NARROWS,
  -- so without the COALESCE to ANY_SCOPE in the generated policy this would be
  -- invisible to every team-scoped person in the school.
  SELECT count(*) INTO n FROM notification WHERE id = '40170000-0000-0000-0000-000000000001';
  PERFORM _assert(n = 1, 'a school-wide notice is invisible to a team-scoped coach');

  -- Publishing is scope-shaped. The coach holds news.publish.team and not
  -- news.publish.school, so a school-level notice must be refused.
  BEGIN
    INSERT INTO notification (school_id, team_code, scope_level, kind, title, body)
    VALUES (HIL, NULL, 'school', 'system', 'Unauthorised', 'Should not commit');
    PERFORM _assert(false, 'a coach published a SCHOOL notice holding only news.publish.team');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- ...and the team notice they may publish goes through. (Not a 'notice':
  -- since db/91 a person's words are a news_post, and the post's trigger
  -- writes the notice; §70.)
  INSERT INTO notification (school_id, team_code, scope_level, kind, title, body)
  VALUES (HIL, '1XI', 'team', 'fixture', 'Nets moved', 'Nets 1-3 at 14:30.');

  -- The catalogue must not be writable by the application role: a row here
  -- would let a notice declare a capability the model never defined.
  BEGIN
    INSERT INTO capability (name) VALUES ('invented.capability');
    PERFORM _assert(false, 'the application role can write the capability catalogue');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- ── 11c. Participation, not authorship, decides a league ───────
  -- The competition is seeded with school_id NULL because that was the only
  -- way a shared league could be readable before competition_entrant existed.
  -- What is new is that the ladder itself is scoped and readable whole: a
  -- team-scoped coach must see BOTH entrants, or the log has one row in it.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM competition_entrant
   WHERE competition_id = '99999999-0000-0000-0000-000000000001';
  PERFORM _assert(n = 2, 'a team-scoped coach cannot read the full league ladder');

  -- Weather inherits the fixture's policy rather than being left open on the
  -- grounds that rain is not confidential.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM match_weather;
  PERFORM _assert(n = 1, 'coach cannot read conditions for their own fixture');

  -- ── 11d. Read state is per person and not a capability ─────────
  PERFORM _as(U_COACH);
  INSERT INTO notification_read (notification_id, person_id)
  VALUES ('40170000-0000-0000-0000-000000000001', U_COACH);
  BEGIN
    INSERT INTO notification_read (notification_id, person_id)
    VALUES ('40170000-0000-0000-0000-000000000001', U_MEDICAL);
    PERFORM _assert(false, 'one person marked a notice read on another person''s behalf');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  PERFORM _as(U_MEDICAL);
  SELECT count(*) INTO n FROM notification_read;
  PERFORM _assert(n = 0, 'one person can see which notices another person has opened');

  -- ── SCRBRD-039. What an innings declared it would capture ─────
  -- db/31's two views derive the declaration from innings_start rows and grade
  -- placement against it. Two things to prove against the real policies:
  --
  --   - The seed's one scored innings (Maritzburg, …0004) declared nothing,
  --     like every innings before SCRBRD-039, and must read EXACTLY as db/08's
  --     count-only label always graded it — the backward-compatibility claim,
  --     live, on sector-era and point-era balls together.
  --   - The views are the caller's view of the log and nothing more: every
  --     innings they name is one whose rows the reader can see, and a
  --     principal with no assignment sees none.
  --
  -- What a DECLARED innings reads is driven through the real API, lease and
  -- epoch in tools/smoke-fold.mjs; it cannot be written from here without
  -- holding a scoring session.
  PERFORM _as(U_COACH);
  DECLARE
    m_seed uuid := '77777777-0000-0000-0000-000000000004';
    r      record;
    v_pts  bigint;
    v_plc  bigint;
  BEGIN
    SELECT count(*) FILTER (WHERE placement_source = 'point'),
           count(*) FILTER (WHERE theta IS NOT NULL OR seg IS NOT NULL)
      INTO v_pts, v_plc
      FROM ball_event_live WHERE match_id = m_seed AND innings = 0 AND kind = 'ball';
    PERFORM _assert(v_pts > 0 AND v_plc > v_pts,
      'the coach cannot see the seeded innings (points and sector-era balls) the declared-profile checks read');
    SELECT * INTO r FROM innings_placement_evidence WHERE match_id = m_seed AND innings = 0;
    PERFORM _assert(r.match_id IS NOT NULL, 'innings_placement_evidence does not show the coach his own side''s innings');
    PERFORM _assert(r.declared_profile IS NULL,
      format('an innings with no declaration reads as declared %s', r.declared_profile));
    PERFORM _assert(r.points = v_pts AND r.placed = v_plc,
      format('innings_placement_evidence counts %s points / %s placed; the log holds %s / %s', r.points, r.placed, v_pts, v_plc));
    PERFORM _assert(r.point_evidence = evidence_label(v_pts) AND r.placement_evidence = evidence_label(v_plc),
      format('an undeclared innings no longer reads as before: %s / %s, db/08 says %s / %s',
             r.point_evidence, r.placement_evidence, evidence_label(v_pts), evidence_label(v_plc)));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM innings_placement_evidence WHERE point_evidence = 'not_captured'
                                                                         OR placement_evidence = 'not_captured')
                    AND NOT EXISTS (SELECT 1 FROM innings_declared_profile),
      'the seed declared nothing, yet something in it is excused as not captured');
    PERFORM _assert(NOT EXISTS (
        SELECT 1 FROM innings_placement_evidence e
         WHERE NOT EXISTS (SELECT 1 FROM ball_event b WHERE b.match_id = e.match_id AND b.innings = e.innings)),
      'innings_placement_evidence names an innings whose log the reader cannot see');
  END;
  PERFORM _as('00000000-0000-0000-0000-0000000000de');
  SELECT count(*) INTO n FROM innings_placement_evidence;
  PERFORM _assert(n = 0, format('a principal with no assignment sees %s innings of placement evidence', n));
  SELECT count(*) INTO n FROM innings_declared_profile;
  PERFORM _assert(n = 0, format('a principal with no assignment sees %s capture declarations', n));

  -- ── 12. Revocation takes effect immediately ────────────────────
  -- This is the property the SECURITY DEFINER lookup was chosen for. Nothing
  -- about authority is carried in the session, so deactivating an assignment
  -- applies on the very next statement rather than at next login.
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM player;
  PERFORM _assert(n > 0, 'coach starts with no visible players');
  -- ── The owner's recovery function only ever refreshes the owner's key ──
  --
  -- db/18. Two things to prove: it exists, and its ONE gate holds — a real
  -- account with no platform-wide superadmin assignment is refused the same
  -- way as an address that does not exist at all, never handed a code.
  PERFORM _assert(to_regprocedure('owner_recovery_issue(text,text,integer)') IS NOT NULL,
    'owner_recovery_issue() is missing — the owner has no way back in but psql');
  DECLARE
    r_owner    record;
    r_notowner record;
    r_nobody   record;
  BEGIN
    SELECT * INTO r_owner    FROM owner_recovery_issue('owner@example.invalid', 'verify-hash-owner', 3600);
    SELECT * INTO r_notowner FROM owner_recovery_issue('coach@example.invalid', 'verify-hash-notowner', 3600);
    SELECT * INTO r_nobody   FROM owner_recovery_issue('nobody-at-all@example.invalid', 'verify-hash-nobody', 3600);
    PERFORM _assert(r_owner.ok = true, 'the seeded owner cannot recover their own key');
    PERFORM _assert(r_notowner.ok = false AND r_notowner.reason = 'not_owner',
      'a real account with no platform-wide superadmin was handed a recovery code');
    PERFORM _assert(r_nobody.ok = false AND r_nobody.reason = 'not_owner',
      'an address with no account was answered differently than a real non-owner — that is enumeration');
    -- Leaves no live code the demonstration didn't already expect: undo the
    -- write this verification made, on the account it touched.
    UPDATE login_code SET used_at = now()
     WHERE code_hash IN ('verify-hash-owner') AND used_at IS NULL;
  END;

  -- ── A scorer sees their own quarantined balls ────────────────
  -- db/17. Placed before the coach's assignment is revoked below. Without this, an INSERT ... ON CONFLICT into quarantine failed the
  -- SELECT-policy check for any scorer who could not otherwise read the
  -- table, and a coach's stale ball was lost with a 42501.
  PERFORM _as(U_COACH);
  PERFORM set_config('app.device_id', 'verify-device', true);
  -- A held event carries its fingerprint (db/36); the write path computes it.
  INSERT INTO ball_event_quarantine (match_id, school_id, submitted_epoch, current_epoch, scorer_user_id, device_id, idempotency_key, body, fingerprint)
  SELECT m.id, m.school_id, 9, 1, U_COACH, 'verify-device', 'verify:quarantine:own', '{}'::jsonb, 'verify-fingerprint'
    FROM match m WHERE m.school_id = '11111111-1111-1111-1111-111111111111' AND m.team_code = '1XI' LIMIT 1
  ON CONFLICT (idempotency_key) DO NOTHING;
  SELECT count(*) INTO n FROM ball_event_quarantine WHERE idempotency_key = 'verify:quarantine:own';
  PERFORM _assert(n = 1, 'a coach cannot quarantine (and then see) their own stale ball');

  -- ── db/36: an idempotency key names ONE event ──────────────────
  -- The write path answers "duplicate" only when the stored event's
  -- fingerprint matches the one it is holding, and "conflict" otherwise. That
  -- is only as good as the fingerprint: present on every row, stamped by the
  -- database for EVERY writer (the seed below wrote its balls with plain SQL,
  -- as scoring_amendment_decide and quarantine_resolve do), and blind to how
  -- an event arrived but not to what it says.
  SELECT count(*) INTO n FROM pg_attribute
   WHERE attrelid = 'ball_event'::regclass AND attname = 'fingerprint' AND attnotnull;
  PERFORM _assert(n = 1, 'ball_event.fingerprint is nullable: an event can be stored that no retry can be compared with');
  SELECT count(*) INTO n FROM pg_trigger
   WHERE tgrelid = 'ball_event'::regclass AND tgname = 'zz_ball_event_fingerprint' AND tgenabled = 'O';
  PERFORM _assert(n = 1, 'the trigger that stamps ball_event.fingerprint is missing or disabled');
  -- BEFORE triggers fire in name order; one after it could change the row
  -- the fingerprint was taken of. (tgtype: 2 = BEFORE, 4 = INSERT.)
  SELECT count(*) INTO n FROM pg_trigger
   WHERE tgrelid = 'ball_event'::regclass AND NOT tgisinternal
     AND (tgtype & 2) = 2 AND (tgtype & 4) = 4 AND tgname > 'zz_ball_event_fingerprint';
  PERFORM _assert(n = 0, 'a BEFORE INSERT trigger on ball_event runs after the fingerprint is taken');
  SELECT count(*) INTO n FROM ball_event;
  PERFORM _assert(n > 0, 'no ball_event rows are visible here to check fingerprints against');
  SELECT count(*) INTO n FROM ball_event b WHERE b.fingerprint IS DISTINCT FROM ball_event_fingerprint(b);
  PERFORM _assert(n = 0, 'a stored event carries a fingerprint that is not the canonical one');
  -- Blind to provenance: a retry under a new epoch, device, seq or clock is
  -- the same event, or every honest retry after a claim is a conflict.
  SELECT count(*) INTO n FROM ball_event b
   WHERE ball_event_fingerprint(b) <> ball_event_fingerprint(jsonb_populate_record(b, jsonb_build_object(
           'seq', b.seq + 1000, 'epoch', b.epoch + 1, 'device_id', 'another-device', 'client_seq', 0,
           'client_ts', now(), 'server_ts', now(), 'recovered', NOT b.recovered, 'id', b.id + 100000)));
  PERFORM _assert(n = 0, 'the fingerprint changes with how an event arrived — an honest retry would be refused');
  -- ...and not blind to content: one more run is a different event.
  SELECT count(*) INTO n FROM ball_event b
   WHERE ball_event_fingerprint(b) = ball_event_fingerprint(jsonb_populate_record(b, jsonb_build_object(
           'value', coalesce(b.value, 0) + 1)));
  PERFORM _assert(n = 0, 'two events that differ by a run share a fingerprint — a changed ball would pass as a retry');
  -- A NEW held event must carry one; only rows held before db/36 may not.
  SELECT count(*) INTO n FROM pg_trigger
   WHERE tgrelid = 'ball_event_quarantine'::regclass
     AND tgname = 'ball_event_quarantine_fingerprint_required' AND tgenabled = 'O';
  PERFORM _assert(n = 1, 'the trigger requiring a held event''s fingerprint is missing or disabled');
  BEGIN
    INSERT INTO ball_event_quarantine (match_id, school_id, submitted_epoch, current_epoch, scorer_user_id, device_id, idempotency_key, body)
    SELECT m.id, m.school_id, 9, 1, U_COACH, 'verify-device', 'verify:quarantine:nofp', '{}'::jsonb
      FROM match m WHERE m.school_id = '11111111-1111-1111-1111-111111111111' AND m.team_code = '1XI' LIMIT 1;
    PERFORM _assert(false, 'a new held event was stored with no fingerprint');
  EXCEPTION WHEN not_null_violation THEN NULL;
  END;

  PERFORM set_config('app.device_id', '', true);


  PERFORM _revoke('88888888-0000-0000-0000-000000000004');

  SELECT count(*) INTO n FROM player;
  PERFORM _assert(n = 0, 'a revoked assignment still grants access');

  -- ── 13. The officials register: open by name, closed by person ──
  -- The register is the one table here that belongs to no school, so it is
  -- the one place the tenant model cannot do the work. What replaces it: a
  -- read anybody signed in may make, a WRITE nobody but a platform-wide
  -- holder may make, and a masked view that keeps the person behind the name.
  PERFORM _as(U_PLAT);
  INSERT INTO official (full_name, born, id_number, email, phone, panel)
  VALUES ('V Pillay', '1982-06-03', '8206035000089', 'v.pillay@example.invalid',
          '+27 82 555 0100', 'KZN Cricket Umpires Association')
  RETURNING id INTO O_UMPIRE;
  INSERT INTO official_accreditation (official_id, level, issued_by, valid_from, valid_until)
  VALUES (O_UMPIRE, 'level2', 'KZNCUA', current_date - 400, current_date + 200);

  -- A school-scoped principal reads the panel. This is deliberate, not a
  -- leak: a director of sport about to appoint somebody has to see who is on
  -- it and at what grade, and the names are announced at the toss anyway.
  -- CHANGED BY DESIGN in db/107 (REACH-D5, Kameel 14 Oct 2026): she reads the
  -- panel through official_panel(), which names its columns, and NO row of
  -- the table itself — it holds ID numbers, and its keeper alone reads it.
  -- This assertion was `count(*) FROM official = 1`; §84 is the full proof.
  PERFORM _as(U_SARAH);
  SELECT count(*) INTO n FROM official_panel(O_UMPIRE);
  PERFORM _assert(n = 1, 'a school cannot see the officials panel at all');
  SELECT count(*) INTO n FROM official WHERE id = O_UMPIRE;
  PERFORM _assert(n = 0, 'a school reads the officials register''s raw row (db/107 closed it)');

  -- ...and reads NOTHING that makes them a person. Since db/107 the masked
  -- view returns her no row at all (it is security_invoker over the closed
  -- table), which is the stronger form of the same assertion.
  SELECT born INTO v_born FROM official_masked WHERE id = O_UMPIRE;
  PERFORM _assert(v_born IS NULL, 'a school reads an official''s date of birth');
  SELECT count(*) INTO n FROM official_masked
   WHERE id = O_UMPIRE AND (id_number IS NOT NULL OR email IS NOT NULL OR phone IS NOT NULL);
  PERFORM _assert(n = 0, 'a school reads an official''s ID number or contact details');

  -- The union does read them, or the register would hold nothing usable.
  PERFORM _as(U_PLAT);
  SELECT born INTO v_born FROM official_masked WHERE id = O_UMPIRE;
  PERFORM _assert(v_born IS NOT NULL, 'the register holder cannot read a date of birth');

  -- WRITING is the boundary that matters most. Sarah holds officiating.assign
  -- — she appoints officials to fixtures all season — and that must not let
  -- her put somebody on the panel or change what they are accredited to
  -- stand. Appointing from a panel and deciding the panel are different jobs.
  PERFORM _as(U_SARAH);
  BEGIN
    INSERT INTO official (full_name, born) VALUES ('Self Appointed', '1990-01-01');
    PERFORM _assert(false, 'a school-scoped role can add somebody to the officials register');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE official SET panel = 'Rewritten' WHERE id = O_UMPIRE;
    PERFORM _assert(NOT FOUND, 'a school-scoped role can edit the officials register');
  END;

  -- The grade is a span, so it answers "today", and stops answering when it
  -- lapses. A register that cannot tell those apart cannot refuse an
  -- appointment, which is the whole reason for keeping one. Sarah reads the
  -- grade through the panel (db/107: the accreditations are the keeper's);
  -- the span itself is asked of the keeper, who reads them.
  SELECT p.level INTO v_level FROM official_panel(O_UMPIRE) p;
  PERFORM _assert(v_level = 'level2', 'a current accreditation does not read as current');
  PERFORM _as(U_PLAT);
  SELECT official_level(O_UMPIRE) INTO v_level;
  PERFORM _assert(v_level = 'level2', 'a current accreditation does not read as current to the keeper');
  SELECT official_level(O_UMPIRE, current_date + 500) INTO v_level;
  PERFORM _assert(v_level IS NULL, 'a lapsed accreditation still reads as current');
  PERFORM _as(U_SARAH);

  -- ── A pupil without a date of birth cannot be written ─────────
  --
  -- The API refuses one at both doors, and this is the floor under that: a
  -- direct INSERT, a script, a future write path nobody has thought of yet.
  -- It matters because guardian_link_establish() refuses a link it cannot put
  -- an end date on, so a boy with no birthday is a boy whose family can never
  -- reach his record — and the office would not learn that until a parent
  -- asked.
  PERFORM _assert(EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'player_born_required' AND convalidated),
    'the date-of-birth constraint is missing or was never validated');

  -- ── How a batter is out is a closed list ──────────────────────
  --
  -- db/13: the dismissal column admits the eleven in the Laws and nothing
  -- else, validated over every row already here. A stray spelling used to
  -- credit the bowler with a wicket that was never his.
  PERFORM _assert(EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'ball_event_dismissal_known' AND convalidated),
    'the dismissal vocabulary constraint is missing or was never validated');

  -- ── Quarantine has a way out ──────────────────────────────────
  -- db/14. The door is a SECURITY DEFINER function that checks its own
  -- authority; the walk tools/smoke-quarantine.mjs exercises who may open it.
  PERFORM _assert(to_regprocedure('quarantine_resolve(bigint,boolean,jsonb,text)') IS NOT NULL,
    'quarantine_resolve() is missing — a quarantined ball has no way out');

  -- ── Every definer function names its search path ───────────────
  -- db/16. A SECURITY DEFINER function without a pinned search_path runs the
  -- owner's privileges over whatever schema a caller can put first. This
  -- verifier's own helpers (the _-prefixed ones above) are created inside this
  -- transaction and rolled back with it, so they are left out of the count.
  SELECT count(*) INTO n
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
   WHERE ns.nspname = 'public' AND p.prosecdef AND p.proname NOT LIKE '\_%'
     AND NOT EXISTS (SELECT 1 FROM unnest(coalesce(p.proconfig, '{}')) c WHERE c LIKE 'search_path=%');
  PERFORM _assert(n = 0,
    n || ' SECURITY DEFINER function(s) do not pin search_path — add "SET search_path = pg_catalog, public, pg_temp" or re-run db/16');

  -- ── A receipt is its owner's ──────────────────────────────────
  -- db/15. The idempotency layer remembers a write's response per person;
  -- another person with the same key must see nothing, or one account's
  -- receipt would answer another's request.
  PERFORM _as(U_COACH2);
  INSERT INTO request_replay (person_id, key, route, status, body)
  VALUES (U_COACH2, 'verify-key', 'POST /api/verify', 200, '{"ok":true}'::jsonb);
  PERFORM _as(U_MEDIC);
  SELECT count(*) INTO n FROM request_replay WHERE key = 'verify-key';
  PERFORM _assert(n = 0, 'a receipt is readable by somebody who is not its owner');
  BEGIN
    INSERT INTO request_replay (person_id, key, route, status, body)
    VALUES (U_COACH2, 'verify-key-2', 'POST /api/verify', 200, '{}'::jsonb);
    PERFORM _assert(false, 'a receipt can be written under another person''s name');
  EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM _as(U_COACH2);
  SELECT count(*) INTO n FROM request_replay WHERE key = 'verify-key';
  PERFORM _assert(n = 1, 'the owner cannot read back their own receipt');

  BEGIN
    INSERT INTO player (school_id, team_code, full_name) VALUES (HIL, '1XI', 'No Birthday');
    PERFORM _assert(false, 'a player was written with no date of birth');
  EXCEPTION WHEN check_violation OR insufficient_privilege THEN NULL;
  END;

  -- ── Guardianship ends at eighteen ──────────────────────────────
  --
  -- A guardian's access is co-ownership of a CHILD's record. The model had no
  -- way to say that: both creation paths wrote valid_until NULL, so a parent
  -- linked to a thirteen-year-old still read medical status, injury nature and
  -- the full passport when that person was thirty. These assertions are what
  -- stop it going back.

  -- Not one guardian link survives the seed open-ended without cause. Since
  -- db/62 (SCRBRD-110 §7.4) a link is open while the child is at school —
  -- the seed's pupils' links are, and the second assertion says so — and
  -- ends at the later of his majority and his leaving. So the claim is: an
  -- open link is a minor's or a pupil's, never an adult's out of school.
  -- Asked of the whole table rather than of one reader's view, because "I
  -- cannot see one" and "there is not one" are different claims and only
  -- the second is the point.
  PERFORM _assert(_count_open_guardian_links() = 0,
    'a guardian link is open-ended for an adult who is not at school');
  PERFORM _assert(_count_open_pupil_links() > 0,
    'no pupil at school has an open guardian link: db/62''s rule is not in use');

  -- Where a link has a date, it is the child's eighteenth birthday, not an
  -- approximation of it (a NULL date is the open link above, which <> skips).
  SELECT count(*) INTO n FROM assignment_subject s
    JOIN role_assignment a ON a.id = s.assignment_id AND a.role = 'guardian'
    JOIN player p ON p.id = s.player_id
   WHERE s.valid_until <> greatest(majority_on(p.born), s.valid_from);
  PERFORM _assert(n = 0, 'a guardian link ends on some date other than the child''s majority');

  -- The live half: a parent of a minor still reads their child today. Asserted
  -- alongside the expiry rather than trusting section 5, so that a change which
  -- expired EVERY link would fail here instead of passing quietly.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED AND born IS NOT NULL;
  PERFORM _assert(n = 1, 'a guardian of a minor cannot read their own child');

  -- The dead half, and the reason the seed carries an adult: a parent whose
  -- child has turned eighteen reads nothing of that child. Not a redacted row
  -- — no row.
  PERFORM _as(U_NAIDOO);
  SELECT count(*) INTO n FROM player_masked WHERE id = P_ADULT;
  PERFORM _assert(n = 0, 'a guardian still reads the record of a child who has turned eighteen');
  SELECT count(*) INTO n FROM injury;
  PERFORM _assert(n = 0, 'an expired guardian link still reaches injuries');

  -- ── The two refusals, and what a refusal must not leave behind ──
  PERFORM _as(U_REGISTRAR);

  -- Linking a guardian to someone already grown is refused. The office cannot
  -- re-open access to an adult's record by making a fresh link.
  --
  -- assignment_subject's own CHECK (valid_from <= valid_until) is a backstop
  -- here — removing the guard below does not let the link through, it makes
  -- the INSERT abort on a constraint violation instead. That is exactly the
  -- difference the guard buys: a named refusal the API can turn into a 422,
  -- rather than an exception that takes the caller's transaction with it.
  SELECT ok, reason INTO v_ok, v_reason
    FROM guardian_link_establish(U_BURSAR, P_ADULT, 'parent');
  PERFORM _assert(NOT v_ok AND v_reason = 'player_is_an_adult',
    'a guardian can be linked to a player who has turned eighteen');

  -- A refusal must leave NOTHING behind. guardian_link_establish() creates the
  -- guardian assignment before it reaches the subject row, and a plpgsql
  -- RETURN is not a rollback — so a guard placed after that INSERT would answer
  -- false and still leave a live guardian assignment standing, naming nobody.
  -- This is the assertion that catches it being moved back.
  PERFORM _assert(_count_guardian_assignments(U_BURSAR) = 0,
    'a refused guardian link left an assignment behind');

  -- No date of birth, no link. Guardianship is precisely where the age has to
  -- be known, and the honest answer is to refuse rather than assume.
  --
  -- The constraint is lifted for the one INSERT because db/11 now forbids this
  -- state outright. That does NOT make the guard below redundant: db/11 is
  -- NOT VALID, so a database that held such a boy before it landed holds him
  -- still, and he is exactly the child whose family must not be quietly given
  -- open-ended access. Restored immediately after.
  PERFORM _born_constraint(false);
  PERFORM _set_born(P_U13, NULL);
  PERFORM _born_constraint(true);
  SELECT ok, reason INTO v_ok, v_reason
    FROM guardian_link_establish(U_BURSAR, P_U13, 'parent');
  PERFORM _assert(NOT v_ok AND v_reason = 'player_date_of_birth_required',
    'a guardian was linked to a child with no recorded date of birth');
  PERFORM _assert(_count_guardian_assignments(U_BURSAR) = 0,
    'a link refused for want of a date of birth left an assignment behind');

  -- Restore the date, and the same call now succeeds: open, because he is
  -- at school (db/62); his own birthday for a boy who is not (section 40).
  PERFORM _set_born(P_U13, (current_date - interval '13 years')::date);
  SELECT ok INTO v_ok FROM guardian_link_establish(U_BURSAR, P_U13, 'parent');
  PERFORM _assert(v_ok, 'a guardian cannot be linked to a thirteen-year-old');
  PERFORM _assert(_count_subjects(P_U13) = 1, 'the link was not recorded');

  -- And asking twice says so, rather than writing a second row. This is not
  -- housekeeping: `already_linked` used to be decided by valid_until IS NULL,
  -- which no link satisfies now that every one of them carries an end date,
  -- so the duplicate would have gone in unnoticed.
  SELECT ok, reason INTO v_ok, v_reason
    FROM guardian_link_establish(U_BURSAR, P_U13, 'parent');
  PERFORM _assert(NOT v_ok AND v_reason = 'already_linked',
    'linking the same guardian to the same child twice was not refused');
  PERFORM _assert(_count_subjects(P_U13) = 1,
    'a duplicate guardian subject row was written for a child already linked');

  -- The two structural claims again, now that a link has been made THROUGH THE
  -- FUNCTION rather than by the seed. Asked twice on purpose: the first pair
  -- above runs before any link is created here, so on its own it only ever
  -- proves the seed's links, and guardian_link_establish() could quietly
  -- write NULL for the wrong child without a single assertion turning red.
  -- (Section 40 asks the same of a boy who is NOT at school: his birthday.)
  PERFORM _assert(_count_open_guardian_links() = 0,
    'guardian_link_establish created an open-ended link for an adult out of school');
  SELECT count(*) INTO n FROM _guardian_link_ends(P_U13, U_BURSAR) e WHERE e IS NULL;
  PERFORM _assert(n = 1 AND _count_subjects(P_U13) = 1,
    'guardian_link_establish did not leave a pupil''s link open while he is at school');
  SELECT count(*) INTO n FROM assignment_subject s
    JOIN role_assignment a ON a.id = s.assignment_id AND a.role = 'guardian'
    JOIN player p ON p.id = s.player_id
   WHERE s.valid_until <> greatest(majority_on(p.born), s.valid_from);
  PERFORM _assert(n = 0,
    'guardian_link_establish ended a link on some date other than the child''s majority');

  -- ── dob_gaps(): the two facts db/10 and db/11 could only log ────
  --
  -- Reuses P_U13 (B Khumalo) exactly as he stands after the block above: born
  -- restored, one live guardian link to U_BURSAR. Nothing below him is read
  -- again in this file, so nothing here needs to leave him as it found him.
  PERFORM _assert(to_regprocedure('dob_gaps()') IS NOT NULL,
    'dob_gaps() is missing — a NULL date of birth is invisible outside a migration log');

  -- A plain gap, with his guardian link left standing and still years from
  -- its own majority date. This is the case dob_gaps() must NOT confuse with
  -- an ended link: every link carries a future end date now, and a query that
  -- tested valid_until IS NOT NULL alone would call this one ended too.
  PERFORM _born_constraint(false);
  PERFORM _set_born(P_U13, NULL);
  PERFORM _born_constraint(true);
  PERFORM _as(U_REGISTRAR);
  SELECT count(*) INTO n FROM dob_gaps() WHERE kind = 'no_dob' AND player_id = P_U13;
  PERFORM _assert(n = 1, 'dob_gaps() did not surface a player with no date of birth');
  SELECT count(*) INTO n FROM dob_gaps() WHERE kind = 'guardian_link_ended' AND player_id = P_U13;
  PERFORM _assert(n = 0, 'dob_gaps() called a link years from its own end date "ended"');
  PERFORM _as(U_BURSAR);
  SELECT count(*) INTO n FROM dob_gaps() WHERE player_id = P_U13;
  PERFORM _assert(n = 0,
    'dob_gaps() showed a data-quality gap to somebody holding neither user.role.assign nor guardian.link.manage');

  -- The other half: the link wound back to its own start date — db/10's own
  -- effect, produced the same way _expire_link() proves expiry live above —
  -- with the birthday still missing. p.born IS NULL and s.valid_until in the
  -- past is the exact signature dob_gaps() reads, not a state asserted for
  -- the test's sake.
  PERFORM _expire_link(P_U13);
  PERFORM _as(U_REGISTRAR);
  SELECT count(*) INTO n FROM dob_gaps()
   WHERE kind = 'guardian_link_ended' AND player_id = P_U13
     AND guardian_id = U_BURSAR AND relationship = 'parent';
  PERFORM _assert(n = 1, 'dob_gaps() did not surface a guardian link ended for want of a date of birth');
  PERFORM _as(U_BURSAR);
  SELECT count(*) INTO n FROM dob_gaps() WHERE player_id = P_U13;
  PERFORM _assert(n = 0, 'dob_gaps() showed an ended guardian link to somebody holding neither capability');

  -- Restored. Nothing later reads P_U13 again, but leaving a child's own
  -- birthday nulled for the rest of the run is not a state worth risking.
  PERFORM _set_born(P_U13, (current_date - interval '13 years')::date);

  -- EXPIRY IS LIVE. Nothing runs between the two reads below but app_can(),
  -- which evaluates valid_until on every call — so there is no window in which
  -- a link is past its date and still working, and no scheduled job whose
  -- failure would silently hold access open.
  --
  -- LAST, because it deliberately winds a good link back to a date already
  -- past. Run earlier it would leave R Pillay's row failing the whole-table
  -- checks above, and the honest fix for that is to do it after them rather
  -- than to teach those checks to ignore a row.
  PERFORM _as(U_PARENT);
  SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED;
  PERFORM _assert(n = 1, 'the fixture for the expiry assertion is not readable to begin with');
  PERFORM _expire_link(P_INJURED);
  SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED;
  PERFORM _assert(n = 0, 'a guardian link past its end date still reads the child');

  -- ── Enrolment leaves nothing behind when it is refused ────────
  --
  -- enrol_person() writes the account, then answers the request through
  -- decide_role_request(). A refusal from that second step arrives with the
  -- account already on the table, so the writes sit in a subtransaction and
  -- the refusal is raised rather than returned.
  --
  -- THIS ASSERTION HAS TO LIVE HERE, in direct SQL, and that is the whole
  -- reason it was moved. Over HTTP withPrincipal() wraps every request in
  -- BEGIN/COMMIT and rolls back on a thrown error, so the API path discards
  -- the orphan whatever enrol_person() does — the walk in tools/smoke-enrol.mjs
  -- CANNOT fail on it, and it was checked: removing the subtransaction leaves
  -- all 31 of its assertions green. A guard nothing can falsify is a guard
  -- nobody will keep, so the falsifying assertion belongs where a caller is
  -- not wrapped in somebody else's transaction.
  PERFORM _as(U_REGISTRAR);
  -- Refused inside decide_role_request(), AFTER the account row is written:
  -- a coach is a coach of a side, and this one names none.
  SELECT ok, reason INTO v_ok, v_reason
    FROM enrol_person('orphan.coach@example.invalid', 'O Coach', 'coach', HIL, NULL, NULL, NULL);
  PERFORM _assert(NOT v_ok AND v_reason = 'team_required',
    'a coach was enrolled with no side');
  PERFORM _assert(_count_accounts('orphan.coach@example.invalid') = 0,
    'a refused enrolment left a half-made account behind');

  -- And the same call, given the side it was missing, does make one.
  SELECT ok INTO v_ok
    FROM enrol_person('real.coach@example.invalid', 'R Coach', 'coach', HIL, 'U13A', NULL, NULL);
  PERFORM _assert(v_ok, 'the office cannot enrol a coach of a named side');
  PERFORM _assert(_count_accounts('real.coach@example.invalid') = 1,
    'the enrolment did not create an account');

  -- ── The owner's key reaches every tenant ──────────────────────
  --
  -- `superadmin` holds all 82 capabilities on an assignment naming no school.
  -- It is the one role in the model that is not least-privilege, and these
  -- assertions are what stop it becoming one by accident: a bundle that
  -- quietly stopped being "everything" would leave the operator locked out of
  -- the thing they most need to reach, and nobody would find out until the day
  -- it mattered.
  -- Every capability but one domain: safeguarding.* is the owner's key's one
  -- carve-out (roles.mjs, db/57; CSA p63). Section 35 proves it reads no
  -- concern even when the rows are granted back.
  PERFORM _assert(
    (SELECT count(*) FROM role_capability WHERE role = 'superadmin')
      = (SELECT count(*) FROM capability WHERE name NOT LIKE 'safeguarding.%')
    AND NOT EXISTS (SELECT 1 FROM role_capability WHERE role = 'superadmin' AND capability LIKE 'safeguarding.%'),
    'the owner''s key does not hold every capability outside safeguarding.*, or holds one inside it');

  PERFORM _as(U_OWNER);

  -- Across tenants, which is the part a school-scoped role can never do:
  -- app_can() has no wildcard for school, so this works only because the
  -- assignment names none.
  SELECT count(DISTINCT school_id) INTO n FROM player_masked;
  PERFORM _assert(n >= 2, 'the owner''s key does not reach every school');

  -- Through the masking, not merely around the row filter. A reader who sees
  -- the row and a redacted column has not reached the record.
  SELECT count(*) INTO n FROM player_masked
   WHERE id = P_INJURED AND born IS NOT NULL AND guardian IS NOT NULL;
  PERFORM _assert(n = 1, 'the owner''s key reads a player row but not its protected columns');
  SELECT count(*) INTO n FROM injury;
  PERFORM _assert(n > 0, 'the owner''s key cannot read injuries');

  -- AND IT IS STILL RLS, not a bypass. The rows arrive because the policies
  -- said yes to this principal, which is why signing out of the role takes the
  -- access away — a superuser connection would not behave like this.
  PERFORM set_config('app.user_id', '', true);
  SELECT count(*) INTO n FROM player_masked;
  PERFORM _assert(n = 0, 'the owner''s key is a connection privilege rather than an assignment');

  -- Nobody mints an owner's key from inside the platform account. platformadmin
  -- is the recovery path and may grant every OTHER role; letting it grant this
  -- one would make the two roles the same thing, one assignment apart.
  PERFORM _assert(NOT EXISTS (
    SELECT 1 FROM role_grantable WHERE granter = 'platformadmin' AND role = 'superadmin'),
    'the platform account can appoint an owner''s key');
  PERFORM _assert(EXISTS (
    SELECT 1 FROM role_grantable WHERE granter = 'superadmin' AND role = 'platformadmin'),
    'the owner''s key cannot appoint a platform account');

  -- ── The newsfeed: three tiers, three audiences ────────────────
  --
  -- news.read and the three publish capabilities were in the model from the
  -- first migration with nothing behind them. These assertions are what makes
  -- the tiers mean something: each is a different AUDIENCE, derived from the
  -- post's anchor, and a tier reaching the same people as the one above it
  -- would not be worth having as its own capability.
  --
  -- NOT the 1XI coach, though he is the obvious reader for a 1XI notice:
  -- section 8 above revokes his assignments to prove revocation narrows, and
  -- this file is one transaction, so he holds nothing by the time it gets
  -- here. The first draft of this block used him and reported zero rows for
  -- every tier — which read like a broken policy and was a dead principal.
  PERFORM _as(U_SARAH);
  SELECT count(*) INTO n FROM news_post WHERE scope = 'team';
  PERFORM _assert(n = 1, 'the director of sport cannot read a side''s notice');
  SELECT count(*) INTO n FROM news_post WHERE scope = 'school';
  PERFORM _assert(n >= 1, 'the director of sport cannot read the school''s notice');
  -- The competition post belongs to NO school. It reaches her because her
  -- school is entered — app_can() has no wildcard for school, so this works
  -- only through competition_entrant.
  SELECT count(*) INTO n FROM news_post WHERE scope = 'competition';
  PERFORM _assert(n = 1, 'a league notice does not reach a school entered in it');

  -- A DRAFT IS NOT A NOTICE. The unsent school post is Sarah''s, and she is
  -- the only person who has it.
  SELECT count(*) INTO n FROM news_post WHERE published_at IS NULL;
  PERFORM _assert(n = 1, 'an author cannot see their own draft');
  PERFORM _as(U_MEDIC);
  SELECT count(*) INTO n FROM news_post WHERE published_at IS NULL;
  PERFORM _assert(n = 0, 'an unsent draft is readable by somebody who did not write it');

  -- A team notice reaches THAT side. Westville''s office administers another
  -- tenant: it reads neither Hilton''s team post nor Hilton''s school post,
  -- and does read the league notice, because Westville is entered in it.
  PERFORM _as('88888888-0000-0000-0000-00000000000d'::uuid);
  SELECT count(*) INTO n FROM news_post WHERE school_id = HIL;
  PERFORM _assert(n = 0, 'another school reads this school''s notices');
  SELECT count(*) INTO n FROM news_post WHERE scope = 'competition';
  PERFORM _assert(n = 1, 'a league notice does not reach the other school entered in it');

  -- ── The tier is the scope, and it is enforced on the write ────
  -- The 2XI coach holds news.publish.team and not news.publish.school. He
  -- cannot reach the whole school by naming a different anchor: the INSERT
  -- policy reads the anchor to decide which capability to demand.
  PERFORM _as(U_COACH2);
  BEGIN
    INSERT INTO news_post (scope, school_id, title, body, published_at)
    VALUES ('school', HIL, 'A coach speaks for the school', 'Not his to send.', now());
    PERFORM _assert(false, 'a coach posted a notice to the whole school');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  -- ...and can post to his own side.
  INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
  VALUES ('team', HIL, '2XI', 'Bus leaves at seven', 'Front gate.', now());
  SELECT count(*) INTO n FROM news_post WHERE title = 'Bus leaves at seven';
  PERFORM _assert(n = 1, 'a coach cannot post to his own side');
  -- The byline is the session, not the caller''s word for it.
  SELECT count(*) INTO n FROM news_post
   WHERE title = 'Bus leaves at seven' AND author_id = U_COACH2;
  PERFORM _assert(n = 1, 'the author was not stamped from the session');

  -- news.read WITHOUT a tier is the shape twenty-three of twenty-five roles
  -- have: read everything meant for you, publish nothing.
  PERFORM _as(U_MEDIC);
  BEGIN
    INSERT INTO news_post (scope, school_id, title, body, published_at)
    VALUES ('school', HIL, 'The physio speaks for the school', 'No.', now());
    PERFORM _assert(false, 'a role with no publish tier published a school notice');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- ── A module switched off is off in the database too ────────────
  --
  -- SCRBRD-014. The module gate is two gates reading one function: the read
  -- API refuses a resource a module owns, the write dispatcher refuses a
  -- route tagged with it, both through my_feature_enabled(), both over HTTP,
  -- both walked by tools/smoke-modules.mjs. This is the half an HTTP walk
  -- cannot reach: the resolver itself, under the policies, as the people
  -- concerned — and the one place the database gates a write on a flag by
  -- itself, a fixture in a sport the school has not been granted: refused,
  -- granted, allowed, on a direct INSERT.
  --
  -- Said plainly, because it is the boundary: injury, training_session,
  -- player_skill and the rest carry no trigger of their own. Their only door
  -- is the API and the route tag is the gate. A write that reaches Postgres
  -- some other way is carrying the schema owner's credentials, and a product
  -- switch is not what stands between that and the data.
  PERFORM _as(U_MEDICAL);
  PERFORM _assert(my_feature_enabled('injuries'),
    'Injuries reads as off for the physio before anybody switched it off');
  PERFORM _as(U_REGISTRAR);
  INSERT INTO feature_suppression (key, school_id, hidden_by, reason)
  VALUES ('injuries', HIL, U_REGISTRAR, 'verify: switched off');
  PERFORM _as(U_MEDICAL);
  PERFORM _assert(NOT my_feature_enabled('injuries'),
    'a school hid Injuries and the resolver still answers on for its physio');
  -- Off at any school you belong to is off. Sarah is Hilton's head of sport
  -- and a Westville parent; Westville did not hide anything, and she is still
  -- refused — the safe direction, and the one the API collapses to.
  PERFORM _as(U_SARAH);
  PERFORM _assert(NOT my_feature_enabled('injuries'),
    'a person assigned at two schools reads a module one of them hid');
  PERFORM _as('88888888-0000-0000-0000-00000000000d'::uuid);   -- Westville's registrar
  PERFORM _assert(my_feature_enabled('injuries'),
    'hiding a module at one school hid it at the other');
  -- A coach cannot lift it: school.feature.manage, at that school. The
  -- UPDATE policy filters rather than raises, so the proof is that it is
  -- still off afterwards.
  PERFORM _as(U_COACH2);
  UPDATE feature_suppression SET lifted_at = now(), lifted_by = U_COACH2
   WHERE key = 'injuries' AND school_id = HIL AND lifted_at IS NULL;
  PERFORM _as(U_MEDICAL);
  PERFORM _assert(NOT my_feature_enabled('injuries'),
    'a coach lifted a suppression his school administrator made');
  PERFORM _as(U_REGISTRAR);
  UPDATE feature_suppression SET lifted_at = now(), lifted_by = U_REGISTRAR
   WHERE key = 'injuries' AND school_id = HIL AND lifted_at IS NULL;
  PERFORM _as(U_MEDICAL);
  PERFORM _assert(my_feature_enabled('injuries'),
    'the school lifted the suppression and Injuries stayed off');

  -- The write the database gates itself. Hockey ships off; the platform
  -- grants it; the same INSERT then goes through.
  PERFORM _as(U_REGISTRAR);
  BEGIN
    INSERT INTO match (school_id, team_code, opponent, starts_at, sport, status)
    VALUES (HIL, '1XI', 'Kearsney', now() + interval '3 days', 'hockey', 'scheduled');
    PERFORM _assert(false, 'a fixture was written in a sport the school has not been granted');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  PERFORM _as(U_PLAT);
  INSERT INTO feature_grant (key, school_id, granted, changed_by)
  VALUES ('sport_hockey', HIL, true, U_PLAT);
  PERFORM _as(U_REGISTRAR);
  INSERT INTO match (school_id, team_code, opponent, starts_at, sport, status)
  VALUES (HIL, '1XI', 'Kearsney', now() + interval '3 days', 'hockey', 'scheduled');
  SELECT count(*) INTO n FROM match WHERE sport = 'hockey' AND opponent = 'Kearsney';
  PERFORM _assert(n = 1, 'the platform granted hockey and the fixture was still refused');

  -- ── A read across every tenant is on the record ────────────────
  -- SCRBRD-026. The owner's key and a platform administrator's reach every
  -- school; db/20 makes the log say so, decided at write time by the same
  -- liveness rule as everything else about the reader.
  PERFORM _as(U_OWNER);
  PERFORM _assert(app_is_platform_wide(), 'the owner does not read as platform-wide');
  PERFORM _as(U_PLAT);
  PERFORM _assert(app_is_platform_wide(), 'a platform administrator does not read as platform-wide');
  PERFORM _as(U_REGISTRAR);
  PERFORM _assert(NOT app_is_platform_wide(), 'a school administrator reads as platform-wide');
  PERFORM _as(U_SARAH);
  PERFORM _assert(NOT app_is_platform_wide(), 'two school assignments add up to the platform');
  -- The row carries the answer, stamped by the function and not by the
  -- caller: the same call, from the owner and from the school's own office.
  PERFORM _as(U_OWNER);
  PERFORM log_restricted_read('players', ARRAY[P_INJURED], ARRAY['born'], HIL);
  PERFORM _as(U_REGISTRAR);
  PERFORM log_restricted_read('players', ARRAY[P_INJURED], ARRAY['born'], HIL);
  -- Read back as the school's own auditor: both rows are theirs to see, and
  -- exactly one of them is a read from outside the school.
  PERFORM _as(U_SARAH);   -- director of sport at Hilton: audit.read
  SELECT count(*) INTO n FROM access_log
   WHERE school_id = HIL AND resource = 'players' AND person_id = U_OWNER AND platform_wide;
  PERFORM _assert(n = 1,
    'the owner''s read of a school''s roster is not marked platform-wide in that school''s log');
  SELECT count(*) INTO n FROM access_log
   WHERE school_id = HIL AND resource = 'players' AND person_id = U_REGISTRAR AND NOT platform_wide;
  PERFORM _assert(n = 1, 'a school''s own read of its own roster was marked platform-wide');


  -- ── SCRBRD-012: support access is an hour, at one school, on the record ──
  --
  -- platformadmin holds no school's roles, so a platform administrator reads
  -- nothing of a school. support_access_begin() hands them ONE role at ONE
  -- school for the minutes asked, as a real assignment with an hour hand —
  -- role_assignment.expires_at (db/22) — that app_can() reads on every
  -- statement (db/23). Every read under it is stamped in the school's log,
  -- and the school's own office can end it.
  PERFORM _as(U_PLAT);
  SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
  PERFORM _assert(n = 0, 'a platform administrator reads a school''s roster without support access');

  -- Refusals first, each for its own reason.
  PERFORM _as(U_SARAH);
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'schooladmin', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', 'somebody without platform.support.impersonate began a support session');
  PERFORM _as(U_PLAT);
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'platformadmin', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'role_not_supportable', 'a platform role was issued at a school');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'superadmin', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'role_not_supportable', 'the owner''s key was issued as support');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'guardian', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'role_needs_subject', 'support was issued as somebody''s parent');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'nosuchrole', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'role_unknown', 'a role that does not exist was issued');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'schooladmin', 'fix');
  PERFORM _assert(NOT v_ok AND v_reason = 'reason_required', 'a support session began with no reason worth reading');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'schooladmin', 'ticket 4411: roster import failing', NULL, 0);
  PERFORM _assert(NOT v_ok AND v_reason = 'minutes_out_of_range', 'a support session of no minutes began');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'schooladmin', 'ticket 4411: roster import failing', NULL, 241);
  PERFORM _assert(NOT v_ok AND v_reason = 'minutes_out_of_range', 'a support session longer than four hours began');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin('00000000-0000-0000-0000-000000000000', 'schooladmin', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'school_unknown', 'support was issued at a school that does not exist');

  -- The door opens: one role, one school, sixty minutes.
  SELECT ok, reason, id, expires_at INTO v_ok, v_reason, S_ID, S_EXP
    FROM support_access_begin(HIL, 'schooladmin', 'ticket 4411: roster import failing');
  PERFORM _assert(v_ok, 'a platform administrator could not begin support access: ' || coalesce(v_reason, '?'));
  PERFORM _assert(S_EXP > now() + interval '59 minutes' AND S_EXP <= now() + interval '60 minutes',
    'the default support session is not an hour');
  SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
  PERFORM _assert(n > 0, 'support access at Hilton reads nothing of Hilton');
  SELECT count(*) INTO n FROM player_masked WHERE school_id = WES;
  PERFORM _assert(n = 0, 'support access at Hilton reads Westville');
  PERFORM _assert(app_support_access_id(HIL) = S_ID, 'the live session is not the one reported for Hilton');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_begin(HIL, 'schooladmin', 'ticket 4411: roster import failing');
  PERFORM _assert(NOT v_ok AND v_reason = 'already_live', 'the same support session was issued twice');

  -- Every read under it is on the record, stamped with the session, in the
  -- school's own log — and the session record is theirs to read.
  PERFORM log_restricted_read('players', ARRAY[P_INJURED], ARRAY['born'], HIL);
  PERFORM _as(U_SARAH);   -- audit.read at Hilton
  -- Both stamps at once: platform_wide says WHO read (a key that answers to
  -- no school, db/20), support_access_id says THROUGH WHICH DOOR.
  SELECT count(*) INTO n FROM access_log
   WHERE school_id = HIL AND person_id = U_PLAT AND support_access_id = S_ID AND platform_wide;
  PERFORM _assert(n = 1, 'a read under support access is not stamped with the session in the school''s log');
  SELECT count(*) INTO n FROM support_access WHERE id = S_ID;
  PERFORM _assert(n = 1, 'the school''s auditor cannot see the support session at their school');
  PERFORM _as(U_COACH);
  SELECT count(*) INTO n FROM support_access WHERE id = S_ID;
  PERFORM _assert(n = 0, 'a coach can read the support session record');

  -- The school ends it. Not the platform: the school.
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_end(S_ID);
  PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', 'a coach ended a support session');
  PERFORM _as(U_SARAH);   -- user.role.assign at Hilton
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_end(S_ID);
  PERFORM _assert(v_ok, 'the school''s office could not end a support session at their school');
  PERFORM _as(U_PLAT);
  SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
  PERFORM _assert(n = 0, 'an ended support session still reads the school');
  SELECT ok, reason INTO v_ok, v_reason FROM support_access_end(S_ID);
  PERFORM _assert(v_ok AND v_reason = 'already_ended', 'ending a session twice is not safe');
  PERFORM _as(U_SARAH);
  SELECT count(*) INTO n FROM support_access WHERE id = S_ID AND ended_by = U_SARAH AND ended_at IS NOT NULL;
  PERFORM _assert(n = 1, 'the record does not say who ended the session');

  -- EXPIRY IS LIVE. Wind the hour hand back and read again: no job, no window.
  PERFORM _as(U_PLAT);
  SELECT ok, reason, id INTO v_ok, v_reason, S_ID
    FROM support_access_begin(HIL, 'schooladmin', 'ticket 4412: the second look');
  PERFORM _assert(v_ok, 'a second support session could not begin after the first ended');
  SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
  PERFORM _assert(n > 0, 'the second support session reads nothing');
  PERFORM _expire_support(S_ID);
  SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
  PERFORM _assert(n = 0, 'a support session past its hour still reads the school');
  PERFORM _assert(app_support_access_id(HIL) IS NULL, 'an expired session is still reported as live');
  -- ...and an ordinary appointment, with no hour hand, is untouched by any of it.
  PERFORM _as(U_SARAH);
  SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
  PERFORM _assert(n > 0, 'the hour hand stopped an ordinary appointment');

  -- ── SCRBRD-034 (db/30): an hour hand always carries a reason ──
  --
  -- expires_at is the support session's hour hand, and support_access_begin()
  -- will not issue one without a reason. role_assignment_write let the
  -- school's office write one directly — an INSERT naming expires_at, or an
  -- UPDATE moving a live session's hour forward — with no reason and no
  -- record. db/30's check is DEFERRED to commit, because the support path
  -- writes the assignment before the record; this file ends in ROLLBACK and
  -- never commits, so each assertion fires the pending check on the spot
  -- with SET CONSTRAINTS ... IMMEDIATE.
  --
  -- The support path itself passes: a session issued, checked at once. The
  -- same statement also fires the checks queued by every begin and every
  -- _expire_support() above — winding an hour hand BACK stays within what
  -- was issued.
  PERFORM _as(U_PLAT);
  SELECT ok, reason, id INTO v_ok, v_reason, S_ID
    FROM support_access_begin(HIL, 'schooladmin', 'ticket 4413: the third look, checked at once');
  PERFORM _assert(v_ok, 'a support session could not begin under the expiry check: ' || coalesce(v_reason, '?'));
  SET CONSTRAINTS role_assignment_expiry_has_reason IMMEDIATE;
  SET CONSTRAINTS role_assignment_expiry_has_reason DEFERRED;

  -- A direct time-boxed grant: the office may appoint an analyst, and may
  -- not give the appointment an hour hand with nothing saying why.
  PERFORM _as(U_SARAH);   -- user.role.assign at Hilton; directorofsport may grant analyst
  BEGIN
    INSERT INTO role_assignment (person_id, role, school_id, expires_at)
    VALUES (U_WATCHER, 'analyst', HIL, now() + interval '1 hour');
    SET CONSTRAINTS role_assignment_expiry_has_reason IMMEDIATE;
    PERFORM _assert(false, 'a time-boxed assignment was written with no support session behind it');
  EXCEPTION WHEN check_violation THEN
    PERFORM _assert(SQLERRM LIKE '%no support session%', 'the direct grant was refused for another reason: ' || SQLERRM);
  END;
  SET CONSTRAINTS role_assignment_expiry_has_reason DEFERRED;
  -- The same appointment with no hour hand is an ordinary one, and is not
  -- this check's business. Undone by raising past it, so U_WATCHER keeps
  -- holding nothing for the assertions that rely on that.
  BEGIN
    INSERT INTO role_assignment (person_id, role, school_id)
    VALUES (U_WATCHER, 'analyst', HIL);
    SET CONSTRAINTS role_assignment_expiry_has_reason IMMEDIATE;
    RAISE EXCEPTION USING ERRCODE = 'ZZ034', MESSAGE = 'undo';
  EXCEPTION WHEN sqlstate 'ZZ034' THEN NULL;
  END;
  SET CONSTRAINTS role_assignment_expiry_has_reason DEFERRED;

  -- Moving a live session's hour FORWARD is a longer session than the reason
  -- was given for. The school's office holds the UPDATE policy over it.
  SELECT s.assignment_id, s.expires_at INTO A_ID, v_until FROM support_access s WHERE s.id = S_ID;
  PERFORM _assert(A_ID IS NOT NULL, 'the school''s auditor cannot see the live support session');
  BEGIN
    UPDATE role_assignment SET expires_at = v_until + interval '1 day' WHERE id = A_ID;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, 'the office could not reach the support assignment at all — the next assertion would prove nothing');
    SET CONSTRAINTS role_assignment_expiry_has_reason IMMEDIATE;
    PERFORM _assert(false, 'a support session''s hour was extended past what its reason was given for');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  SET CONSTRAINTS role_assignment_expiry_has_reason DEFERRED;
  -- ...nor taken OFF, which would make the hour's support permanent while the
  -- support record still reads as over.
  SELECT s.assignment_id INTO A_ID FROM support_access s WHERE s.id = S_ID;
  BEGIN
    UPDATE role_assignment SET expires_at = NULL WHERE id = A_ID;
    PERFORM _assert(false, 'a support session''s hour was removed, making it permanent');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  PERFORM _assert((SELECT expires_at FROM role_assignment WHERE id = A_ID) IS NOT NULL,
    'the support assignment lost its hour');
  -- ...an ordinary appointment cannot be given one after the fact either.
  SELECT a.id INTO A_ID FROM role_assignment a
   WHERE a.person_id = U_COACH2 AND a.active AND a.expires_at IS NULL LIMIT 1;
  BEGIN
    UPDATE role_assignment SET expires_at = now() + interval '1 hour' WHERE id = A_ID;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, 'the office could not reach the 2XI coach''s appointment — the next assertion would prove nothing');
    SET CONSTRAINTS role_assignment_expiry_has_reason IMMEDIATE;
    PERFORM _assert(false, 'an ordinary appointment was given an hour hand with no reason');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  SET CONSTRAINTS role_assignment_expiry_has_reason DEFERRED;
  -- The session this block opened is ended, so nothing below inherits it.
  SELECT ok INTO v_ok FROM support_access_end(S_ID);
  PERFORM _assert(v_ok, 'the school could not end the third support session');

  -- ── SCRBRD-054: a correction takes two people, in the database ──
  --
  -- db/02's INSERT policy on scoring_amendment asked for `scoring.correct`,
  -- which the director of sport holds for session recovery and which also
  -- made her the requester of the corrections she approves. db/24 moved the
  -- request onto `scoring.amend.request`, held by the scorer. Proven here as
  -- Postgres enforces it, not as roles.mjs describes it: Sarah, who approves,
  -- cannot file; the scorer, who files, can — and Sarah still holds what
  -- `scoring.correct` recovers, because taking that away was the wrong fix.
  PERFORM _assert(
    NOT EXISTS (SELECT 1 FROM role_capability
                 WHERE role IN ('directorofsport', 'competitionadmin')
                   AND capability = 'scoring.amend.request'),
    'an approver holds the request as well');
  PERFORM _assert(
    (SELECT count(*) FROM role_capability
      WHERE role IN ('directorofsport', 'competitionadmin') AND capability = 'scoring.correct') = 2,
    'session recovery was withdrawn from the roles that need it at the ground');
  PERFORM _as(U_SARAH);
  BEGIN
    INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
    VALUES ('77777777-0000-0000-0000-000000000001', HIL, 'verify-key', 'Filed by an approver.', U_SARAH);
    PERFORM _assert(false, 'a director of sport filed an amendment request');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM _as(U_SCORER);
  INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
  VALUES ('77777777-0000-0000-0000-000000000001', HIL, 'verify-key', 'Filed by the scorer.', U_SCORER);
  SELECT count(*) INTO n FROM scoring_amendment WHERE target_key = 'verify-key' AND requested_by = U_SCORER;
  PERFORM _assert(n = 1, 'the scorer could not file an amendment request');

  -- ── SCRBRD-053: the disciplinary record, and the six grants on it ──
  --
  -- `discipline.read` and `discipline.write` sat in the catalogue and in six
  -- role bundles gating nothing at all. db/25 is the record they now gate,
  -- and the point of asserting it here rather than in the model suites is
  -- that the policy is HAND-WRITTEN: the table is born after db/09, so
  -- generate-rls.mjs never sees it, and nothing but these assertions and the
  -- ones inside db/25 would notice if a predicate were wrong.
  --
  -- Nobody without the capability, first — AND THE PRINCIPAL MATTERS HERE.
  -- Medical staff are the one seeded account at Hilton whose refusal is
  -- attributable to the capability and to nothing else: the assignment is
  -- school-scoped with a NULL team, names no subject and names no fixture, so
  -- every other dimension of app_can() passes and only `discipline.write`
  -- is missing. A coach would be refused twice over — no capability AND a
  -- team anchor that is not his side — which tables.mjs's own note on derived
  -- anchors warns about: the falsification that does not fail because
  -- something else was already refusing. Granting `medical` the read and
  -- watching this block go red is how that was checked rather than assumed.
  PERFORM _as(U_MEDICAL);
  BEGIN
    INSERT INTO disciplinary_record (player_id, school_id, recorded_by, body)
    VALUES (P_INJURED, HIL, U_MEDICAL, 'Filed by somebody with no disciplinary authority.');
    PERFORM _assert(false, 'medical staff filed a disciplinary record');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- THE UMPIRE'S APPOINTMENT IS ONE FIXTURE, and that is the whole of his
  -- authority here. app_can() refuses a fixture-scoped assignment on a row
  -- that does not state the same fixture, so the match he stood at is the
  -- only match he can file about — and a row naming no fixture at all is
  -- refused too, because NULL on the resource narrows.
  PERFORM _as(U_UMPIRE);
  BEGIN
    INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
    VALUES (P_INJURED, HIL, M_OTHER, U_UMPIRE, 'Filed about a fixture he did not stand at.');
    PERFORM _assert(false, 'an official filed an incident at a fixture he was not appointed to');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    INSERT INTO disciplinary_record (player_id, school_id, recorded_by, body)
    VALUES (P_INJURED, HIL, U_UMPIRE, 'Filed against the school at large.');
    PERFORM _assert(false, 'an official filed a matter with no fixture behind it');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  INSERT INTO disciplinary_record (player_id, school_id, match_id, recorded_by, body)
  VALUES (P_INJURED, HIL, M_STOOD, U_UMPIRE, 'Dissent at the umpire''s decision; sent from the field.');

  -- ...AND HE CANNOT READ IT BACK. `official` holds discipline.write and not
  -- discipline.read — the mirror of schooladmin, who reads and cannot write.
  -- This is also why neither write path uses RETURNING: Postgres applies the
  -- SELECT policy to a row an INSERT returns, so `returning id` would have
  -- refused the writer this capability exists for.
  SELECT count(*) INTO n FROM disciplinary_record;
  PERFORM _assert(n = 0, 'an official can read the disciplinary record he filed');

  -- Authorship is the session's, never the payload's.
  PERFORM _as(U_SARAH);
  SELECT id INTO D_ID FROM disciplinary_record WHERE match_id = M_STOOD;
  PERFORM _assert(
    (SELECT recorded_by FROM disciplinary_record WHERE id = D_ID) = U_UMPIRE,
    'the record does not name the person who actually filed it');

  -- The school-side readers, each for its own scope reason.
  SELECT count(*) INTO n FROM disciplinary_record WHERE id = D_ID;
  PERFORM _assert(n = 1, 'the director of sport cannot read a record at her own school');
  PERFORM _as(U_HEAD_M);
  SELECT count(*) INTO n FROM disciplinary_record WHERE id = D_ID;
  PERFORM _assert(n = 1, 'the principal cannot read a record at his own school');
  -- A pupil reads HIS OWN and nobody else's: `selfaccess` is subject-scoped,
  -- so the person anchor on the row has to be the child his assignment names.
  PERFORM _as(U_SELF);
  SELECT count(*) INTO n FROM disciplinary_record WHERE id = D_ID;
  PERFORM _assert(n = 1, 'a pupil cannot read his own disciplinary record');
  -- Another pupil, and medical staff: both school-scoped with a NULL team and
  -- no subject, so the capability is the only thing refusing either of them.
  PERFORM _as(U_PUPIL);
  SELECT count(*) INTO n FROM disciplinary_record;
  PERFORM _assert(n = 0, 'another pupil at the school reads it');
  PERFORM _as(U_MEDICAL);
  SELECT count(*) INTO n FROM disciplinary_record;
  PERFORM _assert(n = 0, 'medical staff read a disciplinary record');
  -- A coach is refused twice — no capability, and a team anchor that is not
  -- his side. Worth asserting because it is the case a school would actually
  -- worry about, and worth labelling because it would keep passing if the
  -- capability check were removed.
  PERFORM _as(U_COACH2);
  SELECT count(*) INTO n FROM disciplinary_record;
  PERFORM _assert(n = 0, 'a coach reads another side''s disciplinary record');
  -- The tenant line holds: Westville's office reads Westville's.
  PERFORM _as(U_WES_ADM);
  SELECT count(*) INTO n FROM disciplinary_record;
  PERFORM _assert(n = 0, 'another school''s administrator reads Hilton''s disciplinary record');

  -- NOT ANY MORE (READERS_child_data Q10, db/116). A competition
  -- administrator's assignment names no school, and a NULL school on the
  -- ASSIGNMENT widens to every school — so the league used to read this, and
  -- every conduct record at every school, without a line anywhere saying so.
  -- It holds no discipline.read now: it reads the records that arose from its
  -- own competition's fixtures, through competition_discipline_records()
  -- (§93), and this match is in no competition.
  PERFORM _as(U_LEAGUE);
  SELECT count(*) INTO n FROM disciplinary_record WHERE id = D_ID;
  PERFORM _assert(n = 0, 'the competition administrator reads a school''s disciplinary record by standing (READERS Q10)');
  SELECT count(*) INTO n FROM competition_discipline_records(NULL) r WHERE r.id = D_ID;
  PERFORM _assert(n = 0, 'the league reads a record from a match in no competition (READERS Q10)');
  PERFORM _assert(app_is_platform_wide(), 'a competition administrator is not treated as a platform-wide reader');

  -- THE ACCOUNT IS THE AUTHOR'S; THE OUTCOME IS THE SCHOOL'S. The director of
  -- sport did not write this and may not rewrite it, and she is exactly the
  -- person who has to be able to conclude it.
  PERFORM _as(U_SARAH);
  BEGIN
    UPDATE disciplinary_record SET body = 'Rewritten by somebody else.' WHERE id = D_ID;
    PERFORM _assert(false, 'a non-author rewrote the account of a disciplinary matter');
  EXCEPTION WHEN sqlstate '45001' THEN NULL;
  END;
  BEGIN
    UPDATE disciplinary_record SET player_id = P_U16B WHERE id = D_ID;
    PERFORM _assert(false, 'a disciplinary record was re-filed against another child');
  EXCEPTION WHEN sqlstate '45002' THEN NULL;
  END;
  BEGIN
    UPDATE disciplinary_record SET state = 'concluded' WHERE id = D_ID;
    PERFORM _assert(false, 'a matter was concluded without saying what happened');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  UPDATE disciplinary_record SET state = 'concluded',
         outcome = 'Two matches missed; apology delivered to the umpire.' WHERE id = D_ID;
  SELECT count(*) INTO n FROM disciplinary_record
   WHERE id = D_ID AND state = 'concluded' AND recorded_by = U_UMPIRE AND updated_at IS NOT NULL;
  PERFORM _assert(n = 1, 'the school could not conclude a matter an official filed');

  -- Nothing here can be erased, at either layer.
  PERFORM _assert(
    NOT EXISTS (SELECT 1 FROM pg_policy
                 WHERE polrelid = 'disciplinary_record'::regclass AND polcmd = 'd'),
    'disciplinary_record has a delete policy');

  -- ── 14. A plain claim cannot jump a handover (SCRBRD-059, db/28) ─
  -- The scoring screen makes a plain scoring_claim() on ordinary mount. While
  -- a handover is armed or being verified that claim must be refused by the
  -- DATABASE, naming the state — the client's own pre-check is a courtesy a
  -- direct API call never meets. Driven through the real functions, as the
  -- scorer (outgoing, device a) and Sarah (incoming, device b; she also holds
  -- scoring.correct, which the recovery at the end needs).
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SCORER);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-059-a') c;
  PERFORM _assert(v_ok AND v_epoch = 1, 'the scorer could not claim an idle match');
  SELECT a.ok, a.code INTO v_ok, v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-059-a', 0, false) a;
  PERFORM _assert(v_ok AND v_code ~ '^\d{6}$', 'the scorer could not arm a handover');

  -- Armed: another device's plain claim is refused as handover_pending.
  PERFORM _as(U_SARAH);
  SELECT c.ok, c.reason, c.epoch INTO v_ok, v_reason, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-059-b') c;
  PERFORM _assert(NOT v_ok AND v_reason = 'handover_pending' AND v_epoch = 1,
    format('a plain claim jumped an armed handover (ok=%s reason=%s)', v_ok, v_reason));
  SELECT count(*) INTO n FROM scoring_session
   WHERE match_id = M_HANDOVER AND state = 'handover_pending' AND handover_code = v_code AND epoch = 1;
  PERFORM _assert(n = 1, 'a refused claim still disturbed the armed handover');
  -- The arming device's string, sent by somebody else, is not the arming holder.
  SELECT c.reason INTO v_reason FROM scoring_claim(M_HANDOVER, 'verify-059-a') c;
  PERFORM _assert(v_reason IS NOT DISTINCT FROM 'handover_pending',
    'another user claimed an armed handover by naming the arming device');
  -- Not lease-gated: nothing refreshes the outgoing lease once it is armed.
  PERFORM _lapse_scoring_lease(M_HANDOVER);
  SELECT c.reason INTO v_reason FROM scoring_claim(M_HANDOVER, 'verify-059-b') c;
  PERFORM _assert(v_reason IS NOT DISTINCT FROM 'handover_pending',
    'an armed handover was claimable once the outgoing lease lapsed');

  -- The arming device and user taking it back is the client's cancel
  -- (apps/web/src/lib/handover.js) and must keep working.
  PERFORM _as(U_SCORER);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-059-a') c;
  PERFORM _assert(v_ok AND v_epoch = 2, 'the arming device could not take its own handover back');
  SELECT state::text INTO v_state FROM scoring_session WHERE match_id = M_HANDOVER;
  PERFORM _assert(v_state = 'active', 'cancelling a handover left the session ' || coalesce(v_state, 'unreadable'));

  -- Verifying: refused as verifying — the claimant, the outgoing device, lease or no lease.
  SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-059-a', 0, false) a;
  PERFORM _as(U_SARAH);
  SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-059-b', v_code) h;
  PERFORM _assert(v_ok, 'Sarah could not claim the handover with its code');
  SELECT c.ok, c.reason, c.epoch INTO v_ok, v_reason, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-059-b') c;
  PERFORM _assert(NOT v_ok AND v_reason = 'verifying' AND v_epoch = 2,
    format('the claimant skipped its own verification with a plain claim (ok=%s reason=%s)', v_ok, v_reason));
  PERFORM _as(U_SCORER);
  SELECT c.reason INTO v_reason FROM scoring_claim(M_HANDOVER, 'verify-059-a') c;
  PERFORM _assert(v_reason IS NOT DISTINCT FROM 'verifying',
    'the outgoing device claimed back past a verification in progress');
  PERFORM _lapse_scoring_lease(M_HANDOVER);
  SELECT c.reason INTO v_reason FROM scoring_claim(M_HANDOVER, 'verify-059-a') c;
  PERFORM _assert(v_reason IS NOT DISTINCT FROM 'verifying',
    'a verification in progress was claimable once the lease lapsed');
  SELECT count(*) INTO n FROM scoring_session
   WHERE match_id = M_HANDOVER AND state = 'verifying' AND epoch = 2 AND claimant_device = 'verify-059-b';
  PERFORM _assert(n = 1, 'a refused claim still disturbed the verification');

  -- Recovery is unchanged: force-release once the lease has lapsed, then claim.
  PERFORM _as(U_SARAH);
  SELECT f.ok INTO v_ok FROM scoring_force_release(M_HANDOVER) f;
  PERFORM _assert(v_ok, 'a stalled verification could not be force-released');
  PERFORM _as(U_SCORER);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-059-a') c;
  PERFORM _assert(v_ok AND v_epoch = 4, 'the released match could not be claimed fresh');
  -- And the live-lease refusal is exactly what it was.
  PERFORM _as(U_SARAH);
  SELECT c.ok, c.reason INTO v_ok, v_reason FROM scoring_claim(M_HANDOVER, 'verify-059-b') c;
  PERFORM _assert(NOT v_ok AND v_reason = 'lease_active', 'a live lease is no longer refused as lease_active');

  -- ── 15. A duty's lifecycle, and completion ends scoring (SCRBRD-034) ─
  -- db/30's duty_status() derives each state from a fact already on record;
  -- db/33 makes a complete match unscorable for everyone. One fixture walked
  -- through its life: the scorer appointment seeded above (A Wessels, who
  -- holds an account) and an umpire already stood down. Sarah reads.
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SARAH);
  PERFORM _assert(duty_status(O_SCORER) = 'pending',
    'a scheduled fixture''s scorer is not pending: ' || coalesce(duty_status(O_SCORER), 'NULL'));
  PERFORM _assert(duty_status(O_STOOD) = 'revoked', 'a withdrawn appointment is not revoked');
  -- Only to a reader who may see the appointment: Westville's office may not.
  PERFORM _as(U_WES_ADM);
  PERFORM _assert(duty_status(O_SCORER) IS NULL, 'duty_status answered a reader who cannot see the fixture');
  PERFORM _as(U_SARAH);

  PERFORM _set_match_status(M_HANDOVER, 'live');
  PERFORM _assert(duty_status(O_SCORER) = 'active', 'a live fixture''s scorer is not active');
  PERFORM _assert(duty_status(O_STOOD) = 'revoked', 'a stood-down umpire came back to life when play began');

  -- The scorer hands the pen to Sarah: delegated, while she holds it.
  PERFORM _as(U_SCORER);
  SELECT c.ok INTO v_ok FROM scoring_claim(M_HANDOVER, 'verify-034-a') c;
  PERFORM _assert(v_ok, 'the scorer could not claim a live fixture');
  PERFORM _assert(duty_status(O_SCORER) = 'active', 'the scorer holding the pen is not active');
  SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-034-a', 0, false) a;
  PERFORM _as(U_SARAH);
  SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-034-b', v_code) h;
  PERFORM _assert(v_ok, 'Sarah could not claim the scorer''s handover');
  -- A wrong reading answers with the server's own count; the right one follows.
  SELECT v.exp_runs, v.exp_wkts, v.exp_balls INTO v_runs, v_wkts, v_balls
    FROM scoring_verify_takeover(M_HANDOVER, 'verify-034-b', -1, -1, -1) v;
  SELECT v.ok INTO v_ok FROM scoring_verify_takeover(M_HANDOVER, 'verify-034-b', v_runs, v_wkts, v_balls) v;
  PERFORM _assert(v_ok, 'Sarah could not complete the takeover');
  PERFORM _assert(duty_status(O_SCORER) = 'delegated',
    'the scorer who handed the pen over is not delegated: ' || coalesce(duty_status(O_SCORER), 'NULL'));
  -- The scorer reads the fixture and not scoring_audit (audit.read is the
  -- office's) — and is told the same thing about his own duty.
  PERFORM _as(U_SCORER);
  SELECT count(*) INTO n FROM scoring_audit WHERE match_id = M_HANDOVER;
  PERFORM _assert(n = 0, 'the scorer reads scoring_audit — the next assertion would prove nothing');
  PERFORM _assert(duty_status(O_SCORER) IS NOT DISTINCT FROM 'delegated',
    'a reader without audit.read is told something different about the same duty: ' || coalesce(duty_status(O_SCORER), 'NULL'));
  -- He takes it back once her lease lapses: holding it again is active.
  -- Another device held it, so since db/126 that is a confirmed take-over,
  -- over the generation he was shown (a plain claim is held_elsewhere, §103).
  PERFORM _lapse_scoring_lease(M_HANDOVER);
  PERFORM _as(U_SCORER);
  SELECT c.ok INTO v_ok FROM scoring_takeover(M_HANDOVER, 'verify-034-a',
    (SELECT ss.epoch FROM scoring_session ss WHERE ss.match_id = M_HANDOVER)) c;
  PERFORM _assert(v_ok, 'the scorer could not take a lapsed token back');
  PERFORM _assert(duty_status(O_SCORER) = 'active', 'a scorer holding the pen again is still delegated');

  -- ── Completion ends scoring (db/33) ──
  -- Arm a handover and put another one mid-verification first, so both of
  -- the handover functions meet a complete match with work in flight.
  SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-034-a', 0, false) a;
  PERFORM _assert(v_code IS NOT NULL, 'the scorer could not arm a handover on a live fixture');
  PERFORM _set_match_status(M_HANDOVER, 'complete');
  PERFORM _as(U_SARAH);
  SELECT h.ok, h.reason INTO v_ok, v_reason FROM scoring_claim_handover(M_HANDOVER, 'verify-034-b', v_code) h;
  PERFORM _assert(NOT v_ok AND v_reason = 'match_complete',
    format('a handover was claimed on a complete match (ok=%s reason=%s)', v_ok, v_reason));
  PERFORM _set_match_status(M_HANDOVER, 'live');
  SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-034-b', v_code) h;
  PERFORM _assert(v_ok, 'the handover could not be claimed once the fixture was live again');
  PERFORM _set_match_status(M_HANDOVER, 'complete');
  SELECT v.ok, v.reason INTO v_ok, v_reason
    FROM scoring_verify_takeover(M_HANDOVER, 'verify-034-b', v_runs, v_wkts, v_balls) v;
  PERFORM _assert(NOT v_ok AND v_reason = 'match_complete',
    format('a takeover was verified on a complete match (ok=%s reason=%s)', v_ok, v_reason));
  SELECT count(*) INTO n FROM scoring_session
   WHERE match_id = M_HANDOVER AND state = 'verifying' AND claimant_device = 'verify-034-b';
  PERFORM _assert(n = 1, 'a refused takeover still moved the session');

  -- The plain claim: refused for everyone, the supervisor included, once
  -- the session is idle and nothing else would stand in the way.
  PERFORM _lapse_scoring_lease(M_HANDOVER);
  SELECT f.ok INTO v_ok FROM scoring_force_release(M_HANDOVER) f;
  PERFORM _assert(v_ok, 'a session on a complete match could not be force-released — that is how one is tidied');
  SELECT c.ok, c.reason INTO v_ok, v_reason FROM scoring_claim(M_HANDOVER, 'verify-034-b') c;
  PERFORM _assert(NOT v_ok AND v_reason = 'match_complete',
    format('the director of sport claimed a complete match (ok=%s reason=%s)', v_ok, v_reason));
  PERFORM _as(U_SCORER);
  SELECT c.ok, c.reason INTO v_ok, v_reason FROM scoring_claim(M_HANDOVER, 'verify-034-a') c;
  PERFORM _assert(NOT v_ok AND v_reason = 'match_complete',
    format('the appointed scorer claimed a complete match (ok=%s reason=%s)', v_ok, v_reason));
  SELECT count(*) INTO n FROM scoring_session WHERE match_id = M_HANDOVER AND state = 'idle';
  PERFORM _assert(n = 1, 'a refused claim on a complete match still took the token');

  -- The lease: a token held when the result is declared is not extended.
  -- Live again, the scorer claims; complete, the very next check refuses —
  -- while the lease is still running, which is the case that matters.
  PERFORM _set_match_status(M_HANDOVER, 'live');
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-034-a') c;
  PERFORM _assert(v_ok, 'the scorer could not claim the fixture back while live');
  SELECT l.holds INTO v_ok FROM scoring_lease_check(M_HANDOVER, 'verify-034-a', v_epoch) l;
  PERFORM _assert(v_ok, 'the token holder''s lease check fails on a live fixture');
  PERFORM _set_match_status(M_HANDOVER, 'complete');
  v_until := _lease_until(M_HANDOVER);
  SELECT l.holds, l.state INTO v_ok, v_state FROM scoring_lease_check(M_HANDOVER, 'verify-034-a', v_epoch) l;
  PERFORM _assert(NOT v_ok AND v_state = 'match_complete',
    format('a lease was honoured on a complete match (holds=%s state=%s)', v_ok, v_state));
  PERFORM _assert(_lease_until(M_HANDOVER) = v_until, 'a lease was extended on a complete match');
  PERFORM _assert(duty_status(O_SCORER) = 'completed', 'a finished fixture''s scorer is not completed');

  -- Corrections are the amendment path, and completion leaves it open.
  INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
  VALUES (M_HANDOVER, HIL, 'verify-034-key', 'Filed after the result was declared.', U_SCORER);
  SELECT count(*) INTO n FROM scoring_amendment WHERE target_key = 'verify-034-key' AND match_id = M_HANDOVER;
  PERFORM _assert(n = 1, 'completion shut the amendment request as well');

  PERFORM _set_match_status(M_HANDOVER, 'abandoned');
  PERFORM _assert(duty_status(O_SCORER) = 'expired', 'an abandoned fixture''s scorer is not expired');
  PERFORM _assert(duty_status(O_STOOD) = 'revoked', 'withdrawn does not outrank the fixture''s end');

  -- ── Rulebook clauses: anyone signed in reads, nobody writes (SCRBRD-041, db/32)
  -- Reference material under the directive's own predicate. The spectator is
  -- the narrowest signed-in principal there is; if he reads the clause, so
  -- does everyone who can read the limit it explains.
  PERFORM set_config('app.user_id', '', true);
  SELECT count(*) INTO n FROM rulebook_clause;
  PERFORM _assert(n = 0, 'an unidentified session can read rulebook clauses');
  SELECT count(*) INTO n FROM rulebook_clause_age;
  PERFORM _assert(n = 0, 'an unidentified session can read the ages a clause applies to');

  PERFORM _as(U_WATCHER);
  SELECT count(*) INTO n FROM rulebook_clause;
  PERFORM _assert(n >= 7, format('a spectator reads %s rulebook clauses, not the seven db/32 seeds', n));
  -- Every limit he can read cites a clause he can read, for its own band.
  SELECT count(*) INTO n FROM bowling_directive d
    JOIN rulebook_clause_age a ON a.clause_code = d.clause_code AND a.age_band = d.age_band
    JOIN rulebook_clause c ON c.code = d.clause_code;
  PERFORM _assert(n = (SELECT count(*) FROM bowling_directive) AND n = 6,
    format('only %s of the directive''s limits cite a readable clause for their band', n));
  SELECT count(*) INTO n FROM bowling_directive WHERE age_band = 'U13' AND clause_code = 'PACE-U13';
  PERFORM _assert(n = 1, 'the U13 limit does not cite PACE-U13');

  -- Not even the owner's key writes the rulebook through the application: the
  -- privilege is revoked AND there is no write policy, so the refusal is the
  -- same whichever layer a later file loosens first.
  PERFORM _as(U_OWNER);
  BEGIN
    INSERT INTO rulebook_clause (code, title, category, severity, source, body)
    VALUES ('VERIFY-X', 'Written through the application', 'Conduct', 'Guideline', 'db/99 assertion',
            'A clause the application role must never be able to write, whoever it is acting for.');
    PERFORM _assert(false, 'the application role inserted a rulebook clause');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE rulebook_clause SET severity = 'Guideline' WHERE code = 'PACE-U13';
    PERFORM _assert(false, 'the application role downgraded a mandatory clause');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    INSERT INTO rulebook_clause_age (clause_code, age_band) VALUES ('PACE-OPEN', 'U13');
    PERFORM _assert(false, 'the application role widened a clause to another age band');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM _assert(
    NOT EXISTS (SELECT 1 FROM pg_policy
                 WHERE polrelid IN ('rulebook_clause'::regclass, 'rulebook_clause_age'::regclass)
                   AND polcmd <> 'r'),
    'a rulebook table has a write policy');

  -- ── 16. A duty, the authority it rests on, and the pause (SCRBRD-034) ─
  -- db/34 links a match duty to a fixture-scoped assignment the office makes;
  -- db/35 teaches the decision functions to read a suspension. The claims:
  -- only the office links, suspends and lifts; a reason is required each way;
  -- a suspended assignment grants NOTHING, read or write, through every
  -- decision function; lifting restores it without reactivating anything;
  -- withdrawing the duty revokes it.
  --
  -- The appointment alone grants nothing — that was the gap.
  PERFORM _as(U_DUTY);
  SELECT count(*) INTO n FROM match WHERE id = M_DUTY;
  PERFORM _assert(n = 0, 'an appointment with no linked assignment let its scorer read the fixture');

  -- Only the school office links. A coach, another school's office, the duty's
  -- own scorer, and a principal — who holds user.role.assign but may not
  -- appoint a scorer (GRANTABLE_ROLES) — are all refused.
  FOREACH v_code IN ARRAY ARRAY[U_COACH2::text, U_WES_ADM::text, U_DUTY::text, U_HEAD_M::text] LOOP
    PERFORM _as(v_code::uuid);
    SELECT l.ok, l.reason INTO v_ok, v_reason FROM duty_link(D_DUTY) l;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('%s linked a duty to an assignment (ok=%s reason=%s)', v_code, v_ok, v_reason));
  END LOOP;
  PERFORM _as(U_REGISTRAR);
  SELECT l.ok, l.assignment_id INTO v_ok, A_DUTY FROM duty_link(D_DUTY) l;
  PERFORM _assert(v_ok AND A_DUTY IS NOT NULL, 'the school office could not link a duty');
  SELECT count(*) INTO n FROM role_assignment
   WHERE id = A_DUTY AND person_id = U_DUTY AND role = 'scorer' AND school_id = HIL
     AND fixture_id = M_DUTY AND team_code IS NULL AND active AND created_by = U_REGISTRAR;
  PERFORM _assert(n = 1, 'the linked assignment is not exactly the duty''s shape, granted by the office');
  SELECT l.reason INTO v_reason FROM duty_link(D_DUTY) l;
  PERFORM _assert(v_reason = 'already_linked', 'a live link was replaced by a second one');

  -- The link now grants the duty's authority, at that fixture and no other.
  PERFORM _as(U_DUTY);
  SELECT count(*) INTO n FROM match WHERE id = M_DUTY;
  PERFORM _assert(n = 1, 'a linked scorer cannot read their own fixture');
  PERFORM _assert(app_can('scoring.edit', HIL, '1XI', NULL, M_DUTY), 'a linked scorer cannot score their fixture');
  PERFORM _assert(NOT app_can('scoring.edit', HIL, '1XI', NULL, M_OTHER), 'a linked scorer can score a fixture they were not appointed to');

  -- Nobody writes the link around duty_link(). The director of sport holds
  -- officiating.assign AND user.role.assign and may update the appointment;
  -- the league holds officiating.assign everywhere. Neither can touch the
  -- column: the application role has no privilege on it.
  FOREACH v_code IN ARRAY ARRAY[U_SARAH::text, U_LEAGUE::text] LOOP
    PERFORM _as(v_code::uuid);
    BEGIN
      UPDATE match_official SET assignment_id = NULL WHERE id = D_DUTY;
      PERFORM _assert(false, format('%s unlinked a duty directly', v_code));
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      UPDATE match_official SET assignment_id = 'a5510000-0000-0000-0000-000000000023' WHERE id = D_DUTY2;
      PERFORM _assert(false, format('%s linked a duty directly, around duty_link()', v_code));
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;
  -- A linked appointment keeps what it is about, for anyone who may edit it.
  PERFORM _as(U_SARAH);
  BEGIN
    UPDATE match_official SET person_id = U_SCORER WHERE id = D_DUTY;
    PERFORM _assert(false, 'a linked appointment was re-pointed at somebody else');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  -- And the SHAPE holds however the column is written — even as the owner.
  -- E Ndlovu's official assignment is the right role for an umpire and the
  -- wrong person at the wrong fixture; a live link is not dropped.
  BEGIN
    PERFORM _link_raw(D_DUTY2, 'a5510000-0000-0000-0000-000000000023');
    PERFORM _assert(false, 'a duty was linked to another person''s assignment at another fixture');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  BEGIN
    PERFORM _link_raw(D_DUTY, NULL);
    PERFORM _assert(false, 'a duty was unlinked from a live assignment');
  EXCEPTION WHEN check_violation THEN NULL;
  END;

  -- Suspending: the office only, and never without a reason.
  PERFORM _as(U_COACH2);
  SELECT s.ok, s.reason INTO v_ok, v_reason FROM duty_suspend(D_DUTY, 'Not the coach''s call') s;
  PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', 'a coach suspended a duty');
  PERFORM _as(U_DUTY);
  SELECT s.ok, s.reason INTO v_ok, v_reason FROM duty_suspend(D_DUTY, 'Standing myself down') s;
  PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', 'a scorer suspended their own duty');
  PERFORM _as(U_REGISTRAR);
  SELECT s.ok, s.reason INTO v_ok, v_reason FROM duty_suspend(D_DUTY, '   ') s;
  PERFORM _assert(NOT v_ok AND v_reason = 'reason_required', 'a duty was suspended with a blank reason');
  SELECT s.ok, s.reason INTO v_ok, v_reason FROM duty_suspend(D_DUTY, NULL) s;
  PERFORM _assert(NOT v_ok AND v_reason = 'reason_required', 'a duty was suspended with no reason');
  -- Nobody writes the record around the function.
  BEGIN
    INSERT INTO duty_suspension (duty_id, assignment_id, school_id, suspended_by, reason)
    VALUES (D_DUTY, A_DUTY, HIL, U_REGISTRAR, 'Written round the function');
    PERFORM _assert(false, 'the application role wrote a suspension directly');
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  SELECT s.ok INTO v_ok FROM duty_suspend(D_DUTY, 'Complaint about the scorebook under review') s;
  PERFORM _assert(v_ok, 'the school office could not suspend a linked duty');
  PERFORM _assert(duty_status(D_DUTY) = 'suspended', 'a suspended duty does not read as suspended: ' || coalesce(duty_status(D_DUTY), 'NULL'));
  SELECT count(*) INTO n FROM duty_suspension
   WHERE duty_id = D_DUTY AND assignment_id = A_DUTY AND suspended_by = U_REGISTRAR
     AND reason = 'Complaint about the scorebook under review' AND lifted_at IS NULL;
  PERFORM _assert(n = 1, 'the suspension did not record who, when and why');
  -- A principal holds user.role.assign, so may pause a duty (answered as
  -- already suspended, not as not permitted)…
  PERFORM _as(U_HEAD_M);
  SELECT s.reason INTO v_reason FROM duty_suspend(D_DUTY, 'Also pausing it') s;
  PERFORM _assert(v_reason = 'already_suspended',
    format('a principal was refused a suspension for the wrong reason (%s)', v_reason));

  -- WHILE SUSPENDED, THE ASSIGNMENT GRANTS NOTHING. A real read under
  -- fixture.read, a real write decision, and all three decision functions.
  PERFORM _as(U_DUTY);
  SELECT count(*) INTO n FROM match WHERE id = M_DUTY;
  PERFORM _assert(n = 0, 'a suspended scorer still reads the fixture');
  SELECT count(*) INTO n FROM match_official WHERE match_id = M_DUTY;
  PERFORM _assert(n = 0, 'a suspended scorer still reads the fixture''s appointments');
  PERFORM _assert(NOT app_can('scoring.edit', HIL, '1XI', NULL, M_DUTY), 'a suspended scorer may still score');
  PERFORM _assert(NOT app_holds('scoring.edit'), 'app_holds() still counts a suspended assignment');
  -- app_may_grant() carries the same line (db/35's own check asserts it), but
  -- no role a duty can rest on grants anything, so there is no live claim to
  -- make about it here that would not pass for the wrong reason.
  -- The scorer is told they are suspended, and not why.
  PERFORM _assert(assignment_suspended(A_DUTY), 'a suspended scorer cannot see that they are suspended');
  SELECT count(*) INTO n FROM duty_suspension;
  PERFORM _assert(n = 0, 'a suspended scorer reads the office''s reason');
  -- …and nobody but the office can lift it.
  SELECT l.ok, l.reason INTO v_ok, v_reason FROM duty_lift(D_DUTY, 'I am fine now') l;
  PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', 'a scorer lifted their own suspension');
  -- …and a principal, who could pause it, cannot restore a role they may not appoint.
  PERFORM _as(U_HEAD_M);
  SELECT l.ok, l.reason INTO v_ok, v_reason FROM duty_lift(D_DUTY, 'Restoring') l;
  PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', 'a principal lifted a scorer''s suspension');
  PERFORM _as(U_REGISTRAR);
  PERFORM _assert(duty_suspended(D_DUTY), 'duty_suspended() does not report the open suspension');
  SELECT l.ok, l.reason INTO v_ok, v_reason FROM duty_lift(D_DUTY, '') l;
  PERFORM _assert(NOT v_ok AND v_reason = 'reason_required', 'a suspension was lifted without a reason');

  -- LIFTING RESTORES IT, and restores it by closing the record, not by
  -- touching the assignment: same row, never deactivated, nothing reactivated.
  SELECT l.ok INTO v_ok FROM duty_lift(D_DUTY, 'Scorebook checked; no fault found') l;
  PERFORM _assert(v_ok, 'the school office could not lift a suspension');
  PERFORM _assert(duty_status(D_DUTY) <> 'suspended', 'a lifted duty still reads as suspended');
  SELECT count(*) INTO n FROM duty_suspension
   WHERE duty_id = D_DUTY AND lifted_by = U_REGISTRAR AND lifted_at IS NOT NULL
     AND lift_reason = 'Scorebook checked; no fault found'
     AND reason = 'Complaint about the scorebook under review';
  PERFORM _assert(n = 1, 'the lift did not record who, when and why beside the suspension');
  SELECT count(*) INTO n FROM role_assignment WHERE id = A_DUTY AND active AND revoked_at IS NULL;
  PERFORM _assert(n = 1, 'suspending or lifting touched the assignment''s active flag');
  PERFORM _as(U_DUTY);
  SELECT count(*) INTO n FROM match WHERE id = M_DUTY;
  PERFORM _assert(n = 1, 'lifting a suspension did not restore the scorer''s read');
  PERFORM _assert(app_can('scoring.edit', HIL, '1XI', NULL, M_DUTY), 'lifting a suspension did not restore scoring');
  PERFORM _assert(NOT assignment_suspended(A_DUTY), 'a lifted suspension still reads as suspended');

  -- WITHDRAWING THE DUTY REVOKES THE AUTHORITY, in the same statement, by
  -- whoever withdraws it — the director of sport through officiating.assign.
  PERFORM _as(U_SARAH);
  UPDATE match_official SET withdrawn = true WHERE id = D_DUTY;
  SELECT count(*) INTO n FROM role_assignment
   WHERE id = A_DUTY AND NOT active AND revoked_by = U_SARAH AND revoked_at IS NOT NULL;
  PERFORM _assert(n = 1, 'withdrawing a linked duty did not revoke its assignment');
  PERFORM _as(U_DUTY);
  SELECT count(*) INTO n FROM match WHERE id = M_DUTY;
  PERFORM _assert(n = 0, 'a withdrawn scorer still reads the fixture');
  PERFORM _as(U_SARAH);
  BEGIN
    UPDATE match_official SET withdrawn = false WHERE id = D_DUTY;
    PERFORM _assert(false, 'a withdrawn linked appointment was reinstated over a revoked assignment');
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  PERFORM _as(U_REGISTRAR);
  SELECT s.reason INTO v_reason FROM duty_suspend(D_DUTY, 'Too late') s;
  PERFORM _assert(v_reason = 'duty_withdrawn', 'a withdrawn duty could be suspended');
  SELECT l.reason INTO v_reason FROM duty_link(D_DUTY) l;
  PERFORM _assert(v_reason = 'duty_withdrawn', 'a withdrawn duty could be linked again');

  -- ── 17. Quarantine's loose ends (SCRBRD-071, db/37) ────────────
  -- Three guarantees the database holds; the fourth — that a released ball
  -- meets the Laws — is the API's (lawsRefusal() cannot run in SQL), and
  -- tools/smoke-quarantine.mjs drives it end to end.
  --
  -- (a) A released ball keeps contact and trajectory, and (b) takes the live
  --     path's per-match lock before it reads max(seq), so a live batch can
  --     neither race it for a seq nor append after it unjudged. Behaviour is
  --     proved in the walk; here, that the function in the database is the
  --     one db/37 wrote.
  PERFORM _assert(pg_get_functiondef('quarantine_resolve(bigint,boolean,jsonb,text)'::regprocedure)
                    ~ 'p_row->>''contact''.*p_row->>''trajectory''',
    'quarantine_resolve() drops contact and trajectory from a released ball');
  PERFORM _assert(pg_get_functiondef('quarantine_resolve(bigint,boolean,jsonb,text)'::regprocedure)
                    ~ 'FROM scoring_session s WHERE s.match_id = q.match_id FOR UPDATE',
    'quarantine_resolve() no longer takes the per-match lock the live write path takes');
  PERFORM _assert(EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ball_event_quarantine_resolution_check'
                            AND pg_get_constraintdef(oid) LIKE '%superseded%'),
    'a held row cannot be closed as superseded');

  -- (c) A key written live closes its held copy, in the same statement, for
  --     every writer: a ball held under a stale token and re-sent by the
  --     device that now holds the token is not left for a person to
  --     "release" into a log that already has it.
  PERFORM _assert(EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'ball_event'::regclass
                            AND tgname = 'ball_event_supersedes_held' AND tgenabled = 'O'),
    'the trigger that closes a held copy of a key written live is missing or disabled');
  PERFORM _assert(_count_open_held_copies() = 0,
    'a held ball is still waiting for a person although the same event is already in the log');
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SCORER);
  PERFORM set_config('app.device_id', 'verify-037', true);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-037') c;
  PERFORM _assert(v_ok, 'the scorer could not claim the match the db/37 section scores');
  DECLARE
    v_ball jsonb := jsonb_build_object('match_id', M_HANDOVER, 'innings', 0, 'kind', 'ball',
                                       'ball_type', 'run', 'value', 2, 'payload', '{}'::jsonb);
    v_res  text;
    v_by   uuid;
  BEGIN
    -- Held under a stale epoch with the fingerprint the write path computes;
    -- a second key held saying something else.
    INSERT INTO ball_event_quarantine (match_id, school_id, submitted_epoch, current_epoch, scorer_user_id,
                                       device_id, idempotency_key, body, fingerprint)
    VALUES (M_HANDOVER, match_school(M_HANDOVER), v_epoch + 5, v_epoch, U_SCORER, 'verify-037',
            'verify:037:same', '{}'::jsonb,
            ball_event_fingerprint(jsonb_populate_record(null::ball_event, v_ball))),
           (M_HANDOVER, match_school(M_HANDOVER), v_epoch + 5, v_epoch, U_SCORER, 'verify-037',
            'verify:037:other', '{}'::jsonb, 'verify-037-a-different-event');
    -- ...then both keys written live, the way appendEvents writes a row.
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, ball_type, value, payload)
    SELECT M_HANDOVER, match_school(M_HANDOVER), 9000 + k, v_epoch, r.innings, U_SCORER, 'verify-037',
           key, k, now(), r.kind, r.ball_type, r.value, r.payload
      FROM jsonb_populate_record(null::ball_event, v_ball) r,
           (VALUES (1, 'verify:037:same'), (2, 'verify:037:other')) AS x(k, key);
    -- IS NOT DISTINCT FROM, and counts: _assert() passes a NULL condition,
    -- so a comparison with a row that is not there would pass vacuously.
    SELECT resolution, resolved_by INTO v_res, v_by FROM ball_event_quarantine WHERE idempotency_key = 'verify:037:same';
    PERFORM _assert(v_res IS NOT DISTINCT FROM 'superseded' AND v_by IS NOT DISTINCT FROM U_SCORER,
      format('writing a held key live left its held copy %s (by %s), not superseded', coalesce(v_res, 'open'), v_by));
    -- A different event under the key is a conflict — the write path refuses
    -- it before it gets here — and if one is ever written, it stays held for a
    -- person rather than being closed as if it were the same ball.
    SELECT count(*) INTO n FROM ball_event_quarantine
     WHERE idempotency_key = 'verify:037:other' AND resolved_at IS NULL AND resolution IS NULL;
    PERFORM _assert(n = 1, 'a held event was closed by a DIFFERENT event written under its key');
  END;
  PERFORM set_config('app.device_id', '', true);

  -- ── 18. An approved amendment takes the per-match lock (SCRBRD-076, db/38) ──
  -- scoring_amendment_decide() appended its void without the lock the live
  -- path and a release take, so a live batch that had folded the log could
  -- append after the void unjudged. That the void meets the Laws is the API's
  -- (lawsRefusal() cannot run in SQL); tools/smoke-amend.mjs walks it. Here:
  -- the function in the database is db/38's, it locks, and it still answers
  -- every reason db/02 gave, in db/02's order.
  PERFORM _assert(pg_get_functiondef('scoring_amendment_decide(uuid,boolean,text)'::regprocedure)
                    ~ 'FROM scoring_session s WHERE s.match_id = a.match_id FOR UPDATE.*INSERT INTO ball_event',
    'scoring_amendment_decide() does not take the per-match lock before it appends its void');
  PERFORM _assert(EXISTS (SELECT 1 FROM pg_proc
                           WHERE oid = 'scoring_amendment_decide(uuid,boolean,text)'::regprocedure
                             AND prosecdef
                             AND 'search_path=pg_catalog, public, pg_temp' = ANY (proconfig)),
    'scoring_amendment_decide() lost its pinned search_path (db/16) when db/38 replaced it');
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SCORER);
  SELECT c.ok INTO v_ok FROM scoring_claim(M_HANDOVER, 'verify-038') c;
  PERFORM _assert(v_ok, 'the scorer could not claim the match the db/38 section amends');
  PERFORM _assert(_session_xmax(M_HANDOVER) = '0',
    format('the db/38 section''s session row is locked before anything amends it (xmax %s)', _session_xmax(M_HANDOVER)));
  DECLARE
    A_LIVE  uuid;   -- the scorer's request, approved by somebody else
    A_OWN   uuid;   -- the owner's, decided by the owner
    A_GONE  uuid;   -- a second request on a delivery already voided
    v_void  text;
  BEGIN
    -- The ball section 17 wrote live, and one after it: the amendment voids
    -- the OLDER one, which is what an amendment is for.
    INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
    VALUES (M_HANDOVER, match_school(M_HANDOVER), 'verify:037:same', 'db/38: the lock', U_SCORER)
    RETURNING id INTO A_LIVE;

    -- (1) before (2): the scorer holds no approval at all, so deciding his
    --     own request is not_permitted — not the self-approval guard.
    SELECT d.reason INTO v_reason FROM scoring_amendment_decide(A_LIVE, true) d;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'not_permitted',
      format('the scorer deciding his own request was answered %s, not not_permitted', coalesce(v_reason, 'NULL')));
    PERFORM _assert(_session_xmax(M_HANDOVER) = '0',
      'a caller with no standing over the match took its per-match lock');

    PERFORM _as(U_SARAH);
    SELECT d.reason INTO v_reason FROM scoring_amendment_decide(gen_random_uuid(), true) d;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'no_such_amendment',
      format('an amendment that does not exist was answered %s', coalesce(v_reason, 'NULL')));

    SELECT d.ok, d.reason, d.void_key INTO v_ok, v_reason, v_void
      FROM scoring_amendment_decide(A_LIVE, true, 'db/38') d;
    PERFORM _assert(v_ok AND v_void IS NOT DISTINCT FROM 'amendment:' || A_LIVE::text,
      format('the director of sport could not approve the scorer''s amendment (%s)', coalesce(v_reason, 'NULL')));
    -- THE LOCK. Taken by the approval, held to this transaction's end.
    PERFORM _assert(_session_xmax(M_HANDOVER) <> '0',
      'approving an amendment appended to the log without the per-match lock the live path takes');
    SELECT count(*) INTO n FROM ball_event
     WHERE idempotency_key = v_void AND kind = 'void' AND device_id = 'amendment'
       AND scorer_user_id = U_SCORER AND payload->>'approved_by' = U_SARAH::text
       AND payload->>'target' = 'verify:037:same'
       AND seq = (SELECT max(seq) FROM ball_event WHERE match_id = M_HANDOVER);
    PERFORM _assert(n = 1, 'the void is not the requester''s, approved by the approver, at the end of the log');

    SELECT d.reason INTO v_reason FROM scoring_amendment_decide(A_LIVE, true) d;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'already_approved',
      format('an approved amendment decided again was answered %s', coalesce(v_reason, 'NULL')));

    -- (3) a delivery already voided is not live.
    PERFORM _as(U_SCORER);
    INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
    VALUES (M_HANDOVER, match_school(M_HANDOVER), 'verify:037:same', 'db/38: again', U_SCORER)
    RETURNING id INTO A_GONE;
    PERFORM _as(U_SARAH);
    SELECT d.reason INTO v_reason FROM scoring_amendment_decide(A_GONE, true) d;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'no_such_live_delivery',
      format('voiding a delivery already voided was answered %s', coalesce(v_reason, 'NULL')));
    SELECT d.ok INTO v_ok FROM scoring_amendment_decide(A_GONE, false, 'db/38: nothing to void') d;
    SELECT count(*) INTO n FROM scoring_amendment WHERE id = A_GONE AND state = 'declined' AND decided_by = U_SARAH;
    PERFORM _assert(v_ok AND n = 1, 'the director of sport could not decline an amendment');

    -- (2) nobody approves their own, whatever they hold: the owner holds
    --     both halves.
    PERFORM _as(U_OWNER);
    INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
    VALUES (M_HANDOVER, match_school(M_HANDOVER), 'verify:037:other', 'db/38: my own', U_OWNER)
    RETURNING id INTO A_OWN;
    SELECT d.reason INTO v_reason FROM scoring_amendment_decide(A_OWN, true) d;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'cannot_approve_your_own',
      format('the owner deciding their own amendment was answered %s', coalesce(v_reason, 'NULL')));
  END;
  PERFORM set_config('app.device_id', '', true);

  -- ── db/39. Fixture anchors through match_school()/match_team() ──
  --
  -- Seven tables' anchors moved from a subquery on `match` under the caller's
  -- RLS to the SECURITY DEFINER helpers. docs/rls-anchor-audit.md is the
  -- audit: for six of them no role's access changes, and for
  -- match_availability exactly one thing does — a pupil's selfaccess
  -- assignment reaches his OWN declarations for fixtures his team assignment
  -- cannot see. Each claim below is that and nothing more.
  DECLARE
    M_U16B  uuid := '77777777-0000-0000-0000-000000000003';  -- U16B v Kearsney; R Pillay is 1XI
    M_39    uuid := '77777777-0000-0000-0000-000000000039';  -- U15A, nothing else here touches it
    U_DRIVE uuid := '88888888-0000-0000-0000-000000000017';  -- B Ngcobo: transport.read, no fixture.read
    t       text;
    who     uuid;
  BEGIN
    -- Every policy db/39 made still reads the helpers — a later file that put
    -- a subquery back would pass db/39's own check and fail here.
    SELECT count(*) INTO n FROM pg_policies
     WHERE schemaname = 'public'
       AND policyname IN ('match_toss_read', 'match_toss_insert', 'match_toss_update',
                          'match_broadcast_read', 'match_broadcast_insert', 'match_broadcast_update',
                          'drs_review_read', 'drs_review_insert', 'drs_review_update',
                          'match_official_read', 'match_official_insert', 'match_official_update',
                          'match_pitch_report_read', 'match_pitch_report_insert', 'match_pitch_report_update',
                          'match_weather_read', 'match_weather_insert', 'match_weather_update',
                          'match_availability_read', 'match_availability_insert', 'match_availability_update')
       AND coalesce(qual, '') || coalesce(with_check, '') LIKE '%match_school(%'
       AND coalesce(qual, '') || coalesce(with_check, '') NOT LIKE '%FROM match %';
    PERFORM _assert(n = 21, format('%s of db/39''s 21 policies anchor through match_school() — expected all of them', n));

    -- (1) THE BLIND CASE, NOW SEEING. R Pillay's team assignment is 1XI, so
    --     he cannot read the U16B fixture — and before db/39 that also hid his
    --     own availability for it, because the anchor came back NULL.
    PERFORM _as(U_SELF);
    SELECT count(*) INTO n FROM match WHERE id = M_U16B;
    PERFORM _assert(n = 0, 'the pupil reads the U16B fixture itself — the anchor must stay metadata, not a way to the match');
    SELECT count(*) INTO n FROM match_availability WHERE match_id = M_U16B AND player_id = P_INJURED;
    PERFORM _assert(n = 1, 'a pupil cannot read his own availability for a fixture his team assignment cannot see');
    -- Tried here, before the reads below, so it is this write's own policy
    -- that answers: an UPDATE also passes through the read policy, and a
    -- widened read would otherwise be caught first and this line never ran.
    UPDATE match_availability SET status = 'available' WHERE match_id = M_U16B AND player_id = P_U16B;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 0, 'a pupil changed another boy''s availability');
    -- (2) ...and nothing more: not the U16B boy's statement beside it, and in
    --     total exactly his own rows — every one of them, no one else's.
    SELECT count(*) INTO n FROM match_availability WHERE match_id = M_U16B AND player_id <> P_INJURED;
    PERFORM _assert(n = 0, 'a pupil reads another boy''s availability ("unavailable, family") through the resolved anchor');
    SELECT count(*) INTO n FROM match_availability;
    PERFORM _assert(n = _count_availability_of(P_INJURED),
      format('a pupil reads %s availability rows; his own number %s', n, _count_availability_of(P_INJURED)));

    -- (3) THE WRITE. He may make his own statement about that Saturday...
    BEGIN
      INSERT INTO match_availability (match_id, player_id, school_id, status, declared_by)
      VALUES (M_39, P_INJURED, HIL, 'available', U_SELF);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(v_ok, 'a pupil cannot declare his own availability for a fixture his team assignment cannot see');
    -- (4) ...and not anybody else's, however the anchor resolves.
    BEGIN
      INSERT INTO match_availability (match_id, player_id, school_id, status, declared_by)
      VALUES (M_39, P_U16B, HIL, 'unavailable', U_SELF);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'a pupil declared availability for another boy');

    -- (5) THE SIX WHOSE ACCESS DOES NOT CHANGE. Read under fixture.read, which
    --     is the match's own check, so a row is visible only where its fixture
    --     is — for every principal here, including the driver and the pupil
    --     who each hold something on a fixture-anchored table but not the
    --     fixture. If the resolved anchor ever became a way around the match,
    --     this is where it shows.
    PERFORM _assert(_count_rows('match_toss') > 0 AND _count_rows('match_weather') > 0
                    AND _count_rows('match_official') > 0 AND _count_rows('match_pitch_report') > 0,
      'db/39''s no-change claim has nothing to be tested against — a table is empty');
    FOREACH who IN ARRAY ARRAY[U_DRIVE, U_SELF, U_PUPIL, U_WATCHER, U_COACH2, U_SCORER,
                               U_UMPIRE, U_MEDIC, U_BURSAR, U_WES_ADM, U_HEAD_M]::uuid[] LOOP
      PERFORM _as(who);
      FOREACH t IN ARRAY ARRAY['match_toss', 'match_broadcast', 'drs_review', 'match_official',
                               'match_pitch_report', 'match_weather'] LOOP
        EXECUTE format('SELECT count(*) FROM %I x WHERE NOT EXISTS (SELECT 1 FROM match m WHERE m.id = x.match_id)', t)
          INTO n;
        PERFORM _assert(n = 0, format('%s reads %s %s row(s) for a fixture they cannot read', who, n, t));
      END LOOP;
    END LOOP;
    -- The driver in particular: he reads none of them at all.
    PERFORM _as(U_DRIVE);
    SELECT (SELECT count(*) FROM match_toss) + (SELECT count(*) FROM match_weather)
         + (SELECT count(*) FROM match_official) + (SELECT count(*) FROM match_pitch_report)
      INTO n;
    PERFORM _assert(n = 0, format('the driver reads %s fixture-condition row(s) with no fixture.read', n));

    -- (6) WITHHELD, ON PURPOSE. trip keeps its subquery: resolving it would
    --     show a school-wide driver every trip at the school, not his own
    --     (docs/rls-anchor-audit.md, "trip"). db/41 gave the named driver his
    --     own trips instead (its section below); the tripwire that stays here
    --     is that he reads none he is not driving.
    SELECT count(*) INTO n FROM trip WHERE driver_id IS DISTINCT FROM U_DRIVE;
    PERFORM _assert(n = 0, format('the driver reads %s trip(s) he is not driving: trip was withheld from db/39 — see docs/rls-anchor-audit.md', n));
  END;

  -- ── db/41. A driver reaches his own trips, and no other ──
  --
  -- trip_contacts() used to hand the manifest — every travelling child's
  -- parents' numbers — to anybody holding transport.drive at the school, for
  -- any trip there within a day; trip_mark() let them mark any trip there, and
  -- anybody at all mark a trip with no driver named. The read went the other
  -- way: a driver saw no trip, not even his own. Each claim is one half of
  -- that, and the last is that nobody else's view of trip or match moved.
  DECLARE
    U_DRIVE  uuid := '88888888-0000-0000-0000-000000000017';  -- driver A (the seed's)
    U_DRIVE2 uuid := '88888888-0000-0000-0000-00000000041b';  -- driver B, same school
    T_A      uuid := '41410000-0000-0000-0000-00000000000a';  -- A's bus, today
    T_A2     uuid := '41410000-0000-0000-0000-0000000000a2';  -- B's bus to A's fixture
    T_A3     uuid := '41410000-0000-0000-0000-0000000000a3';  -- the office's bus to A's fixture
    T_B      uuid := '41410000-0000-0000-0000-00000000000b';  -- B's bus, today
    T_N      uuid := '41410000-0000-0000-0000-00000000000c';  -- nobody named
    T_F      uuid := '41410000-0000-0000-0000-00000000000f';  -- A's bus, ten days off
    M_A      uuid := '77777777-0000-0000-0000-0000000041a0';
    M_B      uuid := '77777777-0000-0000-0000-0000000041b0';
    M_F      uuid := '77777777-0000-0000-0000-0000000041f0';
    who      uuid;
  BEGIN
    PERFORM _pick_41();
    PERFORM _assert(_manifest_size(T_A) > 0 AND _manifest_size(T_B) > 0 AND _manifest_size(T_F) > 0,
      'db/41''s manifests have nobody on them — the contact assertions below would pass vacuously');

    -- (1) THE READ. A reads his trips — all of them, and nobody else's: not
    --     B's bus at the same school, and not B's second bus to A's own
    --     fixture, which trip_read's anchor would resolve once A can read
    --     that fixture (trip_driver_own_only is what stops it).
    PERFORM _as(U_DRIVE);
    SELECT count(*) INTO n FROM trip WHERE id = T_A;
    PERFORM _assert(n = 1, 'the driver cannot read the trip he is driving');
    SELECT count(*) INTO n FROM trip WHERE id = T_B;
    PERFORM _assert(n = 0, 'the driver reads another driver''s trip at his school');
    SELECT count(*) INTO n FROM trip WHERE id IN (T_A2, T_A3);
    PERFORM _assert(n = 0, format('the driver reads %s other bus(es) to his own fixture', n));
    SELECT count(*) INTO n FROM trip;
    PERFORM _assert(n = _count_trips_driven_by(U_DRIVE),
      format('the driver reads %s trip(s); he is named on %s', n, _count_trips_driven_by(U_DRIVE)));

    -- (2) THE FIXTURE, for the day-of screen: his live trips' fixtures and no
    --     other — and the fixture only, not what hangs off it.
    SELECT count(*) INTO n FROM match WHERE id = M_A;
    PERFORM _assert(n = 1, 'the driver cannot read the fixture of the trip he is driving');
    SELECT count(*) INTO n FROM match WHERE id = M_B;
    PERFORM _assert(n = 0, 'the driver reads the fixture of another driver''s trip');
    SELECT count(*) INTO n FROM match;
    PERFORM _assert(n = _count_matches_driven_by(U_DRIVE),
      format('the driver reads %s fixture(s); he drives to %s', n, _count_matches_driven_by(U_DRIVE)));
    SELECT (SELECT count(*) FROM match_squad) + (SELECT count(*) FROM match_toss)
         + (SELECT count(*) FROM match_availability) + (SELECT count(*) FROM emergency_contact)
      INTO n;
    PERFORM _assert(n = 0, format('the driver reads %s squad/toss/availability/contact row(s) through a fixture he can now see', n));

    -- (3) THE MANIFEST. His own bus, inside the window; nothing for B's bus,
    --     nothing for the other bus to his own fixture, nothing ten days out.
    SELECT count(*) INTO n FROM trip_contacts(T_A);
    PERFORM _assert(n = _manifest_size(T_A),
      format('the driver reads %s of the %s contact rows on his own bus today', n, _manifest_size(T_A)));
    SELECT count(*) INTO n FROM trip_contacts(T_B);
    PERFORM _assert(n = 0, format('the driver reads %s emergency contact(s) off another driver''s bus', n));
    SELECT count(*) INTO n FROM trip_contacts(T_A2);
    PERFORM _assert(n = 0, format('the driver reads %s emergency contact(s) off the other bus to his fixture', n));
    SELECT count(*) INTO n FROM trip_contacts(T_N);
    PERFORM _assert(n = 0, format('the driver reads %s emergency contact(s) off a bus nobody is named on', n));
    SELECT count(*) INTO n FROM trip_contacts(T_F);
    PERFORM _assert(n = 0, format('the driver reads %s emergency contact(s) ten days before his trip', n));

    -- (4) THE MARKS. Not B's bus, not the other bus to his fixture, not a bus
    --     nobody is named on; his own, yes.
    SELECT m.reason INTO v_reason FROM trip_mark(T_B, 'departed') m;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'not_this_driver',
      format('the driver marking another driver''s trip was answered %s', coalesce(v_reason, 'ok')));
    SELECT m.reason INTO v_reason FROM trip_mark(T_A2, 'departed') m;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'not_this_driver',
      format('the driver marking the other bus to his fixture was answered %s', coalesce(v_reason, 'ok')));
    SELECT m.reason INTO v_reason FROM trip_mark(T_N, 'departed') m;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'not_this_driver',
      format('the driver marking a trip nobody is named on was answered %s', coalesce(v_reason, 'ok')));
    SELECT m.ok INTO v_ok FROM trip_mark(T_A, 'departed') m;
    PERFORM _assert(v_ok AND _trip_departed(T_A), 'the driver could not mark his own trip departed');
    -- A trip with no driver named was open to ANYBODY: db/08's gate came out
    -- NULL, and IF NOT NULL does not refuse.
    FOREACH who IN ARRAY ARRAY[U_PARENT, U_WATCHER, U_COACH2]::uuid[] LOOP
      PERFORM _as(who);
      SELECT m.reason INTO v_reason FROM trip_mark(T_N, 'departed') m;
      PERFORM _assert(v_reason IS NOT DISTINCT FROM 'not_this_driver',
        format('%s marking a trip nobody is named on was answered %s', who, coalesce(v_reason, 'ok')));
    END LOOP;
    PERFORM _assert(NOT _trip_departed(T_N), 'a trip nobody is named on was marked departed');
    -- The office stands in for a driver who did not mark.
    PERFORM _as(U_REGISTRAR);
    SELECT m.ok INTO v_ok FROM trip_mark(T_B, 'departed') m;
    PERFORM _assert(v_ok AND _trip_departed(T_B), 'a transport.manage holder could not mark a trip departed');

    -- (5) B, the mirror: his two buses, his manifest, not A's.
    PERFORM _as(U_DRIVE2);
    SELECT count(*) INTO n FROM trip;
    PERFORM _assert(n = 2 AND n = _count_trips_driven_by(U_DRIVE2),
      format('driver B reads %s trip(s); he is named on %s', n, _count_trips_driven_by(U_DRIVE2)));
    SELECT count(*) INTO n FROM trip_contacts(T_B);
    PERFORM _assert(n = _manifest_size(T_B), format('driver B reads %s contact rows on his own bus', n));
    SELECT count(*) INTO n FROM trip_contacts(T_A);
    PERFORM _assert(n = 0, format('driver B reads %s emergency contact(s) off A''s bus', n));
    -- ...and once his driver assignment is revoked, the trips still naming
    -- him give him nothing: no read, no fixture, no manifest, no mark.
    PERFORM _revoke(U_DRIVE2);
    SELECT (SELECT count(*) FROM trip) + (SELECT count(*) FROM match) INTO n;
    PERFORM _assert(n = 0, format('a revoked driver still reads %s trip/fixture row(s)', n));
    SELECT count(*) INTO n FROM trip_contacts(T_A2);
    PERFORM _assert(n = 0, format('a revoked driver reads %s emergency contact(s) off his own bus', n));
    SELECT m.reason INTO v_reason FROM trip_mark(T_A2, 'departed') m;
    PERFORM _assert(v_reason IS NOT DISTINCT FROM 'not_this_driver',
      format('a revoked driver marking the trip that names him was answered %s', coalesce(v_reason, 'ok')));

    -- (6) A cancelled trip no longer shows him its fixture — but he still
    --     reads the trip itself, so the screen can say it is off. That row
    --     is trip_driver_own_read's alone: with the fixture hidden, trip_read's
    --     anchor comes back NULL (for a live trip it resolves through the
    --     fixture he can now read, so the two policies overlap there).
    PERFORM _cancel_trip(T_F);
    PERFORM _as(U_DRIVE);
    SELECT count(*) INTO n FROM match WHERE id = M_F;
    PERFORM _assert(n = 0, 'the driver reads the fixture of a cancelled trip');
    SELECT count(*) INTO n FROM trip WHERE id = T_F;
    PERFORM _assert(n = 1, 'the driver cannot read his own cancelled trip');

    -- (7) NOBODY ELSE MOVED. For every other principal here, what they read
    --     of match and trip is exactly what db/09's policies gave them.
    FOREACH who IN ARRAY ARRAY[U_PARENT, U_SARAH, U_REGISTRAR, U_WATCHER, U_SELF, U_PUPIL,
                               U_COACH2, U_SCORER, U_MEDIC, U_BURSAR, U_WES_ADM, U_HEAD_M,
                               U_UMPIRE, U_LEAGUE, U_PLAT, U_OWNER]::uuid[] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO n FROM match;
      PERFORM _assert(n = _count_match_before_41(),
        format('%s reads %s fixture(s); db/09 gave %s', who, n, _count_match_before_41()));
      SELECT count(*) INTO n FROM trip;
      PERFORM _assert(n = _count_trip_before_41(),
        format('%s reads %s trip(s); db/09 gave %s', who, n, _count_trip_before_41()));
    END LOOP;
    -- ...and the transport office still sees every bus — including the ones
    -- on a fixture its schooladmin is himself driving to.
    PERFORM _as(U_REGISTRAR);
    SELECT count(*) INTO n FROM trip WHERE id IN (T_A, T_A2, T_A3, T_B, T_N, T_F);
    PERFORM _assert(n = 6, format('the transport office, driving one of them, reads %s of db/41''s 6 trips', n));
  END;

  -- ── 19. A player's SQL figures follow the fold (SCRBRD-068/081, db/40) ──
  -- Balls written live, old shapes beside new, and every career reader asked
  -- what moved. Deltas, read before and after, so whatever an earlier section
  -- left in the log cannot pass or fail this one. Every figure is coalesced
  -- to a number before it is compared: _assert() refuses a NULL, and a
  -- missing row is a figure of 0 here, not a check that never ran.
  --
  --   old  a no-ball for 4 with no nbRuns          off the bat: 4 runs, a four
  --   new  a no-ball, 4 byes     (nbRuns byes)     not his: 0 runs, no four
  --   new  a no-ball, 6 leg byes (nbRuns leg_byes) not his: 0 runs, no six
  --   old  a W ball naming timed_out               a ball, his dismissal, not the bowler's
  --   new  retire marked W, retired_out, P_BAT     his dismissal, no ball, no bowler
  --   new  retire marked W, timed_out,   P_OUT     his dismissal, an innings of 0 (0)
  --   new  retire marked W, a typed name           nobody's (not a player id)
  --   old  retire, reason out, NO W marker, P_OUT  not a wicket (as in the fold)
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SCORER);
  PERFORM set_config('app.device_id', 'verify-040', true);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-040') c;
  PERFORM _assert(v_ok, 'the scorer could not claim the match the db/40 section scores');
  DECLARE
    P_BAT  uuid := 'aaaaaaaa-0000-0000-0000-000000000006';  -- K Dlamini
    P_OUT  uuid := 'aaaaaaaa-0000-0000-0000-000000000011';  -- L Mahlangu, never faced a ball
    P_BOWL uuid := 'bbbbbbbb-0000-0000-0000-000000000002';  -- K Botha
    bat0 record; bat1 record; bow0 record; bow1 record;
    d_bat0 bigint; d_bat1 bigint; d_out0 bigint; d_out1 bigint; d_all0 bigint; d_all1 bigint;
    m_out0 bigint; m_out1 bigint; bw0 bigint; bw1 bigint;
    k_ro0 bigint; k_ro1 bigint; k_to0 bigint; k_to1 bigint; k_out0 bigint; k_out1 bigint;
    inn_out record;
  BEGIN
    PERFORM _as(U_OWNER);
    SELECT coalesce(b.runs, 0) AS runs, coalesce(b.balls_faced, 0) AS balls, coalesce(b.fours, 0) AS fours,
           coalesce(b.sixes, 0) AS sixes INTO bat0 FROM player_batting_since(P_BAT, NULL) b;
    SELECT coalesce(w.runs_conceded, 0) AS runs, coalesce(w.legal_balls, 0) AS balls,
           coalesce(w.no_balls, 0) AS nb, coalesce(w.wickets, 0) AS wkts INTO bow0 FROM player_bowling_since(P_BOWL, NULL) w;
    d_bat0 := coalesce(player_dismissals_since(P_BAT, NULL), 0);
    d_out0 := coalesce(player_dismissals_since(P_OUT, NULL), 0);
    SELECT coalesce(sum(dismissals), 0) INTO d_all0 FROM player_dismissals;
    SELECT coalesce((SELECT matches FROM player_batting_career WHERE player_id = P_OUT), 0) INTO m_out0;
    SELECT coalesce(sum(wickets), 0) INTO bw0 FROM player_wicket_breakdown WHERE player_id = P_BOWL;
    SELECT coalesce(sum(dismissals) FILTER (WHERE dismissal = 'retired_out'), 0),
           coalesce(sum(dismissals) FILTER (WHERE dismissal = 'timed_out'), 0)
      INTO k_ro0, k_to0 FROM player_dismissal_breakdown WHERE player_id = P_BAT;
    SELECT coalesce(sum(dismissals), 0) INTO k_out0 FROM player_dismissal_breakdown
     WHERE player_id = P_OUT AND dismissal = 'timed_out';

    PERFORM _as(U_SCORER);
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, ball_type, value,
                            striker_id, bowler_id, dismissal, payload)
    SELECT M_HANDOVER, match_school(M_HANDOVER), 9400 + x.k, v_epoch, 0, U_SCORER, 'verify-040',
           'verify:040:' || x.k, x.k, now(), x.kind, x.bt, x.v,
           CASE WHEN x.kind = 'ball' THEN P_BAT END, CASE WHEN x.kind = 'ball' THEN P_BOWL END,
           x.dis, x.pl
      FROM (VALUES
        (1, 'ball',   'Nb', 4,    NULL,          '{}'::jsonb),
        (2, 'ball',   'Nb', 4,    NULL,          '{"nbRuns":"byes"}'::jsonb),
        (3, 'ball',   'Nb', 6,    NULL,          '{"nbRuns":"leg_byes"}'::jsonb),
        (4, 'ball',   'W',  0,    'timed_out',   '{}'::jsonb),
        (5, 'retire', 'W',  NULL, 'retired_out', jsonb_build_object('batter', P_BAT, 'reason', 'out')),
        (6, 'retire', 'W',  NULL, 'timed_out',   jsonb_build_object('batter', P_OUT, 'reason', 'timed_out')),
        (7, 'retire', 'W',  NULL, 'retired_out', '{"batter":"An Opposition Boy","reason":"out"}'::jsonb),
        (8, 'retire', NULL, NULL, NULL,          jsonb_build_object('batter', P_OUT, 'reason', 'out'))
      ) AS x(k, kind, bt, v, dis, pl);

    PERFORM _as(U_OWNER);
    SELECT coalesce(b.runs, 0) AS runs, coalesce(b.balls_faced, 0) AS balls, coalesce(b.fours, 0) AS fours,
           coalesce(b.sixes, 0) AS sixes INTO bat1 FROM player_batting_since(P_BAT, NULL) b;
    SELECT coalesce(w.runs_conceded, 0) AS runs, coalesce(w.legal_balls, 0) AS balls,
           coalesce(w.no_balls, 0) AS nb, coalesce(w.wickets, 0) AS wkts INTO bow1 FROM player_bowling_since(P_BOWL, NULL) w;
    d_bat1 := coalesce(player_dismissals_since(P_BAT, NULL), 0);
    d_out1 := coalesce(player_dismissals_since(P_OUT, NULL), 0);
    SELECT coalesce(sum(dismissals), 0) INTO d_all1 FROM player_dismissals;
    SELECT coalesce((SELECT matches FROM player_batting_career WHERE player_id = P_OUT), 0) INTO m_out1;
    SELECT coalesce(sum(wickets), 0) INTO bw1 FROM player_wicket_breakdown WHERE player_id = P_BOWL;
    SELECT coalesce(sum(dismissals) FILTER (WHERE dismissal = 'retired_out'), 0),
           coalesce(sum(dismissals) FILTER (WHERE dismissal = 'timed_out'), 0)
      INTO k_ro1, k_to1 FROM player_dismissal_breakdown WHERE player_id = P_BAT;
    SELECT coalesce(sum(dismissals), 0) INTO k_out1 FROM player_dismissal_breakdown
     WHERE player_id = P_OUT AND dismissal = 'timed_out';
    SELECT coalesce(i.runs, -1) AS runs, coalesce(i.balls_faced, -1) AS balls, coalesce(i.out, false) AS out
      INTO inn_out FROM player_innings i WHERE i.player_id = P_OUT AND i.match_id = M_HANDOVER AND i.innings = 0;

    -- (a) Whose runs: runsOffBat(). Only the no-ball hit for four is his.
    PERFORM _assert(bat1.runs - bat0.runs = 4,
      format('a no-ball''s byes / leg byes were credited to the batter: +%s runs, expected +4 (the no-ball off the bat only)', bat1.runs - bat0.runs));
    PERFORM _assert(bat1.fours - bat0.fours = 1 AND bat1.sixes - bat0.sixes = 0,
      format('a no-ball''s byes / leg byes were counted as the batter''s boundary: +%s fours, +%s sixes, expected +1, +0',
             bat1.fours - bat0.fours, bat1.sixes - bat0.sixes));
    -- (b) ...and every no-ball is still a ball he faced; the old W ball is one
    --     too; a retirement is not.
    PERFORM _assert(bat1.balls - bat0.balls = 4,
      format('balls faced moved by %s, expected 4 (three no-balls and the old W ball; no retirement)', bat1.balls - bat0.balls));
    -- (c) The bowler is debited a no-ball's penalty run and the runs off the
    --     bat, not its byes or leg byes (Law 21.15, db/52): 5 + 1 + 1; the
    --     old timed-out W ball is a legal ball of his and not his wicket; a
    --     retirement is no ball and nobody's wicket.
    PERFORM _assert(bow1.runs - bow0.runs = 7 AND bow1.nb - bow0.nb = 3,
      format('the bowler was charged %s runs for %s no-balls, expected 7 for 3 (a no-ball''s byes and leg byes are not his, db/52)',
             bow1.runs - bow0.runs, bow1.nb - bow0.nb));
    PERFORM _assert(bow1.balls - bow0.balls = 1 AND bow1.wkts - bow0.wkts = 0 AND bw1 - bw0 = 0,
      format('the bowler''s legal balls / wickets / wicket breakdown moved by %s / %s / %s, expected 1 / 0 / 0',
             bow1.balls - bow0.balls, bow1.wkts - bow0.wkts, bw1 - bw0));
    -- (d) A retirement marked W is a dismissal of payload.batter — beside the
    --     old W ball naming timed_out, which still is one.
    PERFORM _assert(d_bat1 - d_bat0 = 2,
      format('the batter''s dismissals moved by %s, expected 2 (the old timed-out W ball and a retirement marked W)', d_bat1 - d_bat0));
    PERFORM _assert(d_out1 - d_out0 = 1,
      format('a batter timed out without facing a ball has %s more dismissals, expected 1 (and the unmarked retire none)', d_out1 - d_out0));
    -- (e) Nobody else: a typed name is not a player, and an unmarked retire
    --     with reason out is not a wicket (retirementDismissal()).
    PERFORM _assert(d_all1 - d_all0 = 3,
      format('dismissals across every player moved by %s, expected 3', d_all1 - d_all0));
    -- (f) A timed-out batter played an innings: 0 (0), out.
    PERFORM _assert(inn_out.runs = 0 AND inn_out.balls = 0 AND inn_out.out,
      format('a batter timed out has no innings of 0 (0), out: %s',
             CASE WHEN inn_out.out IS NULL THEN 'no row' ELSE inn_out::text END));
    PERFORM _assert(m_out1 - m_out0 = 1,
      format('a batter timed out has %s more batting matches, expected 1', m_out1 - m_out0));
    -- (g) By method.
    PERFORM _assert(k_ro1 - k_ro0 = 1 AND k_to1 - k_to0 = 1 AND k_out1 - k_out0 = 1,
      format('the dismissal breakdown moved retired_out %s / timed_out %s / timed_out (never faced) %s, expected 1 / 1 / 1',
             k_ro1 - k_ro0, k_to1 - k_to0, k_out1 - k_out0));
  END;
  PERFORM set_config('app.device_id', '', true);

  -- ── 20. A wicket the free hit saved is no wicket in SQL (db/42) ─────
  -- The fold saves a batter dismissed off a free hit by a bowler's method
  -- (standsOnFreeHit); every SQL reader now asks ball_wicket_stands() the
  -- same question. One over, on the match §19 scores and with the pen §19
  -- claimed, then a handover. Deltas, read before and after, coalesced to a
  -- number: _assert() refuses a NULL. Each assertion's label names what it
  -- guards; each was run once, alone, against the pre-db/42 definition of
  -- what it names (or the rule broken the way it says) and failed.
  --
  --    k  delivery                      striker  the fold
  --    1  a dot                          BAT     (whatever came before, no free hit now)
  --    2  W bowled                       BAT     stands, the bowler's
  --    3  W caught                       BAT     stands, the bowler's
  --    4  no-ball                        BAT     free hit
  --    5  W lbw                          SAVE    SAVED — and it breaks the hat-trick
  --    6  no-ball                        SAVE    free hit
  --    7  wide                           SAVE    carries the free hit
  --    8  W stumped                      SAVE    SAVED
  --    9  no-ball                        BAT     free hit
  --   10  W run out                      BAT     stands on a free hit, not the bowler's
  --   11  no-ball                        BAT     ...taken back by
  --   12  void of 11                             so no free hit
  --   13  W bowled                       BAT     stands, the bowler's
  --   14  no-ball                        SAVE    free hit
  --   15  W hit wicket                   SAVE    SAVED (and consumes the free hit)
  --   16  W caught                       BAT     stands, the bowler's
  --
  -- Five wickets stand (2, 3, 10, 13, 16); four are the bowler's, so no
  -- five-for; three are saved, all SAVE's, who is not out. Before db/42 the
  -- SQL counted eight, seven of them the bowler's, a five-for, a hat-trick
  -- completed at k = 5, and SAVE out three times.
  PERFORM set_config('app.device_id', 'verify-040', true);
  DECLARE
    P_BAT  uuid := 'aaaaaaaa-0000-0000-0000-000000000006';  -- K Dlamini
    P_SAVE uuid := 'aaaaaaaa-0000-0000-0000-000000000012';  -- J Sithole: on strike for every saved ball
    P_BOWL uuid := 'bbbbbbbb-0000-0000-0000-000000000002';  -- K Botha
    live0 bigint; live1 bigint; all0 bigint; fig0 bigint; fig1 bigint; bow0 bigint; bow1 bigint;
    wb0 record; wb1 record; sv0 bigint; sv1 bigint; bt0 bigint; bt1 bigint; sk0 bigint; sk1 bigint;
    hat0 bigint; hat1 bigint; five0 int; five1 int; hn0 int; hn1 int; save_out boolean; save_faced bigint;
    x record;
  BEGIN
    PERFORM _as(U_OWNER);
    live0 := coalesce((SELECT wickets FROM match_live_score WHERE match_id = M_HANDOVER AND innings = 0), 0);
    all0  := coalesce((SELECT sum(wickets) FROM match_live_score WHERE match_id = M_HANDOVER), 0);
    fig0  := coalesce((SELECT wickets FROM bowler_innings_figures
                        WHERE player_id = P_BOWL AND match_id = M_HANDOVER AND innings = 0), 0);
    bow0  := coalesce((SELECT wickets FROM player_bowling_since(P_BOWL, NULL)), 0);
    SELECT coalesce(sum(wickets) FILTER (WHERE dismissal IN ('bowled', 'caught')), 0) AS mine,
           coalesce(sum(wickets) FILTER (WHERE dismissal IN ('lbw', 'stumped', 'hit_wicket')), 0) AS saved
      INTO wb0 FROM player_wicket_breakdown WHERE player_id = P_BOWL;
    sv0 := coalesce(player_dismissals_since(P_SAVE, NULL), 0);
    bt0 := coalesce(player_dismissals_since(P_BAT, NULL), 0);
    sk0 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = P_SAVE), 0);
    hat0 := (SELECT count(*) FROM bowler_hat_trick WHERE player_id = P_BOWL AND match_id = M_HANDOVER AND innings = 0);
    five0 := _count_milestones(P_BOWL, 'five_for', M_HANDOVER);
    hn0   := _count_milestones(P_BOWL, 'hat_trick', M_HANDOVER);

    -- One statement per delivery, as they arrive: the milestone trigger is
    -- AFTER ROW, and in one multi-row INSERT every row's trigger would see
    -- the whole over — the five-for below could never be reached at five.
    PERFORM _as(U_SCORER);
    FOR x IN SELECT * FROM (VALUES
        ( 1, 'ball', 'run', NULL,         'bat',  '{}'::jsonb),
        ( 2, 'ball', 'W',   'bowled',     'bat',  '{}'::jsonb),
        ( 3, 'ball', 'W',   'caught',     'bat',  '{}'::jsonb),
        ( 4, 'ball', 'Nb',  NULL,         'bat',  '{}'::jsonb),
        ( 5, 'ball', 'W',   'lbw',        'save', '{}'::jsonb),
        ( 6, 'ball', 'Nb',  NULL,         'save', '{}'::jsonb),
        ( 7, 'ball', 'Wd',  NULL,         'save', '{}'::jsonb),
        ( 8, 'ball', 'W',   'stumped',    'save', '{}'::jsonb),
        ( 9, 'ball', 'Nb',  NULL,         'bat',  '{}'::jsonb),
        (10, 'ball', 'W',   'run_out',    'bat',  '{}'::jsonb),
        (11, 'ball', 'Nb',  NULL,         'bat',  '{}'::jsonb),
        (12, 'void', NULL,  NULL,         NULL,   '{"target":"verify:042:11"}'::jsonb),
        (13, 'ball', 'W',   'bowled',     'bat',  '{}'::jsonb),
        (14, 'ball', 'Nb',  NULL,         'save', '{}'::jsonb),
        (15, 'ball', 'W',   'hit_wicket', 'save', '{}'::jsonb),
        (16, 'ball', 'W',   'caught',     'bat',  '{}'::jsonb)
      ) AS v(k, kind, bt, dis, who, pl) ORDER BY k
    LOOP
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value,
                              striker_id, bowler_id, dismissal, payload)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9500 + x.k, v_epoch, 0, U_SCORER, 'verify-040',
              'verify:042:' || x.k, 9500 + x.k, now(), x.kind, x.bt, CASE WHEN x.kind = 'ball' THEN 0 END,
              CASE x.who WHEN 'bat' THEN P_BAT WHEN 'save' THEN P_SAVE END,
              CASE WHEN x.kind = 'ball' THEN P_BOWL END, x.dis, x.pl);
    END LOOP;

    PERFORM _as(U_OWNER);
    live1 := coalesce((SELECT wickets FROM match_live_score WHERE match_id = M_HANDOVER AND innings = 0), 0);
    fig1  := coalesce((SELECT wickets FROM bowler_innings_figures
                        WHERE player_id = P_BOWL AND match_id = M_HANDOVER AND innings = 0), 0);
    bow1  := coalesce((SELECT wickets FROM player_bowling_since(P_BOWL, NULL)), 0);
    SELECT coalesce(sum(wickets) FILTER (WHERE dismissal IN ('bowled', 'caught')), 0) AS mine,
           coalesce(sum(wickets) FILTER (WHERE dismissal IN ('lbw', 'stumped', 'hit_wicket')), 0) AS saved
      INTO wb1 FROM player_wicket_breakdown WHERE player_id = P_BOWL;
    sv1 := coalesce(player_dismissals_since(P_SAVE, NULL), 0);
    bt1 := coalesce(player_dismissals_since(P_BAT, NULL), 0);
    sk1 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = P_SAVE), 0);
    hat1 := (SELECT count(*) FROM bowler_hat_trick WHERE player_id = P_BOWL AND match_id = M_HANDOVER AND innings = 0);
    five1 := _count_milestones(P_BOWL, 'five_for', M_HANDOVER);
    hn1   := _count_milestones(P_BOWL, 'hat_trick', M_HANDOVER);
    SELECT coalesce(i.out, true), coalesce(i.balls_faced, 0) INTO save_out, save_faced
      FROM player_innings i WHERE i.player_id = P_SAVE AND i.match_id = M_HANDOVER AND i.innings = 0;

    -- (rule) The fold's flag, ball by ball: wides carry it, a void takes its
    -- no-ball away, a legal ball consumes it, a no-ball earns it.
    PERFORM _assert(ball_on_free_hit(M_HANDOVER, 0::smallint, 9505) AND ball_on_free_hit(M_HANDOVER, 0::smallint, 9510)
                    AND ball_on_free_hit(M_HANDOVER, 0::smallint, 9515),
      'db/42 (rule): a ball straight after a no-ball is not on a free hit');
    -- (rule-wide)
    PERFORM _assert(coalesce(ball_on_free_hit(M_HANDOVER, 0::smallint, 9508), false),
      'db/42 (rule-wide): a wide did not carry the free hit to the next ball');
    -- (rule-void)
    PERFORM _assert(NOT coalesce(ball_on_free_hit(M_HANDOVER, 0::smallint, 9513), true),
      'db/42 (rule-void): a no-ball that was taken back still earned a free hit');
    -- (rule-consumed)
    PERFORM _assert(NOT coalesce(ball_on_free_hit(M_HANDOVER, 0::smallint, 9516), true)
                    AND NOT coalesce(ball_on_free_hit(M_HANDOVER, 0::smallint, 9502), true),
      'db/42 (rule-consumed): a legal ball did not consume the free hit');
    -- (rule-methods) Only the six non-delivery methods stand; a NULL method does not.
    PERFORM _assert((SELECT bool_and(dismissal_stands_on_free_hit(d) = (d IN ('run_out', 'handled_ball', 'obstructing_field',
                                                                                'timed_out', 'retired_out', 'hit_twice')))
                       FROM unnest(ARRAY['bowled', 'caught', 'lbw', 'run_out', 'stumped', 'hit_wicket', 'handled_ball',
                                         'obstructing_field', 'timed_out', 'retired_out', 'hit_twice']) d)
                    AND dismissal_stands_on_free_hit(NULL) IS NOT DISTINCT FROM false,
      'db/42 (rule-methods): the methods that stand on a free hit are not events.mjs NON_DELIVERY');
    -- (a) match_live_score
    PERFORM _assert(live1 - live0 = 5,
      format('db/42 (a) match_live_score: wickets moved by %s, expected 5 (three were saved by the free hit)', live1 - live0));
    -- (c) bowler_innings_figures
    PERFORM _assert(fig1 - fig0 = 4,
      format('db/42 (c) bowler_innings_figures: the bowler''s wickets moved by %s, expected 4', fig1 - fig0));
    -- (d) player_bowling_since
    PERFORM _assert(bow1 - bow0 = 4,
      format('db/42 (d) player_bowling_since: the bowler''s career wickets moved by %s, expected 4', bow1 - bow0));
    -- (e) player_wicket_breakdown
    PERFORM _assert(wb1.mine - wb0.mine = 4 AND wb1.saved - wb0.saved = 0,
      format('db/42 (e) player_wicket_breakdown: bowled/caught moved by %s, lbw/stumped/hit wicket by %s, expected 4 and 0',
             wb1.mine - wb0.mine, wb1.saved - wb0.saved));
    -- (f) player_dismissals_since
    PERFORM _assert(sv1 - sv0 = 0 AND bt1 - bt0 = 5,
      format('db/42 (f) player_dismissals_since: the saved batter''s dismissals moved by %s (expected 0), the other''s by %s (expected 5)',
             sv1 - sv0, bt1 - bt0));
    -- (g) player_dismissal_breakdown
    PERFORM _assert(sk1 - sk0 = 0,
      format('db/42 (g) player_dismissal_breakdown: the saved batter has %s more lines of how he got out, expected 0', sk1 - sk0));
    -- (h) player_innings
    PERFORM _assert(save_faced >= 5 AND NOT save_out,
      format('db/42 (h) player_innings: the batter every free hit saved reads out=%s after %s balls faced', save_out, save_faced));
    -- (i) bowler_hat_trick
    PERFORM _assert(hat1 - hat0 = 0,
      format('db/42 (i) bowler_hat_trick: a hat-trick completed by a saved ball (%s new)', hat1 - hat0));
    -- (j) the five-for notice (milestone_watch over bowler_innings_figures)
    PERFORM _assert(five1 - five0 = 0,
      format('db/42 (j) milestone five_for: announced for four wickets and three saved balls (%s)', five1 - five0));
    -- (k) the hat-trick notice (milestone_watch and bowler_hat_trick)
    PERFORM _assert(hn1 - hn0 = 0,
      format('db/42 (k) milestone hat_trick: announced for a saved ball (%s)', hn1 - hn0));

    -- (b) scoring_verify_takeover: the pen goes to Sarah, who states the
    -- fold's count — five more wickets — and the server expects the same.
    PERFORM _as(U_SCORER);
    SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-040', 0, false) a;
    PERFORM _assert(v_code IS NOT NULL, 'db/42: the scorer could not arm a handover after the free-hit over');
    PERFORM _as(U_SARAH);
    SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-042-b', v_code) h;
    PERFORM _assert(v_ok, 'db/42: Sarah could not claim the handover after the free-hit over');
    SELECT v.exp_runs, v.exp_wkts, v.exp_balls INTO v_runs, v_wkts, v_balls
      FROM scoring_verify_takeover(M_HANDOVER, 'verify-042-b', -1, -1, -1) v;
    -- (b) scoring_verify_takeover
    PERFORM _assert(v_wkts - all0 = 5,
      format('db/42 (b) scoring_verify_takeover: expects %s more wickets than before the over, the fold says 5 — the handover could never verify',
             v_wkts - all0));
    SELECT v.ok INTO v_ok FROM scoring_verify_takeover(M_HANDOVER, 'verify-042-b', v_runs, all0::int + 5, v_balls) v;
    -- (b) scoring_verify_takeover
    PERFORM _assert(v_ok, 'db/42 (b) scoring_verify_takeover: the fold''s count did not verify after a saved wicket');
  END;
  PERFORM set_config('app.device_id', '', true);

  -- ── 21. The last places SQL disagreed with the fold (db/43) ─────────
  -- Who is out is the fold's `dismissed ?? striker`; the opposition's balls
  -- faced, boundaries and runs conceded are the fold's; a ball with no type
  -- is a run and a wicket with no method is nobody's; and a new row of either
  -- shape is refused at the door. Eleven balls written live on the match §19
  -- and §20 score, under a fresh claim, then two legacy rows written past the
  -- door as the owner. Figures read before, after the live balls ("mid") and
  -- after the legacy rows, as deltas, coalesced to a number: _assert()
  -- refuses a NULL. Each assertion's label names what it guards; each was run
  -- once, alone, against the definitions db/43 replaced (a database at db/42)
  -- — (rule) against db/13's dismissal_is_bowlers() — and failed.
  --
  --    k  delivery                        striker  who is out       the fold
  --    1  W run out, none run             S1       N0               N0: an innings of 0 (0), out
  --    2  W run out, 1 run, bowler's end  S1       NF               NF out, having faced §20's over
  --    3  W run out, none run             S1       a typed name     nobody here; S1 not out
  --    4  no-ball, 4 off the bat          MK                        his four, a ball faced; 5 to BO
  --    5  no-ball, 4 byes                 MK                        no four, a ball faced; 1 to BO (db/52)
  --    6  no-ball, 6 leg byes             MK                        no six, a ball faced; 1 to BO (db/52)
  --    7  wide, 4 run                     MK                        no ball faced, no four; 5 to BO
  --    8  4 byes                          MK                        a ball faced, no four; 0 to BO
  --    9  4 leg byes                      MK                        a ball faced, no four; 0 to BO
  --   10  6                               MK                        his six
  --   11  wide                            MK                        1 to BO
  --      ── mid ──
  --   12  NO TYPE, 3 (legacy)             MK                        a run: a legal ball, 3 to him and BO
  --   13  W, NO METHOD (legacy)           MK                        MK out; nobody's wicket
  --
  -- Before db/43: N0 had no innings, NF read not out, S1 read out (the typed
  -- name filed against him); MK had faced 3 balls with 4 fours, BO conceded
  -- 25; the no-type ball was no legal ball and nobody's runs; the wicket with
  -- no method was BO's; and either could be written anew.
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SCORER);
  PERFORM set_config('app.device_id', 'verify-043', true);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-043') c;
  PERFORM _assert(v_ok, 'the scorer could not claim the match the db/43 section scores');
  DECLARE
    S1 uuid := 'aaaaaaaa-0000-0000-0000-000000000002';  -- T Bekker: on strike for three run outs at the other end
    N0 uuid := 'aaaaaaaa-0000-0000-0000-000000000013';  -- B Khumalo: run out at the far end, never faced a ball
    NF uuid := 'aaaaaaaa-0000-0000-0000-000000000012';  -- J Sithole: faced §20's over, not out, run out here
    MK uuid := 'bbbbbbbb-0000-0000-0000-000000000001';  -- D Mkhize, Westville: the opposition's batter
    BO uuid := 'bbbbbbbb-0000-0000-0000-000000000002';  -- K Botha, Westville: the opposition's bowler
    M_OPP uuid;
    x record; v_con text;
    i_n0 record; i_nf record; i_s1 record;
    d_n0_0 bigint; d_nf_0 bigint; d_s1_0 bigint; d_n0_1 bigint; d_nf_1 bigint; d_s1_1 bigint;
    k_n0_0 bigint; k_nf_0 bigint; k_s1_0 bigint; k_n0_1 bigint; k_nf_1 bigint; k_s1_1 bigint;
    m_n0_0 bigint; m_n0_1 bigint; b_s1_0 record; b_s1_1 record;
    o0 record; o1 record; o2 record;   -- the opposition's figures (MK batting, BO bowling): before, mid, after
    l1 record; l2 record;               -- match_live_score, innings 0: mid, after
    w1 record; w2 record;               -- player_bowling_since(BO): mid, after
    f1 record; f2 record;               -- bowler_innings_figures(BO, this innings): mid, after
    wb1 bigint; wb2 bigint;             -- BO's wicket breakdown, method not recorded: mid, after
  BEGIN
    -- A day inside the window, whatever the window is: this section is about
    -- the figures the squad read returns, and §24 about when it opens.
    M_OPP := _opposition_fixture(opposition_window_days() - 1);
    PERFORM _as(U_OWNER);
    d_n0_0 := coalesce(player_dismissals_since(N0, NULL), 0);
    d_nf_0 := coalesce(player_dismissals_since(NF, NULL), 0);
    d_s1_0 := coalesce(player_dismissals_since(S1, NULL), 0);
    k_n0_0 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = N0 AND dismissal = 'run_out'), 0);
    k_nf_0 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = NF AND dismissal = 'run_out'), 0);
    k_s1_0 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = S1), 0);
    m_n0_0 := coalesce((SELECT matches FROM player_batting_since(N0, NULL)), 0);
    SELECT coalesce(max(b.runs), 0) AS runs, coalesce(max(b.balls_faced), 0) AS balls INTO b_s1_0 FROM player_batting_since(S1, NULL) b;
    SELECT coalesce(max(o.balls) FILTER (WHERE o.player_id = MK), 0) AS balls,
           coalesce(max(o.runs) FILTER (WHERE o.player_id = MK), 0) AS runs,
           coalesce(max(o.fours) FILTER (WHERE o.player_id = MK), 0) AS fours,
           coalesce(max(o.sixes) FILTER (WHERE o.player_id = MK), 0) AS sixes,
           coalesce(max(o.dismissals) FILTER (WHERE o.player_id = MK), 0) AS dismissals,
           coalesce(max(o.balls_bowled) FILTER (WHERE o.player_id = BO), 0) AS balls_bowled,
           coalesce(max(o.runs_conceded) FILTER (WHERE o.player_id = BO), 0) AS runs_conceded,
           coalesce(max(o.wickets) FILTER (WHERE o.player_id = BO), 0) AS wickets,
           count(*) FILTER (WHERE o.player_id IN (MK, BO)) AS seen
      INTO o0 FROM opposition_squad(M_OPP) o;
    PERFORM _assert(o0.seen = 2, 'db/43: the opposition''s squad could not be read for the section''s fixture');

    -- One statement per delivery, as they arrive (the milestone trigger is AFTER ROW).
    PERFORM _as(U_SCORER);
    FOR x IN SELECT * FROM (VALUES
        ( 1, 'W',   0, 'S1', 'N0', 'run_out', '{}'::jsonb),
        ( 2, 'W',   1, 'S1', 'NF', 'run_out', '{"outAt":"bowler_end"}'::jsonb),
        ( 3, 'W',   0, 'S1', NULL, 'run_out', '{"dismissed":"A Typed Boy"}'::jsonb),
        ( 4, 'Nb',  4, 'MK', NULL, NULL,      '{}'::jsonb),
        ( 5, 'Nb',  4, 'MK', NULL, NULL,      '{"nbRuns":"byes"}'::jsonb),
        ( 6, 'Nb',  6, 'MK', NULL, NULL,      '{"nbRuns":"leg_byes"}'::jsonb),
        ( 7, 'Wd',  4, 'MK', NULL, NULL,      '{}'::jsonb),
        ( 8, 'B',   4, 'MK', NULL, NULL,      '{}'::jsonb),
        ( 9, 'LB',  4, 'MK', NULL, NULL,      '{}'::jsonb),
        (10, 'run', 6, 'MK', NULL, NULL,      '{}'::jsonb),
        (11, 'Wd',  0, 'MK', NULL, NULL,      '{}'::jsonb)
      ) AS v(k, bt, val, who, outp, dis, pl) ORDER BY k
    LOOP
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value,
                              striker_id, bowler_id, dismissed_id, dismissal, payload)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9600 + x.k, v_epoch, 0, U_SCORER, 'verify-043',
              'verify:043:' || x.k, 9600 + x.k, now(), 'ball', x.bt, x.val,
              CASE x.who WHEN 'S1' THEN S1 WHEN 'MK' THEN MK END, BO,
              CASE x.outp WHEN 'N0' THEN N0 WHEN 'NF' THEN NF END, x.dis, x.pl);
    END LOOP;

    PERFORM _as(U_OWNER);
    d_n0_1 := coalesce(player_dismissals_since(N0, NULL), 0);
    d_nf_1 := coalesce(player_dismissals_since(NF, NULL), 0);
    d_s1_1 := coalesce(player_dismissals_since(S1, NULL), 0);
    k_n0_1 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = N0 AND dismissal = 'run_out'), 0);
    k_nf_1 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = NF AND dismissal = 'run_out'), 0);
    k_s1_1 := coalesce((SELECT sum(dismissals) FROM player_dismissal_breakdown WHERE player_id = S1), 0);
    m_n0_1 := coalesce((SELECT matches FROM player_batting_since(N0, NULL)), 0);
    SELECT coalesce(max(b.runs), 0) AS runs, coalesce(max(b.balls_faced), 0) AS balls INTO b_s1_1 FROM player_batting_since(S1, NULL) b;
    SELECT true AS found, i.runs, i.balls_faced AS balls, i.out INTO i_n0
      FROM player_innings i WHERE i.player_id = N0 AND i.match_id = M_HANDOVER AND i.innings = 0;
    SELECT true AS found, i.runs, i.balls_faced AS balls, i.out INTO i_nf
      FROM player_innings i WHERE i.player_id = NF AND i.match_id = M_HANDOVER AND i.innings = 0;
    SELECT true AS found, i.runs, i.balls_faced AS balls, i.out INTO i_s1
      FROM player_innings i WHERE i.player_id = S1 AND i.match_id = M_HANDOVER AND i.innings = 0;
    SELECT coalesce(max(o.balls) FILTER (WHERE o.player_id = MK), 0) AS balls,
           coalesce(max(o.runs) FILTER (WHERE o.player_id = MK), 0) AS runs,
           coalesce(max(o.fours) FILTER (WHERE o.player_id = MK), 0) AS fours,
           coalesce(max(o.sixes) FILTER (WHERE o.player_id = MK), 0) AS sixes,
           coalesce(max(o.dismissals) FILTER (WHERE o.player_id = MK), 0) AS dismissals,
           coalesce(max(o.balls_bowled) FILTER (WHERE o.player_id = BO), 0) AS balls_bowled,
           coalesce(max(o.runs_conceded) FILTER (WHERE o.player_id = BO), 0) AS runs_conceded,
           coalesce(max(o.wickets) FILTER (WHERE o.player_id = BO), 0) AS wickets
      INTO o1 FROM opposition_squad(M_OPP) o;
    SELECT coalesce(max(legal_balls), 0) AS balls, coalesce(max(runs), 0) AS runs, coalesce(max(wickets), 0) AS wickets
      INTO l1 FROM match_live_score WHERE match_id = M_HANDOVER AND innings = 0;
    SELECT coalesce(max(w.runs_conceded), 0) AS runs, coalesce(max(w.legal_balls), 0) AS balls,
           coalesce(max(w.wickets), 0) AS wickets INTO w1 FROM player_bowling_since(BO, NULL) w;
    SELECT coalesce(max(f.wickets), 0) AS wickets, coalesce(max(f.runs_conceded), 0) AS runs
      INTO f1 FROM bowler_innings_figures f WHERE f.player_id = BO AND f.match_id = M_HANDOVER AND f.innings = 0;
    wb1 := coalesce((SELECT sum(wickets) FROM player_wicket_breakdown WHERE player_id = BO AND dismissal IS NULL), 0);

    -- The legacy rows: what a database stored before the door.
    PERFORM _insert_past_the_door(jsonb_build_array(
      jsonb_build_object('match_id', M_HANDOVER, 'seq', 9612, 'epoch', v_epoch, 'innings', 0, 'scorer_user_id', U_SCORER,
                         'device_id', 'verify-043', 'idempotency_key', 'verify:043:12', 'client_seq', 9612,
                         'kind', 'ball', 'ball_type', NULL, 'value', 3, 'striker_id', MK, 'bowler_id', BO),
      jsonb_build_object('match_id', M_HANDOVER, 'seq', 9613, 'epoch', v_epoch, 'innings', 0, 'scorer_user_id', U_SCORER,
                         'device_id', 'verify-043', 'idempotency_key', 'verify:043:13', 'client_seq', 9613,
                         'kind', 'ball', 'ball_type', 'W', 'value', 0, 'striker_id', MK, 'bowler_id', BO, 'dismissal', NULL)));

    SELECT coalesce(max(o.balls) FILTER (WHERE o.player_id = MK), 0) AS balls,
           coalesce(max(o.runs) FILTER (WHERE o.player_id = MK), 0) AS runs,
           coalesce(max(o.dismissals) FILTER (WHERE o.player_id = MK), 0) AS dismissals,
           coalesce(max(o.balls_bowled) FILTER (WHERE o.player_id = BO), 0) AS balls_bowled,
           coalesce(max(o.runs_conceded) FILTER (WHERE o.player_id = BO), 0) AS runs_conceded,
           coalesce(max(o.wickets) FILTER (WHERE o.player_id = BO), 0) AS wickets
      INTO o2 FROM opposition_squad(M_OPP) o;
    SELECT coalesce(max(legal_balls), 0) AS balls, coalesce(max(runs), 0) AS runs, coalesce(max(wickets), 0) AS wickets
      INTO l2 FROM match_live_score WHERE match_id = M_HANDOVER AND innings = 0;
    SELECT coalesce(max(w.runs_conceded), 0) AS runs, coalesce(max(w.legal_balls), 0) AS balls,
           coalesce(max(w.wickets), 0) AS wickets INTO w2 FROM player_bowling_since(BO, NULL) w;
    SELECT coalesce(max(f.wickets), 0) AS wickets, coalesce(max(f.runs_conceded), 0) AS runs
      INTO f2 FROM bowler_innings_figures f WHERE f.player_id = BO AND f.match_id = M_HANDOVER AND f.innings = 0;
    wb2 := coalesce((SELECT sum(wickets) FROM player_wicket_breakdown WHERE player_id = BO AND dismissal IS NULL), 0);

    -- (a) player_innings: the non-striker run out before he faced a ball
    PERFORM _assert(coalesce(i_n0.found AND i_n0.runs = 0 AND i_n0.balls = 0 AND i_n0.out, false),
      format('db/43 (a) player_innings: a batter run out at the non-striker''s end before he faced a ball has no innings of 0 (0), out: %s',
             CASE WHEN i_n0.found IS NULL THEN 'no row' ELSE i_n0::text END));
    -- (b) player_innings: the non-striker run out after facing
    PERFORM _assert(coalesce(i_nf.found AND i_nf.balls >= 1 AND i_nf.out, false),
      format('db/43 (b) player_innings: a batter run out at the non-striker''s end after facing %s ball(s) reads out=%s',
             coalesce(i_nf.balls::text, 'no'), coalesce(i_nf.out::text, 'no row')));
    -- (c) player_innings: the striker of those balls
    PERFORM _assert(coalesce(i_s1.found AND i_s1.runs = 1 AND i_s1.balls = 3 AND NOT i_s1.out, false),
      format('db/43 (c) player_innings: the striker of three run outs at the other end — one of a batter SCRBRD holds no row for — reads %s, expected 1 (3), not out',
             CASE WHEN i_s1.found IS NULL THEN 'no row' ELSE i_s1::text END));
    -- (d) player_dismissals_since
    PERFORM _assert(d_n0_1 - d_n0_0 = 1 AND d_nf_1 - d_nf_0 = 1 AND d_s1_1 - d_s1_0 = 0,
      format('db/43 (d) player_dismissals_since: dismissals moved by %s (never faced), %s (had faced), %s (the striker); expected 1, 1, 0',
             d_n0_1 - d_n0_0, d_nf_1 - d_nf_0, d_s1_1 - d_s1_0));
    -- (e) player_dismissal_breakdown
    PERFORM _assert(k_n0_1 - k_n0_0 = 1 AND k_nf_1 - k_nf_0 = 1 AND k_s1_1 - k_s1_0 = 0,
      format('db/43 (e) player_dismissal_breakdown: run-out lines moved by %s and %s, the striker''s by %s; expected 1, 1, 0',
             k_n0_1 - k_n0_0, k_nf_1 - k_nf_0, k_s1_1 - k_s1_0));
    -- (f) player_batting_since
    PERFORM _assert(m_n0_1 - m_n0_0 = 1 AND b_s1_1.runs - b_s1_0.runs = 1 AND b_s1_1.balls - b_s1_0.balls = 3,
      format('db/43 (f) player_batting_since: the batter run out before facing has %s more batting matches (expected 1); the striker %s more runs off %s more balls (expected 1 off 3)',
             m_n0_1 - m_n0_0, b_s1_1.runs - b_s1_0.runs, b_s1_1.balls - b_s1_0.balls));
    -- (g) opposition_squad: balls faced
    PERFORM _assert(o1.balls - o0.balls = 6,
      format('db/43 (g) opposition_squad balls: the batter faced %s more balls, expected 6 (three no-balls, a bye, a leg bye, a six; not the wides)',
             o1.balls - o0.balls));
    -- (h) opposition_squad: fours and sixes
    PERFORM _assert(o1.fours - o0.fours = 1 AND o1.sixes - o0.sixes = 1 AND o1.runs - o0.runs = 10,
      format('db/43 (h) opposition_squad fours/sixes: %s fours, %s sixes and %s runs more, expected 1, 1 and 10 (off the bat only: no byes, leg byes, wide or no-ball byes to the rope)',
             o1.fours - o0.fours, o1.sixes - o0.sixes, o1.runs - o0.runs));
    -- (i) opposition_squad: runs conceded
    PERFORM _assert(o1.runs_conceded - o0.runs_conceded = 20 AND o1.balls_bowled - o0.balls_bowled = 6,
      format('db/43 (i) opposition_squad runs_conceded: the bowler conceded %s more off %s more balls, expected 20 off 6 (a wide is the penalty run and every run off it; a no-ball the penalty run and the runs off the bat, not its byes or leg byes, db/52)',
             o1.runs_conceded - o0.runs_conceded, o1.balls_bowled - o0.balls_bowled));
    -- (j) match_live_score: the legacy rows
    PERFORM _assert(l2.balls - l1.balls = 2 AND l2.runs - l1.runs = 3 AND l2.wickets - l1.wickets = 1,
      format('db/43 (j) match_live_score: a ball with no type and a wicket with no method moved the legal balls / runs / wickets by %s / %s / %s; expected 2 / 3 / 1',
             l2.balls - l1.balls, l2.runs - l1.runs, l2.wickets - l1.wickets));
    -- (k) player_bowling_since: the legacy rows
    PERFORM _assert(w2.runs - w1.runs = 3 AND w2.balls - w1.balls = 2 AND w2.wickets - w1.wickets = 0,
      format('db/43 (k) player_bowling_since: the legacy rows moved the bowler''s runs / legal balls / wickets by %s / %s / %s; expected 3 / 2 / 0',
             w2.runs - w1.runs, w2.balls - w1.balls, w2.wickets - w1.wickets));
    -- (l) bowler_innings_figures: the legacy rows
    PERFORM _assert(f2.wickets - f1.wickets = 0 AND f2.runs - f1.runs = 3,
      format('db/43 (l) bowler_innings_figures: the legacy rows moved the bowler''s wickets / runs in the innings by %s / %s; expected 0 / 3',
             f2.wickets - f1.wickets, f2.runs - f1.runs));
    -- (m) player_wicket_breakdown: the legacy wicket
    PERFORM _assert(wb2 - wb1 = 0,
      format('db/43 (m) player_wicket_breakdown: a wicket with no method was filed as the bowler''s (%s more)', wb2 - wb1));
    -- (n) opposition_squad: the legacy rows
    PERFORM _assert(o2.balls - o1.balls = 2 AND o2.runs - o1.runs = 3 AND o2.dismissals - o1.dismissals = 0
                    AND o2.balls_bowled - o1.balls_bowled = 2 AND o2.runs_conceded - o1.runs_conceded = 3
                    AND o2.wickets - o1.wickets = 0,
      format('db/43 (n) opposition_squad: the legacy rows moved the batter''s balls / runs / dismissals by %s / %s / %s (expected 2 / 3 / 0) and the bowler''s balls / runs / wickets by %s / %s / %s (expected 2 / 3 / 0)',
             o2.balls - o1.balls, o2.runs - o1.runs, o2.dismissals - o1.dismissals,
             o2.balls_bowled - o1.balls_bowled, o2.runs_conceded - o1.runs_conceded, o2.wickets - o1.wickets));
    -- (rule) the rules themselves
    PERFORM _assert(dismissal_is_bowlers(NULL) IS NOT DISTINCT FROM false
                    AND dismissal_stands_on_free_hit(NULL) IS NOT DISTINCT FROM false
                    AND ball_type_as_folded('ball', NULL) IS NOT DISTINCT FROM 'run'
                    AND ball_type_as_folded('retire', NULL) IS NULL
                    AND ball_dismissed_batter(S1, NULL, '{"dismissed":"A Typed Boy"}'::jsonb) IS NULL
                    AND ball_dismissed_batter(S1, NULL, '{}'::jsonb) IS NOT DISTINCT FROM S1
                    AND ball_dismissed_batter(S1, N0, '{}'::jsonb) IS NOT DISTINCT FROM N0,
      'db/43 (rule): a wicket with no method is the bowler''s or stands on a free hit, a ball with no type is not a run, or who is out is not `dismissed ?? striker`');

    -- (door-type) and (door-method): a client that writes either now is
    -- refused by the table itself, whoever it is — 23514, naming the rule,
    -- as a CHECK would (db/43's trigger).
    PERFORM _as(U_SCORER);
    v_con := NULL;
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value, striker_id, bowler_id)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9620, v_epoch, 0, U_SCORER, 'verify-043',
              'verify:043:door-type', 9620, now(), 'ball', NULL, 1, MK, BO);
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
    END;
    -- (door-type)
    PERFORM _assert(v_con IS NOT DISTINCT FROM 'ball_event_ball_has_type',
      format('db/43 (door-type): a new ball with no type was %s', coalesce('refused by ' || v_con, 'written')));
    v_con := NULL;
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value, striker_id, bowler_id)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9621, v_epoch, 0, U_SCORER, 'verify-043',
              'verify:043:door-method', 9621, now(), 'ball', 'W', 0, MK, BO);
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
    END;
    -- (door-method)
    PERFORM _assert(v_con IS NOT DISTINCT FROM 'ball_event_wicket_has_method',
      format('db/43 (door-method): a new wicket ball with no method was %s', coalesce('refused by ' || v_con, 'written')));
  END;
  PERFORM set_config('app.device_id', '', true);

  -- ── 22. Career figures by season (SCRBRD-086, db/44) ───────────────
  -- The season views are the lifetime views one grain finer: grouped by the
  -- school season each match is in, on the Johannesburg calendar, and read
  -- as the caller. _seed_44() (above) writes the fixture: three Hilton 2XI
  -- matches — 2025, New Year (23:30 UTC on 31 December 2025), 2026 — of the
  -- same fifteen events, and a Westville match in 2024 with one delivery by
  -- a Hilton boy. The log by now also holds everything sections 19 and 20
  -- wrote (no-ball byes, retirements, free-hit saves, a void), so the
  -- invariant below runs over those rules too. Every figure is compared as
  -- a row or a count: _assert() refuses a NULL, so a missing row fails
  -- rather than passing. Each assertion's label names what it guards; each
  -- was run once, alone (every other db/44 assertion switched off), with
  -- db/44 broken the way this table says, and failed for that reason:
  --
  --   (a)   a season view without security_invoker; and one run as its owner
  --         over ball_event itself (an unidentified session read 11 rows)
  --   (b)   a season view without security_invoker (the Westville reader
  --         saw the Hilton boy's row)
  --   (c)   school_season_of() on the UTC date (New Year filed in 2025)
  --   (d1)  batting runs and fours by `value`, as before db/40
  --   (d2)  a delivery with no ball type counted as a ball faced (before
  --         db/43; since db/43 it IS a run and a ball faced, as the fold
  --         reads it, and (d2) holds that — db/43's §21 falsifies it)
  --   (d3)  the dismissals view without ball_wicket_stands()
  --   (d4)  the bowling view without ball_wicket_stands()
  --   (e0)  one Hilton-fixture delivery stamped with Westville's school
  --   (e)   one reader's composition drifting (a NULL ball type counted as
  --         a legal ball); the retirement branch dropped; deliveries counted
  --         as matches; and every match in one season, for the span check
  PERFORM _seed_44();
  DECLARE
    P44_A  uuid := 'aaaaaaaa-0000-0000-0000-00000000044a';  -- on strike
    P44_B  uuid := 'aaaaaaaa-0000-0000-0000-00000000044b';  -- the other end
    P44_C  uuid := 'aaaaaaaa-0000-0000-0000-00000000044c';  -- bowling; once at Westville
    M44_NY uuid := '77777777-0000-0000-0000-0000000440e0';  -- 01:30 on 1 January 2026, Johannesburg
    who    uuid;
    x      record;
    y      record;
    n      bigint;
    n2     bigint;
    n3     bigint;
    n4     bigint;
    detail text;
  BEGIN
    -- (a) Every season view runs as its caller, and so reads nothing for a
    --     session that is nobody. The catalog is asked as well as the rows:
    --     a view that lost security_invoker would still read DELIVERIES as
    --     its caller — it reaches them through ball_event_live, which is
    --     invoker — while reading match and player as its owner, past their
    --     policies. No row count here can see that; (b) is what it looks
    --     like from the other school.
    SELECT count(*) INTO n3 FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
     WHERE ns.nspname = 'public' AND c.relkind = 'v'
       AND c.relname IN ('player_batting_by_season', 'player_bowling_by_season', 'player_dismissals_by_season')
       AND 'security_invoker=true' = ANY (c.reloptions);
    SELECT count(*) INTO n4 FROM pg_proc p
     WHERE p.oid = to_regprocedure('school_season_of(timestamptz)') AND NOT p.prosecdef;
    PERFORM set_config('app.user_id', '', true);
    SELECT (SELECT count(*) FROM player_batting_by_season) + (SELECT count(*) FROM player_bowling_by_season)
         + (SELECT count(*) FROM player_dismissals_by_season) INTO n;
    PERFORM _as(U_OWNER);
    SELECT (SELECT count(*) FROM player_batting_by_season) + (SELECT count(*) FROM player_bowling_by_season)
         + (SELECT count(*) FROM player_dismissals_by_season) INTO n2;
    -- (a) nobody by default
    PERFORM _assert(n3 = 3 AND n4 = 1 AND n = 0 AND n2 > 0,
      format('db/44 (a) nobody by default: %s of the 3 season views are security_invoker and %s of 1 season function runs as its caller; '
             || 'an unidentified session read %s rows of career figures by season (the owner reads %s)', n3, n4, n, n2));

    -- (b) A coach at one school reads nothing of another's through them. The
    --     Westville fixture is in 2024, a season no Hilton fixture is in, and
    --     one of its deliveries is a Hilton boy's: a Hilton coach reads no
    --     2024 row at all — not his own boy's either, from a match he cannot
    --     read — and no Westville player; the Westville administrator reads
    --     his own boys' 2024 figures and nothing of Hilton's. The owner reads
    --     all of it, so none of this passes for want of a row.
    PERFORM _as(U_OWNER);
    SELECT count(*) INTO n FROM player_bowling_by_season WHERE player_id = P44_C AND season = '2024';
    PERFORM _as(U_COACH2);
    SELECT (SELECT count(*) FROM player_batting_by_season    WHERE season = '2024' OR player_id IN (P_WES, P_WES2))
         + (SELECT count(*) FROM player_bowling_by_season    WHERE season = '2024' OR player_id IN (P_WES, P_WES2))
         + (SELECT count(*) FROM player_dismissals_by_season WHERE season = '2024' OR player_id IN (P_WES, P_WES2))
      INTO n2;
    PERFORM _as(U_WES_ADM);
    SELECT (SELECT count(*) FROM player_batting_by_season    WHERE player_id = P_WES  AND season = '2024')
         + (SELECT count(*) FROM player_bowling_by_season    WHERE player_id = P_WES2 AND season = '2024')
         + (SELECT count(*) FROM player_dismissals_by_season WHERE player_id = P_WES  AND season = '2024')
      INTO n3;
    SELECT (SELECT count(*) FROM player_batting_by_season    WHERE player_id IN (P44_A, P44_B, P44_C))
         + (SELECT count(*) FROM player_bowling_by_season    WHERE player_id IN (P44_A, P44_B, P44_C))
         + (SELECT count(*) FROM player_dismissals_by_season WHERE player_id IN (P44_A, P44_B, P44_C))
      INTO n4;
    -- (b) school A sees nothing of school B
    PERFORM _assert(n = 1 AND n2 = 0 AND n3 = 3 AND n4 = 0,
      format('db/44 (b) school A sees nothing of school B: the owner reads %s 2024 row(s) for the Hilton boy who bowled at Westville (expected 1); '
             || 'the Hilton 2XI coach reads %s rows from Westville''s fixture or players (expected 0); '
             || 'the Westville administrator reads %s of his own boys'' three 2024 rows and %s of Hilton''s (expected 3 and 0)', n, n2, n3, n4));

    -- (c) The Johannesburg calendar: the New Year fixture is in 2026, though
    --     its UTC date is still 31 December 2025 — the fixture straddles the
    --     line, so this can tell the two rules apart. The matches read files
    --     it with the same function.
    PERFORM _as(U_SCORER);
    SELECT school_season_of(m.starts_at) AS season, (m.starts_at AT TIME ZONE 'UTC')::date AS utc_day
      INTO x FROM match m WHERE m.id = M44_NY;
    -- (c) the Johannesburg calendar
    PERFORM _assert(x.season = '2026' AND x.utc_day = date '2025-12-31',
      format('db/44 (c) the Johannesburg calendar: a fixture at 01:30 on 1 January 2026 in Johannesburg (UTC day %s) is filed in season %s, expected 2026',
             x.utc_day, x.season));

    -- (d) The figures, season by season, as the school's scorer reads them:
    --     one fixture in 2025, two in 2026 (the New Year one among them).
    SELECT (SELECT row(matches, runs, balls_faced, fours, sixes)::text FROM player_batting_by_season
             WHERE player_id = P44_A AND season = '2025') AS y2025,
           (SELECT row(matches, runs, balls_faced, fours, sixes)::text FROM player_batting_by_season
             WHERE player_id = P44_A AND season = '2026') AS y2026 INTO x;
    -- (d1) batting by season: runs, fours and sixes off the bat
    PERFORM _assert(x.y2025 = '(1,14,7,2,1)' AND x.y2026 = '(2,28,14,4,2)',
      format('db/44 (d1) batting by season: the opener''s (matches, runs, balls, fours, sixes) are %s in 2025 and %s in 2026, expected (1,14,7,2,1) and (2,28,14,4,2) — '
             || 'a no-ball''s byes are not his runs or his boundary, a wide is not a ball he faced, and the New Year fixture is 2026''s',
             coalesce(x.y2025, 'no row'), coalesce(x.y2026, 'no row')));
    SELECT (SELECT row(matches, runs, balls_faced, fours, sixes)::text FROM player_batting_by_season
             WHERE player_id = P44_B AND season = '2025') AS y2025,
           (SELECT row(matches, runs, balls_faced, fours, sixes)::text FROM player_batting_by_season
             WHERE player_id = P44_B AND season = '2026') AS y2026 INTO x;
    -- (d2) batting by season: a delivery with no type is a run; one taken back is nothing
    PERFORM _assert(x.y2025 = '(1,2,2,0,0)' AND x.y2026 = '(2,4,4,0,0)',
      format('db/44 (d2) batting by season: the partner''s (matches, runs, balls, fours, sixes) are %s in 2025 and %s in 2026, expected (1,2,2,0,0) and (2,4,4,0,0) — '
             || 'a delivery with no ball type is a run, as the fold reads it (db/43), and a voided run is nothing to anybody',
             coalesce(x.y2025, 'no row'), coalesce(x.y2026, 'no row')));
    SELECT (SELECT row(a.dismissals, b.dismissals)::text
              FROM player_dismissals_by_season a, player_dismissals_by_season b
             WHERE a.player_id = P44_A AND a.season = '2025' AND b.player_id = P44_B AND b.season = '2025') AS y2025,
           (SELECT row(a.dismissals, b.dismissals)::text
              FROM player_dismissals_by_season a, player_dismissals_by_season b
             WHERE a.player_id = P44_A AND a.season = '2026' AND b.player_id = P44_B AND b.season = '2026') AS y2026 INTO x;
    -- (d3) dismissals by season: the free hit saves, a retirement marked W does not
    PERFORM _assert(x.y2025 = '(1,2)' AND x.y2026 = '(2,4)',
      format('db/44 (d3) dismissals by season: (opener, partner) are %s in 2025 and %s in 2026, expected (1,2) and (2,4) — '
             || 'an lbw on a free hit is no dismissal, a retirement marked W is one, a run out at the other end is the non-striker''s, a W with no method still dismisses its batter',
             coalesce(x.y2025, 'no row'), coalesce(x.y2026, 'no row')));
    SELECT (SELECT row(matches, runs_conceded, legal_balls, wides, no_balls, wickets)::text FROM player_bowling_by_season
             WHERE player_id = P44_C AND season = '2025') AS y2025,
           (SELECT row(matches, runs_conceded, legal_balls, wides, no_balls, wickets)::text FROM player_bowling_by_season
             WHERE player_id = P44_C AND season = '2026') AS y2026 INTO x;
    -- (d4) bowling by season: every run of a wide is his, a no-ball's run and its runs off the bat (not its byes,
    --      db/52); a saved, a run-out or a methodless wicket is not
    PERFORM _assert(x.y2025 = '(1,21,8,1,2,0)' AND x.y2026 = '(2,42,16,2,4,0)',
      format('db/44 (d4) bowling by season: the seamer''s (matches, conceded, legal balls, wides, no-balls, wickets) are %s in 2025 and %s in 2026, expected (1,21,8,1,2,0) and (2,42,16,2,4,0) — '
             || 'a no-ball''s byes are not his (db/52); a delivery with no type is a legal ball and its runs his; an lbw the free hit saved, a run out and a W with no method are not his wickets (db/43)',
             coalesce(x.y2025, 'no row'), coalesce(x.y2026, 'no row')));

    -- (e0) Its precondition, over the whole log: every delivery carries its
    --      fixture's school, so a delivery a reader may see is of a fixture
    --      the reader may see, and filing it under the fixture's season
    --      drops nothing.
    n := _count_ball_school_mismatch();
    n2 := _count_rows('ball_event');
    -- (e0) every delivery is its fixture's school's
    PERFORM _assert(n = 0 AND n2 > 0,
      format('db/44 (e0) every delivery is its fixture''s school''s: %s of %s deliveries carry another school, '
             || 'and a reader who may see one of those may not see its fixture — its season figures would leave it out', n, n2));

    -- (e) THE INVARIANT. For every player each of seven principals may read,
    --     the figures summed over seasons are the lifetime figures, column
    --     by column, across the whole log — the seed's innings, sections 19
    --     and 20, and this fixture. The owner reads every school; the
    --     director, the scorer and the 2XI coach read Hilton at three
    --     different widths; the Westville administrator reads Westville; the
    --     1XI pupil reads his own side's deliveries; and a guardian, whose
    --     assignment is about one child, reads the deliveries of his
    --     child's side's fixtures while his link is live (db/100, §77;
    --     until then the log asked about nobody in particular), and by
    --     here his link has ended, so must get nothing from either side.
    FOREACH who IN ARRAY ARRAY[U_OWNER, U_SARAH, U_SCORER, U_COACH2, U_WES_ADM, U_PARENT, U_SELF] LOOP
      PERFORM _as(who);
      SELECT count(*), string_agg(format('%s %s: lifetime %s, by season %s', d.family, d.player_id, d.lifetime, d.by_season), '; ')
        INTO n, detail FROM _career_season_drift() d;
      -- (e) the invariant
      PERFORM _assert(n = 0,
        format('db/44 (e) the invariant, as %s: %s figure(s) are not the sum of their seasons — %s', who, n, left(detail, 600)));
    END LOOP;
    -- ...and the guardian's reads are none, for the reason db/100 now gives:
    -- the log is read about his child (his child's side's fixtures, §77),
    -- and "Guardianship ends at eighteen" above wound his link to R Pillay
    -- back to a date already past, so it reaches no fixture. Before db/100
    -- he read none because the log asked about nobody in particular.
    PERFORM _as(U_PARENT);
    PERFORM _assert((SELECT count(*) FROM ball_event) = 0
                    AND NOT EXISTS (SELECT 1 FROM player_batting_by_season)
                    AND NOT EXISTS (SELECT 1 FROM player_bowling_by_season),
      format('db/44 (e) as the guardian of R Pillay, whose link has ended: he reads %s deliveries (none; db/100)',
             (SELECT count(*) FROM ball_event)));
    -- ...and it held over something: the fixture's three boys each have two
    -- seasons to add up, for every Hilton reader who can see the 2XI.
    FOREACH who IN ARRAY ARRAY[U_OWNER, U_SARAH, U_SCORER, U_COACH2] LOOP
      PERFORM _as(who);
      SELECT (SELECT count(DISTINCT season) FROM player_batting_by_season    WHERE player_id = P44_A)
           + (SELECT count(DISTINCT season) FROM player_dismissals_by_season WHERE player_id = P44_B)
           + (SELECT count(DISTINCT season) FROM player_bowling_by_season    WHERE player_id = P44_C AND season <> '2024')
        INTO n;
      -- (e) the invariant, over two seasons
      PERFORM _assert(n = 6,
        format('db/44 (e) the invariant, as %s: the fixture''s three boys span %s player-seasons, expected 6 — the sums above were not over two seasons', who, n));
    END LOOP;
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 23. A handover verifies this innings, penalties included (SCRBRD-088, db/45) ──
  -- The incoming scorer states the scoreboard's figures for the innings being
  -- played, and the fold keeps them per innings with penalty awards in the
  -- total. On the match §19–§21 score (every earlier row innings 0), under a
  -- fresh claim: penalty and retirement rows in the first innings, then a
  -- second innings, then a first-innings ball written at a later seq (as a
  -- release from quarantine writes one), then a handover. Deltas and exact
  -- rows, coalesced or compared as text: _assert() refuses a NULL. Each
  -- assertion's label names what it guards; each was run once, alone, with
  -- db/45 broken the way this table says, and failed for that reason:
  --
  --   (current)       match_current_innings() as the innings of the highest
  --                   seq (the late first-innings ball took it back to 0)
  --   (penalty)       penalty_runs_as_folded() returning 0 for every row, as
  --                   `value` alone did; and, separately, with the
  --                   `toBattingTeam` test dropped
  --   (wickets)       innings_score_as_folded() counting every row marked W,
  --                   as ball_wicket_stands() alone did
  --   (innings)       the helper summing every innings up to this one
  --   (nobody)        innings_score_as_folded() and match_current_innings()
  --                   as SECURITY DEFINER, search path pinned (so the db/16
  --                   check above does not catch it first)
  --   (verify-expects) scoring_verify_takeover() as db/42 left it
  --   (audit)         the mismatch's audit row without its innings
  --   (verify-old)    a check that also accepts the match's totals
  --   (verify-penalty) a check that also accepts this innings without its
  --                   penalty runs
  --   (verify-ok)     a check that refuses every statement in a second innings
  --
  --    k  innings  row                                        the fold, this innings
  --    1  0        penalty, 5 to the batting side             +5
  --    2  0        penalty, no runs named                     +5 (`runs ?? 5`)
  --    3  0        penalty, 5 to the fielding side            nothing
  --    4  0        penalty, runs 2, `value` 3 on the row      +2 — value is read on deliveries only
  --    5  0        retire marked W, retired out               a wicket
  --    6  0        retire marked W, method `bowled`, hurt     no wicket: not a retirement dismissal
  --   10  1        innings_start                              the second innings is current, 0/0 off 0
  --   11  1        6                                          6, a legal ball
  --   12  1        W bowled                                   a wicket, a legal ball
  --   13  1        no-ball, 1 run                             2 (the leg bye is on its free hit)
  --   14  1        penalty, 5 to the batting side             5
  --   15  1        penalty, 5 to the fielding side            nothing
  --   16  1        leg bye, 1                                 1, a legal ball
  --   17  1        4                                          ...taken back by
  --   18  1        void of 17                                 nothing
  --   19  0        1, written last                            the first innings' — the second is still current
  --
  -- The second innings reads 14/1 off 3. Before db/45 the check expected the
  -- match: every innings' `value` and every row marked W.
  PERFORM _scoring_session_reset(M_HANDOVER);
  PERFORM _as(U_SCORER);
  PERFORM set_config('app.device_id', 'verify-045', true);
  SELECT c.ok, c.epoch INTO v_ok, v_epoch FROM scoring_claim(M_HANDOVER, 'verify-045') c;
  PERFORM _assert(v_ok, 'the scorer could not claim the match the db/45 section scores');
  DECLARE
    B1 uuid := 'aaaaaaaa-0000-0000-0000-000000000006';  -- K Dlamini
    B2 uuid := 'aaaaaaaa-0000-0000-0000-000000000012';  -- J Sithole
    BO uuid := 'bbbbbbbb-0000-0000-0000-000000000002';  -- K Botha
    x record;
    cur0 smallint; cur1 smallint; cur2 smallint; cur3 smallint;
    f0 record; f1 record; f2 record; g record;
    n bigint; n2 bigint;
    old_runs bigint; old_wkts bigint; old_balls bigint;
    v_detail jsonb;
  BEGIN
    PERFORM _as(U_OWNER);
    cur0 := match_current_innings(M_HANDOVER);
    SELECT * INTO f0 FROM innings_score_as_folded(M_HANDOVER, 0::smallint);
    SELECT count(*) INTO n FROM ball_event_live WHERE match_id = M_HANDOVER AND innings <> 0;
    PERFORM _assert(n = 0 AND f0.runs IS NOT NULL,
      format('db/45: the section expects a match scored in its first innings only (%s rows elsewhere, runs %s)', n, f0.runs));

    PERFORM _as(U_SCORER);
    FOR x IN SELECT * FROM (VALUES
        ( 1, 0, 'penalty', NULL,  NULL::text, NULL::int, NULL, '{"runs":5,"toBattingTeam":true,"reason":"ball tampering"}'::jsonb),
        ( 2, 0, 'penalty', NULL,  NULL,       NULL,      NULL, '{"reason":"time wasting"}'::jsonb),
        ( 3, 0, 'penalty', NULL,  NULL,       NULL,      NULL, '{"runs":5,"toBattingTeam":false,"reason":"pitch damage"}'::jsonb),
        ( 4, 0, 'penalty', NULL,  NULL,       3,         NULL, '{"runs":2,"toBattingTeam":true}'::jsonb),
        ( 5, 0, 'retire',  'W',   'retired_out', NULL,   NULL, jsonb_build_object('batter', 'aaaaaaaa-0000-0000-0000-000000000006', 'reason', 'out')),
        ( 6, 0, 'retire',  'W',   'bowled',   NULL,      NULL, jsonb_build_object('batter', 'aaaaaaaa-0000-0000-0000-000000000012', 'reason', 'hurt'))
      ) AS v(k, inn, kind, bt, dis, val, who, pl) ORDER BY k
    LOOP
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value, dismissal, payload)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9700 + x.k, v_epoch, x.inn, U_SCORER, 'verify-045',
              'verify:045:' || x.k, 9700 + x.k, now(), x.kind, x.bt, x.val, x.dis, x.pl);
    END LOOP;
    PERFORM _as(U_OWNER);
    cur1 := match_current_innings(M_HANDOVER);
    SELECT * INTO f1 FROM innings_score_as_folded(M_HANDOVER, 0::smallint);

    -- The second innings, then a first-innings ball at the highest seq.
    PERFORM _as(U_SCORER);
    FOR x IN SELECT * FROM (VALUES
        (10, 1, 'innings_start', NULL, NULL::text, NULL::int, NULL, '{"battingTeam":"Kearsney","bowlingTeam":"Hilton U16B","overs":20}'::jsonb),
        (11, 1, 'ball', 'run', NULL,     6,    'b1', '{}'::jsonb),
        (12, 1, 'ball', 'W',   'bowled', 0,    'b1', '{}'::jsonb),
        (13, 1, 'ball', 'Nb',  NULL,     1,    'b2', '{}'::jsonb),
        (14, 1, 'penalty', NULL, NULL,   NULL, NULL, '{"runs":5,"toBattingTeam":true}'::jsonb),
        (15, 1, 'penalty', NULL, NULL,   NULL, NULL, '{"runs":5,"toBattingTeam":false}'::jsonb),
        (16, 1, 'ball', 'LB',  NULL,     1,    'b2', '{}'::jsonb),
        (17, 1, 'ball', 'run', NULL,     4,    'b2', '{}'::jsonb),
        (18, 1, 'void', NULL,  NULL,     NULL, NULL, '{"target":"verify:045:17"}'::jsonb)
      ) AS v(k, inn, kind, bt, dis, val, who, pl) ORDER BY k
    LOOP
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value,
                              striker_id, bowler_id, dismissal, payload)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9700 + x.k, v_epoch, x.inn, U_SCORER, 'verify-045',
              'verify:045:' || x.k, 9700 + x.k, now(), x.kind, x.bt, x.val,
              CASE x.who WHEN 'b1' THEN B1 WHEN 'b2' THEN B2 END,
              CASE WHEN x.kind = 'ball' THEN BO END, x.dis, x.pl);
    END LOOP;
    PERFORM _as(U_OWNER);
    cur2 := match_current_innings(M_HANDOVER);
    PERFORM _as(U_SCORER);
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, ball_type, value, striker_id, bowler_id)
    VALUES (M_HANDOVER, match_school(M_HANDOVER), 9719, v_epoch, 0, U_SCORER, 'verify-045',
            'verify:045:19', 9719, now(), 'ball', 'run', 1, B1, BO);
    PERFORM _as(U_OWNER);
    cur3 := match_current_innings(M_HANDOVER);
    SELECT * INTO f2 FROM innings_score_as_folded(M_HANDOVER, 0::smallint);
    SELECT * INTO g  FROM innings_score_as_folded(M_HANDOVER, 1::smallint);
    -- What the check used to expect: the match, by `value`, every row marked W.
    SELECT sum(CASE WHEN b.ball_type IN ('Wd','Nb') THEN 1 + coalesce(b.value,0) ELSE coalesce(b.value,0) END),
           sum(CASE WHEN ball_wicket_stands(b.match_id, b.innings, b.seq, b.kind, b.ball_type, b.dismissal) THEN 1 ELSE 0 END),
           sum(CASE WHEN b.kind = 'ball' AND b.ball_type NOT IN ('Wd','Nb') THEN 1 ELSE 0 END)
      INTO old_runs, old_wkts, old_balls
      FROM ball_event_live b WHERE b.match_id = M_HANDOVER;

    -- (current) the innings the log has reached — not the innings of its last seq
    PERFORM _assert(cur0 = 0 AND cur1 = 0 AND cur2 = 1 AND cur3 = 1,
      format('db/45 (current): the current innings read %s, %s, %s, %s — expected 0 before the second innings, 0 after first-innings penalties, '
             || '1 once it opened, and still 1 after a first-innings ball written at a later seq', cur0, cur1, cur2, cur3));
    -- (penalty) the first innings: +5, +5, nothing to the fielding side, +2 not +5, and the late ball's 1
    PERFORM _assert(f1.runs - f0.runs = 12 AND f2.runs - f0.runs = 13 AND f2.legal_balls - f0.legal_balls = 1,
      format('db/45 (penalty): the first innings'' runs moved by %s and %s (expected 12 and 13) and its legal balls by %s (expected 1) — '
             || 'penalty runs are `runs ?? 5` to the batting side, nothing to the fielding side, and a row''s `value` counts on a delivery only',
             f1.runs - f0.runs, f2.runs - f0.runs, f2.legal_balls - f0.legal_balls));
    -- (wickets) a retirement the fold reads as a dismissal is a wicket; a W marker on any other retirement is not
    PERFORM _assert(f1.wickets - f0.wickets = 1,
      format('db/45 (wickets): the first innings'' wickets moved by %s for one retired out and one retirement marked W with method bowled, expected 1',
             f1.wickets - f0.wickets));
    -- (innings) the second innings alone, as the fold totals it
    PERFORM _assert(row(g.runs, g.wickets, g.legal_balls)::text = '(14,1,3)',
      format('db/45 (innings): the second innings reads %s, expected (14,1,3) — 6, a wicket, a no-ball and its run, five penalty runs, a leg bye; '
             || 'the fielding side''s penalty and a voided four are nothing', row(g.runs, g.wickets, g.legal_balls)::text));

    -- (nobody) The helpers read as their caller: an unidentified session and
    --          another school's office read nothing of this Hilton fixture.
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM innings_score_as_folded(M_HANDOVER, 1::smallint) f
     WHERE f.runs <> 0 OR f.wickets <> 0 OR f.legal_balls <> 0;
    n := n + match_current_innings(M_HANDOVER);
    PERFORM _as(U_WES_ADM);
    SELECT count(*) INTO n2 FROM innings_score_as_folded(M_HANDOVER, 1::smallint) f
     WHERE f.runs <> 0 OR f.wickets <> 0 OR f.legal_balls <> 0;
    n2 := n2 + match_current_innings(M_HANDOVER);
    -- (nobody)
    PERFORM _assert(n = 0 AND n2 = 0,
      format('db/45 (nobody): an unidentified session read %s and the Westville administrator %s of a Hilton fixture''s innings through the helpers, expected 0 and 0',
             n, n2));

    -- The pen goes to Sarah in the second innings.
    PERFORM _as(U_SCORER);
    SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-045', 0, false) a;
    PERFORM _assert(v_code IS NOT NULL, 'db/45: the scorer could not arm a handover in the second innings');
    PERFORM _as(U_SARAH);
    SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-045-b', v_code) h;
    PERFORM _assert(v_ok, 'db/45: Sarah could not claim the handover in the second innings');

    -- (verify-expects) a wrong reading answers with this innings' figures
    SELECT v.ok, v.exp_runs, v.exp_wkts, v.exp_balls INTO v_ok, v_runs, v_wkts, v_balls
      FROM scoring_verify_takeover(M_HANDOVER, 'verify-045-b', -1, -1, -1) v;
    PERFORM _assert(NOT v_ok AND row(v_runs, v_wkts, v_balls)::text = '(14,1,3)',
      format('db/45 (verify-expects): a wrong reading was answered with %s, expected this innings'' (14,1,3)', row(v_runs, v_wkts, v_balls)::text));
    -- (audit) and the refusal is on the record, naming the innings
    PERFORM _as(U_OWNER);
    SELECT a.detail INTO v_detail FROM scoring_audit a
     WHERE a.match_id = M_HANDOVER AND a.event = 'handover_verify_failed' ORDER BY a.id DESC LIMIT 1;
    PERFORM _assert(v_detail->>'innings' = '1' AND v_detail->'expected'->>'runs' = '14',
      format('db/45 (audit): the refusal''s audit detail is %s, expected the second innings and its 14 runs', coalesce(v_detail::text, 'no row')));
    -- (verify-old) the match's totals, which the check used to want, are refused
    PERFORM _as(U_SARAH);
    SELECT v.ok INTO v_ok FROM scoring_verify_takeover(M_HANDOVER, 'verify-045-b', old_runs::int, old_wkts::int, old_balls::int) v;
    PERFORM _assert(NOT v_ok AND row(old_runs, old_wkts, old_balls)::text <> '(14,1,3)',
      format('db/45 (verify-old): the match''s totals %s verified', row(old_runs, old_wkts, old_balls)::text));
    -- (verify-penalty) this innings without its penalty runs is refused
    SELECT v.ok INTO v_ok FROM scoring_verify_takeover(M_HANDOVER, 'verify-045-b', 9, 1, 3) v;
    PERFORM _assert(NOT v_ok, 'db/45 (verify-penalty): the second innings without its five penalty runs verified');
    -- (verify-ok) the fold's figures hand the pen over
    SELECT v.ok, v.epoch INTO v_ok, n FROM scoring_verify_takeover(M_HANDOVER, 'verify-045-b', 14, 1, 3) v;
    PERFORM _assert(v_ok AND n = v_epoch + 1,
      format('db/45 (verify-ok): the second innings'' 14/1 off 3 did not verify (ok %s, epoch %s after %s)', v_ok, n, v_epoch));
  END;
  PERFORM set_config('app.device_id', '', true);
  PERFORM set_config('app.user_id', '', true);

  -- ── 24. The opposition window is five days (SCRBRD-091, db/46) ──────
  -- Kameel, 2026-09-25: "14 days seems excessive; 5-7 days would be more
  -- than appropriate". Five, and one window for everything the dossier opens,
  -- squad and figures alike. The edge from both sides, read by a coach of a
  -- side actually playing (the Westville 1XI, the away side): four days out
  -- the window is open and the squad reads; six days out it is not yet open,
  -- says when it will be, and discloses nothing — no squad, no count. The
  -- number itself is asserted last, so a window moved off five goes red on
  -- the edge it moved, not only on the constant.
  DECLARE
    U_WES_COACH uuid := '88888888-0000-0000-0000-00000000001a';  -- S Pillay, coach, Westville 1XI
    M_FOUR uuid; M_SIX uuid;
    s4 record; s6 record; c6 record;
    q4 int; q6 int;
  BEGIN
    M_FOUR := _opposition_fixture(4);
    M_SIX  := _opposition_fixture(6);
    PERFORM _as(U_WES_COACH);
    SELECT s.open, s.reason, s.my_school INTO s4 FROM opposition_side(M_FOUR) s;
    SELECT s.open, s.reason, s.opens_at, s.closes_at INTO s6 FROM opposition_side(M_SIX) s;
    SELECT count(*) INTO q4 FROM opposition_squad(M_FOUR);
    SELECT count(*) INTO q6 FROM opposition_squad(M_SIX);
    SELECT c.open, c.reason, c.games_analysed, c.deliveries_analysed INTO c6 FROM opposition_context(M_SIX) c;

    -- (four) inside the window: open, and their squad reads
    PERFORM _assert(s4.open AND s4.reason = 'open' AND s4.my_school = WES AND q4 > 0,
      format('db/46 (four): a fixture four days out answered open %s, reason %s, %s squad rows — expected open, with Hilton''s 1XI to read',
             s4.open, s4.reason, q4));
    -- (six) outside it: not yet open, saying when, and nothing read
    PERFORM _assert(s6.open = false AND s6.reason = 'not_yet_open' AND s6.opens_at > now() AND q6 = 0
                    AND c6.open = false AND c6.reason = 'not_yet_open'
                    AND c6.games_analysed IS NULL AND c6.deliveries_analysed IS NULL,
      format('db/46 (six): a fixture six days out answered open %s, reason %s, opening %s, %s squad rows, context %s — '
             || 'expected not_yet_open, opening at a time still to come, no squad and no counts', s6.open, s6.reason, s6.opens_at, q6, c6::text));
    -- (value) five days, the decision
    PERFORM _assert(opposition_window_days() = 5,
      format('db/46 (value): opposition_window_days() answers %s, expected 5', opposition_window_days()));
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 25. The records the public-data rule reads (SCRBRD-083, db/47) ──
  -- docs/policy/PUBLIC_DATA.md §4 and §6 step 2. Every write goes through a
  -- door that checks its own authority, and each refusal below is asserted to
  -- have left nothing behind (counted past RLS). What a stranger's page will
  -- read, public_name_facts(), is asserted to carry the three facts the rule
  -- needs and never a date of birth, a reason or a guardian.
  DECLARE
    U_WHIT    uuid := '88888888-0000-0000-0000-000000000010';  -- H Whitfield, guardian of James
    U_BEKKER  uuid := '88888888-0000-0000-0000-000000000011';  -- A Bekker, guardian of T Bekker
    U_WES_PUB uuid := '88888888-0000-0000-0000-00000000047a';  -- sportsadmin, Westville (above)
    P_JW      uuid := 'aaaaaaaa-0000-0000-0000-000000000001';  -- James Whitfield, 1XI, sixteen
    P_2XI     uuid := 'aaaaaaaa-0000-0000-0000-00000000044a';  -- V44 Opener, 2XI (section 22)
    M_47      uuid := '77777777-0000-0000-0000-000000000047';  -- Hilton 1XI v Westville 1XI
    C_KZN     uuid := '99999999-0000-0000-0000-000000000001';  -- the shared league, no organiser
    V         text := 'public-names-2026-09';
    v_today   text := to_char(sa_today(), 'YYYY-MM-DD');
    v_facts   jsonb;
    v_row     public_name_consent;
    v_grp     text;
    v_born    date;
    v_raised  boolean;
    who       uuid;
  BEGIN
    -- ── Consent: who may give it ──
    -- (guardian) a verified guardian consents for his own child
    PERFORM _as(U_WHIT);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, true, V) s;
    PERFORM _assert(v_ok, format('db/47 (guardian): a verified guardian could not consent for his own child (%s)', v_reason));
    v_row := _consent_last(P_JW);
    PERFORM _assert(v_row.given_by = 'guardian' AND v_row.given_on = sa_today() AND v_row.ended_on IS NULL
                    AND v_row.recorded_by = U_WHIT AND v_row.form_name IS NULL,
      format('db/47 (guardian): the record is not his, today''s and open: %s', row(v_row.given_by, v_row.given_on, v_row.ended_on, v_row.recorded_by)::text));
    -- ...and for the 2XI boy he is also guardian of
    PERFORM _link_47(P_2XI);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_2XI, true, V) s;
    PERFORM _assert(v_ok, format('db/47 (guardian-2): a verified guardian could not consent for his second child (%s)', v_reason));
    -- (other-child) ...and cannot write another child's
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_OTHER, true, V) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND _consent_rows(P_OTHER) = 0,
      format('db/47 (other-child): a guardian of one child wrote another''s consent (ok %s, %s, %s rows)', v_ok, v_reason, _consent_rows(P_OTHER)));
    -- ...nor pass himself off as the office to do it
    SELECT s.ok, s.reason INTO v_ok, v_reason
      FROM public_name_consent_set(P_OTHER, true, V, U_BEKKER, 'Admission form', current_date) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND _consent_rows(P_OTHER) = 0,
      format('db/47 (other-child-office): a guardian recorded another family''s consent as the office (ok %s, %s)', v_ok, v_reason));

    -- (minor) a pupil under eighteen cannot give his own
    PERFORM _as(U_SELF);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_INJURED, true, V) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_eighteen' AND _consent_rows(P_INJURED) = 0,
      format('db/47 (minor): a pupil of sixteen gave his own consent (ok %s, %s, %s rows)', v_ok, v_reason, _consent_rows(P_INJURED)));
    -- (eighteen) ...and can from his birthday (C6): his date of birth moved
    -- back, as the owner, so R Pillay is nineteen
    v_born := _born_of(P_INJURED);
    PERFORM _set_born(P_INJURED, (current_date - interval '19 years')::date);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_INJURED, true, V) s;
    PERFORM _assert(v_ok, format('db/47 (eighteen): a pupil of nineteen could not give his own consent (%s)', v_reason));
    v_facts := public_name_facts(P_INJURED);
    PERFORM _assert(v_facts -> 'consents' @> jsonb_build_array(jsonb_build_object('by', 'pupil', 'competent', true, 'givenOn', v_today)),
      format('db/47 (eighteen): his own consent is not in the facts as competent: %s', v_facts));
    -- (competent-live) competence is worked out on every read, from the
    -- record as it stands: put his birthday back and the same consent is one
    -- a sixteen-year-old gave, which counts for nothing
    PERFORM _set_born(P_INJURED, v_born);
    v_facts := public_name_facts(P_INJURED);
    PERFORM _assert(v_facts -> 'consents' @> jsonb_build_array(jsonb_build_object('by', 'pupil', 'competent', false)),
      format('db/47 (competent-live): a consent given "at eighteen" by a boy the record says is sixteen still counts: %s', v_facts));

    -- ── The office, from its own forms (C1) ──
    PERFORM _as(U_REGISTRAR);
    -- (form-required) a yes from the office names the form
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_OTHER, true, V, U_BEKKER) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'form_required' AND _consent_rows(P_OTHER) = 0,
      format('db/47 (form-required): the office recorded a consent naming no form (ok %s, %s)', v_ok, v_reason));
    -- (form-future) ...signed on a day that has happened
    SELECT s.ok, s.reason INTO v_ok, v_reason
      FROM public_name_consent_set(P_OTHER, true, V, U_BEKKER, 'Admission form 2026', current_date + 30) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'form_in_future' AND _consent_rows(P_OTHER) = 0,
      format('db/47 (form-future): the office recorded a form dated next month (ok %s, %s)', v_ok, v_reason));
    -- (office) ...and records it, on the guardian's behalf, form and date named
    SELECT s.ok, s.reason INTO v_ok, v_reason
      FROM public_name_consent_set(P_OTHER, true, V, U_BEKKER, 'Admission form 2026', current_date - 30) s;
    v_row := _consent_last(P_OTHER);
    PERFORM _assert(v_ok AND v_row.given_by = 'guardian' AND v_row.form_name = 'Admission form 2026'
                    AND v_row.form_date = current_date - 30 AND v_row.recorded_by = U_REGISTRAR
                    AND v_row.given_on = sa_today(),
      format('db/47 (office): the office could not record a guardian''s consent from its form (ok %s, %s, %s)',
             v_ok, v_reason, row(v_row.given_by, v_row.form_name, v_row.form_date, v_row.recorded_by, v_row.given_on)::text));
    -- (office-no-link) ...but only for a guardian with a verified link to him
    SELECT s.ok, s.reason INTO v_ok, v_reason
      FROM public_name_consent_set(P_OTHER, true, V, U_WHIT, 'Admission form 2026', current_date) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'no_verified_link',
      format('db/47 (office-no-link): the office recorded a consent from somebody who is not his guardian (ok %s, %s)', v_ok, v_reason));
    -- (other-office) another school's office cannot
    PERFORM _as(U_WES_ADM);
    SELECT s.ok, s.reason INTO v_ok, v_reason
      FROM public_name_consent_set(P_JW, false, V, U_WHIT) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND _consent_open_rows(P_JW) = 1,
      format('db/47 (other-office): Westville''s office withdrew a Hilton child''s consent (ok %s, %s)', v_ok, v_reason));
    -- (coach) nor can a coach, either way in
    PERFORM _as(U_COACH2);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, false, V, U_WHIT) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('db/47 (coach): a coach recorded a guardian''s answer (ok %s, %s)', v_ok, v_reason));
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, true, V) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('db/47 (coach): a coach consented for a boy he is no guardian of (ok %s, %s)', v_ok, v_reason));
    -- (direct) the application has no way to write the table but the door
    -- (a write that gets past the privilege and fails on anything else has
    -- still got through the door, and is reported as such)
    PERFORM _as(U_REGISTRAR);
    v_raised := false;
    BEGIN
      INSERT INTO public_name_consent (player_id, given_by, giver_assignment_id, giver_link_id, version, given_on, recorded_by)
      SELECT P_U16B, 'guardian', g.assignment_id, g.id, V, sa_today(), U_REGISTRAR
        FROM assignment_subject g WHERE g.player_id = P_U16B LIMIT 1;
    EXCEPTION WHEN insufficient_privilege THEN v_raised := true;
              WHEN OTHERS THEN v_raised := false;
    END;
    PERFORM _assert(v_raised AND _consent_rows(P_U16B) = 0, 'db/47 (direct): the office wrote public_name_consent without its door');

    -- ── Who reads a consent record ──
    PERFORM _as(U_WHIT);
    SELECT count(*) INTO n FROM public_name_consent;
    PERFORM _assert(n = 2, format('db/47 (read-own): a guardian reads %s consent records, expected his own two', n));
    PERFORM _as(U_REGISTRAR);
    SELECT count(*) INTO n FROM public_name_consent WHERE player_id IN (P_JW, P_2XI, P_OTHER, P_INJURED);
    PERFORM _assert(n = 4, format('db/47 (read-office): the office reads %s of the school''s 4 consent records', n));
    -- (read-coach) not even the record about a boy in the side he coaches
    PERFORM _as(U_COACH2);
    SELECT count(*) INTO n FROM public_name_consent;
    PERFORM _assert(n = 0 AND _consent_rows(P_2XI) = 1,
      format('db/47 (read-coach): the 2XI coach reads %s consent records — they name a child''s guardian', n));

    -- ── A "no" is immediate, and ends a record rather than deleting it (C3) ──
    PERFORM _as(U_WHIT);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, false, V) s;
    v_facts := public_name_facts(P_JW);
    PERFORM _assert(v_ok AND _consent_rows(P_JW) = 1 AND _consent_open_rows(P_JW) = 0
                    AND v_facts -> 'consents' = jsonb_build_array(jsonb_build_object(
                          'by', 'guardian', 'competent', true, 'givenOn', v_today, 'endedOn', v_today)),
      format('db/47 (withdraw): a withdrawal did not end the one record today (ok %s, %s rows, facts %s)', v_ok, _consent_rows(P_JW), v_facts));
    -- (same-day) consenting again the same day names him again: the facts
    -- carry his latest act, not a tie with his own withdrawal
    SELECT s.ok INTO v_ok FROM public_name_consent_set(P_JW, true, V) s;
    v_facts := public_name_facts(P_JW);
    PERFORM _assert(v_ok AND _consent_rows(P_JW) = 2 AND jsonb_array_length(v_facts -> 'consents') = 1
                    AND v_facts #>> '{consents,0,endedOn}' IS NULL,
      format('db/47 (same-day): a same-day consent after a withdrawal is not his latest act (%s rows, facts %s)', _consent_rows(P_JW), v_facts));
    -- (again) a second yes to the same wording is refused, not duplicated
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, true, V) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'already_given' AND _consent_open_rows(P_JW) = 1,
      format('db/47 (again): a repeated consent was written (ok %s, %s)', v_ok, v_reason));
    -- (adult) a guardian answers for a minor: James made nineteen, as the
    -- owner, with his guardian's link still open (he is at school, db/62).
    -- Under option C (SCRBRD-083 §6.3, db/62) the guardian's "yes" is
    -- refused for the reason, and the consent given today is not a competent
    -- one. A guardian's "no" is theirs to give only while he is at school:
    -- with his membership closed and the link not yet dated (the close is
    -- deferred to the end of the transaction), the old link still says live
    -- and the "no" is refused as before. Section 40 proves the "no" a
    -- guardian may give. Made sixteen again, and back in his side, the
    -- consent is competent again.
    v_born := _born_of(P_JW);
    PERFORM _set_born(P_JW, (current_date - interval '19 years')::date);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, true, V || '-adult') s;
    v_facts := public_name_facts(P_JW);
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself' AND _consent_open_rows(P_JW) = 1
                    AND v_facts #> '{consents,0,competent}' = 'false'::jsonb,
      format('db/47 (adult): a guardian named, or counted for, a boy of nineteen (ok %s, %s, facts %s)', v_ok, v_reason, v_facts));
    PERFORM _v60_leave(P_JW);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, false, V) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'player_is_an_adult' AND _consent_open_rows(P_JW) = 1,
      format('db/47 (adult): a guardian answered for a boy of nineteen who is not at school (ok %s, %s)', v_ok, v_reason));
    PERFORM _v60_rejoin(P_JW);
    PERFORM _set_born(P_JW, v_born);
    PERFORM _assert(public_name_facts(P_JW) #> '{consents,0,competent}' = 'true'::jsonb,
      'db/47 (adult): the consent is not competent again once he is sixteen');
    -- (refused) a "no" with nothing open is a record that ends the day it begins
    PERFORM _as(U_SARAH);
    SELECT s.ok INTO v_ok FROM public_name_consent_set(P_U16B, false, V) s;
    v_row := _consent_last(P_U16B);
    PERFORM _assert(v_ok AND v_row.end_reason = 'refused' AND v_row.given_on = sa_today() AND v_row.ended_on = sa_today(),
      format('db/47 (refused): a refusal is not a record ending the day it begins: %s', row(v_row.end_reason, v_row.given_on, v_row.ended_on)::text));

    -- ── The never-public mark (C5) ──
    -- (mark-coach) a coach cannot set one
    PERFORM _as(U_COACH2);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM player_never_public_set(P_2XI, 'verify-047: coach') s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND _mark_rows(P_2XI) = 0,
      format('db/47 (mark-coach): a coach set a never-public mark (ok %s, %s)', v_ok, v_reason));
    -- (mark-dos) the director of sport can, with a reason
    PERFORM _as(U_SARAH);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM player_never_public_set(P_2XI, '   ') s;
    PERFORM _assert(NOT v_ok AND v_reason = 'no_reason', format('db/47 (mark-reason): a mark with no reason was set (%s)', v_reason));
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM player_never_public_set(P_2XI, 'verify-047: a protection order') s;
    PERFORM _assert(v_ok, format('db/47 (mark-dos): the director of sport could not set a mark (%s)', v_reason));
    v_facts := public_name_facts(P_2XI);
    PERFORM _assert((v_facts ->> 'neverPublic')::boolean,
      format('db/47 (mark-facts): the facts do not carry the mark: %s', v_facts));
    -- (reason-coach) the reason is unreadable by the coach of that boy's own side
    PERFORM _as(U_COACH2);
    SELECT count(*) INTO n FROM player_never_public;
    PERFORM _assert(n = 0, format('db/47 (reason-coach): the 2XI coach reads %s never-public mark(s), reason and all', n));
    -- ...or by a guardian, or by another school's office
    FOREACH who IN ARRAY ARRAY[U_WHIT, U_WES_ADM, U_WES_PUB, U_WATCHER] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO n FROM player_never_public;
      PERFORM _assert(n = 0, format('db/47 (reason-others): %s reads %s never-public mark(s)', who, n));
    END LOOP;
    -- ...and readable by the people who set such marks
    FOREACH who IN ARRAY ARRAY[U_SARAH, U_REGISTRAR, U_HEAD_M] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO n FROM player_never_public WHERE player_id = P_2XI AND reason = 'verify-047: a protection order';
      PERFORM _assert(n = 1, format('db/47 (reason-setters): %s, who may set a mark, cannot read this one', who));
    END LOOP;
    -- (facts-clean) the facts carry the three keys, the consents their four,
    -- and never the reason, a date of birth or a guardian
    PERFORM set_config('app.user_id', '', true);
    FOREACH who IN ARRAY ARRAY[P_2XI, P_JW, P_INJURED, P_OTHER, P_U16B] LOOP
      v_facts := public_name_facts(who);
      PERFORM _assert(
        (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v_facts) k) = ARRAY['consents', 'namesOff', 'neverPublic']
        AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_facts -> 'consents') c
                         WHERE (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(c) k)
                               <> ARRAY['by', 'competent', 'endedOn', 'givenOn'])
        AND v_facts::text NOT LIKE '%protection order%'
        AND v_facts::text NOT LIKE ('%' || to_char(_born_of(who), 'YYYY-MM-DD') || '%')
        AND v_facts::text !~* ('born|reason|guardian_|link|form|recorded|' || U_WHIT::text || '|' || U_BEKKER::text),
        format('db/47 (facts-clean): the facts about %s carry more than the rule needs: %s', who, v_facts));
    END LOOP;

    -- ── Names off, per age group (C4) ──
    PERFORM _as(U_COACH2);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_names_off_set(HIL, 'open', true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('db/47 (names-coach): a coach switched names off for an age group (ok %s, %s)', v_ok, v_reason));
    -- K Dlamini: U16B by registration, younger by birth. 'open' switched off
    -- names him when he plays in his own sides and not when he plays up into
    -- the 1st XI (the side's age group, §5a).
    v_grp := birth_age_group(_born_of(P_U16B));
    PERFORM _assert(v_grp NOT IN ('U16', 'open'), format('db/47: K Dlamini''s own age group is %s — the fixture needs one that is neither his side''s nor open', v_grp));
    PERFORM _as(U_SARAH);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_names_off_set(HIL, 'open', true) s;
    PERFORM _assert(v_ok, format('db/47 (names-dos): the director of sport could not switch names off (%s)', v_reason));
    PERFORM _assert(NOT (public_name_facts(P_U16B) ->> 'namesOff')::boolean
                    AND NOT (public_name_facts(P_U16B, 'U16B') ->> 'namesOff')::boolean,
      'db/47 (names-own): switching the open age group off unnamed a boy playing in his own U16B');
    PERFORM _assert((public_name_facts(P_U16B, '1XI') ->> 'namesOff')::boolean,
      'db/47 (names-side): a boy playing up into the 1st XI was named with the open age group switched off');
    -- (names-birth) his own age group by birth holds him back in any side
    SELECT s.ok INTO v_ok FROM public_names_off_set(HIL, v_grp, true) s;
    PERFORM _assert(v_ok AND (public_name_facts(P_U16B, 'U16B') ->> 'namesOff')::boolean,
      format('db/47 (names-birth): %s switched off did not hold back a %s boy playing U16B', v_grp, v_grp));
    -- (names-back) switched back on, the switch is off again
    SELECT s.ok INTO v_ok FROM public_names_off_set(HIL, v_grp, false) s;
    PERFORM _assert(v_ok AND NOT (public_name_facts(P_U16B, 'U16B') ->> 'namesOff')::boolean,
      'db/47 (names-back): switching an age group back did not name him again');
    -- (names-school) Westville's switches are not Hilton's: D Mkhize is named
    PERFORM _assert(NOT (public_name_facts(P_WES, '1XI') ->> 'namesOff')::boolean,
      'db/47 (names-school): Hilton''s open switch held back a Westville boy');
    PERFORM _as(U_COACH2);
    SELECT count(*) INTO n FROM public_names_off WHERE school_id = HIL;
    PERFORM _assert(n = 2, format('db/47 (names-read): a coach reads %s of his school''s 2 names-off settings', n));

    -- ── Publishing, side by side (L1, L5) ──
    -- (publish-default) nothing is published until somebody publishes it
    PERFORM _assert(NOT fixture_side_published(M_47, 'home') AND NOT fixture_side_published(M_47, 'away')
                    AND NOT competition_published(C_KZN),
      'db/47 (publish-default): a fixture or competition nobody published reads as published');
    PERFORM _assert((SELECT column_default FROM information_schema.columns
                      WHERE table_schema = 'public' AND table_name = 'fixture_publication' AND column_name = 'published') = 'false'
                    AND (SELECT column_default FROM information_schema.columns
                      WHERE table_schema = 'public' AND table_name = 'competition_publication' AND column_name = 'published') = 'false',
      'db/47 (publish-default): a publication row does not default to unpublished');
    -- (away-home) the away school cannot publish the home side...
    PERFORM _as(U_WES_PUB);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(M_47, 'home', true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND NOT fixture_side_published(M_47, 'home'),
      format('db/47 (away-home): Westville published Hilton''s side (ok %s, %s)', v_ok, v_reason));
    -- (away-own) ...and publishes its own
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(M_47, 'away', true) s;
    PERFORM _assert(v_ok AND fixture_side_published(M_47, 'away') AND NOT fixture_side_published(M_47, 'home'),
      format('db/47 (away-own): Westville could not publish its own side, or doing so published Hilton''s (ok %s, %s)', v_ok, v_reason));
    -- (home-away) the home school cannot publish the away side either
    PERFORM _as(U_SARAH);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(M_47, 'away', false) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND fixture_side_published(M_47, 'away'),
      format('db/47 (home-away): Hilton unpublished Westville''s side (ok %s, %s)', v_ok, v_reason));
    SELECT s.ok INTO v_ok FROM fixture_publish(M_47, 'home', true) s;
    PERFORM _assert(v_ok AND fixture_side_published(M_47, 'home'), 'db/47 (home-own): Hilton could not publish its own side');
    -- (off-platform) a side whose school is not on the platform has nobody to publish it
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(M_DUTY, 'away', true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'side_not_on_platform',
      format('db/47 (off-platform): a side with no school on the platform was published (ok %s, %s)', v_ok, v_reason));
    -- (publish-coach) a coach and the office do not publish
    FOREACH who IN ARRAY ARRAY[U_COACH2, U_REGISTRAR] LOOP
      PERFORM _as(who);
      SELECT s.ok INTO v_ok FROM fixture_publish(M_47, 'home', false) s;
      PERFORM _assert(NOT v_ok AND fixture_side_published(M_47, 'home'),
        format('db/47 (publish-coach): %s, who holds no broadcast.publish, unpublished a side', who));
    END LOOP;
    -- (competition) the league's page: its administrator, and nobody at a school
    FOREACH who IN ARRAY ARRAY[U_SARAH, U_COACH2, U_REGISTRAR] LOOP
      PERFORM _as(who);
      SELECT s.ok INTO v_ok FROM competition_publish(C_KZN, true) s;
      PERFORM _assert(NOT v_ok AND NOT competition_published(C_KZN),
        format('db/47 (competition-others): %s published a league it does not run', who));
    END LOOP;
    PERFORM _as(U_LEAGUE);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM competition_publish(C_KZN, true) s;
    PERFORM _assert(v_ok AND competition_published(C_KZN),
      format('db/47 (competition): the league administrator could not publish its page (%s)', v_reason));
    -- (publication-read) each school reads its own side's row
    PERFORM _as(U_WES_PUB);
    SELECT count(*) INTO n FROM fixture_publication WHERE match_id = M_47;
    PERFORM _assert(n = 1, format('db/47 (publication-read): Westville reads %s publication rows of the fixture, expected its own', n));

    -- ── The mark ends; the row stays ──
    PERFORM _as(U_COACH2);
    SELECT s.ok INTO v_ok FROM player_never_public_end(P_2XI) s;
    PERFORM _assert(NOT v_ok AND (public_name_facts(P_2XI) ->> 'neverPublic')::boolean,
      'db/47 (end-coach): a coach ended a never-public mark');
    PERFORM _as(U_HEAD_M);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM player_never_public_end(P_2XI) s;
    PERFORM _assert(v_ok AND NOT (public_name_facts(P_2XI) ->> 'neverPublic')::boolean AND _mark_rows(P_2XI) = 1,
      format('db/47 (end): the principal''s ending did not lift the mark and keep its row (ok %s, %s, %s rows)', v_ok, v_reason, _mark_rows(P_2XI)));

    -- ── Signed out: nothing (§1 "public" means signed out) ──
    PERFORM set_config('app.user_id', '', true);
    FOREACH v_grp IN ARRAY ARRAY['public_name_consent', 'player_never_public', 'public_names_off',
                                 'fixture_publication', 'competition_publication'] LOOP
      EXECUTE format('SELECT count(*) FROM %I', v_grp) INTO n;
      PERFORM _assert(n = 0 AND _count_rows(v_grp) > 0,
        format('db/47 (signed-out): an unauthenticated session reads %s of %s''s %s rows', n, v_grp, _count_rows(v_grp)));
    END LOOP;
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set(P_JW, false, V) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_signed_in',
      format('db/47 (signed-out): an unauthenticated session answered for a child (%s)', v_reason));
    SELECT s.ok INTO v_ok FROM fixture_publish(M_47, 'home', false) s;
    PERFORM _assert(NOT v_ok, 'db/47 (signed-out): an unauthenticated session unpublished a fixture');
    SELECT s.ok INTO v_ok FROM player_never_public_set(P_JW, 'signed out') s;
    PERFORM _assert(NOT v_ok, 'db/47 (signed-out): an unauthenticated session set a never-public mark');
  END;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.device_id', '', true);

  -- ── 26. Penalty runs to the fielding side, in every total (SCRBRD-094, db/48) ──
  -- Law 41.17.4, as the fold credits it: five to the fielding side go to its
  -- most recently completed innings, or, if it has not batted, to its next,
  -- which opens on them; a chase's target rises with an award made after it
  -- was set, unless the umpires typed it. On §23's match, which it leaves at
  -- 14/1 off 3 in the second innings (Kearsney), with a five to the fielding
  -- side — Hilton U16B, who have no innings yet — in it (row 15), and one in
  -- the first innings, whose innings_start was never written (row 3: an
  -- innings with no side, so nobody's). The pen goes back to the scorer, then:
  --
  --    k  innings  row                                        the fold
  --   20  2        innings_start, Hilton U16B bat             row 15's five: they open on 5
  --   21  2        3                                          8/0 off 1
  --   22  2        penalty, 5 to the fielding side            Kearsney's second innings: 14 → 19
  --   23  3        innings_start, Kearsney bat, target 20     the target 20
  --   24  3        penalty, 5 to the fielding side            Hilton's innings 2: 13; the target 25
  --   25  3        revision, target 40                        the umpires' 40
  --   26  3        penalty, no runs named, to the fielding    Hilton's innings 2: 18; the target stays 40
  --   27  3        2                                          2/0 off 1
  --
  -- A handover in the third innings expects the carried five. Each assertion
  -- was run once, alone, with db/48 broken the way its label says, and failed
  -- for that reason:
  --
  --   (last)     penalty_credit_as_folded() never crediting an earlier innings
  --   (next)     ...never crediting a later one
  --   (live)     match_live_score without the batting side's penalties
  --   (handover) innings_score_as_folded() without the credit
  --   (target)   innings_target_as_folded() not raised by an award
  --   (typed)    ...raised even when the umpires typed it
  --   (after)    match_live_score without the credit
  --   (nobody)   the helpers as SECURITY DEFINER, search path pinned
  DECLARE
    e int;
    t20 int; t25 int; t40 int;
    g1 record; g2 record; g2b record; g3 record;
    l1 bigint; l2 bigint; l2b bigint;
    c1 int; c2 int;
    v_without boolean; v_with boolean;
    n int; n2 int;
    x record;
  BEGIN
    -- The pen from Sarah (§23's holder) back to the scorer, in the second innings.
    PERFORM _as(U_SARAH);
    SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-045-b', 0, false) a;
    PERFORM _as(U_SCORER);
    SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-048', v_code) h;
    SELECT v.ok, v.epoch INTO v_ok, e FROM scoring_verify_takeover(M_HANDOVER, 'verify-048', 14, 1, 3) v;
    PERFORM _assert(v_ok, 'db/48: the scorer could not take the pen back at 14/1 off 3 in the second innings');
    -- The live score before anything is credited to that innings: its own
    -- deliveries and row 14's five to the batting side.
    PERFORM _as(U_OWNER);
    SELECT l.runs INTO l1 FROM match_live_score l WHERE l.match_id = M_HANDOVER AND l.innings = 1;
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', 'verify-048', true);
    FOR x IN SELECT * FROM (VALUES
        (20, 2, 'innings_start', NULL::text, NULL::int, '{"battingTeam":"Hilton U16B","bowlingTeam":"Kearsney","overs":20}'::jsonb),
        (21, 2, 'ball',    'run', 3,    '{}'::jsonb),
        (22, 2, 'penalty', NULL,  NULL, '{"runs":5,"toBattingTeam":false,"reason":"pitch_damage"}'::jsonb)
      ) AS v(k, inn, kind, bt, val, pl) ORDER BY k
    LOOP
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value, payload)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9700 + x.k, e, x.inn, U_SCORER, 'verify-048',
              'verify:048:' || x.k, 9700 + x.k, now(), x.kind, x.bt, x.val, x.pl);
    END LOOP;
    PERFORM _as(U_OWNER);
    SELECT * INTO g2 FROM innings_score_as_folded(M_HANDOVER, 2::smallint);
    c1 := penalty_credit_as_folded(M_HANDOVER, 1::smallint);
    c2 := penalty_credit_as_folded(M_HANDOVER, 2::smallint);

    -- (last) Kearsney's second innings, completed, is credited the five Hilton's third made
    PERFORM _assert(c1 = 5,
      format('db/48 (last): %s runs credited to Kearsney''s innings, expected 5 — the award Hilton''s innings made to them', c1));
    -- (next) Hilton's third innings is credited the five Kearsney's made while Hilton had not batted
    PERFORM _assert(c2 = 5,
      format('db/48 (next): %s runs credited to Hilton''s innings, expected 5 — the award it opens on', c2));
    -- (live) the live score has the batting side's own penalty runs (row 14), as the fold's total does
    PERFORM _assert(l1 = 14,
      format('db/48 (live): match_live_score read %s for Kearsney''s innings, expected the fold''s 14 — six, a no-ball and its run, five penalty runs, a leg bye', l1));

    -- (handover) The pen to Sarah in the third innings: the carried five are on the board.
    PERFORM _as(U_SCORER);
    SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-048', 0, false) a;
    PERFORM _as(U_SARAH);
    SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-048-b', v_code) h;
    PERFORM _assert(v_ok, 'db/48: Sarah could not claim the handover in the third innings');
    SELECT v.ok INTO v_without FROM scoring_verify_takeover(M_HANDOVER, 'verify-048-b', 3, 0, 1) v;
    SELECT v.ok INTO v_with FROM scoring_verify_takeover(M_HANDOVER, 'verify-048-b', 8, 0, 1) v;
    -- (handover)
    PERFORM _assert(NOT v_without AND v_with AND row(g2.runs, g2.wickets, g2.legal_balls)::text = '(8,0,1)',
      format('db/48 (handover): the third innings reads %s; without its carried five it verified %s, with them %s — expected (8,0,1), refused, then verified',
             row(g2.runs, g2.wickets, g2.legal_balls)::text, v_without, v_with));

    -- And back to the scorer, for the fourth innings: a chase with a target.
    PERFORM _as(U_SARAH);
    SELECT a.code INTO v_code FROM scoring_arm_handover(M_HANDOVER, 'verify-048-b', 0, false) a;
    PERFORM _as(U_SCORER);
    SELECT h.ok INTO v_ok FROM scoring_claim_handover(M_HANDOVER, 'verify-048-c', v_code) h;
    SELECT v.ok, v.epoch INTO v_ok, e FROM scoring_verify_takeover(M_HANDOVER, 'verify-048-c', 8, 0, 1) v;
    PERFORM _assert(v_ok, 'db/48: the scorer could not take the pen back at 8/0 off 1 in the third innings');
    PERFORM set_config('app.device_id', 'verify-048-c', true);
    FOR x IN SELECT * FROM (VALUES
        (23, 3, 'innings_start', NULL::text, NULL::int, '{"battingTeam":"Kearsney","bowlingTeam":"Hilton U16B","overs":20,"target":20}'::jsonb),
        (24, 3, 'penalty',  NULL,  NULL, '{"runs":5,"toBattingTeam":false,"reason":"time_wasting"}'::jsonb),
        (25, 3, 'revision', NULL,  NULL, '{"target":40,"reason":"rain"}'::jsonb),
        (26, 3, 'penalty',  NULL,  NULL, '{"toBattingTeam":false,"reason":"protected_area"}'::jsonb),
        (27, 3, 'ball',     'run', 2,    '{}'::jsonb)
      ) AS v(k, inn, kind, bt, val, pl) ORDER BY k
    LOOP
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value, payload)
      VALUES (M_HANDOVER, match_school(M_HANDOVER), 9700 + x.k, e, x.inn, U_SCORER, 'verify-048-c',
              'verify:048:' || x.k, 9700 + x.k, now(), x.kind, x.bt, x.val, x.pl);
      IF x.k = 23 THEN t20 := innings_target_as_folded(M_HANDOVER, 3::smallint); END IF;
      IF x.k = 24 THEN t25 := innings_target_as_folded(M_HANDOVER, 3::smallint); END IF;
    END LOOP;
    t40 := innings_target_as_folded(M_HANDOVER, 3::smallint);
    PERFORM _as(U_OWNER);
    SELECT * INTO g1 FROM innings_score_as_folded(M_HANDOVER, 1::smallint);
    SELECT * INTO g2b FROM innings_score_as_folded(M_HANDOVER, 2::smallint);
    SELECT * INTO g3 FROM innings_score_as_folded(M_HANDOVER, 3::smallint);
    SELECT l.runs INTO l2 FROM match_live_score l WHERE l.match_id = M_HANDOVER AND l.innings = 1;
    SELECT l.runs INTO l2b FROM match_live_score l WHERE l.match_id = M_HANDOVER AND l.innings = 2;

    -- (target) the chase opened at 20 and an award to the side that set it made it 25
    PERFORM _assert(t20 = 20 AND t25 = 25,
      format('db/48 (target): the fourth innings'' target read %s, then %s — expected 20, then 25 after five to the fielding side', t20, t25));
    -- (typed) the umpires' 40 does not move with a later award
    PERFORM _assert(t40 = 40,
      format('db/48 (typed): the target read %s after the umpires'' 40 and another award, expected 40', t40));
    -- (after) every total, as the fold's: Kearsney's second innings 19 (its 14 and
    --         Hilton's award); Hilton's third 18 (the five it opened on, a 3, and
    --         both awards the chase made); the chase itself neither
    PERFORM _assert(g1.runs = 19 AND l2 = 19 AND g2b.runs = 18 AND l2b = 18
                    AND row(g3.runs, g3.wickets, g3.legal_balls)::text = '(2,0,1)',
      format('db/48 (after): Kearsney''s second innings read %s (live %s), expected 19; Hilton''s third %s (live %s), expected 18; '
             || 'the fourth %s, expected (2,0,1)', g1.runs, l2, g2b.runs, l2b, row(g3.runs, g3.wickets, g3.legal_balls)::text));

    -- (nobody) An unidentified session and another school's office read none of it through the helpers.
    PERFORM set_config('app.user_id', '', true);
    n := coalesce(penalty_credit_as_folded(M_HANDOVER, 2::smallint), -1)
       + coalesce(innings_target_as_folded(M_HANDOVER, 3::smallint), 0);
    PERFORM _as(U_WES_ADM);
    n2 := coalesce(penalty_credit_as_folded(M_HANDOVER, 2::smallint), -1)
        + coalesce(innings_target_as_folded(M_HANDOVER, 3::smallint), 0);
    -- (nobody)
    PERFORM _assert(n = 0 AND n2 = 0,
      format('db/48 (nobody): an unidentified session read %s and the Westville administrator %s of a Hilton fixture''s credits and target, expected 0 and 0',
             n, n2));
  END;
  PERFORM set_config('app.device_id', '', true);
  PERFORM set_config('app.user_id', '', true);
  -- ── 27. A career in one pass over the log (db/49) ───────────────────
  -- The three lifetime views were one pass of ball_event per PLAYER (db/02,
  -- over the *_since() functions), so the policy on ball_event ran players ×
  -- balls times and the `career` read outgrew the client's ten seconds. db/49
  -- made each one pass, grouped by player — db/44's season views without the
  -- season — and left the functions as they were. They are the reference:
  -- for every player each of eight readers may read, the views are what the
  -- functions say, column by column, over the whole log — the seed, sections
  -- 19 to 23 and §22's fixture, which between them carry every rule (no-ball
  -- byes, retirements marked W, free-hit saves, voids, run outs at the other
  -- end, typed names, a ball with no type, a wicket with no method). §22's
  -- (e) holds the season views to the same lifetime views, so the three
  -- readers of one composition cannot drift apart. Each assertion's label
  -- names what it guards. db/49 was broken each of these ways, one at a
  -- time, and the whole file run; what went red first is recorded, because
  -- an earlier section often catches a composition that moved before this
  -- one is reached — which is the point of having three readers held to one:
  --
  --   the batting view over player_batting_since() again  → (one-pass)
  --   the bowling view without security_invoker           → §22 (e), as the
  --                                                          director; (one-pass)
  --                                                          names it too
  --   the batting view without its retirement arm         → §19 (a batter timed
  --                                                          out has no innings)
  --   the dismissals view without ball_wicket_stands()    → §22 (e)
  --   the bowling view counting a run out as the bowler's → §22 (e)
  --   the batting view's second arm without its NULLIF    → nothing, by design
  --                                                          (below)
  --
  -- and (same) alone, over a generated log (tools/bench-career.mjs --load),
  -- went red for the last two as the owner and the director, and stayed
  -- green for a Westville reader and a pupil, who could see none of it.
  --
  -- The NULLIF on the batting view's second arm changes no figure: `faced`
  -- is false there, so its row adds nothing to runs, balls, fours or sixes,
  -- and count(DISTINCT), max() ignore a repeat. It is kept so the view reads
  -- as db/44's does, row for row. The dismissals view's NULLIF is load-bearing
  -- and (same) catches it dropped only if a retirement and a wicket ball were
  -- ever one row, which they cannot be; db/44's header has the argument.
  DECLARE
    who uuid;
    n bigint; n2 bigint; n3 bigint; n4 bigint;
    detail text;
  BEGIN
    SELECT count(*) INTO n FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
     WHERE ns.nspname = 'public' AND c.relkind = 'v'
       AND c.relname IN ('player_batting_career', 'player_bowling_career', 'player_dismissals')
       AND 'security_invoker=true' = ANY (c.reloptions)
       AND pg_get_viewdef(c.oid) !~ '_since\(';
    -- (one-pass) three invoker views, none of them a function call per player
    PERFORM _assert(n = 3,
      format('db/49 (one-pass): %s of the 3 lifetime views are security_invoker and read the log in one pass, expected 3', n));

    PERFORM set_config('app.user_id', '', true);
    SELECT (SELECT count(*) FROM player_batting_career) + (SELECT count(*) FROM player_bowling_career)
         + (SELECT count(*) FROM player_dismissals) INTO n;
    -- (nobody) an unidentified session reads nothing through them
    PERFORM _assert(n = 0,
      format('db/49 (nobody): an unidentified session read %s rows of lifetime figures, expected 0', n));

    -- (same) THE INVARIANT, as eight readers: the owner (every school), the
    -- director, the scorer and the 2XI coach (Hilton at three widths), the
    -- Westville administrator, the 1XI pupil, a guardian (fixtures, no
    -- deliveries) and nobody at all.
    FOREACH who IN ARRAY ARRAY[U_OWNER, U_SARAH, U_SCORER, U_COACH2, U_WES_ADM, U_PARENT, U_SELF] LOOP
      PERFORM _as(who);
      SELECT count(*), string_agg(format('%s %s: one pass %s, per player %s', d.family, d.player_id, d.one_pass, d.per_player), '; ')
        INTO n, detail FROM _career_lifetime_drift() d;
      -- (same)
      PERFORM _assert(n = 0,
        format('db/49 (same), as %s: %s lifetime figure(s) are not what the per-player functions say — %s', who, n, left(detail, 600)));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM _career_lifetime_drift();
    -- (same), as nobody
    PERFORM _assert(n = 0, format('db/49 (same), as nobody: %s lifetime figure(s) differ', n));

    -- (over) ...and it held over something: the owner and the director read
    -- batting, bowling and dismissals for §22's three boys, whose log carries
    -- every rule, and the Westville administrator reads his own boys.
    PERFORM _as(U_OWNER);
    SELECT (SELECT count(*) FROM player_batting_career WHERE player_id IN ('aaaaaaaa-0000-0000-0000-00000000044a', 'aaaaaaaa-0000-0000-0000-00000000044b'))
         + (SELECT count(*) FROM player_bowling_career WHERE player_id = 'aaaaaaaa-0000-0000-0000-00000000044c')
         + (SELECT count(*) FROM player_dismissals     WHERE player_id IN ('aaaaaaaa-0000-0000-0000-00000000044a', 'aaaaaaaa-0000-0000-0000-00000000044b'))
      INTO n;
    PERFORM _as(U_SARAH);
    SELECT (SELECT count(*) FROM player_batting_career WHERE player_id IN ('aaaaaaaa-0000-0000-0000-00000000044a', 'aaaaaaaa-0000-0000-0000-00000000044b'))
         + (SELECT count(*) FROM player_bowling_career WHERE player_id = 'aaaaaaaa-0000-0000-0000-00000000044c')
         + (SELECT count(*) FROM player_dismissals     WHERE player_id IN ('aaaaaaaa-0000-0000-0000-00000000044a', 'aaaaaaaa-0000-0000-0000-00000000044b'))
      INTO n2;
    SELECT count(*) INTO n3 FROM player_batting_career;
    PERFORM _as(U_WES_ADM);
    SELECT (SELECT count(*) FROM player_batting_career WHERE player_id = P_WES)
         + (SELECT count(*) FROM player_bowling_career WHERE player_id = P_WES2) INTO n4;
    -- (over)
    PERFORM _assert(n = 5 AND n2 = 5 AND n3 > 2 AND n4 = 2,
      format('db/49 (over): the owner reads %s and the director %s of §22''s five lifetime rows (expected 5 and 5), the director %s batting rows in all '
             || '(expected more than §22''s two), the Westville administrator %s of his two boys'' rows (expected 2)', n, n2, n3, n4));
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 28. The pad's resume credential (SCRBRD-078 option B, db/50) ────
  -- A request signed with the credential runs as the scorer, on his phone,
  -- with app.scope = 'pad' and app.match_id — its match. db/50 narrows that
  -- principal at two layers: app_can() (fixture.read and scoring.edit, on its
  -- fixture, and nothing else; app_holds/app_may_grant false) and a
  -- RESTRICTIVE pad_scope_<cmd> policy on every table behind RLS. Each claim
  -- below is one of those, on two fixtures nothing else here touches (F1 and
  -- F2, copies of M_HANDOVER), and then every way a credential ends.
  --
  -- Each labelled assertion was falsified once — the one thing it guards
  -- broken, as the owner, on a fresh seed, and the whole file run — and each
  -- was the FIRST assertion in the file to go red:
  --
  --   (guards)          pad_scope_select dropped from sport
  --   (definers)        a new SECURITY DEFINER function asking fixture.read
  --   (issue-holder)    pad_resume_issue() without its token-holder check
  --   (issue-shape)     pad_jwk_is_public_p256() answering true
  --   (reissued)        the 'reissued' UPDATE and the one-live index gone
  --   (reads-log)       both layers on ball_event: a permissive policy true
  --                     under pad scope, and its pad_scope_select true
  --   (reads-toss)      the same, on match_toss
  --   (reads-else)      pad_scope_select on sport made true (a policy that
  --                     never asks app_can(): only the guard stands there)
  --   (writes-toss)     both layers on match_toss UPDATE
  --   (writes-other)    both layers on ball_event INSERT
  --   (writes-own)      ball_event's INSERT carve-out removed
  --   (writes-own-row)  pad_scope_insert on request_replay made true
  --   (arm)             scoring_arm_handover() without db/50's first line
  --   (doors)           app_can() restored to db/35's (no pad guard)
  --   (holds)           app_holds() restored to db/35's
  --   (reclaim)         pad_resume_reclaim() without its own-match check
  --   (spend)           pad_resume_spend() without its replay refusal
  --   (end-claimed)     the scoring_session UPDATE trigger dropped
  --   (end-handover)    the trigger revoking on ANY state change (so arming
  --                     ended it)
  --   (end-release)     a force-release recorded as token_moved
  --   (end-sign-out)    pad_resume_sign_out() revoking nothing
  --   (end-office)      pad_resume_revoke() asking scoring.edit, not user.invite
  --   (end-day)         pad_resume_ended() without the expiry arm
  --   (end-match)       the match.status trigger dropped
  --
  -- Several are closed at BOTH layers (app_can() and the restrictive guard);
  -- for those the break had to take both away before anything could read or
  -- write, which is the point of having two.
  DECLARE
    F1  uuid := '77777777-0000-0000-0000-00000000050a';
    F2  uuid := '77777777-0000-0000-0000-00000000050b';
    DEV text := 'verify-050';
    JWK jsonb := '{"kty":"EC","crv":"P-256","x":"MKBCTNIcKUSDii11ySs3526iDZ8AiTo7Tu6KPAqv7D4","y":"4Etl6SRW2YiLUrN5vfvVHuhp7x8PxltmWWlbbM4IFyM"}';
    C1  uuid; C1b uuid; C2 uuid; C3 uuid; C4 uuid; C5 uuid; C6 uuid; C7 uuid;
    e1  integer; e2 integer;
    n   bigint; n2 bigint;
    t   record;
    x   record;
    detail text;
  BEGIN
    PERFORM _db50_fixture(F1, M_HANDOVER);
    PERFORM _db50_fixture(F2, M_HANDOVER);

    -- (guards) Every table behind RLS carries a restrictive pad guard for
    -- every command a permissive policy there admits. db/50 checked this when
    -- it ran; a table added since without pad_scope_guard_install() is here.
    SELECT count(*), string_agg(format('%s.%s', c.relname, cm.cmd), ', ') INTO n, detail
      FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
     CROSS JOIN (VALUES ('r', 'select'), ('a', 'insert'), ('w', 'update'), ('d', 'delete')) AS cm(code, cmd)
     WHERE ns.nspname = 'public' AND c.relkind IN ('r', 'p') AND c.relrowsecurity
       AND EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid AND p.polpermissive AND p.polcmd IN ('*', cm.code::"char"))
       AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid AND NOT p.polpermissive
                          AND p.polname = 'pad_scope_' || cm.cmd AND p.polcmd = cm.code::"char");
    -- (guards)
    PERFORM _assert(n = 0, format('db/50 (guards): %s command(s) behind RLS have no pad guard: %s', n, detail));

    -- (definers) The SECURITY DEFINER functions that ask about one of the
    -- credential's own capabilities (fixture.read, scoring.edit) — or the
    -- scoring.start it lacks — by name: app_can() narrows every one to the
    -- credential's match, so each is a door the credential may reach there,
    -- and db/50's header says why each is safe. A new one is a new door, and
    -- fails here until somebody has looked at it and added it to this list.
    SELECT string_agg(p.proname, ',' ORDER BY p.proname) INTO detail
      FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
     WHERE ns.nspname = 'public' AND p.prosecdef
       -- not app_can() itself (its guard names both), nor this file's own helpers
       AND p.proname <> 'app_can' AND p.proname !~ '^_'
       AND (p.prosrc LIKE '%''fixture.read''%' OR p.prosrc LIKE '%''scoring.edit''%' OR p.prosrc LIKE '%''scoring.start''%');
    -- match_fold_context (db/54): the fixture's start and format, the two
    -- facts the fold is told, for the credential's own match only.
    -- match_conditions_fix, match_conditions_resolve, match_playing_conditions
    -- (db/61, SCRBRD-114): the playing conditions the fold is told, read for
    -- the credential's own match (fixture.read), and fixed on its first event
    -- by the append the credential already makes (scoring.edit) — a league's
    -- published figures, nothing about a person, and no other match's.
    -- competition_entrant_reader (db/67, SCRBRD-123): yes or no, may the
    -- caller read an entrant side's fixtures — asked only by the policy on
    -- competition_blackout, which carries the pad guard, so a credential
    -- reads no blackout whatever it answers.
    -- match_result_readable (db/69, SCRBRD-114 phase 3a): yes or no, may the
    -- caller read a match's result — the fixture's reader at either side, or
    -- the competition's; a credential reads its own match's result, which its
    -- log already says, and a result names sides, never a boy.
    -- progression_check (db/72, SCRBRD-114 phase 3c): asks no capability;
    -- 'fixture.read' is the capability its notices require of their reader.
    -- Not the application's to call (only db/72's triggers call it), so no
    -- credential reaches it.
    -- my_alert_choices (db/120, NOTIFICATIONS S4): app_holds('fixture.read')
    -- to offer the caller his own "fixtures moved" switch; answers nothing at
    -- all under a pad credential (`AND NOT app_pad_scoped()` before it asks),
    -- takes no argument and reads no one but the caller.
    -- my_child_fixtures (db/100): the fixtures the caller's own live links'
    -- children are on, asked of app_can('fixture.read', …, <the child>, …).
    -- Under pad scope app_can() answers only the credential's own match, so
    -- the most it returns is the match the credential already reads; it
    -- takes no argument and answers nobody about anybody else.
    -- my_own_sheet_fixtures (db/112): the fixtures whose sheet names the
    -- caller himself (my_own_boy()), asked of app_can('fixture.read', …, <him>,
    -- …) at his own side. The same bound: under pad scope app_can() answers
    -- only the credential's own match; no argument; nobody else's sheet.
    -- my_own_side_fixtures (db/117): the fixtures of the caller's own side on
    -- their day (my_own_boy(), his team_membership rows), asked of
    -- app_can('fixture.read', …, <him>, …) at his own side. The same bound:
    -- under pad scope only the credential's own match; no argument.
    -- result_official_notices (db/114, OFFICIAL_RESULT): asks no capability;
    -- 'fixture.read' is the capability its notices require of their reader,
    -- as progression_check's. Nobody's to call: db/114's doors and triggers
    -- call it as the owner.
    -- result_staff (db/114): asks 'scoring.edit' among the capabilities that
    -- make a reader "staff" for D11's words, and answers false under pad scope
    -- before it asks anything (NOT app_pad_scoped()); nobody's to call.
    -- ball_event_payload_seen (db/118): a payload handed in, answered back
    -- with a retirement's or a bowler change's reason masked unless the
    -- caller holds fixture.read
    -- at that boy's school, asked with the event's own match as the
    -- fixture, and is not platform-wide (READERS Q2, 28 Oct). Under pad
    -- scope app_can() answers only the credential's own match; it can only
    -- return the payload it was given, or less.
    -- safeguarding_concern_raise (db/116, READERS Q11): fixture.read on a
    -- fixture between the reporter's school and the other side's boy's, to
    -- name a boy on that sheet; refused outright under a pad credential
    -- (`AND NOT app_pad_scoped()` before it asks).
    -- scoring_takeover (db/126): scoring.start, refused outright under pad
    -- scope before it asks (a credential never takes over).
    -- pad_resume_toss (db/126): the credential's own match's toss, only while
    -- the token is this person's on this device, written under the person's
    -- scoring.start with the scope lifted for that one write (§103).
    -- app_can_but_player (db/129): app_can()'s own body bar one line (AND
    -- a.role <> 'player'), the pad guard included word for word: under pad
    -- scope it answers as app_can() does, or less; the owner's alone, asked
    -- only by pupil_side_on(), which only ever narrows an app_can() yes.
    PERFORM _assert(detail = 'app_can_but_player,ball_event_payload_seen,competition_entrant_reader,duty_status,duty_suspended,match_conditions_fix,match_conditions_resolve,match_fold_context,'
                             || 'match_playing_conditions,match_result_readable,my_alert_choices,my_child_fixtures,my_own_sheet_fixtures,my_own_side_fixtures,pad_resume_issue,pad_resume_reclaim,pad_resume_toss,progression_check,'
                             || 'result_official_notices,result_staff,safeguarding_concern_raise,scoring_arm_handover,scoring_claim,'
                             || 'scoring_claim_handover,scoring_lease_check,scoring_takeover,scoring_verify_takeover,trip_fixture_driver_only',
      format('db/50 (definers): the definer functions asking a pad capability by name are %s — a new one needs looking at', detail));

    -- ── Issued to the phone that holds the token, and only then ──
    PERFORM _scoring_session_reset(F1);
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DEV, true);
    SELECT i.reason INTO v_reason FROM pad_resume_issue(F1, repeat('1', 64), JWK) i;
    -- (issue-holder)
    PERFORM _assert(v_reason = 'not_token_holder', format('db/50 (issue-holder): a credential was issued with no claim (%s)', v_reason));
    SELECT c.ok, c.epoch INTO v_ok, e1 FROM scoring_claim(F1, DEV) c;
    PERFORM _assert(v_ok, 'db/50: the scorer could not claim the fixture §28 scores');
    SELECT c.ok, c.epoch INTO v_ok, e2 FROM scoring_claim(F2, DEV) c;
    PERFORM _assert(v_ok, 'db/50: the scorer could not claim the second fixture §28 scores');
    SELECT i.reason INTO v_reason FROM pad_resume_issue(F1, repeat('1', 64), JWK || '{"d":"870MB6gfuTJ4HtUnUvYMyJpr5eUZNP4Bk43bVdj3eAE"}') i;
    SELECT i.reason INTO detail FROM pad_resume_issue(F1, 'not-a-hash', JWK) i;
    -- (issue-shape)
    PERFORM _assert(v_reason = 'bad_key' AND detail = 'bad_credential',
      format('db/50 (issue-shape): a private key read %s and a malformed hash %s, expected bad_key and bad_credential', v_reason, detail));
    SELECT i.credential INTO C1 FROM pad_resume_issue(F1, repeat('1', 64), JWK) i;
    SELECT i.credential INTO C1b FROM pad_resume_issue(F1, repeat('2', 64), JWK) i;
    -- (reissued) one live credential per person, phone and match
    PERFORM _assert(C1 IS NOT NULL AND C1b IS NOT NULL AND _db50_reason(C1) = 'reissued' AND _db50_reason(C1b) = 'live',
      format('db/50 (reissued): the first credential is %s and the second %s, expected reissued and live', _db50_reason(C1), _db50_reason(C1b)));

    -- ── Reads: its match's log, session and toss, and nothing else ──
    -- A toss on F1, by the scorer signed in, so there is one to read — and a
    -- ball on F2 (which he holds too), so there is another match's log.
    INSERT INTO match_toss (match_id, school_id, won_by, decision, called_by)
    VALUES (F1, match_school(F1), 'home', 'bat', U_SCORER);
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, payload)
    VALUES (F2, match_school(F2), 1, e2, 0, U_SCORER, DEV, 'verify:050:f2:1', 1, now(), 'innings_start', '{}'::jsonb);
    SELECT count(*) INTO n2 FROM ball_event WHERE match_id <> F1;
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', F1::text, true);
    SELECT count(*) INTO n FROM ball_event WHERE match_id <> F1;
    -- (reads-log) another match's balls: none, where the same scorer signed in reads them
    PERFORM _assert(n = 0 AND n2 > 0,
      format('db/50 (reads-log): as a credential for F1 the scorer read %s balls of other matches (signed in: %s)', n, n2));
    SELECT count(*) INTO n FROM match_toss WHERE match_id = F1;
    SELECT count(*) INTO n2 FROM (SELECT 1 FROM match_toss WHERE match_id <> F1 UNION ALL SELECT 1 FROM scoring_session WHERE match_id <> F1) o;
    -- (reads-toss) its toss and session, and no other match's
    PERFORM _assert(n = 1 AND n2 = 0 AND (SELECT count(*) FROM scoring_session WHERE match_id = F1) = 1,
      format('db/50 (reads-toss): its toss read %s (expected 1), other matches'' tosses and sessions %s (expected 0)', n, n2));
    -- (reads-else) every other table behind RLS the application may read:
    -- nothing at all — the pupils, the medical record, the scorer's own rows,
    -- the fixture itself and its squad, availability and officials included.
    n := 0; detail := '';
    FOR t IN SELECT c.oid, c.relname FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
              WHERE ns.nspname = 'public' AND c.relkind IN ('r', 'p') AND c.relrowsecurity
                AND c.relname NOT IN ('ball_event', 'ball_event_quarantine', 'scoring_session', 'match_toss')
                AND has_table_privilege('scrbrd_app', c.oid, 'SELECT')
              ORDER BY 1 LOOP
      EXECUTE format('SELECT count(*) FROM %I', t.relname) INTO n2;
      IF n2 > 0 THEN n := n + n2; detail := detail || format('%s %s; ', t.relname, n2); END IF;
    END LOOP;
    PERFORM _assert(n = 0, format('db/50 (reads-else): a credential read %s rows beyond its match''s log: %s', n, left(detail, 400)));
    PERFORM set_config('app.scope', '', true);
    SELECT (SELECT count(*) FROM player) + (SELECT count(*) FROM match) + (SELECT count(*) FROM app_user) INTO n;
    PERFORM set_config('app.scope', 'pad', true);
    -- (reads-else), the control: signed in, the same scorer reads them
    PERFORM _assert(n > 0, 'db/50 (reads-else): the control read nothing signed in, so the pad''s nothing proved nothing');

    -- ── Writes: its match's events, and nothing else ──
    -- (writes-toss) the toss is read, never written, with a credential. F1
    -- has no ball yet, so nothing but the two layers stands in the way.
    BEGIN
      UPDATE match_toss SET decision = 'bowl' WHERE match_id = F1;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM _assert(n = 0, 'db/50 (writes-toss): a credential changed its match''s toss');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, payload)
      VALUES (F2, match_school(F2), 2, e2, 0, U_SCORER, DEV, 'verify:050:f2:2', 2, now(), 'innings_start', '{}'::jsonb);
      -- (writes-other) the scorer holds F2's token on this phone, signed in: only the pad scope stops this
      PERFORM _assert(false, 'db/50 (writes-other): a credential for F1 wrote a ball on F2');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    detail := NULL;
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, payload)
      VALUES (F1, match_school(F1), 1, e1, 0, U_SCORER, DEV, 'verify:050:f1:1', 1, now(), 'innings_start', '{}'::jsonb);
    EXCEPTION WHEN insufficient_privilege THEN detail := SQLERRM;
    END;
    SELECT count(*) INTO n FROM ball_event WHERE match_id = F1;
    -- (writes-own) its own match's ball, under the token, goes in
    PERFORM _assert(n = 1, format('db/50 (writes-own): the credential''s ball on F1 is %s rows, expected 1 (%s)', n, detail));
    BEGIN
      INSERT INTO request_replay (person_id, key, route, status, body)
      VALUES (U_SCORER, 'verify:050:replay', 'POST /x', 200, '{}'::jsonb);
      -- (writes-own-row) a policy that asks only who the caller is: the restrictive guard closes it
      PERFORM _assert(false, 'db/50 (writes-own-row): a credential wrote a row of its person''s own (request_replay)');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- ── The doors: app_can() narrowed, and the one claim a credential makes ──
    SELECT a.reason INTO v_reason FROM scoring_arm_handover(F1, DEV, 0, false) a;
    -- (arm) arming asks scoring.edit, which the credential has: db/50's guard refuses it
    PERFORM _assert(v_reason = 'no_capability', format('db/50 (arm): a credential armed a handover (%s)', v_reason));
    SELECT (SELECT c.reason FROM scoring_claim(F1, DEV) c) || '/' || (SELECT h.reason FROM scoring_claim_handover(F1, DEV, '000000') h)
           || '/' || (SELECT v.reason FROM scoring_verify_takeover(F1, DEV, 0, 0, 0) v) || '/' || (SELECT f.reason FROM scoring_force_release(F1) f)
      INTO detail;
    v_ok := false;
    BEGIN
      PERFORM scoring_lease_check(F2, DEV, e2);
    EXCEPTION WHEN insufficient_privilege THEN v_ok := true;
    END;
    -- (doors) app_can() itself, and every door that asks it: a direct claim,
    -- a handover claimed or verified, a force-release, another match's
    -- heartbeat — refused; its own two capabilities on its own fixture — not
    PERFORM _assert(detail = 'no_capability/no_capability/no_capability/no_capability' AND v_ok
                    AND NOT app_can('fixture.read', match_school(F2), match_team(F2), NULL, F2)
                    AND NOT app_can('player.read', HIL, NULL, '00000000-0000-0000-0000-000000000000'::uuid, NULL)
                    AND NOT app_can('scoring.start', match_school(F1), match_team(F1), NULL, F1)
                    AND app_can('scoring.edit', match_school(F1), match_team(F1), NULL, F1)
                    AND app_can('fixture.read', match_school(F1), match_team(F1), NULL, F1),
      format('db/50 (doors): claim/handover-claim/verify/force-release answered %s, another match''s heartbeat refused: %s, '
             || 'or app_can() answered outside the credential''s two capabilities on its fixture', detail, v_ok));
    SELECT l.holds INTO v_ok FROM scoring_lease_check(F1, DEV, e1) l;
    -- the control: its own heartbeat holds
    PERFORM _assert(v_ok, 'db/50 (doors): the credential''s heartbeat does not hold its own lease');
    -- (holds) nothing platform-wide, nothing to grant, no second credential
    PERFORM _assert(NOT app_holds('fixture.read') AND NOT app_may_grant('scorer')
                    AND (SELECT i.reason FROM pad_resume_issue(F1, repeat('3', 64), JWK) i) = 'not_permitted'
                    AND pad_resume_sign_out() = 0,
      'db/50 (holds): under pad scope app_holds/app_may_grant answered true, or a credential minted or signed out');
    SELECT c.ok, c.epoch INTO v_ok, n FROM pad_resume_reclaim(F1) c;
    SELECT c.reason INTO v_reason FROM pad_resume_reclaim(F2) c;
    -- (reclaim) its own token taken back (the next generation), never another match's
    PERFORM _assert(v_ok AND n = e1 + 1 AND v_reason = 'not_permitted' AND _db50_reason(C1b) = 'live'
                    AND current_setting('app.scope', true) = 'pad',
      format('db/50 (reclaim): F1 %s at %s (expected true at %s), F2 %s, credential %s, scope after %s',
             v_ok, n, e1 + 1, v_reason, _db50_reason(C1b), current_setting('app.scope', true)));
    e1 := e1 + 1;

    -- ── Spending a one-time id ──
    SELECT s.ok INTO v_ok FROM pad_resume_spend(C1b, 'verify-050-jti-0001') s;
    SELECT s.reason INTO v_reason FROM pad_resume_spend(C1b, 'verify-050-jti-0001') s;
    SELECT s.reason INTO detail FROM pad_resume_spend(C1b, 'short') s;
    -- (spend) once, and never again
    PERFORM _assert(v_ok AND v_reason = 'replay' AND detail = 'bad_jti' AND _db50_jtis(C1b) = 1,
      format('db/50 (spend): first %s, again %s, a short id %s, %s kept', v_ok, v_reason, detail, _db50_jtis(C1b)));
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);

    -- ── Every way it ends ──
    -- (end-claimed) another phone takes it over after the lease lapsed: the
    -- token moved. Since db/126 that is the confirmed take-over, over the
    -- generation shown; a plain claim there is held_elsewhere (§103).
    PERFORM _lapse_scoring_lease(F1);
    PERFORM set_config('app.device_id', 'verify-050-other', true);
    SELECT c.ok INTO v_ok FROM scoring_takeover(F1, 'verify-050-other', (SELECT ss.epoch FROM scoring_session ss WHERE ss.match_id = F1)) c;
    PERFORM set_config('app.device_id', DEV, true);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', F1::text, true);
    SELECT c.reason INTO v_reason FROM pad_resume_reclaim(F1) c;
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(v_ok AND _db50_reason(C1b) = 'token_moved' AND v_reason = 'token_moved',
      format('db/50 (end-claimed): the other phone claimed %s; the credential is %s and its re-claim %s', v_ok, _db50_reason(C1b), v_reason));

    -- (end-handover) armed, the credential stands; taken over, it ends
    SELECT i.credential INTO C2 FROM pad_resume_issue(F2, repeat('4', 64), JWK) i;
    SELECT a.ok, a.code INTO v_ok, v_code FROM scoring_arm_handover(F2, DEV, 0, false) a;
    detail := _db50_reason(C2);
    PERFORM _as(U_SARAH);
    PERFORM set_config('app.device_id', 'verify-050-sarah', true);
    PERFORM scoring_claim_handover(F2, 'verify-050-sarah', v_code);
    SELECT v.ok INTO v_ok FROM scoring_verify_takeover(F2, 'verify-050-sarah', 0, 0, 0) v;
    PERFORM _assert(v_ok AND detail = 'live' AND _db50_reason(C2) = 'token_moved',
      format('db/50 (end-handover): taken over %s; armed %s, then %s', v_ok, detail, _db50_reason(C2)));

    -- (end-release) force-released: it ends
    SELECT i.credential INTO C3 FROM pad_resume_issue(F2, repeat('5', 64), JWK) i;
    PERFORM _lapse_scoring_lease(F2);
    SELECT f.ok INTO v_ok FROM scoring_force_release(F2) f;
    PERFORM _assert(C3 IS NOT NULL AND v_ok AND _db50_reason(C3) = 'released',
      format('db/50 (end-release): issued %s, released %s, then %s', C3 IS NOT NULL, v_ok, _db50_reason(C3)));

    -- (end-sign-out) the phone signs out: its credentials end, nobody else's
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DEV, true);
    SELECT c.ok INTO v_ok FROM scoring_claim(F2, DEV) c;
    SELECT i.credential INTO C4 FROM pad_resume_issue(F2, repeat('6', 64), JWK) i;
    n := pad_resume_sign_out();
    PERFORM _assert(v_ok AND n = 1 AND _db50_reason(C4) = 'signed_out' AND _db50_reason(C3) = 'released',
      format('db/50 (end-sign-out): signed out %s, the credential %s', n, _db50_reason(C4)));

    -- (end-office) the school office ends it, under user.invite at the match's
    -- school — and nobody else can: not the scorer, not the 2XI coach, not
    -- Westville's office. The office reads the table; the scorer does not.
    SELECT i.credential INTO C5 FROM pad_resume_issue(F2, repeat('7', 64), JWK) i;
    SELECT count(*) INTO n2 FROM pad_resume_credential;
    detail := (SELECT r.reason FROM pad_resume_revoke(F2) r);
    PERFORM _as(U_COACH2);
    detail := detail || '/' || (SELECT r.reason FROM pad_resume_revoke(F2) r);
    PERFORM _as(U_WES_ADM);
    detail := detail || '/' || (SELECT r.reason FROM pad_resume_revoke(F2) r);
    v_state := _db50_reason(C5);
    PERFORM _as(U_REGISTRAR);
    SELECT count(*) INTO n FROM pad_resume_credential WHERE match_id IN (F1, F2);
    SELECT r.revoked INTO e2 FROM pad_resume_revoke(F2) r;
    PERFORM _assert(detail = 'not_permitted/not_permitted/not_permitted' AND v_state = 'live' AND n2 = 0 AND n >= 5
                    AND e2 = 1 AND _db50_reason(C5) = 'office',
      format('db/50 (end-office): scorer/2XI coach/Westville answered %s (credential then %s); the scorer read %s rows, the office %s; '
             || 'the office revoked %s and it is %s', detail, v_state, n2, n, e2, _db50_reason(C5)));

    -- (end-day) past midnight, Johannesburg: expired, whatever else is true
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DEV, true);
    SELECT i.credential INTO C6 FROM pad_resume_issue(F2, repeat('8', 64), JWK) i;
    PERFORM _db50_expire(C6);
    SELECT l.ended INTO v_reason FROM pad_resume_lookup(repeat('8', 64)) l;
    SELECT s.reason INTO detail FROM pad_resume_spend(C6, 'verify-050-jti-0002') s;
    PERFORM _assert(v_reason = 'expired' AND detail = 'expired',
      format('db/50 (end-day): looked up %s, spent %s, expected expired and expired', v_reason, detail));

    -- (end-match) the match completes: it ends, and none is issued after
    SELECT i.credential INTO C7 FROM pad_resume_issue(F2, repeat('9', 64), JWK) i;
    PERFORM _as(U_SARAH);
    UPDATE match SET status = 'complete' WHERE id = F2;
    PERFORM _as(U_SCORER);
    SELECT i.reason INTO v_reason FROM pad_resume_issue(F2, repeat('a', 64), JWK) i;
    PERFORM _assert(C7 IS NOT NULL AND _db50_reason(C7) = 'match_complete' AND v_reason = 'match_complete',
      format('db/50 (end-match): the credential is %s, a new issue %s', _db50_reason(C7), v_reason));
  END;
  PERFORM set_config('app.scope', '', true);
  PERFORM set_config('app.match_id', '', true);
  PERFORM set_config('app.device_id', '', true);
  PERFORM set_config('app.user_id', '', true);

  -- ── 29. The milestone trigger reads the striker's own balls (SCRBRD-097, db/51) ──
  -- milestone_watch() asked player_innings for the striker's innings and his
  -- career on every scoring ball, and the career question read every
  -- delivery in the log through two of its three arms — the bulk load's
  -- players × balls. db/51 asks two helpers instead, each a sum of runs off
  -- the bat over the balls he faced: the only arm that carries runs. They
  -- are held here to the composition they replace, as the trigger reads it
  -- (the owner, past RLS): every innings in the log — the seed, sections 19
  -- to 23, §22's and this section's fixtures, which carry voids, no-ball
  -- byes, retirements marked W and run outs at the other end, including an
  -- innings with no ball faced in it — and every player's career. And the
  -- trigger is held to the notices it calls, one INSERT per delivery. Each
  -- assertion's label names what it guards; db/51 was broken each of these
  -- ways, one at a time, and the whole file run. Each first stops db/51's own
  -- self-check (named on the right); each was run again with that check
  -- lifted, to see this section go red on its own:
  --
  --   milestone_watch() reading player_innings again         → (shape)    db/51: still reads player_innings
  --   career_runs_off_bat() executable by PUBLIC              → (shape)    db/51: executable by PUBLIC
  --   career_runs_off_bat() over ball_event, voids included   → (same)     db/51: the fixture's figures
  --                                                             (§19–§23's voided balls, and this fixture's)
  --   career_runs_off_bat() without its coalesce              → (same)     db/51: the fixture's figures
  --   innings_runs_off_bat() without its innings              → (notices)  db/51: the fixture's notices
  --                                                             (no fifty in the second innings)
  --   the career threshold compared against the innings figure → (notices) db/51: the fixture's notices
  --   the five-for asked of the bowler's career               → (notices)  db/51: the fixture's notices
  DECLARE
    n bigint;
    detail text;
    v_want text := 'A:fifty:a:0:54 A:hundred:a:0:102 C:hat_trick:a:1:3 C:five_for:a:1:5 '
                || 'A:fifty:b:0:54 A:hundred:b:0:102 A:career_runs:b:0:500 '
                || 'C:hat_trick:b:1:3 C:five_for:b:1:5 C:career_wickets:b:0:25 A:fifty:b:2:54';
  BEGIN
    SELECT count(*) INTO n FROM pg_proc p
     WHERE p.oid IN ('innings_runs_off_bat(uuid,uuid,smallint)'::regprocedure, 'career_runs_off_bat(uuid)'::regprocedure)
       AND NOT p.prosecdef
       AND NOT has_function_privilege('scrbrd_app', p.oid, 'EXECUTE')
       AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) x WHERE x.grantee = 0 AND x.privilege_type = 'EXECUTE');
    -- (shape) the trigger no longer reads player_innings; the two helpers are invoker, and nobody's but the owner's
    PERFORM _assert(n = 2 AND (SELECT prosrc FROM pg_proc WHERE oid = 'milestone_watch()'::regprocedure) !~ 'player_innings',
      format('db/51 (shape): %s of the 2 helpers are invoker and callable by nobody but the owner (expected 2); '
             || 'milestone_watch() reads player_innings: %s', n,
             (SELECT prosrc FROM pg_proc WHERE oid = 'milestone_watch()'::regprocedure) ~ 'player_innings'));

    -- (notices) one INSERT per delivery, every kind the trigger writes
    detail := _milestone_fixture_51();
    PERFORM _assert(detail IS NOT DISTINCT FROM v_want,
      format('db/51 (notices): the fixture raised %s, expected %s', detail, v_want));

    -- (same) THE INVARIANT, over the whole log, this section's fixture included
    SELECT count(*), string_agg(format('%s %s/%s/%s: own balls %s, player_innings %s', d.figure, d.player_id,
                                       d.match_id, d.innings, d.own_balls, d.player_innings), '; ')
      INTO n, detail FROM _milestone_figure_drift() d;
    PERFORM _assert(n = 0,
      format('db/51 (same): %s figure(s) the milestone trigger reads are not what player_innings says — %s', n, left(detail, 600)));
  END;
  -- ── 30. A no-ball's byes and leg byes are not the bowler's (Law 21.15, db/52) ──
  -- The rule as the current Code has it: a no-ball's penalty run and the runs
  -- off the bat are debited to the bowler; runs not off the bat are byes or
  -- leg byes, and not his. ball_runs_to_bowler() is runsToBowler() in SQL
  -- (packages/scoring/src/events.mjs), and every reader of a bowler's runs
  -- asks it. §19, §22 and db/43's fixture above carry no-ball byes and leg
  -- byes and were moved to it; this section holds the rule itself, that every
  -- reader asks it, and that they agree over the whole log — the seed and
  -- every fixture above. db/52 was broken each of these ways and this file
  -- run: the no-ball arm charging 1 + value again (→ rule, and §19/§22/db/43's
  -- figures); player_bowling_career summing the old CASE (→ readers, same).
  DECLARE
    n bigint;
    detail text;
  BEGIN
    -- (rule) runsToBowler()'s table (replay.test.mjs, K)
    PERFORM _assert(ball_runs_to_bowler('Nb', 4, '{"nbRuns":"byes"}') = 1
                    AND ball_runs_to_bowler('Nb', 3, '{"nbRuns":"leg_byes"}') = 1
                    AND ball_runs_to_bowler('Nb', 4, '{}') = 5 AND ball_runs_to_bowler('Nb', 0, '{}') = 1
                    AND ball_runs_to_bowler('Wd', 2, '{}') = 3 AND ball_runs_to_bowler('B', 4, '{}') = 0
                    AND ball_runs_to_bowler('LB', 1, '{}') = 0 AND ball_runs_to_bowler('run', 6, '{}') = 6
                    AND ball_runs_to_bowler('W', 1, '{}') = 1,
      'db/52 (rule): ball_runs_to_bowler() is not runsToBowler() — a no-ball is its penalty run and the runs off the bat, never its byes or leg byes');

    -- (readers) the five that charge a bowler all ask it
    SELECT count(*), string_agg(o, ', ') INTO n, detail FROM (
      SELECT 'player_bowling_since' AS o, prosrc AS src FROM pg_proc WHERE oid = 'player_bowling_since(uuid,timestamptz)'::regprocedure
      UNION ALL SELECT 'opposition_squad', prosrc FROM pg_proc WHERE oid = 'opposition_squad(uuid)'::regprocedure
      UNION ALL SELECT 'bowler_innings_figures', pg_get_viewdef('bowler_innings_figures'::regclass)
      UNION ALL SELECT 'player_bowling_by_season', pg_get_viewdef('player_bowling_by_season'::regclass)
      UNION ALL SELECT 'player_bowling_career', pg_get_viewdef('player_bowling_career'::regclass)) d
     WHERE d.src NOT LIKE '%ball_runs_to_bowler(%';
    PERFORM _assert(n = 0, format('db/52 (readers): %s do(es) not charge the bowler through ball_runs_to_bowler(): %s', n, coalesce(detail, '')));

    -- (same) over the whole log, as this reader sees it: the lifetime view,
    -- the windowed function, the seasons summed and the innings summed
    SELECT count(*), string_agg(k, '; ') INTO n, detail FROM (
      SELECT 'career/since ' || coalesce(l.player_id, o.player_id) AS k
        FROM player_bowling_career l
        FULL JOIN (SELECT p.id AS player_id, c.* FROM player p CROSS JOIN LATERAL player_bowling_since(p.id, NULL) c
                    WHERE c.matches > 0) o ON o.player_id = l.player_id
       WHERE l.runs_conceded IS DISTINCT FROM o.runs_conceded
      UNION ALL
      SELECT 'career/seasons ' || l.player_id
        FROM player_bowling_career l
        JOIN (SELECT player_id, sum(runs_conceded) AS runs FROM player_bowling_by_season GROUP BY player_id) x
          ON x.player_id = l.player_id
       WHERE l.runs_conceded IS DISTINCT FROM x.runs
      UNION ALL
      SELECT 'career/innings ' || l.player_id
        FROM player_bowling_career l
        JOIN (SELECT player_id, sum(runs_conceded) AS runs FROM bowler_innings_figures GROUP BY player_id) f
          ON f.player_id = l.player_id
       WHERE l.runs_conceded IS DISTINCT FROM f.runs) d;
    PERFORM _assert(n = 0, format('db/52 (same): %s bowler figure(s) disagree between the readers — %s', n, left(coalesce(detail, ''), 600)));
  END;

  -- ── 31. Retired out, back with the opposing captain's consent (Law 25.4.3, db/53) ──
  -- A `retire` marked W is a wicket from the moment it is recorded; a later
  -- live `batters` row naming the same batter with captainConsent takes it
  -- back, as the fold does (replay.mjs). ball_event_live reads such a
  -- retirement as no wicket (ball type and dismissal NULL), so every reader
  -- follows: the live score, the handover's count, player_innings, the
  -- dismissal readers. Read as the owner of the platform, under RLS.
  -- _seed_53() writes the fixtures; _void_53() undoes M1's return. db/53 was
  -- broken each of these ways and this file run, with db/53's own proof
  -- lifted (it refuses all but the third itself):
  --   the view's CASEs answering false (no retirement ever resumed) → (b)
  --   retirement_resumed() ignoring voids                          → (c)
  --   retirement_resumed() not checking the batter                 → (b): A's career
  --     lost M2's retirement, which C's return does not take back
  --   retirement_resumed() reading payload names only (not the id columns) → (b)
  PERFORM set_config('app.user_id', '', true);
  PERFORM _seed_53();
  PERFORM _as(U_OWNER);
  DECLARE
    A  uuid := 'aaaaaaaa-0000-0000-0000-00000000053a';
    C  uuid := 'aaaaaaaa-0000-0000-0000-00000000053c';
    M1 uuid := '77777777-0000-0000-0000-000000053001';
    M2 uuid := '77777777-0000-0000-0000-000000053002';
    got text;
  BEGIN
    -- (a) the view asks the rule
    PERFORM _assert((SELECT count(*) FROM regexp_matches(pg_get_viewdef('ball_event_live'::regclass), 'retirement_resumed\(', 'g')) = 2,
      'db/53 (a): ball_event_live does not read a resumed retirement through retirement_resumed()');

    -- (b) M1, "the db/53 fixture": 6 for 1, A not out, his dismissal gone
    SELECT concat_ws(' ',
             (SELECT 'live' || row(s.runs, s.wickets, s.legal_balls)::text FROM match_live_score s WHERE s.match_id = M1 AND s.innings = 0),
             (SELECT 'handover' || row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded(M1, 0::smallint) f),
             (SELECT 'A' || row(i.runs, i.balls_faced, i.out)::text FROM player_innings i WHERE i.player_id = A AND i.match_id = M1),
             (SELECT 'C' || row(i.runs, i.balls_faced, i.out)::text FROM player_innings i WHERE i.player_id = C AND i.match_id = M1),
             'dismissals' || row(coalesce((SELECT d.dismissals FROM player_dismissals d WHERE d.player_id = A), 0),
                                 coalesce((SELECT sum(d.dismissals) FROM player_dismissal_breakdown d WHERE d.player_id = A), 0))::text)
      INTO got;
    -- A's career: one dismissal, M2's retirement that stands — not M1's.
    PERFORM _assert(got = 'live(6,1,4) handover(6,1,4) A(6,2,f) C(0,2,t) dismissals(1,1)',
      format('db/53 (b): the consented return reads %s, the fold reads live(6,1,4) handover(6,1,4) A(6,2,f) C(0,2,t) dismissals(1,1)', got));

    -- (d) M2: a consented return for somebody else leaves A's retirement
    --     standing; a typed name's is taken back
    SELECT concat_ws(' ',
             (SELECT 'live' || row(s.wickets)::text FROM match_live_score s WHERE s.match_id = M2 AND s.innings = 0),
             (SELECT 'A' || row(i.out)::text FROM player_innings i WHERE i.player_id = A AND i.match_id = M2),
             (SELECT 'typed' || row(coalesce(l.ball_type, '-'))::text FROM ball_event_live l WHERE l.match_id = M2 AND l.seq = 4))
      INTO got;
    PERFORM _assert(got = 'live(1) A(t) typed(-)',
      format('db/53 (d): a return naming another batter, or a typed name''s, reads %s; expected live(1) A(t) typed(-)', got));

    -- (c) the return undone: A is out again
    PERFORM _void_53();
    SELECT concat_ws(' ',
             (SELECT 'live' || row(s.wickets)::text FROM match_live_score s WHERE s.match_id = M1 AND s.innings = 0),
             (SELECT 'A' || row(i.out)::text FROM player_innings i WHERE i.player_id = A AND i.match_id = M1))
      INTO got;
    PERFORM _assert(got = 'live(2) A(t)', format('db/53 (c): with the return voided, M1 reads %s; expected live(2) A(t)', got));
  END;

  -- ── 32. A delivery that does not count in the over; the free hit by the format (SCRBRD-113, db/54) ──
  -- Law 17.3.2.5: a delivery under 24.4, 28.2, 41.4 or 41.5 is not one of the
  -- six (payload.notInOver); ball_counts_in_over() is countsInOver() in SQL,
  -- and every reader of the balls of the over asks it. The free hit is a
  -- limited-overs playing condition: none in a declaration or timed match
  -- (free_hits_apply(), freeHitsApply() in SQL), so ball_on_free_hit() asks
  -- the match's format. The fixture (_laws_fixture_54()) is db/54's own; the
  -- invariants run over the whole log this reader sees. db/54 was broken each
  -- of these ways and this file run: bowler_over counting a delivery that
  -- does not count (→ fixture, same), player_bowling_career keeping the old
  -- CASE (→ readers, same), ball_on_free_hit() not asking the format
  -- (→ fixture, readers).
  -- Read as the owner of the platform, named here: the invariants compare
  -- every match, whoever the section before left in the session. With no
  -- principal they compared nothing (an empty user sees no row), and passed.
  -- Once they compared, they found the db/45 section's first innings: a
  -- retire marked W with method bowled, which the live score counted and the
  -- handover's count, as the fold, did not; and a penalty row carrying a
  -- value, which the live score added. db/54 (4) makes the live score count
  -- as the handover does. Broken each way and this file run: the old live
  -- score (→ same, 81/15 against 78/14), its wickets alone (→ same, 15
  -- against 14), its runs alone (→ same, 81 against 78), and the old live
  -- score with no principal set here (→ same, the count below); db/54's own
  -- proof refuses the old live score on its refused rows first.
  PERFORM _as(U_OWNER);
  DECLARE
    n bigint;
    detail text;
    v_want text := 'live(12,3,9) folded(12,3,9) overs(A:0:6/7 C:1:3/4) hattrick(C@13) career(8,3) '
                || 't20(0,true) declaration(1,false,1,1)';
  BEGIN
    -- (rule) countsInOver()'s table (edition.test.mjs, E) and freeHitsApply()'s (G)
    PERFORM _assert(ball_counts_in_over('run', '{}') AND ball_counts_in_over('B', '{}') AND ball_counts_in_over('W', '{}')
                    AND NOT ball_counts_in_over('Wd', '{}') AND NOT ball_counts_in_over('Nb', '{}')
                    AND NOT ball_counts_in_over('run', '{"notInOver":"illegal_fielding"}')
                    AND NOT ball_counts_in_over('LB', '{"notInOver":"obstructing_batter"}')
                    AND ball_counts_in_over('run', '{"notInOver":"helmet_struck"}')
                    AND ball_counts_in_over(NULL, '{}') IS NULL,
      'db/54 (rule): ball_counts_in_over() is not countsInOver() — a delivery under 24.4, 28.2, 41.4 or 41.5 is not one of the six');
    PERFORM _assert(free_hits_apply('T20') AND free_hits_apply('One-Day') AND free_hits_apply(NULL) AND free_hits_apply('50-over')
                    AND NOT free_hits_apply('One-Day Declaration') AND NOT free_hits_apply('Two-Day')
                    AND NOT free_hits_apply(' multi-day ') AND NOT free_hits_apply('Timed'),
      'db/54 (rule): free_hits_apply() is not freeHitsApply() — no free hit in a declaration or timed match, one in every other');

    -- (readers) every reader of the balls of the over asks the rule; the free hit asks the format
    SELECT count(*), string_agg(o, ', ') INTO n, detail FROM (
      SELECT 'match_live_score' AS o, pg_get_viewdef('match_live_score'::regclass) AS src
      UNION ALL SELECT 'innings_score_as_folded', prosrc FROM pg_proc WHERE oid = 'innings_score_as_folded(uuid,smallint)'::regprocedure
      UNION ALL SELECT 'bowler_over', pg_get_viewdef('bowler_over'::regclass)
      UNION ALL SELECT 'bowler_hat_trick', pg_get_viewdef('bowler_hat_trick'::regclass)
      UNION ALL SELECT 'player_bowling_since', prosrc FROM pg_proc WHERE oid = 'player_bowling_since(uuid,timestamptz)'::regprocedure
      UNION ALL SELECT 'opposition_squad', prosrc FROM pg_proc WHERE oid = 'opposition_squad(uuid)'::regprocedure
      UNION ALL SELECT 'player_bowling_by_season', pg_get_viewdef('player_bowling_by_season'::regclass)
      UNION ALL SELECT 'player_bowling_career', pg_get_viewdef('player_bowling_career'::regclass)) d
     WHERE d.src NOT LIKE '%ball_counts_in_over(%';
    PERFORM _assert(n = 0, format('db/54 (readers): %s do(es) not count the balls of the over through ball_counts_in_over(): %s', n, coalesce(detail, '')));
    PERFORM _assert((SELECT prosrc FROM pg_proc WHERE oid = 'ball_on_free_hit(uuid,smallint,integer)'::regprocedure) LIKE '%match_free_hits_apply(p_match)%',
      'db/54 (readers): ball_on_free_hit() does not ask the match''s format');

    -- (fixture) db/54's, read through every reader it moved
    detail := _laws_fixture_54();
    PERFORM _assert(detail IS NOT DISTINCT FROM v_want, format('db/54 (fixture): the fixture reads %s, the fold reads %s', detail, v_want));

    -- (same) over the whole log, as the owner sees it: the live score and
    -- the handover check's count, innings by innings — runs, wickets and
    -- balls of the over; a bowler's career balls and the overs he bowled.
    -- And that there is a whole log to compare: an empty session passes.
    SELECT count(*), string_agg(k, '; ') INTO n, detail FROM (
      SELECT 'live/folded ' || l.match_id || '/' || l.innings
             || ' ' || row(l.runs, l.wickets, l.legal_balls)::text || ' vs ' || row(f.runs, f.wickets, f.legal_balls)::text AS k
        FROM match_live_score l CROSS JOIN LATERAL innings_score_as_folded(l.match_id, l.innings::smallint) f
       WHERE l.legal_balls IS DISTINCT FROM f.legal_balls::bigint OR l.wickets IS DISTINCT FROM f.wickets::bigint
          OR l.runs IS DISTINCT FROM f.runs::bigint
      UNION ALL
      SELECT 'career/overs ' || c.player_id
        FROM player_bowling_career c
        JOIN (SELECT bowler_id, sum(legal_balls) AS balls FROM bowler_over GROUP BY bowler_id) o ON o.bowler_id = c.player_id
       WHERE c.legal_balls IS DISTINCT FROM o.balls) d;
    PERFORM _assert(n = 0, format('db/54 (same): %s figure(s) disagree between the readers — %s', n, left(coalesce(detail, ''), 600)));
    SELECT count(*) INTO n FROM match_live_score;
    PERFORM _assert(n >= 10, format('db/54 (same): this section sees %s innings in the live score — the comparison compared nothing', n));

    -- (context) how the server folds a match: its start and format, for a
    -- caller who may read the fixture, and nothing for one who may not
    PERFORM _as(U_SCORER);
    SELECT count(*), max(format) INTO n, detail FROM match_fold_context('77777777-0000-0000-0000-000000000002');
    PERFORM _assert(n = 1 AND detail = 'T20', format('db/54 (context): the scorer reads %s row(s) of the fixture''s fold context (%s), expected its one', n, detail));
    PERFORM _as(U_WES_ADM);
    SELECT count(*) INTO n FROM match_fold_context('77777777-0000-0000-0000-000000000002');
    PERFORM _assert(n = 0, format('db/54 (context): another school''s admin reads %s row(s) of a fixture he may not read', n));
  END;

  -- ── 33. A pupil reads no team-mate's injury status (K3, db/55) ──────
  -- CSA Safeguarding Policy p52 item 6: a child's medical needs are for
  -- "staff and coaches who need it, but not in general view to other ...
  -- children". db/55 withdrew medical.status.read from `player` (held across
  -- a side, by children). `enquiry` keeps it (Kameel, 2026-09-28): a grant is
  -- coach to coach, for one named player, and both ends are staff. Each
  -- refusal below is paired with a read that proves the principal is live,
  -- so a zero is the capability refusing and not an empty fixture. db/55 was
  -- undone (its role_capability row put back) and this file run: (pupil)
  -- failed, and 3b and 11 above with it; the enquiry's row was deleted and
  -- (enquiry) failed.
  DECLARE
    n       bigint;
    v_req   uuid;
    v_ok    boolean;
    v_why   text;
    v_asg   uuid;
    I_OTHER uuid := 'cccccccc-0000-0000-0000-000000000002';  -- T Bekker's injury, 1XI
  BEGIN
    -- (catalogue) the pupil's row is gone, and nobody else's went with it
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM role_capability
                                 WHERE role = 'player' AND capability = 'medical.status.read'),
      'db/55 (catalogue): player still holds medical.status.read');
    PERFORM _assert((SELECT count(*) FROM role_capability
                      WHERE capability = 'medical.status.read'
                        AND role IN ('coach', 'assistantcoach', 'teammanager', 'medical', 'enquiry', 'guardian', 'selfaccess',
                                     'principal', 'directorofsport', 'schooladmin', 'sportsadmin')) = 11,
      'db/55 (catalogue): a role that needs the status tier lost it');

    -- (pupil) R Pillay, 1XI, injured, beside T Bekker, 1XI, also injured. His
    -- player assignment is the 1XI's; his selfaccess names him alone.
    PERFORM _as(U_SELF);
    SELECT count(*) INTO n FROM injury_masked WHERE player_id = P_INJURED AND injury_type IS NOT NULL AND notes IS NOT NULL;
    PERFORM _assert(n = 1, format('db/55 (pupil): R Pillay reads %s of his own injury rows at every tier, expected 1 — selfaccess must still reach him', n));
    SELECT count(*) INTO n FROM injury_masked WHERE player_id = P_OTHER;
    PERFORM _assert(n = 0, format('db/55 (pupil): R Pillay reads %s row(s) of his 1XI team-mate''s injury — that he is out, and until when', n));
    SELECT count(*) INTO n FROM injury_masked WHERE player_id <> P_INJURED;
    PERFORM _assert(n = 0, format('db/55 (pupil): R Pillay reads %s injury row(s) about somebody else', n));
    SELECT count(*) INTO n FROM player_masked WHERE id = P_OTHER;
    PERFORM _assert(n = 1, 'db/55 (pupil): R Pillay cannot read his team-mate''s profile at all — the refusal above proves nothing');
    -- a pupil school-wide, with no selfaccess: nothing, and the team sheet still
    PERFORM _as(U_PUPIL);
    SELECT count(*) INTO n FROM injury_masked;
    PERFORM _assert(n = 0, format('db/55 (pupil): a pupil reads %s injury row(s) at his school', n));
    SELECT count(*) INTO n FROM player_masked WHERE id IN (P_INJURED, P_OTHER);
    PERFORM _assert(n = 2, 'db/55 (pupil): a pupil cannot read the side at all — the refusal above proves nothing');

    -- (staff) whoever should, still does
    PERFORM _as(U_MEDICAL);
    SELECT count(*) INTO n FROM injury_masked WHERE id IN (I_OWN, I_OTHER) AND notes IS NOT NULL;
    PERFORM _assert(n = 2, format('db/55 (staff): the physio reads %s of the two 1XI injuries in full', n));
    PERFORM _as(U_SARAH);   -- directorofsport, school-wide
    SELECT count(*) INTO n FROM injury_masked WHERE id IN (I_OWN, I_OTHER) AND rtw_date IS NOT NULL AND injury_type IS NOT NULL;
    PERFORM _assert(n = 2, format('db/55 (staff): the director of sport reads %s of the two 1XI injuries, status and nature', n));
    -- (A guardian's read of his own child is 3b's, above: by this point in
    -- the file earlier sections have moved U_PARENT's link.)

    -- (enquiry) the 2XI coach asks for R Pillay (1XI) and is told yes: the
    -- granted assignment reaches his profile and whether he is out, and until
    -- when — and not what is wrong with him, nor any team-mate of his
    PERFORM _as(U_COACH2);
    SELECT count(*) INTO n FROM injury_masked WHERE player_id = P_INJURED;
    PERFORM _assert(n = 0, 'db/55 (enquiry): the 2XI coach reads a 1XI injury before any grant');
    INSERT INTO access_request (player_id, school_id, for_team, requested_by, reason)
      VALUES (P_INJURED, HIL, '2XI', U_COACH2, 'fill_in') RETURNING id INTO v_req;
    PERFORM _as(U_OWNER);   -- holds player.access.grant everywhere
    SELECT d.ok, d.reason, d.assignment INTO v_ok, v_why, v_asg FROM access_request_decide(v_req, true, NULL, 14) d;
    PERFORM _assert(v_ok AND v_asg IS NOT NULL, format('db/55 (enquiry): the grant was refused (%s)', v_why));
    PERFORM _as(U_COACH2);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED;
    PERFORM _assert(n = 1, 'db/55 (enquiry): the granted enquiry does not reach the boy''s profile');
    SELECT count(*) INTO n FROM injury_masked WHERE player_id = P_INJURED AND rtw_date IS NOT NULL;
    PERFORM _assert(n = 1, format('db/55 (enquiry): a granted enquiry reads %s of the boy''s injury status rows, expected 1 — that he is out, and until when (Kameel, 2026-09-28)', n));
    SELECT count(*) INTO n FROM injury_masked WHERE player_id = P_INJURED AND (injury_type IS NOT NULL OR notes IS NOT NULL);
    PERFORM _assert(n = 0, 'db/55 (enquiry): a granted enquiry reads what is wrong with the boy');
    SELECT count(*) INTO n FROM injury_masked WHERE player_id <> P_INJURED;
    PERFORM _assert(n = 0, format('db/55 (enquiry): a granted enquiry reads %s injury row(s) about somebody other than the boy granted', n));
  END;

  -- ── 34. The clearance register to CSA's rules (K4, SG-7, db/56) ─────
  -- CSA's Safeguarding Policy: the Sexual Offences Register, the Child
  -- Protection Register and a criminal check for every adult coach,
  -- administrator and official, each no older than 24 months (p19, p24–26),
  -- a first criminal check no older than six months (p26), the Safeguarding
  -- Awareness Certificate annually (p22). Written as the office writes them —
  -- the registrar, under RLS, through db/08's stamp trigger and db/56's age
  -- rule. db/56 was broken each of these ways and this file run: the ages
  -- table emptied (→ (age), (first)); the first-police rule counting a
  -- revoked row as held (→ (first)); clearance_register() without the pupil
  -- exclusion (→ (pupil)); the requirement rows left out (→ (roles), and the
  -- register's own counts).
  DECLARE
    n       bigint;
    v_err   text;
    v_id    uuid;
    U_DRV   uuid := '88888888-0000-0000-0000-000000000017';  -- B Ngcobo, driver; police current
    U_V56   uuid := '88888888-0000-0000-0000-000000000056';  -- S Naidoo, eighteen: player and scorer
    d       date := sa_today();
  BEGIN
    -- (roles) every adult role is asked for the three checks, the SAC and the
    -- acknowledgement; a pupil's and a parent's roles for nothing
    PERFORM _as(U_REGISTRAR);
    SELECT count(DISTINCT role) INTO n FROM clearance_requirement
     WHERE kind = 'sexual_offences_register'
       AND role IN ('coach', 'assistantcoach', 'teammanager', 'medical', 'driver', 'transportcoordinator',
                    'official', 'scorer', 'facilities', 'media', 'scout', 'schooladmin', 'sportsadmin',
                    'directorofsport', 'principal');
    PERFORM _assert(n = 15, format('db/56 (roles): %s of the 15 adult roles are asked for the Sexual Offences Register', n));
    SELECT count(*) INTO n FROM clearance_requirement
     WHERE role IN ('player', 'selfaccess', 'guardian', 'spectator', 'enquiry');
    PERFORM _assert(n = 0, 'db/56 (roles): a pupil''s or a parent''s role is asked for a clearance');
    SELECT count(*) INTO n FROM clearance_register(HIL)
     WHERE person_id = U_SCORER AND kind IN ('police_clearance', 'child_protection', 'sexual_offences_register',
                                             'safeguarding_awareness', 'safeguarding_acknowledgement')
       AND status = 'missing';
    PERFORM _assert(n = 5, format('db/56 (roles): the scorer, an adult, is missing %s of the five checks CSA asks of him, expected all five', n));

    -- (age) a check runs at most its kind's maximum; exactly the maximum is accepted
    BEGIN
      INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
        VALUES (U_COACH2, HIL, 'child_protection', 'CPR-V56-001', d - 10, d - 10 + 761);
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%runs at most 731 days%', format('db/56 (age): a 25-month Child Protection Register clearance was not refused (%s)', coalesce(v_err, 'accepted')));
    BEGIN
      INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
        VALUES (U_COACH2, HIL, 'sexual_offences_register', 'NRSO-V56-001', d - 10, d - 10 + 732);
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%runs at most 731 days%', format('db/56 (age): a Sexual Offences Register clearance of 732 days was not refused (%s)', coalesce(v_err, 'accepted')));
    INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
      VALUES (U_COACH2, HIL, 'sexual_offences_register', 'NRSO-V56-002', d - 10, d - 10 + 731) RETURNING id INTO v_id;
    PERFORM _assert(v_id IS NOT NULL, 'db/56 (age): a Sexual Offences Register clearance of exactly 24 months was refused');
    SELECT count(*) INTO n FROM clearance_register(HIL)
     WHERE person_id = U_COACH2 AND kind = 'sexual_offences_register' AND status = 'current';
    PERFORM _assert(n = 1, 'db/56 (age): the recorded Sexual Offences Register clearance does not read current on the register');
    BEGIN
      INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
        VALUES (U_COACH2, HIL, 'safeguarding_awareness', 'SAC-V56-001', d, d + 367);
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%runs at most 366 days%', format('db/56 (age): a Safeguarding Awareness Certificate of 367 days was not refused (%s)', coalesce(v_err, 'accepted')));
    -- a kind with no CSA maximum keeps db/08's outer bound only
    INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
      VALUES (U_COACH2, HIL, 'safeguarding_acknowledgement', 'ANNEX-G-V56', d, d + 1000) RETURNING id INTO v_id;
    PERFORM _assert(v_id IS NOT NULL, 'db/56 (age): a signed acknowledgement, which has no CSA maximum, was refused');

    -- (first) a first police clearance at the school no older than six months;
    -- a renewal is not held to it
    BEGIN
      INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
        VALUES (U_BURSAR, HIL, 'police_clearance', 'PCC-V56-001', d - 214, d - 214 + 700);
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%first police clearance must be no older than 183 days%',
      format('db/56 (first): a first police clearance issued seven months ago was not refused (%s)', coalesce(v_err, 'accepted')));
    INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
      VALUES (U_DRV, HIL, 'police_clearance', 'PCC-V56-002', d - 214, d - 214 + 700) RETURNING id INTO v_id;
    PERFORM _assert(v_id IS NOT NULL, 'db/56 (first): a renewal issued seven months ago was refused as though it were a first');
    INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
      VALUES (U_BURSAR, HIL, 'police_clearance', 'PCC-V56-003', d - 183, d - 183 + 700) RETURNING id INTO v_id;
    PERFORM _assert(v_id IS NOT NULL, 'db/56 (first): a first police clearance exactly six months old was refused');
    -- a revoked row is not a check held: revoke the bursar's, and a first rule applies again
    UPDATE adult_clearance SET revoked_at = now(), revoked_reason = 'Verify 056: wrong person' WHERE id = v_id;
    BEGIN
      INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
        VALUES (U_BURSAR, HIL, 'police_clearance', 'PCC-V56-004', d - 214, d - 214 + 700);
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%first police clearance%',
      format('db/56 (first): with only a revoked row held, a seven-month-old police clearance was taken as a renewal (%s)', coalesce(v_err, 'accepted')));

    -- (legacy) a five-year row recorded before db/56 reads current until its
    -- date, and is revoked like any other
    PERFORM set_config('app.user_id', '', true);
    v_id := _legacy_56();
    PERFORM _as(U_REGISTRAR);
    SELECT count(*) INTO n FROM adult_clearance
     WHERE id = v_id AND expires_on - issued_on > 731 AND revoked_at IS NULL;
    PERFORM _assert(n = 1, 'db/56 (legacy): the office cannot read the five-year police clearance recorded before db/56');
    SELECT count(*) INTO n FROM clearance_register(HIL)
     WHERE person_id = U_SCORER AND kind = 'police_clearance' AND clearance_id = v_id AND status = 'current';
    PERFORM _assert(n = 1, 'db/56 (legacy): a police clearance recorded before db/56 to run five years no longer reads current until its date');
    UPDATE adult_clearance SET revoked_at = now(), revoked_reason = 'Verify 056: re-checked under CSA' WHERE id = v_id;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, 'db/56 (legacy): the office cannot revoke a row older than CSA''s 24 months');
    SELECT count(*) INTO n FROM clearance_register(HIL)
     WHERE person_id = U_SCORER AND kind = 'police_clearance' AND status = 'revoked';
    PERFORM _assert(n = 1, 'db/56 (legacy): the revoked five-year row does not read revoked');

    -- (reference) the ages are readable by anyone signed in, and written by nobody
    SELECT count(*) INTO n FROM clearance_kind_max_days;
    PERFORM _assert(n = 5, format('db/56 (reference): the office reads %s of the five CSA maxima', n));
    BEGIN
      INSERT INTO clearance_kind_max_days (kind, max_days, source) VALUES ('first_aid', 30, 'verify');
      v_err := NULL;
    EXCEPTION WHEN insufficient_privilege THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err IS NOT NULL, 'db/56 (reference): the office wrote a CSA maximum');
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM clearance_kind_max_days;
    PERFORM _assert(n = 0, format('db/56 (reference): a caller with no session reads %s CSA maxima', n));

    -- (pupil) a pupil who scores is not an adult missing his checks; an
    -- eighteen-year-old who plays and scores is
    PERFORM _seed_56();
    PERFORM _as(U_REGISTRAR);
    SELECT count(*) INTO n FROM clearance_register(HIL) WHERE person_id = U_SELF;
    PERFORM _assert(n = 0, format('db/56 (pupil): the register asks R Pillay, a pupil who scores, for %s clearance(s)', n));
    SELECT count(*) INTO n FROM clearance_register(HIL) WHERE person_id = U_V56 AND role = 'scorer' AND status = 'missing';
    PERFORM _assert(n = 5, format('db/56 (pupil): the register asks S Naidoo, eighteen, who plays and scores, for %s of the five checks — the pupil exclusion reaches an adult', n));

    -- (trip) nothing refuses from the paste: the driver has none of the new
    -- kinds, and the guard, which refuses only a KNOWN lapse, lets him drive
    PERFORM set_config('app.user_id', '', true);
    v_err := _trip_56(U_DRV);
    PERFORM _assert(v_err = 'ok', format('db/56 (trip): a driver missing only the new CSA checks was refused a trip (%s)', v_err));
    -- ...and a new kind he holds, once lapsed, refuses as a lapsed police clearance does (db/08's rule)
    PERFORM _as(U_REGISTRAR);
    INSERT INTO adult_clearance (person_id, school_id, kind, reference, issued_on, expires_on)
      VALUES (U_DRV, HIL, 'safeguarding_awareness', 'SAC-V56-002', d - 400, d - 35);
    PERFORM set_config('app.user_id', '', true);
    v_err := _trip_56(U_DRV);
    PERFORM _assert(v_err LIKE '%Safeguarding Awareness Certificate expired%',
      format('db/56 (trip): a driver whose recorded certificate lapsed was not refused as db/08''s guard refuses (%s)', v_err));
  END;

  -- ── 35. Safeguarding, phase 1: the DSO and the concern record (db/57) ──
  -- CSA Safeguarding Policy p15–17, p52, p63; docs/design/SAFEGUARDING_DSO.md
  -- §9.1. Nobody but a DSO of the institution that HOLDS a concern reads it:
  -- not the coach, the parent, the office, the principal, the director of
  -- sport, the league, the owner's key, the platform, a support session, the
  -- adult it names — and the audit log does not say it exists. The four
  -- layers are proved one at a time: (owner-cut) and (support-cut) take the
  -- others away and show the one left still holds, and (named) is the case
  -- where only the fourth stands between a DSO and a concern about him.
  -- Falsified once per class against a live database (section 35 alone, so
  -- no earlier section caught it first), each going red at the assertion
  -- named: safeguarding.concern.read granted to principal, schooladmin,
  -- directorofsport, guardian (→ zero); to coach with the policy's team
  -- widened to '*' (→ zero); to competitionadmin and to platformadmin with
  -- the platform cut dropped (→ zero; with the cut kept, only (catalogue)
  -- fired); the platform cut dropped (→ owner-cut); the support cut dropped
  -- (→ support-cut); the named cut dropped, the log's names-me check
  -- removed, the named DSO sent the tenant-wide notice (→ named); the
  -- policy made app_holds() (→ dso); the access_log policy dropped, the
  -- recipient cut dropped, the notices' platform cut dropped, the insert cut
  -- dropped, the SG-9 trigger off, the two role_assignment triggers off,
  -- receipts unfiltered, support allowed to begin as dso, routing blind to a
  -- named DSO and to leadership, a share returning the reporter or ignoring
  -- revocation, the office's rule removed (each → its own letter). A share
  -- outliving the close needed both of its guards removed: the close revokes
  -- every share, and share_open() also refuses a closed concern.
  DECLARE
    n        bigint;
    n2       bigint;
    n3       bigint;
    v_ok     boolean;
    v_why    text;
    v_err    text;
    v_ref1   text;  -- a parent, about his child and the physio
    v_ref2   text;  -- the 2XI coach, about the principal
    v_ref3   text;  -- a pupil, about Hilton's second DSO
    v_ref4   text;  -- a teacher at a school with no DSO
    v_ref5   text;  -- a teacher where there is nobody at all
    v_ref6   text;  -- a DSO, recording a report from The Guardian's app
    v_ref7   text;  -- a teacher, about his school's DSO, with nobody above
    v_unheld boolean;
    v_id1    uuid;
    v_id2    uuid;
    v_share  uuid;
    v_asg    uuid;
    v_json   jsonb;
    v_date   date;
    v_union  uuid;
    i        integer;
    who      uuid[];
    what     text[];
    U_DSO1   uuid := '88888888-0000-0000-0000-000000005701';  -- appointed by the principal below
    U_DSO2   uuid := '88888888-0000-0000-0000-000000005702';  -- Hilton's second DSO
    U_DSOW   uuid := '88888888-0000-0000-0000-000000005703';  -- Westville's DSO
    U_PDSO   uuid := '88888888-0000-0000-0000-000000005704';  -- the union's DSO
    U_V57    uuid := '88888888-0000-0000-0000-000000005705';  -- teacher, school with no DSO
    U_SUP57  uuid := '88888888-0000-0000-0000-000000005706';  -- a support session, simulated
    U_FAR    uuid := '88888888-0000-0000-0000-000000005707';  -- teacher, no union in his province
    U_FDSO   uuid := '88888888-0000-0000-0000-000000005708';  -- a DSO there, named in #7
    U_FAR2   uuid := '88888888-0000-0000-0000-000000005709';  -- a teacher there
    U_FDSO2  uuid := '88888888-0000-0000-0000-000000005710';  -- the other DSO there
    V57C     uuid := '57570000-0000-0000-0000-000000000003';
    U_BEKKER uuid := '88888888-0000-0000-0000-000000000011';  -- A Bekker, guardian of T Bekker
    V57      uuid := '57570000-0000-0000-0000-000000000001';
    V57B     uuid := '57570000-0000-0000-0000-000000000002';
  BEGIN
    PERFORM set_config('app.user_id', '', true);
    v_union := _seed_57();


    -- (appoint) the principal appoints a DSO; the office and the director of
    -- sport cannot; nobody makes a DSO with no institution, or with a team
    PERFORM _as(U_HEAD_M);
    INSERT INTO role_assignment (person_id, role, school_id) VALUES (U_DSO1, 'dso', HIL);
    PERFORM _as(U_DSO1);
    SELECT count(*) INTO n FROM role_assignment WHERE person_id = U_DSO1 AND role = 'dso' AND school_id = HIL AND active;
    PERFORM _assert(n = 1, 'db/57 (appoint): the principal could not appoint a DSO');
    FOREACH v_asg IN ARRAY ARRAY[U_REGISTRAR, U_SARAH] LOOP
      PERFORM _as(v_asg);
      BEGIN
        INSERT INTO role_assignment (person_id, role, school_id) VALUES (U_BURSAR, 'dso', HIL);
        v_err := NULL;
      EXCEPTION WHEN insufficient_privilege THEN v_err := SQLERRM; END;
      PERFORM _assert(v_err IS NOT NULL, format('db/57 (appoint): %s appointed a DSO', v_asg));
    END LOOP;
    PERFORM _as(U_PLAT);
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id) VALUES (U_BURSAR, 'dso', NULL);
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%must name a school%', format('db/57 (appoint): a DSO with no institution was not refused (%s)', coalesce(v_err, 'accepted')));
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id, team_code) VALUES (U_BURSAR, 'dso', HIL, '1XI');
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%names no team%', format('db/57 (appoint): a team-scoped DSO was not refused (%s)', coalesce(v_err, 'accepted')));
    -- (support) support may not take a DSO into a school
    SELECT s.ok, s.reason INTO v_ok, v_why FROM support_access_begin(HIL, 'dso', 'Verify 057: read the concerns') s;
    PERFORM _assert(NOT v_ok AND v_why = 'role_not_supportable', format('db/57 (support): a support session as dso was %s', coalesce(v_why, 'issued')));

    -- (raise) anybody signed in raises, at a school he belongs to; a child only if he can see him
    PERFORM _as(U_BEKKER);
    SELECT r.reason INTO v_why FROM safeguarding_concern_raise(HIL, 'child', ARRAY['bullying'], 'suspicion',
      'He comes home from nets upset and will not say why.', 'told', p_subject_player => P_U16B) r;
    PERFORM _assert(v_why = 'child_not_visible', format('db/57 (raise): a parent named a child he cannot see (%s)', coalesce(v_why, 'accepted')));
    SELECT r.reason INTO v_why FROM safeguarding_concern_raise(WES, 'child', ARRAY['bullying'], 'suspicion',
      'He comes home from nets upset and will not say why.', 'told') r;
    PERFORM _assert(v_why = 'not_your_school', format('db/57 (raise): a Hilton parent raised at Westville (%s)', coalesce(v_why, 'accepted')));
    SELECT r.reason INTO v_why FROM safeguarding_concern_raise(HIL, 'child', ARRAY['bullying'], 'suspicion',
      'A report The Guardian passed on to the school.', 'anonymous_app') r;
    PERFORM _assert(v_why = 'anonymous_app_is_recorded_by_a_dso', format('db/57 (raise): a parent recorded an anonymous-app report (%s)', coalesce(v_why, 'accepted')));
    -- #1: a parent, about his child, naming the physio
    SELECT r.ok, r.reference, r.unheld INTO v_ok, v_ref1, v_unheld FROM safeguarding_concern_raise(HIL, 'adult', ARRAY['physical', 'psychological'],
      'suspicion', 'He says the physio grabbed his arm hard in the change room and shouted at him.', 'told',
      p_subject_player => P_OTHER, p_subject_person => U_MEDICAL, p_occurred_where => 'Pavilion change room') r;
    PERFORM _assert(v_ok AND v_ref1 ~ '^SG-[0-9A-Z]{4}-[0-9]{4}$' AND NOT v_unheld, format('db/57 (raise): the parent''s concern was not taken (%s)', v_ref1));
    -- #2: the 2XI coach, about the principal (ticked "an adult"; the principal's appointment makes it leadership)
    PERFORM _as(U_COACH2);
    SELECT r.ok, r.reference INTO v_ok, v_ref2 FROM safeguarding_concern_raise(HIL, 'adult', ARRAY['psychological'],
      'suspicion', 'The head shouts at the U13 boys on the touchline and they are frightened of him.', 'witness',
      p_subject_person => U_HEAD_M) r;
    PERFORM _assert(v_ok, 'db/57 (raise): the coach''s concern about the principal was not taken');
    -- #3: a pupil, about Hilton's second DSO
    PERFORM _as(U_SELF);
    SELECT r.ok, r.reference INTO v_ok, v_ref3 FROM safeguarding_concern_raise(HIL, 'adult', ARRAY['sexual_harassment'],
      'suspicion', 'The DSO sends me messages late at night that make me uncomfortable.', 'victim',
      p_subject_person => U_DSO2) r;
    PERFORM _assert(v_ok, 'db/57 (raise): the pupil''s concern about the DSO was not taken');
    -- #4: a teacher at a school with no DSO; #5: one where nobody above has one either
    PERFORM _as(U_V57);
    SELECT r.ok, r.reference INTO v_ok, v_ref4 FROM safeguarding_concern_raise(V57, 'child', ARRAY['neglect'],
      'recognised', 'A boy in my side has come to nets hungry every day this week.', 'witness') r;
    PERFORM _assert(v_ok, 'db/57 (raise): a concern at a school with no DSO was not taken');
    PERFORM _as(U_FAR);
    SELECT r.ok, r.reference, r.unheld INTO v_ok, v_ref5, v_unheld FROM safeguarding_concern_raise(V57B, 'unknown', ARRAY['other'],
      'suspicion', 'Something is wrong on the bus home and the boys will not say what.', 'other') r;
    PERFORM _assert(v_ok AND v_unheld, 'db/57 (raise): a concern with nobody above was not written, or not marked unheld');
    -- #7: a teacher, about his school's DSO, with nobody above: held at the
    -- school by the other DSO, and the one it names is not told
    PERFORM _as(U_FAR2);
    SELECT r.ok, r.reference INTO v_ok, v_ref7 FROM safeguarding_concern_raise(V57C, 'dso', ARRAY['psychological'],
      'suspicion', 'The DSO humiliates the younger boys in front of the side.', 'witness', p_subject_person => U_FDSO) r;
    PERFORM _assert(v_ok, 'db/57 (raise): a concern about the DSO with nobody above was not taken');

    -- (route) the school holds a child's and leadership's; the union holds the DSO's and the DSO-less school's
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_route_57(v_ref1) = 'HIL/adult/false', format('db/57 (route): #1 went to %s', _route_57(v_ref1)));
    PERFORM _assert(_route_57(v_ref2) = 'HIL/leadership/false', format('db/57 (route): #2 went to %s — the principal''s appointment did not make it leadership', _route_57(v_ref2)));
    PERFORM _assert(_route_57(v_ref3) LIKE '%/dso/false' AND _route_57(v_ref3) NOT LIKE 'HIL/%', format('db/57 (route): #3, about a DSO, went to %s', _route_57(v_ref3)));
    PERFORM _assert(_route_57(v_ref4) NOT LIKE 'verify-057/%' AND _route_57(v_ref4) LIKE '%/child/false', format('db/57 (route): #4, at a school with no DSO, went to %s', _route_57(v_ref4)));
    PERFORM _assert(_route_57(v_ref5) = 'verify-057b/unknown/true', format('db/57 (route): #5, with nobody above, went to %s', _route_57(v_ref5)));
    PERFORM _assert(_route_57(v_ref7) = 'verify-057c/dso/true', format('db/57 (route): #7, about a DSO with nobody above, went to %s', _route_57(v_ref7)));
    v_id1 := _concern_57(v_ref1);
    v_id2 := _concern_57(v_ref2);

    -- (dso) Hilton's DSOs read Hilton's two, reporter and notes included; not the union's
    FOREACH v_asg IN ARRAY ARRAY[U_DSO1, U_DSO2] LOOP
      PERFORM _as(v_asg);
      SELECT count(*) INTO n FROM safeguarding_concern WHERE reference IN (v_ref1, v_ref2);
      SELECT count(*) INTO n2 FROM safeguarding_concern_reporter r JOIN safeguarding_concern c ON c.id = r.concern_id
       WHERE c.reference IN (v_ref1, v_ref2);
      SELECT count(*) INTO n3 FROM safeguarding_concern WHERE reference IN (v_ref3, v_ref4, v_ref5);
      PERFORM _assert(n = 2 AND n2 = 2 AND n3 = 0, format('db/57 (dso): a Hilton DSO reads %s of Hilton''s two, %s reporters, %s held elsewhere', n, n2, n3));
      SELECT count(*) INTO n FROM notification WHERE kind = 'safeguarding';
      PERFORM _assert(n = 2, format('db/57 (dso): a Hilton DSO has %s safeguarding notices, expected Hilton''s two', n));
      SELECT count(*) INTO n FROM access_log WHERE resource = 'safeguarding_concern_raise' AND school_id = HIL;
      PERFORM _assert(n = 2, format('db/57 (dso): a Hilton DSO sees %s of the two raises on the log', n));
    END LOOP;
    -- (named-dso) the DSO a concern is about reads it nowhere: it went above him
    PERFORM _as(U_DSO2);
    SELECT count(*) INTO n FROM safeguarding_concern WHERE reference = v_ref3;
    PERFORM _assert(n = 0, 'db/57 (named-dso): Hilton''s second DSO reads the concern about himself');
    -- (named) where nobody above can hold it, the other DSO reads it and is
    -- told; the DSO it names reads nothing of it, and is not told
    PERFORM _as(U_FDSO2);
    SELECT count(*) INTO n FROM safeguarding_concern WHERE reference = v_ref7;
    SELECT count(*) INTO n2 FROM notification WHERE kind = 'safeguarding' AND recipient_id = U_FDSO2;
    PERFORM _assert(n = 1 AND n2 = 1, format('db/57 (named): the other DSO reads %s of the concern about his colleague, with %s notice', n, n2));
    PERFORM _as(U_FDSO);
    SELECT (SELECT count(*) FROM safeguarding_concern) + (SELECT count(*) FROM safeguarding_concern_reporter)
         + (SELECT count(*) FROM safeguarding_concern_note) + (SELECT count(*) FROM safeguarding_share) INTO n;
    SELECT count(*) INTO n2 FROM notification WHERE kind = 'safeguarding';
    SELECT count(*) INTO n3 FROM access_log WHERE resource LIKE 'safeguarding%';
    PERFORM _assert(n = 0 AND n2 = 0 AND n3 = 0 AND safeguarding_concern_open(_concern_57(v_ref7)) IS NULL
                    AND NOT EXISTS (SELECT 1 FROM safeguarding_inbox()),
      format('db/57 (named): the DSO a concern names reads %s rows, %s notices, %s log rows of it', n, n2, n3));

    -- (union) the union's DSO reads what is held there, and a leadership notice — never the school's record
    PERFORM _as(U_PDSO);
    SELECT count(*) INTO n FROM safeguarding_concern WHERE reference IN (v_ref3, v_ref4);
    SELECT count(*) INTO n2 FROM safeguarding_concern WHERE reference IN (v_ref1, v_ref2, v_ref5);
    PERFORM _assert(n = 2 AND n2 = 0, format('db/57 (union): the provincial DSO reads %s of the two held at the union and %s held elsewhere', n, n2));
    SELECT count(*) INTO n FROM notification WHERE kind = 'safeguarding';
    SELECT count(*) INTO n2 FROM notification WHERE kind = 'safeguarding' AND body LIKE '%leadership of Hilton College%';
    PERFORM _assert(n = 3 AND n2 = 1, format('db/57 (union): the provincial DSO has %s notices (expected 3), %s about Hilton''s leadership (expected 1)', n, n2));
    PERFORM _assert(safeguarding_concern_open(v_id2) IS NULL, 'db/57 (union): the provincial DSO opened the leadership concern the school holds');
    -- (other-dso) Westville's DSO reads none of Hilton's
    PERFORM _as(U_DSOW);
    SELECT count(*) INTO n FROM safeguarding_concern;
    SELECT count(*) INTO n2 FROM notification WHERE kind = 'safeguarding';
    PERFORM _assert(n = 0 AND n2 = 0, format('db/57 (other-dso): Westville''s DSO reads %s concerns and %s notices', n, n2));

    -- (zero) everyone else reads nothing of it: a row, a hidden log row, a notice.
    -- A row on the log that is NOT a safeguarding read is written first, so an
    -- auditor's zero below is the policy, not an empty log.
    PERFORM _as(U_COACH2);
    PERFORM log_restricted_read('players', ARRAY[P_OTHER], ARRAY['born'], HIL);
    who  := ARRAY[U_COACH2, U_BEKKER, U_REGISTRAR, U_HEAD_M, U_SARAH, U_LEAGUE, U_OWNER, U_PLAT, U_MEDICAL, U_SELF, U_V57, U_FAR];
    what := ARRAY['the 2XI coach (a reporter)', 'the parent of the named child (a reporter)', 'the office', 'the principal (named)',
                  'the director of sport', 'the league', 'the owner''s key', 'the platform', 'the physio (named)',
                  'the pupil (a reporter)', 'the teacher (a reporter)', 'the far teacher (a reporter)'];
    FOR i IN 1 .. array_length(who, 1) LOOP
      PERFORM _as(who[i]);
      SELECT (SELECT count(*) FROM safeguarding_concern) + (SELECT count(*) FROM safeguarding_concern_reporter)
           + (SELECT count(*) FROM safeguarding_concern_note) + (SELECT count(*) FROM safeguarding_share) INTO n;
      SELECT count(*) INTO n2 FROM access_log WHERE resource LIKE 'safeguarding%';
      SELECT count(*) INTO n3 FROM notification WHERE kind = 'safeguarding';
      PERFORM _assert(n = 0 AND n2 = 0 AND n3 = 0,
        format('db/57 (zero): %s reads %s safeguarding rows, %s hidden log rows, %s safeguarding notices', what[i], n, n2, n3));
      PERFORM _assert(safeguarding_concern_open(v_id1) IS NULL AND safeguarding_family(v_id1) IS NULL
                      AND NOT EXISTS (SELECT 1 FROM safeguarding_inbox()),
        format('db/57 (zero): %s opened a concern through a function', what[i]));
    END LOOP;
    -- ...and the auditors among them still read the rest of the log (the zero is the cut, not an empty log)
    FOREACH v_asg IN ARRAY ARRAY[U_REGISTRAR, U_HEAD_M, U_SARAH, U_OWNER, U_PLAT] LOOP
      PERFORM _as(v_asg);
      SELECT count(*) INTO n FROM access_log WHERE resource = 'players' AND school_id = HIL;
      PERFORM _assert(n >= 1, format('db/57 (hidden): an auditor (%s) reads no log at all — the zero above proves nothing', v_asg));
    END LOOP;
    -- ...and the physio, named, is a live account: she reads the injuries she treats
    PERFORM _as(U_MEDICAL);
    SELECT count(*) INTO n FROM injury_masked WHERE notes IS NOT NULL;
    PERFORM _assert(n > 0, 'db/57 (zero): the physio reads no injury — her zero above proves nothing');

    -- (support) a support session, as a coach and as the office, reads nothing either
    PERFORM _as(U_PLAT);
    FOREACH v_why IN ARRAY ARRAY['coach', 'schooladmin'] LOOP
      SELECT s.ok, s.reason INTO v_ok, v_err FROM support_access_begin(HIL, v_why, 'Verify 057: ticket 5757 about the roster',
                                                                       CASE v_why WHEN 'coach' THEN '2XI' END) s;
      PERFORM _assert(v_ok OR v_err = 'already_live', format('db/57 (support): a session as %s was not begun (%s)', v_why, v_err));
    END LOOP;
    PERFORM _assert(app_support_access_id(HIL) IS NOT NULL, 'db/57 (support): no support session is live at Hilton');
    SELECT (SELECT count(*) FROM safeguarding_concern) + (SELECT count(*) FROM safeguarding_concern_note) INTO n;
    SELECT count(*) INTO n2 FROM access_log WHERE resource LIKE 'safeguarding%';
    SELECT count(*) INTO n3 FROM notification WHERE kind = 'safeguarding';
    PERFORM _assert(n = 0 AND n2 = 0 AND n3 = 0, format('db/57 (support): a support session reads %s rows, %s hidden log rows, %s notices', n, n2, n3));

    -- (owner-cut) the owner's key with the capability granted back still reads nothing:
    -- the platform-wide cut on its own
    PERFORM set_config('app.user_id', '', true);
    PERFORM _owner_grant_57(true);
    PERFORM _as(U_OWNER);
    PERFORM _assert(app_can('safeguarding.concern.read', HIL, NULL::text, '00000000-0000-0000-0000-000000000000'::uuid, NULL::uuid),
      'db/57 (owner-cut): the owner''s key does not hold the capability granted back — the zero below proves nothing');
    SELECT count(*) INTO n FROM safeguarding_concern;
    SELECT count(*) INTO n2 FROM access_log WHERE resource LIKE 'safeguarding%';
    SELECT count(*) INTO n3 FROM notification WHERE kind = 'safeguarding';
    PERFORM _assert(n = 0 AND n2 = 0 AND n3 = 0 AND safeguarding_concern_open(v_id1) IS NULL,
      format('db/57 (owner-cut): the owner''s key, holding the capability, reads %s concerns, %s hidden log rows, %s notices', n, n2, n3));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _owner_grant_57(false);

    -- (support-cut) a session as dso, for an account with no platform-wide
    -- assignment, reads nothing; ended, the same assignment reads Hilton's
    PERFORM _support_dso_57(false);
    PERFORM _as(U_SUP57);
    PERFORM _assert(NOT app_is_platform_wide() AND app_support_access_id(HIL) IS NOT NULL,
      'db/57 (support-cut): the simulated session is not a support session without a platform-wide assignment');
    SELECT count(*) INTO n FROM safeguarding_concern;
    SELECT count(*) INTO n2 FROM access_log WHERE resource LIKE 'safeguarding%';
    SELECT count(*) INTO n3 FROM notification WHERE kind = 'safeguarding';
    PERFORM _assert(n = 0 AND n2 = 0 AND n3 = 0 AND safeguarding_concern_open(v_id1) IS NULL,
      format('db/57 (support-cut): a support session as dso reads %s concerns, %s hidden log rows, %s notices', n, n2, n3));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _support_dso_57(true);
    PERFORM _as(U_SUP57);
    SELECT count(*) INTO n FROM safeguarding_concern WHERE reference IN (v_ref1, v_ref2);
    SELECT count(*) INTO n3 FROM notification WHERE kind = 'safeguarding';
    PERFORM _assert(n = 2 AND n3 >= 2, format('db/57 (support-cut): with the session ended the same assignment reads %s of Hilton''s two and %s notices — the zero above proves nothing', n, n3));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _revoke(U_SUP57);

    -- (receipt) the reporter keeps a reference and a time, and nothing else
    PERFORM _as(U_BEKKER);
    SELECT count(*), max(reference) INTO n, v_why FROM my_concern_receipts();
    PERFORM _assert(n = 1 AND v_why = v_ref1, format('db/57 (receipt): the parent has %s receipts (%s), expected his one', n, v_why));
    PERFORM _as(U_SELF);
    SELECT count(*), max(reference) INTO n, v_why FROM my_concern_receipts();
    PERFORM _assert(n = 1 AND v_why = v_ref3, format('db/57 (receipt): the pupil has %s receipts (%s), expected his one', n, v_why));
    PERFORM _as(U_DSO1);
    SELECT count(*) INTO n FROM my_concern_receipts();
    PERFORM _assert(n = 0, 'db/57 (receipt): a DSO has a receipt for a concern somebody else raised');

    -- (contacts) the card: Hilton's DSOs to a Hilton parent; the union's at a school with none
    PERFORM _as(U_BEKKER);
    SELECT count(*) INTO n FROM dso_contacts(HIL) WHERE held_at = 'school' AND name IN ('V57 DSO One', 'V57 DSO Two');
    PERFORM _assert(n = 2, format('db/57 (contacts): a Hilton parent sees %s of Hilton''s two DSOs', n));
    SELECT count(*) INTO n FROM dso_contacts(WES);
    PERFORM _assert(n = 0, 'db/57 (contacts): a Hilton parent reads Westville''s DSOs');
    PERFORM _as(U_V57);
    SELECT count(*) INTO n FROM dso_contacts() WHERE held_at = 'union' AND name = 'V57 Provincial DSO';
    PERFORM _assert(n = 1, 'db/57 (contacts): a school with no DSO is not shown the union''s');

    -- (open) the DSO opens the record — account, reporter — and the read is on the log
    PERFORM _as(U_DSO1);
    v_json := safeguarding_concern_open(v_id1);
    PERFORM _assert(v_json->>'account' LIKE '%grabbed his arm%' AND v_json->'reporter'->>'name' = 'A Bekker'
                    AND v_json->'subjectPlayer'->>'name' = 'T Bekker' AND NOT (v_json ? 'born'),
      format('db/57 (open): the DSO''s open is not the record (%s)', left(v_json::text, 200)));
    SELECT count(*) INTO n FROM access_log WHERE resource = 'safeguarding_concern' AND v_id1 = ANY (record_ids);
    PERFORM _assert(n = 1, format('db/57 (open): the DSO''s open left %s log rows, expected 1', n));
    -- (family) the child's guardians and contacts, through the open concern, logged
    v_json := safeguarding_family(v_id1);
    PERFORM _assert(v_json->'guardians' @> '[{"name": "A Bekker"}]'::jsonb,
      format('db/57 (family): the DSO does not reach the child''s guardian (%s)', v_json::text));
    SELECT count(*) INTO n FROM access_log WHERE resource = 'safeguarding_family' AND v_id1 = ANY (record_ids);
    PERFORM _assert(n = 1, 'db/57 (family): the DSO''s reach into the family is not on the log');

    -- (clock) 24 hours, red after; the NDSO informed stops it; a report from The Guardian's app runs 72
    SELECT count(*) INTO n FROM safeguarding_inbox() WHERE reference = v_ref1 AND clock_hours = 24 AND NOT overdue;
    PERFORM _assert(n = 1, 'db/57 (clock): a fresh concern is not on a 24-hour clock, or is already overdue');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _age_concern_57(v_id1, 25);
    PERFORM _as(U_DSO1);
    SELECT count(*) INTO n FROM safeguarding_inbox() WHERE reference = v_ref1 AND overdue AND hours_open >= 25;
    PERFORM _assert(n = 1, 'db/57 (clock): a concern 25 hours old is not overdue');
    SELECT r.ok INTO v_ok FROM safeguarding_note(v_id1, 'ndso_informed', 'NDSO told by phone at 09:10') r;
    SELECT count(*) INTO n FROM safeguarding_inbox() WHERE reference = v_ref1 AND clock_stopped AND NOT overdue;
    PERFORM _assert(v_ok AND n = 1, 'db/57 (clock): informing the NDSO did not stop the clock');
    SELECT r.ok, r.reference INTO v_ok, v_ref6 FROM safeguarding_concern_raise(HIL, 'unknown', ARRAY['bullying'], 'suspicion',
      'The Guardian passed on an anonymous report of bullying in the U14 side.', 'anonymous_app') r;
    SELECT count(*) INTO n FROM safeguarding_inbox() WHERE reference = v_ref6 AND clock_hours = 72;
    PERFORM _assert(v_ok AND n = 1, 'db/57 (clock): a report from The Guardian''s app is not on a 72-hour clock');
    SELECT count(*) INTO n FROM access_log WHERE resource = 'safeguarding_inbox';
    PERFORM _assert(n >= 1, 'db/57 (clock): the inbox read is not on the log');

    -- (share) need to know: to a named person, the parts named, until a date, and never the reporter
    SELECT r.reason INTO v_why FROM safeguarding_share(v_id1, U_SELF, ARRAY['summary'], now() + interval '1 day', 'The boy needs to know it is being handled') r;
    PERFORM _assert(v_why = 'recipient_is_pupil', format('db/57 (share): a share to a pupil was %s', coalesce(v_why, 'made')));
    SELECT r.reason INTO v_why FROM safeguarding_share(v_id1, U_MEDICAL, ARRAY['summary'], now() + interval '1 day', 'She should know what is said of her') r;
    PERFORM _assert(v_why = 'recipient_is_subject', format('db/57 (share): a share to the adult it names was %s', coalesce(v_why, 'made')));
    SELECT r.reason INTO v_why FROM safeguarding_share(v_id1, U_SARAH, ARRAY['summary'], now() + interval '31 days', 'The director of sport runs the fixture list') r;
    PERFORM _assert(v_why = 'open_until_out_of_range', format('db/57 (share): a 31-day share was %s', coalesce(v_why, 'made')));
    SELECT r.ok, r.share_id INTO v_ok, v_share FROM safeguarding_share(v_id1, U_SARAH, ARRAY['summary', 'account'],
      now() + interval '1 day', 'The director of sport must keep the physio away from the U16s this week') r;
    PERFORM _assert(v_ok, 'db/57 (share): the DSO could not share with the director of sport');
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM notification WHERE kind = 'safeguarding' AND recipient_id = U_SARAH;
    PERFORM _assert(n = 1, format('db/57 (share): the director of sport has %s share notices, expected 1', n));
    SELECT (SELECT count(*) FROM safeguarding_concern) + (SELECT count(*) FROM safeguarding_share) INTO n;
    PERFORM _assert(n = 0, 'db/57 (share): a share opened the tables to its person');
    SELECT count(*) INTO n FROM my_safeguarding_shares() WHERE id = v_share;
    v_json := safeguarding_share_open(v_share);
    PERFORM _assert(n = 1 AND v_json->>'account' LIKE '%grabbed his arm%' AND v_json ? 'summary'
                    AND NOT (v_json ? 'child') AND NOT (v_json ? 'actions') AND NOT (v_json ? 'reporter')
                    AND v_json::text NOT LIKE '%A Bekker%',
      format('db/57 (share): the share did not open to exactly what was named (%s)', left(v_json::text, 300)));
    PERFORM _as(U_HEAD_M);
    SELECT count(*) INTO n FROM notification WHERE kind = 'safeguarding';
    PERFORM _assert(n = 0 AND safeguarding_share_open(v_share) IS NULL,
      'db/57 (share): the principal reads the director of sport''s share, or its notice');
    PERFORM _as(U_DSO1);
    SELECT count(*) INTO n FROM access_log WHERE resource = 'safeguarding_share' AND v_share = ANY (record_ids);
    PERFORM _assert(n = 1, 'db/57 (share): opening a share is not on the log');
    -- ...and it closes: on revocation, on expiry, and with the concern, on the next statement
    SELECT r.ok INTO v_ok FROM safeguarding_share_revoke(v_share) r;
    PERFORM _as(U_SARAH);
    PERFORM _assert(v_ok AND safeguarding_share_open(v_share) IS NULL AND NOT EXISTS (SELECT 1 FROM my_safeguarding_shares()),
      'db/57 (share): a revoked share still opens');
    PERFORM _as(U_DSO1);
    SELECT r.share_id INTO v_share FROM safeguarding_share(v_id1, U_SARAH, ARRAY['summary'], now() + interval '1 day', 'A second share, to let lapse') r;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _expire_share_57(v_share);
    PERFORM _as(U_SARAH);
    PERFORM _assert(safeguarding_share_open(v_share) IS NULL, 'db/57 (share): a lapsed share still opens');
    PERFORM _as(U_DSO1);
    SELECT r.share_id INTO v_share FROM safeguarding_share(v_id1, U_SARAH, ARRAY['summary'], now() + interval '1 day', 'A third share, to end with the concern') r;
    PERFORM _as(U_SARAH);
    PERFORM _assert(safeguarding_share_open(v_share) IS NOT NULL, 'db/57 (share): the third share does not open — the closes below prove nothing');
    PERFORM _as(U_DSO1);
    SELECT r.ok, r.retain_until INTO v_ok, v_date FROM safeguarding_close(v_id1, 'supported', false, 'Physio moved to the 1XI only') r;
    PERFORM _assert(v_ok AND v_date = ((now() AT TIME ZONE 'Africa/Johannesburg') + interval '3 years')::date,
      format('db/57 (close): the close was refused or kept it until %s, not three years', v_date));
    PERFORM _as(U_SARAH);
    PERFORM _assert(safeguarding_share_open(v_share) IS NULL, 'db/57 (share): a share outlived its concern''s close');
    -- the account is written once
    PERFORM _as(U_DSO1);
    BEGIN
      UPDATE safeguarding_concern SET account = 'Changed by the DSO afterwards.' WHERE id = v_id2;
      v_err := NULL;
    EXCEPTION WHEN insufficient_privilege THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err IS NOT NULL, 'db/57 (share): the application edited a concern''s account');

    -- (notice) SG-9: a private notice to a pupil is the system's alone; and
    -- nobody publishes a safeguarding notice through the publish route
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_notice_57(U_SELF, 'lift') = 'refused', 'db/57 (notice): a private lift notice to a pupil was written');
    PERFORM _assert(_notice_57(U_SELF, 'system') = 'ok', 'db/57 (notice): the system''s own notice to a pupil was refused');
    PERFORM _assert(_notice_57(U_SARAH, 'lift') = 'ok', 'db/57 (notice): a private notice to an adult was refused');
    PERFORM _as(U_SARAH);
    BEGIN
      INSERT INTO notification (school_id, scope_level, kind, title, body, required_capability)
        VALUES (HIL, 'school', 'safeguarding', 'A safeguarding concern has been raised', 'Forged', 'safeguarding.concern.read');
      v_err := NULL;
    EXCEPTION WHEN insufficient_privilege THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err IS NOT NULL, 'db/57 (notice): the director of sport published a safeguarding notice');
    -- (a 'fixture': since db/91 a 'notice' is the news_post trigger's alone, §70)
    INSERT INTO notification (school_id, scope_level, kind, title, body) VALUES (HIL, 'school', 'fixture', 'Verify 057', 'Ordinary');
    SELECT count(*) INTO n FROM notification WHERE title = 'Verify 057' AND kind = 'fixture' AND recipient_id IS NULL;
    PERFORM _assert(n = 1, 'db/57 (notice): the director of sport cannot publish an ordinary notice — the refusal above proves nothing');

    -- (guard) the principal, named in an open leadership concern, cannot end a
    -- DSO's appointment, by any column; neither can the office, ever; the
    -- provincial DSO can; a DSO at the school cannot
    PERFORM _as(U_HEAD_M);
    SELECT a.id INTO v_asg FROM role_assignment a WHERE a.person_id = U_DSO2 AND a.role = 'dso' AND a.active;
    PERFORM _assert(v_asg IS NOT NULL, 'db/57 (guard): the principal cannot read the DSO''s appointment');
    BEGIN
      UPDATE role_assignment SET active = false WHERE id = v_asg;
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%cannot be ended from here%', format('db/57 (guard): the principal ended a DSO''s appointment (%s)', coalesce(v_err, 'ended')));
    BEGIN
      UPDATE role_assignment SET valid_until = current_date WHERE id = v_asg;
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%cannot be ended from here%', format('db/57 (guard): the principal dated out a DSO''s appointment (%s)', coalesce(v_err, 'dated out')));
    PERFORM _as(U_REGISTRAR);
    BEGIN
      UPDATE role_assignment SET active = false WHERE id = v_asg;
      v_err := NULL;
    EXCEPTION WHEN check_violation THEN v_err := SQLERRM; END;
    PERFORM _assert(v_err LIKE '%cannot be ended from here%', format('db/57 (guard): the office ended a DSO''s appointment (%s)', coalesce(v_err, 'ended')));
    PERFORM _as(U_DSO1);
    SELECT e.ok, e.reason INTO v_ok, v_why FROM safeguarding_dso_end(v_asg) e;
    PERFORM _assert(NOT v_ok AND v_why = 'not_permitted', 'db/57 (guard): a DSO at the school ended another''s appointment');
    PERFORM _as(U_PDSO);
    SELECT e.ok INTO v_ok FROM safeguarding_dso_end(v_asg) e;
    PERFORM _as(U_DSO2);
    SELECT count(*) INTO n FROM safeguarding_concern;
    PERFORM _assert(v_ok AND n = 0, format('db/57 (guard): the provincial DSO could not end the appointment, or it still reads %s', n));
    -- with the leadership concern closed, the principal may end one again
    PERFORM _as(U_DSO1);
    SELECT r.ok INTO v_ok FROM safeguarding_close(v_id2, 'handed_to_union', true) r;
    PERFORM _assert(v_ok, 'db/57 (guard): the DSO could not close the leadership concern');
    PERFORM _as(U_HEAD_M);
    SELECT a.id INTO v_asg FROM role_assignment a WHERE a.person_id = U_DSO1 AND a.role = 'dso' AND a.active;
    UPDATE role_assignment SET active = false WHERE id = v_asg;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, 'db/57 (guard): with nothing open that names him, the principal cannot end a DSO''s appointment');

    -- (catalogue) the four capabilities are dso's alone; the owner's key holds
    -- none. Last, so a falsification that grants one elsewhere is caught by
    -- the reads above first.
    PERFORM _assert((SELECT string_agg(DISTINCT role, ',') FROM role_capability WHERE capability LIKE 'safeguarding.%') = 'dso',
      'db/57 (catalogue): a role other than dso holds a safeguarding capability');
    PERFORM _assert((SELECT count(*) FROM role_capability WHERE role = 'dso' AND capability LIKE 'safeguarding.%') = 4,
      'db/57 (catalogue): dso does not hold the four safeguarding capabilities');
  END;

  -- ── 36. A boy's fitness is his health (SCRBRD-117, db/58) ─────────
  -- player.fitness was unmasked under player.profile.read, which a pupil holds
  -- across his side. Masked behind medical.status.read on his own team: a
  -- team-mate and another side's coach read NULL, the physio, his coach's
  -- tier, his parent and he himself read it. db/58 undone (fitness taken out
  -- of the mask list) and this file run: (pupil) and (coach) failed.
  DECLARE
    n       bigint;
    v_fit   text;
    U_BEKKER uuid := '88888888-0000-0000-0000-000000000011';
  BEGIN
    -- (pupil) a pupil reads the side, and nobody's fitness but his own
    PERFORM _as(U_PUPIL);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED AND fitness IS NULL;
    PERFORM _assert(n = 1, 'db/58 (pupil): a pupil reads a team-mate''s fitness, or cannot read the side at all');
    SELECT count(*) INTO n FROM player_masked WHERE fitness IS NOT NULL;
    PERFORM _assert(n = 0, format('db/58 (pupil): a pupil reads %s players'' fitness', n));
    PERFORM _as(U_SELF);
    SELECT fitness INTO v_fit FROM player_masked WHERE id = P_INJURED;
    SELECT count(*) INTO n FROM player_masked WHERE id <> P_INJURED AND fitness IS NOT NULL;
    PERFORM _assert(v_fit = 'injured' AND n = 0, format('db/58 (pupil): R Pillay reads his own fitness as %s and %s team-mates''', v_fit, n));
    -- (coach) another side's coach sees the boy on the roster and not his
    -- fitness. The U14A coach: section 33 granted the 2XI coach an enquiry
    -- for R Pillay, which reads the status tier (db/55 as amended).
    PERFORM _as('88888888-0000-0000-0000-00000000000b'::uuid);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED AND fitness IS NULL;
    PERFORM _assert(n = 1, 'db/58 (coach): the U14A coach reads a 1XI boy''s fitness, or cannot see him on the roster');
    -- (staff) the physio and the director of sport read it; a parent reads his own child's
    FOREACH v_fit IN ARRAY ARRAY[U_MEDICAL::text, U_SARAH::text] LOOP
      PERFORM _as(v_fit::uuid);
      SELECT count(*) INTO n FROM player_masked WHERE id = P_INJURED AND fitness = 'injured';
      PERFORM _assert(n = 1, format('db/58 (staff): %s does not read R Pillay''s fitness', v_fit));
    END LOOP;
    PERFORM _as(U_BEKKER);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_OTHER AND fitness IS NOT NULL;
    PERFORM _assert(n = 1, 'db/58 (staff): A Bekker does not read his own son''s fitness');
  END;

  PERFORM set_config('app.user_id', '', true);

  -- ── 37. The signed-out read path (SCRBRD-083 phase 1, db/59) ──
  -- A public request runs as nobody: app.user_id empty, every base table
  -- denied, and only db/59's four SECURITY DEFINER reads answer — and only
  -- for a fixture with a published side. What they return is the rule's
  -- inputs for the API (it applies publicName() and the pseudonyms; see
  -- services/api/public/); here it is held that the inputs are the right
  -- ones: each boy's facts for HIS side, his side's publication, no date of
  -- birth, no reason, no kind that is a conduct matter, and that a
  -- withdrawal, a mark and a publication flip change the next call.
  DECLARE
    ids      jsonb := _seed_59();
    M_ON     uuid;
    M_OFF    uuid;
    U_OFFICE uuid := '88888888-0000-0000-0000-00000000000c';   -- registrar, guardian.link.manage at Hilton
    v_facts  jsonb;
    v_pub    boolean;
    v_grp    text;
    v_keys   text;
    t        text;
    h        record;
  BEGIN
    M_ON := (ids->>'m_on')::uuid;
    M_OFF := (ids->>'m_off')::uuid;
    PERFORM set_config('app.user_id', '', true);

    -- (unpublished) nothing, for nobody and for a signed-in reader alike
    SELECT (SELECT count(*) FROM public_match_header(M_ON)) + (SELECT count(*) FROM public_match_log(M_ON, 0))
         + (SELECT count(*) FROM public_match_people(M_ON)) + (SELECT count(*) FROM public_shot_sectors(M_ON)) INTO n;
    PERFORM _assert(n = 0, format('db/59 (unpublished): a fixture nobody published answered %s rows', n));
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM public_match_log(M_ON, 0);
    PERFORM _assert(n = 0, format('db/59 (unpublished-signed-in): a signed-in reader got %s public rows of an unpublished fixture', n));

    -- the rule's records, through their own doors — starting from every
    -- Hilton age group named (section 25 leaves some switched off)
    PERFORM _as(U_SARAH);
    FOR v_grp IN SELECT o.age_group FROM public_names_off o WHERE o.school_id = HIL AND o.names_off LOOP
      PERFORM public_names_off_set(HIL, v_grp, false);
    END LOOP;
    PERFORM _as((ids->>'g_named')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set((ids->>'named')::uuid, true, 'public-names-2026-09') s;
    PERFORM _assert(v_ok, format('db/59: the named boy''s guardian could not consent (%s)', v_reason));
    FOREACH t IN ARRAY ARRAY['marked', 'up', 'wes'] LOOP
      PERFORM _as((ids->>('g_' || t))::uuid);
      SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_name_consent_set((ids->>t)::uuid, true, 'public-names-2026-09') s;
      PERFORM _assert(v_ok, format('db/59: %s''s guardian could not consent (%s)', t, v_reason));
    END LOOP;
    PERFORM _as(U_SARAH);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM player_never_public_set((ids->>'marked')::uuid, 'a court order') s;
    PERFORM _assert(v_ok, format('db/59: the mark could not be set (%s)', v_reason));
    v_grp := birth_age_group(_born_of((ids->>'up')::uuid));
    PERFORM _assert(v_grp IS NOT NULL AND v_grp NOT IN ('open'), format('db/59: the boy playing up is %s by birth', v_grp));
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_names_off_set(HIL, v_grp, true) s;
    PERFORM _assert(v_ok, format('db/59: names could not be switched off for %s (%s)', v_grp, v_reason));
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(M_ON, 'home', true) s;
    PERFORM _assert(v_ok, format('db/59: Hilton could not publish its side (%s)', v_reason));

    -- (signed-out) nobody reads a base table; the definers answer
    PERFORM set_config('app.user_id', '', true);
    FOREACH t IN ARRAY ARRAY['player', 'match', 'ball_event', 'public_name_consent', 'player_never_public',
                             'fixture_publication', 'assignment_subject', 'match_toss', 'school'] LOOP
      EXECUTE format('SELECT count(*) FROM %I', t) INTO n;
      PERFORM _assert(n = 0 AND _count_rows(t) > 0, format('db/59 (signed-out): nobody reads %s of %s''s %s rows', n, t, _count_rows(t)));
    END LOOP;
    SELECT * INTO h FROM public_match_header(M_ON);
    PERFORM _assert(h.home_published AND NOT h.away_published AND h.away_on_platform AND h.home_label = 'Hilton College 1XI'
                    AND h.served_on = to_char(sa_today(), 'YYYY-MM-DD'),
      format('db/59 (header): %s', row(h.home_published, h.away_published, h.away_on_platform, h.home_label, h.served_on)::text));

    -- (people) each boy the log names, his facts for his side, his side's publication
    SELECT count(*) INTO n FROM public_match_people(M_ON);
    PERFORM _assert(n = 5, format('db/59 (people): %s people for a log naming four Hilton boys, a typed one and a Westville boy — expected 5 (no typed name)', n));
    SELECT string_agg(DISTINCT k, ',' ORDER BY k) INTO v_keys FROM public_match_people(M_ON) pp, jsonb_object_keys(pp.facts) k;
    PERFORM _assert(v_keys = 'consents,namesOff,neverPublic', format('db/59 (facts-clean): the facts carry %s', v_keys));
    SELECT pp.facts, pp.school_published INTO v_facts, v_pub FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'named')::uuid;
    PERFORM _assert(v_pub AND v_facts->'consents'->0->>'competent' = 'true' AND v_facts->'consents'->0->>'endedOn' IS NULL
                    AND (v_facts->>'neverPublic')::boolean = false AND (v_facts->>'namesOff')::boolean = false,
      format('db/59 (named): %s, published %s', v_facts, v_pub));
    SELECT pp.facts INTO v_facts FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'marked')::uuid;
    PERFORM _assert((v_facts->>'neverPublic')::boolean, format('db/59 (marked): the mark is not in his facts: %s', v_facts));
    SELECT pp.facts INTO v_facts FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'none')::uuid;
    PERFORM _assert(jsonb_array_length(v_facts->'consents') = 0, format('db/59 (nothing): %s', v_facts));
    SELECT pp.facts INTO v_facts FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'up')::uuid;
    PERFORM _assert((v_facts->>'namesOff')::boolean, format('db/59 (playing up): names off for his own age group did not hold him back: %s', v_facts));
    SELECT pp.school_published INTO v_pub FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'wes')::uuid;
    PERFORM _assert(NOT v_pub, 'db/59 (L5): the Westville boy reads as published while only Hilton published');

    -- (log) every event but the Law 41 suspension, every field by name
    SELECT count(*) INTO n FROM public_match_log(M_ON, 0);
    PERFORM _assert(n = 6, format('db/59 (log): %s events, expected the 7 written less the suspension', n));
    SELECT count(*) INTO n FROM public_match_log(M_ON, 0) l WHERE l.kind = 'bowler_suspended';
    PERFORM _assert(n = 0, 'db/59 (log): a Law 41 suspension of one boy reached the public log');
    -- (db/78, SCRBRD-139: a ball's shot and `place`, the material of the
    -- words for where it went, which the API makes and drops; §57 holds them
    -- key for key)
    SELECT string_agg(DISTINCT k, ',') INTO v_keys FROM public_match_log(M_ON, 0) l, jsonb_object_keys(l.detail) k
     WHERE k NOT IN ('battingTeam', 'bowlingTeam', 'teamKey', 'bowlingTeamKey', 'squad', 'bowlingSquad', 'overs', 'target',
                     'striker', 'nonStriker', 'bowler', 'dismissed', 'captainConsent', 'fielder', 'freeHit', 'nbRuns', 'nbType',
                     'outAt', 'facesNext', 'notInOver', 'runs', 'toBattingTeam', 'batter', 'reason', 'confirmed', 'shot', 'place');
    PERFORM _assert(v_keys IS NULL, format('db/59 (log): the detail carries %s', v_keys));
    SELECT count(*) INTO n FROM public_match_log(M_ON, 0) l WHERE l.detail ? 'twelfthMan' OR l.detail ? 'captureProfile';
    PERFORM _assert(n = 0, 'db/59 (log): the twelfth man or a capture profile reached the public log');
    SELECT count(*) INTO n FROM public_match_log(M_ON, 4);
    PERFORM _assert(n = 2, format('db/59 (since): %s events after seq 4, expected 2', n));
    SELECT count(*) INTO n FROM public_shot_sectors(M_ON) WHERE sector = 9 AND runs = 4 AND shots = 1;
    PERFORM _assert(n = 1, 'db/59 (sectors): the four through sector 9 is not the team''s');

    -- (off-platform) a typed opposition is nobody's to name
    PERFORM _as(U_SARAH);
    SELECT s.ok INTO v_ok FROM fixture_publish(M_OFF, 'home', true) s;
    PERFORM set_config('app.user_id', '', true);
    SELECT * INTO h FROM public_match_header(M_OFF);
    PERFORM _assert(NOT h.away_on_platform AND h.away_label = 'Kearsney College 1XI',
      format('db/59 (off-platform): %s', row(h.away_on_platform, h.away_label)::text));
    SELECT count(*) INTO n FROM public_match_people(M_OFF);
    PERFORM _assert(n = 1, format('db/59 (off-platform): %s people, expected only the Hilton boy — typed names have no row', n));

    -- (flips) the next call sees each change
    PERFORM _as(U_OFFICE);
    SELECT s.ok, s.reason INTO v_ok, v_reason
      FROM public_name_consent_set((ids->>'named')::uuid, false, 'public-names-2026-09', (ids->>'g_named')::uuid) s;
    PERFORM _assert(v_ok, format('db/59: the office could not withdraw a consent (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT pp.facts INTO v_facts FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'named')::uuid;
    PERFORM _assert(v_facts->'consents'->0->>'endedOn' = to_char(sa_today(), 'YYYY-MM-DD'),
      format('db/59 (withdrawal): the next call still has a live consent: %s', v_facts));
    PERFORM _as(U_SARAH);
    PERFORM player_never_public_end((ids->>'marked')::uuid);
    PERFORM set_config('app.user_id', '', true);
    SELECT pp.facts INTO v_facts FROM public_match_people(M_ON) pp WHERE pp.player_id = (ids->>'marked')::uuid;
    PERFORM _assert(NOT (v_facts->>'neverPublic')::boolean, format('db/59 (mark ended): %s', v_facts));
    PERFORM _as(U_SARAH);
    PERFORM fixture_publish(M_ON, 'home', false);
    PERFORM set_config('app.user_id', '', true);
    SELECT (SELECT count(*) FROM public_match_header(M_ON)) + (SELECT count(*) FROM public_match_log(M_ON, 0))
         + (SELECT count(*) FROM public_match_people(M_ON)) + (SELECT count(*) FROM public_shot_sectors(M_ON)) INTO n;
    PERFORM _assert(n = 0, format('db/59 (withdrawn): a fixture Hilton took back down answered %s rows', n));

    -- (grants) the application, and not PUBLIC or a managed host's API roles
    FOREACH t IN ARRAY ARRAY['public_match_header(uuid)', 'public_match_log(uuid,integer)', 'public_match_people(uuid)',
                             'public_shot_sectors(uuid)'] LOOP
      PERFORM _assert(has_function_privilege('scrbrd_app', t::regprocedure, 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) x
                                       WHERE p.oid = t::regprocedure AND x.grantee = 0 AND x.privilege_type = 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon', 'authenticated')
                                         AND has_function_privilege(r.oid, t::regprocedure, 'EXECUTE')),
        format('db/59 (grants): %s is not the application''s alone', t));
    END LOOP;
  END;

  -- ── 38. Workload phase 1: consent and the count (SCRBRD-110, db/60) ──
  -- The nets band is ordinary processing: a coach records it for a boy with no
  -- health consent, and his figure is an estimate. The table refuses a count
  -- for a net and a band for a paper-scored match. One figure per session,
  -- the bowler's own over the coach's; a paper match on a day the log scored
  -- is marked, not dropped. The EWMA word agrees with workload()'s thresholds
  -- and with the recursion it is the closed form of. The consent: a parent's
  -- yes for a boy of seventeen, and what happens on his eighteenth birthday —
  -- phase 0's rule since db/62 (see the note at (12)). A team-mate, another
  -- side's coach and a parent read and write no load; the fitness coach reads
  -- a load chart and not an injury's notes; a support session reads no
  -- consent and records none.
  DECLARE
    ids     jsonb := _seed_60();
    P_B     uuid; P_T uuid; P_E uuid; P_O uuid;   -- bowler, turning 18, EWMA series, other
    U_C     uuid; U_C2 uuid; U_PH uuid; U_FIT uuid; U_MATE uuid; U_OFF uuid; U_PL uuid;
    U_MUM   uuid; U_MUM2 uuid; U_BOY uuid; U_TURN uuid;
    TS      uuid;
    D_MATCH date;
    V       text := 'health-monitoring-2026-09';
    e_staff uuid; e_self uuid; e_fix uuid;
    rec     record;
    c       record;
    w       record;
    v_con   text;
    v_msg   text;
    v_word  text;
    v_ratio numeric;
    ew      record;
    S_ID    uuid;
    k       int;
  BEGIN
    P_B := (ids->>'p_bowler')::uuid; P_T := (ids->>'p_turning')::uuid;
    P_E := (ids->>'p_ewma')::uuid;   P_O := (ids->>'p_other')::uuid;
    U_C := (ids->>'u_coach')::uuid;  U_C2 := (ids->>'u_coach2')::uuid; U_PH := (ids->>'u_physio')::uuid;
    U_FIT := (ids->>'u_fit')::uuid;  U_MATE := (ids->>'u_mate')::uuid; U_OFF := (ids->>'u_office')::uuid;
    U_PL := (ids->>'u_plat')::uuid;  U_MUM := (ids->>'u_mum')::uuid;   U_MUM2 := (ids->>'u_mum2')::uuid;
    U_BOY := (ids->>'u_boy')::uuid;  U_TURN := (ids->>'u_turner')::uuid;
    TS := (ids->>'ts')::uuid;        D_MATCH := (ids->>'m_on')::date;

    -- (1) The switch arrives off: a coach's nets band is refused until the
    -- platform grants workload_monitoring to his school.
    PERFORM _as(U_C);
    BEGIN
      INSERT INTO load_entry (player_id, kind, training_session_id, band) VALUES (P_B, 'nets', TS, '12_24');
      v_msg := 'accepted';
    EXCEPTION WHEN check_violation THEN v_msg := SQLERRM;
    END;
    PERFORM _assert(v_msg = 'workload_monitoring_off', format('db/60 (switch): a nets band with the module off was %s', v_msg));
    PERFORM _v60_grant(true);

    -- (2) A nets band for a boy WITHOUT health consent is accepted, stamped
    -- as the coach's (staff), dated by the session, and his figure says
    -- "estimate".
    PERFORM _assert(NOT _v60_live(P_B), 'db/60 (fixture): the bowler has a live health consent');
    PERFORM _as(U_C);
    INSERT INTO load_entry (player_id, kind, training_session_id, band, rpe, minutes)
    VALUES (P_B, 'nets', TS, '12_24', 6, 45) RETURNING id INTO e_staff;
    SELECT * INTO rec FROM load_entry WHERE id = e_staff;
    PERFORM _assert(rec.recorded_as = 'staff' AND rec.recorded_by = U_C AND rec.on_date = sa_today()
                    AND rec.school_id = HIL AND rec.units IS NULL,
      format('db/60 (stamp): the coach''s row is %s', row(rec.recorded_as, rec.recorded_by = U_C, rec.on_date, rec.school_id = HIL)::text));
    SELECT * INTO rec FROM load_summary(P_B);
    PERFORM _assert(rec.units_7d = 18 + 13 AND rec.match_units_7d = 13 AND rec.estimated_7d AND NOT rec.monitored,
      format('db/60 (estimate): the coach reads %s for the bowler', row(rec.units_7d, rec.match_units_7d, rec.estimated_7d, rec.monitored)::text));
    SELECT count(*) INTO n FROM load_weeks(P_B) wk WHERE wk.week_start <= sa_today() AND wk.week_end >= sa_today() AND wk.estimated AND wk.units >= 18;
    PERFORM _assert(n = 1, 'db/60 (chart): this week''s bar is not drawn as an estimate');

    -- (3) A nets entry with a count is refused, and so is a paper-scored
    -- match with a band: nobody can be asked to count a net.
    v_con := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, training_session_id, band, units) VALUES (P_B, 'nets', TS, '12_24', 20);
    EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
    END;
    PERFORM _assert(v_con = 'load_entry_band_or_count', format('db/60 (count): a net with a count was %s', coalesce(v_con, 'accepted')));
    v_con := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, on_date, units) VALUES (P_B, 'nets', sa_today(), 20);
    EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
    END;
    PERFORM _assert(v_con = 'load_entry_band_or_count', 'db/60 (count): a net with a count and no band was accepted');
    v_con := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, on_date, band) VALUES (P_B, 'match_elsewhere', D_MATCH, '24_36');
    EXCEPTION WHEN check_violation THEN GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
    END;
    PERFORM _assert(v_con = 'load_entry_band_or_count', 'db/60 (count): a paper-scored match with a band was accepted');
    v_msg := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, on_date, band) VALUES (P_B, 'nets', sa_today() + 1, '12_24');
    EXCEPTION WHEN check_violation THEN v_msg := SQLERRM;
    END;
    PERFORM _assert(v_msg = 'load_entry_in_future', 'db/60 (stamp): a net tomorrow was accepted');

    -- (4) The bowler's own band for the same session: the session counts
    -- once, and it is HIS figure — not the coach's, not the two added, not
    -- the larger.
    PERFORM _as(U_BOY);
    INSERT INTO load_entry (player_id, kind, training_session_id, band, rpe, minutes)
    VALUES (P_B, 'nets', TS, '24_36', 9, 50) RETURNING id INTO e_self;
    SELECT * INTO rec FROM load_entry WHERE id = e_self;
    PERFORM _assert(rec.recorded_as = 'self' AND rec.recorded_by = U_BOY, format('db/60 (self): the boy''s row is %s', rec.recorded_as));
    SELECT * INTO rec FROM _v60_day(P_B, sa_today());
    PERFORM _assert(rec.entered_units = 30 AND rec.sessions = 1 AND rec.estimated AND rec.minutes = 50 AND rec.au = 450,
      format('db/60 (one figure): today reads %s, expected his 30 once', row(rec.entered_units, rec.sessions, rec.minutes, rec.au)::text));
    -- The coach corrects his own figure: still the boy's that counts.
    PERFORM _as(U_C);
    INSERT INTO load_entry (player_id, kind, training_session_id, band, supersedes)
    VALUES (P_B, 'nets', TS, '36plus', e_staff) RETURNING id INTO e_fix;
    SELECT * INTO rec FROM _v60_day(P_B, sa_today());
    PERFORM _assert(rec.entered_units = 30, format('db/60 (one figure): a coach''s correction displaced the boy''s figure (%s)', rec.entered_units));
    -- A correction replaces one's own figure only.
    PERFORM _as(U_BOY);
    v_msg := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, training_session_id, band, supersedes) VALUES (P_B, 'nets', TS, 'lt12', e_fix);
    EXCEPTION WHEN check_violation THEN v_msg := SQLERRM;
    END;
    PERFORM _assert(v_msg = 'supersedes_another_session', 'db/60 (correction): the boy replaced the coach''s figure');
    INSERT INTO load_entry (player_id, kind, training_session_id, band, supersedes) VALUES (P_B, 'nets', TS, 'lt12', e_self);
    SELECT * INTO rec FROM _v60_day(P_B, sa_today());
    PERFORM _assert(rec.entered_units = 6, format('db/60 (correction): his corrected figure reads %s, expected 6', rec.entered_units));
    -- The row is never changed in place.
    v_msg := NULL;
    BEGIN
      UPDATE load_entry SET band = '36plus' WHERE id = e_self;
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (never updated): the application changed a load entry');

    -- (5) A paper-scored match on a day the log already scored for him is
    -- marked, not refused and not dropped.
    INSERT INTO load_entry (player_id, kind, on_date, units) VALUES (P_B, 'match_elsewhere', D_MATCH, 24);
    SELECT * INTO rec FROM _v60_day(P_B, D_MATCH);
    PERFORM _assert(rec.match_units = 13 AND rec.entered_units = 24 AND rec.units = 37 AND rec.possibly_doubled AND NOT rec.estimated,
      format('db/60 (doubled): the scored day reads %s', row(rec.match_units, rec.entered_units, rec.possibly_doubled, rec.estimated)::text));
    SELECT * INTO rec FROM load_summary(P_B);
    PERFORM _assert(rec.possibly_doubled_7d AND D_MATCH = ANY (rec.possibly_doubled_on),
      'db/60 (doubled): his summary does not mark the day');
    SELECT count(*) INTO n FROM _v60_day(P_B, sa_today()) d WHERE d.possibly_doubled;
    PERFORM _assert(n = 0, 'db/60 (doubled): a nets day was marked as possibly counted twice');

    -- (6) workload(): the old columns, in their order, meaning what they meant.
    PERFORM _assert(pg_get_function_result('workload(text)'::regprocedure) LIKE
      'TABLE(player_id uuid, full_name text, team_code text, school_id uuid, age_band text, pace boolean, '
      'max_overs_per_spell smallint, max_overs_per_day smallint, overs_7d integer, overs_28d integer, '
      'longest_spell_7d integer, breaches_28d integer, last_bowled_on date, sessions_7d integer, minutes_7d integer, '
      'sessions_28d integer, minutes_28d integer, acwr numeric, load_state text, units_7d integer, units_28d integer, '
      'estimated_7d boolean, ewma_ratio numeric, load_word text, monitored boolean)',
      'db/60 (workload): workload()''s row is not db/08''s with six columns after it');
    PERFORM _as(U_C);
    SELECT * INTO w FROM workload('U15A') x WHERE x.player_id = P_B;
    PERFORM _assert(w.overs_7d = 2 AND w.overs_28d = 2 AND w.acwr = 4.00 AND w.load_state = 'spike'
                    AND w.units_7d = 6 + 13 + 24 AND w.estimated_7d AND NOT w.monitored,
      format('db/60 (workload): the bowler''s row is %s', row(w.overs_7d, w.overs_28d, w.acwr, w.load_state, w.units_7d, w.estimated_7d, w.monitored)::text));

    -- (7) The EWMA and its word, on a constructed series: load_summary()'s
    -- closed form against the recursion the design describes, and its word
    -- against workload()'s own thresholds, copied here from db/08.
    PERFORM _v60_series(P_E, U_C);
    PERFORM _as(U_C);
    SELECT * INTO ew FROM _v60_ewma(P_E);
    SELECT * INTO rec FROM load_summary(P_E);
    v_ratio := round(ew.acute / ew.chronic, 2);
    PERFORM _assert(rec.ewma_ratio = v_ratio AND rec.ewma_acute = round(ew.acute, 2) AND rec.ewma_chronic = round(ew.chronic, 2),
      format('db/60 (ewma): the summary reads %s, the recursion %s', row(rec.ewma_acute, rec.ewma_chronic, rec.ewma_ratio)::text,
             row(round(ew.acute, 2), round(ew.chronic, 2), v_ratio)::text));
    v_word := CASE WHEN v_ratio > 1.5 THEN 'spike' WHEN v_ratio >= 1.2 THEN 'rising' WHEN v_ratio < 0.8 THEN 'light' ELSE 'steady' END;
    PERFORM _assert(rec.load_word = v_word AND rec.units_7d = 144 AND rec.units_28d = 234 AND rec.estimated_28d AND rec.ratio_estimated,
      format('db/60 (word): %s at ratio %s, workload()''s thresholds say %s', rec.load_word, v_ratio, v_word));
    SELECT * INTO w FROM workload('U15A') x WHERE x.player_id = P_E;
    PERFORM _assert(w.ewma_ratio = rec.ewma_ratio AND w.load_word = rec.load_word AND w.units_7d = rec.units_7d,
      format('db/60 (word): the list says %s and the profile %s', row(w.ewma_ratio, w.load_word)::text, row(rec.ewma_ratio, rec.load_word)::text));
    SELECT count(*) INTO n FROM generate_series(0, 300) g
     WHERE load_ratio_word(g / 100.0) IS DISTINCT FROM
           CASE WHEN g / 100.0 > 1.5 THEN 'spike' WHEN g / 100.0 >= 1.2 THEN 'rising'
                WHEN g / 100.0 < 0.8 THEN 'light' ELSE 'steady' END;
    PERFORM _assert(n = 0, format('db/60 (word): %s ratios between 0 and 3 read a different word from workload()''s', n));
    SELECT count(*) INTO n FROM load_summary(P_E) x
     WHERE x.load_word ~* '(risk|danger|injur|unsafe)' OR x.baseline_word ~* '(risk|danger|injur|unsafe)';
    PERFORM _assert(n = 0, 'db/60 (word): a word names the body');
    -- A baseline needs six weeks with load: this one has three in weeks 3-14.
    PERFORM _assert(rec.baseline_week IS NULL AND rec.baseline_weeks_needed = 3,
      format('db/60 (baseline): %s', row(rec.baseline_week, rec.baseline_weeks_needed)::text));

    -- (8) Who reads and writes a load: a team-mate nothing, another side's
    -- coach nothing, a parent nothing.
    PERFORM _as(U_MATE);
    SELECT (SELECT count(*) FROM load_entry) + (SELECT count(*) FROM load_summary(P_B))
         + (SELECT count(*) FROM load_weeks(P_B)) + (SELECT count(*) FROM workload('U15A'))
         + (SELECT count(*) FROM health_monitoring_consent) + (SELECT count(*) FROM my_health_consents()) INTO n;
    PERFORM _assert(n = 0, format('db/60 (team-mate): a player on the same side read %s rows', n));
    v_msg := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, training_session_id, band) VALUES (P_B, 'nets', TS, '12_24');
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (team-mate): a player recorded a team-mate''s load');
    v_msg := NULL;
    BEGIN
      PERFORM 1 FROM load_day;
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (load_day): the application reads load_day around the per-boy check');
    PERFORM _as(U_C2);
    SELECT (SELECT count(*) FROM load_entry WHERE player_id = P_B) + (SELECT count(*) FROM load_summary(P_B)) INTO n;
    PERFORM _assert(n = 0, format('db/60 (other side): the U16A coach read %s rows of a U15A boy''s load', n));
    v_msg := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, training_session_id, band) VALUES (P_B, 'nets', TS, '12_24');
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (other side): the U16A coach recorded a U15A boy''s load');
    PERFORM _as(U_MUM2);
    SELECT (SELECT count(*) FROM load_entry) + (SELECT count(*) FROM load_summary(P_O)) INTO n;
    PERFORM _assert(n = 0, 'db/60 (parent): a parent reads her son''s nets load by standing');
    v_msg := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, on_date, band) VALUES (P_O, 'nets', sa_today(), '12_24');
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (parent): a parent recorded a nets band');
    -- The boy records his own and nobody else's.
    PERFORM _as(U_BOY);
    v_msg := NULL;
    BEGIN
      INSERT INTO load_entry (player_id, kind, on_date, band) VALUES (P_O, 'nets', sa_today(), '12_24');
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (self): a boy recorded another boy''s load');
    SELECT count(*) INTO n FROM load_summary(P_B);
    PERFORM _assert(n = 1, 'db/60 (self): the boy cannot read his own load');

    -- (9) The fitness coach reads a load chart and records a band; of an
    -- injury he reads what it is, never the physio's notes.
    PERFORM _as(U_FIT);
    SELECT (SELECT count(*) FROM load_summary(P_B)) INTO n;
    SELECT count(*) INTO k FROM load_weeks(P_B);
    PERFORM _assert(n = 1 AND k = 26, format('db/60 (fitness): the chart is %s summary, %s weeks', n, k));
    INSERT INTO load_entry (player_id, kind, on_date, band) VALUES (P_O, 'training', sa_today(), 'lt12') RETURNING recorded_as INTO v_msg;
    PERFORM _assert(v_msg = 'staff', 'db/60 (fitness): the fitness coach''s band is not staff');
    SELECT count(*) INTO n FROM injury_masked i WHERE i.player_id = P_B AND i.injury_type = 'Hamstring strain' AND i.notes IS NULL AND i.physio IS NULL;
    PERFORM _assert(n = 1, 'db/60 (fitness): the fitness coach reads the physio''s notes, or not the injury''s nature');
    PERFORM _as(U_PH);
    SELECT count(*) INTO n FROM injury_masked i WHERE i.player_id = P_B AND i.notes IS NOT NULL;
    PERFORM _assert(n = 1, 'db/60 (fitness): the physio does not read her own note (the test would prove nothing)');

    -- (10) The consent at seventeen. The office records the link and its
    -- terms through db/08's own functions, so the link ends where
    -- guardian_link_establish() ends it today.
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_establish(U_MUM, P_T, 'parent');
    PERFORM _assert(v_ok, format('db/60 (link): the office could not link the mother (%s)', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_verify(U_MUM, P_T, 'popia-2026-01');
    PERFORM _assert(v_ok, format('db/60 (link): the office could not verify the mother (%s)', v_reason));
    -- Who may not answer: another child's parent, his coach, the boy himself at seventeen.
    PERFORM _as(U_MUM2);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/60 (consent): another boy''s parent answered (%s)', v_reason));
    PERFORM _as(U_C);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/60 (consent): his coach answered (%s)', v_reason));
    PERFORM _as(U_TURN);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_eighteen', format('db/60 (consent): the boy answered at seventeen (%s)', v_reason));
    SELECT * INTO c FROM my_health_consents() x WHERE x.player_id = P_T;
    PERFORM _assert(c.relation = 'self' AND c.state = 'not_answered' AND NOT c.can_say_yes AND NOT c.can_say_no AND NOT c.ask_at_18,
      format('db/60 (consent): the boy''s own row at seventeen is %s', row(c.relation, c.state, c.can_say_yes, c.ask_at_18)::text));
    -- The office from the admission form: a yes names the form.
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V, U_MUM);
    PERFORM _assert(NOT v_ok AND v_reason = 'form_required', format('db/60 (consent): the office said yes with no form (%s)', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V, U_MUM, 'Admission form 2026', sa_today());
    PERFORM _assert(v_ok, format('db/60 (consent): the office could not record the form (%s)', v_reason));
    PERFORM _assert(_v60_live(P_T), 'db/60 (consent): a parent''s yes for a boy of seventeen is not live');
    PERFORM _as(U_MUM);
    SELECT * INTO c FROM my_health_consents() x WHERE x.player_id = P_T;
    PERFORM _assert(c.relation = 'guardian' AND c.state = 'given' AND c.from_form AND c.can_say_no AND c.can_say_yes,
      format('db/60 (consent): the mother''s row is %s', row(c.relation, c.state, c.from_form)::text));
    -- She withdraws: dead on the next statement. She says yes again: live.
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, false, V);
    PERFORM _assert(v_ok AND NOT _v60_live(P_T), format('db/60 (withdrawn): %s, live %s', v_reason, _v60_live(P_T)));
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V);
    PERFORM _assert(v_ok AND _v60_live(P_T), format('db/60 (consent): the mother''s own yes (%s)', v_reason));
    SELECT * INTO c FROM my_health_consents() x WHERE x.player_id = P_T;
    PERFORM _assert(c.state = 'given' AND c.by_you AND NOT c.from_form AND c.retention_due IS NULL,
      format('db/60 (consent): after her yes, %s', row(c.state, c.by_you, c.from_form, c.retention_due)::text));
    SELECT count(*) INTO n FROM health_monitoring_consent WHERE player_id = P_T;
    PERFORM _assert(n = 2, format('db/60 (records): the mother reads %s of her own records, expected 2', n));
    -- The records have one door.
    v_msg := NULL;
    BEGIN
      UPDATE health_monitoring_consent SET ended_on = NULL WHERE player_id = P_T;
    EXCEPTION WHEN insufficient_privilege THEN v_msg := 'refused';
    END;
    PERFORM _assert(v_msg = 'refused', 'db/60 (records): the application edited a consent record');
    PERFORM _as(U_C);
    SELECT count(*) INTO n FROM health_monitoring_consent;
    PERFORM _assert(n = 0, 'db/60 (records): a coach reads who agreed to health monitoring');
    SELECT x.monitored INTO v_ok FROM workload('U15A') x WHERE x.player_id = P_T;
    PERFORM _assert(v_ok, 'db/60 (workload): the coach''s list does not show the boy as monitored');
    -- The nets band never waited on any of it (2), and does not now.

    -- (11) A support session, as the office, reads no consent and records none.
    PERFORM _as(U_PL);
    SELECT s.ok, s.reason, s.id INTO v_ok, v_reason, S_ID
      FROM support_access_begin(HIL, 'schooladmin', 'ticket 6060: the consent screen shows the wrong date') s;
    PERFORM _assert(v_ok, format('db/60 (support): the session did not begin (%s)', v_reason));
    SELECT (SELECT count(*) FROM health_monitoring_consent) + (SELECT count(*) FROM my_health_consents()) INTO n;
    PERFORM _assert(n = 0, format('db/60 (support): a support session read %s consent rows', n));
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, false, V, U_MUM);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_under_support', format('db/60 (support): a support session recorded a consent (%s)', v_reason));
    PERFORM support_access_end(S_ID);
    PERFORM _assert(_v60_live(P_T), 'db/60 (support): the refused support write changed the consent');

    -- (12) The eighteenth birthday. His whole history moves back together, so
    -- the mother's yes was given while he was a child and today is the day.
    PERFORM _v60_turn_eighteen(P_T);
    -- ┌─ PHASE 0'S RULE (db/62; flipped from "today's rule" when it landed).
    -- │  guardian_link_establish() wrote her link OPEN, because he is an
    -- │  enrolled pupil, so it does not end on his birthday; her consent
    -- │  counts through a link that is live today, so it carries on while he
    -- │  is at school — no pause in collection (§7.4, Q7). Before db/62 her
    -- │  link ended here, the consent with it, and these read the other way.
    PERFORM _assert(_v38_link_open(P_T, U_MUM), 'db/60 (18, phase 0): guardian_link_establish() did not leave an enrolled pupil''s link open');
    PERFORM _assert(_v60_live(P_T), 'db/60 (18, phase 0): a parent''s pre-18 consent lapsed on his birthday while he is at school');
    PERFORM _as(U_MUM);
    SELECT * INTO c FROM my_health_consents() x WHERE x.player_id = P_T;
    PERFORM _assert(c.relation = 'guardian' AND c.live AND c.state = 'given' AND NOT c.can_say_yes AND c.can_say_no,
      format('db/60 (18, phase 0): the mother''s row after his birthday is %s', row(c.relation, c.live, c.state, c.can_say_yes, c.can_say_no)::text));
    -- └─ end of the assertions phase 0 flipped.
    -- Her yes after eighteen is refused, for the reason, whatever her link says.
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V || '-b');
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself', format('db/60 (18): her yes after eighteen: %s', v_reason));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V || '-b', U_MUM, 'Admission form 2026', sa_today());
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself', format('db/60 (18): the office''s yes for her after eighteen: %s', v_reason));
    -- He is asked, once — and until he answers, collection carries on on hers.
    PERFORM _as(U_TURN);
    SELECT * INTO c FROM my_health_consents() x WHERE x.player_id = P_T;
    PERFORM _assert(c.relation = 'self' AND c.adult AND c.ask_at_18 AND c.state = 'given' AND c.live AND c.can_say_yes AND c.parent_said_yes,
      format('db/60 (18): his own row is %s', row(c.relation, c.adult, c.ask_at_18, c.state, c.live)::text));

    -- (13) With the link open past the birthday, as phase 0 leaves it for an
    -- enrolled pupil: her pre-18 yes is live while he is at school, dead
    -- when he is not in the school system (a club member, or left), live
    -- again when he is back; her yes is still refused; and once he declines,
    -- only his record counts. The link was held open by hand here before
    -- db/62; it is open already, so this now asserts what db/62 wrote.
    -- (Section 40 fires db/62's triggers on his leaving; here the leave is
    -- the membership alone, so the consent's own at-school test is proved.)
    PERFORM _assert(_v38_link_open(P_T, U_MUM), 'db/60 (18, phase 0): the link is not open past his birthday');
    PERFORM _assert(_v60_live(P_T), 'db/60 (18, phase 0): her yes is not live on his birthday while he is at school');
    PERFORM _v60_leave(P_T);
    PERFORM _assert(NOT _v60_live(P_T), 'db/60 (18, phase 0): her yes is live for an adult out of the school system');
    PERFORM _v60_rejoin(P_T);
    PERFORM _assert(_v60_live(P_T), 'db/60 (18, phase 0): her yes is not live again when he is back at school');
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V || '-b');
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself', format('db/60 (18, phase 0): her yes with a live link: %s', v_reason));
    PERFORM _as(U_TURN);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, false, V);
    PERFORM _assert(v_ok AND NOT _v60_live(P_T), format('db/60 (18): he declines — %s, live %s', v_reason, _v60_live(P_T)));
    SELECT * INTO c FROM my_health_consents() x WHERE x.player_id = P_T;
    PERFORM _assert(c.state = 'refused' AND c.given_by = 'self' AND NOT c.ask_at_18,
      format('db/60 (18): after he declines, %s', row(c.state, c.given_by, c.ask_at_18)::text));
    -- Her "no" is still hers to give while her link is live; it changes nothing now.
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, false, V);
    PERFORM _assert(v_ok AND NOT _v60_live(P_T), format('db/60 (18): her no after eighteen: %s', v_reason));
    PERFORM _as(U_TURN);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, true, V);
    PERFORM _assert(v_ok AND _v60_live(P_T), format('db/60 (18): his own yes (%s)', v_reason));

    -- (14) When the rows would fall due: never while live or at school;
    -- twelve months after the later of the consent's end and his leaving.
    PERFORM _assert(_v60_due(P_T) IS NULL, 'db/60 (retention): a live consent has a due date');
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_T, false, V);
    PERFORM _assert(v_ok AND _v60_due(P_T) IS NULL, 'db/60 (retention): a boy still at school has a due date');
    PERFORM _v60_leave(P_T);
    -- sa_today(), not current_date: health_retention_due() counts from the
    -- database's own today (Africa/Johannesburg), and between 22:00 and
    -- midnight UTC the two are a day apart — the consent ended on sa_today().
    PERFORM _assert(_v60_due(P_T) = (sa_today() + interval '12 months')::date,
      format('db/60 (retention): due %s, expected twelve months from today', _v60_due(P_T)));
    PERFORM _assert(_v60_due(P_B) IS NULL, 'db/60 (retention): a boy with no consent recorded has a due date');
  END;

  -- ── 39. Playing conditions per competition, phase 1 (SCRBRD-114, db/61) ──
  -- The design's phase 1 "proves" (docs/design/SCRBRD-114_playing_conditions.md
  -- §9), on a festival Hilton organises and five fixtures (_seed_61()). The
  -- JavaScript half is packages/scoring/test/conditions.test.mjs, which pins
  -- the same catalogue and parity strings; the API half is
  -- tools/smoke-playing-conditions.mjs (the write path and the pad's
  -- credential fixing the document, the handover's hash).
  --
  -- Each labelled assertion was falsified once — the thing it guards broken
  -- in db/61, the database rebuilt and this file run — and went red (three
  -- at db/61's own proof first, which runs before this file can):
  --   (catalogue)   a catalogue row's readers changed in db/61 and not in conditions.mjs
  --   (deny)        the CHECK's deny-list taken off the key (db/61's proof first)
  --   (immutable)   condition_value_guard() not asking the version's status
  --   (retroactive) condition_set_publish() comparing < sa_today() for <=
  --   (support)     condition_set_publish() without its support check
  --   (scorer)      condition_set_read admitting any signed-in reader
  --   (entrant)     match_competition_entered() not asking for the home side
  --   (fix)         match_conditions_fix() not refusing a scored match
  --   (override)    match_condition_override_set() not asking for a row: the
  --                 override table's own trigger refused it, the second wall
  --   (frozen)      match_conditions_guard() not comparing the play part (db/61's proof first)
  --   (parity)      match_free_hits_apply() back to db/54's (db/61's proof first)
  --   (seed)        _seed_rows_61('resolved') writing the other free hit
  DECLARE
    ids jsonb;
    C uuid; M_T20 uuid; M_DECL uuid; M_LATE uuid; M_FR uuid; M_OLD uuid;
    V1 uuid; V2 uuid; VX uuid;
    n bigint;
    got text; f0 text; f1 text; f2 text;
    h1 text; h2 text;
    pc record;
    v_ver smallint;
    t text;
    CATALOGUE text :=
         'format.kind|play|enum|-|limited,declaration,timed|-|-|pad,fold,laws,sql; '
      || 'format.overs_per_innings|play|int|overs|-|-|-|pad,fold,sql,table; '
      || 'format.innings_per_side|play|int|-|-|-|-|fold,pad; '
      || 'format.free_hit|play|bool|-|-|-|-|pad,fold,laws,sql; '
      || 'bowling.max_overs_per_bowler_innings|play|int|overs|-|-|-|pad,sql; '
      || 'bowling.limit|play|object|overs|-|band|-|sql,pad; '
      || 'result.min_overs_per_side|play|int|overs|-|-|-|pad,sql; '
      || 'result.tie_break|play|enum|-|none,super_over|-|"none"|fold,table; '
      -- SCRBRD-130 R1 (db/73)
      || 'target.method|play|enum|-|umpires_revision,dls_standard|-|"umpires_revision"|fold,sql; '
      || 'target.g50|play|int|runs|-|-|-|pad; '
      -- SCRBRD-130 R2 (db/75)
      || 'target.dls_table|play|object|-|-|-|-|pad,sql; '
      || 'points.win|table|int|points|-|-|-|table; '
      || 'points.tie|table|int|points|-|-|-|table; '
      || 'points.draw|table|int|points|-|-|-|table; '
      || 'points.no_result|table|int|points|-|-|-|table; '
      || 'points.loss|table|int|points|-|-|-|table; '
      || 'points.abandoned|table|int|points|-|-|-|table; '
      || 'bonus.kind|table|enum|-|none,run_rate_ratio,batting_bowling|-|"none"|table; '
      || 'bonus.params|table|object|-|-|-|-|table; '
      || 'nrr.method|table|enum|-|standard|-|"standard"|table; '
      || 'table.order|table|list|-|points,wins,nrr,head_to_head,fewer_losses|-|["points", "wins", "nrr"]|table; '
      || 'over_rate.kind|table|enum|-|none,points,runs|-|"none"|table; '
      -- OFFICIAL_RESULT (db/114)
      || 'results.confirmed_by|table|enum|-|organiser,home_school,either_school|-|-|sql; '
      || 'results.dispute_days|table|int|days|-|-|-|sql; '
      || 'eligibility.age_on|sheet|date|-|-|-|-|selection,sql; '
      || 'eligibility.max_age_open|sheet|int|years|-|-|-|selection,sql; '
      || 'eligibility.bona_fide_scholar|sheet|bool|-|-|-|false|selection,pad; '
      || 'over.max_balls|play|int|balls|-|-|-|-; '
      || 'over.free_hit_falls_away_on_last_ball|play|bool|-|-|-|-|-; '
      || 'batting.retire_at_runs|play|int|runs|-|-|-|-; '
      || 'pitch.length_m|play|int|m|-|-|-|-; '
      || 'ball.weight_g|play|int|g|-|-|-|-; '
      || 'fielding.powerplay|play|object|-|-|-|-|-; '
      || 'bowling.rest_overs_between_spells|play|int|overs|-|-|-|-; '
      || 'eligibility.max_overage_players|sheet|int|-|-|-|-|-';
  BEGIN
    ids := _seed_61();
    C := (ids->>'c')::uuid; M_T20 := (ids->>'t20')::uuid; M_DECL := (ids->>'decl')::uuid;
    M_LATE := (ids->>'late')::uuid; M_FR := (ids->>'fr')::uuid; M_OLD := (ids->>'old')::uuid;

    -- (catalogue) the table serialises to conditions.test.mjs's CATALOGUE, read by anyone signed in
    PERFORM _as(U_SCORER);
    SELECT string_agg(concat_ws('|', k.key, k.part, k.value_type, coalesce(k.unit, '-'),
                                coalesce(array_to_string(k.enum_values, ','), '-'), CASE WHEN k.by_age_band THEN 'band' ELSE '-' END,
                                coalesce(k.platform_default::text, '-'),
                                CASE WHEN cardinality(k.readers) = 0 THEN '-' ELSE array_to_string(k.readers, ',') END),
                      '; ' ORDER BY k.sort_order, k.key) INTO got
      FROM playing_condition_key k;
    PERFORM _assert(got = CATALOGUE, format('db/61 (catalogue): the table reads %s', got));
    -- (deny) the schema refuses a key that would need a child's race, whoever writes it
    PERFORM _assert(_owner_61($q$INSERT INTO playing_condition_key (key, part, value_type, readers) VALUES ('quota.black_players', 'sheet', 'int', '{}')$q$) = '23514'
                    AND _owner_61($q$INSERT INTO playing_condition_key (key, part, value_type, readers) VALUES ('transformation.targets', 'sheet', 'int', '{}')$q$) = '23514',
      'db/61 (deny): a quota key was taken into the catalogue');
    PERFORM _assert(NOT has_table_privilege('scrbrd_app', 'playing_condition_key', 'INSERT'),
      'db/61 (deny): the application may write the catalogue');

    -- (parity) the readers over conditions.test.mjs's list (PARITY)
    SELECT string_agg(format('%s:%s/%s', k, play_free_hit(d, f)::text, play_overs(d, o)), ' ' ORDER BY k) INTO got
      FROM (VALUES ('a', '{}'::jsonb, 'T20', 20), ('b', '{}', 'Two-Day', NULL), ('c', '{}', NULL, NULL),
                   ('d', '{"format.free_hit": false}', 'T20', 20), ('e', '{"format.free_hit": true}', 'One-Day Declaration', 100),
                   ('f', '{"format.free_hit": false}', NULL, NULL), ('g', '{"format.overs_per_innings": 25}', 'T20', NULL),
                   ('h', '{"format.overs_per_innings": 25}', 'T20', 20), ('i', '{"format.free_hit": "no"}', 'T20', 20),
                   ('j', '{"format.overs_per_innings": 0}', 'Two-Day', NULL),
                   ('k', '{"format.free_hit": true, "format.overs_per_innings": 50}', 'multi-day', NULL)) AS x(k, d, f, o);
    PERFORM _assert(got = 'a:true/20 b:false/20 c:true/20 d:false/20 e:true/100 f:false/20 g:true/25 h:true/20 i:true/20 j:false/20 k:true/50',
      format('db/61 (parity): the readers read %s', got));

    -- (seed) every scored log folds byte for byte alike with no document and
    -- with the document the resolver would fix; the other free hit moves it
    f0 := _figures_61();
    PERFORM _assert(_seed_rows_61('resolved') >= 2, 'db/61 (seed): no scored match to give a document to');
    f1 := _figures_61();
    PERFORM _assert(f1 = f0, format('db/61 (seed): a document saying what the format says moved a figure: %s against %s', left(f1, 300), left(f0, 300)));
    PERFORM _seed_rows_61('flipped');
    f2 := _figures_61();
    PERFORM _assert(f2 <> f0, 'db/61 (seed): the other free hit moved nothing — the comparison compares nothing');
    PERFORM _seed_rows_61('none');
    PERFORM _assert(_figures_61() = f0, 'db/61 (seed): taking the rows away did not restore the figures');

    -- A version, by the league (competitionadmin, platform-wide): drafted,
    -- a figure entered, published from day +2.
    PERFORM _as(U_LEAGUE);
    SELECT d.set_id, d.version INTO V1, v_ver FROM condition_set_draft(C, 'Verify 061 v1', sa_today() + 2) d;
    PERFORM _assert(V1 IS NOT NULL AND v_ver = 1, 'db/61: the league could not draft version 1');
    PERFORM _assert((SELECT e.ok FROM condition_value_enter(V1, 'format.free_hit', '', 'false', 'unconfirmed') e),
      'db/61: the league could not enter a figure');
    PERFORM _assert((SELECT e.reason FROM condition_value_enter(V1, 'bowling.max_overs_per_bowler_innings', '', '4', 'confirmed') e) = 'citation_required',
      'db/61: a confirmed figure was taken with no citation');
    PERFORM _assert((SELECT e.ok FROM condition_value_enter(V1, 'bowling.max_overs_per_bowler_innings', '', '4', 'confirmed',
                                                            'Verify 061 bye-laws', '7.3', sa_today() - 10) e),
      'db/61: a cited figure was refused');

    -- (scorer) a scorer reads no version, no figure — draft or published
    PERFORM _as(U_SCORER);
    SELECT count(*) INTO n FROM condition_set;
    PERFORM _assert(n = 0 AND _count_rows('condition_set') > 0, format('db/61 (scorer): a scorer reads %s of condition_set', n));
    -- A director of sport at the organising school reads no draft either.
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM condition_set WHERE id = V1;
    PERFORM _assert(n = 0, 'db/61: a draft is read by somebody who does not manage the conditions');
    PERFORM _assert((SELECT d.reason FROM condition_set_draft(C, 'Not mine', sa_today() + 2) d) = 'not_permitted',
      'db/61: a school''s director of sport drafted a league''s conditions');

    -- (retroactive) never dated today or earlier
    PERFORM _as(U_LEAGUE);
    SELECT d.set_id INTO VX FROM condition_set_draft(C, 'Verify 061 dated today', sa_today()) d;
    PERFORM _assert((SELECT p.reason FROM condition_set_publish(VX) p) = 'effective_from_not_future',
      'db/61 (retroactive): a version dated today was published');
    PERFORM condition_set_amend(VX, NULL, sa_today() - 1);
    PERFORM _assert((SELECT p.reason FROM condition_set_publish(VX) p) = 'effective_from_not_future',
      'db/61 (retroactive): a version dated yesterday was published');
    PERFORM _assert((SELECT w.ok FROM condition_set_withdraw(VX, 'Verify 061: dated wrongly') w), 'db/61: a draft could not be withdrawn');

    -- (support) a support session reaches Hilton as competitionadmin, and
    -- may draft, but never publishes
    PERFORM _as(U_PLAT);
    SELECT ok, reason, id INTO v_ok, v_reason, S_ID FROM support_access_begin(HIL, 'competitionadmin', 'ticket 5114: festival conditions');
    PERFORM _assert(v_ok, format('db/61 (support): the session was not issued (%s)', v_reason));
    PERFORM _assert((SELECT p.reason FROM condition_set_publish(V1) p) = 'support_session',
      'db/61 (support): a support session published a competition''s conditions');
    PERFORM _assert((SELECT w.reason FROM condition_set_withdraw(V1, 'support tidying up') w) = 'support_session',
      'db/61 (support): a support session withdrew a competition''s conditions');
    PERFORM support_access_end(S_ID);

    PERFORM _as(U_LEAGUE);
    PERFORM _assert((SELECT p.ok FROM condition_set_publish(V1) p), 'db/61: the league could not publish version 1');
    -- (immutable) a published figure never changes; a change is a new version
    PERFORM _assert((SELECT e.reason FROM condition_value_enter(V1, 'format.free_hit', '', 'true', 'unconfirmed') e) = 'published_is_immutable',
      'db/61 (immutable): a published figure was re-entered');
    -- A value that would be valid in a draft, so only the version's status
    -- can refuse it.
    PERFORM _assert(_owner_61(format($q$UPDATE condition_value SET value = 'true' WHERE set_id = %L AND key = 'format.free_hit'$q$, V1)) = '23514',
      'db/61 (immutable): the owner changed a published figure straight at the table');
    PERFORM _assert(_owner_61(format($q$DELETE FROM condition_value WHERE set_id = %L$q$, V1)) = '23514'
                    AND _owner_61(format($q$UPDATE condition_set SET effective_from = effective_from + 1 WHERE id = %L$q$, V1)) = '23514',
      'db/61 (immutable): the owner deleted a published figure, or moved a published version''s date');
    SELECT d.set_id INTO V2 FROM condition_set_new_version(V1) d;
    PERFORM _assert((SELECT count(*) FROM condition_value WHERE set_id = V2) = (SELECT count(*) FROM condition_value WHERE set_id = V1)
                    AND (SELECT supersedes FROM condition_set WHERE id = V2) = V1,
      'db/61 (immutable): the new version did not copy the old');
    PERFORM condition_value_enter(V2, 'format.free_hit', '', 'true', 'unconfirmed');
    PERFORM condition_set_amend(V2, NULL, sa_today() + 6);
    PERFORM _assert((SELECT p.ok FROM condition_set_publish(V2) p), 'db/61: the league could not publish version 2');

    -- The start day decides: T20 on day +3 is under v1 (published before v2,
    -- and v2 does not reach back); the declaration on day +7 and the T20 on
    -- day +8 under v2.
    PERFORM _as(U_SARAH);
    SELECT * INTO pc FROM match_playing_conditions(M_T20);
    PERFORM _assert(pc.set_version = 1 AND NOT pc.fixed AND pc.applies AND (pc.doc->'play'->>'format.free_hit')::boolean = false,
      format('db/61 (day): the day +3 fixture resolves %s', row(pc.set_version, pc.fixed, pc.doc->'play')::text));
    PERFORM _assert((SELECT set_id FROM match_playing_conditions(M_LATE)) = V2 AND (SELECT set_id FROM match_playing_conditions(M_DECL)) = V2,
      format('db/61 (day): the day +7 and +8 fixtures resolve versions %s and %s, not the second published',
             (SELECT set_version FROM match_playing_conditions(M_DECL)), (SELECT set_version FROM match_playing_conditions(M_LATE))));
    -- A friendly: the platform's defaults and the fixture.
    SELECT * INTO pc FROM match_playing_conditions(M_FR);
    PERFORM _assert(pc.set_id IS NULL AND pc.doc->'play'->'format.free_hit' = 'false' AND pc.doc->'play'->>'format.kind' = 'declaration'
                    AND pc.doc->'play'->'format.overs_per_innings' = '80' AND pc.doc->'table'->>'nrr.method' = 'standard'
                    AND pc.sources->'format.free_hit'->>'from' = 'fixture' AND pc.sources->'points.win'->>'from' = 'platform_default',
      format('db/61 (friendly): %s', pc.doc::text));

    -- (entrant) a fixture in a competition its side never entered is refused
    BEGIN
      INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, competition_id)
      VALUES (HIL, 'U16B', 'Verify 061 not entered', now() + interval '3 days', 'cricket', 'T20', 20, C);
      PERFORM _assert(false, 'db/61 (entrant): a U16B fixture was arranged in a league only the 1st XI entered');
    EXCEPTION WHEN check_violation THEN NULL;
    END;

    -- A departure before play, by the league, with its reason.
    PERFORM _as(U_LEAGUE);
    PERFORM _assert((SELECT o.ok FROM match_condition_override_set(M_T20, 'bowling.max_overs_per_bowler_innings', '', '3', 'Verify 061: shortened spells') o),
      'db/61: the league could not depart from its conditions before play');

    -- (fix) the first event fixes it — as the scorer the write path runs as —
    -- and a later version, override or change of competition moves nothing.
    -- A match scored with no document is never given one (D4).
    PERFORM _as(U_SCORER);
    SELECT count(*) INTO n FROM match_conditions WHERE match_id = M_T20;
    PERFORM _assert(n = 0, 'db/61 (fix): a document before the first event');
    PERFORM _assert((SELECT fx.fixed FROM match_conditions_fix(M_T20) fx) AND (SELECT fx.fixed FROM match_conditions_fix(M_DECL) fx),
      'db/61 (fix): the scorer could not fix the documents');
    PERFORM _assert((SELECT fx.reason FROM match_conditions_fix(M_OLD) fx) = 'scored_before_conditions'
                    AND NOT EXISTS (SELECT 1 FROM match_conditions WHERE match_id = M_OLD),
      'db/61 (fix): a match scored before db/61 was given a document');
    PERFORM _as(U_PARENT);
    PERFORM _assert((SELECT fx.reason FROM match_conditions_fix(M_LATE) fx) = 'not_permitted',
      'db/61 (fix): somebody who may not score the match fixed its conditions');
    -- The scorer reads the document of a match he may read (fixture.read).
    PERFORM _as(U_SCORER);
    PERFORM _log_61(M_T20);
    PERFORM _log_61(M_DECL);
    SELECT doc_hash INTO h1 FROM match_conditions WHERE match_id = M_T20;
    PERFORM _assert(h1 = (SELECT md5(doc::text) FROM match_conditions WHERE match_id = M_T20)
                    AND (SELECT (doc->'play'->>'bowling.max_overs_per_bowler_innings')::int FROM match_conditions WHERE match_id = M_T20) = 3,
      'db/61 (fix): the fixed document is not the resolved one, or its hash is not md5(doc::text)');
    -- (override) refused once fixed
    PERFORM _as(U_LEAGUE);
    PERFORM _assert((SELECT o.reason FROM match_condition_override_set(M_T20, 'format.free_hit', '', 'true', 'Verify 061: too late now') o) = 'conditions_fixed',
      'db/61 (override): a departure was taken after the first ball');
    -- A later version does not touch it.
    SELECT d.set_id INTO VX FROM condition_set_new_version(V2) d;
    PERFORM condition_set_amend(VX, NULL, sa_today() + 9);
    PERFORM condition_set_publish(VX);
    PERFORM _assert((SELECT doc_hash FROM match_conditions WHERE match_id = M_T20) = h1, 'db/61: a later version moved a fixed document');
    -- (frozen) the play part never changes, even for the owner
    PERFORM _assert(_owner_61(format($q$UPDATE match_conditions SET doc = jsonb_set(doc, '{play,format.free_hit}', 'true') WHERE match_id = %L$q$, M_T20)) = '23514',
      'db/61 (frozen): a fixed play document changed');
    -- ...nor the competition it was played under.
    PERFORM _assert(_owner_61(format($q$UPDATE match SET competition_id = NULL WHERE id = %L$q$, M_T20)) = '23514',
      'db/61: a scored fixture changed competition');

    -- (parity) the frozen document decides the free hit, both ways round,
    -- in every SQL reader: a T20 under free_hit = false stands the bowled
    -- after the no-ball; a declaration under free_hit = true saves it. The
    -- fold reads the same (conditions.test.mjs, D).
    PERFORM _as(U_OWNER);
    SELECT string_agg(format('%s(%s,%s,%s,%s)', x.label,
             (SELECT l.wickets FROM match_live_score l WHERE l.match_id = x.m AND l.innings = 0),
             (SELECT f.wickets FROM innings_score_as_folded(x.m, 0::smallint) f),
             (SELECT sum(o.legal_balls) FROM bowler_over o WHERE o.match_id = x.m),
             ball_on_free_hit(x.m, 0::smallint, 2)::text), ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('decl', M_DECL), ('old', M_OLD), ('t20', M_T20)) AS x(label, m);
    PERFORM _assert(got = 'decl(0,0,1,true) old(0,0,1,true) t20(1,1,1,false)',
      format('db/61 (parity): the readers read %s', got));
    PERFORM _assert((SELECT fixed FROM match_playing_conditions(M_T20)) AND NOT (SELECT applies FROM match_playing_conditions(M_OLD)),
      'db/61: a fold would apply the wrong document');

    -- The grants: the application's alone.
    FOREACH t IN ARRAY ARRAY['match_playing_conditions(uuid)', 'match_conditions_fix(uuid)', 'match_conditions_resolve(uuid)',
                             'condition_set_publish(uuid)', 'public_match_conditions(uuid)'] LOOP
      PERFORM _assert(has_function_privilege('scrbrd_app', t::regprocedure, 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) x
                                       WHERE p.oid = t::regprocedure AND x.grantee = 0 AND x.privilege_type = 'EXECUTE'),
        format('db/61 (grants): %s is not the application''s alone', t));
    END LOOP;
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'match_conditions_compute(uuid)', 'EXECUTE'),
      'db/61 (grants): the application may compute a match''s document with no guard');
  END;

  -- ── 40. The guardian link past eighteen (SCRBRD-110 phase 0, db/62) ──
  -- §9's phase 0 row: a pupil's link is open on his eighteenth birthday and
  -- app_can() still grants his parent; a club member's ends on the birthday
  -- as before; a minor who leaves keeps it until his birthday; an adult who
  -- leaves loses it that day; a boy re-enrolled, or enrolled after his link
  -- was made, has it re-opened; a new link for an adult is still refused.
  -- All of it through either door: guardian_link_establish(), and a granted
  -- role_request (decide_role_request(); Kameel, 2026-09-30). (db/10
  -- unchanged is the ledger's and shipped.test's: migrate.mjs refuses a
  -- changed file, and tools/smoke-link18.mjs compares
  -- db/10's hash with db/SHIPPED.sha256 and the ledger.) Then the two
  -- consents on top of it: her health "yes" carries on at eighteen while he
  -- is at school and dies when he leaves; her "yes" after eighteen is refused
  -- and her "no" is not; his own answer governs once given. And option C
  -- for the public name (SCRBRD-083 §6.3): after eighteen she may take his
  -- name off, never put it on, and her "no" beats the other parent's "yes".
  --
  -- db/62's triggers are deferred to the end of the transaction; _v62_fire()
  -- fires them where the application's transaction would commit.
  --
  -- Each guard in db/62 was broken once, the database rebuilt and this file
  -- run, and went red — at the first assertion able to see it, which for
  -- some is an earlier section's:
  --   establish writes the birthday for a pupil  → "did not leave a pupil's link open" (guardianship block)
  --   establish's adult refusal taken out        → "a guardian can be linked to a player who has turned eighteen"
  --   decide_role_request writes the birthday    → (request)
  --   the triggers INITIALLY IMMEDIATE           → db/62's own proof; with that cut too, "no pupil at school has
  --                                                an open guardian link", and (move) in tools/smoke-link18.mjs
  --   the CLOSE doing nothing                    → (leaves)
  --   the CLOSE ending a minor's on the day      → (minor)
  --   the OPEN doing nothing                     → "no pupil at school has an open guardian link" (the seed's)
  --   the OPEN re-opening any ended link         → "a guardian still reads ... turned eighteen" (S Naidoo's)
  --   her "no" after 18 refused (db/47's rule)   → (no-18)
  --   her "yes" after 18 taken                   → section 25's (adult)
  --   the facts without the refusal arm          → (facts)
  --   option C's not-at-school refusal cut       → section 25's (adult)
  --   the data step doing nothing                → db/62's own proof, in the paste rehearsal (on a fresh
  --                                                database the step has nothing to do)
  DECLARE
    ids     jsonb := _seed_62();
    HIL     uuid := '11111111-1111-1111-1111-111111111111';
    ZERO    uuid := '00000000-0000-0000-0000-000000000000';
    CLUB    uuid;
    P_PUP   uuid; P_ADU uuid; P_MIN uuid; P_LATE uuid; P_GROWN uuid; P_CLUB uuid;
    P_RPUP  uuid; P_RCLUB uuid; P_RADU uuid; U_RMUM uuid; U_RCMUM uuid; U_RAMUM uuid;
    U_OFF   uuid; U_COFF uuid; U_MUM uuid; U_DAD uuid; U_AMUM uuid; U_MMUM uuid;
    U_LMUM  uuid; U_GMUM uuid; U_CMUM uuid; U_SELF uuid;
    V       text := 'health-monitoring-2026-09';
    VP      text := 'public-name-2026-09';
    l       record;
    v_facts jsonb;
    v_body  text;
  BEGIN
    CLUB := (ids->>'club')::uuid;
    P_PUP := (ids->>'p_pupil')::uuid;  P_ADU := (ids->>'p_adult')::uuid; P_MIN := (ids->>'p_minor')::uuid;
    P_LATE := (ids->>'p_late')::uuid;  P_GROWN := (ids->>'p_grown')::uuid; P_CLUB := (ids->>'p_club')::uuid;
    U_OFF := (ids->>'u_office')::uuid; U_COFF := (ids->>'u_coffice')::uuid;
    U_MUM := (ids->>'u_mum')::uuid;    U_DAD := (ids->>'u_dad')::uuid;     U_AMUM := (ids->>'u_amum')::uuid;
    U_MMUM := (ids->>'u_mmum')::uuid;  U_LMUM := (ids->>'u_lmum')::uuid;   U_GMUM := (ids->>'u_gmum')::uuid;
    U_CMUM := (ids->>'u_cmum')::uuid;  U_SELF := (ids->>'u_self')::uuid;
    P_RPUP := (ids->>'p_rpupil')::uuid; P_RCLUB := (ids->>'p_rclub')::uuid; P_RADU := (ids->>'p_radult')::uuid;
    U_RMUM := (ids->>'u_rmum')::uuid;  U_RCMUM := (ids->>'u_rcmum')::uuid; U_RAMUM := (ids->>'u_ramum')::uuid;
    -- The seed's memberships were opened in this transaction; what the
    -- application's commit would do to them happens now, before anything
    -- is asked. Liam is then out of the school system when his link is made.
    PERFORM _v62_fire();
    PERFORM _v60_leave(P_LATE);
    PERFORM _v62_fire();

    -- (open) The offices link the parents, as db/08's functions do. A pupil's
    -- link is open; the club member's, and the boy out of school's, end on
    -- the eighteenth birthday exactly as before.
    PERFORM _as(U_OFF);
    FOR l IN SELECT * FROM (VALUES (U_MUM, P_PUP), (U_DAD, P_PUP), (U_AMUM, P_ADU), (U_MMUM, P_MIN), (U_LMUM, P_LATE)) AS v(g, p) LOOP
      SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_establish(l.g, l.p, 'parent');
      PERFORM _assert(v_ok, format('db/62 (link): Hilton''s office could not link a parent (%s)', v_reason));
      SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_verify(l.g, l.p, 'popia-2026-01');
      PERFORM _assert(v_ok, format('db/62 (link): Hilton''s office could not verify a parent (%s)', v_reason));
    END LOOP;
    PERFORM _as(U_COFF);
    SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_establish(U_CMUM, P_CLUB, 'parent');
    PERFORM _assert(v_ok, format('db/62 (link): the club''s office could not link a parent (%s)', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_verify(U_CMUM, P_CLUB, 'popia-2026-01');
    PERFORM _assert(v_ok, format('db/62 (link): the club''s office could not verify a parent (%s)', v_reason));
    SELECT string_agg(format('%s:%s', x.k, coalesce((_v62_link(x.p, x.g)).until::text, 'open')), ' ' ORDER BY x.k) INTO v_body
      FROM (VALUES ('adult', P_ADU, U_AMUM), ('club', P_CLUB, U_CMUM), ('dad', P_PUP, U_DAD), ('late', P_LATE, U_LMUM),
                   ('minor', P_MIN, U_MMUM), ('pupil', P_PUP, U_MUM)) AS x(k, p, g);
    PERFORM _assert(v_body = format('adult:open club:%s dad:open late:%s minor:open pupil:open',
                                    majority_on(_born_of(P_CLUB)), majority_on(_born_of(P_LATE))),
      format('db/62 (open): the links were written %s', v_body));

    -- (grown) A new link is never made for an adult, at school or not.
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_establish(U_GMUM, P_GROWN, 'parent');
    PERFORM _assert(NOT v_ok AND v_reason = 'player_is_an_adult' AND _count_guardian_assignments(U_GMUM) = 0
                    AND _count_subjects(P_GROWN) = 0,
      format('db/62 (grown): a parent was linked to a pupil of eighteen (%s, %s)', v_ok, v_reason));

    -- (request) The other door: the office grants a parent's role_request
    -- (decide_role_request(), and enrol_person() through it). The same rule:
    -- open for a pupil at school, his birthday for a club member, and never
    -- a guardian for an adult — refused, leaving nothing behind.
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM decide_role_request((ids->>'r_rpupil')::uuid, true, 'verify db/62');
    PERFORM _assert(v_ok, format('db/62 (request): Hilton''s office could not grant a parent''s request (%s)', v_reason));
    PERFORM _as(U_COFF);
    SELECT ok, reason INTO v_ok, v_reason FROM decide_role_request((ids->>'r_rclub')::uuid, true, 'verify db/62');
    PERFORM _assert(v_ok, format('db/62 (request): the club''s office could not grant a parent''s request (%s)', v_reason));
    PERFORM _assert((_v62_link(P_RPUP, U_RMUM)).open
                    AND (_v62_link(P_RCLUB, U_RCMUM)).until = majority_on(_born_of(P_RCLUB)),
      format('db/62 (request): a granted request wrote the pupil''s link %s and the club member''s %s',
             coalesce((_v62_link(P_RPUP, U_RMUM)).until::text, 'open'), coalesce((_v62_link(P_RCLUB, U_RCMUM)).until::text, 'open')));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM decide_role_request((ids->>'r_radult')::uuid, true, 'verify db/62');
    PERFORM _assert(NOT v_ok AND v_reason = 'player_is_an_adult' AND _count_guardian_assignments(U_RAMUM) = 0
                    AND _count_subjects(P_RADU) = 0,
      format('db/62 (request): a parent''s request for a pupil of eighteen was granted (%s, %s)', v_ok, v_reason));

    -- Before eighteen: the pupil's mother says yes to health monitoring; his
    -- father says yes to his name on public pages and his mother says
    -- nothing; Andile's mother says yes to health monitoring.
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_PUP, true, V);
    PERFORM _assert(v_ok AND _v60_live(P_PUP), format('db/62 (consent): the mother''s yes at seventeen (%s)', v_reason));
    PERFORM _as(U_DAD);
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_PUP, true, VP);
    PERFORM _assert(v_ok, format('db/62 (consent): the father''s public-name yes at seventeen (%s)', v_reason));
    PERFORM _as(U_AMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_ADU, true, V);
    PERFORM _assert(v_ok AND _v60_live(P_ADU), format('db/62 (consent): Andile''s mother''s yes at seventeen (%s)', v_reason));

    -- (eighteen) Today is the pupil's, Andile's and the club member's
    -- eighteenth birthday.
    PERFORM _v62_turn_eighteen(P_PUP);
    PERFORM _v62_turn_eighteen(P_ADU);
    PERFORM _v62_turn_eighteen(P_CLUB);
    PERFORM _v62_turn_eighteen(P_RPUP);
    PERFORM _v62_turn_eighteen(P_RCLUB);
    -- The pupil's link is open on his birthday, and app_can() still grants
    -- his mother: his record and his roster row.
    PERFORM _assert((_v62_link(P_PUP, U_MUM)).open AND (_v62_link(P_PUP, U_DAD)).open,
      'db/62 (eighteen): a pupil''s guardian link is not open on his eighteenth birthday');
    PERFORM _as(U_MUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_PUP;
    PERFORM _assert(n = 1 AND app_can('player.profile.read', HIL, '1XI', P_PUP, ZERO),
      format('db/62 (eighteen): app_can() refused a pupil''s mother on his eighteenth birthday (%s rows)', n));
    -- The club member's ends on the birthday, as it always has.
    PERFORM _assert((_v62_link(P_CLUB, U_CMUM)).until = current_date,
      format('db/62 (club): the club member''s link ends %s, not on his birthday', (_v62_link(P_CLUB, U_CMUM)).until));
    PERFORM _as(U_CMUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_CLUB;
    PERFORM _assert(n = 0 AND NOT app_can('player.profile.read', CLUB, '1XI', P_CLUB, ZERO),
      'db/62 (club): a club member''s parent still reads him on his eighteenth birthday');
    -- (request) ...and the same through the other door: the granted parent of
    -- the pupil keeps him on his birthday; the club member's does not.
    PERFORM _as(U_RMUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_RPUP;
    PERFORM _assert(n = 1 AND (_v62_link(P_RPUP, U_RMUM)).open AND app_can('player.profile.read', HIL, '1XI', P_RPUP, ZERO),
      format('db/62 (request): a granted parent lost her pupil son on his eighteenth birthday (%s rows)', n));
    PERFORM _as(U_RCMUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_RCLUB;
    PERFORM _assert(n = 0 AND (_v62_link(P_RCLUB, U_RCMUM)).until = current_date,
      'db/62 (request): a granted club parent still reads him on his eighteenth birthday');

    -- (health) Her pre-18 yes is live on his birthday while he is at school;
    -- her yes after it is refused; her "no" after it works; and his own
    -- answer, once given, is the only one that counts.
    PERFORM _assert(_v60_live(P_PUP), 'db/62 (health): her pre-18 yes lapsed on his birthday while he is at school');
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_PUP, true, V || '-b');
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself', format('db/62 (health): her yes after eighteen: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_PUP, false, V);
    PERFORM _assert(v_ok AND NOT _v60_live(P_PUP), format('db/62 (health): her no after eighteen: %s, live %s', v_reason, _v60_live(P_PUP)));
    PERFORM _as(U_SELF);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_PUP, true, V);
    PERFORM _assert(v_ok AND _v60_live(P_PUP), format('db/62 (health): his own yes after her no: %s', v_reason));
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM health_monitoring_consent_set(P_PUP, false, V);
    PERFORM _assert(v_ok AND _v60_live(P_PUP), format('db/62 (health): her later no outvoted his own yes: %s, live %s', v_reason, _v60_live(P_PUP)));

    -- Option C. (carries) His father's standing pre-18 yes still names him;
    -- (yes-18) his mother may not newly put his name on, herself or through
    -- the office's form; (no-18) she may take it off — a refusal, with
    -- nothing of hers open — and (facts) it counts, and is the latest act,
    -- so it beats the father's yes.
    v_facts := public_name_facts(P_PUP);
    PERFORM _assert(jsonb_array_length(v_facts -> 'consents') = 1
                    AND v_facts #> '{consents,0,competent}' = 'true'::jsonb AND v_facts #>> '{consents,0,endedOn}' IS NULL,
      format('db/62 (carries): the father''s pre-18 yes does not carry on at eighteen: %s', v_facts));
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_PUP, true, VP);
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself',
      format('db/62 (yes-18): a parent put an adult''s name on public pages (%s, %s)', v_ok, v_reason));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_PUP, true, VP, U_MUM, 'Admission form 2026', sa_today());
    PERFORM _assert(NOT v_ok AND v_reason = 'adult_consents_for_himself',
      format('db/62 (yes-18): the office put an adult''s name on for his parent (%s, %s)', v_ok, v_reason));
    PERFORM _as(U_MUM);
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_PUP, false, VP);
    PERFORM _assert(v_ok, format('db/62 (no-18): a parent could not take her adult son''s name off while he is at school (%s)', v_reason));
    v_facts := public_name_facts(P_PUP);
    SELECT count(*) INTO n FROM jsonb_array_elements(v_facts -> 'consents') x
     WHERE x ->> 'by' = 'guardian' AND (x ->> 'competent')::boolean
       AND x ->> 'givenOn' = to_char(sa_today(), 'YYYY-MM-DD') AND x ->> 'endedOn' = to_char(sa_today(), 'YYYY-MM-DD');
    PERFORM _assert(n = 1 AND jsonb_array_length(v_facts -> 'consents') = 2
                    AND (SELECT x ->> 'givenOn' FROM jsonb_array_elements(v_facts -> 'consents') x
                          WHERE (x ->> 'competent')::boolean ORDER BY x ->> 'givenOn' DESC LIMIT 1) = to_char(sa_today(), 'YYYY-MM-DD'),
      format('db/62 (facts): her no after eighteen is not a competent, latest act beside his father''s yes: %s', v_facts));
    -- (his) He speaks for himself: his own yes is a competent record, and
    -- from it his records alone govern (publicName(), unchanged).
    PERFORM _as(U_SELF);
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_PUP, true, VP);
    v_facts := public_name_facts(P_PUP);
    PERFORM _assert(v_ok AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_facts -> 'consents') x
                                      WHERE x ->> 'by' = 'pupil' AND (x ->> 'competent')::boolean AND x ->> 'endedOn' IS NULL),
      format('db/62 (his): his own yes at eighteen is not a competent, open record (%s): %s', v_reason, v_facts));

    -- (move) Ten days after his birthday, an adult pupil moved from one side
    -- to another keeps his parent: the move closes a membership and opens
    -- one, and the link is judged on what the transaction leaves — at school.
    -- (Judged statement by statement it would end on the moving day, which is
    -- not his birthday, and nothing would re-open it.)
    PERFORM _v62_older(P_ADU, 10);
    PERFORM _v62_move(P_ADU, '2XI');
    PERFORM _v62_fire();
    PERFORM _assert((_v62_link(P_ADU, U_AMUM)).open AND _v60_live(P_ADU),
      format('db/62 (move): moving an adult pupil between sides ended his parent''s link (until %s)', (_v62_link(P_ADU, U_AMUM)).until));

    -- (leaves) An adult who leaves loses his parent that day — her access,
    -- and the health consent that ran through it; and his public name is no
    -- longer hers to answer for.
    PERFORM _v60_leave(P_ADU);
    PERFORM _v62_fire();
    PERFORM _assert((_v62_link(P_ADU, U_AMUM)).until = current_date,
      format('db/62 (leaves): an adult''s link, on the day he left, ends %s', coalesce((_v62_link(P_ADU, U_AMUM)).until::text, 'never')));
    PERFORM _as(U_AMUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_ADU;
    PERFORM _assert(n = 0 AND NOT app_can('player.profile.read', HIL, '2XI', P_ADU, ZERO),
      'db/62 (leaves): the parent of an adult who has left still reads him');
    PERFORM _assert(NOT _v60_live(P_ADU), 'db/62 (leaves): her health consent outlived her link when he left');
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_ADU, false, VP);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/62 (leaves): her no after he left (%s)', v_reason));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM public_name_consent_set(P_ADU, false, VP, U_AMUM);
    PERFORM _assert(NOT v_ok AND v_reason = 'no_verified_link', format('db/62 (leaves): the office''s no for her after he left (%s)', v_reason));
    -- (never) ...and coming back does not bring it back: it ended on the day
    -- he left, not on his birthday, and a new one cannot be made for an adult.
    PERFORM _v60_rejoin(P_ADU);
    PERFORM _v62_fire();
    PERFORM _assert((_v62_link(P_ADU, U_AMUM)).until = current_date,
      format('db/62 (never): an adult''s link ended on his leaving re-opened when he came back (%s)', coalesce((_v62_link(P_ADU, U_AMUM)).until::text, 'open')));

    -- (minor) A minor who leaves keeps his parent until his birthday.
    PERFORM _v60_leave(P_MIN);
    PERFORM _v62_fire();
    PERFORM _assert((_v62_link(P_MIN, U_MMUM)).until = majority_on(_born_of(P_MIN)),
      format('db/62 (minor): a minor''s link, when he left, ends %s, not on his birthday', coalesce((_v62_link(P_MIN, U_MMUM)).until::text, 'never')));
    PERFORM _as(U_MMUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_MIN;
    PERFORM _assert(n = 1, 'db/62 (minor): a minor''s parent lost him the day he left school');
    -- (back) He comes back: open again.
    PERFORM _v60_rejoin(P_MIN);
    PERFORM _v62_fire();
    PERFORM _assert((_v62_link(P_MIN, U_MMUM)).open, 'db/62 (back): a boy re-enrolled did not have his link re-opened');
    -- He leaves again, and turns eighteen out of school: it ends on the day.
    PERFORM _v60_leave(P_MIN);
    PERFORM _v62_fire();
    PERFORM _v62_turn_eighteen(P_MIN);
    PERFORM _assert((_v62_link(P_MIN, U_MMUM)).until = current_date,
      format('db/62 (minor): out of school, his link does not end on his eighteenth birthday (%s)', (_v62_link(P_MIN, U_MMUM)).until));
    PERFORM _as(U_MMUM);
    SELECT count(*) INTO n FROM player_masked WHERE id = P_MIN;
    PERFORM _assert(n = 0, 'db/62 (minor): the parent of a boy who left at sixteen still reads him on his eighteenth birthday');
    -- (back) The boy enrolled after his link was made.
    PERFORM _assert((_v62_link(P_LATE, U_LMUM)).until = majority_on(_born_of(P_LATE)),
      'db/62 (back): the late boy''s link, made out of school, does not end on his birthday');
    PERFORM _v60_rejoin(P_LATE);
    PERFORM _v62_fire();
    PERFORM _assert((_v62_link(P_LATE, U_LMUM)).open, 'db/62 (back): a boy enrolled after his link was made did not have it re-opened');

    -- Nothing here left the table holding an adult's open link out of school.
    PERFORM _assert(_count_open_guardian_links() = 0,
      'db/62: a guardian link is open-ended for an adult who is not at school');
  END;

  -- ── 41. The scorebook importer, phase 1 (SCRBRD-120, db/63) ──────────
  -- The design's phase 1 "proves" (docs/design/SCRBRD-120_scorebook_importer.md
  -- §8) that the database alone can show; the JavaScript half is
  -- packages/scoring/test/summary.test.mjs (the fold, the seal, the Laws), the
  -- API half tools/smoke-scorebook.mjs (the photos, the commit's Laws and
  -- seal, the amendment, the parity of the arithmetic).
  --
  -- Each labelled assertion was falsified once — the thing it guards broken
  -- in db/63, the database rebuilt and this file run — and went red:
  --   (two)       scorebook_authored() not reading the revisions
  --   (support)   the RESTRICTIVE support cuts dropped from the import and its pages
  --   (page)      scorebook_import_page_read under audit.read as well
  --   (log)       scorebook_page_open() without its access_log row
  --   (figures)   innings_score_as_folded() without its summary branch (db/63's proof first)
  --   (purge)     scorebook_import_purge_due() not asking the window
  --   (public)    public_match_log() serving the payload's typed map
  --   (may)       scorebook_caller_may() answering read from scoring.import.write
  --               (the confirmer lost it), and without the actor check on audit
  --               (the support session was told it may audit)
  --   (names)     scorebook_import_names() without its player.school_id
  --               filter (the Westville boy was named), and asking app_can()
  --               for the read in place of scorebook_may() (the support
  --               session was given the names)
  --   (actors)    scorebook_import_actors() without its pupil filter (the
  --               owner, made a pupil for a moment, was named)
  --   (league)    scorebook_may() without its school-or-league clause (the
  --               league's administrator was told he may confirm a friendly),
  --               and the tables without their RESTRICTIVE reach cut (he read
  --               the friendly's rows)
  --   (remove)    scorebook_import_page_remove() asking scorebook_may() for
  --               confirm as well as write (the confirmer went through)
  --   (purge)     scorebook_import_purge_due() without the removed-page branch
  -- Two stand on two walls and stay green with either one down: (pad) — the
  -- db/50 guard in app_can() and scorebook_actor_ok() — and (door) — the
  -- application role's ball_event insert policy and the door trigger, which
  -- db/63's own proof falsifies as the owner.
  DECLARE
    ids     jsonb := _seed_63();
    M uuid; M2 uuid; M3 uuid; MW uuid; ML uuid; MWL uuid;
    I uuid; I2 uuid; I3 uuid; IL uuid;
    U_WESLG uuid := '88888888-0000-0000-0000-0000000063c0';   -- competitionadmin at Westville: Westville's league
    PG uuid; PG2 uuid; PG3 uuid;
    r       record;
    v_ver   integer;
    v_keys  text[];
    got     text;
    S_ID    uuid;
    U_WESC  uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    TYPED   jsonb := '{"t:1":"Opp Fielder One","t:2":"Opp Bowler Two","t:3":"Opp Bowler Three","t:4":"Opp Fielder Four","t:5":"Opp Bowler Five"}';
    -- packages/scoring/test/scorebook-cards.mjs's base card with Hilton's boys,
    -- the book three runs short and saying so (D4): 127 for 4 in 20.
    CARD    jsonb := '{"v":1,"innings":0,"battingSide":"home","batting":[{"order":1,"ref":"aaaaaaaa-0000-0000-0000-000000000001","howOut":"caught","fielderRef":"t:1","bowlerRef":"t:2","runs":34,"balls":40,"fours":4,"sixes":1},{"order":2,"ref":"aaaaaaaa-0000-0000-0000-000000000002","howOut":"bowled","fielderRef":null,"bowlerRef":"t:2","runs":12,"balls":15,"fours":1,"sixes":0},{"order":3,"ref":"aaaaaaaa-0000-0000-0000-000000000003","howOut":"lbw","fielderRef":null,"bowlerRef":"t:3","runs":0,"balls":3,"fours":0,"sixes":0},{"order":4,"ref":"aaaaaaaa-0000-0000-0000-000000000004","howOut":"run_out","fielderRef":"t:4","bowlerRef":null,"runs":25,"balls":null,"fours":null,"sixes":null},{"order":5,"ref":"aaaaaaaa-0000-0000-0000-000000000005","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":37,"balls":30,"fours":5,"sixes":1},{"order":6,"ref":"aaaaaaaa-0000-0000-0000-000000000011","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":5,"balls":4,"fours":0,"sixes":0}],"didNotBat":["aaaaaaaa-0000-0000-0000-000000000012"],"bowling":[{"ref":"t:2","overs":"8","maidens":0,"runs":40,"wickets":2,"wides":3,"noBalls":1},{"ref":"t:3","overs":"8","maidens":1,"runs":45,"wickets":1,"wides":2,"noBalls":2},{"ref":"t:5","overs":"4","maidens":null,"runs":39,"wickets":0,"wides":null,"noBalls":null}],"extras":{"byes":2,"legByes":1,"wides":5,"noBalls":3,"penalty":0},"total":127,"wickets":4,"overs":"20","fallOfWickets":[{"wicket":1,"score":30,"ref":"aaaaaaaa-0000-0000-0000-000000000002","over":"5.1"},{"wicket":2,"score":31,"ref":"aaaaaaaa-0000-0000-0000-000000000003","over":"5.3"},{"wicket":3,"score":60,"ref":"aaaaaaaa-0000-0000-0000-000000000001","over":"10.2"},{"wicket":4,"score":90,"ref":"aaaaaaaa-0000-0000-0000-000000000004","over":"15"}],"endReason":"overs","unreconciled":{"runs":3,"note":"the book is three short"}}';
  BEGIN
    M := (ids->>'m')::uuid; M2 := (ids->>'m2')::uuid; M3 := (ids->>'m3')::uuid; MW := (ids->>'mw')::uuid;
    ML := (ids->>'ml')::uuid; MWL := (ids->>'mwl')::uuid;

    -- (module) off where the platform has not granted it
    PERFORM _as(U_WESC);
    SELECT * INTO r FROM scorebook_import_open(MW);
    PERFORM _assert(NOT r.ok AND r.reason = 'module_disabled', format('db/63 (module): Westville opened an import (%s)', r.reason));
    -- (may) what a screen is told, by the functions' own checks: w(rite)
    -- c(onfirm) r(ead) a(udit) m(odule), a dash for no. Westville's coach may
    -- write for his own fixture, and is told the module is off there.
    PERFORM _assert(_may_63(MW) = 'w-r-.', format('db/63 (may): Westville''s coach is told %s for his fixture', _may_63(MW)));
    PERFORM _assert(_may_63(M) = '-----', format('db/63 (may): Westville''s coach is told %s for Hilton''s', _may_63(M)));
    FOREACH got IN ARRAY ARRAY[U_SCORER || ':w-r-m', U_SARAH || ':-cram', U_HEAD_M || ':---am', U_PARENT || ':-----',
                               U_PUPIL || ':-----', U_WATCHER || ':-----'] LOOP
      PERFORM _as(split_part(got, ':', 1)::uuid);
      PERFORM _assert(_may_63(M) = split_part(got, ':', 2),
        format('db/63 (may): %s is told %s, not %s', split_part(got, ':', 1), _may_63(M), split_part(got, ':', 2)));
    END LOOP;
    PERFORM _as(U_PLAT);
    SELECT s.ok, s.id INTO r FROM support_access_begin(HIL, 'directorofsport', 'ticket 6365: what may I do here') s;
    S_ID := r.id;
    got := _may_63(M);
    PERFORM support_access_end(S_ID);
    PERFORM _assert(got = '-----', format('db/63 (may): a support session as the director of sport is told %s', got));
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    got := _may_63(M);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(got = '-----', format('db/63 (may): a pad''s credential is told %s', got));

    -- The scorer opens, adds a page, types the card; the owner types a cell too.
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scorebook_import_open(M);
    PERFORM _assert(r.ok, format('db/63: the scorer could not open an import (%s)', r.reason));
    I := r.import_id;
    SELECT * INTO r FROM scorebook_import_open(M);
    PERFORM _assert(NOT r.ok AND r.reason = 'import_open', 'db/63: a second open import for one match');
    SELECT * INTO r FROM scorebook_import_page_add(I, HIL || '/' || gen_random_uuid() || '/' || gen_random_uuid() || '.jpg',
                                                  repeat('a', 64), 1000, 1600, 1200, 'image/jpeg');
    PERFORM _assert(NOT r.ok AND r.reason = 'key_invalid', 'db/63 (key): a page was recorded under another import''s key');
    SELECT * INTO r FROM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.jpg',
                                                  repeat('a', 64), 1000, 1600, 1200, 'image/jpeg');
    PERFORM _assert(r.ok AND r.page_no = 1, format('db/63: the page was not recorded (%s)', r.reason));
    PG := r.page_id;

    -- (remove) a wrong photo, taken off by a writer and by nobody else
    SELECT * INTO r FROM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.jpg',
                                                  repeat('c', 64), 1000, 1600, 1200, 'image/jpeg');
    PERFORM _assert(r.ok AND r.page_no = 2, format('db/63: the second page was not recorded (%s)', r.reason));
    PG2 := r.page_id;
    FOREACH got IN ARRAY ARRAY[U_PARENT::text, U_PUPIL::text, U_WESC::text, U_SARAH::text, U_HEAD_M::text] LOOP
      PERFORM _as(got::uuid);
      SELECT * INTO r FROM scorebook_import_page_remove(I, 2);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (remove): %s removed a page (%s)', got, r.reason));
    END LOOP;
    PERFORM _as(U_PLAT);
    SELECT s.ok, s.id INTO r FROM support_access_begin(HIL, 'scorer', 'ticket 6364: a wrong page on the import') s;
    PERFORM _assert(r.ok, 'db/63 (remove): the support session did not begin');
    S_ID := r.id;
    SELECT * INTO r FROM scorebook_import_page_remove(I, 2);
    PERFORM support_access_end(S_ID);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (remove): a support session as a scorer removed a page (%s)', r.reason));
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    SELECT * INTO r FROM scorebook_import_page_remove(I, 2);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (remove): a pad''s credential removed a page (%s)', r.reason));
    SELECT version INTO v_ver FROM scorebook_import WHERE id = I;
    SELECT * INTO r FROM scorebook_import_page_remove(I, 2);
    PERFORM _assert(r.ok AND r.version = v_ver + 1, format('db/63 (remove): the scorer could not remove his page (%s)', r.reason));
    PERFORM _assert((SELECT action || ':' || note || ':' || actor_id FROM scorebook_import_revision WHERE import_id = I AND version = r.version)
                    = 'pages:page 2 removed:' || U_SCORER, 'db/63 (remove): no revision says who removed the page');
    SELECT * INTO r FROM scorebook_import_page_remove(I, 2);
    PERFORM _assert(NOT r.ok AND r.reason = 'page_removed', format('db/63 (remove): a page was removed twice (%s)', r.reason));
    SELECT * INTO r FROM scorebook_page_open(I, 2);
    PERFORM _assert(NOT r.ok AND r.reason = 'page_removed', format('db/63 (remove): a removed page was opened (%s)', r.reason));
    -- The same photo may go back on, under a new number: no number is reused.
    SELECT * INTO r FROM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.jpg',
                                                  repeat('c', 64), 1000, 1600, 1200, 'image/jpeg');
    PERFORM _assert(r.ok AND r.page_no = 3, format('db/63 (remove): a removed photo could not be added again as page 3 (%s %s)', r.reason, r.page_no));
    PG3 := r.page_id;
    SELECT * INTO r FROM scorebook_import_page_remove(I, 3);
    PERFORM _assert(r.ok, format('db/63 (remove): page 3 could not be removed (%s)', r.reason));
    -- (purge) a removed page's photo is due at once, the import still a draft;
    -- once gone, the draft is not marked purged
    PERFORM _assert((SELECT string_agg(p.page_id::text, ',' ORDER BY p.page_id) FROM scorebook_import_purge_due(I) p)
                    = (SELECT string_agg(x::text, ',' ORDER BY x) FROM unnest(ARRAY[PG2, PG3]) x),
      'db/63 (purge): a removed page''s photo is not due at once, or a live one is');
    PERFORM _as(U_PLAT);
    PERFORM _assert((SELECT count(*) FROM scorebook_import_purge_due(NULL) p WHERE p.import_id = I) = 2,
      'db/63 (purge): the platform''s run does not retry a removed page''s photo');
    PERFORM _as(U_PARENT);
    PERFORM _assert(NOT scorebook_page_purged(PG2), 'db/63 (purge): a parent marked a removed page''s photo deleted');
    PERFORM _as(U_SCORER);
    PERFORM _assert(scorebook_page_purged(PG2) AND scorebook_page_purged(PG3), 'db/63 (purge): a removed page''s photo could not be marked deleted');
    PERFORM _assert((SELECT count(*) FROM scorebook_import_purge_due(I)) = 0
                    AND (SELECT pages_purged_at IS NULL AND state = 'draft' FROM scorebook_import WHERE id = I),
      'db/63 (purge): a draft whose removed photos are gone is marked purged, or still has photos due');
    SELECT version INTO v_ver FROM scorebook_import WHERE id = I;
    SELECT * INTO r FROM scorebook_import_save(I, jsonb_build_array(CARD), TYPED, '{}'::jsonb, v_ver);
    PERFORM _assert(r.ok, format('db/63: the scorer''s save was refused (%s)', r.reason));
    v_ver := r.version;
    -- (two) the confirmer cannot save
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM scorebook_import_save(I, jsonb_build_array(CARD), TYPED, '{}'::jsonb, v_ver);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (two): the director of sport saved a card (%s)', r.reason));
    -- The owner's key holds both halves: typing a cell makes him an author.
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_save(I, jsonb_build_array(CARD), TYPED, '{}'::jsonb, v_ver);
    PERFORM _assert(r.ok, format('db/63: the owner''s save was refused (%s)', r.reason));
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scorebook_import_submit(I, r.version);
    PERFORM _assert(r.ok, format('db/63: the submit was refused (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_page_remove(I, 1);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_editable', format('db/63 (remove): a page was removed from a submitted import (%s)', r.reason));

    -- (two) the submitter and a revision's author cannot confirm or return
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', 'db/63 (two): the scorer confirmed an import');
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'cannot_confirm_your_own', format('db/63 (two): a revision''s author confirmed it (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_return(I, 'check the extras line');
    PERFORM _assert(NOT r.ok AND r.reason = 'cannot_confirm_your_own', 'db/63 (two): a revision''s author returned it');

    -- (zeros) nobody else reads an import, a revision or a page
    FOREACH got IN ARRAY ARRAY[U_PARENT::text, U_PUPIL::text, U_WESC::text, U_WATCHER::text, U_BURSAR::text] LOOP
      PERFORM _as(got::uuid);
      SELECT (SELECT count(*) FROM scorebook_import) + (SELECT count(*) FROM scorebook_import_page)
           + (SELECT count(*) FROM scorebook_import_revision) INTO n;
      PERFORM _assert(n = 0, format('db/63 (zeros): %s read %s import rows', got, n));
      SELECT * INTO r FROM scorebook_page_open(I, 1);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (zeros): %s opened a page', got));
    END LOOP;
    -- (page) the principal audits the card's history, never a page; and,
    -- since db/116 (READERS Q2: audit.read opens the access log and the audit
    -- screen's own reads), not the import row with the confirmer's notes
    PERFORM _as(U_HEAD_M);
    PERFORM _assert((SELECT count(*) FROM scorebook_import WHERE id = I) = 0
                    AND (SELECT count(*) FROM scorebook_import_revision WHERE import_id = I) >= 4,
      'db/63 (page): the principal reads the import row (READERS Q2), or not its revisions');
    PERFORM _assert((SELECT count(*) FROM scorebook_import_page) = 0, 'db/63 (page): the principal reads a page''s row');
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM _assert(NOT r.ok, 'db/63 (page): the principal opened a page');
    PERFORM _assert(_reads_63(I) = '', format('db/63 (log): a refused read was logged: %s', _reads_63(I)));

    -- (log) the two roles at the school read the page, and each read is on the record
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM _assert(r.ok AND r.mime = 'image/jpeg' AND r.sha256 = repeat('a', 64), 'db/63: the scorer could not open his page');
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM _assert(r.ok, 'db/63: the director of sport could not open the page');
    PERFORM _assert(_reads_63(I) = U_SCORER || ':page:1 ' || U_SARAH || ':page:1',
      format('db/63 (log): the page reads on access_log are %s', _reads_63(I)));

    -- (names) the card's own boys, named to the two who check it, and to
    -- nobody else: seven on the card (six batted, one did not)
    got := 'aaaaaaaa-0000-0000-0000-000000000001,aaaaaaaa-0000-0000-0000-000000000002,aaaaaaaa-0000-0000-0000-000000000003,'
        || 'aaaaaaaa-0000-0000-0000-000000000004,aaaaaaaa-0000-0000-0000-000000000005,aaaaaaaa-0000-0000-0000-000000000011,'
        || 'aaaaaaaa-0000-0000-0000-000000000012';
    PERFORM _as(U_SCORER);
    PERFORM _assert(_names_63(I) = got, format('db/63 (names): the scorer is given %s', _names_63(I)));
    PERFORM _assert((SELECT n.name FROM scorebook_import_names(I) n WHERE n.player_id = 'aaaaaaaa-0000-0000-0000-000000000012')
                    = (SELECT _owner_name_63('aaaaaaaa-0000-0000-0000-000000000012')),
      'db/63 (names): the name is not the boy''s own');
    PERFORM _as(U_SARAH);
    PERFORM _assert(_names_63(I) = got, format('db/63 (names): the director of sport is given %s', _names_63(I)));
    FOREACH got IN ARRAY ARRAY[U_PARENT::text, U_PUPIL::text, U_WESC::text, U_WATCHER::text, U_BURSAR::text, U_HEAD_M::text] LOOP
      PERFORM _as(got::uuid);
      PERFORM _assert(_names_63(I) = '', format('db/63 (names): %s is given the card''s names: %s', got, _names_63(I)));
    END LOOP;
    PERFORM _as(U_PLAT);
    SELECT s.ok, s.id INTO r FROM support_access_begin(HIL, 'directorofsport', 'ticket 6366: the names on the card') s;
    S_ID := r.id;
    got := _names_63(I);
    PERFORM support_access_end(S_ID);
    PERFORM _assert(got = '', format('db/63 (names): a support session as the director of sport is given %s', got));
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    got := _names_63(I);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(got = '', format('db/63 (names): a pad''s credential is given %s', got));

    -- (actors) the history's authors by name — the scorer and the owner, who
    -- typed — to the two who check it, and to nobody else; a pupil unnamed
    got := U_SCORER || ':' || _user_name_63(U_SCORER) || ',' || U_OWNER || ':' || _user_name_63(U_OWNER);
    PERFORM _as(U_SARAH);
    PERFORM _assert(_actors_63(I) = got, format('db/63 (actors): the director of sport is given %s', _actors_63(I)));
    PERFORM _as(U_SCORER);
    PERFORM _assert(_actors_63(I) = got, format('db/63 (actors): the scorer is given %s', _actors_63(I)));
    PERFORM _pupil_63(U_OWNER, true);
    got := _actors_63(I);
    PERFORM _pupil_63(U_OWNER, false);
    PERFORM _assert(got = U_SCORER || ':' || _user_name_63(U_SCORER), format('db/63 (actors): a pupil is named: %s', got));
    FOREACH got IN ARRAY ARRAY[U_PARENT::text, U_PUPIL::text, U_WESC::text, U_WATCHER::text, U_BURSAR::text, U_HEAD_M::text] LOOP
      PERFORM _as(got::uuid);
      PERFORM _assert(_actors_63(I) = '', format('db/63 (actors): %s is given the authors: %s', got, _actors_63(I)));
    END LOOP;
    PERFORM _as(U_PLAT);
    SELECT s.ok, s.id INTO r FROM support_access_begin(HIL, 'directorofsport', 'ticket 6367: who typed this') s;
    S_ID := r.id;
    got := _actors_63(I);
    PERFORM support_access_end(S_ID);
    PERFORM _assert(got = '', format('db/63 (actors): a support session as the director of sport is given %s', got));
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    got := _actors_63(I);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(got = '', format('db/63 (actors): a pad''s credential is given %s', got));

    -- (support) a support session as the director of sport reads and signs nothing
    PERFORM _as(U_PLAT);
    SELECT s.ok, s.id INTO r FROM support_access_begin(HIL, 'directorofsport', 'ticket 6363: the import screen will not load') s;
    PERFORM _assert(r.ok, 'db/63 (support): the session did not begin');
    S_ID := r.id;
    SELECT (SELECT count(*) FROM scorebook_import) + (SELECT count(*) FROM scorebook_import_page) INTO n;
    PERFORM _assert(n = 0, format('db/63 (support): a support session read %s import rows', n));
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM _assert(NOT r.ok, 'db/63 (support): a support session opened a page');
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (support): a support session confirmed (%s)', r.reason));
    PERFORM support_access_end(S_ID);

    -- (pad) the scorer's pad resume credential for this very match reads nothing
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    SELECT (SELECT count(*) FROM scorebook_import) + (SELECT count(*) FROM scorebook_import_page)
         + (SELECT count(*) FROM scorebook_import_revision) INTO n;
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(n = 0 AND NOT r.ok, format('db/63 (pad): a pad''s credential read %s rows, page %s', n, r.ok));

    -- (league) a league's administrator — a school-less competitionadmin —
    -- reaches nothing of a school's friendly: told nothing, no name, no page,
    -- no row, no confirm. The platform's key (the owner) keeps its reach.
    PERFORM _as(U_LEAGUE);
    PERFORM _assert(_may_63(M) = '-----', format('db/63 (league): the league''s administrator is told %s for a friendly', _may_63(M)));
    PERFORM _assert(_names_63(I) = '' AND _actors_63(I) = '', 'db/63 (league): the league''s administrator is given a friendly''s names');
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (league): the league''s administrator opened a friendly''s page (%s)', r.reason));
    SELECT (SELECT count(*) FROM scorebook_import WHERE id = I) + (SELECT count(*) FROM scorebook_import_revision WHERE import_id = I)
         + (SELECT count(*) FROM scorebook_import_page WHERE import_id = I) INTO n;
    PERFORM _assert(n = 0, format('db/63 (league): the league''s administrator reads %s rows of a friendly''s import', n));
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (league): the league''s administrator confirmed a friendly (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_return(I, 'not his to return');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (league): the league''s administrator returned a friendly (%s)', r.reason));
    PERFORM _as(U_OWNER);
    PERFORM _assert(_may_63(M) = 'wcram', format('db/63 (league): the owner''s key is told %s for a friendly', _may_63(M)));
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], false);
    PERFORM _assert(NOT r.ok AND r.reason = 'unreconciled_not_acknowledged', format('db/63 (D4): committed unacknowledged (%s)', r.reason));
    -- The commit: three events per innings under the derived keys
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], true, 'checked against the book');
    PERFORM _assert(r.ok, format('db/63: the director of sport could not confirm (%s %s)', r.reason, r.detail));
    v_keys := r.keys;
    PERFORM _assert(_log_63(M) = format('scorebook:%s:0:start,scorebook:%s:0:summary,scorebook:%s:0:end', I, I, I),
      format('db/63: the commit wrote %s', _log_63(M)));
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_submitted', 'db/63: a second commit was not refused');
    -- ...and the keys themselves refuse a second writing, whoever tries
    PERFORM _assert(_owner_61(format(
      $q$INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq, client_ts, kind, payload)
         VALUES (%L, %L, 99, 1, 0, %L, 'verify-063', %L, 99, now(), 'innings_start', '{}')$q$,
      M, HIL, U_SCORER, v_keys[1])) = '23505', 'db/63: an event was written twice under a scorebook key');
    -- (figures) the summary is the innings, in both readers
    SELECT format('%s|%s', (SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded(M, 0::smallint) f),
                  (SELECT row(l.runs, l.wickets, l.legal_balls)::text FROM match_live_score l WHERE l.match_id = M AND l.innings = 0))
      INTO got;
    PERFORM _assert(got = '(127,4,120)|(127,4,120)', format('db/63 (figures): a summarised innings reads %s, the fold 127/4 in 120', got));
    PERFORM _assert(_deliveries_63(M) = 0, 'db/63: a summarised innings has overs, a spell, a milestone or a shot sector');
    -- D10: complete, and scoring_claim() refuses
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scoring_claim(M, 'verify-063-pad');
    PERFORM _assert(NOT r.ok AND r.reason = 'match_complete', format('db/63: a claim on an imported match (%s)', r.reason));
    SELECT state, confirmed_by = U_SARAH AS by_her, applied_keys = v_keys AS named INTO r FROM scorebook_import WHERE id = I;
    PERFORM _assert(r.state = 'confirmed' AND r.by_her AND r.named, 'db/63: the import does not say it was confirmed, by whom, with what');
    -- (door) the application role writes no summary, whatever it sets
    PERFORM set_config('scrbrd.scorebook_commit', I::text, true);
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id, idempotency_key, client_seq, client_ts, kind, payload)
      VALUES (M, HIL, 50, 1, 1, U_SCORER, 'scorebook:' || I, 'verify-063-forged', 50, now(), 'innings_summary',
              jsonb_build_object('card', CARD, 'source', jsonb_build_object('import', I)));
      got := 'written';
    EXCEPTION WHEN check_violation OR insufficient_privilege THEN got := 'refused';
    END;
    PERFORM set_config('scrbrd.scorebook_commit', '', true);
    PERFORM _assert(got = 'refused', 'db/63 (door): the application role wrote an innings summary');

    -- (public) the served log carries the card and never a typed name
    PERFORM _publish_63(M);
    SELECT string_agg(l.detail::text, ' ') INTO got FROM public_match_log(M, 0) l;
    PERFORM _assert(got LIKE '%"card"%' AND got NOT LIKE '%Opp %' AND got NOT LIKE '%typed%' AND got NOT LIKE '%three short%'
                    AND got NOT LIKE '%source%', format('db/63 (public): the public log serves %s', left(got, 300)));

    -- (purge) the photos go after the window; the rows stay
    PERFORM _as(U_PLAT);
    PERFORM _assert((SELECT count(*) FROM scorebook_import_purge_due(NULL) p WHERE p.import_id = I) = 0,
      'db/63 (purge): a photo was due before the window');
    PERFORM _age_63(I);
    PERFORM _as(U_SCORER);
    PERFORM _assert((SELECT count(*) FROM scorebook_import_purge_due(NULL)) = 0, 'db/63 (purge): the scorer runs the platform''s purge');
    PERFORM _as(U_PLAT);
    PERFORM _assert((SELECT count(*) FROM scorebook_import_purge_due(NULL) p WHERE p.page_id = PG) = 1,
      'db/63 (purge): the photo was not due after the window');
    PERFORM _assert(scorebook_page_purged(PG), 'db/63 (purge): the photo could not be marked deleted');
    PERFORM _as(U_SCORER);
    PERFORM _assert((SELECT deleted_at IS NOT NULL FROM scorebook_import_page WHERE id = PG)
                    AND (SELECT pages_purged_at IS NOT NULL FROM scorebook_import WHERE id = I),
      'db/63 (purge): the rows do not say the photo is gone');
    SELECT * INTO r FROM scorebook_page_open(I, 1);
    PERFORM _assert(NOT r.ok AND r.reason = 'page_deleted', 'db/63 (purge): a deleted photo was opened');

    -- An abandoned import's photos are due at once, to whoever abandoned it.
    SELECT * INTO r FROM scorebook_import_open(M3);
    I3 := r.import_id;
    PERFORM scorebook_import_page_add(I3, HIL || '/' || I3 || '/' || gen_random_uuid() || '.png', repeat('b', 64), 10, 8, 4, 'image/png');
    -- (names) a draft that names another school's child: his name is not given
    SELECT version INTO v_ver FROM scorebook_import WHERE id = I3;
    SELECT * INTO r FROM scorebook_import_save(I3,
      jsonb_build_array(jsonb_set(CARD, '{didNotBat}', '["bbbbbbbb-0000-0000-0000-000000000001", "aaaaaaaa-0000-0000-0000-000000000012"]')),
      TYPED, '{}'::jsonb, v_ver);
    PERFORM _assert(r.ok, format('db/63: the draft naming a Westville boy was not saved (%s)', r.reason));
    PERFORM _assert(_names_63(I3) NOT LIKE '%bbbbbbbb%' AND _names_63(I3) LIKE '%aaaaaaaa-0000-0000-0000-000000000012',
      format('db/63 (names): another school''s child is named: %s', _names_63(I3)));
    SELECT * INTO r FROM scorebook_import_abandon(I3);
    PERFORM _assert(r.ok, 'db/63: the scorer could not abandon his import');
    PERFORM _assert((SELECT count(*) FROM scorebook_import_purge_due(I3)) = 1, 'db/63 (purge): an abandoned import''s photo is not due at once');
    -- (league) his own league's match: he is told he may confirm and read,
    -- is given its names, reads its rows, and confirms it. The director of
    -- sport still reads it (her school's) and may not confirm it (the league's).
    SELECT * INTO r FROM scorebook_import_open(ML);
    PERFORM _assert(r.ok, format('db/63: the scorer could not open the league match''s import (%s)', r.reason));
    IL := r.import_id;
    SELECT * INTO r FROM scorebook_import_save(IL, jsonb_build_array(CARD), TYPED, '{}'::jsonb, 1);
    SELECT * INTO r FROM scorebook_import_submit(IL, r.version);
    PERFORM _assert(r.ok, format('db/63: the league match''s import was not submitted (%s)', r.reason));
    PERFORM _as(U_SARAH);
    PERFORM _assert(_may_63(ML) = '--ram', format('db/63 (league): the director of sport is told %s for a league match', _may_63(ML)));
    PERFORM _as(U_WESLG);
    PERFORM _assert(_may_63(ML) = '-----' AND _names_63(IL) = ''
                    AND (SELECT count(*) FROM scorebook_import WHERE id = IL) = 0,
      format('db/63 (league): Westville''s league administrator reaches the pilot league''s match (%s)', _may_63(ML)));
    PERFORM _assert(_may_63(MWL) = '-----',
      format('db/63 (league): Westville''s league administrator reaches Hilton''s match in his league (%s)', _may_63(MWL)));
    SELECT * INTO r FROM scorebook_import_commit(IL, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/63 (league): another league''s administrator confirmed (%s)', r.reason));
    PERFORM _as(U_LEAGUE);
    PERFORM _assert(_may_63(ML) = '-cr-m', format('db/63 (league): the league''s administrator is told %s for his league''s match', _may_63(ML)));
    PERFORM _assert(length(_names_63(IL)) = 7 * 36 + 6 AND (SELECT count(*) FROM scorebook_import WHERE id = IL) = 1,
      format('db/63 (league): the league''s administrator is not given his match''s names (%s)', _names_63(IL)));
    SELECT * INTO r FROM scorebook_import_commit(IL, '{}'::uuid[], true, 'the league''s');
    PERFORM _assert(r.ok, format('db/63 (league): the league''s administrator could not confirm his league''s match (%s %s)', r.reason, r.detail));

    -- A submitter who holds the confirm capability cannot confirm his own.
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_open(M2);
    I2 := r.import_id;
    SELECT * INTO r FROM scorebook_import_save(I2, jsonb_build_array(CARD), TYPED, '{}'::jsonb, 1);
    SELECT * INTO r FROM scorebook_import_submit(I2, r.version);
    PERFORM _assert(r.ok, format('db/63: the owner could not submit (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_commit(I2, '{}'::uuid[], true);
    PERFORM _assert(NOT r.ok AND r.reason = 'cannot_confirm_your_own', format('db/63 (two): the submitter confirmed his own (%s)', r.reason));
  END;

  -- ── 42. The scorebook importer, phase 2: careers and tables (SCRBRD-120, db/64) ──
  -- The design's phase 2 "proves" (docs/design/SCRBRD-120_scorebook_importer.md
  -- §8): a boy's career after an import is the card's line for him, balls
  -- and boundaries NULL where the card had none; the season view files the
  -- match under its start day; the opposition's dossier shows his runs and
  -- no dot percentage; voiding the summary by an approved amendment takes
  -- him out of every view. The import is the real one: the scorer types two
  -- cards (our innings and theirs), the director of sport confirms.
  -- tools/smoke-fold-figures.mjs holds the same readers to the fold itself.
  --
  -- Each labelled assertion was falsified once — the thing it guards broken
  -- in db/64, the database rebuilt and this file run — and went red:
  --   (career)   player_batting_career's balls_faced coalesced to 0 again
  --              (db/64's own proof first, when broken in the file)
  --   (bowling)  summary_bowling_line reading a missing wides figure as nought
  --   (same)     player_dismissals_since() without its summary branch
  --              (player_batting_since() without its: (career) first)
  --   (season)   player_batting_by_season filing a book's match under the
  --              season it was imported in
  --   (typed)    summary_batting_line's player_id made up for a typed ref
  --   (dossier)  opposition_squad()'s dot_pct over every ball, book and live
  --   (void)     summary_batting_line over ball_event rather than ball_event_live
  -- (scope) stands on two walls and stays green with either one down: the
  -- line's own security_invoker, and ball_event_live's, which a view running
  -- as its owner still reads as its caller. With both down — the line as its
  -- owner, over ball_event — it went red; with only the first, section 9
  -- goes red (it now asks for security_invoker=true, not for the option's
  -- name, which a view set to false had passed).
  DECLARE
    M       uuid := _seed_64();
    I       uuid;
    M_OPP   uuid;
    A1      uuid;
    A2      uuid;
    r       record;
    got     text;
    who     uuid;
    v_start timestamptz;
    p2b     record;
    p2a     record;
    o1b     record;
    o1a     record;
    BK_A    uuid := 'aaaaaaaa-0000-0000-0000-0000000064a0';   -- run out 25; the book has no balls column for him
    BK_B    uuid := 'aaaaaaaa-0000-0000-0000-0000000064b0';   -- 4-0-30-2; no wides or no-balls on the book
    P1      uuid := 'aaaaaaaa-0000-0000-0000-000000000001';   -- c t:1 b t:2 34 (40), four fours and a six
    P2      uuid := 'aaaaaaaa-0000-0000-0000-000000000002';   -- bats in ours; bowls 3.2-0-24-1, a wide, in theirs
    U_WESC  uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    TYPED   jsonb := '{"t:1":"Opp Fielder One","t:2":"Opp Bowler Two","t:3":"Opp Bowler Three","t:4":"Opp Fielder Four","t:5":"Opp Bowler Five","t:6":"Opp Six","t:7":"Opp Seven","t:8":"Opp Eight","t:9":"Opp Nine"}';
    -- packages/scoring/test/scorebook-cards.mjs's base card with Hilton's
    -- boys, the fourth of them BK_A: 127 for 4 in 20.
    CARD0   jsonb := '{"v":1,"innings":0,"battingSide":"home","batting":[{"order":1,"ref":"aaaaaaaa-0000-0000-0000-000000000001","howOut":"caught","fielderRef":"t:1","bowlerRef":"t:2","runs":34,"balls":40,"fours":4,"sixes":1},{"order":2,"ref":"aaaaaaaa-0000-0000-0000-000000000002","howOut":"bowled","fielderRef":null,"bowlerRef":"t:2","runs":12,"balls":15,"fours":1,"sixes":0},{"order":3,"ref":"aaaaaaaa-0000-0000-0000-000000000003","howOut":"lbw","fielderRef":null,"bowlerRef":"t:3","runs":0,"balls":3,"fours":0,"sixes":0},{"order":4,"ref":"aaaaaaaa-0000-0000-0000-0000000064a0","howOut":"run_out","fielderRef":"t:4","bowlerRef":null,"runs":25,"balls":null,"fours":null,"sixes":null},{"order":5,"ref":"aaaaaaaa-0000-0000-0000-000000000005","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":40,"balls":30,"fours":5,"sixes":1},{"order":6,"ref":"aaaaaaaa-0000-0000-0000-000000000011","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":5,"balls":4,"fours":0,"sixes":0}],"didNotBat":[],"bowling":[{"ref":"t:2","overs":"8","maidens":0,"runs":40,"wickets":2,"wides":3,"noBalls":1},{"ref":"t:3","overs":"8","maidens":1,"runs":45,"wickets":1,"wides":2,"noBalls":2},{"ref":"t:5","overs":"4","maidens":null,"runs":39,"wickets":0,"wides":null,"noBalls":null}],"extras":{"byes":2,"legByes":1,"wides":5,"noBalls":3,"penalty":0},"total":127,"wickets":4,"overs":"20","fallOfWickets":[{"wicket":1,"score":30,"ref":"aaaaaaaa-0000-0000-0000-000000000002","over":"5.1"},{"wicket":2,"score":31,"ref":"aaaaaaaa-0000-0000-0000-000000000003","over":"5.3"},{"wicket":3,"score":60,"ref":"aaaaaaaa-0000-0000-0000-000000000001","over":"10.2"},{"wicket":4,"score":90,"ref":"aaaaaaaa-0000-0000-0000-0000000064a0","over":"15"}],"endReason":"overs","unreconciled":null}';
    -- Theirs: 56 for 3 in 7.2 when time was called, every batter a typed
    -- name, our two bowlers by id, BK_A's catch.
    CARD1   jsonb := '{"v":1,"innings":1,"battingSide":"away","batting":[{"order":1,"ref":"t:6","howOut":"bowled","fielderRef":null,"bowlerRef":"aaaaaaaa-0000-0000-0000-0000000064b0","runs":20,"balls":18,"fours":2,"sixes":0},{"order":2,"ref":"t:7","howOut":"caught","fielderRef":"aaaaaaaa-0000-0000-0000-0000000064a0","bowlerRef":"aaaaaaaa-0000-0000-0000-000000000002","runs":15,"balls":null,"fours":null,"sixes":null},{"order":3,"ref":"t:8","howOut":"lbw","fielderRef":null,"bowlerRef":"aaaaaaaa-0000-0000-0000-0000000064b0","runs":10,"balls":null,"fours":null,"sixes":null},{"order":4,"ref":"t:9","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":8,"balls":null,"fours":null,"sixes":null}],"didNotBat":[],"bowling":[{"ref":"aaaaaaaa-0000-0000-0000-0000000064b0","overs":"4","maidens":null,"runs":30,"wickets":2,"wides":null,"noBalls":null},{"ref":"aaaaaaaa-0000-0000-0000-000000000002","overs":"3.2","maidens":0,"runs":24,"wickets":1,"wides":1,"noBalls":0}],"extras":{"byes":2,"legByes":0,"wides":1,"noBalls":0,"penalty":0},"total":56,"wickets":3,"overs":"7.2","fallOfWickets":[{"wicket":1,"score":20,"ref":"t:6","over":"3.1"},{"wicket":2,"score":38,"ref":"t:7","over":"5"},{"wicket":3,"score":50,"ref":"t:8","over":"6.4"}],"endReason":"time","unreconciled":null}';
  BEGIN
    SELECT starts_at INTO v_start FROM match WHERE id = M;
    M_OPP := _opposition_fixture(opposition_window_days() - 1);
    -- Before: P2's bowling, as the director reads it; P1 in Westville's
    -- dossier on Hilton's 1XI, as their coach reads it.
    PERFORM _as(U_SARAH);
    SELECT coalesce(max(c.matches), 0) AS matches, coalesce(max(c.runs_conceded), 0) AS runs, coalesce(max(c.legal_balls), 0) AS balls,
           coalesce(max(c.wides), 0) AS wides, coalesce(max(c.no_balls), 0) AS no_balls, coalesce(max(c.wickets), 0) AS wickets
      INTO p2b FROM player_bowling_career c WHERE c.player_id = P2;
    PERFORM _as(U_WESC);
    SELECT o.innings, o.runs, o.balls, o.dismissals, o.dots, o.dot_pct INTO o1b FROM opposition_squad(M_OPP) o WHERE o.player_id = P1;
    PERFORM _assert(o1b.innings IS NOT NULL, 'db/64: Westville''s coach reads no dossier on Hilton''s 1XI');

    -- The import: the scorer types both cards, the director of sport confirms.
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scorebook_import_open(M);
    PERFORM _assert(r.ok, format('db/64: the scorer could not open an import (%s)', r.reason));
    I := r.import_id;
    SELECT * INTO r FROM scorebook_import_save(I, jsonb_build_array(CARD0, CARD1), TYPED, '{}'::jsonb,
                                               (SELECT version FROM scorebook_import WHERE id = I));
    PERFORM _assert(r.ok, format('db/64: the save was refused (%s %s)', r.reason, r.detail));
    SELECT * INTO r FROM scorebook_import_submit(I, r.version);
    PERFORM _assert(r.ok, format('db/64: the submit was refused (%s %s)', r.reason, r.detail));
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM scorebook_import_commit(I, '{}'::uuid[], false);
    PERFORM _assert(r.ok, format('db/64: the director of sport could not confirm (%s %s)', r.reason, r.detail));

    -- (career) the batter's line is the card's, balls and boundaries NULL
    SELECT concat_ws(' | ',
      (SELECT row(i.innings, i.runs, i.balls_faced, i.out, i.ended_at = v_start)::text FROM player_innings i WHERE i.player_id = BK_A),
      (SELECT row(c.matches, c.runs, c.balls_faced, c.fours, c.sixes, c.last_ball_at = v_start)::text FROM player_batting_career c WHERE c.player_id = BK_A),
      (SELECT row(c.matches, c.runs, c.balls_faced, c.fours, c.sixes)::text FROM player_batting_since(BK_A, NULL) c),
      (SELECT d.dismissals::text FROM player_dismissals d WHERE d.player_id = BK_A),
      (SELECT string_agg(d.dismissal || '=' || d.dismissals, ',') FROM player_dismissal_breakdown d WHERE d.player_id = BK_A),
      (SELECT row(u.innings_without_balls, u.runs_without_balls, u.innings_without_boundaries, u.bowling_without_extras)::text
         FROM player_unrecorded_figures u WHERE u.player_id = BK_A))
      INTO got;
    PERFORM _assert(got = '(0,25,,t,t) | (1,25,,,,t) | (1,25,,,) | 1 | run_out=1 | (1,25,1,0)',
      format('db/64 (career): BK_A reads %s, where the card says run out 25, balls, fours and sixes not recorded', got));

    -- (bowling) the bowler's line is the card's, wides and no-balls NULL;
    -- and P2's recorded figures moved by exactly his row
    SELECT concat_ws(' | ',
      (SELECT row(c.matches, c.runs_conceded, c.legal_balls, c.wides, c.no_balls, c.wickets)::text FROM player_bowling_career c WHERE c.player_id = BK_B),
      (SELECT row(c.matches, c.runs_conceded, c.legal_balls, c.wides, c.no_balls, c.wickets)::text FROM player_bowling_since(BK_B, NULL) c),
      (SELECT row(f.innings, f.wickets, f.runs_conceded)::text FROM bowler_innings_figures f WHERE f.player_id = BK_B),
      (SELECT string_agg(w.dismissal || '=' || w.wickets, ',' ORDER BY w.dismissal) FROM player_wicket_breakdown w WHERE w.player_id = BK_B),
      (SELECT row(u.bowling_without_extras)::text FROM player_unrecorded_figures u WHERE u.player_id = BK_B))
      INTO got;
    SELECT c.matches, c.runs_conceded AS runs, c.legal_balls AS balls, c.wides, c.no_balls, c.wickets
      INTO p2a FROM player_bowling_career c WHERE c.player_id = P2;
    PERFORM _assert(got = '(1,30,24,,,2) | (1,30,24,,,2) | (1,2,30) | bowled=1,lbw=1 | (1)'
                    AND p2a.matches = p2b.matches + 1 AND p2a.runs = p2b.runs + 24 AND p2a.balls = p2b.balls + 20
                    AND p2a.wides = p2b.wides + 1 AND p2a.no_balls = p2b.no_balls AND p2a.wickets = p2b.wickets + 1,
      format('db/64 (bowling): BK_B reads %s, where the card says 4-0-30-2 with no extras; P2 moved from %s to %s, where the card says 3.2-0-24-1 with a wide',
             got, p2b, p2a));

    -- (season) filed under the season of the match's start, not of the commit
    SELECT string_agg(format('%s:%s', f, s = school_season_of(v_start)), ' ' ORDER BY f) INTO got
      FROM (SELECT 'bat' AS f, b.season AS s FROM player_batting_by_season b WHERE b.player_id = BK_A
            UNION ALL SELECT 'bowl', w.season FROM player_bowling_by_season w WHERE w.player_id = BK_B
            UNION ALL SELECT 'out', d.season FROM player_dismissals_by_season d WHERE d.player_id = BK_A
            UNION ALL SELECT 'unrecorded', u.season FROM player_unrecorded_figures u WHERE u.player_id = BK_A) x;
    PERFORM _assert(got = 'bat:t bowl:t out:t unrecorded:t' AND school_season_of(v_start) <> school_season_of(now()),
      format('db/64 (season): the book''s figures are filed %s, the match in %s and the commit in %s',
             got, school_season_of(v_start), school_season_of(now())));

    -- (same) Σ seasons = lifetime = the windowed functions, as every reader
    FOREACH who IN ARRAY ARRAY[U_OWNER, U_SARAH, U_SCORER, U_COACH, U_WESC, U_PARENT] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO n FROM (SELECT 1 FROM _career_season_drift() UNION ALL SELECT 1 FROM _career_lifetime_drift()) d;
      PERFORM _assert(n = 0, format('db/64 (same), as %s: %s career figure(s) differ between the seasons, the lifetime views and the functions', who, n));
    END LOOP;

    -- (typed) a name the scorer typed is nobody: no player row, no line's id
    PERFORM _as(U_OWNER);
    SELECT format('%s typed lines, %s of them somebody; %s players named as typed; %s innings rows',
                  count(*) FILTER (WHERE l.ref LIKE 't:%'),
                  count(*) FILTER (WHERE (l.ref LIKE 't:%' AND l.player_id IS NOT NULL)
                                      OR (l.bowler_ref LIKE 't:%' AND l.bowler_id IS NOT NULL)),
                  _typed_players_64(), (SELECT count(*) FROM player_innings i WHERE i.match_id = M))
      INTO got FROM summary_batting_line l WHERE l.match_id = M;
    PERFORM _assert(got = '4 typed lines, 0 of them somebody; 0 players named as typed; 6 innings rows',
      format('db/64 (typed): %s (expected 4 typed lines, none somebody, no player, our six boys'' innings)', got));

    -- (dossier) Westville's coach reads BK_A's runs and no dot percentage;
    -- P1's book innings moves his runs, balls and innings, never his dots
    PERFORM _as(U_WESC);
    SELECT concat_ws(' | ',
      (SELECT row(o.innings, o.runs, o.balls, o.dismissals, o.fours, o.sixes, o.dots, o.strike_rate, o.dot_pct)::text
         FROM opposition_squad(M_OPP) o WHERE o.player_id = BK_A),
      (SELECT row(o.balls_bowled, o.runs_conceded, o.wickets, o.economy)::text FROM opposition_squad(M_OPP) o WHERE o.player_id = BK_B))
      INTO got;
    SELECT o.innings, o.runs, o.balls, o.dismissals, o.dots, o.dot_pct INTO o1a FROM opposition_squad(M_OPP) o WHERE o.player_id = P1;
    PERFORM _assert(got = '(1,25,,0,,,,,) | (24,30,2,)'
                    AND o1a.innings = o1b.innings + 1 AND o1a.runs = o1b.runs + 34 AND o1a.balls = o1b.balls + 40
                    AND o1a.dismissals = o1b.dismissals + 1 AND o1a.dots = o1b.dots AND o1a.dot_pct IS NOT DISTINCT FROM o1b.dot_pct,
      format('db/64 (dossier): BK_A and BK_B read %s (expected his 25 in one innings and nothing unrecorded counted; 24 balls, 30, 2); P1 from %s to %s',
             got, o1b, o1a));

    -- (scope) nobody who could not read the match's log reads a book line
    FOREACH who IN ARRAY ARRAY[U_PARENT, U_WESC, NULL] LOOP
      PERFORM set_config('app.user_id', coalesce(who::text, ''), true);
      SELECT (SELECT count(*) FROM summary_batting_line WHERE match_id = M) + (SELECT count(*) FROM summary_bowling_line WHERE match_id = M)
           + (SELECT count(*) FROM player_batting_career WHERE player_id = BK_A)
           + (SELECT count(*) FROM player_unrecorded_figures WHERE player_id IN (BK_A, BK_B)) INTO n;
      PERFORM _assert(n = 0, format('db/64 (scope): %s read %s rows of the book''s figures', coalesce(who::text, 'nobody'), n));
    END LOOP;

    -- (void) an approved amendment voiding each summary takes both boys out
    -- of every view, and puts P2 and P1 back where they were
    PERFORM _as(U_SCORER);
    INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
    VALUES (M, HIL, format('scorebook:%s:0:summary', I), 'The book was another fixture''s.', U_SCORER) RETURNING id INTO A1;
    INSERT INTO scoring_amendment (match_id, school_id, target_key, reason, requested_by)
    VALUES (M, HIL, format('scorebook:%s:1:summary', I), 'The book was another fixture''s.', U_SCORER) RETURNING id INTO A2;
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM scoring_amendment_decide(A1, true, 'Checked against the book.');
    PERFORM _assert(r.ok, format('db/64: the first void was not approved (%s)', r.reason));
    SELECT * INTO r FROM scoring_amendment_decide(A2, true, 'Checked against the book.');
    PERFORM _assert(r.ok, format('db/64: the second void was not approved (%s)', r.reason));
    SELECT (SELECT count(*) FROM summary_batting_line WHERE match_id = M) + (SELECT count(*) FROM summary_bowling_line WHERE match_id = M)
         + (SELECT count(*) FROM player_innings WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_batting_career WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_bowling_career WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_dismissals WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_dismissal_breakdown WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_batting_by_season WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_bowling_by_season WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_dismissals_by_season WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM bowler_innings_figures WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_wicket_breakdown WHERE player_id IN (BK_A, BK_B))
         + (SELECT count(*) FROM player_unrecorded_figures WHERE player_id IN (BK_A, BK_B))
         + (SELECT matches FROM player_batting_since(BK_A, NULL)) + (SELECT matches FROM player_bowling_since(BK_B, NULL))
         + player_dismissals_since(BK_A, NULL)
      INTO n;
    SELECT coalesce(max(c.matches), 0) AS matches, coalesce(max(c.runs_conceded), 0) AS runs, coalesce(max(c.legal_balls), 0) AS balls,
           coalesce(max(c.wides), 0) AS wides, coalesce(max(c.no_balls), 0) AS no_balls, coalesce(max(c.wickets), 0) AS wickets
      INTO p2a FROM player_bowling_career c WHERE c.player_id = P2;
    PERFORM _as(U_WESC);
    SELECT concat_ws(' | ',
      (SELECT row(o.innings, o.runs, o.balls, o.dots)::text FROM opposition_squad(M_OPP) o WHERE o.player_id = BK_A),
      (SELECT row(o.balls_bowled, o.runs_conceded, o.wickets)::text FROM opposition_squad(M_OPP) o WHERE o.player_id = BK_B))
      INTO got;
    SELECT o.innings, o.runs, o.balls, o.dismissals, o.dots, o.dot_pct INTO o1a FROM opposition_squad(M_OPP) o WHERE o.player_id = P1;
    PERFORM _assert(n = 0 AND got = '(0,0,0,0) | (0,0,0)'
                    AND row(p2a.matches, p2a.runs, p2a.balls, p2a.wides, p2a.no_balls, p2a.wickets)::text
                        IS NOT DISTINCT FROM row(p2b.matches, p2b.runs, p2b.balls, p2b.wides, p2b.no_balls, p2b.wickets)::text
                    AND row(o1a.innings, o1a.runs, o1a.balls, o1a.dismissals, o1a.dots, o1a.dot_pct)::text
                        = row(o1b.innings, o1b.runs, o1b.balls, o1b.dismissals, o1b.dots, o1b.dot_pct)::text,
      format('db/64 (void): after the voids %s rows still read the book, the dossier reads %s, P2 %s (was %s), P1 %s (was %s)',
             n, got, p2a, p2b, o1a, o1b));
    FOREACH who IN ARRAY ARRAY[U_OWNER, U_SARAH] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO n FROM (SELECT 1 FROM _career_season_drift() UNION ALL SELECT 1 FROM _career_lifetime_drift()) d;
      PERFORM _assert(n = 0, format('db/64 (same), after the voids, as %s: %s career figure(s) differ', who, n));
    END LOOP;
  END;

  -- ── 43. Availability asks again when the fixture changes (SCRBRD-122, db/65) ──
  -- Each answer carries the fixture as it stood when it was given; a change
  -- to its time, ground, format or overs makes the answer read
  -- needs_reconfirming (not its status), keeps the old answer readable, and
  -- asks whoever gave it and the boy's live guardians to answer again. A
  -- change to anything else (the opponent's name) does none of that, and a
  -- re-declaration clears it. Four families: Whitfield (P1) answered by his
  -- guardian, Bekker (P2) by his, Cele (P4) by the director of sport, and
  -- R Pillay (P5) by himself. tools/smoke-availability.mjs holds the API's
  -- readers (availability, readiness) to the same rule.
  --
  -- Each labelled assertion was falsified once — the thing it guards broken
  -- in db/65, the database rebuilt and this file run — and went red:
  --   (stamp)     availability_stamp_fixture() fired BEFORE INSERT only (a
  --               re-declaration kept the old snapshot: (redeclare) went red),
  --               and stamping only a snapshot the caller left empty (the
  --               supplied one stood)
  --   (opponent)  availability_ask_again() on every update of the fixture,
  --               asking about every answer (the rename asked five people)
  --   (move)      availability_effective() returning the status as given
  --   (ground)    availability_fixture_moved() without the ground
  --   (notice)    availability_ask_again() without its guardians (Cele's
  --               guardian was not asked), and without its live-link test
  --               (R Pillay's parent, whose link the expiry check above ended,
  --               was asked)
  --   (reach)     the notice without its recipient_id: (notice) first; with
  --               (notice) set aside, the director of sport read every
  --               family's notice
  --   (history)   availability_keep_history() dropped
  --   (rls)       the history's person anchor dropped (Bekker's guardian read
  --               Whitfield's earlier answer)
  --   (write)     the history granted to the application
  --   (past)      availability_ask_again() without its future-only test
  DECLARE
    ids     jsonb := _seed_65();
    M       uuid;
    MP      uuid;
    U_WHIT  uuid := '88888888-0000-0000-0000-000000000010';   -- guardian of J Whitfield (P1)
    U_BEKK  uuid := '88888888-0000-0000-0000-000000000011';   -- guardian of T Bekker (P2)
    U_CELE  uuid := '88888888-0000-0000-0000-000000000013';   -- guardian of P4
    P1      uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
    P2      uuid := 'aaaaaaaa-0000-0000-0000-000000000002';
    P4      uuid := 'aaaaaaaa-0000-0000-0000-000000000004';
    GROUND  uuid := 'ffffffff-0000-0000-0000-000000000001';   -- Gordon Sherwood Oval
    v_start timestamptz;
    got     text;
    want    text;
    k       bigint;
    who     uuid;
    r       record;
  BEGIN
    M := (ids->>'m')::uuid; MP := (ids->>'past')::uuid;
    SELECT starts_at INTO v_start FROM match WHERE id = M;

    -- The four answers, each by the person who gives it.
    PERFORM _as(U_WHIT);
    -- A snapshot in the request is not the caller's to give.
    INSERT INTO match_availability (match_id, player_id, school_id, status, declared_by,
                                    fixture_starts_at, fixture_ground_id, fixture_format, fixture_overs)
    VALUES (M, P1, HIL, 'available', U_WHIT, '2000-01-01', NULL, 'Test', 90);
    PERFORM _as(U_BEKK);
    INSERT INTO match_availability (match_id, player_id, school_id, status, reason_kind, declared_by)
    VALUES (M, P2, HIL, 'unavailable', 'family', U_BEKK);
    PERFORM _as(U_SARAH);
    INSERT INTO match_availability (match_id, player_id, school_id, status, reason_kind, declared_by)
    VALUES (M, P4, HIL, 'doubtful', 'academic', U_SARAH);
    PERFORM _as(U_SELF);
    INSERT INTO match_availability (match_id, player_id, school_id, status, declared_by)
    VALUES (M, P_INJURED, HIL, 'available', U_SELF);

    -- (stamp) every answer carries the fixture as it stands, whatever was sent
    PERFORM _as(U_SARAH);
    SELECT string_agg(format('%s:%s', right(a.player_id::text, 1),
                             (a.fixture_starts_at, a.fixture_ground_id, a.fixture_format, a.fixture_overs)
                               IS NOT DISTINCT FROM (f.starts_at, f.ground_id, f.format, f.overs)), ' ' ORDER BY a.player_id)
      INTO got FROM match_availability a JOIN match f ON f.id = a.match_id WHERE a.match_id = M;
    PERFORM _assert(got = '1:t 2:t 4:t 5:t',
      format('db/65 (stamp): the answers'' snapshots against the fixture read %s', got));
    PERFORM _assert(_eff_65(M) = '1=available 2=unavailable 4=doubtful 5=available',
      format('db/65: before any change the answers read %s', _eff_65(M)));

    -- (opponent) a change to what is not in the snapshot asks nobody anything
    UPDATE match SET opponent = 'Verify 065 Renamed' WHERE id = M;
    GET DIAGNOSTICS k = ROW_COUNT;
    PERFORM _assert(k = 1, 'db/65: the director of sport could not rename the opposition');
    PERFORM _assert(_eff_65(M) = '1=available 2=unavailable 4=doubtful 5=available' AND _notice_count_65(M) = 0,
      format('db/65 (opponent): renaming the opposition made the answers read %s and wrote %s notice(s)',
             _eff_65(M), _notice_count_65(M)));

    -- (move) the fixture moves a day: every answer asks again, the old one kept
    UPDATE match SET starts_at = starts_at + interval '1 day' WHERE id = M;
    PERFORM _assert(_eff_65(M) = '1=needs_reconfirming 2=needs_reconfirming 4=needs_reconfirming 5=needs_reconfirming',
      format('db/65 (move): after the move the answers read %s', _eff_65(M)));
    SELECT string_agg(format('%s:%s:%s', right(a.player_id::text, 1), a.status, a.fixture_starts_at = v_start), ' ' ORDER BY a.player_id)
      INTO got FROM match_availability a WHERE a.match_id = M;
    PERFORM _assert(got = '1:available:t 2:unavailable:t 4:doubtful:t 5:available:t',
      format('db/65 (move): the answers as given, and the fixture they were about, read %s', got));

    -- (notice) whoever answered, and the boy's live guardians, once each
    SELECT string_agg(x, ' ' ORDER BY x) INTO want FROM unnest(ARRAY[
      U_WHIT || '/' || P1 || '/availability',            -- answered, and his guardian: once
      U_BEKK || '/' || P2 || '/availability',
      U_SARAH || '/' || P4 || '/availability',           -- the director of sport, who recorded it
      U_CELE || '/' || P4 || '/availability',            -- and the boy's guardian, who did not
      U_SELF || '/' || P_INJURED || '/system']           -- a pupil: the system's own notice (SG-9)
      || CASE WHEN _link_live_65(P_INJURED, U_PARENT) THEN ARRAY[U_PARENT || '/' || P_INJURED || '/availability'] ELSE '{}'::text[] END) x;
    PERFORM _assert(_notices_65(M) = want,
      format('db/65 (notice): the move asked %s; expected %s', _notices_65(M), want));

    -- (reach) each reads his own notice and nobody else's
    FOR r IN SELECT * FROM (VALUES (U_WHIT, P1), (U_BEKK, P2), (U_SARAH, P4), (U_CELE, P4), (U_SELF, P_INJURED)) v(who, boy) LOOP
      PERFORM _as(r.who);
      SELECT string_agg(n.subject_person_id || ':' || (n.body LIKE '%is now%' AND n.body LIKE '%was for%'), ',') INTO got
        FROM notification n WHERE n.subject_id = M;
      PERFORM _assert(got = r.boy || ':true', format('db/65 (reach): %s reads %s of the fixture''s notices', r.who, got));
    END LOOP;
    FOREACH who IN ARRAY ARRAY[U_WATCHER, U_COACH2, U_NAIDOO] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO n FROM notification WHERE subject_id = M;
      PERFORM _assert(n = 0, format('db/65 (reach): %s reads %s of the fixture''s notices', who, n));
    END LOOP;

    -- (redeclare) Whitfield's guardian answers again: current, and the old kept
    PERFORM _as(U_WHIT);
    INSERT INTO match_availability (match_id, player_id, school_id, status, declared_by, declared_at)
    VALUES (M, P1, HIL, 'available', U_WHIT, now())
    ON CONFLICT (match_id, player_id) DO UPDATE
      SET status = excluded.status, reason_kind = excluded.reason_kind, note = excluded.note,
          declared_by = excluded.declared_by, declared_at = now();
    PERFORM _assert(_eff_65(M) = '1=available',
      format('db/65 (redeclare): after answering again the guardian reads %s', _eff_65(M)));
    -- (history) the answer it replaced, the fixture it was about, and why
    SELECT string_agg(format('%s:%s:%s:%s', h.status, h.fixture_starts_at = v_start, h.was_stale, h.superseded_by = U_WHIT), ' ')
      INTO got FROM match_availability_history h WHERE h.match_id = M;
    PERFORM _assert(got = 'available:t:t:t',
      format('db/65 (history): the guardian reads the history %s', got));

    -- (rls) a guardian reads his own child's answers and history, nobody else's
    SELECT (SELECT count(*) FROM match_availability WHERE match_id = M AND player_id <> P1)
         + (SELECT count(*) FROM match_availability_history WHERE match_id = M AND player_id <> P1) INTO n;
    PERFORM _assert(n = 0, format('db/65 (rls): Whitfield''s guardian reads %s row(s) of other boys''', n));
    PERFORM _as(U_BEKK);
    INSERT INTO match_availability (match_id, player_id, school_id, status, reason_kind, declared_by)
    VALUES (M, P2, HIL, 'unavailable', 'family', U_BEKK)
    ON CONFLICT (match_id, player_id) DO UPDATE
      SET status = excluded.status, reason_kind = excluded.reason_kind, declared_by = excluded.declared_by, declared_at = now();
    SELECT string_agg(right(h.player_id::text, 1), ',') INTO got FROM match_availability_history h WHERE h.match_id = M;
    PERFORM _assert(got = '2' AND _eff_65(M) = '2=unavailable',
      format('db/65 (rls): Bekker''s guardian reads the history of %s and the answers %s', got, _eff_65(M)));
    FOREACH who IN ARRAY ARRAY[U_WATCHER, U_COACH2, U_NAIDOO] LOOP
      PERFORM _as(who);
      SELECT (SELECT count(*) FROM match_availability WHERE match_id = M)
           + (SELECT count(*) FROM match_availability_history WHERE match_id = M) INTO n;
      PERFORM _assert(n = 0, format('db/65 (rls): %s reads %s answer(s) or earlier answer(s)', who, n));
    END LOOP;
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM match_availability_history WHERE match_id = M;
    PERFORM _assert(n = 2 AND _eff_65(M) = '1=available 2=unavailable 4=needs_reconfirming 5=needs_reconfirming',
      format('db/65 (rls): the director of sport reads %s earlier answers and %s', n, _eff_65(M)));
    -- match_availability's own policies, as db/39 left them.
    SELECT string_agg(policyname || ':' || (coalesce(qual, '') || coalesce(with_check, '') LIKE '%match_school(match_id), match_team(match_id), player_id, match_id)%'), ' ' ORDER BY policyname)
      INTO got FROM pg_policies WHERE tablename = 'match_availability' AND policyname NOT LIKE 'pad_scope_%';
    PERFORM _assert(got = 'match_availability_insert:true match_availability_read:true match_availability_update:true',
      format('db/65 (rls): match_availability''s policies are now %s', got));

    -- (write) nobody writes the history but its trigger
    PERFORM _as(U_WHIT);
    BEGIN
      INSERT INTO match_availability_history (match_id, player_id, school_id, status, declared_at, fixture_starts_at, was_stale)
      VALUES (M, P1, HIL, 'unavailable', now(), now(), false);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/65 (write): a guardian wrote an earlier answer into the history');
    BEGIN
      UPDATE match_availability_history SET status = 'unavailable' WHERE match_id = M;
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/65 (write): a guardian rewrote the history');

    -- (ground) a new ground alone asks again; the old ground back answers it
    PERFORM _as(U_SARAH);
    k := _notice_count_65(M);
    UPDATE match SET ground_id = NULL WHERE id = M;
    PERFORM _assert(_eff_65(M) = '1=needs_reconfirming 2=needs_reconfirming 4=needs_reconfirming 5=needs_reconfirming'
                    AND _notice_count_65(M) = k + 5 + CASE WHEN _link_live_65(P_INJURED, U_PARENT) THEN 1 ELSE 0 END,
      format('db/65 (ground): with no ground the answers read %s, and %s notice(s) were added', _eff_65(M), _notice_count_65(M) - k));
    UPDATE match SET ground_id = GROUND WHERE id = M;
    -- (back) the fixture back where it was: the two answered for the move
    -- stand, and Cele's, given for the original, asks again no more once the
    -- day is back too
    PERFORM _assert(_eff_65(M) = '1=available 2=unavailable 4=needs_reconfirming 5=needs_reconfirming',
      format('db/65 (back): with the ground back the answers read %s', _eff_65(M)));
    UPDATE match SET starts_at = v_start WHERE id = M;
    PERFORM _assert(_eff_65(M) = '1=needs_reconfirming 2=needs_reconfirming 4=doubtful 5=available',
      format('db/65 (back): with the day back the answers read %s', _eff_65(M)));

    -- (past) a played fixture's time corrected asks nobody, though it reads so
    PERFORM _as(U_WHIT);
    INSERT INTO match_availability (match_id, player_id, school_id, status, declared_by)
    VALUES (MP, P1, HIL, 'available', U_WHIT);
    PERFORM _as(U_SARAH);
    UPDATE match SET starts_at = starts_at - interval '1 hour', overs = 25 WHERE id = MP;
    PERFORM _assert(_eff_65(MP) = '1=needs_reconfirming' AND _notice_count_65(MP) = 0,
      format('db/65 (past): the played fixture''s answer reads %s and %s notice(s) went out', _eff_65(MP), _notice_count_65(MP)));
  END;

  -- ── 44. The scorebook importer, phase 4: the reader (SCRBRD-120, db/66) ──
  -- The design's phase 4 proofs (§8) that the database can show: with the
  -- reader off, nothing starts (the route then says `off`); the platform's
  -- default, even locked on, turns it on for no school — only a grant for
  -- the school does; a read writes read_by with the pages' hashes, and names
  -- no page the import has not got; the person who pressed Read is an author
  -- of the card and cannot confirm it; the read cells are not ticked. The
  -- adapter's half (the request carries the pages and nothing else; an id
  -- in a name cell is dropped) is services/api/ai/scorebook-reader.test.mjs;
  -- the route's is tools/smoke-scorebook.mjs group L.
  --
  -- Each labelled assertion was falsified once — the guard broken in db/66,
  -- the function replaced in the database and this file run — and went red:
  --   (default)  scorebook_reader_on() without its per-school grant clause
  --   (off)      scorebook_import_read_start() without the reader check
  --   (sent)     scorebook_import_read_start() without its access_log rows
  --   (pages)    scorebook_import_read_done() without the pages_unknown check
  --   (typed)    scorebook_import_read_done() taking an id as a typed name
  --   (ticks)    scorebook_import_read_done() carrying the old ticks over
  --   (yours)    scorebook_import_read_done() without not_yours
  DECLARE
    ids   jsonb := _seed_66();
    M uuid; M2 uuid; I uuid; I2 uuid;
    H1 text := repeat('d', 64); H2 text := repeat('e', 64); H3 text := repeat('f', 64);
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';
    r     record;
    v     integer;
    x     scorebook_import;
    got   text;
    S_ID  uuid;
    DRAFT jsonb := '{"v":1,"innings":0,"battingSide":"home","batting":[{"order":1,"ref":"aaaaaaaa-0000-0000-0000-000000000001","howOut":"caught","fielderRef":"t:1","bowlerRef":null,"runs":34,"balls":null,"fours":null,"sixes":null}],"didNotBat":[],"bowling":[],"extras":{"byes":null,"legByes":null,"wides":null,"noBalls":null,"penalty":null},"total":135,"wickets":null,"overs":"20","fallOfWickets":[],"endReason":null,"unreconciled":null}';
    TYPED jsonb := '{"t:1":"Opp Fielder One","t:2":"Opp Bowler Two","t:3":"Opp Bowler Three","t:4":"Opp Fielder Four","t:5":"Opp Bowler Five"}';
    CARD  jsonb := '{"v":1,"innings":0,"battingSide":"home","batting":[{"order":1,"ref":"aaaaaaaa-0000-0000-0000-000000000001","howOut":"caught","fielderRef":"t:1","bowlerRef":"t:2","runs":34,"balls":40,"fours":4,"sixes":1},{"order":2,"ref":"aaaaaaaa-0000-0000-0000-000000000002","howOut":"bowled","fielderRef":null,"bowlerRef":"t:2","runs":12,"balls":15,"fours":1,"sixes":0},{"order":3,"ref":"aaaaaaaa-0000-0000-0000-000000000003","howOut":"lbw","fielderRef":null,"bowlerRef":"t:3","runs":0,"balls":3,"fours":0,"sixes":0},{"order":4,"ref":"aaaaaaaa-0000-0000-0000-000000000004","howOut":"run_out","fielderRef":"t:4","bowlerRef":null,"runs":25,"balls":null,"fours":null,"sixes":null},{"order":5,"ref":"aaaaaaaa-0000-0000-0000-000000000005","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":40,"balls":30,"fours":5,"sixes":1},{"order":6,"ref":"aaaaaaaa-0000-0000-0000-000000000011","howOut":"not_out","fielderRef":null,"bowlerRef":null,"runs":5,"balls":4,"fours":0,"sixes":0}],"didNotBat":["aaaaaaaa-0000-0000-0000-000000000012"],"bowling":[{"ref":"t:2","overs":"8","maidens":0,"runs":40,"wickets":2,"wides":3,"noBalls":1},{"ref":"t:3","overs":"8","maidens":1,"runs":45,"wickets":1,"wides":2,"noBalls":2},{"ref":"t:5","overs":"4","maidens":null,"runs":39,"wickets":0,"wides":null,"noBalls":null}],"extras":{"byes":2,"legByes":1,"wides":5,"noBalls":3,"penalty":0},"total":127,"wickets":4,"overs":"20","fallOfWickets":[{"wicket":1,"score":30,"ref":"aaaaaaaa-0000-0000-0000-000000000002","over":"5.1"},{"wicket":2,"score":31,"ref":"aaaaaaaa-0000-0000-0000-000000000003","over":"5.3"},{"wicket":3,"score":60,"ref":"aaaaaaaa-0000-0000-0000-000000000001","over":"10.2"},{"wicket":4,"score":90,"ref":"aaaaaaaa-0000-0000-0000-000000000004","over":"15"}],"endReason":"overs","unreconciled":null}';
    CELLS jsonb := '{"total":{"c":0.98,"p":1,"b":[0.64,0.86,0.04,0.04],"v":135},"batting.0.ref":{"c":0.95,"p":1,"b":null,"v":"aaaaaaaa-0000-0000-0000-000000000001"}}';
  BEGIN
    M := (ids->>'m')::uuid; M2 := (ids->>'m2')::uuid;

    -- The scorer opens an import and adds three photos; the third comes off.
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scorebook_import_open(M);
    PERFORM _assert(r.ok, format('db/66: the scorer could not open an import (%s)', r.reason));
    I := r.import_id;
    PERFORM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.jpg', H1, 1000, 1600, 1100, 'image/jpeg');
    PERFORM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.png', H2, 1000, 1600, 1100, 'image/png');
    PERFORM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.jpg', H3, 1000, 1600, 1100, 'image/jpeg');
    PERFORM scorebook_import_page_remove(I, 3);
    -- A tick left over from typing (card 0's total), which a read must not keep.
    SELECT version INTO v FROM scorebook_import WHERE id = I;
    SELECT * INTO r FROM scorebook_import_save(I, '[]', '{}', '{"0.total":true}', v);
    PERFORM _assert(r.ok, format('db/66: the scorer could not save (%s)', r.reason));
    v := r.version;

    -- (off) where the platform has not granted the reader, nothing starts.
    PERFORM _assert(NOT scorebook_reader_may(I), 'db/66 (off): the scorer is told the reader is on');
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM _assert(NOT r.ok AND r.reason = 'reader_off', format('db/66 (off): a read began without the reader (%s)', r.reason));
    PERFORM _assert((_import_66(I)).state = 'review' AND _sent_66(I) = '', 'db/66 (off): a refused read moved the import or logged a page');
    -- (default) the platform's default on, even locked, is on for no school.
    PERFORM _default_66(true);
    PERFORM _assert(NOT scorebook_reader_may(I), 'db/66 (default): the platform default turned the reader on for Hilton');
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM _assert(NOT r.ok AND r.reason = 'reader_off', format('db/66 (default): a read began under the platform default (%s)', r.reason));
    PERFORM _default_66(false);

    -- The platform grants it to Hilton.
    PERFORM _grant_66(HIL, true);
    -- (may) the writers of the import, and nobody else.
    FOREACH got IN ARRAY ARRAY[U_SCORER || ':t', U_OWNER || ':t', U_SARAH || ':f', U_HEAD_M || ':f', U_PARENT || ':f',
                               U_PUPIL || ':f', U_WATCHER || ':f', U_WESC || ':f', U_PLAT || ':f', U_LEAGUE || ':f'] LOOP
      PERFORM _as(split_part(got, ':', 1)::uuid);
      PERFORM _assert(scorebook_reader_may(I)::text = CASE split_part(got, ':', 2) WHEN 't' THEN 'true' ELSE 'false' END,
        format('db/66 (may): %s is told %s', split_part(got, ':', 1), scorebook_reader_may(I)));
    END LOOP;
    -- (start) nobody but a writer, as themself, starts a read.
    FOREACH got IN ARRAY ARRAY[U_SARAH::text, U_HEAD_M::text, U_PARENT::text, U_PUPIL::text, U_WESC::text, U_LEAGUE::text] LOOP
      PERFORM _as(got::uuid);
      SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/66 (start): %s began a read (%s)', got, r.reason));
    END LOOP;
    PERFORM _as(U_PLAT);
    SELECT s.ok, s.id INTO r FROM support_access_begin(HIL, 'scorer', 'ticket 6601: the reader will not start') s;
    S_ID := r.id;
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM support_access_end(S_ID);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/66 (start): a support session as a scorer began a read (%s)', r.reason));
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/66 (start): a pad''s credential began a read (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v - 1);
    PERFORM _assert(NOT r.ok AND r.reason = 'version_conflict', format('db/66 (start): a read over an older version (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_start(I, 4, v);
    PERFORM _assert(NOT r.ok AND r.reason = 'innings_invalid', format('db/66 (start): a fifth innings (%s)', r.reason));

    -- (sent) the scorer presses Read: the live pages only, each on access_log first.
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM _assert(r.ok, format('db/66: the scorer could not start a read (%s %s)', r.reason, r.detail));
    PERFORM _assert((SELECT string_agg((p->>'pageNo') || ':' || (p->>'sha256'), ',' ORDER BY (p->>'pageNo')::int) FROM jsonb_array_elements(r.pages) p)
                    = '1:' || H1 || ',2:' || H2, format('db/66: the read was given %s', r.pages));
    PERFORM _assert(_sent_66(I) = U_SCORER || ':page:1 ' || U_SCORER || ':page:2', format('db/66 (sent): access_log says %s', _sent_66(I)));
    x := _import_66(I);
    PERFORM _assert(x.state = 'reading' AND x.reading_by = U_SCORER AND x.reading_from = 'review' AND x.reading_innings = 0 AND x.version = v,
      format('db/66: reading reads %s', row(x.state, x.reading_by, x.reading_from, x.reading_innings, x.version)));
    -- While it reads, nothing else changes it.
    SELECT * INTO r FROM scorebook_import_save(I, '[]', '{}', '{}', v);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_editable', format('db/66: a save while reading (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_page_add(I, HIL || '/' || I || '/' || gen_random_uuid() || '.jpg', repeat('9', 64), 1000, 1600, 1100, 'image/jpeg');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_editable', format('db/66: a page added while reading (%s)', r.reason));
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM _assert(NOT r.ok AND r.reason = 'reading', format('db/66: a second read while one is in progress (%s)', r.reason));
    -- (yours) only the person who pressed Read finishes it.
    SELECT * INTO r FROM scorebook_import_read_done(I, DRAFT, '{"t:1":"Opp One"}', CELLS, 'anthropic', 'claude-opus-5-5', ARRAY[H1, H2], 'read');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_yours', format('db/66 (yours): the owner finished the scorer''s read (%s)', r.reason));
    PERFORM _as(U_SCORER);
    -- (pages) the record names only this import's live pages.
    SELECT * INTO r FROM scorebook_import_read_done(I, DRAFT, '{"t:1":"Opp One"}', CELLS, 'anthropic', 'claude-opus-5-5', ARRAY[H1, H3], 'read');
    PERFORM _assert(NOT r.ok AND r.reason = 'pages_unknown', format('db/66 (pages): a removed page recorded as sent (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_done(I, DRAFT, '{"t:1":"Opp One"}', CELLS, 'anthropic', 'claude-opus-5-5', ARRAY[repeat('a', 64)], 'read');
    PERFORM _assert(NOT r.ok AND r.reason = 'pages_unknown', format('db/66 (pages): another import''s page recorded as sent (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_done(I, DRAFT, '{"t:1":"Opp One"}', CELLS, NULL, NULL, NULL, 'read');
    PERFORM _assert(NOT r.ok AND r.reason = 'record_invalid', format('db/66 (pages): a read with no processing record (%s)', r.reason));
    -- (typed) the reader never gives an id as a name.
    SELECT * INTO r FROM scorebook_import_read_done(I, DRAFT, '{"t:1":"aaaaaaaa-0000-0000-0000-000000000009"}', CELLS, 'anthropic', 'claude-opus-5-5', ARRAY[H1, H2], 'read');
    PERFORM _assert(NOT r.ok AND r.reason = 'typed_invalid', format('db/66 (typed): an id became a typed name (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_done(I, jsonb_set(DRAFT, '{innings}', '1'), '{"t:1":"Opp One"}', CELLS, 'anthropic', 'claude-opus-5-5', ARRAY[H1, H2], 'read');
    PERFORM _assert(NOT r.ok AND r.reason = 'card_shape', format('db/66: a card for an innings not asked for (%s)', r.reason));

    -- The read lands: the card added, a `read` revision by the scorer, read_by
    -- written with the pages' hashes, the cell unticked.
    SELECT * INTO r FROM scorebook_import_read_done(I, DRAFT, '{"t:1":"Opp One"}', CELLS, 'anthropic', 'claude-opus-5-5', ARRAY[H2, H1], 'read');
    PERFORM _assert(r.ok AND r.version = v + 1, format('db/66: the read did not land (%s %s)', r.reason, r.detail));
    x := _import_66(I);
    PERFORM _assert(x.state = 'review' AND jsonb_array_length(x.card) = 1 AND x.typed = '{"t:1":"Opp One"}' AND x.reading_by IS NULL
                    AND x.read_cells ? '0' AND x.read_cells->'0'->'total'->>'v' = '135',
      format('db/66: after the read, %s', row(x.state, x.card, x.typed, x.reading_by, x.read_cells)));
    PERFORM _assert(jsonb_array_length(x.read_by) = 1
                    AND (x.read_by->0) - 'at' = jsonb_build_object('provider', 'anthropic', 'model', 'claude-opus-5-5', 'pageHashes', jsonb_build_array(H1, H2),
                                                                   'innings', 0, 'outcome', 'read', 'by', U_SCORER),
      format('db/66 (sent): read_by is %s', x.read_by));
    PERFORM _assert((SELECT action || ':' || actor_id FROM scorebook_import_revision WHERE import_id = I AND version = r.version) = 'read:' || U_SCORER,
      'db/66: the read is not a revision by the person who pressed Read');
    PERFORM _assert((SELECT checked FROM scorebook_import_revision WHERE import_id = I AND version = r.version) = '{}'::jsonb,
      format('db/66 (ticks): the read card starts ticked: %s', (SELECT checked FROM scorebook_import_revision WHERE import_id = I AND version = r.version)));
    -- The principal (audit.read) no longer reads the import row since db/116
    -- (READERS Q2); a parent reads neither.
    PERFORM _as(U_HEAD_M);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM scorebook_import WHERE id = I), 'db/66: the principal (audit.read) reads the processing record (READERS Q2)');
    PERFORM _as(U_PARENT);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM scorebook_import WHERE id = I), 'db/66: a parent reads the processing record');
    PERFORM _as(U_SCORER);
    v := r.version;
    SELECT * INTO r FROM scorebook_import_read_start(I, 0, v);
    PERFORM _assert(NOT r.ok AND r.reason = 'innings_on_card', format('db/66: an innings read over itself (%s)', r.reason));

    -- A read that fails after the pages went: back to where it was, and the
    -- processing record says so. One that sent nothing records nothing.
    SELECT * INTO r FROM scorebook_import_read_start(I, 1, v);
    PERFORM _assert(r.ok, format('db/66: the second read did not start (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_done(I, NULL, NULL, NULL, 'anthropic', 'claude-opus-5-5', ARRAY[H1, H2], 'timeout');
    PERFORM _assert(r.ok, format('db/66: a timed-out read was not recorded (%s)', r.reason));
    x := _import_66(I);
    PERFORM _assert(x.state = 'review' AND jsonb_array_length(x.card) = 1 AND jsonb_array_length(x.read_by) = 2
                    AND x.read_by->1->>'outcome' = 'timeout' AND x.read_by->1->>'innings' = '1',
      format('db/66: after a timeout, %s', row(x.state, jsonb_array_length(x.card), x.read_by)));
    v := r.version;
    SELECT * INTO r FROM scorebook_import_read_start(I, 1, v);
    SELECT * INTO r FROM scorebook_import_read_done(I, NULL, NULL, NULL, NULL, NULL, NULL, 'not_sent');
    x := _import_66(I);
    PERFORM _assert(r.ok AND x.state = 'review' AND jsonb_array_length(x.read_by) = 2,
      format('db/66: a read that sent nothing is recorded as sent (%s)', x.read_by));
    v := r.version;

    -- A read left behind by a crashed API: after five minutes another writer (the owner's key)
    -- may give it up; before, nobody but its presser.
    SELECT * INTO r FROM scorebook_import_read_start(I, 1, v);
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_read_done(I, NULL, NULL, NULL, NULL, NULL, NULL, 'not_sent');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_yours', format('db/66 (yours): the owner gave up a fresh read (%s)', r.reason));
    PERFORM _stale_66(I);
    SELECT * INTO r FROM scorebook_import_read_done(I, NULL, NULL, NULL, NULL, NULL, NULL, 'not_sent');
    PERFORM _assert(r.ok AND (_import_66(I)).state = 'review', format('db/66: the owner could not give up a stale read (%s)', r.reason));
    PERFORM _as(U_SCORER);

    -- (author) the person who pressed Read cannot confirm the card. The owner
    -- (who holds confirm too) reads the scorer's import on the second fixture;
    -- the scorer submits it; the owner is refused, the director of sport is not.
    SELECT * INTO r FROM scorebook_import_open(M2);
    I2 := r.import_id;
    PERFORM scorebook_import_page_add(I2, HIL || '/' || I2 || '/' || gen_random_uuid() || '.jpg', H1, 1000, 1600, 1100, 'image/jpeg');
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_read_start(I2, 0, (SELECT version FROM scorebook_import WHERE id = I2));
    PERFORM _assert(r.ok, format('db/66 (author): the owner could not start a read (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_read_done(I2, CARD, TYPED, '{}', 'anthropic', 'claude-opus-5-5', ARRAY[H1], 'read');
    PERFORM _assert(r.ok, format('db/66 (author): the owner''s read did not land (%s %s)', r.reason, r.detail));
    PERFORM _as(U_SCORER);
    SELECT * INTO r FROM scorebook_import_submit(I2, r.version);
    PERFORM _assert(r.ok, format('db/66 (author): the scorer could not submit the read card (%s %s)', r.reason, r.detail));
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM scorebook_import_commit(I2, '{}', true, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'cannot_confirm_your_own', format('db/66 (author): the person who pressed Read confirmed (%s)', r.reason));
    SELECT * INTO r FROM scorebook_import_return(I2, 'the reader''s card, checked by a second person');
    PERFORM _assert(NOT r.ok AND r.reason = 'cannot_confirm_your_own', format('db/66 (author): the person who pressed Read returned it (%s)', r.reason));
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM scorebook_import_return(I2, 'please check batter four''s balls against page 1');
    PERFORM _assert(r.ok, format('db/66 (author): the director of sport could not return it (%s)', r.reason));

    PERFORM _grant_66(HIL, false);
    PERFORM _as(U_SCORER);
    PERFORM _assert(NOT scorebook_reader_may(I), 'db/66: a revoked grant left the reader on');
  END;

  -- ── 45. The fixture planner, phase 2: inputs, drafts, publishing (SCRBRD-123, db/67) ──
  -- The ground owner's windows and closures are facility.manage at the
  -- ground's school and nobody else's; a pitch lies on a field of its own
  -- school and never on itself; a blackout is the league's, or an entrant
  -- school's for its own side; the inputs and every draft are the league
  -- manager's alone — an entrant school reads nothing of a draft until it
  -- is published; the inputs carry a field's closure with the pitch on it
  -- (the engine closes the pitch: planner.test.mjs C, smoke-planner D); a
  -- published fixture's match is made once, whoever publishes twice; and a
  -- fixture the route refuses leaves no match and no item. The API's half
  -- (the recheck, the route's words) is tools/smoke-planner.mjs.
  --
  -- Each labelled assertion was falsified once — the guard broken in db/67,
  -- the function or policy replaced in the database and this file run — and
  -- went red:
  --   (cycle)   ground_parent_guard() without its walk up the tree
  --   (ends)    ground_ends_named dropped
  --   (window)  ground_window_insert WITH CHECK (true)
  --   (blackout) competition_blackout_add() without the arranger check
  --   (inputs)  planner_inputs() without the manager check
  --   (draft)   fixture_plan_read without the published_at clause
  --   (twice)   fixture_plan_item without its primary key
  --   (half)    fixture_plan_item_record() without the competition check
  --   (frozen)  fixture_plan_recompute() without the draft check
  -- and for making a league (§8a–8c):
  --   (create)  competition_create() without the competition.manage check
  --   (accept)  competition_entrant_acceptor() without "not the manager"
  --   (columns) competition_entrant's UPDATE granted back whole
  --   (entered) match_competition_entered() without the accepted status
  --   (copy)    condition_set_start() without the source's visibility check
  DECLARE
    ids   jsonb := _seed_67();
    C     uuid := (ids->>'comp')::uuid;
    EH    uuid := (ids->>'eh')::uuid;
    EW    uuid := (ids->>'ew')::uuid;
    FIELD uuid := (ids->>'field')::uuid;
    PITCH uuid := (ids->>'pitch')::uuid;
    D     date := sa_today() + 40;
    T0    timestamptz := (sa_today() + 40)::timestamp AT TIME ZONE 'Africa/Johannesburg' + interval '9 hours';
    KEY   text;
    KEY2  text;
    ENTS  jsonb;
    V_PLAN  jsonb;
    v_in  jsonb;
    r     record;
    P     uuid; P2 uuid; P3 uuid;
    M     uuid; M2 uuid;
    n     integer;
    who   uuid;
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    U_WESLG uuid := '88888888-0000-0000-0000-0000000067c0';  -- competitionadmin at Westville (_seed_67)
    NC    uuid; NH1 uuid; NW1 uuid; NW2 uuid;
  BEGIN
    KEY  := 'rr:' || least(EH::text, EW::text) || ':' || greatest(EH::text, EW::text) || ':1';
    KEY2 := 'rr:' || least(EH::text, EW::text) || ':' || greatest(EH::text, EW::text) || ':2';
    ENTS := jsonb_build_array(jsonb_build_object('id', EH, 'schoolId', HIL, 'teamCode', '1XI', 'name', 'Hilton 1st XI'),
                              jsonb_build_object('id', EW, 'schoolId', WES, 'teamCode', '1XI', 'name', 'Westville 1st XI'));
    V_PLAN := jsonb_build_object('format', 'double_round_robin', 'byes', '[]'::jsonb, 'staleLocks', '[]'::jsonb, 'placed', 2, 'unscheduled', 0,
                               'fixtures', jsonb_build_array(jsonb_build_object('id', KEY), jsonb_build_object('id', KEY2)));

    -- (cycle) Hilton puts its pitch on its field; the field on its own pitch,
    -- a ground on itself, and a pitch on another school's ground are refused.
    PERFORM _as(U_SARAH);
    UPDATE ground SET parent_id = FIELD WHERE id = PITCH;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, 'db/67: Hilton could not put its pitch on its field');
    BEGIN
      UPDATE ground SET parent_id = PITCH WHERE id = FIELD;
      PERFORM _assert(false, 'db/67 (cycle): a field was put on its own pitch');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    BEGIN
      UPDATE ground SET parent_id = PITCH WHERE id = PITCH;
      PERFORM _assert(false, 'db/67 (cycle): a pitch was put on itself');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    BEGIN
      UPDATE ground SET parent_id = 'ffffffff-0000-0000-0000-000000000002' WHERE id = PITCH;
      PERFORM _assert(false, 'db/67 (cycle): a pitch was put on Westville''s ground');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    PERFORM _as(U_COACH2);
    UPDATE ground SET parent_id = NULL WHERE id = PITCH;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 0, 'db/67: Hilton''s 2XI coach took a pitch off its field');

    -- (ends) The pitch's two named ends: Hilton names both; one alone is
    -- refused; the 2XI coach and Westville's office name none.
    FOREACH who IN ARRAY ARRAY[U_COACH2, U_WES_ADM] LOOP
      PERFORM _as(who);
      UPDATE ground SET end_a_name = 'Not Theirs End', end_b_name = 'Nor This End' WHERE id = PITCH;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM _assert(n = 0, format('db/67 (ends): %s named Hilton''s ends', who));
    END LOOP;
    PERFORM _as(U_SARAH);
    BEGIN
      UPDATE ground SET end_a_name = 'Pavilion End' WHERE id = PITCH;
      PERFORM _assert(false, 'db/67 (ends): a pitch was given one end');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    UPDATE ground SET end_a_name = 'Pavilion End', end_b_name = 'School End' WHERE id = PITCH;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, 'db/67: Hilton could not name its pitch''s ends');

    -- (window) Hilton offers a window on the pitch and closes the field for
    -- the day; Hilton's 2XI coach, the league and Westville's office can do
    -- neither, nor take Hilton's off. (U_COACH is not used from here: section
    -- 8 revoked his assignments, and a refusal of nobody proves nothing.)
    PERFORM _as(U_SARAH);
    INSERT INTO ground_window (ground_id, starts_at, ends_at, competition_id) VALUES (PITCH, T0, T0 + interval '4 hours', C);
    INSERT INTO ground_closure (ground_id, closed_from, closed_to, reason) VALUES (FIELD, T0 - interval '9 hours', T0 + interval '15 hours', 'verify 067: square reseeded');
    FOREACH who IN ARRAY ARRAY[U_COACH2, U_LEAGUE, U_WES_ADM] LOOP
      PERFORM _as(who);
      BEGIN
        INSERT INTO ground_window (ground_id, starts_at, ends_at) VALUES (PITCH, T0 + interval '1 day', T0 + interval '1 day 4 hours');
        PERFORM _assert(false, format('db/67 (window): %s offered a window on Hilton''s pitch', who));
      EXCEPTION WHEN insufficient_privilege THEN NULL;
      END;
      BEGIN
        INSERT INTO ground_closure (ground_id, closed_from, closed_to, reason) VALUES (PITCH, T0, T0 + interval '1 hour', 'not theirs');
        PERFORM _assert(false, format('db/67 (window): %s closed Hilton''s pitch', who));
      EXCEPTION WHEN insufficient_privilege THEN NULL;
      END;
      DELETE FROM ground_window WHERE ground_id = PITCH;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM _assert(n = 0, format('db/67 (window): %s removed Hilton''s window', who));
      DELETE FROM ground_closure WHERE ground_id = FIELD;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM _assert(n = 0, format('db/67 (window): %s reopened Hilton''s field', who));
    END LOOP;

    -- (blackout) The league's day for everybody; Westville's office, its own
    -- side's exams. Hilton may not black out Westville's side or the league;
    -- Westville's 1XI coach (no fixture.update) not even his own. Hilton's
    -- principal reads the league's day and not Westville's exams; Westville's
    -- 1XI coach reads both (the exams are his side's).
    PERFORM _as(U_LEAGUE);
    SELECT * INTO r FROM competition_blackout_add(C, D - 1, NULL, 'verify 067 league day');
    PERFORM _assert(r.ok, format('db/67: the league could not black out a day (%s)', r.reason));
    PERFORM _as(U_WES_ADM);
    SELECT * INTO r FROM competition_blackout_add(C, D - 2, EW, 'verify 067 exams');
    PERFORM _assert(r.ok, format('db/67: Westville could not black out its own side (%s)', r.reason));
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM competition_blackout_add(C, D - 3, EW, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (blackout): Hilton blacked out Westville''s side (%s)', r.reason));
    SELECT * INTO r FROM competition_blackout_add(C, D - 3, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (blackout): Hilton blacked out the league (%s)', r.reason));
    PERFORM _as(U_WESC);
    SELECT * INTO r FROM competition_blackout_add(C, D - 3, EW, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (blackout): Westville''s 1XI coach blacked out his side (%s)', r.reason));
    PERFORM _assert((SELECT string_agg(coalesce(entrant_id::text, 'all'), ' ' ORDER BY day DESC) FROM competition_blackout WHERE competition_id = C)
                    = 'all ' || EW::text, 'db/67: Westville''s 1XI coach does not read the league''s day and his side''s exams');
    PERFORM _as(U_HEAD_M);
    PERFORM _assert((SELECT string_agg(coalesce(entrant_id::text, 'all'), ' ') FROM competition_blackout WHERE competition_id = C) = 'all',
      format('db/67: Hilton''s principal does not read exactly the league''s day: %s',
             (SELECT string_agg(coalesce(entrant_id::text, 'all') || '@' || day, ' ') FROM competition_blackout WHERE competition_id = C)));
    BEGIN
      INSERT INTO competition_blackout (competition_id, day) VALUES (C, D - 4);
      PERFORM _assert(false, 'db/67: the application wrote a blackout directly');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- (inputs) The league reads the inputs: the window on the pitch, the pitch
    -- on the field, the field's closure — the engine closes the pitch from
    -- exactly this. Nobody else reads them.
    PERFORM _as(U_LEAGUE);
    v_in := planner_inputs(C, D, D);
    PERFORM _assert(jsonb_array_length(v_in->'windows') = 1 AND v_in->'windows'->0->>'groundId' = PITCH::text
                    AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_in->'grounds') g WHERE g->>'id' = PITCH::text AND g->>'parentId' = FIELD::text)
                    AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_in->'grounds') g WHERE g->>'id' = FIELD::text AND jsonb_array_length(g->'closed') = 1),
      format('db/67: the inputs do not carry the pitch, its field and the field''s closure: %s', v_in));
    FOREACH who IN ARRAY ARRAY[U_SARAH, U_HEAD_M, U_COACH2, U_WES_ADM, U_WESC] LOOP
      PERFORM _as(who);
      PERFORM _assert(planner_inputs(C, D, D) IS NULL, format('db/67 (inputs): %s read the planner''s inputs', who));
    END LOOP;

    -- (draft) The league saves a draft with those inputs; the stored inputs
    -- are the ones read. Hilton and Westville — entrant schools — read nothing
    -- of it and can neither save, recompute, publish nor begin an item.
    PERFORM _as(U_LEAGUE);
    SELECT * INTO r FROM fixture_plan_save(C, 'double_round_robin', D, D, '{"durationMinutes": 180}', ENTS, '[]', v_in, V_PLAN, NULL);
    PERFORM _assert(r.ok AND r.version = 1, format('db/67: the league could not save a draft (%s)', r.reason));
    P := r.plan_id;
    PERFORM _assert((SELECT inputs->'grounds' FROM fixture_plan WHERE id = P) = v_in->'grounds', 'db/67: the stored inputs are not the ones read');
    FOREACH who IN ARRAY ARRAY[U_SARAH, U_HEAD_M, U_WES_ADM, U_WESC] LOOP
      PERFORM _as(who);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM fixture_plan WHERE competition_id = C), format('db/67 (draft): %s read a draft', who));
      SELECT * INTO r FROM fixture_plan_save(C, 'round_robin', D, D, '{"durationMinutes": 180}', ENTS, '[]', v_in, V_PLAN, NULL);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67: %s saved a draft', who));
      SELECT * INTO r FROM fixture_plan_recompute(P, '[]', v_in, V_PLAN);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67: %s recomputed a draft', who));
      SELECT * INTO r FROM fixture_plan_publish(P);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67: %s published a draft', who));
      SELECT * INTO r FROM fixture_plan_item_begin(P, KEY);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67: %s began an item', who));
    END LOOP;
    PERFORM _as(U_LEAGUE);
    BEGIN
      UPDATE fixture_plan SET plan = V_PLAN WHERE id = P;
      PERFORM _assert(false, 'db/67: the application wrote a plan directly');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    SELECT * INTO r FROM fixture_plan_item_begin(P, KEY);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_published', format('db/67: an item was begun on a draft (%s)', r.reason));

    -- Published: the entrant school reads it now.
    SELECT * INTO r FROM fixture_plan_publish(P);
    PERFORM _assert(r.ok AND r.first, format('db/67: the league could not publish (%s)', r.reason));
    FOREACH who IN ARRAY ARRAY[U_WESC, U_HEAD_M] LOOP
      PERFORM _as(who);
      PERFORM _assert(EXISTS (SELECT 1 FROM fixture_plan WHERE id = P AND state = 'published'),
        format('db/67: %s, at an entrant school, cannot read the published plan', who));
    END LOOP;

    -- (twice) The match made once: the item begun, the match inserted as the
    -- fixture route inserts it (as the league, under match_insert), the item
    -- recorded; begun again, it names that match; a second item for the
    -- fixture is refused, and its match goes with the transaction.
    PERFORM _as(U_LEAGUE);
    SELECT * INTO r FROM fixture_plan_item_begin(P, KEY);
    PERFORM _assert(r.ok AND r.match_id IS NULL, format('db/67: the first begin found a match (%s %s)', r.reason, r.match_id));
    INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, ground_id, starts_at, sport, format, overs, status, competition_id)
    VALUES (HIL, '1XI', WES, '1XI', 'pending', PITCH, T0 + interval '30 minutes', 'cricket', 'T20', 20, 'scheduled', C) RETURNING id INTO M;
    SELECT * INTO r FROM fixture_plan_item_record(P, KEY, M);
    PERFORM _assert(r.ok, format('db/67: the item was not recorded (%s)', r.reason));
    SELECT * INTO r FROM fixture_plan_item_begin(P, KEY);
    PERFORM _assert(r.ok AND r.match_id = M, format('db/67 (twice): begun again, the item does not name its match (%s)', r.match_id));
    BEGIN
      INSERT INTO match (school_id, team_code, away_school_id, away_team_code, opponent, ground_id, starts_at, sport, format, overs, status, competition_id)
      VALUES (HIL, '1XI', WES, '1XI', 'pending', PITCH, T0 + interval '30 minutes', 'cricket', 'T20', 20, 'scheduled', C) RETURNING id INTO M2;
      SELECT * INTO r FROM fixture_plan_item_record(P, KEY, M2);
      PERFORM _assert(false, 'db/67 (twice): a second item was recorded for one fixture');
    EXCEPTION WHEN unique_violation THEN NULL;
    END;
    PERFORM _assert(_made_67(C) = '1/1', format('db/67 (twice): publishing twice made %s (matches/items)', _made_67(C)));

    -- (half) A fixture the route refuses — a side that has not entered — leaves
    -- no match; and a match outside the competition is not recorded as the
    -- fixture's (the API then rolls its match back with it).
    BEGIN
      INSERT INTO match (school_id, team_code, opponent, ground_id, starts_at, sport, format, overs, status, competition_id)
      VALUES (HIL, '2XI', 'Verify 067 refused', PITCH, T0 + interval '1 day', 'cricket', 'T20', 20, 'scheduled', C);
      PERFORM _assert(false, 'db/67: a side that had not entered was given a fixture in the league');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    PERFORM _assert(NOT _any_match_67('Verify 067 refused'), 'db/67: a refused fixture left a match');
    BEGIN
      INSERT INTO match (school_id, team_code, opponent, ground_id, starts_at, sport, format, overs, status)
      VALUES (HIL, '1XI', 'Verify 067 friendly', PITCH, T0 + interval '2 days', 'cricket', 'T20', 20, 'scheduled') RETURNING id INTO M2;
      SELECT * INTO r FROM fixture_plan_item_record(P, KEY2, M2);
      PERFORM _assert(NOT r.ok AND r.reason = 'match_not_in_competition',
        format('db/67 (half): a friendly was recorded as the league''s fixture (%s)', r.reason));
      RAISE EXCEPTION USING ERRCODE = 'ZZ067', MESSAGE = 'db/67: the API rolls the fixture back';
    EXCEPTION WHEN sqlstate 'ZZ067' THEN NULL;
    END;
    PERFORM _assert(_made_67(C) = '1/1' AND NOT _any_match_67('Verify 067 friendly'),
      format('db/67 (half): a refused fixture left %s (matches/items)', _made_67(C)));

    -- (frozen) A published plan is not recomputed; a later version published
    -- supersedes it, and it is then not published again. A draft saved after
    -- that stays the league's.
    SELECT * INTO r FROM fixture_plan_recompute(P, '[]', v_in, V_PLAN);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_a_draft', format('db/67 (frozen): a published plan was recomputed (%s)', r.reason));
    SELECT * INTO r FROM fixture_plan_save(C, 'double_round_robin', D, D, '{"durationMinutes": 180}', ENTS, '[]', v_in, V_PLAN, P);
    P2 := r.plan_id;
    SELECT * INTO r FROM fixture_plan_publish(P2);
    PERFORM _assert(r.ok AND r.first, format('db/67: version 2 was not published (%s)', r.reason));
    SELECT * INTO r FROM fixture_plan_publish(P);
    PERFORM _assert(NOT r.ok AND r.reason = 'superseded', format('db/67: a superseded plan was published (%s)', r.reason));
    SELECT * INTO r FROM fixture_plan_publish(P2);
    PERFORM _assert(r.ok AND NOT r.first, format('db/67: publishing version 2 again was not a retry (%s)', r.reason));
    PERFORM _assert((SELECT string_agg(state, ',' ORDER BY version) FROM fixture_plan WHERE competition_id = C) = 'superseded,published',
      'db/67: version 1 was not superseded by version 2');
    SELECT * INTO r FROM fixture_plan_save(C, 'round_robin', D, D, '{"durationMinutes": 180}', ENTS, '[]', v_in, V_PLAN, NULL);
    P3 := r.plan_id;
    PERFORM _as(U_SARAH);
    PERFORM _assert((SELECT count(*) FROM fixture_plan WHERE competition_id = C) = 2 AND NOT EXISTS (SELECT 1 FROM fixture_plan WHERE id = P3),
      'db/67: Hilton reads other than the two published versions');
    PERFORM _assert((SELECT count(*) FROM fixture_plan_item WHERE competition_id = C) = 1, 'db/67: Hilton does not read the published plan''s item');

    -- ── Making a league (db/67 §8a–8c) ──
    -- (create) competition.manage at the organiser, and nobody else: Hilton's
    -- director of sport creates none; Westville's competition administrator
    -- creates Westville's and not Hilton's or a league with no organiser —
    -- and manages what he created, with no new role.
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM competition_create(NULL, 'Verify 067 Sarah League', 'league', 'T20', NULL, NULL, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (create): Hilton''s director of sport created a league (%s)', r.reason));
    SELECT * INTO r FROM competition_create(HIL, 'Verify 067 Sarah League', 'league', 'T20', NULL, NULL, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (create): Hilton''s director of sport created Hilton''s league (%s)', r.reason));
    PERFORM _as(U_WESLG);
    SELECT * INTO r FROM competition_create(HIL, 'Verify 067 Hilton League', 'league', 'T20', NULL, NULL, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (create): Westville''s administrator created Hilton''s league (%s)', r.reason));
    SELECT * INTO r FROM competition_create(NULL, 'Verify 067 Open League', 'league', 'T20', NULL, NULL, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (create): Westville''s administrator created a league with no organiser (%s)', r.reason));
    SELECT * INTO r FROM competition_create(WES, 'Verify 067 Westville League', 'league', 'T20', '1XI', 'boys', 'school', NULL);
    PERFORM _assert(r.ok, format('db/67: Westville''s administrator could not create Westville''s league (%s)', r.reason));
    NC := r.competition_id;
    PERFORM _assert(competition_conditions_manager(NC), 'db/67: the creator does not manage what he created');
    SELECT * INTO r FROM competition_create(WES, 'Verify 067 Westville League', 'league', 'T20', NULL, NULL, NULL, '1999');
    PERFORM _assert(NOT r.ok AND r.reason = 'season_unknown', format('db/67: an unknown season was taken (%s)', r.reason));

    -- (accept) Invited by the league; answered by each school for its own
    -- side, never by the league's managers (the Westville administrator holds
    -- fixture.update at Westville; the platform-wide one everywhere).
    SELECT * INTO r FROM competition_entrant_invite(NC, HIL, '1XI', NULL);
    NH1 := r.entrant_id;
    SELECT * INTO r FROM competition_entrant_invite(NC, WES, '1XI', NULL);
    NW1 := r.entrant_id;
    SELECT * INTO r FROM competition_entrant_invite(NC, WES, '2XI', NULL);
    NW2 := r.entrant_id;
    PERFORM _assert(r.ok AND r.status = 'invited' AND _status_67(NH1) = 'invited', format('db/67: the invitations were not made (%s)', r.reason));
    FOREACH who IN ARRAY ARRAY[U_WESLG, U_LEAGUE] LOOP
      PERFORM _as(who);
      SELECT * INTO r FROM competition_entrant_respond(NW1, true);
      PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (accept): the league''s manager %s accepted for Westville (%s)', who, r.reason));
    END LOOP;
    PERFORM _as(U_SARAH);
    SELECT * INTO r FROM competition_entrant_respond(NW1, true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67 (accept): Hilton accepted for Westville (%s)', r.reason));
    SELECT * INTO r FROM competition_entrant_invite(NC, HIL, '2XI', NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/67: Hilton invited itself (%s)', r.reason));
    SELECT * INTO r FROM competition_entrant_respond(NH1, true);
    PERFORM _assert(r.ok AND r.status = 'accepted', format('db/67: Hilton could not accept for its own side (%s)', r.reason));
    PERFORM _as(U_WES_ADM);
    SELECT * INTO r FROM competition_entrant_respond(NW1, true);
    PERFORM _assert(r.ok, format('db/67: Westville could not accept (%s)', r.reason));
    SELECT * INTO r FROM competition_entrant_respond(NW2, false);
    PERFORM _assert(r.ok AND _status_67(NW2) = 'declined', format('db/67: Westville could not decline (%s)', r.reason));
    SELECT * INTO r FROM competition_entrant_respond(NW2, true);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_invited', format('db/67: a declined side was accepted after (%s)', r.reason));

    -- (columns) Nobody writes an entrant's status, or enters a side, but
    -- through those functions: not the league's manager, not the school.
    FOREACH who IN ARRAY ARRAY[U_WESLG, U_WES_ADM] LOOP
      PERFORM _as(who);
      BEGIN
        UPDATE competition_entrant SET status = 'accepted' WHERE id = NW2;
        PERFORM _assert(false, format('db/67 (columns): %s wrote an entrant''s status', who));
      EXCEPTION WHEN insufficient_privilege THEN NULL;
      END;
      BEGIN
        INSERT INTO competition_entrant (competition_id, school_id, team_code, display_name, status) VALUES (NC, WES, '3XI', 'Westville 3rd XI', 'accepted');
        PERFORM _assert(false, format('db/67 (columns): %s entered a side directly', who));
      EXCEPTION WHEN insufficient_privilege THEN NULL;
      END;
    END LOOP;
    PERFORM _assert(_status_67(NW2) = 'declined', 'db/67 (columns): the declined side is no longer declined');

    -- (entered) A side that declined has no fixture in the competition; the
    -- planner draws the two that accepted.
    PERFORM _as(U_WESLG);
    BEGIN
      INSERT INTO match (school_id, team_code, opponent, starts_at, sport, format, overs, status, competition_id)
      VALUES (WES, '2XI', 'Verify 067 declined', T0 + interval '3 days', 'cricket', 'T20', 20, 'scheduled', NC);
      PERFORM _assert(false, 'db/67 (entered): the side that declined was given a fixture in the league');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    PERFORM _assert(NOT _any_match_67('Verify 067 declined'), 'db/67 (entered): a refused fixture left a match');
    v_in := planner_inputs(NC, D, D);
    PERFORM _assert((SELECT string_agg(e->>'id', ',' ORDER BY e->>'id') FROM jsonb_array_elements(v_in->'entrants') e)
                    = (SELECT string_agg(x::text, ',' ORDER BY x::text) FROM unnest(ARRAY[NH1, NW1]) x),
      format('db/67 (entered): the planner draws %s', v_in->'entrants'));

    -- (copy) Conditions from a competition the caller cannot read are refused
    -- in the same words as none at all; from the platform's defaults they
    -- are unconfirmed, each saying where from. The platform-wide league
    -- administrator, who may read the Hilton cup, copies its cited figure.
    SELECT * INTO r FROM condition_set_start(NC, 'competition', (ids->>'hcup')::uuid, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'source_invalid', format('db/67 (copy): Westville copied a competition it cannot read (%s)', r.reason));
    SELECT * INTO r FROM condition_set_start(NC, 'competition', gen_random_uuid(), NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'source_invalid', format('db/67: a competition that is not there was answered otherwise (%s)', r.reason));
    SELECT * INTO r FROM condition_set_start(NC, 'defaults', NULL, NULL, NULL);
    PERFORM _assert(r.ok AND r.version = 1 AND r.entered > 5, format('db/67: the defaults were not entered (%s)', r.reason));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM condition_value v WHERE v.set_id = r.set_id AND (v.status <> 'unconfirmed' OR v.source_note IS NULL))
                    AND (SELECT v.value FROM condition_value v WHERE v.set_id = r.set_id AND v.key = 'bowling.limit' AND v.age_band = 'U13') = '{"day": 10, "spell": 5}',
      'db/67: the defaults are not unconfirmed with their source, or the U13 limit is not the directive''s');
    SELECT * INTO r FROM condition_set_start(NC, 'defaults', NULL, NULL, NULL);
    PERFORM _assert(NOT r.ok AND r.reason = 'already_started', format('db/67: conditions were started twice (%s)', r.reason));
    PERFORM _as(U_LEAGUE);
    SELECT * INTO r FROM competition_create(NULL, 'Verify 067 Copy League', 'league', 'T20', NULL, NULL, NULL, NULL);
    SELECT * INTO r FROM condition_set_start(r.competition_id, 'competition', (ids->>'hcup')::uuid, NULL, NULL);
    PERFORM _assert(r.ok AND r.entered = 1, format('db/67: the league could not copy the Hilton cup (%s)', r.reason));
    PERFORM _assert((SELECT v.status || '|' || v.source_document || '|' || v.source_clause FROM condition_value v WHERE v.set_id = r.set_id)
                    = 'confirmed|Verify 067 Cup Rules|4.2', 'db/67 (copy): the cited figure was not copied with its citation');
  END;

  -- ── 46. The wicket-keeper: his dismissals, and a stumping only his (SCRBRD-126, db/68) ──
  -- A keeper named, and changed mid-over, in a Hilton fixture (_seed_68());
  -- its twin has the same deliveries and no keeper row. The keeper's catches
  -- and stumpings are the fold's for that log (keeper.test.mjs, group E,
  -- folds the same events: …02 one catch; …01 one catch, two stumpings — a
  -- stumping a free hit saved is nobody's, a catch by …02 after he gave the
  -- gloves up is not as keeper, an undone keeper row never kept); every
  -- other figure of the log is its twin's; the door refuses a stumping
  -- credited to a fielder who was not keeping, while one is recorded, and
  -- takes it in the twin, which records none; and the two new views are
  -- read as their reader — Westville's coach sees nothing of Hilton's
  -- keeping. tools/smoke-fold-figures.mjs holds the same views to the fold
  -- over generated logs.
  --
  -- Each labelled assertion was falsified once — the function, view or
  -- trigger replaced in the database and this file run — and went red:
  --   (stands)  keeper_dismissal without ball_wicket_stands()
  --   (name)    keeper_is_fielder() without the name: by reference only (the
  --             door, which asks it, refused _seed_68()'s stumping by name first)
  --   (void)    keeper_at() over ball_event rather than ball_event_live (the
  --             door first: the undone keeper row was keeping at seq 13)
  --   (door)    the trigger ball_event_stumped_by_keeper dropped
  --   (scope)   keeper_dismissal and player_keeping_career as their owner
  --             (section 9 first: no view in public may run as its owner)
  DECLARE
    ids    jsonb := _seed_68();
    M      uuid;
    MP     uuid;
    K1     uuid := 'aaaaaaaa-0000-0000-0000-000000000002';
    K2     uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
    F1     uuid := 'aaaaaaaa-0000-0000-0000-000000000005';
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    got    text;
  BEGIN
    M := (ids->>'m')::uuid;
    MP := (ids->>'plain')::uuid;
    PERFORM _as(U_SARAH);
    -- (stands) (name) (void) the keeper's dismissals, ball by ball
    SELECT string_agg(d.seq || ':' || CASE d.player_id WHEN K1 THEN 'k1' WHEN K2 THEN 'k2' WHEN F1 THEN 'f1' ELSE '?' END
                      || ':' || d.dismissal, ' ' ORDER BY d.seq)
      INTO got FROM keeper_dismissal d WHERE d.match_id = M;
    PERFORM _assert(got = '3:k1:caught 7:k2:stumped 8:k2:caught 13:k2:stumped',
      format('db/68 (stands/name/void): the keeper''s dismissals read %s, where the fold says 3:k1:caught 7:k2:stumped 8:k2:caught 13:k2:stumped', got));
    -- the careers: this fixture's keeping, for each of the three
    SELECT string_agg(CASE c.player_id WHEN K1 THEN 'k1' WHEN K2 THEN 'k2' ELSE 'f1' END || '='
                      || row(c.matches, c.innings_kept, c.catches, c.stumpings)::text, ' ' ORDER BY c.player_id = K2, c.player_id = F1)
      INTO got FROM player_keeping_career c WHERE c.player_id IN (K1, K2, F1);
    PERFORM _assert(got = 'k1=(1,1,1,0) k2=(1,1,1,2)',
      format('db/68: player_keeping_career reads %s, where the fold says k1=(1,1,1,0) k2=(1,1,1,2)', got));
    -- old logs: the twin has no keeper's dismissal, and every figure the
    -- live score, the handover's count and the bowler's innings keep is the same
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM keeper_dismissal WHERE match_id = MP), 'db/68: a log with no keeper row has keeper dismissals');
    SELECT concat_ws(' | ',
      (SELECT row(l.runs, l.wickets, l.legal_balls)::text FROM match_live_score l WHERE l.match_id = M),
      (SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded(M, 0::smallint) f),
      (SELECT row(b.wickets, b.runs_conceded)::text FROM bowler_innings_figures b WHERE b.match_id = M AND b.player_id = 'aaaaaaaa-0000-0000-0000-000000000003'),
      (SELECT string_agg(o.over_no || '/' || o.legal_balls || '/' || o.deliveries, ',' ORDER BY o.over_no) FROM bowler_over o WHERE o.match_id = M))
      INTO got;
    PERFORM _assert(got = concat_ws(' | ',
      (SELECT row(l.runs, l.wickets, l.legal_balls)::text FROM match_live_score l WHERE l.match_id = MP),
      (SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded(MP, 0::smallint) f),
      (SELECT row(b.wickets, b.runs_conceded)::text FROM bowler_innings_figures b WHERE b.match_id = MP AND b.player_id = 'aaaaaaaa-0000-0000-0000-000000000003'),
      (SELECT string_agg(o.over_no || '/' || o.legal_balls || '/' || o.deliveries, ',' ORDER BY o.over_no) FROM bowler_over o WHERE o.match_id = MP))
      AND got = '(3,6,7) | (3,6,7) | (4,3) | 0/6/7,1/1/1',
      format('db/68: the log with keeper rows reads %s; its twin without them is the same, and the fold says (3,6,7) | (3,6,7) | (4,3) | 0/6/7,1/1/1', got));

    -- (door) a stumping credited to a fielder not keeping is refused while
    -- one is recorded (Law 39); the same row in the twin, which records
    -- none, is taken as it always was
    PERFORM _assert(_owner_61(format($q$INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
        idempotency_key, client_seq, client_ts, kind, ball_type, value, dismissal, payload)
        VALUES (%L, '11111111-1111-1111-1111-111111111111', 30, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-068',
                'v68:door', 30, now(), 'ball', 'W', 0, 'stumped', '{"fielder":"V68 Five"}')$q$, M)) = '23514'
                    AND _owner_61(format($q$INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
        idempotency_key, client_seq, client_ts, kind, ball_type, value, dismissal, payload)
        VALUES (%L, '11111111-1111-1111-1111-111111111111', 30, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-068',
                'v68:door:plain', 30, now(), 'ball', 'W', 0, 'stumped', '{"fielder":"V68 Five"}')$q$, MP)) = 'ok',
      'db/68 (door): a stumping by a fielder who was not keeping was taken while a keeper was recorded, or refused in a log with none');

    -- (scope) Westville's coach reads nothing of Hilton's keeping
    PERFORM _as(U_WESC);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM keeper_dismissal WHERE match_id IN (M, MP))
                    AND NOT EXISTS (SELECT 1 FROM player_keeping_career WHERE player_id IN (K1, K2)),
      'db/68 (scope): Westville''s coach reads Hilton''s keeping');
    -- the new objects: views as their reader, the application role's to
    -- read, functions as their caller
    PERFORM _assert((SELECT bool_and(coalesce('security_invoker=true' = ANY (c.reloptions), false)
                                     AND has_table_privilege('scrbrd_app', c.oid, 'SELECT'))
                       FROM pg_class c WHERE c.oid IN ('keeper_dismissal'::regclass, 'player_keeping_career'::regclass))
                    AND NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname IN ('keeper_at', 'keeper_is_fielder', 'ball_event_stumped_by_keeper')
                                       AND p.prosecdef),
      'db/68 (scope): a new view runs as its owner or is not the application role''s to read, or a new function runs as its owner');
  END;

  -- ── 47. Match results and the table (SCRBRD-114 phase 3a, db/69) ──
  -- _seed_69(): a Hilton league of four sides, seven matches under the
  -- documents their first events fix (version 1, win 4 / tie 2 / no result
  -- 2 / loss 0, confirmed; version 2 from 8 October, win 5), a friendly, a
  -- typed ladder, and an amendment waiting. Every figure below was worked by
  -- hand from the log, ball by ball; tools/smoke-fold-figures.mjs holds
  -- match_result() to the fold over result-logs.mjs, so the rule and the
  -- fold cannot part.
  --
  -- Each labelled assertion was falsified once — the function, trigger,
  -- index or view replaced in the database and this file run — and went red:
  --   (abandoned)   match_result() reading a chase sealed abandoned as any other
  --   (rates)       an all-out innings charged its balls, not its allotted overs
  --   (fallback)    an abandoned match taking points.abandoned with no fallback
  --   (precedence)  a concession applied over play's winner
  --   (needs-play)  the decision trigger's no-ball check removed
  --   (one)         the one-standing index dropped (and the function's own check)
  --   (decider)     match_result_decider() asking fixture.update for a league match
  --   (support)     match_result_decide() and the re-fix without the support check
  --   (audit)       scoring_amendment_decide() without its audit line
  --   (refix)       match_conditions_refix_table() not keeping the part it replaced
  --   (scope)       competition_standing as its owner; competition_standing_rows()
  --                 not asking whether its reader may see the competition
  --   (away)        match_result() run as its caller (the visitors' coach reads
  --                 no innings of the home school's log: no result)
  --   (public)      public_competition_standing() and the rows beneath it not
  --                 asking for a publication (two layers: either alone holds)
  DECLARE
    ids    jsonb := _seed_69();
    C      uuid;  C2 uuid;  V1 uuid;  V2 uuid;
    EA     uuid;  ED uuid;
    M1 uuid; M2 uuid; M3 uuid; M5 uuid; M6 uuid; F uuid;
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    T0     text;  -- the table as first read
    got    text;
    h1     text;  h2 text;
    v_id   uuid;  v_id2 uuid;
    r      record;
    j      jsonb;
  BEGIN
    C := (ids->>'c')::uuid; C2 := (ids->>'c2')::uuid; V1 := (ids->>'v1')::uuid; V2 := (ids->>'v2')::uuid;
    EA := (ids->>'a')::uuid; ED := (ids->>'d')::uuid;
    M1 := (ids->>'m1')::uuid; M2 := (ids->>'m2')::uuid; M3 := (ids->>'m3')::uuid;
    M5 := (ids->>'m5')::uuid; M6 := (ids->>'m6')::uuid; F := (ids->>'f')::uuid;

    -- §results. Each match's result, as its league reads it (abandoned): M5's
    -- chase sealed abandoned is no result, not a win by the 31 runs it was
    -- short; M4, the visitors batting first, a tie; M6 abandoned before a ball.
    PERFORM _as(U_LEAGUE);
    SELECT string_agg(x.label || '=' || concat_ws(',', r2.outcome, coalesce(r2.margin_kind, '-'), coalesce(r2.margin::text, '-'),
                      coalesce(r2.decided_by, '-'), coalesce(r2.winner_side, '-')), ' ' ORDER BY x.label) INTO got
      FROM competition_results(C) r2
      JOIN (VALUES ('m1', (ids->>'m1')::uuid), ('m2', (ids->>'m2')::uuid), ('m3', (ids->>'m3')::uuid), ('m4', (ids->>'m4')::uuid),
                   ('m5', (ids->>'m5')::uuid), ('m6', (ids->>'m6')::uuid), ('m7', (ids->>'m7')::uuid)) AS x(label, m) ON x.m = r2.match_id;
    PERFORM _assert(got = 'm1=away_win,wickets,10,play,away m2=home_win,runs,50,play,home m3=away_win,wickets,10,play,away '
                       || 'm4=tie,-,-,play,- m5=no_result,-,-,-,- m6=abandoned,-,-,-,- m7=home_win,runs,30,play,home',
      format('db/69 (abandoned): the league''s results read %s', got));
    PERFORM _as(U_SARAH);
    SELECT concat_ws(',', r2.outcome, r2.margin_kind, r2.margin, r2.decided_by, r2.winner_side, r2.winner_school_id = HIL)
      INTO got FROM match_result(F) r2;
    PERFORM _assert(got = 'home_win,runs,6,play,home,t', format('db/69: the friendly reads %s', got));

    -- §table. Computed (every counted match's figures confirmed), points from
    -- each match's own document — M7, played after version 2 took effect,
    -- gives D 5 for its win where M3, the week before, gave 4 — and M6,
    -- abandoned, 2 each from points.no_result, the set stating no
    -- points.abandoned (fallback). Read by Westville's coach, a participant.
    PERFORM _as(U_WESC);
    T0 := _table_69(C, ids);
    PERFORM _assert(T0 = 'A=4,0,3,0,1,2,4 B=3,1,0,1,1,8,3 C=3,1,0,1,1,8,2 D=4,2,1,0,1,11,1',
      format('db/69 (fallback): the table reads %s', T0));
    -- (away) the visitors' coach reads the result of the match his side
    -- played, whoever's log it is; and, a participant, every result in it
    SELECT string_agg(concat_ws(',', r2.outcome, r2.margin_kind, r2.margin), ' ' ORDER BY x.n) INTO got
      FROM (VALUES (1, M1), (2, M2)) AS x(n, m), LATERAL match_result(x.m) r2;
    PERFORM _assert(got = 'away_win,wickets,10 home_win,runs,50',
      format('db/69 (away): Westville''s coach reads %s for M1 and M2', got));
    SELECT string_agg(concat_ws('/', s.runs_for, s.balls_for, s.runs_against, s.balls_against), ' ' ORDER BY s.display_name),
           bool_and(s.basis = 'computed'), count(*)
      INTO got, v_ok, n FROM competition_standing s WHERE s.competition_id = C;
    -- (rates) §6.4 to the ball: B's chase in 14.3 overs is charged 87; C all
    -- out in 17 overs of 20 is charged 120; A all out in 8 of a match revised
    -- to 12 is charged 72; D's two wides are two runs and no balls; M5 (no
    -- result) and M6 (abandoned) add nothing.
    PERFORM _assert(got = '106/312/138/245 160/240/110/240 121/207/120/240 127/278/146/312' AND v_ok AND n = 4,
      format('db/69 (rates): the run figures read %s (computed: %s, rows: %s)', got, v_ok, n));
    PERFORM _assert((SELECT s.nrr FROM competition_standing s WHERE s.competition_id = C AND s.display_name = 'Verify 069 Westville 1st XI')
                    = 121::numeric * 6 / 207 - 120::numeric * 6 / 240
                    AND (SELECT s.nrr FROM competition_standing s WHERE s.competition_id = C AND s.display_name = 'Verify 069 Hilton 2nd XI') = 1.25,
      'db/69 (rates): net run rate is not runs × 6 ÷ balls, for less against');
    -- the typed ladder: no confirmed points, the schools' own figures; two
    -- sides level on every key share a rank
    SELECT string_agg(s.display_name || '=' || s.basis || ',' || s.points || ',' || s.rank, ' ' ORDER BY s.display_name) INTO got
      FROM competition_standing s WHERE s.competition_id = C2;
    PERFORM _assert(got = 'Verify 069 Typed One=entered,4,1 Verify 069 Typed Three=entered,0,3 Verify 069 Typed Two=entered,4,1',
      format('db/69: the typed ladder reads %s', got));
    -- (scope) a reader who holds no competition.read reads none of it
    PERFORM _as(U_SCOUT);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM competition_standing s WHERE s.competition_id IN (C, C2))
                    -- the rows function is the application's to call: it asks
                    -- for the competition itself, not only through the view
                    AND NOT EXISTS (SELECT 1 FROM competition_standing_rows(C))
                    AND NOT EXISTS (SELECT 1 FROM competition_standing_rows(C2))
                    AND NOT EXISTS (SELECT 1 FROM competition_results(C))
                    AND NOT EXISTS (SELECT 1 FROM competition_points_adjustment a WHERE a.competition_id = C),
      'db/69 (scope): a reader with no competition.read reads the league''s table or results');

    -- §adjustments: entered by the league, never by a school; withdrawn with
    -- a note, the table restored; an over-rate penalty in points only where
    -- the competition's over_rate.kind says points.
    PERFORM _as(U_SARAH);
    SELECT a.reason INTO got FROM competition_points_adjust(C, ED, NULL, 'conduct', -2, 'umpires'' report: dissent at the toss') a;
    PERFORM _assert(got = 'not_permitted', format('db/69: a school adjusted the league''s table (%s)', got));
    PERFORM _as(U_LEAGUE);
    PERFORM _assert((SELECT a.reason FROM competition_points_adjust(C, ED, NULL, 'conduct', -2, 'short') a) = 'reason_required',
      'db/69: an adjustment was entered with no reason');
    SELECT a.ok, a.adjustment_id INTO v_ok, v_id FROM competition_points_adjust(C, ED, M3, 'conduct', -2, 'umpires'' report: conduct at M3') a;
    PERFORM _assert(v_ok AND _table_69(C, ids) LIKE '%D=4,2,1,0,1,9.0,1',
      format('db/69: the adjustment did not land: %s', _table_69(C, ids)));
    SELECT a.ok, a.adjustment_id INTO v_ok, v_id2 FROM competition_points_adjust(C, EA, M1, 'over_rate', -1, 'over rate: two overs short at M1') a;
    PERFORM _assert(v_ok, 'db/69: an over-rate penalty in points was refused where the league counts them in points');
    PERFORM _assert((SELECT a.reason FROM competition_points_adjust(C2, (SELECT e.id FROM competition_entrant e WHERE e.competition_id = C2 LIMIT 1),
                                                                    NULL, 'over_rate', -1, 'over rate: one over short') a) = 'over_rate_not_points',
      'db/69: an over-rate penalty was taken by a league that has none');
    -- (each write its own statement: a STABLE read sees its statement's snapshot)
    PERFORM _assert((SELECT w.reason FROM competition_points_adjustment_withdraw(v_id, 'short') w) = 'note_required',
      'db/69: an adjustment was withdrawn with no note');
    PERFORM _assert((SELECT w.ok FROM competition_points_adjustment_withdraw(v_id, 'entered against the wrong side') w),
      'db/69: the conduct adjustment could not be withdrawn');
    PERFORM _assert((SELECT w.ok FROM competition_points_adjustment_withdraw(v_id2, 'the umpires withdrew the report') w),
      'db/69: the over-rate adjustment could not be withdrawn');
    PERFORM _assert(_table_69(C, ids) = T0, format('db/69: withdrawing the adjustments did not restore the table: %s', _table_69(C, ids)));
    PERFORM _assert((SELECT count(*) FROM competition_points_adjustment a WHERE a.competition_id = C) = 2,
      'db/69: a withdrawn adjustment was deleted');
    BEGIN
      DELETE FROM competition_points_adjustment WHERE id = v_id;
      PERFORM _assert(false, 'db/69: the league deleted an adjustment');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- §decisions (D8): a league match's under competition.manage at the
    -- organiser (decider) — not the home school's director of sport —
    -- a friendly's under the home school's fixture.update.
    PERFORM _as(U_SARAH);
    PERFORM _assert((SELECT d.reason FROM match_result_decide(M5, 'conceded', 'away', 'Westville could not field eleven') d) = 'not_permitted',
      'db/69 (decider): a school decided a league match''s result');
    PERFORM _as(U_LEAGUE);
    -- (needs-play) no ball bowled: a walkover or a concession, never an award
    PERFORM _assert((SELECT d.reason FROM match_result_decide(M6, 'awarded', 'home', 'the higher placed side goes through') d) = 'needs_play',
      'db/69 (needs-play): an award was made on a match with no ball bowled');
    PERFORM _assert((SELECT d.reason FROM match_result_decide(M2, 'conceded', 'home', 'Hilton conceded the match', true) d) = 'override_not_award'
                    AND (SELECT d.reason FROM match_result_decide(M2, 'forfeit', 'home', 'Hilton conceded the match') d) = 'kind_invalid'
                    AND (SELECT d.reason FROM match_result_decide(M2, 'conceded', 'both', 'Hilton conceded the match') d) = 'side_invalid'
                    AND (SELECT d.reason FROM match_result_decide(M2, 'conceded', 'home', 'short') d) = 'reason_required',
      'db/69: a malformed decision was not refused by name');
    SELECT d.ok, d.decision_id INTO v_ok, v_id FROM match_result_decide(M6, 'walkover', 'home', 'Westville did not arrive at the ground') d;
    PERFORM _assert(v_ok AND _table_69(C, ids) = 'A=4,1,3,0,0,4,4 B=3,1,1,1,0,6,3 C=3,1,0,1,1,8,2 D=4,2,1,0,1,11,1',
      format('db/69: a walkover is not a win and a loss in the table: %s', _table_69(C, ids)));
    -- (one) a second standing decision is refused
    PERFORM _assert((SELECT d.reason FROM match_result_decide(M6, 'conceded', 'away', 'Westville conceded by letter') d) = 'already_decided',
      'db/69 (one): a second standing decision was taken');
    PERFORM _assert((SELECT w.reason FROM match_result_decision_withdraw(v_id, 'short') w) = 'note_required',
      'db/69: a decision was withdrawn with no note');
    PERFORM _assert((SELECT w.ok FROM match_result_decision_withdraw(v_id, 'Westville were on the field; the walkover was wrong') w),
      'db/69: the walkover could not be withdrawn');
    PERFORM _assert(_table_69(C, ids) = T0, format('db/69: withdrawing the walkover did not restore play''s answer: %s', _table_69(C, ids)));
    -- (precedence) play < decision < an award overriding play. A concession
    -- on a match play decided changes nothing — the result, its hash, the
    -- table; an award overriding play makes D the winner of M2.
    SELECT r2.result_hash INTO h1 FROM match_result(M2) r2;
    SELECT d.decision_id INTO v_id FROM match_result_decide(M2, 'conceded', 'home', 'entered against the wrong fixture') d;
    SELECT r2.result_hash, r2.outcome || ',' || r2.decided_by || ',' || r2.decision_applied INTO h2, got FROM match_result(M2) r2;
    PERFORM _assert(h2 = h1 AND got = 'home_win,play,false' AND _table_69(C, ids) = T0,
      format('db/69 (precedence): a concession moved a result play had decided: %s', got));
    PERFORM match_result_decision_withdraw(v_id, 'entered against the wrong fixture');
    SELECT d.decision_id INTO v_id FROM match_result_decide(M2, 'awarded', 'away', 'protest upheld: an unregistered player', true) d;
    SELECT r2.result_hash, concat_ws(',', r2.outcome, r2.margin_kind, r2.decided_by, r2.play_outcome) INTO h2, got FROM match_result(M2) r2;
    PERFORM _assert(h2 <> h1 AND got = 'away_win,awarded,decision,home_win'
                    AND _table_69(C, ids) = 'A=4,0,3,0,1,2,4 B=3,1,0,1,1,8,2 C=3,0,1,1,1,4,3 D=4,3,0,0,1,15,1',
      format('db/69 (precedence): the award reads %s and the table %s', got, _table_69(C, ids)));
    -- the decision is read by a participant, as its result is
    PERFORM _as(U_WESC);
    PERFORM _assert((SELECT count(*) FROM match_result_decision x WHERE x.match_id = M2) = 2,
      'db/69: a participant cannot read the league''s decisions');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM match_result_decision x WHERE x.match_id = M2),
      'db/69 (scope): nobody signed in reads a decision');
    PERFORM _as(U_LEAGUE);
    PERFORM match_result_decision_withdraw(v_id, 'the protest was overturned on appeal');
    SELECT r2.result_hash INTO h2 FROM match_result(M2) r2;
    PERFORM _assert(h2 = h1 AND _table_69(C, ids) = T0, 'db/69: withdrawing the award did not restore play''s result and its hash');
    BEGIN
      UPDATE match_result_decision SET reason = 'rewritten afterwards' WHERE id = v_id;
      PERFORM _assert(false, 'db/69: the league rewrote a decision');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    -- a friendly: the home school decides, the visitors do not
    PERFORM _as(U_SARAH);
    SELECT d.ok, d.decision_id INTO v_ok, v_id FROM match_result_decide(F, 'awarded', 'away', 'the visitors'' protest upheld by both schools', true) d;
    PERFORM _assert(v_ok AND (SELECT r2.outcome FROM match_result(F) r2) = 'away_win', 'db/69: the home school could not decide its friendly');
    PERFORM _as(U_WES_ADM);
    PERFORM _assert((SELECT w.reason FROM match_result_decision_withdraw(v_id, 'Westville would like it back') w) = 'not_permitted',
      'db/69 (decider): a school decided another school''s friendly');
    PERFORM _as(U_SARAH);
    PERFORM match_result_decision_withdraw(v_id, 'agreed in error; play stands');
    -- (support) a support session decides nothing and re-fixes nothing
    PERFORM _as(U_PLAT);
    SELECT ok, reason, id INTO v_ok, v_reason, S_ID FROM support_access_begin(HIL, 'competitionadmin', 'ticket 6901: a league''s table');
    PERFORM _assert(v_ok, format('db/69 (support): the session was not issued (%s)', v_reason));
    PERFORM _assert((SELECT d.reason FROM match_result_decide(M5, 'conceded', 'away', 'Westville could not field eleven') d) = 'support_session'
                    AND (SELECT x.reason FROM match_conditions_refix_table(M3, V2, 'support re-fixing the league') x) = 'support_session'
                    AND (SELECT a.reason FROM competition_points_adjust(C, ED, NULL, 'conduct', -2, 'support entering a penalty') a) = 'support_session',
      'db/69 (support): a support session decided, re-fixed or adjusted');
    PERFORM support_access_end(S_ID);

    -- §re-fix (parent §3.4): M3's table part from version 2, with a reason;
    -- the part it replaced kept beside it; play, the version it was fixed
    -- under and the sheet as they were; D's win now worth 5.
    PERFORM _as(U_LEAGUE);
    j := _doc_69(M3);
    PERFORM _assert((SELECT x.reason FROM match_conditions_refix_table(M3, V2, 'short') x) = 'reason_required'
                    AND (SELECT x.reason FROM match_conditions_refix_table(M3, gen_random_uuid(), 'version 2 corrected the win') x) = 'set_invalid'
                    AND (SELECT x.reason FROM match_conditions_refix_table(F, V2, 'version 2 corrected the win') x) = 'not_permitted',
      'db/69 (refix): a re-fix with no reason, an unknown version or of a friendly was not refused');
    PERFORM _as(U_SARAH);
    PERFORM _assert((SELECT x.reason FROM match_conditions_refix_table(M3, V2, 'version 2 corrected the win') x) = 'not_permitted',
      'db/69: a school re-fixed a league match''s table figures');
    PERFORM _as(U_LEAGUE);
    PERFORM _assert((SELECT x.ok FROM match_conditions_refix_table(M3, V2, 'version 2 corrected the win to five points') x),
      'db/69: the league could not re-fix M3');
    PERFORM _assert(_doc_69(M3)->'doc'->'play' = j->'doc'->'play' AND _doc_69(M3)->'doc'->'sheet' = j->'doc'->'sheet'
                    AND _doc_69(M3)->>'set' = V1::text
                    AND _doc_69(M3)->'before' = j->'doc'->'table'
                    AND _doc_69(M3)->'doc'->'table'->'points.win' = '5'::jsonb
                    AND _doc_69(M3)->>'by' = U_LEAGUE::text AND _doc_69(M3)->>'reason' = 'version 2 corrected the win to five points',
      format('db/69 (refix): the re-fix reads %s', _doc_69(M3)));
    PERFORM _assert(_table_69(C, ids) = 'A=4,0,3,0,1,2,4 B=3,1,0,1,1,8,3 C=3,1,0,1,1,8,2 D=4,2,1,0,1,12,1'
                    AND (SELECT string_agg(s.conditions_adjusted::text, ',' ORDER BY s.display_name) FROM competition_standing s WHERE s.competition_id = C) = '1,0,0,1',
      format('db/69: the re-fix did not reach the table, or the table does not say which sides it touched: %s', _table_69(C, ids)));

    -- §correction (design §2.6): an approved amendment that voids B's winning
    -- single makes M1 no result; the table follows on the next read, and the
    -- audit names the result before and after.
    SELECT r2.result_hash INTO h1 FROM match_result(M1) r2;
    PERFORM _as(U_SARAH);
    PERFORM _assert((SELECT a.ok FROM scoring_amendment_decide((ids->>'amend')::uuid, true, 'the single was a dead ball') a),
      'db/69: the amendment could not be approved');
    SELECT r2.result_hash, r2.outcome INTO h2, got FROM match_result(M1) r2;
    j := _audit_69(M1);
    -- (audit)
    PERFORM _assert(got = 'no_result' AND h2 <> h1
                    AND j->>'outcome_before' = 'away_win' AND j->>'result_hash_before' = h1
                    AND j->>'outcome_after' = 'no_result' AND j->>'result_hash_after' = h2 AND (j->>'result_changed')::boolean,
      format('db/69 (audit): M1 reads %s after the amendment, and the audit line %s', got, j));
    PERFORM _as(U_WESC);
    PERFORM _assert(_table_69(C, ids) = 'A=4,0,2,0,2,4,4 B=3,0,0,1,2,6,3 C=3,1,0,1,1,8,2 D=4,2,1,0,1,12,1'
                    AND (SELECT concat_ws('/', s.runs_for, s.balls_for, s.runs_against, s.balls_against) FROM competition_standing s
                          WHERE s.competition_id = C AND s.display_name = 'Verify 069 Hilton 1st XI') = '46/192/77/158',
      format('db/69: the amended result did not flip the table: %s', _table_69(C, ids)));

    -- (public) signed out: a published competition's table, sides and
    -- figures, no reason; an unpublished one nothing; a served fixture's
    -- result as structure, an unserved one nothing.
    PERFORM _publish_69(M2, C);
    PERFORM set_config('app.user_id', '', true);
    SELECT string_agg(concat_ws(',', p.rank, p.side, p.points, p.basis), ' ' ORDER BY p.rank) INTO got FROM public_competition_standing(C) p;
    PERFORM _assert(got = '1,Verify 069 Westville 2nd XI,12,computed 2,Verify 069 Hilton 2nd XI,8,computed 3,Verify 069 Westville 1st XI,6,computed 4,Verify 069 Hilton 1st XI,4,computed'
                    AND NOT EXISTS (SELECT 1 FROM public_competition_standing(C2))
                    AND (SELECT concat_ws(',', p.outcome, p.margin_kind, p.margin, p.winner_side) FROM public_match_result(M2) p) = 'home_win,runs,50,home'
                    AND NOT EXISTS (SELECT 1 FROM public_match_result(M1))
                    AND pg_get_function_result('public_match_result(uuid)'::regprocedure) !~ 'reason'
                    AND pg_get_function_result('public_competition_standing(uuid)'::regprocedure) !~ 'reason',
      format('db/69 (public): the signed-out table reads %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM competition_standing) AND NOT EXISTS (SELECT 1 FROM match_result(M2)),
      'db/69 (public): nobody signed in read the table or a result past the public reads');

    -- The new objects: the view as its reader, the rule as its caller, the
    -- tables closed to the application's writes.
    PERFORM _assert(coalesce((SELECT 'security_invoker=true' = ANY (c.reloptions) FROM pg_class c WHERE c.oid = 'competition_standing'::regclass), false)
                    AND NOT has_function_privilege('scrbrd_app', 'match_result_compute(uuid)', 'EXECUTE')
                    AND NOT has_table_privilege('scrbrd_app', 'match_result_decision', 'INSERT')
                    AND NOT has_table_privilege('scrbrd_app', 'competition_points_adjustment', 'UPDATE')
                    AND NOT has_function_privilege('scrbrd_app', 'competition_results_all(uuid)', 'EXECUTE'),
      'db/69 (scope): a new object runs as its owner, or the application may write a decision or an adjustment directly');
  END;

  -- ── 49. The family app's children: my_children (step 4 phase A, G1/G11) ──
  -- docs/design/STEP4_parent_pupil.md §5 G1 and §8 phase A. The read is not a
  -- database object — phase A needs no migration — so this section runs the
  -- read's own SQL, copied between the my_children markers below and held
  -- equal to services/api/read/read-api.mjs by read.test.mjs, as a TEMPORARY
  -- view owned by scrbrd_app: it runs as the caller, under RLS, exactly as
  -- the API runs it. It returns the caller's own live guardian links and
  -- nothing else: both of Sarah's children, at two schools, and none of the
  -- families her director-of-sport assignment lets her read the links of;
  -- each parent his own child; nothing for a coach, a spectator, the pupil
  -- (whose self link is not a guardian's), the office (which reads every
  -- link at its school), a parent whose link has ended, or a parent of a
  -- different child. valid_until rides along, NULL while the child is at
  -- school (db/62) and the date otherwise.
  --
  -- By here R Pillay's link has been wound back by the expiry assertion
  -- (_expire_link above), so D Pillay is the parent whose link has ended.
  --
  -- Each guard was falsified once — taken out of this copy of the read and
  -- the file run against the migrated database — and went red at the first
  -- assertion able to see it (read.test.mjs holds the two copies equal, so a
  -- guard cannot leave the API's copy and stay in this one):
  --   `a.person_id = app_user_id()` removed       → (own): Sarah lists the school's families
  --   `a.role = 'guardian'` removed               → a coach's family app lists his enquiry grant's boy
  --   the subject's valid_until clause removed    → (live)
  --   `s.verification_state = 'verified'` removed → (verified)
  -- (live) and (verified) are asked of Sarah because a plain parent cannot
  -- show them: RLS on the player already hides a child whose only link is
  -- dead, and the read's own clauses are the second wall, not the first.
  DECLARE
    U_WHIT  uuid := '88888888-0000-0000-0000-000000000010';  -- H Whitfield, parent of James Whitfield
    U_BEKK  uuid := '88888888-0000-0000-0000-000000000011';  -- A Bekker, parent of T Bekker
    U_CELE  uuid := '88888888-0000-0000-0000-000000000013';  -- N Cele: verified, consent not yet given
    P_WHIT  uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
    P_CELE  uuid := 'aaaaaaaa-0000-0000-0000-000000000004';
    got     text;
    n       integer;
    r       record;
  BEGIN
    EXECUTE $v49$CREATE TEMP VIEW _v49_my_children AS
-- my_children:begin
select s.player_id, p.full_name, p.known_as, p.team_code,
                  p.school_id, sc.name as school_name, sc.kind as school_kind,
                  s.relationship, s.verification_state, s.consent_state,
                  s.consent_version, s.consent_at,
                  s.valid_from, s.valid_until
             from role_assignment a
             join assignment_subject s on s.assignment_id = a.id
             join player p on p.id = s.player_id
             left join school sc on sc.id = p.school_id
            where a.person_id = app_user_id()
              and a.role = 'guardian'
              and a.active
              and (a.valid_from  is null or a.valid_from  <= sa_today())
              and (a.valid_until is null or a.valid_until >  sa_today())
              and (a.expires_at  is null or a.expires_at  >  now())
              and s.verification_state = 'verified'
              and s.valid_from <= sa_today()
              and (s.valid_until is null or s.valid_until > sa_today())
            order by p.full_name, s.player_id
-- my_children:end
$v49$;

    -- (own) Sarah: a director of sport, a coach and a parent at two schools.
    -- Her two children, each with his own school, and nobody else's — though
    -- her office assignment reads every Hilton family's link.
    PERFORM _as(U_SARAH);
    SELECT string_agg(full_name || '@' || school_kind || '@' || coalesce(school_name, '?'), ',' ORDER BY full_name)
      INTO got FROM _v49_my_children;
    PERFORM _assert(got = 'D Mkhize@school@Westville Boys'' High,K Dlamini@school@Hilton College',
      format('§49 (own): Sarah''s family app lists %s', coalesce(got, 'nothing')));
    PERFORM _assert((SELECT count(*) FROM assignment_subject) > 2,
      '§49: the fixture is void — Sarah reads no other family''s link to be kept from');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children WHERE valid_until IS NOT NULL OR relationship <> 'parent'
                                  OR verification_state <> 'verified' OR consent_state <> 'granted'),
      '§49: Sarah''s links are not the open, verified, consented parent links the seed made');
    -- (GA-I20 A1, R8a) Each link carries the wording of the school's terms
    -- it was agreed under, and when, as the link holds them (the seed
    -- records popia-2026-01 on every granted link).
    PERFORM _assert((SELECT count(*) FROM _v49_my_children
                      WHERE consent_version = 'popia-2026-01' AND consent_at IS NOT NULL) = 2,
      '§49 (A1): Sarah''s granted links do not carry their own consent version and time');

    -- (G11) The end date rides along, and is the link's own.
    PERFORM _set_link_end_49(P_U16B, U_SARAH, current_date + 400);
    SELECT valid_until INTO r FROM _v49_my_children WHERE player_id = P_U16B;
    PERFORM _assert(r.valid_until = current_date + 400, format('§49 (G11): the link''s end date reads %s', r.valid_until));
    PERFORM _assert((SELECT valid_until FROM _v49_my_children WHERE player_id = P_WES) IS NULL,
      '§49 (G11): one link''s end date leaked onto the other child''s');

    -- (live) and (verified): a link that has ended, or that the office has
    -- not verified, is no link — even for Sarah, whose office assignment
    -- still reads the boy's own row, so RLS on the player cannot hide it.
    PERFORM _set_link_end_49(P_U16B, U_SARAH, current_date);
    PERFORM _assert(EXISTS (SELECT 1 FROM player WHERE id = P_U16B), '§49: the fixture is void — Sarah cannot read K Dlamini as staff');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children WHERE player_id = P_U16B),
      '§49 (live): a link that ended today is still on Sarah''s family app');
    PERFORM _set_link_end_49(P_U16B, U_SARAH, NULL);
    PERFORM _set_link_state_49(P_U16B, U_SARAH, 'pending');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children WHERE player_id = P_U16B),
      '§49 (verified): a link the office has not verified is on Sarah''s family app');
    PERFORM _set_link_state_49(P_U16B, U_SARAH, 'verified');
    PERFORM _assert(EXISTS (SELECT 1 FROM _v49_my_children WHERE player_id = P_U16B AND valid_until IS NULL),
      '§49: K Dlamini did not come back once his link was verified and open again');

    -- Each other parent: exactly his own live links, as the owner counts
    -- them (an earlier section gave H Whitfield a second child of his own),
    -- and none of Sarah's or each other's.
    PERFORM _as(U_WHIT);
    SELECT string_agg(player_id::text, ',' ORDER BY player_id::text) INTO got FROM _v49_my_children;
    PERFORM _assert(got = _live_guardian_links_49(U_WHIT) AND got LIKE '%' || P_WHIT::text || '%',
      format('§49: H Whitfield''s family app lists %s, his links are %s', coalesce(got, 'nothing'), _live_guardian_links_49(U_WHIT)));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children WHERE player_id IN (P_U16B, P_WES, P_OTHER, P_INJURED)),
      '§49: another family''s child is on H Whitfield''s family app');
    PERFORM _as(U_BEKK);
    SELECT string_agg(player_id::text, ',' ORDER BY player_id::text) INTO got FROM _v49_my_children;
    PERFORM _assert(got = _live_guardian_links_49(U_BEKK) AND got LIKE '%' || P_OTHER::text || '%',
      format('§49: A Bekker''s family app lists %s, his links are %s', coalesce(got, 'nothing'), _live_guardian_links_49(U_BEKK)));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children WHERE player_id IN (P_U16B, P_WES, P_WHIT, P_INJURED)),
      '§49: another family''s child is on A Bekker''s family app');
    PERFORM _as(U_SARAH);
    PERFORM _assert((SELECT string_agg(player_id::text, ',' ORDER BY player_id::text) FROM _v49_my_children) = _live_guardian_links_49(U_SARAH),
      '§49 (own): Sarah''s family app is not exactly her live links');

    -- (pending) A link the school verified but the parent has not consented
    -- under is a live link (app_can() reads verification, not consent), and
    -- says which it is.
    PERFORM _as(U_CELE);
    SELECT count(*) INTO n FROM _v49_my_children WHERE player_id = P_CELE AND consent_state = 'pending'
                                                   AND consent_version IS NULL AND consent_at IS NULL;
    PERFORM _assert(n = 1, '§49 (pending): N Cele''s verified link is missing, does not say consent is pending, or claims a version or time no one recorded');
    -- A link the school has not verified is no link at all.
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children WHERE verification_state <> 'verified'),
      '§49 (pending): an unverified link is listed');

    -- (ended) The parent whose link has ended — D Pillay, wound back above,
    -- and V Naidoo, whose son turned eighteen before the seed was written.
    PERFORM _as(U_PARENT);
    SELECT count(*) INTO n FROM _v49_my_children;
    PERFORM _assert(n = 0, format('§49 (ended): D Pillay''s ended link still lists %s child(ren)', n));
    PERFORM _as(U_NAIDOO);
    SELECT count(*) INTO n FROM _v49_my_children;
    PERFORM _assert(n = 0, format('§49 (ended): V Naidoo''s ended link still lists %s child(ren)', n));

    -- Nothing for anybody who is not a guardian: a coach, a spectator, the
    -- pupil reading his own file (self) and the office, which reads every
    -- link at its school to work them.
    PERFORM _as(U_COACH2);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children), '§49: a coach''s family app lists children');
    PERFORM _as(U_WATCHER);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children), '§49: a spectator''s family app lists children');
    PERFORM _as(U_SELF);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children), '§49 (self): the pupil''s own self link is listed as a child');
    PERFORM _as(U_REGISTRAR);
    PERFORM _assert((SELECT count(*) FROM assignment_subject) >= 6,
      '§49: the fixture is void — the office reads no families'' links to be kept from');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v49_my_children), '§49 (office): the office''s family app lists the school''s families');

    EXECUTE 'DROP VIEW _v49_my_children';
  END;

  -- ── 48. Parent lift clubs, phase 1: the arrangement (SCRBRD-124, db/70) ──
  -- docs/design/SCRBRD-124_lift_clubs.md §8's phase 1 row, with principals:
  -- the school's two keys; who may offer and who may ask, and the zeros —
  -- a parent at another school, a parent with no child on the side, a pupil
  -- under eighteen, a coach, the office, a support session, the owner's key
  -- and a pad credential neither offer nor ask and read no offer; consent per
  -- boy per lift, by version; the lone passenger; clearance; a fixture moved
  -- and called off; links that end; names and numbers only through the two
  -- logged doors, numbers only on the day; no name, number or address in any
  -- lift row or notice; the policy withdrawn. _seed_70() builds its own world.
  -- With Kameel's decisions of 2026-10-01: a lift needs the family's consent
  -- to processing GRANTED (Pat's mother, pending, then granted); a withdrawal
  -- or a voided seat that leaves one boy alone under a policy refusing it
  -- takes his seat back to requested, and one allowing it does not; and no
  -- pupil drives, offers, or acts for anybody — Ed, eighteen, not for his
  -- brother through a guardian link. With Kameel's follow-up (2026-10-01):
  -- Ed, eighteen and at school, asks a seat for himself, is seated, reads his
  -- own seat and the lift it is on (the driver's name and number once it is
  -- confirmed, logged) and withdraws it; his mother asks and withdraws for him
  -- too; at seventeen, or gone from school, he is refused, and his own seat
  -- is void when he leaves; the one-to-one rule counts children only.
  -- tools/smoke-lifts.mjs walks the same through the API.
  --
  -- Each labelled assertion was falsified once — the guard broken (as the
  -- owner, inside this file's own transaction, before the section ran) — and
  -- went red, and was green again restored. 82 breaks, and five single
  -- layers that held alone as designed (marked "held"):
  --   (keys)      lift_module_live() without the policy; lift_policy_sign()
  --               without the platform's grant; with fixture.read for the
  --               policy capability (the office signed)
  --   (declare)   the roadworthy check dropped; the contact not required to be
  --               a child of hers; the registration not normalised
  --   (pupil)     lift_driver_declare() without its pupil refusal;
  --               my_lift_standing() without its pupil answer;
  --               lift_seat_accept() without its driver test (Ed accepted);
  --               the pupil clause off lift_uncut() (held: every door has its
  --               own), off lift_passengers() (held), off both (Ed, linked to
  --               his brother, read three names: (adult-brother))
  --   (offer)     the out leg's meeting time unchecked; seats past the
  --               declaration; lift_offer_one_live dropped
  --   (zero)      lift_seat_not_platform dropped (the owner's key read six
  --               rows: (rls)); lift_uncut() without the platform clause (the
  --               owner signed: (keys)); the declaration's pad guard dropped;
  --               lift_offer_read widened to any guardian at the school
  --   (cut)       lift_offer_not_pupil dropped (Ed, linked to his brother,
  --               read three rows); lift_policy_not_pupil dropped
  --   (adult)     Kameel's follow-up: the request's not_yet_eighteen word
  --               dropped, and lift_acting_for() calling every pupil 'self'
  --               (Dan, seventeen: (pupil)); lift_adult_at_school() without
  --               the age (Dan read offers: (zero)) and without
  --               still_at_school() ((adult-left)); lift_uncut_for() without
  --               its exception (Ed read nothing); the request's
  --               pupil_excluded for another boy dropped (refused, wrong
  --               word: (cut)), and with lift_uncut_for()'s pupil clause and
  --               lift_acting_for()'s pupil return also gone (a seat for his
  --               brother: (cut)); lift_offers_for() listing a pupil's guardian
  --               links (held: each boy listed must pass lift_uncut_for()),
  --               and with that check dropped too ((cut)); the driver's name
  --               shown before his seat is confirmed ((zero)); lift_contacts()
  --               without its self branch, and without "confirmed" for him;
  --               lift_notify_family() not telling him; lift_notify() closed
  --               to him; lift_notify() open to any pupil with
  --               lift_self_accounts() not asking his age (Dan was told);
  --               lift_seat_consent_live() taking a self seat on trust
  --               ((adult-17)); withdraw without 'self'; the guardian of an
  --               adult refused; the one-to-one count of every passenger (Ed
  --               alone refused), of the confirmed of any age (Dan beside Ed
  --               confirmed); the fallback counting Ed (Dan stayed
  --               confirmed); lift_self_settle() not voiding, and not called
  --               from the team trigger ((adult-left))
  --   (consent)   the link test back to "not withdrawn" (Pat's pending mother
  --               read the offers: (zero)); the declaration without its
  --               granted test; the standing line without its consent word
  --   (lone)      the fallback dropped from a withdrawal; dropped from a
  --               voided seat; taken whatever the policy (Dan, allowed,
  --               fell back); the family not told; the boy's name put in
  --               the notice ((privacy))
  --   (request)   the driver's own son; the side check
  --   (dup)       the pre-check (the index alone answers with no other offer)
  --   (names)     a requester let in; the log dropped; the coach on the way home
  --   (full), (one), (accept)  the seat count; the lone passenger; the driver test
  --   (summary)   oversee swapped for fixture.read (the coach read the counts)
  --   (numbers)   the window; confirmed swapped for any guardian at the school;
  --               the log dropped
  --   (move)      the version not bumped; the status without driver_version;
  --               reaffirm asking no family; a request, a reconfirm and a stale
  --               reaffirm each let through while waiting on the driver
  --   (edit)      the edit not carrying the driver's yes
  --   (withdraw)  a stranger let in
  --   (link)      lift_links_settle() without its seats, without its offers;
  --               lift_team_changed dropped (first red at (adult-left),
  --               which it also carries); lift_link_changed dropped
  --   (clear)     the clearance requirement skipped
  --   (void)      the abandoned branch; the driver not told
  --   (side)      the side test widened to any child at the school
  --   (policy)    the withdrawal not cancelling offers
  --   (privacy)   a driver_phone column; the driver's name in a notice body
  --   (write)     INSERT granted, and an INSERT policy, each alone held (two
  --               layers, as db/57); both together went red
  --   (coexist)   db/65's availability_ask_again dropped
  DECLARE
    ids      jsonb := _seed_70();
    M        uuid; MV uuid; MT uuid; MA uuid; O_MA uuid; S_ED uuid; S_MD uuid; S_MP uuid;
    P_JONO   uuid; P_BEN uuid; P_CARL uuid; P_DAN uuid; P_ED uuid; P_FINN uuid; P_WES70 uuid;
    U_DMUM   uuid; U_BMUM uuid; U_BDAD uuid; U_CMUM uuid; U_DNMUM uuid; U_EMUM uuid; U_FMUM uuid; U_WMUM uuid;
    U_PMUM   uuid; P_PAT uuid; S_PAT uuid; S_VP uuid;
    U_DAN    uuid; U_ED uuid; U_COACH70 uuid; U_OFFICE uuid; U_TCO uuid; U_HEAD uuid;
    C_JONO   uuid; C_BEN uuid;
    O_OUT    uuid; O_BACK uuid; O_TWO uuid; O_T uuid; O_V uuid; O_LATE uuid;
    S_BEN    uuid; S_CARL uuid; S_BACK_BEN uuid; S_BACK_CARL uuid; S_T uuid; S_VD uuid;
    v_ok     boolean;
    v_reason text;
    v_id     uuid;
    v_other  uuid;
    v_ver    integer;
    v_start  timestamptz;
    j        jsonb;
    got      text;
    want     text;
    k        bigint;
    who      uuid;
    BODY     text := 'Lifts to fixtures are arranged between families. The school facilitates and does not operate '
                  || 'lifts: it does not inspect or insure cars. A driver undertakes that she holds a licence, that '
                  || 'the car is insured and roadworthy, and that every boy wears a belt. If a boy is not collected, '
                  || 'stay with him and ring the school office. A concern goes to the DSO.';
  BEGIN
    M := (ids->>'m')::uuid; MV := (ids->>'mv')::uuid; MT := (ids->>'mt')::uuid; MA := (ids->>'ma')::uuid;
    P_JONO := (ids->>'p_jono')::uuid; P_BEN := (ids->>'p_ben')::uuid; P_CARL := (ids->>'p_carl')::uuid;
    P_DAN := (ids->>'p_dan')::uuid; P_ED := (ids->>'p_ed')::uuid; P_FINN := (ids->>'p_finn')::uuid;
    P_WES70 := (ids->>'p_wes')::uuid;
    U_DMUM := (ids->>'u_dmum')::uuid; U_BMUM := (ids->>'u_bmum')::uuid; U_BDAD := (ids->>'u_bdad')::uuid;
    U_CMUM := (ids->>'u_cmum')::uuid; U_DNMUM := (ids->>'u_dnmum')::uuid; U_EMUM := (ids->>'u_emum')::uuid;
    U_FMUM := (ids->>'u_fmum')::uuid; U_WMUM := (ids->>'u_wmum')::uuid;
    U_DAN := (ids->>'u_dan')::uuid; U_ED := (ids->>'u_ed')::uuid; U_COACH70 := (ids->>'u_coach')::uuid;
    U_PMUM := (ids->>'u_pmum')::uuid; P_PAT := (ids->>'p_pat')::uuid;
    U_OFFICE := (ids->>'u_office')::uuid; U_TCO := (ids->>'u_tco')::uuid; U_HEAD := (ids->>'u_head')::uuid;
    C_JONO := (ids->>'c_jono')::uuid; C_BEN := (ids->>'c_ben')::uuid;
    v_start := (ids->>'m_start')::timestamptz;
    -- The seed's own deferred events fire now, as its commit would: so each
    -- link step below is judged by the trigger it is about, and no other.
    PERFORM _v70_fire();

    -- (keys) the platform's grant AND the principal's signed policy (D17)
    PERFORM _as(U_HEAD);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_policy_sign(HIL, BODY, false, true, 'the Chapel car park');
    PERFORM _assert(NOT v_ok AND v_reason = 'module_disabled' AND NOT lift_module_live(HIL),
      format('db/70 (keys): the principal signed a policy before the platform granted the module: %s %s', v_ok, v_reason));
    PERFORM _v70_grant(HIL, true);
    PERFORM _assert(NOT lift_module_live(HIL), 'db/70 (keys): the platform''s grant alone switched lift clubs on');
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'silver Toyota Fortuner', 'ND 123 456', 4,
                                                                  true, true, true, true, true, C_JONO);
    PERFORM _assert(NOT v_ok AND v_reason = 'module_disabled',
      format('db/70 (keys): a parent declared with no policy signed: %s %s', v_ok, v_reason));
    FOREACH who IN ARRAY ARRAY[U_OFFICE, U_DMUM, U_OWNER] LOOP
      PERFORM _as(who);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_policy_sign(HIL, BODY, false, true, NULL);
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
        format('db/70 (keys): %s signed the school''s lift policy: %s %s', who, v_ok, v_reason));
    END LOOP;
    PERFORM _as(U_HEAD);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_policy_sign(HIL, 'Too short to be a policy.', false, true, NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'policy_too_short', format('db/70 (keys): a two-line policy was taken: %s', v_reason));
    SELECT ok, reason, version INTO v_ok, v_reason, v_ver FROM lift_policy_sign(HIL, BODY, false, true, 'the Chapel car park');
    PERFORM _assert(v_ok AND v_ver = 1 AND lift_module_live(HIL),
      format('db/70 (keys): the principal''s signature left lift clubs %s (%s, version %s)', lift_module_live(HIL), v_reason, v_ver));
    PERFORM _assert(NOT lift_module_live(WES), 'db/70 (keys): Westville, which the platform has not granted, is live');

    -- (declare) the yearly declaration: the four facts, the code, the car, her number
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'silver Toyota Fortuner', 'ND 123 456', 4,
                                                                  true, true, false, true, true, C_JONO);
    PERFORM _assert(NOT v_ok AND v_reason = 'declaration_incomplete', format('db/70 (declare): a car not roadworthy was declared: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'silver Toyota Fortuner', 'ND 123 456', 4,
                                                                  true, true, true, true, true, C_BEN);
    PERFORM _assert(NOT v_ok AND v_reason = 'contact_required',
      format('db/70 (declare): a driver named another family''s number as hers: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'silver Toyota Fortuner', 'nd 123-456', 4,
                                                                  true, true, true, true, true, C_JONO);
    PERFORM _assert(v_ok AND (SELECT registration FROM lift_driver_declaration WHERE person_id = U_DMUM AND withdrawn_at IS NULL) = 'ND 123 456'
                    AND (SELECT may_drive FROM my_lift_standing(HIL)),
      format('db/70 (declare): the driver''s declaration: %s %s', v_ok, v_reason));
    -- (pupil) a pupil never drives, at eighteen too (decisions 4 and 5)
    PERFORM _as(U_ED);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'white Polo', 'NP 1', 4, true, true, true, true, true, NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'pupil_excluded' AND (SELECT reason FROM my_lift_standing(HIL)) = 'pupil_excluded'
                    AND (SELECT words FROM my_lift_standing(HIL)) LIKE '%A pupil does not drive%',
      format('db/70 (pupil): a pupil of eighteen declared to drive: %s %s', v_ok, v_reason));
    -- (consent) a family whose consent to processing is not granted neither
    -- drives nor asks, and is told why in plain words (decision 2)
    PERFORM _as(U_PMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'grey Polo', 'NP 77', 2, true, true, true, true, true, NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'consent_not_granted'
                    AND (SELECT reason FROM my_lift_standing(HIL)) = 'consent_not_granted'
                    AND (SELECT words FROM my_lift_standing(HIL)) LIKE '%consent to the processing%',
      format('db/70 (consent): a guardian whose consent is pending declared to drive: %s %s', v_ok, v_reason));
    PERFORM _as(U_WMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_driver_declare(HIL, 'blue Hilux', 'NU 77', 4, true, true, true, true, true, NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'no_child_at_school',
      format('db/70 (declare): a parent at another school declared at Hilton: %s', v_reason));
    PERFORM _as(U_BMUM);
    SELECT ok INTO v_ok FROM lift_driver_declare(HIL, 'red Corolla', 'NU 88', 1, true, true, true, true, true, C_BEN);
    PERFORM _assert(v_ok, 'db/70 (declare): a second parent could not declare');

    -- (offer) the driver offers both legs of her own son's fixture (D1, D2)
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'out', 2, 'school', v_start + interval '30 minutes', NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'meet_after_start', format('db/70 (offer): an out leg meeting after the start: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'out', 5, 'school', v_start - interval '105 minutes', NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'more_seats_than_declared', format('db/70 (offer): five seats in a car declared with four: %s', v_reason));
    SELECT ok, reason, offer_id INTO v_ok, v_reason, O_OUT FROM lift_offer_create(M, 'out', 2, 'school', v_start - interval '105 minutes', 'leaving sharp');
    SELECT ok, reason, offer_id INTO v_ok, v_reason, O_BACK FROM lift_offer_create(M, 'back', 2, 'ground', v_start + interval '5 hours', NULL);
    PERFORM _assert(O_OUT IS NOT NULL AND O_BACK IS NOT NULL
                    AND (_v70_offer(O_OUT)).team_code = 'U15A' AND (_v70_offer(O_OUT)).fixture_starts_at = v_start,
      format('db/70 (offer): the driver''s two legs: %s %s %s', O_OUT, O_BACK, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'out', 2, 'ground', v_start - interval '60 minutes', NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'already_offered', format('db/70 (offer): a second out leg by the same driver: %s', v_reason));

    -- (zero) nobody else offers, asks, or reads an offer — but Ed, eighteen
    -- and at school, reads the offers on his own side as a boy who may ask:
    -- no driver's name, and himself the only boy on it (decision 5)
    FOREACH who IN ARRAY ARRAY[U_WMUM, U_FMUM, U_DAN, U_ED, U_PMUM, U_COACH70, U_OFFICE, U_TCO, U_HEAD, U_OWNER, U_PLAT] LOOP
      PERFORM _as(who);
      SELECT ok INTO v_ok FROM lift_offer_create(M, 'back', 1, 'ground', v_start + interval '6 hours', NULL);
      PERFORM _assert(NOT v_ok, format('db/70 (zero): %s offered a lift on the U15A''s fixture', who));
      SELECT ok INTO v_ok FROM lift_seat_request(O_OUT, P_DAN);
      PERFORM _assert(NOT v_ok, format('db/70 (zero): %s asked for a seat for Dan', who));
      SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_seat)
           + (SELECT count(*) FROM lift_offers_for(M) f
               WHERE who IS DISTINCT FROM U_ED OR f.driver_name IS NOT NULL
                  OR f.my_children <> jsonb_build_array(jsonb_build_object('playerId', P_ED, 'name', 'Ed Liftseventy', 'how', 'self'))) INTO k;
      PERFORM _assert(k = 0, format('db/70 (zero): %s reads %s lift row(s)', who, k));
      -- The coach is the out leg's receiver (§1.6), asked below.
      CONTINUE WHEN who = U_COACH70;
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM lift_passengers(O_OUT)) AND lift_contacts(O_OUT) IS NULL,
        format('db/70 (zero): %s reads the lift''s passengers or numbers', who));
    END LOOP;
    -- ...nor a support session at the school (as the transport coordinator,
    -- who holds oversee), nor a pad credential
    PERFORM _as(U_PLAT);
    SELECT ok, reason, id INTO v_ok, v_reason, v_id FROM support_access_begin(HIL, 'transportcoordinator', 'ticket v70: a family''s lift');
    PERFORM _assert(v_ok, format('db/70 (zero): no support session to test with: %s', v_reason));
    SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_driver_declaration) + (SELECT count(*) FROM lift_summary(M)) INTO k;
    PERFORM _assert(k = 0, format('db/70 (zero): a support session at Hilton reads %s lift row(s)', k));
    PERFORM support_access_end(v_id);
    PERFORM _as(U_DMUM);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', M::text, true);
    SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_driver_declaration) + (SELECT count(*) FROM lift_offers_for(M)) INTO k;
    SELECT ok INTO v_ok FROM lift_offer_create(MV, 'out', 1, 'school', (ids->>'mv_start')::timestamptz - interval '1 hour', NULL);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(k = 0 AND NOT v_ok, format('db/70 (zero): the driver''s pad credential reads %s lift row(s) or offers (%s)', k, v_ok));

    -- (rls) the family on the side reads the offers; the driver reads hers
    PERFORM _as(U_BMUM);
    SELECT count(*) INTO k FROM lift_offer WHERE match_id = M;
    SELECT string_agg(leg || ':' || driver_name || ':' || seats_left, ' ' ORDER BY leg) INTO got FROM lift_offers_for(M);
    PERFORM _assert(k = 2 AND got = 'back:V70 Dmum:2 out:V70 Dmum:2',
      format('db/70 (rls): Ben''s mother reads %s offer row(s) and the offers %s', k, got));

    -- (request) consent is his own guardian's, per boy, per lift (rule 1)
    SELECT ok, reason, seat_id INTO v_ok, v_reason, S_BEN FROM lift_seat_request(O_OUT, P_BEN);
    PERFORM _assert(v_ok, format('db/70 (request): Ben''s mother could not ask: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_CARL);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('db/70 (request): Ben''s mother asked for a team-mate: %s %s', v_ok, v_reason));
    PERFORM _as(U_CMUM);
    SELECT ok, seat_id INTO v_ok, S_CARL FROM lift_seat_request(O_OUT, P_CARL);
    PERFORM _assert(v_ok, 'db/70 (request): Carl''s mother could not ask');
    -- (pupil) a pupil under eighteen does not ask, even for himself (Ed, at
    -- eighteen, is (adult) below)
    PERFORM _as(U_DAN);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_BACK, P_DAN);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_eighteen' AND NOT EXISTS (SELECT 1 FROM _v70_seats_of(P_DAN)),
      format('db/70 (pupil): Dan, seventeen, asked for himself: %s %s', v_ok, v_reason));
    -- (consent) Pat's mother, pending, is refused and reads no offer; the
    -- office records her consent, and she asks
    PERFORM _as(U_PMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_PAT);
    SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_offers_for(M)) INTO k;
    PERFORM _assert(NOT v_ok AND v_reason = 'consent_not_granted' AND k = 0,
      format('db/70 (consent): a guardian whose consent is pending asked (%s %s) or read %s offer row(s)', v_ok, v_reason, k));
    PERFORM _v70_consent(P_PAT, U_PMUM);
    PERFORM _v70_fire();
    SELECT ok, reason, seat_id INTO v_ok, v_reason, S_PAT FROM lift_seat_request(O_OUT, P_PAT);
    PERFORM _assert(v_ok AND (_v70_seat(S_PAT)).guardian_link_id IS NOT NULL AND (SELECT may_drive IS NOT NULL FROM my_lift_standing(HIL))
                    AND (SELECT reason FROM my_lift_standing(HIL)) = 'no_declaration',
      format('db/70 (consent): with her consent granted, Pat''s mother could not ask: %s %s', v_ok, v_reason));
    -- (pupil) a pupil withdraws, accepts and reconfirms nothing either
    PERFORM _as(U_ED);
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_PAT);
    PERFORM _assert(NOT v_ok AND (SELECT ok FROM lift_seat_reconfirm(S_PAT)) IS NOT TRUE
                    AND (SELECT ok FROM lift_seat_accept(ARRAY[S_PAT])) IS NOT TRUE,
      'db/70 (pupil): a pupil acted on another family''s seat');
    PERFORM _as(U_FMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_FINN);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_on_side',
      format('db/70 (request): Finn, of the U14A, was asked onto the U15A''s lift: %s %s', v_ok, v_reason));
    PERFORM _as(U_CMUM);
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_CARL]);
    PERFORM _assert(NOT v_ok AND (_v70_seat(S_CARL)).state = 'requested', 'db/70 (accept): a family accepted its own request');
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_JONO);
    PERFORM _assert(NOT v_ok AND v_reason = 'driver_own_child', format('db/70 (request): the driver seated her own son: %s', v_reason));
    -- (dup) one live seat per boy per fixture per leg
    PERFORM _as(U_BMUM);
    SELECT ok, offer_id INTO v_ok, O_TWO FROM lift_offer_create(M, 'out', 1, 'ground', v_start - interval '45 minutes', NULL);
    PERFORM _as(U_CMUM);
    SELECT ok, reason, other_offer INTO v_ok, v_reason, v_other FROM lift_seat_request(O_TWO, P_CARL);
    PERFORM _assert(O_TWO IS NOT NULL AND NOT v_ok AND v_reason = 'already_on_a_lift' AND v_other = O_OUT,
      format('db/70 (dup): Carl asked onto a second out leg: %s %s %s', v_ok, v_reason, v_other));
    -- the driver is told, by notice, naming nobody
    PERFORM _assert(_v70_notice_count(U_DMUM, 'A seat has been asked for') = 3,
      format('db/70 (request): the driver has %s request notice(s), expected 3', _v70_notice_count(U_DMUM, 'A seat has been asked for')));

    -- (seat-rls) a family reads its own seat; the driver her seats and no names
    PERFORM _as(U_BMUM);
    SELECT string_agg(player_id::text, ' ') INTO got FROM lift_seat;
    PERFORM _assert(got = P_BEN::text, format('db/70 (rls): Ben''s mother reads the seats of %s', got));
    PERFORM _as(U_DMUM);
    SELECT count(*) INTO k FROM lift_seat WHERE offer_id = O_OUT;
    PERFORM _assert(k = 3 AND NOT EXISTS (SELECT 1 FROM player WHERE id IN (P_BEN, P_CARL, P_ED)),
      format('db/70 (rls): the driver reads %s seat(s), or a passenger''s name by SQL', k));
    FOREACH who IN ARRAY ARRAY[U_ED, U_COACH70, U_OFFICE, U_OWNER, U_PLAT] LOOP
      PERFORM _as(who);
      SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_seat) + (SELECT count(*) FROM lift_seat_live) INTO k;
      PERFORM _assert(k = 0, format('db/70 (rls): %s reads %s offer or seat row(s)', who, k));
    END LOOP;
    PERFORM _as(U_OFFICE);
    SELECT count(*) INTO k FROM lift_driver_declaration;
    PERFORM _assert(k = 2, format('db/70 (rls): the office reads %s declaration(s), expected the two', k));
    -- (cut) a pupil who is also a verified guardian — Ed, eighteen, linked to
    -- his younger brother Dan — still reads no lift row, never drives, and
    -- sees no boy but himself on the offers (D8, rule 4): the RESTRICTIVE
    -- pupil cut, not the absence of a link, is what keeps him out
    PERFORM _v70_brother(U_ED, P_DAN, true);
    PERFORM _as(U_ED);
    SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_seat) + (SELECT count(*) FROM lift_driver_declaration)
         + (SELECT count(*) FROM lift_policy)
         + (SELECT count(*) FROM lift_offers_for(M) f, jsonb_array_elements(f.my_children) c WHERE c->>'playerId' <> P_ED::text) INTO k;
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'back', 1, 'ground', v_start + interval '6 hours', NULL);
    PERFORM _assert(k = 0 AND NOT v_ok AND v_reason = 'pupil_excluded',
      format('db/70 (cut): Ed, a pupil linked as his brother''s guardian, reads %s lift row(s) and offers: %s %s', k, v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_DAN);
    PERFORM _assert(NOT v_ok AND v_reason = 'pupil_excluded' AND NOT EXISTS (SELECT 1 FROM _v70_seats_of(P_DAN)),
      format('db/70 (cut): Ed asked a seat for his brother through his guardian link: %s %s', v_ok, v_reason));
    PERFORM _v70_brother(U_ED, P_DAN, false);

    -- (names) to the driver, logged; nothing to a family not yet confirmed
    PERFORM _as(U_DMUM);
    SELECT string_agg(full_name || ':' || status, ' ' ORDER BY full_name) INTO got FROM lift_passengers(O_OUT);
    PERFORM _assert(got = 'Ben Liftseventy:requested Carl Liftseventy:requested Pat Liftseventy:requested'
                    AND _v70_logged('lift_passengers', O_OUT, U_DMUM) = 1,
      format('db/70 (names): the driver reads %s, logged %s time(s)', got, _v70_logged('lift_passengers', O_OUT, U_DMUM)));
    PERFORM _as(U_BMUM);
    SELECT count(*) INTO k FROM lift_passengers(O_OUT);
    PERFORM _assert(k = 0 AND _v70_logged('lift_passengers', O_OUT, U_BMUM) = 0,
      format('db/70 (names): a family whose seat is only asked for read %s other passenger(s), or was let in', k));

    -- (full) the seats are the seats
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_BEN, S_CARL, S_PAT]);
    PERFORM _assert(NOT v_ok AND v_reason = 'seats_full', format('db/70 (full): three accepted into two seats: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_BEN]);
    PERFORM _assert(v_ok AND _v70_status(S_BEN) = 'confirmed',
      format('db/70 (accept): a lone passenger, which the policy allows, was refused: %s %s', v_reason, _v70_status(S_BEN)));
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_CARL]);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_PAT]);
    PERFORM _assert(NOT v_ok AND v_reason = 'seats_full' AND _v70_status(S_CARL) = 'confirmed' AND _v70_status(S_PAT) = 'requested',
      format('db/70 (full): a third into two seats: %s %s', v_ok, v_reason));

    -- (one) the school's policy refuses a lone passenger (D5): judged on the
    -- count an acceptance leaves, so two may be taken together
    PERFORM _as(U_HEAD);
    SELECT ok, version INTO v_ok, v_ver FROM lift_policy_sign(HIL, BODY, false, false, 'the Chapel car park');
    PERFORM _assert(v_ok AND v_ver = 2 AND (_v70_offer(O_OUT)).state = 'open',
      'db/70 (one): re-signing the policy did not take, or touched an open offer');
    PERFORM _as(U_BMUM);
    SELECT seat_id INTO S_BACK_BEN FROM lift_seat_request(O_BACK, P_BEN);
    PERFORM _as(U_CMUM);
    SELECT seat_id INTO S_BACK_CARL FROM lift_seat_request(O_BACK, P_CARL);
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_BACK_BEN]);
    PERFORM _assert(NOT v_ok AND v_reason = 'one_to_one_not_allowed',
      format('db/70 (one): a lone passenger under a policy refusing one: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_BACK_BEN, S_BACK_CARL]);
    PERFORM _assert(v_ok AND _v70_status(S_BACK_BEN) = 'confirmed' AND _v70_status(S_BACK_CARL) = 'confirmed',
      format('db/70 (one): two together under that policy: %s %s', v_ok, v_reason));

    -- (names) a confirmed family reads the other confirmed boys, logged; not the asked-for one
    PERFORM _as(U_BMUM);
    SELECT string_agg(full_name, ' ' ORDER BY full_name) INTO got FROM lift_passengers(O_OUT);
    PERFORM _assert(got = 'Ben Liftseventy Carl Liftseventy' AND _v70_logged('lift_passengers', O_OUT, U_BMUM) = 1,
      format('db/70 (names): Ben''s confirmed mother reads %s', got));
    -- the coach, for the side's out leg (§1.6): confirmed names, logged; nothing of the way home
    PERFORM _as(U_COACH70);
    SELECT string_agg(full_name, ' ' ORDER BY full_name) INTO got FROM lift_passengers(O_OUT);
    PERFORM _assert(got = 'Ben Liftseventy Carl Liftseventy' AND NOT EXISTS (SELECT 1 FROM lift_passengers(O_BACK))
                    AND _v70_logged('lift_passengers', O_OUT, U_COACH70) = 1,
      format('db/70 (names): the side''s coach reads %s of the way out', got));

    -- (summary) the office's counts, and no name; nothing for anybody else
    PERFORM _as(U_OFFICE);
    SELECT string_agg(format('%s:%s/%s/%s/%s/%s', leg, offers, seats_offered, confirmed, requested, awaiting), ' ' ORDER BY leg) INTO got
      FROM lift_summary(M);
    PERFORM _assert(got = 'back:1/2/2/0/0 out:2/3/2/1/0', format('db/70 (summary): the office reads %s', got));
    FOREACH who IN ARRAY ARRAY[U_COACH70, U_BMUM, U_DMUM, U_HEAD, U_OWNER] LOOP
      PERFORM _as(who);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM lift_summary(M)), format('db/70 (summary): %s reads the office''s counts', who));
    END LOOP;

    -- (numbers) on the day only, to the driver and a confirmed family; logged
    PERFORM _as(U_DMUM);
    j := lift_contacts(O_OUT);
    PERFORM _assert(j IS NULL AND _v70_logged('lift_contacts', O_OUT) = 0,
      format('db/70 (numbers): the driver read numbers ten days before the lift: %s', j));
    SELECT offer_id INTO O_T FROM lift_offer_create(MT, 'out', 2, 'school',
                                                    ((current_date + 1)::timestamp + time '08:00') AT TIME ZONE 'Africa/Johannesburg', NULL);
    PERFORM _as(U_BMUM);
    SELECT seat_id INTO S_T FROM lift_seat_request(O_T, P_BEN);
    PERFORM _as(U_CMUM);
    SELECT seat_id INTO v_id FROM lift_seat_request(O_T, P_CARL);
    PERFORM _as(U_DMUM);
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_T, v_id]);
    j := lift_contacts(O_T);
    PERFORM _assert(v_ok AND j->>'as' = 'driver'
                    AND (SELECT string_agg(p->>'name' || '/' || (p->'contacts'->0->>'phone'), ' ' ORDER BY p->>'name')
                           FROM jsonb_array_elements(j->'passengers') p) = 'Ben Liftseventy/+27 82 070 0002 Carl Liftseventy/+27 82 070 0003'
                    AND j->'passengers'->0->>'guardian' = 'V70 Bmum',
      format('db/70 (numbers): the driver reads, on the day, %s', j));
    PERFORM _as(U_BMUM);
    j := lift_contacts(O_T);
    PERFORM _assert(j->>'as' = 'guardian' AND j->'driver'->>'phone' = '+27 82 070 0001'
                    AND j->'driver'->>'registration' = 'ND 123 456' AND j->'driver'->>'name' = 'V70 Dmum',
      format('db/70 (numbers): Ben''s mother reads, on the day, %s', j));
    PERFORM _assert(_v70_logged('lift_contacts', O_T, U_DMUM) = 1 AND _v70_logged('lift_contacts', O_T, U_BMUM) = 1,
      'db/70 (numbers): a read of the numbers was not on the access log');
    FOREACH who IN ARRAY ARRAY[U_FMUM, U_COACH70, U_OFFICE, U_ED] LOOP
      PERFORM _as(who);
      PERFORM _assert(lift_contacts(O_T) IS NULL, format('db/70 (numbers): %s read the day''s numbers', who));
    END LOOP;

    -- (move) the fixture moves a day: every lift on it waits on its driver,
    -- then on each family, then is confirmed again (§1.5)
    PERFORM _v70_fixture(M, interval '1 day');
    PERFORM _assert((_v70_offer(O_OUT)).version = 2 AND (_v70_offer(O_OUT)).driver_version = 1
                    AND (_v70_offer(O_OUT)).fixture_changed_at IS NOT NULL,
      format('db/70 (move): the out leg after the move is version %s, the driver behind %s',
             (_v70_offer(O_OUT)).version, (_v70_offer(O_OUT)).driver_version));
    SELECT string_agg(_v70_status(x), ' ') INTO got FROM unnest(ARRAY[S_BEN, S_CARL, S_PAT, S_BACK_BEN]) x;
    PERFORM _assert(got = 'awaiting_driver awaiting_driver awaiting_driver awaiting_driver',
      format('db/70 (move): after the move the seats read %s', got));
    PERFORM _assert(_v70_notice_count(U_DMUM, 'A fixture has moved: do you still offer the lift?') = 2
                    AND _v70_notice_count(U_BMUM, 'A lift has changed: please confirm again') = 0,
      'db/70 (move): the driver was not asked about both legs, or a family was asked before she answered');
    PERFORM _as(U_CMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_reconfirm(S_CARL);
    PERFORM _assert(NOT v_ok AND v_reason = 'awaiting_driver', format('db/70 (move): a family said yes before the driver: %s', v_reason));
    PERFORM _as(U_DNMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_DAN);
    PERFORM _assert(NOT v_ok AND v_reason = 'awaiting_driver', format('db/70 (move): a new request on a lift waiting on its driver: %s', v_reason));
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_reaffirm(O_OUT, 1);
    PERFORM _assert(NOT v_ok AND v_reason = 'version_conflict', format('db/70 (move): a reaffirm against a stale version: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_reaffirm(O_OUT, 2);
    SELECT string_agg(_v70_status(x), ' ') INTO got FROM unnest(ARRAY[S_BEN, S_CARL, S_PAT]) x;
    PERFORM _assert(v_ok AND got = 'awaiting_guardian awaiting_guardian awaiting_guardian'
                    AND _v70_notice_count(U_BMUM, 'A lift has changed: please confirm again') = 1
                    -- Asked of the parent who asked for the seat only, not Ben's
                    -- father (Kameel, 2026-10-01; db/76 re-emits the notice path).
                    AND _v70_notice_count(U_BDAD, 'A lift has changed: please confirm again') = 0,
      format('db/70 (move): after the driver stood behind it: %s %s, seats %s', v_ok, v_reason, got));
    PERFORM _as(U_BMUM);
    SELECT ok INTO v_ok FROM lift_seat_reconfirm(S_BEN);
    PERFORM _assert(v_ok AND _v70_status(S_BEN) = 'confirmed' AND _v70_status(S_CARL) = 'awaiting_guardian',
      format('db/70 (move): after Ben''s mother said yes again, Ben %s and Carl %s', _v70_status(S_BEN), _v70_status(S_CARL)));
    -- an edit is a new lift too: version up, every family asked again
    PERFORM _as(U_DMUM);
    SELECT ok, reason, version INTO v_ok, v_reason, v_ver FROM lift_offer_update(O_BACK, 2, 'school',
                                                                               v_start + interval '1 day 5 hours', 'by the scoreboard', 2);
    PERFORM _assert(v_ok AND v_ver = 3 AND _v70_status(S_BACK_BEN) = 'awaiting_guardian' AND _v70_status(S_BACK_CARL) = 'awaiting_guardian',
      format('db/70 (edit): after the driver''s edit: %s %s %s, Ben %s', v_ok, v_reason, v_ver, _v70_status(S_BACK_BEN)));

    -- (withdraw) a "no" from either guardian ends the seat (D13)
    PERFORM _as(U_BDAD);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_withdraw(S_BEN);
    PERFORM _assert(v_ok AND (_v70_seat(S_BEN)).state = 'withdrawn' AND (_v70_seat(S_BEN)).ended_by = U_BDAD,
      format('db/70 (withdraw): Ben''s father''s no: %s %s', v_ok, v_reason));
    -- (lone) that left Carl alone on the way there, under a policy refusing
    -- one-to-one (version 2): his seat is not confirmed any more, and his
    -- family and the driver are told, naming nobody (decision 3)
    PERFORM _assert((_v70_seat(S_CARL)).state = 'requested' AND (_v70_seat(S_CARL)).driver_ok_version IS NULL
                    AND _v70_status(S_CARL) <> 'confirmed'
                    AND _v70_notice_count(U_CMUM, 'A seat on a lift is no longer confirmed') = 1
                    AND _v70_notice_count(U_DMUM, 'One boy is left on your lift') = 1,
      format('db/70 (lone): after Ben was withdrawn Carl''s seat is %s (%s), his mother told %s time(s), the driver %s',
             (_v70_seat(S_CARL)).state, _v70_status(S_CARL), _v70_notice_count(U_CMUM, 'A seat on a lift is no longer confirmed'),
             _v70_notice_count(U_DMUM, 'One boy is left on your lift')));
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_CARL]);
    PERFORM _assert(NOT v_ok AND v_reason IN ('one_to_one_not_allowed', 'awaiting_guardian'),
      format('db/70 (lone): the driver confirmed Carl alone again: %s %s', v_ok, v_reason));
    PERFORM _as(U_FMUM);
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_CARL);
    PERFORM _assert(NOT v_ok, 'db/70 (withdraw): a parent withdrew somebody else''s son');

    -- (link) a link that ends voids the seats it consented to (§6.4)
    PERFORM _v70_end_link(P_CARL, U_CMUM);
    PERFORM _v70_fire();
    PERFORM _assert((_v70_seat(S_CARL)).state = 'void' AND (_v70_seat(S_BACK_CARL)).state = 'void'
                    AND (_v70_offer(O_OUT)).state = 'open',
      format('db/70 (link): with Carl''s mother''s link ended, his seats are %s and %s',
             (_v70_seat(S_CARL)).state, (_v70_seat(S_BACK_CARL)).state));
    -- (lone) and Ben, left alone on the way home by Carl's voided seat, falls
    -- back too; the parent who asked for the seat is told — not his father
    -- (Kameel, 2026-10-01: the asker only; db/76) — and the driver again
    PERFORM _assert((_v70_seat(S_BACK_BEN)).state = 'requested'
                    AND _v70_notice_count(U_BMUM, 'A seat on a lift is no longer confirmed') >= 1
                    AND _v70_notice_count(U_BDAD, 'A seat on a lift is no longer confirmed') = 0
                    AND _v70_notice_count(U_DMUM, 'One boy is left on your lift') >= 2,
      format('db/70 (lone): with Carl''s seat voided, Ben''s seat on the way home is %s', (_v70_seat(S_BACK_BEN)).state));

    -- (clear) a policy requiring clearance: missing refuses, three current allow (D4)
    PERFORM _as(U_HEAD);
    SELECT ok INTO v_ok FROM lift_policy_sign(HIL, BODY, true, true, NULL);
    PERFORM _as(U_BMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'back', 1, 'ground', v_start + interval '1 day 6 hours', NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'clearance_required' AND (SELECT reason FROM my_lift_standing(HIL)) = 'clearance_required',
      format('db/70 (clear): a driver with no clearance recorded offered under a policy requiring it: %s %s', v_ok, v_reason));
    PERFORM _v70_clear(U_BMUM, HIL);
    SELECT ok, reason, offer_id INTO v_ok, v_reason, O_LATE FROM lift_offer_create(M, 'back', 1, 'ground', v_start + interval '1 day 6 hours', NULL);
    PERFORM _assert(v_ok, format('db/70 (clear): a driver with the three checks current was refused: %s', v_reason));
    PERFORM _v70_clear(U_DMUM, HIL);

    -- (void) the fixture called off: every lift and seat on it void; one
    -- notice to each adult, none to a pupil
    PERFORM _as(U_BMUM);
    SELECT offer_id INTO O_V FROM lift_offer_create(MV, 'out', 1, 'school', (ids->>'mv_start')::timestamptz - interval '1 hour', NULL);
    PERFORM _as(U_DMUM);
    SELECT offer_id INTO v_id FROM lift_offer_create(MV, 'out', 3, 'school', (ids->>'mv_start')::timestamptz - interval '2 hours', NULL);
    PERFORM _as(U_DNMUM);
    SELECT seat_id INTO S_VD FROM lift_seat_request(v_id, P_DAN);
    PERFORM _as(U_PMUM);
    SELECT seat_id INTO S_VP FROM lift_seat_request(v_id, P_PAT);
    PERFORM _as(U_DMUM);
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_VD, S_VP]);
    PERFORM _assert(v_ok AND O_V IS NOT NULL, 'db/70 (void): the lifts to the fixture that is called off could not be arranged');
    -- (lone) under a policy that allows one-to-one (version 3), a withdrawal
    -- that leaves Dan alone leaves his seat confirmed
    PERFORM _as(U_PMUM);
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_VP);
    PERFORM _assert(v_ok AND (_v70_seat(S_VD)).state = 'confirmed' AND _v70_status(S_VD) = 'confirmed'
                    AND _v70_notice_count(U_DNMUM, 'A seat on a lift is no longer confirmed') = 0,
      format('db/70 (lone): under a policy allowing it, Dan alone is %s', _v70_status(S_VD)));
    PERFORM _v70_fixture(MV, interval '0', 'abandoned');
    PERFORM _assert((_v70_offer(O_V)).state = 'void' AND (_v70_offer(v_id)).state = 'void' AND (_v70_offer(v_id)).cancel_kind = 'fixture'
                    AND (_v70_seat(S_VD)).state = 'void' AND (_v70_seat(S_VP)).state = 'withdrawn',
      format('db/70 (void): after the fixture was called off the lifts are %s and %s', (_v70_offer(O_V)).state, (_v70_offer(v_id)).state));
    PERFORM _assert(_v70_notices(MV, 'A lift is no longer available') || ' ' || _v70_notices(MV, 'A fixture is off')
                      = U_DNMUM::text
                        || ' ' || (SELECT string_agg(x::text, ' ' ORDER BY x::text) FROM unnest(ARRAY[U_BMUM, U_DMUM]) x),
      format('db/70 (void): the called-off fixture told %s / %s; expected Dan''s family and the two drivers once each',
             _v70_notices(MV, 'A lift is no longer available'), _v70_notices(MV, 'A fixture is off')));

    -- (adult) Kameel's follow-up (2026-10-01): a pupil of eighteen still at
    -- school asks a seat for himself — his own say, through his own self
    -- link — reads his own seat and the lift it is on, and withdraws it; his
    -- mother, by db/62's link past eighteen, may ask and withdraw for him too.
    -- Under a policy refusing one-to-one (version 4): the rule counts
    -- children, so an adult alone is seated and keeps no child company.
    PERFORM _as(U_HEAD);
    SELECT ok, version INTO v_ok, v_ver FROM lift_policy_sign(HIL, BODY, true, false, NULL);
    PERFORM _as(U_DMUM);
    SELECT ok, reason, offer_id INTO v_ok, v_reason, O_MA
      FROM lift_offer_create(MA, 'out', 3, 'school', (ids->>'ma_start')::timestamptz - interval '1 hour', NULL);
    PERFORM _assert(v_ok AND v_ver = 4, format('db/70 (adult): no lift to test with: %s %s, policy version %s', v_ok, v_reason, v_ver));
    PERFORM _as(U_ED);
    SELECT string_agg(coalesce(f.driver_name, '-') || ':' || f.meet_place || ':' || f.seats_left || ':' || f.my_children::text, ' ')
      INTO got FROM lift_offers_for(MA) f;
    want := '-:At school:3:' || jsonb_build_array(jsonb_build_object('playerId', P_ED, 'name', 'Ed Liftseventy', 'how', 'self'))::text;
    PERFORM _assert(got = want, format('db/70 (adult): Ed, eighteen and at school, reads the lift as %s', got));
    SELECT ok, reason, seat_id INTO v_ok, v_reason, S_ED FROM lift_seat_request(O_MA, P_ED);
    PERFORM _assert(v_ok AND (_v70_seat(S_ED)).consent_by = 'self' AND (_v70_seat(S_ED)).guardian_link_id IS NULL
                    AND (_v70_seat(S_ED)).requested_by = U_ED AND _v70_status(S_ED) = 'requested',
      format('db/70 (adult): Ed, eighteen and at school, could not ask for himself: %s %s', v_ok, v_reason));
    -- (adult-brother) ...and for nobody else: not for his brother, through a guardian link
    PERFORM _v70_brother(U_ED, P_DAN, true);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_MA, P_DAN);
    PERFORM _assert(NOT v_ok AND v_reason = 'pupil_excluded' AND NOT EXISTS (SELECT 1 FROM _v70_seats_of(P_DAN)),
      format('db/70 (adult-brother): Ed, eighteen, asked a seat for his brother: %s %s', v_ok, v_reason));
    PERFORM _v70_brother(U_ED, P_DAN, false);
    PERFORM _v70_fire();
    -- (adult-read) his own seat and nothing else: no lift table, no passenger
    -- list, no counts, and no name or number while his seat is only asked for
    PERFORM _as(U_ED);
    SELECT (SELECT count(*) FROM lift_offer) + (SELECT count(*) FROM lift_seat) + (SELECT count(*) FROM lift_seat_live)
         + (SELECT count(*) FROM lift_driver_declaration) + (SELECT count(*) FROM lift_policy)
         + (SELECT count(*) FROM lift_passengers(O_MA)) + (SELECT count(*) FROM lift_summary(MA)) INTO k;
    SELECT string_agg(coalesce(f.driver_name, '-') || ':' || (f.my_seats->0->>'status'), ' ') INTO got FROM lift_offers_for(MA) f;
    PERFORM _assert(k = 0 AND got = '-:requested' AND lift_contacts(O_MA) IS NULL AND _v70_logged('lift_contacts', O_MA) = 0,
      format('db/70 (adult-read): Ed reads %s lift row(s), and his seat as %s', k, got));
    -- (one-adult) the driver confirms Ed alone: an adult is not a lone child
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_ED]);
    PERFORM _assert(v_ok AND _v70_status(S_ED) = 'confirmed',
      format('db/70 (one-adult): Ed alone, eighteen, was refused under a policy refusing one-to-one: %s %s', v_ok, v_reason));
    -- ...and keeps no child company: Dan with only Ed beside him is still one-to-one
    PERFORM _as(U_DNMUM);
    SELECT seat_id INTO S_MD FROM lift_seat_request(O_MA, P_DAN);
    PERFORM _as(U_PMUM);
    SELECT seat_id INTO S_MP FROM lift_seat_request(O_MA, P_PAT);
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_MD]);
    PERFORM _assert(NOT v_ok AND v_reason = 'one_to_one_not_allowed' AND S_MP IS NOT NULL,
      format('db/70 (one-adult): Dan, seventeen, was confirmed with only Ed, an adult, beside him: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_MD, S_MP]);
    PERFORM _assert(v_ok AND _v70_status(S_MD) = 'confirmed' AND _v70_status(S_MP) = 'confirmed',
      format('db/70 (one-adult): Dan and Pat together beside Ed: %s %s', v_ok, v_reason));
    -- (adult-read) confirmed, Ed reads the driver's name and her number, as a
    -- guardian would, logged; still no passenger list and no counts
    PERFORM _as(U_ED);
    SELECT string_agg(coalesce(f.driver_name, '-') || ':' || (f.my_seats->0->>'status'), ' ') INTO got FROM lift_offers_for(MA) f;
    j := lift_contacts(O_MA);
    PERFORM _assert(got = 'V70 Dmum:confirmed' AND j->>'as' = 'guardian' AND j->'driver'->>'phone' = '+27 82 070 0001'
                    AND j->'driver'->>'name' = 'V70 Dmum' AND j->'passengers' IS NULL
                    AND _v70_logged('lift_contacts', O_MA, U_ED) = 1
                    AND NOT EXISTS (SELECT 1 FROM lift_passengers(O_MA)) AND NOT EXISTS (SELECT 1 FROM lift_summary(MA)),
      format('db/70 (adult-read): Ed, confirmed, reads %s and %s, logged %s time(s)', got, j, _v70_logged('lift_contacts', O_MA, U_ED)));
    -- (adult-brother) linked again as Dan's guardian, with Dan confirmed beside
    -- him, Ed reads no passenger list and cannot withdraw his brother's seat
    PERFORM _v70_brother(U_ED, P_DAN, true);
    PERFORM _as(U_ED);
    SELECT count(*) INTO k FROM lift_passengers(O_MA);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_withdraw(S_MD);
    PERFORM _assert(k = 0 AND _v70_logged('lift_passengers', O_MA, U_ED) = 0 AND NOT v_ok AND _v70_status(S_MD) = 'confirmed',
      format('db/70 (adult-brother): Ed, linked to Dan, read %s passenger(s) or withdrew his seat (%s %s)', k, v_ok, v_reason));
    PERFORM _v70_brother(U_ED, P_DAN, false);
    PERFORM _v70_fire();
    PERFORM _as(U_ED);
    -- (adult-notice) he is told his seat is confirmed, naming nobody — he
    -- asked for it, so he alone (Kameel, 2026-10-01: the asker only; db/76),
    -- not his mother; he reads his own notice, and no team-mate reads it
    SELECT count(*) INTO k FROM notification n
     WHERE n.title = 'A seat on a lift is confirmed' AND n.subject_person_id = P_ED AND n.kind = 'system';
    PERFORM _assert(k = 1 AND _v70_notice_count(U_EMUM, 'A seat on a lift is confirmed') = 0,
      format('db/70 (adult-notice): Ed reads %s notice(s) that his seat is confirmed; his mother has %s',
             k, _v70_notice_count(U_EMUM, 'A seat on a lift is confirmed')));
    PERFORM _as(U_DAN);
    SELECT count(*) INTO k FROM notification n WHERE n.subject_person_id = P_ED;
    PERFORM _assert(k = 0 AND _v70_lift_notices_to(U_DAN) = 0,
      format('db/70 (adult-notice): Dan, seventeen, reads %s notice(s) about Ed, and has %s lift notice(s)', k, _v70_lift_notices_to(U_DAN)));
    -- (lone-adult) Pat withdrawn leaves Dan the only child: he falls back,
    -- his family told; Ed, an adult, stays confirmed
    PERFORM _as(U_PMUM);
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_MP);
    PERFORM _assert(v_ok AND (_v70_seat(S_MD)).state = 'requested' AND _v70_status(S_ED) = 'confirmed'
                    AND _v70_notice_count(U_DNMUM, 'A seat on a lift is no longer confirmed') = 1
                    AND _v70_lift_notices_to(U_DAN) = 0,
      format('db/70 (lone-adult): with Pat withdrawn, Dan beside Ed is %s and Ed %s', (_v70_seat(S_MD)).state, _v70_status(S_ED)));
    -- (adult) Ed withdraws his own seat
    PERFORM _as(U_ED);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_withdraw(S_ED);
    PERFORM _assert(v_ok AND (_v70_seat(S_ED)).state = 'withdrawn' AND (_v70_seat(S_ED)).ended_by = U_ED,
      format('db/70 (adult): Ed could not withdraw his own seat: %s %s', v_ok, v_reason));
    -- (guardian-adult) his mother asks for him and withdraws it, her granted link the consent
    PERFORM _as(U_EMUM);
    SELECT ok, reason, seat_id INTO v_ok, v_reason, S_ED FROM lift_seat_request(O_MA, P_ED);
    PERFORM _assert(v_ok AND (_v70_seat(S_ED)).consent_by = 'guardian' AND (_v70_seat(S_ED)).guardian_link_id IS NOT NULL,
      format('db/70 (guardian-adult): Ed''s mother could not ask for him at eighteen: %s %s', v_ok, v_reason));
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_ED);
    PERFORM _assert(v_ok AND (_v70_seat(S_ED)).state = 'withdrawn' AND (_v70_seat(S_ED)).ended_by = U_EMUM,
      'db/70 (guardian-adult): Ed''s mother could not withdraw his seat');
    -- (adult-17) at seventeen (his date of birth put right) he is refused,
    -- reads no lift, and the seat he had asked for himself stands on no yes:
    -- the driver cannot confirm it
    PERFORM _as(U_ED);
    SELECT ok, seat_id INTO v_ok, S_ED FROM lift_seat_request(O_MA, P_ED);
    PERFORM _set_born(P_ED, (current_date - make_interval(years => 17) - make_interval(days => 40))::date);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_MA, P_ED);
    SELECT count(*) INTO k FROM lift_offers_for(MA);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_eighteen' AND k = 0 AND lift_contacts(O_MA) IS NULL
                    AND _v70_status(S_ED) = 'awaiting_guardian',
      format('db/70 (adult-17): Ed at seventeen asked (%s %s), read %s offer(s), his seat %s', v_ok, v_reason, k, _v70_status(S_ED)));
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_ED]);
    PERFORM _assert(NOT v_ok AND v_reason = 'awaiting_guardian',
      format('db/70 (adult-17): the driver confirmed Ed''s own seat at seventeen: %s %s', v_ok, v_reason));
    PERFORM _set_born(P_ED, (current_date - make_interval(years => 18) - make_interval(days => 40))::date);
    -- (adult-left) at eighteen and gone from school: refused, reads no lift,
    -- and the seat he had asked for himself is void
    PERFORM _as(U_ED);
    PERFORM _assert(_v70_status(S_ED) = 'requested', format('db/70 (adult-left): Ed''s own seat at eighteen again reads %s', _v70_status(S_ED)));
    PERFORM _v60_leave(P_ED);
    PERFORM _v70_fire();
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_MA, P_ED);
    SELECT count(*) INTO k FROM lift_offers_for(MA);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_at_school' AND k = 0 AND (_v70_seat(S_ED)).state = 'void',
      format('db/70 (adult-left): Ed, gone from school, asked (%s %s), read %s offer(s), his seat %s',
             v_ok, v_reason, k, (_v70_seat(S_ED)).state));
    PERFORM _v60_rejoin(P_ED);
    PERFORM _v70_fire();

    -- (link) the driver's son leaves the side: her lifts on it are cancelled
    -- link_ended, and she cannot offer on it (D2)
    PERFORM _v70_move(P_JONO, 'U14A');
    PERFORM _v70_fire();
    PERFORM _assert((_v70_offer(O_OUT)).state = 'cancelled' AND (_v70_offer(O_OUT)).cancel_kind = 'link_ended'
                    AND (_v70_offer(O_T)).cancel_kind = 'link_ended' AND (_v70_seat(S_T)).state = 'cancelled'
                    AND (_v70_offer(O_TWO)).state = 'open',
      format('db/70 (link): with her son moved off the side, her lift is %s (%s)', (_v70_offer(O_OUT)).state, (_v70_offer(O_OUT)).cancel_kind));
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'out', 2, 'school', v_start + interval '1 day' - interval '2 hours', NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'no_child_on_side',
      format('db/70 (side): a driver with no son on the side offered: %s %s', v_ok, v_reason));
    PERFORM _assert(_v70_notice_count(U_BMUM, 'A lift is no longer available') >= 1,
      'db/70 (link): the family on a lift cancelled when its driver''s son left the side was not told');

    -- (withdraw-policy) the principal withdraws: every open offer cancelled, and off
    PERFORM _as(U_HEAD);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_policy_withdraw(HIL);
    PERFORM _assert(v_ok AND NOT lift_module_live(HIL)
                    AND (_v70_offer(O_TWO)).cancel_kind = 'policy_withdrawn' AND (_v70_offer(O_LATE)).cancel_kind = 'policy_withdrawn'
                    AND NOT EXISTS (SELECT 1 FROM lift_offer o WHERE o.school_id = HIL AND o.state IN ('open', 'closed')),
      format('db/70 (policy): withdrawing the policy left lifts open: %s %s', v_ok, v_reason));
    PERFORM _as(U_BMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_create(M, 'back', 1, 'ground', v_start + interval '1 day 7 hours', NULL);
    PERFORM _assert(NOT v_ok AND v_reason IN ('module_disabled', 'no_policy'),
      format('db/70 (policy): an offer after the policy was withdrawn: %s', v_reason));

    -- (privacy) no lift row holds a number, address or name; no notice names
    -- a person or reaches a pupil but the boy of eighteen about his own seat;
    -- the application writes no lift row
    SELECT string_agg(table_name || '.' || column_name, ' ') INTO got FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name LIKE 'lift\_%'
       AND column_name ~ '(phone|address|name|email|id_number|mobile|location|latitude|longitude)';
    PERFORM _assert(got IS NULL, format('db/70 (privacy): lift rows carry %s', got));
    PERFORM _assert(_v70_named_notices() = 0 AND _v70_pupil_notices() = 0,
      format('db/70 (privacy): %s lift notice(s) name a person and %s reach a pupil', _v70_named_notices(), _v70_pupil_notices()));
    PERFORM _as(U_DMUM);
    BEGIN
      INSERT INTO lift_offer (school_id, match_id, team_code, leg, driver_id, declaration_id, seats, meet_kind, meet_at, fixture_starts_at)
      VALUES (HIL, M, 'U15A', 'out', U_DMUM, (SELECT id FROM lift_driver_declaration LIMIT 1), 1, 'school', now(), now());
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/70 (write): a parent wrote a lift row past the functions');
    BEGIN
      UPDATE lift_seat SET state = 'confirmed' WHERE player_id = P_JONO;
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/70 (write): a parent rewrote a seat past the functions');
    -- (coexist) SCRBRD-122's trigger and this file's both stand on match
    PERFORM _assert((SELECT count(*) FROM pg_trigger WHERE tgrelid = 'match'::regclass AND NOT tgisinternal
                       AND tgname IN ('availability_ask_again', 'lift_fixture_moved')) = 2,
      'db/70 (coexist): db/65''s and db/70''s triggers on match are not both in place');
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 50. The super over (SCRBRD-114 phase 3b, db/71) ──
  -- _seed_71(): a Hilton cup (a tie goes to a super over) and a Hilton
  -- league (a tie stands), five matches tied on the same over, and
  -- _so_71() appending the super over each is about (the seed's header).
  -- The Laws' refusals and the write path's super_over_not_provided are the
  -- fold's (packages/scoring/test/super-over.test.mjs; tools/smoke-results.mjs
  -- through the API); tools/smoke-fold-figures.mjs holds match_result() and
  -- ball_event_live.super_over to the fold over the design's logs. Here, as
  -- the application role, what the database must hold.
  --
  -- Each labelled assertion was falsified once — the function, view or
  -- trigger replaced in the database and this file run — and went red:
  --   (career)     ball_event_career without its filter: every career reader
  --                counts the super over
  --   (workload)   bowler_over reading ball_event_career: the boy's day loses
  --                the balls he bowled
  --   (marker)     ball_event_live.super_over read as NULL: every reader takes
  --                the super over for a match innings
  --   (live)       match_live_score without super_over
  --   (result)     match_result_compute() without its super-over block: a cup
  --                tie settled by a super over reads as settled by nobody
  --   (provided)   match_result_compute() deciding by a super over the
  --                document does not provide
  --   (pair)       penalty_credit_as_folded() and penalty_carried_as_folded()
  --                crediting across pairs
  --   (two)        innings_end_squad() not ending a super over at two wickets
  --   (gate)       the completion trigger dropped
  --   (scope)      ball_event_career as its owner
  --   (board)      broadcast_state() taking a chase's fallback target across
  --                pairs: the super over's first innings "chasing" the match
  DECLARE
    ids    jsonb := _seed_71();
    K1 uuid; K2 uuid; K3 uuid; K4 uuid; K5 uuid; L1 uuid; LG uuid;
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    P_NAID uuid := 'aaaaaaaa-0000-0000-0000-000000000003';
    c_before text; c_after text;
    t_before text; t_after text;
    w_before integer; w_after integer;
    got    text;
    v_ok   boolean;
    r      record;
  BEGIN
    K1 := (ids->>'k1')::uuid; K2 := (ids->>'k2')::uuid; K3 := (ids->>'k3')::uuid; K4 := (ids->>'k4')::uuid;
    K5 := (ids->>'k5')::uuid; L1 := (ids->>'l1')::uuid; LG := (ids->>'league')::uuid;

    -- Before any super over: every career figure, the boy's day, the table.
    PERFORM _as(U_SARAH);
    c_before := _careers_71(K1);
    PERFORM _assert(c_before LIKE 'aaaaaaaa-0000-0000-0000-000000000001,0,14,6,f;%',
      format('db/71: the seed is not as its header says: %s', left(c_before, 120)));
    PERFORM _as(U_OWNER);
    w_before := _load_71(P_NAID, DATE '2026-10-03');
    SELECT string_agg(concat_ws(',', s.team_code, s.played, s.won, s.lost, s.tied, s.points, round(s.nrr, 3), s.runs_for, s.balls_for), ' ' ORDER BY s.school_id)
      INTO t_before FROM competition_standing s WHERE s.competition_id = LG;

    -- (gate) a cup tie is not marked complete before its super over, nor
    -- before the organiser's award where none is played
    FOREACH got IN ARRAY ARRAY[K1::text, K4::text] LOOP
      BEGIN
        UPDATE match SET status = 'complete' WHERE id = got::uuid;
        v_ok := FOUND;
      EXCEPTION WHEN check_violation THEN v_ok := false;
      END;
      PERFORM _assert(NOT v_ok, format('db/71 (gate): a cup tie (%s) was marked complete with nothing settling who goes through', got));
    END LOOP;

    PERFORM _so_71(K1, 'k1'); PERFORM _so_71(K2, 'k2'); PERFORM _so_71(K3, 'k3'); PERFORM _so_71(L1, 'l1');

    -- (career) not a run, a ball, a wicket, a dismissal or a catch of a
    -- super over is in any career, season, window or keeper's record
    PERFORM _as(U_SARAH);
    c_after := _careers_71(K1);
    PERFORM _assert(c_after = c_before, format('db/71 (career): a super over moved a career: before %s; after %s', c_before, c_after));
    -- (scope) the career log is the reader's: a coach of neither side (the
    -- 2XI's) reads none of it, the home school reads it, and since db/97 so
    -- do the visitors, whose fixture it is (the log follows the fixture, §75)
    PERFORM _assert((SELECT count(*) FROM ball_event_career WHERE match_id = K1) > 0, 'db/71 (scope): Hilton''s director of sport reads none of her school''s career log');
    PERFORM _as(U_COACH2);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM ball_event_career WHERE match_id = K1),
      'db/71 (scope): a coach of neither side reads the fixture''s log through ball_event_career');
    PERFORM _as(U_WESC);
    PERFORM _assert((SELECT count(*) FROM ball_event_career WHERE match_id = K1) > 0,
      'db/71 (scope): the visitors'' coach reads none of his own fixture''s log through ball_event_career (db/97)');

    -- (marker) (live) the board's block: innings 2 and 3 are the first super over
    PERFORM _as(U_SARAH);
    SELECT string_agg(x.innings || '=' || coalesce(x.super_over::text, '-'), ' ' ORDER BY x.innings) INTO got
      FROM match_live_score x WHERE x.match_id = K1;
    PERFORM _assert(got = '0=- 1=- 2=1 3=1', format('db/71 (live): match_live_score reads %s', got));
    SELECT string_agg(DISTINCT b.innings || '=' || coalesce(b.super_over::text, '-'), ' ') INTO got
      FROM ball_event_live b WHERE b.match_id = K1;
    PERFORM _assert(got = '0=- 1=- 2=1 3=1', format('db/71 (marker): ball_event_live.super_over reads %s', got));

    -- (result) the match's outcome is the tie; the super over says who goes through
    SELECT concat_ws(',', x.outcome, x.decided_by, x.winner_side, x.winner_school_id = HIL, x.play_outcome,
                     x.super_overs->0->>'state', x.super_overs->0->>'first', x.super_overs->0->'b'->>'runs')
      INTO got FROM match_result(K1) x;
    PERFORM _assert(got = 'tie,super_over,home,t,tie,won,away,9', format('db/71 (result): K1 reads %s', got));
    -- (two) two wickets end a super over: all out, and the pair incomplete
    -- once the chase is sealed abandoned; nobody has decided it
    SELECT concat_ws(',', x.outcome, coalesce(x.decided_by, '-'), x.innings->2->>'end_reason', x.innings->2->>'complete',
                     x.super_overs->0->>'state')
      INTO got FROM match_result(K3) x;
    PERFORM _assert(got = 'tie,-,all_out,true,incomplete', format('db/71 (two): K3 reads %s', got));
    -- (pair) the five awarded in innings 2 open innings 3, never a match innings
    SELECT string_agg(x.innings || '=' || x.runs, ' ' ORDER BY x.innings) INTO got FROM match_live_score x WHERE x.match_id = K2;
    PERFORM _assert(got = '0=14 1=14 2=8 3=9', format('db/71 (pair): K2''s innings read %s', got));
    SELECT concat_ws(',', x.outcome, x.decided_by, x.winner_side) INTO got FROM match_result(K2) x;
    PERFORM _assert(got = 'tie,super_over,home', format('db/71 (pair): K2 reads %s', got));

    -- (provided) a super over the league's document does not provide: the
    -- tie stands, nobody is named, and the table does not move — points,
    -- wins, net run rate — by its runs or its balls
    PERFORM _as(U_OWNER);
    SELECT concat_ws(',', x.outcome, x.decided_by, coalesce(x.winner_side, '-'), jsonb_array_length(x.super_overs)) INTO got FROM match_result(L1) x;
    PERFORM _assert(got = 'tie,play,-,0', format('db/71 (provided): L1 reads %s', got));
    SELECT string_agg(concat_ws(',', s.team_code, s.played, s.won, s.lost, s.tied, s.points, round(s.nrr, 3), s.runs_for, s.balls_for), ' ' ORDER BY s.school_id)
      INTO t_after FROM competition_standing s WHERE s.competition_id = LG;
    PERFORM _assert(t_after = t_before AND t_after = '1XI,1,0,0,1,2,0.000,14,6 1XI,1,0,0,1,2,0.000,14,6',
      format('db/71 (provided): the league''s table read %s before the super over and %s after', t_before, t_after));

    -- (workload) the boy bowled the super overs: his day counts every ball
    -- (6 in K1, 6 in K2, 2 in K3, 6 in L1), and each is a spell of its own
    w_after := _load_71(P_NAID, DATE '2026-10-03');
    PERFORM _assert(w_after - w_before = 20, format('db/71 (workload): S Naidoo''s day went from %s to %s deliveries', w_before, w_after));
    SELECT string_agg(x.innings || ':' || x.spell_no || ':' || x.legal_balls, ' ' ORDER BY x.innings) INTO got
      FROM bowler_spell x WHERE x.match_id = K1 AND x.bowler_id = P_NAID;
    PERFORM _assert(got = '1:1:6 2:1:6', format('db/71 (workload): S Naidoo''s spells in K1 read %s', got));

    -- (board) the broadcast board on the super over's first ball: innings 2,
    -- one run, and no target — it chases nothing
    PERFORM _so_71(K5, 'k5');
    SELECT concat_ws(',', x.innings, x.runs, coalesce(x.target::text, '-')) INTO got FROM broadcast_state(K5) x;
    PERFORM _assert(got = '2,1,-', format('db/71 (board): the board on a super over''s first ball reads %s', got));

    -- (gate) completion once settled: a super over won (K1), a pair left
    -- incomplete (K3), the organiser's award (K4)
    UPDATE match SET status = 'complete' WHERE id IN (K1, K3);
    PERFORM _assert((SELECT count(*) FROM match WHERE id IN (K1, K3) AND status = 'complete') = 2,
      'db/71 (gate): a cup tie settled by its super over, or left incomplete, could not be completed');
    SELECT * INTO r FROM match_result_decide(K4, 'awarded', 'away', 'the cup''s rules: the higher seed goes through', false);
    PERFORM _assert(r.ok, format('db/71 (gate): the organiser''s award on K4 was refused: %s', r.reason));
    UPDATE match SET status = 'complete' WHERE id = K4;
    PERFORM _assert(EXISTS (SELECT 1 FROM match WHERE id = K4 AND status = 'complete'),
      'db/71 (gate): a cup tie the organiser awarded could not be completed');
    -- (scope) the new view runs as its reader; the new functions are not the application's
    PERFORM _assert(coalesce((SELECT 'security_invoker=true' = ANY (c.reloptions) FROM pg_class c WHERE c.oid = 'ball_event_career'::regclass), false)
                    AND NOT has_function_privilege('scrbrd_app', 'match_completion_refusal(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'innings_super_over_of(uuid,smallint)', 'EXECUTE'),
      'db/71 (scope): ball_event_career runs as its owner, or the application may call the gate''s functions');
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 51. Knockout progression (SCRBRD-114 phase 3c, db/72) ──
  -- _seed_72(): a Hilton cup, two semi-finals played (Hilton 1XI and
  -- Westville 2XI through), one never played, and the final between the
  -- two winners. The organiser (the owner here: every capability) records
  -- where each side came from, as the planner's publish does; then the
  -- semi-finals' results are corrected by each path that can change one —
  -- a decision, its withdrawal, a void appended to the log — before and
  -- after the final has a ball.
  --
  -- Each labelled assertion was falsified once — the function, trigger or
  -- view replaced in the database and this file run — and went red:
  --   (record)     match_progression_record() not checking the side is the winner
  --   (school)     match_progression_record() not asking the organiser's capability
  --   (reresolve)  progression_check() not amending an unplayed fixture's side
  --   (await)      progression_check() not flagging a side whose winner is gone
  --   (played)     progression_check() rewriting a played fixture
  --   (decision)   the decision trigger dropped
  --   (log)        the event trigger dropped
  --   (note)       progression_clear() taking a note under ten characters
  --   (clearer)    progression_clear() not asking the organiser's capability
  --   (ack)        progression_clear() not taking the result as it now is: an
  --                unrelated event flags the cleared side again
  --   (scope)      progression_conflict as its owner
  DECLARE
    ids    jsonb := _seed_72();
    C uuid; U1 uuid; U2 uuid; U3 uuid; D uuid;
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    r      record;
    v_ok   boolean;
    got    text;
    h1     text;
    dec    uuid;
  BEGIN
    C := (ids->>'c')::uuid; U1 := (ids->>'u1')::uuid; U2 := (ids->>'u2')::uuid; U3 := (ids->>'u3')::uuid; D := (ids->>'d')::uuid;

    -- (school) a school records no row, and writes none past the doors
    PERFORM _as(U_WES_ADM);
    SELECT * INTO r FROM match_progression_record(D, 'home', U1, 'winner', 'ko:r1:m1');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/72 (school): a school recorded where a side came from: %s', r.reason));
    BEGIN
      INSERT INTO match_progression (match_id, side, from_match_id, competition_id, created_by) VALUES (D, 'home', U1, C, U_WES_ADM);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/72 (school): the application wrote a progression row past the functions');

    -- (record) the organiser records each side, from its winner, with the hash
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM match_progression_record(D, 'away', U1, 'winner', 'ko:r1:m1');
    PERFORM _assert(NOT r.ok AND r.reason = 'side_mismatch', format('db/72 (record): a side that is not the winner was recorded: %s', coalesce(r.reason, 'ok')));
    SELECT * INTO r FROM match_progression_record(D, 'home', U3, 'winner', 'ko:r1:m3');
    PERFORM _assert(NOT r.ok AND r.reason = 'no_winner', format('db/72 (record): a side was recorded from a match with no winner: %s', coalesce(r.reason, 'ok')));
    SELECT * INTO r FROM match_progression_record(D, 'home', U1, 'winner', 'ko:r1:m1');
    PERFORM _assert(r.ok, format('db/72 (record): the home side was not recorded: %s', r.reason));
    SELECT * INTO r FROM match_progression_record(D, 'away', U2, 'winner', 'ko:r1:m2');
    PERFORM _assert(r.ok, format('db/72 (record): the away side was not recorded: %s', r.reason));
    SELECT result_hash INTO h1 FROM match_result(U1);
    PERFORM _assert((_row_72(D, 'home')).resolved_result_hash = h1 AND (_row_72(D, 'home')).resolved_school_id = HIL,
      'db/72 (record): the row does not hold the result it was resolved from');
    SELECT * INTO r FROM match_progression_record(D, 'home', U1, 'winner', 'ko:r1:m1');
    PERFORM _assert(r.ok AND r.detail = 'already', 'db/72 (record): a second publish of the same side was not idempotent');

    -- (reresolve) (decision) an award overriding U1's play: the unplayed final's
    -- home side becomes Westville 1XI, the row the new hash, both schools told
    SELECT * INTO r FROM match_result_decide(U1, 'awarded', 'away', 'protest upheld: an ineligible player in the Hilton side', true);
    PERFORM _assert(r.ok, format('db/72: the organiser''s award on U1 was refused: %s', r.reason));
    dec := r.decision_id;
    PERFORM _assert(_sides_72(D) = 'WES 1XI v WES 2XI', format('db/72 (reresolve): the final reads %s after U1 was awarded to Westville', _sides_72(D)));
    PERFORM _assert((_row_72(D, 'home')).resolved_result_hash = (SELECT result_hash FROM match_result(U1))
                    AND (_row_72(D, 'home')).resolved_school_id = WES AND (_row_72(D, 'home')).conflict_at IS NULL,
      'db/72 (reresolve): the row was not re-resolved to the new result');
    PERFORM _assert(_notices_72(D) = 3, format('db/72 (reresolve): %s knockout notice(s), not three (both schools, the organiser)', _notices_72(D)));
    SELECT * INTO r FROM match_result_decision_withdraw(dec, 'entered against the wrong semi-final');
    PERFORM _assert(r.ok AND _sides_72(D) = 'HIL 1XI v WES 2XI', format('db/72 (decision): withdrawing the award left the final as %s', _sides_72(D)));

    -- (await) (log) a void appended to U2's log takes its winning run away: no
    -- winner; the final keeps its side, flagged; the run again resolves it
    PERFORM _void_72(U2, 15);
    PERFORM _assert((_row_72(D, 'away')).resolved_school_id IS NULL AND (_row_72(D, 'away')).conflict_note LIKE 'awaiting a winner of %'
                    AND _sides_72(D) = 'HIL 1XI v WES 2XI',
      format('db/72 (await): with no winner of U2 the away row reads %s, the final %s', (_row_72(D, 'away')).conflict_note, _sides_72(D)));
    PERFORM _ev_71(U2, 1::smallint, 'ball', 'run', 1, NULL, NULL);
    PERFORM _assert((_row_72(D, 'away')).resolved_school_id = WES AND (_row_72(D, 'away')).conflict_at IS NULL,
      'db/72 (log): the winning run again did not resolve the away side again');

    -- (played) the final has begun: a correction to U1 now only flags it
    PERFORM _ev_71(D, 0::smallint, 'innings_start', NULL, NULL, NULL, jsonb_build_object('battingTeam', '1XI', 'bowlingTeam', 'Westville 2XI', 'overs', 1));
    SELECT * INTO r FROM match_result_decide(U1, 'awarded', 'away', 'protest upheld after the final began, on appeal', true);
    dec := r.decision_id;
    PERFORM _assert(_sides_72(D) = 'HIL 1XI v WES 2XI'
                    AND (_row_72(D, 'home')).conflict_note LIKE 'the result of % changed after this match was played',
      format('db/72 (played): the played final reads %s, its flag %s', _sides_72(D), (_row_72(D, 'home')).conflict_note));

    -- (scope) the flag on the bracket: the participants read it, nobody else
    PERFORM _as(U_WESC);
    SELECT count(*)::int INTO n FROM progression_conflict WHERE competition_id = C;
    PERFORM _assert(n = 1, format('db/72 (scope): Westville''s coach reads %s flag(s) on the cup''s bracket', n));
    PERFORM _as(U_SCOUT);
    SELECT count(*)::int INTO n FROM progression_conflict WHERE competition_id = C;
    PERFORM _assert(n = 0, format('db/72 (scope): a scout with no reach reads %s flag(s)', n));

    -- (clearer) (note) cleared by the organiser alone, with a note
    PERFORM _as(U_WES_ADM);
    SELECT * INTO r FROM progression_clear(D, 'home', 'Westville accept the result stands as played');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('db/72 (clearer): a school cleared a flag: %s', coalesce(r.reason, 'ok')));
    PERFORM _as(U_OWNER);
    SELECT * INTO r FROM progression_clear(D, 'home', 'ok');
    PERFORM _assert(NOT r.ok AND r.reason = 'note_required', format('db/72 (note): a flag cleared with "ok": %s', coalesce(r.reason, 'ok')));
    SELECT * INTO r FROM progression_clear(D, 'home', 'the final stands as played; Hilton 1XI keep the place');
    PERFORM _assert(r.ok, format('db/72 (note): the organiser could not clear the flag: %s', r.reason));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM progression_conflict WHERE competition_id = C), 'db/72: a cleared flag still stands');
    -- (ack) an event that changes nothing does not raise it again; a change does
    PERFORM _ev_71(U1, 1::smallint, 'batters', NULL, NULL, NULL, '{"striker":"W1","nonStriker":"W2"}');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM progression_conflict WHERE competition_id = C),
      'db/72 (ack): an event that changed no result flagged the cleared side again');
    SELECT * INTO r FROM match_result_decision_withdraw(dec, 'the appeal was itself withdrawn by Westville');
    PERFORM _assert(EXISTS (SELECT 1 FROM progression_conflict WHERE competition_id = C AND match_id = D AND side = 'home'),
      'db/72 (ack): a later change to the result did not flag the played final again');
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 52. Rain: interruptions, par and the deemed NRR (SCRBRD-130 R1, db/73) ──
  -- _seed_73(): the league "Verify 073 Rain" (dls_standard) and Hilton
  -- friendlies under the default method; every figure below worked by hand
  -- from the log. tools/smoke-fold-figures.mjs holds match_result() and
  -- innings_stop_as_folded() to the fold over rain-logs.mjs, so the rule and
  -- the fold cannot part.
  --
  -- Each labelled assertion was falsified once — the function replaced in
  -- the database and this file run — and went red:
  --   (par)       match_result_compute() reading a terminated chase as no
  --               result whatever the par (the 3a rule)
  --   (faced)     result.min_overs_per_side read from the chase's allotment,
  --               not its overs faced, on a terminated chase
  --   (method)    revised_target set without the frozen target.method (always
  --               umpires_revision)
  --   (deemed)    competition_standing_rows() reading the innings' own figures
  --               where match_result_compute() deemed others (D8)
  --   (stopped)   innings_stop_as_folded() not asking whether a seal closed the stop
  --   (public)    public_match_log() without the two kinds
  --   (super over) innings_par_as_folded() reading the match's last par
  --               whatever the innings (a super over then carried the chase's)
  DECLARE
    ids  jsonb := _seed_73();
    C    uuid;
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    got  text;
    j    jsonb;
  BEGIN
    C := (ids->>'c')::uuid;

    -- (par) a chase terminated with the umpires' par is decided on it, as the
    -- league reads it: L1 14/1 against a par of 18, Hilton by 4 runs; L2, cut
    -- to an over and a target of 10, 6/0: Hilton by 3; L3, no revision: B by 10 wickets.
    PERFORM _as(U_WESC);
    SELECT string_agg(x.label || '=' || concat_ws(',', r2.outcome, coalesce(r2.margin_kind, '-'), coalesce(r2.margin::text, '-'),
                      coalesce(r2.decided_by, '-'), coalesce(r2.winner_side, '-')), ' ' ORDER BY x.label) INTO got
      FROM competition_results(C) r2
      JOIN (VALUES ('l1', (ids->>'l1')::uuid), ('l2', (ids->>'l2')::uuid), ('l3', (ids->>'l3')::uuid)) AS x(label, m) ON x.m = r2.match_id;
    PERFORM _assert(got = 'l1=home_win,runs,4,play,home l2=home_win,runs,3,play,home l3=away_win,wickets,10,play,away',
      format('db/73 (par): the league''s results read %s', got));
    -- ...and the three outcomes and the no-par no result, on the friendlies:
    -- level (a tie), above (won by the runs ahead of par: db/121, Kameel's
    -- decision of 28 Oct 2026, the Laws audit F10), no par (no result)
    PERFORM _as(U_SARAH);
    SELECT string_agg(x.label || '=' || concat_ws(',', r2.outcome, coalesce(r2.margin_kind, '-'), coalesce(r2.margin::text, '-'),
                      coalesce(r2.winner_side, '-')), ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('f1', (ids->>'f1')::uuid), ('f2', (ids->>'f2')::uuid), ('f3', (ids->>'f3')::uuid),
                   ('f4', (ids->>'f4')::uuid), ('f5', (ids->>'f5')::uuid)) AS x(label, m), LATERAL match_result(x.m) r2;
    -- (faced) F4 is F2 under a document asking two overs a side: one over
    -- faced, so no result, though its allotment was two
    PERFORM _assert(got = 'f1=tie,-,-,- f2=away_win,runs,2,away f3=no_result,-,-,- f4=no_result,-,-,- f5=in_progress,-,-,-',
      format('db/73 (par, faced): the friendlies read %s', got));

    -- (method) the words' suffix: the chase names the method its revised
    -- target was set under (the league's dls_standard; the friendlies' default,
    -- the umpires' revision); a chase never revised names none
    SELECT string_agg(x.label || '=' || coalesce(r2.innings->1->>'revised_target', '-'), ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('f1', (ids->>'f1')::uuid), ('f3', (ids->>'f3')::uuid)) AS x(label, m), LATERAL match_result(x.m) r2;
    PERFORM _as(U_WESC);
    SELECT got || ' ' || string_agg(x.label || '=' || coalesce(r2.innings->1->>'revised_target', '-'), ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('l1', (ids->>'l1')::uuid), ('l2', (ids->>'l2')::uuid), ('l3', (ids->>'l3')::uuid)) AS x(label, m), LATERAL match_result(x.m) r2;
    PERFORM _assert(got = 'f1=umpires_revision f3=- l1=dls_standard l2=dls_standard l3=-',
      format('db/73 (method): the revised-target method reads %s', got));

    -- (deemed) net run rate to the ball (D8). Hilton for: L1 deemed 18 off
    -- the 9 balls the terminated chase faced, L2 deemed 9 (the target 10 less
    -- one) off the chase's allotted 6, L3 24 off 12 = 51/27; against: 14/9,
    -- 6/6, 25/7 = 45/22. Westville the mirror. Without D8 Hilton's would read
    -- 72/36. L3, never revised, carries no deemed figure.
    SELECT string_agg(s.display_name || '=' || concat_ws('/', s.runs_for, s.balls_for, s.runs_against, s.balls_against) || ',' || s.points,
                      ' ' ORDER BY s.display_name) INTO got
      FROM competition_standing s WHERE s.competition_id = C;
    PERFORM _assert(got = 'Verify 073 Hilton 1st XI=51/27/45/22,8 Verify 073 Westville 1st XI=45/22/51/27,4',
      format('db/73 (deemed): the table reads %s', got));
    PERFORM _assert((SELECT s.nrr FROM competition_standing s WHERE s.competition_id = C AND s.display_name = 'Verify 073 Hilton 1st XI')
                    = 51::numeric * 6 / 27 - 45::numeric * 6 / 22,
      'db/73 (deemed): Hilton''s net run rate is not 51 × 6 ÷ 27 less 45 × 6 ÷ 22');
    SELECT r2.innings INTO j FROM match_result((ids->>'l3')::uuid) r2;
    PERFORM _assert(NOT (j->0 ? 'nrr_runs') AND NOT (j->0 ? 'nrr_balls') AND NOT (j->1 ? 'revised_target'),
      format('db/73 (deemed): a match never revised carries deemed figures: %s', j));

    -- (stopped) inn.stopped and inn.par: F5's first innings stopped and not
    -- resumed; F1's terminated chase closed by its seal, its par 15; F3's no par
    PERFORM _as(U_SARAH);
    SELECT string_agg(x.label || '=' || concat_ws(',', s.stopped, coalesce(s.par::text, '-')), ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('f1', (ids->>'f1')::uuid, 1), ('f3', (ids->>'f3')::uuid, 1), ('f5', (ids->>'f5')::uuid, 0)) AS x(label, m, i),
           LATERAL innings_stop_as_folded(x.m, x.i::smallint) s;
    PERFORM _assert(got = 'f1=f,15 f3=f,- f5=t,-', format('db/73 (stopped): the stops read %s', got));
    SELECT r2.innings INTO j FROM match_result((ids->>'f5')::uuid) r2;
    PERFORM _assert((j->0->>'stopped')::boolean AND j->0->'par' = 'null'::jsonb,
      format('db/73 (stopped): the result''s innings do not carry the open stop: %s', j));

    -- (public) the signed-out log carries the stop, its reason and time,
    -- and the umpires' par — never the scorer's note
    PERFORM _publish_73((ids->>'f1')::uuid);
    SELECT string_agg(l.kind || ':' || l.detail::text, ' | ' ORDER BY l.seq) INTO got
      FROM public_match_log((ids->>'f1')::uuid, 0) l WHERE l.kind IN ('play_stopped', 'revision');
    PERFORM _assert(got = 'play_stopped:{"at": 1791622800000, "reason": "rain"} | revision:{"par": 15, "reason": "rain"}',
      format('db/73 (public): the signed-out log reads %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM public_match_log((ids->>'f1')::uuid, 0) l WHERE l.detail::text LIKE '%private note%'),
      'db/73 (public): a stop''s note reached the signed-out log');

    -- (careers) a stop and a resumption change no figure: the same six balls
    -- with and without them, ball for ball in the career view and in the
    -- handover's count (the completion gate reads the same)
    SELECT string_agg(concat_ws('/', p.player_id, p.runs, p.balls_faced, p.out), ' ' ORDER BY p.player_id) INTO got
      FROM player_innings p WHERE p.match_id = (ids->>'p')::uuid;
    PERFORM _assert(got IS NOT NULL AND got = (SELECT string_agg(concat_ws('/', p.player_id, p.runs, p.balls_faced, p.out), ' ' ORDER BY p.player_id)
                                                 FROM player_innings p WHERE p.match_id = (ids->>'w')::uuid),
      format('db/73 (careers): the career view moved with a stop: %s', got));
    PERFORM _assert((SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded((ids->>'p')::uuid, 0::smallint) f)
                    = (SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded((ids->>'w')::uuid, 0::smallint) f),
      'db/73 (careers): the handover''s count moved with a stop');

    -- (super over) rain never revises a super over (the Laws refuse a
    -- revision in one: super_over_no_revision, rain.test.mjs): SO's chase is
    -- level with the umpires' par, a tie (DLS), and its super over decides
    -- it — Hilton chasing 7 reach 8. The rain blocks read the match's own
    -- innings alone: the chase says dls_standard and the first innings is
    -- deemed 15 off the 9 balls faced; neither super-over innings carries a
    -- par, a stop, a revised target or a deemed figure.
    PERFORM _as(U_SARAH);
    SELECT concat_ws(',', r2.outcome, coalesce(r2.decided_by, '-'), coalesce(r2.winner_side, '-'), jsonb_array_length(r2.innings),
                     coalesce(r2.innings->1->>'revised_target', '-'), coalesce(r2.innings->0->>'nrr_runs', '-'), coalesce(r2.innings->0->>'nrr_balls', '-'),
                     (SELECT count(*) FROM jsonb_array_elements(r2.innings) y
                       WHERE y->'super_over' <> 'null'::jsonb
                         AND (y ? 'revised_target' OR y ? 'nrr_runs' OR y->'par' <> 'null'::jsonb OR (y->>'stopped')::boolean)))
      INTO got FROM match_result((ids->>'so')::uuid) r2;
    PERFORM _assert(got = 'tie,super_over,home,4,dls_standard,15,9,0',
      format('db/73 (super over): a DLS tie and its super over read %s', got));
  END;

  -- ── 53. Venue par (SCRBRD-130 R3, db/74) ──────────────────────────
  -- _seed_74(): a Hilton field with a pitch on it, five first innings that
  -- count and one excluded for each of §6.2's rules; every figure worked by
  -- hand. The JavaScript half (par at a point, the floor's pin) is
  -- packages/scoring/test/venue.test.mjs.
  --
  -- Each labelled assertion was falsified once — the function replaced in
  -- the database and this file run — and went red:
  --   (floor)     venue_par_min_innings() answering 4
  --   (revised)   the pool not asking for a revision of the overs
  --   (ended)     the pool taking an innings terminated (abandoned)
  --   (grain)     the pool not asking the allotment be the grain's overs
  --   (window)    three seasons back allowed into the window
  --   (pooled)    ground_root() answering the ground itself (no pooling)
  --   (guard)     venue_par() not asking facility.read at the ground's school
  DECLARE
    ids  jsonb := _seed_74();
    F    uuid;  P uuid;
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    got  text;
    v    record;
  BEGIN
    F := (ids->>'f')::uuid; P := (ids->>'p')::uuid;
    -- (floor) the constant, as venue.test.mjs pins it
    PERFORM _assert('venue_par.min_innings=' || venue_par_min_innings() = 'venue_par.min_innings=5',
      format('db/74 (floor): the floor is %s', venue_par_min_innings()));
    PERFORM _as(U_SARAH);
    SELECT * INTO v FROM venue_par(F, 20, 'U15', DATE '2026-10-31');
    -- (revised, ended, grain, window) exactly the five that count: 100, 120,
    -- 140 (on the pitch), 160 (2024), 150 (the book); the mean 134, median
    -- 140, range 100–160, seasons 2024–2026, one from a book
    SELECT string_agg(i->>'runs', ',' ORDER BY (i->>'date')) INTO got FROM jsonb_array_elements(v.innings) i;
    PERFORM _assert(got = '160,140,100,120,150',
      format('db/74 (revised, ended, grain, window): the pool reads %s', got));
    PERFORM _assert(v.n = 5 AND v.sufficient AND v.par = 134 AND v.median = 140 AND v.low = 100 AND v.high = 160
                    AND v.first_season = 2024 AND v.last_season = 2026 AND v.from_books = 1 AND v.floor = 5,
      format('db/74: the figure reads n %s par %s median %s range %s–%s seasons %s–%s books %s',
             v.n, v.par, v.median, v.low, v.high, v.first_season, v.last_season, v.from_books));
    -- (pooled) the pitch pools with its field, read from either; the
    -- breakdown names each ground with its own count and mean
    SELECT string_agg(b->>'name' || '=' || (b->>'n') || '/' || (b->>'mean'), ' ' ORDER BY b->>'name') INTO got FROM jsonb_array_elements(v.breakdown) b;
    PERFORM _assert(got = 'Verify 074 Field=4/133 Verify 074 Oval B=1/140' AND v.pooled_ground_id = F,
      format('db/74 (pooled): the breakdown reads %s', got));
    PERFORM _assert((SELECT w.par FROM venue_par(P, 20, 'U15', DATE '2026-10-31') w) = 134,
      'db/74 (pooled): the pitch does not read its field''s par');
    -- the floor: a year on, the 2024 innings ages out — four, insufficient, no par
    SELECT * INTO v FROM venue_par(F, 20, 'U15', DATE '2027-10-31');
    PERFORM _assert(v.n = 4 AND NOT v.sufficient AND v.par IS NULL,
      format('db/74 (floor): four innings read n %s sufficient %s par %s', v.n, v.sufficient, v.par));
    -- another band, another ground: their own pools
    PERFORM _assert((SELECT w.n FROM venue_par(F, 20, 'U14', DATE '2026-10-31') w) = 1
                    AND (SELECT w.n FROM venue_par((ids->>'x')::uuid, 20, 'U15', DATE '2026-10-31') w) = 1
                    AND (SELECT w.n FROM venue_par(F, 50, 'U15', DATE '2026-10-31') w) = 1,
      'db/74 (grain): a band, a ground or an allotment pooled with another');
    -- (guard) a Westville coach reads no Hilton ground's par …
    PERFORM _as(U_WESC);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM venue_par(F, 20, 'U15', DATE '2026-10-31')),
      'db/74 (guard): a reader with no facility.read at the ground''s school read its par');
    -- … but reads the par of the ground his own fixture is played on, at its
    -- overs and band, as its board does
    SELECT * INTO v FROM venue_par_for_match((ids->>'m2')::uuid, DATE '2026-10-31');
    PERFORM _assert(v.par = 134 AND v.overs = 20 AND v.age_band = 'U15',
      format('db/74: the visitors'' coach reads his fixture''s ground at par %s, %s overs, %s', v.par, v.overs, v.age_band));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM venue_par_for_match((ids->>'mx')::uuid, DATE '2026-10-31')),
      'db/74 (guard): a reader of no fixture read its ground''s par');
    -- the pool and the figure are the owner's: the application cannot call them
    PERFORM _assert(NOT has_function_privilege('venue_par_pool(uuid,integer,date)', 'EXECUTE')
                    AND NOT has_function_privilege('venue_par_compute(uuid,integer,text,date)', 'EXECUTE'),
      'db/74: the application may read the pool past the readers'' guards');
  END;

  -- ── 54. The DLS table: loading, publishing, freezing (SCRBRD-130 R2, db/75) ──
  -- Every cell here is the synthetic generator's (_synth_75), never a value
  -- of the published table (D5). The JavaScript half — the calculator, its
  -- six cases worked by hand, the D5 grep — is packages/scoring/test/dls.test.mjs.
  --
  -- Each labelled assertion was falsified once — the function replaced in
  -- the database and this file run — and went red:
  --   (operator)  dls_operator() answering true for anyone signed in
  --   (structure) dls_table_problems() without its not_falling_in_wickets check
  --   (synthetic) dls_table_publish() not refusing a SYNTHETIC title
  --   (published) dls_resource_guard() letting a published table's cell move
  --   (withdrawn) dls_table_guard() letting a published table be deleted
  --   (frozen)    the resolver's block reading a draft table, not a published one
  --   (platform)  condition_platform_key_guard() letting the key through
  --   (guard)     dls_table_for_match() not asking match_result_readable()
  DECLARE
    ids  jsonb := _seed_75();
    U_WESC uuid := '88888888-0000-0000-0000-00000000001a';   -- S Pillay, coach, Westville 1XI
    BALL uuid; OVR uuid; PUB uuid;
    got  text;
    v    record;
    j    jsonb;
    v_ok boolean;
  BEGIN
    -- (operator) platform.reference.manage, held through no school: a school's
    -- director loads, publishes, withdraws and lists nothing
    PERFORM _as(U_SARAH);
    SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075 by a director', 901, 'over'), _synth_75('over'));
    PERFORM _assert(NOT v.ok AND v.reason = 'not_permitted', format('db/75 (operator): a school''s director loaded a table: %s', v.reason));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM dls_tables()), 'db/75 (operator): a school''s director lists the tables');
    PERFORM _assert(NOT dls_operator() AND NOT app_can('platform.reference.manage', HIL),
      'db/75 (operator): a school''s director holds platform.reference.manage');

    -- a platform administrator inside a support session (§ support: U_PLAT's
    -- is still open here) acts for a school, not for the platform: refused
    PERFORM _as(U_PLAT);
    IF app_support_access_id() IS NOT NULL THEN
      SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075 in support', 901, 'over'), _synth_75('over'));
      PERFORM _assert(NOT v.ok AND v.reason = 'not_permitted', format('db/75 (operator): a support session loaded a table: %s', v.reason));
    END IF;

    -- the synthetic table loads at both grains, hashed as dls.test.mjs pins it;
    -- the owner (superadmin) as the operator
    PERFORM _as(U_OWNER);
    SELECT * INTO v FROM dls_table_load(_meta_75('SYNTHETIC — tests only', 901, 'ball'), _synth_75('ball'));
    PERFORM _assert(v.ok AND v.row_count = 3010 AND v.content_hash = '0847f8f488da304bddc426b9d0d50febfac43e6461fc7016b365da151b1dfa47',
      format('db/75: the synthetic table by the ball loaded %s, %s cells, hash %s', v.reason, v.row_count, v.content_hash));
    BALL := v.table_id;
    SELECT * INTO v FROM dls_table_load(_meta_75('SYNTHETIC — tests only', 902, 'over'), _synth_75('over'));
    PERFORM _assert(v.ok AND v.row_count = 510 AND v.content_hash = '95766fbf157ef9908c29ab997d53807a2bdaa9eedca81ed7367db0a5d8afc564',
      format('db/75: the synthetic table by the over loaded %s, %s cells, hash %s', v.reason, v.row_count, v.content_hash));
    OVR := v.table_id;
    SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075 again', 902, 'over'), _synth_75('over'));
    PERFORM _assert(NOT v.ok AND v.reason = 'version_taken', format('db/75: a version loaded twice: %s', v.reason));
    -- the provenance and the permission are not optional
    SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075', 903, 'over') - 'sourceDocument', _synth_75('over'));
    PERFORM _assert(NOT v.ok AND v.reason = 'provenance_required', format('db/75: a table with no source loaded: %s', v.reason));
    SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075', 903, 'over') || '{"permissionNote": "yes"}', _synth_75('over'));
    PERFORM _assert(NOT v.ok AND v.reason = 'permission_note_required', format('db/75: a table with no permission loaded: %s', v.reason));

    -- (structure) each check refuses, alone: one cell moved at a time
    SELECT string_agg(x.label || '=' || coalesce(array_to_string(r.problems, '+'), r.reason), ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('a_grain', 'inning', '{}'::jsonb), ('b_missing', 'over', '{"6,3": null}'), ('c_range', 'over', '{"6,0": 19.5}'),
                   ('d_end', 'over', '{"0,0": 1}'), ('e_start', 'over', '{"300,0": 999}'), ('f_balls', 'over', '{"12,9": 1}'),
                   ('g_wickets', 'over', '{"6,1": 21}')) AS x(label, grain, patch),
           LATERAL dls_table_load(_meta_75('Verify 075 broken', 904, x.grain), _synth_75('over', x.patch)) r;
    PERFORM _assert(got = 'a_grain=grain b_missing=missing_cell c_range=out_of_range d_end=not_zero_at_end e_start=not_full_at_start '
                       || 'f_balls=not_rising_in_balls g_wickets=not_falling_in_wickets',
      format('db/75 (structure): the checks read %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM dls_tables() t WHERE t.version = 904), 'db/75 (structure): a broken table was kept');

    -- (synthetic) the tests' table is never published
    SELECT * INTO v FROM dls_table_publish(BALL);
    PERFORM _assert(NOT v.ok AND v.reason = 'synthetic_title', format('db/75 (synthetic): the synthetic table published: %s', v.reason));

    -- (frozen) a match fixed with no table published names none, for ever
    j := _freeze_75((ids->>'m0')::uuid);
    PERFORM _assert(NOT (j->'doc'->'play' ? 'target.dls_table') AND j->'sources'->'target.dls_table'->>'from' = 'platform_default',
      format('db/75 (frozen): a match fixed with no table published named %s', j->'doc'->'play'->'target.dls_table'));

    -- a table under the test's own title (still the generator's cells) publishes
    SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075 rehearsal table', 905, 'over'), _synth_75('over'));
    PUB := v.table_id;
    SELECT * INTO v FROM dls_table_publish(PUB);
    PERFORM _assert(v.ok, format('db/75: the rehearsal table did not publish: %s %s', v.reason, v.detail));
    SELECT * INTO v FROM dls_table_publish(PUB);
    PERFORM _assert(NOT v.ok AND v.reason = 'not_draft', format('db/75: a table published twice: %s', v.reason));
    -- the listing carries provenance and never a cell
    SELECT string_agg(t.version || ':' || t.status, ' ' ORDER BY t.version) INTO got FROM dls_tables() t WHERE t.version >= 901;
    PERFORM _assert(got = '901:draft 902:draft 905:published', format('db/75: the operator lists %s', got));

    -- (frozen) a match fixed now names it, from the platform
    j := _freeze_75((ids->>'m1')::uuid);
    PERFORM _assert(j->'doc'->'play'->'target.dls_table' = jsonb_build_object('id', PUB, 'version', 905,
                      'hash', '95766fbf157ef9908c29ab997d53807a2bdaa9eedca81ed7367db0a5d8afc564')
                    AND j->'sources'->'target.dls_table' = '{"from": "platform", "status": "confirmed"}',
      format('db/75 (frozen): the document reads %s from %s', j->'doc'->'play'->'target.dls_table', j->'sources'->'target.dls_table'));

    -- (published) a published table never changes: not a cell, not its
    -- title, not deleted, not a cell added — even by the owner
    SELECT string_agg(_try_75(x.s), ' ' ORDER BY x.i) INTO got FROM (VALUES
      (1, format('UPDATE dls_resource SET resource_tenths = resource_tenths WHERE table_id = %L AND balls_remaining = 6', PUB)),
      (2, format('DELETE FROM dls_resource WHERE table_id = %L AND balls_remaining = 6', PUB)),
      (3, format('INSERT INTO dls_resource SELECT %L, 1, w, 0 FROM generate_series(0, 9) w', PUB)),
      (4, format('UPDATE dls_resource_table SET title = %L WHERE id = %L', 'Verify 075 renamed', PUB)),
      (5, format('UPDATE dls_resource_table SET status = %L WHERE id = %L', 'draft', PUB))) AS x(i, s);
    PERFORM _assert(got = 'dls_resource_published_immutable dls_resource_published_immutable dls_resource_published_immutable '
                       || 'dls_table_published_immutable dls_table_published_immutable',
      format('db/75 (published): writes to a published table read %s', got));

    -- (withdrawn) withdrawal says why, keeps every row, and the match that
    -- named it still reads it, "since withdrawn"
    SELECT * INTO v FROM dls_table_withdraw(PUB, 'short');
    PERFORM _assert(NOT v.ok AND v.reason = 'note_required', format('db/75 (withdrawn): withdrawn without a reason: %s', v.reason));
    SELECT * INTO v FROM dls_table_withdraw(PUB, 'Verify 075: superseded in the rehearsal');
    PERFORM _assert(v.ok, format('db/75 (withdrawn): the table did not withdraw: %s', v.reason));
    PERFORM _assert(_try_75(format('DELETE FROM dls_resource_table WHERE id = %L', PUB)) = 'dls_table_kept'
                    AND _try_75(format('UPDATE dls_resource_table SET status = %L, withdrawn_note = NULL WHERE id = %L', 'published', PUB))
                        = 'dls_table_published_immutable',
      'db/75 (withdrawn): a withdrawn table was deleted or brought back');
    PERFORM _as(U_SARAH);
    SELECT * INTO v FROM dls_table_for_match((ids->>'m1')::uuid);
    PERFORM _assert(v.id = PUB AND v.status = 'withdrawn' AND NOT v.current AND jsonb_array_length(v.cells) = 510,
      format('db/75 (withdrawn): the fixed match reads table %s, %s, %s cells', v.version, v.status, jsonb_array_length(v.cells)));
    -- the match fixed with none reads no table now none is published
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM dls_table_for_match((ids->>'m0')::uuid)),
      'db/75: a match fixed with no table read a withdrawn one');
    -- a later version moves no earlier match: M1 still reads the one it was
    -- fixed under; M0, fixed under none, reads the current one and says so
    PERFORM _as(U_OWNER);
    SELECT * INTO v FROM dls_table_load(_meta_75('Verify 075 rehearsal table, corrected', 906, 'over'), _synth_75('over'));
    SELECT * INTO v FROM dls_table_publish(v.table_id);
    PERFORM _as(U_SARAH);
    SELECT string_agg(x.label || '=' || t.version || ',' || t.status || ',' || t.current, ' ' ORDER BY x.label) INTO got
      FROM (VALUES ('m0', (ids->>'m0')::uuid), ('m1', (ids->>'m1')::uuid)) AS x(label, m), LATERAL dls_table_for_match(x.m) t;
    PERFORM _assert(v.ok AND got = 'm0=906,published,true m1=905,withdrawn,false',
      format('db/75 (frozen): after version 906 the matches read %s', got));

    -- (guard) the cells go only to a reader of the match's result: a
    -- Westville coach reads nothing of a Hilton friendly's
    PERFORM _as(U_WESC);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM dls_table_for_match((ids->>'m1')::uuid)),
      'db/75 (guard): a reader of no result read the table''s cells');

    -- (platform) a competition's version or a fixture's departure never names the table
    got := _try_75(format('INSERT INTO condition_value (set_id, key, value, status, source_document, source_clause, source_date, entered_by) '
                          'VALUES (%L, %L, %L, %L, %L, %L, %L, %L)', ids->>'v', 'target.dls_table', jsonb_build_object('id', PUB), 'confirmed',
                          'Verify 075 league rules', '9.9', '2026-10-01', U_OWNER))
        || ' ' || _try_75(format('INSERT INTO match_condition_override (match_id, key, value, reason, set_by) VALUES (%L, %L, %L, %L, %L)',
                          ids->>'m2', 'target.dls_table', jsonb_build_object('id', PUB), 'Verify 075: a league''s own table', U_OWNER));
    PERFORM _assert(got = 'condition_platform_key condition_platform_key', format('db/75 (platform): naming the table read %s', got));

    -- the application reads no table directly, and calls nothing of the owner's
    BEGIN
      PERFORM 1 FROM dls_resource LIMIT 1;
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/75: the application selected a resource cell');
    PERFORM _assert(NOT has_table_privilege('dls_resource_table', 'SELECT') AND NOT has_table_privilege('dls_resource', 'SELECT')
                    AND NOT has_function_privilege('dls_table_problems(text,integer,jsonb)', 'EXECUTE')
                    AND NOT has_function_privilege('dls_canonical_text(uuid)', 'EXECUTE'),
      'db/75: the application may read a DLS table past the functions');
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 55. Parent lift clubs, phase 2: the day (SCRBRD-124, db/76) ──────
  -- docs/design/SCRBRD-124_lift_clubs.md §8's phase 2 row, with principals:
  -- the marks go forward only, each once, on the day, by the driver alone (a
  -- revoked guardian is refused on an offer that still names her); the out
  -- leg's receiver is the side's coach and a guardian is refused there, the
  -- back leg's a guardian (or the boy himself at eighteen) and the coach is
  -- refused there; not collected tells every live guardian and the office,
  -- naming nobody, and the lift is not done until he is received or
  -- resolved; the watch alerts once per seat and only for the platform's
  -- key; the office reads the exceptions by name, logged, and resolves; the
  -- coach reads his expected list, logged, and nobody else does; my_lifts()
  -- gives the boy of eighteen at school his own lift with no number and a
  -- pupil of seventeen nothing; a lift on the road is seen through (a
  -- withdrawal, a fixture moved, a link ended and a cancel each leave it);
  -- the purge deletes what is due, refuses what is not, and leaves counts
  -- naming nobody; and the zeros. _seed_76() builds its own world.
  -- tools/smoke-lifts.mjs walks the same through the API.
  --
  -- Each labelled assertion was falsified once — the guard broken (as the
  -- owner, inside this file's own transaction, before the section ran) —
  -- and went red, and was green again restored. 65 breaks: 60 red at their
  -- own assertion, four red at a second layer (marked "layer"), one single
  -- layer that held alone as designed (marked "held"):
  --   (zero)       lift_mark()'s and lift_seat_mark()'s driver test
  --   (day)        the day window; (forward) a second "left", a second "in",
  --                a handover before leaving, a second handover, received
  --                twice, resolved twice; arrived before leaving (layer: the
  --                table's arrives_after_departing check)
  --   (road)       departing while the lift waits on its driver; the row
  --                guard dropped; lift_offer_end() ending a lift on the road
  --                (layer: the row guard; with the guard dropped and its own
  --                test blinded, red at (revoked)); a fixture move
  --                re-versioning it, the lone boy in the car falling back, a
  --                boy in the car voided when the link ends (each with the
  --                guard dropped); cancel on the road; edit on the road
  --                (layer: the row guard; with it dropped, red at its word)
  --   (depart)     requests not declined; the offer not closed
  --   (not-boarded) the family not told
  --   (board)      a seat only asked for marked in
  --   (not-collected) the family not told; the office not told; the
  --                office's notice behind arrange (the office could not read it)
  --   (receive-out), (receive-back)  anybody at the ground; anybody at home;
  --                not collected then received left unresolved
  --   (done)       done on arrival whoever was received; not asked after a receipt
  --   (resolve)    oversee swapped for fixture.read; any word (layer: the
  --                table's resolution check); before the meeting time; a lift
  --                under way made to wait for its meeting time
  --   (expected)   receive swapped for fixture.read; the log dropped; a boy in
  --                the car not expected once his link ended (lift_day_status())
  --   (exceptions) oversee swapped for news.read; the log dropped; not
  --                collected dropped; not boarded dropped
  --   (my-day)     the driver's names not logged; any guardian at the school;
  --                off the day; the cuts (held: each branch asks its own)
  --   (mine)       any pupil's own seat (Tom, seventeen, read his)
  --   (watch)      anybody runs it; not left alerted again; a handover
  --                alerted after a not-left alert (once per seat, D14); the
  --                side's staff not told; the driver told per seat; staff of
  --                any side (the U17B's coach told)
  --   (purge)      oversee swapped for news.read; before the date; no row of
  --                counts; due at two years; a declaration before its year
  --   (told)       Kameel, 2026-10-01 ("this isn't an airline with assigned
  --                seats"): an ordinary notice to every guardian (Lou's father
  --                and Max's told of seats they did not ask for); a seat on his
  --                own say told to nobody (Ole); the withdrawal not told to
  --                the asker; the day's alerts to the asker only (Lou's father,
  --                in the car alone, not told: (road)); not collected sent as
  --                an ordinary notice (Max's father not told)
  --   (privacy)    the boy's name in the not-collected notice
  DECLARE
    ids      jsonb := _seed_76();
    MT uuid; MU uuid; MW uuid; MX uuid; MF uuid; MP uuid; MQ uuid;
    P_KAI uuid; P_LOU uuid; P_MAX uuid; P_NED uuid; P_PIP uuid; P_OLE uuid; P_TOM uuid; P_REX uuid;
    U_DMUM uuid; U_LMUM uuid; U_LDAD uuid; U_MMUM uuid; U_MDAD uuid; S_MAX_F uuid; U_NMUM uuid; U_PMUM uuid; U_OMUM uuid; U_TMUM uuid;
    U_RMUM uuid; U_WMUM uuid; U_OLE uuid; U_TOM uuid; U_CO uuid; U_BCO uuid; U_OFF uuid; U_TCO uuid; U_HD uuid;
    C_KAI uuid;
    O_OUT uuid; O_BACK uuid; O_W uuid; O_X uuid; O_F uuid; O_U uuid; O_P uuid; O_Q uuid;
    D_OLD uuid; D_NEW uuid;
    S_LOU_OUT uuid; S_MAX_OUT uuid; S_NED_OUT uuid; S_LOU_BACK uuid; S_MAX_BACK uuid; S_OLE_BACK uuid;
    S_NED_W uuid; S_PIP_W uuid; S_TOM_W uuid; S_LOU_X uuid; S_MAX_X uuid; S_LOU_U uuid; S_MAX_U uuid;
    v_ok     boolean;
    v_reason text;
    v_id     uuid;
    v_ver    integer;
    v_t      timestamptz;
    j        jsonb;
    got      text;
    k        bigint;
    k2       bigint;
    who      uuid;
    BODY     text := 'Lifts to fixtures are arranged between families. The school facilitates and does not operate '
                  || 'lifts: it does not inspect or insure cars. A driver undertakes that she holds a licence, that '
                  || 'the car is insured and roadworthy, and that every boy wears a belt. If a boy is not collected, '
                  || 'stay with him and ring the school office. A concern goes to the DSO.';
  BEGIN
    MT := (ids->>'mt')::uuid; MU := (ids->>'mu')::uuid; MW := (ids->>'mw')::uuid; MX := (ids->>'mx')::uuid;
    MF := (ids->>'mf')::uuid; MP := (ids->>'mp')::uuid; MQ := (ids->>'mq')::uuid;
    P_KAI := (ids->>'p_kai')::uuid; P_LOU := (ids->>'p_lou')::uuid; P_MAX := (ids->>'p_max')::uuid;
    P_NED := (ids->>'p_ned')::uuid; P_PIP := (ids->>'p_pip')::uuid; P_OLE := (ids->>'p_ole')::uuid;
    P_TOM := (ids->>'p_tom')::uuid; P_REX := (ids->>'p_rex')::uuid;
    U_DMUM := (ids->>'u_dmum')::uuid; U_LMUM := (ids->>'u_lmum')::uuid; U_LDAD := (ids->>'u_ldad')::uuid;
    U_MMUM := (ids->>'u_mmum')::uuid; U_MDAD := (ids->>'u_mdad')::uuid; U_NMUM := (ids->>'u_nmum')::uuid; U_PMUM := (ids->>'u_pmum')::uuid;
    U_OMUM := (ids->>'u_omum')::uuid; U_TMUM := (ids->>'u_tmum')::uuid; U_RMUM := (ids->>'u_rmum')::uuid;
    U_WMUM := (ids->>'u_wmum')::uuid; U_OLE := (ids->>'u_ole')::uuid; U_TOM := (ids->>'u_tom')::uuid;
    U_CO := (ids->>'u_coach')::uuid; U_BCO := (ids->>'u_bcoach')::uuid; U_OFF := (ids->>'u_office')::uuid;
    U_TCO := (ids->>'u_tco')::uuid; U_HD := (ids->>'u_head')::uuid;
    C_KAI := (ids->>'c_kai')::uuid;
    PERFORM _v76_fire();

    -- The arrangement, as phase 1 makes it (db/70; §48 is its proof): the
    -- platform grants, the principal signs a policy refusing one boy alone
    -- with a driver not his parent, the driver declares and offers.
    PERFORM _v76_grant(HIL, true);
    PERFORM _as(U_HD);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_policy_sign(HIL, BODY, false, false, 'the Chapel car park');
    PERFORM _assert(v_ok, format('db/76 (setup): the principal could not sign: %s', v_reason));
    PERFORM _as(U_DMUM);
    SELECT ok, reason, declaration_id INTO v_ok, v_reason, D_NEW
      FROM lift_driver_declare(HIL, 'silver Toyota Fortuner', 'ND 760 760', 4, true, true, true, true, true, C_KAI);
    PERFORM _assert(v_ok, format('db/76 (setup): the driver could not declare: %s', v_reason));
    SELECT offer_id INTO O_OUT  FROM lift_offer_create(MT, 'out',  3, 'school', (ids->>'mt_start')::timestamptz - interval '90 minutes', NULL);
    SELECT offer_id INTO O_BACK FROM lift_offer_create(MT, 'back', 4, 'ground', (ids->>'mt_start')::timestamptz + interval '5 hours', NULL);
    SELECT offer_id INTO O_W    FROM lift_offer_create(MW, 'out',  3, 'school', (ids->>'mw_start')::timestamptz - interval '60 minutes', NULL);
    SELECT offer_id INTO O_X    FROM lift_offer_create(MX, 'out',  2, 'school', (ids->>'mx_start')::timestamptz - interval '60 minutes', NULL);
    SELECT offer_id INTO O_U    FROM lift_offer_create(MU, 'out',  2, 'school', (ids->>'mu_start')::timestamptz - interval '60 minutes', NULL);
    SELECT offer_id INTO O_F    FROM lift_offer_create(MF, 'out',  2, 'school', (ids->>'mf_start')::timestamptz - interval '60 minutes', NULL);
    PERFORM _assert(O_OUT IS NOT NULL AND O_BACK IS NOT NULL AND O_W IS NOT NULL AND O_X IS NOT NULL AND O_U IS NOT NULL
                    AND O_F IS NOT NULL, 'db/76 (setup): the driver''s six lifts were not all offered');
    PERFORM _as(U_LMUM);
    SELECT seat_id INTO S_LOU_OUT  FROM lift_seat_request(O_OUT, P_LOU);
    SELECT seat_id INTO S_LOU_BACK FROM lift_seat_request(O_BACK, P_LOU);
    -- His father asks for the evening's and noon's lifts.
    PERFORM _as(U_LDAD);
    SELECT seat_id INTO S_LOU_X    FROM lift_seat_request(O_X, P_LOU);
    SELECT seat_id INTO S_LOU_U    FROM lift_seat_request(O_U, P_LOU);
    PERFORM _as(U_MMUM);
    SELECT seat_id INTO S_MAX_OUT  FROM lift_seat_request(O_OUT, P_MAX);
    SELECT seat_id INTO S_MAX_BACK FROM lift_seat_request(O_BACK, P_MAX);
    SELECT seat_id INTO S_MAX_X    FROM lift_seat_request(O_X, P_MAX);
    SELECT seat_id INTO S_MAX_U    FROM lift_seat_request(O_U, P_MAX);
    PERFORM _as(U_NMUM);
    SELECT seat_id INTO S_NED_OUT  FROM lift_seat_request(O_OUT, P_NED);
    SELECT seat_id INTO S_NED_W    FROM lift_seat_request(O_W, P_NED);
    PERFORM _as(U_PMUM);
    SELECT seat_id INTO S_PIP_W    FROM lift_seat_request(O_W, P_PIP);
    PERFORM _as(U_TMUM);
    SELECT seat_id INTO S_TOM_W    FROM lift_seat_request(O_W, P_TOM);
    PERFORM _as(U_OLE);
    SELECT seat_id INTO S_OLE_BACK FROM lift_seat_request(O_BACK, P_OLE);
    PERFORM _as(U_DMUM);
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_LOU_OUT, S_MAX_OUT]);
    PERFORM _assert(v_ok, 'db/76 (setup): the way there was not accepted');
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_LOU_BACK, S_MAX_BACK, S_OLE_BACK]);
    PERFORM _assert(v_ok, 'db/76 (setup): the way home was not accepted');
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_NED_W, S_PIP_W, S_TOM_W]);
    PERFORM _assert(v_ok, 'db/76 (setup): the afternoon''s lift was not accepted');
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_LOU_X, S_MAX_X]);
    PERFORM _assert(v_ok, 'db/76 (setup): the evening''s lift was not accepted');
    SELECT ok INTO v_ok FROM lift_seat_accept(ARRAY[S_LOU_U, S_MAX_U]);
    PERFORM _assert(v_ok, 'db/76 (setup): the noon lift was not accepted');
    -- (told) "this isn't an airline with assigned seats" (Kameel, 2026-10-01):
    -- a confirmed seat is told to the parent who asked for it and no other
    -- guardian — Lou's mother for the morning, his father for the evening,
    -- Max's mother and never his father; Ole's own seat to Ole, not his mother
    PERFORM _assert(_v76_told_on(U_LMUM, 'A seat on a lift is confirmed', MT) = 2 AND _v76_told_on(U_LDAD, 'A seat on a lift is confirmed', MT) = 0
                    AND _v76_told_on(U_LDAD, 'A seat on a lift is confirmed', MX) = 1 AND _v76_told_on(U_LMUM, 'A seat on a lift is confirmed', MX) = 0
                    AND _v76_told(U_MMUM, 'A seat on a lift is confirmed') = 4 AND _v76_told(U_MDAD, 'A seat on a lift is confirmed') = 0
                    AND _v76_told(U_OLE, 'A seat on a lift is confirmed') = 1 AND _v76_told(U_OMUM, 'A seat on a lift is confirmed') = 0,
      format('db/76 (told): confirmed: Lou''s mother %s/%s, his father %s/%s; Max''s mother %s, father %s; Ole %s, his mother %s',
             _v76_told_on(U_LMUM, 'A seat on a lift is confirmed', MT), _v76_told_on(U_LMUM, 'A seat on a lift is confirmed', MX),
             _v76_told_on(U_LDAD, 'A seat on a lift is confirmed', MT), _v76_told_on(U_LDAD, 'A seat on a lift is confirmed', MX),
             _v76_told(U_MMUM, 'A seat on a lift is confirmed'), _v76_told(U_MDAD, 'A seat on a lift is confirmed'),
             _v76_told(U_OLE, 'A seat on a lift is confirmed'), _v76_told(U_OMUM, 'A seat on a lift is confirmed')));
    -- ...and a seat withdrawn by his other parent is told to the one who asked
    PERFORM _as(U_MMUM);
    SELECT seat_id INTO S_MAX_F FROM lift_seat_request(O_F, P_MAX);
    PERFORM _as(U_MDAD);
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_MAX_F);
    PERFORM _assert(v_ok AND _v76_told(U_MMUM, 'A seat you asked for was withdrawn') = 1
                    AND _v76_told(U_MDAD, 'A seat you asked for was withdrawn') = 0,
      format('db/76 (told): Max''s father withdrew his mother''s seat (%s); she was told %s, he %s', v_ok,
             _v76_told(U_MMUM, 'A seat you asked for was withdrawn'), _v76_told(U_MDAD, 'A seat you asked for was withdrawn')));
    PERFORM _assert(_v76_status(S_NED_OUT) = 'requested' AND _v76_status(S_LOU_OUT) = 'confirmed'
                    AND _v76_status(S_OLE_BACK) = 'confirmed' AND _v76_status(S_TOM_W) = 'confirmed',
      format('db/76 (setup): seats read %s %s %s %s', _v76_status(S_NED_OUT), _v76_status(S_LOU_OUT),
             _v76_status(S_OLE_BACK), _v76_status(S_TOM_W)));

    -- (zero) nobody but the driver marks: a guardian on the lift, a parent at
    -- another school, the coach, the office, the transport coordinator, the
    -- principal, the owner's key, a platform administrator, a pupil of
    -- seventeen, the boy of eighteen on the lift; nothing changes
    FOREACH who IN ARRAY ARRAY[U_LMUM, U_WMUM, U_CO, U_OFF, U_TCO, U_HD, U_OWNER, U_PLAT, U_TOM, U_OLE] LOOP
      PERFORM _as(who);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'departed');
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (zero): %s marked the lift as left: %s', who, v_reason));
      SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_LOU_OUT, 'boarded');
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (zero): %s marked Lou in the car: %s', who, v_reason));
    END LOOP;
    PERFORM _assert((_v76_offer(O_OUT)).departed_at IS NULL AND (_v76_seat(S_LOU_OUT)).boarded_at IS NULL,
      'db/76 (zero): a refused mark left a time behind');
    -- ...nor under a support session at the school, nor her own pad credential
    PERFORM _as(U_PLAT);
    SELECT ok, reason, id INTO v_ok, v_reason, v_id FROM support_access_begin(HIL, 'transportcoordinator', 'ticket v76: the day');
    PERFORM _assert(v_ok, format('db/76 (zero): no support session to test with: %s', v_reason));
    SELECT ok INTO v_ok FROM lift_resolve(S_LOU_OUT, 'other');
    SELECT count(*) INTO k FROM lift_exceptions(HIL);
    PERFORM _assert(NOT v_ok AND k = 0, format('db/76 (zero): a support session resolved (%s) or read %s exception(s)', v_ok, k));
    PERFORM support_access_end(v_id);
    PERFORM _as(U_DMUM);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', MT::text, true);
    SELECT ok INTO v_ok FROM lift_mark(O_OUT, 'departed');
    SELECT jsonb_array_length(lift_my_day(MT)) INTO k;
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(NOT v_ok AND k = 0, format('db/76 (zero): the driver''s pad credential marked (%s) or read %s day card(s)', v_ok, k));

    -- (day) marks are on the day only, and only the words they are
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_F, 'departed');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_the_day', format('db/76 (day): a lift ten days out was marked as left: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'flew');
    PERFORM _assert(NOT v_ok AND v_reason = 'unknown_event', format('db/76 (day): an unknown mark: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'arrived');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_departed', format('db/76 (forward): arrived before leaving: %s', v_reason));

    -- (board) a boy in: once, confirmed seats only; no handover before the car leaves
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_LOU_OUT, 'boarded');
    PERFORM _assert(v_ok AND (_v76_seat(S_LOU_OUT)).boarded_at IS NOT NULL, format('db/76 (board): Lou was not marked in: %s', v_reason));
    v_t := (_v76_seat(S_LOU_OUT)).boarded_at;
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_LOU_OUT, 'boarded');
    PERFORM _assert(NOT v_ok AND v_reason = 'already_marked' AND (_v76_seat(S_LOU_OUT)).boarded_at = v_t,
      format('db/76 (forward): Lou was marked in twice: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_NED_OUT, 'boarded');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_confirmed', format('db/76 (board): a boy only asked for was marked in: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_LOU_OUT, 'handed_over');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_departed', format('db/76 (forward): handed over before the car left: %s', v_reason));

    -- (road) a boy in the car: his family's withdrawal is refused (db/70);
    -- the other boy's withdrawal leaves him alone under a policy refusing
    -- it — but he is in the car, so his seat stands and the driver and his
    -- family are told to speak now; the lift cannot be cancelled, edited or
    -- voided by anybody, the row guard besides
    PERFORM _as(U_LMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_withdraw(S_LOU_OUT);
    PERFORM _assert(NOT v_ok AND v_reason = 'already_boarded', format('db/76 (road): a boy in the car was withdrawn: %s', v_reason));
    PERFORM _as(U_MMUM);
    SELECT ok INTO v_ok FROM lift_seat_withdraw(S_MAX_OUT);
    PERFORM _assert(v_ok AND _v76_status(S_LOU_OUT) = 'confirmed'
                    AND _v76_told(U_LMUM, 'One boy is left on a lift') = 1 AND _v76_told(U_LDAD, 'One boy is left on a lift') = 1
                    AND _v76_told(U_DMUM, 'One boy is left on your lift') = 1,
      format('db/76 (road): left alone in the car Lou reads %s; his mother told %s, the driver %s', _v76_status(S_LOU_OUT),
             _v76_told(U_LMUM, 'One boy is left on a lift'), _v76_told(U_DMUM, 'One boy is left on your lift')));
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_cancel(O_OUT);
    PERFORM _assert(NOT v_ok AND v_reason = 'on_the_road', format('db/76 (road): the driver cancelled a lift with a boy in it: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_update(O_OUT, 2, 'ground', (ids->>'mt_start')::timestamptz - interval '30 minutes', NULL, 1);
    PERFORM _assert(NOT v_ok AND v_reason = 'on_the_road', format('db/76 (road): the driver edited a lift with a boy in it: %s', v_reason));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_offer_cancel(O_OUT);
    PERFORM _assert(NOT v_ok AND v_reason = 'on_the_road', format('db/76 (road): the office cancelled a lift with a boy in it: %s', v_reason));
    -- (road-move) the start delayed on the day: the lift on the road keeps
    -- its version; the way home, not yet under way, waits on its driver
    PERFORM _v76_fixture(MT, interval '30 minutes');
    PERFORM _assert((_v76_offer(O_OUT)).version = 1 AND _v76_status(S_LOU_OUT) = 'confirmed'
                    AND (_v76_offer(O_BACK)).version = 2 AND _v76_status(S_OLE_BACK) = 'awaiting_driver',
      format('db/76 (road): the start moved: the way there is version %s (%s), the way home %s (%s)',
             (_v76_offer(O_OUT)).version, _v76_status(S_LOU_OUT), (_v76_offer(O_BACK)).version, _v76_status(S_OLE_BACK)));
    -- ...and a lift waiting on its driver does not leave until she stands behind it
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_BACK, 'departed');
    PERFORM _assert(NOT v_ok AND v_reason = 'awaiting_driver' AND (_v76_offer(O_BACK)).departed_at IS NULL,
      format('db/76 (road): a lift waiting on its driver after the fixture moved was marked as left: %s', v_reason));
    -- (road-link) Lou's mother's link revoked: in the car he keeps his seat;
    -- his seat home, which her link gave, is void — and Max, the one child
    -- left on the way home (Ole is eighteen), falls back, not being on the road
    PERFORM _v76_end_link(P_LOU, U_LMUM);
    PERFORM _v76_fire();
    PERFORM _assert((_v76_seat(S_LOU_OUT)).state = 'confirmed' AND (_v76_seat(S_LOU_BACK)).state = 'void'
                    AND (_v76_seat(S_MAX_BACK)).state = 'requested' AND (_v76_seat(S_OLE_BACK)).state = 'confirmed',
      format('db/76 (road): with his mother''s link ended Lou''s seats read %s and %s; Max %s, Ole %s',
             (_v76_seat(S_LOU_OUT)).state, (_v76_seat(S_LOU_BACK)).state, (_v76_seat(S_MAX_BACK)).state, (_v76_seat(S_OLE_BACK)).state));
    PERFORM _assert(_v76_told(U_MMUM, 'A seat on a lift is no longer confirmed') = 1
                    AND _v76_told(U_MDAD, 'A seat on a lift is no longer confirmed') = 0,
      format('db/76 (told): Max fell back: his mother told %s, his father %s',
             _v76_told(U_MMUM, 'A seat on a lift is no longer confirmed'), _v76_told(U_MDAD, 'A seat on a lift is no longer confirmed')));
    -- (road-guard) and past the functions, the row guard refuses the same
    PERFORM _assert(_v76_force_end(O_OUT) AND _v76_force_unseat(S_LOU_OUT) AND (_v76_offer(O_OUT)).state = 'open',
      'db/76 (road): the row guard let a lift on the road, or a boy in the car, be ended past the functions');

    -- (depart) the car leaves: it takes no more requests; Ned's request,
    -- never accepted, is declined and his mother told
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'departed');
    PERFORM _assert(v_ok AND (_v76_offer(O_OUT)).departed_at IS NOT NULL AND (_v76_offer(O_OUT)).state = 'closed'
                    AND (_v76_seat(S_NED_OUT)).state = 'declined' AND _v76_told(U_NMUM, 'A seat request was not accepted') = 1,
      format('db/76 (depart): the car left: %s %s; Ned %s, told %s', v_ok, v_reason, (_v76_seat(S_NED_OUT)).state,
             _v76_told(U_NMUM, 'A seat request was not accepted')));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'departed');
    PERFORM _assert(NOT v_ok AND v_reason = 'already_departed', format('db/76 (forward): a second "left": %s', v_reason));
    PERFORM _as(U_NMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_request(O_OUT, P_NED);
    PERFORM _assert(NOT v_ok AND v_reason = 'offer_not_open', format('db/76 (depart): a seat was asked on a lift that has left: %s', v_reason));

    -- (handover) the driver hands Lou over at the ground
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_LOU_OUT, 'handed_over');
    PERFORM _assert(v_ok AND (_v76_seat(S_LOU_OUT)).handover_kind = 'received',
      format('db/76 (handover): Lou was not handed over: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_LOU_OUT, 'not_collected');
    PERFORM _assert(NOT v_ok AND v_reason = 'already_marked' AND (_v76_seat(S_LOU_OUT)).handover_kind = 'received',
      format('db/76 (forward): a handover was re-marked: %s', v_reason));

    -- (expected) the side's coach reads who is arriving by lift, logged;
    -- nobody else reads it — not the other side's coach, not a parent, not
    -- the office, the owner's key or a pupil
    PERFORM _as(U_CO);
    SELECT string_agg(full_name || ':' || status || ':' || (handed_over_at IS NOT NULL), ',' ORDER BY full_name) INTO got FROM lift_expected(MT);
    PERFORM _assert(got = 'Lou Liftseventysix:confirmed:true' AND _v76_logged('lift_expected', O_OUT, U_CO) = 1,
      format('db/76 (expected): the coach expects %s (logged %s)', got, _v76_logged('lift_expected', O_OUT, U_CO)));
    FOREACH who IN ARRAY ARRAY[U_BCO, U_LMUM, U_DMUM, U_OFF, U_TCO, U_HD, U_OWNER, U_PLAT, U_OLE, U_TOM] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO k FROM lift_expected(MT);
      PERFORM _assert(k = 0 AND _v76_logged('lift_expected', O_OUT, who) = 0,
        format('db/76 (expected): %s reads %s expected boy(s)', who, k));
    END LOOP;

    -- (receive-out) the way out is received by the side's staff: a guardian
    -- (not at the ground), the other side's coach and the office are refused
    FOREACH who IN ARRAY ARRAY[U_LDAD, U_DMUM, U_BCO, U_OFF, U_OLE] LOOP
      PERFORM _as(who);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_LOU_OUT);
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (receive-out): %s received Lou at the ground: %s', who, v_reason));
    END LOOP;
    PERFORM _as(U_CO);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_LOU_OUT);
    PERFORM _assert(v_ok AND (_v76_seat(S_LOU_OUT)).acknowledged_by = U_CO, format('db/76 (receive-out): the coach could not say "with us": %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_LOU_OUT);
    PERFORM _assert(NOT v_ok AND v_reason = 'already_received', format('db/76 (forward): received twice: %s', v_reason));
    -- (arrive) the driver arrives: every boy on it received, the lift is done
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'arrived');
    PERFORM _assert(v_ok AND (_v76_offer(O_OUT)).state = 'done' AND (_v76_seat(S_LOU_OUT)).state = 'done',
      format('db/76 (done): the way there, arrived and received, is %s', (_v76_offer(O_OUT)).state));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_OUT, 'arrived');
    PERFORM _assert(NOT v_ok AND v_reason = 'offer_ended', format('db/76 (forward): a done lift was marked again: %s', v_reason));

    -- (my-day) the day cards: the driver's names her passengers, logged; a
    -- family's carries her own boy and nobody else's, unlogged; nobody else
    -- has one — not the coach, the office, a pupil of seventeen
    PERFORM _as(U_DMUM);
    j := lift_my_day(MT);
    SELECT string_agg(e->>'leg' || ':' || (e->>'as') || ':' || (SELECT string_agg(x->>'name', '+' ORDER BY x->>'name')
                                                                  FROM jsonb_array_elements(e->'seats') x), ' ')
      INTO got FROM jsonb_array_elements(j) e;
    PERFORM _assert(got = 'out:driver:Lou Liftseventysix back:driver:Max Liftseventysix+Ole Liftseventysix'
                    AND _v76_logged('lift_day', O_BACK, U_DMUM) = 1,
      format('db/76 (my-day): the driver''s day reads %s (logged %s)', got, _v76_logged('lift_day', O_BACK, U_DMUM)));
    PERFORM _as(U_OMUM);
    j := lift_my_day(MT);
    PERFORM _assert(jsonb_array_length(j) = 1 AND j->0->>'as' = 'family' AND j->0->>'driverName' = 'V76 Dmum'
                    AND j->0->'seats'->0->>'name' = 'Ole Liftseventysix' AND j::text NOT LIKE '%Max%'
                    AND j::text NOT LIKE '%076 0001%' AND _v76_logged('lift_day', O_BACK, U_OMUM) = 0,
      format('db/76 (my-day): Ole''s mother''s day reads %s', j));
    PERFORM _as(U_OLE);
    j := lift_my_day(MT);
    PERFORM _assert(jsonb_array_length(j) = 1 AND j->0->'seats'->0->>'self' = 'true' AND j::text NOT LIKE '%Max%',
      format('db/76 (my-day): Ole, eighteen and at school, reads %s', j));
    FOREACH who IN ARRAY ARRAY[U_CO, U_OFF, U_TOM, U_WMUM, U_OWNER, U_LMUM, U_NMUM] LOOP
      PERFORM _as(who);
      PERFORM _assert(jsonb_array_length(lift_my_day(MT)) = 0, format('db/76 (my-day): %s has a day card on the morning fixture: %s', who, lift_my_day(MT)));
    END LOOP;
    PERFORM _as(U_TMUM);
    j := lift_my_day(MW);
    PERFORM _assert(jsonb_array_length(j) = 1 AND j->0->'seats'->0->>'name' = 'Tom Liftseventysix' AND j::text NOT LIKE '%Ned%',
      format('db/76 (my-day): Tom''s mother reads %s', j));
    PERFORM _as(U_DMUM);
    PERFORM _assert(jsonb_array_length(lift_my_day(MF)) = 0, 'db/76 (my-day): a lift ten days out has a day card');

    -- (mine) my_lifts(): the boy of eighteen at school, his own lift, no
    -- number; a pupil of seventeen with a confirmed seat reads nothing
    -- (decision 4); a parent nothing
    PERFORM _as(U_DMUM);
    SELECT ok INTO v_ok FROM lift_offer_reaffirm(O_BACK, 2);
    PERFORM _as(U_OLE);
    SELECT ok INTO v_ok FROM lift_seat_reconfirm(S_OLE_BACK);
    PERFORM _assert(v_ok AND _v76_status(S_OLE_BACK) = 'confirmed', format('db/76 (setup): Ole''s seat home reads %s', _v76_status(S_OLE_BACK)));
    SELECT string_agg(leg || ':' || driver_name || ':' || vehicle || ':' || meet_place, ',') INTO got FROM my_lifts();
    SELECT to_jsonb(array_agg(m)) INTO j FROM my_lifts() m;
    PERFORM _assert(got = 'back:V76 Dmum:silver Toyota Fortuner:At the ground' AND j::text NOT LIKE '%076 0001%'
                    AND j::text NOT LIKE '%ND 760%',
      format('db/76 (mine): Ole''s own lifts read %s / %s', got, j));
    FOREACH who IN ARRAY ARRAY[U_TOM, U_TMUM, U_LDAD, U_DMUM, U_CO, U_OWNER] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO k FROM my_lifts();
      PERFORM _assert(k = 0, format('db/76 (mine): %s reads %s lift(s) as his own', who, k));
    END LOOP;

    -- The way home, under way: Lou again (his father asks), Max reconfirmed, both accepted
    PERFORM _as(U_LDAD);
    SELECT seat_id INTO S_LOU_BACK FROM lift_seat_request(O_BACK, P_LOU);
    PERFORM _as(U_MMUM);
    SELECT ok INTO v_ok FROM lift_seat_reconfirm(S_MAX_BACK);
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_accept(ARRAY[S_LOU_BACK, S_MAX_BACK]);
    PERFORM _assert(v_ok, format('db/76 (setup): the way home was not accepted again: %s', v_reason));
    PERFORM lift_seat_mark(S_LOU_BACK, 'boarded'); PERFORM lift_seat_mark(S_MAX_BACK, 'boarded'); PERFORM lift_seat_mark(S_OLE_BACK, 'boarded');
    SELECT ok INTO v_ok FROM lift_mark(O_BACK, 'departed');
    PERFORM _assert(v_ok AND _v76_told(U_LDAD, 'A lift has left: he was not marked in the car') = 0,
      'db/76 (setup): the way home did not leave, or a boy in the car was reported left behind');
    PERFORM lift_seat_mark(S_LOU_BACK, 'handed_over');

    -- (not-collected) Max is not collected: his mother, the office and the
    -- transport coordinator are told, pointed at him and naming nobody; no
    -- coach is told on the way home; the lift, arrived, is not done
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_MAX_BACK, 'not_collected');
    PERFORM _assert(v_ok AND (_v76_seat(S_MAX_BACK)).handover_kind = 'not_collected'
                    AND _v76_told(U_MMUM, 'He was not collected from his lift') = 1
                    AND _v76_told(U_MDAD, 'He was not collected from his lift') = 1
                    AND _v76_told(U_OFF, 'A boy was not collected from a lift') = 1
                    AND _v76_told(U_TCO, 'A boy was not collected from a lift') = 1
                    AND _v76_told_about(P_MAX, 'A boy was not collected from a lift')
                        = _v76_overseers(HIL)
                    AND _v76_told(U_CO, 'A boy on a lift was not handed over') = 0
                    AND _v76_told(U_HD, 'A boy was not collected from a lift') = 0,
      format('db/76 (not-collected): Max: %s %s; mother %s, father %s, office %s, coordinator %s, coach %s, principal %s', v_ok, v_reason,
             _v76_told(U_MMUM, 'He was not collected from his lift'), _v76_told(U_MDAD, 'He was not collected from his lift'), _v76_told(U_OFF, 'A boy was not collected from a lift'),
             _v76_told(U_TCO, 'A boy was not collected from a lift'), _v76_told(U_CO, 'A boy on a lift was not handed over'),
             _v76_told(U_HD, 'A boy was not collected from a lift')));
    -- ...and the office reads that notice, the principal does not
    PERFORM _as(U_OFF);
    SELECT count(*) INTO k FROM notification WHERE title = 'A boy was not collected from a lift' AND subject_person_id = P_MAX;
    PERFORM _as(U_HD);
    SELECT count(*) INTO k2 FROM notification WHERE title = 'A boy was not collected from a lift' AND subject_person_id = P_MAX;
    PERFORM _assert(k = 1 AND k2 = 0, format('db/76 (not-collected): the office reads %s of its notice, the principal %s', k, k2));
    PERFORM _v76_handed(S_OLE_BACK, interval '40 minutes');
    PERFORM _as(U_DMUM);
    SELECT ok INTO v_ok FROM lift_mark(O_BACK, 'arrived');
    PERFORM _assert(v_ok AND (_v76_offer(O_BACK)).state = 'closed' AND (_v76_offer(O_BACK)).arrived_at IS NOT NULL,
      format('db/76 (done): the way home, a boy not collected, reads %s', (_v76_offer(O_BACK)).state));

    -- (watch) the platform's key alone runs it; Ole, handed over forty
    -- minutes ago and not acknowledged, is asked after — to his mother and to
    -- him (eighteen, his own seat), never to the coach — and only once
    FOREACH who IN ARRAY ARRAY[U_DMUM, U_OFF, U_TCO, U_CO, U_HD, U_OLE] LOOP
      PERFORM _as(who);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_missed_watch();
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (watch): %s ran the watch: %s', who, v_reason));
    END LOOP;
    PERFORM _assert((_v76_seat(S_OLE_BACK)).missed_alerted_at IS NULL, 'db/76 (watch): a refused watch alerted');
    PERFORM _as(U_OWNER);
    SELECT ok INTO v_ok FROM lift_missed_watch();
    PERFORM _assert(v_ok AND (_v76_seat(S_OLE_BACK)).missed_alerted_at IS NOT NULL
                    AND _v76_told(U_OMUM, 'Please confirm you have him') = 1 AND _v76_told(U_OLE, 'Please confirm you have him') = 1
                    AND _v76_told(U_CO, 'A boy on a lift is not marked with the side') = 0
                    AND (_v76_seat(S_LOU_BACK)).missed_alerted_at IS NULL AND (_v76_seat(S_MAX_BACK)).missed_alerted_at IS NULL,
      format('db/76 (watch): Ole''s handover: alerted %s, his mother told %s, he %s',
             (_v76_seat(S_OLE_BACK)).missed_alerted_at, _v76_told(U_OMUM, 'Please confirm you have him'),
             _v76_told(U_OLE, 'Please confirm you have him')));

    -- (exceptions) the office reads the exceptions by name, logged: Max not
    -- collected, Ole not received; Lou (handed over minutes ago) is not one;
    -- nobody else reads them
    PERFORM _as(U_OFF);
    SELECT string_agg(full_name || ':' || kind, ',' ORDER BY full_name) INTO got FROM lift_exceptions(HIL, MT);
    PERFORM _assert(got = 'Max Liftseventysix:not_collected,Ole Liftseventysix:not_received'
                    AND _v76_logged('lift_exceptions', O_BACK, U_OFF) = 1,
      format('db/76 (exceptions): the office reads %s (logged %s)', got, _v76_logged('lift_exceptions', O_BACK, U_OFF)));
    FOREACH who IN ARRAY ARRAY[U_DMUM, U_MMUM, U_CO, U_HD, U_OWNER, U_PLAT, U_OLE, U_WMUM] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO k FROM lift_exceptions(HIL);
      PERFORM _assert(k = 0 AND _v76_logged('lift_exceptions', O_BACK, who) = 0,
        format('db/76 (exceptions): %s reads %s exception(s)', who, k));
    END LOOP;

    -- (receive-back) the way home is received by a guardian of the boy, or by
    -- the boy himself at eighteen: the coach, the office and the driver are
    -- refused; Lou's father has him; Max's mother collects him late, which
    -- resolves him; Ole says he is home; the lift is done
    FOREACH who IN ARRAY ARRAY[U_CO, U_OFF, U_DMUM, U_MMUM, U_TOM, U_LMUM] LOOP
      PERFORM _as(who);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_LOU_BACK);
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (receive-back): %s received Lou at home: %s', who, v_reason));
    END LOOP;
    PERFORM _as(U_LDAD);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_LOU_BACK);
    PERFORM _assert(v_ok, format('db/76 (receive-back): Lou''s father could not say he has him: %s', v_reason));
    PERFORM _as(U_MMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_MAX_BACK);
    PERFORM _assert(v_ok AND (_v76_seat(S_MAX_BACK)).resolution = 'collected_late' AND (_v76_offer(O_BACK)).state = 'closed',
      format('db/76 (receive-back): Max collected late: %s %s, resolution %s, lift %s', v_ok, v_reason,
             (_v76_seat(S_MAX_BACK)).resolution, (_v76_offer(O_BACK)).state));
    PERFORM _as(U_OLE);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_receive(S_OLE_BACK);
    PERFORM _assert(v_ok AND (_v76_offer(O_BACK)).state = 'done' AND (_v76_seat(S_MAX_BACK)).state = 'done',
      format('db/76 (done): the way home, every boy received, reads %s (%s %s)', (_v76_offer(O_BACK)).state, v_ok, v_reason));
    PERFORM _as(U_OFF);
    SELECT count(*) INTO k FROM lift_exceptions(HIL, MT);
    PERFORM _assert(k = 0, format('db/76 (exceptions): %s exception(s) remain on a fixture whose lifts are done', k));

    -- (watch-left) the afternoon's lift is an hour past its meeting time and
    -- has not left: each family on it is told once and the driver once; Tom,
    -- seventeen, is told nothing (his mother is); a second run tells nobody
    PERFORM _v76_meet(O_W, now() - interval '60 minutes');
    PERFORM _as(U_OWNER);
    SELECT ok INTO v_ok FROM lift_missed_watch();
    SELECT ok INTO v_ok FROM lift_missed_watch();
    PERFORM _assert(v_ok AND _v76_told(U_NMUM, 'A lift has not been marked as leaving') = 1
                    AND _v76_told(U_PMUM, 'A lift has not been marked as leaving') = 1
                    AND _v76_told(U_TMUM, 'A lift has not been marked as leaving') = 1
                    AND _v76_told(U_TOM, 'A lift has not been marked as leaving') = 0
                    AND _v76_told(U_DMUM, 'Has your lift left?') = 1,
      format('db/76 (watch-left): told: Ned''s mother %s, Pip''s %s, Tom''s %s, Tom %s, the driver %s',
             _v76_told(U_NMUM, 'A lift has not been marked as leaving'), _v76_told(U_PMUM, 'A lift has not been marked as leaving'),
             _v76_told(U_TMUM, 'A lift has not been marked as leaving'), _v76_told(U_TOM, 'A lift has not been marked as leaving'),
             _v76_told(U_DMUM, 'Has your lift left?')));
    PERFORM _as(U_CO);
    SELECT string_agg(full_name || ':' || not_left, ',' ORDER BY full_name) INTO got FROM lift_expected(MW);
    PERFORM _assert(got = 'Ned Liftseventysix:true,Pip Liftseventysix:true,Tom Liftseventysix:true',
      format('db/76 (expected): the coach''s afternoon list reads %s', got));
    PERFORM _as(U_OFF);
    SELECT string_agg(full_name || ':' || kind, ',' ORDER BY full_name) INTO got FROM lift_exceptions(HIL, MW);
    PERFORM _assert(got = 'Ned Liftseventysix:not_left,Pip Liftseventysix:not_left,Tom Liftseventysix:not_left',
      format('db/76 (exceptions): the afternoon reads %s', got));
    -- (not-boarded) she leaves late with Pip and Tom, not Ned: Ned's mother
    -- is told he was not marked in, and he is an exception until resolved
    PERFORM _as(U_DMUM);
    PERFORM lift_seat_mark(S_PIP_W, 'boarded'); PERFORM lift_seat_mark(S_TOM_W, 'boarded');
    SELECT ok INTO v_ok FROM lift_mark(O_W, 'departed');
    PERFORM _assert(v_ok AND _v76_told(U_NMUM, 'A lift has left: he was not marked in the car') = 1
                    AND _v76_told(U_PMUM, 'A lift has left: he was not marked in the car') = 0,
      format('db/76 (not-boarded): Ned''s mother told %s, Pip''s %s', _v76_told(U_NMUM, 'A lift has left: he was not marked in the car'),
             _v76_told(U_PMUM, 'A lift has left: he was not marked in the car')));
    PERFORM _v76_handed(S_PIP_W, interval '40 minutes');
    PERFORM lift_seat_mark(S_TOM_W, 'handed_over');
    SELECT ok INTO v_ok FROM lift_mark(O_W, 'arrived');
    -- (once) Pip, alerted already for the lift not leaving, is not alerted
    -- again for his handover (one alert per seat, D14)
    PERFORM _as(U_OWNER);
    PERFORM lift_missed_watch();
    PERFORM _assert(_v76_told(U_PMUM, 'Please confirm you have him') = 0,
      format('db/76 (once): Pip''s mother was alerted twice (%s)', _v76_told(U_PMUM, 'Please confirm you have him')));
    PERFORM _as(U_OFF);
    SELECT string_agg(full_name || ':' || kind, ',' ORDER BY full_name) INTO got FROM lift_exceptions(HIL, MW);
    PERFORM _assert(got = 'Ned Liftseventysix:not_boarded,Pip Liftseventysix:not_received',
      format('db/76 (exceptions): after the late start the afternoon reads %s', got));
    -- (resolve) the office closes Ned: a word it knows, by the office only
    SELECT ok, reason INTO v_ok, v_reason FROM lift_resolve(S_NED_W, 'found');
    PERFORM _assert(NOT v_ok AND v_reason = 'resolution', format('db/76 (resolve): an unknown resolution: %s', v_reason));
    FOREACH who IN ARRAY ARRAY[U_NMUM, U_DMUM, U_CO, U_HD, U_OWNER] LOOP
      PERFORM _as(who);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_resolve(S_NED_W, 'school_office');
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (resolve): %s resolved Ned: %s', who, v_reason));
    END LOOP;
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_resolve(S_NED_W, 'school_office');
    PERFORM _assert(v_ok AND (_v76_seat(S_NED_W)).resolution = 'school_office' AND (_v76_seat(S_NED_W)).resolved_by = U_OFF
                    AND (_v76_offer(O_W)).state = 'closed',
      format('db/76 (resolve): the office could not resolve Ned: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_resolve(S_NED_W, 'other');
    PERFORM _assert(NOT v_ok AND v_reason = 'already_received', format('db/76 (forward): resolved twice: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_resolve(S_LOU_U, 'other');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet', format('db/76 (resolve): a lift not yet due was resolved: %s', v_reason));
    PERFORM _as(U_CO);
    PERFORM lift_receive(S_PIP_W); PERFORM lift_receive(S_TOM_W);
    PERFORM _assert((_v76_offer(O_W)).state = 'done', format('db/76 (done): the afternoon reads %s', (_v76_offer(O_W)).state));

    -- (watch-out) the evening's lift, under way, Lou handed over forty minutes
    -- ago at the ground and nobody saying he is with the side: his family and
    -- the U17A's staff are told, the U17B's coach is not
    PERFORM _v76_under_way(O_X, ARRAY[P_LOU, P_MAX], P_LOU, interval '40 minutes');
    PERFORM _as(U_OWNER);
    PERFORM lift_missed_watch();
    PERFORM _assert(_v76_told(U_LDAD, 'Please confirm you have him') = 1
                    AND _v76_told(U_CO, 'A boy on a lift is not marked with the side') = 1
                    AND _v76_told(U_BCO, 'A boy on a lift is not marked with the side') = 0,
      format('db/76 (watch-out): told: his father %s, the coach %s, the U17B''s coach %s',
             _v76_told(U_LDAD, 'Please confirm you have him'), _v76_told(U_CO, 'A boy on a lift is not marked with the side'),
             _v76_told(U_BCO, 'A boy on a lift is not marked with the side')));

    -- (revoked) the driver's guardian assignment revoked: her lift under way
    -- runs to its end — not cancelled — and she is refused its marks; her
    -- lifts not yet under way are cancelled 'link_ended' (db/70)
    PERFORM _v76_revoke(U_DMUM);
    PERFORM _v76_fire();
    PERFORM _as(U_DMUM);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_mark(O_X, 'arrived');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND (_v76_offer(O_X)).state = 'closed'
                    AND (_v76_offer(O_U)).cancel_kind = 'link_ended' AND (_v76_offer(O_F)).cancel_kind = 'link_ended',
      format('db/76 (revoked): a revoked driver marked (%s %s); under way %s, ahead %s %s', v_ok, v_reason,
             (_v76_offer(O_X)).state, (_v76_offer(O_U)).cancel_kind, (_v76_offer(O_F)).cancel_kind));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_seat_mark(S_MAX_X, 'handed_over');
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (revoked): a revoked driver handed a boy over: %s', v_reason));
    PERFORM _assert(jsonb_array_length(lift_my_day(MX)) = 0, 'db/76 (revoked): a revoked driver reads her day card');
    PERFORM _as(U_OFF);
    SELECT string_agg(full_name || ':' || kind, ',' ORDER BY full_name) INTO got FROM lift_exceptions(HIL, MX);
    PERFORM _assert(got = 'Lou Liftseventysix:not_received', format('db/76 (revoked): the evening''s exceptions read %s', got));
    -- (resolve) a lift under way is resolved before its meeting time: Max,
    -- in the car with a revoked driver, is with the school office
    SELECT ok, reason INTO v_ok, v_reason FROM lift_resolve(S_MAX_X, 'school_office');
    PERFORM _assert(v_ok AND (_v76_seat(S_MAX_X)).resolution = 'school_office',
      format('db/76 (resolve): the office could not resolve a boy on a lift under way: %s %s', v_ok, v_reason));

    -- (purge) the office's due list: the lift of three years and ten days
    -- ago, and the declaration that ended a year and five days ago; not the
    -- lift of three years less ten days, nor the declaration that ended 300
    -- days ago. Purged, they are gone and a row of counts names nobody;
    -- refused before the date and to anybody but the office
    O_P := _v76_old_lift(MP, U_DMUM, ARRAY[P_LOU, P_MAX], ARRAY[U_LDAD, U_MMUM]);
    O_Q := _v76_old_lift(MQ, U_DMUM, ARRAY[P_LOU, P_MAX], ARRAY[U_LDAD, U_MMUM]);
    D_OLD := _v76_old_declaration(U_PMUM, 370);
    v_id := _v76_old_declaration(U_NMUM, 300);
    PERFORM _as(U_OFF);
    SELECT string_agg(kind || ':' || coalesce(seats::text, '-'), ',' ORDER BY kind) INTO got FROM lift_purge_due(HIL)
     WHERE id IN (O_P, O_Q, D_OLD, v_id, D_NEW);
    PERFORM _assert(got = 'declaration:-,offer:2', format('db/76 (purge): the due list reads %s', got));
    FOREACH who IN ARRAY ARRAY[U_DMUM, U_LDAD, U_CO, U_HD, U_OWNER, U_PLAT, U_OLE] LOOP
      PERFORM _as(who);
      SELECT count(*) INTO k FROM lift_purge_due(HIL);
      SELECT ok, reason INTO v_ok, v_reason FROM lift_purge(O_P);
      PERFORM _assert(k = 0 AND NOT v_ok AND v_reason = 'not_permitted' AND _v76_exists(O_P),
        format('db/76 (purge): %s read %s due row(s) or purged: %s %s', who, k, v_ok, v_reason));
    END LOOP;
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM lift_purge(O_Q);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_due' AND _v76_exists(O_Q), format('db/76 (purge): a lift not yet due was purged: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_purge_declaration(v_id);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_due', format('db/76 (purge): a declaration not yet due was purged: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_purge_declaration(D_NEW);
    PERFORM _assert(NOT v_ok AND v_reason IN ('not_due', 'lifts_remain'), format('db/76 (purge): a live declaration was purged: %s', v_reason));
    got := to_char(((ids->>'mp_start')::timestamptz AT TIME ZONE 'Africa/Johannesburg'), 'YYYY');
    SELECT ok, reason INTO v_ok, v_reason FROM lift_purge(O_P);
    PERFORM _assert(v_ok AND NOT _v76_exists(O_P) AND _v76_seats_on(O_P) = 0
                    AND (_v76_purge_log(HIL, got)).offers = 1 AND (_v76_purge_log(HIL, got)).seats = 2,
      format('db/76 (purge): the old lift: %s %s; left %s seat(s); the log reads %s', v_ok, v_reason, _v76_seats_on(O_P),
             to_jsonb(_v76_purge_log(HIL, got))));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_purge(O_P);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('db/76 (purge): a lift was purged twice: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM lift_purge_declaration(D_OLD);
    PERFORM _assert(v_ok AND NOT _v76_exists(D_OLD)
                    AND (_v76_purge_log(HIL, to_char(current_date - 370, 'YYYY'))).declarations >= 1,
      format('db/76 (purge): the old declaration: %s %s', v_ok, v_reason));
    SELECT count(*) INTO k FROM lift_purge_log WHERE school_id = HIL;
    PERFORM _as(U_LDAD);
    SELECT count(*) INTO k2 FROM lift_purge_log;
    PERFORM _assert(k >= 1 AND k2 = 0, format('db/76 (purge): the office reads %s log row(s), a parent %s', k, k2));

    -- (privacy) still no number, address or name in any lift row; no lift
    -- notice names anybody or reaches a pupil but the boy of eighteen about
    -- his own seat; the application writes no lift row; the module is still
    -- off by default (the platform grants it, per school)
    SELECT string_agg(table_name || '.' || column_name, ' ') INTO got FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name LIKE 'lift\_%'
       AND column_name ~ '(phone|address|name|email|id_number|mobile|location|latitude|longitude)';
    PERFORM _assert(got IS NULL, format('db/76 (privacy): lift rows carry %s', got));
    PERFORM _assert(_v70_named_notices() = 0 AND _v70_pupil_notices() = 0,
      format('db/76 (privacy): %s lift notice(s) name a person and %s reach a pupil', _v70_named_notices(), _v70_pupil_notices()));
    PERFORM _as(U_OFF);
    BEGIN
      INSERT INTO lift_purge_log (school_id, season, offers, seats) VALUES (HIL, '2001', 0, 0);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, 'db/76 (write): the office wrote a purge log row past the functions');
    PERFORM _assert((SELECT NOT enabled FROM feature_flag WHERE key = 'lift_club'),
      'db/76 (module): lift_club is on by default');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 55

  -- ── 56. Ending a role (SCRBRD-132 C1, db/77) ──────────────────────
  -- role_assignment_end(): an assignment granted through the real path
  -- (enrol_person()) and ended stops granting on the next statement; whoever
  -- may not grant the role may not end it; nobody ends their own last key,
  -- their own DSO appointment, a superadmin's role from below, or the owner's
  -- key; the reason is required; the audit row and the notice are written,
  -- the notice without the reason and readable by somebody left with no role;
  -- the ended row stays on the audit read; a guardian role keeps the guardian
  -- link's rules (guardian.link.manage, the last verified link of a minor)
  -- and takes its live links with it; db/57's DSO guard still answers.
  -- _seed_77() builds its own world. tools/smoke-end-role.mjs walks the same
  -- through the API.
  --
  -- Each labelled guard was falsified once, by taking it out of
  -- role_assignment_end() as the owner before this file ran, and went red. It
  -- was green again once restored. 15 breaks:
  --   (scope)       app_may_grant_at() without its school condition: it
  --                 answered at Hilton on Westville's key; and with that
  --                 direct assertion taken out as well, enrol_person() appointed
  --                 medical staff at Hilton on Westville's principal
  --   (grant)       the UPDATE of active dropped: the ended coach still held
  --                 his capabilities
  --   (granter)     app_may_grant_at() dropped from the authority test: the office
  --                 ended a medical appointment
  --   (last-admin)  the last_admin answer dropped: the platform ended its only key
  --   (superadmin)  the superadmin_only answer dropped: the office ended the
  --                 coaching role of the owner's key
  --   (owner)       the owners_key answer dropped: a superadmin ended the key
  --   (reason)      the ten-character test lowered to one: held by
  --                 role_assignment_ending's CHECK, the second layer (the
  --                 end raised); with that CHECK dropped as well, 'short'
  --                 ended a role
  --   (audit)       the ending row's INSERT dropped; the notice's INSERT dropped
  --                 (the row had no notice_id)
  --   (notice)      notification_role_ended dropped: the coach, with no role
  --                 left, read nothing
  --   (guardian)    the last_verified_link answer dropped; the
  --                 guardian.link.manage test dropped (the platform got past
  --                 not_permitted); the links left verified (Mum's link stayed
  --                 'verified')
  --   (dso)         the own_dso answer dropped: the principal ended his own
  DECLARE
    ids      jsonb := _seed_77();
    U_OFF    uuid := (ids->>'u_office')::uuid;
    U_HD     uuid := (ids->>'u_head')::uuid;
    U_DS     uuid := (ids->>'u_dso')::uuid;
    U_PL     uuid := (ids->>'u_plat')::uuid;
    U_OWN    uuid := (ids->>'u_own')::uuid;
    U_MUM    uuid := (ids->>'u_mum')::uuid;
    U_DAD    uuid := (ids->>'u_dad')::uuid;
    U_MED    uuid := (ids->>'u_medic')::uuid;
    P_KID    uuid := (ids->>'p_kid')::uuid;
    A_COACH  uuid;
    U_CO     uuid;
    v_notice uuid;
    WHY      text := 'Left the school at the end of the term.';
    NIL      uuid := '00000000-0000-0000-0000-000000000000';
    e        role_assignment_ending;
    nt       notification;
    lk       assignment_subject;
  BEGIN
    -- (grant) granted through enrol_person(), as the office does it
    PERFORM _as(U_OFF);
    SELECT x.ok, x.reason, x.user_id, x.assignment_id INTO v_ok, v_reason, U_CO, A_COACH
      FROM enrol_person('v77.coach@example.invalid', 'V77 Coach', 'coach', HIL, 'U15A', NULL, NULL) x;
    PERFORM _assert(v_ok AND A_COACH IS NOT NULL, format('§56 (grant): the office could not enrol a coach: %s', v_reason));
    PERFORM _as(U_CO);
    PERFORM _assert(app_can('team.manage', HIL, 'U15A', NIL, NIL) AND app_holds('team.manage'),
      '§56 (grant): the enrolled coach does not hold team.manage at his side');

    -- (granter) nobody who may not grant the role ends it
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (granter): the coach ended his own appointment: %s %s', v_ok, v_reason));
    PERFORM _as(U_MED);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (granter): the medical officer ended a coach: %s %s', v_ok, v_reason));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_medic')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND (_v77_assignment((ids->>'a_medic')::uuid)).active,
      format('§56 (granter): the office, which may not appoint medical staff, ended one: %s %s', v_ok, v_reason));
    PERFORM _as(U_WES_ADM);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (granter): another school''s office ended a Hilton coach: %s %s', v_ok, v_reason));

    -- (scope) the role question is asked at the school the scope question
    -- is: Hilton's office who is Westville's principal appoints and ends a
    -- medical officer at Westville, and neither at Hilton
    PERFORM _as((ids->>'u_two')::uuid);
    PERFORM _assert(NOT app_may_grant_at('medical', HIL) AND app_may_grant_at('medical', WES)
                    AND NOT app_may_grant_at('medical', NULL),
      '§56 (scope): app_may_grant_at() does not answer at the school asked');
    SELECT x.ok, x.reason INTO v_ok, v_reason
      FROM enrol_person('v77.hilmedic@example.invalid', 'V77 Hilmedic', 'medical', HIL, NULL, NULL, NULL) x;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (scope): Westville''s principal, through Hilton''s office, appointed medical staff at Hilton: %s %s', v_ok, v_reason));
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id) VALUES (U_MED, 'medical', HIL);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§56 (scope): role_assignment_write let a Hilton medical appointment through on Westville''s key');
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_medic')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted' AND (_v77_assignment((ids->>'a_medic')::uuid)).active,
      format('§56 (scope): Westville''s principal, through Hilton''s office, ended Hilton''s medical officer: %s %s', v_ok, v_reason));
    SELECT x.ok, x.reason, x.assignment_id INTO v_ok, v_reason, A_ID
      FROM enrol_person('v77.wesmedic@example.invalid', 'V77 Wesmedic', 'medical', WES, NULL, NULL, NULL) x;
    PERFORM _assert(v_ok AND A_ID IS NOT NULL, format('§56 (scope): Westville''s principal could not appoint medical staff at Westville: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_ID, WHY);
    PERFORM _assert(v_ok, format('§56 (scope): Westville''s principal could not end Westville''s medical officer: %s', v_reason));

    -- (reason) at least ten characters, after trimming
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, 'short');
    PERFORM _assert(NOT v_ok AND v_reason = 'reason_required' AND (_v77_assignment(A_COACH)).active,
      format('§56 (reason): a five-letter reason ended a role: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, '   left    ');
    PERFORM _assert(NOT v_ok AND v_reason = 'reason_required',
      format('§56 (reason): padding made a reason: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, NULL);
    PERFORM _assert(NOT v_ok AND v_reason = 'reason_required', '§56 (reason): no reason ended a role');

    -- (grant) ended, and no longer granted on the very next statement
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, WHY);
    PERFORM _assert(v_ok, format('§56 (grant): the office could not end the coach: %s', v_reason));
    PERFORM _as(U_CO);
    PERFORM _assert(NOT app_can('team.manage', HIL, 'U15A', NIL, NIL) AND NOT app_holds('team.manage')
                    AND NOT app_can('fixture.read', HIL, 'U15A', NIL, NIL),
      '§56 (grant): the ended coach still holds his capabilities');
    PERFORM _assert((_v77_assignment(A_COACH)).active = false AND (_v77_assignment(A_COACH)).revoked_by = U_OFF
                    AND (_v77_assignment(A_COACH)).revoked_at IS NOT NULL,
      '§56 (grant): the row does not say it was withdrawn, and by the office');
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end(A_COACH, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'already_ended', format('§56: a second end answered %s %s', v_ok, v_reason));

    -- (audit) one row: who, when, why; the office reads it, the coach does not
    e := _v77_ending(A_COACH);
    PERFORM _assert(e.assignment_id = A_COACH AND e.ended_by = U_OFF AND e.reason = WHY AND e.role = 'coach'
                    AND e.school_id = HIL AND e.ended_at IS NOT NULL AND e.notice_id IS NOT NULL,
      '§56 (audit): the ending row is missing or wrong');
    PERFORM _assert((SELECT count(*) FROM role_assignment_ending WHERE assignment_id = A_COACH) = 1,
      '§56 (audit): the office cannot read the ending row');
    -- the ended row is still on the audit read (role_assignment, as the office)
    PERFORM _assert((SELECT count(*) FROM role_assignment WHERE id = A_COACH AND NOT active AND revoked_by = U_OFF) = 1,
      '§56 (audit): the withdrawn assignment is gone from the office''s read');

    -- (notice) to him, without the reason, readable with no role left
    nt := _v77_notice(e.notice_id);
    PERFORM _assert(nt.recipient_id = U_CO AND nt.kind = 'system' AND nt.school_id = HIL
                    AND position('Coach' IN nt.body) > 0 AND position('Hilton College' IN nt.body) > 0
                    AND position('term' IN nt.body) = 0 AND position('term' IN nt.title) = 0,
      format('§56 (notice): the notice is wrong or carries the reason: %s', nt.body));
    PERFORM _as(U_CO);
    PERFORM _assert((SELECT count(*) FROM notification WHERE id = e.notice_id) = 1,
      '§56 (notice): the coach, with no role left, cannot read the notice about it');
    PERFORM _assert((SELECT count(*) FROM role_assignment_ending) = 0,
      '§56 (audit): the coach reads the reason his role was ended');
    PERFORM _assert((SELECT count(*) FROM role_assignment WHERE id = A_COACH) = 1,
      '§56: the coach cannot see his own ended appointment');
    PERFORM _as(U_OFF);
    PERFORM _assert((SELECT count(*) FROM notification WHERE id = e.notice_id) = 0,
      '§56 (notice): the office reads a notice addressed to the coach');
    -- the door is not forgeable: a system notice the office publishes about
    -- his ended assignment is not admitted by it
    -- (No RETURNING: the office may not read a notice addressed to him.)
    v_notice := gen_random_uuid();
    BEGIN
      INSERT INTO notification (id, school_id, scope_level, kind, title, body, required_capability, subject_kind, subject_id, recipient_id)
      VALUES (v_notice, HIL, 'school', 'system', 'Forged', 'Forged', 'news.read', 'system', A_COACH, U_CO);
    EXCEPTION WHEN insufficient_privilege OR check_violation THEN v_notice := NULL;
    END;
    PERFORM _assert(v_notice IS NOT NULL, '§56: the fixture is void — the office could not publish the forged notice');
    PERFORM _as(U_CO);
    PERFORM _assert((SELECT count(*) FROM notification WHERE id = v_notice) = 0,
      '§56 (notice): a notice the office wrote reached the coach through the role-ended door');

    -- (superadmin) a superadmin's role, only by a superadmin; (owner) never the key
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_own_coach')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'superadmin_only',
      format('§56 (superadmin): the office ended the owner''s coaching role: %s %s', v_ok, v_reason));
    PERFORM _as(U_PL);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_own_coach')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'superadmin_only',
      format('§56 (superadmin): the platform ended the owner''s coaching role: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_own')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (owner): the platform ended the owner''s key: %s %s', v_ok, v_reason));
    PERFORM _as(U_OWNER);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_own')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'owners_key' AND (_v77_assignment((ids->>'a_own')::uuid)).active,
      format('§56 (owner): a superadmin ended the owner''s key: %s %s', v_ok, v_reason));
    PERFORM _as(U_OWN);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_own')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'owners_key',
      format('§56 (owner): the key ended itself: %s %s', v_ok, v_reason));
    PERFORM _as(U_OWNER);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_own_coach')::uuid, WHY);
    PERFORM _assert(v_ok, format('§56 (superadmin): a superadmin could not end another''s coaching role: %s', v_reason));

    -- (last-admin) nobody ends their own last key over a school
    PERFORM _as(U_PL);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_plat')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'last_admin' AND (_v77_assignment((ids->>'a_plat')::uuid)).active,
      format('§56 (last-admin): the platform administrator ended his only key: %s %s', v_ok, v_reason));
    PERFORM _assert(app_can('user.role.assign', HIL, '*', NIL, NIL), '§56 (last-admin): the platform lost its key');
    PERFORM _as(U_HD);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_head_office')::uuid, WHY);
    PERFORM _assert(v_ok, format('§56 (last-admin): the principal, keeping his own key, could not end his office role: %s', v_reason));
    PERFORM _assert(app_can('user.role.assign', HIL, '*', NIL, NIL), '§56 (last-admin): the principal lost his key');

    -- (dso) not the office; never one's own; db/57's guard still answers
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_dso')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (dso): the office ended a DSO: %s %s', v_ok, v_reason));
    PERFORM _as(U_DS);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_dso')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (dso): a DSO ended his own appointment: %s %s', v_ok, v_reason));
    PERFORM _as(U_HD);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_head_dso')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'own_dso' AND (_v77_assignment((ids->>'a_head_dso')::uuid)).active,
      format('§56 (dso): the principal ended his own DSO appointment: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_dsob')::uuid, WHY);
    PERFORM _assert(v_ok, format('§56 (dso): the principal could not end a DSO''s appointment: %s', v_reason));
    PERFORM _v77_concern(HIL, U_HD);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_dso')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'dso_blocked' AND (_v77_assignment((ids->>'a_dso')::uuid)).active
                    AND (_v77_ending((ids->>'a_dso')::uuid)).assignment_id IS NULL,
      format('§56 (dso): with a concern naming him open, the principal ended the DSO: %s %s', v_ok, v_reason));

    -- (guardian) the guardian link's rules hold
    PERFORM _as(U_PL);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_mum')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§56 (guardian): the platform, holding no guardian.link.manage, ended a parent: %s %s', v_ok, v_reason));
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_mum')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'last_verified_link' AND (_v77_assignment((ids->>'a_mum')::uuid)).active,
      format('§56 (guardian): the last verified parent of a minor was ended: %s %s', v_ok, v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM guardian_link_verify(U_DAD, P_KID, 'popia-2026-01', NULL);
    PERFORM _assert(v_ok AND _v77_live_links(P_KID) = 2, format('§56: the fixture is void — Dad''s link was not verified: %s', v_reason));
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_mum')::uuid, WHY);
    PERFORM _assert(v_ok, format('§56 (guardian): with Dad verified, Mum''s role could not be ended: %s', v_reason));
    lk := _v77_link((ids->>'a_mum')::uuid);
    PERFORM _assert(lk.verification_state = 'revoked' AND lk.valid_until = current_date AND _v77_live_links(P_KID) = 1,
      format('§56 (guardian): Mum''s link is %s until %s, and the boy counts %s live link(s)',
             lk.verification_state, lk.valid_until, _v77_live_links(P_KID)));
    PERFORM _as(U_MUM);
    PERFORM _assert(NOT app_can('player.profile.read', HIL, 'U15A', P_KID, NIL),
      '§56 (guardian): Mum still reaches the boy');
    PERFORM _as(U_OFF);
    SELECT ok, reason INTO v_ok, v_reason FROM role_assignment_end((ids->>'a_dad')::uuid, WHY);
    PERFORM _assert(NOT v_ok AND v_reason = 'last_verified_link',
      format('§56 (guardian): Dad, now the last verified parent, was ended: %s %s', v_ok, v_reason));
  END;
  PERFORM set_config('app.user_id', '', true);

  -- ── 57. Public commentary names the shot and where it went (SCRBRD-139, db/78) ──
  -- PUBLIC_DATA L7 as amended (Kameel, 2026-10-01): a ball's shot and where
  -- it went may be named in public commentary, as words; no coordinate ever
  -- reaches a browser or the public cache. The words are made on the API
  -- (redact.mjs, by packages/scoring's ballAreas(): one implementation, the
  -- commentary's own), so what the application role gets from
  -- public_match_log() for a served fixture is, key for key: a ball's `shot`
  -- and `place` {theta, radius, seg, source} — the four fields the words
  -- read — and nothing else positional; a ball with nothing recorded,
  -- neither; any other kind, neither. The API drops `place` once it has the
  -- word (services/api/public/public.test.mjs, tools/smoke-public.mjs: no
  -- coordinate in any response). _seed_78() builds its own two fixtures.
  --
  -- Each labelled assertion was falsified once — public_match_log() replaced
  -- in the database (as the owner, inside this file's transaction, before
  -- the section ran) — and went red at its own assertion; six breaks:
  --   (unpublished)  public_fixture_served() dropped from the WHERE
  --   (shot)         the shot not selected
  --   (place)        `place` given the zone as well
  --   (never)        the contact selected as a key of its own
  --   (bare)         `place` without its nullif: an empty object on a ball
  --                  with nothing recorded
  --   (ball-only)    `shot` and `place` built for every kind, not only a ball
  -- (withdrawn) rests on the same guard as (unpublished), which goes red
  -- first when it is dropped.
  DECLARE
    ids     jsonb := _seed_78();
    M_PUB   uuid;
    M_UN    uuid;
    v_keys  text;
    j       jsonb;
  BEGIN
    M_PUB := (ids->>'pub')::uuid;
    M_UN := (ids->>'un')::uuid;

    -- (unpublished) neither fixture answers while nobody has published it,
    -- signed out or signed in
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_match_log(M_PUB, 0);
    PERFORM _assert(n = 0, format('db/78 (unpublished): an unpublished fixture''s log answered %s rows', n));
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM public_match_log(M_UN, 0);
    PERFORM _assert(n = 0, format('db/78 (unpublished): a signed-in reader got %s public rows of an unpublished fixture', n));
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(M_PUB, 'home', true) s;
    PERFORM _assert(v_ok, format('db/78: Hilton could not publish its side (%s)', v_reason));

    -- Signed out from here: what the API's public read gets.
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_match_log(M_UN, 0);
    PERFORM _assert(n = 0, format('db/78 (unpublished): the fixture nobody published answered %s rows once the other was', n));

    -- (shot) the placed four: the shot, and the words' material, exactly
    SELECT l.detail INTO j FROM public_match_log(M_PUB, 0) l WHERE l.seq = 2;
    PERFORM _assert(j->>'shot' = 'drive', format('db/78 (shot): the placed four''s detail is %s', j));
    -- (place) exactly the four fields the words read
    PERFORM _assert(j->'place' = '{"theta": 235, "radius": 0.35, "seg": 8, "source": "point"}'::jsonb,
      format('db/78 (place): the placed four''s place is %s', j->'place'));
    SELECT l.detail INTO j FROM public_match_log(M_PUB, 0) l WHERE l.seq = 3;
    PERFORM _assert(j - 'bowler' = '{"shot": "drive", "place": {"seg": 3, "source": "sector"}}'::jsonb,
      format('db/78 (place): the sector-era four''s detail is %s', j));

    -- (never) no other placement field, at the top or inside `place`, on any row
    SELECT string_agg(DISTINCT k, ',' ORDER BY k) INTO v_keys
      FROM public_match_log(M_PUB, 0) l, jsonb_object_keys(l.detail) k
     WHERE k IN ('theta', 'radius', 'seg', 'zone', 'placementSource', 'placementNull', 'closePosition', 'captureProfile',
                 'contact', 'trajectory', 'bowlerApproach', 'placement');
    PERFORM _assert(v_keys IS NULL, format('db/78 (never): the detail carries %s', v_keys));
    SELECT string_agg(DISTINCT k, ',' ORDER BY k) INTO v_keys
      FROM public_match_log(M_PUB, 0) l, jsonb_object_keys(l.detail->'place') k
     WHERE l.detail ? 'place' AND k NOT IN ('theta', 'radius', 'seg', 'source');
    PERFORM _assert(v_keys IS NULL, format('db/78 (never): a place carries %s', v_keys));
    SELECT count(*) INTO n FROM public_match_log(M_PUB, 0) l
     WHERE l.detail::text ~ '(boundary|middle|"ground"|skipped|quick|bowlerApproach|"over")';
    PERFORM _assert(n = 0, format('db/78 (never): %s rows carry a zone, a contact, a trajectory, a null reason, a profile or an approach', n));

    -- (bare) a ball with nothing recorded says only its outcome: the columns
    -- and the typed bowler, nothing of a shot or a place
    SELECT l.detail INTO j FROM public_match_log(M_PUB, 0) l WHERE l.seq = 4;
    PERFORM _assert(j - 'bowler' = '{}'::jsonb AND (SELECT l.ball_type = 'run' AND l.value = 0 FROM public_match_log(M_PUB, 0) l WHERE l.seq = 4),
      format('db/78 (bare): the ball with nothing recorded reads %s', j));

    -- (ball-only) a kind that is not a ball has no shot and no place
    SELECT l.detail INTO j FROM public_match_log(M_PUB, 0) l WHERE l.seq = 5;
    PERFORM _assert(NOT (j ? 'shot') AND NOT (j ? 'place') AND (j->>'runs')::int = 5,
      format('db/78 (ball-only): the penalty reads %s', j));
    SELECT count(*) INTO n FROM public_match_log(M_PUB, 0) l WHERE l.kind <> 'ball' AND (l.detail ? 'shot' OR l.detail ? 'place');
    PERFORM _assert(n = 0, format('db/78 (ball-only): %s rows not a ball carry a shot or a place', n));

    -- (withdrawn) taken down, it answers nothing again
    PERFORM _as(U_SARAH);
    PERFORM fixture_publish(M_PUB, 'home', false);
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_match_log(M_PUB, 0);
    PERFORM _assert(n = 0, format('db/78 (withdrawn): a fixture Hilton took back down answered %s rows', n));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 57

  -- ┌── section 58 · db/79: the audit log, read (SCRBRD-132 B2) ────────
  -- audit_log() is the one door to the audit tables for Management's tab,
  -- under audit.read (Kameel, 2026-10-01): whoever holds it today. Under the
  -- application role, against _seed_79()'s world on 1 January 2000 (a window
  -- nothing real falls in):
  --   (school)   Hilton's office reads Hilton's five rows and not
  --              Westville's; Westville's office the reverse; neither reads
  --              the other school by naming it
  --   (none)     a coach, holding no audit.read, gets nothing
  --   (masked)   the pupil and the leaver are "V S Pupil" and "V S Leaver"
  --              wherever they appear — actor, subject, from/to — and never
  --              whole; an adult is named whole
  --   (safeguarding) no row whose resource starts `safeguarding`, for the
  --              office or for the DSO whose read it was
  --   (text)     no reason written about anybody reaches a row
  --   (office)   the DSO (audit.read, not the office's key) reads no duty
  --              suspension; the office does
  --   (logged)   every call — answered, refused, empty — leaves exactly one
  --              access_log row, at the school asked about, and the office's
  --              names the child its rows named
  --   (paged)    a page and the page after it, by (at, key), are the window,
  --              without a repeat; a kind filter narrows to that kind
  --
  -- Each labelled assertion was falsified once — audit_log() or a helper
  -- replaced in the database (as the owner, inside this file's transaction,
  -- before the section ran) — and went red at its own assertion; seven breaks:
  --   (school)        the access branch's `l.school_id = p_school` dropped
  --   (none)          the gate `IF v_any THEN` made `IF true THEN`
  --   (masked)        audit_mask_name() returning the name whole for a child
  --   (safeguarding)  the `l.resource NOT LIKE 'safeguarding%'` cut dropped
  --   (text)          the ended role's reason added to its row's detail
  --   (office)        `v_office` dropped from both duty branches
  --   (logged)        the PERFORM log_restricted_read() line dropped
  -- (paged) was not falsified on its own: a cursor that repeats or skips a
  -- row fails its count, which the run itself showed while it was written.
  DECLARE
    ids     jsonb := _seed_79();
    W0      timestamptz := timestamptz '2000-01-01 00:00:00+02';
    W1      timestamptz := timestamptz '2000-01-02 00:00:00+02';
    U_OFF   uuid := (ids->>'u_office')::uuid;
    U_WOFF  uuid := (ids->>'u_wes')::uuid;
    U_DSO   uuid := (ids->>'u_dso')::uuid;
    U_CO    uuid := (ids->>'u_coach')::uuid;
    U_PUP   uuid := (ids->>'u_pupil')::uuid;
    P_PUP   uuid := (ids->>'p_pupil')::uuid;
    k       int;
    k2      int;
    v_txt   text;
    v_at    timestamptz;
    v_key   text;
    v_keys1 text[];
    v_keys2 text[];
  BEGIN
    -- (none) first: a coach holds no audit.read: nothing, and the asking is on the record
    PERFORM _as(U_CO);
    k := _v79_reads(U_CO, HIL);
    SELECT count(*) INTO n FROM audit_log(HIL, NULL, NULL, NULL, NULL, 200);
    PERFORM _assert(n = 0, format('db/79 (none): a coach read %s rows of the audit log', n));
    PERFORM _assert(_v79_reads(U_CO, HIL) = k + 1, 'db/79 (logged): the coach''s refused read is not on the record');
    PERFORM _assert(_v79_reads_naming(U_CO, P_PUP) = 0, 'db/79 (logged): the coach''s refused read names a child');

    -- (school) Hilton's office: Hilton's five rows in the window, and only Hilton's
    PERFORM _as(U_OFF);
    k := _v79_reads(U_OFF, HIL);
    SELECT count(*), string_agg(l.kind, ',' ORDER BY l.kind) INTO n, v_txt FROM audit_log(HIL, NULL, W0, W1, NULL, 200) l
     WHERE l.school_id = HIL AND coalesce(l.detail->>'resource', '') NOT LIKE 'safeguarding%';
    PERFORM _assert(n = 5 AND v_txt = 'access,access,duty,role,scoring',
      format('db/79 (school): Hilton''s office read %s rows in the window: %s', n, v_txt));
    PERFORM _assert(_v79_reads(U_OFF, HIL) = k + 1,
      format('db/79 (logged): the office''s read left %s access_log rows, not one', _v79_reads(U_OFF, HIL) - k));
    PERFORM _assert(_v79_reads_naming(U_OFF, P_PUP) >= 1,
      'db/79 (logged): the office''s read does not name the child its rows named');
    SELECT count(*) INTO n FROM audit_log(HIL, NULL, NULL, NULL, NULL, 200) l WHERE l.school_id IS DISTINCT FROM HIL;
    PERFORM _assert(n = 0, format('db/79 (school): Hilton''s office read %s rows of another school', n));
    k := _v79_reads(U_OFF, WES);
    SELECT count(*) INTO n FROM audit_log(WES, NULL, NULL, NULL, NULL, 200);
    PERFORM _assert(n = 0, format('db/79 (school): Hilton''s office read %s of Westville''s rows by naming it', n));
    PERFORM _assert(_v79_reads(U_OFF, WES) = k + 1, 'db/79 (logged): the office''s refused read of Westville is not on the record');
    -- ...and Westville's office the reverse
    PERFORM _as(U_WOFF);
    SELECT count(*), string_agg(l.kind, ',' ORDER BY l.kind) INTO n, v_txt FROM audit_log(WES, NULL, W0, W1, NULL, 200) l;
    PERFORM _assert(n = 2 AND v_txt = 'access,role', format('db/79 (school): Westville''s office read %s rows: %s', n, v_txt));
    SELECT count(*) INTO n FROM audit_log(HIL, NULL, NULL, NULL, NULL, 200);
    PERFORM _assert(n = 0, format('db/79 (school): Westville''s office read %s of Hilton''s rows', n));

    -- (masked) the children in initials, everywhere; an adult whole
    PERFORM _as(U_OFF);
    SELECT string_agg(row_to_json(l)::text, ' ') INTO v_txt FROM audit_log(HIL, NULL, W0, W1, NULL, 200) l;
    -- (text) first: the reasons name the children, and must be absent for
    -- their own sake before the names are looked for
    PERFORM _assert(v_txt NOT LIKE '%left the school%' AND v_txt NOT LIKE '%briefing%' AND v_txt NOT LIKE '%section 58%',
      format('db/79 (text): a reason reached the log: %s', v_txt));
    PERFORM _assert(v_txt NOT LIKE '%Verify Seventynine%' AND v_txt NOT LIKE '%Seventynine Pupil%',
      format('db/79 (masked): a child is named whole: %s', v_txt));
    SELECT count(*) INTO n FROM audit_log(HIL, NULL, W0, W1, NULL, 200) l
     WHERE (l.kind = 'access' AND l.action = 'Read players' AND l.actor = 'V S Pupil' AND l.subject = 'V S Pupil')
        OR (l.kind = 'access' AND l.action = 'Read users'   AND l.actor = 'V79 Office' AND l.subject = 'V S Pupil')
        OR (l.kind = 'role'    AND l.subject = 'V S Leaver' AND l.actor = 'V79 Office')
        OR (l.kind = 'scoring' AND l.actor = 'V S Pupil' AND l.action = 'Took the scoring pen')
        OR (l.kind = 'duty'    AND l.subject = 'V S Pupil' AND l.actor = 'V79 Office');
    PERFORM _assert(n = 5, format('db/79 (masked): %s of the five rows read as masked: %s', n, v_txt));


    -- (safeguarding) never, for the office or the DSO whose read it was
    SELECT count(*) INTO n FROM audit_log(HIL, ARRAY['access'], NULL, NULL, NULL, 200) l
     WHERE l.detail->>'resource' LIKE 'safeguarding%' OR l.action ILIKE '%safeguarding%';
    PERFORM _assert(n = 0, format('db/79 (safeguarding): the office read %s safeguarding rows', n));
    PERFORM _as(U_DSO);
    k := _v79_reads(U_DSO, HIL);
    SELECT count(*), count(*) FILTER (WHERE l.detail->>'resource' LIKE 'safeguarding%' OR l.action ILIKE '%safeguarding%'),
           count(*) FILTER (WHERE l.kind = 'duty')
      INTO n, k2, k FROM audit_log(HIL, NULL, W0, W1, NULL, 200) l;
    PERFORM _assert(k2 = 0, format('db/79 (safeguarding): the DSO read %s safeguarding rows on the audit log', k2));
    -- (office) the DSO holds audit.read and not the office's key: no suspension
    PERFORM _assert(n = 4 AND k = 0, format('db/79 (office): the DSO read %s rows, %s of them duty suspensions', n, k));
    PERFORM _assert(_v79_reads(U_DSO, HIL) >= 1, 'db/79 (logged): the DSO''s read is not on the record');

    -- (paged) two rows, then the rest strictly older, by (at, key)
    PERFORM _as(U_OFF);
    SELECT array_agg(l.key ORDER BY l.at DESC, l.key DESC), min(l.at) INTO v_keys1, v_at
      FROM audit_log(HIL, NULL, W0, W1, NULL, 2) l;
    SELECT l.key INTO v_key FROM unnest(v_keys1) WITH ORDINALITY l(key, o) ORDER BY o DESC LIMIT 1;
    SELECT array_agg(l.key) INTO v_keys2 FROM audit_log(HIL, NULL, W0, v_at, v_key, 10) l;
    PERFORM _assert(cardinality(v_keys1) = 2 AND cardinality(v_keys2) = 3 AND NOT v_keys1 && v_keys2,
      format('db/79 (paged): page one %s, page two %s', v_keys1, v_keys2));
    SELECT count(*), string_agg(DISTINCT l.kind, ',') INTO n, v_txt FROM audit_log(HIL, ARRAY['role'], W0, W1, NULL, 200) l;
    PERFORM _assert(n = 1 AND v_txt = 'role', format('db/79 (paged): the role filter read %s rows of %s', n, v_txt));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 58

  -- ┌── section 59 · db/80: the audit log shows roles granted (SCRBRD-132 B2) ─
  -- audit_log() lists a role GRANTED beside a role ended (Kameel,
  -- 2026-10-02), under audit.read AND role_assignment's own reader, never a
  -- support hour's assignment, a child in initials. Under the application
  -- role, against _seed_80()'s world at Verify 080 (a school nothing else in
  -- this file touches):
  --   (grant)    the office reads the school's six grants, "Granted a role:
  --              <words> (<team>)", each by whom it was made, keyed
  --              role:<id>:granted; the DSO's appointment among them
  --   (system)   an appointment made by nobody (a seed) has a null actor
  --   (masked)   the pupil and the leaver are "V E Pupil" and "V E Leaver",
  --              never whole; an adult (the coach) is named whole
  --   (detail)   a grant's detail is {role, team} and nothing else: no id
  --   (both)     the role filter shows the leaver's role granted and ended,
  --              the ending under db/79's key, role:<id>
  --   (support)  the support hour is one support row, never also a grant
  --   (gate)     the DSO (audit.read, not the office's key) reads his own
  --              appointment and no other grant; a coach (no audit.read)
  --              reads nothing; Hilton's office reads nothing at Verify 080
  --   (door)     role_assignment_read is still the reader the branch mirrors
  --   (logged)   the office's read is on the record, naming the pupil
  --
  -- Falsified, each once, by replacing audit_log() in the database (as the
  -- owner, inside this file's transaction, before the section ran) with
  -- db/80's body broken in one place; each went red at its own assertion:
  --   (gate)     `(ra.person_id = v_me OR app_can('user.role.assign', ...))`
  --              made `true`: the DSO read every grant
  --   (masked)   the grant's subject taken from app_user.name directly, not
  --              through the person (and so audit_person_label()'s mask)
  --   (support)  the `NOT EXISTS (... support_access ...)` cut dropped
  --   (detail)   the grant's created_by added to its detail
  --   (both)     the ending's key given the grant's suffix, `:ended`
  DECLARE
    ids     jsonb := _seed_80();
    V80     uuid := (ids->>'school')::uuid;
    U_OFF   uuid := (ids->>'u_office')::uuid;
    U_DSO   uuid := (ids->>'u_dso')::uuid;
    U_CO    uuid := (ids->>'u_coach')::uuid;
    U_HIL   uuid := (ids->>'u_hil')::uuid;
    U_PUP   uuid := (ids->>'u_pupil')::uuid;
    A_LEAV  uuid := (ids->>'a_leaver')::uuid;
    A_SUP   uuid := (ids->>'a_support')::uuid;
    k       int;
    k1      int;
    v_txt   text;
  BEGIN
    -- (gate) first, the coach: no audit.read, nothing, his own grant included
    PERFORM _as(U_CO);
    SELECT count(*) INTO n FROM audit_log(V80, NULL, NULL, NULL, NULL, 200);
    PERFORM _assert(n = 0, format('db/80 (gate): a coach read %s rows of the audit log', n));
    -- ...Hilton's office, at Verify 080: nothing
    PERFORM _as(U_HIL);
    SELECT count(*) INTO n FROM audit_log(V80, NULL, NULL, NULL, NULL, 200);
    PERFORM _assert(n = 0, format('db/80 (gate): Hilton''s office read %s of Verify 080''s rows', n));
    SELECT count(*) INTO n FROM audit_log(HIL, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE l.subject LIKE 'V E %' OR (l.subject LIKE 'V80 %' AND l.subject <> 'V80 Hil');
    PERFORM _assert(n = 0, format('db/80 (gate): Hilton''s office read %s of Verify 080''s grants at Hilton', n));
    -- ...the DSO: audit.read without the office's key, so his own appointment
    -- (role_assignment_read admits a person's own row) and no other grant
    PERFORM _as(U_DSO);
    SELECT count(*), string_agg(l.key, ',') INTO n, v_txt FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE l.key LIKE '%:granted';
    PERFORM _assert(n = 1 AND v_txt = 'role:' || (ids->>'a_dso') || ':granted',
      format('db/80 (gate): the DSO read %s grants: %s', n, v_txt));

    -- (door) the reader mirrored is still role_assignment's own
    SELECT string_agg(regexp_replace(p.qual, '\s+', ' ', 'g'), ' | ') INTO v_txt FROM pg_policies p
     WHERE p.schemaname = 'public' AND p.tablename = 'role_assignment' AND p.cmd = 'SELECT' AND p.permissive = 'PERMISSIVE';
    PERFORM _assert(v_txt = '((person_id = app_user_id()) OR app_can(''user.role.assign''::text, school_id, team_code, NULL::uuid, NULL::uuid))',
      format('db/80 (door): role_assignment''s reader is now %s; move audit_log()''s grant gate with it', v_txt));

    -- The office reads Verify 080.
    PERFORM _as(U_OFF);
    k := _v79_reads(U_OFF, V80);
    SELECT string_agg(row_to_json(l)::text, ' ') INTO v_txt FROM audit_log(V80, NULL, NULL, NULL, NULL, 200) l;
    k1 := _v79_reads(U_OFF, V80);
    -- (masked) the children in initials, never whole (the reason names the
    -- leaver too, and must be absent for its own sake)
    PERFORM _assert(v_txt NOT LIKE '%left Verify 080%' AND v_txt NOT LIKE '%support hour%',
      format('db/80 (masked): a reason reached the log: %s', v_txt));
    PERFORM _assert(v_txt NOT LIKE '%Verify Eighty%' AND v_txt NOT LIKE '%Eighty Pupil%' AND v_txt NOT LIKE '%Eighty Leaver%',
      format('db/80 (masked): a child is named whole: %s', v_txt));
    SELECT count(*) INTO n FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE (l.key = 'role:' || (ids->>'a_pupil') || ':granted' AND l.subject = 'V E Pupil' AND l.subject_kind = 'person'
            AND l.actor = 'V80 Office' AND l.action = 'Granted a role: Player (U15A)')
        OR (l.key = 'role:' || (ids->>'a_coach') || ':granted' AND l.subject = 'V80 Coach' AND l.actor = 'V80 Office'
            AND l.action = 'Granted a role: Coach (U15A)');
    PERFORM _assert(n = 2, format('db/80 (masked): %s of the pupil''s and the coach''s grants read as they should: %s', n, v_txt));

    -- (logged) the first read is on the record, once, naming the pupil it named
    PERFORM _assert(k1 = k + 1, format('db/80 (logged): the office''s read left %s access_log rows, not one', k1 - k));
    PERFORM _assert(_v79_reads_naming(U_OFF, U_PUP) >= 1, 'db/80 (logged): the office''s read does not name the pupil it named');
    -- (support) one support row, never a grant
    SELECT count(*) FILTER (WHERE l.kind = 'role' AND l.key LIKE 'role:' || A_SUP || '%'),
           count(*) FILTER (WHERE l.kind = 'support' AND l.key = 'support:' || (ids->>'s_support') || ':began')
      INTO n, k FROM audit_log(V80, ARRAY['role', 'support'], NULL, NULL, NULL, 200) l;
    PERFORM _assert(n = 0 AND k = 1, format('db/80 (support): the support hour reads as %s grants and %s support rows', n, k));
    -- (grant) the school's six, each by whom it was made, the DSO's among them
    SELECT count(*), string_agg(l.subject || '<-' || coalesce(l.actor, '-'), ',' ORDER BY l.subject)
      INTO n, v_txt FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE l.key LIKE 'role:%:granted' AND l.kind = 'role' AND l.action LIKE 'Granted a role: %' AND l.school_id = V80;
    PERFORM _assert(n = 6 AND v_txt = 'V E Leaver<-V80 Office,V E Pupil<-V80 Office,V80 Coach<-V80 Office,'
                                       'V80 Dso<-V80 Principal,V80 Office<--,V80 Principal<--',
      format('db/80 (grant): the office read %s grants: %s', n, v_txt));
    SELECT count(*) INTO n FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE l.key = 'role:' || (ids->>'a_dso') || ':granted' AND l.action = 'Granted a role: Safeguarding Officer';
    PERFORM _assert(n = 1, 'db/80 (grant): the office does not read the DSO''s appointment');
    -- (system) the seed's appointment: nobody made it, and the row says so
    SELECT count(*) INTO n FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE l.key = 'role:' || (ids->>'a_office') || ':granted' AND l.actor IS NULL;
    PERFORM _assert(n = 1, 'db/80 (system): an appointment made by nobody does not read with a null actor');
    -- (detail) {role, team}, nothing else, and no id
    SELECT count(*) INTO n FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l
     WHERE l.key LIKE '%:granted'
       AND (l.detail - 'role' - 'team' <> '{}'::jsonb
            OR l.detail::text ~ '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}');
    PERFORM _assert(n = 0, format('db/80 (detail): %s grants carry more than {role, team}', n));
    -- (both) the leaver's role granted and ended, under the filter "role"
    SELECT string_agg(l.key || '=' || l.action, ' | ' ORDER BY l.key) INTO v_txt
      FROM audit_log(V80, ARRAY['role'], NULL, NULL, NULL, 200) l WHERE l.key LIKE 'role:' || A_LEAV || '%';
    PERFORM _assert(v_txt = 'role:' || A_LEAV || '=Ended a role: Player (U15A) | role:' || A_LEAV || ':granted=Granted a role: Player (U15A)',
      format('db/80 (both): the leaver''s role reads %s', v_txt));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 59
  -- ┌── section 60: sign-up with Google, and an account with no school (db/81, SCRBRD-140) ──
  -- docs/design/SCRBRD-140_signup_and_school_linking.md §4.3 and §9 proof 1.
  -- auth_identity_sign_in() is called as the exchange calls it, with no
  -- identity, after the API has verified Google's token; everything else as
  -- the person or the office, under the application role. _seed_81() builds
  -- its own world (Hilton's and Westville's offices, the platform, two
  -- owner's keys, a parent with one verified link, three pupils, an inactive
  -- account and a departed teacher).
  --
  --   (signup)      an unknown Google account with an unknown address is a
  --                 new account: no school, role 'none', nothing else; again,
  --                 the same account
  --   (nothing)     signed in as it, every table and view the application
  --                 may read answers nothing — but its own app_user row and
  --                 the policy catalogue every signed-out session reads too
  --   (own)         its own sign-ins, never a uid; its own requests only
  --   (d14)         the sixteen reference tables "any signed-in account" read
  --                 answer it nothing, and answer an enrolled person
  --   (grant)       the office grants its request; on the very next
  --                 statement it reads its side, the reference tables, and its
  --                 account has the request's school
  --   (claim)       an address the office enrolled — a parent with one
  --                 verified link, a departed teacher, a deactivated account,
  --                 an owner's key — is claim_required, never linked; asking
  --                 again is the same one claim
  --   (link)        an address on an account that holds and held nothing (an
  --                 onboarding stub) links at once
  --   (stub)        ...and loses the school its unverified asker typed: Hilton's
  --                 office may not issue it a code, still sees and decides its
  --                 request, and the grant files it at Hilton
  --   (office)      who may confirm: the account's office, once, never their
  --                 own, never an owner's key from below; the Claims list
  --   (pupil)       the trigger: a minor whose family has not consented is
  --                 refused by every door; consented, or eighteen, is not
  --   (self)        adding and removing one's own; a uid is one account's
  --   (revoke)      a revoked sign-in, and a deactivated account, sign in to
  --                 nothing
  --   (codes)       the office issues a login code (db/05's function, re-emitted)
  --                 or confirms a claim only for an account whose every standing
  --                 role it could appoint: never the principal, the DSO, another
  --                 school's office or an owner's key; a coach and a parent, yes
  --                 (a pupil's own record counts as granted with `player`, so the
  --                 director of sport issues a pupil's code but not a parent's);
  --                 a superadmin, the owner's key and the DSO; and the seam never
  --                 files a platform-wide account under a school
  --
  -- Falsified once each, the change made in the database as the owner before
  -- this file ran, and red at its own assertion:
  --   app_enrolled() made `SELECT true`            → (nothing) red: sixteen tables
  --                                                   and official_masked answer
  --   the auto-link rule made "link on any email
  --   match of an active account"                   → (claim) red: the parent's
  --                                                   address was linked
  --   the pupil-consent trigger dropped             → (pupil) red: the office
  --                                                   linked a minor without consent
  --   the school seam left out of
  --   decide_role_request()                         → (grant) red: no school
  --   auth_office_refusal() without its may-grant
  --   clause (the old rule: user.invite alone)       → (codes) red: the office
  --                                                   issued itself the principal's code
  --   its platform-wide floor removed (superadmin
  --   no longer required)                            → (office) red: an owner's key
  --                                                   at Hilton answered not_permitted,
  --                                                   not superadmin_only
  --   the rule's statement taken back out of
  --   login_code_issue()                            → (codes) red: the same
  --   the stub's school left as typed on an
  --   automatic link                                → (stub) red: still filed at Hilton
  --   the seam's platform-wide guard removed        → (codes) red: the platform
  --                                                   administrator filed at Hilton
  DECLARE
    ids       jsonb;
    HIL81     uuid := '11111111-1111-1111-1111-111111111111';
    NIL81     uuid := '00000000-0000-0000-0000-000000000000';
    U_OFFICE  uuid; U_WESOFF uuid; U_PLAT81 uuid; U_OWN uuid; U_OWNHIL uuid;
    U_PARENT81 uuid; U_ENDED uuid; U_MINOR uuid; U_PUP uuid; U_ADULT uuid; U_GONE uuid;
    U_NEW     uuid;
    U_STUB    uuid;
    U_HEAD    uuid; U_DSO81 uuid; U_COACH81 uuid;
    v_out     text;
    v_user    uuid;
    v_req     uuid;
    v_claim   uuid;
    v_id      uuid;
    v_how     text;
    k         bigint;
    k2        bigint;
    t         record;
    detail    text;
    u         app_user;
    ai        auth_identity;
    pc        pending_claim;
  BEGIN
    PERFORM set_config('app.user_id', '', true);
    ids := _seed_81();
    U_OFFICE := (ids->>'u_office')::uuid;  U_WESOFF := (ids->>'u_wes')::uuid;
    U_PLAT81 := (ids->>'u_plat')::uuid;    U_OWN := (ids->>'u_own')::uuid;
    U_OWNHIL := (ids->>'u_ownhil')::uuid;  U_PARENT81 := (ids->>'u_parent')::uuid;
    U_ENDED := (ids->>'u_ended')::uuid;    U_MINOR := (ids->>'u_minor')::uuid;
    U_PUP := (ids->>'u_pupil')::uuid;      U_ADULT := (ids->>'u_adult')::uuid;
    U_GONE := (ids->>'u_gone')::uuid;
    U_HEAD := (ids->>'u_head')::uuid;      U_DSO81 := (ids->>'u_dso')::uuid;
    U_COACH81 := (ids->>'u_coach')::uuid;

    -- ── (signup) ──
    SELECT s.outcome, s.user_id INTO v_out, U_NEW
      FROM auth_identity_sign_in('google.com', 'v81-new', 'V81.Newcomer@Example.invalid', '  New   Comer ') s;
    PERFORM _assert(v_out = 'new_account' AND U_NEW IS NOT NULL, format('§60 (signup): a first sign-in answered %s', v_out));
    u := _v81_user(U_NEW);
    PERFORM _assert(u.school_id IS NULL AND u.role = 'none' AND u.email = 'v81.newcomer@example.invalid'
                    AND u.name = 'New Comer' AND u.active AND u.player_id IS NULL,
      format('§60 (signup): the new account is %s', row_to_json(u)));
    ai := _v81_identity('v81-new');
    PERFORM _assert(ai.user_id = U_NEW AND ai.linked_how = 'new_account' AND ai.email_at_link = 'v81.newcomer@example.invalid',
      '§60 (signup): the identity was not written as a new account''s');
    SELECT s.outcome, s.user_id INTO v_out, v_user FROM auth_identity_sign_in('google.com', 'v81-new', 'v81.newcomer@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'signed_in' AND v_user = U_NEW, format('§60 (signup): the second sign-in answered %s %s', v_out, v_user));
    PERFORM _assert((_v81_identity('v81-new')).last_sign_in_at IS NOT NULL, '§60 (signup): the sign-in was not stamped');
    -- Asked inside a session, or with a provider nobody allowed, it answers nothing.
    PERFORM _as(U_OFFICE);
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', 'v81-x', 'v81.x@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'refused', format('§60 (signup): called inside a session it answered %s', v_out));
    PERFORM set_config('app.user_id', '', true);
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('password', 'v81-x', 'v81.x@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'refused', format('§60 (signup): an unknown provider answered %s', v_out));
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', '', 'v81.x@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'refused', format('§60 (signup): an empty uid answered %s', v_out));

    -- ── (nothing) every table and view, as the account with no school ──
    PERFORM _as(U_NEW);
    k := 0; detail := '';
    FOR t IN SELECT c.relname FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
              WHERE ns.nspname = 'public' AND c.relkind IN ('r', 'p', 'v', 'm')
                AND has_table_privilege('scrbrd_app', c.oid, 'SELECT')
                -- its own row, and the policy catalogue (checked against signed-out below)
                AND c.relname NOT IN ('app_user', 'capability', 'role_capability', 'role_grantable')
              ORDER BY 1 LOOP
      EXECUTE format('SELECT count(*) FROM %I', t.relname) INTO k2;
      IF k2 > 0 THEN k := k + k2; detail := detail || format('%s %s; ', t.relname, k2); END IF;
    END LOOP;
    -- (nothing)
    PERFORM _assert(k = 0, format('§60 (nothing): the account with no school read %s rows: %s', k, left(detail, 600)));
    PERFORM _assert(NOT app_enrolled(), '§60 (nothing): a school-less account counts as enrolled');
    SELECT count(*) INTO k FROM app_user;
    PERFORM _assert(k = 1 AND (SELECT id FROM app_user) = U_NEW, format('§60 (nothing): it reads %s app_user rows, not just its own', k));
    SELECT (SELECT count(*) FROM capability) + (SELECT count(*) FROM role_capability) + (SELECT count(*) FROM role_grantable) INTO k;
    PERFORM set_config('app.user_id', '', true);
    SELECT (SELECT count(*) FROM capability) + (SELECT count(*) FROM role_capability) + (SELECT count(*) FROM role_grantable) INTO k2;
    PERFORM _assert(k = k2 AND k > 0, format('§60 (nothing): the catalogue reads %s signed in and %s signed out', k, k2));
    -- The control: the same sweep finds rows for the office, so nothing proved nothing.
    PERFORM _as(U_OFFICE);
    SELECT (SELECT count(*) FROM player) + (SELECT count(*) FROM season) + (SELECT count(*) FROM official) INTO k;
    PERFORM _assert(k > 0, '§60 (nothing): the control read nothing as the office');
    -- The two new tables: no privilege at all, for anybody through the application.
    PERFORM _as(U_NEW);
    BEGIN
      PERFORM 1 FROM auth_identity LIMIT 1;
      PERFORM _assert(false, '§60 (nothing): the application read auth_identity');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      PERFORM 1 FROM pending_claim LIMIT 1;
      PERFORM _assert(false, '§60 (nothing): the application read pending_claim');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- ── (own) ──
    SELECT count(*), min(m.provider), min(m.email_at_link) INTO k, v_out, detail FROM my_sign_ins() m;
    PERFORM _assert(k = 1 AND v_out = 'google.com' AND detail = 'v81.newcomer@example.invalid',
      format('§60 (own): my_sign_ins() answered %s rows', k));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_proc p, unnest(coalesce(p.proargnames, '{}')) a
                                 WHERE p.oid IN ('my_sign_ins()'::regprocedure, 'pending_claims()'::regprocedure,
                                                 'account_sign_ins(uuid)'::regprocedure) AND a ~ 'uid'),
      '§60 (own): a sign-in reader returns the provider uid');
    SELECT count(*) INTO k FROM pending_claims();
    SELECT count(*) INTO k2 FROM account_sign_ins(U_PARENT81);
    PERFORM _assert(k = 0 AND k2 = 0, format('§60 (own): the account with no school read %s claims and %s of another''s sign-ins', k, k2));
    -- It asks for a role at Hilton: its own request, and nothing else it may write.
    INSERT INTO role_request (person_id, role, school_id, team_code, note)
    VALUES (U_NEW, 'coach', HIL81, 'U15A', 'I coach the under-15s on Saturdays.') RETURNING id INTO v_req;
    BEGIN
      INSERT INTO role_request (person_id, role, school_id, team_code) VALUES (U_PARENT81, 'coach', HIL81, 'U15A');
      PERFORM _assert(false, '§60 (own): it asked for a role in somebody else''s name');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id, team_code) VALUES (U_NEW, 'coach', HIL81, 'U15A');
      PERFORM _assert(false, '§60 (own): it appointed itself');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    SELECT count(*), bool_and(person_id = U_NEW) INTO k, v_out FROM role_request;
    PERFORM _assert(k = 1 AND v_out::boolean, format('§60 (own): it reads %s requests, not just its own', k));
    -- The office sees who asked, though the account has no school yet.
    PERFORM _as(U_OFFICE);
    SELECT q.name INTO v_out FROM role_requester(v_req) q;
    PERFORM _assert(v_out = 'New Comer', format('§60 (own): the office cannot see who asked (%s)', v_out));
    PERFORM _as(U_WESOFF);
    SELECT count(*) INTO k FROM role_requester(v_req);
    PERFORM _assert(k = 0, '§60 (own): another school''s office sees who asked at Hilton');

    -- ── (d14) the sixteen, before and after ──
    PERFORM _as(U_OFFICE);
    PERFORM _assert(app_enrolled(), '§60 (d14): the office is not enrolled');
    -- CHANGED BY DESIGN in db/107 (REACH-D5 and the grant note, Kameel 14 Oct
    -- 2026): `official` and `official_accreditation` left this list — the
    -- office no longer reads them (their keeper does; §84) — and with
    -- feature_grant (now app_enrolled_at(school_id)) they left the count
    -- below, which was sixteen.
    FOR t IN SELECT x FROM unnest(ARRAY['season', 'sport', 'feature_flag', 'load_unit',
                                        'bowling_directive', 'clearance_requirement', 'clearance_kind_max_days',
                                        'playing_condition_key', 'rulebook_clause', 'rulebook_clause_age', 'drill',
                                        'sponsor_category']) x LOOP
      EXECUTE format('SELECT count(*) FROM %I', t.x) INTO k;
      PERFORM _assert(k > 0, format('§60 (d14): the office reads no %s, so the narrowing proved nothing', t.x));
    END LOOP;
    SELECT (SELECT count(*) FROM official) + (SELECT count(*) FROM official_accreditation) INTO k;
    PERFORM _assert(k = 0, format('§60 (d14): the office reads %s rows of the officials register (db/107 closed it)', k));
    SELECT string_agg(tablename || '.' || policyname, ', ') INTO detail FROM pg_policies
     WHERE schemaname = 'public' AND coalesce(qual, '') ~ 'app_user_id\(\) IS NOT NULL';
    PERFORM _assert(detail IS NULL, format('§60 (d14): a policy still opens on any signed-in account: %s', detail));
    SELECT count(*) INTO k FROM pg_policies WHERE schemaname = 'public' AND qual ~ 'app_enrolled\(\)';
    PERFORM _assert(k = 13, format('§60 (d14): %s policies read app_enrolled(), expected thirteen (sixteen less db/107''s three)', k));

    -- ── (grant) the office answers; the next statement sees it ──
    SELECT d.ok, d.reason INTO v_ok, v_reason FROM decide_role_request(v_req, true, 'Known to the sportsmaster.', NULL, NULL) d;
    PERFORM _assert(v_ok, format('§60 (grant): the office could not grant the request: %s', v_reason));
    PERFORM _as(U_NEW);
    SELECT count(*) INTO k FROM player WHERE school_id = HIL81;
    PERFORM _assert(k > 0, '§60 (grant): the granted coach reads no Hilton player on the next statement');
    SELECT count(*) INTO k FROM season;
    PERFORM _assert(k > 0 AND app_enrolled(), '§60 (grant): the granted coach still reads no season');
    PERFORM _assert((_v81_user(U_NEW)).school_id = HIL81,
      format('§60 (grant): the account''s school is %s after its first grant', (_v81_user(U_NEW)).school_id));

    -- ── (claim) never linked on an address alone ──
    PERFORM set_config('app.user_id', '', true);
    SELECT s.outcome, s.user_id INTO v_out, v_user FROM auth_identity_sign_in('google.com', 'v81-parent', 'V81.PARENT@example.invalid', 'Mum') s;
    -- (claim)
    PERFORM _assert(v_out = 'claim_required' AND v_user IS NULL,
      format('§60 (claim): a parent''s address answered %s %s', v_out, v_user));
    PERFORM _assert((_v81_identity('v81-parent')).id IS NULL, '§60 (claim): the parent''s address was linked');
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', 'v81-parent', 'v81.parent@example.invalid', 'Mum') s;
    PERFORM _assert(v_out = 'claim_required' AND _v81_open_claims('v81-parent') = 1,
      format('§60 (claim): asking again answered %s with %s open claims', v_out, _v81_open_claims('v81-parent')));
    pc := _v81_claim('v81-parent');
    PERFORM _assert(pc.user_id = U_PARENT81 AND pc.email = 'v81.parent@example.invalid', '§60 (claim): the claim names the wrong account');
    FOR t IN SELECT * FROM (VALUES ('v81-ended', 'v81.ended@example.invalid', 'a departed teacher'),
                                   ('v81-gone',  'v81.gone@example.invalid',  'a deactivated account'),
                                   ('v81-own',   'v81.own@example.invalid',   'the owner''s key'),
                                   ('v81-ownhil','v81.ownhil@example.invalid','an owner''s key filed at Hilton'),
                                   ('v81-minor', 'v81.minor@example.invalid', 'a pupil'),
                                   ('v81-pupil', 'v81.pupil@example.invalid', 'a consented pupil'),
                                   ('v81-adult', 'v81.adult@example.invalid', 'a pupil of eighteen')) AS v(uid, email, who) LOOP
      SELECT s.outcome, s.user_id INTO v_out, v_user FROM auth_identity_sign_in('google.com', t.uid, t.email, 'x') s;
      PERFORM _assert(v_out = 'claim_required' AND v_user IS NULL AND (_v81_identity(t.uid)).id IS NULL,
        format('§60 (claim): %s''s address answered %s %s', t.who, v_out, v_user));
    END LOOP;

    -- ── (link) an account holding nothing ──
    PERFORM onboard_request('v81.stub@example.invalid', 'V81 Stub', 'spectator', HIL81, NULL, 'Following the 1st XI.');
    SELECT s.outcome, s.user_id INTO v_out, U_STUB FROM auth_identity_sign_in('google.com', 'v81-stub', 'v81.stub@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'linked' AND U_STUB IS NOT NULL AND (_v81_user(U_STUB)).email = 'v81.stub@example.invalid',
      format('§60 (link): the onboarding stub''s address answered %s', v_out));
    PERFORM _assert((_v81_identity('v81-stub')).linked_how = 'new_account', '§60 (link): the stub''s identity is not new_account');
    -- (stub) the school the unverified asker typed is not kept: no office
    -- reaches the account until a grant files it, and its request stands.
    PERFORM _assert((_v81_user(U_STUB)).school_id IS NULL,
      format('§60 (stub): the auto-linked stub is still filed at %s', (_v81_user(U_STUB)).school_id));
    PERFORM _as(U_OFFICE);
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.stub@example.invalid', md5('v81-code-stub'), 3600) i;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§60 (stub): Hilton''s office issued itself a code for the auto-linked stub: %s %s', v_ok, v_reason));
    SELECT r.id INTO v_req FROM role_request r WHERE r.person_id = U_STUB AND r.state = 'pending';
    SELECT q.name INTO v_out FROM role_requester(v_req) q;
    PERFORM _assert(v_req IS NOT NULL AND v_out = 'V81 Stub',
      format('§60 (stub): Hilton''s office no longer sees the stub''s request (%s, %s)', v_req, v_out));
    SELECT d.ok, d.reason INTO v_ok, v_reason FROM decide_role_request(v_req, true, 'Known to the office.', NULL, NULL) d;
    PERFORM _assert(v_ok AND (_v81_user(U_STUB)).school_id = HIL81,
      format('§60 (stub): deciding the stub''s request answered %s %s and filed it at %s', v_ok, v_reason, (_v81_user(U_STUB)).school_id));
    PERFORM set_config('app.user_id', '', true);
    -- A second Google account with the stub's address is a claim now: it holds a sign-in.
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', 'v81-stub-b', 'v81.stub@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'claim_required', format('§60 (link): a second Google account took the stub''s address: %s', v_out));

    -- ── (office) who confirms, and the list ──
    PERFORM _as(U_OFFICE);
    SELECT string_agg(c.account_email, ',' ORDER BY c.account_email) INTO detail FROM pending_claims() c;
    PERFORM _assert(detail = 'v81.adult@example.invalid,v81.ended@example.invalid,v81.gone@example.invalid,v81.minor@example.invalid,'
                             || 'v81.parent@example.invalid,v81.pupil@example.invalid,v81.stub@example.invalid',
      format('§60 (office): Hilton''s Claims list is %s', detail));
    SELECT c.id INTO v_claim FROM pending_claims() c WHERE c.account_email = 'v81.parent@example.invalid';
    PERFORM _as(U_WESOFF);
    SELECT count(*) INTO k FROM pending_claims();
    SELECT p.reason INTO v_reason FROM pending_claim_confirm(v_claim) p;
    PERFORM _assert(k = 0 AND v_reason = 'not_permitted',
      format('§60 (office): Westville''s office lists %s Hilton claims and confirming one answered %s', k, v_reason));
    PERFORM _as(U_NEW);   -- a coach: no user.invite
    SELECT p.reason INTO v_reason FROM pending_claim_confirm(v_claim) p;
    PERFORM _assert(v_reason = 'not_permitted', format('§60 (office): a coach confirmed a claim: %s', v_reason));
    PERFORM _as(U_OFFICE);
    SELECT p.ok, p.reason INTO v_ok, v_reason FROM pending_claim_confirm(v_claim) p;
    PERFORM _assert(v_ok, format('§60 (office): the office could not confirm the parent''s claim: %s', v_reason));
    ai := _v81_identity('v81-parent');
    PERFORM _assert(ai.user_id = U_PARENT81 AND ai.linked_how = 'office_confirmed' AND ai.linked_by = U_OFFICE,
      '§60 (office): the confirmed identity is not the office''s act on the parent''s account');
    PERFORM _assert((_v81_claim('v81-parent')).resolved_how = 'office_confirmed' AND _v81_log('auth.claim_confirmed', U_PARENT81) = 1,
      '§60 (office): the claim is not closed, or the confirmation is not on the record');
    SELECT p.reason INTO v_reason FROM pending_claim_confirm(v_claim) p;
    PERFORM _assert(v_reason = 'already_resolved', format('§60 (office): a second confirm answered %s', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT s.outcome, s.user_id INTO v_out, v_user FROM auth_identity_sign_in('google.com', 'v81-parent', 'v81.parent@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'signed_in' AND v_user = U_PARENT81, format('§60 (office): after confirming, the parent signs in as %s %s', v_out, v_user));
    -- Declined: the deactivated account's.
    PERFORM _as(U_OFFICE);
    SELECT c.id INTO v_claim FROM pending_claims() c WHERE c.account_email = 'v81.gone@example.invalid';
    SELECT p.ok INTO v_ok FROM pending_claim_decline(v_claim) p;
    PERFORM _assert(v_ok AND (_v81_claim('v81-gone')).resolved_how = 'declined', '§60 (office): the office could not decline a claim');
    -- The owner's keys: never from below.
    SELECT count(*) INTO k FROM pending_claims() c WHERE c.account_email IN ('v81.own@example.invalid', 'v81.ownhil@example.invalid');
    PERFORM _assert(k = 0, '§60 (office): the office lists a claim on an owner''s key');
    SELECT p.reason INTO v_reason FROM pending_claim_confirm((_v81_claim('v81-ownhil')).id) p;
    PERFORM _assert(v_reason = 'superadmin_only', format('§60 (office): Hilton''s office confirmed a sign-in onto an owner''s key filed at Hilton: %s', v_reason));
    SELECT p.reason INTO v_reason FROM pending_claim_confirm((_v81_claim('v81-own')).id) p;
    PERFORM _assert(v_reason = 'not_permitted', format('§60 (office): Hilton''s office confirmed onto the owner''s key: %s', v_reason));
    PERFORM _as(U_PLAT81);
    SELECT p.reason INTO v_reason FROM pending_claim_confirm((_v81_claim('v81-own')).id) p;
    PERFORM _assert(v_reason IN ('not_permitted', 'superadmin_only'), format('§60 (office): the platform confirmed onto the owner''s key: %s', v_reason));
    PERFORM _as(U_OWN);
    SELECT p.reason INTO v_reason FROM pending_claim_confirm((_v81_claim('v81-own')).id) p;
    PERFORM _assert(v_reason = 'cannot_confirm_your_own', format('§60 (office): the owner confirmed his own claim: %s', v_reason));
    SELECT p.ok, p.reason INTO v_ok, v_reason FROM pending_claim_confirm((_v81_claim('v81-ownhil')).id) p;
    PERFORM _assert(v_ok, format('§60 (office): one owner could not confirm a claim on another''s account: %s', v_reason));

    -- ── (pupil) the family's consent, or eighteen ──
    PERFORM _as(U_OFFICE);
    SELECT p.ok, p.reason INTO v_ok, v_reason FROM pending_claim_confirm((_v81_claim('v81-minor')).id) p;
    -- (pupil)
    PERFORM _assert(NOT v_ok AND v_reason = 'pupil_consent_required' AND (_v81_identity('v81-minor')).id IS NULL,
      format('§60 (pupil): the office linked a minor whose family has not consented: %s %s', v_ok, v_reason));
    PERFORM _assert(_v81_open_claims('v81-minor') = 1, '§60 (pupil): the refused claim was closed');
    PERFORM _as(U_MINOR);
    SELECT l.ok, l.reason INTO v_ok, v_reason FROM auth_identity_link_self('google.com', 'v81-minor-b', 'v81.minor.b@example.invalid') l;
    PERFORM _assert(NOT v_ok AND v_reason = 'pupil_consent_required',
      format('§60 (pupil): the minor added a Google account himself: %s %s', v_ok, v_reason));
    PERFORM _as(U_OFFICE);
    SELECT p.ok, p.reason INTO v_ok, v_reason FROM pending_claim_confirm((_v81_claim('v81-pupil')).id) p;
    PERFORM _assert(v_ok, format('§60 (pupil): a consented pupil could not be linked: %s', v_reason));
    SELECT p.ok, p.reason INTO v_ok, v_reason FROM pending_claim_confirm((_v81_claim('v81-adult')).id) p;
    PERFORM _assert(v_ok, format('§60 (pupil): a pupil of eighteen could not be linked: %s', v_reason));

    -- ── (self) adding and removing one's own ──
    PERFORM _as(U_NEW);
    SELECT l.ok, l.reason, l.identity_id, l.linked_how INTO v_ok, v_reason, v_id, v_how
      FROM auth_identity_link_self('google.com', 'v81-new-b', 'v81.newcomer.b@example.invalid') l;
    PERFORM _assert(v_ok AND v_how = 'self_added' AND (_v81_identity('v81-new-b')).linked_by = U_NEW,
      format('§60 (self): adding a second Google account answered %s %s %s', v_ok, v_reason, v_how));
    SELECT l.ok, l.reason INTO v_ok, v_reason FROM auth_identity_link_self('google.com', 'v81-new-b', 'v81.newcomer.b@example.invalid') l;
    PERFORM _assert(v_ok AND v_reason = 'already_linked', format('§60 (self): adding it again answered %s %s', v_ok, v_reason));
    SELECT l.ok, l.reason INTO v_ok, v_reason FROM auth_identity_link_self('google.com', 'v81-parent', 'v81.parent@example.invalid') l;
    PERFORM _assert(NOT v_ok AND v_reason = 'identity_in_use', format('§60 (self): it took the parent''s Google account: %s %s', v_ok, v_reason));
    -- The code path: the departed teacher redeemed the office's code, and adds
    -- the Google account his claim was waiting on.
    PERFORM _as(U_ENDED);
    SELECT l.ok, l.linked_how INTO v_ok, v_how FROM auth_identity_link_self('google.com', 'v81-ended', 'v81.ended@example.invalid') l;
    PERFORM _assert(v_ok AND v_how = 'code' AND (_v81_claim('v81-ended')).resolved_how = 'code',
      format('§60 (self): after a code the teacher''s claim linked as %s', v_how));
    PERFORM set_config('app.user_id', '', true);
    SELECT l.reason INTO v_reason FROM auth_identity_link_self('google.com', 'v81-z', 'v81.z@example.invalid') l;
    PERFORM _assert(v_reason = 'not_signed_in', format('§60 (self): with no session, linking answered %s', v_reason));

    -- ── (revoke) ──
    PERFORM _as(U_NEW);
    SELECT r.ok INTO v_ok FROM auth_identity_revoke_self((_v81_identity('v81-parent')).id) r;
    PERFORM _assert(NOT v_ok, '§60 (revoke): the coach revoked the parent''s sign-in as his own');
    SELECT r.ok INTO v_ok FROM auth_identity_revoke_self(v_id) r;
    PERFORM _assert(v_ok AND (_v81_identity('v81-new-b')).revoked_by = U_NEW, '§60 (revoke): the coach could not remove his own');
    SELECT count(*) FILTER (WHERE m.revoked_at IS NULL), count(*) INTO k, k2 FROM my_sign_ins() m;
    PERFORM _assert(k = 1 AND k2 = 2, format('§60 (revoke): my_sign_ins() shows %s live of %s', k, k2));
    PERFORM _as(U_WESOFF);
    SELECT r.reason INTO v_reason FROM auth_identity_revoke((_v81_identity('v81-parent')).id) r;
    PERFORM _assert(v_reason = 'not_permitted', format('§60 (revoke): Westville''s office revoked a Hilton sign-in: %s', v_reason));
    PERFORM _as(U_OFFICE);
    SELECT count(*) INTO k FROM account_sign_ins(U_PARENT81);
    SELECT r.ok INTO v_ok FROM auth_identity_revoke((_v81_identity('v81-parent')).id) r;
    PERFORM _assert(k = 1 AND v_ok AND _v81_log('auth.identity_revoked', U_PARENT81) = 1,
      format('§60 (revoke): the office read %s of the parent''s sign-ins and revoked %s', k, v_ok));
    PERFORM set_config('app.user_id', '', true);
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', 'v81-new-b', 'v81.newcomer.b@example.invalid', 'x') s;
    SELECT s.outcome INTO v_reason FROM auth_identity_sign_in('google.com', 'v81-parent', 'v81.parent@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'revoked' AND v_reason = 'revoked', format('§60 (revoke): revoked sign-ins answered %s and %s', v_out, v_reason));
    PERFORM _v81_deactivate(U_STUB);
    SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', 'v81-stub', 'v81.stub@example.invalid', 'x') s;
    PERFORM _assert(v_out = 'account_inactive', format('§60 (revoke): a deactivated account''s sign-in answered %s', v_out));

    -- ── (codes) the office becomes only somebody it could appoint ──
    -- login_code_issue() (db/05, re-emitted by db/81) and every door above
    -- ask one rule: the issuer could grant every standing role the account
    -- holds; a platform-wide one, only a superadmin.
    PERFORM _as(U_OFFICE);
    FOR t IN SELECT * FROM (VALUES ('v81.head@example.invalid',   'not_permitted',   'the principal'),
                                   ('v81.dso@example.invalid',    'not_permitted',   'the DSO'),
                                   ('v81.ownhil@example.invalid', 'superadmin_only', 'an owner''s key filed at Hilton'),
                                   ('v81.own@example.invalid',    'not_permitted',   'the owner''s key'),
                                   ('v81.wes@example.invalid',    'not_permitted',   'Westville''s office')) AS v(email, want, who) LOOP
      SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue(t.email, md5('v81-code-' || t.email), 3600) i;
      -- (codes)
      PERFORM _assert(NOT v_ok AND v_reason = t.want,
        format('§60 (codes): Hilton''s office issued itself a code for %s: %s %s (expected %s)', t.who, v_ok, v_reason, t.want));
    END LOOP;
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.coach@example.invalid', md5('v81-code-coach'), 3600) i;
    PERFORM _assert(v_ok, format('§60 (codes): the office could not issue a code to a coach it may appoint: %s', v_reason));
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.parent@example.invalid', md5('v81-code-parent'), 3600) i;
    PERFORM _assert(v_ok, format('§60 (codes): the office could not issue a code to a parent: %s', v_reason));
    -- The director of sport may enrol a pupil (player, and the record that
    -- comes with it) and not appoint a parent. Since db/122 (§1d, Kameel 29
    -- Oct 2026) a pupil's code is the office's alone, the people shown his
    -- address: she is told office_only for his, and not_permitted for the
    -- parent's, as before.
    PERFORM _as((ids->>'u_dos')::uuid);
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.pupil@example.invalid', md5('v81-code-pupil'), 3600) i;
    PERFORM _assert(NOT v_ok AND v_reason = 'office_only',
      format('§60 (codes): the director of sport, since db/122, was answered %s %s for a pupil''s code', v_ok, v_reason));
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.parent@example.invalid', md5('v81-code-parent2'), 3600) i;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§60 (codes): the director of sport issued herself a parent''s code: %s %s', v_ok, v_reason));
    PERFORM _as(U_HEAD);   -- the principal may appoint a DSO
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.dso@example.invalid', md5('v81-code-dso'), 3600) i;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§60 (codes): the principal, holding no user.invite, issued a code: %s %s', v_ok, v_reason));
    PERFORM _as(U_OWN);
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.ownhil@example.invalid', md5('v81-code-ownhil'), 3600) i;
    PERFORM _assert(v_ok, format('§60 (codes): a superadmin could not issue a code to an owner''s key: %s', v_reason));
    SELECT i.ok, i.reason INTO v_ok, v_reason FROM login_code_issue('v81.dso@example.invalid', md5('v81-code-dso2'), 3600) i;
    PERFORM _assert(v_ok, format('§60 (codes): a superadmin could not issue a code to a DSO: %s', v_reason));
    -- Claims follow the same rule.
    PERFORM set_config('app.user_id', '', true);
    FOR t IN SELECT * FROM (VALUES ('v81-head', 'v81.head@example.invalid'), ('v81-dso', 'v81.dso@example.invalid'),
                                   ('v81-coach', 'v81.coach@example.invalid')) AS v(uid, email) LOOP
      SELECT s.outcome INTO v_out FROM auth_identity_sign_in('google.com', t.uid, t.email, 'x') s;
      PERFORM _assert(v_out = 'claim_required', format('§60 (codes): %s answered %s', t.email, v_out));
    END LOOP;
    PERFORM _as(U_OFFICE);
    SELECT string_agg(c.account_email, ',' ORDER BY c.account_email) INTO detail FROM pending_claims() c
     WHERE c.account_email IN ('v81.head@example.invalid', 'v81.dso@example.invalid', 'v81.coach@example.invalid');
    PERFORM _assert(detail = 'v81.coach@example.invalid', format('§60 (codes): Hilton''s Claims list shows %s', detail));
    SELECT p.reason INTO v_reason FROM pending_claim_confirm((_v81_claim('v81-dso')).id) p;
    PERFORM _assert(v_reason = 'not_permitted', format('§60 (codes): the office confirmed a Google sign-in onto the DSO: %s', v_reason));
    SELECT p.reason INTO v_reason FROM pending_claim_confirm((_v81_claim('v81-head')).id) p;
    PERFORM _assert(v_reason = 'not_permitted', format('§60 (codes): the office confirmed a Google sign-in onto the principal: %s', v_reason));
    SELECT p.ok, p.reason INTO v_ok, v_reason FROM pending_claim_confirm((_v81_claim('v81-coach')).id) p;
    PERFORM _assert(v_ok, format('§60 (codes): the office could not confirm a coach''s claim: %s', v_reason));
    -- The seam never files a platform-wide account under a school.
    PERFORM _as(U_PLAT81);
    INSERT INTO role_request (person_id, role, school_id, team_code) VALUES (U_PLAT81, 'coach', HIL81, 'U15A') RETURNING id INTO v_req;
    PERFORM _as(U_OFFICE);
    SELECT d.ok, d.reason INTO v_ok, v_reason FROM decide_role_request(v_req, true, 'Helps with the under-15s.', NULL, NULL) d;
    PERFORM _assert(v_ok AND (_v81_user(U_PLAT81)).school_id IS NULL,
      format('§60 (codes): granting the platform administrator a coaching role filed him at %s (%s %s)',
             (_v81_user(U_PLAT81)).school_id, v_ok, v_reason));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 60
  -- ┌── section 61 · db/82: listing on the home page, and the live read (SCRBRD-142) ──
  -- docs/design/SCRBRD-142_public_home_page.md §1.2–§1.4, §2.2; PUBLIC_DATA
  -- rule 7 as amended (D1a). Two schools, one listing at a time: a fixture is
  -- on the home page when, for at least one side, that side is published AND
  -- its school lists. Signed out (what the API's public read gets) for every
  -- read of public_live_fixtures(); as each school's publisher for every
  -- switch. _seed_82() builds seven fixtures, nothing published or listed.
  --
  --   (default)    nothing is listed until a school lists: no fixture of
  --                _seed_82()'s answers while every side is published
  --   (door)       a coach, and Westville's publisher for Hilton, cannot list
  --   (rows)       §1.4 row by row with Hilton listing: f1 (home lists, home
  --                published), f2 (home lists, both published, away does not
  --                list), f3 (home does not list, the away school lists and
  --                published its side) answer; f4 (neither lists), f5
  --                (listed, nothing published), f6 (the listing school
  --                published nothing of its own) and f7 (yesterday) do not
  --   (both)       Westville lists too: f4 and f6 join
  --   (unlist)     Hilton stops listing: f1 and f3 leave at once; f2 stays,
  --                Westville's own published side and its listing hold it
  --   (withdrawn)  Westville withdraws its side of f2: gone
  --   (card)       f1's row: the schools' names and codes, live, its two
  --                innings with the side that batted each (home, away);
  --                its ground's name appears nowhere in any row
  --   (read)       each school's publisher reads its own switch and not the
  --                other's; a coach reads none
  --
  -- Falsified once each, by replacing public_live_fixtures() in the database
  -- (as the owner, before the verify ran, then restored) and watching the section
  -- go red at its own assertion: the listing test dropped from the away
  -- branch (default: two answered before anyone listed); fixture_side_published() dropped from the home
  -- branch (rows: f5 answered); the day test dropped (rows: f7 answered);
  -- the side lookup dropped (card).
  DECLARE
    ids    jsonb := _seed_82();
    U_WPUB uuid := '88888888-0000-0000-0000-00000000047a';   -- sportsadmin, Westville, school-wide (§25)
    U_C2   uuid := '88888888-0000-0000-0000-00000000000a';   -- 2XI coach, Hilton
    F1 uuid; F2 uuid; F3 uuid; F4 uuid; F5 uuid; F6 uuid; F7 uuid;
    mine   uuid[];
    v_ok boolean; v_reason text; n int; j jsonb; v_list text; v_first uuid;
  BEGIN
    F1 := (ids->>'f1')::uuid; F2 := (ids->>'f2')::uuid; F3 := (ids->>'f3')::uuid; F4 := (ids->>'f4')::uuid;
    F5 := (ids->>'f5')::uuid; F6 := (ids->>'f6')::uuid; F7 := (ids->>'f7')::uuid;
    mine := ARRAY[F1, F2, F3, F4, F5, F6, F7];

    -- Publish as each school's own publisher (fixture_publish(), db/47).
    PERFORM _as(U_SARAH);
    FOREACH v_list IN ARRAY ARRAY[F1::text || ':home', F2::text || ':home', F3::text || ':away', F7::text || ':home'] LOOP
      SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(split_part(v_list, ':', 1)::uuid, split_part(v_list, ':', 2), true) s;
      PERFORM _assert(v_ok, format('§61: Hilton could not publish %s (%s)', v_list, v_reason));
    END LOOP;
    PERFORM _as(U_WPUB);
    FOREACH v_list IN ARRAY ARRAY[F2::text || ':away', F4::text || ':home', F6::text || ':home'] LOOP
      SELECT s.ok, s.reason INTO v_ok, v_reason FROM fixture_publish(split_part(v_list, ':', 1)::uuid, split_part(v_list, ':', 2), true) s;
      PERFORM _assert(v_ok, format('§61: Westville could not publish %s (%s)', v_list, v_reason));
    END LOOP;

    -- (default)
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_live_fixtures() x WHERE x.match_id = ANY (mine);
    PERFORM _assert(n = 0, format('§61 (default): %s fixtures answered with no school listing', n));
    PERFORM _assert((SELECT column_default FROM information_schema.columns
                      WHERE table_schema = 'public' AND table_name = 'public_listing' AND column_name = 'listed') = 'false',
      '§61 (default): a listing row does not default to off');

    -- (door)
    PERFORM _as(U_C2);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_listing_set(HIL, true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§61 (door): a coach listed Hilton (%s %s)', v_ok, v_reason));
    PERFORM _as(U_WPUB);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_listing_set(HIL, true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§61 (door): Westville''s publisher listed Hilton (%s %s)', v_ok, v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_live_fixtures() x WHERE x.match_id = ANY (mine);
    PERFORM _assert(n = 0, format('§61 (door): a refused listing put %s fixtures on the home page', n));

    -- (rows)
    PERFORM _as(U_SARAH);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_listing_set(HIL, true) s;
    PERFORM _assert(v_ok, format('§61 (rows): Hilton''s director of sport could not list (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT string_agg(z.k, ',' ORDER BY z.k) INTO v_list
      FROM (SELECT CASE x.match_id WHEN F1 THEN 'f1' WHEN F2 THEN 'f2' WHEN F3 THEN 'f3' WHEN F4 THEN 'f4'
                                   WHEN F5 THEN 'f5' WHEN F6 THEN 'f6' WHEN F7 THEN 'f7' END AS k
              FROM public_live_fixtures() x WHERE x.match_id = ANY (mine)) z;
    PERFORM _assert(v_list = 'f1,f2,f3', format('§61 (rows): Hilton listing, the home page answers %s (expected f1,f2,f3)', v_list));
    -- Live first.
    SELECT y.match_id INTO v_first FROM public_live_fixtures() y WHERE y.match_id = ANY (mine) LIMIT 1;
    PERFORM _assert(v_first = F1, format('§61 (rows): the live fixture is not first (%s)', v_first));

    -- (both)
    PERFORM _as(U_WPUB);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM public_listing_set(WES, true) s;
    PERFORM _assert(v_ok, format('§61 (both): Westville''s publisher could not list (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT string_agg(z.k, ',' ORDER BY z.k) INTO v_list
      FROM (SELECT CASE x.match_id WHEN F1 THEN 'f1' WHEN F2 THEN 'f2' WHEN F3 THEN 'f3' WHEN F4 THEN 'f4'
                                   WHEN F5 THEN 'f5' WHEN F6 THEN 'f6' WHEN F7 THEN 'f7' END AS k
              FROM public_live_fixtures() x WHERE x.match_id = ANY (mine)) z;
    PERFORM _assert(v_list = 'f1,f2,f3,f4,f6', format('§61 (both): both listing, the home page answers %s', v_list));

    -- (unlist)
    PERFORM _as(U_SARAH);
    SELECT s.ok INTO v_ok FROM public_listing_set(HIL, false) s;
    PERFORM set_config('app.user_id', '', true);
    SELECT string_agg(z.k, ',' ORDER BY z.k) INTO v_list
      FROM (SELECT CASE x.match_id WHEN F1 THEN 'f1' WHEN F2 THEN 'f2' WHEN F3 THEN 'f3' WHEN F4 THEN 'f4'
                                   WHEN F5 THEN 'f5' WHEN F6 THEN 'f6' WHEN F7 THEN 'f7' END AS k
              FROM public_live_fixtures() x WHERE x.match_id = ANY (mine)) z;
    PERFORM _assert(v_ok AND v_list = 'f2,f4,f6', format('§61 (unlist): Hilton unlisted, the home page answers %s', v_list));

    -- (withdrawn)
    PERFORM _as(U_WPUB);
    PERFORM fixture_publish(F2, 'away', false);
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_live_fixtures() x WHERE x.match_id = F2;
    PERFORM _assert(n = 0, '§61 (withdrawn): f2 answered after its only listing school withdrew its side');

    -- (card) Hilton lists again for f1's row.
    PERFORM _as(U_SARAH);
    PERFORM public_listing_set(HIL, true);
    PERFORM set_config('app.user_id', '', true);
    SELECT to_jsonb(x) INTO j FROM public_live_fixtures() x WHERE x.match_id = F1;
    PERFORM _assert(j->>'home_label' = 'Hilton College' AND j->>'home_code' = '1XI'
                    AND j->>'away_label' = 'Verify Eightytwo College 1XI' AND j->>'away_code' IS NULL
                    AND (j->>'away_on_platform')::boolean = false AND j->>'status' = 'live',
      format('§61 (card): f1 reads %s', j));
    PERFORM _assert(jsonb_path_query_array(j->'scores', '$[*].side') = '["home", "away"]'::jsonb
                    AND jsonb_path_query_array(j->'scores', '$[*].runs') = '[4, 1]'::jsonb,
      format('§61 (card): f1''s scores are %s', j->'scores'));
    SELECT count(*) INTO n FROM public_live_fixtures() x WHERE to_jsonb(x)::text ~ 'Gordon Sherwood|ffffffff-0000-0000-0000-000000000001';
    PERFORM _assert(n = 0, format('§61 (card): %s rows carry a ground', n));

    -- (read)
    PERFORM _as(U_WPUB);
    SELECT string_agg(l.school_id::text, ',') INTO v_list FROM public_listing l;
    PERFORM _assert(v_list = WES::text, format('§61 (read): Westville''s publisher reads the switches of %s', v_list));
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM public_listing l WHERE l.school_id = HIL;
    PERFORM _assert(n = 1, '§61 (read): Hilton''s director of sport cannot read her own switch');
    PERFORM _as(U_C2);
    SELECT count(*) INTO n FROM public_listing;
    PERFORM _assert(n = 0, format('§61 (read): a coach reads %s listing switches', n));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 61
  -- ┌── section 62 · db/83: public news on the home page (SCRBRD-142 phase 3) ──
  -- docs/design/SCRBRD-142_public_home_page.md §3, §7 phase 3. A post reaches
  -- the home page when its author asked, a school-wide broadcast.publish
  -- holder at its school who is not the author approved, its words name none
  -- of the school's pupils, it is unchanged since, and the school lists.
  -- Signed out for every read of public_news().
  --
  --   (request)   only the author asks; not a draft, not a competition post;
  --               asked twice is refused
  --   (sod)       the 2XI coach (no broadcast.publish), Westville's publisher
  --               for Hilton's post, and the director of sport for her own
  --               post cannot approve; the table refuses a requester approving
  --   (scan)      a post naming a pupil by full name, by known-as, by his
  --               surname alone or by his first name alone (db/118) is
  --               refused names_pupils with a count — and no name anywhere in
  --               the answer; news_public_check() gives the count to the
  --               author and the school's publishers, and nobody else
  --   (approve)   approved, it is not on the home page until the school
  --               lists; listed, it is, with id, school, team, title, body,
  --               date and nothing else — no author
  --   (edited)    the author edits it: off the home page until asked and
  --               approved again
  --   (withdraw)  Westville's publisher cannot take it down; the director of
  --               sport — who cannot UPDATE the coach's post (db/12) — can
  --   (internal)  the author's own withdrawal (published_at = null) takes it off
  --   (decline)   a request withdrawn by the office is no longer approvable
  --   (read)      requests are read by the author and the school's publishers,
  --               and written only through the doors
  --
  -- Falsified once each, by replacing a function in the database (as the
  -- owner, before the verify ran, then restored) and watching the section go
  -- red at its own assertion: the listing test dropped from public_news()
  -- (approve: on the home page unlisted); known-as dropped from the scan
  -- (scan: the known-as post passed); the digest test dropped from
  -- public_news() (edited: still public after the edit); the author and
  -- requester test dropped from news_public_approve() with the table's CHECK
  -- lifted (sod: she approved her own post — and db/83's $check$ refused to
  -- re-run without the CHECK).
  DECLARE
    U_WPUB uuid := '88888888-0000-0000-0000-00000000047a';   -- sportsadmin, Westville, school-wide (§25)
    U_C2   uuid := '88888888-0000-0000-0000-00000000000a';   -- 2XI coach, Hilton: news.publish.team only
    U_LEAG uuid := '88888888-0000-0000-0000-000000000021';   -- wrote the league notice
    U_DOC  uuid := '88888888-0000-0000-0000-000000000003';   -- news.read, nothing else here
    C_POST uuid := '0c000000-0000-0000-0000-000000000003';   -- the league notice (competition)
    D_POST uuid := '0c000000-0000-0000-0000-000000000004';   -- Sarah's draft
    P1 uuid; P2 uuid; P3 uuid; P4 uuid; P5 uuid; S1 uuid; v_post uuid;
    v_ok boolean; v_reason text; v_names int; n int; j jsonb; v_list text;
  BEGIN
    PERFORM _seed_83();

    PERFORM _as(U_C2);
    -- P1 names no school: since db/118 the boys of the schools Hilton plays are
    -- scanned too, and this file names some of Westville's after their school.
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Second XI through to the final', 'The side won by six wickets on Saturday.', now())
    RETURNING id INTO P1;
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'A hundred on Saturday', 'Well batted, JAMES   whitfield — the first of the season.', now())
    RETURNING id INTO P2;
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Four wickets', 'Bekks took four for twelve.', now())
    RETURNING id INTO P3;
    -- db/118: a surname alone, and a first name alone (James Whitfield has no
    -- known-as), each name one pupil.
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Five for twelve', 'PILLAY bowled beautifully on Saturday.', now())
    RETURNING id INTO P4;
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Well done', 'Well batted, james: the first of the season.', now())
    RETURNING id INTO P5;
    PERFORM _as(U_SARAH);
    INSERT INTO news_post (scope, school_id, title, body, published_at)
    VALUES ('school', HIL, 'Pavilion open on Saturday', 'Teas from three.', now())
    RETURNING id INTO S1;

    -- (request)
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(P1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§62 (request): the director of sport asked for the coach''s post (%s %s)', v_ok, v_reason));
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(D_POST) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_published', format('§62 (request): a draft was asked for (%s %s)', v_ok, v_reason));
    PERFORM _as(U_LEAG);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(C_POST) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'scope_not_public', format('§62 (request): a competition post was asked for (%s %s)', v_ok, v_reason));
    PERFORM _as(U_C2);
    FOREACH v_post IN ARRAY ARRAY[P1, P2, P3, P4, P5] LOOP
      SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(v_post) r;
      PERFORM _assert(v_ok, format('§62 (request): the coach could not ask for %s (%s)', v_post, v_reason));
    END LOOP;
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(P1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'already_requested', format('§62 (request): asked twice (%s %s)', v_ok, v_reason));
    PERFORM _as(U_SARAH);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(S1) r;
    PERFORM _assert(v_ok, format('§62 (request): the director of sport could not ask for her own post (%s)', v_reason));

    -- (sod)
    PERFORM _as(U_C2);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(P1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§62 (sod): the coach approved (%s %s)', v_ok, v_reason));
    PERFORM _as(U_WPUB);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(P1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§62 (sod): Westville''s publisher approved Hilton''s post (%s %s)', v_ok, v_reason));
    PERFORM _as(U_SARAH);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(S1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'own_post', format('§62 (sod): the director of sport approved her own post (%s %s)', v_ok, v_reason));
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'news_post_public_two_people'
                             AND pg_get_constraintdef(oid) ~ 'approved_by <> requested_by'),
      '§62 (sod): the table does not refuse a requester approving');

    -- (scan)
    SELECT r.ok, r.reason, r.names, to_jsonb(r) INTO v_ok, v_reason, v_names, j FROM news_public_approve(P2) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'names_pupils' AND v_names = 1,
      format('§62 (scan): a post naming James Whitfield by full name answered %s %s %s', v_ok, v_reason, v_names));
    PERFORM _assert(j::text !~* 'whitfield|james|aaaaaaaa', format('§62 (scan): the refusal carries a name: %s', j));
    SELECT r.ok, r.reason, r.names INTO v_ok, v_reason, v_names FROM news_public_approve(P3) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'names_pupils' AND v_names = 1,
      format('§62 (scan): a post naming a pupil by his known-as answered %s %s %s', v_ok, v_reason, v_names));
    SELECT r.ok, r.reason, r.names, to_jsonb(r) INTO v_ok, v_reason, v_names, j FROM news_public_approve(P4) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'names_pupils' AND v_names = 1,
      format('§62 (scan): a post naming a pupil by his surname alone answered %s %s %s', v_ok, v_reason, v_names));
    PERFORM _assert(j::text !~* 'pillay|aaaaaaaa', format('§62 (scan): the surname refusal carries a name: %s', j));
    SELECT r.ok, r.reason, r.names INTO v_ok, v_reason, v_names FROM news_public_approve(P5) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'names_pupils' AND v_names = 1,
      format('§62 (scan): a post naming a pupil by his first name alone answered %s %s %s', v_ok, v_reason, v_names));
    PERFORM _assert(news_public_check(P2) = 1 AND news_public_check(P1) = 0, '§62 (scan): the publisher''s check is not 1 and 0');
    PERFORM _as(U_C2);
    PERFORM _assert(news_public_check(P2) = 1, '§62 (scan): the author cannot see his post''s count');
    PERFORM _as(U_DOC);
    PERFORM _assert(news_public_check(P2) IS NULL, '§62 (scan): somebody neither the author nor a publisher read the count');
    PERFORM _as(U_WPUB);
    PERFORM _assert(news_public_check(P2) IS NULL, '§62 (scan): another school''s publisher read the count');

    -- (approve) Hilton not listing first.
    PERFORM _as(U_SARAH);
    PERFORM public_listing_set(HIL, false);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(P1) r;
    PERFORM _assert(v_ok, format('§62 (approve): the director of sport could not approve the coach''s post (%s)', v_reason));
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(P1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'already_public', format('§62 (approve): approved twice (%s %s)', v_ok, v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(n = 0, '§62 (approve): approved, on the home page of a school that does not list');
    PERFORM _as(U_SARAH);
    PERFORM public_listing_set(HIL, true);
    PERFORM set_config('app.user_id', '', true);
    SELECT to_jsonb(x) INTO j FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(j->>'school' = 'Hilton College' AND j->>'team_code' = '2XI' AND j->>'title' = 'Second XI through to the final'
                    AND j->>'published_at' IS NOT NULL,
      format('§62 (approve): listed, the read answers %s', j));
    SELECT string_agg(k, ',' ORDER BY k) INTO v_list FROM jsonb_object_keys(j) k;
    PERFORM _assert(v_list = 'body,id,published_at,school,team_code,title', format('§62 (approve): the read''s columns are %s', v_list));
    PERFORM _assert(strpos(j::text, U_C2::text) = 0, '§62 (approve): the author''s id is in the row');
    SELECT string_agg(CASE x.id WHEN P1 THEN 'p1' WHEN P2 THEN 'p2' WHEN P3 THEN 'p3' WHEN P4 THEN 'p4' WHEN P5 THEN 'p5'
                                WHEN S1 THEN 's1' END, ',') INTO v_list
      FROM public_news(20) x WHERE x.id IN (P1, P2, P3, P4, P5, S1);
    PERFORM _assert(v_list = 'p1', format('§62 (approve): the home page answers %s (only p1 is approved)', v_list));

    -- (edited)
    PERFORM _as(U_C2);
    UPDATE news_post SET body = body || ' Well played, all.' WHERE id = P1;
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(n = 0, '§62 (edited): edited after approval, still on the home page');
    PERFORM _as(U_C2);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(P1) r;
    PERFORM _assert(v_ok, format('§62 (edited): the author could not ask again for the new words (%s)', v_reason));
    PERFORM _as(U_SARAH);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(P1) r;
    PERFORM _assert(v_ok, format('§62 (edited): the new words could not be approved (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(n = 1, '§62 (edited): approved again, not on the home page');

    -- (withdraw)
    PERFORM _as(U_WPUB);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_withdraw(P1) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§62 (withdraw): Westville''s publisher took down Hilton''s post (%s %s)', v_ok, v_reason));
    PERFORM _as(U_SARAH);
    UPDATE news_post SET published_at = NULL WHERE id = P1;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 0, '§62 (withdraw): the director of sport could UPDATE the coach''s post (db/12 is the author''s)');
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_withdraw(P1) r;
    PERFORM _assert(v_ok, format('§62 (withdraw): the director of sport could not take the coach''s post down (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(n = 0, '§62 (withdraw): taken down, still on the home page');

    -- (internal)
    PERFORM _as(U_C2);
    PERFORM news_public_request(P1);
    PERFORM _as(U_SARAH);
    PERFORM news_public_approve(P1);
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(n = 1, '§62 (internal): asked and approved a third time, not on the home page');
    PERFORM _as(U_C2);
    UPDATE news_post SET published_at = NULL WHERE id = P1;
    PERFORM set_config('app.user_id', '', true);
    SELECT count(*) INTO n FROM public_news(20) x WHERE x.id = P1;
    PERFORM _assert(n = 0, '§62 (internal): the author withdrew the notice, still on the home page');

    -- (decline)
    PERFORM _as(U_SARAH);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_withdraw(P3) r;
    PERFORM _assert(v_ok, format('§62 (decline): the office could not decline a request (%s)', v_reason));
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(P3) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_requested', format('§62 (decline): a declined request was approvable (%s %s)', v_ok, v_reason));

    -- (read)
    PERFORM _as(U_C2);
    SELECT count(*) INTO n FROM news_post_public WHERE post_id IN (P1, P2, P3);
    PERFORM _assert(n >= 3, format('§62 (read): the author reads %s of his requests', n));
    SELECT count(*) INTO n FROM news_post_public WHERE post_id = S1;
    PERFORM _assert(n = 0, '§62 (read): the coach reads the director of sport''s request');
    PERFORM _as(U_WPUB);
    SELECT count(*) INTO n FROM news_post_public WHERE school_id = HIL;
    PERFORM _assert(n = 0, format('§62 (read): Westville''s publisher reads %s of Hilton''s requests', n));
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM news_post_public WHERE post_id IN (P1, P2, P3, S1);
    PERFORM _assert(n >= 4, format('§62 (read): Hilton''s director of sport reads %s of its requests', n));
    BEGIN
      INSERT INTO news_post_public (post_id, school_id, requested_by) VALUES (S1, HIL, U_SARAH);
      PERFORM _assert(false, '§62 (read): the application wrote a request directly');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 62
  -- ┌── section 63 · db/84: the database keeps the routes' rules ──
  -- The security review of 2026-10-06 fixed three things in a route; db/84
  -- puts each beneath the route, where every door passes it.
  --
  --   (order)    the school-of-side guard is the FIRST BEFORE row trigger on
  --              match_squad, ahead of the two that name a boy
  --   (owner)    as the owner — no route, no policy — another school's boy
  --              is refused 42501 for either side, in words that name
  --              nobody; his own school's boy goes in; an away side that is
  --              no school on SCRBRD is refused before anything names him; a
  --              withdrawn row passes, and un-withdrawing it does not; moving
  --              a boy to the other side is an UPDATE and is refused
  --   (route)    as Hilton's director of sport (team.select) under RLS, with
  --              the route's gate bypassed: Westville's registered adult is
  --              refused, and Westville's unregistered minor is refused
  --              without his name or his consent state
  --   (news)     the author cannot move his post to another school, another
  --              side, or widen it to the school; he can still edit it and
  --              withdraw it; the byline may be cleared (ON DELETE SET NULL)
  --              and never moved
  --   (asked)    a request filed signed out (POST /api/onboard) is marked;
  --              Google linking the stub does not clear the mark; a request
  --              filed signed out AFTER linking is marked; the person's own,
  --              signed in, is not; the mark cannot be changed by its person
  --
  -- Falsified once each, by disabling the trigger (as the owner, before the
  -- verify ran, then re-enabled) and watching the section go red at its own
  -- assertion: match_squad_00_school_of_side (order); news_post_anchor_frozen
  -- (news: moved to Westville); role_request_asked_unverified (asked: the
  -- signed-out request is not marked).
  DECLARE
    U_C2        uuid := '88888888-0000-0000-0000-00000000000a';  -- 2XI coach, Hilton: news.publish.team
    P_HIL_ADULT uuid := 'aaaaaaaa-0000-0000-0000-000000000003';  -- Hilton 1XI, past eighteen
    F_BOTH uuid; F_TYPED uuid; v_post uuid; v_stub uuid; R1 uuid; R2 uuid; R3 uuid;
    v_got text; v_out text; n int; j jsonb; v_order text[];
  BEGIN
    j := _seed_84();
    F_BOTH := (j->>'both')::uuid; F_TYPED := (j->>'typed')::uuid;

    -- (order)
    v_order := _v84_squad_trigger_order();
    PERFORM _assert(v_order[1] = 'match_squad_00_school_of_side',
      format('§63 (order): the first BEFORE row trigger on match_squad is %s', v_order[1]));
    PERFORM _assert(v_order @> ARRAY['match_squad_is_age_eligible', 'match_squad_is_registered', 'match_squad_side_is_real'],
      format('§63 (order): the db/08 squad triggers are not all there: %s', v_order));

    -- (owner)
    v_got := _v84_pick(F_BOTH, P_WES2, 'home');
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (owner): Westville''s adult on Hilton''s side answered %s', v_got));
    PERFORM _assert(v_got !~* 'botha|mkhize|westville|registered|january|bbbbbbbb',
      format('§63 (owner): the refusal says who he is: %s', v_got));
    v_got := _v84_pick(F_BOTH, P_WES, 'home');
    PERFORM _assert(v_got LIKE '42501:%' AND v_got !~* 'mkhize|registered|consent|bbbbbbbb',
      format('§63 (owner): Westville''s unregistered minor on Hilton''s side answered %s', v_got));
    v_got := _v84_pick(F_BOTH, P_HIL_ADULT, 'away');
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (owner): Hilton''s boy on Westville''s side answered %s', v_got));
    v_got := _v84_pick(F_BOTH, P_HIL_ADULT, 'home');
    PERFORM _assert(v_got = 'ok', format('§63 (owner): Hilton''s own adult could not be named for Hilton (%s)', v_got));
    v_got := _v84_pick(F_BOTH, P_WES2, 'away');
    PERFORM _assert(v_got = 'ok', format('§63 (owner): Westville''s own adult could not be named for Westville (%s)', v_got));
    v_got := _v84_pick(F_BOTH, P_HIL_ADULT, 'away');
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (owner): moving Hilton''s boy to the away side answered %s', v_got));
    v_got := _v84_pick(F_TYPED, P_HIL_ADULT, 'away');
    PERFORM _assert(v_got LIKE '23514:%not a school on SCRBRD%' AND v_got !~* 'naidoo|aaaaaaaa',
      format('§63 (owner): a typed away side answered %s', v_got));
    v_got := _v84_pick(F_BOTH, P_WES, 'home', true);
    PERFORM _assert(v_got = 'ok', format('§63 (owner): a withdrawn row was refused (%s)', v_got));
    v_got := _v84_pick(F_BOTH, P_WES, 'home', false);
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (owner): un-withdrawing Westville''s boy on Hilton''s side answered %s', v_got));

    -- (route) the API's gate is not here: this is the database alone.
    PERFORM _as(U_SARAH);
    BEGIN
      INSERT INTO match_squad (match_id, player_id, side) VALUES (F_BOTH, P_WES2, 'home')
      ON CONFLICT (match_id, player_id) DO UPDATE SET side = 'home', withdrawn = false;
      v_got := 'ok';
    EXCEPTION WHEN OTHERS THEN v_got := SQLSTATE || ': ' || SQLERRM;
    END;
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (route): Hilton''s director of sport put Westville''s adult on her side (%s)', v_got));
    BEGIN
      INSERT INTO match_squad (match_id, player_id, side) VALUES (F_TYPED, P_WES, 'home');
      v_got := 'ok';
    EXCEPTION WHEN OTHERS THEN v_got := SQLSTATE || ': ' || SQLERRM;
    END;
    PERFORM _assert(v_got LIKE '42501:%' AND v_got !~* 'mkhize|registered|consent|bbbbbbbb',
      format('§63 (route): Westville''s minor, posted by Hilton, answered %s', v_got));
    PERFORM set_config('app.user_id', '', true);

    -- (news)
    PERFORM _as(U_C2);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Nets on Thursday', 'Nets at four, whites please.', now())
    RETURNING id INTO v_post;
    BEGIN
      UPDATE news_post SET school_id = WES WHERE id = v_post;
      GET DIAGNOSTICS n = ROW_COUNT;
      v_got := 'ok ' || n;
    EXCEPTION WHEN OTHERS THEN v_got := SQLSTATE || ': ' || SQLERRM;
    END;
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (news): the author moved his post to Westville (%s)', v_got));
    BEGIN
      UPDATE news_post SET team_code = '1XI' WHERE id = v_post;
      GET DIAGNOSTICS n = ROW_COUNT;
      v_got := 'ok ' || n;
    EXCEPTION WHEN OTHERS THEN v_got := SQLSTATE || ': ' || SQLERRM;
    END;
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (news): the author moved his post to another side (%s)', v_got));
    BEGIN
      UPDATE news_post SET scope = 'school', team_code = NULL WHERE id = v_post;
      GET DIAGNOSTICS n = ROW_COUNT;
      v_got := 'ok ' || n;
    EXCEPTION WHEN OTHERS THEN v_got := SQLSTATE || ': ' || SQLERRM;
    END;
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (news): the author widened his team post to the school (%s)', v_got));
    UPDATE news_post SET title = 'Nets on Friday', body = 'Nets at four on Friday instead.' WHERE id = v_post;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, '§63 (news): the author can no longer edit his post');
    UPDATE news_post SET published_at = NULL WHERE id = v_post;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, '§63 (news): the author can no longer withdraw his post');
    PERFORM set_config('app.user_id', '', true);
    v_got := _v84_set_author(v_post, U_SARAH);
    PERFORM _assert(v_got LIKE '42501:%', format('§63 (news): the byline moved to somebody else (%s)', v_got));
    v_got := _v84_set_author(v_post, NULL);
    PERFORM _assert(v_got = 'ok', format('§63 (news): the byline could not be cleared, as ON DELETE SET NULL does (%s)', v_got));

    -- (asked) signed out, as POST /api/onboard calls it.
    PERFORM set_config('app.user_id', '', true);
    R1 := onboard_request('v84.stub@example.invalid', 'V84 Stub', 'coach', HIL, 'U14A', 'I help with the under-14s.');
    j := _v84_request(R1);
    PERFORM _assert((j->>'asked_unverified')::boolean IS TRUE, format('§63 (asked): a request filed signed out is not marked: %s', j));
    SELECT s.outcome, s.user_id INTO v_out, v_stub
      FROM auth_identity_sign_in('google.com', 'v84-stub-uid', 'v84.stub@example.invalid', 'V84 Stub') s;
    PERFORM _assert(v_out = 'linked' AND v_stub = _v84_user_by_email('v84.stub@example.invalid'),
      format('§63 (asked): the stub was not linked by Google (%s)', v_out));
    j := _v84_request(R1);
    PERFORM _assert((j->>'asked_unverified')::boolean IS TRUE AND j->>'state' = 'pending',
      format('§63 (asked): linking the stub cleared the mark: %s', j));
    R2 := onboard_request('v84.stub@example.invalid', 'Somebody Else', 'coach', HIL, 'U15A', NULL);
    j := _v84_request(R2);
    PERFORM _assert(j->>'person_id' = v_stub::text AND (j->>'asked_unverified')::boolean IS TRUE,
      format('§63 (asked): a request filed signed out for a linked account is not marked: %s', j));
    PERFORM _as(v_stub);
    INSERT INTO role_request (person_id, role, school_id, team_code) VALUES (v_stub, 'coach', HIL, 'U16A')
    RETURNING id INTO R3;
    j := _v84_request(R3);
    PERFORM _assert((j->>'asked_unverified')::boolean IS FALSE, format('§63 (asked): his own request, signed in, is marked: %s', j));
    -- Withdrawing is the one update he makes; it does not clear the mark.
    UPDATE role_request SET state = 'withdrawn', asked_unverified = false WHERE id = R2;
    GET DIAGNOSTICS n = ROW_COUNT;
    j := _v84_request(R2);
    PERFORM _assert(n = 1 AND j->>'state' = 'withdrawn' AND (j->>'asked_unverified')::boolean IS TRUE,
      format('§63 (asked): the requester cleared the mark (%s rows): %s', n, j));
    -- The office reads the mark where it reads the request.
    PERFORM _as(U_SARAH);
    SELECT count(*) INTO n FROM role_request r WHERE r.id = R1 AND (to_jsonb(r)->>'asked_unverified')::boolean;
    PERFORM _assert(n = 1, '§63 (asked): Hilton''s director of sport cannot read the mark on the stub''s request');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 63

  -- ┌── 64 · A session ends when it is ended (db/85, GA-I03) ──────────
  -- Everything below as the application role, through app_session_begin()
  -- — the one call the API makes to become somebody — and the db/85 doors:
  --
  --   (mint)       with no identity, a session for an active account; none
  --                for an inactive one; signed in, only for yourself
  --   (begin)      a live session sets app.user_id and app.device_id; the
  --                wrong device, a session never issued, or the wrong epoch
  --                is 28000 session_revoked, and the identity is not set
  --   (anon)       no person: the empty identity, as before
  --   (signed_out) auth_sign_out() ends this device's sessions, not another
  --                device's
  --   (everywhere) auth_sign_out_everywhere() bumps the epoch: every older
  --                session is refused; a session minted after it works
  --   (disable)    the office (account_set_active) disables the account:
  --                every session refused, no new one minted; never your own;
  --                not by a coach or another school's office; enabling
  --                brings nothing back, a fresh session works
  --   (update)     the plain-UPDATE door (no function, the owner) ends
  --                sessions just the same: the rule is a trigger
  --   (sign-in)    removing a Google sign-in ends the account's sessions
  --   (pad)        a pad credential begins while live, for a live account;
  --                disabling the account and signing out everywhere end it,
  --                with the reason on the row
  --   (server)     the server acting as a person: active only
  --   (privilege)  the application reads neither table and cannot bump
  --
  -- Falsified, as the owner before the verify ran: with the
  -- auth_account_disabled trigger disabled, (disable) went red at "the epoch
  -- row says"; with both epoch comparisons taken out of app_session_begin(),
  -- (begin) went red at "a session began under an epoch it was not minted
  -- in". Each restored, and green again.
  DECLARE
    U_C       uuid := '88888888-0000-0000-0000-000000000004';  -- coach of 1XI
    s1 uuid; s2 uuid; s3 uuid; s4 uuid; s5 uuid; c1 uuid; c2 uuid; v_id uuid;
    e0 int; e1 int; e2 int;
    v_got text; n int; j jsonb;
  BEGIN
    -- (anon)
    v_got := _v85_begin(NULL, NULL, NULL, NULL);
    PERFORM _assert(v_got = 'ok::', format('§64 (anon): nobody did not set the empty identity (%s)', v_got));

    -- (mint)
    e0 := (_v85_state(U_PARENT)->>'epoch')::int;
    SELECT o.session_id, o.epoch INTO s1, e1 FROM auth_session_open(U_PARENT, 'v85-phone', 1800) o;
    PERFORM _assert(s1 IS NOT NULL AND e1 = e0, format('§64 (mint): no session minted for an active account (%s, epoch %s of %s)', s1, e1, e0));
    PERFORM _v85_set_active(U_BURSAR, false);
    SELECT o.session_id INTO v_id FROM auth_session_open(U_BURSAR, 'v85-phone', 1800) o;
    PERFORM _assert(v_id IS NULL, '§64 (mint): a session was minted for an inactive account');
    PERFORM _v85_set_active(U_BURSAR, true);
    PERFORM _as(U_REGISTRAR);
    SELECT o.session_id INTO v_id FROM auth_session_open(U_PARENT, 'v85-phone', 1800) o;
    PERFORM _assert(v_id IS NULL, '§64 (mint): a signed-in person minted a session for somebody else');
    PERFORM set_config('app.user_id', '', true);

    -- (begin)
    v_got := _v85_begin(U_PARENT, 'v85-phone', s1, e1);
    PERFORM _assert(v_got = 'ok:' || U_PARENT || ':v85-phone', format('§64 (begin): a live session did not begin (%s)', v_got));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-other-phone', s1, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (begin): a session began on another device (%s)', v_got));
    v_got := _v85_begin(U_PARENT, 'v85-phone', gen_random_uuid(), e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (begin): a session never issued began (%s)', v_got));
    v_got := _v85_begin(U_COACH, 'v85-phone', s1, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (begin): the parent''s session began as the coach (%s)', v_got));
    v_got := _v85_begin(U_PARENT, 'v85-phone', s1, e1 + 1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (begin): a session began under an epoch it was not minted in (%s)', v_got));
    PERFORM _assert(app_user_id() IS NULL, '§64 (begin): a refused session left an identity behind');

    -- (signed_out)
    SELECT o.session_id INTO s2 FROM auth_session_open(U_PARENT, 'v85-laptop', 1800) o;
    PERFORM _v85_begin(U_PARENT, 'v85-phone', s1, e1);
    n := auth_sign_out();
    PERFORM _assert(n = 1, format('§64 (signed_out): the phone''s sign-out ended %s sessions (expected 1)', n));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-phone', s1, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (signed_out): the signed-out session still began (%s)', v_got));
    v_got := _v85_begin(U_PARENT, 'v85-laptop', s2, e1);
    PERFORM _assert(v_got LIKE 'ok:%', format('§64 (signed_out): the laptop was signed out with the phone (%s)', v_got));

    -- (everywhere)
    SELECT o.ok, o.epoch INTO STRICT v_got, e2 FROM auth_sign_out_everywhere() o;
    PERFORM _assert(v_got = 'true' AND e2 = e1 + 1, format('§64 (everywhere): signing out everywhere answered %s, epoch %s (expected %s)', v_got, e2, e1 + 1));
    j := _v85_state(U_PARENT);
    PERFORM _assert(j->>'reason' = 'signed_out_everywhere' AND (j->>'by')::uuid = U_PARENT, format('§64 (everywhere): the epoch row says %s', j));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-laptop', s2, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (everywhere): a session from before still began (%s)', v_got));
    v_got := _v85_begin(U_PARENT, 'v85-laptop', s2, e2);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (everywhere): an old session claiming the new epoch began (%s)', v_got));
    SELECT o.session_id, o.epoch INTO s3, e1 FROM auth_session_open(U_PARENT, 'v85-phone', 1800) o;
    v_got := _v85_begin(U_PARENT, 'v85-phone', s3, e1);
    PERFORM _assert(e1 = e2 AND v_got LIKE 'ok:%', format('§64 (everywhere): a session minted after it did not begin (%s, epoch %s)', v_got, e1));

    -- (disable)
    PERFORM _as(U_REGISTRAR);
    SELECT o.reason INTO v_got FROM account_set_active(U_REGISTRAR, false, 'Verify 085: a phone lost on tour') o;
    PERFORM _assert(v_got = 'cannot_disable_yourself', format('§64 (disable): the office disabled itself (%s)', v_got));
    PERFORM _as(U_C);
    SELECT o.reason INTO v_got FROM account_set_active(U_PARENT, false, 'Verify 085: a phone lost on tour') o;
    PERFORM _assert(v_got = 'not_permitted', format('§64 (disable): a coach disabled a parent (%s)', v_got));
    PERFORM _as(U_WES_ADM);
    SELECT o.reason INTO v_got FROM account_set_active(U_PARENT, false, 'Verify 085: a phone lost on tour') o;
    PERFORM _assert(v_got = 'not_permitted', format('§64 (disable): Westville''s office disabled Hilton''s parent (%s)', v_got));
    PERFORM _assert((_v85_state(U_PARENT)->>'active')::boolean, '§64 (disable): a refused disable disabled the account');
    PERFORM _as(U_REGISTRAR);
    SELECT o.ok::text || ':' || o.active::text INTO v_got FROM account_set_active(U_PARENT, false, 'Verify 085: a phone lost on tour') o;
    PERFORM _assert(v_got = 'true:false', format('§64 (disable): Hilton''s office could not disable its parent (%s)', v_got));
    j := _v85_state(U_PARENT);
    PERFORM _assert(j->>'reason' = 'account_disabled' AND (j->>'epoch')::int = e2 + 1 AND (j->>'by')::uuid = U_REGISTRAR,
      format('§64 (disable): the epoch row says %s', j));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-phone', s3, e2);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (disable): a disabled account''s session began (%s)', v_got));
    SELECT o.session_id INTO v_id FROM auth_session_open(U_PARENT, 'v85-phone', 1800) o;
    PERFORM _assert(v_id IS NULL, '§64 (disable): a disabled account was minted a session');
    PERFORM _as(U_REGISTRAR);
    SELECT o.ok::text || ':' || o.active::text INTO v_got FROM account_set_active(U_PARENT, true, 'Verify 085: the phone was found') o;
    PERFORM _assert(v_got = 'true:true', format('§64 (disable): Hilton''s office could not enable its parent (%s)', v_got));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-phone', s3, e2);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (disable): enabling brought an old session back (%s)', v_got));
    -- The owner's key may do what the office may.
    PERFORM _as(U_OWNER);
    SELECT o.ok::text || ':' || o.active::text INTO v_got FROM account_set_active(U_PARENT, false, 'Verify 085: a phone lost on tour') o;
    PERFORM _assert(v_got = 'true:false', format('§64 (disable): the owner could not disable a parent (%s)', v_got));
    SELECT o.ok::text || ':' || o.active::text INTO v_got FROM account_set_active(U_PARENT, true, 'Verify 085: the phone was found') o;
    PERFORM _assert(v_got = 'true:true', format('§64 (disable): the owner could not enable a parent (%s)', v_got));
    PERFORM set_config('app.user_id', '', true);
    SELECT o.session_id, o.epoch INTO s4, e1 FROM auth_session_open(U_PARENT, 'v85-phone', 1800) o;
    v_got := _v85_begin(U_PARENT, 'v85-phone', s4, e1);
    PERFORM _assert(v_got LIKE 'ok:%', format('§64 (disable): a fresh session after enabling did not begin (%s)', v_got));

    -- (update)
    PERFORM _v85_set_active(U_PARENT, false);
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-phone', s4, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (update): a plain UPDATE left the session working (%s)', v_got));
    PERFORM _v85_set_active(U_PARENT, true);
    v_got := _v85_begin(U_PARENT, 'v85-phone', s4, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (update): the session came back with the account (%s)', v_got));
    PERFORM _assert((_v85_state(U_PARENT)->>'reason') = 'account_disabled' AND (_v85_state(U_PARENT)->>'epoch')::int = e1 + 1,
      format('§64 (update): the plain UPDATE did not bump the epoch: %s', _v85_state(U_PARENT)));

    -- (sign-in)
    v_id := _v85_identity(U_PARENT);
    SELECT o.session_id, o.epoch INTO s5, e1 FROM auth_session_open(U_PARENT, 'v85-phone', 1800) o;
    PERFORM _v85_begin(U_PARENT, 'v85-phone', s5, e1);
    SELECT o.ok::text INTO v_got FROM auth_identity_revoke_self(v_id) o;
    PERFORM _assert(v_got = 'true', format('§64 (sign-in): the parent could not remove his Google sign-in (%s)', v_got));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, 'v85-phone', s5, e1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (sign-in): a session from before the removal still began (%s)', v_got));
    PERFORM _assert((_v85_state(U_PARENT)->>'reason') = 'sign_in_removed', format('§64 (sign-in): the epoch row says %s', _v85_state(U_PARENT)));

    -- (pad)
    c1 := _v85_pad(U_SCORER, 'v85-pad-1');
    v_got := _v85_begin(U_SCORER, 'v85-pad-1', NULL, NULL, c1);
    PERFORM _assert(v_got LIKE 'ok:%', format('§64 (pad): a live credential did not begin (%s)', v_got));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_SCORER, 'v85-pad-2', NULL, NULL, c1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (pad): a credential began on another device (%s)', v_got));
    PERFORM _as(U_REGISTRAR);
    SELECT o.ok::text INTO v_got FROM account_set_active(U_SCORER, false, 'Verify 085: a phone lost on tour') o;
    PERFORM _assert(v_got = 'true', format('§64 (pad): Hilton''s office could not disable its scorer (%s)', v_got));
    PERFORM _assert(_v85_pad_reason(c1) = 'account_disabled', format('§64 (pad): the credential reads %s after the account was disabled', _v85_pad_reason(c1)));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_SCORER, 'v85-pad-1', NULL, NULL, c1);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (pad): a disabled scorer''s credential began (%s)', v_got));
    PERFORM _as(U_REGISTRAR);
    PERFORM account_set_active(U_SCORER, true, 'Verify 085: the phone was found');
    PERFORM _assert(_v85_pad_reason(c1) = 'account_disabled', '§64 (pad): enabling the account brought the credential back');
    c2 := _v85_pad(U_SCORER, 'v85-pad-2');
    PERFORM _as(U_SCORER);
    PERFORM auth_sign_out_everywhere();
    PERFORM _assert(_v85_pad_reason(c2) = 'signed_out_everywhere', format('§64 (pad): signing out everywhere left the credential %s', _v85_pad_reason(c2)));
    PERFORM set_config('app.user_id', '', true);
    -- A pad's own request cannot sign out everywhere.
    c2 := _v85_pad(U_SCORER, 'v85-pad-3');
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.scope', 'pad', true);
    SELECT o.reason INTO v_got FROM auth_sign_out_everywhere() o;
    PERFORM set_config('app.scope', '', true);
    PERFORM _assert(v_got = 'not_permitted' AND _v85_pad_reason(c2) = 'live', format('§64 (pad): a credential signed out everywhere (%s)', v_got));

    -- (server)
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, NULL, NULL, NULL);
    PERFORM _assert(v_got LIKE 'ok:%', format('§64 (server): the server could not act as an active account (%s)', v_got));
    PERFORM _v85_set_active(U_PARENT, false);
    PERFORM set_config('app.user_id', '', true);
    v_got := _v85_begin(U_PARENT, NULL, NULL, NULL);
    PERFORM _assert(v_got = '28000: session_revoked', format('§64 (server): the server acted as a disabled account (%s)', v_got));
    PERFORM _v85_set_active(U_PARENT, true);

    -- (privilege)
    PERFORM _as(U_OWNER);
    v_got := _v85_try('SELECT count(*) FROM auth_session');
    PERFORM _assert(v_got = '42501', format('§64 (privilege): the application read auth_session (%s)', v_got));
    v_got := _v85_try('SELECT count(*) FROM auth_epoch');
    PERFORM _assert(v_got = '42501', format('§64 (privilege): the application read auth_epoch (%s)', v_got));
    v_got := _v85_try(format('UPDATE auth_epoch SET epoch = 1 WHERE user_id = %L', U_PARENT));
    PERFORM _assert(v_got = '42501', format('§64 (privilege): the application wrote auth_epoch (%s)', v_got));
    v_got := _v85_try(format('SELECT auth_epoch_bump(%L, %L)', U_PARENT, 'signed_out_everywhere'));
    PERFORM _assert(v_got = '42501', format('§64 (privilege): the application bumped an epoch directly (%s)', v_got));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 64

  -- ┌── 65 · A platform role belongs to no school (db/86) ─────────────
  -- Kameel, 2026-10-07: "a super admin role isn't attached to any school
  -- and shouldn't be." The RBAC diagnosis that day found POST /api/users
  -- answering 200 to the platform account for a platformadmin at Westville,
  -- and to the owner for a superadmin there. Everything below as the
  -- application role unless it says the owner:
  --
  --   (enrol)    enrol_person(), POST /api/users's door: the platform account
  --              asking for a platformadmin at Westville and at Hilton, the
  --              owner for a superadmin and a platformadmin at Westville —
  --              each answered platform_role_needs_no_school, with no
  --              account, request or appointment left behind
  --   (decide)   a request for a platform role at a school, filed signed out:
  --              the platform account's grant is refused by name and the
  --              request stays pending; declining it still works
  --   (policy)   the INSERT through role_assignment_write, as the platform
  --              account and as the owner, at a school: 23514, by name
  --   (owner)    as the table owner, past every policy, live or ended: the
  --              same
  --   (still)    tenant-less still works where it did: the platform account
  --              appoints a platformadmin and the owner a superadmin through
  --              the policy; the owner's own SQL (the seed, bootstrap.mjs)
  --              writes both; the seed's two keys are live; an ordinary role
  --              at a school still enrols
  --   (record)   nothing on the record breaks the rule, the constraint is
  --              validated, and the roles carrying a platform-only capability
  --              are exactly the two it names
  --
  -- Falsified: against a database at db/85 (no db/86), the section goes red
  -- at its first assertion, "(enrol): the platform account was answered
  -- ok:" — the 200 the diagnosis found.
  DECLARE
    v_ok boolean; v_reason text; v_asg uuid; v_req uuid; v_got text;
    v_p1 uuid; v_p2 uuid; v_p3 uuid; v_p4 uuid; v_p5 uuid;
  BEGIN
    -- (enrol)
    PERFORM _as(U_PLAT);
    SELECT e.ok, e.reason INTO v_ok, v_reason
      FROM enrol_person('v86.plat.wes@example.invalid', 'V86 Platwes', 'platformadmin', WES, NULL, NULL, NULL) e;
    PERFORM _assert(v_ok IS FALSE AND v_reason = 'platform_role_needs_no_school',
      format('§65 (enrol): the platform account was answered %s:%s for a platformadmin at Westville', v_ok, v_reason));
    PERFORM _assert(_v86_left('v86.plat.wes@example.invalid') = '0/0/0',
      format('§65 (enrol): the refusal left %s behind (accounts/requests/appointments)', _v86_left('v86.plat.wes@example.invalid')));
    SELECT e.ok, e.reason INTO v_ok, v_reason
      FROM enrol_person('v86.plat.hil@example.invalid', 'V86 Plathil', 'platformadmin', HIL, NULL, NULL, NULL) e;
    PERFORM _assert(v_ok IS FALSE AND v_reason = 'platform_role_needs_no_school',
      format('§65 (enrol): the platform account was answered %s:%s for a platformadmin at Hilton', v_ok, v_reason));
    PERFORM _as(U_OWNER);
    SELECT e.ok, e.reason INTO v_ok, v_reason
      FROM enrol_person('v86.own.wes@example.invalid', 'V86 Ownwes', 'superadmin', WES, NULL, NULL, NULL) e;
    PERFORM _assert(v_ok IS FALSE AND v_reason = 'platform_role_needs_no_school',
      format('§65 (enrol): the owner was answered %s:%s for a superadmin at Westville', v_ok, v_reason));
    PERFORM _assert(_v86_left('v86.own.wes@example.invalid') = '0/0/0',
      format('§65 (enrol): the owner''s refusal left %s behind', _v86_left('v86.own.wes@example.invalid')));
    SELECT e.ok, e.reason INTO v_ok, v_reason
      FROM enrol_person('v86.own.plat@example.invalid', 'V86 Ownplat', 'platformadmin', WES, NULL, NULL, NULL) e;
    PERFORM _assert(v_ok IS FALSE AND v_reason = 'platform_role_needs_no_school',
      format('§65 (enrol): the owner was answered %s:%s for a platformadmin at Westville', v_ok, v_reason));

    -- (decide) filed signed out, as POST /api/onboard files it.
    PERFORM set_config('app.user_id', '', true);
    v_req := onboard_request('v86.asker@example.invalid', 'V86 Asker', 'platformadmin', WES, NULL, 'I run the platform.');
    PERFORM _as(U_PLAT);
    SELECT d.ok, d.reason, d.assignment_id INTO v_ok, v_reason, v_asg
      FROM decide_role_request(v_req, true, NULL, NULL, NULL) d;
    PERFORM _assert(v_ok IS FALSE AND v_reason = 'platform_role_needs_no_school' AND v_asg IS NULL,
      format('§65 (decide): the platform account''s grant was answered %s:%s', v_ok, v_reason));
    PERFORM _assert(_v86_request(v_req) = 'pending',
      format('§65 (decide): the refused request is %s, not pending', _v86_request(v_req)));
    SELECT d.ok, d.reason INTO v_ok, v_reason FROM decide_role_request(v_req, false, 'Not a school''s role.', NULL, NULL) d;
    PERFORM _assert(v_ok IS TRUE AND _v86_request(v_req) = 'declined',
      format('§65 (decide): the request could not be declined (%s:%s, %s)', v_ok, v_reason, _v86_request(v_req)));

    -- (policy)
    PERFORM set_config('app.user_id', '', true);
    v_p1 := _v86_person('one'); v_p2 := _v86_person('two'); v_p3 := _v86_person('three');
    v_p4 := _v86_person('four'); v_p5 := _v86_person('five');
    PERFORM _as(U_PLAT);
    v_got := _v86_insert(v_p1, 'platformadmin', WES);
    PERFORM _assert(v_got = '23514:platform_role_needs_no_school',
      format('§65 (policy): the platform account wrote a platformadmin at Westville (%s)', v_got));
    PERFORM _as(U_OWNER);
    v_got := _v86_insert(v_p1, 'superadmin', WES);
    PERFORM _assert(v_got = '23514:platform_role_needs_no_school',
      format('§65 (policy): the owner wrote a superadmin at Westville (%s)', v_got));

    -- (owner)
    PERFORM set_config('app.user_id', '', true);
    v_got := _v86_appoint(v_p1, 'superadmin', HIL);
    PERFORM _assert(v_got = '23514:platform_role_needs_no_school',
      format('§65 (owner): the table owner wrote a superadmin at Hilton (%s)', v_got));
    v_got := _v86_appoint(v_p1, 'platformadmin', HIL, false);
    PERFORM _assert(v_got = '23514:platform_role_needs_no_school',
      format('§65 (owner): the table owner wrote an ended platformadmin at Hilton (%s)', v_got));

    -- (still)
    PERFORM _as(U_PLAT);
    v_got := _v86_insert(v_p2, 'platformadmin', NULL);
    PERFORM _assert(v_got = 'ok', format('§65 (still): the platform account could not appoint a platformadmin with no school (%s)', v_got));
    PERFORM _as(U_OWNER);
    v_got := _v86_insert(v_p3, 'superadmin', NULL);
    PERFORM _assert(v_got = 'ok', format('§65 (still): the owner could not appoint a superadmin with no school (%s)', v_got));
    PERFORM set_config('app.user_id', '', true);
    v_got := _v86_appoint(v_p4, 'superadmin', NULL);
    PERFORM _assert(v_got = 'ok', format('§65 (still): the owner''s own SQL could not write an owner''s key (%s)', v_got));
    v_got := _v86_appoint(v_p5, 'platformadmin', NULL);
    PERFORM _assert(v_got = 'ok', format('§65 (still): the owner''s own SQL could not write a platformadmin (%s)', v_got));
    PERFORM _as(U_PLAT);
    SELECT e.ok, e.reason INTO v_ok, v_reason
      FROM enrol_person('v86.coach@example.invalid', 'V86 Coach', 'coach', WES, '1XI', NULL, NULL) e;
    PERFORM _assert(v_ok IS TRUE, format('§65 (still): the platform account could not enrol a coach at Westville (%s)', v_reason));

    -- (record)
    v_got := _v86_record();
    PERFORM _assert(v_got = '0/2/true/platformadmin,superadmin',
      format('§65 (record): school-scoped platform appointments / the seed''s keys live / validated / platform roles = %s', v_got));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 65
  -- ┌── section 66 · db/87: a wicket on a wide or a no-ball ──
  -- _seed_87(): a Hilton innings with a stumping off a wide, a run out off a
  -- no-ball, and a stumping off a wide on the free hit that follows (saved).
  -- Every figure below is the fold's for that log (replay.test.mjs group P,
  -- "the log db/87 proves"); tools/smoke-fold-figures.mjs holds every reader
  -- to the fold over generated logs with wickets on extras.
  --
  -- With db/87 left out (the database as db/85 left it) this section went
  -- red at its first assertion: the live score read (6,0,2) — no wicket on
  -- either extra. What each label holds:
  --   (score)   the live score and the handover's count: 2 wickets, not 0
  --   (bowler)  the bowler's innings and career: the stumping is his
  --   (batter)  who is out: …01 run out off the no-ball, …02 stumped off the wide
  --   (keeper)  the stumping off the wide is the keeper's
  --   (door)    a method the Law does not allow off the extra is refused
  DECLARE
    M    uuid;
    b0   jsonb;
    b1   jsonb;
    got  text;
    A1 uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
    A2 uuid := 'aaaaaaaa-0000-0000-0000-000000000002';
    BW uuid := 'aaaaaaaa-0000-0000-0000-000000000003';
    A3 uuid := 'aaaaaaaa-0000-0000-0000-000000000005';
    A4 uuid := 'aaaaaaaa-0000-0000-0000-000000000006';
  BEGIN
    PERFORM _as(U_SARAH);
    b0 := _careers_87();
    M := _seed_87();
    PERFORM _as(U_SARAH);
    b1 := _careers_87();
    -- (score) runs 1 + 1 + 3 + 1 + 0; two wickets (the saved stumping is none); two balls of the over
    SELECT concat_ws(' | ',
      (SELECT row(l.runs, l.wickets, l.legal_balls)::text FROM match_live_score l WHERE l.match_id = M),
      (SELECT row(f.runs, f.wickets, f.legal_balls)::text FROM innings_score_as_folded(M, 0::smallint) f))
      INTO got;
    PERFORM _assert(got = '(6,2,2) | (6,2,2)',
      format('§66 (score): the live score and the handover''s count read %s, where the fold says (6,2,2) | (6,2,2)', got));
    -- (bowler) his innings: one wicket, six conceded (both wides, the no-ball and its two off the bat)
    SELECT row(b.wickets, b.runs_conceded)::text INTO got FROM bowler_innings_figures b WHERE b.match_id = M AND b.player_id = BW;
    PERFORM _assert(got = '(1,6)', format('§66 (bowler): S Naidoo''s innings reads %s, where the fold says (1,6)', got));
    PERFORM _assert(b1->'bowl_since' = jsonb_build_array((b0->'bowl_since'->>0)::int + 2, (b0->'bowl_since'->>1)::int + 2,
                                                         (b0->'bowl_since'->>2)::int + 1, (b0->'bowl_since'->>3)::int + 1,
                                                         (b0->'bowl_since'->>4)::int + 6)
                    AND (b1->>'bowl_career')::int = (b0->>'bowl_career')::int + 1
                    AND (b1->>'bowl_season')::int = (b0->>'bowl_season')::int + 1
                    AND (b1->>'wkt_stumped')::int = (b0->>'wkt_stumped')::int + 1,
      format('§66 (bowler): his career moved %s → %s; the fold says two balls, two wides, a no-ball, one wicket (stumped), six runs', b0, b1));
    -- (batter) who is out, and what each faced: a no-ball is a ball faced, a wide is not
    SELECT string_agg(CASE x.player_id WHEN A1 THEN 'a1' WHEN A2 THEN 'a2' WHEN A3 THEN 'a3' ELSE 'a4' END
                      || '=' || row(x.runs, x.balls_faced, x.out)::text, ' ' ORDER BY x.player_id)
      INTO got FROM player_innings x WHERE x.match_id = M;
    PERFORM _assert(got = 'a1=(1,1,t) a2=(0,0,t) a3=(2,1,f) a4=(0,1,f)',
      format('§66 (batter): the innings'' batting reads %s, where the fold says a1=(1,1,t) a2=(0,0,t) a3=(2,1,f) a4=(0,1,f)', got));
    PERFORM _assert(b1->'out_since' = jsonb_build_array((b0->'out_since'->>0)::int + 1, (b0->'out_since'->>1)::int + 1, (b0->'out_since'->>2)::int)
                    AND (b1->>'out_view')::int = (b0->>'out_view')::int + 2
                    AND (b1->>'out_season')::int = (b0->>'out_season')::int + 2
                    AND (b1->>'out_ro')::int = (b0->>'out_ro')::int + 1
                    AND (b1->>'out_st')::int = (b0->>'out_st')::int + 1
                    AND b1->'bat_since' = jsonb_build_array((b0->'bat_since'->>0)::int + 2, (b0->'bat_since'->>1)::int + 1)
                    AND b1->'bat_wide' = b0->'bat_wide',
      format('§66 (batter): the careers moved %s → %s; the fold says …01 run out, …02 stumped, …06 not out; …05 2 off a ball; …02 faced nothing', b0, b1));
    -- (keeper) the stumping off the wide is M Cele's; the saved one is nobody's
    SELECT string_agg(k.seq || ':' || k.dismissal, ',' ORDER BY k.seq) INTO got FROM keeper_dismissal k WHERE k.match_id = M;
    PERFORM _assert(got = '4:stumped' AND (b1->>'keeping')::int = (b0->>'keeping')::int + 1,
      format('§66 (keeper): the keeper''s dismissals read %s (career %s → %s), where the fold says 4:stumped', got, b0->'keeping', b1->'keeping'));
    -- (door) a bowled off a wide, a stumping or a catch off a no-ball: refused,
    -- as the owner writes (no route, no policy); a run out off either taken
    PERFORM _assert(_owner_61(format($q$INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
        idempotency_key, client_seq, client_ts, kind, ball_type, value, dismissal, payload)
        VALUES (%L, '11111111-1111-1111-1111-111111111111', 30, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-087',
                'v87:door:wd', 30, now(), 'ball', 'Wd', 0, 'bowled', '{}')$q$, M)) = '23514'
                    AND _owner_61(format($q$INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
        idempotency_key, client_seq, client_ts, kind, ball_type, value, dismissal, payload)
        VALUES (%L, '11111111-1111-1111-1111-111111111111', 30, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-087',
                'v87:door:nb', 30, now(), 'ball', 'Nb', 0, 'caught', '{}')$q$, M)) = '23514'
                    AND _owner_61(format($q$INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
        idempotency_key, client_seq, client_ts, kind, ball_type, value, dismissal, payload)
        VALUES (%L, '11111111-1111-1111-1111-111111111111', 30, 1, 0, '88888888-0000-0000-0000-000000000006', 'verify-087',
                'v87:door:ok', 30, now(), 'ball', 'Nb', 1, 'run_out', '{}')$q$, M)) = 'ok',
      '§66 (door): a bowled off a wide or a catch off a no-ball was taken, or a run out off a no-ball refused');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 66

  -- ── 67. Par for the public pages (SCRBRD-133 G2, db/88) ─────────────
  -- _seed_88(): a ground of five innings (par 120), a ground of four, and a
  -- published, an unpublished and a below-the-floor fixture. Read as NOBODY —
  -- the principal every /api/public/ request runs as — except where a reader
  -- of the result is the control. The JavaScript half (the words, the track,
  -- the leak check) is apps/web/test/par.test.mjs and
  -- services/api/public/public.test.mjs.
  --
  -- Each labelled assertion was falsified once — the function replaced in
  -- the database and this file run — and went red:
  --   (served)    public_venue_par() without public_fixture_served()
  --   (floor)     public_venue_par() without `v.sufficient`
  --   (columns)   public_venue_par() returning the innings list
  --   (table)     public_dls_table() without public_fixture_served()
  DECLARE
    ids  jsonb := _seed_88();
    M_ON uuid; M_OFF uuid; M_FEW uuid;
    got  text;
    v    record;
  BEGIN
    M_ON := (ids->>'on')::uuid; M_OFF := (ids->>'off')::uuid; M_FEW := (ids->>'few')::uuid;
    -- (columns) team-level, by name: no innings list, no breakdown, no id of
    -- a ground or another match — those name fixtures nobody published
    PERFORM _assert(pg_get_function_result('public_venue_par(uuid)'::regprocedure)
                    = 'TABLE(overs integer, age_band text, n integer, floor integer, sufficient boolean, par integer, '
                      'median numeric, low integer, high integer, first_season integer, last_season integer)',
      format('§67 (columns): public_venue_par returns %s', pg_get_function_result('public_venue_par(uuid)'::regprocedure)));
    PERFORM _assert(pg_get_function_result('public_dls_table(uuid)'::regprocedure)
                    = 'TABLE(id uuid, version smallint, grain text, max_balls smallint, status text, current boolean, cells jsonb)',
      format('§67 (columns): public_dls_table returns %s', pg_get_function_result('public_dls_table(uuid)'::regprocedure)));
    -- the application's, and nobody else's: not PUBLIC
    PERFORM _assert(has_function_privilege('public_venue_par(uuid)', 'EXECUTE') AND has_function_privilege('public_dls_table(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'public_venue_par(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'public_dls_table(uuid)', 'EXECUTE'),
      '§67: the public par reads are not the application''s alone');

    -- (served) as nobody, a published fixture reads its ground's par and its
    -- evidence; the signed-in reader's door stays shut to nobody
    PERFORM set_config('app.user_id', '', true);
    SELECT row(w.overs, w.age_band, w.n, w.floor, w.sufficient, w.par, w.median, w.low, w.high,
               w.first_season <= w.last_season AND w.last_season = extract(year FROM sa_today())::integer)::text
      INTO got FROM public_venue_par(M_ON) w;
    PERFORM _assert(got = '(20,U15,5,5,t,120,120,100,140,t)', format('§67 (served): the published fixture''s ground reads %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM venue_par_for_match(M_ON)),
      '§67: nobody read a ground''s par through the signed-in reader');
    -- (served) nobody published OFF: the same nothing as a fixture that does not exist
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM public_venue_par(M_OFF)) AND NOT EXISTS (SELECT 1 FROM public_venue_par(gen_random_uuid())),
      '§67 (served): an unpublished fixture''s ground answered');
    -- (floor) four innings: nothing at all, not a row with no par
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM public_venue_par(M_FEW)), '§67 (floor): a ground of four innings answered');
    -- …while Hilton's director reads that ground as four of five, insufficient:
    -- the floor hides it, not the lack of a ground
    PERFORM _as(U_SARAH);
    SELECT * INTO v FROM venue_par_for_match(M_FEW);
    PERFORM _assert(v.n = 4 AND NOT v.sufficient AND v.par IS NULL,
      format('§67 (floor): the director reads the short ground as n %s, sufficient %s', v.n, v.sufficient));

    -- (table) the DLS table goes to the server for a published fixture —
    -- exactly the one a reader of the result reads (§54 left one published)
    -- — and for an unpublished one, nothing
    SELECT string_agg(t.id || ':' || t.version || ':' || t.status || ':' || jsonb_array_length(t.cells), ' ') INTO got
      FROM dls_table_for_match(M_ON) t;
    PERFORM _assert(got IS NOT NULL, '§67 (table): the director reads no DLS table for the fixture; §54 left none published');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT string_agg(t.id || ':' || t.version || ':' || t.status || ':' || jsonb_array_length(t.cells), ' ')
                       FROM public_dls_table(M_ON) t) = got,
      format('§67 (table): the published fixture''s server reads %s, the director %s',
             (SELECT string_agg(t.id || ':' || t.version, ' ') FROM public_dls_table(M_ON) t), got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM public_dls_table(M_OFF)), '§67 (table): an unpublished fixture read the DLS table');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM dls_table_for_match(M_ON)), '§67: nobody read the table through the signed-in reader');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 67

  -- ── 68. Notifications S1: the contract and read state (db/89) ───────
  -- docs/design/NOTIFICATIONS.md D1, D4, D5, D17, D18, D19. _seed_89() writes
  -- five notices as the owner (as the system's own definers do); every read
  -- below is as a person, under RLS, through scrbrd_app. The JavaScript half:
  -- packages/policy/test/notifications.test.mjs (the lists agree with this
  -- file's CHECKs), services/api/notify/receipts.test.mjs (the two routes),
  -- apps/web/test/notifications-store.test.mjs (one store, one count), and
  -- tools/smoke-summary.mjs (the count falls on a second device's receipt).
  --
  -- What each label holds:
  --   (kinds)     D1/D5: a kind outside the nine refused; welfare and news stored
  --   (stored)    every stored row is in the list and none is public (D6);
  --               both CHECKs validated
  --   (shape)     D4: a person's notice names no child, has no recipient, is
  --               never high and asks news.read alone; nothing is public;
  --               on insert and on update; through the application too
  --   (life)      D4: expiry by kind when the writer left it null
  --   (door)      D18: the retraction columns are notification_retract()'s
  --               alone; the application cannot call it
  --   (retract)   D18: the words per kind, the person, once only, one
  --               "withdrawn" notice to the same audience, urgency capped
  --   (excluded)  D17/D19: the view leaves out the retracted and the expired
  --   (audience)  another child's parent gets neither notice nor stub
  --   (stub)      D19: a retracted notice opens as a stub with no words
  --   (tiered)    D17: a tiered row lists its title; its body is read on
  --               open, and the open is logged; a news.read open is not
  --   (receipts)  D17: a receipt is the reader's own, for a notice he can
  --               see; the count falls with it; read-all is per person
  --   (milestone) D19: milestone_notice and recognition() leave out a
  --               retracted mark
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at its label:
  --   (excluded)  my_notifications without `n.retracted_at IS NULL`
  --   (door)      notification_retraction_door() without its owner test
  --   (kinds)     db/89 without notification_kind_known
  --   (shape)     notification_contract() without its `kind = 'notice'` block
  --   (stub)      notification_by_id() returning the row when retracted
  --   (tiered)    notification_by_id() without its log_restricted_read()
  --   (milestone) milestone_notice_not_retracted dropped
  DECLARE
    ids    jsonb := _seed_89();
    R uuid; N uuid; G uuid; F uuid; SG uuid; W uuid; WF uuid; v uuid;
    U_KIN    uuid := '88888888-0000-0000-0000-000000000010';  -- H Whitfield, guardian of J Whitfield (1XI)
    U_OTHER  uuid := '88888888-0000-0000-0000-000000000011';  -- A Bekker, guardian of T Bekker (1XI): not J Whitfield
    P_KIN    uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
    N_ALL  uuid := '40170000-0000-0000-0000-000000000001';  -- the seed's school-wide notice, news.read
    N_INJ  uuid := '40170000-0000-0000-0000-000000000002';  -- the seed's injury notice, medical.status.read
    P_FIFTY  uuid := 'aaaaaaaa-0000-0000-0000-000000000002';  -- T Bekker: a fifty in the seed's match …04
    P_FIFTY2 uuid := 'aaaaaaaa-0000-0000-0000-000000000004';  -- and another boy's, left standing
    M_FIFTY  uuid := '77777777-0000-0000-0000-000000000004';
    got    text;
    j      jsonb;
    c0     integer;
    c1     integer;
  BEGIN
    R := (ids->>'rec')::uuid; N := (ids->>'note')::uuid; G := (ids->>'gone')::uuid;
    F := (ids->>'fix')::uuid; SG := (ids->>'sg')::uuid;

    -- (kinds) as the owner, so nothing but the schema can refuse
    PERFORM _assert(_try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body)
                                        VALUES (%L, 'school', 'training', 'v89', 'v89')$q$, HIL)) = 'notification_kind_known',
      '§68 (kinds): a notice of kind ''training'' was stored');
    PERFORM _assert(_try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, required_capability, subject_kind)
                                        VALUES (%L, 'school', 'welfare', 'v89', 'v89', 'player.workload.read', 'welfare')$q$, HIL)) = 'ok'
                    AND _try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, subject_kind)
                                        VALUES (%L, 'school', 'notice', 'v89', 'v89', 'news')$q$, HIL)) = 'ok',
      '§68 (kinds): a welfare or a news subject was refused (D5)');
    PERFORM _assert(_try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, subject_kind)
                                        VALUES (%L, 'school', 'notice', 'v89', 'v89', 'weather')$q$, HIL)) = 'notification_subject_kind_known',
      '§68 (kinds): a subject outside the list was stored');
    -- (stored)
    got := _stored_89();
    PERFORM _assert(got = 'none / 0 public', format('§68 (stored): stored notices outside the list / public: %s', got));
    PERFORM _assert((SELECT count(*) FROM pg_constraint WHERE conrelid = 'notification'::regclass AND convalidated
                       AND conname IN ('notification_kind_known', 'notification_subject_kind_known')) = 2,
      '§68 (stored): the kind and subject CHECKs are not both validated');

    -- (shape) D4, as the owner: the trigger refuses, not a policy
    PERFORM _assert(_try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, subject_person_id)
                                        VALUES (%L, 'school', 'notice', 'v89', 'v89', %L)$q$, HIL, P_INJURED)) = 'notification_notice_shape'
                    AND _try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, recipient_id)
                                        VALUES (%L, 'school', 'notice', 'v89', 'v89', %L)$q$, HIL, U_SARAH)) = 'notification_notice_shape'
                    AND _try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, urgency, title, body)
                                        VALUES (%L, 'school', 'notice', 'high', 'v89', 'v89')$q$, HIL)) = 'notification_notice_shape'
                    AND _try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, required_capability)
                                        VALUES (%L, 'school', 'notice', 'v89', 'v89', 'medical.nature.read')$q$, HIL)) = 'notification_notice_shape',
      '§68 (shape): a person''s notice named a child, had a recipient, was high or asked more than news.read');
    PERFORM _assert(_try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, is_public)
                                        VALUES (%L, 'school', 'system', 'v89', 'v89', true)$q$, HIL)) = 'notification_never_public',
      '§68 (shape): a public notice was stored (D6)');
    -- …and an edit cannot reach what an insert may not
    PERFORM _assert(_try_75(format('UPDATE notification SET urgency = ''high'' WHERE id = %L', N)) = 'notification_notice_shape'
                    AND _try_75(format('UPDATE notification SET subject_person_id = %L WHERE id = %L', P_INJURED, N)) = 'notification_notice_shape'
                    AND _try_75(format('UPDATE notification SET is_public = true WHERE id = %L', R)) = 'notification_never_public',
      '§68 (shape): an update made a notice high, about a child, or public');
    -- …and through the application: the contract refuses first; and since
    -- db/91 (D9, §70) the application writes no notice at all, an ordinary
    -- one included: a person's words are a news_post, and its trigger writes
    -- the notice
    PERFORM _as(U_SARAH);
    PERFORM _assert(_app_89(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, subject_person_id)
                                       VALUES (%L, 'school', 'notice', 'v89', 'v89', %L)$q$, HIL, P_INJURED)) = 'notification_notice_shape'
                    AND _app_89(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body)
                                       VALUES (%L, 'school', 'notice', 'v89 app', 'v89')$q$, HIL)) = '42501',
      '§68 (shape): the director of sport published a notice about a child, or wrote a notice through the application (db/91)');

    -- (life) from published_at, by kind; a writer's own expiry kept
    SELECT concat_ws(' ',
      (SELECT ((x->>'expires_at')::timestamptz - (x->>'published_at')::timestamptz)::text FROM _row_89(R) x),
      (SELECT ((x->>'expires_at')::timestamptz - (x->>'published_at')::timestamptz)::text FROM _row_89(N) x),
      (SELECT ((x->>'expires_at')::timestamptz = (SELECT m.starts_at + interval '7 days' FROM match m WHERE m.id = '77777777-0000-0000-0000-000000000002'))::text FROM _row_89(F) x),
      (SELECT ((x->>'expires_at')::timestamptz < now())::text FROM _row_89(G) x)) INTO got;
    PERFORM _assert(got = '180 days 60 days true true',
      format('§68 (life): recognition / notice / fixture (start + 7 days) / the writer''s own read %s', got));

    -- (door) as the application, which may UPDATE the fixture notice
    -- (news.publish at the side; a 'notice' it may not update at all since
    -- db/91, §70)…
    PERFORM _as(U_SARAH);
    UPDATE notification SET body = body WHERE id = F RETURNING id INTO v;
    PERFORM _assert(v = F, '§68 (door): the director of sport cannot update the fixture notice at all — the refusals below prove nothing');
    -- …but not its retraction, not with the door's setting forged, and not by
    -- writing a "withdrawn" notice of her own
    PERFORM _assert(_app_89(format('UPDATE notification SET retracted_at = now(), retraction_kind = ''superseded'' WHERE id = %L', F)) = 'notification_retraction_door',
      '§68 (door): the application set retracted_at');
    PERFORM set_config('scrbrd.notification_retract', F::text, true);
    PERFORM _assert(_app_89(format('UPDATE notification SET retracted_at = now(), retraction_kind = ''superseded'' WHERE id = %L', F)) = 'notification_retraction_door',
      '§68 (door): the application set retracted_at with the door''s setting forged');
    PERFORM set_config('scrbrd.notification_retract', '', true);
    PERFORM _assert(_app_89(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, retracts_id)
                                       VALUES (%L, 'school', 'notice', 'v89', 'v89', %L)$q$, HIL, N)) = 'notification_retraction_door',
      '§68 (door): the application wrote a "withdrawn" notice');
    -- the owner outside the function: refused too; a notice is not born retracted
    PERFORM _assert(_try_75(format('UPDATE notification SET retracted_at = now(), retraction_kind = ''correction'' WHERE id = %L', R)) = 'notification_retraction_door'
                    AND _try_75(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body, retracted_at, retraction_kind)
                                        VALUES (%L, 'school', 'notice', 'v89', 'v89', now(), 'correction')$q$, HIL)) = 'notification_retraction_door',
      '§68 (door): the owner retracted a notice outside notification_retract(), or wrote one born retracted');
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'notification_retract(uuid,text,boolean)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'notification_retract(uuid,text,boolean)', 'EXECUTE')
                    AND _app_89(format('SELECT notification_retract(%L, ''withdrawn'', true)', N)) = '42501',
      '§68 (door): the application can call notification_retract()');
    PERFORM _assert(has_table_privilege('scrbrd_app', 'my_notifications', 'SELECT')
                    AND NOT has_table_privilege('scrbrd_app', 'my_notifications', 'INSERT')
                    AND NOT has_table_privilege('scrbrd_app', 'my_notifications', 'UPDATE')
                    AND NOT has_table_privilege('public', 'my_notifications', 'SELECT')
                    AND (SELECT c.reloptions FROM pg_class c WHERE c.oid = 'my_notifications'::regclass) @> ARRAY['security_invoker=true'],
      '§68 (door): my_notifications is not a read, as the caller, for the application alone');

    -- (retract) the word must fit the kind (D2)
    SELECT concat_ws(' ', _retract_89(SG, 'correction', true, NULL), _retract_89(N, 'correction', true, NULL),
                          _retract_89(R, 'withdrawn', true, U_SARAH), _retract_89(N, 'withdrawn', true, NULL),
                          _retract_89(N, 'withdrawn', true, U_KIN), _retract_89(N, 'regretted', true, NULL)) INTO got;
    PERFORM _assert(got = 'notification_retract_kind notification_retract_kind notification_retract_kind 42501 42501 22023',
      format('§68 (retract): safeguarding / a notice corrected / a fifty withdrawn / nobody / not the author / no such word read %s', got));
    -- a correction, while a scorer is signed in: still the system's
    W := _retract_89(R, 'correction', true, U_SCORER)::uuid;
    j := _row_89(R);
    PERFORM _assert(j->>'retracted_at' IS NOT NULL AND j->>'retracted_by' IS NULL AND j->>'retraction_kind' = 'correction',
      format('§68 (retract): the corrected fifty reads %s', j));
    j := _row_89(W);
    PERFORM _assert(j->>'kind' = 'recognition' AND j->>'urgency' = 'medium' AND j->>'team_code' = '1XI' AND j->>'scope_level' = 'team'
                    AND j->>'school_id' = HIL::text AND j->>'required_capability' = 'news.read'
                    AND j->>'subject_person_id' = P_KIN::text AND j->>'recipient_id' IS NULL
                    AND j->>'retracts_id' = R::text AND j->>'published_by' IS NULL AND j->>'retracted_at' IS NULL
                    AND j->>'title' = 'A notice was withdrawn'
                    AND j->>'body' = '''Fifty for J Whitfield'' was withdrawn after the scorecard was corrected.',
      format('§68 (retract): the "withdrawn" notice is not the original''s audience in the system''s words: %s', j));
    PERFORM _assert(_retract_89(R, 'correction', true, NULL) = W::text AND _said_89(R) = 1,
      '§68 (retract): a second retraction said something again');
    -- superseded: a high fixture notice's withdrawal is medium
    WF := _retract_89(F, 'superseded', true, NULL)::uuid;
    j := _row_89(WF);
    PERFORM _assert(j->>'urgency' = 'medium' AND j->>'required_capability' = 'fixture.read' AND j->>'kind' = 'fixture'
                    AND j->>'body' = '''Verify 089 fixture moved'' was replaced by a later notice.',
      format('§68 (retract): the superseded fixture notice''s withdrawal reads %s', j));
    -- withdrawn by its author, saying nothing: on the record as hers
    -- (Called first, on its own: a STABLE reader in the same statement would
    -- read the row as the statement found it.)
    got := _retract_89(N, 'withdrawn', false, U_SARAH);
    PERFORM _assert(got = 'said nothing'
                    AND _row_89(N)->>'retracted_by' = U_SARAH::text AND _row_89(N)->>'retraction_kind' = 'withdrawn'
                    AND _said_89(N) = 0 AND _logged_89('notification.retract', N) = 1
                    AND _logged_89('notification.retract', R) = 0,
      format('§68 (retract): the author''s withdrawal answered %s and reads %s, logged %s', got, _row_89(N), _logged_89('notification.retract', N)));

    -- (excluded) J Whitfield's guardian: the view leaves out what was taken
    -- back and what expired; the table's own policy still admits both, so it
    -- is the view that takes them away
    PERFORM _as(U_KIN);
    PERFORM _assert(EXISTS (SELECT 1 FROM notification WHERE id = R) AND EXISTS (SELECT 1 FROM notification WHERE id = G),
      '§68 (excluded): J Whitfield''s guardian cannot read the fifty or the expired notice at all — the exclusions below prove nothing');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM my_notifications WHERE id IN (R, N, G))
                    AND EXISTS (SELECT 1 FROM my_notifications WHERE id = W),
      '§68 (excluded): the guardian''s list holds a retracted or expired notice, or lacks the "withdrawn" one');

    -- (stub)
    j := notification_by_id(R);
    PERFORM _assert(j->>'id' = R::text AND (j->>'withdrawn')::boolean AND j->>'retracted_at' IS NOT NULL
                    AND j->>'withdrawal_id' = W::text
                    AND (SELECT string_agg(k, ',' ORDER BY k) FROM jsonb_object_keys(j) k) = 'id,retracted_at,withdrawal_id,withdrawn',
      format('§68 (stub): the retracted fifty opens as %s', j));
    PERFORM _assert(notification_by_id(W)->>'body' = '''Fifty for J Whitfield'' was withdrawn after the scorecard was corrected.'
                    AND NOT (notification_by_id(W)->>'withdrawn')::boolean,
      '§68 (stub): the "withdrawn" notice does not open in full');
    PERFORM _assert(notification_by_id(G) IS NULL AND notification_by_id(gen_random_uuid()) IS NULL,
      '§68 (stub): an expired or unknown notice answered');

    -- (audience) another 1XI family: neither notice, nor its stub
    PERFORM _as(U_OTHER);
    PERFORM _assert(EXISTS (SELECT 1 FROM my_notifications WHERE id = N_ALL),
      '§68 (audience): the other guardian reads no notice at all — the refusals below prove nothing');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM my_notifications WHERE id IN (R, W))
                    AND notification_by_id(R) IS NULL AND notification_by_id(W) IS NULL,
      '§68 (audience): another child''s parent read J Whitfield''s fifty, its stub, or its withdrawal');

    -- (tiered) the medical officer: the injury notice's title in the list,
    -- its body on open, and the open on the record
    PERFORM _as(U_MEDICAL);
    SELECT row(m.tiered, m.body IS NULL, m.title)::text INTO got FROM my_notifications m WHERE m.id = N_INJ;
    PERFORM _assert(got = '(t,t,"Availability update")', format('§68 (tiered): the injury notice lists as %s', got));
    c0 := _logged_89('notification.open', N_INJ);
    j := notification_by_id(N_INJ);
    PERFORM _assert(j->>'body' = 'R Pillay is unavailable for selection. Review in two weeks.' AND (j->>'tiered')::boolean
                    AND _logged_89('notification.open', N_INJ) = c0 + 1,
      format('§68 (tiered): the open read %s, logged %s → %s', j->>'body', c0, _logged_89('notification.open', N_INJ)));
    SELECT row(m.tiered, m.body)::text INTO got FROM my_notifications m WHERE m.id = N_ALL;
    PERFORM _assert(got = '(f,"The 2026/27 fixture list is now available.")'
                    AND notification_by_id(N_ALL)->>'body' = 'The 2026/27 fixture list is now available.'
                    AND _logged_89('notification.open', N_ALL) = 0,
      format('§68 (tiered): a news.read notice lists as %s, or its open was logged', got));

    -- (receipts) the guardian's own
    PERFORM _as(U_KIN);
    SELECT count(*) INTO c0 FROM my_notifications WHERE NOT read;
    INSERT INTO notification_read (notification_id, person_id) VALUES (W, app_user_id());
    SELECT count(*) INTO c1 FROM my_notifications WHERE NOT read;
    PERFORM _assert(c1 = c0 - 1 AND (SELECT read FROM my_notifications WHERE id = W)
                    AND (notification_by_id(W)->>'read')::boolean,
      format('§68 (receipts): a receipt moved the guardian''s unread count %s → %s', c0, c1));
    PERFORM _assert(_app_89(format('INSERT INTO notification_read (notification_id, person_id) VALUES (%L, %L)', N_ALL, U_OTHER)) = '42501',
      '§68 (receipts): the guardian marked a notice read for somebody else');
    PERFORM _as(U_OTHER);
    SELECT count(*) INTO c0 FROM my_notifications WHERE NOT read;
    PERFORM _assert(_app_89(format('INSERT INTO notification_read (notification_id, person_id) VALUES (%L, %L)', R, U_OTHER)) = '42501',
      '§68 (receipts): a receipt was written for a notice its reader cannot see');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification_read WHERE person_id = U_KIN),
      '§68 (receipts): one guardian read another''s receipts');
    -- read-all, as the route writes it: the guardian's alone
    PERFORM _as(U_KIN);
    INSERT INTO notification_read (notification_id, person_id)
      SELECT id, app_user_id() FROM my_notifications WHERE NOT read ON CONFLICT DO NOTHING;
    SELECT count(*) INTO c1 FROM my_notifications WHERE NOT read;
    PERFORM _assert(c1 = 0, format('§68 (receipts): after read-all the guardian has %s unread', c1));
    PERFORM _as(U_OTHER);
    SELECT count(*) INTO c1 FROM my_notifications WHERE NOT read;
    PERFORM _assert(c0 > 0 AND c1 = c0, format('§68 (receipts): the guardian''s read-all moved the other family''s count %s → %s', c0, c1));

    -- (milestone) a mark whose notice was retracted is read nowhere
    PERFORM _as(U_SARAH);
    PERFORM _assert(EXISTS (SELECT 1 FROM recognition(P_FIFTY) x WHERE x.family = 'milestone' AND x.match_id = M_FIFTY AND x.kind = 'fifty'),
      '§68 (milestone): the seed''s fifty is not in recognition() — the exclusion below proves nothing');
    PERFORM _milestone_89(P_FIFTY, M_FIFTY, 60, true);
    PERFORM _milestone_89(P_FIFTY2, M_FIFTY, 71, false);
    PERFORM _as(U_SARAH);
    SELECT string_agg(mn.player_id::text, ',') INTO got FROM milestone_notice mn WHERE mn.match_id = M_FIFTY;
    PERFORM _assert(got = P_FIFTY2::text, format('§68 (milestone): milestone_notice for the match reads %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM recognition(P_FIFTY) x WHERE x.family = 'milestone' AND x.match_id = M_FIFTY AND x.kind = 'fifty')
                    AND EXISTS (SELECT 1 FROM recognition(P_FIFTY2) x WHERE x.family = 'milestone' AND x.match_id = M_FIFTY AND x.kind = 'fifty'),
      '§68 (milestone): recognition() kept a retracted fifty, or lost a standing one');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 68
  -- ┌── 69 · An account changes with a reason (db/90, account lifecycle slice 2) ──
  -- As the application role, through the two db/90 doors:
  --
  --   (reason)    no reason, a short one or one past 2,000 characters is
  --               refused by name and changes nothing; a stranger is refused
  --               not_permitted before the reason is looked at
  --   (row)       a disable writes one row (which way, the reason, who, the
  --               school) and no notice; asking again writes nothing
  --   (notice)    an enable writes the row and one 'system' notice to the
  --               person: the date, never the reason; it reaches him, and
  --               nobody else, the owner included
  --   (door)      an account holding nothing (no news.read) reads its enable
  --               notice through notification_account_enabled, and not a
  --               'system' notice no audit row admits
  --   (reader)    the office (user.invite) and the principal (audit.read)
  --               read the rows; the bursar (user.read), a coach, Westville's
  --               office and the person do not; an office holder does not
  --               read a row about himself
  --   (column)    the application cannot write app_user.active, by the
  --               office's or the principal's policy; the rest of the row is
  --               writable as before
  --   (signature) account_set_active(uuid, boolean) is gone
  --   (preview)   counts move with what the account holds (a session, a pad
  --               credential, a scoring token by its fixture, a duty); a
  --               parent's linked children are counted; a stranger, Westville's
  --               office, the principal, the account itself and a pad are
  --               refused with no counts; an account with a role at another
  --               school is other_school to its own office only
  --
  -- Falsified, each red at its own label with its key line removed and
  -- green again restored: the reason checks out of account_set_active()
  -- (reason); the account_status_change INSERT (row); the notification
  -- INSERT (notice); the notification_account_enabled policy (door); the
  -- `user_id <> app_user_id()` clause of the read policy (reader); the
  -- REVOKE UPDATE ON app_user (column); the DROP FUNCTION (signature); the
  -- scoring_session arm of the preview, and the auth_office_refusal() call
  -- in it (preview).
  DECLARE
    V_PARENT  uuid := '88888888-0000-0000-0000-000000000005';
    V_SCORER  uuid := '88888888-0000-0000-0000-000000000006';
    V_OFFICE  uuid := '88888888-0000-0000-0000-00000000000c';  -- schooladmin, Hilton: user.invite
    V_HEAD    uuid := '88888888-0000-0000-0000-000000000016';  -- principal: audit.read, no user.invite
    V_BURSAR  uuid := '88888888-0000-0000-0000-000000000015';  -- finance: user.read only
    V_COACH   uuid := '88888888-0000-0000-0000-00000000000a';  -- 2XI coach
    V_WES     uuid := '88888888-0000-0000-0000-00000000000d';  -- schooladmin, Westville
    V_SARAH   uuid := '88888888-0000-0000-0000-000000000007';  -- director of sport, a guardian at Westville too
    V_OWN     uuid := '88888888-0000-0000-0000-000000000022';  -- the owner's key
    v_bare uuid; v_note uuid; v_stray uuid; v_row uuid;
    v_got text; v_label text; n0 int; n1 int; j jsonb; p record; p0 record;
  BEGIN
    -- (reason)
    PERFORM _as(V_OFFICE);
    n0 := _v90_changes(V_SCORER);
    v_got := _v90_set(V_SCORER, false, NULL);
    PERFORM _assert(v_got = 'reason_required', format('§69 (reason): no reason answered %s', v_got));
    v_got := _v90_set(V_SCORER, false, '   too short   ');
    PERFORM _assert(v_got = 'reason_required', format('§69 (reason): nine characters, padded, answered %s', v_got));
    v_got := _v90_set(V_SCORER, false, repeat('x', 2001));
    PERFORM _assert(v_got = 'reason_too_long', format('§69 (reason): 2,001 characters answered %s', v_got));
    PERFORM _assert((_v85_state(V_SCORER)->>'active')::boolean AND _v90_changes(V_SCORER) = n0,
      '§69 (reason): a refused disable disabled the account, or wrote a row');
    PERFORM _as(V_COACH);
    v_got := _v90_set(V_SCORER, false, NULL);
    PERFORM _assert(v_got = 'not_permitted', format('§69 (reason): a coach with no reason was told %s, not not_permitted', v_got));

    -- (preview), before: what the scorer holds now
    PERFORM _as(V_OFFICE);
    SELECT * INTO p0 FROM account_offboard_preview(V_SCORER);
    PERFORM _assert(p0.ok AND p0.reason IS NULL AND p0.active AND p0.lifts = 0 AND p0.children = 0,
      format('§69 (preview): the office''s first preview of the scorer reads %s', row_to_json(p0)));
    PERFORM set_config('app.user_id', '', true);
    PERFORM auth_session_open(V_SCORER, 'v90-phone', 1800);
    PERFORM _v85_pad(V_SCORER, 'v90-pad');
    v_label := _v90_open(V_SCORER);
    PERFORM _as(V_OFFICE);
    SELECT * INTO p FROM account_offboard_preview(V_SCORER);
    PERFORM _assert(p.ok AND p.sessions = p0.sessions + 1 AND p.pad_credentials = p0.pad_credentials + 1
                    AND p.duties = p0.duties + 1 AND p.lifts = 0 AND p.children = 0,
      format('§69 (preview): after a session, a pad credential and a duty the preview reads %s (before %s)', row_to_json(p), row_to_json(p0)));
    PERFORM _assert(v_label = ANY (p.scoring_tokens) AND cardinality(p.scoring_tokens) = cardinality(p0.scoring_tokens) + 1,
      format('§69 (preview): the scoring token for %s is not in %s', v_label, p.scoring_tokens));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM unnest(p.scoring_tokens) t WHERE t ~* 'pillay|whitfield|dlamini'),
      '§69 (preview): a child''s name is in the preview');
    -- Refused, with nothing counted.
    PERFORM _as(V_COACH);
    SELECT * INTO p FROM account_offboard_preview(V_SCORER);
    PERFORM _assert(NOT p.ok AND p.reason = 'not_permitted' AND p.active IS NULL AND p.sessions IS NULL AND p.pad_credentials IS NULL
                    AND p.scoring_tokens IS NULL AND p.duties IS NULL AND p.lifts IS NULL AND p.children IS NULL,
      format('§69 (preview): a coach''s preview of the scorer reads %s', row_to_json(p)));
    PERFORM _as(V_WES);
    SELECT * INTO p FROM account_offboard_preview(V_SCORER);
    PERFORM _assert(NOT p.ok AND p.reason = 'not_permitted' AND p.sessions IS NULL AND p.scoring_tokens IS NULL,
      format('§69 (preview): Westville''s office previewed Hilton''s scorer: %s', row_to_json(p)));
    PERFORM _as(V_HEAD);
    SELECT * INTO p FROM account_offboard_preview(V_SCORER);
    PERFORM _assert(NOT p.ok AND p.reason = 'not_permitted' AND p.sessions IS NULL,
      format('§69 (preview): the principal (no user.invite) previewed the scorer: %s', row_to_json(p)));
    PERFORM _as(V_OFFICE);
    SELECT * INTO p FROM account_offboard_preview(V_OFFICE);
    PERFORM _assert(NOT p.ok AND p.reason = 'cannot_disable_yourself' AND p.sessions IS NULL,
      format('§69 (preview): the office previewed itself: %s', row_to_json(p)));
    PERFORM set_config('app.scope', 'pad', true);
    SELECT * INTO p FROM account_offboard_preview(V_SCORER);
    PERFORM set_config('app.scope', '', true);
    PERFORM _assert(NOT p.ok AND p.reason = 'not_permitted' AND p.sessions IS NULL,
      format('§69 (preview): a pad''s request previewed an account: %s', row_to_json(p)));
    SELECT * INTO p FROM account_offboard_preview(V_SARAH);
    PERFORM _assert(NOT p.ok AND p.reason = 'other_school' AND p.sessions IS NULL,
      format('§69 (preview): Hilton''s office previewed its director of sport (a guardian at Westville): %s', row_to_json(p)));
    PERFORM _as(V_WES);
    SELECT * INTO p FROM account_offboard_preview(V_SARAH);
    PERFORM _assert(NOT p.ok AND p.reason = 'not_permitted',
      format('§69 (preview): Westville''s office was told about Hilton''s account: %s', row_to_json(p)));

    -- (row)
    PERFORM _as(V_OFFICE);
    n0 := _v90_changes(V_SCORER);
    SELECT o.ok::text || ':' || o.active::text INTO v_got
      FROM account_set_active(V_SCORER, false, '  Verify 090: stepped back for a week  ') o;
    PERFORM _assert(v_got = 'true:false', format('§69 (row): Hilton''s office could not disable its scorer (%s)', v_got));
    j := _v90_row(V_SCORER, 'Verify 090: stepped back for a week');
    PERFORM _assert(_v90_changes(V_SCORER) = n0 + 1 AND (j->>'active')::boolean = false
                    AND j->>'reason' = 'Verify 090: stepped back for a week' AND (j->>'changed_by')::uuid = V_OFFICE
                    AND j->>'school_id' = '11111111-1111-1111-1111-111111111111' AND j->>'notice_id' IS NULL,
      format('§69 (row): the disable wrote %s rows, the last %s', _v90_changes(V_SCORER) - n0, j));
    SELECT * INTO p FROM account_offboard_preview(V_SCORER);
    PERFORM _assert(p.ok AND NOT p.active AND p.sessions = 0 AND p.pad_credentials = 0 AND v_label = ANY (p.scoring_tokens),
      format('§69 (preview): after the disable the preview reads %s', row_to_json(p)));
    SELECT o.ok::text || ':' || o.active::text INTO v_got
      FROM account_set_active(V_SCORER, false, 'Verify 090: asked a second time') o;
    PERFORM _assert(v_got = 'true:false' AND _v90_changes(V_SCORER) = n0 + 1,
      format('§69 (row): disabling twice answered %s and wrote %s rows', v_got, _v90_changes(V_SCORER) - n0));
    PERFORM _assert(_v85_try(format('INSERT INTO account_status_change (user_id, active, reason, changed_by) VALUES (%L, true, %L, %L)',
                                    V_SCORER, 'Verify 090: written by hand', V_OFFICE)) = '42501',
      '§69 (row): the application wrote account_status_change itself');

    -- (notice)
    SELECT o.ok::text || ':' || o.active::text INTO v_got
      FROM account_set_active(V_SCORER, true, 'Verify 090: back after the week') o;
    PERFORM _assert(v_got = 'true:true', format('§69 (notice): Hilton''s office could not enable its scorer (%s)', v_got));
    j := _v90_row(V_SCORER, 'Verify 090: back after the week');
    v_note := (j->>'notice_id')::uuid;
    PERFORM _assert(_v90_changes(V_SCORER) = n0 + 2 AND (j->>'active')::boolean AND j->>'reason' = 'Verify 090: back after the week'
                    AND v_note IS NOT NULL,
      format('§69 (notice): the enable wrote %s', j));
    j := _row_89(v_note);
    PERFORM _assert(j->>'kind' = 'system' AND (j->>'recipient_id')::uuid = V_SCORER AND j->>'title' = 'Your account was re-enabled'
                    AND j->>'body' LIKE 'Your account was re-enabled on %. Every device was signed out when it was disabled; sign in again where you need to.'
                    AND position('week' IN j->>'body') = 0 AND NOT (j->>'is_public')::boolean
                    AND (j->>'expires_at')::timestamptz > now() + interval '179 days',
      format('§69 (notice): the notice is %s', j));
    PERFORM _as(V_SCORER);
    PERFORM _assert(EXISTS (SELECT 1 FROM my_notifications m WHERE m.id = v_note)
                    AND notification_by_id(v_note)->>'title' = 'Your account was re-enabled',
      '§69 (notice): the scorer cannot read the notice about his own account');
    FOREACH v_row IN ARRAY ARRAY[V_OFFICE, V_HEAD, V_PARENT, V_OWN] LOOP
      PERFORM _as(v_row);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification x WHERE x.id = v_note) AND notification_by_id(v_note) IS NULL,
        format('§69 (notice): %s read the scorer''s notice', v_row));
    END LOOP;

    -- (door)
    v_bare := _v90_bare();
    PERFORM _as(V_OFFICE);
    SELECT o.ok::text INTO v_got FROM account_set_active(v_bare, false, 'Verify 090: the bare account, off') o;
    PERFORM _assert(v_got = 'true', format('§69 (door): the office could not disable an account holding nothing (%s)', v_got));
    SELECT o.ok::text INTO v_got FROM account_set_active(v_bare, true, 'Verify 090: the bare account, on') o;
    v_note := (_v90_row(v_bare, 'Verify 090: the bare account, on')->>'notice_id')::uuid;
    v_stray := _v90_stray(v_bare);
    PERFORM _as(v_bare);
    PERFORM _assert(v_got = 'true' AND v_note IS NOT NULL AND EXISTS (SELECT 1 FROM my_notifications m WHERE m.id = v_note),
      '§69 (door): an account with no news.read cannot read its enable notice');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification x WHERE x.id = v_stray),
      '§69 (door): a system notice no audit row admits came through the door');
    -- (preview), a parent: the bare account made a guardian of two children
    PERFORM _v90_link(v_bare);
    PERFORM _as(V_OFFICE);
    SELECT * INTO p FROM account_offboard_preview(v_bare);
    PERFORM _assert(p.ok AND p.children = 2 AND p.sessions = 0 AND p.duties = 0 AND cardinality(p.scoring_tokens) = 0,
      format('§69 (preview): a parent of two reads %s', row_to_json(p)));

    -- (reader) The office (user.invite) reads why; since READERS Q2 (db/116)
    -- the principal, who holds audit.read and not user.invite, does not.
    FOREACH v_row IN ARRAY ARRAY[V_OFFICE] LOOP
      PERFORM _as(v_row);
      SELECT count(*) INTO n1 FROM account_status_change c WHERE c.user_id = V_SCORER;
      PERFORM _assert(n1 = _v90_changes(V_SCORER) AND n1 >= 2, format('§69 (reader): %s reads %s of the scorer''s %s rows', v_row, n1, _v90_changes(V_SCORER)));
    END LOOP;
    FOREACH v_row IN ARRAY ARRAY[V_HEAD, V_BURSAR, V_COACH, V_WES, V_SCORER] LOOP
      PERFORM _as(v_row);
      SELECT count(*) INTO n1 FROM account_status_change c WHERE c.user_id = V_SCORER;
      PERFORM _assert(n1 = 0, format('§69 (reader): %s reads %s of the scorer''s rows', v_row, n1));
    END LOOP;
    v_row := _v90_plant(V_OFFICE, V_OWN);
    PERFORM _as(V_OFFICE);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM account_status_change c WHERE c.id = v_row)
                    AND EXISTS (SELECT 1 FROM account_status_change c WHERE c.user_id = V_SCORER),
      '§69 (reader): the office read a row about itself');
    -- The director of sport holds user.invite at Hilton: he reads the plant,
    -- so the office's zero above is about the office, not an empty row.
    PERFORM _as('88888888-0000-0000-0000-000000000007');
    PERFORM _assert(EXISTS (SELECT 1 FROM account_status_change c WHERE c.id = v_row),
      '§69 (reader): the director of sport cannot read the row about the office (the plant proves nothing)');

    -- (column)
    FOREACH v_row IN ARRAY ARRAY[V_OFFICE, V_HEAD] LOOP
      PERFORM _as(v_row);
      v_got := _v85_try(format('UPDATE app_user SET active = false WHERE id = %L', V_SCORER));
      PERFORM _assert(v_got = '42501', format('§69 (column): %s wrote app_user.active directly (%s)', v_row, v_got));
    END LOOP;
    PERFORM _assert((_v85_state(V_SCORER)->>'active')::boolean, '§69 (column): the scorer was disabled by a plain UPDATE');
    PERFORM _as(V_OFFICE);
    v_got := _v85_try(format('UPDATE app_user SET name = name WHERE id = %L', V_SCORER));
    PERFORM _assert(v_got = 'ok' AND NOT has_column_privilege('app_user', 'active', 'UPDATE')
                    AND has_column_privilege('app_user', 'name', 'UPDATE'),
      format('§69 (column): the rest of the row is not writable as before (%s)', v_got));

    -- (signature)
    PERFORM _assert(to_regprocedure('account_set_active(uuid,boolean)') IS NULL,
      '§69 (signature): account_set_active(uuid, boolean) is still there');
    v_got := _v85_try(format('SELECT * FROM account_set_active(%L::uuid, false)', V_SCORER));
    PERFORM _assert(v_got = '42883', format('§69 (signature): a call with no reason answered %s', v_got));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 69

  -- ── 70. Notifications S2: one stream (db/91) ────────────────────────
  -- docs/design/NOTIFICATIONS.md D9, D10, D11. Every write below is a person's,
  -- through scrbrd_app under RLS, as the routes make it: a post is inserted,
  -- edited and withdrawn by people; the notices are the trigger's. The owner's
  -- helpers (_notices_91, _reports_91, _row_89, _said_89, _logged_89) only read.
  -- The JavaScript half: services/api/notify/push-api.test.mjs (the two
  -- closed routes, the report route), services/api/write/news-api.test.mjs
  -- (urgency, the withdrawal door), and tools/smoke-push.mjs (publishing
  -- through /api/news).
  --
  -- What each label holds:
  --   (publish)  a post sent at once writes ONE notice: kind notice, the
  --              post's scope and anchor, news.read, its urgency and title,
  --              its first 280 characters, subject news = the post, by its
  --              author, about nobody and for nobody
  --   (draft)    a draft writes nothing; sending it writes one
  --   (readers)  the side's family and pupil read it; another school does not
  --   (edit)     an edit re-syncs the words; one row still; published_at kept
  --   (urgency)  never high; a sent post's urgency is fixed
  --   (app)      the application writes and edits no notice (D9)
  --   (league)   a league post: one notice per school entered
  --   (withdraw) a news.publish.school holder withdraws a coach's post; the
  --              notice is retracted 'withdrawn' by her, one "withdrawn"
  --              notice said, on the log; a parent may not; the author's own
  --              withdrawal (the old route's UPDATE) retracts too
  --   (report)   a reader's report writes ONE no-name DSO notice (school,
  --              high, safeguarding.concern.read, subject the post) and one
  --              log row; a repeat is refused and writes nothing; another
  --              reader's report is his own; a non-reader, a system notice and
  --              a "withdrawn" notice are refused; the DSO reads the notice,
  --              the family does not; the log row is the DSO's, not the
  --              office's or the author's; a school with no DSO says unheld
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at its label:
  --   (publish)  news_post_notice() without its INSERT
  --   (edit)     news_post_notice() without its re-sync UPDATE
  --   (urgency)  news_post_notice() without its sent-urgency refusal
  --   (withdraw) news_post_notice() without its notification_retract() call;
  --              news_post_withdraw() without its news.publish.school arm
  --   (report)   notification_report() without its already-reported check;
  --              without its DSO INSERT; without its app_can() reader test
  --   (app)      notification_notice_insert_system dropped (red first at
  --              §68 (shape), whose application insert now expects 42501)
  DECLARE
    V_HIL    uuid := '11111111-1111-1111-1111-111111111111';
    V_WES    uuid := '22222222-2222-2222-2222-222222222222';
    V_COACH  uuid := '88888888-0000-0000-0000-00000000000b';  -- U14A coach: news.publish.team (the 1XI coach is revoked above, line ~5015)
    V_REG    uuid := '88888888-0000-0000-0000-00000000000c';  -- Hilton's office: audit.read, not a DSO
    V_SARAH  uuid := '88888888-0000-0000-0000-000000000007';  -- director of sport: news.publish.school, audit.read
    V_KIN    uuid := '88888888-0000-0000-0000-000000000010';  -- guardian of J Whitfield (1XI)
    V_PUPIL  uuid := '88888888-0000-0000-0000-000000000009';  -- a 1XI player
    V_DSO    uuid := '88888888-0000-0000-0000-000000000057';  -- Hilton's DSO
    V_LEAGUE uuid := '88888888-0000-0000-0000-000000000021';  -- runs the league
    V_WCOACH uuid := '88888888-0000-0000-0000-00000000001a';  -- a coach at Westville (no DSO there)
    V_WREG   uuid := '88888888-0000-0000-0000-00000000000d';  -- Westville's office
    V_COMP   uuid := '99999999-0000-0000-0000-000000000001';
    P uuid; D uuid; L uuid; R uuid; W uuid;
    NP uuid; ND uuid; NR uuid; NW uuid; v uuid;
    j  jsonb;
    x  jsonb;
    got text;
    t0 timestamptz;
  BEGIN
    -- (publish) the U14A coach sends a medium post at once
    PERFORM _as(V_COACH);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, urgency)
    VALUES ('team', V_HIL, 'U14A', 'Verify 091 nets', repeat('Nets on Thursday at half past two. ', 12), now(), 'medium')
    RETURNING id INTO P;
    j := _notices_91(P);
    PERFORM _assert(jsonb_array_length(j) = 1, format('§70 (publish): a sent post wrote %s notices, not one', jsonb_array_length(j)));
    x := j->0; NP := (x->>'id')::uuid;
    got := concat_ws(' ', x->>'kind', x->>'scope_level', x->>'team_code', (x->>'school_id' = V_HIL::text), x->>'urgency',
                     x->>'required_capability', x->>'subject_kind', (x->>'subject_id' = P::text), (x->>'published_by' = V_COACH::text),
                     coalesce(x->>'subject_person_id', '-'), coalesce(x->>'recipient_id', '-'), x->>'is_public', x->>'title');
    PERFORM _assert(got = 'notice team U14A t medium news.read news t t - - false Verify 091 nets',
      format('§70 (publish): the notice reads %s', got));
    PERFORM _assert(length(x->>'body') = 280 AND right(x->>'body', 1) = '…'
                    AND left(x->>'body', 279) = left((SELECT b.body FROM news_post b WHERE b.id = P), 279),
      format('§70 (publish): the notice''s body is not the post''s first 280 characters (%s)', length(x->>'body')));
    PERFORM _assert((x->>'published_at')::timestamptz = (SELECT b.published_at FROM news_post b WHERE b.id = P)
                    AND (x->>'expires_at')::timestamptz = (x->>'published_at')::timestamptz + interval '60 days',
      '§70 (publish): the notice''s published_at is not the post''s, or it does not live sixty days');

    -- (draft) saved unsent: nothing; sent (POST /api/news/:id/publish): one
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, 'U14A', 'Verify 091 draft', 'Kit check on Monday.', NULL) RETURNING id INTO D;
    PERFORM _assert(jsonb_array_length(_notices_91(D)) = 0, '§70 (draft): a draft wrote a notice');
    UPDATE news_post SET published_at = now() WHERE id = D AND published_at IS NULL;
    j := _notices_91(D);
    PERFORM _assert(jsonb_array_length(j) = 1 AND j->0->>'urgency' = 'low' AND j->0->>'body' = 'Kit check on Monday.',
      format('§70 (draft): sending the draft wrote %s', j));
    ND := (j->0->>'id')::uuid;

    -- (edit) the author edits the sent post: the words follow, the time does not
    PERFORM _as(V_COACH);
    t0 := (x->>'published_at')::timestamptz;
    UPDATE news_post SET title = 'Verify 091 nets moved', body = 'Nets on Friday instead.' WHERE id = P;
    j := _notices_91(P);
    PERFORM _assert(jsonb_array_length(j) = 1 AND j->0->>'id' = NP::text AND j->0->>'title' = 'Verify 091 nets moved'
                    AND j->0->>'body' = 'Nets on Friday instead.' AND (j->0->>'published_at')::timestamptz = t0,
      format('§70 (edit): after the edit the post''s notices read %s', j));
    -- nobody else's edit lands (db/12)
    PERFORM _as(V_SARAH);
    UPDATE news_post SET body = 'Not mine to change.' WHERE id = P RETURNING id INTO v;
    PERFORM _assert(v IS NULL AND _notices_91(P)->0->>'body' = 'Nets on Friday instead.',
      '§70 (edit): somebody other than the author edited the post, or its notice');

    -- (urgency) never high; and a sent post's is fixed
    PERFORM _as(V_COACH);
    PERFORM _assert(_app_89(format($q$INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, urgency)
                                       VALUES ('team', %L, 'U14A', 'Verify 091 loud', 'Loud.', now(), 'high')$q$, V_HIL)) = 'news_post_urgency_known',
      '§70 (urgency): a post was sent high');
    got := _app_89(format('UPDATE news_post SET urgency = ''low'' WHERE id = %L', P));
    PERFORM _assert(got = 'news_post_urgency_sent' AND _notices_91(P)->0->>'urgency' = 'medium',
      '§70 (urgency): a sent post''s urgency was changed');
    PERFORM _assert(_app_89(format('UPDATE news_post SET urgency = ''medium'' WHERE id = %L', D)) = 'news_post_urgency_sent',
      '§70 (urgency): a sent draft''s urgency was changed');

    -- (app) D9: the application writes and edits no notice, the director of sport's publishing tiers notwithstanding
    PERFORM _as(V_SARAH);
    PERFORM _assert(_app_89(format($q$INSERT INTO notification (school_id, scope_level, kind, title, body)
                                       VALUES (%L, 'school', 'notice', 'Verify 091 typed', 'Typed.')$q$, V_HIL)) = '42501',
      '§70 (app): the application wrote a notice');
    UPDATE notification SET body = 'Rewritten.' WHERE id = NP RETURNING id INTO v;
    PERFORM _assert(v IS NULL AND _notices_91(P)->0->>'body' = 'Nets on Friday instead.',
      '§70 (app): the application rewrote a post''s notice');

    -- (league) the league's post: one notice per school entered, each at its school
    PERFORM _as(V_LEAGUE);
    INSERT INTO news_post (scope, competition_id, title, body, published_at)
    VALUES ('competition', V_COMP, 'Verify 091 league', 'Round five is on Saturday.', now()) RETURNING id INTO L;
    j := _notices_91(L);
    SELECT string_agg(e->>'scope_level' || ':' || (e->>'school_id'), ',' ORDER BY e->>'school_id') INTO got FROM jsonb_array_elements(j) e;
    PERFORM _assert(jsonb_array_length(j) = 2
                    AND got = (SELECT string_agg('competition:' || ce.school_id, ',' ORDER BY ce.school_id::text)
                                 FROM competition_entrant ce WHERE ce.competition_id = V_COMP),
      format('§70 (league): the league post''s notices are %s', got));

    -- (withdraw) a parent may not; the director of sport (news.publish.school) withdraws the coach's post
    PERFORM _as(V_KIN);
    got := _withdraw_91(P);
    PERFORM _assert(got = 'no_such_notice' AND (_row_89(NP)->>'retracted_at') IS NULL,
      '§70 (withdraw): a parent withdrew a post');
    PERFORM _as(V_SARAH);
    PERFORM _assert(_withdraw_91(P) = 'ok', '§70 (withdraw): the director of sport could not withdraw the coach''s post');
    x := _row_89(NP);
    PERFORM _assert(x->>'retraction_kind' = 'withdrawn' AND x->>'retracted_by' = V_SARAH::text AND (x->>'retracted_at') IS NOT NULL,
      format('§70 (withdraw): the notice reads retracted %s by %s', x->>'retraction_kind', x->>'retracted_by'));
    PERFORM _assert(_said_89(NP) = 1 AND _logged_89('notification.retract', NP) = 1,
      format('§70 (withdraw): %s "withdrawn" notices and %s log rows, not one each', _said_89(NP), _logged_89('notification.retract', NP)));
    got := _withdraw_91(P);
    PERFORM _assert((SELECT b.published_at FROM news_post b WHERE b.id = P) IS NULL AND got = 'no_such_notice',
      '§70 (withdraw): the post is still sent, or withdraws twice');
    -- The side's readers are told. Since db/101 a U14A post reaches the U14A
    -- side and nobody wider, and the seed has no U14A family: Hilton's office
    -- reads every side; the 1XI family reads neither notice (§78 proves the
    -- side's own families).
    PERFORM _as(V_REG);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM my_notifications WHERE id = NP)
                    AND EXISTS (SELECT 1 FROM my_notifications WHERE retracts_id = NP AND title = 'A notice was withdrawn'),
      '§70 (withdraw): the side''s readers still read the withdrawn notice, or were not told');
    PERFORM _as(V_KIN);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification WHERE id = NP OR retracts_id = NP),
      '§70 (withdraw): a 1XI family reads a U14A post''s notice, or its "withdrawn" one (db/101)');
    -- the author's own withdrawal, as the old route wrote it
    PERFORM _as(V_COACH);
    UPDATE news_post SET published_at = NULL WHERE id = D AND published_at IS NOT NULL;
    PERFORM _assert(_row_89(ND)->>'retraction_kind' = 'withdrawn' AND _row_89(ND)->>'retracted_by' = V_COACH::text AND _said_89(ND) = 1,
      '§70 (withdraw): the author''s withdrawal did not retract the notice as him');

    -- (report) the director of sport posts to the 1XI; its guardian reports the notice
    PERFORM _as(V_SARAH);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, '1XI', 'Verify 091 J Whitfield', 'Well batted J Whitfield.', now()) RETURNING id INTO R;
    NR := (_notices_91(R)->0->>'id')::uuid;

    -- (readers) the side's family and a pupil on it read it; another school's coach does not
    PERFORM _as(V_KIN);
    PERFORM _assert(EXISTS (SELECT 1 FROM my_notifications WHERE id = NR AND NOT tiered AND body IS NOT NULL),
      '§70 (readers): the 1XI guardian does not read the side''s notice');
    PERFORM _as(V_PUPIL);
    PERFORM _assert(EXISTS (SELECT 1 FROM my_notifications WHERE id = NR), '§70 (readers): a 1XI pupil does not read the side''s notice');
    PERFORM _as(V_WCOACH);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification WHERE id = NR), '§70 (readers): a coach at another school read the notice');

    PERFORM _as(V_KIN);
    PERFORM _assert(_report_91(NR) = 'ok', '§70 (report): the guardian''s report was refused');
    j := _reports_91(R);
    PERFORM _assert(jsonb_array_length(j) = 1, format('§70 (report): one report wrote %s DSO notices', jsonb_array_length(j)));
    x := j->0;
    got := concat_ws(' ', x->>'school_id' = V_HIL::text, x->>'scope_level', coalesce(x->>'team_code', '-'), x->>'urgency',
                     x->>'required_capability', coalesce(x->>'recipient_id', '-'), coalesce(x->>'subject_person_id', '-'),
                     coalesce(x->>'published_by', '-'), x->>'subject_id' = R::text, x->>'title');
    PERFORM _assert(got = 't school - high safeguarding.concern.read - - - t A notice was reported at your school',
      format('§70 (report): the DSO''s notice reads %s', got));
    PERFORM _assert(x->>'body' NOT ILIKE '%Whitfield%' AND x->>'body' NOT ILIKE '%Verify 091%' AND x->>'body' ILIKE '%the 1XI%'
                    AND x->>'body' NOT ILIKE '%Mokoena%' AND x->>'body' NOT ILIKE '%Pillay%',  -- the author; the pupil who reports next
      format('§70 (report): the DSO''s notice names somebody, or not where the notice went: %s', x->>'body'));
    PERFORM _assert(_logged_89('safeguarding.notice_report', NR) = 1, '§70 (report): the report is not on the log once');
    -- a repeat: refused, nothing written
    got := _report_91(NR);
    PERFORM _assert(got = 'already_reported' AND jsonb_array_length(_reports_91(R)) = 1
                    AND _logged_89('safeguarding.notice_report', NR) = 1,
      '§70 (report): a second report of the same notice by the same person was taken');
    -- another reader's report is his own
    PERFORM _as(V_PUPIL);
    got := _report_91(NR);
    PERFORM _assert(got = 'ok' AND jsonb_array_length(_reports_91(R)) = 2,
      '§70 (report): a pupil''s report of the same notice was refused, or wrote nothing');
    -- a non-reader, a system notice and a "withdrawn" notice: refused
    PERFORM _as(V_WCOACH);
    PERFORM _assert(_report_91(NR) = 'no_such_notice', '§70 (report): a coach at another school reported a notice he cannot read');
    PERFORM _as(V_KIN);
    PERFORM _assert(_report_91('40170000-0000-0000-0000-000000000001') = 'not_reportable',
      '§70 (report): a system notice was reported as a person''s words');
    PERFORM _as(V_REG);   -- a reader of the U14A side (db/101): the family reads none of it
    PERFORM _assert(_report_91((SELECT m.id FROM my_notifications m WHERE m.retracts_id = NP)) = 'not_reportable',
      '§70 (report): a "withdrawn" notice was reported');
    PERFORM _assert(_report_91(NP) = 'no_such_notice', '§70 (report): a withdrawn notice was reported');
    -- who reads what: the DSO the notice, the family not; the log the DSO's alone
    PERFORM _as(V_DSO);
    PERFORM _assert(EXISTS (SELECT 1 FROM my_notifications m WHERE m.id = (x->>'id')::uuid AND m.tiered AND m.body IS NULL),
      '§70 (report): the DSO does not read the report''s notice, or reads its body in the list');
    PERFORM _assert((SELECT count(*) FROM access_log l WHERE l.resource = 'safeguarding.notice_report' AND l.record_ids @> ARRAY[NR]) = 2,
      '§70 (report): the DSO does not read both reports on the log');
    PERFORM _as(V_KIN);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM my_notifications m WHERE m.id = (x->>'id')::uuid),
      '§70 (report): the reporting family reads the DSO''s notice');
    PERFORM _as(V_REG);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM access_log l WHERE l.resource = 'safeguarding.notice_report')
                    AND NOT EXISTS (SELECT 1 FROM audit_log(V_HIL, ARRAY['access'], NULL, NULL, NULL, 200) a
                                     WHERE a.detail->>'resource' = 'safeguarding.notice_report'),
      '§70 (report): the office (audit.read) reads who reported a notice');
    PERFORM _as(V_SARAH);
    PERFORM _assert(notification_report_about_me(ARRAY[NR]), '§70 (report): the author is not recognised as the notice''s author');
    PERFORM _as(V_DSO);
    PERFORM _assert(NOT notification_report_about_me(ARRAY[NR]), '§70 (report): the DSO is taken for the notice''s author');
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'access_log' AND policyname = 'access_log_notice_report_author'
                               AND permissive = 'RESTRICTIVE'),
      '§70 (report): nothing keeps the log row from the notice''s author');
    -- a school with no DSO (db/57's section appointed Westville one; his account is disabled): taken, and said to be unheld
    PERFORM _v81_deactivate('88888888-0000-0000-0000-000000005703');
    PERFORM _as(V_WCOACH);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_WES, '1XI', 'Verify 091 Westville', 'Nets on Tuesday.', now()) RETURNING id INTO W;
    NW := (_notices_91(W)->0->>'id')::uuid;
    PERFORM _as(V_WREG);
    got := _report_91(NW);
    PERFORM _assert(got = 'ok unheld', format('§70 (report): a report at a school with no DSO answered %s', got));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 70
  -- ┌── section 73: the school staff register (db/92, SCRBRD-140 phase 2) ──
  -- docs/design/SCRBRD-140_phase2_register.md §8 item 4, every proof it
  -- lists. _seed_92() builds its own world (see its comment). Claimants who
  -- have never been here sign in through auth_identity_sign_in(), as the
  -- exchange does; everything else runs as the person, under the
  -- application role.
  --
  --   (fences)    a guardian, player, selfaccess, enquiry, dso or platform
  --               row is refused at upload, and the CHECK refuses the first
  --               five written past the function; a role the uploader may
  --               not grant is refused; the owner's key is never listable
  --   (ceiling)   a role whose bundle holds medical.details.read,
  --               discipline.read or safeguarding.* is refused, read from
  --               role_capability; a role under it is not
  --   (shape)     a side for a coach, a real side at the school, a date in
  --               the window, one row per person, role and side; one bad
  --               row commits nothing
  --   (who)       only user.role.assign at the school uploads: never a
  --               coach, another school's office, a pad, or nobody
  --   (commit)    one upload id, the rows, the log; a row still open is not
  --               listed twice
  --   (warn)      an ending here in the last year warns; commit needs the
  --               warning's key; a live role here refuses; a role at another
  --               school is never mentioned
  --   (read)      the office reads the register; a coach, a parent, the
  --               DSO, a pad, a school-less account and another school's
  --               office do not; the table itself is nobody's
  --   (claim)     a new Google account's two rows both grant in one call,
  --               through the door, decided by the uploader, with one notice
  --               to the office; the account takes the school
  --   (once)      a claimed row is not claimed again, by its claimant or by
  --               another account sharing the address
  --   (match)     a code-only account, and app_user.email alone, match
  --               nothing; another school's row for the same address stays
  --   (first)     a person holding a duty-suspended assignment at the school
  --               cannot claim
  --   (lapsed)    an uploader who lost user.role.assign, or lost the grant of
  --               that role, grants nothing: consumed as requested, pending
  --   (pupil)     a pupil's account is consumed as requested, nothing granted
  --   (withdraw)  only whoever may list it; an open row only; it then
  --               matches nothing
  --   (expiry)    a row past its date matches nothing
  --   (redact)    ninety days after expiry or withdrawal, name and email go
  --               and the rest stays; never a claimed row; only the office
  --   (hand)      a hand grant through decide_role_request() still names its
  --               caller as the decider and still refuses a coach
  --   (door)      role_request_grant_as() is not the application's, and
  --               app_may_grant_at_for() still mirrors app_may_grant_at()
  --
  -- Falsified once each, the change made in the database as the owner before
  -- this file ran, and red at its own assertion:
  --   register_role_over_ceiling() made `false`      → (ceiling) red: medical,
  --                                                     schooladmin, directorofsport listed
  --   register_claim() without the P2-D4 refusal     → (first) red: the paused
  --                                                     teacher claimed
  --   step 1's two uploader re-checks removed        → (lapsed) red: granted
  --   the match also made on app_user.email          → (match) red: the code-only
  --                                                     account claimed
  --   school_register_rows()'s DSO cut inverted      → (read) red: the DSO read it
  --   app_may_grant_at_for() made `SELECT true`      → (lapsed) red: the demoted
  --                                                     principal's row granted
  --   app_may_grant_at_for() re-emitted without the
  --   account's `active`                             → (door) red: the mirror
  DECLARE
    ids       jsonb;
    HIL92     uuid := '11111111-1111-1111-1111-111111111111';
    WES92     uuid := '22222222-2222-2222-2222-222222222222';
    U_OFF     uuid; U_OFF2 uuid; U_HEAD uuid; U_DSO92 uuid; U_COACH92 uuid; U_WES uuid; U_WESDSO uuid;
    U_WESCOACH uuid; U_OWN92 uuid; U_PARENT92 uuid; U_PUPIL92 uuid; U_ENDED uuid; U_CODE uuid;
    U_DIFF uuid; U_TWIN1 uuid; U_TWIN2 uuid; U_PAUSED uuid;
    U_NEW     uuid; U_LAPSE1 uuid; U_LAPSE2 uuid; U_LATE uuid; U_ASK uuid; U_NOSCHOOL uuid;
    j         jsonb;
    x         jsonb;
    got       text;
    v_out     text;
    v_up      uuid;
    R_COACH   uuid; R_SCORER uuid; R_CODE uuid; R_DIFF uuid; R_TWIN uuid; R_PAUSED uuid; R_WES uuid;
    R_LAPSE1  uuid; R_LAPSE2 uuid; R_PUPIL uuid; R_WD uuid; R_LATE uuid;
    g         school_register;
    q         role_request;
    ra        role_assignment;
    n         notification;
    k         integer;
    k2        integer;
    v_req     uuid;
  BEGIN
    PERFORM set_config('app.user_id', '', true);
    ids := _seed_92();
    U_OFF := (ids->>'u_office')::uuid;    U_OFF2 := (ids->>'u_office2')::uuid;  U_HEAD := (ids->>'u_head')::uuid;
    U_DSO92 := (ids->>'u_dso')::uuid;     U_COACH92 := (ids->>'u_coach')::uuid; U_WES := (ids->>'u_wes')::uuid;
    U_WESDSO := (ids->>'u_wesdso')::uuid; U_WESCOACH := (ids->>'u_wescoach')::uuid;
    U_OWN92 := (ids->>'u_own')::uuid;     U_PARENT92 := (ids->>'u_parent')::uuid; U_PUPIL92 := (ids->>'u_pupil')::uuid;
    U_ENDED := (ids->>'u_ended')::uuid;   U_CODE := (ids->>'u_codeonly')::uuid; U_DIFF := (ids->>'u_differs')::uuid;
    U_TWIN1 := (ids->>'u_twin1')::uuid;   U_TWIN2 := (ids->>'u_twin2')::uuid;   U_PAUSED := (ids->>'u_paused')::uuid;

    -- ── (fences), (shape) — one file, every refusal, nothing written ──
    PERFORM _as(U_OFF);
    j := _up92(HIL92, jsonb_build_array(
      _r92('v92.newcoach@example.invalid', 'coach', 'U15A'),          -- 2  fine
      _r92('v92.g@example.invalid', 'guardian'),                       -- 3
      _r92('v92.p@example.invalid', 'player', 'U15A'),                 -- 4
      _r92('v92.s@example.invalid', 'selfaccess'),                     -- 5
      _r92('v92.e@example.invalid', 'enquiry'),                        -- 6
      _r92('v92.d@example.invalid', 'dso'),                            -- 7
      _r92('v92.o@example.invalid', 'superadmin'),                     -- 8
      _r92('v92.pa@example.invalid', 'platformadmin'),                 -- 9
      _r92('v92.h@example.invalid', 'principal'),                      -- 10 not the office's to grant
      _r92('v92.c1@example.invalid', 'coach'),                         -- 11 no side
      _r92('v92.c2@example.invalid', 'coach', 'XYZ'),                  -- 12 not a side
      _r92('v92.c3@example.invalid', 'coach', 'U13C'),                 -- 13 not a Hilton side
      _r92('V92.NEWCOACH@example.invalid ', 'Coach', 'u15a'),          -- 14 line 2 again, typed differently
      _r92('v92.coach@example.invalid', 'scorer'),                     -- 15 already Coach (U15A) here
      _r92('v92.past@example.invalid', 'scorer', NULL, to_char(current_date - 1, 'YYYY-MM-DD')),
      _r92('v92.far@example.invalid', 'scorer', NULL, to_char(current_date + 600, 'YYYY-MM-DD')),
      _r92('v92.bad@example.invalid', 'scorer', NULL, '31/12/2026'),
      _r92('v92.n@example.invalid', 'scorer', NULL, NULL, 'X'),
      _r92('not-an-address', 'scorer'),
      _r92('v92.who@example.invalid', 'wizard')), true);
    SELECT string_agg((e->>'line') || '=' || coalesce(e->>'problem', 'ok'), ' ' ORDER BY (e->>'line')::int) INTO got
      FROM jsonb_array_elements(j) e;
    PERFORM _assert(got = '2=ok 3=guardian_row 4=child_role 5=child_role 6=child_role 7=dso_row 8=not_grantable_here '
                          '9=not_grantable_here 10=not_grantable_here 11=team_required 12=team_invalid 13=team_unknown '
                          '14=duplicate_in_file 15=already_holds_role 16=valid_until_past 17=valid_until_too_far '
                          '18=valid_until_invalid 19=name_invalid 20=email_invalid 21=role_unknown',
      format('§73 (shape): the upload answered %s', got));
    PERFORM _assert((SELECT e->>'detail' FROM jsonb_array_elements(j) e WHERE e->>'line' = '15') = 'Coach (U15A)'
                    AND (SELECT e->>'detail' FROM jsonb_array_elements(j) e WHERE e->>'line' = '14') = '2',
      '§73 (shape): the refusals do not say which role, or which line');
    PERFORM _assert(_v92_rows(HIL92, 'v92.newcoach@example.invalid') = 0 AND (j->0->>'upload_id') IS NULL,
      '§73 (shape): a file with bad rows committed its good one');
    -- The CHECK, past the function.
    PERFORM set_config('app.user_id', '', true);
    FOREACH got IN ARRAY ARRAY['guardian', 'selfaccess', 'enquiry', 'player', 'dso'] LOOP
      PERFORM _assert(_v92_child_row(HIL92, U_OFF, got) = 'check_violation',
        format('§73 (fences): a %s row was written past register_upload()', got));
    END LOOP;
    -- The owner's key lists nothing of the platform's.
    PERFORM _as(U_OWN92);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.o2@example.invalid', 'superadmin'),
                                        _r92('v92.pa2@example.invalid', 'platformadmin')));
    PERFORM _assert(j->0->>'problem' = 'not_grantable_here' AND j->1->>'problem' = 'not_grantable_here',
      format('§73 (fences): the owner''s key listed a platform role: %s', j));

    -- ── (ceiling) ──
    PERFORM _as(U_HEAD);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.m@example.invalid', 'medical'),
                                        _r92('v92.sa@example.invalid', 'schooladmin'),
                                        _r92('v92.ds@example.invalid', 'directorofsport'),
                                        _r92('v92.sp@example.invalid', 'sportsadmin'),
                                        _r92('v92.fi@example.invalid', 'finance')));
    SELECT string_agg(coalesce(e->>'problem', 'ok'), ',' ORDER BY (e->>'line')::int) INTO got FROM jsonb_array_elements(j) e;
    PERFORM _assert(got = 'sensitive_role,sensitive_role,sensitive_role,ok,ok',
      format('§73 (ceiling): the principal''s upload answered %s', got));

    -- ── (who) ──
    FOREACH v_up IN ARRAY ARRAY[U_COACH92, U_WES, U_DSO92, U_PARENT92] LOOP
      PERFORM _as(v_up);
      j := _up92(HIL92, jsonb_build_array(_r92('v92.x@example.invalid', 'scorer')), true);
      PERFORM _assert(jsonb_array_length(j) = 1 AND j->0->>'problem' = 'not_permitted' AND (j->0->>'line')::int = 0,
        format('§73 (who): %s uploaded to Hilton''s register: %s', v_up, j));
    END LOOP;
    PERFORM _as(U_OFF);
    PERFORM set_config('app.scope', 'pad', true);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.x@example.invalid', 'scorer')), true);
    PERFORM set_config('app.scope', '', true);
    PERFORM _assert(j->0->>'problem' = 'not_permitted', '§73 (who): the office''s pad credential uploaded');
    PERFORM set_config('app.user_id', '', true);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.x@example.invalid', 'scorer')), true);
    PERFORM _assert(j->0->>'problem' = 'not_permitted', '§73 (who): nobody signed in uploaded');

    -- ── (commit) ──
    PERFORM _as(U_OFF);
    j := _up92(HIL92, jsonb_build_array(
      _r92('v92.newcoach@example.invalid', 'coach', 'U15A', NULL, 'V92 New Coach'),
      _r92('v92.newcoach@example.invalid', 'scorer', NULL, NULL, 'V92 New Coach'),
      _r92('v92.codeonly@example.invalid', 'scorer'),
      _r92('v92.differs@example.invalid', 'scorer'),
      _r92('v92.twin@example.invalid', 'scorer'),
      _r92('v92.paused@example.invalid', 'scorer'),
      -- Westville's coach: a role at another school is never mentioned
      _r92('v92.wescoach@example.invalid', 'analyst')), true);
    PERFORM _assert(jsonb_array_length(j) = 7 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(j) e
                                                               WHERE e->>'problem' IS NOT NULL OR e->>'warning' IS NOT NULL
                                                                  OR e->>'row_id' IS NULL),
      format('§73 (commit): the clean file answered %s', j));
    v_up := (j->0->>'upload_id')::uuid;
    PERFORM _assert(v_up IS NOT NULL AND (SELECT count(DISTINCT e->>'upload_id') FROM jsonb_array_elements(j) e) = 1,
      '§73 (commit): the rows do not share one upload id');
    R_COACH := (j->0->>'row_id')::uuid; R_SCORER := (j->1->>'row_id')::uuid; R_CODE := (j->2->>'row_id')::uuid;
    R_DIFF := (j->3->>'row_id')::uuid;  R_TWIN := (j->4->>'row_id')::uuid;   R_PAUSED := (j->5->>'row_id')::uuid;
    g := _v92_row(R_COACH);
    PERFORM _assert(g.email = 'v92.newcoach@example.invalid' AND g.role = 'coach' AND g.team_code = 'U15A'
                    AND g.uploaded_by = U_OFF AND g.upload_id = v_up AND g.claimed_at IS NULL
                    AND g.valid_until = (SELECT s.ends_on FROM season s WHERE s.level = 'school'
                                          AND current_date BETWEEN s.starts_on AND s.ends_on),
      format('§73 (commit): the row reads %s', row_to_json(g)));
    PERFORM _assert(_v92_log('register.upload', v_up) = 1 AND _v92_log('register.upload', R_PAUSED) = 1,
      '§73 (commit): the upload is not on the log once, with its rows');
    j := _up92(HIL92, jsonb_build_array(_r92('v92.newcoach@example.invalid', 'coach', 'U15A')), true);
    PERFORM _assert(j->0->>'problem' = 'already_listed' AND _v92_rows(HIL92, 'v92.newcoach@example.invalid') = 2,
      format('§73 (commit): an open row was listed twice: %s', j));
    -- The same address at Westville, by Westville's office.
    PERFORM _as(U_WES);
    j := _up92(WES92, jsonb_build_array(_r92('v92.newcoach@example.invalid', 'scorer', NULL, NULL, 'V92 New Coach')), true);
    R_WES := (j->0->>'row_id')::uuid;
    PERFORM _assert(R_WES IS NOT NULL, format('§73 (commit): Westville could not list the address: %s', j));

    -- ── (warn) ──
    PERFORM _as(U_OFF);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.ended@example.invalid', 'scorer')));
    x := j->0;
    PERFORM _assert((x->>'ok')::boolean AND x->>'warning' = 'recently_ended' AND (x->>'ended_on')::date = current_date
                    AND x->>'detail' = 'Coach (U15A)' AND (x->>'ack') IS NOT NULL,
      format('§73 (warn): the dry run answered %s', x));
    j := _up92(HIL92, jsonb_build_array(_r92('v92.ended@example.invalid', 'scorer')), true);
    PERFORM _assert(j->0->>'problem' = 'warning_not_acknowledged' AND _v92_rows(HIL92, 'v92.ended@example.invalid') = 0,
      format('§73 (warn): an unacknowledged warning committed: %s', j));
    j := _up92(HIL92, jsonb_build_array(_r92('v92.ended@example.invalid', 'scorer')), true, ARRAY[(x->>'ack')::uuid]);
    g := _v92_row((j->0->>'row_id')::uuid);
    PERFORM _assert(g.id IS NOT NULL AND g.warned_ended_on = current_date,
      format('§73 (warn): the acknowledged row was not written with its warning: %s', j));
    -- Westville's coach was listed above with no warning and no refusal.
    PERFORM _assert(_v92_rows(HIL92, 'v92.wescoach@example.invalid') = 1,
      '§73 (warn): another school''s coach was refused or warned about');

    -- ── (read) ──
    PERFORM _as(U_OFF);
    SELECT count(*) INTO k FROM school_register_rows(HIL92, NULL) r WHERE r.upload_id = v_up;
    SELECT count(*) INTO k2 FROM school_register_rows(HIL92, 'open') r WHERE r.upload_id = v_up AND r.uploaded_by_name = 'V92 Office';
    PERFORM _assert(k = 7 AND k2 = 7, format('§73 (read): the office reads %s of its 7 rows (%s open)', k, k2));
    FOREACH v_up IN ARRAY ARRAY[U_COACH92, U_PARENT92, U_DSO92, U_WES, U_CODE] LOOP
      PERFORM _as(v_up);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM school_register_rows(HIL92, NULL)),
        format('§73 (read): %s read Hilton''s register', v_up));
      PERFORM _assert(_v92_table_read() = 'refused', format('§73 (read): %s read school_register itself', v_up));
    END LOOP;
    PERFORM _as(U_OFF);
    PERFORM _assert(_v92_table_read() = 'refused', '§73 (read): the office read school_register itself');
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM school_register_rows(HIL92, NULL)), '§73 (read): a pad read the register');
    PERFORM set_config('app.scope', '', true);

    -- ── (claim) — a stranger to SCRBRD, listed twice ──
    PERFORM set_config('app.user_id', '', true);
    SELECT s.user_id INTO U_NEW FROM auth_identity_sign_in('google.com', 'v92-newcoach', 'V92.NewCoach@Example.invalid', 'V92 New Coach') s;
    PERFORM _assert(U_NEW IS NOT NULL AND (_v81_user(U_NEW)).school_id IS NULL, '§73 (claim): the newcomer is not a new account');
    PERFORM _as(U_NEW);
    got := _claim92(HIL92);
    PERFORM _assert(got = 'coach:U15A:granted,scorer::granted', format('§73 (claim): the claim answered %s', got));
    PERFORM _assert(_v92_held(U_NEW, HIL92) = 'coach:U15A,scorer', format('§73 (claim): the newcomer holds %s', _v92_held(U_NEW, HIL92)));
    PERFORM _assert((_v81_user(U_NEW)).school_id = HIL92, '§73 (claim): the account did not take the school');
    q := _v92_request(U_NEW, 'coach', HIL92);
    g := _v92_row(R_COACH);
    PERFORM _assert(q.state = 'granted' AND q.decided_by = U_OFF AND q.team_code = 'U15A'
                    AND q.decided_note = format('from the staff register, row %s, uploaded %s', R_COACH, to_char(g.uploaded_at, 'YYYY-MM-DD'))
                    AND q.assignment_id = (_v92_assignment(U_NEW, 'coach', HIL92)).id AND NOT q.asked_unverified,
      format('§73 (claim): the request reads %s', row_to_json(q)));
    PERFORM _assert(g.claimed_by = U_NEW AND g.outcome = 'granted' AND g.outcome_reason IS NULL AND g.claimed_request = q.id
                    AND g.claimed_identity = (_v81_identity('v92-newcoach')).id AND g.claimed_at IS NOT NULL,
      format('§73 (claim): the row reads %s', row_to_json(g)));
    PERFORM _assert((_v92_row(R_SCORER)).outcome = 'granted' AND _v92_log('register.claim', R_COACH) = 1
                    AND _v92_log('register.claim', R_SCORER) = 1,
      '§73 (claim): the second row was not granted, or the claim is not on the log per row');
    -- P2-D9: the identity keeps its honest linked_how.
    PERFORM _assert((_v81_identity('v92-newcoach')).linked_how = 'new_account', '§73 (claim): the identity was relabelled');
    -- The office is told, once; the coach and the newcomer are not.
    n := _v92_notice(HIL92, 'Joined from the staff register');
    PERFORM _assert(_v92_notices(HIL92, 'Joined from the staff register') = 1 AND n.kind = 'system' AND n.recipient_id IS NULL
                    AND n.required_capability = 'user.role.assign' AND n.scope_level = 'school'
                    AND n.body LIKE '%V92 New Coach joined as Coach (U15A) today, from the row V92 Office uploaded on%'
                    AND n.body LIKE '%V92 New Coach joined as Scorer today%' AND n.body LIKE '%end the role on People.',
      format('§73 (claim): the office''s notice reads %s', row_to_json(n)));
    PERFORM _as(U_OFF);
    PERFORM _assert(EXISTS (SELECT 1 FROM notification WHERE id = n.id), '§73 (claim): the office does not read its notice');
    FOREACH v_up IN ARRAY ARRAY[U_COACH92, U_NEW, U_DSO92] LOOP
      PERFORM _as(v_up);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification WHERE id = n.id),
        format('§73 (claim): %s read the office''s notice', v_up));
    END LOOP;
    -- On the next statement the newcomer is a Hilton coach.
    PERFORM _as(U_NEW);
    PERFORM _assert(app_enrolled() AND app_can('team.read', HIL92, 'U15A', '00000000-0000-0000-0000-000000000000'::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
      '§73 (claim): the granted coach cannot read his side');

    -- ── (once), (match) ──
    PERFORM _assert(_claim92(HIL92) = '-::no_match', '§73 (once): the claimant claimed again');
    PERFORM _assert((_v92_row(R_WES)).claimed_at IS NULL, '§73 (match): Westville''s row went with Hilton''s claim');
    PERFORM _as(U_TWIN1);
    PERFORM _assert(_claim92(HIL92) = 'scorer::granted', '§73 (once): the first twin could not claim');
    PERFORM _as(U_TWIN2);
    PERFORM _assert(_claim92(HIL92) = '-::no_match' AND (_v92_row(R_TWIN)).claimed_by = U_TWIN1
                    AND _v92_held(U_TWIN2, HIL92) = '',
      '§73 (once): the second account sharing the address claimed the row too');
    PERFORM _as(U_CODE);
    PERFORM _assert(_claim92(HIL92) = '-::no_match' AND (_v92_row(R_CODE)).claimed_at IS NULL,
      '§73 (match): a code-only account claimed by its typed address');
    PERFORM _as(U_DIFF);
    PERFORM _assert(_claim92(HIL92) = '-::no_match' AND (_v92_row(R_DIFF)).claimed_at IS NULL,
      '§73 (match): app_user.email matched where Google''s address did not');

    -- ── (first) — paused on a duty after his row was listed ──
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v92_pause(U_PAUSED, U_OFF);
    PERFORM _as(U_PAUSED);
    PERFORM _assert(_claim92(HIL92) = '-::no_match' AND (_v92_row(R_PAUSED)).claimed_at IS NULL
                    AND _v92_held(U_PAUSED, HIL92) = 'scorer'
                    AND (_v92_request(U_PAUSED, 'scorer', HIL92)).id IS NULL,
      '§73 (first): a person with a paused assignment here claimed, or asked');

    -- ── (lapsed) — the uploader lost the key; then lost the grant of the role ──
    PERFORM _as(U_OFF2);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.lapse1@example.invalid', 'scorer')), true);
    R_LAPSE1 := (j->0->>'row_id')::uuid;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _revoke(U_OFF2);
    SELECT s.user_id INTO U_LAPSE1 FROM auth_identity_sign_in('google.com', 'v92-lapse1', 'v92.lapse1@example.invalid', 'V92 Lapse') s;
    PERFORM _as(U_LAPSE1);
    got := _claim92(HIL92);
    g := _v92_row(R_LAPSE1);
    q := _v92_request(U_LAPSE1, 'scorer', HIL92);
    PERFORM _assert(got = 'scorer::requested' AND g.outcome = 'requested' AND g.outcome_reason = 'uploader_authority_lapsed'
                    AND q.state = 'pending' AND q.id = g.claimed_request AND _v92_held(U_LAPSE1, HIL92) = '',
      format('§73 (lapsed): a departed office''s row answered %s, the row %s', got, row_to_json(g)));
    PERFORM _assert((_v92_notice(HIL92, 'A staff register claim is waiting')).body LIKE '%is waiting in Requests.',
      '§73 (lapsed): the office is not told the claim waits');
    PERFORM _as(U_HEAD);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.lapse2@example.invalid', 'sportsadmin')), true);
    R_LAPSE2 := (j->0->>'row_id')::uuid;
    PERFORM _assert(R_LAPSE2 IS NOT NULL, format('§73 (lapsed): the principal could not list a sports administrator: %s', j));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v92_demote(U_HEAD);
    SELECT s.user_id INTO U_LAPSE2 FROM auth_identity_sign_in('google.com', 'v92-lapse2', 'v92.lapse2@example.invalid', 'V92 Lapse Two') s;
    PERFORM _as(U_LAPSE2);
    got := _claim92(HIL92);
    g := _v92_row(R_LAPSE2);
    PERFORM _assert(got = 'sportsadmin::requested' AND g.outcome_reason = 'uploader_authority_lapsed'
                    AND _v92_held(U_LAPSE2, HIL92) = '' AND (_v92_request(U_LAPSE2, 'sportsadmin', HIL92)).state = 'pending',
      format('§73 (lapsed): an uploader who may no longer grant the role granted it: %s', got));

    -- ── (pupil) — Westville lists a Hilton pupil's Google address ──
    PERFORM _as(U_WES);
    j := _up92(WES92, jsonb_build_array(_r92('v92.pupil@example.invalid', 'scorer')), true);
    R_PUPIL := (j->0->>'row_id')::uuid;
    PERFORM _as(U_PUPIL92);
    got := _claim92(WES92);
    g := _v92_row(R_PUPIL);
    PERFORM _assert(got = 'scorer::requested' AND g.outcome_reason = 'refused' AND _v92_held(U_PUPIL92, WES92) = ''
                    AND (_v92_request(U_PUPIL92, 'scorer', WES92)).state = 'pending',
      format('§73 (pupil): a pupil''s account answered %s and holds %s at Westville', got, _v92_held(U_PUPIL92, WES92)));
    -- At his own school he holds a role: the first door.
    PERFORM _assert(_claim92(HIL92) = '-::no_match', '§73 (pupil): the pupil claimed at his own school');

    -- ── (withdraw) ──
    PERFORM _as(U_OFF);
    j := _up92(HIL92, jsonb_build_array(_r92('v92.wd@example.invalid', 'scorer'), _r92('v92.late@example.invalid', 'scorer')), true);
    R_WD := (j->0->>'row_id')::uuid; R_LATE := (j->1->>'row_id')::uuid;
    FOREACH v_up IN ARRAY ARRAY[U_COACH92, U_WES, U_DSO92, U_NEW] LOOP
      PERFORM _as(v_up);
      SELECT CASE WHEN w.ok THEN 'ok' ELSE w.reason END INTO got FROM register_withdraw(R_WD) w;
      PERFORM _assert(got = 'not_permitted', format('§73 (withdraw): %s withdrew Hilton''s row: %s', v_up, got));
    END LOOP;
    PERFORM _as(U_OFF);
    SELECT CASE WHEN w.ok THEN 'ok' ELSE w.reason END INTO got FROM register_withdraw(R_WD) w;
    PERFORM _assert(got = 'ok' AND (_v92_row(R_WD)).withdrawn_by = U_OFF AND _v92_log('register.withdraw', R_WD) = 1,
      format('§73 (withdraw): the office''s withdrawal answered %s', got));
    SELECT CASE WHEN w.ok THEN 'ok' ELSE w.reason END INTO got FROM register_withdraw(R_WD) w;
    PERFORM _assert(got = 'already_withdrawn', format('§73 (withdraw): a second withdrawal answered %s', got));
    SELECT CASE WHEN w.ok THEN 'ok' ELSE w.reason END INTO got FROM register_withdraw(R_COACH) w;
    PERFORM _assert(got = 'already_claimed', format('§73 (withdraw): a claimed row answered %s', got));
    PERFORM set_config('app.user_id', '', true);
    SELECT s.user_id INTO v_up FROM auth_identity_sign_in('google.com', 'v92-wd', 'v92.wd@example.invalid', 'V92 Withdrawn') s;
    PERFORM _as(v_up);
    PERFORM _assert(_claim92(HIL92) = '-::no_match', '§73 (withdraw): a withdrawn row was claimed');

    -- ── (expiry) ──
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v92_age(R_LATE, current_date - 1, NULL);
    SELECT s.user_id INTO U_LATE FROM auth_identity_sign_in('google.com', 'v92-late', 'v92.late@example.invalid', 'V92 Late') s;
    PERFORM _as(U_LATE);
    PERFORM _assert(_claim92(HIL92) = '-::no_match' AND (_v92_row(R_LATE)).claimed_at IS NULL,
      '§73 (expiry): a row past its date was claimed');
    PERFORM _as(U_OFF);
    PERFORM _assert((SELECT r.state FROM school_register_rows(HIL92, NULL) r WHERE r.id = R_LATE) = 'expired',
      '§73 (expiry): the expired row does not read expired');
    -- Listing him again withdraws the expired row and opens a fresh one.
    j := _up92(HIL92, jsonb_build_array(_r92('v92.late@example.invalid', 'scorer')), true);
    PERFORM _assert(j->0->>'row_id' IS NOT NULL AND (_v92_row(R_LATE)).withdrawn_by = U_OFF,
      format('§73 (expiry): an expired row blocked a fresh listing: %s', j));
    PERFORM _as(U_LATE);
    PERFORM _assert(_claim92(HIL92) = 'scorer::granted', '§73 (expiry): the fresh listing could not be claimed');

    -- ── (redact) — ninety-one days on ──
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v92_age(R_LATE, NULL, now() - interval '91 days');
    PERFORM _v92_age(R_DIFF, current_date - 91, NULL);
    PERFORM _v92_age(R_CODE, current_date - 89, NULL);          -- not yet due
    PERFORM _as(U_COACH92);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM register_redact_due(HIL92)) AND _redact92(HIL92) = 'refused',
      '§73 (redact): a coach saw or cleared what is due');
    PERFORM _as(U_OFF);
    SELECT string_agg(d.id::text, ',' ORDER BY d.id) INTO got FROM register_redact_due(HIL92) d;
    PERFORM _assert(got = (SELECT string_agg(x2::text, ',' ORDER BY x2) FROM unnest(ARRAY[R_LATE, R_DIFF]) x2),
      format('§73 (redact): due are %s', got));
    PERFORM _assert(_redact92(HIL92) = '2', '§73 (redact): the office did not clear two rows');
    g := _v92_row(R_DIFF);
    PERFORM _assert(g.name = 'Redacted' AND g.email = 'redacted+' || R_DIFF || '@redacted.invalid' AND g.redacted_at IS NOT NULL
                    AND g.role = 'scorer' AND g.uploaded_by = U_OFF AND g.valid_until = current_date - 91,
      format('§73 (redact): the cleared row reads %s', row_to_json(g)));
    PERFORM _assert((_v92_row(R_CODE)).redacted_at IS NULL AND (_v92_row(R_COACH)).email = 'v92.newcoach@example.invalid'
                    AND NOT EXISTS (SELECT 1 FROM register_redact_due(HIL92)) AND _v92_log('register.redact', R_DIFF) = 1,
      '§73 (redact): a row not yet due, or a claimed row, was cleared; or nothing is on the log');

    -- ── (hand) — the office's own door, after the factoring ──
    PERFORM set_config('app.user_id', '', true);
    SELECT s.user_id INTO U_ASK FROM auth_identity_sign_in('google.com', 'v92-ask', 'v92.ask@example.invalid', 'V92 Ask') s;
    PERFORM _as(U_ASK);
    INSERT INTO role_request (person_id, role, school_id, team_code) VALUES (U_ASK, 'coach', HIL92, 'U15A') RETURNING id INTO v_req;
    PERFORM _as(U_COACH92);
    PERFORM _assert(_decide93(v_req, true) = 'not_permitted', '§73 (hand): a coach granted a request');
    PERFORM _as(U_OFF);
    PERFORM _assert(_decide93(v_req, true) = 'ok', '§73 (hand): the office could not grant a request');
    q := _v92_request(U_ASK, 'coach', HIL92);
    ra := _v92_assignment(U_ASK, 'coach', HIL92);
    PERFORM _assert(q.state = 'granted' AND q.decided_by = U_OFF AND q.decided_note = 'Verify 93'
                    AND ra.id = q.assignment_id AND ra.created_by = U_OFF AND ra.team_code = 'U15A',
      format('§73 (hand): the hand grant reads %s / %s', row_to_json(q), row_to_json(ra)));
    PERFORM _assert(_decide93(v_req, true) = 'already_decided', '§73 (hand): a request was granted twice');

    -- ── (door) ──
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'role_request_grant_as(uuid,uuid,text,uuid,text)', 'EXECUTE')
                    AND _door92(v_req, U_OFF) = 'refused',
      '§73 (door): the application may call role_request_grant_as()');
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'app_may_grant_at_for(uuid,text,uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'app_may_assign_at_for(uuid,uuid)', 'EXECUTE'),
      '§73 (door): the application may ask about somebody else''s authority');
    PERFORM _assert((SELECT p.prosrc FROM pg_proc p WHERE p.oid = 'app_may_grant_at_for(uuid,text,uuid)'::regprocedure)
                    = replace(replace((SELECT p.prosrc FROM pg_proc p WHERE p.oid = 'app_may_grant_at(text,uuid)'::regprocedure),
                                      'SELECT NOT app_pad_scoped() AND EXISTS (',
                                      'SELECT EXISTS (SELECT 1 FROM app_user u WHERE u.id = p_person AND u.active) AND EXISTS ('),
                              'app_user_id()', 'p_person'),
      '§73 (door): app_may_grant_at_for() no longer mirrors app_may_grant_at(); re-emit them together');
  END;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.scope', '', true);
  -- └── end of section 73
  -- ┌── section 74: a declined parent claim, and the request cooldown (db/93) ──
  -- docs/design/SCRBRD-140_phase2_register.md §4 and §8 item 4's last
  -- proofs, and the lead's review note (1): the cooldown refuses a register
  -- claim too, from the claim's own request.
  --
  --   (notice)    a declined guardian request writes exactly one
  --               safeguarding notice at its school, naming nobody; the DSO
  --               reads it, the office and a coach do not; a declined coach
  --               request writes none
  --   (cooldown)  the third decline in thirty days pauses the asker: every
  --               request route refuses with request_cooldown, the DSOs are
  --               told, the table is nobody's to read
  --   (claim)     a register claim under a cooldown raises the cooldown and
  --               consumes nothing (the lead's note (1))
  --   (lift)      only a DSO at one of its schools lifts it; not the office,
  --               not the owner's key, not another school's DSO; then the
  --               claim grants
  --   (schools)   guardian requests at three schools in thirty days pause on
  --               one decline; every school's DSOs are told; each may lift
  --   (signin)    a declined sign-in claim on a pupil's or a parent's
  --               account tells the DSO; on a coach's, nobody
  --
  -- Falsified once each, as the owner before this file ran:
  --   role_request_declined_notice disabled            → (notice) red: no notice
  --   role_request_cooldown disabled                   → (cooldown) red: asked again
  --   request_cooldown_lift() asking user.role.assign  → (lift) red: the office lifted
  DECLARE
    HIL93    uuid := '11111111-1111-1111-1111-111111111111';
    WES93    uuid := '22222222-2222-2222-2222-222222222222';
    ids      jsonb;
    TRD      uuid;
    U_OFF    uuid := _v92_id('v92.office@example.invalid');
    U_DSO93  uuid := _v92_id('v92.dso@example.invalid');
    U_COACH93 uuid := _v92_id('v92.coach@example.invalid');
    U_WES93  uuid := _v92_id('v92.wes@example.invalid');
    U_WESDSO93 uuid := _v92_id('v92.wesdso@example.invalid');
    U_OWN93  uuid := _v92_id('v92.own@example.invalid');
    U_TOFF   uuid; U_TDSO uuid;
    U_ASK1   uuid; U_ASK2 uuid;
    v_req    uuid;
    v_hil    uuid; v_trd uuid;
    v_row    uuid;
    v_pc     uuid;
    got      text;
    k        integer;
    k2       integer;
    k3       integer;
    n        notification;
    c        request_cooldown;
    j        jsonb;
    DECLINED text := 'A parent claim was declined';
    PAUSED   text := 'An account has been paused from asking';
    SIGNIN   text := 'A sign-in claim was declined';
  BEGIN
    PERFORM set_config('app.user_id', '', true);
    ids := _seed_93();
    TRD := (ids->>'school')::uuid; U_TOFF := (ids->>'u_office')::uuid; U_TDSO := (ids->>'u_dso')::uuid;
    SELECT s.user_id INTO U_ASK1 FROM auth_identity_sign_in('google.com', 'v93-ask1', 'v93.ask1@example.invalid', 'V93 Asker One') s;
    SELECT s.user_id INTO U_ASK2 FROM auth_identity_sign_in('google.com', 'v93-ask2', 'v93.ask2@example.invalid', 'V93 Asker Two') s;
    PERFORM _assert(U_OFF IS NOT NULL AND U_DSO93 IS NOT NULL AND U_ASK1 IS NOT NULL AND U_ASK2 IS NOT NULL,
      '§74: section 73''s accounts, or the askers, are missing');

    -- ── (notice) ──
    PERFORM _as(U_ASK1);
    v_req := _ask93('guardian', HIL93, 'For my son Kid Ninetythree in the U15A')::uuid;
    k := _v92_notices(HIL93, DECLINED);
    PERFORM _as(U_OFF);
    PERFORM _assert(_decide93(v_req, false) = 'ok', '§74 (notice): the office could not decline');
    n := _v92_notice(HIL93, DECLINED);
    PERFORM _assert(_v92_notices(HIL93, DECLINED) = k + 1,
      format('§74 (notice): one decline wrote %s notices', _v92_notices(HIL93, DECLINED) - k));
    PERFORM _assert(n.kind = 'safeguarding' AND n.required_capability = 'safeguarding.concern.read' AND n.recipient_id IS NULL
                    AND n.subject_person_id IS NULL AND n.team_code IS NULL AND n.scope_level = 'school' AND NOT n.is_public
                    AND n.body LIKE 'A request to be linked to a child at your school was declined by the office on %. The office can tell you who asked. If anything about it concerns you, raise a concern.',
      format('§74 (notice): the notice reads %s', row_to_json(n)));
    PERFORM _assert(n.body NOT ILIKE '%Ninetythree%' AND n.body NOT ILIKE '%Asker%' AND n.body NOT ILIKE '%v93.ask1%'
                    AND n.body NOT ILIKE '%U15A%' AND n.title NOT ILIKE '%Asker%',
      format('§74 (notice): the notice names somebody: %s', n.body));
    PERFORM _as(U_DSO93);
    PERFORM _assert(EXISTS (SELECT 1 FROM notification WHERE id = n.id), '§74 (notice): the DSO does not read it');
    FOREACH v_row IN ARRAY ARRAY[U_OFF, U_COACH93, U_ASK1, U_WESDSO93, U_OWN93] LOOP
      PERFORM _as(v_row);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification WHERE id = n.id),
        format('§74 (notice): %s read the DSO''s notice', v_row));
    END LOOP;
    -- A declined scorer's request is not a parent's claim.
    PERFORM _as(U_ASK1);
    v_req := _ask93('scorer', HIL93)::uuid;
    PERFORM _as(U_OFF);
    PERFORM _assert(_decide93(v_req, false) = 'ok' AND _v92_notices(HIL93, DECLINED) = k + 1,
      '§74 (notice): a declined scorer''s request told the DSO');

    -- ── (cooldown) — the second and third declines ──
    PERFORM _as(U_ASK1);
    v_req := _ask93('guardian', HIL93, 'Again')::uuid;
    PERFORM _as(U_OFF);
    PERFORM _assert(_decide93(v_req, false) = 'ok' AND _v93_cooldowns(U_ASK1) = 0,
      '§74 (cooldown): two declines paused the asker');
    PERFORM _as(U_ASK1);
    v_req := _ask93('guardian', HIL93, 'A third time')::uuid;
    k2 := _v92_notices(HIL93, PAUSED);
    PERFORM _as(U_OFF);
    PERFORM _assert(_decide93(v_req, false) = 'ok', '§74 (cooldown): the third decline failed');
    c := _v93_cooldown(U_ASK1);
    PERFORM _assert(_v93_cooldowns(U_ASK1) = 1 AND c.reason = 'repeated_declines' AND c.school_ids = ARRAY[HIL93]
                    AND c.until = now() + interval '30 days' AND c.lifted_at IS NULL,
      format('§74 (cooldown): the cooldown reads %s', row_to_json(c)));
    n := _v92_notice(HIL93, PAUSED);
    PERFORM _assert(_v92_notices(HIL93, PAUSED) = k2 + 1 AND n.kind = 'safeguarding' AND n.subject_id = c.id
                    AND n.required_capability = 'safeguarding.concern.read' AND n.body NOT ILIKE '%Asker%'
                    AND _v92_notices(HIL93, DECLINED) = k + 3,
      format('§74 (cooldown): the DSOs'' notice reads %s', row_to_json(n)));
    PERFORM _as(U_DSO93);
    PERFORM _assert(EXISTS (SELECT 1 FROM notification WHERE id = n.id), '§74 (cooldown): the DSO is not told of the pause');
    PERFORM _assert(_v93_table_read() = 'refused', '§74 (cooldown): the DSO read request_cooldown itself');
    PERFORM _as(U_ASK1);
    got := _ask93('scorer', HIL93);
    PERFORM _assert(got = 'raised 23514 request_cooldown', format('§74 (cooldown): a request under a cooldown answered %s', got));
    PERFORM _assert(_v93_table_read() = 'refused', '§74 (cooldown): the asker read request_cooldown');
    PERFORM set_config('app.user_id', '', true);
    got := _onboard93('v93.ask1@example.invalid', HIL93);
    PERFORM _assert(got = 'raised 23514 request_cooldown', format('§74 (cooldown): onboarding under a cooldown answered %s', got));

    -- ── (claim) — the lead's note (1) ──
    PERFORM _as(U_OFF);
    j := _up92(HIL93, jsonb_build_array(_r92('v93.ask1@example.invalid', 'scorer', NULL, NULL, 'V93 Asker One')), true);
    v_row := (j->0->>'row_id')::uuid;
    PERFORM _assert(v_row IS NOT NULL, format('§74 (claim): the office could not list the asker: %s', j));
    PERFORM _as(U_ASK1);
    got := _claim92(HIL93);
    PERFORM _assert(got = 'raised 23514 request_cooldown' AND (_v92_row(v_row)).claimed_at IS NULL
                    AND _v92_log('register.claim', v_row) = 0 AND _v92_held(U_ASK1, HIL93) = '',
      format('§74 (claim): a claim under a cooldown answered %s, or consumed its row', got));

    -- ── (lift) ──
    FOREACH v_req IN ARRAY ARRAY[U_OFF, U_OWN93, U_WESDSO93, U_ASK1, U_COACH93, U_TDSO] LOOP
      PERFORM _as(v_req);
      got := _lift93(c.id);
      PERFORM _assert(got = 'not_permitted', format('§74 (lift): %s lifting answered %s', v_req, got));
    END LOOP;
    PERFORM _as(U_DSO93);
    PERFORM _assert(_lift93(c.id) = 'ok', '§74 (lift): the DSO could not lift it');
    PERFORM _assert(_lift93(c.id) = 'already_lifted', '§74 (lift): lifted twice');
    c := _v93_cooldown(U_ASK1);
    PERFORM _assert(c.lifted_by = U_DSO93 AND c.lift_note = 'Verify 93: spoke to the family.'
                    AND _v92_log('safeguarding.cooldown_lift', c.id) = 1,
      format('§74 (lift): the lift reads %s', row_to_json(c)));
    PERFORM _as(U_ASK1);
    got := _claim92(HIL93);
    PERFORM _assert(got = 'scorer::granted', format('§74 (lift): after the lift the claim answered %s', got));

    -- ── (schools) — three schools in thirty days, one decline ──
    PERFORM _as(U_ASK2);
    v_hil := _ask93('guardian', HIL93)::uuid;
    v_req := _ask93('guardian', WES93)::uuid;
    v_trd := _ask93('guardian', TRD)::uuid;
    k := _v92_notices(HIL93, PAUSED); k2 := _v92_notices(WES93, PAUSED); k3 := _v92_notices(TRD, PAUSED);
    PERFORM _as(U_WES93);
    PERFORM _assert(_decide93(v_req, false) = 'ok', '§74 (schools): Westville could not decline');
    c := _v93_cooldown(U_ASK2);
    PERFORM _assert(c.reason = 'many_schools'
                    AND (SELECT array_agg(x ORDER BY x) FROM unnest(c.school_ids) x)
                        = (SELECT array_agg(x ORDER BY x) FROM unnest(ARRAY[HIL93, WES93, TRD]) x),
      format('§74 (schools): the cooldown reads %s', row_to_json(c)));
    PERFORM _assert(_v92_notices(HIL93, PAUSED) = k + 1 AND _v92_notices(WES93, PAUSED) = k2 + 1 AND _v92_notices(TRD, PAUSED) = k3 + 1,
      '§74 (schools): each school''s DSOs were not told once');
    PERFORM _as(U_ASK2);
    PERFORM _assert(_ask93('scorer', TRD) = 'raised 23514 request_cooldown', '§74 (schools): the asker asked again');
    PERFORM _as(U_TOFF);
    PERFORM _assert(_lift93(c.id) = 'not_permitted', '§74 (schools): the third school''s office lifted it');
    PERFORM _as(U_TDSO);
    PERFORM _assert(_lift93(c.id) = 'ok', '§74 (schools): the third school''s DSO could not lift it');

    -- ── (signin) — a stranger's Google sign-in reaching for a pupil's, a parent's, a coach's account ──
    k := _v92_notices(HIL93, SIGNIN);
    FOREACH got IN ARRAY ARRAY['pupil', 'parent', 'coach'] LOOP
      PERFORM set_config('app.user_id', '', true);
      PERFORM _assert((SELECT s.outcome FROM auth_identity_sign_in('google.com', 'v93-' || got, 'v92.' || got || '@example.invalid', 'Stranger') s)
                      = 'claim_required', format('§74 (signin): the %s''s address was not a claim', got));
      v_pc := _v93_claim('v93-' || got);
      PERFORM _as(U_OFF);
      PERFORM _assert((SELECT d.ok FROM pending_claim_decline(v_pc) d),
        format('§74 (signin): the office could not decline the %s claim', got));
    END LOOP;
    n := _v92_notice(HIL93, SIGNIN);
    PERFORM _assert(_v92_notices(HIL93, SIGNIN) = k + 2 AND n.kind = 'safeguarding' AND n.recipient_id IS NULL
                    AND n.required_capability = 'safeguarding.concern.read'
                    AND n.body NOT ILIKE '%Ninetytwo%' AND n.body NOT ILIKE '%Stranger%' AND n.body NOT ILIKE '%v92.%',
      format('§74 (signin): %s notices (two expected), the last %s', _v92_notices(HIL93, SIGNIN) - k, row_to_json(n)));
    PERFORM _as(U_DSO93);
    PERFORM _assert(EXISTS (SELECT 1 FROM notification WHERE id = n.id), '§74 (signin): the DSO does not read it');
    PERFORM _as(U_OFF);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification WHERE id = n.id), '§74 (signin): the office reads it');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 74

  -- ── 71. The cockpit's read fixes, held in the schema (SCRBRD-136/137 phase B, B0) ──
  -- docs/design/SCRBRD-136-137_phaseB.md §5 (PB-D8). Phase A's three read
  -- fixes live in services/api/read/read-api.mjs, which is JavaScript: the
  -- texts are held by services/api/read/read.test.mjs (statically) and by
  -- tools/smoke-cockpit.mjs (over HTTP, as each persona). This section holds
  -- the schema facts those texts rest on. No migration of its own.
  --
  -- What each label holds:
  --   (invoker)   bowler_over and bowler_spell are security_invoker views: a
  --               reader's spells are the log his own row security admits
  --   (directive) bowling_directive_for() is callable by scrbrd_app (the
  --               bowling_spells read's lateral) and answers the band and its
  --               limits for a boy the caller may read
  --   (gate)      bowling_spells' w.may and workload()'s boys CTE ask
  --               app_can('player.workload.read', …) per boy: the coach, the
  --               assistant coach and the physio hold it for the 17XI bowler;
  --               the team manager, a scorer and the other school's coach do not
  --   (spells)    the spell itself is the match's log: the team manager reads
  --               it; the other school's coach does not (not his fixture)
  --   (void)      ball_event_live drops a ball the scorer voided, so the
  --               match's wheel (shot_points) and the overs drop it too
  --   (workload)  workload() gives the team manager nothing and the coach and
  --               the assistant the bowler
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at its label:
  --   (invoker)   bowler_spell re-created WITH (security_invoker = false)
  --   (gate)      teammanager granted player.workload.read in role_capability
  --   (void)      ball_event_live without its void filter
  DECLARE
    x       jsonb := _v71_stage();
    V_HIL   uuid := '11111111-1111-1111-1111-111111111111';
    V_BOY   uuid := (x->>'boy')::uuid;
    V_M     uuid := (x->>'match')::uuid;
    ZERO    uuid := '00000000-0000-0000-0000-000000000000';
    k       text;
    d       record;
  BEGIN
    -- (invoker)
    PERFORM _assert((SELECT bool_and(coalesce(c.reloptions, '{}') @> ARRAY['security_invoker=true'])
                       FROM pg_class c WHERE c.oid IN ('bowler_over'::regclass, 'bowler_spell'::regclass)),
      '§71 (invoker): bowler_over or bowler_spell is not security_invoker');

    -- (directive)
    PERFORM _assert(has_function_privilege('scrbrd_app', 'bowling_directive_for(uuid)', 'EXECUTE'),
      '§71 (directive): the application cannot call bowling_directive_for()');
    PERFORM _as((x->>'coach')::uuid);
    SELECT * INTO d FROM bowling_directive_for(V_BOY);
    PERFORM _assert(d.age_band = 'U15' AND d.pace AND d.max_overs_per_spell = 6 AND d.max_overs_per_day = 12,
      format('§71 (directive): the 17XI bowler''s directive reads %s %s %s/%s', d.age_band, d.pace, d.max_overs_per_spell, d.max_overs_per_day));

    -- (gate): the expression both reads ask, per persona
    FOREACH k IN ARRAY ARRAY['coach', 'assistant', 'medical'] LOOP
      PERFORM _as((x->>k)::uuid);
      PERFORM _assert(app_can('player.workload.read', V_HIL, '17XI', V_BOY, ZERO),
        format('§71 (gate): the %s does not hold player.workload.read for the side''s bowler', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['manager', 'scorer', 'wescoach'] LOOP
      PERFORM _as((x->>k)::uuid);
      PERFORM _assert(NOT app_can('player.workload.read', V_HIL, '17XI', V_BOY, ZERO),
        format('§71 (gate): the %s holds player.workload.read for the side''s bowler', k));
    END LOOP;

    -- (spells)
    PERFORM _as((x->>'manager')::uuid);
    PERFORM _assert((SELECT count(*) FROM bowler_spell s WHERE s.match_id = V_M AND s.bowler_id = V_BOY) = 1,
      '§71 (spells): the team manager does not read the side''s spell (the match''s log is his)');
    PERFORM _as((x->>'wescoach')::uuid);
    PERFORM _assert((SELECT count(*) FROM bowler_spell s WHERE s.match_id = V_M) = 0,
      '§71 (spells): another school''s coach reads the spells of a fixture that is not his');

    -- (void): the seventh ball is on the record and out of the live log
    PERFORM _as((x->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM ball_event b WHERE b.match_id = V_M AND b.idempotency_key = 'v71-voided') = 1,
      '§71 (void): the voided ball is not on the record');
    PERFORM _assert((SELECT count(*) FROM ball_event_live b WHERE b.match_id = V_M AND b.idempotency_key = 'v71-voided') = 0,
      '§71 (void): ball_event_live still carries a voided ball');
    PERFORM _assert((SELECT count(*) FROM ball_event_live b WHERE b.match_id = V_M AND b.kind = 'ball') = 6
                    AND (SELECT sum(legal_balls) FROM bowler_over o WHERE o.match_id = V_M) = 6,
      '§71 (void): the live log or the overs count the voided ball');
    -- (workload)
    PERFORM _as((x->>'manager')::uuid);
    PERFORM _assert((SELECT count(*) FROM workload('17XI')) = 0, '§71 (workload): the team manager reads the side''s workload');
    FOREACH k IN ARRAY ARRAY['coach', 'assistant'] LOOP
      PERFORM _as((x->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM workload('17XI') w WHERE w.player_id = V_BOY AND w.overs_7d = 1) = 1,
        format('§71 (workload): the %s does not read the bowler''s one over', k));
    END LOOP;

  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 71

  -- ── 72. bowler_day(): a boy's overs today, across every match (db/94) ──
  -- docs/design/SCRBRD-136-137_phaseB.md §1.7 (PB-D1 to PB-D4). The API half
  -- is tools/smoke-cockpit.mjs (bowler_day over HTTP, as each persona); the
  -- card it feeds (S2c) is apps/web/test/signals.test.mjs's.
  --
  -- What each label holds:
  --   (sum)      the coach of the side reads the bowler's row: eleven overs
  --              from two matches on the day, one of them another side's, with
  --              the U15 directive (6 a spell, 12 a day) and its clause
  --   (rows)     a boy who has not bowled is a row with 0, not an absent one
  --   (readers)  the assistant coach, the physio, the S&C coach and the
  --              director of sport read the same row
  --   (owner)    so does the owner's key: superadmin holds every capability
  --              but safeguarding (roles.mjs ALL_CAPABILITIES, db/01), so the
  --              capability gate admits him at every school. The design's
  --              reader list (PB-D1) does not name him; roles are unchanged
  --   (refused)  the scorer, the team manager, a pupil on the side, the
  --              bowler's guardian, the coach of another side at the school
  --              and the other school's coach read no row for the side
  --   (self)     the boy, through self-access, reads his own row and nobody else's
  --   (spinner)  a spinner's row carries no day limit and no clause
  --   (date)     the date is the fixture's SA start date: three days ago is
  --              the spinner's two overs, not today's
  --   (agree)    for a boy whose only overs this week are today's, overs_today
  --              equals workload().overs_7d
  --   (doors)    a stable SECURITY DEFINER with a pinned path; executable by
  --              scrbrd_app and not by PUBLIC (nor anon/authenticated where a
  --              managed host has them); bowling_directive_for() likewise
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at its label:
  --   (sum)      bowler_day() with its day CTE filtered to one match
  --   (refused)  bowler_day() with the app_can() line removed from its boys CTE
  --   (self)     bowler_day() asking app_can() without the boy's id: the team
  --              and school scopes still answer, self-access no longer does
  --   (doors)    GRANT EXECUTE ON FUNCTION bowler_day(date, text) TO PUBLIC
  DECLARE
    y       jsonb := _v94_stage();
    V_QUICK uuid := (y->>'quick')::uuid;
    V_SPIN  uuid := (y->>'spin')::uuid;
    V_BAT   uuid := (y->>'bat')::uuid;
    V_OWN   uuid := '88888888-0000-0000-0000-000000000022';   -- superadmin, every capability
    k       text;
    r       record;
    got     text;
  BEGIN
    -- (sum)
    PERFORM _as((y->>'coach')::uuid);
    SELECT * INTO r FROM bowler_day(sa_today(), '18XI') b WHERE b.player_id = V_QUICK;
    got := concat_ws(' ', r.overs_today, r.matches_today, r.age_band, r.pace, r.max_overs_per_spell, r.max_overs_per_day,
                     r.clause_code, r.bowled_on = sa_today(), r.team_code);
    PERFORM _assert(got = '11 2 U15 t 6 12 PACE-U14-U15 t 18XI', format('§72 (sum): the coach reads the bowler''s day as %s', got));
    SELECT string_agg(b.full_name || ':' || b.overs_today, ', ' ORDER BY ord) INTO got
      FROM bowler_day(sa_today(), '18XI') WITH ORDINALITY AS b(player_id, full_name, team_code, school_id, bowled_on,
             overs_today, matches_today, age_band, pace, max_overs_per_spell, max_overs_per_day, clause_code, ord);
    PERFORM _assert(got = 'Verify NinetyFour Quick:11, Verify NinetyFour Spin:3, Verify NinetyFour Bat:0',
      format('§72 (sum): the side reads %s, most overs first', got));

    -- (rows)
    PERFORM _assert((SELECT count(*) FROM bowler_day(sa_today(), '18XI') b
                      WHERE b.player_id = V_BAT AND b.overs_today = 0 AND b.matches_today = 0) = 1,
      '§72 (rows): a boy who has not bowled is not a row with 0');

    -- (readers)
    FOREACH k IN ARRAY ARRAY['assistant', 'medical', 'fitness', 'director'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM bowler_day(sa_today(), '18XI') b
                        WHERE b.player_id = V_QUICK AND b.overs_today = 11 AND b.matches_today = 2) = 1,
        format('§72 (readers): the %s does not read the bowler''s day', k));
    END LOOP;

    -- (owner)
    PERFORM _as(V_OWN);
    PERFORM _assert((SELECT count(*) FROM bowler_day(sa_today(), '18XI') b WHERE b.player_id = V_QUICK AND b.overs_today = 11) = 1,
      '§72 (owner): the owner''s key does not read the bowler''s day, though it holds player.workload.read everywhere');

    -- (refused)
    FOREACH k IN ARRAY ARRAY['scorer', 'manager', 'pupil', 'guardian', 'othercoach', 'wescoach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM bowler_day(sa_today(), '18XI')) = 0
                      AND NOT EXISTS (SELECT 1 FROM bowler_day(sa_today(), NULL) b WHERE b.player_id IN (V_QUICK, V_SPIN, V_BAT)),
        format('§72 (refused): the %s reads an 18XI boy''s day', k));
    END LOOP;

    -- (self)
    PERFORM _as((y->>'self')::uuid);
    SELECT string_agg(b.player_id::text || ':' || b.overs_today, ',') INTO got FROM bowler_day(sa_today(), NULL) b;
    PERFORM _assert(got = V_QUICK::text || ':11', format('§72 (self): the boy''s own read is %s', got));

    -- (spinner)
    PERFORM _as((y->>'coach')::uuid);
    SELECT * INTO r FROM bowler_day(sa_today(), '18XI') b WHERE b.player_id = V_SPIN;
    PERFORM _assert(r.pace = false AND r.max_overs_per_day IS NULL AND r.max_overs_per_spell IS NULL AND r.clause_code IS NULL
                    AND r.overs_today = 3 AND r.matches_today = 1,
      format('§72 (spinner): the spinner''s row reads %s %s %s %s', r.pace, r.max_overs_per_day, r.clause_code, r.overs_today));

    -- (date)
    SELECT string_agg(b.full_name || ':' || b.overs_today || '/' || b.matches_today, ', ' ORDER BY b.full_name) INTO got
      FROM bowler_day(sa_today() - 3, '18XI') b;
    PERFORM _assert(got = 'Verify NinetyFour Bat:0/0, Verify NinetyFour Quick:0/0, Verify NinetyFour Spin:2/1',
      format('§72 (date): three days ago reads %s', got));

    -- (agree)
    PERFORM _assert((SELECT b.overs_today FROM bowler_day(sa_today(), '18XI') b WHERE b.player_id = V_QUICK)
                    = (SELECT w.overs_7d FROM workload('18XI') w WHERE w.player_id = V_QUICK),
      '§72 (agree): bowler_day and workload() disagree about a week that is one day');

    -- (doors)
    PERFORM _assert((SELECT prosecdef AND provolatile = 's' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                       FROM pg_proc WHERE oid = 'bowler_day(date,text)'::regprocedure),
      '§72 (doors): bowler_day is not a stable SECURITY DEFINER with a pinned path');
    FOREACH k IN ARRAY ARRAY['bowler_day(date,text)', 'bowling_directive_for(uuid)'] LOOP
      PERFORM _assert(has_function_privilege('scrbrd_app', k::regprocedure, 'EXECUTE'),
        format('§72 (doors): the application cannot call %s', k));
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                   WHERE p.oid = k::regprocedure AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
        format('§72 (doors): %s is executable by PUBLIC', k));
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                     AND has_function_privilege(g.oid, k::regprocedure, 'EXECUTE')),
        format('§72 (doors): a managed host''s API role can call %s', k));
    END LOOP;
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 72
  -- ┌── db/96 (section 76) ───────────────────────────────────────────
  -- ── 76. The plan to the side: a team post tagged to a fixture (db/96) ──
  -- docs/design/SCRBRD-138_phaseB.md §1–§2, §7.2 (PB-D1 to PB-D5). The
  -- audience and the anchor are proved here; the words are not (PB-D7): they
  -- are packages/policy/test/words.test.mjs's and
  -- services/api/write/news-api.test.mjs's. Every write below is a person's,
  -- through scrbrd_app under RLS; the owner's helpers (_v96_stage,
  -- _v96_named, _v96_pupil_recipients, _notices_91, _notice_57) stage or only
  -- read. Westville stands in for the design's Kearsney (not in the seed).
  --
  -- What each label holds:
  --   (readers)  the U15A coach sends a plan for U15A's fixture; it reads as
  --              kind plan on that fixture to the captain, a team-mate on
  --              the sheet, a boy on the roster and not on the sheet, a
  --              guardian of a U15A boy, the team manager and the assistant
  --              coach
  --              and the director of sport, who reads every side
  --   (others)   a U15B boy, his guardian, Westville's U15A coach, a
  --              Westville U15A boy, a follower (spectator), the school's
  --              finance office and an anonymous session read no row
  --   (notice)   the plan wrote ONE notice: news, the post, the side, for
  --              nobody, about nobody; the side's readers read it and the
  --              others above do not; no notification about the plan names
  --              anybody; nothing anywhere is addressed to a pupil but the
  --              system's own; and db/57's refusal of a private notice to a
  --              pupil still refuses
  --   (one)      a second live plan for the fixture and side is refused by
  --              the index, the coach's and the team manager's alike (his
  --              refusal is the index's, so news.publish.team let him by);
  --              a second draft is kept, and refused when it is sent
  --   (withdraw) after news_post_withdraw() the plan reads to nobody but its
  --              author, and the draft is sent; the withdrawn plan cannot be
  --              sent again while the new one is live
  --   (guard)    refused: a plan for another side's fixture, a plan to the
  --              school, a plan with no fixture, a post with a fixture, a
  --              kind nobody knows; on a sent plan a new fixture or a new
  --              kind; a draft's fixture still moves, and its side does not
  --              (db/84's anchor freeze, which this file relies on)
  --   (away)     Westville's coach sends his side's plan for the same
  --              fixture, from the away end; his boy reads it; no Hilton
  --              reader does, and Hilton's live plan stands beside it
  --   (writer)   the assistant coach, holding no news.publish.team, is
  --              refused the insert
  --   (public)   a plan cannot be asked onto the public home page
  --   (post)     an ordinary team post: the side's captain and guardian
  --              read it and its notice. Until db/101 the U15B parent and
  --              the follower read it too (the narrowing was the plan's
  --              alone); since db/101 (Kameel, 2026-10-14) they read neither
  --   (doors)    the four functions are SECURITY DEFINER with a pinned path;
  --              the two trigger functions are executable by neither
  --              scrbrd_app nor PUBLIC, the two reach functions by scrbrd_app
  --              and not by PUBLIC; both narrowing policies are RESTRICTIVE
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at its label:
  --   (one)      DROP INDEX news_post_plan_live (red at the coach's second
  --              live plan)
  --   (others)   DROP POLICY news_post_plan_side, and news_plan_reach()
  --              without its team.read clause (each red at the U15B parent);
  --              news_plan_reach() asking news.read where it asks team.read
  --              (red at the follower)
  --   (notice)   DROP POLICY notification_plan_side (red at the U15B parent)
  --   (guard)    news_post_plan_guard() without its side check (red at the
  --              other side's fixture); without its fixed check (red at the
  --              sent plan's new fixture)
  --   (public)   DROP TRIGGER news_post_public_not_plan (the request answered ok)
  DECLARE
    y        jsonb := _v96_stage();
    V_HIL    uuid := '11111111-1111-1111-1111-111111111111';
    V_WES    uuid := '22222222-2222-2222-2222-222222222222';
    F1       uuid := (y->>'f1')::uuid;
    F2       uuid := (y->>'f2')::uuid;
    F3       uuid := (y->>'f3')::uuid;
    P uuid; D uuid; W uuid; v uuid;
    j  jsonb;
    k  text;
    got text;
    ins text := $q$INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
                   VALUES (%L, %L, %L, %L, 'Bat first if we win it.', %s, %L, %L)$q$;
  BEGIN
    -- (readers)
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, 'U15A', 'The plan: v Westville U15A', 'Bat first if we win it. Captain and Mate open.', now(), 'plan', F1)
    RETURNING id INTO P;
    FOREACH k IN ARRAY ARRAY['captain', 'mate', 'reserve', 'guardian', 'manager', 'assistant', 'coach', 'director'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P AND n.kind = 'plan' AND n.fixture_id = F1) = 1,
        format('§76 (readers): the %s does not read the side''s plan', k));
    END LOOP;

    -- (others)
    FOREACH k IN ARRAY ARRAY['bboy', 'bparent', 'wescoach', 'wesboy', 'follower', 'finance'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P) = 0
                      AND (SELECT count(*) FROM news_post n WHERE n.fixture_id = F1 AND n.school_id = V_HIL) = 0,
        format('§76 (others): the %s reads Hilton U15A''s plan', k));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P OR n.kind = 'plan') = 0,
      '§76 (others): an anonymous session reads a plan');

    -- (notice)
    j := _notices_91(P);
    got := concat_ws(' ', jsonb_array_length(j), j->0->>'kind', j->0->>'subject_kind', (j->0->>'subject_id' = P::text),
                     j->0->>'scope_level', (j->0->>'school_id' = V_HIL::text), j->0->>'team_code', j->0->>'required_capability',
                     j->0->>'urgency', coalesce(j->0->>'recipient_id', '-'), coalesce(j->0->>'subject_person_id', '-'));
    PERFORM _assert(got = '1 notice news t team t U15A news.read low - -', format('§76 (notice): the plan''s notices read %s', got));
    PERFORM _assert(_v96_named(P) = '1 rows, 0 to somebody, 0 about somebody', format('§76 (notice): about the plan, %s', _v96_named(P)));
    FOREACH k IN ARRAY ARRAY['captain', 'mate', 'reserve', 'guardian', 'manager', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM my_notifications n WHERE n.subject_kind = 'news' AND n.subject_id = P) = 1,
        format('§76 (notice): the %s does not have the plan''s notice', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['bboy', 'bparent', 'wescoach', 'wesboy', 'follower', 'finance'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id = P) = 0,
        format('§76 (notice): the %s reads the plan''s notice', k));
    END LOOP;
    PERFORM _assert(_v96_pupil_recipients() = 0,
      format('§76 (notice): %s notifications are addressed to a pupil and are not the system''s', _v96_pupil_recipients()));
    PERFORM _assert(_notice_57((y->>'captain')::uuid, 'lift') = 'refused',
      '§76 (notice): db/57 no longer refuses a private notice to a pupil');
    PERFORM _assert(_v96_pupil_recipients() = 0, '§76 (notice): db/57''s refusal left a row behind');

    -- (one)
    PERFORM _as((y->>'coach')::uuid);
    got := _app_89(format(ins, 'team', V_HIL, 'U15A', 'The plan, again', 'now()', 'plan', F1));
    PERFORM _assert(got = 'news_post_plan_live', format('§76 (one): the coach''s second live plan answered %s', got));
    PERFORM _as((y->>'manager')::uuid);
    got := _app_89(format(ins, 'team', V_HIL, 'U15A', 'The manager''s plan', 'now()', 'plan', F1));
    PERFORM _assert(got = 'news_post_plan_live', format('§76 (one): the team manager''s second live plan answered %s', got));
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, 'U15A', 'The plan: v Westville U15A', 'Bowl first; Mate from the top end.', NULL, 'plan', F1)
    RETURNING id INTO D;
    PERFORM _assert(D IS NOT NULL, '§76 (one): a second plan kept as a draft was refused');
    got := _app_89(format('UPDATE news_post SET published_at = now() WHERE id = %L AND published_at IS NULL', D));
    PERFORM _assert(got = 'news_post_plan_live', format('§76 (one): sending the draft beside a live plan answered %s', got));

    -- (withdraw)
    PERFORM _assert(_withdraw_91(P) = 'ok', '§76 (withdraw): the author could not withdraw the plan');
    FOREACH k IN ARRAY ARRAY['captain', 'guardian', 'manager'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P) = 0,
        format('§76 (withdraw): the %s still reads the withdrawn plan', k));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P AND n.published_at IS NULL) = 1,
      '§76 (withdraw): the withdrawn plan is not its author''s draft');
    got := _app_89(format('UPDATE news_post SET published_at = now() WHERE id = %L AND published_at IS NULL', D));
    PERFORM _assert(got = 'ok' AND (SELECT n.published_at IS NOT NULL FROM news_post n WHERE n.id = D),
      format('§76 (withdraw): after the withdrawal the draft could not be sent (%s)', got));
    PERFORM _as((y->>'captain')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = D) = 1, '§76 (withdraw): the captain does not read the new plan');
    PERFORM _as((y->>'coach')::uuid);
    got := _app_89(format('UPDATE news_post SET published_at = now() WHERE id = %L AND published_at IS NULL', P));
    PERFORM _assert(got = 'news_post_plan_live', format('§76 (withdraw): the withdrawn plan was sent again beside the new one (%s)', got));
    PERFORM _assert(_v96_named(P) = '2 rows, 0 to somebody, 0 about somebody',
      format('§76 (withdraw): about the withdrawn plan, %s (its notice and the one "withdrawn")', _v96_named(P)));

    -- (guard)
    PERFORM _as((y->>'coach')::uuid);
    FOREACH k IN ARRAY ARRAY[
      format(ins, 'team', V_HIL, 'U15A', 'Another side''s fixture', 'now()', 'plan', F3) || ' -> news_post_plan_side',
      format(ins, 'team', V_HIL, 'U15A', 'Another side''s fixture, a draft', 'NULL', 'plan', F3) || ' -> news_post_plan_side',
      format(ins, 'school', V_HIL, NULL, 'To the school', 'now()', 'plan', F2) || ' -> news_post_plan_anchored',
      format(ins, 'team', V_HIL, 'U15A', 'No fixture', 'now()', 'plan', NULL) || ' -> news_post_plan_anchored',
      format(ins, 'team', V_HIL, 'U15A', 'A post with a fixture', 'now()', 'post', F2) || ' -> news_post_post_unanchored',
      format(ins, 'team', V_HIL, 'U15A', 'A kind nobody knows', 'now()', 'note', F2) || ' -> news_post_kind_known',
      format('UPDATE news_post SET fixture_id = %L WHERE id = %L', F2, D) || ' -> news_post_plan_fixed',
      format('UPDATE news_post SET kind = ''post'', fixture_id = NULL WHERE id = %L', D) || ' -> news_post_plan_fixed',
      -- the side never moves on any post: db/84's anchor freeze, 42501
      format('UPDATE news_post SET team_code = ''U15B'', fixture_id = %L WHERE id = %L', F3, P) || ' -> 42501',
      format('UPDATE news_post SET fixture_id = %L WHERE id = %L', F2, P) || ' -> ok'] LOOP
      got := _app_89(split_part(k, ' -> ', 1));
      PERFORM _assert(got = split_part(k, ' -> ', 2),
        format('§76 (guard): %s answered %s, not %s', left(split_part(k, ' -> ', 1), 120), got, split_part(k, ' -> ', 2)));
    END LOOP;
    PERFORM _assert((SELECT n.fixture_id FROM news_post n WHERE n.id = D) = F1 AND (SELECT n.kind FROM news_post n WHERE n.id = D) = 'plan',
      '§76 (guard): the sent plan''s fixture or kind moved');
    PERFORM _assert((SELECT n.fixture_id FROM news_post n WHERE n.id = P) = F2, '§76 (guard): the draft''s fixture did not move');

    -- (away)
    PERFORM _as((y->>'wescoach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_WES, 'U15A', 'The plan: at Hilton U15A', 'Bowl first if we win it.', now(), 'plan', F1)
    RETURNING id INTO W;
    PERFORM _assert(W IS NOT NULL, '§76 (away): Westville''s coach could not send his side''s plan for the fixture');
    PERFORM _as((y->>'wesboy')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = W) = 1, '§76 (away): the Westville boy does not read his side''s plan');
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = D) = 0, '§76 (away): the Westville boy reads Hilton''s plan');
    FOREACH k IN ARRAY ARRAY['coach', 'manager', 'captain', 'mate', 'reserve', 'guardian', 'bboy', 'bparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = W) = 0,
        format('§76 (away): the Hilton %s reads Westville''s plan', k));
    END LOOP;
    PERFORM _as((y->>'captain')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = D AND n.published_at IS NOT NULL) = 1,
      '§76 (away): Hilton''s live plan does not stand beside Westville''s');
    PERFORM _assert(_v96_named(W) = '1 rows, 0 to somebody, 0 about somebody'
                    AND (_notices_91(W)->0->>'school_id') = V_WES::text,
      format('§76 (away): Westville''s plan''s notice is %s', _notices_91(W)));

    -- (writer)
    PERFORM _as((y->>'assistant')::uuid);
    got := _app_89(format(ins, 'team', V_HIL, 'U15A', 'The assistant''s plan', 'NULL', 'plan', F2));
    PERFORM _assert(got = '42501', format('§76 (writer): the assistant coach''s plan answered %s', got));

    -- (public)
    PERFORM _as((y->>'coach')::uuid);
    got := _app_89(format('SELECT * FROM news_public_request(%L)', D));
    PERFORM _assert(got = 'news_post_public_not_plan', format('§76 (public): asking for the plan on the home page answered %s', got));

    -- (post)
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, 'U15A', 'Verify 096 nets', 'Nets at three on Thursday.', now()) RETURNING id INTO v;
    -- db/101 (Kameel, 2026-10-14: "Yes, in its own migration") narrowed an
    -- ordinary team post to the side as well: the U15B parent and the
    -- follower, who read it here before db/101, now read neither it nor its
    -- notice. §78 is the full proof.
    FOREACH k IN ARRAY ARRAY['captain', 'guardian'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = v) = 1
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id = v) = 1,
        format('§76 (post): the %s no longer reads an ordinary U15A post or its notice', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['bparent', 'follower'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = v) = 0
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id = v) = 0,
        format('§76 (post): the %s reads an ordinary U15A post or its notice (db/101 keeps it to the side)', k));
    END LOOP;

    -- (doors)
    FOREACH k IN ARRAY ARRAY['news_plan_reach(uuid,text)', 'news_notice_reach(uuid)'] LOOP
      PERFORM _assert((SELECT prosecdef AND provolatile = 's' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = k::regprocedure),
        format('§76 (doors): %s is not a stable SECURITY DEFINER with a pinned path', k));
      PERFORM _assert(has_function_privilege('scrbrd_app', k::regprocedure, 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = k::regprocedure AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
        format('§76 (doors): %s is not the application''s alone', k));
    END LOOP;
    PERFORM _assert((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE' AND cmd = 'SELECT'
                       AND (tablename, policyname) IN (('news_post', 'news_post_plan_side'), ('notification', 'notification_plan_side'))) = 2,
      '§76 (doors): the plan''s two narrowing policies are not both RESTRICTIVE SELECT policies');
    FOREACH k IN ARRAY ARRAY['news_post_plan_guard()', 'news_post_public_not_plan()'] LOOP
      PERFORM _assert((SELECT prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = k::regprocedure),
        format('§76 (doors): %s is not a SECURITY DEFINER with a pinned path', k));
      PERFORM _assert(NOT has_function_privilege('scrbrd_app', k::regprocedure, 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = k::regprocedure AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
        format('§76 (doors): %s is executable by the application or by PUBLIC', k));
    END LOOP;
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 76
  -- └── db/96 (section 76) ───────────────────────────────────────────

  -- ┌── db/97 (section 75) ──────────────────────────────────────────────
  -- ── 75. The ball log follows the fixture: the away side reads its match (db/97) ──
  -- docs/design/SCRBRD-136-137_away_visibility.md §9 (AV-D1 to AV-D5). The
  -- API half is tools/smoke-cockpit.mjs's group 5; the read texts it rests on
  -- are services/api/read/read.test.mjs's. Rows are _v97_stage()'s, invented.
  --
  -- What each label holds:
  --   (rule)      for every reader below and each of the three fixtures, the
  --               balls row security admits are exactly the ones the rule
  --               admits (host branch OR away branch, asked with app_can()
  --               apart from the policy), in ball_event and ball_event_live
  --   (each way)  both coaches read every ball of both shared fixtures, as
  --               many as the owner; a pupil and a spectator of each school
  --               read the other school's fixture whole (AV-D5)
  --   (unchanged) a reader of the host school reads exactly what the host
  --               branch alone (db/02's policy) gave; what a visitor gained
  --               is the away branch and nothing else
  --   (per boy)   the API's bowling_spells at Hilton's fixture, as
  --               Westville's coach: his quick's spell with the U15 directive
  --               filled, the flag a boolean, no breach; Hilton's quick's
  --               spell is in the log (bowler_spell) but not in the read:
  --               the read joins player, whose record is not Westville's,
  --               and the load gate answers false for him. The mirror at
  --               Westville's fixture, as Hilton's coach. (The design's §9
  --               item 2 expected the host's boy as a row with the directive
  --               null; the join drops the row, which is narrower.)
  --   (refused)   the third school's coach and spectator read neither shared
  --               fixture nor any ball of it, without an error; Hilton's coach
  --               of another side reads what the host branch gave him: none
  --   (pupils)    each pupil reads the other school's fixture, and his own
  --               wheel across both (36 and 72 balls); the other school's
  --               boy's wheel is refused (his record is not the pupil's)
  --   (guardians) each guardian reads both shared fixtures' rows. As db/97
  --               left it, no ball of either (the log asked about nobody in
  --               particular, and a guardian's assignment is about one
  --               child); db/100 (§77) changed that: each reads both shared
  --               fixtures whole, since his child's side plays both, and his
  --               own child's wheel and not the other's. The (rule) and
  --               (unchanged) loops no longer list the guardians
  --   (pad)       Westville's coach, scorer and spectator read none of
  --               Hilton's fixture's session, held ball or audit row (each
  --               exists); Westville's scorer, holding the token, cannot write
  --               a ball to it: ball_event_insert refuses (AV-D4)
  --   (no away)   a fixture with no away school: Hilton's coach reads it,
  --               Westville's reads none, and nothing raises (in (rule))
  --   (columns)   ball_event's columns are a fixed list: a medical, note or
  --               PII column on the log fails here before it is widened
  --   (text)      ball_event_read names away_school_id and away_team_code and
  --               match_team( once; the writes and the pad's policies name no
  --               away anchor; the chain the away branch rides is
  --               security_invoker
  --   (day)       bowler_day for Westville's quick, as his coach, is the sum
  --               of his spells across both fixtures: seven, two matches
  --
  -- Falsified once, by putting db/02's host-only ball_event_read back in the
  -- database and running this file with each assertion made to report
  -- rather than raise: red at (rule) for every visiting reader (the coach,
  -- scorer, spectator and pupil of each school at the other's fixture: 0
  -- balls where the rule gives 48 or 60), (each way), (per boy) (no spell
  -- of either quick at the other school's fixture), (pupils) (each wheel
  -- short by the away innings: 18 of 36, 30 of 72), (text) and (day)
  -- (bowler_day 7, the readable spells 4). (unchanged), (refused),
  -- (guardians), (pad), (columns) stayed green, as they should: they hold
  -- what db/97 must not change. db/71 (scope) went red first.
  DECLARE
    z       jsonb := _v97_stage();
    V_FH    uuid := (z->>'fh')::uuid;
    V_FW    uuid := (z->>'fw')::uuid;
    V_FN    uuid := (z->>'fn')::uuid;
    V_HQ    uuid := (z->>'h_quick')::uuid;
    V_WQ    uuid := (z->>'w_quick')::uuid;
    V_HB    uuid := (z->>'h_bat')::uuid;
    V_WB    uuid := (z->>'w_bat')::uuid;
    V_OWN   uuid := '88888888-0000-0000-0000-000000000022';
    ZERO    uuid := '00000000-0000-0000-0000-000000000000';
    k       text;
    f       uuid;
    rr      record;
    n       int;
    n2      int;
    got     text;
    q       text;
  BEGIN
    -- (rule), for every reader and every fixture (the guardians are
    -- db/100's third branch since, and held to it below and in §77)
    FOREACH k IN ARRAY ARRAY['hilcoach', 'hil2coach', 'hilscorer', 'hilspec', 'hilpupil',
                             'wescoach', 'wesscorer', 'wesspec', 'wespupil', 'kcoach', 'kspec'] LOOP
      PERFORM _as((z->>k)::uuid);
      FOREACH f IN ARRAY ARRAY[V_FH, V_FW, V_FN] LOOP
        rr := _v97_rule(f);
        SELECT count(*) INTO n FROM ball_event b WHERE b.match_id = f;
        SELECT count(*) INTO n2 FROM ball_event_live b WHERE b.match_id = f;
        PERFORM _assert(n = rr.either AND n2 = rr.either,
          format('§75 (rule): as %s at %s, row security admits %s balls (%s live) where the rule gives %s (host %s, away %s, of %s)',
                 k, CASE f WHEN V_FH THEN 'Hilton''s fixture' WHEN V_FW THEN 'Westville''s fixture' ELSE 'the unshared fixture' END,
                 n, n2, rr.either, rr.host, rr.away, rr.total));
      END LOOP;
    END LOOP;

    -- (each way)
    PERFORM _as(V_OWN);
    SELECT count(*) INTO n FROM bowler_over WHERE match_id IN (V_FH, V_FW) AND bowler_id IS NOT NULL;
    PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = V_FH) = 48 AND (SELECT count(*) FROM ball_event WHERE match_id = V_FW) = 60
                    AND n = 11,
      format('§75 (each way): the owner''s count of the shared fixtures is not 48 and 60 balls and 11 overs by a boy on record (%s overs)', n));
    FOREACH k IN ARRAY ARRAY['hilcoach', 'wescoach'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = V_FH) = 48
                      AND (SELECT count(*) FROM ball_event WHERE match_id = V_FW) = 60
                      AND (SELECT count(*) FROM bowler_over WHERE match_id IN (V_FH, V_FW) AND bowler_id IS NOT NULL) = n,
        format('§75 (each way): the %s does not read every ball and over of both shared fixtures', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['wespupil', 'wesspec', 'wesscorer'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = V_FH) = 48,
        format('§75 (each way): Westville''s %s does not read Hilton''s fixture whole', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['hilpupil', 'hilspec', 'hilscorer'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = V_FW) = 60,
        format('§75 (each way): Hilton''s %s does not read Westville''s fixture whole', k));
    END LOOP;

    -- (unchanged): the host's readers at the host's fixture, the visitors at
    -- their own, and every reader at the unshared one, read what db/02 gave
    FOREACH k IN ARRAY ARRAY['hilcoach', 'hil2coach', 'hilscorer', 'hilspec', 'hilpupil', 'kcoach', 'kspec'] LOOP
      PERFORM _as((z->>k)::uuid);
      FOREACH f IN ARRAY ARRAY[V_FH, V_FN] LOOP
        PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = f) = (_v97_rule(f)).host,
          format('§75 (unchanged): as %s, a Hilton-hosted fixture reads other than the host branch gave', k));
      END LOOP;
    END LOOP;
    FOREACH k IN ARRAY ARRAY['wescoach', 'wesscorer', 'wesspec', 'wespupil'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = V_FW) = (_v97_rule(V_FW)).host,
        format('§75 (unchanged): as %s, Westville''s own fixture reads other than the host branch gave', k));
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = V_FN) = 0,
        format('§75 (unchanged): as %s, a Hilton fixture with no away school is read', k));
    END LOOP;
    -- ...and what a visitor gained is exactly the away branch
    FOREACH k IN ARRAY ARRAY['wescoach', 'wespupil', 'wesspec'] LOOP
      PERFORM _as((z->>k)::uuid);
      rr := _v97_rule(V_FH);
      PERFORM _assert(rr.host = 0 AND rr.away = 48 AND rr.total = 48, format('§75 (unchanged): as %s at Hilton, host %s away %s', k, rr.host, rr.away));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['hilcoach', 'hilpupil', 'hilspec'] LOOP
      PERFORM _as((z->>k)::uuid);
      rr := _v97_rule(V_FW);
      PERFORM _assert(rr.host = 0 AND rr.away = 60 AND rr.total = 60, format('§75 (unchanged): as %s at Westville, host %s away %s', k, rr.host, rr.away));
    END LOOP;

    -- (per boy), at Hilton's fixture as Westville's coach
    PERFORM _as((z->>'wescoach')::uuid);
    SELECT string_agg(concat_ws(' ', s.overs, s.age_band, s.pace, s.max_overs_per_spell, s.max_overs_per_day,
                                s.over_spell_limit, s.breach_recorded), '; ') INTO got
      FROM _v97_spells(V_FH) s WHERE s.bowler_id = V_WQ;
    PERFORM _assert(got = '3 U15 t 6 12 f f', format('§75 (per boy): Westville''s coach reads his quick at Hilton as %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v97_spells(V_FH) s WHERE s.bowler_id <> V_WQ),
      '§75 (per boy): Westville''s coach''s bowling_spells at Hilton carries a Hilton boy');
    PERFORM _assert((SELECT count(*) FROM bowler_spell s WHERE s.match_id = V_FH AND s.bowler_id = V_HQ AND s.overs = 2) = 1,
      '§75 (per boy): Hilton''s quick''s spell is not in the log Westville''s coach reads (the spell is the match''s)');
    PERFORM _assert(NOT app_can('player.workload.read', '11111111-1111-1111-1111-111111111111', '16XI', V_HQ, ZERO)
                    AND app_can('player.workload.read', '22222222-2222-2222-2222-222222222222', '16XI', V_WQ, ZERO),
      '§75 (per boy): the load gate does not answer Westville''s coach for his boy and against Hilton''s');
    PERFORM _assert((SELECT count(*) FROM player WHERE id = V_HQ) = 0,
      '§75 (per boy): Westville''s coach reads Hilton''s quick''s record');
    -- ...and the mirror, at Westville's fixture as Hilton's coach
    PERFORM _as((z->>'hilcoach')::uuid);
    SELECT string_agg(concat_ws(' ', s.overs, s.age_band, s.pace, s.max_overs_per_spell, s.max_overs_per_day,
                                s.over_spell_limit, s.breach_recorded), '; ') INTO got
      FROM _v97_spells(V_FW) s WHERE s.bowler_id = V_HQ;
    PERFORM _assert(got = '2 U15 t 6 12 f f', format('§75 (per boy): Hilton''s coach reads his quick at Westville as %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v97_spells(V_FW) s WHERE s.bowler_id <> V_HQ),
      '§75 (per boy): Hilton''s coach''s bowling_spells at Westville carries a Westville boy');
    PERFORM _assert((SELECT count(*) FROM bowler_spell s WHERE s.match_id = V_FW AND s.bowler_id = V_WQ AND s.overs = 4) = 1,
      '§75 (per boy): Westville''s quick''s spell is not in the log Hilton''s coach reads');
    PERFORM _assert(NOT app_can('player.workload.read', '22222222-2222-2222-2222-222222222222', '16XI', V_WQ, ZERO),
      '§75 (per boy): Hilton''s coach holds the load gate for Westville''s quick');

    -- (refused)
    FOREACH k IN ARRAY ARRAY['kcoach', 'kspec'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id IN (V_FH, V_FW, V_FN)) = 0
                      AND (SELECT count(*) FROM match WHERE id IN (V_FH, V_FW, V_FN)) = 0
                      AND (SELECT count(*) FROM bowler_spell WHERE match_id IN (V_FH, V_FW)) = 0,
        format('§75 (refused): the third school''s %s reads a fixture of the other two', k));
    END LOOP;
    PERFORM _as((z->>'hil2coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id IN (V_FH, V_FW)) = 0
                    AND (_v97_rule(V_FH)).host = 0 AND (_v97_rule(V_FW)).either = 0,
      '§75 (refused): Hilton''s coach of another side reads a 16XI fixture');

    -- (pupils)
    PERFORM _as((z->>'wespupil')::uuid);
    PERFORM _assert(_v97_wheel(V_WB) = 36 AND _v97_wheel(V_HB) = 0,
      format('§75 (pupils): Westville''s pupil reads his own wheel as %s balls (36) and Hilton''s boy''s as %s (none)', _v97_wheel(V_WB), _v97_wheel(V_HB)));
    PERFORM _as((z->>'hilpupil')::uuid);
    PERFORM _assert(_v97_wheel(V_HB) = 72 AND _v97_wheel(V_WB) = 0,
      format('§75 (pupils): Hilton''s pupil reads his own wheel as %s balls (72) and Westville''s boy''s as %s (none)', _v97_wheel(V_HB), _v97_wheel(V_WB)));
    -- ...and the coaches likewise, the other school's boy refused
    PERFORM _as((z->>'wescoach')::uuid);
    PERFORM _assert(_v97_wheel(V_WB) = 36 AND _v97_wheel(V_HB) = 0, '§75 (pupils): Westville''s coach draws a Hilton boy''s wheel');

    -- (guardians), as db/100 made it (§77 holds the rule): each guardian's
    -- child is on his school's 16XI, the side at both shared fixtures, so
    -- each reads both whole, his own child's wheel and not the other's;
    -- Hilton's also reads the unshared one (his son's side's), Westville's
    -- none of it
    PERFORM _as((z->>'hilguardian')::uuid);
    PERFORM _assert((SELECT count(*) FROM match WHERE id IN (V_FH, V_FW)) = 2
                    AND (SELECT count(*) FROM ball_event WHERE match_id = V_FH) = 48
                    AND (SELECT count(*) FROM ball_event WHERE match_id = V_FW) = 60
                    AND (SELECT count(*) FROM ball_event WHERE match_id = V_FN) = 6
                    AND _v97_wheel(V_HB) = 72 AND _v97_wheel(V_WB) = 0,
      '§75 (guardians): Hilton''s guardian reads other than both fixtures and his son''s side''s, whole, and his son''s wheel alone');
    PERFORM _as((z->>'wesguardian')::uuid);
    PERFORM _assert((SELECT count(*) FROM match WHERE id IN (V_FH, V_FW)) = 2
                    AND (SELECT count(*) FROM ball_event WHERE match_id = V_FH) = 48
                    AND (SELECT count(*) FROM ball_event WHERE match_id = V_FW) = 60
                    AND (SELECT count(*) FROM ball_event WHERE match_id = V_FN) = 0
                    AND _v97_wheel(V_WB) = 36 AND _v97_wheel(V_HB) = 0,
      '§75 (guardians): Westville''s guardian reads other than both shared fixtures, whole, and his son''s wheel alone');

    -- (pad)
    PERFORM _as(V_OWN);
    PERFORM _assert(_v97_pad_rows(V_FH) = '1/1/1', format('§75 (pad): the stage''s pad rows are %s', _v97_pad_rows(V_FH)));
    FOREACH k IN ARRAY ARRAY['wescoach', 'wesscorer', 'wesspec'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM scoring_session WHERE match_id = V_FH) = 0
                      AND (SELECT count(*) FROM ball_event_quarantine WHERE match_id = V_FH) = 0
                      AND (SELECT count(*) FROM scoring_audit WHERE match_id = V_FH) = 0,
        format('§75 (pad): Westville''s %s reads Hilton''s session, held ball or audit', k));
    END LOOP;
    PERFORM _as((z->>'hilcoach')::uuid);
    PERFORM _assert((SELECT count(*) FROM scoring_session WHERE match_id = V_FH) = 1,
      '§75 (pad): Hilton''s coach does not read his own fixture''s session (the control)');
    PERFORM _as((z->>'wesscorer')::uuid);
    PERFORM set_config('app.device_id', 'v97-away-pad', true);
    got := NULL;
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value)
      VALUES (V_FH, '11111111-1111-1111-1111-111111111111', 61, 0, 1, (z->>'wesscorer')::uuid, 'v97-away-pad',
              'v97-away-write', 49, now(), 'ball', 'run', 4);
      got := 'written';
    EXCEPTION WHEN insufficient_privilege THEN
      got := SQLERRM;
    END;
    PERFORM set_config('app.device_id', '', true);
    PERFORM _assert(got LIKE '%row-level security%',
      format('§75 (pad): Westville''s scorer, holding the token, writes to Hilton''s fixture: %s', got));

    -- (columns)
    SELECT string_agg(attname, ',' ORDER BY attnum) INTO got
      FROM pg_attribute WHERE attrelid = 'ball_event'::regclass AND attnum > 0 AND NOT attisdropped;
    PERFORM _assert(got = 'id,match_id,school_id,seq,epoch,innings,scorer_user_id,device_id,idempotency_key,client_seq,'
                          'client_ts,server_ts,kind,ball_type,value,shot,contact,trajectory,seg,zone,striker_id,'
                          'non_striker_id,bowler_id,dismissed_id,dismissal,payload,recovered,theta,radius,'
                          'placement_source,placement_null,close_position,capture_profile,fingerprint',
      format('§75 (columns): ball_event''s columns are now %s; a new column on the log is read by both schools', got));

    -- (text)
    SELECT pg_get_expr(p.polqual, p.polrelid) INTO q FROM pg_policy p
     WHERE p.polrelid = 'ball_event'::regclass AND p.polname = 'ball_event_read' AND p.polcmd = 'r' AND p.polpermissive;
    PERFORM _assert(position('away_school_id' IN q) > 0 AND position('away_team_code' IN q) > 0
                    AND (length(q) - length(replace(q, 'match_team(', ''))) / length('match_team(') = 1,
      format('§75 (text): ball_event_read reads %s', q));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_policy p
                                 WHERE p.polrelid IN ('ball_event'::regclass, 'scoring_session'::regclass,
                                                      'ball_event_quarantine'::regclass, 'scoring_audit'::regclass)
                                   AND p.polname <> 'ball_event_read'
                                   AND concat(pg_get_expr(p.polqual, p.polrelid), pg_get_expr(p.polwithcheck, p.polrelid)) LIKE '%away\_%'),
      '§75 (text): a write or a pad table''s policy names the away side');
    PERFORM _assert((SELECT bool_and(coalesce(c.reloptions, '{}') @> ARRAY['security_invoker=true']) AND count(*) = 5
                       FROM pg_class c WHERE c.oid IN ('ball_event_live'::regclass, 'bowler_over'::regclass, 'bowler_spell'::regclass,
                                                       'ball_event_career'::regclass, 'match_live_score'::regclass)),
      '§75 (text): a view the away branch rides is not security_invoker');

    -- (day)
    PERFORM _as((z->>'wescoach')::uuid);
    SELECT concat_ws(' ', b.overs_today, b.matches_today) INTO got FROM bowler_day(sa_today(), '16XI') b WHERE b.player_id = V_WQ;
    SELECT sum(s.overs)::int INTO n FROM (SELECT * FROM _v97_spells(V_FH) UNION ALL SELECT * FROM _v97_spells(V_FW)) s WHERE s.bowler_id = V_WQ;
    PERFORM _assert(got = '7 2' AND n = 7,
      format('§75 (day): bowler_day reads Westville''s quick as %s; his spells across both fixtures sum to %s', got, n));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 75

  -- ┌── db/100 (section 77) ─────────────────────────────────────────────
  -- ── 77. A parent reads the ball log of his child's side's matches (db/100) ──
  -- Kameel's decision of 2026-10-14: a guardian reads the balls of fixtures
  -- his child's side plays, home and away; per-boy figures stay gated as
  -- today. The API half is tools/smoke-cockpit.mjs's group 6. Rows are
  -- _v100_stage()'s, invented: f1 Hilton 13XI v Westville 13XI at Hilton (18
  -- balls; B of 14XI plays up for Hilton), f2 the return at Westville (24),
  -- f3 Hilton's 14XI alone (6), f4 Hilton's 13XI against a school not on the
  -- platform (36; B picked and withdrawn), f5 a third school's (12), f6
  -- Westville's 14XI (18).
  --
  -- What each label holds:
  --   (every ball)  g1, guardian of A (Hilton 13XI), reads every ball of f1
  --                 (home), f2 (away) and f4, as many as the owner counts,
  --                 in ball_event, ball_event_live and ball_event_career,
  --                 and the live score of each
  --   (other side)  g1 reads none of f3 (another side at his son's school),
  --                 nor, since db/106, the fixture itself; none of f5 (a
  --                 third school) or f6 (Westville's seconds)
  --   (two schools) g2, guardian of B at Hilton and of W at Westville, reads
  --                 f3 (B's side), f1 (B on the sheet, playing up; W's side
  --                 away), f2 (W's side at home), each once and whole; none of
  --                 f4 (Hilton's 13XI, W's team code at another school, B
  --                 withdrawn), f6 (Westville's 14XI, B's code at another
  --                 school) or f5
  --   (playing up)  g5, guardian of B alone, reads f3 (his side) and f1,
  --                 where he is on Hilton's sheet for the 13XI, whole; not f4,
  --                 from whose sheet he was withdrawn, nor any other. The
  --                 sheet is what reaches f1: B's team is the 14XI
  --   (per boy)     g1 draws A's wheel across the three fixtures (48 balls)
  --                 and neither B's nor W's though both batted at f1; the
  --                 matchup coverage of W is none; bowling_spells at f1 and f2
  --                 carry no boy of his (Q is not his), at f4 A's own spell
  --                 with the directive null (a guardian holds no
  --                 player.workload.read); workload(), bowler_day() and
  --                 load_summary() answer him nothing; the career views name
  --                 A alone. g2 draws B's (12) and W's (18), not A's
  --   (ended)       g3, whose link to E ended today, and g4, whose link to A
  --                 was never verified, read no ball anywhere; g1's own link
  --                 ended mid-section leaves him none from the next query
  --   (rule)        for every reader who is not a guardian (both Hilton
  --                 coaches, the scorer, a spectator, B as a pupil with
  --                 self-access, Westville's coach and scorer, a third
  --                 school's coach) and every fixture, row security admits
  --                 exactly db/97's host and away branches: the guardian
  --                 branch gives nobody else anything. B's own coach (14XI)
  --                 reads none of f1, where B played up. B himself reads
  --                 every ball of f1 since db/112 (Kameel, 15 Oct 2026: the
  --                 boy playing up reads his match's balls; §89 is its
  --                 proof), and nothing else beyond db/97's branches
  --   (pad)         neither guardian reads f1's session, held ball or audit
  --                 row (each exists); g1 cannot write a ball to f1
  --   (text)        ball_event_read keeps db/97's two branches (match_team(
  --                 once, the away anchors) and asks my_child_fixtures(),
  --                 never the all-zeros person; the helper is a stable
  --                 definer for scrbrd_app alone, asks app_can() about the
  --                 child at both ends, names the sheet and the caller's own
  --                 links; no other policy on the log or the pad names it
  --   (helper)      my_child_fixtures() answers each reader his own: g1 f1,
  --                 f2, f4; g2 f1, f2, f3; g5 f1, f3; g3 and g4 nothing; B as
  --                 a pupil f3, his side's, which (rule) shows his team
  --                 assignment already reads, and not f1; every other reader
  --                 nothing
  --
  -- Falsified four ways, each by putting a wrong ball_event_read (or helper)
  -- in the database and running this section with each assertion made to
  -- report rather than raise:
  --   db/97's policy back: red at (every ball), (other side) (0 of 78),
  --     (two schools), (playing up), (per boy) (every wheel, coverage, A's
  --     spell and career empty) and (text). Green, as they should be:
  --     (other side)'s refusals, (ended), (rule), (pad), (helper).
  --   match_read's all-zeros person: red at (other side) (f3 read, 84 of
  --     78), (two schools) (f4 and f6 read: 18 24 6 36 0 18), (playing up)
  --     (18 24 6 36 0 0) and (text). The per-boy gates held: the record
  --     join, not the log, is what keeps another boy's wheel his.
  --   the team alone (no sheet): red at (playing up) (f1 not read: B's
  --     wheel 6 of 12), (text) and (helper).
  --   the sheet alone (no team): red at (every ball) (f2, f4), (other side),
  --     (two schools), (playing up), (per boy) and (helper).
  DECLARE
    z      jsonb := _v100_stage();
    F1 uuid := (z->>'f1')::uuid;  F2 uuid := (z->>'f2')::uuid;  F3 uuid := (z->>'f3')::uuid;
    F4 uuid := (z->>'f4')::uuid;  F5 uuid := (z->>'f5')::uuid;  F6 uuid := (z->>'f6')::uuid;
    C_A uuid := (z->>'a')::uuid;  C_B uuid := (z->>'b')::uuid;  C_W uuid := (z->>'w')::uuid;
    C_Q uuid := (z->>'q')::uuid;
    G1 uuid := (z->>'g1')::uuid;  G2 uuid := (z->>'g2')::uuid;
    V_OWN uuid := '88888888-0000-0000-0000-000000000022';
    k   text;
    f   uuid;
    rr  record;
    n   int;
    got text;
    q   text;
  BEGIN
    -- The stage, as the owner counts it.
    PERFORM _as(V_OWN);
    SELECT string_agg(_v100_owner_balls(x)::text, ' ' ORDER BY o) INTO got
      FROM unnest(ARRAY[F1, F2, F3, F4, F5, F6]) WITH ORDINALITY u(x, o);
    PERFORM _assert(got = '18 24 6 36 12 18', format('§77 (stage): the fixtures carry %s balls', got));
    PERFORM _assert((SELECT count(*) FROM match_squad WHERE match_id = F1 AND player_id = C_B AND side = 'home' AND NOT withdrawn) = 1
                    AND (SELECT count(*) FROM match_squad WHERE match_id = F4 AND player_id = C_B AND withdrawn) = 1,
      '§77 (stage): B is not on f1''s sheet playing up, or not withdrawn from f4''s');

    -- (every ball)
    PERFORM _as(G1);
    FOREACH f IN ARRAY ARRAY[F1, F2, F4] LOOP
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = f) = _v100_owner_balls(f)
                      AND (SELECT count(*) FROM ball_event_live WHERE match_id = f) = _v100_owner_balls(f)
                      AND (SELECT count(*) FROM ball_event_career WHERE match_id = f) = _v100_owner_balls(f)
                      AND (SELECT count(*) FROM match_live_score WHERE match_id = f) > 0,
        format('§77 (every ball): A''s guardian reads %s of %s balls at %s',
               (SELECT count(*) FROM ball_event WHERE match_id = f), _v100_owner_balls(f),
               CASE f WHEN F1 THEN 'f1 (home)' WHEN F2 THEN 'f2 (away)' ELSE 'f4' END));
    END LOOP;

    -- (other side)
    -- Since db/106 (REACH-D1, §83) match_read no longer shows him f3 either:
    -- this read "= 1" while match_read asked with the all-zeros person.
    PERFORM _assert((SELECT count(*) FROM match WHERE id = F3) = 0
                    AND (SELECT count(*) FROM ball_event WHERE match_id = F3) = 0
                    AND (SELECT count(*) FROM match_live_score WHERE match_id = F3) = 0,
      '§77 (other side): A''s guardian reads f3, Hilton''s 14XI, or a ball of it (db/106: the side only)');
    PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id IN (F5, F6)) = 0,
      '§77 (other side): A''s guardian reads a ball at a school that is not his son''s fixture''s');
    PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id IN (F1, F2, F3, F4, F5, F6)) = 78,
      format('§77 (other side): A''s guardian reads %s of the stage''s balls (78: f1, f2, f4)',
             (SELECT count(*) FROM ball_event WHERE match_id IN (F1, F2, F3, F4, F5, F6))));

    -- (two schools)
    PERFORM _as(G2);
    SELECT string_agg((SELECT count(*) FROM ball_event b WHERE b.match_id = x)::text, ' ' ORDER BY o) INTO got
      FROM unnest(ARRAY[F1, F2, F3, F4, F5, F6]) WITH ORDINALITY u(x, o);
    PERFORM _assert(got = '18 24 6 0 0 0',
      format('§77 (two schools): B''s and W''s guardian reads f1..f6 as %s (18 24 6 0 0 0)', got));
    PERFORM _assert((SELECT count(*) FROM player WHERE id IN (C_A, C_B, C_W, C_Q)) = 2
                    AND (SELECT count(*) FROM player WHERE id IN (C_B, C_W)) = 2,
      '§77 (two schools): B''s and W''s guardian reads a record other than his two boys''');

    -- (playing up)
    PERFORM _as((z->>'g5')::uuid);
    SELECT string_agg((SELECT count(*) FROM ball_event b WHERE b.match_id = x)::text, ' ' ORDER BY o) INTO got
      FROM unnest(ARRAY[F1, F2, F3, F4, F5, F6]) WITH ORDINALITY u(x, o);
    PERFORM _assert(got = '18 0 6 0 0 0',
      format('§77 (playing up): B''s guardian reads f1..f6 as %s (18 0 6 0 0 0: f1 by the sheet, f3 by his side)', got));
    PERFORM _assert(_v97_wheel(C_B) = 12 AND _v97_wheel(C_A) = 0,
      format('§77 (playing up): B''s guardian draws B''s wheel as %s (12, both fixtures) and A''s as %s', _v97_wheel(C_B), _v97_wheel(C_A)));

    -- (per boy), as A's guardian
    PERFORM _as(G1);
    PERFORM _assert(_v97_wheel(C_A) = 48 AND _v97_wheel(C_B) = 0 AND _v97_wheel(C_W) = 0,
      format('§77 (per boy): A''s guardian draws A''s wheel as %s balls (48), B''s as %s and W''s as %s (none)',
             _v97_wheel(C_A), _v97_wheel(C_B), _v97_wheel(C_W)));
    -- matchup_coverage, as read-api.mjs asks it for a named batter
    PERFORM _assert((SELECT count(*) FROM ball_event_career
                      WHERE kind = 'ball' AND striker_id = C_W AND EXISTS (SELECT 1 FROM player p WHERE p.id = C_W)) = 0
                    AND (SELECT count(*) FROM ball_event_career
                          WHERE kind = 'ball' AND striker_id = C_A AND EXISTS (SELECT 1 FROM player p WHERE p.id = C_A)) = 48,
      '§77 (per boy): A''s guardian''s matchup coverage counts W''s balls, or not A''s');
    -- matchups join both boys' records: Q bowled to A at f2 and is not his
    PERFORM _assert((SELECT count(*) FROM ball_event_career b
                       JOIN player bat ON bat.id = b.striker_id JOIN player bowl ON bowl.id = b.bowler_id
                      WHERE b.match_id IN (F1, F2)) = 0,
      '§77 (per boy): A''s guardian reads a matchup naming a boy not his');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v97_spells(F1)) AND NOT EXISTS (SELECT 1 FROM _v97_spells(F2)),
      '§77 (per boy): A''s guardian''s bowling_spells at f1 or f2 carries Q, who is not his');
    SELECT string_agg(concat_ws(' ', s.overs, s.age_band, s.pace, s.max_overs_per_spell, s.max_overs_per_day,
                                s.over_spell_limit, s.breach_recorded), '; ') INTO got
      FROM _v97_spells(F4) s;
    PERFORM _assert(got = '1 f', format('§77 (per boy): A''s guardian reads A''s spell at f4 as %s (one over, the directive null)', got));
    PERFORM _assert((SELECT count(*) FROM workload(NULL::text)) = 0
                    AND (SELECT count(*) FROM bowler_day(sa_today(), NULL::text)) = 0
                    AND (SELECT count(*) FROM load_summary(C_A, 'cricket')) = 0,
      '§77 (per boy): workload(), bowler_day() or load_summary() answers A''s guardian');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM player_batting_career WHERE player_id <> C_A)
                    AND NOT EXISTS (SELECT 1 FROM player_bowling_career WHERE player_id <> C_A)
                    AND (SELECT c.balls_faced FROM player_batting_career c WHERE c.player_id = C_A) = 48,
      format('§77 (per boy): A''s guardian''s career views read %s (A alone, 48 faced)',
             (SELECT string_agg(player_id::text || ':' || balls_faced, ',') FROM player_batting_career)));
    -- ...and as B's and W's guardian
    PERFORM _as(G2);
    PERFORM _assert(_v97_wheel(C_B) = 12 AND _v97_wheel(C_W) = 18 AND _v97_wheel(C_A) = 0,
      format('§77 (per boy): B''s and W''s guardian draws B''s wheel as %s (12), W''s as %s (18), A''s as %s (none)',
             _v97_wheel(C_B), _v97_wheel(C_W), _v97_wheel(C_A)));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM _v97_spells(F1)) AND (SELECT count(*) FROM workload(NULL::text)) = 0,
      '§77 (per boy): B''s and W''s guardian reads Q''s spell or a boy''s load');

    -- (ended)
    FOREACH k IN ARRAY ARRAY['g3', 'g4'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id IN (F1, F2, F3, F4, F5, F6)) = 0,
        format('§77 (ended): %s, whose link is %s, reads a ball', k, CASE k WHEN 'g3' THEN 'ended' ELSE 'unverified' END));
    END LOOP;

    -- (rule): nobody but a guardian gains anything
    FOREACH k IN ARRAY ARRAY['coacha', 'coachb', 'scorer', 'spec', 'pupilb', 'wescoach', 'wesscorer', 'kcoach'] LOOP
      PERFORM _as((z->>k)::uuid);
      FOREACH f IN ARRAY ARRAY[F1, F2, F3, F4, F5, F6] LOOP
        rr := _v97_rule(f);
        SELECT count(*) INTO n FROM ball_event b WHERE b.match_id = f;
        -- db/112: B, on f1's sheet at his own school's end, reads all of it.
        PERFORM _assert(n = CASE WHEN k = 'pupilb' AND f = F1 THEN rr.total ELSE rr.either END,
          format('§77 (rule): as %s, row security admits %s balls of a fixture where db/97''s branches give %s (host %s, away %s, of %s)',
                 k, n, rr.either, rr.host, rr.away, rr.total));
      END LOOP;
    END LOOP;
    FOREACH k IN ARRAY ARRAY['coachb', 'pupilb'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id = F1) = CASE k WHEN 'pupilb' THEN 18 ELSE 0 END
                      AND (SELECT count(*) FROM ball_event WHERE match_id = F3) = 6,
        format('§77 (rule): as %s, f1 (B playing up: his own since db/112, not his coach''s) or f3 (B''s side) reads other than it should', k));
    END LOOP;

    -- (pad)
    PERFORM _as(V_OWN);
    PERFORM _assert(_v97_pad_rows(F1) = '1/1/1', format('§77 (pad): the stage''s pad rows are %s', _v97_pad_rows(F1)));
    FOREACH k IN ARRAY ARRAY['g1', 'g2'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM scoring_session WHERE match_id = F1) = 0
                      AND (SELECT count(*) FROM ball_event_quarantine WHERE match_id = F1) = 0
                      AND (SELECT count(*) FROM scoring_audit WHERE match_id = F1) = 0,
        format('§77 (pad): %s reads f1''s session, held ball or audit', k));
    END LOOP;
    PERFORM _as(G1);
    got := NULL;
    BEGIN
      INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                              idempotency_key, client_seq, client_ts, kind, ball_type, value)
      VALUES (F1, '11111111-1111-1111-1111-111111111111', 19, 0, 1, G1, 'v100-pad', 'v100-parent-write', 19, now(), 'ball', 'run', 4);
      got := 'written';
    EXCEPTION WHEN insufficient_privilege THEN
      got := SQLERRM;
    END;
    PERFORM _assert(got LIKE '%row-level security%', format('§77 (pad): A''s guardian writes a ball to f1: %s', got));

    -- (text)
    SELECT pg_get_expr(p.polqual, p.polrelid) INTO q FROM pg_policy p
     WHERE p.polrelid = 'ball_event'::regclass AND p.polname = 'ball_event_read' AND p.polcmd = 'r' AND p.polpermissive;
    PERFORM _assert((length(q) - length(replace(q, 'match_team(', ''))) / length('match_team(') = 1
                    AND position('away_school_id IS NOT NULL' IN q) > 0
                    AND position('my_child_fixtures()' IN q) > 0
                    AND position('00000000-0000-0000-0000-000000000000' IN q) = 0,
      format('§77 (text): ball_event_read reads %s', left(q, 400)));
    SELECT p.prosrc INTO got FROM pg_proc p
     WHERE p.oid = to_regprocedure('my_child_fixtures()') AND p.prosecdef AND p.provolatile = 's';
    PERFORM _assert(position('app_can(''fixture.read'', m.school_id, m.team_code, p.id, m.id)' IN got) > 0
                    AND position('app_can(''fixture.read'', m.away_school_id, m.away_team_code, p.id, m.id)' IN got) > 0
                    AND position('NOT s.withdrawn' IN got) > 0 AND position('a.person_id = app_user_id()' IN got) > 0
                    AND position('00000000-0000-0000-0000-000000000000' IN got) = 0
                    AND NOT has_function_privilege('public', to_regprocedure('my_child_fixtures()'), 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', to_regprocedure('my_child_fixtures()'), 'EXECUTE'),
      format('§77 (text): my_child_fixtures() is not a stable definer for scrbrd_app asking about the child: %s', left(coalesce(got, 'missing'), 300)));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_policy p
                                 WHERE p.polrelid IN ('ball_event'::regclass, 'scoring_session'::regclass,
                                                      'ball_event_quarantine'::regclass, 'scoring_audit'::regclass)
                                   AND p.polname <> 'ball_event_read'
                                   AND concat(pg_get_expr(p.polqual, p.polrelid), pg_get_expr(p.polwithcheck, p.polrelid))
                                       LIKE '%my\_child\_fixtures%'),
      '§77 (text): a write or a pad table''s policy asks my_child_fixtures()');

    -- (helper): each reader his own, and nobody else anything
    FOREACH k IN ARRAY ARRAY['g1', 'g2', 'g5', 'g3', 'g4', 'coacha', 'coachb', 'scorer', 'spec', 'pupilb', 'wescoach', 'kcoach'] LOOP
      PERFORM _as((z->>k)::uuid);
      SELECT string_agg(l, ' ' ORDER BY l) INTO got
        FROM (SELECT CASE x WHEN F1 THEN 'f1' WHEN F2 THEN 'f2' WHEN F3 THEN 'f3' WHEN F4 THEN 'f4'
                            WHEN F5 THEN 'f5' WHEN F6 THEN 'f6' ELSE 'another' END AS l
                FROM unnest(my_child_fixtures()) x) y;
      -- B as a pupil: his self link names him, and his team assignment
      -- (14XI, naming nobody) answers fixture.read about him at his own
      -- side's fixture, which the host branch already gives him; not f1,
      -- where he played up: that assignment is not the 13XI's.
      PERFORM _assert(coalesce(got, '') = CASE k WHEN 'g1' THEN 'f1 f2 f4' WHEN 'g2' THEN 'f1 f2 f3' WHEN 'g5' THEN 'f1 f3'
                                                 WHEN 'pupilb' THEN 'f3' ELSE '' END,
        format('§77 (helper): my_child_fixtures() answers %s with %s', k, coalesce(got, 'nothing')));
    END LOOP;

    -- (ended), last: g1's own link ends, and his next read has nothing
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v100_end_link(G1, C_A);
    PERFORM _as(G1);
    PERFORM _assert((SELECT count(*) FROM ball_event WHERE match_id IN (F1, F2, F3, F4, F5, F6)) = 0
                    AND _v97_wheel(C_A) = 0,
      '§77 (ended): A''s guardian reads a ball after his link ended');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 77
  -- ┌── db/101 (section 78) ──────────────────────────────────────────
  -- ── 78. News to the side: a team post, and the team sheet (db/101) ──
  -- Kameel's two decisions of 2026-10-14: an ordinary team post and its
  -- notice reach the side only, as a plan does ("Yes, in its own
  -- migration"); a boy on a fixture's sheet and his guardians read that
  -- fixture's plan even when his own side is another ("Yes: the team sheet
  -- counts too"). Every write below is a person's, through scrbrd_app under
  -- RLS, except the stage and the one deleted squad row (_v101_unsheet: no
  -- person may delete one). Westville stands in for the other school.
  --
  -- What each label holds:
  --   (team)     the U15A coach's ordinary post: the side's boy, his
  --              guardian, the coach (its author), the team manager, the
  --              assistant coach and the director of sport read it and its
  --              notice; the U15B boy and parent, a follower, finance,
  --              sponsorship, a driver, facilities, the U14A boys (on the
  --              sheet or not) and their guardians, the U14A coach,
  --              Westville's coach and boy, and nobody signed in, read
  --              neither
  --   (school)   a school post still reaches the whole school, those above
  --              included, with its notice
  --   (public)   db/83's door is unchanged: the author asks, the director of
  --              sport approves, and the signed-out home page reads the post
  --   (sheet)    the coach's plan for f1, and another for f2: the U14A boy
  --              on f1's sheet reads f1's plan and its notice, and so does
  --              his guardian; neither reads f2's plan or its notice, nor the
  --              ordinary post: of every U15A row he reads f1's plan alone;
  --              the U14A boy on no sheet, his guardian, the U14A coach, the
  --              U15B parent, the follower and finance read nothing of it
  --   (report)   the boy playing up may report f1's plan's notice, and the
  --              side's guardian the post's (any reader may, SG-9 rule 4);
  --              the U15B parent, the follower and the U14A guardian off the
  --              sheet, who read neither, are told there is no such notice
  --   (off)      withdrawn from the sheet he reads neither, nor does his
  --              guardian; put back he reads it; his row deleted he reads
  --              neither again
  --   (away)     Westville's coach sends his side's plan for f1: the
  --              Westville boy, the Westville U14A boy on the away sheet and
  --              both their guardians read it and its notice; the visiting
  --              U14A boy and his guardian read nothing of Hilton U15A; no
  --              Hilton boy or guardian reads Westville's plan
  --   (withdraw) Hilton's f1 plan withdrawn: the boy playing up and his
  --              guardian read neither it nor its notice, and do read the
  --              "withdrawn" notice; the U14A guardian off the sheet does not
  --   (author)   the team manager writes to U15A and then leaves the side:
  --              he still reads his own post, and not the coach's
  --   (doors)    the three new functions and db/96's news_notice_reach are
  --              stable SECURITY DEFINERs with a pinned path, the
  --              application's and not PUBLIC's or a managed host's; the two
  --              narrowing policies RESTRICTIVE, the two sheet reads
  --              PERMISSIVE, all four FOR SELECT; db/96's plan policy reads
  --              the sheet; the application holds no DELETE on either table
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at the first assertion that depends on it:
  --   (sheet)    DROP POLICY news_post_read_sheet and notification_read_sheet
  --              (red at §78 (sheet): the boy playing up reading f1's plan)
  --   (team)     DROP POLICY news_post_team_side (red at §76 (post): the
  --              U15B parent reads an ordinary U15A post); DROP POLICY
  --              notification_team_side (red at §70 (withdraw): a 1XI family
  --              reads a U14A post's notice). Both run before §78 (team),
  --              which asserts the same of the U15B parent
  --   (report)   notification_report() with db/91's reader test (red at the
  --              boy playing up reporting f1's plan's notice: no_such_notice)
  DECLARE
    y        jsonb := _v101_stage();
    V_HIL    uuid := '11111111-1111-1111-1111-111111111111';
    V_WES    uuid := '22222222-2222-2222-2222-222222222222';
    F1       uuid := (y->>'f1')::uuid;
    F2       uuid := (y->>'f2')::uuid;
    T uuid; S uuid; P1 uuid; P2 uuid; W uuid; M uuid; NP1 uuid;
    v_ok boolean; v_reason text;
    k  text;
    got text;
    n  integer;
  BEGIN
    -- (team)
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    -- Not 'Verify ...': this file's own pupils are called Verify, and since
    -- db/118 any word of a pupil's name keeps a post off the home page.
    VALUES ('team', V_HIL, 'U15A', 'Section 78 nets', 'Nets on Thursday.', now()) RETURNING id INTO T;
    PERFORM _assert(jsonb_array_length(_notices_91(T)) = 1, '§78 (team): the post did not write one notice');
    FOREACH k IN ARRAY ARRAY['aboy', 'aparent', 'coach', 'manager', 'assistant', 'director'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = T) = 1
                      AND (SELECT count(*) FROM my_notifications n WHERE n.subject_kind = 'news' AND n.subject_id = T) = 1,
        format('§78 (team): the %s does not read the side''s post and its notice', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['bboy', 'bparent', 'follower', 'finance', 'sponsorship', 'driver', 'facilities',
                             'upboy', 'upparent', 'u14boy', 'u14parent', 'u14coach', 'wescoach', 'wesboy'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = T) = 0
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id = T) = 0,
        format('§78 (team): the %s reads Hilton U15A''s post, or its notice', k));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = T) = 0
                    AND (SELECT count(*) FROM notification n WHERE n.subject_id = T) = 0,
      '§78 (team): an anonymous session reads the side''s post, or its notice');

    -- (school)
    PERFORM _as((y->>'director')::uuid);
    INSERT INTO news_post (scope, school_id, title, body, published_at)
    VALUES ('school', V_HIL, 'Verify 101 assembly', 'Colours at Friday assembly.', now()) RETURNING id INTO S;
    FOREACH k IN ARRAY ARRAY['aboy', 'aparent', 'bboy', 'bparent', 'follower', 'finance', 'sponsorship', 'driver',
                             'facilities', 'upboy', 'upparent', 'u14boy', 'u14parent', 'u14coach', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = S) = 1
                      AND (SELECT count(*) FROM my_notifications n WHERE n.subject_kind = 'news' AND n.subject_id = S) = 1,
        format('§78 (school): the %s no longer reads a school post and its notice', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['wescoach', 'wesboy'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = S) = 0,
        format('§78 (school): Westville''s %s reads a Hilton school post', k));
    END LOOP;

    -- (public)
    PERFORM _as((y->>'coach')::uuid);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_request(T) r;
    PERFORM _assert(v_ok, format('§78 (public): the author could not ask for his team post (%s)', v_reason));
    PERFORM _as((y->>'director')::uuid);
    PERFORM public_listing_set(V_HIL, true);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM news_public_approve(T) r;
    PERFORM _assert(v_ok, format('§78 (public): the director of sport could not approve the team post (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM public_news(20) x WHERE x.id = T AND x.team_code = 'U15A' AND x.title = 'Section 78 nets') = 1,
      '§78 (public): the approved team post is not on the home page');

    -- (sheet)
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, 'U15A', 'The plan: v Westville U15A', 'Bat first if we win it.', now(), 'plan', F1)
    RETURNING id INTO P1;
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, 'U15A', 'The plan: v Visitors', 'Bowl first if we win it.', now(), 'plan', F2)
    RETURNING id INTO P2;
    NP1 := (_notices_91(P1)->0->>'id')::uuid;
    PERFORM _assert(NP1 IS NOT NULL AND jsonb_array_length(_notices_91(P2)) = 1, '§78 (sheet): the plans did not write their notices');
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent', 'aboy', 'aparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P1 AND n.kind = 'plan' AND n.fixture_id = F1) = 1
                      AND (SELECT count(*) FROM my_notifications n WHERE n.id = NP1) = 1,
        format('§78 (sheet): the %s does not read f1''s plan and its notice', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id IN (P2, T)) = 0
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id IN (P2, T)) = 0,
        format('§78 (sheet): the %s reads U15A''s other plan or its ordinary post, or a notice of one', k));
      PERFORM _assert((SELECT string_agg(n.id::text, ',') FROM news_post n WHERE n.school_id = V_HIL AND n.team_code = 'U15A') = P1::text,
        format('§78 (sheet): of Hilton U15A the %s reads more than f1''s plan', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['u14boy', 'u14parent', 'u14coach', 'bparent', 'follower', 'finance'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.school_id = V_HIL AND n.team_code = 'U15A') = 0
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id IN (P1, P2, T)) = 0,
        format('§78 (sheet): the %s reads something of Hilton U15A', k));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id IN (P1, P2)) = 0, '§78 (sheet): an anonymous session reads a plan');

    -- (report)
    PERFORM _as((y->>'upboy')::uuid);
    got := _report_91(NP1);
    PERFORM _assert(got = 'ok', format('§78 (report): the boy playing up could not report f1''s plan''s notice (%s)', got));
    PERFORM _as((y->>'aparent')::uuid);
    got := _report_91((_notices_91(T)->0->>'id')::uuid);
    PERFORM _assert(got = 'ok', format('§78 (report): the side''s guardian could not report the side''s post''s notice (%s)', got));
    FOREACH k IN ARRAY ARRAY['bparent', 'follower', 'u14parent'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _report_91((_notices_91(T)->0->>'id')::uuid) || ' ' || _report_91(NP1);
      PERFORM _assert(got = 'no_such_notice no_such_notice',
        format('§78 (report): the %s, who reads neither, reported the side''s notices (%s)', k, got));
    END LOOP;

    -- (off)
    PERFORM _as((y->>'coach')::uuid);
    UPDATE match_squad SET withdrawn = true WHERE match_id = F1 AND player_id = (y->>'p_up')::uuid;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, '§78 (off): the coach could not take the boy off the sheet');
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P1) = 0
                      AND (SELECT count(*) FROM notification n WHERE n.id = NP1) = 0,
        format('§78 (off): withdrawn from the sheet, the %s still reads f1''s plan or its notice', k));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    UPDATE match_squad SET withdrawn = false WHERE match_id = F1 AND player_id = (y->>'p_up')::uuid;
    PERFORM _as((y->>'upboy')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P1) = 1, '§78 (off): put back on the sheet, the boy does not read f1''s plan');
    PERFORM _assert(_v101_unsheet(F1, (y->>'p_up')::uuid) = 1, '§78 (off): the boy''s squad row was not deleted');
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P1) = 0
                      AND (SELECT count(*) FROM notification n WHERE n.id = NP1) = 0,
        format('§78 (off): off the sheet, the %s still reads f1''s plan or its notice', k));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO match_squad (match_id, player_id, side, batting_no) VALUES (F1, (y->>'p_up')::uuid, 'home', 2);

    -- (away)
    PERFORM _as((y->>'wescoach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_WES, 'U15A', 'The plan: at Hilton U15A', 'Bowl first if we win it.', now(), 'plan', F1)
    RETURNING id INTO W;
    FOREACH k IN ARRAY ARRAY['wesboy', 'wesup', 'wesparent', 'wesupparent', 'wescoach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = W) = 1
                      AND (SELECT count(*) FROM my_notifications n WHERE n.subject_kind = 'news' AND n.subject_id = W) = 1,
        format('§78 (away): the Westville %s does not read his side''s plan for f1 and its notice', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['wesup', 'wesupparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.school_id = V_HIL AND n.team_code = 'U15A') = 0
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id IN (P1, P2, T)) = 0,
        format('§78 (away): the Westville %s reads something of Hilton U15A', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent', 'aboy', 'aparent', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = W) = 0
                      AND (SELECT count(*) FROM notification n WHERE n.subject_kind = 'news' AND n.subject_id = W) = 0,
        format('§78 (away): the Hilton %s reads Westville''s plan, or its notice', k));
    END LOOP;

    -- (withdraw)
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert(_withdraw_91(P1) = 'ok', '§78 (withdraw): the coach could not withdraw f1''s plan');
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P1) = 0
                      AND NOT EXISTS (SELECT 1 FROM my_notifications n WHERE n.id = NP1)
                      AND EXISTS (SELECT 1 FROM my_notifications n WHERE n.retracts_id = NP1 AND n.title = 'A notice was withdrawn'),
        format('§78 (withdraw): the %s still reads the withdrawn plan, or was not told', k));
    END LOOP;
    PERFORM _as((y->>'u14parent')::uuid);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM notification n WHERE n.id = NP1 OR n.retracts_id = NP1),
      '§78 (withdraw): the U14A guardian off the sheet reads the plan''s notices');

    -- (author)
    PERFORM _as((y->>'manager')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, 'U15A', 'Verify 101 kit', 'Whites on Saturday.', now()) RETURNING id INTO M;
    PERFORM _revoke((y->>'manager')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = M) = 1, '§78 (author): the author no longer reads his own post');
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = T) = 0, '§78 (author): off the side, he still reads the coach''s post');
    PERFORM _as((y->>'bparent')::uuid);
    PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = M) = 0, '§78 (author): the U15B parent reads the manager''s post');

    -- (doors)
    FOREACH k IN ARRAY ARRAY['news_sheet_reach(uuid,uuid,text)', 'news_team_notice_reach(uuid)',
                             'news_notice_sheet(uuid,uuid,text)', 'news_notice_reach(uuid)'] LOOP
      PERFORM _assert((SELECT prosecdef AND provolatile = 's' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = to_regprocedure(k)),
        format('§78 (doors): %s is not a stable SECURITY DEFINER with a pinned path', k));
      PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure(k), 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = to_regprocedure(k) AND a.grantee = 0 AND a.privilege_type = 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                         AND has_function_privilege(g.oid, to_regprocedure(k), 'EXECUTE')),
        format('§78 (doors): %s is not the application''s alone', k));
    END LOOP;
    PERFORM _assert((SELECT prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                       FROM pg_proc WHERE oid = to_regprocedure('notification_report(uuid)'))
                    AND has_function_privilege('scrbrd_app', to_regprocedure('notification_report(uuid)'), 'EXECUTE')
                    AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                     WHERE p.oid = to_regprocedure('notification_report(uuid)') AND a.grantee = 0
                                       AND a.privilege_type = 'EXECUTE'),
      '§78 (doors): notification_report is not a SECURITY DEFINER with a pinned path, the application''s alone');
    PERFORM _assert((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND cmd = 'SELECT'
                       AND ((permissive = 'RESTRICTIVE' AND (tablename, policyname) IN
                              (('news_post', 'news_post_team_side'), ('notification', 'notification_team_side')))
                         OR (permissive = 'PERMISSIVE' AND (tablename, policyname) IN
                              (('news_post', 'news_post_read_sheet'), ('notification', 'notification_read_sheet'))))) = 4,
      '§78 (doors): the side''s two narrowing policies are not RESTRICTIVE, or its two sheet reads not PERMISSIVE, SELECT policies');
    PERFORM _assert((SELECT count(*) FROM pg_policies WHERE schemaname = 'public'
                       AND policyname IN ('news_post_team_side', 'notification_team_side', 'news_post_read_sheet', 'notification_read_sheet')
                       AND cmd <> 'SELECT') = 0,
      '§78 (doors): a policy of db/101''s governs a write');
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'news_post'
                               AND policyname = 'news_post_plan_side' AND permissive = 'RESTRICTIVE' AND cmd = 'SELECT'
                               AND qual LIKE '%news_sheet_reach(%'),
      '§78 (doors): db/96''s plan narrowing does not read the sheet');
    PERFORM _assert(NOT has_table_privilege('scrbrd_app', 'news_post', 'DELETE')
                    AND NOT has_table_privilege('scrbrd_app', 'notification', 'DELETE'),
      '§78 (doors): the application may delete a post or a notice');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 78
  -- └── db/101 (section 78) ───────────────────────────────────────────
  -- ┌── section 79: who a module was hidden from is the school's to read (db/102) ──
  -- feature_suppression's read policy was "anybody enrolled" (db/08, db/81),
  -- and module_suppressions handed any school's named rows, names and reasons
  -- to any parent, pupil or follower anywhere. The API half is
  -- tools/smoke-modules.mjs ("One person, not the whole school").
  --
  -- What each label holds:
  --   (manager)    Hilton's school administrator reads both Hilton named
  --                rows and their reasons, and not Westville's
  --   (self)       the coach Skills was hidden from reads his own row, not
  --                its reason, and not his colleague's row
  --   (refused)    another Hilton coach, a parent, a pupil, a spectator and
  --                Westville's administrator read neither Hilton named row,
  --                nor its reason, and module_suppressions (its query,
  --                verbatim) gives them no named Hilton row
  --   (wide)       every one of them still reads the school-wide row and its
  --                reason, as before: the refusals above are the policy's
  --   (column)     nobody selects feature_suppression.reason directly, not
  --                even a manager: the column is not the application's
  --   (resolve)    Skills resolves as hidden for the named coach and as on for
  --                every other Hilton reader; Training the other way round;
  --                Westville's row reaches only Westville's coach
  --   (school)     the school-wide row resolves Leagues off for everybody at
  --                Hilton and for nobody at Westville
  --   (writes)     a manager still hides from a person (INSERT … RETURNING)
  --                and lifts it (UPDATE … RETURNING), as scouting-api does
  --   (doors)      the policy's text; the column privilege; the reason
  --                function a stable definer for scrbrd_app, not PUBLIC
  --
  -- Falsified once, by putting the open policy back (feature_suppression_read
  -- USING (app_enrolled()), as db/81 left it) and running this file: red at
  -- (manager), Hilton's administrator reading Westville's named row.
  DECLARE
    y        jsonb := _v102_stage();
    HIL      uuid := '11111111-1111-1111-1111-111111111111';
    N1       uuid := (y->>'n1')::uuid;
    N2       uuid := (y->>'n2')::uuid;
    S1       uuid := (y->>'s1')::uuid;
    W1       uuid := (y->>'w1')::uuid;
    k        text;
    got      text;
    v_new    uuid;
  BEGIN
    -- (manager)
    PERFORM _as((y->>'manager')::uuid);
    SELECT string_agg(s.key || '@' || (s.school_id = HIL) || ':' || coalesce(feature_suppression_reason(s.id), '(none)'),
                      ', ' ORDER BY s.key, s.school_id = HIL) INTO got
      FROM feature_suppression s WHERE s.id IN (N1, N2, W1);
    PERFORM _assert(got = 'skills@true:v102: pending a review of his conduct, training@true:v102: on leave',
      format('§79 (manager): Hilton''s administrator reads %s', coalesce(got, 'no row')));
    PERFORM _assert(feature_suppression_reason(W1) IS NULL,
      '§79 (manager): Hilton''s administrator reads the reason Westville wrote');
    PERFORM _as((y->>'wesmanager')::uuid);
    PERFORM _assert((SELECT string_agg(s.id::text, ',') FROM feature_suppression s WHERE s.id IN (N1, N2, W1)) = W1::text
                    AND feature_suppression_reason(W1) = 'v102: Westville''s own note',
      '§79 (manager): Westville''s administrator does not read his own school''s named row, or reads Hilton''s');

    -- (self)
    PERFORM _as((y->>'named')::uuid);
    SELECT string_agg(s.key || ':' || (s.person_id = (y->>'named')::uuid), ',') INTO got
      FROM feature_suppression s WHERE s.id IN (N1, N2, W1);
    PERFORM _assert(got = 'skills:true', format('§79 (self): the named coach reads %s, not his own row alone', coalesce(got, 'no row')));
    PERFORM _assert(feature_suppression_reason(N1) IS NULL,
      '§79 (self): the named coach reads the reason his administrator wrote about him');

    -- (refused), and (wide) beside it
    FOREACH k IN ARRAY ARRAY['teacher', 'parent', 'pupil', 'spectator', 'wesmanager'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM feature_suppression s WHERE s.id IN (N1, N2)),
        format('§79 (refused): the %s reads a Hilton suppression naming somebody', k));
      PERFORM _assert(feature_suppression_reason(N1) IS NULL AND feature_suppression_reason(N2) IS NULL,
        format('§79 (refused): the %s reads the reason written about a Hilton coach', k));
      -- module_suppressions, as services/api/read/read-api.mjs runs it.
      PERFORM _assert(NOT EXISTS (
          SELECT 1 FROM (
            select s.key, s.school_id, s.person_id, u.name as person_name,
                   feature_suppression_reason(s.id) as reason, s.hidden_at
              from feature_suppression s
              left join app_user u on u.id = s.person_id
             where s.school_id = HIL
               and s.lifted_at is null
               and (null::text is null or s.key = null::text)
             order by s.key, u.name nulls first) m
           WHERE m.person_id IS NOT NULL),
        format('§79 (refused): module_suppressions gives the %s a named Hilton row', k));
      PERFORM _assert(EXISTS (SELECT 1 FROM feature_suppression s WHERE s.id = S1)
                      AND feature_suppression_reason(S1) = 'v102: not running leagues this term',
        format('§79 (wide): the %s no longer reads Hilton''s school-wide suppression, or its reason', k));
    END LOOP;

    -- (column)
    FOREACH k IN ARRAY ARRAY['manager', 'named', 'parent'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := 'read';
      BEGIN
        PERFORM s.reason FROM feature_suppression s WHERE s.id = S1;
      EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
      END;
      PERFORM _assert(got = 'refused', format('§79 (column): the %s selects the reason column directly', k));
    END LOOP;

    -- (resolve)
    PERFORM _assert(feature_enabled('skills', HIL, NULL) AND feature_enabled('training', HIL, NULL),
      '§79 (resolve): Skills or Training is off at Hilton before anybody was named; this proves nothing');
    PERFORM _as((y->>'named')::uuid);
    PERFORM _assert(NOT my_feature_enabled('skills') AND NOT feature_enabled('skills', HIL, (y->>'named')::uuid),
      '§79 (resolve): Skills reads as on for the coach it was hidden from');
    PERFORM _assert(my_feature_enabled('training'),
      '§79 (resolve): the coach reads Training as off, which was hidden from his colleague');
    PERFORM _as((y->>'colleague')::uuid);
    PERFORM _assert(NOT my_feature_enabled('training') AND my_feature_enabled('skills'),
      '§79 (resolve): his colleague''s Training and Skills resolve the wrong way round');
    FOREACH k IN ARRAY ARRAY['manager', 'teacher', 'parent', 'pupil', 'spectator'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(my_feature_enabled('skills') AND my_feature_enabled('training')
                      AND feature_enabled('skills', HIL, (y->>k)::uuid),
        format('§79 (resolve): Skills or Training reads as off for the %s, from whom nothing was hidden', k));
    END LOOP;
    PERFORM _as((y->>'wesnamed')::uuid);
    PERFORM _assert(NOT my_feature_enabled('skills'), '§79 (resolve): Westville''s named coach reads Skills as on');
    PERFORM _as((y->>'wesmanager')::uuid);
    PERFORM _assert(my_feature_enabled('skills'), '§79 (resolve): Westville''s row reached its administrator');

    -- (school)
    FOREACH k IN ARRAY ARRAY['manager', 'named', 'teacher', 'parent', 'pupil', 'spectator'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(NOT my_feature_enabled('leagues'),
        format('§79 (school): Leagues reads as on for the %s at a school that hid it', k));
    END LOOP;
    PERFORM _as((y->>'wesmanager')::uuid);
    PERFORM _assert(my_feature_enabled('leagues') AND NOT feature_enabled('leagues', HIL, NULL),
      '§79 (school): Hilton''s school-wide row reached Westville, or stopped resolving at Hilton');

    -- (writes)
    PERFORM _as((y->>'manager')::uuid);
    INSERT INTO feature_suppression (key, school_id, person_id, reason, hidden_by)
    VALUES ('analytics', HIL, (y->>'teacher')::uuid, 'v102: a write', app_user_id())
    RETURNING id INTO v_new;
    PERFORM _assert(v_new IS NOT NULL AND feature_suppression_reason(v_new) = 'v102: a write',
      '§79 (writes): the manager''s hide returned no row, or he cannot read the reason he wrote');
    UPDATE feature_suppression SET lifted_at = now(), lifted_by = app_user_id()
     WHERE id = v_new AND lifted_at IS NULL
    RETURNING person_id::text INTO got;
    PERFORM _assert(got = (y->>'teacher'), '§79 (writes): the manager could not lift the suppression he wrote');

    -- (doors)
    PERFORM _assert((SELECT pg_get_expr(p.polqual, p.polrelid) FROM pg_policy p
                      WHERE p.polrelid = 'feature_suppression'::regclass AND p.polname = 'feature_suppression_read')
                    = '(((person_id IS NULL) AND app_enrolled()) OR ((person_id IS NOT NULL) AND ((person_id = app_user_id()) OR '
                      'app_can(''school.feature.manage''::text, school_id, NULL::text, NULL::uuid, NULL::uuid))))',
      '§79 (doors): feature_suppression_read is not the policy db/102 wrote');
    PERFORM _assert(NOT has_column_privilege('scrbrd_app', 'feature_suppression', 'reason', 'SELECT')
                    AND has_column_privilege('scrbrd_app', 'feature_suppression', 'person_id', 'SELECT'),
      '§79 (doors): scrbrd_app selects the reason, or lost the rest of the row');
    PERFORM _assert((SELECT prosecdef AND provolatile = 's' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                       FROM pg_proc WHERE oid = 'feature_suppression_reason(uuid)'::regprocedure)
                    AND has_function_privilege('scrbrd_app', 'feature_suppression_reason(uuid)'::regprocedure, 'EXECUTE')
                    AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                     WHERE p.oid = 'feature_suppression_reason(uuid)'::regprocedure
                                       AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
      '§79 (doors): feature_suppression_reason is not a stable definer for scrbrd_app alone');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 79
  -- ┌── db/103 (section 80) ──────────────────────────────────────────
  -- ── 80. The plan's byline: who wrote the side's plan (db/103) ──
  -- SCRBRD-138 phase B's "Plan from …" and CSA SG-9: a pupil knows which
  -- adult wrote to his side. plan_author_name(post) gives the author's name
  -- of a live plan to a reader of that plan, and nothing to anybody else.
  -- Every write below is a person's, through scrbrd_app under RLS;
  -- _v103_stage() stages as the owner.
  --
  -- What each label holds:
  --   (readers)  the 10XI coach sends a plan for 10XI's fixture; its author's
  --              name reads to the captain (on the sheet), a boy on the
  --              roster and not on it, the captain's guardian, the team
  --              manager and the coach himself; and the pupil and the parent
  --              still read no row of the coach's account (nothing else
  --              about him is opened)
  --   (side)     11XI's plan, and Westville's plan for the same fixture from
  --              the away end, name nobody to a 10XI reader; their own sides
  --              read their own authors
  --   (sheet)    a 11XI boy named on the fixture's sheet (playing up), and
  --              his guardian, read the author's name of the 10XI plan
  --              (db/101's news_post_read_sheet); Westville's plan they do
  --              not; once he is withdrawn from the sheet, neither reads it
  --   (others)   a 11XI boy and his guardian, Westville's coach and boy, a
  --              follower, the finance office, a signed-in account holding
  --              nothing, and an anonymous session get no name for the plan
  --   (draft)    the coach's draft plan for the fixture names nobody, to the
  --              side or to its author: the byline is a live plan's
  --   (post)     an ordinary 10XI post, which the captain and the guardian
  --              do read, names nobody through this function (ordinary posts
  --              are as before)
  --   (nothing)  a post that is not there, and no post at all, answer null
  --   (agree)    for every reader above and every post staged here, the name
  --              comes back exactly when the reader reads the row as a live
  --              plan under news_post's own policies, before the withdrawal
  --              and after it
  --   (withdrawn) once the coach withdraws the plan, nobody gets its author
  --   (doors)    a stable SECURITY DEFINER with a pinned path, returning one
  --              text; the application's to call and not PUBLIC's, nor a
  --              managed host's API roles'
  --
  -- Falsified once each, by replacing the function in the database and
  -- running this file; each went red at its label:
  --   (side)     asking app_can('news.read') at the side where it asks
  --              news_plan_reach() (red at the captain's guardian, on the
  --              11XI plan: a guardian's school-wide assignment, db/96 §4)
  --   (post)     without "n.kind = 'plan'" (red at the captain, on the
  --              ordinary post)
  --   (draft)    without "n.published_at IS NOT NULL AND …" (red at the
  --              captain, on the draft)
  --   (sheet)    without "OR news_sheet_reach(...)" (red at the boy playing
  --              up, on the sheet)
  DECLARE
    y        jsonb := _v103_stage();
    V_HIL    uuid := '11111111-1111-1111-1111-111111111111';
    V_WES    uuid := '22222222-2222-2222-2222-222222222222';
    F1       uuid := (y->>'f1')::uuid;
    F2       uuid := (y->>'f2')::uuid;
    EVERYONE text[] := ARRAY['coach', 'manager', 'captain', 'reserve', 'guardian', 'bcoach', 'bboy', 'bparent',
                             'upboy', 'upparent', 'wescoach', 'wesboy', 'follower', 'finance', 'stranger'];
    P uuid; D uuid; O uuid; B uuid; W uuid;
    k  text;
    x  uuid;
    got text;
  BEGIN
    -- The posts: the 10XI plan, a 10XI draft plan for the same fixture and
    -- an ordinary 10XI post, all the coach's; 11XI's plan; Westville's.
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, '10XI', 'The plan: v Westville 10XI', 'Bat first if we win it.', now(), 'plan', F1)
    RETURNING id INTO P;
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, '10XI', 'The plan: v Westville 10XI', 'Bowl first instead.', NULL, 'plan', F1)
    RETURNING id INTO D;
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, '10XI', 'Verify 103 nets', 'Nets at three on Thursday.', now())
    RETURNING id INTO O;
    PERFORM _as((y->>'bcoach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_HIL, '11XI', 'The plan: v Visitors', 'Bowl first if we win it.', now(), 'plan', F2)
    RETURNING id INTO B;
    PERFORM _as((y->>'wescoach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
    VALUES ('team', V_WES, '10XI', 'The plan: at Hilton 10XI', 'Bat first if we win it.', now(), 'plan', F1)
    RETURNING id INTO W;
    PERFORM _assert(P IS NOT NULL AND D IS NOT NULL AND O IS NOT NULL AND B IS NOT NULL AND W IS NOT NULL,
      '§80: a post was not staged');

    -- (readers)
    FOREACH k IN ARRAY ARRAY['captain', 'reserve', 'guardian', 'manager', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := plan_author_name(P);
      PERFORM _assert(got = 'V103 Coach', format('§80 (readers): the %s reads the plan''s author as %s', k, coalesce(got, 'null')));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['captain', 'guardian'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM app_user u WHERE u.id = (y->>'coach')::uuid) = 0,
        format('§80 (readers): the %s reads the coach''s account', k));
    END LOOP;

    -- (side)
    FOREACH k IN ARRAY ARRAY['captain', 'reserve', 'guardian'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(plan_author_name(B) IS NULL AND plan_author_name(W) IS NULL,
        format('§80 (side): the %s reads the author of another side''s plan (%s, %s)', k, plan_author_name(B), plan_author_name(W)));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['bboy', 'bparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(plan_author_name(B) = 'V103 Bcoach', format('§80 (side): the %s does not read his own side''s plan''s author', k));
    END LOOP;
    PERFORM _as((y->>'wesboy')::uuid);
    PERFORM _assert(plan_author_name(W) = 'V103 Wescoach', '§80 (side): the Westville boy does not read his side''s plan''s author');

    -- (sheet)
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = P) = 1,
        format('§80 (sheet): the %s does not read the 10XI plan through the sheet, so this proves nothing', k));
      got := plan_author_name(P);
      PERFORM _assert(got = 'V103 Coach', format('§80 (sheet): the %s, on the sheet, reads the plan''s author as %s', k, coalesce(got, 'null')));
      PERFORM _assert(plan_author_name(W) IS NULL AND plan_author_name(D) IS NULL,
        format('§80 (sheet): the %s reads the author of Westville''s plan or of the draft', k));
    END LOOP;

    -- (others)
    FOREACH k IN ARRAY ARRAY['bboy', 'bparent', 'bcoach', 'wescoach', 'wesboy', 'follower', 'finance', 'stranger'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := plan_author_name(P);
      PERFORM _assert(got IS NULL, format('§80 (others): the %s reads the 10XI plan''s author as %s', k, got));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(plan_author_name(P) IS NULL AND plan_author_name(B) IS NULL AND plan_author_name(W) IS NULL,
      '§80 (others): an anonymous session reads a plan''s author');

    -- (draft)
    FOREACH k IN ARRAY ARRAY['captain', 'reserve', 'guardian', 'manager', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := plan_author_name(D);
      PERFORM _assert(got IS NULL, format('§80 (draft): the %s reads the draft plan''s author as %s', k, got));
    END LOOP;

    -- (post)
    FOREACH k IN ARRAY ARRAY['captain', 'guardian', 'manager', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM news_post n WHERE n.id = O) = 1,
        format('§80 (post): the %s does not read the ordinary 10XI post, so this proves nothing', k));
      got := plan_author_name(O);
      PERFORM _assert(got IS NULL, format('§80 (post): the %s reads an ordinary post''s author through the plan''s byline as %s', k, got));
    END LOOP;

    -- (nothing)
    PERFORM _as((y->>'captain')::uuid);
    PERFORM _assert(plan_author_name(gen_random_uuid()) IS NULL AND plan_author_name(NULL) IS NULL,
      '§80 (nothing): a post that is not there has an author');

    -- (agree)
    FOREACH k IN ARRAY EVERYONE LOOP
      PERFORM _as((y->>k)::uuid);
      FOREACH x IN ARRAY ARRAY[P, D, O, B, W] LOOP
        PERFORM _assert((plan_author_name(x) IS NOT NULL)
                        = EXISTS (SELECT 1 FROM news_post n WHERE n.id = x AND n.kind = 'plan' AND n.published_at IS NOT NULL),
          format('§80 (agree): for the %s, the byline of %s (%s) and the read of it as a live plan disagree',
                 k, CASE x WHEN P THEN 'the 10XI plan' WHEN D THEN 'the draft' WHEN O THEN 'the post'
                           WHEN B THEN 'the 11XI plan' ELSE 'Westville''s plan' END, coalesce(plan_author_name(x), 'null')));
      END LOOP;
    END LOOP;

    -- (sheet), off it: withdrawn from the sheet, the boy and his guardian
    -- read neither the plan nor its author.
    PERFORM _assert(_v103_off_sheet(F1, (y->>'p_up')::uuid) = 1, '§80 (sheet): the boy was not withdrawn from the sheet');
    FOREACH k IN ARRAY ARRAY['upboy', 'upparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := plan_author_name(P);
      PERFORM _assert(got IS NULL AND (SELECT count(*) FROM news_post n WHERE n.id = P) = 0,
        format('§80 (sheet): off the sheet, the %s reads the plan''s author as %s', k, coalesce(got, 'null')));
      FOREACH x IN ARRAY ARRAY[P, D, O, B, W] LOOP
        PERFORM _assert((plan_author_name(x) IS NOT NULL)
                        = EXISTS (SELECT 1 FROM news_post n WHERE n.id = x AND n.kind = 'plan' AND n.published_at IS NOT NULL),
          format('§80 (agree): off the sheet, for the %s, the byline of a post and the read of it disagree', k));
      END LOOP;
    END LOOP;

    -- (withdrawn)
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert(_withdraw_91(P) = 'ok', '§80 (withdrawn): the author could not withdraw the plan');
    FOREACH k IN ARRAY EVERYONE LOOP
      PERFORM _as((y->>k)::uuid);
      got := plan_author_name(P);
      PERFORM _assert(got IS NULL, format('§80 (withdrawn): the %s reads the withdrawn plan''s author as %s', k, got));
      FOREACH x IN ARRAY ARRAY[P, D, O, B, W] LOOP
        PERFORM _assert((plan_author_name(x) IS NOT NULL)
                        = EXISTS (SELECT 1 FROM news_post n WHERE n.id = x AND n.kind = 'plan' AND n.published_at IS NOT NULL),
          format('§80 (agree): after the withdrawal, for the %s, the byline of a post and the read of it disagree', k));
      END LOOP;
    END LOOP;

    -- (doors)
    PERFORM _assert((SELECT prosecdef AND provolatile = 's' AND NOT proretset AND prorettype = 'text'::regtype
                            AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                       FROM pg_proc WHERE oid = to_regprocedure('plan_author_name(uuid)')),
      '§80 (doors): plan_author_name is not a stable SECURITY DEFINER returning one text with a pinned path');
    PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure('plan_author_name(uuid)'), 'EXECUTE')
                    AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                     WHERE p.oid = to_regprocedure('plan_author_name(uuid)') AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
      '§80 (doors): plan_author_name is not the application''s alone');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                   AND has_function_privilege(g.oid, to_regprocedure('plan_author_name(uuid)'), 'EXECUTE')),
      '§80 (doors): a managed host''s API role can call plan_author_name');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 80
  -- └── db/103 (section 80) ──────────────────────────────────────────
  -- ┌── section 81: corrections to a coach's judgement, and the coaching point (db/104) ──
  -- GA-I26a slice A1 (AH-D2, AH-D3, AH-D5). The API half is
  -- tools/smoke-assessment-history.mjs (the routes, the reads' access-log rows,
  -- the ratings over standing scores).
  --
  -- What each label holds:
  --   (score)      the coach's same-day revision is one row, his; the
  --                assistant (no development.write) is refused by policy;
  --                a second coach's same-day upsert is refused 45003 and his
  --                next-day row is his own; a forged assessor is stamped over
  --   (withdraw)   skill_withdraw(): refused to the boy, the assistant,
  --                Westville's coach and an empty reason; made by the coach and,
  --                on another row, by his colleague (any holder), the assessor
  --                kept; a second withdrawal refused; a withdrawn score not
  --                revised (45004); the same day re-rated on a new row
  --   (reads)      `skills` (its query, verbatim) leaves the withdrawn row out;
  --                `skills_history` returns it struck, with why
  --   (point)      coaching_point_write(): written by the coach on a skill row
  --                (author, no discipline, no adjustment, as-of the row's day);
  --                refused to the assistant, the director, the principal, the
  --                boy, Westville's coach; for a batterId not his, a skill row
  --                not his, a team-mate or a visitor named from the sheet, a
  --                never-word, an over-long body, an as-of or a head that
  --                does not parse, a pointer over 4 KB; evidence_text on S11 by the
  --                CHECK; a pointer inserted directly by policy
  --   (readers)    the point read by the coach, the assistant, the director,
  --                the principal; by nobody else: the boy (either account), his
  --                parent, the captain over him, the team manager, the analyst,
  --                the physio, the scorer, Westville's coach, the owner's key,
  --                an anonymous session — and the boy's selfaccess DOES read his
  --                scores, so the refusal is the note tier, not an empty account
  --   (support)    a support session as the side's coach reads the boy's player
  --                row, and no score and no point, and withdraws and writes none
  --   (edit)       a point's body is not edited (45002); a plain note keeps its
  --                author's edit and refuses a colleague's (45001) and a pointer
  --                (45002); note_withdraw() by the director changes the two
  --                columns alone; refused to the boy and Westville; a withdrawn
  --                note is not revised (45004)
  --   (doors)      the definers, the triggers, the cuts, the CHECKs
  --
  -- Falsified three times on 15 Oct, each red and then green on restoring:
  -- (1) the trigger player_skill_keeps_its_assessor dropped (the API's old
  -- re-attributing upsert, in effect): red at (score), "a colleague's
  -- same-day upsert onto the coach's row ended ok, not 45003"; (2) the note
  -- tier opened to the boy (player.note.read granted to selfaccess in
  -- role_capability, I27's reach): red at (readers), "the self reads a note
  -- or a coaching point about the boy"; (3) player_skill_not_support
  -- dropped: red at (support), "a support session reads the boy's scores".
  DECLARE
    y      jsonb := _v104_stage();
    HIL    uuid := '11111111-1111-1111-1111-111111111111';
    SUBJ   uuid := (y->>'subject')::uuid;
    M      uuid := (y->>'mate')::uuid;
    F1     uuid := (y->>'f1')::uuid;
    k      text;
    got    text;
    n      int;
    v_ok   boolean;
    v_why  text;
    K1     uuid;   -- footwork, the coach's
    K2     uuid;   -- footwork tomorrow, the colleague's
    KT     uuid;   -- timing, the wrong boy: withdrawn
    KT2    uuid;   -- timing re-rated the same day
    KP     uuid;   -- power, the coach's, withdrawn by the colleague
    KM     uuid;   -- the team-mate's footwork
    PT     uuid;   -- the coaching point
    NP     uuid;   -- a plain note
    SUP    uuid;   -- the support session
    upsert text := 'insert into player_skill (player_id, assessed_on, assessed_by, category, metric, score, note) '
                   'values (%L, %s, app_user_id(), ''technical'', %L, %s, null) '
                   'on conflict (player_id, assessed_on, category, metric) where withdrawn_at is null '
                   'do update set score = excluded.score, note = excluded.note returning id';
  BEGIN
    -- (score)
    PERFORM _as((y->>'coach')::uuid);
    EXECUTE format(upsert, SUBJ, 'current_date', 'footwork', 11) INTO K1;
    EXECUTE format(upsert, SUBJ, 'current_date', 'footwork', 12) INTO got;
    PERFORM _assert(got::uuid = K1 AND (_v104_skill(K1)->>'score')::int = 12
                    AND _v104_skill(K1)->>'assessed_by' = y->>'coach',
      '§81 (score): the coach''s same-day revision is not one row, his, at 12');
    PERFORM _as((y->>'assistant')::uuid);
    PERFORM _assert(_v104_try(format(upsert, SUBJ, 'current_date', 'footwork', 14)) = '42501',
      '§81 (score): the assistant coach rated the boy');
    PERFORM _as((y->>'coach2')::uuid);
    got := _v104_try(format(upsert, SUBJ, 'current_date', 'footwork', 9));
    PERFORM _assert(got = '45003', format('§81 (score): a colleague''s same-day upsert onto the coach''s row ended %s, not 45003', got));
    PERFORM _assert(_v104_try(format('update player_skill set score = 9 where id = %L', K1)) = '45003',
      '§81 (score): a colleague revised the coach''s score directly');
    PERFORM _assert((_v104_skill(K1)->>'score')::int = 12 AND _v104_skill(K1)->>'assessed_by' = y->>'coach',
      '§81 (score): the coach''s row moved, or changed hands');
    EXECUTE format(upsert, SUBJ, 'current_date + 1', 'footwork', 9) INTO K2;
    PERFORM _assert(K2 <> K1 AND _v104_skill(K2)->>'assessed_by' = y->>'coach2',
      '§81 (score): the colleague''s next-day rating is not a row of his own');
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO player_skill (player_id, assessed_on, assessed_by, category, metric, score)
    VALUES (SUBJ, current_date, (y->>'coach2')::uuid, 'technical', 'timing', 7) RETURNING id INTO KT;
    PERFORM _assert(_v104_skill(KT)->>'assessed_by' = y->>'coach',
      '§81 (score): an insert naming another assessor was not stamped with the writer');
    EXECUTE format(upsert, SUBJ, 'current_date', 'power', 13) INTO KP;
    EXECUTE format(upsert, M, 'current_date', 'footwork', 10) INTO KM;

    -- (withdraw)
    FOREACH k IN ARRAY ARRAY['self', 'assistant', 'wescoach', 'manager', 'parent'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT w.ok, w.reason INTO v_ok, v_why FROM skill_withdraw(KT, 'rated the wrong boy') w;
      PERFORM _assert(NOT v_ok AND v_why = 'not_permitted', format('§81 (withdraw): the %s withdrew a score (%s)', k, v_why));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    SELECT w.ok, w.reason INTO v_ok, v_why FROM skill_withdraw(KT, '  ') w;
    PERFORM _assert(NOT v_ok AND v_why = 'reason_required', '§81 (withdraw): a withdrawal without a reason was taken');
    SELECT w.ok, w.reason INTO v_ok, v_why FROM skill_withdraw(KT, 'rated the wrong boy') w;
    PERFORM _assert(v_ok, format('§81 (withdraw): the coach could not withdraw his score (%s)', v_why));
    PERFORM _assert(_v104_skill(KT)->>'assessed_by' = y->>'coach'
                    AND _v104_skill(KT)->>'withdrawn_by' = y->>'coach'
                    AND _v104_skill(KT)->>'withdrawn_reason' = 'rated the wrong boy'
                    AND _v104_skill(KT)->>'withdrawn_at' IS NOT NULL
                    AND (_v104_skill(KT)->>'score')::int = 7,
      '§81 (withdraw): the withdrawn row lost its assessor or its score, or was not stamped');
    SELECT w.ok, w.reason INTO v_ok, v_why FROM skill_withdraw(KT, 'again') w;
    PERFORM _assert(NOT v_ok AND v_why = 'already_withdrawn', '§81 (withdraw): a score was withdrawn twice');
    PERFORM _assert(_v104_try(format('update player_skill set score = 8 where id = %L', KT)) = '45004',
      '§81 (withdraw): a withdrawn score was revised');
    PERFORM _assert(_v104_try(format('update player_skill set withdrawn_at = null, withdrawn_by = null where id = %L', KT)) = '45004',
      '§81 (withdraw): a withdrawn score was put back');
    EXECUTE format(upsert, SUBJ, 'current_date', 'timing', 14) INTO KT2;
    PERFORM _assert(KT2 IS NOT NULL AND KT2 <> KT AND (_v104_skill(KT2)->>'score')::int = 14,
      '§81 (withdraw): the same day could not be re-rated after a withdrawal');
    PERFORM _as((y->>'coach2')::uuid);
    SELECT w.ok, w.reason INTO v_ok, v_why FROM skill_withdraw(KP, 'not watched; my mistake') w;
    PERFORM _assert(v_ok AND _v104_skill(KP)->>'assessed_by' = y->>'coach' AND _v104_skill(KP)->>'withdrawn_by' = y->>'coach2',
      format('§81 (withdraw): the colleague could not withdraw the coach''s score, or took it (%s)', v_why));

    -- (reads) `skills` and `skills_history`, as services/api/read/read-api.mjs runs them
    PERFORM _as((y->>'coach')::uuid);
    SELECT string_agg(x.metric || ':' || x.score, ',' ORDER BY x.metric) INTO got
      FROM (select s.id, s.player_id, s.assessed_on, s.category, s.metric, s.score, p.full_name, p.team_code
              from player_skill s join player p on p.id = s.player_id
             where s.withdrawn_at is null
             order by s.assessed_on desc, p.full_name) x
     WHERE x.player_id = SUBJ AND x.assessed_on = current_date;
    PERFORM _assert(got = 'footwork:12,timing:14', format('§81 (reads): `skills` gives today %s, not footwork 12 and timing 14', coalesce(got, 'nothing')));
    SELECT count(*) FILTER (WHERE x.withdrawn_at IS NOT NULL AND x.withdrawn_reason IS NOT NULL), count(*) INTO n, k
      FROM (select s.id, s.player_id, p.school_id, s.assessed_on, s.category, s.metric, s.score,
                   s.assessed_by, a.name as assessed_by_name,
                   s.withdrawn_at, s.withdrawn_by, w.name as withdrawn_by_name, s.withdrawn_reason
              from player_skill s
              join player p on p.id = s.player_id
              left join app_user a on a.id = s.assessed_by
              left join app_user w on w.id = s.withdrawn_by
             where (SUBJ::uuid is null or s.player_id = SUBJ)
             order by s.player_id, s.category, s.metric, s.assessed_on, s.id) x;
    PERFORM _assert(n = 2 AND k::int = 5, format('§81 (reads): `skills_history` gives %s rows, %s struck, not 5 and 2', k, n));
    PERFORM _as((y->>'self')::uuid);
    SELECT count(*) INTO n FROM player_skill WHERE player_id = SUBJ;
    PERFORM _assert(n = 5, format('§81 (reads): the boy reads %s of his own five scores', n));

    -- (point)
    PERFORM _as((y->>'coach')::uuid);
    SELECT c.ok, c.reason, c.id INTO v_ok, v_why, PT
      FROM coaching_point_write(SUBJ, NULL, 'front foot is late to the pitch',
                                jsonb_build_object('read', 'skills', 'params', jsonb_build_object('skillId', K1))) c;
    PERFORM _assert(v_ok, format('§81 (point): the coach could not write a coaching point (%s)', v_why));
    PERFORM _assert(_v104_note(PT)->>'author_id' = y->>'coach'
                    AND _v104_note(PT)->>'about_discipline' IS NULL AND _v104_note(PT)->>'adjustment' IS NULL
                    AND _v104_note(PT)->>'evidence_read' = 'skills'
                    AND (_v104_note(PT)->>'evidence_as_of')::timestamptz = (current_date::timestamp AT TIME ZONE 'Africa/Johannesburg')
                    AND _v104_note(PT)->'evidence_params'->>'skillId' = K1::text,
      '§81 (point): the point is not the coach''s, pinned to the row, moving nothing');
    FOREACH k IN ARRAY ARRAY['assistant', 'director', 'principal', 'self', 'boy', 'wescoach', 'manager'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT c.ok, c.reason INTO v_ok, v_why
        FROM coaching_point_write(SUBJ, NULL, 'front foot is late to the pitch',
                                  jsonb_build_object('read', 'skills', 'params', jsonb_build_object('skillId', K1))) c;
      PERFORM _assert(NOT v_ok AND v_why = 'not_permitted', format('§81 (point): the %s wrote a coaching point (%s)', k, v_why));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    FOREACH k IN ARRAY ARRAY[
        'batter|{"read":"matchups","asOf":"2026-10-01T10:00:00Z","params":{"batterId":"' || M || '"}}|front foot is late|evidence_names_another_boy',
        'skill|{"read":"skills","params":{"skillId":"' || KM || '"}}|front foot is late|evidence_not_his',
        'mate|{"read":"skills","params":{"skillId":"' || K1 || '"}}|plays like Verify OneOhFour Mate at his best|names_another_boy',
        'visitor|{"read":"skills","params":{"skillId":"' || K1 || '"}}|watch Verify OneOhFour Visitor on the drive|names_another_boy',
        'word|{"read":"skills","params":{"skillId":"' || K1 || '"}}|a hamstring niggle, so no short balls|forbidden_word',
        'pct|{"read":"skills","params":{"skillId":"' || K1 || '"}}|bowled at 70 % of his pace|forbidden_word',
        'long|{"read":"skills","params":{"skillId":"' || K1 || '"}}|' || repeat('x', 501) || '|body_length',
        'noread|{"params":{"skillId":"' || K1 || '"}}|front foot is late|evidence_required',
        'noasof|{"read":"matchups"}|front foot is late|evidence_as_of_required',
        'badasof|{"read":"matchups","asOf":"the day after the nets"}|front foot is late|evidence_malformed',
        'badhead|{"read":"matchups","asOf":"2026-10-01T10:00:00Z","head":"twelve"}|front foot is late|evidence_malformed',
        'big|{"read":"matchups","asOf":"2026-10-01T10:00:00Z","params":{"pad":"' || repeat('x', 5000) || '"}}|front foot is late|evidence_too_large'] LOOP
      SELECT c.ok, c.reason INTO v_ok, v_why
        FROM coaching_point_write(SUBJ, F1, split_part(k, '|', 3), split_part(k, '|', 2)::jsonb) c;
      PERFORM _assert(NOT v_ok AND v_why = split_part(k, '|', 4),
        format('§81 (point): %s ended %s, not %s', split_part(k, '|', 1), coalesce(v_why, 'written'), split_part(k, '|', 4)));
    END LOOP;
    got := _v104_try(format('select * from coaching_point_write(%L, null, ''late on the pull'', %L::jsonb)', SUBJ,
                            '{"read":"matchups","rule":"S11","asOf":"2026-10-01T10:00:00Z","text":["line one"]}'));
    PERFORM _assert(got = '23514', format('§81 (point): evidence_text on an S11 card ended %s, not the CHECK', got));
    got := _v104_try(format('insert into development_note (player_id, school_id, author_id, body, evidence_read, evidence_as_of) '
                            'values (%L, %L, app_user_id(), ''a point by the back door'', ''skills'', now())', SUBJ, HIL));
    PERFORM _assert(got = '42501', format('§81 (point): a pointer inserted directly by policy ended %s', got));

    -- (readers)
    FOREACH k IN ARRAY ARRAY['coach', 'coach2', 'assistant', 'director', 'principal'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM development_note WHERE id = PT) = 1,
        format('§81 (readers): the %s does not read the coaching point', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['self', 'boy', 'parent', 'captain', 'manager', 'analyst', 'medical', 'scorer', 'wescoach', 'owner', 'plat'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM development_note WHERE player_id = SUBJ) = 0,
        format('§81 (readers): the %s reads a note or a coaching point about the boy', k));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM development_note WHERE player_id = SUBJ) = 0
                    AND (SELECT count(*) FROM player_skill WHERE player_id = SUBJ) = 0,
      '§81 (readers): an anonymous session reads the boy''s judgements');
    -- The refusals above are the note tier: the same people's reach of the scores.
    PERFORM _as((y->>'self')::uuid);
    PERFORM _assert((SELECT count(*) FROM player_skill WHERE player_id = SUBJ) > 0,
      '§81 (readers): the boy reads none of his scores — his refusal above proves nothing');
    PERFORM _as((y->>'owner')::uuid);
    PERFORM _assert((SELECT count(*) FROM player_skill WHERE player_id = SUBJ) > 0,
      '§81 (readers): the owner''s key reads none of the boy''s scores — its note refusal above proves nothing');
    FOREACH k IN ARRAY ARRAY['boy', 'parent', 'captain', 'manager', 'analyst', 'medical', 'scorer', 'wescoach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM player_skill WHERE player_id = SUBJ) = 0,
        format('§81 (readers): the %s reads the boy''s scores', k));
    END LOOP;
    PERFORM _as((y->>'captain')::uuid);
    PERFORM _assert((SELECT count(*) FROM player WHERE id = SUBJ) = 1,
      '§81 (readers): the captain does not read his team-mate''s player row — his refusals above prove nothing');

    -- (support)
    PERFORM _as((y->>'plat')::uuid);
    SELECT b.ok, b.reason, b.id INTO v_ok, v_why, SUP
      FROM support_access_begin(HIL, 'coach', 'Verify 104: ticket 1041 about the side', '20XI', 30) b;
    PERFORM _assert(v_ok, format('§81 (support): the session was not begun (%s)', v_why));
    PERFORM _assert((SELECT count(*) FROM player WHERE id = SUBJ) = 1,
      '§81 (support): the session as the side''s coach reads no player row — its refusals below prove nothing');
    PERFORM _assert((SELECT count(*) FROM player_skill WHERE player_id = SUBJ) = 0,
      '§81 (support): a support session reads the boy''s scores');
    PERFORM _assert((SELECT count(*) FROM development_note WHERE player_id = SUBJ) = 0,
      '§81 (support): a support session reads a note or a point');
    SELECT w.ok, w.reason INTO v_ok, v_why FROM skill_withdraw(K2, 'support says so') w;
    PERFORM _assert(NOT v_ok, '§81 (support): a support session withdrew a score');
    SELECT c.ok INTO v_ok FROM coaching_point_write(SUBJ, NULL, 'front foot is late',
                                                    jsonb_build_object('read', 'skills', 'params', jsonb_build_object('skillId', K1))) c;
    PERFORM _assert(NOT v_ok, '§81 (support): a support session wrote a coaching point');
    PERFORM _assert(_v104_try(format(upsert, SUBJ, 'current_date + 3', 'footwork', 3)) = '42501',
      '§81 (support): a support session rated the boy');
    PERFORM support_access_end(SUP);
    PERFORM set_config('app.user_id', '', true);

    -- (edit)
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert(_v104_try(format('update development_note set body = ''front foot is very late'' where id = %L', PT)) = '45002',
      '§81 (edit): the author edited his coaching point');
    INSERT INTO development_note (player_id, school_id, author_id, body, about_discipline, adjustment, observed_on)
    SELECT SUBJ, player_school(SUBJ), app_user_id(), 'Quiet in the nets this week.', NULL, NULL, current_date
     WHERE player_school(SUBJ) IS NOT NULL
    RETURNING id INTO NP;
    PERFORM _assert(_v104_try(format('update development_note set body = ''Quiet in the nets; spoke to him.'' where id = %L', NP)) = 'ok'
                    AND _v104_note(NP)->>'body' = 'Quiet in the nets; spoke to him.',
      '§81 (edit): the author could not edit his plain note');
    PERFORM _assert(_v104_try(format('update development_note set evidence_read = ''skills'', evidence_as_of = now() where id = %L', NP)) = '45002',
      '§81 (edit): a plain note gained a pointer by an edit');
    PERFORM _as((y->>'assistant')::uuid);
    PERFORM _assert(_v104_try(format('update development_note set body = ''Rewritten.'' where id = %L', NP)) = '45001',
      '§81 (edit): a colleague edited the coach''s plain note');
    PERFORM _assert(_v104_try(format('insert into development_note (player_id, school_id, author_id, body) '
                                     'values (%L, %L, app_user_id(), ''Bowled well to the left-handers.'')', SUBJ, HIL)) = 'ok',
      '§81 (edit): the assistant could not write a plain note');
    FOREACH k IN ARRAY ARRAY['self', 'wescoach', 'principal', 'manager'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT w.ok, w.reason INTO v_ok, v_why FROM note_withdraw(PT) w;
      PERFORM _assert(NOT v_ok AND v_why = 'not_permitted', format('§81 (edit): the %s withdrew the coaching point (%s)', k, v_why));
    END LOOP;
    got := (_v104_note(PT) - 'withdrawn_at' - 'withdrawn_by')::text;
    PERFORM _as((y->>'director')::uuid);
    SELECT w.ok, w.reason INTO v_ok, v_why FROM note_withdraw(PT) w;
    PERFORM _assert(v_ok AND (_v104_note(PT) - 'withdrawn_at' - 'withdrawn_by')::text = got
                    AND _v104_note(PT)->>'withdrawn_by' = y->>'director' AND _v104_note(PT)->>'withdrawn_at' IS NOT NULL,
      format('§81 (edit): the director''s withdrawal changed more than its two columns, or failed (%s)', v_why));
    SELECT w.ok, w.reason INTO v_ok, v_why FROM note_withdraw(PT) w;
    PERFORM _assert(NOT v_ok AND v_why = 'already_withdrawn', '§81 (edit): a point was withdrawn twice');
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM development_note WHERE id = PT AND withdrawn_at IS NOT NULL) = 1,
      '§81 (edit): the withdrawn point is no longer readable, struck, to the coach');
    SELECT w.ok INTO v_ok FROM note_withdraw(NP) w;
    PERFORM _assert(v_ok AND _v104_try(format('update development_note set body = ''Changed my mind.'' where id = %L', NP)) = '45004',
      '§81 (edit): a withdrawn plain note was revised');

    -- (doors)
    FOREACH k IN ARRAY ARRAY['coaching_point_write(uuid,uuid,text,jsonb)', 'skill_withdraw(uuid,text)', 'note_withdraw(uuid)'] LOOP
      PERFORM _assert((SELECT prosecdef AND provolatile = 'v' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = to_regprocedure(k)),
        format('§81 (doors): %s is not a volatile SECURITY DEFINER with a pinned path', k));
      PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure(k), 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = to_regprocedure(k) AND a.grantee = 0 AND a.privilege_type = 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                         AND has_function_privilege(g.oid, to_regprocedure(k), 'EXECUTE')),
        format('§81 (doors): %s is not the application''s alone', k));
    END LOOP;
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', to_regprocedure('coaching_point_never(text)'), 'EXECUTE'),
      '§81 (doors): the application calls the internal coaching_point_never');
    PERFORM _assert((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE'
                       AND (tablename, policyname) IN (('player_skill', 'player_skill_not_support'),
                                                       ('development_note', 'development_note_not_support'),
                                                       ('development_note', 'development_note_not_platform'),
                                                       ('development_note', 'development_note_plain_insert'))) = 4,
      '§81 (doors): the four RESTRICTIVE policies are not all there');
    PERFORM _assert((SELECT pg_get_constraintdef(c.oid) FROM pg_constraint c
                      WHERE c.conrelid = 'development_note'::regclass AND c.conname = 'note_evidence_whole')
                    = 'CHECK (((evidence_read IS NULL) OR (evidence_as_of IS NOT NULL)))',
      '§81 (doors): a pointer without its as-of is not refused by the CHECK');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public'
                                  AND tablename IN ('player_skill', 'development_note') AND cmd = 'DELETE'),
      '§81 (doors): a judgement may be deleted');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 81
  -- ┌── section 82: the development loop — a target, the side's plan, the register (db/105) ──
  -- GA-I26a slice A2 (AH-D1, AH-D3, AH-D9). The API half is
  -- tools/smoke-assessment-history.mjs (the routes, `injured` refused with
  -- 422, the export refusals, the Training gate, the reads' log rows).
  --
  -- What each label holds:
  --   (set)        target_set() by the coach over a standing 9: the row, on
  --                that score, his; refused at 9 and 8 (already_there), at 21
  --                (the CHECK), for a retired drill, another school's drill, a
  --                note about the team-mate, a date gone by, and to the
  --                assistant, the director, the team manager, the boy, his
  --                parent, Westville's coach; a second target on the metric
  --                replaces the first (struck 'replaced'), one open row
  --   (withdraw)   target_withdraw(): refused to the boy and without a
  --                reason; made by the coach; not twice
  --   (readers)    the target read by the coach, the assistant, the director
  --                and the boy himself; by nobody else: the principal, his
  --                parent, the team manager, the analyst, the team-mate (his
  --                own selfaccess included) who is captain, U19F's coach,
  --                Westville's coach, an anonymous session; `targets` (its
  --                query, verbatim) gives the boy no note id and the coach his
  --   (writes)     no person writes development_target directly: INSERT,
  --                UPDATE, DELETE refused to the coach
  --   (plan)       the team manager plans U19E's sessions (platform drills)
  --                under team.training.run (Kameel, 15 Oct), and the coach
  --                too; the team manager, the boy, the parent, the team-mate,
  --                the analyst and the director read the plan; U19F's coach,
  --                Westville's coach and an anonymous session do not; the
  --                assistant (whose bundle holds no team.training.run), the
  --                parent and the boy write none; the team manager writes
  --                none for U19F, another side; a Westville drill on a Hilton
  --                plan is refused; the team manager replaces a plan (delete)
  --   (register)   the team manager marks the boy present; `injured` refused
  --                (insert and update) under the application's role; the
  --                parent and the assistant write none, nor the team manager
  --                on U19F's session; the team-mate's
  --                `injured` row written
  --                before db/105 reads back `excused` through
  --                `training_attendance` (its query, verbatim)
  --   (since)      `development_since` (its query, verbatim) for batting, as
  --                the coach and as the boy: anchored ten days ago; four
  --                sessions (not the cancelled one, not the one ahead, not
  --                the one before the look), three with a register, present
  --                one, late one, never the absence; throw-downs ran three
  --                times and short-pitch once; the target's drill ran three
  --                times and he was there for two. The team manager and the
  --                parent get no rows. The anchor withdrawn: the window opens
  --                back to twenty days and counts five. The window starts at
  --                the day he joined his side when that is later.
  --   (manager)    team.training.run is all he gained: the team manager is
  --                still refused the drill library, the kit register and the
  --                calendar (team.manage's), at his own side
  --   (support)    a support session as U19E's coach reads no target and
  --                sets none
  --   (doors)      the definers, the privileges, the cuts, the trigger
  --
  -- Falsified three times on 15 Oct, each red and then green on restoring
  -- (re-pasting db/105): (1) training_attendance_no_health_word dropped: red
  -- at (register), "`injured` was written by the application"; (2)
  -- development_target_read widened to player.profile.read (the register's
  -- tier): red at (readers), "the principal reads the boy's targets"; (3) the
  -- trigger training_session_drill_from_the_library dropped: red at (plan),
  -- "a Westville drill went on a Hilton plan". And on team.training.run
  -- (Kameel, 15 Oct): (4) the team manager's row taken out of role_capability:
  -- red at (plan), his insert refused; (5) the plan's insert policy's side
  -- scope dropped (team '*', with the school read past row security so the
  -- session's own read policy, which also refuses him U19F's session, does not
  -- mask it): red at (plan), "the team manager planned U19F's session, another
  -- side's"; with the side kept and only the school read past row security it
  -- stays green, so the side scope is what refuses him.
  DECLARE
    y      jsonb := _v105_stage();
    HIL    uuid := '11111111-1111-1111-1111-111111111111';
    SUBJ   uuid := (y->>'p_subject')::uuid;
    MATE   uuid := (y->>'p_mate')::uuid;
    TD     uuid := (y->>'throwdowns')::uuid;
    SP     uuid := (y->>'shortpitch')::uuid;
    BAT    text[] := ARRAY['technical.footwork','technical.timing','technical.power','technical.shotRange','technical.defence',
                           'technical.againstPace','technical.againstSpin','mental.concentration','mental.composure',
                           'mental.decisions','mental.bravery','tactical.strikeRotation','tactical.oppositionAnalysis',
                           'tactical.deathOversExecution'];
    Q_SINCE text := $qsince$with b as (
             select p.id, p.school_id, p.team_code
               from player p
              where p.id = $1::uuid
                and app_can('player.development.read', p.school_id, p.team_code, p.id,
                            '00000000-0000-0000-0000-000000000000'::uuid)),
           disc(discipline, attrs, ord) as (
             values ('batting', $2::text[], 1), ('bowling', $3::text[], 2),
                    ('fielding', $4::text[], 3), ('keeping', $5::text[], 4)),
           a as (
             select b.id as player_id, b.school_id, b.team_code, disc.discipline, disc.attrs, disc.ord,
                    (select max(s.assessed_on) from player_skill s
                      where s.player_id = b.id and s.withdrawn_at is null
                        and (s.category || '.' || s.metric) = any(disc.attrs)) as anchor,
                    (select max(m.joined_on) from team_membership m
                      where m.player_id = b.id and m.left_on is null and m.team_code = b.team_code) as joined_on
               from b cross join disc),
           w as (
             select a.*, case when a.anchor is null then null
                              else greatest(a.anchor, coalesce(a.joined_on, a.anchor)) end as window_from
               from a),
           sess as (
             select w.discipline, t.id as session_id,
                    exists (select 1 from training_attendance r where r.session_id = t.id) as registered,
                    (select r.status from training_attendance r where r.session_id = t.id and r.player_id = w.player_id) as his
               from w join training_session t
                 on w.window_from is not null
                and t.school_id = w.school_id and t.team_code = w.team_code and not t.cancelled
                and t.starts_at >= (w.window_from::timestamp at time zone 'Africa/Johannesburg')
                and t.starts_at <= now())
           select w.player_id, w.school_id, w.team_code, w.discipline, w.anchor, w.joined_on, w.window_from,
                  case when w.window_from is null then null else
                    (select count(*) from sess where sess.discipline = w.discipline)::int end as sessions,
                  case when w.window_from is null then null else
                    (select count(*) from sess where sess.discipline = w.discipline and sess.registered)::int end as registered,
                  case when w.window_from is null then null else
                    (select count(*) from sess where sess.discipline = w.discipline and sess.his = 'present')::int end as present,
                  case when w.window_from is null then null else
                    (select count(*) from sess where sess.discipline = w.discipline and sess.his = 'late')::int end as late,
                  (select coalesce(jsonb_agg(jsonb_build_object('drillId', x.drill_id, 'name', x.name, 'times', x.times)
                                             order by x.times desc, x.name), '[]'::jsonb)
                     from (select k.drill_id, d.name, count(*)::int as times
                             from sess join training_session_drill k on k.session_id = sess.session_id
                             join drill d on d.id = k.drill_id
                            where sess.discipline = w.discipline
                            group by k.drill_id, d.name) x) as drills,
                  (select coalesce(jsonb_agg(jsonb_build_object(
                            'id', t.id, 'category', t.category, 'metric', t.metric, 'target_score', t.target_score,
                            'set_on', t.set_on, 'due_on', t.due_on, 'drillId', t.drill_id, 'drillName', d.name,
                            'drillRan', (select count(*) from sess join training_session_drill k
                                           on k.session_id = sess.session_id and k.drill_id = t.drill_id
                                          where sess.discipline = w.discipline),
                            'drillAttended', (select count(*) from sess join training_session_drill k
                                                on k.session_id = sess.session_id and k.drill_id = t.drill_id
                                               where sess.discipline = w.discipline and sess.his in ('present', 'late')))
                            order by t.category, t.metric), '[]'::jsonb)
                     from development_target t left join drill d on d.id = t.drill_id
                    where t.player_id = w.player_id and t.withdrawn_at is null
                      and (t.category || '.' || t.metric) = any(w.attrs)) as targets
             from w
            order by w.ord$qsince$;
    Q_TARGETS text := $qtargets$select t.id, t.player_id, t.school_id, t.category, t.metric, t.target_score,
                  t.set_on, t.due_on, t.set_by, sb.name as set_by_name,
                  t.drill_id, d.name as drill_name, d.category as drill_category,
                  (select n.id from development_note n where n.id = t.note_id) as note_id,
                  t.from_skill_id, fs.score as from_score, fs.assessed_on as from_assessed_on,
                  fs.withdrawn_at is not null as from_withdrawn,
                  now_s.score as standing_score, now_s.assessed_on as standing_on,
                  (select min(r.assessed_on) from player_skill r
                    where r.player_id = t.player_id and r.category = t.category and r.metric = t.metric
                      and r.withdrawn_at is null and r.assessed_on >= t.set_on
                      and r.score >= t.target_score) as reached_on,
                  t.withdrawn_at, t.withdrawn_by, t.withdrawn_reason
             from development_target t
             left join app_user sb on sb.id = t.set_by
             left join drill d on d.id = t.drill_id
             left join player_skill fs on fs.id = t.from_skill_id
             left join lateral (
               select s.score, s.assessed_on from player_skill s
                where s.player_id = t.player_id and s.category = t.category and s.metric = t.metric
                  and s.withdrawn_at is null
                order by s.assessed_on desc, s.id desc limit 1) now_s on true
            where ($1::uuid is null or t.player_id = $1)
            order by t.player_id, t.withdrawn_at nulls first, t.set_on desc, t.created_at desc$qtargets$;
    Q_ATT  text := $qatt$select a.session_id, a.player_id,
                  case when a.status = 'injured' then 'excused' else a.status end as status,
                  p.full_name
             from training_attendance a
             join player p on p.id = a.player_id
            where ($1::uuid is null or a.session_id = $1)
            order by p.full_name$qatt$;
    Q_PLAN text := $qplan$select x.session_id, x.position, x.drill_id, d.name, d.category,
                  coalesce(x.minutes, d.duration_min) as minutes, x.minutes is null as default_minutes
             from training_session_drill x
             join drill d on d.id = x.drill_id
            where ($1::uuid is null or x.session_id = $1)
            order by x.session_id, x.position$qplan$;
    k      text;
    got    text;
    j      jsonb;
    n      int;
    v_ok   boolean;
    v_why  text;
    T1     uuid;   -- the first target on againstPace
    T2     uuid;   -- its replacement
    SUP    uuid;
  BEGIN
    -- (set)
    PERFORM _as((y->>'coach')::uuid);
    SELECT t.ok, t.reason, t.id INTO v_ok, v_why, T1 FROM target_set(SUBJ, 'technical', 'againstPace', 12, current_date + 45, TD, NULL) t;
    PERFORM _assert(v_ok, format('§82 (set): the coach could not set a target (%s)', v_why));
    PERFORM _assert(_v105_target(T1)->>'from_skill_id' = y->>'k10' AND _v105_target(T1)->>'set_by' = y->>'coach'
                    AND (_v105_target(T1)->>'target_score')::int = 12 AND _v105_target(T1)->>'school_id' = HIL::text,
      '§82 (set): the target does not stand on the standing 9, or is not the coach''s');
    FOREACH k IN ARRAY ARRAY[
        '9||||already_there', '8||||already_there',
        '13|retired|||drill_retired', '13|wesdrill|||no_such_drill',
        '13||matenote||note_not_his', '13|||past|due_in_past'] LOOP
      SELECT t.ok, t.reason INTO v_ok, v_why
        FROM target_set(SUBJ, 'technical', 'againstPace', split_part(k, '|', 1)::int,
                        CASE WHEN split_part(k, '|', 4) = 'past' THEN current_date - 1 END,
                        (y->>nullif(split_part(k, '|', 2), ''))::uuid, (y->>nullif(split_part(k, '|', 3), ''))::uuid) t;
      PERFORM _assert(NOT v_ok AND v_why = split_part(k, '|', 5),
        format('§82 (set): %s ended %s, not %s', k, coalesce(v_why, 'set'), split_part(k, '|', 5)));
    END LOOP;
    got := _v104_try(format('select * from target_set(%L, ''technical'', ''againstPace'', 21, null, null, null)', SUBJ));
    PERFORM _assert(got = '23514', format('§82 (set): a target of 21 ended %s, not the CHECK', got));
    FOREACH k IN ARRAY ARRAY['assistant', 'director', 'manager', 'self', 'parent', 'wescoach', 'principal'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT t.ok, t.reason INTO v_ok, v_why FROM target_set(SUBJ, 'technical', 'againstPace', 13, NULL, NULL, NULL) t;
      PERFORM _assert(NOT v_ok AND v_why = 'not_permitted', format('§82 (set): the %s set a target (%s)', k, v_why));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    SELECT t.ok, t.reason, t.id INTO v_ok, v_why, T2 FROM target_set(SUBJ, 'technical', 'againstPace', 13, NULL, TD, NULL) t;
    PERFORM _assert(v_ok AND T2 <> T1 AND _v105_target(T1)->>'withdrawn_reason' = 'replaced'
                    AND _v105_target(T1)->>'withdrawn_by' = y->>'coach' AND _v105_target(T2)->>'withdrawn_at' IS NULL,
      format('§82 (set): the second target did not replace the first (%s)', v_why));
    PERFORM _assert((SELECT count(*) FROM development_target WHERE player_id = SUBJ AND metric = 'againstPace' AND withdrawn_at IS NULL) = 1
                    AND (SELECT count(*) FROM development_target WHERE player_id = SUBJ AND metric = 'againstPace') = 2,
      '§82 (set): not one open target and one struck on the metric');

    -- (withdraw) on a target of its own (footwork), so the loop's stands
    SELECT t.id INTO T1 FROM target_set(SUBJ, 'technical', 'footwork', 14, NULL, NULL, NULL) t;
    PERFORM _as((y->>'self')::uuid);
    SELECT w.ok, w.reason INTO v_ok, v_why FROM target_withdraw(T1, 'not mine to keep') w;
    PERFORM _assert(NOT v_ok AND v_why = 'not_permitted', '§82 (withdraw): the boy withdrew his own target');
    PERFORM _as((y->>'coach')::uuid);
    SELECT w.ok, w.reason INTO v_ok, v_why FROM target_withdraw(T1, '') w;
    PERFORM _assert(NOT v_ok AND v_why = 'reason_required', '§82 (withdraw): a target was withdrawn without a reason');
    SELECT w.ok, w.reason INTO v_ok, v_why FROM target_withdraw(T1, 'set it on the wrong attribute') w;
    PERFORM _assert(v_ok AND _v105_target(T1)->>'withdrawn_reason' = 'set it on the wrong attribute',
      format('§82 (withdraw): the coach could not withdraw his target (%s)', v_why));
    SELECT w.ok, w.reason INTO v_ok, v_why FROM target_withdraw(T1, 'again') w;
    PERFORM _assert(NOT v_ok AND v_why = 'already_withdrawn', '§82 (withdraw): a target was withdrawn twice');

    -- (readers)
    FOREACH k IN ARRAY ARRAY['coach', 'assistant', 'director', 'self'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM development_target WHERE player_id = SUBJ) = 3,
        format('§82 (readers): the %s does not read the boy''s three targets', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['principal', 'parent', 'manager', 'analyst', 'mate', 'othercoach', 'wescoach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM development_target WHERE player_id = SUBJ) = 0,
        format('§82 (readers): the %s reads the boy''s targets', k));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM development_target) = 0, '§82 (readers): an anonymous session reads a target');
    PERFORM _as((y->>'mate')::uuid);
    PERFORM _assert((SELECT count(*) FROM player WHERE id = SUBJ) = 1,
      '§82 (readers): the team-mate does not read the boy''s player row — his refusal above proves nothing');
    -- `targets`, as the API runs it: the reasoning's id to staff, not to the boy.
    PERFORM _as((y->>'coach')::uuid);
    SELECT c.id INTO T1 FROM coaching_point_write(SUBJ, NULL, 'gets across too early to the short ball',
                                                  jsonb_build_object('read', 'skills', 'params', jsonb_build_object('skillId', y->>'k10'))) c;
    SELECT t.id INTO T2 FROM target_set(SUBJ, 'technical', 'againstPace', 12, NULL, TD, T1) t;
    EXECUTE 'select count(*) from (' || Q_TARGETS || ') z where z.id = $2 and z.note_id = $3 and z.standing_score = 9 and z.from_score = 9'
      INTO n USING SUBJ, T2, T1;
    PERFORM _assert(n = 1, '§82 (readers): `targets` does not give the coach the reasoning''s id and the standing 9');
    PERFORM _as((y->>'self')::uuid);
    EXECUTE 'select count(*) from (' || Q_TARGETS || ') z where z.id = $2 and z.note_id is null and z.target_score = 12'
      INTO n USING SUBJ, T2;
    PERFORM _assert(n = 1, '§82 (readers): `targets` gives the boy the reasoning''s id, or not his target');

    -- (writes)
    PERFORM _as((y->>'coach')::uuid);
    FOREACH k IN ARRAY ARRAY[
        format('insert into development_target (player_id, school_id, category, metric, target_score, set_by) '
               'values (%L, %L, ''technical'', ''timing'', 15, app_user_id())', SUBJ, HIL),
        format('update development_target set target_score = 20 where player_id = %L', SUBJ),
        format('delete from development_target where player_id = %L', SUBJ)] LOOP
      got := _v104_try(k);
      PERFORM _assert(got = '42501', format('§82 (writes): a direct write on development_target ended %s: %s', got, left(k, 40)));
    END LOOP;

    -- (plan)
    PERFORM _as((y->>'manager')::uuid);
    INSERT INTO training_session_drill (session_id, drill_id, position) VALUES
      ((y->>'d8')::uuid, TD, 1), ((y->>'d6')::uuid, TD, 1), ((y->>'d6')::uuid, SP, 2), ((y->>'d2')::uuid, TD, 1),
      ((y->>'d12')::uuid, TD, 1), ((y->>'d3')::uuid, TD, 1);
    PERFORM _assert(_v104_try(format('insert into training_session_drill (session_id, drill_id, position) values (%L, %L, 1)',
                                     y->>'other', TD)) = '42501',
      '§82 (plan): the team manager planned U19F''s session, another side''s');
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO training_session_drill (session_id, drill_id, position) VALUES ((y->>'d2ahead')::uuid, SP, 1);
    PERFORM _assert(_v104_try(format('insert into training_session_drill (session_id, drill_id, position) values (%L, %L, 2)',
                                     y->>'d8', y->>'wesdrill')) = '23514',
      '§82 (plan): a Westville drill went on a Hilton plan');
    FOREACH k IN ARRAY ARRAY['coach', 'manager', 'self', 'parent', 'mate', 'analyst', 'director'] LOOP
      PERFORM _as((y->>k)::uuid);
      EXECUTE 'select count(*) from (' || Q_PLAN || ') z' INTO n USING (y->>'d6')::uuid;
      PERFORM _assert(n = 2, format('§82 (plan): the %s reads %s of the session''s two drills', k, n));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['othercoach', 'wescoach'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM training_session_drill WHERE session_id = (y->>'d6')::uuid) = 0,
        format('§82 (plan): the %s reads U19E''s plan', k));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert((SELECT count(*) FROM training_session_drill) = 0, '§82 (plan): an anonymous session reads a plan');
    FOREACH k IN ARRAY ARRAY['assistant', 'parent', 'self'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v104_try(format('insert into training_session_drill (session_id, drill_id, position) values (%L, %L, 3)', y->>'d6', y->>'throwdowns'));
      PERFORM _assert(got = '42501', format('§82 (plan): the %s wrote the plan (%s)', k, got));
    END LOOP;
    PERFORM _as((y->>'manager')::uuid);
    DELETE FROM training_session_drill WHERE session_id = (y->>'d2ahead')::uuid;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, '§82 (plan): the team manager could not replace a plan');

    -- (register)
    PERFORM _as((y->>'manager')::uuid);
    PERFORM _assert(_v104_try(format('insert into training_attendance (session_id, player_id, status) values (%L, %L, ''present'')',
                                     y->>'d12', SUBJ)) = 'ok',
      '§82 (register): the team manager could not mark the boy present');
    PERFORM _assert(_v104_try(format('insert into training_attendance (session_id, player_id, status) values (%L, %L, ''present'')',
                                     y->>'other', MATE)) = '42501',
      '§82 (register): the team manager took U19F''s register, another side''s');
    PERFORM _assert(_v104_try(format('insert into training_attendance (session_id, player_id, status) values (%L, %L, ''injured'')',
                                     y->>'d2', MATE)) = '42501',
      '§82 (register): `injured` was written by the application');
    PERFORM _assert(_v104_try(format('update training_attendance set status = ''injured'' where session_id = %L and player_id = %L',
                                     y->>'d12', SUBJ)) = '42501',
      '§82 (register): a row was changed to `injured` by the application');
    FOREACH k IN ARRAY ARRAY['parent', 'assistant'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(_v104_try(format('insert into training_attendance (session_id, player_id, status) values (%L, %L, ''present'')',
                                       y->>'d2', SUBJ)) = '42501',
        format('§82 (register): the %s wrote the register', k));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    EXECUTE 'select string_agg(z.status, '','') from (' || Q_ATT || ') z where z.player_id = $2' INTO got USING (y->>'d8')::uuid, MATE;
    PERFORM _assert(got = 'excused', format('§82 (register): the team-mate''s old `injured` row reads %s, not excused', coalesce(got, 'nothing')));
    EXECUTE 'select count(*) from (' || Q_ATT || ') z where z.status = ''injured''' INTO n USING NULL::uuid;
    PERFORM _assert(n = 0, '§82 (register): `training_attendance` returns the word `injured`');
    -- The row written at twelve days stays out of the panel below: before the look.

    -- (since)
    FOREACH k IN ARRAY ARRAY['coach', 'self'] LOOP
      PERFORM _as((y->>k)::uuid);
      EXECUTE 'select to_jsonb(z) from (' || Q_SINCE || ') z where z.discipline = ''batting'''
        INTO j USING SUBJ, BAT, '{}'::text[], '{}'::text[], '{}'::text[];
      PERFORM _assert((j->>'anchor')::date = current_date - 10 AND (j->>'sessions')::int = 4 AND (j->>'registered')::int = 3
                      AND (j->>'present')::int = 1 AND (j->>'late')::int = 1
                      AND j->'drills' = jsonb_build_array(jsonb_build_object('drillId', TD, 'name', 'Throw-downs', 'times', 3),
                                                          jsonb_build_object('drillId', SP, 'name', 'Short-pitch defence', 'times', 1))
                      AND jsonb_array_length(j->'targets') = 1
                      AND (j->'targets'->0->>'drillRan')::int = 3 AND (j->'targets'->0->>'drillAttended')::int = 2
                      AND (j->'targets'->0->>'target_score')::int = 12,
        format('§82 (since): the %s reads batting as %s', k, coalesce(j::text, 'no row')));
      PERFORM _assert(NOT (j ? 'absent') AND j::text NOT LIKE '%absent%' AND j::text NOT LIKE '%injured%',
        format('§82 (since): the %s''s panel says an absence or a health word', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['manager', 'parent', 'mate', 'principal'] LOOP
      PERFORM _as((y->>k)::uuid);
      EXECUTE 'select count(*) from (' || Q_SINCE || ') z' INTO n USING SUBJ, BAT, '{}'::text[], '{}'::text[], '{}'::text[];
      PERFORM _assert(n = 0, format('§82 (since): the %s reads %s rows of the boy''s panel', k, n));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    SELECT w.ok INTO v_ok FROM skill_withdraw((y->>'k10')::uuid, 'Verify 105: the look was another boy''s') w;
    UPDATE player_skill SET withdrawn_at = now(), withdrawn_reason = 'Verify 105: footwork too'
     WHERE player_id = SUBJ AND metric = 'footwork' AND assessed_on = current_date - 10;
    EXECUTE 'select to_jsonb(z) from (' || Q_SINCE || ') z where z.discipline = ''batting'''
      INTO j USING SUBJ, BAT, '{}'::text[], '{}'::text[], '{}'::text[];
    PERFORM _assert(v_ok AND (j->>'anchor')::date = current_date - 20 AND (j->>'sessions')::int = 5
                    AND (j->>'present')::int = 2,
      format('§82 (since): with the anchor withdrawn the window reads %s', coalesce(j::text, 'no row')));
    PERFORM _v105_joined(SUBJ, current_date - 5);
    EXECUTE 'select to_jsonb(z) from (' || Q_SINCE || ') z where z.discipline = ''batting'''
      INTO j USING SUBJ, BAT, '{}'::text[], '{}'::text[], '{}'::text[];
    PERFORM _assert((j->>'window_from')::date = current_date - 5 AND (j->>'sessions')::int = 2,
      format('§82 (since): the window does not start at the day he joined the side: %s', coalesce(j::text, 'no row')));

    -- (manager)
    PERFORM _as((y->>'manager')::uuid);
    PERFORM _assert(app_can('team.training.run', HIL, 'U19E', '00000000-0000-0000-0000-000000000000'::uuid,
                            '00000000-0000-0000-0000-000000000000'::uuid)
                    AND NOT app_can('team.manage', HIL, 'U19E', '00000000-0000-0000-0000-000000000000'::uuid,
                                    '00000000-0000-0000-0000-000000000000'::uuid),
      '§82 (manager): the team manager does not hold team.training.run without team.manage at his side');
    FOREACH k IN ARRAY ARRAY[
        format('insert into drill (school_id, name, category, duration_min) values (%L, ''Verify 105 manager drill'', ''batting'', 20)', HIL),
        format('insert into equipment (school_id, kind, label, quantity) values (%L, ''bat'', ''Verify 105 bats'', 4)', HIL),
        format('insert into training_session (school_id, team_code, title, starts_at, duration_min, session_type) '
               'values (%L, ''U19E'', ''Verify 105 manager nets'', now() + interval ''3 days'', 60, ''batting'')', HIL)] LOOP
      got := _v104_try(k);
      PERFORM _assert(got = '42501', format('§82 (manager): the team manager wrote what team.manage keeps (%s): %s', got, left(k, 40)));
    END LOOP;
    UPDATE training_session SET title = 'Verify 105 moved by the manager' WHERE id = (y->>'d2ahead')::uuid;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 0, '§82 (manager): the team manager rescheduled a session');

    -- (support)
    PERFORM _as((y->>'plat')::uuid);
    SELECT b.ok, b.reason, b.id INTO v_ok, v_why, SUP
      FROM support_access_begin(HIL, 'coach', 'Verify 105: ticket 1051 about the side', 'U19E', 30) b;
    PERFORM _assert(v_ok AND (SELECT count(*) FROM player WHERE id = SUBJ) = 1,
      format('§82 (support): the session was not begun, or reads no player row (%s)', v_why));
    PERFORM _assert((SELECT count(*) FROM development_target WHERE player_id = SUBJ) = 0,
      '§82 (support): a support session reads the boy''s targets');
    SELECT t.ok INTO v_ok FROM target_set(SUBJ, 'technical', 'timing', 15, NULL, NULL, NULL) t;
    PERFORM _assert(NOT v_ok, '§82 (support): a support session set a target');
    PERFORM support_access_end(SUP);
    PERFORM set_config('app.user_id', '', true);

    -- (doors)
    FOREACH k IN ARRAY ARRAY['target_set(uuid,text,text,integer,date,uuid,uuid)', 'target_withdraw(uuid,text)'] LOOP
      PERFORM _assert((SELECT prosecdef AND provolatile = 'v' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = to_regprocedure(k)),
        format('§82 (doors): %s is not a volatile SECURITY DEFINER with a pinned path', k));
      PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure(k), 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = to_regprocedure(k) AND a.grantee = 0 AND a.privilege_type = 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                         AND has_function_privilege(g.oid, to_regprocedure(k), 'EXECUTE')),
        format('§82 (doors): %s is not the application''s alone', k));
    END LOOP;
    PERFORM _assert(NOT has_table_privilege('scrbrd_app', 'development_target', 'INSERT')
                    AND NOT has_table_privilege('scrbrd_app', 'development_target', 'UPDATE')
                    AND NOT has_table_privilege('scrbrd_app', 'development_target', 'DELETE'),
      '§82 (doors): the application holds a write privilege on development_target');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'development_target'
                                  AND cmd <> 'SELECT' AND permissive = 'PERMISSIVE'),
      '§82 (doors): a permissive policy writes development_target');
    PERFORM _assert((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE'
                       AND (tablename, policyname) IN (('development_target', 'development_target_not_support'),
                                                       ('training_attendance', 'training_attendance_no_health_word'),
                                                       ('training_attendance', 'training_attendance_no_health_word_update'))) = 3,
      '§82 (doors): the three RESTRICTIVE policies are not all there');
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'training_session_drill_from_the_library' AND tgenabled = 'O')
                    AND NOT has_function_privilege('scrbrd_app', to_regprocedure('training_session_drill_library()'), 'EXECUTE'),
      '§82 (doors): the plan''s library trigger is missing, or the application may call it');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 82

  -- ┌── db/106 (section 83) ─────────────────────────────────────────────
  -- ── 83. REACH R-A: a family reads its side's fixtures, trips and training (db/106) ──
  -- docs/design/REACH_parent_pupil.md §6.1, REACH-D1 ("the side only", Kameel,
  -- 2026-10-14). Rows are _v106_stage()'s, invented. What each label holds:
  --   (reader)    each reader's whole set of the stage's fixtures (match),
  --               trips, training sessions, the toss/umpire/weather of f1, f2,
  --               f6 (each table alike) and fixture_publication rows, against
  --               the set the design gives him:
  --                 g1 (A's, one child): the 6XI's fixtures home and away and
  --                   nothing else; the away fixture's toss, umpire and weather
  --                   (new: home-only before); the 6XI's buses at Hilton, not
  --                   Westville's bus to f2, not the 8XI's (t6, whose notes
  --                   name B); the 6XI's nets
  --                 g2 (two schools): B's side at Hilton and W's at Westville
  --                   and nothing else at either; each school's bus at its
  --                   own end only
  --                 gup (UP plays up): f1 by the sheet and his own side's f3;
  --                   not the 6XI's next (f4) nor f5, from whose sheet UP was
  --                   withdrawn; f1's buses; his own side's nets only
  --                 upboy (UP himself, Kameel 2026-10-15): f1, the fixture
  --                   he is picked for, with its toss, umpire, weather and
  --                   buses, as his guardian reads it (db/106 (e)); his own
  --                   side's f3 and nets; not the 6XI's next (f4) or its bus
  --                   (t4), not f5, whose sheet he was withdrawn from
  --                 upmate (UP's team-mate, on no sheet): his side's f3 only;
  --                   UP's sheet gives him nothing
  --                 aboy (a pupil): his side's, home and away, as before
  --                 wesg (the away family): her side's two; Hilton's bus to
  --                   f1 never; f1's toss, umpire and weather (new)
  --                 gdriver (B's, and a driver): B's side; f1 only through
  --                   the trip he drives (db/41), and of f1's buses his own
  --                   alone (trip_fixture_driver_only now asks fixture_reach);
  --                   no bus to a fixture he cannot read (t3, t4), though his
  --                   driver's transport.read is school-wide (db/106 (d))
  --                 coach6, coach7, wescoach, spec (school-wide), spec6
  --                   (scoped to the 6XI), office: as before
  --                 g3 (ended), g4 (pending), g5 (revoked), a stranger, an
  --                   anonymous session: nothing
  --   (unchanged) every reader whose assignments name nobody reads the stage's
  --               fixtures, trips and training exactly as db/09 gave them
  --   (team-less) retired at the wave 3 integration: db/108 (§85) refuses
  --               the team-less `player` row this reader was, so it cannot
  --               be staged; §85 proves none is live and none can be written
  --   (spelling)  for every stage reader and fixture end, app_can() with NULL
  --               and with all-f answer alike (§5 item 2)
  --   (literal)   for every person holding an assignment and every staged or
  --               seed fixture, fixture_reach() under fixture.read and
  --               transport.read equals §2.5's text spelled out over every
  --               boy on the side and sheet, and side_reach() under
  --               team.read equals it on every side. Since db/117 (SR-2) the
  --               text is §2.10's, "the boy's side on the fixture's day",
  --               spelled with side_on() (_v117_lit_fixture, _v117_lit_side);
  --               db/106's spelling, the side now (_v106_lit_fixture), is
  --               kept and §94 (literal) asserts it answers apart for a
  --               moved boy's family (design §8.2)
  --   (agree)     §6.1 proof 1: for every person and every fixture with a
  --               ball, ball_event_read (db/100) admits exactly the fixtures
  --               match_read does, which (shape) holds to fixture_reach();
  --               for every guardian, the fixtures my_child_fixtures()
  --               returns are exactly match_read's; for every person and every plan's
  --               side, news_plan_reach() (db/96) is news.read and
  --               side_reach('team.read'); for every guardian and plan,
  --               db/101's reach (side or sheet) is news.read and
  --               fixture_end_reach('team.read') at the plan's end
  --   (shape)     db/106 asks the rule in a set-once shape (its header):
  --               for every person holding an assignment, match_read admits
  --               exactly the staged and scored fixtures fixture_reach()
  --               does (with db/41's driver's fixture), trip_read every trip
  --               fixture_end_reach() does at its own end (with db/41's two
  --               driver policies), training_session_read every session
  --               side_reach() does, match_toss_read every toss
  --   (text)      each re-created read asks the unnamed branch with all-f and
  --               the named branches through the helpers, never the all-zeros
  --               person; no pad table asks a helper; the eight helpers are
  --               stable definers for scrbrd_app alone
  --   (ended)     g1's own link ended mid-section: his next read is nothing
  --
  -- Cost (§5 item 11) is in db/106's header: on a forty-fixture season the
  -- fixture list costs a guardian of two 34 ms (db/09: 8.5), a coach 10
  -- (11), the director 8 (8); her trips 100 (47), a coach's 38 (51); the
  -- first build, which put the one-row helpers in the policies, cost every
  -- reader 350–500 ms.
  --
  -- Falsified five ways, each by putting the wrong definition in the database
  -- and running this section alone with each assertion made to report rather
  -- than raise (beside the seed only, so (agree)'s "proves nothing" guards
  -- report in every run, the control's too; nothing else did in the control):
  --   db/09's match_read (zeros): red at (reader) for g1 (f3, f6), g2 (f3,
  --     f4, f5, f8), gup, wesg (f8), gdriver; (shape) for every family
  --     reader; (text)
  --   side_reach() without the named boy (2): red at (reader) for every
  --     publication row a family reads (g1, g2, wesg, gdriver); (literal),
  --     (agree) (the log and my_child_fixtures() for every seed and staged
  --     guardian) and (shape) for every family reader
  --   my_fixture_ends() without the sheet (3): red at (reader) for gup (f1,
  --     t1, t1b and f1's toss, umpire, weather lost) and (shape) for him
  --   trip_read over both ends: red at (reader) for g1, g2, aboy, coach6,
  --     office, teamless (Westville's t2), wesg and wescoach (Hilton's t1,
  --     t1b, the Opener named in its notes), gdriver; (unchanged); (shape)
  --   db/41's trip_fixture_driver_only() (zeros): red at (reader) for gdriver
  --     (the other bus to f1, t1b)
  -- Kameel's 2026-10-15 branch for the boy himself (db/106 (e)), twice:
  --   the sheet's "not withdrawn" dropped: red at (reader) for upboy (f5,
  --     the sheet he was taken off), (shape) and (withdrawn)
  --   the sheet dropped (any fixture at his school): red at (reader) for
  --     upboy (f4, f5, f6, t4, t6), upmate (f1, f4–f6: a team-mate gains the
  --     whole school) and aboy; (agree), (shape), (withdrawn)
  -- And a sixth, found by the whole file rather than made: trip_read without
  -- db/106 (d)'s "and reads its fixture" went red at db/39's section (a school-wide
  -- driver read two trips he was not driving) and here at gdriver (t3, t4).
  DECLARE
    z    jsonb := _v106_stage();
    FX   uuid[];
    TX   uuid[];
    SX   uuid[];
    want jsonb;
    ZERO uuid := '00000000-0000-0000-0000-000000000000';
    ALLF uuid := 'ffffffff-ffff-ffff-ffff-ffffffffffff';
    ppl  uuid[];
    k    text;
    g    text;
    e    text;
    u    uuid;
    f    uuid;
    n    int;
    bad  text;
    rr   record;
  BEGIN
    FX := ARRAY[(z->>'f1')::uuid, (z->>'f2')::uuid, (z->>'f3')::uuid, (z->>'f4')::uuid,
                (z->>'f5')::uuid, (z->>'f6')::uuid, (z->>'f7')::uuid, (z->>'f8')::uuid];
    TX := ARRAY[(z->>'t1')::uuid, (z->>'t1b')::uuid, (z->>'t2')::uuid, (z->>'t3')::uuid,
                (z->>'t4')::uuid, (z->>'t6')::uuid, (z->>'t8')::uuid];
    SX := ARRAY[(z->>'s6')::uuid, (z->>'s7')::uuid, (z->>'s8')::uuid, (z->>'sw')::uuid];
    ppl := _v106_people();

    -- (reader): m fixtures · t trips · s training · x toss/umpire/weather · p publication
    want := '{
      "g1":       {"m": "f1 f2 f4 f5",       "t": "t1 t1b t4",       "s": "s6",       "x": "f1 f2",    "p": "f1-home"},
      "g2":       {"m": "f1 f2 f6",          "t": "t2 t6",           "s": "s8 sw",    "x": "f1 f2 f6", "p": "f1-away f6-home"},
      "gup":      {"m": "f1 f3",             "t": "t1 t1b t3",       "s": "s7",       "x": "f1",       "p": ""},
      "upboy":    {"m": "f1 f3",             "t": "t1 t1b t3",       "s": "s7",       "x": "f1",       "p": ""},
      "upmate":   {"m": "f3",                "t": "t3",              "s": "s7",       "x": "",         "p": ""},
      "aboy":     {"m": "f1 f2 f4 f5",       "t": "t1 t1b t4",       "s": "s6",       "x": "f1 f2",    "p": "f1-home"},
      "wesg":     {"m": "f1 f2",             "t": "t2",              "s": "sw",       "x": "f1 f2",    "p": "f1-away"},
      "gdriver":  {"m": "f1 f6",             "t": "t1 t6",           "s": "s8",       "x": "f6",       "p": "f6-home"},
      "coach6":   {"m": "f1 f2 f4 f5",       "t": "t1 t1b t4",       "s": "s6",       "x": "f1 f2",    "p": "f1-home"},
      "coach7":   {"m": "f3",                "t": "t3",              "s": "s7",       "x": "",         "p": ""},
      "wescoach": {"m": "f1 f2",             "t": "t2",              "s": "sw",       "x": "f1 f2",    "p": "f1-away"},
      "spec":     {"m": "f1 f2 f3 f4 f5 f6", "t": "",                "s": "",         "x": "f1 f2 f6", "p": "f1-home f6-home"},
      "spec6":    {"m": "f1 f2 f4 f5",       "t": "",                "s": "",         "x": "f1 f2",    "p": "f1-home"},
      "office":   {"m": "f1 f2 f3 f4 f5 f6", "t": "t1 t1b t3 t4 t6", "s": "s6 s7 s8", "x": "f1 f2 f6", "p": "f1-home f6-home"},
      "g3":       {"m": "", "t": "", "s": "", "x": "", "p": ""},
      "g4":       {"m": "", "t": "", "s": "", "x": "", "p": ""},
      "g5":       {"m": "", "t": "", "s": "", "x": "", "p": ""},
      "stranger": {"m": "", "t": "", "s": "", "x": "", "p": ""},
      "anon":     {"m": "", "t": "", "s": "", "x": "", "p": ""}}'::jsonb;
    FOR k IN SELECT jsonb_object_keys(want) LOOP
      IF k = 'anon' THEN PERFORM set_config('app.user_id', '', true); ELSE PERFORM _as((z->>k)::uuid); END IF;
      g := concat_ws(' | ',
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, id) l FROM match WHERE id = ANY (FX)) x),
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, id) l FROM trip WHERE id = ANY (TX)) x),
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, id) l FROM training_session WHERE id = ANY (SX)) x),
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, match_id) l FROM match_toss WHERE match_id = ANY (FX)) x),
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, match_id) l FROM match_official WHERE match_id = ANY (FX)) x),
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, match_id) l FROM match_weather WHERE match_id = ANY (FX)) x),
        (SELECT coalesce(string_agg(l, ' ' ORDER BY l), '') FROM (SELECT _v106_label(z, match_id) || '-' || side l FROM fixture_publication WHERE match_id = ANY (FX)) x));
      e := concat_ws(' | ', want->k->>'m', want->k->>'t', want->k->>'s', want->k->>'x', want->k->>'x', want->k->>'x', want->k->>'p');
      PERFORM _assert(g = e, format('§83 (reader): the %s reads [%s], the design gives [%s] (fixtures | trips | training | toss | umpire | weather | publication)', k, g, e));
    END LOOP;

    -- (both): a mother of two boys on two sides keeps both boys. REACH-D1
    -- narrows the rows about a SIDE, never her children: g2 reads B's and W's
    -- own player rows and no other boy's of the stage, and each boy's own
    -- side's fixture without the other's sheet (f6, B's 8XI at Hilton; f2,
    -- W's 6XI at Westville, which names neither). The browser walk's
    -- two-school guardian (Sarah, §49 (own)) is the same case on the seed.
    PERFORM _as((z->>'g2')::uuid);
    SELECT string_agg(l, ' ' ORDER BY l) INTO bad
      FROM (SELECT CASE p.id WHEN (z->>'a')::uuid THEN 'A' WHEN (z->>'up')::uuid THEN 'UP' WHEN (z->>'b')::uuid THEN 'B'
                             WHEN (z->>'w')::uuid THEN 'W' WHEN (z->>'e')::uuid THEN 'E' WHEN (z->>'n')::uuid THEN 'N'
                             WHEN (z->>'m')::uuid THEN 'M' END l
              FROM player p
             WHERE p.id IN ((z->>'a')::uuid, (z->>'up')::uuid, (z->>'b')::uuid, (z->>'w')::uuid,
                            (z->>'e')::uuid, (z->>'n')::uuid, (z->>'m')::uuid)) x;
    PERFORM _assert(bad IS NOT DISTINCT FROM 'B W',
      format('§83 (both): the guardian of two boys on two sides reads the stage''s boys [%s], not [B W]', coalesce(bad, '')));
    PERFORM _assert((SELECT count(*) FROM match WHERE id IN ((z->>'f6')::uuid, (z->>'f2')::uuid)) = 2,
      '§83 (both): the guardian of two boys on two sides lost one boy''s own side''s fixture');

    -- (unchanged): every reader naming nobody, exactly as db/09 gave
    FOREACH k IN ARRAY ARRAY['coach6', 'coach7', 'wescoach', 'spec', 'spec6', 'office'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert(
        (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM match WHERE id = ANY (FX))
          = (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(FX) x WHERE _v106_old_match(x))
        AND (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM trip WHERE id = ANY (TX))
          = (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(TX) x WHERE _v106_old_trip(x))
        AND (SELECT coalesce(array_agg(id ORDER BY id), '{}') FROM training_session WHERE id = ANY (SX))
          = (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(SX) x WHERE _v106_old_training(x)),
        format('§83 (unchanged): the %s reads a fixture, trip or session other than db/09 gave', k));
    END LOOP;

    -- (team-less): retired at the wave 3 integration. The reader it asked
    -- about, a live `player` row with no team, is refused by db/108's CHECK;
    -- §85 (check) and (seed) are the proof now.

    -- (spelling): NULL and all-f answer alike, at both ends of each fixture
    FOR k IN SELECT jsonb_object_keys(want) LOOP
      IF k = 'anon' THEN CONTINUE; END IF;
      PERFORM _as((z->>k)::uuid);
      SELECT string_agg(format('%s/%s', _v106_label(z, x.f), x.cap), ' ') INTO bad
        FROM (SELECT f0 AS f, c.cap FROM unnest(FX) f0, (VALUES ('fixture.read'), ('transport.read'), ('team.read')) c(cap)) x
       WHERE NOT _v106_spelling(x.cap, x.f);
      PERFORM _assert(bad IS NULL, format('§83 (spelling): as the %s, NULL and all-f answer apart at %s', k, bad));
    END LOOP;

    -- (literal): the build is §2.5's text, for everyone, everywhere staged or scored
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      SELECT string_agg(format('%s/%s', x.f, x.cap), ' ') INTO bad
        FROM (SELECT f0 AS f, c.cap FROM unnest(FX || _v106_seed_matches()) f0, (VALUES ('fixture.read'), ('transport.read')) c(cap)) x
       WHERE fixture_reach(x.cap, x.f) IS DISTINCT FROM _v117_lit_fixture(x.cap, x.f);
      PERFORM _assert(bad IS NULL, format('§83 (literal): for %s fixture_reach() and §2.5''s text answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(format('%s/%s', s.school, s.team), ' ') INTO bad
        FROM _v106_sides() s
       WHERE side_reach('team.read', s.school, s.team, ZERO) IS DISTINCT FROM _v117_lit_side('team.read', s.school, s.team, ZERO, sa_today());
      PERFORM _assert(bad IS NULL, format('§83 (literal): for %s side_reach() and §2.5''s text answer apart at %s', u, left(bad, 300)));
    END LOOP;

    -- (agree) 1: db/100's log. For every person, the fixtures whose balls he
    -- reads are exactly the scored fixtures match_read shows him (bar the
    -- fixture a driver reads only as its driver, which shows no ball). Since
    -- db/112 that includes the one a boy playing up reads only as the boy on
    -- its sheet, db/106 (e): he reads its balls too (§89). (shape) below holds
    -- match_read to fixture_reach() on every one of them.
    n := 0;
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      SELECT string_agg(x::text, ' ') INTO bad
        FROM ((SELECT DISTINCT b.match_id FROM ball_event b)
              EXCEPT (SELECT m.id FROM match m WHERE m.id = ANY (_v106_ball_matches())
                       AND NOT trip_fixture_driver_only(m.id))) d(x);
      PERFORM _assert(bad IS NULL, format('§83 (agree): %s reads the balls of %s, which match_read does not give him', u, left(bad, 300)));
      SELECT string_agg(x::text, ' ') INTO bad
        FROM ((SELECT m.id FROM match m WHERE m.id = ANY (_v106_ball_matches())
                AND NOT trip_fixture_driver_only(m.id))
              EXCEPT (SELECT DISTINCT b.match_id FROM ball_event b)) d(x);
      PERFORM _assert(bad IS NULL, format('§83 (agree): %s reads %s through match_read and none of its balls', u, left(bad, 300)));
      n := n + (SELECT count(DISTINCT b.match_id) FROM ball_event b);
    END LOOP;
    PERFORM _assert(n > 0 AND cardinality(_v106_ball_matches()) > 1 AND cardinality(ppl) > 20,
      format('§83 (agree): the log comparison ran over %s people, %s fixtures and %s reads: it proves nothing',
             cardinality(ppl), cardinality(_v106_ball_matches()), n));
    -- (agree) 2: db/100's helper, for every guardian
    n := 0;
    FOREACH u IN ARRAY _v106_guardians_only() LOOP
      PERFORM _as(u);
      PERFORM _assert(
        (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(my_child_fixtures()) x)
          = (SELECT coalesce(array_agg(m.id ORDER BY m.id), '{}') FROM match m),
        format('§83 (agree): for the guardian %s my_child_fixtures() and match_read give different fixtures', u));
      n := n + cardinality(my_child_fixtures());
    END LOOP;
    PERFORM _assert(n > 10, format('§83 (agree): the guardians'' fixtures number %s: it proves nothing', n));
    -- (agree) 3: db/96's side, for everyone; db/101's sheet, for every guardian
    PERFORM _assert((SELECT count(*) FROM _v106_plans()) > 0, '§83 (agree): no plan is staged to compare');
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      SELECT string_agg(format('%s/%s', p.school, p.team), ' ') INTO bad
        FROM _v106_plans() p
       WHERE news_plan_reach(p.school, p.team) IS DISTINCT FROM
             (app_can('news.read', p.school, p.team, ZERO, ZERO) AND side_reach('team.read', p.school, p.team, ZERO));
      PERFORM _assert(bad IS NULL, format('§83 (agree): for %s news_plan_reach() and side_reach() answer apart at %s', u, bad));
    END LOOP;
    n := 0;
    FOREACH u IN ARRAY _v106_guardians_only() LOOP
      PERFORM _as(u);
      SELECT string_agg(format('%s/%s', p.school, p.team), ' ') INTO bad
        FROM _v106_plans() p
       -- since db/117 the side on the plan's day (its fixture's), as
       -- news_post_plan_side and news_post_team_side ask it
       WHERE (news_plan_reach(p.school, p.team, side_day(p.fixture)) OR news_sheet_reach(p.fixture, p.school, p.team)) IS DISTINCT FROM
             (app_can('news.read', p.school, p.team, ZERO, ZERO) AND fixture_end_reach('team.read', p.fixture, p.school, p.team));
      PERFORM _assert(bad IS NULL, format('§83 (agree): for the guardian %s db/101''s plan reach and fixture_end_reach() answer apart at %s', u, bad));
      n := n + (SELECT count(*) FROM _v106_plans() p
                 WHERE news_sheet_reach(p.fixture, p.school, p.team) AND NOT news_plan_reach(p.school, p.team, side_day(p.fixture)));
    END LOOP;
    PERFORM _assert(n > 0, '§83 (agree): no guardian reaches a plan by the sheet alone: the sheet comparison proves nothing');

    -- (shape): each policy admits exactly the rows the one-row question
    -- admits, for every person, on every row of the table (db/106 header,
    -- THE SHAPE). match also opens to the driver of a trip to it (db/41);
    -- trip is narrowed for a driver by db/41's restrictive policy.
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      SELECT string_agg(_v106_label(z, x) || '?' || x::text, ' ') INTO bad
        FROM unnest(FX || _v106_ball_matches()) x
       WHERE EXISTS (SELECT 1 FROM match m WHERE m.id = x)
             IS DISTINCT FROM (fixture_reach('fixture.read', x) OR x IN (SELECT trip_driven_matches()));
      PERFORM _assert(bad IS NULL, format('§83 (shape): for %s match_read and fixture_reach() answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, t.id), t.id::text), ' ') INTO bad
        FROM _v106_trips() t
       WHERE EXISTS (SELECT 1 FROM trip v WHERE v.id = t.id)
             IS DISTINCT FROM (((fixture_end_reach('transport.read', t.match_id, t.school_id, t.team_code)
                                 AND (fixture_reach('fixture.read', t.match_id) OR t.match_id IN (SELECT trip_driven_matches())))
                                OR (coalesce(t.driver_id = app_user_id(), false)
                                    AND app_can('transport.read', t.school_id, t.team_code, ZERO, t.match_id)))
                               AND (coalesce(t.driver_id = app_user_id(), false) OR NOT trip_fixture_driver_only(t.match_id)));
      PERFORM _assert(bad IS NULL, format('§83 (shape): for %s trip_read and fixture_end_reach() answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, t.id), t.id::text), ' ') INTO bad
        FROM _v117_sessions() t   -- since db/117, on the session's own day
       WHERE EXISTS (SELECT 1 FROM training_session v WHERE v.id = t.id)
             IS DISTINCT FROM side_reach_on('team.read', t.school_id, t.team_code, ZERO, t.day);
      PERFORM _assert(bad IS NULL, format('§83 (shape): for %s training_session_read and side_reach() answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, x), x::text), ' ') INTO bad
        FROM unnest(_v106_toss_matches()) x
       WHERE EXISTS (SELECT 1 FROM match_toss v WHERE v.match_id = x)
             IS DISTINCT FROM fixture_reach('fixture.read', x);
      PERFORM _assert(bad IS NULL, format('§83 (shape): for %s match_toss_read and fixture_reach() answer apart at %s', u, left(bad, 300)));
    END LOOP;
    PERFORM _assert(cardinality(_v106_toss_matches()) >= 3 AND (SELECT count(*) FROM _v106_trips()) >= 7
                    AND (SELECT count(*) FROM _v106_sessions()) >= 4,
      '§83 (shape): too few rows to compare: it proves nothing');

    -- (text): each re-created read asks the unnamed branch with all-f and
    -- the named branches through the helpers, never the all-zeros person
    -- (training's fixture argument, "no fixture", aside)
    SELECT string_agg(x.tbl || '.' || x.pol, ' ') INTO bad
      FROM (VALUES
        ('match', 'match_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_toss', 'match_toss_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_broadcast', 'match_broadcast_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('drs_review', 'drs_review_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_official', 'match_official_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_pitch_report', 'match_pitch_report_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_weather', 'match_weather_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_conditions', 'match_conditions_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_condition_override', 'match_condition_override_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('match_result_decision', 'match_result_decision_read', 'my_fixture_ends(''fixture.read''::text)'),
        ('fixture_publication', 'fixture_publication_read', 'side_reach(''fixture.read''::text, school_id, team_code, match_id)'),
        ('trip', 'trip_read', 'my_fixture_ends(''transport.read''::text)'),
        ('training_session', 'training_session_read', 'my_sides(''team.read''::text)')
      ) x(tbl, pol, q)
     WHERE NOT EXISTS (SELECT 1 FROM pg_policy p
                        WHERE p.polrelid = to_regclass(x.tbl) AND p.polname = x.pol AND p.polcmd = 'r' AND p.polpermissive
                          AND position(x.q IN pg_get_expr(p.polqual, p.polrelid)) > 0
                          AND replace(pg_get_expr(p.polqual, p.polrelid),
                                      '''ffffffff-ffff-ffff-ffff-ffffffffffff''::uuid, ''00000000-0000-0000-0000-000000000000''::uuid)', '')
                              NOT LIKE '%00000000-0000-0000-0000-000000000000%');
    PERFORM _assert(bad IS NULL, format('§83 (text): %s is not the policy db/106 wrote', bad));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_policy p
                                 WHERE p.polrelid IN (to_regclass('scoring_session'), to_regclass('ball_event_quarantine'),
                                                      to_regclass('scoring_audit'))
                                   AND concat(pg_get_expr(p.polqual, p.polrelid), pg_get_expr(p.polwithcheck, p.polrelid))
                                       ~ '(side_reach|fixture_reach|fixture_end_reach|my_fixture_ends|my_sides)\('),
      '§83 (text): a pad table''s policy asks a reach helper');
    PERFORM _assert((SELECT bool_and(p.prosecdef AND p.provolatile = 's'
                                     AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(p.proconfig, '{}'))
                                     AND has_function_privilege('scrbrd_app', p.oid, 'EXECUTE')
                                     AND NOT has_function_privilege('public', p.oid, 'EXECUTE'))
                       FROM pg_proc p
                      WHERE p.oid IN (to_regprocedure('side_reach(text,uuid,text,uuid)'),
                                      to_regprocedure('fixture_end_reach(text,uuid,uuid,text)'),
                                      to_regprocedure('fixture_reach(text,uuid)'), to_regprocedure('my_fixture_ends(text)'),
                                      to_regprocedure('my_sides(text)'), to_regprocedure('match_away_school(uuid)'),
                                      to_regprocedure('match_away_team(uuid)'), to_regprocedure('my_own_boy()')))
                    AND (SELECT count(*) FROM pg_proc p
                          WHERE p.oid IN (to_regprocedure('side_reach(text,uuid,text,uuid)'),
                                          to_regprocedure('fixture_end_reach(text,uuid,uuid,text)'),
                                          to_regprocedure('fixture_reach(text,uuid)'), to_regprocedure('my_fixture_ends(text)'),
                                          to_regprocedure('my_sides(text)'), to_regprocedure('match_away_school(uuid)'),
                                          to_regprocedure('match_away_team(uuid)'), to_regprocedure('my_own_boy()'))) = 8,
      '§83 (text): a reach helper is missing, not a stable definer with a pinned path, or not scrbrd_app''s alone');

    -- (withdrawn): taken off f1's sheet, UP reads nothing of it, nor does
    -- his guardian; f5, which he was withdrawn from at the start, was never
    -- his (the (reader) sets above)
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v106_withdraw((z->>'f1')::uuid, (z->>'up')::uuid) = 1, '§83 (withdrawn): UP was not on f1''s sheet to take off');
    FOREACH k IN ARRAY ARRAY['upboy', 'gup'] LOOP
      PERFORM _as((z->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM match WHERE id IN ((z->>'f1')::uuid, (z->>'f5')::uuid)) = 0
                      AND (SELECT count(*) FROM trip WHERE match_id = (z->>'f1')::uuid) = 0
                      AND (SELECT count(*) FROM match_toss WHERE match_id = (z->>'f1')::uuid) = 0
                      AND (SELECT count(*) FROM match WHERE id = (z->>'f3')::uuid) = 1,
        format('§83 (withdrawn): the %s still reads f1 (or f5), its bus or its toss after UP was withdrawn, or lost his own side''s f3', k));
    END LOOP;

    -- (ended), last: g1's own link ends, and his next read has nothing
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v100_end_link((z->>'g1')::uuid, (z->>'a')::uuid);
    PERFORM _as((z->>'g1')::uuid);
    PERFORM _assert((SELECT count(*) FROM match WHERE id = ANY (FX)) = 0
                    AND (SELECT count(*) FROM trip WHERE id = ANY (TX)) = 0
                    AND (SELECT count(*) FROM training_session WHERE id = ANY (SX)) = 0
                    AND (SELECT count(*) FROM match_toss WHERE match_id = ANY (FX)) = 0,
      '§83 (ended): A''s guardian reads a fixture, trip, session or toss after his link ended');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 83


  -- ┌── section 84: the officials register and the grant notes, closed (db/107) ──
  -- REACH-D5 (Kameel, 14 Oct 2026): `official` held ID numbers, dates of
  -- birth, emails and phones — a pupil who scores among them — and every
  -- enrolled person read it raw. And feature_grant's note, the platform's
  -- words about one school's plan, reached every school. The API walks are
  -- tools/smoke-register.mjs, tools/smoke-officials.mjs (the appoint route)
  -- and tools/smoke-modules.mjs ("A school's plan is its own").
  --
  -- What each label holds:
  --   (closed)   a pupil, a parent, a coach, the principal, the office,
  --              Westville's office and a Westville parent read no row of
  --              `official`, `official_accreditation` or `official_masked`;
  --              the register's query (read-api.mjs, verbatim) gives each of
  --              them every official by name, with born, id_number, email
  --              and phone NULL on every row — the pupil-scorer's included
  --   (keeper)   the register's keeper (a competition administrator) and the
  --              platform read every row raw, and the register query gives
  --              them the ID number and the date of birth
  --   (own)      the pupil who scores reads his own row and grade, raw, and
  --              nobody else's; the register gives him his own date of birth
  --              and no other
  --   (panel)    the panel's grade, accreditations and account flag; nothing
  --              to an account enrolled nowhere, nothing to a pad credential
  --   (appoint)  the appoint route's query (events-api.mjs, verbatim) as the
  --              principal, the coach and Westville's office: the conflict
  --              flag equals what the route's own query answered before
  --              db/107, reader by reader (_v107_conflict_before)
  --   (grant)    Hilton's people read Hilton's grant row and its note and not
  --              Westville's; Westville's the reverse; the platform both;
  --              module_settings (verbatim) gives another school's
  --              school_granted and grant_note NULL; the account enrolled
  --              nowhere reads none
  --   (resolve)  the module still resolves for everybody as before: on at
  --              Hilton (granted), off at Westville (revoked), through the
  --              definers, whoever asks
  --   (writes)   the keeper adds an official and an accreditation and retires
  --              one (INSERT/UPDATE … RETURNING, as officials-register-api
  --              does); the platform writes a grant row with ON CONFLICT, as
  --              scouting-api does
  --   (doors)    the three policies' text, one permissive read each; the
  --              panel's column list against the never-list; the three
  --              functions stable definers for scrbrd_app alone
  --
  -- Falsified, each change made in the database as the owner before this
  -- file ran (and undone after), red at its own label:
  --   official_read put back to app_enrolled()          → (closed) red: the
  --                                                        pupil reads a raw row
  --   official_panel()'s gate made `true`               → (panel) red: a pad
  --                                                        credential reads the
  --                                                        panel (8 rows)
  --   feature_grant_read put back to app_enrolled()     → (grant) red: a Hilton
  --                                                        pupil reads Westville's
  --                                                        note
  --   official_conflict() without the caller's
  --   role_assignment_read predicate                    → (appoint) red: the
  --                                                        coach is told of a
  --                                                        conflict he could not
  --                                                        see before
  DECLARE
    y        jsonb := _v107_stage();
    HIL      uuid := '11111111-1111-1111-1111-111111111111';
    WES      uuid := '22222222-2222-2222-2222-222222222222';
    U_PLAT   uuid := '88888888-0000-0000-0000-000000000014';
    U1       uuid := (y->>'u1')::uuid;
    S1       uuid := (y->>'s1')::uuid;
    C1       uuid := (y->>'c1')::uuid;
    M        uuid := (y->>'m')::uuid;
    N_ALL    int  := (y->>'n_officials')::int;
    k        text;
    got      text;
    n        int;
    n2       int;
    v_new    uuid;
    v_other  uuid;
  BEGIN
    -- (closed)
    FOREACH k IN ARRAY ARRAY['pupil', 'parent', 'coach', 'principal', 'office', 'wesoffice', 'wesparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(app_enrolled(), format('§84 (closed): the %s is not enrolled, so this proves nothing', k));
      SELECT (SELECT count(*) FROM official) + (SELECT count(*) FROM official_accreditation)
             + (SELECT count(*) FROM official_masked) INTO n;
      PERFORM _assert(n = 0, format('§84 (closed): the %s reads %s rows of the officials register, raw or masked', k, n));
      -- official_register, as services/api/read/read-api.mjs runs it.
      SELECT count(*), count(*) FILTER (WHERE q.born IS NOT NULL OR q.id_number IS NOT NULL
                                            OR q.email IS NOT NULL OR q.phone IS NOT NULL)
        INTO n, n2
        FROM (select o.id, o.full_name, o.panel, o.active,
                     r.born, r.id_number, r.email, r.phone,
                     o.level, o.accredited_until, o.accreditations
                from official_panel() o
                left join official r on r.id = o.id
               order by o.full_name, o.id) q;
      PERFORM _assert(n = N_ALL AND n2 = 0,
        format('§84 (closed): the register gives the %s %s of %s officials, %s with a date of birth, ID number or contact', k, n, N_ALL, n2));
      PERFORM _assert((SELECT string_agg(q.full_name, ',' ORDER BY q.full_name) FROM official_panel() q WHERE q.id IN (U1, S1, C1))
                      = 'Verify OneOhSeven Linked Umpire,Verify OneOhSeven Scorer,Verify OneOhSeven Umpire',
        format('§84 (closed): the %s does not read the panel by name', k));
    END LOOP;

    -- (keeper)
    FOREACH k IN ARRAY ARRAY['keeper', 'platform'] LOOP
      PERFORM _as(CASE WHEN k = 'platform' THEN U_PLAT ELSE (y->>k)::uuid END);
      SELECT count(*) INTO n FROM official;
      PERFORM _assert(n = N_ALL, format('§84 (keeper): the %s reads %s of %s officials raw', k, n, N_ALL));
      SELECT q.id_number || '|' || q.born INTO got
        FROM (select o.id, r.born, r.id_number
                from official_panel() o left join official r on r.id = o.id) q WHERE q.id = U1;
      PERFORM _assert(got = '8001015000080|1980-01-01', format('§84 (keeper): the register gives the %s %s for the umpire', k, coalesce(got, 'nothing')));
      PERFORM _assert((SELECT count(*) FROM official_accreditation WHERE official_id IN (U1, S1)) = 2,
        format('§84 (keeper): the %s does not read the accreditations', k));
    END LOOP;

    -- (own)
    PERFORM _as((y->>'scorer')::uuid);
    SELECT string_agg(o.full_name, ',') INTO got FROM official o;
    PERFORM _assert(got = 'Verify OneOhSeven Scorer', format('§84 (own): the pupil who scores reads %s raw, not his own row alone', coalesce(got, 'nothing')));
    SELECT string_agg(a.level, ',') INTO got FROM official_accreditation a;
    PERFORM _assert(got = 'club', format('§84 (own): the pupil who scores reads accreditations %s, not his own alone', coalesce(got, 'none')));
    SELECT count(*) FILTER (WHERE q.born IS NOT NULL), count(*) FILTER (WHERE q.id = S1 AND q.id_number IS NOT NULL)
      INTO n, n2
      FROM (select o.id, r.born, r.id_number from official_panel() o left join official r on r.id = o.id) q;
    PERFORM _assert(n = 1 AND n2 = 1, format('§84 (own): the register gives the pupil who scores %s dates of birth (his own: %s)', n, n2));

    -- (panel)
    PERFORM _as((y->>'pupil')::uuid);
    SELECT string_agg(format('%s:%s:%s:%s', p.panel, coalesce(p.level, '-'), p.accreditations, p.linked), ',' ORDER BY p.full_name) INTO got
      FROM official_panel() p WHERE p.id IN (U1, S1, C1);
    PERFORM _assert(got = 'V107 Umpires:-:0:t,V107 Scorers:club:1:t,V107 Umpires:level1:1:f',
      format('§84 (panel): the pupil reads the panel as %s', coalesce(got, 'nothing')));
    PERFORM _assert((SELECT count(*) FROM official_panel(U1)) = 1 AND (SELECT count(*) FROM official_panel(gen_random_uuid())) = 0,
      '§84 (panel): the panel asked for one official does not answer one row, or answers for an id that is none');
    PERFORM set_config('app.scope', 'pad', true);
    SELECT count(*) INTO n FROM official_panel();
    n2 := CASE WHEN official_conflict(C1, M) IS NULL THEN 0 ELSE 1 END;
    PERFORM set_config('app.scope', '', true);
    PERFORM _assert(n = 0 AND n2 = 0, format('§84 (panel): a pad credential reads %s panel rows, or the conflict flag', n));
    PERFORM _as((y->>'drifter')::uuid);
    PERFORM _assert(NOT app_enrolled(), '§84 (panel): the drifter is enrolled, so this proves nothing');
    PERFORM _assert((SELECT count(*) FROM official_panel()) = 0 AND official_conflict(C1, M) IS NULL,
      '§84 (panel): an account enrolled nowhere reads the panel, or the conflict flag');

    -- (appoint)
    FOREACH k IN ARRAY ARRAY['principal', 'coach', 'wesoffice'] LOOP
      PERFORM _as((y->>k)::uuid);
      -- The appoint route's query, as services/api/write/events-api.mjs runs
      -- it ($1 the official, $2 the match).
      SELECT format('%s:%s:%s', q.full_name, q.linked, q.conflict) INTO got
        FROM (select o.id, o.full_name, o.panel, o.active, o.level, o.accreditations, o.linked,
                     official_conflict(o.id, M) as conflict
                from official_panel(C1) o) q;
      PERFORM _assert(got = format('Verify OneOhSeven Linked Umpire:t:%s', _v107_conflict_before((y->>'linked')::uuid, M)),
        format('§84 (appoint): the %s is answered %s for the linked umpire; before db/107 the conflict was %s',
               k, coalesce(got, 'nothing'), _v107_conflict_before((y->>'linked')::uuid, M)));
      SELECT format('%s:%s:%s', q.full_name, q.linked, q.conflict) INTO got
        FROM (select o.id, o.full_name, o.panel, o.active, o.level, o.accreditations, o.linked,
                     official_conflict(o.id, M) as conflict
                from official_panel(U1) o) q;
      PERFORM _assert(got = 'Verify OneOhSeven Umpire:f:f',
        format('§84 (appoint): the unlinked umpire reads to the %s as %s', k, coalesce(got, 'nothing')));
    END LOOP;
    -- The values themselves, so the agreement above is not two NULLs agreeing.
    PERFORM _as((y->>'principal')::uuid);
    PERFORM _assert(official_conflict(C1, M), '§84 (appoint): the principal is not told the linked umpire holds a role at Hilton');
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert(NOT official_conflict(C1, M), '§84 (appoint): the coach is told of a role he cannot read');

    -- (grant)
    FOREACH k IN ARRAY ARRAY['pupil', 'parent', 'coach', 'principal', 'office', 'wesoffice', 'wesparent'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT string_agg(CASE WHEN g.school_id = HIL THEN 'hil' ELSE 'wes' END || ':' || g.note, ',') INTO got
        FROM feature_grant g WHERE g.key = 'opposition';
      PERFORM _assert(got = CASE WHEN k LIKE 'wes%' THEN 'wes:v107: Westville plan note' ELSE 'hil:v107: Hilton plan note' END,
        format('§84 (grant): the %s reads the opposition grants as %s', k, coalesce(got, 'nothing')));
      -- module_settings, as services/api/read/read-api.mjs runs it, asked
      -- about the OTHER school.
      v_other := CASE WHEN k LIKE 'wes%' THEN HIL ELSE WES END;
      SELECT format('%s|%s|%s', m.school_granted, m.grant_note, m.resolved) INTO got
        FROM (select f.key, f.kind, f.label, f.enabled as platform_default,
                     f.locked, f.reason, f.changed_at,
                     g.granted as school_granted, g.note as grant_note,
                     feature_enabled(f.key, v_other::uuid, null) as resolved
                from feature_flag f
                left join feature_grant g on g.key = f.key and g.school_id = v_other
               order by f.kind, f.key) m
       WHERE m.key = 'opposition';
      PERFORM _assert(got = CASE WHEN k LIKE 'wes%' THEN '||t' ELSE '||f' END,
        format('§84 (grant): module_settings gives the %s the other school''s opposition row as %s', k, got));
    END LOOP;
    PERFORM _as(U_PLAT);
    PERFORM _assert((SELECT count(*) FROM feature_grant g WHERE g.key = 'opposition' AND g.note LIKE 'v107:%') = 2,
      '§84 (grant): the platform does not read both schools'' grant rows');
    PERFORM _as((y->>'drifter')::uuid);
    PERFORM _assert((SELECT count(*) FROM feature_grant) = 0, '§84 (grant): an account enrolled nowhere reads a grant row');

    -- (resolve)
    FOREACH k IN ARRAY ARRAY['pupil', 'parent', 'wesoffice', 'wesparent', 'drifter'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(feature_enabled('opposition', HIL, NULL) AND NOT feature_enabled('opposition', WES, NULL),
        format('§84 (resolve): opposition does not resolve on at Hilton and off at Westville for the %s', k));
    END LOOP;
    PERFORM _as((y->>'pupil')::uuid);
    PERFORM _assert(my_feature_enabled('opposition'), '§84 (resolve): the Hilton pupil reads opposition as off');
    PERFORM _as((y->>'wesparent')::uuid);
    PERFORM _assert(NOT my_feature_enabled('opposition'), '§84 (resolve): the Westville parent reads opposition as on');

    -- (writes)
    PERFORM _as((y->>'keeper')::uuid);
    INSERT INTO official (full_name, born, panel) VALUES ('Verify OneOhSeven New', '1985-05-05', 'V107 Umpires')
    RETURNING id INTO v_new;
    INSERT INTO official_accreditation (official_id, level, issued_by, valid_from)
    VALUES (v_new, 'club', 'V107', current_date) RETURNING official_id::text INTO got;
    PERFORM _assert(v_new IS NOT NULL AND got = v_new::text, '§84 (writes): the keeper could not add an official and grade him');
    UPDATE official SET active = false WHERE id = v_new AND active RETURNING id::text INTO got;
    PERFORM _assert(got = v_new::text, '§84 (writes): the keeper could not retire an official');
    PERFORM _as(U_PLAT);
    INSERT INTO feature_grant (key, school_id, granted, note, changed_by, changed_at)
    VALUES ('opposition', WES, true, 'v107: a write', app_user_id(), now())
    ON CONFLICT (key, school_id) DO UPDATE SET granted = EXCLUDED.granted, note = EXCLUDED.note,
                                               changed_by = EXCLUDED.changed_by, changed_at = EXCLUDED.changed_at
    RETURNING note INTO got;
    PERFORM _assert(got = 'v107: a write', '§84 (writes): the platform could not write a grant over an existing row');

    -- (doors)
    PERFORM _assert((SELECT string_agg(p.polrelid::regclass::text || '=' || pg_get_expr(p.polqual, p.polrelid), ' ; '
                                       ORDER BY p.polrelid::regclass::text)
                       FROM pg_policy p
                      WHERE p.polcmd = 'r' AND p.polpermissive
                        AND p.polrelid IN ('official'::regclass, 'official_accreditation'::regclass, 'feature_grant'::regclass))
                    = 'feature_grant=(app_enrolled_at(school_id) OR app_holds(''platform.feature.manage''::text)) ; '
                      'official=(app_can(''officiating.registry.manage''::text) OR ((person_id IS NOT NULL) AND (person_id = app_user_id()))) ; '
                      'official_accreditation=(app_can(''officiating.registry.manage''::text) OR (EXISTS ( SELECT 1' || chr(10)
                      || '   FROM official o' || chr(10)
                      || '  WHERE ((o.id = official_accreditation.official_id) AND (o.person_id = app_user_id())))))',
      '§84 (doors): the three read policies are not db/107''s, or one table has a second permissive read');
    SELECT string_agg(a.n, ',' ORDER BY a.i) INTO got
      FROM pg_proc p, unnest(p.proargnames, p.proargmodes) WITH ORDINALITY AS a(n, m, i)
     WHERE p.oid = 'official_panel(uuid)'::regprocedure AND a.m = 't';
    PERFORM _assert(got = 'id,full_name,panel,active,level,accredited_until,accreditations,linked'
                    AND got !~ '(^|,)(born|id_number|email|phone|person_id|created_by|created_at)(,|$)',
      format('§84 (doors): official_panel() returns %s', got));
    FOREACH k IN ARRAY ARRAY['app_enrolled_at(uuid)', 'official_panel(uuid)', 'official_conflict(uuid,uuid)'] LOOP
      PERFORM _assert((SELECT prosecdef AND provolatile = 's' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = to_regprocedure(k)),
        format('§84 (doors): %s is not a stable SECURITY DEFINER with a pinned path', k));
      PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure(k), 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = to_regprocedure(k) AND a.grantee = 0 AND a.privilege_type = 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                         AND has_function_privilege(g.oid, to_regprocedure(k), 'EXECUTE')),
        format('§84 (doors): %s is not the application''s alone', k));
    END LOOP;
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 84

  -- ┌── section 85: a pupil is a pupil of a side (db/108) ──
  -- REACH-D4 (Kameel, 14 Oct 2026): a `player` row with no team passed
  -- app_can()'s team test for every side at the school. The migration's own
  -- refusal on a database that holds one, and the fix file that clears it,
  -- are proved by tools/smoke-player-team.mjs (they cannot be proved here:
  -- this file runs after the migration).
  --
  -- What each label holds:
  --   (check)    a live `player` row with no team is refused — through the
  --              application's INSERT policy as the office, and as the owner,
  --              whom no policy stops — by role_assignment_player_team_scoped
  --              by name; with a team it is written
  --   (history)  an ENDED `player` row with no team is history, not a breach:
  --              it is written, and reactivating it is refused (db/01's
  --              trigger, with this CHECK beneath it)
  --   (grant)    decide_role_request() as the office: a request naming a boy
  --              on a side and no team is granted with HIS side; a boy on no
  --              side, or no boy, is refused by name (team_required), nothing
  --              written and the request still pending; a team the asker or
  --              the decider names is kept
  --   (enrol)    enrol_person() for a pupil takes his side from the roster; a
  --              pupil on no side is refused by name and no account is left
  --   (seed)     the whole table holds no live team-less `player` row, and
  --              the seed's spectator@ account is on the 1st XI
  --   (doors)    the constraint as written and validated; db/01's coach rule
  --              untouched; the grant door derives
  --
  -- Falsified, each change made as the owner before this file ran:
  --   the CHECK dropped                                 → (check) red: the
  --                                                        office wrote a
  --                                                        team-less player row
  --   role_request_grant_as() put back to db/92's text  → (grant) red: the
  --                                                        request for the boy
  --                                                        on U15A raised the
  --                                                        CHECK instead of
  --                                                        taking his side
  -- and the walk (tools/smoke-player-team.mjs), each change made to the file
  -- on disk and undone after:
  --   db/108's refusal block removed                    → red: db/108 ran on a
  --                                                        database holding a
  --                                                        team-less row (and
  --                                                        then failed to
  --                                                        VALIDATE, unnamed)
  --   the fix file's approved-accounts test removed     → red: it ended another
  --                                                        account's row
  DECLARE
    y        jsonb := _v108_stage();
    HIL      uuid := '11111111-1111-1111-1111-111111111111';
    got      text;
    v_ok     boolean;
    v_reason text;
    v_asg    uuid;
    v_user   uuid;
    v_id     uuid;
  BEGIN
    -- (check)
    PERFORM _as((y->>'office')::uuid);
    got := 'written';
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id, team_code)
      VALUES ((y->>'u_direct')::uuid, 'player', HIL, NULL);
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS got = CONSTRAINT_NAME;
    END;
    PERFORM _assert(got = 'role_assignment_player_team_scoped',
      format('§85 (check): the office''s team-less player row answered %s', got));
    INSERT INTO role_assignment (person_id, role, school_id, team_code)
    VALUES ((y->>'u_direct')::uuid, 'player', HIL, '3XI') RETURNING id INTO v_id;
    PERFORM _assert(v_id IS NOT NULL, '§85 (check): the office could not appoint a pupil to a side');
    got := _v108_raw((y->>'u_direct')::uuid, NULL, true);
    PERFORM _assert(got = '23514:role_assignment_player_team_scoped',
      format('§85 (check): the owner''s team-less player row answered %s', got));

    -- (history)
    got := _v108_raw((y->>'u_direct')::uuid, NULL, false);
    PERFORM _assert(got LIKE 'ok:%', format('§85 (history): an ended team-less player row answered %s', got));
    got := _v108_reactivate(substring(got FROM 4)::uuid);
    PERFORM _assert(got LIKE '23514:%', format('§85 (history): reactivating an ended team-less player row answered %s', got));

    -- (grant)
    SELECT d.ok, d.reason, d.assignment_id INTO v_ok, v_reason, v_asg FROM decide_role_request((y->>'r1')::uuid, true, 'v108', NULL, NULL) d;
    PERFORM _assert(v_ok AND _v108_fact('team_of', v_asg) = 'U15A' AND _v108_fact('request', (y->>'r1')::uuid) = 'granted:U15A',
      format('§85 (grant): the boy on U15A was answered %s/%s with side %s', v_ok, v_reason, _v108_fact('team_of', v_asg)));
    FOREACH got IN ARRAY ARRAY['r2', 'r3'] LOOP
      SELECT d.ok, d.reason, d.assignment_id INTO v_ok, v_reason, v_asg FROM decide_role_request((y->>got)::uuid, true, 'v108', NULL, NULL) d;
      PERFORM _assert(NOT v_ok AND v_reason = 'team_required' AND v_asg IS NULL
                      AND _v108_fact('held', (y->>('u_' || got))::uuid) = ''
                      AND _v108_fact('request', (y->>got)::uuid) = 'pending:-',
        format('§85 (grant): %s was answered %s/%s, holds [%s], request %s', got, v_ok, v_reason,
               _v108_fact('held', (y->>('u_' || got))::uuid), _v108_fact('request', (y->>got)::uuid)));
    END LOOP;
    SELECT d.ok, d.assignment_id INTO v_ok, v_asg FROM decide_role_request((y->>'r4')::uuid, true, 'v108', NULL, NULL) d;
    PERFORM _assert(v_ok AND _v108_fact('team_of', v_asg) = '2XI', '§85 (grant): the side the asker named was not kept');
    SELECT d.ok, d.assignment_id INTO v_ok, v_asg FROM decide_role_request((y->>'r5')::uuid, true, 'v108', NULL, 'U14A') d;
    PERFORM _assert(v_ok AND _v108_fact('team_of', v_asg) = 'U14A', '§85 (grant): the side the office named was not kept');

    -- (enrol)
    SELECT e.ok, e.reason, e.user_id, e.assignment_id INTO v_ok, v_reason, v_user, v_asg
      FROM enrol_person('v108.enrol1@example.invalid', 'V108 Enrol One', 'player', HIL, NULL, (y->>'e1')::uuid) e;
    PERFORM _assert(v_ok AND _v108_fact('team_of', v_asg) = 'U14A',
      format('§85 (enrol): the boy on U14A was enrolled %s/%s with side %s', v_ok, v_reason, _v108_fact('team_of', v_asg)));
    SELECT e.ok, e.reason INTO v_ok, v_reason
      FROM enrol_person('v108.enrol2@example.invalid', 'V108 Enrol Two', 'player', HIL, NULL, (y->>'e2')::uuid) e;
    PERFORM _assert(NOT v_ok AND v_reason = 'team_required' AND _v108_fact('account') = '0',
      format('§85 (enrol): the boy on no side was answered %s/%s and %s account(s) left', v_ok, v_reason, _v108_fact('account')));

    -- (seed)
    PERFORM _assert(_v108_fact('teamless_live') = '0',
      format('§85 (seed): %s live team-less player rows on the record', _v108_fact('teamless_live')));
    PERFORM _assert(_v108_fact('team_of', 'a5510000-0000-0000-0000-000000000001') = '1XI',
      '§85 (seed): the seed''s spectator@ account is not a pupil of the 1st XI');

    -- (doors)
    PERFORM _assert((SELECT pg_get_constraintdef(c.oid) FROM pg_constraint c
                      WHERE c.conrelid = 'role_assignment'::regclass AND c.conname = 'role_assignment_player_team_scoped'
                        AND c.contype = 'c' AND c.convalidated)
                    = 'CHECK (((role <> ''player''::text) OR (team_code IS NOT NULL) OR (NOT active)))',
      '§85 (doors): role_assignment_player_team_scoped is not db/108''s, or not validated');
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_constraint
                             WHERE conrelid = 'role_assignment'::regclass AND conname = 'assignment_team_scoped' AND convalidated
                               AND pg_get_constraintdef(oid) LIKE '%coach%assistantcoach%teammanager%'
                               AND pg_get_constraintdef(oid) NOT LIKE '%player%'),
      '§85 (doors): db/01''s assignment_team_scoped moved');
    PERFORM _assert((SELECT prosecdef AND prosrc LIKE '%IF r.role = ''player'' AND v_team IS NULL THEN%'
                       FROM pg_proc WHERE oid = 'role_request_grant_as(uuid,uuid,text,uuid,text)'::regprocedure),
      '§85 (doors): role_request_grant_as() does not derive a pupil''s side');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 85
  -- ┌── section 86: a child's links, and the reason for an ending (db/109) ──
  -- Account lifecycle slice 3 (ACCOUNT_LIFECYCLE.md §4, D11–D14, Q8, Q10,
  -- Q13). The API half is tools/smoke-family-links.mjs (child_links and the
  -- two revoke routes).
  --
  -- What each label holds:
  --   (q13)        a disabled parent still counts as a verified guardian
  --   (before)     Mum's consents count, his health consent is live, her
  --                seat stands, and no ending row exists for any link yet
  --   (refused)    a stranger, a coach, the director of sport (no
  --                guardian.link.manage), the parent herself and Westville's
  --                office are not_permitted; nothing moves
  --   (own)        nobody ends a link of their own (G1)
  --   (words)      no_such_link, kind_required, kind_not_allowed for an
  --                automatic kind, reason_required, reason_too_long; nothing
  --                moves
  --   (revoke)     the office ends Mum's link (custody): revoked, dated today,
  --                no reason on the link (D13), her guardian role ended with
  --                her last link, one row with the kind, the reason and the
  --                office's name
  --   (notice)     Mum reads one 'system' notice naming the school and the
  --                date, not the child, not the reason; Dad does not; a
  --                forged notice reaches her through no door
  --   (readers)    the office reads the kind and the reason; Mum, the coach,
  --                the DSO, the director of sport (audit.read alone, since
  --                db/116: READERS Q2) and Westville's office read no row;
  --                the DSO reads none of the child's links either (D12)
  --   (platform)   the platform administrator reads no row with no support
  --                session, nor inside one at Westville; inside one at Hilton
  --                it reads the kind and the reason; ended, nothing again
  --                (Kameel, 15 October 2026)
  --   (owner)      the owner's key cannot end a link with no support session,
  --                and can inside a live one at Hilton (the same day's rule)
  --   (dso)        inside the open concern the DSO reads the kind and the date
  --                and never the reason (Q10)
  --   (d14)        his public-name consent through Mum's link is no longer
  --                competent and none is (he is "Batter": db/47, unchanged);
  --                the health consent lapsed; her seat is void; the contact
  --                stays
  --   (again)      no_open_link; last_verified_link for Dad, now his only one
  --   (role)       ending Gran's guardian role (db/77) writes 'role_ended'
  --                rows for the link it revoked, with the role's reason
  --   (left)       Two leaves at 14: Dad keeps his link until Two's birthday,
  --                one 'majority' row, no reason, no actor (D11); nothing was
  --                written before he left (Q8); he comes back and the row goes
  --   (adult)      Old leaves at 19: Aunt's link ends today, 'left_school'
  --   (writes)     the application writes no ending row, and cannot call
  --                db/08's door without a kind or a reason
  --   (doors)      the functions' shape and grants, the policies
  --
  -- Falsified seven ways, each red for the right reason: the read policy's
  -- DSO cut removed (red at (readers): the DSO reads the boy's ending row);
  -- the guardian admitted to her own row (red at (readers): Mum reads it);
  -- db/08's door given back to scrbrd_app (red at (writes)); the notice's
  -- door answering true for any notice (red at (notice): the forged notice
  -- reaches Mum); db/109's trigger on role_assignment_ending dropped (red at
  -- (role): Gran's link has no row); the RESTRICTIVE platform cut dropped (red
  -- at (platform): read with no support session); the door's platform
  -- refusal taken out (red at (owner): the owner's key ends a link with no
  -- support session).
  DECLARE
    y       jsonb := _v109_stage();
    U_DSO   uuid := '88888888-0000-0000-0000-000000000057';
    B       uuid := (y->>'boy')::uuid;
    T       uuid := (y->>'two')::uuid;
    O       uuid := (y->>'old')::uuid;
    L_MUM   uuid := (y->>'l_mum')::uuid;
    L_DAD   uuid := (y->>'l_dad')::uuid;
    L_GRAN  uuid := (y->>'l_gran')::uuid;
    L_DAD2  uuid := (y->>'l_dad2')::uuid;
    L_OLD   uuid := (y->>'l_old')::uuid;
    WHY     text := 'V109: a custody order of the High Court';
    k       text;
    got     text;
    n       integer;
    e       jsonb;
    v_j     jsonb;
    v_extra uuid;
    v_stray uuid;
    v_birth date;
    v_ok    boolean;
    v_sess  uuid;
  BEGIN
    -- (q13)
    PERFORM _v109_disable((y->>'dad')::uuid);
    PERFORM _as((y->>'office')::uuid);
    PERFORM _assert((SELECT live_links FROM player_guardian_status WHERE player_id = B) = 2,
      '§86 (q13): a disabled parent no longer counts as a verified guardian');

    -- (before)
    PERFORM _assert((_v109_facts(B) -> 'consents') @> '[{"by": "guardian", "competent": true}]'::jsonb,
      format('§86 (before): Mum''s public-name consent does not count, so (d14) proves nothing: %s', _v109_facts(B)));
    PERFORM _assert(_v109_health(B), '§86 (before): his health consent is not live, so (d14) proves nothing');
    PERFORM _assert((_v70_seat((y->>'seat')::uuid)).state = 'requested', '§86 (before): Mum''s seat is not live');
    PERFORM _assert(_v109_ending(L_MUM) IS NULL AND _v109_ending(L_DAD2) IS NULL AND _v109_ending(L_OLD) IS NULL,
      '§86 (before): an ending row exists before anything ended');

    -- (refused)
    PERFORM set_config('app.user_id', '', true);
    got := _v109_revoke(L_MUM, 'custody', WHY);
    PERFORM _assert(got = 'not_signed_in', format('§86 (refused): nobody signed in was told %s', got));
    FOREACH k IN ARRAY ARRAY['coach', 'dos', 'mum', 'wesoffice'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v109_revoke(L_MUM, 'custody', WHY);
      PERFORM _assert(got = 'not_permitted', format('§86 (refused): the %s was told %s', k, got));
    END LOOP;
    PERFORM _assert((_v109_link_row(L_MUM))->>'verification_state' = 'verified' AND _v109_ending(L_MUM) IS NULL,
      '§86 (refused): a refused revoke moved the link, or wrote a row');

    -- (own)
    v_extra := _v109_grant((y->>'aunt')::uuid, 'schooladmin');
    PERFORM _as((y->>'aunt')::uuid);
    got := _v109_revoke(L_OLD, 'office', WHY);
    PERFORM _assert(got = 'own_link', format('§86 (own): the office ending its own link was told %s', got));
    PERFORM _v109_ungrant(v_extra);

    -- (words)
    PERFORM _as((y->>'office')::uuid);
    got := _v109_revoke(gen_random_uuid(), 'custody', WHY);
    PERFORM _assert(got = 'no_such_link', format('§86 (words): a link that is not there answered %s', got));
    got := _v109_revoke(NULL, 'custody', WHY);
    PERFORM _assert(got = 'no_such_link', format('§86 (words): no link answered %s', got));
    got := _v109_revoke(L_MUM, NULL, WHY);
    PERFORM _assert(got = 'kind_required', format('§86 (words): no kind answered %s', got));
    FOREACH k IN ARRAY ARRAY['majority', 'left_school', 'role_ended', 'whim'] LOOP
      got := _v109_revoke(L_MUM, k, WHY);
      PERFORM _assert(got = 'kind_not_allowed', format('§86 (words): the kind %s answered %s', k, got));
    END LOOP;
    got := _v109_revoke(L_MUM, 'custody', '   too short   ');
    PERFORM _assert(got = 'reason_required', format('§86 (words): nine characters, padded, answered %s', got));
    got := _v109_revoke(L_MUM, 'custody', repeat('x', 2001));
    PERFORM _assert(got = 'reason_too_long', format('§86 (words): 2,001 characters answered %s', got));
    PERFORM _assert((_v109_link_row(L_MUM))->>'verification_state' = 'verified' AND _v109_ending(L_MUM) IS NULL,
      '§86 (words): a refused revoke moved the link, or wrote a row');

    -- (revoke)
    got := _v109_revoke(L_MUM, 'custody', '  ' || WHY || '  ');
    PERFORM _assert(got = 'ok', format('§86 (revoke): the office was told %s', got));
    v_j := _v109_link_row(L_MUM);
    PERFORM _assert(v_j->>'verification_state' = 'revoked' AND (v_j->>'valid_until')::date = current_date
                    AND v_j->>'verified_note' IS NULL,
      format('§86 (revoke): the link reads %s', v_j));
    PERFORM _assert(position('High Court' IN v_j::text) = 0, '§86 (revoke): the reason is on the link (D13)');
    PERFORM _assert(_v109_role((y->>'mum')::uuid) IS NULL, '§86 (revoke): Mum''s guardian role outlived her last link');
    e := _v109_ending(L_MUM);
    PERFORM _assert(e->>'kind' = 'custody' AND e->>'reason' = WHY AND (e->>'ended_by')::uuid = (y->>'office')::uuid
                    AND (e->>'ends_on')::date = current_date AND (e->>'guardian_id')::uuid = (y->>'mum')::uuid
                    AND (e->>'player_id')::uuid = B AND e->>'notice_id' IS NOT NULL,
      format('§86 (revoke): the ending row reads %s', e));

    -- (notice)
    v_j := _v109_notice((e->>'notice_id')::uuid);
    PERFORM _assert(v_j->>'kind' = 'system' AND (v_j->>'recipient_id')::uuid = (y->>'mum')::uuid
                    AND v_j->>'subject_person_id' IS NULL AND v_j->>'urgency' = 'medium'
                    AND v_j->>'body' = 'Your link to a child at Hilton College ended on '
                                       || to_char(current_date, 'FMDD FMMonth YYYY')
                                       || '. The school office can say why; the platform does not.',
      format('§86 (notice): the notice reads %s', v_j));
    PERFORM _assert(position('OneOhNine' IN v_j::text) = 0 AND position('High Court' IN v_j::text) = 0,
      '§86 (notice): the notice names the child or gives the reason');
    PERFORM _as((y->>'mum')::uuid);
    PERFORM _assert((SELECT count(*) FROM notification n WHERE n.id = (e->>'notice_id')::uuid) = 1,
      '§86 (notice): Mum, with no role left at the school, does not read her notice');
    v_stray := _v90_stray((y->>'mum')::uuid);
    PERFORM _assert((SELECT count(*) FROM notification n WHERE n.id = v_stray) = 0,
      '§86 (notice): a system notice no ending row admits reaches Mum');
    PERFORM _as((y->>'dad')::uuid);
    PERFORM _assert((SELECT count(*) FROM notification n WHERE n.id = (e->>'notice_id')::uuid) = 0,
      '§86 (notice): Dad reads the notice written to Mum');

    -- (readers)
    FOREACH k IN ARRAY ARRAY['office'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT x.kind || ':' || x.reason INTO got FROM guardian_link_ending x WHERE x.link_id = L_MUM;
      PERFORM _assert(got = 'custody:' || WHY, format('§86 (readers): the %s reads %s', k, coalesce(got, 'no row')));
    END LOOP;
    -- The director of sport holds audit.read and not guardian.link.manage:
    -- since db/116 (READERS Q2) a revocation's reason is the office's act's
    -- alone, and audit.read opens the access log and nothing else.
    FOREACH k IN ARRAY ARRAY['mum', 'dad', 'coach', 'wesoffice', 'dso', 'dos'] LOOP
      PERFORM _as(CASE k WHEN 'dso' THEN U_DSO ELSE (y->>k)::uuid END);
      PERFORM _assert((SELECT count(*) FROM guardian_link_ending x WHERE x.player_id = B) = 0,
        format('§86 (readers): the %s reads an ending row of the boy''s', k));
    END LOOP;
    PERFORM _as(U_DSO);
    PERFORM _assert((SELECT count(*) FROM assignment_subject g WHERE g.player_id = B) = 0,
      '§86 (readers): the DSO reads the boy''s links by standing (D12)');

    -- (platform) Kameel, 15 October 2026: never platform-wide; inside a live
    -- support session at the boy's school, and only there.
    PERFORM _as((y->>'platform')::uuid);
    PERFORM _assert((SELECT count(*) FROM guardian_link_ending x WHERE x.player_id = B) = 0,
      '§86 (platform): the platform administrator reads the boy''s ending row with no support session');
    SELECT r.ok, r.id INTO v_ok, v_sess
      FROM support_access_begin('22222222-2222-2222-2222-222222222222', 'schooladmin', 'V109: Westville asked for help', NULL, 60) r;
    PERFORM _assert(v_ok, '§86 (platform): a support session at Westville could not be begun');
    PERFORM _assert((SELECT count(*) FROM guardian_link_ending x WHERE x.player_id = B) = 0,
      '§86 (platform): inside a session at Westville, the platform administrator reads Hilton''s ending row');
    PERFORM support_access_end(v_sess);
    SELECT r.ok, r.id INTO v_ok, v_sess
      FROM support_access_begin('11111111-1111-1111-1111-111111111111', 'schooladmin', 'V109: Hilton asked for help', NULL, 60) r;
    PERFORM _assert(v_ok, '§86 (platform): a support session at Hilton could not be begun');
    SELECT x.kind || ':' || x.reason INTO got FROM guardian_link_ending x WHERE x.link_id = L_MUM;
    PERFORM _assert(got = 'custody:' || WHY,
      format('§86 (platform): inside a session at Hilton, the platform administrator reads %s', coalesce(got, 'no row')));
    PERFORM support_access_end(v_sess);
    PERFORM _assert((SELECT count(*) FROM guardian_link_ending x WHERE x.player_id = B) = 0,
      '§86 (platform): the session ended and the platform administrator still reads the row');

    -- (owner) No platform role gains school authority here: the owner's key
    -- ends a family's link only inside a live support session at that school.
    PERFORM _as((y->>'owner')::uuid);
    got := _v109_revoke((y->>'l_uncle')::uuid, 'office', 'V109: the school asked the platform to end it');
    PERFORM _assert(got = 'not_permitted', format('§86 (owner): the owner''s key with no support session was told %s', got));
    PERFORM _assert((_v109_link_row((y->>'l_uncle')::uuid))->>'verification_state' = 'verified'
                    AND _v109_ending((y->>'l_uncle')::uuid) IS NULL,
      '§86 (owner): a refused revoke by the owner''s key moved the link, or wrote a row');
    SELECT r.ok, r.id INTO v_ok, v_sess
      FROM support_access_begin('11111111-1111-1111-1111-111111111111', 'schooladmin', 'V109: Hilton asked the platform to help', NULL, 60) r;
    PERFORM _assert(v_ok, '§86 (owner): the owner''s key could not begin a support session at Hilton');
    got := _v109_revoke((y->>'l_uncle')::uuid, 'office', 'V109: the school asked the platform to end it');
    PERFORM _assert(got = 'ok', format('§86 (owner): inside a session at Hilton the owner''s key was told %s', got));
    PERFORM _assert((_v109_ending((y->>'l_uncle')::uuid))->>'kind' = 'office'
                    AND ((_v109_ending((y->>'l_uncle')::uuid))->>'ended_by')::uuid = (y->>'owner')::uuid,
      format('§86 (owner): the ending reads %s', _v109_ending((y->>'l_uncle')::uuid)));
    PERFORM support_access_end(v_sess);

    -- (dso)
    PERFORM _as(U_DSO);
    v_j := safeguarding_family((y->>'concern')::uuid);
    PERFORM _assert(v_j -> 'ended' @> jsonb_build_array(jsonb_build_object('kind', 'custody', 'endsOn', current_date,
                                                                          'linkId', L_MUM)),
      format('§86 (dso): inside the concern the DSO does not read how Mum''s link ended: %s', v_j -> 'ended'));
    PERFORM _assert(position('High Court' IN v_j::text) = 0 AND NOT (v_j -> 'ended' -> 0 ? 'reason'),
      '§86 (dso): inside the concern the DSO reads the office''s reason (Q10)');

    -- (d14)
    PERFORM _assert(NOT ((_v109_facts(B) -> 'consents') @> '[{"competent": true}]'::jsonb),
      format('§86 (d14): a consent through a revoked link still counts, so he is named: %s', _v109_facts(B)));
    PERFORM _assert((_v109_facts(B) -> 'consents') @> '[{"by": "guardian", "competent": false}]'::jsonb,
      format('§86 (d14): Mum''s consent is gone from the facts rather than read as incompetent: %s', _v109_facts(B)));
    PERFORM _assert(NOT _v109_health(B), '§86 (d14): his health consent through a revoked link is still live');
    PERFORM _v70_fire();
    PERFORM _assert((_v70_seat((y->>'seat')::uuid)).state = 'void',
      format('§86 (d14): Mum''s seat reads %s, not void', (_v70_seat((y->>'seat')::uuid)).state));
    PERFORM _assert(_v109_contacts(B) = 1, '§86 (d14): the emergency contact went with the link');

    -- (again)
    PERFORM _as((y->>'office')::uuid);
    got := _v109_revoke(L_MUM, 'custody', WHY);
    PERFORM _assert(got = 'no_open_link', format('§86 (again): an ended link answered %s', got));
    got := _v109_revoke(L_DAD, 'custody', WHY);
    PERFORM _assert(got = 'last_verified_link', format('§86 (again): his only verified link answered %s', got));
    got := _v109_revoke(L_DAD, NULL, NULL);
    PERFORM _assert(got = 'last_verified_link', format('§86 (again): the last link, asked with nothing, answered %s', got));
    PERFORM _assert((_v109_link_row(L_DAD))->>'verification_state' = 'verified' AND _v109_ending(L_DAD) IS NULL,
      '§86 (again): his last link moved');

    -- (role)
    SELECT r.ok::text || coalesce(r.reason, '') INTO got
      FROM role_assignment_end(_v109_role((y->>'gran')::uuid), 'V109: Gran stepped back from the family') r;
    PERFORM _assert(got = 'true', format('§86 (role): ending Gran''s role answered %s', got));
    e := _v109_ending(L_GRAN);
    PERFORM _assert(e->>'kind' = 'role_ended' AND e->>'reason' = 'V109: Gran stepped back from the family'
                    AND (e->>'ended_by')::uuid = (y->>'office')::uuid AND e->>'notice_id' IS NOT NULL
                    AND (e->>'ends_on')::date = current_date,
      format('§86 (role): Gran''s link reads %s', e));
    PERFORM _assert(_v109_ending(L_DAD2) IS NULL, '§86 (role): ending Gran''s role wrote a row for Dad''s link');

    -- (left)
    PERFORM _assert(_v109_ending(L_DAD2) IS NULL AND (_v109_link_row(L_DAD2))->>'valid_until' IS NULL,
      '§86 (left): Dad''s link to Two ends, or has a row, before Two left (Q8)');
    PERFORM _v109_leave(T);
    v_birth := majority_on((SELECT p.born FROM player p WHERE p.id = T));
    e := _v109_ending(L_DAD2);
    PERFORM _assert(e->>'kind' = 'majority' AND (e->>'ends_on')::date = v_birth
                    AND e->>'reason' IS NULL AND e->>'ended_by' IS NULL AND e->>'notice_id' IS NULL,
      format('§86 (left): Two left at 14 and Dad''s link reads %s', e));
    PERFORM _assert((_v109_link_row(L_DAD2))->>'verification_state' = 'verified'
                    AND ((_v109_link_row(L_DAD2))->>'valid_until')::date = v_birth,
      '§86 (left): Dad does not keep his link until Two''s birthday (D11)');
    PERFORM _as((y->>'office')::uuid);
    PERFORM _assert((SELECT x.kind FROM guardian_link_ending x WHERE x.link_id = L_DAD2) = 'majority',
      '§86 (left): the office does not read how Dad''s link will end');
    PERFORM _v109_return(T);
    PERFORM _assert(_v109_ending(L_DAD2) IS NULL AND (_v109_link_row(L_DAD2))->>'valid_until' IS NULL,
      format('§86 (left): Two came back and Dad''s link reads %s, its row %s', _v109_link_row(L_DAD2), _v109_ending(L_DAD2)));

    -- (adult)
    PERFORM _v109_leave(O);
    e := _v109_ending(L_OLD);
    -- The day he left: the session's, or the day his side began if that is
    -- later (THE DAY, AT ANY HOUR, above _v60_leave).
    PERFORM _assert(e->>'kind' = 'left_school' AND (e->>'ends_on')::date = _v109_left_on(O)
                    AND (e->>'ends_on')::date >= current_date
                    AND e->>'reason' IS NULL AND e->>'ended_by' IS NULL,
      format('§86 (adult): Old left at 19 and Aunt''s link reads %s', e));

    -- (writes)
    PERFORM _as((y->>'office')::uuid);
    got := 'written';
    BEGIN
      INSERT INTO guardian_link_ending (link_id, player_id, school_id, guardian_id, kind, reason, ended_by, ends_on)
      VALUES (L_DAD, B, '11111111-1111-1111-1111-111111111111', (y->>'dad')::uuid, 'office', WHY, (y->>'office')::uuid, current_date);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'refused', '§86 (writes): the application wrote an ending row');
    got := 'written';
    BEGIN
      UPDATE guardian_link_ending SET reason = 'V109: rewritten after the fact' WHERE link_id = L_MUM;
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'refused', '§86 (writes): the application rewrote an ending row');
    got := 'called';
    BEGIN
      PERFORM guardian_link_revoke((y->>'dad')::uuid, T, 'no kind, no reason'::text);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'refused', '§86 (writes): db/08''s door without a kind or a reason is callable');

    -- (doors)
    FOREACH k IN ARRAY ARRAY['guardian_link_revoke(uuid,text,text)', 'guardian_link_ending_notice_is_mine(uuid)',
                             'safeguarding_family(uuid)'] LOOP
      PERFORM _assert((SELECT prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                         FROM pg_proc WHERE oid = to_regprocedure(k))
                      AND has_function_privilege('scrbrd_app', to_regprocedure(k), 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                       WHERE p.oid = to_regprocedure(k) AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
        format('§86 (doors): %s is not a SECURITY DEFINER with a pinned path, the application''s alone', k));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['role_assignment_ending_links()', 'guardian_links_close_on_leaving(uuid,date)',
                             'guardian_links_reopen_at_school(uuid)', 'guardian_link_revoke(uuid,uuid,text)'] LOOP
      PERFORM _assert(NOT has_function_privilege('scrbrd_app', to_regprocedure(k), 'EXECUTE'),
        format('§86 (doors): the application may call %s', k));
    END LOOP;
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'notification'
                               AND policyname = 'notification_link_ended' AND permissive = 'PERMISSIVE' AND cmd = 'SELECT')
                    AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'guardian_link_ending'
                                   AND policyname = 'pad_scope_select' AND permissive = 'RESTRICTIVE')
                    AND NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public'
                                       AND tablename = 'guardian_link_ending' AND cmd <> 'SELECT'),
      '§86 (doors): the notice''s door, the pad cut, or a write policy on guardian_link_ending is wrong');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 86
  -- ┌── db/110 (section 87) ──────────────────────────────────────────
  -- ── 87. The coach's draft plan: changed, and thrown away (db/110) ──
  -- Kameel, 15 Oct (final): a plan never sent is its author's to edit and to
  -- delete; a withdrawn plan is his to edit and send again, never to delete;
  -- a plan out with the side is not changed in place. Every write below is a
  -- person's, through scrbrd_app under RLS, unless it says it is a door;
  -- _v110_stage(), _v110_row() and _v110_versions() stage or only read.
  --
  -- What each label holds:
  --   (draft)     the coach saves a draft plan; he changes its words and its
  --               urgency, and it stays a plan never sent
  --   (author)    the second coach and the team manager change nothing of it
  --               (db/12's update policy: no row); through a door that is not
  --               the policy, the second coach is refused
  --               news_post_plan_author and its author is let through
  --   (delete)    nobody but its author throws it away (no_such_draft, the
  --               row kept), nor an anonymous session; its author does, and
  --               it is gone; an ordinary draft post is no plan to discard;
  --               the application still holds no DELETE on news_post
  --   (sent)      a plan sent is dated; its words and urgency are refused
  --               while it is out (news_post_plan_sent), and discarding it
  --               answers plan_kept, the row kept
  --   (withdrawn) withdrawn, it keeps its date; its author changes it, and
  --               nobody else does; it is never discarded (plan_kept), even
  --               after he tries to clear the date; he sends it again, and
  --               its first date stands
  --   (history)   the plan's two sendings stand in its notices, in order:
  --               the first, retracted, with the words it went out with; the
  --               second, live, with the new words; the boy reads the new
  --               plan
  --   (insert)    a date the caller writes on a draft is not kept; a plan
  --               sent at once is dated at once
  --   (post)      an ordinary post sent is still its author's to edit, as
  --               before (the decision is the plan's)
  --   (doors)     the guard is the trigger's alone; news_plan_discard is a
  --               SECURITY DEFINER with a pinned path, the application's
  --               alone
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this file; each went red at its label:
  --   (withdrawn) news_plan_discard() without "OR n.first_sent_at IS NOT
  --               NULL" (red at the withdrawn plan discarded)
  --   (author)    news_post_plan_drafts() without its author clause (red at
  --               the second coach's door)
  --   (sent)      news_post_plan_drafts() without its sent clause (red at
  --               the author changing the live plan's words)
  DECLARE
    y   jsonb := _v110_stage();
    V_HIL uuid := '11111111-1111-1111-1111-111111111111';
    F1  uuid := (y->>'f1')::uuid;
    F2  uuid := (y->>'f2')::uuid;
    D uuid; P uuid; X uuid; O uuid; Q uuid;
    k   text;
    got text;
    ins text := $q$INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id)
                   VALUES ('team', %L, '12XI', %L, %L, %s, 'plan', %L) RETURNING id$q$;
  BEGIN
    -- (draft)
    PERFORM _as((y->>'coach')::uuid);
    EXECUTE format(ins, V_HIL, 'The plan: v Visitors', 'Bat first if we win it.', 'NULL', F1) INTO D;
    got := _app_89(format('UPDATE news_post SET body = %L, urgency = ''medium'' WHERE id = %L', 'Bowl first if we win it.', D));
    PERFORM _assert(got = 'ok' AND _v110_row(D) = 'plan | Bowl first if we win it. | medium | f | f',
      format('§87 (draft): the author changing his draft answered %s, and it reads %s', got, _v110_row(D)));

    -- (author)
    FOREACH k IN ARRAY ARRAY['coach2', 'manager', 'captain'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _app_89(format('UPDATE news_post SET body = %L WHERE id = %L', 'Not his to change.', D));
      PERFORM _assert(_v110_row(D) = 'plan | Bowl first if we win it. | medium | f | f',
        format('§87 (author): the %s changed the coach''s draft (%s): %s', k, got, _v110_row(D)));
    END LOOP;
    PERFORM _as((y->>'coach2')::uuid);
    got := _v110_door_edit(D, 'Not his to change.');
    PERFORM _assert(got = 'news_post_plan_author' AND _v110_row(D) LIKE 'plan | Bowl first if we win it.%',
      format('§87 (author): through a door, the second coach changing the draft answered %s', got));
    PERFORM _as((y->>'coach')::uuid);
    got := _v110_door_edit(D, 'Bowl first if we win it. Captain opens.');
    PERFORM _assert(got = 'ok', format('§87 (author): through a door, the author changing his draft answered %s', got));

    -- (delete)
    FOREACH k IN ARRAY ARRAY['coach2', 'manager', 'captain', 'guardian'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT d.reason INTO got FROM news_plan_discard(D) d;
      PERFORM _assert(got = 'no_such_draft' AND _v110_row(D) <> 'gone',
        format('§87 (delete): the %s discarding the coach''s draft answered %s (%s)', k, got, _v110_row(D)));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    SELECT d.reason INTO got FROM news_plan_discard(D) d;
    PERFORM _assert(got = 'not_permitted' AND _v110_row(D) <> 'gone', format('§87 (delete): an anonymous session answered %s', got));
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, '12XI', 'Verify 110 nets', 'Nets at three.', NULL) RETURNING id INTO O;
    SELECT d.reason INTO got FROM news_plan_discard(O) d;
    PERFORM _assert(got = 'no_such_draft' AND _v110_row(O) <> 'gone', format('§87 (delete): an ordinary draft post was discarded as a plan (%s)', got));
    SELECT d.ok::text || coalesce(d.reason, '') INTO got FROM news_plan_discard(D) d;
    PERFORM _assert(got = 'true' AND _v110_row(D) = 'gone', format('§87 (delete): the author discarding his draft answered %s (%s)', got, _v110_row(D)));
    got := _app_89(format('DELETE FROM news_post WHERE id = %L', O));
    PERFORM _assert(got = '42501' AND _v110_row(O) <> 'gone', format('§87 (delete): the application deleted a post directly (%s)', got));

    -- (sent)
    PERFORM _as((y->>'coach')::uuid);
    -- Sent an hour ago, so its first date and a later sending differ (this
    -- file is one transaction: now() does not move).
    EXECUTE format(ins, V_HIL, 'The plan: v Visitors', 'Bat first if we win it.', 'now() - interval ''1 hour''', F1) INTO P;
    PERFORM _assert(_v110_row(P) = 'plan | Bat first if we win it. | low | t | t', format('§87 (sent): the sent plan reads %s', _v110_row(P)));
    FOREACH k IN ARRAY ARRAY[
      format('UPDATE news_post SET body = %L WHERE id = %L', 'Bowl first after all.', P),
      format('UPDATE news_post SET title = %L WHERE id = %L', 'The plan, again', P),
      format('UPDATE news_post SET urgency = ''medium'' WHERE id = %L', P),
      format('UPDATE news_post SET body = %L, published_at = NULL WHERE id = %L', 'Bowl first after all.', P)] LOOP
      got := _app_89(k);
      PERFORM _assert(got = 'news_post_plan_sent', format('§87 (sent): %s answered %s', left(k, 90), got));
    END LOOP;
    SELECT d.reason INTO got FROM news_plan_discard(P) d;
    PERFORM _assert(got = 'plan_kept' AND _v110_row(P) = 'plan | Bat first if we win it. | low | t | t',
      format('§87 (sent): discarding the live plan answered %s (%s)', got, _v110_row(P)));

    -- (withdrawn)
    PERFORM _assert(_withdraw_91(P) = 'ok', '§87 (withdrawn): the author could not withdraw the plan');
    PERFORM _assert(_v110_row(P) = 'plan | Bat first if we win it. | low | f | t', format('§87 (withdrawn): the withdrawn plan reads %s', _v110_row(P)));
    FOREACH k IN ARRAY ARRAY['coach2', 'manager'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _app_89(format('UPDATE news_post SET body = %L WHERE id = %L', 'Not his to change.', P));
      PERFORM _assert(_v110_row(P) LIKE 'plan | Bat first if we win it.%', format('§87 (withdrawn): the %s changed the withdrawn plan (%s)', k, got));
      SELECT d.reason INTO got FROM news_plan_discard(P) d;
      PERFORM _assert(got = 'no_such_draft' AND _v110_row(P) <> 'gone', format('§87 (withdrawn): the %s discarding it answered %s', k, got));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    got := _app_89(format('UPDATE news_post SET body = %L WHERE id = %L', 'Bowl first after all. Captain opens.', P));
    PERFORM _assert(got = 'ok' AND _v110_row(P) = 'plan | Bowl first after all. Captain opens. | low | f | t',
      format('§87 (withdrawn): the author changing the withdrawn plan answered %s (%s)', got, _v110_row(P)));
    SELECT d.reason INTO got FROM news_plan_discard(P) d;
    PERFORM _assert(got = 'plan_kept' AND _v110_row(P) <> 'gone', format('§87 (withdrawn): discarding the withdrawn plan answered %s (%s)', got, _v110_row(P)));
    got := _app_89(format('UPDATE news_post SET first_sent_at = NULL WHERE id = %L', P));
    PERFORM _assert(_v110_row(P) LIKE '% | t', format('§87 (withdrawn): clearing the date answered %s and it reads %s', got, _v110_row(P)));
    SELECT d.reason INTO got FROM news_plan_discard(P) d;
    PERFORM _assert(got = 'plan_kept' AND _v110_row(P) <> 'gone', format('§87 (withdrawn): after clearing the date, discarding answered %s', got));
    got := (SELECT first_sent_at::text FROM news_post WHERE id = P);
    k := _app_89(format('UPDATE news_post SET published_at = now() WHERE id = %L AND published_at IS NULL', P));
    PERFORM _assert(k = 'ok'
                    AND _v110_row(P) = 'plan | Bowl first after all. Captain opens. | low | t | t'
                    AND (SELECT first_sent_at::text FROM news_post WHERE id = P) = got
                    AND (SELECT first_sent_at < published_at FROM news_post WHERE id = P),
      format('§87 (withdrawn): sent again, it reads %s and its first date moved', _v110_row(P)));

    -- (history)
    got := _v110_versions(P);
    PERFORM _assert(got = 'Bat first if we win it. (retracted) / Bowl first after all. Captain opens. (live)',
      format('§87 (history): the plan''s sendings read %s', got));
    FOREACH k IN ARRAY ARRAY['captain', 'guardian'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT n.body FROM news_post n WHERE n.id = P) = 'Bowl first after all. Captain opens.',
        format('§87 (history): the %s does not read the plan sent again', k));
    END LOOP;

    -- (insert)
    PERFORM _as((y->>'coach')::uuid);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at, kind, fixture_id, first_sent_at)
    VALUES ('team', V_HIL, '12XI', 'The plan: v Second Visitors', 'Bat first.', NULL, 'plan', F2, now() - interval '1 day') RETURNING id INTO X;
    PERFORM _assert(_v110_row(X) = 'plan | Bat first. | low | f | f', format('§87 (insert): a forged date on a draft reads %s', _v110_row(X)));
    SELECT d.ok::text INTO got FROM news_plan_discard(X) d;
    PERFORM _assert(got = 'true' AND _v110_row(X) = 'gone', '§87 (insert): the draft with a forged date could not be discarded');

    -- (post)
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', V_HIL, '12XI', 'Verify 110 nets moved', 'Nets at four.', now()) RETURNING id INTO Q;
    got := _app_89(format('UPDATE news_post SET body = %L WHERE id = %L', 'Nets at five.', Q));
    PERFORM _assert(got = 'ok' AND _v110_row(Q) = 'post | Nets at five. | low | t | f',
      format('§87 (post): the author editing his sent post answered %s (%s)', got, _v110_row(Q)));

    -- (doors)
    PERFORM _assert((SELECT prosecdef AND provolatile = 'v' AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                       FROM pg_proc WHERE oid = to_regprocedure('news_plan_discard(uuid)'))
                    AND has_function_privilege('scrbrd_app', to_regprocedure('news_plan_discard(uuid)'), 'EXECUTE')
                    AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                     WHERE p.oid = to_regprocedure('news_plan_discard(uuid)') AND a.grantee = 0 AND a.privilege_type = 'EXECUTE')
                    AND NOT EXISTS (SELECT 1 FROM pg_roles g WHERE g.rolname IN ('anon', 'authenticated')
                                       AND has_function_privilege(g.oid, to_regprocedure('news_plan_discard(uuid)'), 'EXECUTE')),
      '§87 (doors): news_plan_discard is not a SECURITY DEFINER with a pinned path, the application''s alone');
    PERFORM _assert((SELECT prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}'))
                       FROM pg_proc WHERE oid = to_regprocedure('news_post_plan_drafts()'))
                    AND NOT has_function_privilege('scrbrd_app', to_regprocedure('news_post_plan_drafts()'), 'EXECUTE')
                    AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'news_post'::regclass AND tgname = 'news_post_plan_drafts'
                                   AND tgenabled = 'O'),
      '§87 (doors): the guard is callable by the application, or not the trigger''s');
    PERFORM _assert(NOT has_table_privilege('scrbrd_app', 'news_post', 'DELETE'), '§87 (doors): the application may delete a post');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 87
  -- └── db/110 (section 87) ──────────────────────────────────────────
  -- ┌── db/111 (section 88) ──────────────────────────────────────────
  -- ── 88. The physio's injury record, its reviews and her worklist (db/111) ──
  -- GA-I19 slice A, and slice C's SG-12 injury half. Every write below is a
  -- person's, through scrbrd_app, through the two doors; _v111_stage() and the
  -- _v111_ helpers stage and read as the owner.
  --
  -- What each label holds:
  --   (doors)    the application writes neither table directly: a physio's
  --              INSERT or UPDATE on injury and INSERT on injury_review are
  --              refused for want of privilege (D2's REVOKE)
  --   (record)   the physio records: recorded_by is she, the injury opens
  --              active with its next review, one review (the recording) by
  --              her, one "Injury recorded" notice, fitness 'injured', no
  --              safeguarding notice for a moderate injury
  --   (who)      every other reader is refused, by name: 12XI's coach,
  --              assistant and manager, 20XI's coach, the director, the
  --              principal, the office, the fitness coach, a scorer, a
  --              follower, a granted enquiry, the boy's parent, the boy, his
  --              team-mate, Westville's physio, the owner's key, and nobody
  --              signed in; and the same for a review
  --   (family)   a physio who is a boy's mother is refused for him, as
  --              author of a record and of a review, and records another boy;
  --              a physio whose guardian claim on the boy is still pending is
  --              refused for him too (Q6)
  --   (rules)    a record with no next review, one in the past, an injury in
  --              the future, a severity outside the three, no injury named, a
  --              return before the injury, and a boy who is not there
  --   (module)   the Injuries module hidden from the physio: both doors say
  --              module_off; shown again, she records
  --   (review)   a review to rehab moves the phase and fitness and writes no
  --              notice, keeping the restriction and return date it was not
  --              given; refused with no next review, a phase outside the
  --              three, a cleared boy restricted or given a next review, a
  --              next review past, a review dated before the last; a moved
  --              return date writes one "Return date updated"; clearing writes
  --              one "Cleared to play", unrestricts him, ends the clock and
  --              sets fitness 'fit'; a cleared injury is not reviewed again
  --   (reopen)   a recurrence names the cleared injury; not another boy's,
  --              and not an open one
  --   (key)      a review naming one boy's injury and another boy is refused
  --              by the key, even to the owner
  --   (fitness)  'rehab' while one is in rehab and none active; 'injured'
  --              while one is active; 'unavailable' set for another reason
  --              is left when the last injury clears
  --   (tiers)    the reviews, column by column: the physio, the parent and the
  --              boy read every tier; 12XI's coach, assistant and manager, the
  --              director, the office and the fitness coach read phases and
  --              dates and never the note or its author; the principal and the
  --              granted enquiry read that a review happened and what it left
  --              his availability as, and nothing of the phase; 20XI's coach,
  --              the team-mate, a scorer, a follower, Westville's physio and
  --              the DSO read none. And injury_masked's new columns, by tier
  --   (principal) status and nature (READERS Q9, 21 Oct 2026, later than
  --              D3; db/116 restores medical.nature.read): of the injury row
  --              its type, severity, phase, next review and emergency mark
  --              with its restriction, dates and his fitness word; never the
  --              clinical details tier (the note, the author)
  --   (worklist) the physio's list: one reason each — overdue, return
  --              passed, due, no return date, new — in that order, with the
  --              clock; a quiet open injury is not on it; a boy who left is
  --              off it and his row stays, which the physio no longer reads
  --              (READERS Q3, db/116); the mother-physio's own son is off
  --              hers, and the claiming physio's boy off hers; nobody without
  --              medical.write gets a row, nor the owner's key, nor
  --              Westville's physio a Hilton row
  --   (left)     injury_left_on(): the day the leaver left, to the physio,
  --              his coach and the principal; NULL for a boy still there and
  --              to another side's coach. And (record)/(tiers): is_recording
  --              marks the recording alone, read at the status tier
  --   (support)  a support session as the physio, and as the sports office: no
  --              review row, no worklist, both doors not_under_support; the
  --              injury rows themselves as today (Q7)
  --   (sg12)     a severe record writes the DSO one safeguarding notice that
  --              names no child, no diagnosis and no id, for the school, high,
  --              under safeguarding.concern.read; the physio and the side's
  --              coach do not read it; a second edit and a review write no
  --              second; a moderate record writes none until it is made
  --              severe, then one, and none when it is eased and made severe
  --              again; an injury already serious before db/111 writes none
  --              on a later edit; a minor one with emergency services called
  --              writes one; the DSO reads no injury and no review
  --   (retention) NULL while he is at school; twelve months after he leaves
  --   (agree)    every review row the physio reads is one the owner holds,
  --              and the injury row's state is its latest review's
  --   (doors2)   the functions: definers pinned, the worklist an invoker, the
  --              application's three and nobody else's
  --
  -- Falsified once each, by replacing the object inside this file's own
  -- transaction and running the section; each went red at its label:
  --   (tiers)    the note masked at the nature tier (red at the coach: 2 notes)
  --   (family)   injury_write_refusal() without its family line (red at the
  --              mother-physio recording her son)
  --   (family)   injury_writer_is_family() as is_family_of() alone (red at the
  --              physio whose claim is pending)
  --   (review)   the door's next-review check and the table's CHECK both gone
  --              (red at next_review_required, answered ok)
  --   (support)  injury_review_not_support dropped (red at the support session
  --              as the physio: every review at the school)
  --   (worklist) app_can('medical.status.read') where it asks medical.write
  --              (red at the coach: 4 rows); the family cut removed (red at
  --              the mother-physio's list holding her son's two)
  --   (record)   injury_record() writing is_recording false (red at the recording)
  --   (left)     injury_left_on() as a definer (red at 20XI's coach, given the date)
  --   (tiers)    [db/111's: the principal's medical.nature.read row added
  --              back. Since db/116 (READERS Q9) that row is the decided state.]
  --   (sg12)     the boy's name in the words (red at D10's words); the stamp
  --              guard removed (red at made severe a second time); the
  --              "becomes" rule removed (red at the injury already serious)
  DECLARE
    y        jsonb := _v111_stage();
    V_HIL    uuid := '11111111-1111-1111-1111-111111111111';
    U_DSO    uuid := '88888888-0000-0000-0000-000000000057';
    U_PLAT   uuid := '88888888-0000-0000-0000-000000000014';
    U_SUPER  uuid := '88888888-0000-0000-0000-000000000022';
    T        date := sa_today();
    BOY      uuid := (y->>'p_boy')::uuid;
    MATE     uuid := (y->>'p_mate')::uuid;
    OWN      uuid := (y->>'p_own')::uuid;
    LEAVER   uuid := (y->>'p_leaver')::uuid;
    SIDE     uuid := (y->>'p_side')::uuid;
    WESBOY   uuid := (y->>'p_wes')::uuid;
    REST     uuid := (y->>'p_rest')::uuid;
    U_PHYSIO   uuid := (y->>'physio')::uuid;
    sg0      int  := _v111_sg_count('11111111-1111-1111-1111-111111111111');
    I1 uuid; I_RECUR uuid; I_MATE uuid; I_OWN uuid; I_OVER uuid; I_RET uuid; I_NORTW uuid;
    I_QUIET uuid; I_LEFT uuid; I_SEV uuid; I_MOD uuid; I_EMS uuid; I_U uuid; v_sid uuid;
    v_ok boolean; v_reason text; v_id uuid; j jsonb; k text; n int; got text;
    e_rows int; e_phase int; e_note int; e_by int;
    c_rows int; c_phase int; c_next int; c_note int; c_by int; c_status int;
  BEGIN
    -- ── (doors) ──
    PERFORM _as(U_PHYSIO);
    BEGIN
      INSERT INTO injury (school_id, player_id, injury_type, severity, date_injured) VALUES (V_HIL, BOY, 'Bruise', 'minor', T);
      PERFORM _assert(false, '§88 (doors): the physio inserted an injury row directly, around the door');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      UPDATE injury SET phase = 'cleared' WHERE player_id = BOY;
      PERFORM _assert(false, '§88 (doors): the physio updated an injury row directly, around the door');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      INSERT INTO injury_review (school_id, player_id, injury_id, reviewed_by, phase_after, restricted_after, next_review_on)
      SELECT i.school_id, i.player_id, i.id, U_PHYSIO, 'cleared', false, NULL FROM injury i LIMIT 1;
      PERFORM _assert(false, '§88 (doors): the physio inserted a review directly, around the door');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- ── (record) ──
    SELECT r.ok, r.reason, r.injury_id INTO v_ok, v_reason, I1
      FROM injury_record(BOY, 'Grade 1 hamstring strain', 'moderate', T - 1, true, T + 21, T + 14, false,
                         'V111 clinical: eccentric programme from day three.') r;
    PERFORM _assert(v_ok AND I1 IS NOT NULL, format('§88 (record): the physio could not record an injury (%s)', v_reason));
    j := _v111_injury(I1);
    PERFORM _assert((j->>'recorded_by')::uuid = U_PHYSIO AND j->>'phase' = 'active' AND (j->>'restricted')::boolean
                    AND (j->>'next_review_on')::date = T + 14 AND (j->>'rtw_date')::date = T + 21
                    AND NOT (j->>'emergency_services')::boolean AND j->>'dso_notified_at' IS NULL
                    AND j->>'physio' IS NULL AND j->>'notes' = 'V111 clinical: eccentric programme from day three.',
      format('§88 (record): the injury row is not what she recorded: %s', j));
    j := _v111_reviews(I1);
    PERFORM _assert(jsonb_array_length(j) = 1 AND (j->0->>'reviewed_by')::uuid = U_PHYSIO AND j->0->>'phase_after' = 'active'
                    AND (j->0->>'restricted_after')::boolean AND (j->0->>'next_review_on')::date = T + 14
                    AND (j->0->>'rtw_date_after')::date = T + 21 AND j->0->>'note' IS NULL
                    AND (j->0->>'is_recording')::boolean,
      format('§88 (record): the recording is not one review, by her, of the state recorded: %s', j));
    PERFORM _assert(_v111_notices(I1) = ARRAY['Injury recorded'],
      format('§88 (record): the recording wrote %s, not one "Injury recorded"', _v111_notices(I1)));
    PERFORM _assert(_v111_fitness(BOY) = 'injured', format('§88 (record): his fitness reads %s, not injured', _v111_fitness(BOY)));
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0, '§88 (record): a moderate injury wrote a safeguarding notice');

    -- ── (who) ──
    FOREACH k IN ARRAY ARRAY['coach', 'assistant', 'manager', 'coach20', 'director', 'principal', 'office', 'fitness',
                             'scorer', 'follower', 'enquirer', 'parent', 'boy', 'mate', 'wesphysio'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT r.ok, r.reason INTO v_ok, v_reason
        FROM injury_record(BOY, 'Side strain', 'minor', T, true, T + 7, T + 7, false, NULL) r;
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
        format('§88 (who): the %s recording an injury got %s / %s, not not_permitted', k, v_ok, v_reason));
      SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_review_record(I1, 'cleared', false, NULL, NULL, NULL) r;
      PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
        format('§88 (who): the %s reviewing an injury got %s / %s, not not_permitted', k, v_ok, v_reason));
    END LOOP;
    PERFORM _as(U_SUPER);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(BOY, 'Side strain', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted', format('§88 (who): the owner''s key recorded an injury (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(BOY, 'Side strain', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_signed_in', format('§88 (who): nobody signed in got %s', v_reason));
    PERFORM _assert(_v111_notices(I1) = ARRAY['Injury recorded'] AND jsonb_array_length(_v111_reviews(I1)) = 1,
      '§88 (who): a refused caller changed the record');

    -- ── (family) ──
    PERFORM _as(U_PHYSIO);
    SELECT r.injury_id INTO I_OWN FROM injury_record(OWN, 'Ankle sprain', 'minor', T - 2, true, T + 10, T + 20, false, NULL) r;
    PERFORM _as((y->>'mumphysio')::uuid);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(OWN, 'Shin splints', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'family_cannot_record',
      format('§88 (family): the physio who is his mother recorded an injury for her son (%s / %s)', v_ok, v_reason));
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_review_record(I_OWN, 'rehab', true, NULL, T + 7, 'Mum''s note') r;
    PERFORM _assert(NOT v_ok AND v_reason = 'family_cannot_record',
      format('§88 (family): the physio who is his mother reviewed her son''s injury (%s / %s)', v_ok, v_reason));
    SELECT r.ok, r.reason, r.injury_id INTO v_ok, v_reason, I_MATE
      FROM injury_record(MATE, 'Bruised thumb', 'minor', T - 1, true, T + 5, T + 3, false, NULL) r;
    PERFORM _assert(v_ok AND I_MATE IS NOT NULL, format('§88 (family): the mother-physio could not record another boy (%s)', v_reason));
    PERFORM _as((y->>'claimphysio')::uuid);
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(BOY, 'Side strain', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'family_cannot_record',
      format('§88 (family): a physio with a pending guardian claim on the boy recorded for him (%s / %s)', v_ok, v_reason));
    PERFORM _assert(jsonb_array_length(_v111_reviews(I_OWN)) = 1, '§88 (family): the refused review was written');

    -- ── (rules) ──
    PERFORM _as(U_PHYSIO);
    FOR k, v_reason IN
      SELECT x.label, (SELECT r.reason FROM injury_record(x.p, x.t, x.s, x.d, true, x.rtw, x.nxt, false, NULL) r)
        FROM (VALUES ('next_review_required',   BOY, 'Side strain', 'minor', T,     T + 7,  NULL::date),
                     ('next_review_in_past',    BOY, 'Side strain', 'minor', T,     T + 7,  T - 1),
                     ('date_injured_in_future', BOY, 'Side strain', 'minor', T + 1, T + 7,  T + 7),
                     ('date_injured_required',  BOY, 'Side strain', 'minor', NULL,  T + 7,  T + 7),
                     ('severity_invalid',       BOY, 'Side strain', 'mild',  T,     T + 7,  T + 7),
                     ('injury_type_required',   BOY, '   ',         'minor', T,     T + 7,  T + 7),
                     ('return_before_injury',   BOY, 'Side strain', 'minor', T - 1, T - 5,  T + 7),
                     ('no_such_player',         gen_random_uuid(), 'Side strain', 'minor', T, T + 7, T + 7))
             AS x(label, p, t, s, d, rtw, nxt) LOOP
      PERFORM _assert(v_reason = k, format('§88 (rules): a record that should be %s was answered %s', k, coalesce(v_reason, 'ok')));
    END LOOP;

    -- ── (module) ──
    PERFORM _v111_hide(U_PHYSIO, true);
    SELECT r.reason INTO v_reason FROM injury_record(BOY, 'Side strain', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(v_reason = 'module_off', format('§88 (module): with Injuries off for her, a record got %s', coalesce(v_reason, 'ok')));
    SELECT r.reason INTO v_reason FROM injury_review_record(I1, 'rehab', NULL, NULL, T + 7, NULL) r;
    PERFORM _assert(v_reason = 'module_off', format('§88 (module): with Injuries off for her, a review got %s', coalesce(v_reason, 'ok')));
    PERFORM _v111_hide(U_PHYSIO, false);

    -- ── (review) ──
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_review_record(I1, 'rehab', NULL, NULL, T + 7, 'V111: strengthening, week two.') r;
    PERFORM _assert(v_ok, format('§88 (review): the physio could not review to rehab (%s)', v_reason));
    j := _v111_injury(I1);
    PERFORM _assert(j->>'phase' = 'rehab' AND (j->>'restricted')::boolean AND (j->>'rtw_date')::date = T + 21
                    AND (j->>'next_review_on')::date = T + 7,
      format('§88 (review): rehab did not reach the injury row, or moved what it was not given: %s', j));
    j := _v111_reviews(I1);
    PERFORM _assert(jsonb_array_length(j) = 2 AND (j->1->>'restricted_after')::boolean AND (j->1->>'rtw_date_after')::date = T + 21
                    AND NOT (j->1->>'is_recording')::boolean,
      format('§88 (review): the review row does not state the whole state after it: %s', j->1));
    PERFORM _assert(_v111_fitness(BOY) = 'rehab', format('§88 (fitness): in rehab his fitness reads %s', _v111_fitness(BOY)));
    PERFORM _assert(_v111_notices(I1) = ARRAY['Injury recorded'],
      format('§88 (review): a phase step wrote a notice: %s', _v111_notices(I1)));
    FOR k, v_reason IN
      SELECT x.label, (SELECT r.reason FROM injury_review_record(I1, x.ph, x.restr, NULL, x.nxt, NULL) r)
        FROM (VALUES ('next_review_required',       'rehab',     NULL::boolean, NULL::date),
                     ('phase_invalid',              'returning', NULL,          T + 7),
                     ('cleared_is_not_restricted',  'cleared',   true,          NULL),
                     ('cleared_has_no_next_review', 'cleared',   false,         T + 7),
                     ('next_review_in_past',        'active',    NULL,          T - 1)) AS x(label, ph, restr, nxt) LOOP
      PERFORM _assert(v_reason = k, format('§88 (review): a review that should be %s was answered %s', k, coalesce(v_reason, 'ok')));
    END LOOP;
    PERFORM _assert(jsonb_array_length(_v111_reviews(I1)) = 2, '§88 (review): a refused review was written');
    SELECT r.ok INTO v_ok FROM injury_review_record(I1, 'rehab', true, T + 28, T + 7, NULL) r;
    PERFORM _assert(v_ok AND _v111_notices(I1) = ARRAY['Injury recorded', 'Return date updated'],
      format('§88 (review): moving the return date wrote %s', _v111_notices(I1)));
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_review_record(I1, 'cleared', NULL, NULL, NULL, 'V111: cleared, full training.') r;
    PERFORM _assert(v_ok, format('§88 (review): the physio could not clear him (%s)', v_reason));
    j := _v111_injury(I1);
    PERFORM _assert(j->>'phase' = 'cleared' AND NOT (j->>'restricted')::boolean AND j->>'next_review_on' IS NULL,
      format('§88 (review): clearing did not unrestrict him and end the clock: %s', j));
    PERFORM _assert(_v111_notices(I1) = ARRAY['Cleared to play', 'Injury recorded', 'Return date updated'],
      format('§88 (review): clearing wrote %s', _v111_notices(I1)));
    PERFORM _assert(_v111_fitness(BOY) = 'fit', format('§88 (fitness): cleared, his fitness reads %s', _v111_fitness(BOY)));
    SELECT r.reason INTO v_reason FROM injury_review_record(I1, 'rehab', true, NULL, T + 7, NULL) r;
    PERFORM _assert(v_reason = 'injury_cleared', format('§88 (review): a cleared injury was reviewed again (%s)', coalesce(v_reason, 'ok')));
    SELECT r.reason INTO v_reason FROM injury_review_record(gen_random_uuid(), 'rehab', true, NULL, T + 7, NULL) r;
    PERFORM _assert(v_reason = 'no_such_injury', format('§88 (review): an injury that is not there got %s', coalesce(v_reason, 'ok')));
    PERFORM _assert(jsonb_array_length(_v111_reviews(I1)) = 4 AND _v111_sg_count(V_HIL) = sg0,
      '§88 (review): the story is not four reviews and no safeguarding notice');

    -- ── (reopen) ──
    SELECT r.ok, r.reason, r.injury_id INTO v_ok, v_reason, I_RECUR
      FROM injury_record(BOY, 'Grade 1 hamstring strain, again', 'moderate', T, true, T + 21, T + 14, false, NULL, I1) r;
    PERFORM _assert(v_ok AND (_v111_injury(I_RECUR)->>'recurs_injury_id')::uuid = I1,
      format('§88 (reopen): the recurrence does not name the cleared injury (%s)', v_reason));
    SELECT r.reason INTO v_reason FROM injury_record(BOY, 'Bruise', 'minor', T, true, T + 7, T + 7, false, NULL, I_MATE) r;
    PERFORM _assert(v_reason = 'recurs_not_his', format('§88 (reopen): another boy''s injury was named as his (%s)', coalesce(v_reason, 'ok')));
    SELECT r.reason INTO v_reason FROM injury_record(BOY, 'Bruise', 'minor', T, true, T + 7, T + 7, false, NULL, I_RECUR) r;
    PERFORM _assert(v_reason = 'recurs_an_open_injury', format('§88 (reopen): an open injury was named as recurring (%s)', coalesce(v_reason, 'ok')));
    PERFORM _assert(_v111_fitness(BOY) = 'injured', format('§88 (fitness): injured again, his fitness reads %s', _v111_fitness(BOY)));

    -- ── (key) ──
    PERFORM _assert(_v111_mismatch(I_RECUR, MATE) = '23503',
      format('§88 (key): a review naming the boy''s injury and his team-mate was not refused by the key (%s)', _v111_mismatch(I_RECUR, MATE)));

    -- ── review dated before the last ──
    PERFORM _v111_future_review(I_MATE);
    PERFORM _as((y->>'mumphysio')::uuid);
    SELECT r.reason INTO v_reason FROM injury_review_record(I_MATE, 'rehab', true, NULL, T + 3, NULL) r;
    PERFORM _assert(v_reason = 'review_before_last', format('§88 (review): a review behind the last one got %s', coalesce(v_reason, 'ok')));
    PERFORM _as(U_PHYSIO);

    -- ── (fitness) 'unavailable' for another reason is left ──
    SELECT r.injury_id INTO I_U FROM injury_record(REST, 'Blister', 'minor', T, true, T + 3, T + 3, false, NULL) r;
    PERFORM _v111_set_fitness(REST, 'unavailable');
    SELECT r.ok INTO v_ok FROM injury_review_record(I_U, 'cleared', false, NULL, NULL, NULL) r;
    PERFORM _assert(v_ok AND _v111_fitness(REST) = 'unavailable',
      format('§88 (fitness): clearing his last injury wrote %s over unavailable', _v111_fitness(REST)));

    -- ── (tiers) the boy's five reviews: I1's four, I_RECUR's one ──
    -- Two carry a note (the rehab step and the clearance); four a next review
    -- (all but the clearance).
    FOR k, e_rows, e_phase, e_note, e_by IN
      SELECT x.who, x.r, x.ph, x.nt, x.b FROM (VALUES
        ('physio', 5, 5, 2, 5), ('parent', 5, 5, 2, 5), ('boy', 5, 5, 2, 5),
        ('coach', 5, 5, 0, 0), ('assistant', 5, 5, 0, 0), ('manager', 5, 5, 0, 0), ('director', 5, 5, 0, 0),
        ('office', 5, 5, 0, 0), ('fitness', 5, 5, 0, 0),
        -- READERS Q9 (db/116): the principal reads the nature tier again.
        ('principal', 5, 5, 0, 0), ('enquirer', 5, 0, 0, 0),
        ('coach20', 0, 0, 0, 0), ('mate', 0, 0, 0, 0), ('scorer', 0, 0, 0, 0), ('follower', 0, 0, 0, 0),
        ('wesphysio', 0, 0, 0, 0), ('dso', 0, 0, 0, 0)) AS x(who, r, ph, nt, b) LOOP
      PERFORM _as(CASE WHEN k = 'dso' THEN U_DSO ELSE (y->>k)::uuid END);
      SELECT count(*)::int, count(phase_after)::int, count(next_review_on)::int, count(note)::int, count(reviewed_by)::int,
             (count(reviewed_at) + count(restricted_after))::int
        INTO c_rows, c_phase, c_next, c_note, c_by, c_status
        FROM injury_review_masked WHERE player_id = BOY;
      PERFORM _assert(c_rows = e_rows AND c_phase = e_phase AND c_next = CASE WHEN e_phase = 5 THEN 4 ELSE 0 END
                      AND c_note = e_note AND c_by = e_by AND c_status = 2 * e_rows,
        format('§88 (tiers): the %s reads %s reviews of the boy, %s phases, %s next reviews, %s notes, %s authors (expected %s, %s, %s, %s)',
               k, c_rows, c_phase, c_next, c_note, c_by, e_rows, e_phase, e_note, e_by));
      SELECT count(*)::int INTO c_rows FROM injury_review WHERE player_id = BOY;
      PERFORM _assert(c_rows = e_rows, format('§88 (tiers): the %s reads %s rows of the table, not %s', k, c_rows, e_rows));
      -- is_recording is the status tier's: the two recordings (I1's, I_RECUR's), to every reader of a row.
      SELECT count(*) FILTER (WHERE is_recording)::int INTO c_rows FROM injury_review_masked WHERE player_id = BOY;
      PERFORM _assert(c_rows = CASE WHEN e_rows = 5 THEN 2 ELSE 0 END,
        format('§88 (tiers): the %s reads %s recordings among the boy''s reviews', k, c_rows));
      -- injury_masked's new columns, on the open recurrence.
      SELECT count(*)::int, count(next_review_on)::int, count(emergency_services)::int, count(recorded_by)::int,
             count(recurs_injury_id)::int, count(rtw_date)::int
        INTO c_rows, c_next, c_phase, c_by, c_note, c_status
        FROM injury_masked WHERE id = I_RECUR;
      PERFORM _assert(c_rows = sign(e_rows) AND c_next = sign(e_phase) AND c_phase = sign(e_phase) AND c_by = sign(e_by)
                      AND c_note = sign(e_rows) AND c_status = sign(e_rows),
        format('§88 (tiers): the %s reads injury_masked''s new columns wrong (row %s, next %s, emergency %s, author %s, recurs %s, return %s)',
               k, c_rows, c_next, c_phase, c_by, c_note, c_status));
    END LOOP;

    -- ── (principal) status and nature (READERS Q9, 21 Oct 2026; db/116) ──
    -- That the boy is out, since when and until when, his fitness word, and
    -- what is wrong, how bad, the phase and the physio's next date; never the
    -- clinical details tier.
    PERFORM _as((y->>'principal')::uuid);
    SELECT count(*)::int, count(injury_type)::int + count(severity)::int + count(phase)::int
                          + count(next_review_on)::int + count(emergency_services)::int,
           count(restricted)::int + count(rtw_date)::int + count(date_injured)::int
      INTO c_rows, c_phase, c_status
      FROM injury_masked WHERE id = I_RECUR;
    PERFORM _assert(c_rows = 1 AND c_phase = 5 AND c_status = 3,
      format('§88 (principal): the principal reads the recurrence as %s row, %s of 5 nature columns and %s of 3 status columns', c_rows, c_phase, c_status));
    SELECT fitness INTO got FROM player_masked WHERE id = BOY;
    PERFORM _assert(got = 'injured', format('§88 (principal): the principal reads the boy''s fitness as %s, not injured', coalesce(got, 'null')));
    PERFORM _assert(app_can('medical.nature.read', V_HIL, '12XI', BOY, '00000000-0000-0000-0000-000000000000'::uuid)
                    AND NOT app_can('medical.details.read', V_HIL, '12XI', BOY, '00000000-0000-0000-0000-000000000000'::uuid),
      '§88 (principal): the principal lacks medical.nature.read (READERS Q9), or holds medical.details.read');

    -- ── (worklist) ──
    PERFORM _as(U_PHYSIO);
    SELECT r.injury_id INTO I_OVER FROM injury_record(SIDE, 'Calf strain', 'minor', T - 3, true, T + 30, T + 10, false, NULL) r;
    PERFORM _v111_edit(I_OVER, T - 2, T + 30);
    SELECT r.injury_id INTO I_RET FROM injury_record(SIDE, 'Groin strain', 'minor', T - 6, true, T + 5, T + 20, false, NULL) r;
    PERFORM injury_review_record(I_RET, 'rehab', true, NULL, T + 20, NULL);
    PERFORM _v111_edit(I_RET, T + 20, T - 1);
    SELECT r.injury_id INTO I_NORTW FROM injury_record(OWN, 'Stress reaction, lower back', 'moderate', T - 4, true, NULL, T + 20, false, NULL) r;
    PERFORM injury_review_record(I_NORTW, 'rehab', true, NULL, T + 20, NULL);
    SELECT r.injury_id INTO I_QUIET FROM injury_record(SIDE, 'Finger sprain', 'minor', T - 2, true, T + 30, T + 20, false, NULL) r;
    PERFORM injury_review_record(I_QUIET, 'rehab', true, NULL, T + 20, NULL);
    SELECT r.injury_id INTO I_LEFT FROM injury_record(LEAVER, 'Knee sprain', 'minor', T - 1, true, T + 9, T + 3, false, NULL) r;
    PERFORM _assert(I_OVER IS NOT NULL AND I_RET IS NOT NULL AND I_NORTW IS NOT NULL AND I_QUIET IS NOT NULL AND I_LEFT IS NOT NULL,
      '§88 (worklist): an injury was not staged');
    SELECT w.reason INTO got FROM injury_worklist() w WHERE w.injury_id = I_LEFT;
    PERFORM _assert(got = 'due', format('§88 (worklist): before he leaves, the leaver''s injury reads %s', coalesce(got, 'absent')));
    PERFORM _assert(_v111_leave(LEAVER) = 1, '§88 (worklist): the leaver had no open membership to close');
    FOR k, got, j IN
      SELECT x.label, x.want, x.clock FROM (VALUES
        ('I_OVER',  'overdue',        jsonb_build_object('due', T - 2, 'over', 2, 'since', T - 2)),
        ('I_RET',   'return_passed',  jsonb_build_object('due', T - 1, 'over', 1, 'since', T - 1)),
        ('I_MATE',  'due',            jsonb_build_object('due', T + 3, 'over', 0)),
        ('I_NORTW', 'no_return_date', jsonb_build_object('due', T + 20, 'over', 0, 'since', 'last_review')),
        ('I_RECUR', 'new',            jsonb_build_object('due', T + 14, 'over', 0, 'since', 'last_review')),
        ('I_OWN',   'new',            jsonb_build_object('due', T + 20, 'over', 0, 'since', 'last_review')),
        ('I_QUIET', NULL,             NULL),
        ('I_LEFT',  NULL,             NULL),
        ('I1',      NULL,             NULL)) AS x(label, want, clock) LOOP
      v_id := CASE k WHEN 'I_OVER' THEN I_OVER WHEN 'I_RET' THEN I_RET WHEN 'I_MATE' THEN I_MATE WHEN 'I_NORTW' THEN I_NORTW
                     WHEN 'I_RECUR' THEN I_RECUR WHEN 'I_OWN' THEN I_OWN WHEN 'I_QUIET' THEN I_QUIET
                     WHEN 'I_LEFT' THEN I_LEFT ELSE I1 END;
      SELECT count(*)::int, max(w.reason), max(w.due_on - T), max(w.days_over), max(w.since - T)
        INTO n, v_reason, c_rows, c_phase, e_rows
        FROM injury_worklist() w WHERE w.injury_id = v_id;
      IF got IS NULL THEN
        PERFORM _assert(n = 0, format('§88 (worklist): %s is on the physio''s list as %s', k, v_reason));
      ELSE
        PERFORM _assert(n = 1 AND v_reason = got, format('§88 (worklist): %s reads %s (%s rows), not %s', k, coalesce(v_reason, 'absent'), n, got));
        -- 'last_review': the day of the injury's latest review, from the row's
        -- own reviewed_at, in Johannesburg. Not T: T is sa_today() at the
        -- transaction's start, and the doors stamp clock_timestamp(), so a run
        -- that crosses midnight in South Africa reviewed "tomorrow".
        PERFORM _assert(T + c_rows = (j->>'due')::date AND c_phase = (j->>'over')::int
                        AND (NOT j ? 'since'
                             OR T + e_rows = CASE WHEN j->>'since' = 'last_review'
                                                  THEN (SELECT (max((r->>'reviewed_at')::timestamptz) AT TIME ZONE 'Africa/Johannesburg')::date
                                                          FROM jsonb_array_elements(_v111_reviews(v_id)) r)
                                                  ELSE (j->>'since')::date END),
          format('§88 (worklist): %s''s clock reads due %s, over %s, since %s, not %s', k, T + c_rows, c_phase, T + e_rows, j));
      END IF;
    END LOOP;
    SELECT to_jsonb(array_agg(x.injury_id ORDER BY x.ord)) INTO j
      FROM injury_worklist() WITH ORDINALITY AS x(injury_id, school_id, player_id, reason, since, due_on, days_over, ord)
     WHERE x.injury_id IN (I_OVER, I_RET, I_MATE, I_NORTW, I_RECUR);
    PERFORM _assert(j = to_jsonb(ARRAY[I_OVER, I_RET, I_MATE, I_NORTW, I_RECUR]),
      format('§88 (worklist): the list is not overdue, return passed, due, no return date, new: %s', j));
    -- READERS_child_data Q3 (db/116, §93): ACCOUNT_LIFECYCLE Q9 over GA-I19
    -- D11. Once he has left, his clinical record is the office's and his
    -- family's, not the physio's; the row itself is untouched (below).
    SELECT count(*)::int INTO n FROM injury_masked WHERE id = I_LEFT;
    PERFORM _assert(n = 0, '§88 (worklist): the physio still reads the injury of the boy who left (READERS Q3)');
    -- (left) the "left the school" mark, under each reader's own RLS: the day
    -- he left to the physio, his coach and the principal (status tier); NULL
    -- for a boy still there; NULL to a reader of neither (20XI's coach).
    FOREACH k IN ARRAY ARRAY['physio', 'coach', 'principal', 'coach20'] LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(injury_left_on(LEAVER, V_HIL) IS NOT DISTINCT FROM CASE WHEN k = 'coach20' THEN NULL ELSE T END
                      AND injury_left_on(BOY, V_HIL) IS NULL,
        format('§88 (left): the %s reads the leaver as left on %s and the boy as left on %s', k,
               injury_left_on(LEAVER, V_HIL), injury_left_on(BOY, V_HIL)));
    END LOOP;
    PERFORM _as(U_PHYSIO);
    PERFORM _assert((_v111_injury(I_LEFT)->>'phase') = 'active', '§88 (worklist): leaving changed his injury row');
    PERFORM _as((y->>'mumphysio')::uuid);
    SELECT count(*) FILTER (WHERE w.injury_id IN (I_NORTW, I_OWN))::int, count(*) FILTER (WHERE w.injury_id = I_RECUR)::int
      INTO n, c_rows FROM injury_worklist() w;
    PERFORM _assert(n = 0 AND c_rows = 1, format('§88 (worklist): the mother-physio''s list holds %s of her son''s injuries and %s of the boy''s', n, c_rows));
    PERFORM _as((y->>'claimphysio')::uuid);
    SELECT count(*) FILTER (WHERE w.injury_id = I_RECUR)::int, count(*) FILTER (WHERE w.injury_id = I_OWN)::int
      INTO n, c_rows FROM injury_worklist() w;
    PERFORM _assert(n = 0 AND c_rows = 1, format('§88 (worklist): the claiming physio''s list holds %s of the boy''s and %s of another', n, c_rows));
    FOREACH k IN ARRAY ARRAY['coach', 'assistant', 'manager', 'coach20', 'director', 'principal', 'office', 'fitness',
                             'scorer', 'follower', 'enquirer', 'parent', 'boy', 'mate', 'owner', 'dso'] LOOP
      PERFORM _as(CASE k WHEN 'owner' THEN U_SUPER WHEN 'dso' THEN U_DSO ELSE (y->>k)::uuid END);
      SELECT count(*)::int INTO n FROM injury_worklist();
      PERFORM _assert(n = 0, format('§88 (worklist): the %s reads %s worklist rows', k, n));
    END LOOP;
    PERFORM _as((y->>'wesphysio')::uuid);
    SELECT count(*)::int INTO n FROM injury_worklist() w WHERE w.school_id = V_HIL;
    PERFORM _assert(n = 0, format('§88 (worklist): Westville''s physio reads %s of Hilton''s worklist', n));

    -- ── (support) ──
    -- sportsadmin, not schooladmin: earlier sections leave the platform's own
    -- schooladmin session at Hilton live in this transaction (already_live).
    FOREACH k IN ARRAY ARRAY['medical', 'sportsadmin'] LOOP
      PERFORM _as(U_PLAT);
      SELECT r.ok, r.id, r.reason INTO v_ok, v_sid, v_reason FROM support_access_begin(V_HIL, k, 'v111: the injuries screen will not load') r;
      PERFORM _assert(v_ok, format('§88 (support): a support session as %s did not begin (%s)', k, v_reason));
      SELECT count(*)::int INTO n FROM injury_review;
      SELECT count(*)::int INTO c_rows FROM injury_review_masked;
      SELECT count(*)::int INTO c_phase FROM injury_masked WHERE player_id = BOY;
      PERFORM _assert(n = 0 AND c_rows = 0, format('§88 (support): a support session as %s reads %s reviews (%s through the view)', k, n, c_rows));
      PERFORM _assert(c_phase = 2, format('§88 (support): a support session as %s reads %s of the boy''s injury rows, not 2 (Q7: as today)', k, c_phase));
      SELECT count(*)::int INTO n FROM injury_worklist();
      PERFORM _assert(n = 0, format('§88 (support): a support session as %s reads %s worklist rows', k, n));
      SELECT r.reason INTO v_reason FROM injury_record(BOY, 'Side strain', 'minor', T, true, T + 7, T + 7, false, NULL) r;
      PERFORM _assert(v_reason = 'not_under_support', format('§88 (support): a support session as %s recording got %s', k, coalesce(v_reason, 'ok')));
      SELECT r.reason INTO v_reason FROM injury_review_record(I_RECUR, 'rehab', true, NULL, T + 7, NULL) r;
      PERFORM _assert(v_reason = 'not_under_support', format('§88 (support): a support session as %s reviewing got %s', k, coalesce(v_reason, 'ok')));
      PERFORM support_access_end(v_sid);
    END LOOP;
    PERFORM _assert(jsonb_array_length(_v111_reviews(I_RECUR)) = 1, '§88 (support): a support session wrote a review');

    -- ── (sg12) ──
    PERFORM _as(U_PHYSIO);
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0, '§88 (sg12): nothing serious has been recorded, and a safeguarding notice was written');
    SELECT r.injury_id INTO I_SEV FROM injury_record(SIDE, 'Compound wrist fracture', 'severe', T, true, T + 60, T + 7, false, NULL) r;
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 1, format('§88 (sg12): a severe record wrote %s safeguarding notices', _v111_sg_count(V_HIL) - sg0));
    PERFORM _assert(_v111_injury(I_SEV)->>'dso_notified_at' IS NOT NULL, '§88 (sg12): the once-guard was not stamped');
    PERFORM _as(U_DSO);
    SELECT count(*)::int, max(x.title), max(x.body),
           bool_and(x.subject_id IS NULL AND x.subject_person_id IS NULL AND x.subject_kind IS NULL AND x.team_code IS NULL
                    AND x.recipient_id IS NULL AND x.scope_level = 'school' AND x.urgency = 'high' AND NOT x.is_public
                    AND x.required_capability = 'safeguarding.concern.read' AND x.school_id = V_HIL)
      INTO n, got, v_reason, v_ok
      FROM notification x WHERE x.kind = 'safeguarding' AND x.title = 'A serious injury has been recorded';
    PERFORM _assert(n = 1 AND v_ok, format('§88 (sg12): the DSO reads %s serious-injury notices, shaped %s', n, v_ok));
    PERFORM _assert(v_reason = 'A pupil at your school has had a serious injury recorded by the physio today. This is for your awareness under CSA''s Safeguarding Policy; the clinical record stays with the physio. Raise a concern if there is a safeguarding question.',
      format('§88 (sg12): the notice''s words are not D10''s: %s', v_reason));
    PERFORM _assert(got || v_reason !~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
                    AND got || v_reason !~* '(Verify|OneEleven|Otherside|fracture|wrist|compound)',
      '§88 (sg12): the notice names a child, an id or a diagnosis');
    SELECT count(*)::int INTO n FROM injury;
    SELECT count(*)::int INTO c_rows FROM injury_review;
    PERFORM _assert(n = 0 AND c_rows = 0, format('§88 (sg12): the DSO reads %s injuries and %s reviews', n, c_rows));
    FOREACH k IN ARRAY ARRAY['physio', 'coach20', 'director'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*)::int INTO n FROM notification WHERE kind = 'safeguarding';
      PERFORM _assert(n = 0, format('§88 (sg12): the %s reads %s safeguarding notices', k, n));
    END LOOP;
    PERFORM _as((y->>'coach20')::uuid);
    SELECT count(*)::int INTO n FROM notification WHERE kind = 'injury' AND subject_id = I_SEV;
    PERFORM _assert(n = 1, format('§88 (sg12): the side''s coach reads %s "Injury recorded" notices for it (notify_injury unchanged)', n));
    PERFORM _v111_serious(I_SEV, 'severe', true);
    PERFORM _as(U_PHYSIO);
    PERFORM injury_review_record(I_SEV, 'rehab', true, NULL, T + 7, NULL);
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 1, '§88 (sg12): a second edit or a review wrote a second notice');
    SELECT r.injury_id INTO I_MOD FROM injury_record(SIDE, 'Shoulder dislocation', 'moderate', T, true, T + 30, T + 7, false, NULL) r;
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 1, '§88 (sg12): a moderate record wrote a notice');
    PERFORM _v111_serious(I_MOD, 'severe', false);
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 2, '§88 (sg12): made severe, it wrote no notice');
    PERFORM _v111_serious(I_MOD, 'severe', true);
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 2, '§88 (sg12): told twice about one injury');
    -- Eased, then made severe again: told once (the stamp).
    PERFORM _v111_serious(I_MOD, 'moderate', false);
    PERFORM _v111_serious(I_MOD, 'severe', false);
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 2, '§88 (sg12): made severe a second time, the DSO was told twice');
    -- Serious before db/111 ran, and never stamped: a later edit tells nobody
    -- (the notice is for an injury that BECOMES serious).
    v_id := _v111_legacy_severe(SIDE);
    PERFORM _v111_serious(v_id, 'severe', true);
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 2, '§88 (sg12): an edit to an injury already serious before db/111 told the DSO');
    SELECT r.injury_id INTO I_EMS FROM injury_record(SIDE, 'Concussion, ambulance called', 'minor', T, true, T + 14, T + 2, true, NULL) r;
    PERFORM _assert(_v111_sg_count(V_HIL) = sg0 + 3, '§88 (sg12): emergency services called wrote no notice');
    PERFORM _as(U_DSO);
    SELECT count(*)::int INTO n FROM notification WHERE kind = 'safeguarding' AND title = 'A serious injury has been recorded';
    PERFORM _assert(n = 3, format('§88 (sg12): the DSO reads %s of the three', n));

    -- ── (retention) ──
    PERFORM _assert(_v111_due(BOY) IS NULL, format('§88 (retention): at school, his record is due %s', _v111_due(BOY)));
    PERFORM _assert(_v111_due(LEAVER) = (T + interval '12 months')::date,
      format('§88 (retention): left today, his record is due %s', _v111_due(LEAVER)));

    -- ── (agree) every door-written injury's state is its latest review's ──
    FOREACH v_id IN ARRAY ARRAY[I1, I_RECUR, I_OWN, I_MATE, I_NORTW, I_QUIET, I_LEFT, I_SEV, I_MOD, I_EMS] LOOP
      j := _v111_injury(v_id);
      PERFORM _assert((SELECT z.r->>'phase_after' = j->>'phase' AND (z.r->>'restricted_after')::boolean = (j->>'restricted')::boolean
                              AND z.r->>'rtw_date_after' IS NOT DISTINCT FROM j->>'rtw_date'
                              AND z.r->>'next_review_on' IS NOT DISTINCT FROM j->>'next_review_on'
                         FROM (SELECT _v111_reviews(v_id) -> -1 AS r) z),
        format('§88 (agree): injury %s and its latest review disagree', j->>'injury_type'));
    END LOOP;
    -- Of the boys still at the school: I_LEFT is the leaver's, whom this
    -- section moved off his side above (_v111_leave), and since db/116
    -- (READERS Q3) a departed boy's reviews are the office's and his family's,
    -- not the physio's. She reads none of his.
    PERFORM _as(U_PHYSIO);
    SELECT count(*)::int INTO n FROM injury_review_masked
     WHERE injury_id IN (I1, I_RECUR, I_OWN, I_MATE, I_NORTW, I_QUIET, I_SEV, I_MOD, I_EMS, I_OVER, I_RET, I_U);
    SELECT sum(jsonb_array_length(_v111_reviews(x)))::int INTO c_rows
      FROM unnest(ARRAY[I1, I_RECUR, I_OWN, I_MATE, I_NORTW, I_QUIET, I_SEV, I_MOD, I_EMS, I_OVER, I_RET, I_U]) x;
    PERFORM _assert(n = c_rows AND n > 0, format('§88 (agree): the physio reads %s of the %s reviews of boys at her school', n, c_rows));
    SELECT count(*)::int INTO n FROM injury_review_masked WHERE injury_id = I_LEFT;
    PERFORM _assert(n = 0 AND jsonb_array_length(_v111_reviews(I_LEFT)) > 0,
      format('§88 (agree): the physio reads %s review(s) of the boy who left (READERS Q3)', n));

    -- ── (doors2) ──
    PERFORM _assert((SELECT bool_and(prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(proconfig, '{}')))
                       FROM pg_proc WHERE oid IN (to_regprocedure('injury_record(uuid,text,text,date,boolean,date,date,boolean,text,uuid)'),
                                                  to_regprocedure('injury_review_record(uuid,text,boolean,date,date,text)'),
                                                  to_regprocedure('injury_apply_review()'), to_regprocedure('injury_serious_watch()'),
                                                  to_regprocedure('injury_retention_due(uuid)'))),
      '§88 (doors2): a door or a trigger is not a pinned SECURITY DEFINER');
    PERFORM _assert((SELECT NOT prosecdef FROM pg_proc WHERE oid = to_regprocedure('injury_worklist()')),
      '§88 (doors2): the worklist runs as its owner, past the caller''s RLS');
    PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure('injury_record(uuid,text,text,date,boolean,date,date,boolean,text,uuid)'), 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', to_regprocedure('injury_review_record(uuid,text,boolean,date,date,text)'), 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', to_regprocedure('injury_worklist()'), 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', to_regprocedure('injury_retention_due(uuid)'), 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', to_regprocedure('injury_write_refusal(uuid,uuid)'), 'EXECUTE'),
      '§88 (doors2): the application cannot call its doors, or can call an internal');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a
                                 WHERE p.proname IN ('injury_record', 'injury_review_record', 'injury_worklist', 'injury_writer_is_family',
                                                     'injury_write_refusal', 'injury_apply_review', 'injury_serious_watch', 'injury_retention_due')
                                   AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
      '§88 (doors2): PUBLIC may call one of db/111''s functions');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_roles g, pg_proc p WHERE g.rolname IN ('anon', 'authenticated')
                                   AND p.proname IN ('injury_record', 'injury_review_record', 'injury_worklist')
                                   AND has_function_privilege(g.oid, p.oid, 'EXECUTE')),
      '§88 (doors2): a managed host''s API role can call a door');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 88
  -- └── db/111 (section 88) ──────────────────────────────────────────
  -- ┌── db/112 (section 89) ──────────────────────────────────────────
  -- ── 89. A moved pupil follows his new side (SR-1); the boy playing up reads his match's balls ──
  -- docs/design/SEASON_ROLLOVER.md §1.2 and §8 (Kameel, 15 Oct 2026, as
  -- recommended), and the playing-up ball log (Kameel, 15 Oct 2026: yes).
  -- Every move below is the office's own UPDATE of player.team_code, through
  -- scrbrd_app, as the move route (roster-api.mjs) writes it; _v112_stage()
  -- and the _v112_ helpers stage and read as the owner. The HTTP half is
  -- tools/smoke-player-move.mjs.
  --
  -- What each label holds:
  --   (before)     on U14E, mb reads U14E's fixture, nets, plan and balls and
  --                none of U15E's
  --   (carry)      the office moves mb to U15E: his account's `player` row on
  --                U14E is ended (kept, stamped with the office and the time)
  --                and one is opened on U15E, made by the office; the history
  --                trigger's row beside it; his self-access row, its link and
  --                his mother's row and link untouched. The same for sb, whose
  --                account is his only by a verified self-access link
  --   (reads)      after the move mb reads U15E's fixture, nets, plan and
  --                balls and none of U14E's; his mother reads the same side
  --   (whose)      a would-be account whose self-access claim is pending, and
  --                an account that is also another boy, are not carried
  --   (none)       the office moves nb to no side: the move is made, his row
  --                on U14E is ended, kept, and none is opened; no live
  --                `player` row names no side; he reads none of U14E's
  --   (idempotent) the moves leave no row out of step but those earlier
  --                sections staged so; the one-time correction, after moves
  --                made before this file (the carry switched off) and rows
  --                written by hand: it carries each boy once (tm ended 1 and
  --                opened 1 on his side, mb's stray row ended, nb's ended: he
  --                has no side), and the earlier sections' too; nothing then
  --                disagrees, and a second run changes nothing at all; the
  --                seed's two `player` rows (R Pillay's, and spectator@'s, no
  --                boy's) are as they were
  --   (playing up) up reads every ball of f16a (home) and f16w (away), the
  --                matches he is on the sheet of, and none of f16b, the older
  --                side's other match; and his own side's f14 as before. His
  --                team-mate on no sheet reads none of the older side's
  --   (withdrawn)  wd, withdrawn from f16a, reads none of it: no fixture, no
  --                ball; his own side's as before
  --   (guardians)  for every person whose every live role is a guardian's, the
  --                new branch is empty and the balls read are db/100's three
  --                branches exactly; up's mother reads f16a's and f16w's
  --                balls by db/100's sheet branch, as before
  --   (agree)      for every person holding an assignment and every scored
  --                fixture, ball_event_read admits exactly db/100's three
  --                branches or the boy himself on the sheet (db/106 (e)
  --                spelled out apart, _v106_self_sheet())
  --   (check)      db/108's CHECK as written and validated, no live team-less
  --                `player` row, role_request_grant_as() db/92's body with
  --                db/108's block (its md5 guard), my_child_fixtures() db/100's
  --   (doors)      the trigger enabled; the five SR-1 functions pinned
  --                definers no one but the owner may call; the sheet helper
  --                scrbrd_app's alone
  --
  -- Falsified on 16 Oct 2026, each change made as the owner in the same
  -- transaction before this section ran (so a ROLLBACK put it back), each
  -- red, and green again without it:
  --   the trigger disabled (no carry)               → (carry) red: "after the
  --                                                    move mb's account holds
  --                                                    U14E:live"
  --   the carry opening the new row whatever the    → (none) red: "the move to
  --     side (carry to NULL)                           no side was refused:
  --                                                    role_assignment_player_
  --                                                    team_scoped"
  --   my_own_sheet_fixtures() without the sheet     → (before) red: mb, on no
  --     (every fixture at his school's ends)           sheet, read the balls of
  --                                                    f14 f15 f16a f16b f16w
  --   my_own_sheet_fixtures() without NOT withdrawn → (withdrawn) red: wd read
  --                                                    f16a's balls
  DECLARE
    z        jsonb := _v112_stage();
    OFFICE   uuid;
    MB uuid; SB uuid; NB uuid; UPB uuid; WD uuid; TM uuid; PB uuid; T1 uuid;
    U_MB uuid; U_SB uuid; U_NB uuid; U_UP uuid; U_WD uuid; U_TM uuid; U_PA uuid; U_TWO uuid;
    G uuid; GUP uuid;
    got      text;
    n        int;
    v_others text;
    v_gothers text;
    v_seed   text;
    v_all    text;
    u        uuid;
    m        uuid;
    bad      text;
    ppl      uuid[];
    v_child  uuid[];
    v_base   text;
    j        jsonb;
  BEGIN
    OFFICE := (z->>'office')::uuid;
    MB := (z->>'mb')::uuid; SB := (z->>'sb')::uuid; NB := (z->>'nb')::uuid; UPB := (z->>'up')::uuid;
    WD := (z->>'wd')::uuid; TM := (z->>'tm')::uuid; PB := (z->>'pb')::uuid; T1 := (z->>'t1')::uuid;
    U_MB := (z->>'u_mb')::uuid; U_SB := (z->>'u_sb')::uuid; U_NB := (z->>'u_nb')::uuid; U_UP := (z->>'u_up')::uuid;
    U_WD := (z->>'u_wd')::uuid; U_TM := (z->>'u_tm')::uuid; U_PA := (z->>'u_pa')::uuid; U_TWO := (z->>'u_two')::uuid;
    G := (z->>'g')::uuid; GUP := (z->>'gup')::uuid;
    v_seed := _v112_fact('seed_live');
    v_base := _v112_fact('disagree_boys');

    -- ── (before) ──
    PERFORM _as(U_MB);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f14] training [s14] plans [p14] balls [f14]',
      format('§89 (before): on U14E mb reads %s', got));

    -- ── (carry) ──
    v_others := _v112_others(U_MB);
    v_gothers := _v112_others(G);
    PERFORM _as(OFFICE);
    UPDATE player SET team_code = 'U15E' WHERE id = MB;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 1, '§89 (carry): the office could not move mb');
    PERFORM _assert(_v112_roles(U_MB) = 'U14E:ended U15E:live',
      format('§89 (carry): after the move mb''s account holds %s', _v112_roles(U_MB)));
    PERFORM _assert(_v112_fact('ended_by', U_MB) = OFFICE::text AND _v112_fact('made_by', U_MB) = OFFICE::text,
      format('§89 (carry): the ended row reads %s and the new one was made by %s, not the office',
             _v112_fact('ended_by', U_MB), _v112_fact('made_by', U_MB)));
    PERFORM _assert(_v112_fact('open_membership', MB) = 'U15E',
      format('§89 (carry): the history trigger''s open row is %s', _v112_fact('open_membership', MB)));
    PERFORM _assert(_v112_others(U_MB) = v_others AND _v112_others(G) = v_gothers,
      '§89 (carry): the move touched mb''s self-access row or link, or his mother''s');
    UPDATE player SET team_code = 'U15E' WHERE id = SB;
    PERFORM _assert(_v112_roles(U_SB) = 'U14E:ended U15E:live',
      format('§89 (carry): after the move sb''s account (self-access only) holds %s', _v112_roles(U_SB)));

    -- ── (reads) ──
    PERFORM _as(U_MB);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f15] training [s15] plans [p15] balls [f15]',
      format('§89 (reads): after the move to U15E mb reads %s', got));
    PERFORM _as(U_SB);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f15] training [s15] plans [p15] balls [f15]',
      format('§89 (reads): after the move to U15E sb reads %s', got));
    PERFORM _as(G);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f15] training [s15] plans [p15] balls [f15]',
      format('§89 (reads): mb''s mother reads %s, not her son''s side', got));

    -- ── (whose) ──
    PERFORM _as(OFFICE);
    UPDATE player SET team_code = 'U15E' WHERE id IN (PB, T1);
    PERFORM _assert(_v112_roles(U_PA) = 'U14E:live' AND _v112_roles(U_TWO) = 'U14E:live',
      format('§89 (whose): a pending claim''s account holds %s, an account of two boys %s', _v112_roles(U_PA), _v112_roles(U_TWO)));

    -- ── (none) ──
    got := 'moved';
    BEGIN
      UPDATE player SET team_code = NULL WHERE id = NB;
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS got = CONSTRAINT_NAME;
      got := 'refused: ' || coalesce(nullif(got, ''), SQLERRM);
    END;
    PERFORM _assert(got = 'moved', format('§89 (none): the move to no side was %s', got));
    PERFORM _assert(_v112_fact('side', NB) = '(none)' AND _v112_roles(U_NB) = 'U14E:ended'
                    AND _v112_fact('ended_by', U_NB) = OFFICE::text,
      format('§89 (none): on no side nb''s account holds [%s] (ended by %s)', _v112_roles(U_NB), _v112_fact('ended_by', U_NB)));
    PERFORM _assert(_v112_fact('teamless_live') = '0',
      format('§89 (none): %s live player rows name no side', _v112_fact('teamless_live')));
    PERFORM _as(U_NB);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [] training [] plans [] balls []', format('§89 (none): on no side nb reads %s', got));

    -- ── (playing up) ──
    PERFORM _as(U_UP);
    PERFORM _assert(_v112_balls((z->>'f16a')::uuid) = _v112_fact('owner_balls', (z->>'f16a')::uuid)::int
                    AND _v112_balls((z->>'f16a')::uuid) = 18
                    AND _v112_balls((z->>'f16w')::uuid) = 30,
      format('§89 (playing up): up reads %s of f16a''s 18 balls and %s of f16w''s 30',
             _v112_balls((z->>'f16a')::uuid), _v112_balls((z->>'f16w')::uuid)));
    PERFORM _assert(_v112_balls((z->>'f16b')::uuid) = 0,
      format('§89 (playing up): up reads %s balls of f16b, the older side''s other match', _v112_balls((z->>'f16b')::uuid)));
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f14 f16a f16w] training [s14] plans [p14] balls [f14 f16a f16w]',
      format('§89 (playing up): up reads %s', got));
    PERFORM _as(U_TM);
    PERFORM _assert(_v112_balls((z->>'f16a')::uuid) = 0 AND _v112_balls((z->>'f16w')::uuid) = 0,
      '§89 (playing up): up''s team-mate, on no sheet, reads the older side''s balls');
    -- ...and his old team-mates on U14E read none of them either.
    PERFORM _as(U_PA);
    PERFORM _assert(_v112_balls((z->>'f16a')::uuid) = 0 AND _v112_balls((z->>'f16w')::uuid) = 0,
      '§89 (playing up): a U14E player on no sheet reads the older side''s balls');

    -- ── (withdrawn) ──
    PERFORM _as(U_WD);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f14] training [s14] plans [p14] balls [f14]',
      format('§89 (withdrawn): withdrawn from f16a wd reads %s', got));

    -- ── (guardians) ──
    PERFORM _as(GUP);
    PERFORM _assert(_v112_balls((z->>'f16a')::uuid) = 18 AND _v112_balls((z->>'f16w')::uuid) = 30
                    AND _v112_balls((z->>'f16b')::uuid) = 0,
      '§89 (guardians): up''s mother does not read the balls of the matches he is on the sheet of, and only those');
    -- db/100's, or since db/117 db/100's dated on the fixture's day (§94):
    -- db/112 itself does not touch it.
    PERFORM _assert(_v112_fact('child_md5') IN ('78db5a4d195937ed800efc92e0489516', '69846e82142ceea5c17809122f375706'),
      '§89 (guardians): my_child_fixtures() is not db/100''s, nor db/117''s');
    n := 0;
    FOREACH u IN ARRAY _v106_guardians_only() LOOP
      PERFORM _as(u);
      v_child := my_child_fixtures();
      PERFORM _assert(cardinality(my_own_sheet_fixtures()) = 0,
        format('§89 (guardians): the guardian %s has fixtures on the new branch', u));
      SELECT string_agg(x::text, ' ') INTO bad FROM (
        ((SELECT DISTINCT b.match_id FROM ball_event b)
         EXCEPT (SELECT y FROM unnest(_v106_ball_matches()) y WHERE _v112_db100(y, v_child)))
        UNION ALL
        ((SELECT y FROM unnest(_v106_ball_matches()) y WHERE _v112_db100(y, v_child))
         EXCEPT (SELECT DISTINCT b.match_id FROM ball_event b))) d(x);
      PERFORM _assert(bad IS NULL, format('§89 (guardians): the guardian %s reads balls apart from db/100 at %s', u, left(bad, 300)));
      n := n + 1;
    END LOOP;
    PERFORM _assert(n > 10, format('§89 (guardians): %s guardians compared: it proves nothing', n));

    -- ── (idempotent) ──
    -- The moves made through the trigger left nothing out of step: the boys
    -- whose rows disagree are the ones earlier sections staged that way (an
    -- account handed a side its boy is not on, a stage's shortcut), and no
    -- more.
    PERFORM _assert(_v112_fact('disagree_boys') = v_base,
      format('§89 (idempotent): after the moves the boys out of step are [%s], before them [%s]: %s',
             _v112_fact('disagree_boys'), v_base, _v112_fact('disagree_names')));
    -- Moves made before this file: tm moved with the carry off; mb given a
    -- second row on his old side by hand; nb, on no side, given one by hand.
    PERFORM _v112_move_untracked(TM, 'U15E');
    PERFORM _v112_grant(U_MB, 'U14E');
    PERFORM _v112_grant(U_NB, 'U14E');
    PERFORM _assert((SELECT count(*) FROM unnest(string_to_array(_v112_fact('disagree_boys'), ',')) x
                      WHERE x::uuid IN (TM, MB, NB)) = 3,
      format('§89 (idempotent): the stale state staged [%s]', _v112_fact('disagree_names')));
    j := _v112_correct();
    PERFORM _assert(j->>TM::text = '1:1' AND j->>MB::text = '1:0' AND j->>NB::text = '1:0'
                    AND (SELECT count(*) FROM jsonb_object_keys(j)) = 3 + coalesce(cardinality(string_to_array(nullif(v_base, ''), ',')), 0),
      format('§89 (idempotent): the correction answered %s (tm 1:1, mb 1:0, nb 1:0, and the %s staged out of step before)', j, v_base));
    PERFORM _assert(_v112_roles(U_TM) = 'U14E:ended U15E:live'
                    AND _v112_roles(U_MB) = 'U14E:ended U14E:ended U15E:live'
                    AND _v112_roles(U_NB) = 'U14E:ended U14E:ended',
      format('§89 (idempotent): after the correction tm holds [%s], mb [%s], nb [%s]',
             _v112_roles(U_TM), _v112_roles(U_MB), _v112_roles(U_NB)));
    PERFORM _assert(_v112_fact('disagree') = '0', '§89 (idempotent): a row still disagrees after the correction');
    v_all := _v112_fact('all_assignments');
    j := _v112_correct();
    PERFORM _assert(j = '{}'::jsonb AND _v112_fact('all_assignments') = v_all,
      format('§89 (idempotent): a second correction answered %s, or changed an assignment', j));
    PERFORM _assert(_v112_fact('seed_live') = v_seed
                    AND v_seed LIKE '%a5510000-0000-0000-0000-000000000001:1XI%'
                    AND v_seed LIKE '%a5510000-0000-0000-0000-00000000000c:1XI%',
      format('§89 (idempotent): the seed''s live player rows are now %s, were %s', _v112_fact('seed_live'), v_seed));
    PERFORM _as(U_TM);
    got := _v112_reads(z);
    PERFORM _assert(got = 'fixtures [f15] training [s15] plans [p15] balls [f15]',
      format('§89 (idempotent): corrected onto U15E tm reads %s', got));

    -- ── (agree) ──
    ppl := _v106_people();
    n := 0;
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      v_child := my_child_fixtures();
      SELECT string_agg(x::text, ' ') INTO bad FROM (
        ((SELECT DISTINCT b.match_id FROM ball_event b)
         EXCEPT (SELECT y FROM unnest(_v106_ball_matches()) y WHERE _v112_db100(y, v_child) OR _v106_self_sheet('fixture.read', y)))
        UNION ALL
        ((SELECT y FROM unnest(_v106_ball_matches()) y WHERE _v112_db100(y, v_child) OR _v106_self_sheet('fixture.read', y))
         EXCEPT (SELECT DISTINCT b.match_id FROM ball_event b))) d(x);
      PERFORM _assert(bad IS NULL, format('§89 (agree): %s reads balls apart from db/100 and the sheet at %s', u, left(bad, 300)));
      IF EXISTS (SELECT 1 FROM unnest(_v106_ball_matches()) y WHERE _v106_self_sheet('fixture.read', y) AND NOT _v112_db100(y, v_child)) THEN
        n := n + 1;
      END IF;
    END LOOP;
    PERFORM _assert(n >= 1 AND cardinality(ppl) > 20,
      format('§89 (agree): %s of %s people read a match by the sheet alone: it proves nothing', n, cardinality(ppl)));

    -- ── (check) ──
    PERFORM _assert((SELECT pg_get_constraintdef(c.oid) FROM pg_constraint c
                      WHERE c.conrelid = to_regclass('role_assignment') AND c.conname = 'role_assignment_player_team_scoped'
                        AND c.contype = 'c' AND c.convalidated)
                    = 'CHECK (((role <> ''player''::text) OR (team_code IS NOT NULL) OR (NOT active)))',
      '§89 (check): role_assignment_player_team_scoped is not db/108''s, or not validated');
    PERFORM _assert(_v112_fact('teamless_live') = '0', '§89 (check): a live player row names no side');
    PERFORM _assert(_v112_fact('grant_md5') = 'a9a5a09414e0629d70c873fcbeb99f75',
      '§89 (check): role_request_grant_as() is not db/92''s body with db/108''s block');

    -- ── (doors) ──
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = to_regclass('player')
                               AND t.tgname = 'player_assignment_follows_side' AND t.tgenabled = 'O'
                               AND t.tgfoid = to_regprocedure('player_assignment_follows_side()')),
      '§89 (doors): the trigger is missing or disabled');
    PERFORM _assert((SELECT bool_and(p.prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(p.proconfig, '{}'))
                                     AND NOT has_function_privilege('scrbrd_app', p.oid, 'EXECUTE')
                                     AND NOT has_function_privilege('public', p.oid, 'EXECUTE'))
                           AND count(*) = 5
                       FROM pg_proc p
                      WHERE p.oid IN (to_regprocedure('player_own_accounts(uuid)'), to_regprocedure('player_assignment_carry(uuid,uuid,text)'),
                                      to_regprocedure('player_assignment_follows_side()'), to_regprocedure('player_assignment_disagreements()'),
                                      to_regprocedure('player_assignment_correct()'))),
      '§89 (doors): an SR-1 function is not a pinned definer, or the application or PUBLIC may call it');
    PERFORM _assert(has_function_privilege('scrbrd_app', to_regprocedure('my_own_sheet_fixtures()'), 'EXECUTE')
                    AND NOT has_function_privilege('public', to_regprocedure('my_own_sheet_fixtures()'), 'EXECUTE'),
      '§89 (doors): my_own_sheet_fixtures() is not scrbrd_app''s alone');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 89
  -- └── db/112 (section 89) ──────────────────────────────────────────
  -- ┌── db/113 (section 90) ──────────────────────────────────────────
  -- ── 90. A correction takes back what it falsified (db/113) ──
  -- GA-I36 A2 with NOTIFICATIONS S5. A void re-asks every notice its ball
  -- could have caused; one that no longer holds is withdrawn, once, to its
  -- own audience, in the design's words; one that holds again returns in
  -- place and nothing new is sent. _v113_stage() and _v113_ev() write as the
  -- owner, as the pad and the amendment route reach the log; every read
  -- below is a person's, through scrbrd_app under RLS.
  --
  -- What each label holds:
  --   (fifty)      a six takes the batter from 46 to 52: one milestone row,
  --                linked to one live "Fifty for …" notice his side reads
  --   (withdrawn)  the six is voided (46): the mark and its notice are
  --                retracted as a correction, by the system, and ONE
  --                "withdrawn" notice goes: "A notice was withdrawn",
  --                "'Fifty for …' was withdrawn after the scorecard was
  --                corrected.", to exactly the original's audience, low
  --   (live)       nobody reads the withdrawn notice as live: not in the coach's,
  --                the boy's or his parent's list, a stub when opened
  --                (withdrawn, no words, pointing at the withdrawal), the mark
  --                gone from milestone_notice; the withdrawal in each list once
  --   (audience)   another boy's parent, another school's coach and a follower
  --                read neither the notice nor its withdrawal
  --   (standing)   the partner's fifty, on a ball nobody voided, is untouched
  --   (names)      no withdrawal's title names a child (the push is a pointer
  --                whatever the row says: push-api.test.mjs); a welfare
  --                withdrawal names nobody in its body either
  --   (idempotent) a second void of the same ball sends no second withdrawal
  --                and moves nothing; a void of an unrelated dot retracts
  --                nothing
  --   (once)       a re-entered four restores the fifty (50): the SAME row
  --                and notice return, re-synced to 50, nothing new is sent,
  --                and its withdrawal is superseded, unsaid; every reader
  --                sees one live fifty and no withdrawal. Voided again, one
  --                live withdrawal again
  --   (breach)     a U13 bowler's sixth over of a spell: one breach and one
  --                high welfare notice; that ball voided: the breach is hidden,
  --                workload() counts none, the notice withdrawn at medium to
  --                the same staff; the ball re-entered: the same breach and
  --                notice return, nothing new
  --   (newly)      W, dot, W, W and the dot voided: the hat-trick the
  --                corrected history holds is noticed once, "after a
  --                correction"; a second void sends nothing more
  --   (doors)      the new functions are nobody's to call (not the
  --                application's); the triggers fire on a void (and the
  --                public one on a released ball) only
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this section; each went red at its label (see the commit):
  --   (withdrawn)  milestone_retract() without its notification_retract()
  --   (once)       milestone_notify_as() inserting a new notice on a
  --                re-reached mark instead of un-retracting the row
  --   (names)      notification_retract() titling the withdrawal with the
  --                original's title ("A notice was withdrawn: Fifty for …")
  --   (breach)     workload() without `x.retracted_at IS NULL`
  DECLARE
    y     jsonb := _v113_stage();
    M     uuid := (y->>'match')::uuid;
    BAT   uuid := (y->>'bat')::uuid;
    PAR   uuid := (y->>'par')::uuid;
    Q     uuid := (y->>'quick')::uuid;
    H     uuid := (y->>'hat')::uuid;
    SIDE  text[] := ARRAY['coach', 'boy', 'parent'];
    AWAY  text[] := ARRAY['pparent', 'wescoach', 'follower'];
    NAMES text[] := ARRAY['Verify OneThirteen Opener', 'Verify OneThirteen Partner', 'Verify OneThirteen Quick', 'Verify OneThirteen Hattrick'];
    k6 text; dot text; four text; kb text; hdot text; x text;
    F uuid; W uuid; W2 uuid; PF uuid; B uuid; BN uuid; BW uuid; HT uuid;
    j jsonb; k text; nm text; i integer; got text; n integer;
    saw text[] := '{}';
  BEGIN
    -- (fifty)
    FOR i IN 1..9 LOOP PERFORM _v113_ev(M, 0::smallint, 'ball', 'run', 6, PAR, NULL); END LOOP;   -- the partner: 54
    FOR i IN 1..7 LOOP PERFORM _v113_ev(M, 0::smallint, 'ball', 'run', 6, BAT, NULL); END LOOP;   -- the batter: 42
    PERFORM _v113_ev(M, 0::smallint, 'ball', 'run', 4, BAT, NULL);                                 -- 46
    k6 := _v113_ev(M, 0::smallint, 'ball', 'run', 6, BAT, NULL);                                   -- 52: the fifty
    j := _v113_mark(BAT, 'fifty', M);
    F := (j->>'notice_id')::uuid;
    PF := (_v113_mark(PAR, 'fifty', M)->>'notice_id')::uuid;
    PERFORM _assert(j->>'retracted_at' IS NULL AND (j->>'value')::int = 52 AND F IS NOT NULL AND PF IS NOT NULL,
      format('§90 (fifty): the fifty was not noticed and linked: %s', j));
    PERFORM _assert(_row_89(F)->>'title' = 'Fifty for Verify OneThirteen Opener' AND _row_89(F)->>'retracted_at' IS NULL,
      format('§90 (fifty): the notice is not the live "Fifty for …": %s', _row_89(F)));
    -- Who read the fifty: the withdrawal must reach exactly them (audience).
    FOREACH k IN ARRAY SIDE || AWAY LOOP
      PERFORM _as((y->>k)::uuid);
      IF EXISTS (SELECT 1 FROM my_notifications WHERE id = F) THEN saw := saw || k; END IF;
    END LOOP;
    PERFORM _assert(saw @> SIDE AND NOT saw && ARRAY['pparent', 'wescoach'],
      format('§90 (fifty): the fifty was read by %s, not the side alone', saw));

    -- (withdrawn)
    PERFORM _v113_ev(M, 0::smallint, 'void', NULL, NULL, NULL, NULL, NULL, k6);
    j := _v113_mark(BAT, 'fifty', M);
    PERFORM _assert(j->>'retracted_at' IS NOT NULL, format('§90 (withdrawn): the voided fifty''s mark stands: %s', j));
    j := _row_89(F);
    PERFORM _assert(j->>'retracted_at' IS NOT NULL AND j->>'retraction_kind' = 'correction' AND j->>'retracted_by' IS NULL,
      format('§90 (withdrawn): the fifty''s notice was not retracted as the system''s correction: %s', j));
    PERFORM _assert(_said_89(F) = 1, format('§90 (withdrawn): %s withdrawal(s) were sent, not one', _said_89(F)));
    SELECT (e->>'id')::uuid INTO W FROM jsonb_array_elements(_v113_about(BAT)) e WHERE (e->>'retracts_id')::uuid = F;
    j := _row_89(W);
    -- (its title is (names)'s to hold)
    PERFORM _assert(j->>'body' = '''Fifty for Verify OneThirteen Opener'' was withdrawn after the scorecard was corrected.'
                    AND j->>'kind' = 'recognition' AND j->>'urgency' = 'low' AND j->>'required_capability' = 'news.read'
                    AND j->>'retracted_at' IS NULL AND j->>'published_by' IS NULL,
      format('§90 (withdrawn): the withdrawal is not the design''s: %s', j));
    PERFORM _assert((j->>'school_id', j->>'team_code', j->>'scope_level', j->>'subject_person_id', j->>'recipient_id', j->>'subject_id')
                    IS NOT DISTINCT FROM (_row_89(F)->>'school_id', _row_89(F)->>'team_code', _row_89(F)->>'scope_level',
                                          _row_89(F)->>'subject_person_id', _row_89(F)->>'recipient_id', _row_89(F)->>'subject_id'),
      '§90 (withdrawn): the withdrawal is not addressed to exactly the original''s audience');

    -- (live)
    FOREACH k IN ARRAY SIDE LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM my_notifications WHERE id = F) = 0,
        format('§90 (live): the %s reads the withdrawn fifty as live', k));
      PERFORM _assert((SELECT count(*) FROM my_notifications WHERE subject_person_id = BAT AND title LIKE 'Fifty for%') = 0,
        format('§90 (live): the %s reads a fifty for the batter', k));
      PERFORM _assert((SELECT count(*) FROM my_notifications WHERE id = W AND retracts_id = F) = 1
                      AND (SELECT count(*) FROM my_notifications WHERE retracts_id = F) = 1,
        format('§90 (live): the %s does not read the one withdrawal', k));
      j := notification_by_id(F);
      PERFORM _assert((j->>'withdrawn')::boolean AND NOT (j ? 'title') AND NOT (j ? 'body') AND (j->>'withdrawal_id')::uuid = W,
        format('§90 (live): the %s opens the withdrawn fifty as %s, not a stub', k, j));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM milestone_notice WHERE player_id = BAT AND match_id = M) = 0
                    AND (SELECT count(*) FROM milestone_notice WHERE player_id = PAR AND match_id = M) = 1,
      '§90 (live): the coach reads the voided mark in milestone_notice, or lost the partner''s');

    -- (audience)
    -- Exactly the original's readers read the withdrawal: whoever read the
    -- fifty (the side, and a follower if the school's notices reach him),
    -- and nobody who did not (another boy's parent, another school's coach).
    FOREACH k IN ARRAY SIDE || AWAY LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert(EXISTS (SELECT 1 FROM my_notifications WHERE id = W) = (k = ANY (saw)),
        format('§90 (audience): the %s %s the withdrawal, and %s the fifty', k,
               CASE WHEN EXISTS (SELECT 1 FROM my_notifications WHERE id = W) THEN 'reads' ELSE 'does not read' END,
               CASE WHEN k = ANY (saw) THEN 'read' ELSE 'did not read' END));
      IF NOT k = ANY (saw) THEN
        PERFORM _assert((SELECT count(*) FROM my_notifications WHERE subject_person_id = BAT) = 0
                        AND notification_by_id(W) IS NULL AND notification_by_id(F) IS NULL,
          format('§90 (audience): the %s reads the batter''s notice or its withdrawal', k));
      END IF;
    END LOOP;
    PERFORM _as((y->>'pparent')::uuid);
    PERFORM _assert((SELECT count(*) FROM my_notifications WHERE id = PF) = 1,
      '§90 (audience): the partner''s parent does not read his own boy''s fifty, so this proves nothing');

    -- (standing)
    j := _v113_mark(PAR, 'fifty', M);
    PERFORM _assert(j->>'retracted_at' IS NULL AND _row_89(PF)->>'retracted_at' IS NULL AND _said_89(PF) = 0,
      format('§90 (standing): the partner''s fifty was touched: %s / %s', j, _row_89(PF)));
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM my_notifications WHERE id = PF) = 1, '§90 (standing): the coach lost the partner''s fifty');

    -- (idempotent)
    got := _v113_mark(BAT, 'fifty', M)->>'retracted_at';
    n := jsonb_array_length(_v113_about(BAT));
    PERFORM _v113_ev(M, 0::smallint, 'void', NULL, NULL, NULL, NULL, NULL, k6);
    PERFORM _assert(_said_89(F) = 1 AND jsonb_array_length(_v113_about(BAT)) = n
                    AND _v113_mark(BAT, 'fifty', M)->>'retracted_at' = got,
      format('§90 (idempotent): a second void of the six moved something: %s withdrawal(s), %s notices (was %s)',
             _said_89(F), jsonb_array_length(_v113_about(BAT)), n));
    n := jsonb_array_length(_v113_about(PAR));
    dot := _v113_ev(M, 0::smallint, 'ball', 'run', 0, PAR, NULL);
    PERFORM _v113_ev(M, 0::smallint, 'void', NULL, NULL, NULL, NULL, NULL, dot);
    PERFORM _assert(jsonb_array_length(_v113_about(PAR)) = n AND _row_89(PF)->>'retracted_at' IS NULL,
      '§90 (idempotent): a void of the partner''s dot retracted or sent something');

    -- (once)
    four := _v113_ev(M, 0::smallint, 'ball', 'run', 4, BAT, NULL);                                 -- 50 again
    j := _v113_mark(BAT, 'fifty', M);
    PERFORM _assert(j->>'retracted_at' IS NULL AND (j->>'value')::int = 50 AND (j->>'notice_id')::uuid = F,
      format('§90 (once): the re-reached fifty is not the same mark, returned at 50: %s', j));
    j := _row_89(F);
    PERFORM _assert(j->>'retracted_at' IS NULL AND j->>'retraction_kind' IS NULL
                    AND j->>'body' = 'Fifty (50) against Verify OneThirteen Visitors.',
      format('§90 (once): the fifty''s notice did not return, re-synced: %s', j));
    PERFORM _assert((SELECT count(*) FROM jsonb_array_elements(_v113_about(BAT)) e
                      WHERE e->>'title' = 'Fifty for Verify OneThirteen Opener') = 1,
      '§90 (once): the re-reached fifty was sent a second time');
    PERFORM _assert(_row_89(W)->>'retraction_kind' = 'superseded' AND _said_89(W) = 0 AND _said_89(F) = 1,
      format('§90 (once): the withdrawal was not superseded unsaid: %s', _row_89(W)));
    FOREACH k IN ARRAY SIDE LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM my_notifications WHERE subject_person_id = BAT AND title LIKE 'Fifty for%') = 1
                      AND (SELECT count(*) FROM my_notifications WHERE id = F) = 1
                      AND (SELECT count(*) FROM my_notifications WHERE retracts_id = F) = 0,
        format('§90 (once): the %s does not read one live fifty and no withdrawal', k));
    END LOOP;
    PERFORM _v113_ev(M, 0::smallint, 'void', NULL, NULL, NULL, NULL, NULL, four);
    SELECT (e->>'id')::uuid INTO W2 FROM jsonb_array_elements(_v113_about(BAT)) e
     WHERE (e->>'retracts_id')::uuid = F AND e->>'retracted_at' IS NULL;
    PERFORM _assert(_row_89(F)->>'retracted_at' IS NOT NULL AND W2 IS NOT NULL AND W2 <> W AND _said_89(F) = 2,
      '§90 (once): voided again, the fifty was not withdrawn once more');
    FOREACH k IN ARRAY SIDE LOOP
      PERFORM _as((y->>k)::uuid);
      PERFORM _assert((SELECT count(*) FROM my_notifications WHERE retracts_id = F) = 1
                      AND (SELECT count(*) FROM my_notifications WHERE id = F) = 0,
        format('§90 (once): voided again, the %s does not read exactly one withdrawal', k));
    END LOOP;

    -- (names)
    FOR j IN SELECT e FROM jsonb_array_elements(_v113_about(BAT) || _v113_about(PAR)) e WHERE e->>'retracts_id' IS NOT NULL LOOP
      FOREACH nm IN ARRAY NAMES LOOP
        PERFORM _assert(position(nm IN j->>'title') = 0, format('§90 (names): a withdrawal''s title names a child: %s', j->>'title'));
      END LOOP;
      PERFORM _assert(j->>'title' = 'A notice was withdrawn', format('§90 (names): a withdrawal is titled %s', j->>'title'));
    END LOOP;

    -- (breach)
    FOR i IN 1..30 LOOP PERFORM _v113_ev(M, 1::smallint, 'ball', 'run', 0, NULL, Q); END LOOP;     -- five overs
    PERFORM _assert(jsonb_array_length(_v113_breaches(Q)) = 0, '§90 (breach): five overs breached a U13 spell of five');
    kb := _v113_ev(M, 1::smallint, 'ball', 'run', 0, NULL, Q);                                       -- the sixth over
    j := _v113_breaches(Q) -> 0;
    B := (j->>'id')::uuid; BN := (j->>'notice_id')::uuid;
    PERFORM _assert(jsonb_array_length(_v113_breaches(Q)) = 1 AND j->>'kind' = 'spell' AND j->>'retracted_at' IS NULL
                    AND _row_89(BN)->>'title' = 'Bowling directive exceeded' AND _row_89(BN)->>'urgency' = 'high',
      format('§90 (breach): the sixth over did not record one breach with its notice: %s', _v113_breaches(Q)));
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM bowling_breach WHERE id = B) = 1 AND (SELECT count(*) FROM my_notifications WHERE id = BN) = 1
                    AND (SELECT w.breaches_28d FROM workload('U19F') w WHERE w.player_id = Q) = 1,
      '§90 (breach): the coach does not read the breach, its notice, or its count');
    PERFORM _v113_ev(M, 1::smallint, 'void', NULL, NULL, NULL, NULL, NULL, kb);
    j := _v113_breaches(Q) -> 0;
    PERFORM _assert(jsonb_array_length(_v113_breaches(Q)) = 1 AND j->>'retracted_at' IS NOT NULL AND (j->>'id')::uuid = B,
      format('§90 (breach): the voided over''s breach stands: %s', j));
    PERFORM _assert(_row_89(BN)->>'retraction_kind' = 'correction' AND _said_89(BN) = 1,
      format('§90 (breach): the breach''s notice was not withdrawn once: %s', _row_89(BN)));
    SELECT (e->>'id')::uuid INTO BW FROM jsonb_array_elements(_v113_about(Q)) e WHERE (e->>'retracts_id')::uuid = BN;
    j := _row_89(BW);
    PERFORM _assert(j->>'title' = 'A notice was withdrawn'
                    AND j->>'body' = '''Bowling directive exceeded'' was withdrawn after the scorecard was corrected.'
                    AND j->>'kind' = 'welfare' AND j->>'urgency' = 'medium' AND j->>'required_capability' = 'player.workload.read'
                    AND (j->>'subject_person_id')::uuid = Q,
      format('§90 (breach): the welfare withdrawal is not the design''s: %s', j));
    FOREACH nm IN ARRAY NAMES LOOP
      PERFORM _assert(position(nm IN j->>'title') = 0 AND position(nm IN j->>'body') = 0,
        format('§90 (names): the welfare withdrawal names a child: %s', j));
    END LOOP;
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM bowling_breach WHERE id = B) = 0
                    AND (SELECT count(*) FROM my_notifications WHERE id = BN) = 0
                    AND (SELECT count(*) FROM my_notifications WHERE id = BW AND retracts_id = BN) = 1,
      '§90 (breach): the coach reads the withdrawn breach or its notice as live, or not its withdrawal');
    PERFORM _assert((SELECT w.breaches_28d FROM workload('U19F') w WHERE w.player_id = Q) = 0,
      format('§90 (breach): workload() still counts the withdrawn breach (%s)',
             (SELECT w.breaches_28d FROM workload('U19F') w WHERE w.player_id = Q)));
    PERFORM _v113_ev(M, 1::smallint, 'ball', 'run', 0, NULL, Q);                                     -- the sixth over, again
    j := _v113_breaches(Q) -> 0;
    PERFORM _assert(jsonb_array_length(_v113_breaches(Q)) = 1 AND (j->>'id')::uuid = B AND j->>'retracted_at' IS NULL
                    AND _row_89(BN)->>'retracted_at' IS NULL AND _row_89(BW)->>'retraction_kind' = 'superseded'
                    AND (SELECT count(*) FROM jsonb_array_elements(_v113_about(Q)) e WHERE e->>'title' = 'Bowling directive exceeded') = 1,
      format('§90 (breach): the re-reached breach did not return in place, once: %s', _v113_breaches(Q)));
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM bowling_breach WHERE id = B) = 1 AND (SELECT count(*) FROM my_notifications WHERE id = BN) = 1
                    AND (SELECT count(*) FROM my_notifications WHERE retracts_id = BN) = 0
                    AND (SELECT w.breaches_28d FROM workload('U19F') w WHERE w.player_id = Q) = 1,
      '§90 (breach): after the re-entered ball the coach does not read the one breach, live');

    -- (newly)
    PERFORM _v113_ev(M, 2::smallint, 'ball', 'W', 0, NULL, H, 'bowled');
    hdot := _v113_ev(M, 2::smallint, 'ball', 'run', 0, NULL, H);
    PERFORM _v113_ev(M, 2::smallint, 'ball', 'W', 0, NULL, H, 'bowled');
    PERFORM _v113_ev(M, 2::smallint, 'ball', 'W', 0, NULL, H, 'bowled');
    PERFORM _assert(_v113_mark(H, 'hat_trick', M) IS NULL, '§90 (newly): W, dot, W, W was noticed as a hat-trick');
    PERFORM _v113_ev(M, 2::smallint, 'void', NULL, NULL, NULL, NULL, NULL, hdot);
    j := _v113_mark(H, 'hat_trick', M);
    HT := (j->>'notice_id')::uuid;
    PERFORM _assert(j->>'retracted_at' IS NULL AND HT IS NOT NULL
                    AND _row_89(HT)->>'title' = 'Hat-trick for Verify OneThirteen Hattrick'
                    AND _row_89(HT)->>'body' = 'Hat-trick against Verify OneThirteen Visitors, after a correction.',
      format('§90 (newly): the hat-trick the correction made was not noticed, after a correction: %s / %s', j, _row_89(HT)));
    PERFORM _v113_ev(M, 2::smallint, 'void', NULL, NULL, NULL, NULL, NULL, hdot);
    PERFORM _assert((SELECT count(*) FROM jsonb_array_elements(_v113_about(H)) e WHERE e->>'title' LIKE 'Hat-trick for%') = 1,
      '§90 (newly): a second void sent the hat-trick again');
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert((SELECT count(*) FROM my_notifications WHERE id = HT) = 1, '§90 (newly): the coach does not read the hat-trick');

    -- (doors)
    FOREACH x IN ARRAY ARRAY['notification_unretract(uuid)', 'milestone_still_holds(uuid,text,uuid,smallint,integer)',
                             'milestone_notify_as(uuid,text,uuid,smallint,integer,boolean)',
                             'milestone_retract()', 'bowling_breach_retract()'] LOOP
      PERFORM _assert(NOT has_function_privilege('scrbrd_app', to_regprocedure(x), 'EXECUTE')
                      AND NOT has_function_privilege('public', to_regprocedure(x), 'EXECUTE'),
        format('§90 (doors): %s is callable by the application or PUBLIC', x));
    END LOOP;
    BEGIN
      PERFORM notification_unretract(F);
      PERFORM _assert(false, '§90 (doors): the application un-retracted a notice');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    PERFORM _assert((SELECT count(*) FROM pg_trigger g
                      WHERE g.tgrelid = 'ball_event'::regclass AND NOT g.tgisinternal
                        AND g.tgname IN ('ball_event_milestone_retract', 'ball_event_breach_retract')
                        AND pg_get_triggerdef(g.oid) LIKE '%AFTER INSERT ON public.ball_event FOR EACH ROW WHEN ((new.kind = ''void''::text))%') = 2
                    AND EXISTS (SELECT 1 FROM pg_trigger g
                                 WHERE g.tgrelid = 'ball_event'::regclass AND g.tgname = 'public_data_changed'
                                   AND g.tgfoid = 'public_data_notify()'::regprocedure
                                   AND pg_get_triggerdef(g.oid) LIKE '%WHEN (((new.kind = ''void''::text) OR new.recovered)) EXECUTE FUNCTION public_data_notify(''match'', ''match_id'')%'),
      '§90 (doors): the void triggers, or the public one, are not what db/113 wrote');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 90
  -- └── db/113 (section 90) ──────────────────────────────────────────
  -- ┌── db/114 (section 91) ──────────────────────────────────────────
  -- ── 91. When a result becomes official (db/114) ──
  -- docs/design/OFFICIAL_RESULT.md S1 (D1–D14, Q1–Q8). A confirmation is one
  -- row pinned to the log's head and the result's hash; "official" is read
  -- off it, and every correction makes it provisional again by itself.
  -- _v114_stage() and the owner's helpers write the log as the pad, the
  -- amendment route and the hold do; every door and every read below is a
  -- person's, through scrbrd_app under RLS.
  --
  -- What each label holds:
  --   (caps)       result.confirm is the four roles' and nobody else's; no
  --                role that files a correction holds it (D5, §5)
  --   (when)       a live match → not_finished; an unsealed innings →
  --                innings_unsealed; a pending amendment → amendment_pending;
  --                a held ball → ball_held (D6, in that order of asking)
  --   (who)        a friendly: the scorer, the coach, the away director, a
  --                league organiser appointed with no school → not_permitted;
  --                a league fixture: either director →
  --                not_permitted, the organiser may; a document saying
  --                home_school lets the home director and not the away one;
  --                either_school lets the away one too (D2–D4, Q1, Q8)
  --   (hands)      the man who scored a log, the requester of an applied
  --                amendment and its approver each → you_wrote_this_log (D5)
  --   (confirm)    a clean confirmer: one row at the head and the hash, the
  --                state official, one low fixture notice per side naming
  --                nobody, a second confirm → already_official
  --   (review)     a dispute: the scorer → not_permitted, the confirmer →
  --                cannot_dispute_your_own, a short note → note_required; the
  --                away director → under_review for staff, provisional for a
  --                follower and on the public page, never "under review";
  --                its words reach the disputant and audit.read, not the
  --                coach; the disputant cannot clear; for a friendly the home
  --                director clears it: official again
  --   (lapse)      an approved amendment's void: the row stamped
  --                `correction`, the state provisional, the official notices
  --                retracted superseded (nothing said), one medium "reopened"
  --                notice per side; re-confirmed → a second row, the first
  --                kept; a decision recorded → `decision`; complete →
  --                abandoned → `status`
  --   (league)     the organiser confirms (as organiser); the table's points
  --                are identical before and after (D10) and provisional_results
  --                falls by one, in the table and its public read; a home
  --                dispute only the organiser clears; his withdrawal within the
  --                window → provisional, both sides told, and — the league
  --                having no organising school — its administrator by name
  --   (window)     eight days on: a dispute and a withdrawal → window_closed
  --   (organiser)  a league Hilton organises: Hilton's director gets
  --                not_permitted on confirm and clear and never reads
  --                Westville's note; the cup's administrator confirms as the
  --                organiser, reads it and clears it (the security review)
  --   (forged)     a pad void whose payload forges an approved amendment:
  --                the seal is broken (innings_unsealed) and the director it
  --                names is no hand on the log
  --   (badseal)    a seal that never stood, with nothing after it, is no seal
  --   (abandoned)  abandoned before a ball: confirmable, and official (Q6)
  --   (reads)      a reader of neither side reads no state; a pad's credential
  --                opens no door; the application cannot write the table nor
  --                read a person or a note on it
  --
  -- Falsified once each, by replacing the object in the database and running
  -- this section; each went red at its label (see the commit):
  --   (hands)   match_confirmable() without its result_hand_on_log() check
  --   (review)  result_official_at() reading a disputed row as official
  --   (lapse)   the ball_event lapse trigger dropped
  --   (caps)    result.confirm granted to the scorer
  --   (who)     result_school_holds() without its own-school half
  --   (organiser) result_scope_holds() without competition.manage
  --   (forged)  match_seals_stand() trusting the void's payload again
  --   (badseal) match_seals_stand() without "a two-hand event after the seal"
  --   (league)  result_official_notices() without the organiser's recipient notice
  DECLARE
    y   jsonb := _v114_stage();
    F   uuid := (y->>'F')::uuid;
    L   uuid := (y->>'L')::uuid;
    L2  uuid := (y->>'L2')::uuid;
    L3  uuid := (y->>'L3')::uuid;
    TM  uuid := (y->>'T')::uuid;
    UM  uuid := (y->>'U')::uuid;
    AM  uuid := (y->>'A')::uuid;
    C   uuid := (y->>'comp')::uuid;
    HDOS uuid := (y->>'hdos')::uuid;
    HPRIN uuid := (y->>'hprin')::uuid;
    WDOS uuid := (y->>'wdos')::uuid;
    SCO uuid := (y->>'scorer')::uuid;
    TWO uuid := (y->>'twohats')::uuid;
    ORG uuid := (y->>'org')::uuid;
    j jsonb; r record; o record; k text; n integer; got text; x text;
    keys text[]; a uuid; c1 uuid; c2 uuid; pts_before text; prov_before integer;
  BEGIN
    -- (caps)
    PERFORM _assert((SELECT string_agg(rc.role, ',' ORDER BY rc.role) FROM role_capability rc WHERE rc.capability = 'result.confirm')
                    = 'competitionadmin,directorofsport,principal,superadmin',
      format('§91 (caps): result.confirm is held by %s', (SELECT string_agg(rc.role, ',' ORDER BY rc.role) FROM role_capability rc
                                                          WHERE rc.capability = 'result.confirm')));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM role_capability a1 JOIN role_capability b1 ON b1.role = a1.role
                                 WHERE a1.capability = 'result.confirm' AND b1.capability = 'scoring.amend.request'
                                   AND a1.role <> 'superadmin'),
      '§91 (caps): a role that files a correction may confirm a result');

    -- (when) F is live: not finished.
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_confirmable(F);
    PERFORM _assert(r.ok = false AND r.reason = 'not_finished', format('§91 (when): a live match answered %s/%s', r.ok, r.reason));
    PERFORM _assert((SELECT s.state FROM match_official_state(F) s) = 'not_finished', '§91 (when): a live match''s state is not not_finished');
    PERFORM _v114_status(F, 'complete');
    SELECT * INTO r FROM match_confirmable(UM);
    PERFORM _assert(r.reason = 'innings_unsealed', format('§91 (when): an unsealed innings answered %s', r.reason));
    keys := (SELECT array_agg(b.idempotency_key ORDER BY b.seq) FROM ball_event b WHERE b.match_id = F AND b.kind = 'ball');
    a := _v114_request(F, keys[1], TWO);
    SELECT * INTO r FROM match_confirmable(F);
    PERFORM _assert(r.reason = 'amendment_pending', format('§91 (when): a pending amendment answered %s', r.reason));
    PERFORM _assert((SELECT s.state || '/' || s.blocked_by FROM match_official_state(F) s) = 'provisional/amendment_pending',
      '§91 (when): the staff state does not name the pending amendment');
    -- The principal approves it (the second signature): the void is appended.
    PERFORM _as(HPRIN);
    SELECT * INTO r FROM scoring_amendment_decide(a, true, 'Verify 114: approved');
    PERFORM _assert(r.ok, format('§91 (when): the approval was refused: %s', r.reason));
    j := _v114_fact(F);
    PERFORM _assert((j->>'verified')::boolean = false AND (j->>'seals')::boolean,
      format('§91 (when): after an approved void the scorer''s seal should be broken and the two-hand path stand: %s', j));
    PERFORM _v114_hold(F, SCO, false);
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_confirmable(F);
    PERFORM _assert(r.reason = 'ball_held', format('§91 (when): a held ball answered %s', r.reason));
    PERFORM _v114_hold(F, SCO, true);

    -- (who) a friendly is the home school's.
    -- (the league's organiser too: appointed with no school, app_can() reaches
    -- every school, and a friendly is still not his, D3)
    FOREACH k IN ARRAY ARRAY['scorer', 'coach', 'wdos', 'wescoach', 'follower', 'org'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT * INTO r FROM match_result_confirm(F);
      PERFORM _assert(r.ok = false AND r.reason = 'not_permitted', format('§91 (who): the %s confirming the friendly answered %s', k, r.reason));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['hdos', 'wdos'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT * INTO r FROM match_confirmable(L);
      PERFORM _assert(r.reason = 'not_permitted', format('§91 (who): the %s may confirm a league fixture: %s', k, r.reason));
    END LOOP;
    PERFORM _as(ORG);
    SELECT * INTO r FROM match_confirmable(L);
    PERFORM _assert(r.ok, format('§91 (who): the organiser may not confirm his league''s fixture: %s', r.reason));
    PERFORM _as(WDOS);
    SELECT * INTO r FROM match_confirmable(L2);
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (who): home_school let the away director: %s', r.reason));
    SELECT * INTO r FROM match_confirmable(L3);
    PERFORM _assert(r.ok, format('§91 (who): either_school did not let the away director: %s', r.reason));
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_confirm(L2);
    PERFORM _assert(r.ok AND (_v114_rows(L2)->0->>'confirmed_as') = 'home_school'
                    AND (_v114_rows(L2)->0->>'window_closes_at')::timestamptz - (_v114_rows(L2)->0->>'confirmed_at')::timestamptz = interval '3 days',
      format('§91 (who): the home director''s confirmation under home_school (3 days): %s / %s', r.reason, _v114_rows(L2)));

    -- (hands) D5: no hand on the log confirms it.
    PERFORM _as(TWO);
    SELECT * INTO r FROM match_result_confirm(TM);
    PERFORM _assert(r.reason = 'you_wrote_this_log', format('§91 (hands): the man who scored it answered %s', r.reason));
    SELECT * INTO r FROM match_result_confirm(F);
    PERFORM _assert(r.reason = 'you_wrote_this_log', format('§91 (hands): the amendment''s requester answered %s', r.reason));
    PERFORM _as(HPRIN);
    SELECT * INTO r FROM match_result_confirm(F);
    PERFORM _assert(r.reason = 'you_wrote_this_log', format('§91 (hands): the amendment''s approver answered %s', r.reason));
    PERFORM _assert(jsonb_array_length(_v114_rows(F)) = 0, '§91 (hands): a refused confirmation wrote a row');

    -- (confirm)
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_confirm(F);
    j := _v114_rows(F);
    PERFORM _assert(r.ok AND jsonb_array_length(j) = 1 AND (j->0->>'head_seq')::integer = (_v114_fact(F)->>'head')::integer
                    AND j->0->>'result_hash' = (SELECT m.result_hash FROM match_result(F) m)
                    AND j->0->>'confirmed_as' = 'home_school' AND (j->0->>'confirmed_by')::uuid = HDOS,
      format('§91 (confirm): the row is not at the head and the hash: %s / %s', r.reason, j));
    c1 := r.confirmation_id;
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'official' AND o.staff AND o.confirmed_as = 'home_school' AND o.confirmer = 'you'
                    AND o.can_withdraw AND NOT o.can_dispute AND NOT o.can_confirm AND o.confirm_refusal = 'already_official',
      format('§91 (confirm): the director reads %s', to_jsonb(o)));
    j := _v114_notes(F);
    PERFORM _assert(jsonb_array_length(j) = 2
                    AND (SELECT bool_and(e->>'urgency' = 'low' AND e->>'scope' = 'team' AND e->>'cap' = 'fixture.read'
                                         AND e->>'title' = 'Official result · Hilton College U17F v Westville Boys'' High U17F'
                                         AND e->>'person' IS NULL AND (e->>'live')::boolean AND e->>'retracted' IS NULL)
                           FROM jsonb_array_elements(j) e)
                    AND (SELECT count(DISTINCT e->>'school') FROM jsonb_array_elements(j) e) = 2,
      format('§91 (confirm): not one low notice per side, naming nobody: %s', j));
    SELECT * INTO r FROM match_result_confirm(F);
    PERFORM _assert(r.reason = 'already_official', format('§91 (confirm): a second confirm answered %s', r.reason));
    PERFORM _as((y->>'follower')::uuid);
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'official' AND NOT o.staff AND o.confirmed_at IS NOT NULL AND o.confirmed_as IS NULL
                    AND o.confirmation_id IS NULL AND o.confirmer IS NULL,
      format('§91 (confirm): a follower reads more than the word and the time: %s', to_jsonb(o)));
    SELECT * INTO o FROM public_match_result(F);
    PERFORM _assert(o.official AND o.official_at IS NOT NULL, format('§91 (confirm): the public result is not official: %s', to_jsonb(o)));

    -- (review)
    PERFORM _as(SCO);
    SELECT * INTO r FROM match_result_dispute(F, 'Verify 114: the scorer disagrees');
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (review): the scorer''s dispute answered %s', r.reason));
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_dispute(F, 'Verify 114: my own result');
    PERFORM _assert(r.reason = 'cannot_dispute_your_own', format('§91 (review): the confirmer''s dispute answered %s', r.reason));
    PERFORM _as(WDOS);
    SELECT * INTO r FROM match_result_dispute(F, 'short');
    PERFORM _assert(r.reason = 'note_required', format('§91 (review): a short note answered %s', r.reason));
    SELECT * INTO r FROM match_result_dispute(F, 'Verify 114: the fourth ball was a dot, not a single');
    PERFORM _assert(r.ok, format('§91 (review): the away director''s dispute was refused: %s', r.reason));
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'under_review' AND o.disputed_as = 'away_school' AND o.dispute_note LIKE 'Verify 114: the fourth%'
                    AND NOT o.can_clear,
      format('§91 (review): the disputant reads %s', to_jsonb(o)));
    PERFORM _as((y->>'follower')::uuid);
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'provisional' AND o.disputed_at IS NULL AND o.dispute_note IS NULL,
      format('§91 (review): a follower reads "under review": %s', to_jsonb(o)));
    SELECT * INTO o FROM public_match_result(F);
    PERFORM _assert(NOT o.official AND o.official_at IS NULL, format('§91 (review): the public result is official under review: %s', to_jsonb(o)));
    PERFORM _as((y->>'coach')::uuid);
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'under_review' AND o.staff AND o.disputed_as = 'away_school' AND o.dispute_note IS NULL
                    AND NOT o.can_clear AND NOT o.can_dispute,
      format('§91 (review): the coach reads the dispute''s words, or may act on it: %s', to_jsonb(o)));
    PERFORM _as(HPRIN);
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'under_review' AND o.dispute_note IS NOT NULL AND o.can_clear,
      format('§91 (review): the principal (audit.read) does not read the dispute''s words, or may not clear: %s', to_jsonb(o)));
    PERFORM _as(WDOS);
    SELECT * INTO r FROM match_result_dispute_clear(c1, 'Verify 114: I withdraw my point');
    PERFORM _assert(r.reason = 'cannot_clear_your_own', format('§91 (review): the disputant''s clear answered %s', r.reason));
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_dispute_clear(c1, 'Verify 114: the book shows a single');
    PERFORM _assert(r.ok AND (SELECT s.state FROM match_official_state(F) s) = 'official',
      format('§91 (review): cleared by the home director, the result is not official: %s', r.reason));
    PERFORM _as(WDOS);
    SELECT * INTO r FROM match_result_dispute(F, 'Verify 114: and again, the same ball');
    PERFORM _assert(r.reason = 'already_disputed', format('§91 (review): a second dispute answered %s', r.reason));

    -- (lapse) a correction by amendment: requested by the scorer, approved by the principal.
    a := _v114_request(F, keys[2], SCO);
    PERFORM _as(HPRIN);
    SELECT * INTO r FROM scoring_amendment_decide(a, true, 'Verify 114: approved again');
    j := _v114_rows(F);
    PERFORM _assert(r.ok AND j->0->>'lapsed_reason' = 'correction' AND (j->0->>'lapsed_seq')::integer = (_v114_fact(F)->>'head')::integer
                    AND _v114_fact(F)->>'state' = 'provisional',
      format('§91 (lapse): the void did not lapse the confirmation: %s / %s', r.reason, j));
    j := _v114_notes(F);
    PERFORM _assert((SELECT count(*) FROM jsonb_array_elements(j) e WHERE e->>'urgency' = 'low' AND e->>'retracted' = 'superseded') = 2
                    AND (SELECT count(*) FROM jsonb_array_elements(j) e WHERE e->>'retracts' IS NOT NULL) = 0
                    AND (SELECT count(*) FROM jsonb_array_elements(j) e
                          WHERE e->>'urgency' = 'medium' AND e->>'scope' = 'team' AND e->>'retracted' IS NULL
                            AND e->>'title' LIKE 'Result reopened · %'
                            AND e->>'body' LIKE '% is no longer official: the scorecard was corrected at %. It will be confirmed again.') = 2,
      format('§91 (lapse): not the two superseded and two reopened notices: %s', j));
    PERFORM _as(HDOS);
    SELECT * INTO o FROM match_official_state(F);
    PERFORM _assert(o.state = 'provisional' AND o.lapsed_reason = 'correction' AND o.was_official_at IS NOT NULL AND o.can_confirm,
      format('§91 (lapse): the director reads %s', to_jsonb(o)));
    SELECT * INTO r FROM match_result_confirm(F);
    j := _v114_rows(F);
    PERFORM _assert(r.ok AND jsonb_array_length(j) = 2 AND j->0->>'lapsed_at' IS NOT NULL AND j->1->>'lapsed_at' IS NULL
                    AND (j->1->>'head_seq')::integer > (j->0->>'head_seq')::integer,
      format('§91 (lapse): re-confirming did not keep the first row beside a second: %s', j));
    c2 := r.confirmation_id;
    SELECT * INTO r FROM match_result_decide(F, 'conceded', 'away', 'Verify 114: Westville conceded the match');
    j := _v114_rows(F);
    PERFORM _assert(r.ok AND j->1->>'lapsed_reason' = 'decision', format('§91 (lapse): a decision did not lapse it: %s', j));
    SELECT * INTO r FROM match_result_confirm(F);
    PERFORM _assert(r.ok AND (_v114_rows(F)->2->>'decision_id') IS NOT NULL, format('§91 (lapse): the decision is not pinned: %s', _v114_rows(F)));
    PERFORM _v114_status(F, 'abandoned');
    PERFORM _assert(_v114_rows(F)->2->>'lapsed_reason' = 'status', format('§91 (lapse): a status change did not lapse it: %s', _v114_rows(F)));

    -- (league) the organiser's, and the table that does not wait for him.
    PERFORM _as(ORG);
    SELECT string_agg(s.display_name || '=' || s.points || '/' || s.played, ' ' ORDER BY s.display_name), min(s.provisional_results)
      INTO pts_before, prov_before FROM competition_standing s WHERE s.competition_id = C;
    SELECT * INTO r FROM match_result_confirm(L);
    PERFORM _assert(r.ok AND _v114_rows(L)->0->>'confirmed_as' = 'organiser', format('§91 (league): the organiser''s confirmation: %s', _v114_rows(L)));
    c1 := r.confirmation_id;
    SELECT string_agg(s.display_name || '=' || s.points || '/' || s.played, ' ' ORDER BY s.display_name) INTO got
      FROM competition_standing s WHERE s.competition_id = C;
    PERFORM _assert(got = pts_before AND got LIKE '%V114 Hilton U17E=%' AND prov_before >= 2
                    AND (SELECT min(s.provisional_results) FROM competition_standing s WHERE s.competition_id = C) = prov_before - 1
                    AND (SELECT min(p.provisional_results) FROM public_competition_standing(C) p) = prov_before - 1,
      format('§91 (league): the table moved (%s → %s), or the count did not fall from %s', pts_before, got, prov_before));
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_dispute(L, 'Verify 114: Hilton disputes the league result');
    PERFORM _assert(r.ok, format('§91 (league): the home director may not dispute: %s', r.reason));
    SELECT * INTO r FROM match_result_dispute_clear(c1, 'Verify 114: Hilton clears its own');
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (league): a school cleared a league dispute: %s', r.reason));
    PERFORM _as(ORG);
    SELECT * INTO r FROM match_result_dispute_clear(c1, 'Verify 114: the organiser has looked');
    PERFORM _assert(r.ok, format('§91 (league): the organiser could not clear: %s', r.reason));
    SELECT * INTO r FROM match_result_confirmation_withdraw(c1, 'Verify 114: confirmed the wrong fixture');
    PERFORM _assert(r.ok AND (SELECT s.state FROM match_official_state(L) s) = 'provisional'
                    AND (SELECT count(*) FROM jsonb_array_elements(_v114_notes(L)) e
                          WHERE e->>'urgency' = 'medium' AND e->>'scope' = 'team'
                            AND e->>'body' LIKE '%the confirmation was withdrawn at%') = 2,
      format('§91 (league): the withdrawal: %s / %s', r.reason, _v114_notes(L)));
    -- ...and the organiser is told too: the league has no organising school,
    -- so each competition administrator appointed with no school, by name (D8, D9).
    PERFORM _assert((SELECT count(*) FROM jsonb_array_elements(_v114_notes(L)) e
                      WHERE e->>'scope' = 'competition' AND (e->>'recipient')::uuid = ORG AND e->>'urgency' = 'medium'
                        AND e->>'cap' = 'competition.manage' AND e->>'body' LIKE '%the confirmation was withdrawn at%') = 1
                    AND (SELECT count(*) FROM jsonb_array_elements(_v114_notes(L)) e
                          WHERE e->>'scope' = 'competition' AND (e->>'recipient')::uuid = HDOS) = 0
                    AND EXISTS (SELECT 1 FROM my_notifications n WHERE n.subject_id = L AND n.title LIKE 'Result reopened · %'),
      format('§91 (league): the organiser of a league with no organising school was not told, or does not read it: %s', _v114_notes(L)));

    -- (window)
    SELECT * INTO r FROM match_result_confirm(L);
    c1 := r.confirmation_id;
    PERFORM _v114_age(c1);
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_dispute(L, 'Verify 114: too late to say so');
    PERFORM _assert(r.reason = 'window_closed', format('§91 (window): a late dispute answered %s', r.reason));
    PERFORM _as(ORG);
    SELECT * INTO r FROM match_result_confirmation_withdraw(c1, 'Verify 114: too late to take back');
    PERFORM _assert(r.reason = 'window_closed', format('§91 (window): a late withdrawal answered %s', r.reason));

    -- (abandoned) Q6.
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_confirm(AM);
    PERFORM _assert(r.ok AND (SELECT s.state FROM match_official_state(AM) s) = 'official',
      format('§91 (abandoned): an abandoned match with no ball was not made official: %s', r.reason));

    -- (organiser) a league Hilton organises: its administrator is the
    -- organiser; Hilton's director is a school's, never the organiser.
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_result_confirm((y->>'H')::uuid);
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (organiser): the organising school''s director confirmed its own win: %s', r.reason));
    PERFORM _as((y->>'horg')::uuid);
    SELECT * INTO r FROM match_result_confirm((y->>'H')::uuid);
    PERFORM _assert(r.ok AND _v114_rows((y->>'H')::uuid)->0->>'confirmed_as' = 'organiser',
      format('§91 (organiser): the cup''s administrator could not confirm as organiser: %s / %s', r.reason, _v114_rows((y->>'H')::uuid)));
    c1 := r.confirmation_id;
    PERFORM _as(WDOS);
    SELECT * INTO r FROM match_result_dispute((y->>'H')::uuid, 'Verify 114: Westville''s book has the sixth ball a dot');
    PERFORM _assert(r.ok, format('§91 (organiser): Westville could not dispute: %s', r.reason));
    PERFORM _as(HDOS);
    SELECT * INTO o FROM match_official_state((y->>'H')::uuid);
    PERFORM _assert(o.state = 'under_review' AND o.dispute_note IS NULL AND NOT o.can_clear,
      format('§91 (organiser): Hilton''s director reads Westville''s note, or may clear it: %s', to_jsonb(o)));
    SELECT * INTO r FROM match_result_dispute_clear(c1, 'Verify 114: Hilton says it stands');
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (organiser): Hilton''s director cleared the dispute against it: %s', r.reason));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM results_to_confirm() t WHERE t.match_id = (y->>'H')::uuid),
      '§91 (organiser): Hilton''s director is offered the dispute against Hilton to settle');
    PERFORM _as((y->>'horg')::uuid);
    SELECT * INTO o FROM match_official_state((y->>'H')::uuid);
    PERFORM _assert(o.dispute_note LIKE 'Verify 114: Westville%' AND o.can_clear,
      format('§91 (organiser): the administrator does not read the note, or may not clear: %s', to_jsonb(o)));
    SELECT * INTO r FROM match_result_dispute_clear(c1, 'Verify 114: both books checked; it stands');
    PERFORM _assert(r.ok, format('§91 (organiser): the administrator could not clear: %s', r.reason));

    -- (forged) a pad void whose payload claims an approved amendment counts
    -- for nothing: the seal is broken, and the director it names is no hand.
    PERFORM _as(HDOS);
    SELECT * INTO r FROM match_confirmable((y->>'FG')::uuid);
    PERFORM _assert(r.reason = 'innings_unsealed' AND NOT (_v114_fact((y->>'FG')::uuid)->>'seals')::boolean
                    AND _v114_hand((y->>'FG')::uuid, HDOS) IS NULL,
      format('§91 (forged): a forged amendment payload answered %s, seals %s, hand %s', r.reason,
             _v114_fact((y->>'FG')::uuid)->>'seals', _v114_hand((y->>'FG')::uuid, HDOS)));
    -- (badseal) a seal that never stood, with nothing after it, is no seal.
    SELECT * INTO r FROM match_confirmable((y->>'BS')::uuid);
    PERFORM _assert(r.reason = 'innings_unsealed', format('§91 (badseal): a seal that never stood answered %s', r.reason));

    -- (reads)
    PERFORM _as((y->>'outsider')::uuid);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM match_official_state(F))
                    AND NOT EXISTS (SELECT 1 FROM match_result_confirmation WHERE match_id = F),
      '§91 (reads): a reader of neither side reads the state or a row');
    SELECT * INTO r FROM match_confirmable(F);
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (reads): an outsider learned %s', r.reason));
    PERFORM _as(HDOS);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', TM::text, true);
    SELECT * INTO r FROM match_result_confirm(TM);
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (reads): a pad''s credential confirmed: %s', r.reason));
    SELECT * INTO r FROM match_result_dispute(L2, 'Verify 114: from the pad');
    PERFORM _assert(r.reason = 'not_permitted', format('§91 (reads): a pad''s credential disputed: %s', r.reason));
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert((SELECT count(*) FROM match_result_confirmation WHERE match_id = F) = 3,
      '§91 (reads): the director does not read the friendly''s three rows');
    BEGIN
      PERFORM dispute_note FROM match_result_confirmation LIMIT 1;
      PERFORM _assert(false, '§91 (reads): the application read a dispute''s note');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      PERFORM confirmed_by FROM match_result_confirmation LIMIT 1;
      PERFORM _assert(false, '§91 (reads): the application read who confirmed');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      INSERT INTO match_result_confirmation (match_id, head_seq, result_hash, confirmed_by, confirmed_as, window_closes_at)
      VALUES (F, 0, md5('x'), HDOS, 'home_school', now());
      PERFORM _assert(false, '§91 (reads): the application wrote a confirmation');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    FOREACH x IN ARRAY ARRAY['match_head_seq(uuid)', 'match_verified(uuid)', 'result_lapse(uuid,text)',
                             'result_official_notices(uuid,text,timestamptz)', 'match_official_core(uuid)'] LOOP
      PERFORM _assert(NOT has_function_privilege('scrbrd_app', to_regprocedure(x), 'EXECUTE'),
        format('§91 (reads): the application may call %s', x));
    END LOOP;
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 91
  -- └── db/114 (section 91) ──────────────────────────────────────────
  -- ┌── db/115 (section 92) ──────────────────────────────────────────
  -- ── 92. A family's consents are the family's (db/115, REACH R-B) ──
  -- Kameel, 16 Oct 2026. Passport consent: office only. Scouting consent:
  -- keep the coach. Staged by _v115_stage(); every read is the caller's own,
  -- under row security (_v115_passport(), _v115_scouting()).
  --
  -- What each label holds:
  --   (family)    a guardian reads her child's passport consents (live and
  --               withdrawn) and scouting decision, and no other family's at
  --               the same receiving school or on the same side; the boy
  --               reads his own through his self-access link
  --   (team-mate) O6: a pupil reads no team-mate's scouting decision, though
  --               his `player` role holds player.profile.read across the side;
  --               nor does a pupil at Westville read W's
  --   (office)    the office of the school a passport consent names reads
  --               what names it and nothing naming another school; the office
  --               at the boy's school reads his side's and other sides'
  --               scouting decisions, and not another school's; the owner's
  --               key reads all
  --   (coach)     decision 1: the receiving school's coach, its director of
  --               sport, a parent and a pupil there read no passport consent,
  --               and the coach still opens the passport (passport_open(),
  --               passport_name()), and not one nobody named his school for.
  --               Decision 2: his own side's coach and assistant coach read
  --               the side's scouting decisions; another side's coach reads
  --               his own side's and none of these; the coach of the same
  --               team code at another school reads only his own boy's; the
  --               director of sport reads his school's (school-wide
  --               player.development.read)
  --   (sending)   §6.2: a coach at the sending school reads no passport
  --               consent; nor do his office, principal or director of sport
  --               (the school concerned is the one the row names)
  --   (nobody)    the team manager, scorer, physio, analyst, scout and a
  --               spectator read neither table's staged rows
  --   (writes)    the receiving office cannot name a school for a boy; a coach
  --               cannot decide a scouting consent; the guardian can, and
  --               reads the change
  --   (doors)     both read policies exactly as db/115 wrote them, the only
  --               permissive read on each table, and no read under
  --               player.profile.read left on either
  --
  -- Falsified, each change made as the owner before this section ran (the
  -- section alone, cut from this file, on 16 Oct 2026), each red the first:
  --   passport_consent_read back to db/08's       → (coach) red: wescoach at the
  --     (player.profile.read, zeros, '*')            receiving school reads
  --                                                  [A>WES,M>WES]
  --   passport: the family alone, no office term  → (office) red: the receiving
  --                                                  wesoffice reads []
  --   passport: the office at the BOY's school    → (office) red: the receiving
  --     (player_school) instead of to_school_id      wesoffice reads []
  --   player_scouting_consent_read back to db/08  → (team-mate) red: the pupil
  --                                                  aboy reads [A,M(w)]
  --   scouting: the coach term as                 → (team-mate) red: the pupil
  --     player.profile.read ("as today")             aboy reads [A,M(w)]
  --   scouting: no coach term                     → (coach) red: coach18 reads []
  --   scouting: the coach term at '*' (any side)  → (coach) red: coach18 reads
  --                                                  [A,B,M(w)]
  --   scouting: no office term                    → (office) red: office reads []
  --   scouting: no family term                    → (family) red: ga reads []
  DECLARE
    y   jsonb := _v115_stage();
    got text;
    who text;
    v_ok boolean;
    v_reason text;
  BEGIN
    -- (family)
    FOR who, got IN SELECT * FROM (VALUES ('ga', 'A>WES,A>X'), ('aboy', 'A>WES,A>X'),
                                          ('gm', 'M>WES,M>X(w)'), ('mboy', 'M>WES,M>X(w)')) v LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_passport(y) = got,
        format('§92 (family): %s reads passport consents [%s], not [%s]', who, _v115_passport(y), got));
    END LOOP;
    FOR who, got IN SELECT * FROM (VALUES ('ga', 'A'), ('gm', 'M(w)'), ('wesg', 'W')) v LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_scouting(y) = got,
        format('§92 (family): %s reads scouting decisions [%s], not [%s]', who, _v115_scouting(y), got));
    END LOOP;

    -- (team-mate)
    FOR who, got IN SELECT * FROM (VALUES ('aboy', 'A'), ('mboy', 'M(w)'), ('wesmate', '')) v LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_scouting(y) = got,
        format('§92 (team-mate): the pupil %s reads scouting decisions [%s], not [%s]', who, _v115_scouting(y), got));
    END LOOP;

    -- (office)
    FOR who, got IN SELECT * FROM (VALUES ('wesoffice', 'A>WES,M>WES'), ('wesprincipal', 'A>WES,M>WES')) v LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_passport(y) = got,
        format('§92 (office): the receiving %s reads passport consents [%s], not [%s]', who, _v115_passport(y), got));
    END LOOP;
    FOR who, got IN SELECT * FROM (VALUES ('office', 'A,B,M(w)'), ('principal', 'A,B,M(w)'),
                                          ('wesoffice', 'W'), ('wesprincipal', 'W')) v LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_scouting(y) = got,
        format('§92 (office): %s reads scouting decisions [%s], not [%s]', who, _v115_scouting(y), got));
    END LOOP;
    PERFORM _as(U_OWNER);
    PERFORM _assert(_v115_passport(y) = 'A>WES,A>X,M>WES,M>X(w)' AND _v115_scouting(y) = 'A,B,M(w),W',
      format('§92 (office): the owner''s key reads [%s] and [%s]', _v115_passport(y), _v115_scouting(y)));

    -- (coach) decision 1: the receiving school reads the passport, not the consents
    FOREACH who IN ARRAY ARRAY['wescoach', 'wesdos', 'wesg', 'wesmate'] LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_passport(y) = '',
        format('§92 (coach): %s at the receiving school reads passport consents [%s]', who, _v115_passport(y)));
    END LOOP;
    PERFORM _as((y->>'wescoach')::uuid);
    PERFORM _assert(_passport_open((y->>'A')::uuid) AND passport_name((y->>'A')::uuid) = 'Verify OneFifteen Able',
      '§92 (coach): the receiving coach can no longer open the passport his school was named for');
    PERFORM _assert(NOT _passport_open((y->>'B')::uuid) AND passport_name((y->>'B')::uuid) IS NULL,
      '§92 (coach): the receiving coach opens a passport nobody named his school for');
    -- decision 2: his own side's coach reads the side's scouting decisions
    FOR who, got IN SELECT * FROM (VALUES ('coach18', 'A,M(w)'), ('asst18', 'A,M(w)'), ('coach19', 'B'),
                                          ('wescoach', 'W'), ('dos', 'A,B,M(w)'), ('wesdos', 'W')) v LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_scouting(y) = got,
        format('§92 (coach): %s reads scouting decisions [%s], not [%s]', who, _v115_scouting(y), got));
    END LOOP;

    -- (sending)
    FOREACH who IN ARRAY ARRAY['coach18', 'asst18', 'dos', 'office', 'principal'] LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_passport(y) = '',
        format('§92 (sending): %s at the sending school reads passport consents [%s]', who, _v115_passport(y)));
    END LOOP;

    -- (nobody)
    FOREACH who IN ARRAY ARRAY['manager18', 'coach19', 'scorer', 'medical', 'analyst', 'scout', 'spec'] LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(_v115_passport(y) = '' AND (who = 'coach19' OR _v115_scouting(y) = ''),
        format('§92 (nobody): %s reads [%s] and [%s]', who, _v115_passport(y), _v115_scouting(y)));
    END LOOP;

    -- (writes)
    PERFORM _as((y->>'wesoffice')::uuid);
    got := 'written';
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'B')::uuid, WES);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'refused', '§92 (writes): the receiving office named its own school for a boy');
    PERFORM _as((y->>'coach18')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set((y->>'A')::uuid, false) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_a_consented_guardian',
      format('§92 (writes): the coach''s scouting decision was answered %s/%s', v_ok, v_reason));
    PERFORM _as((y->>'ga')::uuid);
    SELECT s.ok INTO v_ok FROM scouting_consent_set((y->>'A')::uuid, false) s;
    PERFORM _assert(v_ok AND _v115_scouting(y) = 'A(w)',
      format('§92 (writes): the guardian''s withdrawal answered %s and reads [%s]', v_ok, _v115_scouting(y)));
    PERFORM _as((y->>'aboy')::uuid);
    PERFORM _assert(_v115_scouting(y) = 'A(w)',
      format('§92 (writes): the boy reads his withdrawn decision as [%s]', _v115_scouting(y)));

    -- (doors)
    PERFORM _assert((SELECT pg_get_expr(p.polqual, p.polrelid) FROM pg_policy p
                      WHERE p.polrelid = 'passport_consent'::regclass AND p.polname = 'passport_consent_read'
                        AND p.polcmd = 'r' AND p.polpermissive)
                    = '(is_family_of(player_id) OR app_can(''guardian.link.manage''::text, to_school_id, ''*''::text, ''00000000-0000-0000-0000-000000000000''::uuid, ''00000000-0000-0000-0000-000000000000''::uuid))',
      '§92 (doors): passport_consent_read is not db/115''s');
    PERFORM _assert((SELECT pg_get_expr(p.polqual, p.polrelid) FROM pg_policy p
                      WHERE p.polrelid = 'player_scouting_consent'::regclass AND p.polname = 'player_scouting_consent_read'
                        AND p.polcmd = 'r' AND p.polpermissive)
                    = '(is_family_of(player_id) OR app_can(''guardian.link.manage''::text, player_school(player_id), ''*''::text, ''00000000-0000-0000-0000-000000000000''::uuid, ''00000000-0000-0000-0000-000000000000''::uuid) OR app_can(''player.development.read''::text, player_school(player_id), player_team(player_id), player_id, ''00000000-0000-0000-0000-000000000000''::uuid))',
      '§92 (doors): player_scouting_consent_read is not db/115''s');
    PERFORM _assert((SELECT count(*) FROM pg_policy p
                      WHERE p.polrelid IN ('passport_consent'::regclass, 'player_scouting_consent'::regclass)
                        AND p.polpermissive AND p.polcmd IN ('r', '*')) = 2
                    AND NOT EXISTS (SELECT 1 FROM pg_policy p
                                     WHERE p.polrelid IN ('passport_consent'::regclass, 'player_scouting_consent'::regclass)
                                       AND p.polpermissive
                                       AND pg_get_expr(p.polqual, p.polrelid) LIKE '%player.profile.read%'),
      '§92 (doors): a second permissive read, or a player.profile.read one, stands on the consent tables');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 92
  -- └── db/115 (section 92) ──────────────────────────────────────────
  -- ┌── db/116 (section 93) ──────────────────────────────────────────
  -- ┌── section 93: who reads a child's data (db/116) ──
  -- READERS_child_data §7, decided by Kameel on 21 Oct 2026. One label per
  -- decision that has SQL:
  --   (Q2 reasons)   the DSO (audit.read) reads no disable reason, no role
  --                  ending's reason, no amendment's reason, no staff
  --                  register; the office reads the two that are its acts,
  --                  the approver the amendment; the log still lists the
  --                  ending, with no reason in it; the access log is read.
  --                  A guardian link's ending (db/109) is §86's: the office
  --                  reads it, the director of sport (audit.read) does not
  --   (Q3 departed)  d's injury and the physio's review of it: the physio
  --                  and his coach read them while he is at Hilton and not
  --                  once he has left; the office and his parent still do;
  --                  the head does not (not the office's key); he re-enrols
  --                  and the physio reads both again
  --   (Q7 twelve)    a pupil of thirteen says no: recorded, and competent in
  --                  the facts; a yes from him is refused (not_yet_eighteen);
  --                  a no at eleven is refused (not_yet_twelve); his
  --                  guardian's later yes is recorded beside it
  --   (Q8 notice)    compromise is a kind; to a pupil of nineteen it is
  --                  admitted and lives 730 days; to a pupil of thirteen it
  --                  is refused, and so is any other kind but system;
  --                  system to the thirteen-year-old is as it was
  --   (Q10 league)   the league reads no disciplinary_record row; through
  --                  competition_discipline_records() it reads none of r1,
  --                  r2 (a competition with no organiser) or r3 (no
  --                  competition), being platform-wide (db/118; §95 proves
  --                  the school-scoped league), and nothing is logged;
  --                  another school's league reads none; the office none
  --   (Q5 coach)     the 16XI coach reads h's records through
  --                  side_discipline_records() (r1, r3), not the table; the
  --                  read is logged; the 15XI coach reads none until h moves
  --                  to 15XI, and then the old coach reads none
  --   (Q11 concern)  a Westville parent names Hilton's h, on Hilton's sheet
  --                  at f: the concern is Hilton's, held by Hilton; Westville
  --                  is told one exists and nothing more; k, on no sheet, is
  --                  refused as child_not_visible
  --   (Q12 manifest) the coordinator reads no emergency_contact row; today's
  --                  trip's manifest he reads (h); a trip in ten days, and a
  --                  cancelled one, he does not; the sports office, which
  --                  holds transport.manage and no manifest, reads none
  --   (Q13 scorer)   the Westville pupil scoring f reads, of Hilton, the boy
  --                  on the sheet (h) and nobody else; not h's honour, side
  --                  history or recognition(); the adult scorer of the same
  --                  fixture still reads the roster (the cut is a pupil's);
  --                  the pupil reads his own side as before
  --   (A1 passport)  h's passport (his family has named Westville): open to
  --                  his parent, the office, the head (guardian.link.manage),
  --                  his coach and Westville's coach; shut to two team-mates,
  --                  another side's coach, the physio, Westville's parent and
  --                  DSO, Hilton's DSO, the adult scorer and the pupil
  --                  scorer (a Westville pupil, player.profile.read there);
  --                  no rating line and no assessing coach on it; the four
  --                  doors and scouting_candidates() are not PUBLIC's (A5)
  --   (Q14, Q15, Q16) a pupil holds no audit.read; a parent reads no conduct
  --                  record; a pupil's own ID number is NULL to him and not
  --                  to his parent (held)
  --
  -- Falsified, each change made as the owner before this file ran:
  --   db/90's audit.read arm put back on account_status_change_read
  --                                       → (Q2 reasons) red: the DSO read the
  --                                         disable reason
  --   injury_departed_cut dropped         → (Q3 departed) red: the physio read
  --                                         a departed boy's injury
  --   player_pupil_sheet_only dropped     → (Q13 scorer) red: the pupil read k
  DECLARE
    y    jsonb := _v116_stage();
    HIL  uuid := '11111111-1111-1111-1111-111111111111';
    WES  uuid := '22222222-2222-2222-2222-222222222222';
    NIL  uuid := '00000000-0000-0000-0000-000000000000';
    U_LEAGUE uuid := '88888888-0000-0000-0000-000000000021';
    U_SELF   uuid := '88888888-0000-0000-0000-000000000009';  -- R Pillay, his own record
    P_PILLAY uuid := 'aaaaaaaa-0000-0000-0000-000000000005';
    got  text;
    n    int;
    v_ok boolean;
    v_reason text;
    v_ref text;
  BEGIN
    -- (Q2 reasons)
    PERFORM _as((y->>'dso')::uuid);
    SELECT count(*) INTO n FROM account_status_change WHERE id = (y->>'status')::uuid;
    PERFORM _assert(n = 0, '§93 (Q2 reasons): the DSO read why an account was disabled');
    SELECT count(*) INTO n FROM role_assignment_ending WHERE assignment_id = (y->>'ended')::uuid;
    PERFORM _assert(n = 0, '§93 (Q2 reasons): the DSO read why a role was ended');
    SELECT count(*) INTO n FROM scoring_amendment WHERE id = (y->>'amend')::uuid;
    PERFORM _assert(n = 0, '§93 (Q2 reasons): the DSO read why a ball was amended');
    SELECT count(*) INTO n FROM school_register_rows(HIL) r WHERE r.id = (y->>'register')::uuid;
    PERFORM _assert(n = 0, '§93 (Q2 reasons): the DSO read the staff register');
    SELECT count(*) INTO n FROM audit_log(HIL, ARRAY['role']) l WHERE l.key = 'role:' || (y->>'ended');
    PERFORM _assert(n = 1, '§93 (Q2 reasons): the log no longer lists the ending to the DSO');
    SELECT count(*) INTO n FROM audit_log(HIL, ARRAY['role']) l
     WHERE l.key = 'role:' || (y->>'ended') AND (l.detail::text LIKE '%hearing%' OR l.action LIKE '%hearing%');
    PERFORM _assert(n = 0, '§93 (Q2 reasons): the log carries the ending''s reason');
    SELECT count(*) INTO n FROM access_log WHERE school_id = HIL AND resource = 'audit_log';
    PERFORM _assert(n >= 1, '§93 (Q2 reasons): the DSO cannot read the access log (audit.read opens it)');
    PERFORM _as((y->>'office')::uuid);
    SELECT count(*) INTO n FROM account_status_change WHERE id = (y->>'status')::uuid;
    PERFORM _assert(n = 1, '§93 (Q2 reasons): the office (user.invite) cannot read the disable reason');
    SELECT count(*) INTO n FROM role_assignment_ending WHERE assignment_id = (y->>'ended')::uuid;
    PERFORM _assert(n = 1, '§93 (Q2 reasons): the office (user.role.assign) cannot read the ending');
    SELECT count(*) INTO n FROM school_register_rows(HIL) r WHERE r.id = (y->>'register')::uuid;
    PERFORM _assert(n = 1, '§93 (Q2 reasons): the office cannot read its staff register');
    SELECT count(*) INTO n FROM scoring_amendment WHERE id = (y->>'amend')::uuid;
    PERFORM _assert(n = 0, '§93 (Q2 reasons): the office (audit.read, no approval) read an amendment''s reason');
    PERFORM _as((y->>'head')::uuid);
    SELECT count(*) INTO n FROM scoring_amendment WHERE id = (y->>'amend')::uuid;
    PERFORM _assert(n = 1, '§93 (Q2 reasons): the approver cannot read the amendment');
    PERFORM _as((y->>'scorer')::uuid);
    SELECT count(*) INTO n FROM scoring_amendment WHERE id = (y->>'amend')::uuid;
    PERFORM _assert(n = 1, '§93 (Q2 reasons): the requester cannot read his own amendment');

    -- (Q3 departed)
    FOREACH got IN ARRAY ARRAY['physio', 'coach', 'office', 'parent'] LOOP
      PERFORM _as((y->>got)::uuid);
      SELECT count(*) INTO n FROM injury_masked WHERE id = (y->>'injury')::uuid;
      PERFORM _assert(n = 1, format('§93 (Q3 departed): the %s cannot read the injury of a boy at school', got));
      SELECT count(*) INTO n FROM injury_review_masked WHERE id = (y->>'review')::uuid;
      PERFORM _assert(n = 1, format('§93 (Q3 departed): the %s cannot read the review of a boy at school', got));
    END LOOP;
    PERFORM _v116_move((y->>'d')::uuid, NULL);
    FOREACH got IN ARRAY ARRAY['physio', 'coach', 'head'] LOOP
      PERFORM _as((y->>got)::uuid);
      SELECT count(*) INTO n FROM injury_masked WHERE id = (y->>'injury')::uuid;
      PERFORM _assert(n = 0, format('§93 (Q3 departed): the %s reads the injury of a boy who has left', got));
      SELECT count(*) INTO n FROM injury_review_masked WHERE id = (y->>'review')::uuid;
      PERFORM _assert(n = 0, format('§93 (Q3 departed): the %s reads the review of a boy who has left', got));
    END LOOP;
    PERFORM _as((y->>'physio')::uuid);
    SELECT count(*) INTO n FROM injury_worklist() w WHERE w.injury_id = (y->>'injury')::uuid;
    PERFORM _assert(n = 0, '§93 (Q3 departed): a departed boy is on the physio''s worklist');
    FOREACH got IN ARRAY ARRAY['office', 'sports', 'parent'] LOOP
      PERFORM _as((y->>got)::uuid);
      SELECT count(*) INTO n FROM injury_masked WHERE id = (y->>'injury')::uuid;
      PERFORM _assert(n = 1, format('§93 (Q3 departed): the %s no longer reads the injury of a boy who has left', got));
    END LOOP;
    FOREACH got IN ARRAY ARRAY['office', 'parent'] LOOP
      PERFORM _as((y->>got)::uuid);
      SELECT count(*) INTO n FROM injury_review_masked WHERE id = (y->>'review')::uuid;
      PERFORM _assert(n = 1, format('§93 (Q3 departed): the %s no longer reads the review of a boy who has left', got));
    END LOOP;
    PERFORM _v116_move((y->>'d')::uuid, '16XI');
    PERFORM _as((y->>'physio')::uuid);
    SELECT count(*) INTO n FROM injury_masked WHERE id = (y->>'injury')::uuid;
    PERFORM _assert(n = 1, '§93 (Q3 departed): re-enrolment did not reopen the physio''s read');
    SELECT count(*) INTO n FROM injury_review_masked WHERE id = (y->>'review')::uuid;
    PERFORM _assert(n = 1, '§93 (Q3 departed): re-enrolment did not reopen the physio''s read of the review');

    -- (Q7 twelve)
    PERFORM _as((y->>'teen')::uuid);
    SELECT c.ok, c.reason INTO v_ok, v_reason FROM public_name_consent_set((y->>'t')::uuid, true, 'v116') c;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_eighteen', format('§93 (Q7 twelve): his yes at thirteen answered %s/%s', v_ok, v_reason));
    SELECT c.ok, c.reason INTO v_ok, v_reason FROM public_name_consent_set((y->>'t')::uuid, false, 'v116') c;
    PERFORM _assert(v_ok, format('§93 (Q7 twelve): his no at thirteen answered %s/%s', v_ok, v_reason));
    PERFORM _as((y->>'young')::uuid);
    SELECT c.ok, c.reason INTO v_ok, v_reason FROM public_name_consent_set((y->>'y')::uuid, false, 'v116') c;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_twelve', format('§93 (Q7 twelve): a no at eleven answered %s/%s', v_ok, v_reason));
    PERFORM _as((y->>'parent')::uuid);
    SELECT c.ok, c.reason INTO v_ok, v_reason FROM public_name_consent_set((y->>'t')::uuid, true, 'v116') c;
    PERFORM _assert(v_ok, format('§93 (Q7 twelve): his guardian''s yes answered %s/%s', v_ok, v_reason));
    got := (SELECT string_agg((x->>'by') || ':' || (x->>'competent') || ':' || coalesce(x->>'endedOn', 'open'), ',' ORDER BY x->>'by')
              FROM jsonb_array_elements(public_name_facts((y->>'t')::uuid)->'consents') x);
    PERFORM _assert(got = format('guardian:true:open,pupil:true:%s', to_char(sa_today(), 'YYYY-MM-DD')),
      format('§93 (Q7 twelve): the facts read %s', got));

    -- (Q8 notice)
    got := _v116_notice((y->>'adult')::uuid, 'compromise');
    PERFORM _assert(got = 'ok', format('§93 (Q8 notice): a compromise notice to a pupil of nineteen answered %s', got));
    PERFORM _assert(_v116_fact('life', (y->>'adult')::uuid) = '730',
      format('§93 (Q8 notice): a compromise notice lives %s days', _v116_fact('life', (y->>'adult')::uuid)));
    got := _v116_notice((y->>'teen')::uuid, 'compromise');
    PERFORM _assert(got LIKE '23514:%', format('§93 (Q8 notice): a compromise notice to a pupil of thirteen answered %s', got));
    got := _v116_notice((y->>'adult')::uuid, 'welfare');
    PERFORM _assert(got LIKE '23514:%', format('§93 (Q8 notice): a welfare notice to one pupil of nineteen answered %s', got));
    got := _v116_notice((y->>'teen')::uuid, 'system');
    PERFORM _assert(got = 'ok', format('§93 (Q8 notice): the system''s own notice to a pupil of thirteen answered %s', got));
    got := _v116_notice((y->>'office')::uuid, 'gossip');
    PERFORM _assert(got = '23514:notification_kind_known', format('§93 (Q8 notice): a kind outside the list answered %s', got));

    -- (Q10 league). db/116 let this platform-wide league read r1 and r2
    -- through its door. db/118 (Kameel, 28 Oct 2026: "Only its own
    -- competitions: refuse a platform-wide caller") closes the door to a
    -- platform-wide caller, and this competition names no organiser, which
    -- opens it to nobody: it reads nothing, and nothing is logged. §95 proves
    -- a school-scoped league reads its own competition's records, logged per
    -- school.
    PERFORM _as(U_LEAGUE);
    SELECT count(*) INTO n FROM disciplinary_record WHERE id IN ((y->>'r1')::uuid, (y->>'r2')::uuid, (y->>'r3')::uuid);
    PERFORM _assert(n = 0, format('§93 (Q10 league): the league read %s disciplinary_record row(s) by standing', n));
    got := (SELECT string_agg(z.x, ',' ORDER BY z.x) FROM (SELECT CASE r.id WHEN (y->>'r1')::uuid THEN 'r1' WHEN (y->>'r2')::uuid THEN 'r2' WHEN (y->>'r3')::uuid THEN 'r3' END AS x
              FROM competition_discipline_records((y->>'c')::uuid) r) z);
    PERFORM _assert(got IS NULL, format('§93 (Q10 league): through its door the platform-wide league read %s (db/118)', got));
    SELECT count(*) INTO n FROM competition_discipline_records(NULL) r WHERE r.id = (y->>'r3')::uuid;
    PERFORM _assert(n = 0, '§93 (Q10 league): the league read a record from a match in no competition');
    PERFORM _assert(_v116_fact('logged', U_LEAGUE, HIL) = '0:' AND _v116_fact('logged', U_LEAGUE, WES) = '0:',
      format('§93 (Q10 league): a read that returned nothing was logged: Hilton %s, Westville %s',
             _v116_fact('logged', U_LEAGUE, HIL), _v116_fact('logged', U_LEAGUE, WES)));
    FOREACH got IN ARRAY ARRAY['wesleague', 'office'] LOOP
      PERFORM _as((y->>got)::uuid);
      SELECT count(*) INTO n FROM competition_discipline_records((y->>'c')::uuid);
      PERFORM _assert(n = 0, format('§93 (Q10 league): the %s read %s record(s) through the league''s door', got, n));
    END LOOP;

    -- (Q5 coach): his own side's records, logged; not by standing; a boy
    -- moved takes his record to his new coach.
    PERFORM _as((y->>'coach')::uuid);
    SELECT count(*) INTO n FROM disciplinary_record WHERE player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 0, format('§93 (Q5 coach): the coach read %s disciplinary_record row(s) by standing', n));
    got := (SELECT string_agg(z.x, ',' ORDER BY z.x) FROM (SELECT CASE r.id WHEN (y->>'r1')::uuid THEN 'r1' WHEN (y->>'r3')::uuid THEN 'r3' ELSE 'other' END AS x
              FROM side_discipline_records(NULL) r) z);
    PERFORM _assert(got = 'r1,r3', format('§93 (Q5 coach): his side''s records read %s', coalesce(got, 'nothing')));
    PERFORM _assert(_v116_fact('side_logged', (y->>'coach')::uuid, (y->>'h')::uuid) = '1',
      format('§93 (Q5 coach): his read was logged %s time(s)', _v116_fact('side_logged', (y->>'coach')::uuid, (y->>'h')::uuid)));
    PERFORM _as((y->>'coach15')::uuid);
    SELECT count(*) INTO n FROM side_discipline_records(NULL) r WHERE r.player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 0, '§93 (Q5 coach): another side''s coach read the boy''s records');
    PERFORM _v116_move((y->>'h')::uuid, '15XI');
    SELECT count(*) INTO n FROM side_discipline_records(NULL) r WHERE r.player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 2, '§93 (Q5 coach): the moved boy''s records did not follow him to his new coach');
    PERFORM _as((y->>'coach')::uuid);
    SELECT count(*) INTO n FROM side_discipline_records(NULL) r WHERE r.player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 0, '§93 (Q5 coach): the old coach still reads a moved boy''s records');
    PERFORM _v116_move((y->>'h')::uuid, '16XI');
    PERFORM _as((y->>'parent')::uuid);
    SELECT count(*) INTO n FROM side_discipline_records(NULL);
    PERFORM _assert(n = 0, '§93 (Q5 coach): a parent read through the coach''s door');

    -- (Q11 concern)
    PERFORM _as((y->>'wesparent')::uuid);
    SELECT c.ok, c.reason, c.reference INTO v_ok, v_reason, v_ref
      FROM safeguarding_concern_raise(WES, 'child', ARRAY['physical'], 'suspicion',
                                      'v116: I saw the Hilton boy pushed to the ground by an adult after play.', 'witness',
                                      (y->>'h')::uuid) c;
    PERFORM _assert(v_ok, format('§93 (Q11 concern): naming the other side''s boy on the sheet answered %s/%s', v_ok, v_reason));
    got := _v116_fact('concern_of', (y->>'wesparent')::uuid);
    PERFORM _assert(got = HIL::text || ':' || HIL::text || ':' || (y->>'h'),
      format('§93 (Q11 concern): the concern is held %s, not by Hilton about h', got));
    got := _v116_fact('told', WES);
    PERFORM _assert(got IS NOT NULL AND got LIKE '%Hilton%' AND got LIKE '%safeguarding.concern.read'
                    AND got NOT LIKE '%OneSixteen%' AND got NOT LIKE '%pushed%' AND got NOT LIKE '%V116%',
      format('§93 (Q11 concern): Westville was told %s', coalesce(got, 'nothing')));
    SELECT c.ok, c.reason INTO v_ok, v_reason
      FROM safeguarding_concern_raise(WES, 'child', ARRAY['physical'], 'suspicion',
                                      'v116: a boy of the other school on no sheet of ours, named by id.', 'witness',
                                      (y->>'k')::uuid) c;
    PERFORM _assert(NOT v_ok AND v_reason = 'child_not_visible',
      format('§93 (Q11 concern): naming a boy on no shared sheet answered %s/%s', v_ok, v_reason));

    -- (Q12 manifest)
    PERFORM _as((y->>'coord')::uuid);
    SELECT count(*) INTO n FROM emergency_contact WHERE player_id IN ((y->>'h')::uuid, (y->>'k')::uuid);
    PERFORM _assert(n = 0, format('§93 (Q12 manifest): the coordinator read %s emergency_contact row(s) by standing', n));
    got := (SELECT string_agg(t.player_id::text, ',') FROM trip_contacts((y->>'trip_today')::uuid) t);
    PERFORM _assert(got = (y->>'h'), format('§93 (Q12 manifest): today''s manifest to the coordinator was %s', coalesce(got, 'nothing')));
    SELECT count(*) INTO n FROM trip_contacts((y->>'trip_later')::uuid);
    PERFORM _assert(n = 0, '§93 (Q12 manifest): the coordinator read a manifest ten days before the trip');
    SELECT count(*) INTO n FROM trip_contacts((y->>'trip_cancelled')::uuid);
    PERFORM _assert(n = 0, '§93 (Q12 manifest): the coordinator read a cancelled trip''s manifest');
    PERFORM _as((y->>'sports')::uuid);
    SELECT count(*) INTO n FROM trip_contacts((y->>'trip_today')::uuid);
    PERFORM _assert(n = 0, '§93 (Q12 manifest): the sports office (transport.manage, no manifest) read a manifest');
    PERFORM _as((y->>'office')::uuid);
    SELECT count(*) INTO n FROM trip_contacts((y->>'trip_today')::uuid);
    PERFORM _assert(n = 1, '§93 (Q12 manifest): the office (player.emergency.read) lost the manifest');

    -- (Q13 scorer)
    PERFORM _as((y->>'pupil')::uuid);
    got := (SELECT string_agg(z.x, ',' ORDER BY z.x) FROM (SELECT CASE p.id WHEN (y->>'h')::uuid THEN 'h' WHEN (y->>'k')::uuid THEN 'k' WHEN (y->>'d')::uuid THEN 'd' END AS x
              FROM player p WHERE p.id IN ((y->>'h')::uuid, (y->>'k')::uuid, (y->>'d')::uuid)) z);
    PERFORM _assert(got = 'h', format('§93 (Q13 scorer): of Hilton''s boys the pupil scorer read %s', coalesce(got, 'nobody')));
    SELECT count(*) INTO n FROM player_masked WHERE school_id = HIL;
    PERFORM _assert(n = 1, format('§93 (Q13 scorer): the pupil scorer read %s Hilton roster row(s)', n));
    SELECT count(*) INTO n FROM match_squad WHERE match_id = (y->>'f')::uuid AND NOT withdrawn;
    PERFORM _assert(n = 2, format('§93 (Q13 scorer): the pupil scorer read %s of the sheet''s two names', n));
    SELECT count(*) INTO n FROM honour WHERE player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 0, '§93 (Q13 scorer): the pupil scorer read the boy''s honour');
    SELECT count(*) INTO n FROM team_membership WHERE player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 0, '§93 (Q13 scorer): the pupil scorer read the boy''s side history');
    SELECT count(*) INTO n FROM recognition((y->>'h')::uuid);
    PERFORM _assert(n = 0, '§93 (Q13 scorer): recognition() gave the pupil scorer the boy''s honours');
    PERFORM _assert(NOT _passport_open((y->>'h')::uuid), '§93 (Q13 scorer): _passport_open() opened for the pupil scorer');
    SELECT count(*) INTO n FROM player WHERE id = (y->>'a')::uuid;
    PERFORM _assert(n = 1, '§93 (Q13 scorer): the pupil lost his own side''s team-mate');
    PERFORM _as((y->>'scorer')::uuid);
    SELECT count(*) INTO n FROM player WHERE id = (y->>'k')::uuid;
    PERFORM _assert(n = 1, '§93 (Q13 scorer): the adult scorer lost the roster (the cut is a pupil''s alone)');

    -- (A1 passport): who opens h's passport, and that no rating rides on it.
    FOREACH got IN ARRAY ARRAY['parent:t', 'office:t', 'head:t', 'coach:t', 'wescoach:t',
                               'teen:f', 'young:f', 'coach15:f', 'physio:f', 'wesparent:f', 'wesdso:f', 'dso:f',
                               'scorer:f', 'pupil:f'] LOOP
      PERFORM _as((y->>split_part(got, ':', 1))::uuid);
      PERFORM _assert(_passport_open((y->>'h')::uuid) = (split_part(got, ':', 2) = 't'),
        format('§93 (A1 passport): _passport_open() for the %s is %s', split_part(got, ':', 1), _passport_open((y->>'h')::uuid)));
      SELECT count(*) INTO n FROM passport((y->>'h')::uuid);
      PERFORM _assert((n > 0) = (split_part(got, ':', 2) = 't'),
        format('§93 (A1 passport): the %s read %s passport line(s)', split_part(got, ':', 1), n));
      PERFORM _assert((passport_name((y->>'h')::uuid) IS NOT NULL) = (split_part(got, ':', 2) = 't'),
        format('§93 (A1 passport): passport_name() to the %s', split_part(got, ':', 1)));
    END LOOP;
    PERFORM _as((y->>'office')::uuid);
    SELECT count(*) INTO n FROM passport((y->>'h')::uuid) l WHERE l.family = 'rating' OR l.recorded_by LIKE '%Coach%';
    PERFORM _assert(n = 0, format('§93 (A1 passport): %s rating line(s), or the assessing coach, on the passport', n));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) x
                                 WHERE p.oid IN ('passport(uuid)'::regprocedure, 'passport_name(uuid)'::regprocedure,
                                                 'passport_open(uuid)'::regprocedure, 'trip_contacts(uuid)'::regprocedure,
                                                 'scouting_candidates()'::regprocedure)
                                   AND x.grantee = 0 AND x.privilege_type = 'EXECUTE'),
      '§93 (A5): a passport door, trip_contacts() or scouting_candidates() is still PUBLIC''s');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) x
                                 WHERE p.oid = 'recognition(uuid)'::regprocedure AND x.grantee = 0 AND x.privilege_type = 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'recognition(uuid)', 'EXECUTE'),
      '§93 (A5): recognition() is PUBLIC''s, or not the application''s');
    PERFORM _assert(has_function_privilege('scrbrd_app', 'scouting_candidates()', 'EXECUTE'),
      '§93 (A5): the application lost scouting_candidates()');

    -- (Q14, Q15, Q16)
    PERFORM _as(U_SELF);
    PERFORM _assert(NOT app_can('audit.read', HIL, '*'::text, NIL, NIL), '§93 (Q14): a pupil holds audit.read');
    SELECT count(*) INTO n FROM player_masked WHERE id = P_PILLAY AND id_number IS NOT NULL;
    PERFORM _assert(n = 0, '§93 (Q16): a pupil reads his own ID number');
    SELECT count(*) INTO n FROM player_masked WHERE id = P_PILLAY AND born IS NOT NULL;
    PERFORM _assert(n = 1, '§93 (Q16): a pupil lost his own date of birth (the withdrawal took more than the ID)');
    -- The guardian's half, on this section's own family: by now earlier
    -- sections have moved the seed guardian's link to R Pillay (see db/55's
    -- note), so the seed pair proves nothing here.
    PERFORM _as((y->>'teen')::uuid);
    SELECT count(*) INTO n FROM player_masked WHERE id = (y->>'t')::uuid AND id_number IS NOT NULL;
    PERFORM _assert(n = 0, '§93 (Q16): the thirteen-year-old reads his own ID number');
    PERFORM _as((y->>'parent')::uuid);
    SELECT count(*) INTO n FROM player_masked WHERE id = (y->>'t')::uuid AND id_number IS NOT NULL;
    PERFORM _assert(n = 1, '§93 (Q16): his guardian''s read of the ID number moved (held for Kameel)');
    PERFORM _as((y->>'parent')::uuid);
    SELECT count(*) INTO n FROM disciplinary_record WHERE player_id = (y->>'h')::uuid;
    PERFORM _assert(n = 0, '§93 (Q15): a parent read her son''s disciplinary record');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 93
  -- └── db/116 (section 93) ──────────────────────────────────────────

  -- ┌── db/117 (section 94) ──────────────────────────────────────────
  -- ── 94. The dated side: a family keeps the season of the side a boy was on (SR-2); the move voids his seats (SR-4) ──
  -- docs/design/SEASON_ROLLOVER.md §1.3, §2.10, §3.1 step 2a, §8.2 (Kameel,
  -- 15 Oct 2026: D1; Q2 as recommended). Rows are _v117_stage()'s, invented;
  -- the move and its undoing are the office's own UPDATE of player.team_code
  -- through scrbrd_app with app.effective_on set, as the move route
  -- (roster-api.mjs) writes them. The HTTP half is tools/smoke-player-move.mjs.
  -- What each label holds:
  --   (before)     on the 15XI since t-60 (the 14XI t-90..t-60), A's mother
  --                reads the 15XI's rows from t-60 on and the 14XI's of his
  --                time there (f43b, not f43a); A himself the same, his
  --                14XI fixture by branch (5); the newcomer's mother reads the
  --                19XI's from t-10 only (Q2): not f42a, its bus or its
  --                t-30 post; M's mother the 15XI's
  --   (move)       the office moves A to the 19XI from t-10 (or this
  --                season's start, 1 to 10 January: db/117's floor): the history's
  --                three rows; his `player` row carried (db/112); his links
  --                and consents untouched (§8.2's §49 and db/47 assertions)
  --   (after)      his mother keeps the 15XI's season up to t-10 (f41a, f41w
  --                away, f41d the move's day, its bus, nets, post and plan,
  --                the balls of f41a), keeps f41s by the sheet, gains the
  --                19XI's from t-10 (f42d, f42n, s42d, s42n, n42n) and NOT
  --                its earlier rows (f42a, its bus, nets, post, balls: Q2);
  --                loses the 15XI's after the move (f41n, its bus, nets, the
  --                post and plan of now). A himself: the same old season by
  --                (5), his new side from the day he joined by his `player`
  --                row (1) (dated since db/129, §106: not f42a), and his
  --                old side's post and plan of his time on it (n41a, p41a),
  --                not the ones after he left (n41n, p41n) (Kameel, 22 Oct
  --                2026: news_post_read_old_side)
  --   (old posts)  news_own_old_side() answers true for A alone, and only at
  --                the 15XI posts and plans dated inside his closed rows; of
  --                those he reads the two that are out (n41a, p41a), not the
  --                draft (d41a) or the withdrawn plan (w41a): sent only
  --   (unchanged)  every other reader reads exactly what he read before the
  --                move: the newcomer's and M's mothers, M and C themselves
  --                (a team-mate on the 15XI and a boy who joined the 19XI
  --                later gain nothing from the old-side read), both coaches,
  --                the school-wide spectator, the office
  --   (seats)      A's seat on the lift to f41n (after the move, the side he
  --                left) is void, ended by the office; his seat to f41s (his
  --                name on its sheet), his seat to x41p (after the move's day
  --                but already past) and M's seat to f41n stand; the driver
  --                and A's mother are each told, once
  --   (literal)    for every person of _v117_people() (the stage; one holder
  --                of every class of live assignment, its role and whether
  --                it names a boy; and every reader of a boy with a dated
  --                history on a side of the fixtures compared) and every
  --                staged or seed fixture, fixture_reach() under fixture.read
  --                and transport.read equals §2.10's rule spelled out with
  --                side_on() over every boy ever on the side
  --                (_v117_lit_fixture); for every session side_reach_on()
  --                equals it on the session's day; and db/106's spelling
  --                (player.team_code, _v106_lit_fixture) answers APART for
  --                A's mother at f41a and f42a (the rewrite did something)
  --   (shape)      for the same people: match_read admits exactly
  --                fixture_reach() (and db/41's driver) on the staged and
  --                seed fixtures, trip_read the §83 formula on every trip,
  --                training_session_read side_reach_on() on every session's
  --                day, the ball log the fixtures match_read gives on those
  --                fixtures' balls, and for each guardian among them
  --                my_child_fixtures() is match_read; for every team post,
  --                news_plan_reach() on its day is news.read and
  --                side_reach_on('team.read') on that day
  --                Until 28 Oct 2026 these two asked every person the file
  --                had staged by then (some 430) and, in (shape), every
  --                fixture with balls and every ball: about 55 minutes of the
  --                verify; and inside the verify's one transaction their
  --                plans ran on the seed's statistics, about five times the
  --                cost on analysed rows, so the section analyses first
  --                (_v117_fresh_stats(): rolled back with the rest, no answer
  --                changes). §83 and §89 still ask every person the same
  --                policy-against-helper questions, under db/117's live
  --                definitions. Falsified on 28 Oct 2026: side_reach_on()'s
  --                named branch swapped for the side now, for every boy
  --                (red at (literal), for the stage's mother) and for boys
  --                outside the stage only (red at (literal), for an earlier
  --                section's moved boy's mother, whom rule (c) brings in).
  --   (undo)       a move back the same day (§3.3): four rows, both kept; his
  --                mother reads the 15XI's from t-10 on again and the 19XI's
  --                t-10 day only; the voided seat stays void (no un-void)
  --   (school)     answer 2 (Kameel, 22 Oct 2026): A moves to Westville;
  --                db/117's doors give him nothing of Hilton's; with his
  --                Hilton `player` role ended (player_leave()'s part, not
  --                built), his mother and he read none of Hilton's 15XI
  --                fixtures, buses, nets, posts or plans; Hilton's 15XI coach
  --                reads all he read before
  --   (import)     the import's day (import_joined_on(), Kameel 22 Oct 2026):
  --                a boy new to the books with no date in the file joins his
  --                side on the school season's start; with a date, on it; a
  --                boy already on the books moved by the file, today; a day
  --                still to come is refused; the membership floor (Kameel,
  --                22 Oct 2026: this season's start) refuses a person's
  --                write of a day before it, naming both, and not the day
  --                itself or after; the owner's own dated row (a seed) stands
  --   (doors)      the void trigger enabled beside db/08's and db/112's;
  --                side_on() and side_day() scrbrd_app's alone; my_sides()
  --                returns the spans; no job on a clock (§8.3 item 12)
  --
  -- Falsified on 21 Oct 2026 (see the slice's report): each change made as
  -- the owner before this section ran, red, then green without it.
  DECLARE
    z      jsonb := _v117_stage();
    OFFICE uuid;
    A uuid; G uuid; GM uuid; ABOY uuid;
    FX     uuid[];
    RX     uuid[];
    RB     uuid[];
    ppl    uuid[];
    got    text;
    want   text;
    v_about text;
    v_before jsonb := '{}';
    k      text;
    u      uuid;
    n      int;
    bad    text;
    t      date := sa_today();
    ZERO   uuid := '00000000-0000-0000-0000-000000000000';
    -- The move's day (the stage's: t-10, or this season's start in early
    -- January), the school move's (t-5, or the day after the move) and the dated
    -- import's (t-20, or the season's start): each a person's write or after
    -- one, so never before db/117's floor.
    XM     int;
    XS     int;
    XD     int;
    v_season date;
    v_new  uuid;
    v_dated uuid;
  BEGIN
    OFFICE := (z->>'office')::uuid; A := (z->>'a')::uuid; G := (z->>'g')::uuid; GM := (z->>'gm')::uuid;
    ABOY := (z->>'aboy')::uuid;
    FX := ARRAY(SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^f4');
    SELECT s.starts_on INTO v_season FROM season_for(sa_today(), 'school') s;
    XM := (z->>'day_move')::date - t;
    XS := greatest(XM + 1, -5);   -- a day after the move back, so the rows read in one order
    XD := greatest(v_season - t, -20);
    PERFORM _v117_fresh_stats();

    -- ── (before) ──
    PERFORM _assert(_v117_fact('rows', A) = '14XI:-90..-60 15XI:-60..',
      format('§94 (before): A''s rows are %s', _v117_fact('rows', A)));
    FOR k, want IN SELECT * FROM (VALUES
        ('g',    'fixtures [f41a f41d f41n f41s f41w f43b] trips [t41a t41n] training [s41a s41n] posts [n41a n41n p41a p41n] balls [f41a f41n]'),
        ('aboy', 'fixtures [f41a f41d f41n f41s f41w f43b] trips [t41a t41n] training [s41a s41n] posts [n41a n41n p41a p41n] balls [f41a f41n]'),
        ('gm',   'fixtures [f41a f41d f41n f41s f41w] trips [t41a t41n] training [s41a s41n] posts [n41a n41n p41a p41n] balls [f41a f41n]'),
        ('gc',   'fixtures [f42d f42n] trips [] training [s42d s42n] posts [n42n] balls []')) x LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v117_reads(z);
      PERFORM _assert(got = want, format('§94 (before): the %s reads %s, the design gives %s', k, got, want));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['gc', 'gm', 'mboy', 'cboy', 'coach41', 'coach42', 'spec', 'office'] LOOP
      PERFORM _as((z->>k)::uuid);
      v_before := v_before || jsonb_build_object(k, _v117_reads(z));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    v_about := _v117_fact('about_him', A);
    PERFORM _assert(_v117_fact('lift_notices', G) = '' AND _v117_fact('lift_notices', GM) = '',
      '§94 (before): a lift notice is there before the move');

    -- ── (move) ──
    PERFORM _as(OFFICE);
    PERFORM set_config('app.effective_on', (t + XM)::text, true);
    UPDATE player SET team_code = '19XI' WHERE id = A;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM set_config('app.effective_on', '', true);
    PERFORM _assert(n = 1, '§94 (move): the office could not move A');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v117_fact('rows', A) = format('14XI:-90..-60 15XI:-60..%s 19XI:%s..', XM, XM),
      format('§94 (move): A''s rows are %s', _v117_fact('rows', A)));
    PERFORM _assert(_v112_roles(ABOY) = '15XI:ended 19XI:live',
      format('§94 (move): A''s own `player` rows are %s (db/112''s carry)', _v112_roles(ABOY)));
    PERFORM _assert(_v117_fact('about_him', A) = v_about,
      '§94 (move): the move changed a link or a consent of A''s (§8.2: §49, db/47)');

    -- ── (after) ──
    FOR k, want IN SELECT * FROM (VALUES
        ('g',    'fixtures [f41a f41d f41s f41w f42d f42n f43b] trips [t41a] training [s41a s42d s42n] posts [n41a n42n p41a] balls [f41a]'),
        -- Since db/129 his `player` row reads the 19XI only from the day he
        -- joined it (Q2): not f42a, its bus, nets, post or balls (§106).
        ('aboy', 'fixtures [f41a f41d f41s f41w f42d f42n f43b] trips [t41a] training [s41a s42d s42n] posts [n41a n42n p41a] balls [f41a]')) x LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v117_reads(z);
      PERFORM _assert(got = want, format('§94 (after): the %s reads %s, the design gives %s', k, got, want));
    END LOOP;

    -- ── (old posts) ──
    -- A reads his old side's post and plan of his time on it, and not the
    -- ones after he left; and by the new read alone.
    PERFORM _as(ABOY);
    PERFORM _assert(EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'n41a')::uuid)
                    AND EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'p41a')::uuid)
                    AND NOT EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'n41n')::uuid)
                    AND NOT EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'p41n')::uuid),
      '§94 (old posts): A does not read his old side''s post and plan of his time on it, or reads one from after he left');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'d41a')::uuid)
                    AND NOT EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'w41a')::uuid),
      '§94 (old posts): A reads a plan of his old side that is not out (a draft, or a withdrawn one)');
    PERFORM _as((z->>'coach41')::uuid);
    PERFORM _assert(EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'d41a')::uuid)
                    AND EXISTS (SELECT 1 FROM news_post WHERE id = (z->>'w41a')::uuid),
      '§94 (old posts): the draft and the withdrawn plan are not their author''s to read (the test proves nothing)');
    PERFORM _as(ABOY);
    PERFORM _assert(NOT app_can('news.read', '11111111-1111-1111-1111-111111111111'::uuid, '15XI', ZERO, ZERO)
                    AND NOT news_plan_reach('11111111-1111-1111-1111-111111111111'::uuid, '15XI', t - 30),
      '§94 (old posts): A reads the 15XI''s posts by a rule other than his old side''s (the test proves nothing)');
    -- Whom news_own_old_side() answers for, over every team post: A alone,
    -- at the 15XI post and plan inside his closed rows.
    FOREACH k IN ARRAY ARRAY['aboy', 'mboy', 'cboy', 'g', 'gm', 'gc', 'coach41', 'coach42', 'spec', 'office'] LOOP
      PERFORM _as((z->>k)::uuid);
      SELECT coalesce(string_agg(coalesce(_v106_label(z, p.id), p.id::text), ' ' ORDER BY coalesce(_v106_label(z, p.id), p.id::text)), '') INTO got
        FROM _v117_posts() p WHERE news_own_old_side(p.school, p.team, p.day);
      want := CASE k WHEN 'aboy' THEN 'd41a n41a p41a w41a' ELSE '' END;
      PERFORM _assert(got = want, format('§94 (old posts): news_own_old_side() is true for the %s at [%s], the design gives [%s]', k, got, want));
    END LOOP;

    -- ── (unchanged) ──
    FOREACH k IN ARRAY ARRAY['gc', 'gm', 'mboy', 'cboy', 'coach41', 'coach42', 'spec', 'office'] LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v117_reads(z);
      PERFORM _assert(got = v_before->>k, format('§94 (unchanged): the %s read %s before the move and %s after', k, v_before->>k, got));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);

    -- ── (seats) ──
    PERFORM _assert(_v117_fact('seat', (z->>'seat_a_41n')::uuid) = 'void:' || OFFICE::text
                    AND _v117_fact('seat', (z->>'seat_a_41s')::uuid) = 'requested:-'
                    AND _v117_fact('seat', (z->>'seat_a_41p')::uuid) = 'requested:-'
                    AND _v117_fact('seat', (z->>'seat_m_41n')::uuid) = 'requested:-',
      format('§94 (seats): after the move A''s seat to f41n is %s, to f41s %s, to x41p (past) %s; M''s to f41n %s',
             _v117_fact('seat', (z->>'seat_a_41n')::uuid), _v117_fact('seat', (z->>'seat_a_41s')::uuid),
             _v117_fact('seat', (z->>'seat_a_41p')::uuid), _v117_fact('seat', (z->>'seat_m_41n')::uuid)));
    PERFORM _assert(_v117_fact('lift_notices', GM) = 'A seat was withdrawn'
                    AND _v117_fact('lift_notices', G) = 'A seat on a lift was withdrawn',
      format('§94 (seats): the driver was told [%s], A''s mother [%s]', _v117_fact('lift_notices', GM), _v117_fact('lift_notices', G)));

    -- ── (literal) ──
    -- The people are _v117_people()'s rule (its header): the stage, one
    -- holder of every class of assignment, and everyone linked to a boy with
    -- a dated history. The rows are what they were: the stage's fixtures and
    -- the seed's, under both capabilities, and every session.
    ppl := _v117_people(z);
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      SELECT string_agg(format('%s/%s', coalesce(_v106_label(z, x.f), x.f::text), x.cap), ' ') INTO bad
        FROM (SELECT f0 AS f, c.cap FROM unnest(FX || _v106_seed_matches()) f0, (VALUES ('fixture.read'), ('transport.read')) c(cap)) x
       WHERE fixture_reach(x.cap, x.f) IS DISTINCT FROM _v117_lit_fixture(x.cap, x.f);
      PERFORM _assert(bad IS NULL, format('§94 (literal): for %s fixture_reach() and §2.10''s rule answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, s.id), s.id::text), ' ') INTO bad
        FROM _v117_sessions() s
       WHERE side_reach_on('team.read', s.school_id, s.team_code, ZERO, s.day)
             IS DISTINCT FROM _v117_lit_side('team.read', s.school_id, s.team_code, ZERO, s.day);
      PERFORM _assert(bad IS NULL, format('§94 (literal): for %s side_reach_on() and §2.10''s rule answer apart at sessions %s', u, left(bad, 300)));
    END LOOP;
    PERFORM _as(G);
    PERFORM _assert(fixture_reach('fixture.read', (z->>'f41a')::uuid) AND NOT _v106_lit_fixture('fixture.read', (z->>'f41a')::uuid)
                    AND NOT fixture_reach('fixture.read', (z->>'f42a')::uuid) AND _v106_lit_fixture('fixture.read', (z->>'f42a')::uuid),
      '§94 (literal): db/106''s spelling (the side now) and the dated rule do not answer apart for A''s mother at f41a and f42a');

    -- ── (shape) ──
    -- The same people as (literal). The fixtures are (literal)'s, the stage's
    -- and the seed's (RX), which hold balls of their own (RB): the ball log is
    -- compared on those fixtures' balls, not on every ball the file has
    -- scored by now. Every trip, session and team post, as before.
    RX := FX || _v106_seed_matches();
    RB := ARRAY(SELECT x FROM unnest(RX) x WHERE x = ANY (_v106_ball_matches()));
    n := 0;
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      SELECT string_agg(coalesce(_v106_label(z, x), x::text), ' ') INTO bad
        FROM unnest(RX) x
       WHERE EXISTS (SELECT 1 FROM match m WHERE m.id = x)
             IS DISTINCT FROM (fixture_reach('fixture.read', x) OR x IN (SELECT trip_driven_matches()));
      PERFORM _assert(bad IS NULL, format('§94 (shape): for %s match_read and fixture_reach() answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, s.id), s.id::text), ' ') INTO bad
        FROM _v117_sessions() s
       WHERE EXISTS (SELECT 1 FROM training_session v WHERE v.id = s.id)
             IS DISTINCT FROM side_reach_on('team.read', s.school_id, s.team_code, ZERO, s.day);
      PERFORM _assert(bad IS NULL, format('§94 (shape): for %s training_session_read and side_reach_on() answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, x.id), x.id::text), ' ') INTO bad
        FROM _v106_trips() x
       WHERE EXISTS (SELECT 1 FROM trip v WHERE v.id = x.id)
             IS DISTINCT FROM (((fixture_end_reach('transport.read', x.match_id, x.school_id, x.team_code)
                                 AND (fixture_reach('fixture.read', x.match_id) OR x.match_id IN (SELECT trip_driven_matches())))
                                OR (coalesce(x.driver_id = app_user_id(), false)
                                    AND app_can('transport.read', x.school_id, x.team_code, ZERO, x.match_id)))
                               AND (coalesce(x.driver_id = app_user_id(), false) OR NOT trip_fixture_driver_only(x.match_id)));
      PERFORM _assert(bad IS NULL, format('§94 (shape): for %s trip_read and fixture_end_reach() answer apart at %s', u, left(bad, 300)));
      SELECT string_agg(x::text, ' ') INTO bad
        FROM (((SELECT DISTINCT b.match_id FROM ball_event b WHERE b.match_id = ANY (RB))
               EXCEPT (SELECT m.id FROM match m WHERE m.id = ANY (RB) AND NOT trip_fixture_driver_only(m.id)))
              UNION ALL
              ((SELECT m.id FROM match m WHERE m.id = ANY (RB) AND NOT trip_fixture_driver_only(m.id))
               EXCEPT (SELECT DISTINCT b.match_id FROM ball_event b WHERE b.match_id = ANY (RB)))) d(x);
      PERFORM _assert(bad IS NULL, format('§94 (shape): %s reads balls apart from match_read at %s', u, left(bad, 300)));
      SELECT string_agg(coalesce(_v106_label(z, p.id), p.id::text), ' ') INTO bad
        FROM _v117_posts() p
       WHERE news_plan_reach(p.school, p.team, p.day) IS DISTINCT FROM
             (app_can('news.read', p.school, p.team, ZERO, ZERO) AND side_reach_on('team.read', p.school, p.team, ZERO, p.day));
      PERFORM _assert(bad IS NULL, format('§94 (shape): for %s news_plan_reach() and side_reach_on() answer apart at posts %s', u, left(bad, 300)));
    END LOOP;
    FOREACH u IN ARRAY ARRAY(SELECT x FROM unnest(_v106_guardians_only()) x WHERE x = ANY (ppl)) LOOP
      PERFORM _as(u);
      PERFORM _assert(
        (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(my_child_fixtures()) x)
          = (SELECT coalesce(array_agg(m.id ORDER BY m.id), '{}') FROM match m),
        format('§94 (shape): for the guardian %s my_child_fixtures() and match_read give different fixtures', u));
      n := n + cardinality(my_child_fixtures());
    END LOOP;
    PERFORM _assert(n > 10 AND cardinality(ppl) > 20 AND (SELECT count(*) FROM _v117_posts()) >= 6
                    AND cardinality(RB) >= 3 AND _v117_people_dated_beyond(z) > 0
                    AND ARRAY[OFFICE, G, GM, ABOY, (z->>'gc')::uuid, (z->>'mboy')::uuid, (z->>'cboy')::uuid,
                              (z->>'coach41')::uuid, (z->>'coach42')::uuid, (z->>'spec')::uuid] <@ ppl,
      format('§94 (shape): %s guardian fixtures, %s people (%s linked to a dated boy beyond the stage), %s posts, %s fixtures with balls compared, or the stage is not all asked: it proves nothing',
             n, cardinality(ppl), _v117_people_dated_beyond(z), (SELECT count(*) FROM _v117_posts()), cardinality(RB)));

    -- ── (undo) ──
    PERFORM _as(OFFICE);
    PERFORM set_config('app.effective_on', (t + XM)::text, true);
    UPDATE player SET team_code = '15XI' WHERE id = A;
    PERFORM set_config('app.effective_on', '', true);
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v117_fact('rows', A) = format('14XI:-90..-60 15XI:-60..%s 19XI:%s..%s 15XI:%s..', XM, XM, XM, XM),
      format('§94 (undo): A''s rows are %s', _v117_fact('rows', A)));
    FOR k, want IN SELECT * FROM (VALUES
        ('g',    'fixtures [f41a f41d f41n f41s f41w f42d f43b] trips [t41a t41n] training [s41a s41n s42d] posts [n41a n41n p41a p41n] balls [f41a f41n]'),
        ('aboy', 'fixtures [f41a f41d f41n f41s f41w f42d f43b] trips [t41a t41n] training [s41a s41n s42d] posts [n41a n41n p41a p41n] balls [f41a f41n]')) x LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v117_reads(z);
      PERFORM _assert(got = want, format('§94 (undo): the %s reads %s, the design gives %s', k, got, want));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v117_fact('seat', (z->>'seat_a_41n')::uuid) = 'void:' || OFFICE::text
                    AND _v117_fact('lift_notices', G) = 'A seat on a lift was withdrawn'
                    AND _v117_fact('about_him', A) = v_about,
      '§94 (undo): the move back un-voided the seat, told someone again, or changed a link or consent');

    -- ── (school) ──
    -- Answer 2: the old school keeps its season. A moves to Westville's 15XI
    -- from t-5.
    PERFORM _v117_move_school(A, '22222222-2222-2222-2222-222222222222'::uuid, '15XI', t + XS);
    PERFORM _assert(_v117_fact('rows', A) = format('14XI:-90..-60 15XI:-60..%s 19XI:%s..%s 15XI:%s..%s 15XI:%s..', XM, XM, XM, XM, XS, XS)
                    AND _v117_fact('school', A) = '22222222-2222-2222-2222-222222222222',
      format('§94 (school): A''s rows are %s', _v117_fact('rows', A)));
    -- db/117's doors give A himself nothing of Hilton's now: not the old
    -- side's posts (news_own_old_side()), not its fixtures or balls
    -- (my_own_side_fixtures(), my_fixture_ends()'s branch (5)).
    PERFORM _as(ABOY);
    PERFORM _assert(NOT news_own_old_side('11111111-1111-1111-1111-111111111111'::uuid, '15XI', t - 30) AND NOT news_own_old_side('11111111-1111-1111-1111-111111111111'::uuid, '15XI', t + XM)
                    AND NOT EXISTS (SELECT 1 FROM unnest(my_own_side_fixtures()) x
                                     WHERE x IN (SELECT value::uuid FROM jsonb_each_text(z) WHERE key ~ '^(f|x)4'))
                    AND NOT EXISTS (SELECT 1 FROM my_fixture_ends('fixture.read') e WHERE e.school_id = '11111111-1111-1111-1111-111111111111'::uuid),
      '§94 (school): a db/117 door still answers for A at Hilton after he moved school');
    -- His own Hilton `player` role is not db/117's: db/112 carries a role
    -- within a school, and a boy leaving a school ends his roles there by
    -- ACCOUNT_LIFECYCLE's player_leave() (not built; no route changes a
    -- boy's school today). Ended here as that will, the boy and his mother
    -- read nothing of Hilton's 15XI.
    PERFORM _v117_end_player_roles(ABOY, '11111111-1111-1111-1111-111111111111'::uuid);
    FOREACH k IN ARRAY ARRAY['g', 'aboy'] LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v117_reads(z);
      PERFORM _assert(got !~ '[ftsnp]41',
        format('§94 (school): after A moved school the %s reads %s, a Hilton 15XI row among them', k, got));
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM news_post WHERE id IN ((z->>'n41a')::uuid, (z->>'p41a')::uuid, (z->>'d41a')::uuid, (z->>'w41a')::uuid))
                      AND NOT EXISTS (SELECT 1 FROM match WHERE id IN ((z->>'f41a')::uuid, (z->>'f41d')::uuid, (z->>'x41p')::uuid)),
        format('§94 (school): after A moved school the %s reads a Hilton 15XI post, plan or fixture', k));
    END LOOP;
    PERFORM _as((z->>'coach41')::uuid);
    got := _v117_reads(z);
    PERFORM _assert(got = v_before->>'coach41' AND got ~ 'f41a' AND got ~ 'n41a' AND got ~ 'p41a',
      format('§94 (school): Hilton''s 15XI coach read %s before and %s after A moved school', v_before->>'coach41', got));
    PERFORM set_config('app.user_id', '', true);

    -- ── (import) ──
    -- As the import writes a row: the office, app.effective_on set from
    -- import_joined_on() before the write (services/api/io/import-api.mjs).
    PERFORM _as(OFFICE);
    PERFORM _assert(import_joined_on(false, NULL) = v_season AND import_joined_on(true, NULL) IS NULL
                    AND import_joined_on(false, t + XD) = t + XD AND import_joined_on(true, t + XD) = t + XD,
      format('§94 (import): import_joined_on() gives %s, %s, %s, %s',
             import_joined_on(false, NULL), import_joined_on(true, NULL), import_joined_on(false, t + XD), import_joined_on(true, t + XD)));
    -- a new boy, no date in the file: the season's start
    PERFORM set_config('app.effective_on', coalesce(import_joined_on(false, NULL)::text, ''), true);
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
    VALUES ('11111111-1111-1111-1111-111111111111'::uuid, '15XI', 'Verify OneOneSeven Imported', 1174, 'batter',
            make_date(extract(year FROM t)::int - 15, 3, 1)) RETURNING id INTO v_new;
    -- a new boy, a date in the file
    PERFORM set_config('app.effective_on', coalesce(import_joined_on(false, t + XD)::text, ''), true);
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
    VALUES ('11111111-1111-1111-1111-111111111111'::uuid, '15XI', 'Verify OneOneSeven Dated', 1175, 'batter',
            make_date(extract(year FROM t)::int - 15, 3, 1)) RETURNING id INTO v_dated;
    -- M, on the books, moved by the file with no date: today, as before
    PERFORM set_config('app.effective_on', coalesce(import_joined_on(true, NULL)::text, ''), true);
    UPDATE player SET team_code = '19XI' WHERE id = (z->>'m')::uuid;
    PERFORM set_config('app.effective_on', '', true);
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v117_fact('rows', v_new) = format('15XI:%s..', v_season - t),
      format('§94 (import): a new boy with no date has %s, not the season''s start (%s)', _v117_fact('rows', v_new), v_season - t));
    PERFORM _assert(_v117_fact('rows', v_dated) = format('15XI:%s..', XD),
      format('§94 (import): a new boy with a date has %s, not the file''s day', _v117_fact('rows', v_dated)));
    PERFORM _assert(_v117_fact('rows', (z->>'m')::uuid) = '15XI:-60..0 19XI:0..',
      format('§94 (import): a boy moved by the file with no date has %s, not a move today', _v117_fact('rows', (z->>'m')::uuid)));
    -- a day still to come is refused
    PERFORM _as(OFFICE);
    BEGIN
      PERFORM import_joined_on(false, t + 1);
      PERFORM _assert(false, '§94 (import): a joined_on still to come was accepted');
    EXCEPTION WHEN check_violation THEN NULL;
    END;
    -- The floor (Kameel, 22 October 2026): no earlier than this season's
    -- start. The rule, then the guard on a person's write (the office, as the
    -- import and the move route write), before, on and after the floor.
    PERFORM _assert(membership_joined_floor() = v_season,
      format('§94 (floor): the floor is %s, not this season''s start (%s)', membership_joined_floor(), v_season));
    PERFORM _assert(membership_floor_refusal(v_season - 1, v_season) LIKE '%' || (v_season - 1)::text || '%' || v_season::text || '%'
                    AND membership_floor_refusal(v_season, v_season) IS NULL
                    AND membership_floor_refusal(v_season + 1, v_season) IS NULL,
      format('§94 (floor): the rule gives [%s] before, [%s] on, [%s] after',
             membership_floor_refusal(v_season - 1, v_season), membership_floor_refusal(v_season, v_season),
             membership_floor_refusal(v_season + 1, v_season)));
    PERFORM _as(OFFICE);
    BEGIN
      PERFORM set_config('app.effective_on', (v_season - 1)::text, true);
      INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
      VALUES ('11111111-1111-1111-1111-111111111111'::uuid, '15XI', 'Verify OneOneSeven Before', 1176, 'batter', make_date(extract(year FROM t)::int - 15, 3, 1));
      PERFORM _assert(false, '§94 (floor): the office opened a membership the day before this season''s start');
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS got = MESSAGE_TEXT;
      PERFORM _assert(got LIKE '%' || (v_season - 1)::text || '%' || v_season::text || '%',
        format('§94 (floor): the refusal does not name the day and the floor: %s', got));
    END;
    PERFORM set_config('app.effective_on', v_season::text, true);
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
    VALUES ('11111111-1111-1111-1111-111111111111'::uuid, '15XI', 'Verify OneOneSeven OnFloor', 1177, 'batter', make_date(extract(year FROM t)::int - 15, 3, 1))
    RETURNING id INTO v_new;
    PERFORM set_config('app.effective_on', (v_season + 1)::text, true);
    INSERT INTO player (school_id, team_code, full_name, squad_no, playing_role, born)
    VALUES ('11111111-1111-1111-1111-111111111111'::uuid, '15XI', 'Verify OneOneSeven AfterFloor', 1178, 'batter', make_date(extract(year FROM t)::int - 15, 3, 1))
    RETURNING id INTO v_dated;
    PERFORM set_config('app.effective_on', '', true);
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v117_fact('rows', v_new) = format('15XI:%s..', v_season - t)
                    AND _v117_fact('rows', v_dated) = format('15XI:%s..', v_season + 1 - t),
      format('§94 (floor): on the floor %s, after it %s', _v117_fact('rows', v_new), _v117_fact('rows', v_dated)));
    -- The owner's own dated row, nobody signed in (the seed's way): stands.
    v_new := _v117_owner_joins(v_season - 30);
    PERFORM _assert(_v117_fact('rows', v_new) = format('15XI:%s..', v_season - 30 - t),
      '§94 (floor): the owner''s own dated row, nobody signed in, was refused');

    -- ── (doors) ──
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'player'::regclass AND tgname = 'player_move_voids_seats' AND tgenabled = 'O')
                    AND NOT has_function_privilege('scrbrd_app', to_regprocedure('player_move_voids_seats()'), 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', to_regprocedure('side_on(uuid,uuid,date)'), 'EXECUTE')
                    AND NOT has_function_privilege('public', to_regprocedure('side_on(uuid,uuid,date)'), 'EXECUTE')
                    AND NOT has_function_privilege('public', to_regprocedure('side_day(uuid)'), 'EXECUTE')
                    AND pg_get_function_result(to_regprocedure('my_sides(text)'))
                        = 'TABLE(school_id uuid, team_code text, joined_on date, left_on date)'
                    AND (SELECT position('my_own_side_fixtures()' IN pg_get_expr(p.polqual, p.polrelid)) > 0
                           FROM pg_policy p WHERE p.polrelid = 'ball_event'::regclass AND p.polname = 'ball_event_read')
                    AND (SELECT position('sa_date(training_session.starts_at)' IN pg_get_expr(p.polqual, p.polrelid)) > 0
                           FROM pg_policy p WHERE p.polrelid = 'training_session'::regclass AND p.polname = 'training_session_read')
                    AND has_function_privilege('scrbrd_app', to_regprocedure('news_own_old_side(uuid,text,date)'), 'EXECUTE')
                    AND NOT has_function_privilege('public', to_regprocedure('news_own_old_side(uuid,text,date)'), 'EXECUTE')
                    AND NOT has_function_privilege('public', to_regprocedure('import_joined_on(boolean,date)'), 'EXECUTE')
                    AND EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = 'news_post'::regclass
                                   AND p.polname = 'news_post_read_old_side' AND p.polpermissive AND p.polcmd = 'r')
                    AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'team_membership'::regclass
                                   AND tgname = 'team_membership_floor' AND tgenabled = 'O')
                    AND NOT has_function_privilege('scrbrd_app', to_regprocedure('team_membership_floor()'), 'EXECUTE'),
      '§94 (doors): the void trigger, the helpers'' grants, my_sides()''s spans or the dated policies are not what db/117 wrote');
    PERFORM _assert(to_regclass('cron.job') IS NULL, '§94 (doors): a job runs on a clock (cron.job exists)');
  END;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.effective_on', '', true);
  -- └── end of section 94
  -- └── db/117 (section 94) ──────────────────────────────────────────


  -- ┌── db/118 (section 95) ──────────────────────────────────────────
  -- Names, login emails, retirements and bowler changes (db/118). Sections
  -- 92-94 are db/115-117's; 96 and 97 are kept for db/119 and db/120.
  --
  --   (scan)    the surname column is read on its own: a pupil whose stored
  --             surname is not in his full name is still found by it; a
  --             surname particle alone ("van") names nobody
  --   (email)   a pupil's login email (linked to a player row, or holding a
  --             player role) reads NULL to finance and sponsorship, which
  --             hold user.read; the office (guardian.link.manage) and the
  --             pupil himself read it; an adult's reads as before; another
  --             school's office is not this school's
  --   (retire)  a retirement that is not a dismissal reads "not out" to a
  --             reader with no fixture.read at the retiring boy's school,
  --             and as written to one with it; a retired-out keeps its
  --             reason; a typed name is at no school; nothing else moves
  --   (scan)    and a word of a name written with punctuation ("Zungu, S",
  --             "Mary-Anne"), and an opponent's boy (a fixture with his school)
  --   (word)    the author is told the word of his post that matched, as he
  --             wrote it; another school's office is told nothing
  --   (suspension) a Law 41 suspension's ground, as a bowler change's reason
  --   (bowler)  a bowler change keeps its reason for a reader with
  --             fixture.read at the bowler's school, and loses it (the
  --             change itself kept) for the other school and a typed name
  --   (two letters) a two-letter first name alone is caught, and the
  --             author told it; "Jo" is not found inside "Johannesburg"
  --   (email)   and the director of sport and the platform account read
  --             NULL; the principal reads it (the office alone, 28 Oct)
  --   (retire)  and a team-mate at his school reads "hurt" (Q1 as built)
  --   (platform) the league account and the owner's key read "not out", no
  --             bowler change's reason and no suspension's ground
  --   (league)  a platform-wide league and the owner's key read no conduct
  --             record; a school-scoped league reads its own competition's,
  --             logged per school, and no other; a competition nobody
  --             organises opens to nobody
  --   (doors)   the three definers are the application's and not PUBLIC's
  --
  -- Falsified once each, by replacing a function in the database and
  -- watching the section go red at its own assertion: the surname column
  -- dropped from the scan (scan); the pupil test made to return the email
  -- (email: finance read it); the school test dropped from the payload
  -- (retire: Westville read 'hurt').
  DECLARE
    U_C2_91  uuid := '88888888-0000-0000-0000-00000000000a';   -- 2XI coach, Hilton
    U_WCOACH uuid := '88888888-0000-0000-0000-00000000001a';   -- 1XI coach, Westville
    P91 uuid; v_email text; v_pay jsonb; v_post91 uuid; z jsonb; got text; n int;
    P_PILLAY uuid := 'aaaaaaaa-0000-0000-0000-000000000005';
  BEGIN
    -- (scan) as the 2XI coach writes and asks; the director of sport approves.
    PERFORM _as(U_C2_91);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Van', 'van', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) = 0, '§95 (scan): a surname particle alone named a pupil');
    SELECT p.id INTO P91 FROM player p WHERE p.school_id = HIL AND p.full_name = 'K Dlamini';
    PERFORM _assert(P91 IS NOT NULL, '§95 (scan): K Dlamini is not seeded at Hilton');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _seed_118_surname(P91, 'Zwelithini');
    PERFORM _as(U_C2_91);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Zwelithini', 'zwelithini', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) = 1, '§95 (scan): the stored surname was not read');
    -- A name written with a comma, and a hyphenated first name: each word is
    -- a word of his name.
    PERFORM set_config('app.user_id', '', true);
    PERFORM _seed_118_name(P_ADULT, 'Zungu, S');
    PERFORM _seed_118_name(P_U13, 'Mary-Anne Mkhwanazi');
    PERFORM _as(U_C2_91);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Zungu', 'zungu', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) = 1, '§95 (scan): a surname written "Zungu," was not found');
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Anne', 'anne', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) = 1, '§95 (scan): half of "Mary-Anne" was not found');
    -- (two letters) Kameel, 28 Oct 2026: "Catch two-letter names too". A
    -- first name of two letters alone is caught; whole-word, so "Jo" is not
    -- found inside "Johannesburg".
    PERFORM set_config('app.user_id', '', true);
    PERFORM _seed_118_name(P_U13, 'Jo Mkhwanazi');
    PERFORM _as(U_C2_91);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Well played', 'Well played Jo, a fine fifty', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) = 1, '§95 (two letters): a two-letter first name alone was not caught');
    PERFORM _assert(news_public_word(v_post91) = 'Jo',
      format('§95 (two letters): the author was told %s, not the word Jo', news_public_word(v_post91)));
    -- No other word of this post may be a staged boy's name: "Away" is one
    -- (§75's and §77's Westville 'Verify ... Away ...' boys), which is the designed
    -- common-word refusal, not this case.
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Fixtures', 'The 2XI travel to Johannesburg on Saturday', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) = 0,
      format('§95 (two letters): the post was refused on the word %s ("Jo" must not be found inside "Johannesburg")',
             coalesce(news_public_word(v_post91), '(none)')));
    -- An opponent's boy (Kameel, 22 Oct): Westville's D Mkhize, with a
    -- Hilton-Westville fixture tomorrow. The author is told the word of his
    -- post that matched, as he wrote it; somebody else is told nothing.
    PERFORM set_config('app.user_id', '', true);
    PERFORM _seed_118_fixture(HIL, WES);
    PERFORM _as(U_C2_91);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL, '2XI', 'Opponents', 'Watch out for mKhize on Saturday', now()) RETURNING id INTO v_post91;
    PERFORM _assert(news_public_check(v_post91) >= 1, '§95 (scan): a post naming an opponent''s boy was not caught');
    PERFORM _assert(news_public_word(v_post91) = 'mKhize',
      format('§95 (word): the author was not told the word as he wrote it (%s)', news_public_word(v_post91)));
    PERFORM _as(U_WES_ADM);
    PERFORM _assert(news_public_word(v_post91) IS NULL, '§95 (word): somebody neither the author nor a publisher was told the word');
    PERFORM _as(U_C2_91);

    -- (email)
    PERFORM _as(U_BURSAR);   -- finance and sponsorship: user.read, nothing more
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_SELF;
    PERFORM _assert(v_email IS NULL, format('§95 (email): finance read a pupil''s login email (%s)', v_email));
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_PUPIL;
    PERFORM _assert(v_email IS NULL, format('§95 (email): finance read the email of an account holding a player role (%s)', v_email));
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_C2_91;
    PERFORM _assert(v_email = 'coach2@example.invalid', format('§95 (email): finance lost an adult''s email (%s)', v_email));
    PERFORM _as(U_REGISTRAR);
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_SELF;
    PERFORM _assert(v_email = 'pillay@example.invalid', format('§95 (email): the office lost a pupil''s email (%s)', v_email));
    PERFORM _as(U_SELF);
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_SELF;
    PERFORM _assert(v_email = 'pillay@example.invalid', format('§95 (email): a pupil lost his own email (%s)', v_email));
    PERFORM _as(U_WES_ADM);
    PERFORM _assert(app_user_email_seen(U_SELF, HIL, 'x@example.invalid') IS NULL,
      '§95 (email): Westville''s office read a Hilton pupil''s email');
    -- Kameel, 28 Oct 2026: "The office alone, as A4 says". The director of
    -- sport appoints staff (user.role.assign) and reads the pupil's account
    -- with no email on it; so does the platform account; the principal,
    -- who holds guardian.link.manage, reads it.
    PERFORM _as(U_SARAH);
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_SELF;
    PERFORM _assert(v_email IS NULL, format('§95 (email): the director of sport read a pupil''s login email (%s)', v_email));
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_C2_91;
    PERFORM _assert(v_email = 'coach2@example.invalid', format('§95 (email): the director of sport lost an adult''s email (%s)', v_email));
    -- The platform account as itself: SCRBRD-012's third support session (ticket
    -- 4413) is still live and lends it the office's role at Hilton, under
    -- which it reads what the office reads, on the school's record (db/22).
    PERFORM set_config('app.user_id', '', true);
    PERFORM _seed_118_end_support(U_PLAT);
    PERFORM _as(U_PLAT);
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_SELF;
    PERFORM _assert(v_email IS NULL, format('§95 (email): the platform account read a pupil''s login email (%s)', v_email));
    PERFORM _as(U_HEAD_M);
    SELECT app_user_email_seen(u.id, u.school_id, u.email) INTO v_email FROM app_user u WHERE u.id = U_SELF;
    PERFORM _assert(v_email = 'pillay@example.invalid', format('§95 (email): the principal lost a pupil''s email (%s)', v_email));

    -- (retire)
    v_pay := jsonb_build_object('batter', P_PILLAY, 'reason', 'hurt');
    PERFORM _as(U_WCOACH);
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, v_pay)->>'reason' = 'not out',
      '§95 (retire): Westville''s coach read a Hilton boy retired hurt');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, v_pay)->>'batter' = P_PILLAY::text,
      '§95 (retire): the batter moved');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', 'W', NULL, jsonb_build_object('batter', P_PILLAY, 'reason', 'out'))->>'reason' = 'out',
      '§95 (retire): a retired-out lost its reason');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, jsonb_build_object('batter', P_WES, 'reason', 'hurt'))->>'reason' = 'hurt',
      '§95 (retire): Westville''s coach lost his own boy''s reason');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'ball', NULL, NULL, jsonb_build_object('reason', 'injury')) = jsonb_build_object('reason', 'injury'),
      '§95 (retire): a payload that is not a retirement moved');
    -- (bowler) A Hilton bowler replaced mid-over because he is injured: the
    -- change reaches Westville, the reason does not; Westville's own bowler's
    -- reason reaches Westville.
    PERFORM _assert(NOT (ball_event_payload_seen(M_OTHER, 'bowler', NULL, P_PILLAY, jsonb_build_object('reason', 'injury')) ? 'reason'),
      '§95 (bowler): Westville''s coach read why a Hilton bowler was replaced');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'bowler', NULL, P_WES, jsonb_build_object('reason', 'injury'))->>'reason' = 'injury',
      '§95 (bowler): Westville''s coach lost why his own bowler was replaced');
    PERFORM _assert(NOT (ball_event_payload_seen(M_OTHER, 'bowler', NULL, NULL, jsonb_build_object('bowler', P_PILLAY::text, 'reason', 'suspended')) ? 'reason'),
      '§95 (bowler): a Hilton bowler named in the payload carried his reason to Westville');
    -- A Law 41 suspension: Westville reads that a Hilton bowler was suspended,
    -- and for how long, not on what ground.
    v_pay := ball_event_payload_seen(M_OTHER, 'bowler_suspended', NULL, P_PILLAY, jsonb_build_object('reason', 'beamers', 'scope', 'match'));
    PERFORM _assert(NOT (v_pay ? 'reason') AND v_pay->>'scope' = 'match',
      format('§95 (suspension): Westville''s coach read the ground of a Hilton bowler''s suspension, or lost its scope: %s', v_pay));
    v_pay := jsonb_build_object('batter', P_PILLAY, 'reason', 'hurt');
    PERFORM _as(U_C2_91);
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, v_pay)->>'reason' = 'hurt',
      '§95 (retire): Hilton''s coach lost his own boy''s reason');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, jsonb_build_object('batter', 'A Typed Name', 'reason', 'hurt'))->>'reason' = 'not out',
      '§95 (retire): a typed name read as hurt');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'bowler', NULL, P_PILLAY, jsonb_build_object('reason', 'injury'))->>'reason' = 'injury',
      '§95 (bowler): Hilton''s coach lost why his own bowler was replaced');
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'bowler_suspended', NULL, P_PILLAY, jsonb_build_object('reason', 'beamers', 'scope', 'match'))->>'reason' = 'beamers',
      '§95 (suspension): Hilton''s coach lost the ground of his own bowler''s suspension');
    PERFORM _assert(NOT (ball_event_payload_seen(M_OTHER, 'bowler', NULL, P_WES, jsonb_build_object('reason', 'injury')) ? 'reason'),
      '§95 (bowler): Hilton''s coach read why a Westville bowler was replaced');
    PERFORM _assert(NOT (ball_event_payload_seen(M_OTHER, 'bowler', NULL, NULL, jsonb_build_object('bowler', 'A Typed Bowler', 'reason', 'injury')) ? 'reason'),
      '§95 (bowler): a typed bowler''s reason reached a reader');
    -- The office at his school. His own guardian is walked in smoke-cockpit
    -- (group 7); earlier sections here change that guardian's link.
    PERFORM _as(U_REGISTRAR);
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, v_pay)->>'reason' = 'hurt',
      '§95 (retire): the office at his school lost the reason');
    -- Q1 as built (Kameel, 28 Oct 2026: "Everyone at his school (as
    -- built)"): a team-mate at his school, with his player role's
    -- fixture.read, reads "hurt" too.
    PERFORM _as(U_PUPIL);
    PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, v_pay)->>'reason' = 'hurt',
      '§95 (retire): a reader at his school lost the reason (Q1: the school is the boundary)');
    -- (platform) Kameel, 28 Oct 2026: a platform-wide caller never unmasks.
    -- The league account and the owner's key hold fixture.read on an
    -- assignment naming no school, which app_can() passes for every school.
    FOREACH z IN ARRAY ARRAY[to_jsonb(U_LEAGUE), to_jsonb(U_OWNER)] LOOP
      PERFORM _as((z #>> '{}')::uuid);
      PERFORM _assert(app_is_platform_wide(), format('§95 (platform): %s is not platform-wide', z));
      got := ball_event_payload_seen(M_OTHER, 'retire', NULL, NULL, v_pay)->>'reason';
      PERFORM _assert(got = 'not out', format('§95 (platform): a platform-wide caller read a retirement as %s', got));
      PERFORM _assert(NOT (ball_event_payload_seen(M_OTHER, 'bowler', NULL, P_PILLAY, jsonb_build_object('reason', 'injury')) ? 'reason'),
        '§95 (platform): a platform-wide caller read why a bowler was replaced');
      PERFORM _assert(NOT (ball_event_payload_seen(M_OTHER, 'bowler_suspended', NULL, P_PILLAY, jsonb_build_object('reason', 'beamers', 'scope', 'match')) ? 'reason'),
        '§95 (platform): a platform-wide caller read the ground of a suspension');
      PERFORM _assert(ball_event_payload_seen(M_OTHER, 'retire', 'W', NULL, jsonb_build_object('batter', P_PILLAY, 'reason', 'out'))->>'reason' = 'out',
        '§95 (platform): a retired-out lost its reason for a platform-wide caller');
    END LOOP;

    -- (league) Kameel, 28 Oct 2026: "Only its own competitions: refuse a
    -- platform-wide caller". The seed's league account is platform-wide, and
    -- so is the owner's key: neither reads any conduct record through the
    -- door, whichever competition is asked. A league scoped to Hilton reads
    -- its own competition's two records (a Hilton boy's and a Westville
    -- boy's), logged in each boy's school, and nothing of Westville's league
    -- or of the competition nobody organises; Westville's league reads its
    -- own. The competition nobody organises opens to nobody.
    PERFORM set_config('app.user_id', '', true);
    z := _seed_118_league();
    FOREACH got IN ARRAY ARRAY[U_LEAGUE::text, U_OWNER::text] LOOP
      PERFORM _as(got::uuid);
      SELECT count(*) INTO n FROM competition_discipline_records(NULL);
      PERFORM _assert(n = 0, format('§95 (league): a platform-wide caller read %s conduct record(s)', n));
      SELECT count(*) INTO n FROM (SELECT 1 FROM competition_discipline_records((z->>'c_hil')::uuid)
                                   UNION ALL SELECT 1 FROM competition_discipline_records((z->>'c_wes')::uuid)
                                   UNION ALL SELECT 1 FROM competition_discipline_records((z->>'c_none')::uuid)) q;
      PERFORM _assert(n = 0, format('§95 (league): a platform-wide caller read %s record(s) of a named competition', n));
      PERFORM _assert(_v116_fact('logged', got::uuid, HIL) = '0:',
        format('§95 (league): a platform-wide read that returned nothing was logged (%s)', _v116_fact('logged', got::uuid, HIL)));
    END LOOP;
    PERFORM _as((z->>'hilleague')::uuid);
    PERFORM _assert(NOT app_is_platform_wide(), '§95 (league): Hilton''s league is platform-wide');
    got := (SELECT string_agg(x.k, ',' ORDER BY x.k) FROM (
              SELECT CASE r.id WHEN (z->>'r_hil')::uuid THEN 'r_hil' WHEN (z->>'r_hil_w')::uuid THEN 'r_hil_w'
                               WHEN (z->>'r_wes')::uuid THEN 'r_wes' WHEN (z->>'r_none')::uuid THEN 'r_none' ELSE 'other' END AS k
                FROM competition_discipline_records(NULL) r) x);
    PERFORM _assert(got = 'r_hil,r_hil_w', format('§95 (league): Hilton''s league read %s, not its own competition''s two', coalesce(got, 'nothing')));
    SELECT count(*) INTO n FROM competition_discipline_records((z->>'c_wes')::uuid);
    PERFORM _assert(n = 0, format('§95 (league): Hilton''s league read %s of Westville''s league''s records', n));
    SELECT count(*) INTO n FROM competition_discipline_records((z->>'c_none')::uuid);
    PERFORM _assert(n = 0, format('§95 (league): a competition nobody organises opened %s record(s) to Hilton''s league', n));
    PERFORM _assert(_v116_fact('logged', (z->>'hilleague')::uuid, HIL) LIKE '%' || P_PILLAY::text || '%'
                    AND _v116_fact('logged', (z->>'hilleague')::uuid, WES) LIKE '%' || P_WES::text || '%'
                    AND _v116_fact('logged', (z->>'hilleague')::uuid, HIL) NOT LIKE '%' || P_WES::text || '%',
      format('§95 (league): the reads were not logged per school: Hilton %s, Westville %s',
             _v116_fact('logged', (z->>'hilleague')::uuid, HIL), _v116_fact('logged', (z->>'hilleague')::uuid, WES)));
    PERFORM _as((z->>'wesleague')::uuid);
    got := (SELECT string_agg(CASE r.id WHEN (z->>'r_wes')::uuid THEN 'r_wes' ELSE 'other' END, ',')
              FROM competition_discipline_records(NULL) r);
    PERFORM _assert(got = 'r_wes', format('§95 (league): Westville''s league read %s, not its own competition''s one', coalesce(got, 'nothing')));

    -- (doors)
    PERFORM _assert(NOT has_function_privilege('public', 'app_user_email_seen(uuid,uuid,text)'::regprocedure, 'EXECUTE')
                    AND NOT has_function_privilege('public', 'ball_event_payload_seen(uuid,text,text,uuid,jsonb)'::regprocedure, 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'app_user_email_seen(uuid,uuid,text)'::regprocedure, 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'ball_event_payload_seen(uuid,text,text,uuid,jsonb)'::regprocedure, 'EXECUTE')
                    AND NOT has_function_privilege('public', 'competition_discipline_records(uuid)'::regprocedure, 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'competition_discipline_records(uuid)'::regprocedure, 'EXECUTE'),
      '§95 (doors): the definers are not the application''s alone');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 95
  -- └── db/118 (section 95) ──────────────────────────────────────────


  -- ┌── db/119 (section 96) ──────────────────────────────────────────
  -- ── 96. His family means a link live today (db/119) ──
  -- The Opus review of #176: is_family_of() read no date and no pad scope.
  -- Staged by _v119_stage(); every read and write is the caller's own, under
  -- row security (_v119_passport(), _v119_scouting(), _v119_name_x(),
  -- _v119_withdraw()). Holds with or without db/115: Westville's consent is
  -- read by nobody at Hilton through the policies' other terms, and the
  -- scouting read's other terms are app_can(), which reads the same dates.
  --
  -- What each label holds:
  --   (live)     a live guardian and the boy (self-access) are his family:
  --              each reads his passport consent and scouting decision; the
  --              guardian names school X for him and the boy withdraws it
  --   (ended)    a guardian whose assignment's valid_until is today, one whose
  --              expires_at has passed, and one whose link ended today (db/62)
  --              are nobody's family: each reads neither table's row, names no
  --              school (refused) and withdraws nothing (no row moves)
  --   (early)    a guardian whose link begins tomorrow: the same
  --   (pad)      on a pad's credential the live guardian and the boy are
  --              nobody's family: no read, no write; off the pad, both again
  --   (passport) passport() and passport_name() (db/116, through
  --              passport_open()): the live guardian, the boy and his coach
  --              open them; the ended, expired, link-ended and early
  --              guardians get no line and no name; on a pad's credential
  --              nobody does, the coach included (app_can() refuses a pad)
  --   (physio)   db/111's refusal: the physio who is F's mother may not
  --              record his injury on her live link, nor once it has ended
  --              (is_family_of() then says no; injury_writer_is_family() still
  --              says yes), nor on a pad (not_permitted, and the family test
  --              still yes)
  --   (grants)   is_family_of() a pinned, stable definer; EXECUTE for
  --              scrbrd_app and not PUBLIC, nor anon or authenticated where
  --              they exist
  --
  -- Falsified, each change made as the owner before this section ran (the
  -- section alone, cut from this file, on 22 Oct 2026); unchanged it passed,
  -- and each change went red at its label:
  --   is_family_of() without a.valid_until  → (ended): ended is the boy's family
  --   is_family_of() without a.expires_at   → (ended): expired is the boy's family
  --   is_family_of() without s.valid_until  → (ended): linkend is the boy's family
  --   is_family_of() without s.valid_from   → (early): early is the boy's family
  --   is_family_of() without the pad test   → (pad): live is the boy's family on a pad
  --   injury_writer_is_family() as          → (physio): injury_writer_is_family()
  --     is_family_of() alone                   let her ended link go
  --   GRANT EXECUTE ... TO PUBLIC           → (grants): is_family_of() is not
  --                                            scrbrd_app's alone
  DECLARE
    y    jsonb := _v119_stage();
    F    uuid;
    who  text;
    T    date := sa_today();
    v_ok boolean;
    v_reason text;
    v_f  oid := to_regprocedure('is_family_of(uuid)');
    v_n  int;
  BEGIN
    F := (y->>'F')::uuid;
    PERFORM _assert(_v119_owner_passport(y) = 'WES', format('§96: staged consents read [%s]', _v119_owner_passport(y)));

    -- (live)
    FOREACH who IN ARRAY ARRAY['live', 'fboy'] LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(is_family_of(F), format('§96 (live): %s is not the boy''s family', who));
      PERFORM _assert(_v119_passport(y) = 'WES' AND _v119_scouting(y) = 'granted',
        format('§96 (live): %s reads [%s] and [%s]', who, _v119_passport(y), _v119_scouting(y)));
    END LOOP;
    PERFORM _as((y->>'live')::uuid);
    PERFORM _assert(_v119_name_x(y) = 'written', '§96 (live): the live guardian could not name school X');
    PERFORM _as((y->>'fboy')::uuid);
    PERFORM _assert(_v119_withdraw(y, (y->>'X')::uuid) = 1, '§96 (live): the boy could not withdraw school X');
    PERFORM _assert(_v119_owner_passport(y) = 'WES,X(w)', format('§96 (live): the owner reads [%s]', _v119_owner_passport(y)));

    -- (ended), (early)
    FOREACH who IN ARRAY ARRAY['ended', 'expired', 'linkend', 'early'] LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM _assert(NOT is_family_of(F),
        format('§96 (%s): %s is the boy''s family', CASE who WHEN 'early' THEN 'early' ELSE 'ended' END, who));
      PERFORM _assert(_v119_passport(y) = '' AND _v119_scouting(y) = '',
        format('§96 (%s): %s reads [%s] and [%s]', CASE who WHEN 'early' THEN 'early' ELSE 'ended' END,
               who, _v119_passport(y), _v119_scouting(y)));
      PERFORM _assert(_v119_name_x(y) = 'refused',
        format('§96 (%s): %s named school X for the boy', CASE who WHEN 'early' THEN 'early' ELSE 'ended' END, who));
      PERFORM _assert(_v119_withdraw(y, '22222222-2222-2222-2222-222222222222'::uuid) = 0,
        format('§96 (%s): %s withdrew the boy''s consent', CASE who WHEN 'early' THEN 'early' ELSE 'ended' END, who));
    END LOOP;
    PERFORM _assert(_v119_owner_passport(y) = 'WES,X(w)', format('§96 (ended): the owner reads [%s]', _v119_owner_passport(y)));

    -- (pad)
    FOREACH who IN ARRAY ARRAY['live', 'fboy'] LOOP
      PERFORM _as((y->>who)::uuid);
      PERFORM set_config('app.scope', 'pad', true);
      PERFORM _assert(NOT is_family_of(F), format('§96 (pad): %s is the boy''s family on a pad', who));
      PERFORM _assert(_v119_passport(y) = '' AND _v119_scouting(y) = '',
        format('§96 (pad): %s on a pad reads [%s] and [%s]', who, _v119_passport(y), _v119_scouting(y)));
      PERFORM _assert(_v119_name_x(y) = 'refused', format('§96 (pad): %s on a pad named school X', who));
      PERFORM _assert(_v119_withdraw(y, '22222222-2222-2222-2222-222222222222'::uuid) = 0,
        format('§96 (pad): %s on a pad withdrew the boy''s consent', who));
      PERFORM set_config('app.scope', '', true);
      PERFORM _assert(is_family_of(F) AND _v119_passport(y) = 'WES,X(w)',
        format('§96 (pad): off the pad %s reads [%s]', who, _v119_passport(y)));
    END LOOP;

    -- (passport)
    FOREACH who IN ARRAY ARRAY['live:t', 'fboy:t', 'coach:t', 'ended:f', 'expired:f', 'linkend:f', 'early:f'] LOOP
      PERFORM _as((y->>split_part(who, ':', 1))::uuid);
      SELECT count(*) INTO v_n FROM passport(F);
      PERFORM _assert((v_n > 0) = (split_part(who, ':', 2) = 't')
                      AND (passport_name(F) IS NOT NULL) = (split_part(who, ':', 2) = 't'),
        format('§96 (passport): %s reads %s passport line(s) and the name %s',
               split_part(who, ':', 1), v_n, coalesce(passport_name(F), '(none)')));
      PERFORM set_config('app.scope', 'pad', true);
      SELECT count(*) INTO v_n FROM passport(F);
      PERFORM _assert(v_n = 0 AND passport_name(F) IS NULL,
        format('§96 (passport): %s on a pad reads %s passport line(s) and the name %s',
               split_part(who, ':', 1), v_n, coalesce(passport_name(F), '(none)')));
      PERFORM set_config('app.scope', '', true);
    END LOOP;

    -- (physio)
    PERFORM _as((y->>'mum')::uuid);
    PERFORM _assert(is_family_of(F) AND injury_writer_is_family(F), '§96 (physio): the mother-physio''s live link is not family');
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(F, 'Shin splints', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'family_cannot_record',
      format('§96 (physio): on her live link the mother-physio recorded her son''s injury (%s / %s)', v_ok, v_reason));
    PERFORM _v119_end_link((y->>'mum')::uuid, F);
    PERFORM _assert(NOT is_family_of(F), '§96 (physio): the mother-physio''s ended link is still is_family_of()');
    PERFORM _assert(injury_writer_is_family(F), '§96 (physio): injury_writer_is_family() let her ended link go');
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(F, 'Shin splints', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'family_cannot_record',
      format('§96 (physio): on her ended link the mother-physio recorded her son''s injury (%s / %s)', v_ok, v_reason));
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM _assert(injury_writer_is_family(F), '§96 (physio): on a pad injury_writer_is_family() says she is not his mother');
    SELECT r.ok, r.reason INTO v_ok, v_reason FROM injury_record(F, 'Shin splints', 'minor', T, true, T + 7, T + 7, false, NULL) r;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_permitted',
      format('§96 (physio): on a pad the mother-physio''s record was answered %s / %s', v_ok, v_reason));
    PERFORM set_config('app.scope', '', true);

    -- (grants)
    PERFORM _assert((SELECT p.prosecdef AND p.provolatile = 's'
                            AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(p.proconfig, '{}'))
                       FROM pg_proc p WHERE p.oid = v_f),
      '§96 (grants): is_family_of() is not a pinned, stable definer');
    PERFORM _assert(has_function_privilege('scrbrd_app', v_f, 'EXECUTE')
                    AND NOT has_function_privilege('public', v_f, 'EXECUTE')
                    AND NOT EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon', 'authenticated')
                                       AND has_function_privilege(r.oid, v_f, 'EXECUTE')),
      '§96 (grants): is_family_of() is not scrbrd_app''s alone');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 96
  -- └── db/119 (section 96) ──────────────────────────────────────────
  -- ┌── db/120 (section 97) ──────────────────────────────────────────
  -- ── 97. Push switched off, own rows only (db/120, NOTIFICATIONS S4) ──
  -- D20: a person's own preference, per kind or per kind and child; never
  -- safeguarding, welfare or system (nor injury or compromise, db/120 §2);
  -- push only. D21: a pupil's quiet hours, asked of the caller alone.
  -- Staged by _v120_stage(); every read and write below is the caller's own.
  --
  -- What each label holds:
  --   (own)      a guardian writes and reads his own rows; another guardian,
  --              the pupil and the coach read none of them
  --   (others)   nobody writes a row in another person's name, moves his own
  --              to another person, or changes another's
  --   (child)    a row about a child only for his family: ga for A, not B;
  --              not the coach of A's side; a row never moves to another child
  --   (locked)   safeguarding, welfare, system, injury, compromise, an unknown
  --              kind, and a per-child row for a kind never about a child,
  --              are each refused by a CHECK
  --   (one)      one row per person, kind and child; no DELETE
  --   (hidden)   nothing: ga muted the kind and the child, and the notice about
  --              A is still in his my_notifications
  --   (quiet)    my_push_quiet_hours() is true for the pupil alone
  --   (choices)  my_alert_choices(): ga per child, the pupil and the coach per
  --              kind, each the caller's own; an assignment ended (_revoke())
  --              takes the child off and his row can no longer be changed
  --   (ended)    a link ended by its date (valid_until yesterday) under an
  --              assignment still live (db/119's is_family_of()): gend is
  --              offered his kinds and not the child, can neither write a new
  --              row about him nor flip the one he wrote while live (which he
  --              still reads), and passport_name() no longer names the boy
  --   (pad)      under a pad's resume credential (db/50) a person reads none of
  --              his preferences, writes none and changes none, is offered no
  --              switch, and is told of no quiet hours
  --
  -- Falsified on 28 Oct 2026, each change made as the owner before this
  -- section ran (the section alone, cut from this file), each red the first:
  --   notification_pref_read as `true`             → (own) red: gb reads 2 of
  --                                                   ga's preferences
  --   the insert policy without is_family_of()     → (child) red: ga wrote a
  --                                                   preference about B
  --   'welfare' in notification_pref_mutable_kind  → (locked) red: a welfare
  --                                                   preference was accepted
  --   pad_scope_select on notification_pref true  → (pad) red: ga reads 2 of
  --                                                   his preferences on a pad
  -- (ended) was added on 28 Oct 2026 after the Opus review; its own
  -- falsification is db/119's: is_family_of() without s.valid_until turns it
  -- red at "gend flipped his row about A", and my_alert_choices() without its
  -- s.valid_until turns it red at "gend is offered".
  DECLARE
    y   jsonb := _v120_stage();
    ga  uuid;
    k   text;
    n   int;
    got text;
  BEGIN
    ga := (y->>'ga')::uuid;
    -- (own)
    PERFORM _as(ga);
    INSERT INTO notification_pref (person_id, kind, push) VALUES (ga, 'notice', false);
    INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES (ga, 'recognition', (y->>'A')::uuid, false);
    SELECT count(*) INTO n FROM notification_pref;
    PERFORM _assert(n = 2, format('§97 (own): ga reads %s of his two preferences', n));
    PERFORM _assert((SELECT updated_at FROM notification_pref WHERE kind = 'notice') IS NOT NULL, '§97 (own): no time on his row');
    FOREACH k IN ARRAY ARRAY['gb', 'pupil', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO n FROM notification_pref WHERE person_id = ga;
      PERFORM _assert(n = 0, format('§97 (own): %s reads %s of ga''s preferences', k, n));
    END LOOP;

    -- (others)
    PERFORM _as((y->>'gb')::uuid);
    BEGIN
      INSERT INTO notification_pref (person_id, kind, push) VALUES (ga, 'fixture', false);
      PERFORM _assert(false, '§97 (others): gb wrote a preference in ga''s name');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    UPDATE notification_pref SET push = true WHERE person_id = ga;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 0, format('§97 (others): gb changed %s of ga''s preferences', n));
    INSERT INTO notification_pref (person_id, kind, push) VALUES ((y->>'gb')::uuid, 'fixture', false);
    BEGIN
      UPDATE notification_pref SET person_id = ga WHERE kind = 'fixture';
      PERFORM _assert(false, '§97 (others): gb moved his own preference to ga');
    EXCEPTION WHEN insufficient_privilege OR check_violation THEN NULL;
    END;
    PERFORM _as(ga);
    SELECT count(*) INTO n FROM notification_pref WHERE NOT push;
    PERFORM _assert(n = 2, format('§97 (others): ga''s two rows read %s off after gb''s tries', n));

    -- (child)
    BEGIN
      INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES (ga, 'availability', (y->>'B')::uuid, false);
      PERFORM _assert(false, '§97 (child): ga wrote a preference about B, who is not his');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      UPDATE notification_pref SET subject_player_id = (y->>'B')::uuid WHERE kind = 'recognition';
      PERFORM _assert(false, '§97 (child): ga moved his row about A onto B');
    EXCEPTION WHEN insufficient_privilege OR check_violation THEN NULL;
    END;
    PERFORM _as((y->>'coach')::uuid);
    BEGIN
      INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES ((y->>'coach')::uuid, 'lift', (y->>'A')::uuid, false);
      PERFORM _assert(false, '§97 (child): A''s coach wrote a preference about A');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    PERFORM _as((y->>'gb')::uuid);
    INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES ((y->>'gb')::uuid, 'lift', (y->>'B')::uuid, false);

    -- (locked)
    PERFORM _as(ga);
    FOREACH k IN ARRAY ARRAY['safeguarding', 'welfare', 'system', 'injury', 'compromise', 'gossip'] LOOP
      BEGIN
        INSERT INTO notification_pref (person_id, kind, push) VALUES (ga, k, false);
        PERFORM _assert(false, format('§97 (locked): a %s preference was accepted', k));
      EXCEPTION WHEN check_violation THEN NULL;
      END;
    END LOOP;
    FOREACH k IN ARRAY ARRAY['notice', 'fixture'] LOOP
      BEGIN
        INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES (ga, k, (y->>'A')::uuid, false);
        PERFORM _assert(false, format('§97 (locked): a per-child %s preference was accepted', k));
      EXCEPTION WHEN check_violation THEN NULL;
      END;
    END LOOP;

    -- (one)
    BEGIN
      INSERT INTO notification_pref (person_id, kind, push) VALUES (ga, 'notice', true);
      PERFORM _assert(false, '§97 (one): a second notice preference for ga');
    EXCEPTION WHEN unique_violation THEN NULL;
    END;
    INSERT INTO notification_pref (person_id, kind, push) VALUES (ga, 'notice', true)
      ON CONFLICT (person_id, kind, (coalesce(subject_player_id, '00000000-0000-0000-0000-000000000000'::uuid)))
      DO UPDATE SET push = excluded.push;
    PERFORM _assert((SELECT push FROM notification_pref WHERE kind = 'notice'), '§97 (one): on again did not take');
    UPDATE notification_pref SET push = false WHERE kind = 'notice';
    BEGIN
      DELETE FROM notification_pref WHERE kind = 'notice';
      PERFORM _assert(false, '§97 (one): the application deleted a preference');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- (hidden) muted for the kind and for A, and still his to read
    SELECT count(*) INTO n FROM my_notifications WHERE id = (y->>'N')::uuid;
    PERFORM _assert(n = 1, format('§97 (hidden): ga muted recognition for A and his notice about A reads %s rows in my_notifications', n));
    SELECT count(*) INTO n FROM notification WHERE id = (y->>'N')::uuid;
    PERFORM _assert(n = 1, '§97 (hidden): the notice is gone from ga''s notification read');

    -- (pad) the same people, under a pad's resume credential
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', gen_random_uuid()::text, true);
    SELECT count(*) INTO n FROM notification_pref;
    PERFORM _assert(n = 0, format('§97 (pad): ga reads %s of his preferences on a pad', n));
    BEGIN
      INSERT INTO notification_pref (person_id, kind, push) VALUES (ga, 'fixture', false);
      PERFORM _assert(false, '§97 (pad): ga wrote a preference on a pad');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    UPDATE notification_pref SET push = true;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM _assert(n = 0, format('§97 (pad): ga changed %s preference(s) on a pad', n));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM my_alert_choices()), '§97 (pad): ga is offered switches on a pad');
    PERFORM _as((y->>'pupil')::uuid);
    PERFORM _assert(NOT my_push_quiet_hours(), '§97 (pad): the pupil is told of quiet hours on a pad');
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _as(ga);
    SELECT count(*) INTO n FROM notification_pref WHERE NOT push;
    PERFORM _assert(n = 2, format('§97 (pad): off the pad ga reads %s of his two rows off', n));

    -- (quiet)
    PERFORM _assert(NOT my_push_quiet_hours(), '§97 (quiet): a guardian has quiet hours');
    PERFORM _as((y->>'pupil')::uuid);
    PERFORM _assert(my_push_quiet_hours(), '§97 (quiet): the pupil has no quiet hours');
    PERFORM _as((y->>'coach')::uuid);
    PERFORM _assert(NOT my_push_quiet_hours(), '§97 (quiet): a coach has quiet hours');

    -- (choices)
    PERFORM _as(ga);
    got := _v120_choices(y);
    PERFORM _assert(got = 'notice(off),fixture,recognition@A(off),availability@A,lift@A', format('§97 (choices): ga is offered %s', got));
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM my_alert_choices() WHERE quiet_hours), '§97 (choices): ga is told of quiet hours');
    PERFORM _as((y->>'gb')::uuid);
    got := _v120_choices(y);
    PERFORM _assert(got = 'notice,fixture(off),recognition@B,availability@B,lift@B(off)', format('§97 (choices): gb is offered %s', got));
    PERFORM _as((y->>'pupil')::uuid);
    got := _v120_choices(y);
    PERFORM _assert(got = 'notice,recognition,fixture', format('§97 (choices): the pupil is offered %s', got));
    PERFORM _assert((SELECT bool_and(quiet_hours) FROM my_alert_choices()), '§97 (choices): the pupil is not told of his quiet hours');
    PERFORM _as((y->>'coach')::uuid);
    got := _v120_choices(y);
    PERFORM _assert(got = 'notice,recognition,fixture', format('§97 (choices): the coach is offered %s', got));
    -- The link ends: A leaves ga's switches, and his row about A is fixed.
    PERFORM _revoke(ga);
    PERFORM _as(ga);
    got := _v120_choices(y);
    PERFORM _assert(got = '', format('§97 (choices): with his link ended ga is offered %s', got));
    BEGIN
      UPDATE notification_pref SET push = true WHERE kind = 'recognition';
      PERFORM _assert(false, '§97 (choices): ga changed his row about A after his link ended');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;

    -- (ended) gend's link to A ends by its date; his assignment stays live.
    PERFORM _as((y->>'gend')::uuid);
    got := _v120_choices(y);
    PERFORM _assert(got = 'notice,fixture,recognition@A,availability@A,lift@A', format('§97 (ended): while live gend is offered %s', got));
    INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES ((y->>'gend')::uuid, 'availability', (y->>'A')::uuid, false);
    PERFORM _assert(passport_name((y->>'A')::uuid) IS NOT NULL, '§97 (ended): while live gend does not open A''s passport');
    PERFORM _v120_end_link((y->>'gend')::uuid, (y->>'A')::uuid);
    PERFORM _assert(EXISTS (SELECT 1 FROM role_assignment a WHERE a.person_id = (y->>'gend')::uuid AND a.active
                               AND (a.valid_until IS NULL OR a.valid_until > current_date)),
      '§97 (ended): gend''s assignment is not live, so this is not the dated-link case');
    PERFORM _assert(NOT is_family_of((y->>'A')::uuid), '§97 (ended): gend is still A''s family');
    got := _v120_choices(y);
    PERFORM _assert(got = 'notice,fixture', format('§97 (ended): with his link ended gend is offered %s', got));
    BEGIN
      INSERT INTO notification_pref (person_id, kind, subject_player_id, push) VALUES ((y->>'gend')::uuid, 'lift', (y->>'A')::uuid, false);
      PERFORM _assert(false, '§97 (ended): gend wrote a new row about A after his link ended');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      UPDATE notification_pref SET push = true WHERE subject_player_id = (y->>'A')::uuid;
      PERFORM _assert(false, '§97 (ended): gend flipped his row about A after his link ended');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    SELECT count(*) INTO n FROM notification_pref WHERE subject_player_id = (y->>'A')::uuid AND NOT push;
    PERFORM _assert(n = 1, format('§97 (ended): gend reads %s of his own row about A (off)', n));
    PERFORM _assert(passport_name((y->>'A')::uuid) IS NULL, '§97 (ended): with his link ended gend still opens A''s passport');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 97
  -- └── db/120 (section 97) ──────────────────────────────────────────

  -- ┌── db/121 (section 98) ──────────────────────────────────────────
  -- ┌── section 98: the Laws audit of 28 Oct 2026 (db/121) ──
  -- Kameel's decisions (audit/AUDIT_scoring_laws_2026-10-28.md §6), the ones
  -- with SQL, on _v121_stage()'s fixture:
  --   (F5)  a run out going for a second bye: the bye is not A's run and not
  --         C's; the rules' table, as laws-audit.test.mjs has it
  --   (Q2)  no free hit after a waist-high no-ball (21 bowled stands); one
  --         after a front-foot no-ball (24 lbw saved, over a delivery not in
  --         the over: F11) and after one of no recorded kind (30 saved); a
  --         beamer on a free hit leaves it for the next (27 caught saved)
  --   (F7)  an all-run four and six with overthrows are no four and no six;
  --         a struck four and a no-ball's six are
  --   (F4)  the scorer's amendment approved by the superadmin, 4 voided; the
  --         route's re-judging handed to scoring_amendment_rejudge(): 5 and 6
  --         are A's, 7 B's, in ball_event_live and every career reader; a
  --         reader who may not read the match reads none of it; anybody but
  --         the approver, in the approving transaction, is refused
  --   (S2)  the door names only a batter of the innings (the bowler is
  --         refused) with a player row (an id with none is refused in words)
  --   (B1)  on M2 the re-judging reaches the milestone notices both ways: D's
  --         fifty, which the void alone left standing on the stamps, is taken
  --         back; E's, which the re-judged log makes, is noticed "after a
  --         correction."
  --   (B2)  tools/sql/laws121-precheck.sql's query (_v121_precheck()) finds
  --         no match beside this section's whose stored dismissals db/121
  --         moves — the seeded database holds none — and on this section's
  --         match the one of each it planted (21 now stands, 24 now saved)
  --
  -- Falsified, each change made as the owner before this file ran:
  --   ball_runs_off_bat()'s 'W' arm put back (db/40's)  → (F5) red
  --   ball_on_free_hit() put back (db/54's)              → (Q2) red: 21 saved
  --   ball_event_live put back (db/71's)                 → (F4) red: 5 is B's
  --   milestone_recheck() made to do nothing             → (B1) red: D's fifty stays
  DECLARE
    y   jsonb := _v121_stage();
    M   uuid;  V_A uuid;  V_B uuid;  V_C uuid;  am uuid;
    got text;
    r   record;
    n   integer;
    U_STRANGER uuid := 'dddddddd-0000-0000-0000-000000000121';
    names jsonb;
  BEGIN
    M := (y->>'m')::uuid; V_A := (y->>'a')::uuid; V_B := (y->>'b')::uuid; V_C := (y->>'c')::uuid; am := (y->>'am')::uuid;

    -- (F5) the rules
    PERFORM _assert(ball_runs_off_bat('W', 1, '{"nbRuns":"byes"}') = 0 AND ball_runs_off_bat('W', 1, '{"nbRuns":"leg_byes"}') = 0
                    AND ball_runs_off_bat('W', 3, '{}') = 3 AND ball_runs_to_bowler('W', 1, '{"nbRuns":"byes"}') = 0
                    AND ball_runs_to_bowler('W', 2, '{}') = 2,
      '§98 (F5): a wicket ball''s byes are the striker''s or the bowler''s');

    -- (Q2, F11) which wickets stand, as the owner of the fixture reads them
    PERFORM _as(U_OWNER);
    SELECT string_agg(b.seq || '=' || CASE WHEN ball_wicket_stands(b.match_id, b.innings, b.seq, b.kind, b.ball_type, b.dismissal) THEN 'out' ELSE 'saved' END,
                      ',' ORDER BY b.seq) INTO got
      FROM ball_event_live b WHERE b.match_id = M AND b.innings = 1 AND b.ball_type = 'W';
    PERFORM _assert(got = '21=out,24=saved,27=saved,30=saved',
      format('§98 (Q2, F11): the wickets on the free-hit fixture read %s', got));

    -- (B2) the precheck: the seeded database holds no dismissal the rule
    -- moves; this section's own match holds the one of each it planted
    SELECT count(*) INTO n FROM _v121_precheck() x WHERE x.match_id <> M;
    PERFORM _assert(n = 0, format('§98 (B2): the precheck finds %s match(es) beside this section''s whose stored dismissals db/121 moves', n));
    SELECT x.now_stands || '/' || x.now_saved INTO got FROM _v121_precheck() x WHERE x.match_id = M;
    PERFORM _assert(got = '1/1', format('§98 (B2): the precheck reads this section''s match %s (21 now stands, 24 now saved: 1/1)', got));

    -- (F4) the amendment, approved, and the balls after it re-judged
    SELECT d.ok, d.reason INTO r FROM scoring_amendment_decide(am, true, NULL) d;
    PERFORM _assert(r.ok, format('§98 (F4): the superadmin could not approve the scorer''s amendment (%s)', r.reason));
    -- (S2) the door names only a batter of the innings with a player row
    BEGIN
      PERFORM scoring_amendment_rejudge(am, jsonb_build_array(jsonb_build_object('seq', 5, 'striker_id', V_C)));
      PERFORM _assert(false, '§98 (S2): the re-judging put the bowler, no batter of the innings, on strike');
    EXCEPTION WHEN invalid_parameter_value THEN
      GET STACKED DIAGNOSTICS got = MESSAGE_TEXT;
      PERFORM _assert(got LIKE '%is not a batter of innings 0%', format('§98 (S2): the bowler was refused in other words: %s', got));
    END;
    BEGIN
      PERFORM scoring_amendment_rejudge(am, jsonb_build_array(jsonb_build_object('seq', 5, 'striker_id', 'eeeeeeee-0000-0000-0000-000000000121')));
      PERFORM _assert(false, '§98 (S2): the re-judging wrote an id SCRBRD holds no player row for');
    EXCEPTION WHEN invalid_parameter_value THEN
      GET STACKED DIAGNOSTICS got = MESSAGE_TEXT;
      PERFORM _assert(got LIKE '%holds no player row%', format('§98 (S2): an id with no player row was refused in other words: %s', got));
    END;
    PERFORM _as(U_SCORER);
    BEGIN
      PERFORM scoring_amendment_rejudge(am, '[]'::jsonb);
      PERFORM _assert(false, '§98 (F4): the scorer, who did not approve it, re-judged the amendment''s balls');
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    PERFORM _as(U_OWNER);
    SELECT scoring_amendment_rejudge(am, jsonb_build_array(
             jsonb_build_object('seq', 5, 'striker_id', V_A), jsonb_build_object('seq', 6, 'striker_id', V_A),
             jsonb_build_object('seq', 7, 'striker_id', V_B), jsonb_build_object('seq', 44, 'striker_id', V_B))) INTO n;
    PERFORM _assert(n = 3, format('§98 (F4): %s ball(s) re-judged (expected 3: 5, 6, 7; 44 is another innings)', n));
    SELECT string_agg(b.seq || '=' || CASE b.striker_id WHEN V_A THEN 'A' WHEN V_B THEN 'B' ELSE '?' END, ',' ORDER BY b.seq) INTO got
      FROM ball_event_live b WHERE b.match_id = M AND b.innings = 0 AND b.kind = 'ball';
    PERFORM _assert(got = '5=A,6=A,7=B', format('§98 (F4): ball_event_live''s strikers read %s (the fold: 5=A,6=A,7=B)', got));
    PERFORM _as(U_STRANGER);
    SELECT count(*) INTO n FROM ball_event_rejudged WHERE match_id = M;
    PERFORM _assert(n = 0, format('§98 (F4): a reader with no read on the match read %s re-judged row(s)', n));
    PERFORM _as(U_OWNER);
    SELECT count(*) INTO n FROM ball_event_rejudged WHERE match_id = M;
    PERFORM _assert(n = 3, format('§98 (F4): the control read %s re-judged row(s), not 3', n));

    -- (B1) the re-judging reaches the milestone notices, both ways: D's
    -- fifty, which the re-judged log takes away, is taken back; E's, which
    -- it makes, is noticed after a correction
    names := jsonb_build_object(y->>'d', 'D', y->>'e', 'E');
    got := _v121_notices((y->>'m2')::uuid, names);
    PERFORM _assert(got = 'D fifty live (notice up): Fifty (51) against Verify 121 B1.',
      format('§98 (B1): before the amendment M2''s notices read %s', got));
    SELECT d.ok, d.reason INTO r FROM scoring_amendment_decide((y->>'am2')::uuid, true, NULL) d;
    PERFORM _assert(r.ok, format('§98 (B1): the superadmin could not approve the second amendment (%s)', r.reason));
    got := _v121_notices((y->>'m2')::uuid, names);
    PERFORM _assert(got = 'D fifty live (notice up): Fifty (51) against Verify 121 B1.',
      format('§98 (B1): the void alone, on the stamps, moved M2''s notices: %s', got));
    SELECT scoring_amendment_rejudge((y->>'am2')::uuid, jsonb_build_array(jsonb_build_object('seq', 30, 'striker_id', y->>'e'))) INTO n;
    PERFORM _assert(n = 1, format('§98 (B1): %s ball(s) re-judged on M2 (expected 1: 30)', n));
    got := _v121_notices((y->>'m2')::uuid, names);
    PERFORM _assert(got = 'D fifty retracted (notice down): Fifty (51) against Verify 121 B1.; E fifty live (notice up): Fifty (50) against Verify 121 B1, after a correction.',
      format('§98 (B1): after the re-judging M2''s notices read %s', got));
    SELECT (SELECT x.runs FROM player_batting_since((y->>'d')::uuid, NULL) x) || '/'
        || (SELECT x.runs FROM player_batting_since((y->>'e')::uuid, NULL) x) INTO got;
    PERFORM _assert(got = '49/50', format('§98 (B1): D and E''s runs read %s after the re-judging (49/50)', got));
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'milestone_recheck(uuid,smallint,uuid[],boolean)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'milestone_recheck(uuid,smallint,uuid[],boolean)', 'EXECUTE'),
      '§98 (B1, doors): milestone_recheck() is callable by the application or PUBLIC');

    -- (F4, F5, F7) every figure, through the career readers
    SELECT x.runs || '/' || x.balls_faced || ' 4s ' || x.fours || ' 6s ' || x.sixes INTO got FROM player_batting_since(V_A, NULL) x;
    PERFORM _assert(got = '25/7 4s 2 6s 1', format('§98 (F4, F5, F7): A''s batting reads %s (the fold: 25/7 4s 2 6s 1)', got));
    SELECT x.runs || '/' || x.balls_faced || ' 4s ' || x.fours || ' 6s ' || x.sixes INTO got FROM player_batting_career x WHERE x.player_id = V_A;
    PERFORM _assert(got = '25/7 4s 2 6s 1', format('§98 (F7): player_batting_career reads A %s', got));
    SELECT x.runs || '/' || x.balls_faced INTO got FROM player_batting_since(V_B, NULL) x;
    PERFORM _assert(got = '2/12', format('§98 (F4): B''s batting reads %s (the fold: 2/12)', got));
    SELECT x.runs_conceded || ' w ' || x.wickets INTO got FROM player_bowling_since(V_C, NULL) x;
    PERFORM _assert(got = '33 w 1', format('§98 (F5, Q2): C''s bowling reads %s (the fold: 33 w 1)', got));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 98
  -- └── db/121 (section 98) ──────────────────────────────────────────
  -- ┌── db/122 (section 99) ──────────────────────────────────────────
  -- ── 99. Kameel's four decisions of 29 Oct 2026 (db/122) ──
  -- Staged by _v122_stage(); every read and write is the caller's own under
  -- row security, or a definer the application calls.
  --
  -- What each label holds:
  --   (lapse)    "The consent lapses when the link that gave it ends." The
  --              mother names Westville: its coach opens C's passport and its
  --              office reads the consent in force. Her link ends: the coach
  --              no longer opens it (no line, no name); the office and the
  --              father still read the row, lapsed (in force false); she reads
  --              nothing; C's own coach still opens it (his school's arm). The
  --              father, as the grant route does, withdraws the lapsed row and
  --              names Westville afresh: the coach opens it again
  --   (nobody)   a consent with no giver on record opens nothing: school X's
  --              office reads it lapsed and does not open the passport
  --   (scouts)   S's guardian says yes through scouting_consent_set(): the
  --              accredited scout sees him, the office reads the yes in force.
  --              Her link ends: the scout no longer sees him; the office reads
  --              the row still 'granted', in force false
  --   (eighteen) "Let a boy of eighteen record his own scouting yes or no":
  --              Y's guardian's yes is refused (he_is_of_age, db/125 §5 (1),
  --              Kameel 30 Oct 2026: READERS Q1 stands) and her no recorded;
  --              her link ends and she is then refused; Y, eighteen, records
  --              his own yes on his self-access link: one row for him, his,
  --              in force. C, fifteen, on his own live link, is refused
  --              not_yet_eighteen
  --   (age)      "Under eighteen, only his guardian; at eighteen, he does it
  --              himself": C, fifteen, on his own live link, names no school
  --              and withdraws none; Y, eighteen, names one himself and
  --              withdraws it; D's live guardian names one for him
  --   (readers)  the in-force answers are NULL to a reader of neither row (a
  --              Westville parent, the scout, the mother once her link ended)
  --              and on a pad
  --   (email)    "Close both doors": the director of sport reads the pupil
  --              E's name and no address through role_requester(),
  --              pending_claims() (account and presented) and
  --              account_sign_ins(); the adult's addresses as before; the
  --              office reads E's; E reads his own request's
  --   (particles) "Skip them, as the three-letter ones are skipped": a post
  --              of the six two-letter particles alone names nobody; "Al", a
  --              two-letter first name, is still caught, and told; "de Wet"
  --              is still caught by the surname
  --   (sast)     "The school's day (SAST), everywhere": D moved with no date
  --              in a session whose day is not Johannesburg's is dated
  --              sa_today() (closed and opened today), and his seat on the
  --              13XI's lift is voided by Johannesburg's day: kept for a
  --              fixture later today, voided for one tomorrow
  --   (doors)    the readers' definers are scrbrd_app's alone; the giver test
  --              and the scan are nobody's to call
  -- After the read-through (§1d, Kameel 29 Oct 2026, 21:15: each as
  -- recommended):
  --   (self)     Q1: a consent C named for himself at fifteen, before db/122,
  --              is lapsed: school Q's coach does not open his passport, his
  --              father reads it lapsed, and the father's grant to Q clears
  --              it and opens it
  --   (age)      Q2: C, fifteen, may still take a school's name back
  --   (relink)   Q4: S's guardian's ended link granted afresh does not bring
  --              her lapsed yes back; the end corrected in place does
  --   (consent)  Q8: gp, a verified guardian with no processing consent on
  --              record, names no school
  --   (claims)   Q3: the director of sport confirms and declines no pupil's
  --              claim and issues no pupil's code (office_only); the office
  --              does both; her adult's claim and code as before
  --
  -- Falsified, each change made as the owner before this section ran (the
  -- section alone, cut from this file with the setup above it, on 29 Oct
  -- 2026); unchanged it passed, and each change went red at its label:
  --   passport_open() as db/116 wrote it     → (lapse): the Westville coach
  --                                             opened the passport on a lapsed consent
  --   scouting_candidates() as db/08 wrote it → (scouts): the scout saw S on
  --                                             a lapsed yes
  --   scouting_consent_set() as db/08 wrote it → (eighteen): Y, eighteen, was
  --                                             refused his own yes
  --   the two RESTRICTIVE write policies dropped → (age): C, fifteen, named a
  --                                             school for himself
  --   role_requester() as db/81 wrote it      → (email): the director of
  --                                             sport read E's address
  --   pending_claims() as db/81 wrote it      → (email): ... E's claim's addresses
  --   account_sign_ins() as db/81 wrote it    → (email): ... E's sign-in's address
  --   news_public_hits() as db/118 wrote it   → (particles): the particles named 6
  --   player_team_membership_log() as db/08   → (sast): D's rows were dated
  --     wrote it                                  by the session's day
  --   player_move_voids_seats() as db/117     → (sast): the seat's fate was
  --     wrote it                                  decided by the session's day
  -- And after the read-through, the same way (the section alone, 29 Oct
  -- 2026), each guard broken once:
  --   consent_giver_live() without the self-access age → (self): school Q's
  --                                             coach opened the passport
  --   the update policy asking writer_ok() again → (age): C, fifteen, could
  --                                             not take X's name back
  --   consent_giver_live() without the two dates → (relink): the yes came
  --                                             back with a link granted afresh
  --   writer_ok() without processing consent → (consent): gp named a school
  --   pending_claim_confirm() as db/81 wrote it → (claims): the director
  --                                             confirmed the pupil's claim
  --   pending_claim_decline() as db/81 wrote it → (claims): ... declined it
  --   login_code_issue() without the pupil's rule → (claims): ... was issued
  --                                             the pupil's code
  DECLARE
    y    jsonb := _v122_stage();
    C    uuid;
    S    uuid;
    v_pc uuid;
    v_self uuid;
    v_n  int;
    v_ok boolean;
    v_reason text;
    got  text;
    v_h  int;
    v_day text;
    V_C2 uuid := '88888888-0000-0000-0000-00000000000a';   -- 2XI coach, Hilton: writes the posts
    HIL_ uuid := '11111111-1111-1111-1111-111111111111';
    WES_ uuid := '22222222-2222-2222-2222-222222222222';
  BEGIN
    C := (y->>'C')::uuid; S := (y->>'S')::uuid; v_h := (y->>'h')::int;

    -- (lapse)
    PERFORM _as((y->>'mum')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES (C, WES_) RETURNING id INTO v_pc;
    PERFORM _as((y->>'wescoach')::uuid);
    SELECT count(*) INTO v_n FROM passport(C);
    PERFORM _assert(_passport_open(C) AND v_n > 0 AND passport_name(C) IS NOT NULL,
      format('§99 (lapse): on the mother''s live word the Westville coach opens %s line(s)', v_n));
    PERFORM _as((y->>'wesoffice')::uuid);
    PERFORM _assert(passport_consent_in_force(v_pc) IS TRUE, '§99 (lapse): the Westville office does not read the live consent in force');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v119_end_link((y->>'mum')::uuid, C);
    PERFORM _assert(_v122_fact('consents', y) = 'WES(mum),X(-)', format('§99 (lapse): the owner reads [%s]', _v122_fact('consents', y)));
    PERFORM _as((y->>'wescoach')::uuid);
    SELECT count(*) INTO v_n FROM passport(C);
    PERFORM _assert(NOT _passport_open(C) AND v_n = 0 AND passport_name(C) IS NULL,
      format('§99 (lapse): with the mother''s link ended the Westville coach still opens the passport (%s line(s), name %s)',
             v_n, coalesce(passport_name(C), '(none)')));
    FOREACH got IN ARRAY ARRAY['wesoffice', 'dad'] LOOP
      PERFORM _as((y->>got)::uuid);
      PERFORM _assert(_v122_reads(y) >= 1 AND passport_consent_in_force(v_pc) IS FALSE,
        format('§99 (lapse): %s reads %s consent row(s), in force %s', got, _v122_reads(y), passport_consent_in_force(v_pc)));
    END LOOP;
    PERFORM _as((y->>'mum')::uuid);
    PERFORM _assert(_v122_reads(y) = 0 AND passport_consent_in_force(v_pc) IS NULL AND NOT _passport_open(C),
      format('§99 (lapse): the mother, her link ended, reads %s row(s) and in force %s', _v122_reads(y), passport_consent_in_force(v_pc)));
    PERFORM _as((y->>'hcoach')::uuid);
    PERFORM _assert(_passport_open(C), '§99 (lapse): his own coach lost his passport (the home arm is not the consent''s)');
    -- The father gives it afresh, as the grant route does (kit-api.mjs).
    PERFORM _as((y->>'dad')::uuid);
    UPDATE passport_consent SET withdrawn_at = now()
     WHERE player_id = C AND to_school_id = WES_ AND withdrawn_at IS NULL AND passport_consent_in_force(id) = false;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§99 (lapse): the father withdrew %s lapsed row(s), not 1', v_n));
    INSERT INTO passport_consent (player_id, to_school_id) VALUES (C, WES_);
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v122_fact('consents', y) = 'WES(dad),WES(mum)(w:dad),X(-)',
      format('§99 (lapse): after the father''s grant the owner reads [%s]', _v122_fact('consents', y)));
    PERFORM _as((y->>'wescoach')::uuid);
    PERFORM _assert(_passport_open(C), '§99 (lapse): on the father''s live word the Westville coach does not open the passport');

    -- (nobody)
    PERFORM _as((y->>'xoffice')::uuid);
    PERFORM _assert(_v122_reads(y) = 1 AND passport_consent_in_force((y->>'pc_x')::uuid) IS FALSE AND NOT _passport_open(C),
      format('§99 (nobody): school X''s office reads %s row(s), in force %s, and opens the passport: %s',
             _v122_reads(y), passport_consent_in_force((y->>'pc_x')::uuid), _passport_open(C)));

    -- (self)
    PERFORM set_config('app.user_id', '', true);
    v_self := _v122_self_consent(y);
    PERFORM _as((y->>'qcoach')::uuid);
    PERFORM _assert(NOT _passport_open(C) AND passport_name(C) IS NULL,
      '§99 (self): on the word C gave himself at fifteen, school Q''s coach opens his passport');
    PERFORM _as((y->>'dad')::uuid);
    PERFORM _assert(passport_consent_in_force(v_self) IS FALSE,
      format('§99 (self): his father reads the consent C gave himself as in force %s, not lapsed', passport_consent_in_force(v_self)));
    PERFORM _as((y->>'cboy')::uuid);
    PERFORM _assert(passport_consent_in_force(v_self) IS FALSE, '§99 (self): C reads his own fifteen-year-old''s consent in force');
    -- His father names Q, as the grant route does: the lapsed row first.
    PERFORM _as((y->>'dad')::uuid);
    UPDATE passport_consent SET withdrawn_at = now()
     WHERE player_id = C AND to_school_id = (y->>'Q')::uuid AND withdrawn_at IS NULL AND passport_consent_in_force(id) = false;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§99 (self): the father''s grant cleared %s lapsed row(s), not 1', v_n));
    INSERT INTO passport_consent (player_id, to_school_id) VALUES (C, (y->>'Q')::uuid);
    PERFORM _as((y->>'qcoach')::uuid);
    PERFORM _assert(_passport_open(C), '§99 (self): on his father''s word school Q''s coach does not open the passport');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v122_fact('consents', y) = 'Q(cboy)(w:dad),Q(dad),WES(dad),WES(mum)(w:dad),X(-)',
      format('§99 (self): the owner reads [%s]', _v122_fact('consents', y)));

    -- (scouts)
    PERFORM _as((y->>'sg')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set(S, true) s;
    PERFORM _assert(v_ok, format('§99 (scouts): his guardian could not say yes (%s)', v_reason));
    PERFORM _as((y->>'scout')::uuid);
    PERFORM _assert(EXISTS (SELECT 1 FROM scouting_candidates() x WHERE x.player_id = S),
      '§99 (scouts): on his guardian''s live yes the scout does not see him');
    PERFORM _assert(scouting_consent_in_force(S) IS NULL, '§99 (readers): the scout is told whether a yes is in force');
    PERFORM _as((y->>'hoffice')::uuid);
    PERFORM _assert(scouting_consent_in_force(S) IS TRUE, '§99 (scouts): the office does not read the live yes in force');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v119_end_link((y->>'sg')::uuid, S);
    PERFORM _as((y->>'scout')::uuid);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM scouting_candidates() x WHERE x.player_id = S),
      '§99 (scouts): with his guardian''s link ended the scout still sees him');
    PERFORM _as((y->>'hoffice')::uuid);
    SELECT string_agg(c.consent_state, ',') INTO got FROM player_scouting_consent c WHERE c.player_id = S;
    PERFORM _assert(got = 'granted' AND scouting_consent_in_force(S) IS FALSE,
      format('§99 (scouts): the office reads [%s], in force %s', got, scouting_consent_in_force(S)));
    PERFORM _as((y->>'hcoach')::uuid);
    PERFORM _assert(scouting_consent_in_force(S) IS FALSE, '§99 (scouts): his side''s coach does not read the yes lapsed');

    -- (relink)
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v122_relink((y->>'sg')::uuid, S);
    PERFORM _as((y->>'sg')::uuid);
    PERFORM _assert(is_family_of(S), '§99 (relink): the link granted afresh is not live, so this proves nothing');
    PERFORM _as((y->>'hoffice')::uuid);
    PERFORM _assert(scouting_consent_in_force(S) IS FALSE,
      '§99 (relink): a link granted afresh brought her lapsed yes back');
    PERFORM _as((y->>'scout')::uuid);
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM scouting_candidates() x WHERE x.player_id = S),
      '§99 (relink): with her link granted afresh the scout sees him on the old yes');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v122_correct((y->>'sg')::uuid, S);
    PERFORM _as((y->>'hoffice')::uuid);
    PERFORM _assert(scouting_consent_in_force(S) IS TRUE,
      '§99 (relink): the end corrected in place did not bring the yes back');
    PERFORM _as((y->>'scout')::uuid);
    PERFORM _assert(EXISTS (SELECT 1 FROM scouting_candidates() x WHERE x.player_id = S),
      '§99 (relink): with the end corrected the scout does not see him');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v119_end_link((y->>'sg')::uuid, S);

    -- (eighteen)
    -- Reversed by db/125 §5 (1) (Kameel, 30 Oct 2026, seams call 1; READERS
    -- Q1): from his eighteenth birthday his guardian's yes is refused, in
    -- words; her no is still recorded.
    PERFORM _as((y->>'yg')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set((y->>'Y')::uuid, true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'he_is_of_age',
      format('§99 (eighteen): his guardian said yes for the boy of eighteen on her live link (%s/%s)', v_ok, coalesce(v_reason, '-')));
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set((y->>'Y')::uuid, false) s;
    PERFORM _assert(v_ok, format('§99 (eighteen): his guardian''s no was refused on her live link (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v119_end_link((y->>'yg')::uuid, (y->>'Y')::uuid);
    PERFORM _as((y->>'hoffice')::uuid);
    PERFORM _assert(scouting_consent_in_force((y->>'Y')::uuid) IS FALSE, '§99 (eighteen): the guardian''s no reads as a yes in force');
    PERFORM _as((y->>'yg')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set((y->>'Y')::uuid, false) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_a_consented_guardian',
      format('§99 (eighteen): the guardian, her link ended, was answered %s/%s', v_ok, v_reason));
    PERFORM _as((y->>'yboy')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set((y->>'Y')::uuid, true) s;
    PERFORM _assert(v_ok, format('§99 (eighteen): the boy of eighteen was refused his own yes (%s)', v_reason));
    PERFORM _assert(scouting_consent_in_force((y->>'Y')::uuid) IS TRUE, '§99 (eighteen): the boy does not read his own yes in force');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v122_fact('scouting', y) = 'granted:yboy',
      format('§99 (eighteen): Y''s scouting rows read [%s], not one live row of his own', _v122_fact('scouting', y)));
    PERFORM _as((y->>'hoffice')::uuid);
    PERFORM _assert(scouting_consent_in_force((y->>'Y')::uuid) IS TRUE, '§99 (eighteen): the office does not read his own yes in force');
    PERFORM _as((y->>'cboy')::uuid);
    SELECT s.ok, s.reason INTO v_ok, v_reason FROM scouting_consent_set(C, true) s;
    PERFORM _assert(NOT v_ok AND v_reason = 'not_yet_eighteen',
      format('§99 (eighteen): the boy of fifteen, on his own link, was answered %s/%s', v_ok, v_reason));
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM _as((y->>'yboy')::uuid);
    SELECT s.ok INTO v_ok FROM scouting_consent_set((y->>'Y')::uuid, false) s;
    PERFORM _assert(NOT v_ok, '§99 (eighteen): on a pad the boy of eighteen changed his decision');
    PERFORM set_config('app.scope', '', true);
    PERFORM _assert(has_function_privilege('scrbrd_app', 'scouting_consent_set(uuid,boolean)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'scouting_consent_set(uuid,boolean)', 'EXECUTE'),
      '§99 (eighteen): scouting_consent_set() is not the application''s alone');

    -- (age)
    PERFORM _as((y->>'cboy')::uuid);
    got := 'written';
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES (C, (y->>'Z')::uuid);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'refused', '§99 (age): the boy of fifteen named a school for himself');
    -- Under eighteen he may still say no (§1d, Q2): X's name, which nobody
    -- on record gave.
    UPDATE passport_consent SET withdrawn_at = now() WHERE id = (y->>'pc_x')::uuid AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§99 (age): the boy of fifteen took back %s name(s), not X''s one', v_n));
    PERFORM _assert(_v122_reads(y) >= 1, '§99 (age): the boy of fifteen no longer reads his own consents');
    PERFORM _as((y->>'yboy')::uuid);
    got := 'written';
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'Y')::uuid, (y->>'Z')::uuid);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'written', '§99 (age): the boy of eighteen could not name a school himself');
    UPDATE passport_consent SET withdrawn_at = now() WHERE player_id = (y->>'Y')::uuid AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§99 (age): the boy of eighteen withdrew %s consent(s), not his one', v_n));
    PERFORM _as((y->>'gd')::uuid);
    got := 'written';
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'D')::uuid, (y->>'Z')::uuid);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'written', '§99 (age): a live guardian could not name a school for her son of thirteen');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v122_fact('consents', y) = 'Q(cboy)(w:dad),Q(dad),WES(dad),WES(mum)(w:dad),X(-)(w:cboy)',
      format('§99 (age): the owner reads [%s]', _v122_fact('consents', y)));

    -- (consent)
    PERFORM _as((y->>'gp')::uuid);
    PERFORM _assert(is_family_of(C), '§99 (consent): gp''s verified link is not live, so this proves nothing');
    got := 'written';
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES (C, (y->>'Z')::uuid);
    EXCEPTION WHEN insufficient_privilege THEN got := 'refused';
    END;
    PERFORM _assert(got = 'refused', '§99 (consent): a guardian with no processing consent on record named a school');
    PERFORM set_config('app.user_id', '', true);

    -- (readers)
    PERFORM _as((y->>'wesparent')::uuid);
    PERFORM _assert(passport_consent_in_force(v_pc) IS NULL AND scouting_consent_in_force(S) IS NULL,
      '§99 (readers): a parent who is nothing to them is told whether a consent is in force');
    PERFORM _as((y->>'wesoffice')::uuid);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM _assert(passport_consent_in_force(v_pc) IS NULL, '§99 (readers): on a pad the office is told whether a consent is in force');
    PERFORM set_config('app.scope', '', true);

    -- (email)
    PERFORM _as((y->>'dos')::uuid);
    SELECT q.name || '|' || coalesce(q.email, '-') INTO got FROM role_requester((y->>'req_epupil')::uuid) q;
    PERFORM _assert(got = 'V122 Epupil|-', format('§99 (email): the director of sport reads the pupil''s request as [%s]', got));
    SELECT q.name || '|' || coalesce(q.email, '-') INTO got FROM role_requester((y->>'req_eadult')::uuid) q;
    PERFORM _assert(got = 'V122 Eadult|v122.eadult@example.invalid', format('§99 (email): the director of sport reads the adult''s request as [%s]', got));
    SELECT coalesce(string_agg(split_part(coalesce(x.account_email, '-'), '@', 1) || '/' || split_part(coalesce(x.presented_email, '-'), '@', 1),
                               ',' ORDER BY x.account_name), '') INTO got
      FROM pending_claims() x WHERE x.user_id IN ((y->>'epupil')::uuid, (y->>'eadult')::uuid);
    PERFORM _assert(got = 'v122.eadult/v122.eadult.claim,-/-', format('§99 (email): the director of sport reads the claims as [%s]', got));
    SELECT count(*) INTO v_n FROM account_sign_ins((y->>'epupil')::uuid) x;
    PERFORM _assert(v_n = 1 AND (SELECT count(x.email_at_link) FROM account_sign_ins((y->>'epupil')::uuid) x) = 0,
      format('§99 (email): the director of sport reads %s of the pupil''s sign-ins, with an address on %s',
             v_n, (SELECT count(x.email_at_link) FROM account_sign_ins((y->>'epupil')::uuid) x)));
    PERFORM _assert((SELECT string_agg(x.email_at_link, ',') FROM account_sign_ins((y->>'eadult')::uuid) x) = 'v122.eadult.link@example.invalid',
      '§99 (email): the director of sport lost the adult''s sign-in address');
    PERFORM _as((y->>'hoffice')::uuid);
    SELECT q.email INTO got FROM role_requester((y->>'req_epupil')::uuid) q;
    PERFORM _assert(got = 'v122.epupil@example.invalid', format('§99 (email): the office reads the pupil''s request with [%s]', got));
    SELECT x.account_email || '/' || x.presented_email INTO got FROM pending_claims() x WHERE x.user_id = (y->>'epupil')::uuid;
    PERFORM _assert(got = 'v122.epupil@example.invalid/v122.epupil.claim@example.invalid',
      format('§99 (email): the office reads the pupil''s claim as [%s]', got));
    PERFORM _assert((SELECT string_agg(x.email_at_link, ',') FROM account_sign_ins((y->>'epupil')::uuid) x) = 'v122.epupil.link@example.invalid',
      '§99 (email): the office does not read the pupil''s sign-in address');
    PERFORM _as((y->>'epupil')::uuid);
    SELECT q.email INTO got FROM role_requester((y->>'req_epupil')::uuid) q;
    PERFORM _assert(got = 'v122.epupil@example.invalid', format('§99 (email): the pupil reads his own request with [%s]', got));

    -- (claims)
    PERFORM _as((y->>'dos')::uuid);
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM pending_claim_confirm((y->>'claim_epupil')::uuid) x;
    PERFORM _assert(NOT v_ok AND v_reason = 'office_only',
      format('§99 (claims): the director of sport confirming the pupil''s claim was answered %s/%s', v_ok, v_reason));
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM pending_claim_decline((y->>'claim_epupil')::uuid) x;
    PERFORM _assert(NOT v_ok AND v_reason = 'office_only',
      format('§99 (claims): the director of sport declining the pupil''s claim was answered %s/%s', v_ok, v_reason));
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM login_code_issue('v122.epupil@example.invalid', md5('v122-dos-pupil'), 600) x;
    PERFORM _assert(NOT v_ok AND v_reason = 'office_only',
      format('§99 (claims): the director of sport issuing the pupil''s code was answered %s/%s', v_ok, v_reason));
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM login_code_issue('v122.eadult@example.invalid', md5('v122-dos-adult'), 600) x;
    PERFORM _assert(v_ok, format('§99 (claims): the director of sport was refused the adult''s code (%s)', v_reason));
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM pending_claim_decline((y->>'claim_eadult')::uuid) x;
    PERFORM _assert(v_ok, format('§99 (claims): the director of sport was refused the adult''s claim (%s)', v_reason));
    PERFORM _as((y->>'hoffice')::uuid);
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM login_code_issue('v122.epupil@example.invalid', md5('v122-office-pupil'), 600) x;
    PERFORM _assert(v_ok, format('§99 (claims): the office was refused the pupil''s code (%s)', v_reason));
    SELECT x.ok, x.reason INTO v_ok, v_reason FROM pending_claim_confirm((y->>'claim_epupil')::uuid) x;
    PERFORM _assert(v_ok, format('§99 (claims): the office could not confirm the pupil''s claim (%s)', v_reason));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v122_claims(y) = 'eadult:declined,epupil:office_confirmed',
      format('§99 (claims): the owner reads the claims as [%s]', _v122_claims(y)));

    -- (particles)
    PERFORM _as(V_C2);
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL_, '2XI', 'Tour de France', 'du pain, le chat, la mer, da capo, di tutti', now()) RETURNING id INTO v_pc;
    PERFORM _assert(news_public_check(v_pc) = 0,
      format('§99 (particles): a post of the two-letter particles alone named %s, on the word %s',
             news_public_check(v_pc), coalesce(news_public_word(v_pc), '(none)')));
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL_, '2XI', 'Well done', 'Well done Al', now()) RETURNING id INTO v_pc;
    PERFORM _assert(news_public_check(v_pc) = 1 AND news_public_word(v_pc) = 'Al',
      format('§99 (particles): a two-letter first name named %s, on the word %s', news_public_check(v_pc), coalesce(news_public_word(v_pc), '(none)')));
    INSERT INTO news_post (scope, school_id, team_code, title, body, published_at)
    VALUES ('team', HIL_, '2XI', 'Five', 'de Wet took five', now()) RETURNING id INTO v_pc;
    PERFORM _assert(news_public_check(v_pc) = 1,
      format('§99 (particles): a surname that carries a particle named %s', news_public_check(v_pc)));
    PERFORM set_config('app.user_id', '', true);

    -- (sast) Before noon in Johannesburg a session at UTC-12 is a day behind
    -- it, and the lift is later today; after noon a session at UTC+14 is a day
    -- ahead, and the lift is tomorrow.
    v_day := _v122_move((y->>'D')::uuid, '14XI', CASE WHEN v_h < 12 THEN 'Etc/GMT+12' ELSE 'Pacific/Kiritimati' END);
    PERFORM _assert(v_day::date <> sa_today(), format('§99 (sast): the session''s day %s is Johannesburg''s, so this proves nothing', v_day));
    PERFORM _assert(_v122_fact('rows', y) = '13XI:-30..0 14XI:0..',
      format('§99 (sast): D''s sides read %s, not closed and opened on Johannesburg''s day (the session''s was %s)', _v122_fact('rows', y), v_day));
    PERFORM _assert(_v122_fact('seat', y) = CASE WHEN v_h < 12 THEN 'requested' ELSE 'void' END,
      format('§99 (sast): at %s:00 SAST D''s seat on the 13XI lift is %s', v_h, _v122_fact('seat', y)));

    -- (doors)
    PERFORM _assert(has_function_privilege('scrbrd_app', 'passport_consent_in_force(uuid)', 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'scouting_consent_in_force(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'passport_consent_in_force(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'scouting_consent_in_force(uuid)', 'EXECUTE'),
      '§99 (doors): the in-force answers are not the application''s alone');
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'consent_giver_live(uuid,uuid,timestamptz)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'consent_giver_live(uuid,uuid,timestamptz)', 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'news_public_hits(uuid)', 'EXECUTE'),
      '§99 (doors): the giver test or the scan is callable');
    PERFORM _assert((SELECT bool_and(p.prosecdef AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(p.proconfig, '{}')))
                       FROM pg_proc p WHERE p.oid IN ('passport_open(uuid)'::regprocedure, 'scouting_candidates()'::regprocedure,
                                                      'role_requester(uuid)'::regprocedure, 'pending_claims()'::regprocedure,
                                                      'account_sign_ins(uuid)'::regprocedure,
                                                      'pending_claim_confirm(uuid)'::regprocedure,
                                                      'pending_claim_decline(uuid)'::regprocedure,
                                                      'login_code_issue(text,text,integer)'::regprocedure,
                                                      'player_team_membership_log()'::regprocedure,
                                                      'player_move_voids_seats()'::regprocedure)),
      '§99 (doors): a replaced definer lost SECURITY DEFINER or its pinned search_path');
    PERFORM _assert(has_function_privilege('scrbrd_app', 'pending_claim_confirm(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'pending_claim_confirm(uuid)', 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'pending_claim_decline(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'pending_claim_decline(uuid)', 'EXECUTE'),
      '§99 (doors): the claim doors are not the application''s alone');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 99
  -- └── db/122 (section 99) ──────────────────────────────────────────

  -- ┌── db/123 (section 100) ─────────────────────────────────────────
  -- ── 100. Notices follow the side (db/123, REACH R-E) ──
  -- REACH §6.5: a notice with a team and no child reaches the side
  -- (side_reach()), a notice about a child his family, a notice to a
  -- recipient him alone. Staged by _v123_stage(); each count is read through
  -- the table and through my_notifications ('table/view').
  --
  -- What each label holds:
  --   (side)       S ("U15A team sheet published") and T ("U15A training
  --                moved") reach ga and gc (U15A parents), A himself and the
  --                U15A coach; not gb (the U13B parent), not B, not the U13B
  --                coach
  --   (child)      K, about A, reaches ga and not gc (same side) nor gb
  --   (recipient)  R, to ga, reaches ga alone: not gc on his side, not the
  --                coach (unchanged, db/57)
  --   (school)     W, a school notice, reaches all three parents and both
  --                boys (unchanged)
  --   (report)     notification_report(S): gb is told no_such_notice, as for
  --                a notice that is not there; ga, who reads it, is told
  --                not_reportable (a fixture notice is the system's)
  --   (ended)      ga's link to A ended by its date (valid_until yesterday,
  --                his assignment still live): S and T no longer reach him
  --   (up)         decision 1: U, a U14A boy on MU's sheet, and gu read SU,
  --                MU's notice; neither reads SO (another U15A fixture) nor T
  --                (U15A's training); gb reads none of SU
  --   (moved)      decision 2: V moved U16B → U17B at t-10. He and gv read OB
  --                (U16B, t-30) and not OA (U16B, after the move); gv does not
  --                read NB (U17B, t-30: before V joined); V does, through his
  --                player role on the U17B (db/112), as db/117 left his new
  --                side's earlier fixtures and posts
  -- After the read-through (29 Oct 2026):
  --   (only-him)   notification_read_side gives a row that db/09's own
  --                notification_read does not to the boy himself alone: of
  --                SU, SO, S, T, OB, OA and NB, upboy gains SU and vboy OB,
  --                and every other reader it admits db/09 already admits.
  --                db/09's qual is read from pg_policy, so a later file that
  --                narrows it turns this red until notification_read_side is
  --                looked at again (db/123's header)
  --   (retraction) as built, not decided: OB taken back after V's move. The
  --                retraction is a new row dated by its own day, the old
  --                side's then, so V and gv do not read "A notice was
  --                withdrawn"; they still read OB's row, marked taken back,
  --                which my_notifications leaves off their list (1/0): the
  --                notice goes from their list without the words
  --
  -- Falsified on 29 Oct 2026 on a database at db/123, each change made as the
  -- owner before this section ran (the section alone, with its staging cut
  -- from this file), each red the first:
  --   DROP POLICY notification_follows_side      → (side) red: gb reads 2/2
  --                                                of U15A's side notices
  --   notification_report() at db/101's body     → (report) red: gb was told
  --                                                not_reportable
  --   notice_follows_side() without its match arm → (up) red: upboy reads
  --                                                0/0 of MU's notice
  --   notice_follows_side() asking today's side   → (moved) red: vboy reads
  --     (sa_today() for sa_date(p_at))             0/0 of OB
  --   db/09's notification_read narrowed to        → (only-him) red: the
  --     leave out notices about a match              U15A coach, a parent and
  --                                                  a pupil gained SU and SO
  --                                                  through the side read
  DECLARE
    y   jsonb := _v123_stage();
    k   text;
    got text;
    r   record;
  BEGIN
    -- (side)
    FOREACH k IN ARRAY ARRAY['ga', 'gc', 'pupil', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['S', 'T']);
      PERFORM _assert(got = '2/2', format('§100 (side): %s reads %s of U15A''s two side notices (2/2)', k, got));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['gb', 'pupilb', 'coachb'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['S', 'T']);
      PERFORM _assert(got = '0/0', format('§100 (side): U13B''s %s reads %s of U15A''s side notices', k, got));
    END LOOP;

    -- (child)
    PERFORM _as((y->>'ga')::uuid);
    got := _v123_reads(y, ARRAY['K']);
    PERFORM _assert(got = '1/1', format('§100 (child): A''s guardian reads %s of the notice about A', got));
    FOREACH k IN ARRAY ARRAY['gc', 'gb'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['K']);
      PERFORM _assert(got = '0/0', format('§100 (child): %s reads %s of the notice about A', k, got));
    END LOOP;

    -- (recipient)
    PERFORM _as((y->>'ga')::uuid);
    got := _v123_reads(y, ARRAY['R']);
    PERFORM _assert(got = '1/1', format('§100 (recipient): ga reads %s of the notice to him', got));
    FOREACH k IN ARRAY ARRAY['gc', 'gb', 'pupil', 'coach'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['R']);
      PERFORM _assert(got = '0/0', format('§100 (recipient): %s reads %s of the notice to ga', k, got));
    END LOOP;

    -- (school)
    FOREACH k IN ARRAY ARRAY['ga', 'gb', 'gc', 'pupil', 'pupilb'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['W']);
      PERFORM _assert(got = '1/1', format('§100 (school): %s reads %s of the school''s notice', k, got));
    END LOOP;

    -- (report)
    PERFORM _as((y->>'gb')::uuid);
    SELECT * INTO r FROM notification_report((y->>'S')::uuid);
    PERFORM _assert(NOT r.ok AND r.reason = 'no_such_notice',
      format('§100 (report): the U13B parent was told %s of U15A''s side notice (no_such_notice)', r.reason));
    PERFORM _as((y->>'ga')::uuid);
    SELECT * INTO r FROM notification_report((y->>'S')::uuid);
    PERFORM _assert(NOT r.ok AND r.reason = 'not_reportable',
      format('§100 (report): the U15A parent was told %s of his side''s fixture notice (not_reportable)', r.reason));

    -- (ended)
    PERFORM _v120_end_link((y->>'ga')::uuid, (y->>'A')::uuid);
    PERFORM _as((y->>'ga')::uuid);
    got := _v123_reads(y, ARRAY['S', 'T']);
    PERFORM _assert(got = '0/0', format('§100 (ended): with his link ended ga reads %s of U15A''s side notices', got));

    -- (up)
    FOREACH k IN ARRAY ARRAY['upboy', 'gu'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['SU']);
      PERFORM _assert(got = '1/1', format('§100 (up): %s reads %s of MU''s notice (1/1)', k, got));
      got := _v123_reads(y, ARRAY['SO', 'T']);
      PERFORM _assert(got = '0/0', format('§100 (up): %s reads %s of the U15A''s other notices', k, got));
    END LOOP;
    PERFORM _as((y->>'gb')::uuid);
    got := _v123_reads(y, ARRAY['SU']);
    PERFORM _assert(got = '0/0', format('§100 (up): the U13B parent reads %s of MU''s notice', got));

    -- (moved)
    FOREACH k IN ARRAY ARRAY['vboy', 'gv'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['OB']);
      PERFORM _assert(got = '1/1', format('§100 (moved): %s reads %s of the U16B''s notice from before the move (1/1)', k, got));
      got := _v123_reads(y, ARRAY['OA']);
      PERFORM _assert(got = '0/0', format('§100 (moved): %s reads %s of the U16B''s notice from after the move', k, got));
    END LOOP;
    PERFORM _as((y->>'gv')::uuid);
    got := _v123_reads(y, ARRAY['NB']);
    PERFORM _assert(got = '0/0', format('§100 (moved): gv reads %s of the U17B''s notice from before V joined', got));
    PERFORM _as((y->>'vboy')::uuid);
    got := _v123_reads(y, ARRAY['NB']);
    PERFORM _assert(got = '1/1', format('§100 (moved): vboy reads %s of his new side''s earlier notice (1/1, his player role)', got));

    -- (only-him)
    got := '';
    FOREACH k IN ARRAY ARRAY['ga', 'gb', 'gc', 'gu', 'gv', 'pupil', 'pupilb', 'coach', 'coachb', 'upboy', 'vboy'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := concat_ws(',', nullif(got, ''), nullif(_v123_only_side_read(y, ARRAY['SU', 'SO', 'S', 'T', 'OB', 'OA', 'NB'], k), ''));
    END LOOP;
    PERFORM _assert(got = 'SU:upboy,OB:vboy',
      format('§100 (only-him): the side read gave rows db/09 does not to [%s], not the two boys alone', got));

    -- (retraction)
    PERFORM set_config('app.user_id', '', true);
    y := y || jsonb_build_object('OBR', _v123_retract(y));
    PERFORM _assert(y->>'OBR' IS NOT NULL, '§100 (retraction): OB was not taken back with words');
    FOREACH k IN ARRAY ARRAY['vboy', 'gv'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v123_reads(y, ARRAY['OB']) || ' ' || _v123_reads(y, ARRAY['OBR']);
      PERFORM _assert(got = '1/0 0/0',
        format('§100 (retraction): as built %s reads %s of OB and its retraction (1/0 0/0: OB''s row, marked taken back and so off his list; the retraction dated by its own day, not his)', k, got));
    END LOOP;
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 100
  -- └── db/123 (section 100) ──────────────────────────────────────────
  -- ┌── db/124 (section 101) ─────────────────────────────────────────
  -- ── 101. The union passport (db/124, Kameel 29 Oct 2026) ──
  -- "CSA Schools/Provincial Union will be able to access a child's full
  -- passport"; "With his guardian's consent, as the receiving school's is";
  -- "Named selectors and the schools cricket manager only, every read
  -- logged", so his family can see who looked. Staged by _v124_stage();
  -- every read and write is the caller's own under row security, or a
  -- definer the application calls.
  --
  -- What each label holds:
  --   (scope)      a union selector is appointed at a union or the federation,
  --                never at a school, for a team, or platform-wide
  --   (without)    with no consent, no union reader opens anything of B and no
  --                read is logged
  --   (not-his)    his guardian cannot name another province's union; B, at
  --                fifteen, cannot name his own (db/122: his guardian decides)
  --   (with)       his mother names his union: its selector opens the passport
  --                (its lines and his name), each read logged (passport, name),
  --                and each lands in his school's access log too
  --   (organiser)  a competition organiser at the union: closed, and reads
  --                neither the consent row nor its in-force answer
  --   (office)     the union's school administrator, whom db/122's named-
  --                school arm would have let in: closed, the same
  --   (another)    another province's union selector: closed, and closed
  --                still on a consent naming his union written past the
  --                insert policy (as the owner)
  --   (federation) CSA Schools' selector: closed on a consent naming the
  --                union; open once his father names CSA Schools
  --   (platform)   a union selector who also holds a platform-wide assignment:
  --                closed (the reader is held at the organisation)
  --   (pad)        the selector on a pad: closed, nothing logged; his mother on
  --                a pad reads no log
  --   (owner)      the owner's key opens it through its own arm, as before,
  --                and no union read is logged for it
  --   (public)     the selector reads nothing of B's player row: the passport
  --                is the whole of it
  --   (family)     his mother, his father and B himself (on his own link) read
  --                who at which union looked, by name, role and union; another
  --                family, the union's people and the owner's key read none;
  --                the family's own passport reads are not logged as a union's
  --   (withdraw)   his mother withdraws the union: its selector is closed; B,
  --                at fifteen, withdraws CSA Schools: its selector is closed
  --   (ended)      named again, then his mother's link ends: the consent has
  --                lapsed and the selector is closed; she reads no log; his
  --                father still does, and reads the consent lapsed
  --   (correct)    the office corrects his mother's end date in place: her
  --                consent counts again (db/122 §1d Q4, unchanged)
  -- db/124 §5 (Kameel, 30 Oct 2026, both as recommended):
  --   (self-age)   a consent E gave himself at fifteen does not count now he
  --                is eighteen; given again at eighteen, it does
  --   (reopen)     R's guardian named his union at school; R left at
  --                seventeen, turned eighteen away (the link ended) and came
  --                back today (db/62 reopened it in place): the old consent
  --                stays lapsed. Given again after his return it counted until
  --                db/125 §5 (1) (Kameel, 30 Oct 2026, seams call 1): he is
  --                nineteen, so his guardian may no longer give it; she clears
  --                the lapsed row and her new one is refused
  --   (birthday)   N2: a consent E2 gives himself on his eighteenth
  --                birthday itself counts; one E3 gave the day before his
  --                does not
  --   (doors)      the application's doors are scrbrd_app's alone; the
  --                internal ones nobody's, passport_open() among them (Q1);
  --                the log no table read reaches
  -- db/124 §6, after the red-team (Kameel, 30 Oct 2026, 11:06, all as
  -- recommended):
  --   (club)       Q4: a club is no school: refused by the test and the
  --                policy, not offered by passport_recipients(); a club
  --                consent already on record opens nothing to the club's
  --                office and reads as not in force; the list is his
  --                family's alone
  --   (other-arm)  Q2: a selector who is also B's coach, or his guardian,
  --                reads as that, and no union read is written
  --   (family)     Q3: the selector's account renamed after his reads, the
  --                family still reads the name he read under
  --   (self-appoint) Q7: the union's principal appoints himself its selector
  --                through the policy, and his read is logged by his name
  --                (E's, on E's own consent at eighteen, since db/125 leaves
  --                R with none)
  --
  -- Falsified, each change made as the owner before this section ran (the
  -- section alone, cut from this file with the setup above it, on 29 Oct
  -- 2026); unchanged it passed, and each change went red at its label:
  --   passport_open() without the named-school arm's union cut → (office):
  --                                             the union's office opened it
  --   passport_union_consent() taking any union → (another): a union not his
  --                                             opened it
  --   passport_union_reader_at() without the platform-wide cut → (platform)
  --   passport() without its log              → (with): the log lost the passport
  --   passport_name() without its log         → (with): the log lost his name
  --   passport_union_consent() without consent_giver_live() → (ended)
  --   passport_union_consent() counting a withdrawn consent → (withdraw)
  --   passport.union.read granted to competitionadmin → (organiser)
  --   passport_consent_union_family_only dropped → (office): its office read
  --                                             the consent row
  --   passport_consent_union_is_his dropped   → (not-his)
  --   passport_consent_in_force() answering a union's office → (office)
  --   passport_union_reads() without the family test → (family): another
  --                                             family read his log
  --   the scope trigger dropped               → (scope)
  --   passport_union_consent() granted to the application → (doors)
  --   the log granted to the application      → (doors)
  -- And §5's two (30 Oct 2026, the section alone, each broken and restored):
  --   consent_giver_live() asking his age today, as db/122 wrote it
  --                                           → (self-age): E's consent at
  --                                             fifteen counted at eighteen
  --   consent_giver_live() without the reopening → (reopen): the old consent
  --                                             came back with the reopened link
  -- And §6's (30 Oct 2026, the section alone, each broken as the owner and
  -- restored; unchanged it passed before and after):
  --   passport_open() granted back to the application → (doors)
  --   passport_open_not_union() granted to the application → (doors)
  --   passport() logging whenever a union consent admits, as before Q2
  --                                           → (other-arm): selcoach and
  --                                             selpar logged as the union
  --   passport_name() the same                → (other-arm)
  --   passport_union_reads() reading the account's name now, not the copy
  --                                           → (family): 0 of 4 by the name
  --                                             he read under
  --   passport_consent_recipient_ok() taking anything but a union → (club)
  --   passport_open_not_union() without the recipient test → (club): the
  --                                             club's office opened it
  --   passport_consent_in_force() without the recipient test → (club)
  --   passport_recipients() without the family test → (club): another
  --                                             family was offered his union
  --   consent_giver_live() with < for <=      → (birthday): E2's consent on
  --                                             his birthday did not count
  --   consent_giver_live() a day early        → (birthday): E3's counted
  --   a RESTRICTIVE policy refusing a self-appointment → (self-appoint)
  -- One did not go red, and cannot alone: passport_union_reader_at()'s own
  -- pad test, because app_can() refuses on a pad first; it stays as a second
  -- lock, as db/57's readers keep theirs.
  DECLARE
    y      jsonb := _v124_stage();
    B      uuid;
    U_     uuid;
    F_     uuid;
    v_pc   uuid;
    v_pf   uuid;
    v_n    int;
    v_n2   int;
    v_ok   boolean;
    got    text;
    k      text;
    OWNER_ uuid := '88888888-0000-0000-0000-000000000022';
  BEGIN
    B := (y->>'B')::uuid; U_ := (y->>'U')::uuid; F_ := (y->>'F')::uuid;

    -- (scope)
    PERFORM set_config('app.user_id', '', true);
    got := _v124_scope(y);
    PERFORM _assert(got = 'school:refused,team:refused,platform:refused,union:ok',
      format('§101 (scope): a union selector''s appointment reads [%s]', got));

    -- (without)
    FOREACH k IN ARRAY ARRAY['sel', 'fsel', 'osel', 'org', 'uoffice'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO v_n FROM passport(B);
      PERFORM _assert(NOT _passport_open(B) AND v_n = 0 AND passport_name(B) IS NULL,
        format('§101 (without): with no consent %s opens B''s passport (%s line(s))', k, v_n));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v124_log(y) = '', format('§101 (without): a read was logged with no consent: [%s]', _v124_log(y)));

    -- (not-his)
    PERFORM _as((y->>'mum')::uuid);
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES (B, (y->>'OU')::uuid);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§101 (not-his): his mother named another province''s union');
    PERFORM _assert(NOT passport_consent_recipient_ok(B, (y->>'OU')::uuid) AND passport_consent_recipient_ok(B, U_)
                    AND passport_consent_recipient_ok(B, F_)
                    AND passport_consent_recipient_ok(B, '22222222-2222-2222-2222-222222222222'::uuid),
      '§101 (not-his): the recipient test is not "his union, CSA Schools and any school"');
    PERFORM _as((y->>'bself')::uuid);
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES (B, U_);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§101 (not-his): B, at fifteen, named his union himself');

    -- (club) Q4: a school, his union or CSA Schools; nothing else.
    PERFORM _assert(NOT passport_consent_recipient_ok(B, (y->>'C')::uuid),
      '§101 (club): the recipient test lets a family name a club');
    PERFORM _as((y->>'mum')::uuid);
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES (B, (y->>'C')::uuid);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§101 (club): his mother named a club for his record');
    SELECT string_agg(CASE r.id WHEN U_ THEN 'U' WHEN F_ THEN 'F' WHEN (y->>'OU')::uuid THEN 'OU' WHEN (y->>'C')::uuid THEN 'C'
                                WHEN '11111111-1111-1111-1111-111111111111'::uuid THEN 'HIL'
                                WHEN '22222222-2222-2222-2222-222222222222'::uuid THEN 'WES' ELSE NULL END, ',' ORDER BY r.kind, r.name),
           bool_and(r.kind = 'school' OR r.id IN (U_, F_))
      INTO got, v_ok FROM passport_recipients(B) r;
    PERFORM _assert(v_ok AND got LIKE '%HIL%' AND got LIKE '%WES%' AND got LIKE '%U%' AND got LIKE '%F%'
                    AND got NOT LIKE '%OU%' AND got NOT LIKE '%C%',
      format('§101 (club): his mother may name [%s]: not every school, his union and CSA Schools alone', got));
    FOREACH k IN ARRAY ARRAY['ofam', 'sel', 'coffice', 'uoffice'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO v_n FROM passport_recipients(B);
      PERFORM _assert(v_n = 0, format('§101 (club): %s, not his family, is offered %s institution(s) for B', k, v_n));
    END LOOP;
    -- A club consent already on record (written past the policy, as the
    -- owner, in his mother's name): it opens nothing, and is not in force.
    PERFORM set_config('app.user_id', '', true);
    v_pf := _v124_consent_as_owner(y, (y->>'C')::uuid);
    PERFORM _as((y->>'coffice')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(NOT _passport_open(B) AND v_n = 0 AND passport_name(B) IS NULL,
      format('§101 (club): on a club consent on record the club''s office opens %s line(s)', v_n));
    PERFORM _as((y->>'mum')::uuid);
    PERFORM _assert(passport_consent_in_force(v_pf) IS FALSE,
      format('§101 (club): his mother reads the club consent in force %s, not false', passport_consent_in_force(v_pf)));
    UPDATE passport_consent SET withdrawn_at = now() WHERE id = v_pf AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, '§101 (club): his mother could not take the club''s name back');

    -- (with)
    PERFORM _as((y->>'mum')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES (B, U_) RETURNING id INTO v_pc;
    PERFORM _assert(passport_consent_in_force(v_pc) IS TRUE, '§101 (with): his mother does not read her consent to his union in force');
    PERFORM _as((y->>'sel')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    got := passport_name(B);
    PERFORM _assert(_passport_open(B) AND v_n > 0 AND got = 'Verify OneTwentyFour Boy',
      format('§101 (with): on his mother''s word the union selector opens %s line(s), name %s', v_n, coalesce(got, '(none)')));
    SELECT count(*) INTO v_n FROM passport(B) WHERE family = 'honour';
    PERFORM _assert(v_n = 1, format('§101 (with): the union selector reads %s honour line(s): not the full passport', v_n));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v124_log(y) = 'sel:name@U,sel:passport@U,sel:passport@U',
      format('§101 (with): the log reads [%s] (two passport reads and one of his name)', _v124_log(y)));
    PERFORM _assert(_v124_access(y) = 3, format('§101 (with): his school''s access log holds %s union read(s), not 3', _v124_access(y)));

    -- (other-arm) Q2: a selector another arm admits reads as that, unlogged.
    FOREACH k IN ARRAY ARRAY['selcoach', 'selpar'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO v_n FROM passport(B);
      got := passport_name(B);
      PERFORM _assert(v_n > 0 AND got IS NOT NULL,
        format('§101 (other-arm): %s, a union selector and B''s %s, opens %s line(s)', k,
               CASE k WHEN 'selcoach' THEN 'coach' ELSE 'guardian' END, v_n));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v124_log(y) = 'sel:name@U,sel:passport@U,sel:passport@U' AND _v124_access(y) = 3,
      format('§101 (other-arm): a coach''s or a parent''s read was logged as the union''s: [%s], %s access row(s)',
             _v124_log(y), _v124_access(y)));

    -- (organiser), (office)
    FOREACH k IN ARRAY ARRAY['org', 'uoffice'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO v_n FROM passport(B);
      SELECT count(*) INTO v_n2 FROM passport_consent WHERE player_id = B;
      PERFORM _assert(NOT _passport_open(B) AND v_n = 0 AND passport_name(B) IS NULL AND v_n2 = 0
                      AND passport_consent_in_force(v_pc) IS NULL,
        format('§101 (%s): %s opens %s line(s), reads %s consent row(s), in force %s',
               CASE k WHEN 'org' THEN 'organiser' ELSE 'office' END, k, v_n, v_n2, passport_consent_in_force(v_pc)));
    END LOOP;

    -- (another)
    PERFORM _as((y->>'osel')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(NOT _passport_open(B) AND v_n = 0 AND passport_name(B) IS NULL,
      format('§101 (another): another province''s union selector opens %s line(s)', v_n));
    -- ...even on a consent naming his own union, written past the insert
    -- policy (as the owner, in his mother's name): the read asks it too.
    PERFORM set_config('app.user_id', '', true);
    v_pf := _v124_far_consent(y);
    PERFORM _as((y->>'osel')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(NOT _passport_open(B) AND v_n = 0,
      format('§101 (another): on a consent naming a union not his, its selector opens %s line(s)', v_n));
    PERFORM _as((y->>'mum')::uuid);
    UPDATE passport_consent SET withdrawn_at = now() WHERE id = v_pf AND withdrawn_at IS NULL;

    -- (federation)
    PERFORM _as((y->>'fsel')::uuid);
    PERFORM _assert(NOT _passport_open(B), '§101 (federation): CSA Schools'' selector opens a passport named for the union');
    PERFORM _as((y->>'dad')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES (B, F_) RETURNING id INTO v_pf;
    PERFORM _as((y->>'fsel')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(_passport_open(B) AND v_n > 0,
      format('§101 (federation): on his father''s word CSA Schools'' selector opens %s line(s)', v_n));
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(_passport_open(B), '§101 (federation): his union''s selector lost the passport when CSA Schools was named');

    -- (platform)
    PERFORM _as((y->>'sel2')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(NOT _passport_open(B) AND v_n = 0,
      format('§101 (platform): a union selector holding a platform-wide assignment opens %s line(s)', v_n));

    -- (pad)
    PERFORM set_config('app.user_id', '', true);
    v_n2 := length(_v124_log(y));
    PERFORM _as((y->>'sel')::uuid);
    PERFORM set_config('app.scope', 'pad', true);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(NOT _passport_open(B) AND v_n = 0 AND passport_name(B) IS NULL,
      format('§101 (pad): the selector on a pad opens %s line(s)', v_n));
    PERFORM _as((y->>'mum')::uuid);
    SELECT count(*) INTO v_n FROM passport_union_reads();
    PERFORM _assert(v_n = 0, format('§101 (pad): his mother on a pad reads %s union read(s)', v_n));
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(length(_v124_log(y)) = v_n2, '§101 (pad): a read on a pad was logged');

    -- (owner)
    PERFORM _as(OWNER_);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(_passport_open(B) AND v_n > 0, format('§101 (owner): the owner''s key opens %s line(s) (its own arm, as before)', v_n));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(length(_v124_log(y)) = v_n2, format('§101 (owner): the owner''s read was logged as a union''s: [%s]', _v124_log(y)));

    -- (public)
    PERFORM _as((y->>'sel')::uuid);
    SELECT count(*) INTO v_n FROM player WHERE id = B;
    SELECT count(*) INTO v_n2 FROM player_masked WHERE id = B;
    PERFORM _assert(v_n = 0 AND v_n2 = 0, format('§101 (public): the union selector reads %s/%s of B''s player row', v_n, v_n2));

    -- (family)
    PERFORM set_config('app.user_id', '', true);
    -- Q3: his account is renamed (anonymised) after his reads; the family
    -- still reads the name he read under, which the log copied.
    PERFORM _v124_rename((y->>'sel')::uuid, 'Anonymised Account');
    v_n2 := length(_v124_log(y));
    PERFORM _as((y->>'mum')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(v_n > 0 AND passport_name(B) IS NOT NULL, '§101 (family): his mother does not open his passport');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(length(_v124_log(y)) = v_n2, '§101 (family): the family''s own read was logged as a union''s');
    FOREACH k IN ARRAY ARRAY['mum', 'dad', 'bself'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*),
             count(*) FILTER (WHERE r.reader_name = 'V124 Sel' AND r.reader_role = 'Union Selector'
                                AND r.organisation = (SELECT s.name FROM public_schools() s WHERE s.id = U_)),
             string_agg(DISTINCT r.what, ',' ORDER BY r.what)
        INTO v_n, v_n2, got
        FROM passport_union_reads() r WHERE r.player_id = B;
      -- sel: the passport twice and his name (with); asked once more after
      -- CSA Schools was named (federation), through passport_open() as the
      -- owner, which no route can ask since §6 Q1, so not logged; fsel: the
      -- passport once (federation). selcoach and selpar read as B's coach and
      -- guardian (Q2), so not logged either.
      PERFORM _assert(v_n = 4 AND v_n2 = 3 AND got = 'name,passport',
        format('§101 (family): %s reads %s union read(s), %s by the union''s selector by the name he read under (V124 Sel, since renamed) and union, of [%s]', k, v_n, v_n2, got));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['ofam', 'sel', 'fsel', 'org', 'uoffice'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO v_n FROM passport_union_reads();
      PERFORM _assert(v_n = 0, format('§101 (family): %s reads %s union read(s) of a boy not his', k, v_n));
    END LOOP;
    PERFORM _as(OWNER_);
    SELECT count(*) INTO v_n FROM passport_union_reads();
    PERFORM _assert(v_n = 0, format('§101 (family): the owner''s key reads %s union read(s)', v_n));

    -- (withdraw)
    PERFORM _as((y->>'mum')::uuid);
    UPDATE passport_consent SET withdrawn_at = now() WHERE id = v_pc AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, '§101 (withdraw): his mother could not withdraw the union');
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(NOT _passport_open(B) AND passport_name(B) IS NULL, '§101 (withdraw): the union''s selector opens it after the withdrawal');
    PERFORM _as((y->>'bself')::uuid);
    UPDATE passport_consent SET withdrawn_at = now() WHERE id = v_pf AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, '§101 (withdraw): B, at fifteen, could not take CSA Schools'' name back');
    PERFORM _as((y->>'fsel')::uuid);
    PERFORM _assert(NOT _passport_open(B), '§101 (withdraw): CSA Schools'' selector opens it after B withdrew');

    -- (ended)
    PERFORM _as((y->>'mum')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES (B, U_) RETURNING id INTO v_pc;
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(_passport_open(B), '§101 (ended): named again, the union''s selector does not open it');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v119_end_link((y->>'mum')::uuid, B);
    PERFORM _as((y->>'sel')::uuid);
    SELECT count(*) INTO v_n FROM passport(B);
    PERFORM _assert(NOT _passport_open(B) AND v_n = 0 AND passport_name(B) IS NULL,
      format('§101 (ended): with his mother''s link ended the union''s selector opens %s line(s)', v_n));
    PERFORM _as((y->>'mum')::uuid);
    SELECT count(*) INTO v_n FROM passport_union_reads();
    PERFORM _assert(v_n = 0, format('§101 (ended): his mother, her link ended, reads %s union read(s)', v_n));
    PERFORM _as((y->>'dad')::uuid);
    SELECT count(*) INTO v_n FROM passport_union_reads() WHERE player_id = B;
    PERFORM _assert(v_n = 4, format('§101 (ended): his father reads %s union read(s), not 4', v_n));
    PERFORM _assert(passport_consent_in_force(v_pc) IS FALSE, '§101 (ended): his father does not read the lapsed consent as lapsed');

    -- (correct) the office corrects his mother's end date in place: the same
    -- link, so her consent counts again (db/122 §1d Q4, unchanged).
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v124_correct((y->>'mum')::uuid, B);
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(_passport_open(B), '§101 (correct): with his mother''s end corrected in place, the selector does not open it');
    PERFORM _as((y->>'dad')::uuid);
    PERFORM _assert(passport_consent_in_force(v_pc) IS TRUE, '§101 (correct): his father reads the revived consent as lapsed');

    -- (self-age) and (reopen): db/124 §5 (Kameel, 30 Oct 2026).
    PERFORM set_config('app.user_id', '', true);
    y := y || _v124_stage5(y);
    -- (self-age) E, eighteen today, named his union himself at fifteen.
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(NOT _passport_open((y->>'E')::uuid),
      '§101 (self-age): the consent E gave himself at fifteen counts now he is eighteen');
    PERFORM _as((y->>'eself')::uuid);
    PERFORM _assert(passport_consent_in_force((y->>'pc_e')::uuid) IS FALSE,
      format('§101 (self-age): E reads his fifteen-year-old''s consent in force %s, not lapsed', passport_consent_in_force((y->>'pc_e')::uuid)));
    -- Given again today, at eighteen, as the grant route does: it counts.
    UPDATE passport_consent SET withdrawn_at = now()
     WHERE player_id = (y->>'E')::uuid AND to_school_id = U_ AND withdrawn_at IS NULL AND passport_consent_in_force(id) = false;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§101 (self-age): E cleared %s lapsed row(s), not 1', v_n));
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'E')::uuid, U_);
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(_passport_open((y->>'E')::uuid), '§101 (self-age): E''s own consent at eighteen does not open his passport to his union');
    -- (birthday) N2: on his eighteenth birthday itself his word counts; the
    -- day before, it does not.
    PERFORM _as((y->>'e2self')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'E2')::uuid, U_) RETURNING id INTO v_pc;
    PERFORM _assert(passport_consent_in_force(v_pc) IS TRUE,
      format('§101 (birthday): E2, eighteen today, reads his own consent given today in force %s', passport_consent_in_force(v_pc)));
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(_passport_open((y->>'E2')::uuid), '§101 (birthday): E2''s own consent on his eighteenth birthday does not open it');
    PERFORM _assert(NOT _passport_open((y->>'E3')::uuid), '§101 (birthday): E3''s own consent the day before his eighteenth birthday opens it');
    PERFORM _as((y->>'e3self')::uuid);
    PERFORM _assert(passport_consent_in_force((y->>'pc_e3')::uuid) IS FALSE,
      format('§101 (birthday): E3 reads his consent of the day before his birthday in force %s', passport_consent_in_force((y->>'pc_e3')::uuid)));
    PERFORM _as((y->>'sel')::uuid);
    -- (reopen) R's guardian named his union two years ago, at school.
    PERFORM _assert(_passport_open((y->>'R')::uuid), '§101 (reopen): before he left, the selector does not open R''s passport');
    PERFORM set_config('app.user_id', '', true);
    got := _v124_away(y);
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(NOT _passport_open((y->>'R')::uuid),
      format('§101 (reopen): his link ended away (ends %s days from today), and the selector still opens it', got));
    PERFORM set_config('app.user_id', '', true);
    got := _v124_back(y);
    PERFORM _assert(got = 'open', format('§101 (reopen): db/62 did not reopen R''s link in place on his return (%s)', got));
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(NOT _passport_open((y->>'R')::uuid),
      '§101 (reopen): the link reopened on his return brought back a consent given before it ended');
    PERFORM _as((y->>'rg')::uuid);
    PERFORM _assert(passport_consent_in_force((y->>'pc_r')::uuid) IS FALSE,
      format('§101 (reopen): his guardian reads the old consent in force %s, not lapsed', passport_consent_in_force((y->>'pc_r')::uuid)));
    -- Given again on the reopened link, as the grant route does: it counts.
    UPDATE passport_consent SET withdrawn_at = now()
     WHERE player_id = (y->>'R')::uuid AND to_school_id = U_ AND withdrawn_at IS NULL AND passport_consent_in_force(id) = false;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§101 (reopen): his guardian cleared %s lapsed row(s), not 1', v_n));
    -- db/125 §5 (1): he is nineteen, so his guardian names nothing for him now.
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'R')::uuid, U_);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§101 (reopen): his guardian named his union for him at nineteen (db/125 §5 (1))');
    PERFORM _as((y->>'sel')::uuid);
    PERFORM _assert(NOT _passport_open((y->>'R')::uuid), '§101 (reopen): the selector opens R''s passport with no consent of his own');

    -- (self-appoint) Q7: the union's principal appoints himself its selector,
    -- through the write policy, and what he then reads is logged by his name.
    -- E, whose own consent at eighteen names the union (self-age), is read;
    -- the read is his name (passport_name()), which opens and logs exactly as
    -- passport() does. (It was R until db/125 §5 (1) left R with no consent.)
    PERFORM _as((y->>'uhead')::uuid);
    PERFORM _assert(passport_name((y->>'E')::uuid) IS NULL AND NOT _passport_open((y->>'E')::uuid),
      '§101 (self-appoint): the union''s principal opens E''s passport before he is its selector');
    BEGIN
      INSERT INTO role_assignment (person_id, role, school_id) VALUES ((y->>'uhead')::uuid, 'unionselector', U_);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege OR check_violation THEN v_ok := false;
    END;
    PERFORM _assert(v_ok, '§101 (self-appoint): the union''s principal could not appoint himself its selector');
    k := passport_name((y->>'E')::uuid);
    PERFORM set_config('app.user_id', '', true);
    got := _v124_reads_of((y->>'E')::uuid);
    PERFORM _assert(k = 'Verify OneTwentyFour Elder' AND got = 'V124 Uhead (Union Selector):name',
      format('§101 (self-appoint): he reads E''s name as [%s], and E''s log reads [%s]', coalesce(k, '(none)'), got));
    PERFORM _as((y->>'eself')::uuid);
    SELECT count(*) INTO v_n FROM passport_union_reads() r WHERE r.player_id = (y->>'E')::uuid AND r.reader_name = 'V124 Uhead';
    PERFORM _assert(v_n = 1, format('§101 (self-appoint): E reads %s line(s) naming the principal', v_n));

    -- (doors)
    PERFORM _assert(has_function_privilege('scrbrd_app', 'passport_union_reads()', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'passport_union_reads()', 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'passport_consent_recipient_ok(uuid,uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'passport_consent_recipient_ok(uuid,uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'passport(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'passport_open(uuid)', 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'passport_recipients(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'passport_recipients(uuid)', 'EXECUTE'),
      '§101 (doors): an application door is PUBLIC''s, or not the application''s');
    -- Q1: passport_open() answers the application nothing; it is no door.
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'passport_open(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'passport_open_not_union(uuid)', 'EXECUTE'),
      '§101 (doors): passport_open() or passport_open_not_union() is the application''s to call');
    PERFORM _as((y->>'sel')::uuid);
    BEGIN
      v_ok := passport_open((y->>'R')::uuid);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§101 (doors): the application asked passport_open() a union selector''s yes or no');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(NOT has_function_privilege('scrbrd_app', 'passport_union_consent(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'passport_union_reader_at(uuid)', 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'passport_union_log(uuid,uuid,text)', 'EXECUTE'),
      '§101 (doors): an internal union function is the application''s to call');
    BEGIN
      PERFORM 1 FROM passport_union_read LIMIT 1;
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§101 (doors): the application reads the union read log directly');
  END;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.scope', '', true);
  -- └── end of section 101
  -- └── db/124 (section 101) ──────────────────────────────────────────
  -- ┌── db/125 (section 102) ─────────────────────────────────────────
  -- ── 102. The union selector's list (db/125, Kameel 30 Oct 2026) ──
  -- docs/design/UNION_SELECTOR_FIND.md, slice S1: a selector lists only the
  -- boys whose consent to his institution is in force at the moment he asks,
  -- by school or age group, each row his name, school and side; every row
  -- shown is a logged read his family sees. Kameel's six answers (30 Oct
  -- 2026, 21:05 SAST, all as recommended). Staged by _v125_stage(); every
  -- call is the caller's own, as the application makes it.
  --
  -- What each label holds:
  --   (orgs)     the institutions each caller reads at: his union, CSA
  --              Schools, or both; nothing for an organiser, a platform-wide
  --              caller, a support session or a pad
  --   (schools)  the schools a selector may filter by: his union's, or every
  --              school for CSA Schools; none at an institution he does not
  --              read at
  --   (f)        a call with neither school nor age group is refused
  --              (choose_a_school_or_age_group), a name alone too, and an age
  --              group not of the form U15; a refusal logs nothing
  --   (a)        the selector at the union lists only the boys whose in-force
  --              consent names it, in order (school, surname); the count
  --              equals a direct count over passport_consent with db/124's test
  --   (g)        each row returned writes exactly one 'list' row, his name and
  --              role copied in, under the consent the row names, and one
  --              access_log row per school with every boy's id
  --   (name)     Q6: a name fragment narrows within the consented set; a boy
  --              consented elsewhere, unconsented, or nobody reads the same
  --   (coach)    Q2: a selector who is also a boy's coach, or his guardian,
  --              is logged for every row as a union read
  --   (d)        a consent naming CSA Schools appears to its selector and not
  --              to the province's, and the reverse; another province's
  --              school's boy never appears to the province, not even on a
  --              consent naming it written past the insert policy
  --   (e)        a platform-wide caller, a support session, a pad and a
  --              competition organiser each get an empty list and no log row
  --   (dual)     D4: a selector at both, asking for both, sees one row per
  --              boy, under the consent the passport would log under
  --   (h)        passport_union_reads() returns the 'list' rows to his
  --              guardian and to the boy on his own link, and nothing to a
  --              stranger
  --   (b)        a withdrawn consent drops the row in the same transaction
  --   (c)        a giver's link ended yesterday drops it
  --   (i)        the row is the six columns; the bodies read no born, no
  --              player_innings, no honour, no style, no passport_name()
  --   (j)        the three are definers with the pinned path, the writer is
  --              not; nobody but scrbrd_app executes the three, nobody the
  --              writer
  --   (k)        Q3: consent_giver_live() asks sa_today() in its four link
  --              tests and current_date nowhere; nor does the list's record
  -- The seams audit's calls 1, 2 and 4 (Kameel, 30 Oct 2026, 21:53 SAST, as
  -- recommended), folded into db/125:
  --   (of-age)   call 1: G is eighteen and at school. His guardian's scouting
  --              yes is refused (he_is_of_age) and her no recorded; her
  --              naming his union is refused; a consent she gave before his
  --              birthday stands (the selector lists him; in force), one in
  --              her name dated after it does not (CSA Schools' selector does
  --              not list him; not in force); her withdrawal still counts
  --   (scout-log) call 2: the accredited scout's read of the candidates
  --              writes one access_log row per school, naming that school's
  --              boys (resource scouting_candidates, field full_name)
  --   (processing) call 4: PD's guardian withdraws processing consent on her
  --              link: his union's and CSA Schools' selectors no longer list
  --              him, the scout no longer sees him, and her passport and
  --              scouting consents read not in force
  --
  -- Falsified (30 Oct 2026, the section alone, each change made as the owner
  -- and restored; unchanged it passed before and after):
  --   passport_union_list() without the log call  → (g)
  --   passport_union_list() without consent_giver_live() → (c)
  --   passport_union_list() counting a withdrawn consent → (b)
  --   passport_union_list() without passport_union_reader_at() → (d): fails
  --                                             closed, CSA Schools' selector's
  --                                             list at the union finding no
  --                                             role to log (reader_role NOT NULL)
  --   passport_union_list() taking any union, not his school's → (d)
  --   passport_union_list() without the filter refusal → (f)
  --   passport_union_log_list() granted to the application → (j)
  --   consent_giver_live() back on current_date   → (k)
  --   passport_consent_writer_ok() without the guardian's age → (of-age)
  --   scouting_consent_set() without the guardian's age → (of-age)
  --   consent_giver_live() without the guardian's age → (of-age)
  --   scouting_candidates() without its log        → (scout-log)
  --   consent_giver_live() without processing consent → (processing)
  DECLARE
    y      jsonb := _v125_stage();
    U_     uuid;
    F_     uuid;
    SA_    uuid;
    SB_    uuid;
    FAR_   uuid;
    v_pc   uuid;
    v_pf   uuid;
    v_n    int;
    v_n2   int;
    v_ok   boolean;
    v_cids uuid[];
    got    text;
    v_t    text;
    k      text;
  BEGIN
    U_ := (y->>'U')::uuid; F_ := (y->>'F')::uuid; SA_ := (y->>'SA')::uuid; SB_ := (y->>'SB')::uuid; FAR_ := (y->>'FAR')::uuid;

    -- Each family names the institution, through the write policy.
    PERFORM _as((y->>'ga')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PA')::uuid, U_);
    PERFORM _as((y->>'gd')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PD')::uuid, U_);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PD')::uuid, F_) RETURNING id INTO v_pc;
    PERFORM _as((y->>'ga2')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PA2')::uuid, F_);
    PERFORM _as((y->>'gb')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PB')::uuid, U_);
    PERFORM _as((y->>'gc')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PC')::uuid, U_);
    PERFORM _as((y->>'gx')::uuid);
    INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'PX')::uuid, F_);
    -- PD's CSA Schools consent is the later of his two (D4).
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v125_later(v_pc);

    -- (orgs)
    FOREACH k IN ARRAY ARRAY['sel', 'fsel', 'both', 'org', 'plat', 'sup', 'gn'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v125_orgs(y);
      PERFORM _assert(got = CASE k WHEN 'sel' THEN 'U' WHEN 'fsel' THEN 'F' WHEN 'both' THEN 'U,F' ELSE '' END,
        format('§102 (orgs): %s reads as a union at [%s]', k, got));
    END LOOP;
    PERFORM _as((y->>'sel')::uuid);
    PERFORM set_config('app.scope', 'pad', true);
    got := _v125_orgs(y);
    PERFORM set_config('app.scope', '', true);
    PERFORM _assert(got = '', format('§102 (orgs): the selector on a pad reads as a union at [%s]', got));

    -- (schools)
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_schools(y, U_);
    PERFORM _assert(got = 'HIL,SA,SB,WES', format('§102 (schools): the union''s selector may filter by [%s], not its four', got));
    got := _v125_schools(y, F_);
    PERFORM _assert(got = '', format('§102 (schools): the union''s selector is offered CSA Schools'' schools [%s]', got));
    PERFORM _as((y->>'fsel')::uuid);
    got := _v125_schools(y, F_);
    PERFORM _assert(got = 'HIL,SA,SB,FAR,WES', format('§102 (schools): CSA Schools'' selector may filter by [%s], not every school', got));
    PERFORM _as((y->>'org')::uuid);
    got := _v125_schools(y, U_);
    PERFORM _assert(got = '', format('§102 (schools): the union''s organiser is offered [%s]', got));

    -- (f)
    PERFORM set_config('app.user_id', '', true);
    v_t := _v125_total();
    PERFORM _as((y->>'sel')::uuid);
    FOREACH k IN ARRAY ARRAY['none', 'name-only', 'blank', 'not-a-band'] LOOP
      BEGIN
        got := CASE k WHEN 'none'       THEN _v125_list(y, U_, NULL, NULL)
                      WHEN 'name-only'  THEN _v125_list(y, U_, NULL, NULL, 'Kilo')
                      WHEN 'blank'      THEN _v125_list(y, U_, NULL, '  ', NULL)
                      ELSE                   _v125_list(y, U_, NULL, '15', NULL) END;
        v_ok := true;
      EXCEPTION WHEN invalid_parameter_value THEN
        GET STACKED DIAGNOSTICS got = MESSAGE_TEXT;
        v_ok := false;
      END;
      PERFORM _assert(NOT v_ok AND got = 'choose_a_school_or_age_group',
        format('§102 (f): a call with %s was answered, or refused as [%s]', k, got));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v125_total() = v_t, format('§102 (f): a refused call logged (%s, was %s)', _v125_total(), v_t));

    -- (a) and (g): the selector's first list, at SA.
    PERFORM _as((y->>'sel')::uuid);
    SELECT coalesce(string_agg(_v125_key(y, l.player_id) || '@' || _v125_key(y, l.org_id)
                               || '|' || l.name || '|' || l.school_name || '|' || l.team_code, ',' ORDER BY l.n), ''),
           array_agg(l.consent_id ORDER BY l.consent_id)
      INTO got, v_cids
      FROM passport_union_list(U_, SA_, NULL, NULL) WITH ORDINALITY AS l(player_id, name, school_name, team_code, org_id, consent_id, n);
    PERFORM _assert(got = 'PD@U|Verify OneTwentyFive Echo|Verify OneTwentyFive Alpha School|U15A,'
                       || 'PA@U|Verify OneTwentyFive Kilo|Verify OneTwentyFive Alpha School|U15A',
      format('§102 (a): the union''s selector lists SA as [%s]', got));
    v_n := _v125_direct((y->>'sel')::uuid, U_, SA_, NULL);
    PERFORM _assert(v_n = 2, format('§102 (a): the direct count over passport_consent at SA is %s, not the list''s 2', v_n));
    PERFORM set_config('app.user_id', '', true);
    got := _v125_reads(y, (y->>'sel')::uuid);
    PERFORM _assert(got = 'PA@U,PD@U', format('§102 (g): the selector''s list of two wrote [%s]', got));
    got := _v125_who((y->>'sel')::uuid);
    PERFORM _assert(got = 'V125 Sel (Union Selector)', format('§102 (g): the list rows name the reader as [%s]', got));
    PERFORM _assert(_v125_consents((y->>'sel')::uuid) = v_cids,
      '§102 (g): the list rows are not under the consents the list named');
    got := _v125_access(y, (y->>'sel')::uuid);
    PERFORM _assert(got = 'SA:PA+PD', format('§102 (g): SA''s access log reads [%s], not one row with both boys', got));
    -- By age group, across two schools: one log row a boy, one access row a
    -- school; the count is the direct count.
    v_t := _v125_total();
    PERFORM _as((y->>'sel')::uuid);
    SELECT count(*), count(DISTINCT l.school_name),
           coalesce(string_agg(_v125_key(y, l.player_id), ',' ORDER BY l.n) FILTER (WHERE _v125_key(y, l.player_id) <> '?'), '')
      INTO v_n, v_n2, got
      FROM passport_union_list(U_, NULL, 'u15', NULL) WITH ORDINALITY AS l(player_id, name, school_name, team_code, org_id, consent_id, n);
    PERFORM _assert(got = 'PD,PA,PB', format('§102 (a): the union''s selector lists U15 as [%s] of this section''s boys', got));
    PERFORM _assert(v_n = _v125_direct((y->>'sel')::uuid, U_, NULL, 'U15'),
      format('§102 (a): the U15 list holds %s row(s), the direct count %s', v_n, _v125_direct((y->>'sel')::uuid, U_, NULL, 'U15')));
    PERFORM set_config('app.user_id', '', true);
    got := _v125_total();
    PERFORM _assert(got = (split_part(v_t, '/', 1)::int + v_n)::text || '/' || (split_part(v_t, '/', 2)::int + v_n2)::text,
      format('§102 (g): a list of %s boy(s) at %s school(s) took the log from %s to %s', v_n, v_n2, v_t, got));
    PERFORM _assert(_v125_access(y, (y->>'sel')::uuid) LIKE '%SB:PB%',
      format('§102 (g): SB''s access log does not hold PB''s list row [%s]', _v125_access(y, (y->>'sel')::uuid)));

    -- (name) Q6
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SA_, NULL, ' KILO ');
    PERFORM _assert(got = 'PA@U', format('§102 (name): "kilo" at SA lists [%s]', got));
    got := _v125_list(y, U_, NULL, 'U15', 'oscar');
    PERFORM _assert(got = 'PB@U', format('§102 (name): "oscar" in U15 lists [%s]', got));
    FOREACH k IN ARRAY ARRAY['Lima', 'Mike', 'Nobody', '%', '_'] LOOP
      got := _v125_list(y, U_, SA_, NULL, k);
      PERFORM _assert(got = '', format('§102 (name): "%s" at SA lists [%s]: a miss must read as nobody', k, got));
    END LOOP;

    -- (coach) Q2
    FOREACH k IN ARRAY ARRAY['selcoach', 'selpar'] LOOP
      PERFORM _as((y->>k)::uuid);
      got := _v125_list(y, U_, SA_, NULL);
      PERFORM _assert(got = 'PD@U,PA@U', format('§102 (coach): %s lists SA as [%s]', k, got));
      PERFORM set_config('app.user_id', '', true);
      got := _v125_reads(y, (y->>k)::uuid) || ' ' || _v125_who((y->>k)::uuid);
      PERFORM _assert(got = 'PA@U,PD@U ' || upper('v125') || ' ' || initcap(k) || ' (Union Selector)',
        format('§102 (coach): %s, also PA''s %s, was logged as [%s]', k, CASE k WHEN 'selcoach' THEN 'coach' ELSE 'guardian' END, got));
    END LOOP;

    -- (d)
    PERFORM _as((y->>'fsel')::uuid);
    got := _v125_list(y, F_, SA_, NULL);
    PERFORM _assert(got = 'PD@F,PA2@F', format('§102 (d): CSA Schools'' selector lists SA as [%s]', got));
    got := _v125_list(y, F_, FAR_, NULL);
    PERFORM _assert(got = 'PX@F', format('§102 (d): CSA Schools'' selector lists the far school as [%s]', got));
    got := _v125_list(y, U_, SA_, NULL);
    PERFORM _assert(got = '', format('§102 (d): CSA Schools'' selector lists the union''s consents [%s]', got));
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SA_, 'U15');
    PERFORM _assert(got = 'PD@U,PA@U', format('§102 (d): the union''s selector lists SA''s U15 as [%s] (PA2 named CSA Schools only)', got));
    got := _v125_list(y, U_, FAR_, NULL) || '|' || _v125_list(y, F_, SA_, NULL);
    PERFORM _assert(got = '|', format('§102 (d): the union''s selector lists another province''s school, or CSA Schools'', as [%s]', got));
    -- ...even on a consent naming his union for a boy whose union it is not,
    -- written past the insert policy (as the owner, in his guardian's name).
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v125_far_consent(y);
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, FAR_, NULL) || '|' || _v125_list(y, U_, NULL, 'U15', 'xray');
    PERFORM _assert(got = '|', format('§102 (d): on a consent naming a union not his, its selector lists [%s]', got));

    -- (e)
    PERFORM set_config('app.user_id', '', true);
    v_t := _v125_total();
    FOREACH k IN ARRAY ARRAY['plat', 'sup', 'org', 'pad'] LOOP
      PERFORM _as((y->>CASE k WHEN 'pad' THEN 'sel' ELSE k END)::uuid);
      IF k = 'pad' THEN PERFORM set_config('app.scope', 'pad', true); END IF;
      got := _v125_list(y, U_, SA_, NULL) || '|' || _v125_list(y, NULL, NULL, 'U15');
      PERFORM set_config('app.scope', '', true);
      PERFORM _assert(got = '|', format('§102 (e): %s lists [%s]', k, got));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v125_total() = v_t, format('§102 (e): an empty list logged (%s, was %s)', _v125_total(), v_t));

    -- (dual) D4: one row a boy, under the consent the passport would log under.
    PERFORM _as((y->>'both')::uuid);
    got := _v125_list(y, NULL, SA_, NULL);
    PERFORM _assert(got = 'PD@U,PA@U,PA2@F', format('§102 (dual): the selector at both lists SA as [%s]', got));
    SELECT l.consent_id INTO v_pc FROM passport_union_list(NULL, SA_, NULL, 'echo') l;
    PERFORM _assert(v_pc = _v125_union_consent((y->>'PD')::uuid),
      '§102 (dual): PD''s row is not under the consent his passport would log under');
    got := _v125_list(y, F_, SA_, NULL);
    PERFORM _assert(got = 'PD@F,PA2@F', format('§102 (dual): the selector at both, asking CSA Schools, lists SA as [%s]', got));

    -- (h)
    PERFORM set_config('app.user_id', '', true);
    v_n2 := _v125_rows_of((y->>'PA')::uuid);
    FOREACH k IN ARRAY ARRAY['ga', 'paself'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*), count(*) FILTER (WHERE r.reader_name = 'V125 Sel' AND r.reader_role = 'Union Selector'
                                          AND r.organisation = y->>'Uname')
        INTO v_n, v_n2
        FROM passport_union_reads() r WHERE r.player_id = (y->>'PA')::uuid AND r.what = 'list';
      PERFORM _assert(v_n = _v125_rows_of((y->>'PA')::uuid) AND v_n > 0 AND v_n2 = 4,
        format('§102 (h): %s reads %s of PA''s %s list row(s), %s by the union''s selector by name, role and union (4)',
               k, v_n, _v125_rows_of((y->>'PA')::uuid), v_n2));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['gn', 'gd', 'sel', 'org'] LOOP
      PERFORM _as((y->>k)::uuid);
      SELECT count(*) INTO v_n FROM passport_union_reads() r WHERE r.player_id = (y->>'PA')::uuid;
      PERFORM _assert(v_n = 0, format('§102 (h): %s, not PA''s family, reads %s of his union read(s)', k, v_n));
    END LOOP;

    -- (b)
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SB_, NULL);
    PERFORM _assert(got = 'PB@U,PC@U', format('§102 (b): before the withdrawal the selector lists SB as [%s]', got));
    PERFORM _as((y->>'gb')::uuid);
    UPDATE passport_consent SET withdrawn_at = now() WHERE player_id = (y->>'PB')::uuid AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, format('§102 (b): PB''s guardian withdrew %s consent(s), not 1', v_n));
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SB_, NULL);
    PERFORM _assert(got = 'PC@U', format('§102 (b): after the withdrawal the selector lists SB as [%s]', got));

    -- (c)
    PERFORM set_config('app.user_id', '', true);
    PERFORM _v125_ended_yesterday((y->>'gc')::uuid, (y->>'PC')::uuid);
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SB_, NULL) || '|' || _v125_list(y, U_, NULL, 'U16', 'papa');
    PERFORM _assert(got = '|', format('§102 (c): with his guardian''s link ended yesterday the selector lists [%s]', got));

    -- (of-age) call 1: G turned eighteen a month ago and is at school; gg's
    -- link is open.
    PERFORM _as((y->>'gg')::uuid);
    SELECT s.ok, s.reason INTO v_ok, got FROM scouting_consent_set((y->>'G')::uuid, true) s;
    PERFORM _assert(NOT v_ok AND got = 'he_is_of_age',
      format('§102 (of-age): his guardian''s scouting yes at eighteen was answered %s/%s', v_ok, coalesce(got, '-')));
    SELECT s.ok, s.reason INTO v_ok, got FROM scouting_consent_set((y->>'G')::uuid, false) s;
    PERFORM _assert(v_ok, format('§102 (of-age): his guardian''s no at eighteen was refused (%s)', got));
    BEGIN
      INSERT INTO passport_consent (player_id, to_school_id) VALUES ((y->>'G')::uuid, U_);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§102 (of-age): his guardian named his union for him at eighteen');
    -- One she gave two months ago, before his birthday, stands; one in her
    -- name today (written past the policy, as the owner) does not.
    PERFORM set_config('app.user_id', '', true);
    v_pc := _v125_consent_as((y->>'gg')::uuid, (y->>'G')::uuid, U_, now() - interval '2 months');
    v_pf := _v125_consent_as((y->>'gg')::uuid, (y->>'G')::uuid, F_, now());
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, (y->>'HIL')::uuid, NULL, 'onetwentyfive golf');
    PERFORM _assert(got = 'G@U', format('§102 (of-age): on her word given before his birthday the selector lists [%s]', got));
    PERFORM _as((y->>'fsel')::uuid);
    got := _v125_list(y, F_, (y->>'HIL')::uuid, NULL, 'onetwentyfive golf');
    PERFORM _assert(got = '', format('§102 (of-age): on her word given at eighteen CSA Schools'' selector lists [%s]', got));
    PERFORM _as((y->>'gg')::uuid);
    PERFORM _assert(passport_consent_in_force(v_pc) IS TRUE AND passport_consent_in_force(v_pf) IS FALSE,
      format('§102 (of-age): she reads her consents in force %s (before his birthday) and %s (after)',
             passport_consent_in_force(v_pc), passport_consent_in_force(v_pf)));
    UPDATE passport_consent SET withdrawn_at = now() WHERE id = v_pc AND withdrawn_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    PERFORM _assert(v_n = 1, '§102 (of-age): his guardian could not withdraw her consent at eighteen');
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, (y->>'HIL')::uuid, NULL, 'onetwentyfive golf');
    PERFORM _assert(got = '', format('§102 (of-age): after her withdrawal the selector lists [%s]', got));

    -- (scout-log) call 2
    FOREACH k IN ARRAY ARRAY['ga:PA', 'gd:PD', 'gb:PB'] LOOP
      PERFORM _as((y->>split_part(k, ':', 1))::uuid);
      SELECT s.ok, s.reason INTO v_ok, got FROM scouting_consent_set((y->>split_part(k, ':', 2))::uuid, true) s;
      PERFORM _assert(v_ok, format('§102 (scout-log): %s could not say yes to scouts (%s)', k, got));
    END LOOP;
    PERFORM _as((y->>'scout')::uuid);
    SELECT coalesce(string_agg(_v125_key(y, x.player_id), ',' ORDER BY _v125_key(y, x.player_id) COLLATE "C")
                      FILTER (WHERE _v125_key(y, x.player_id) <> '?'), ''), count(*)
      INTO got, v_n FROM scouting_candidates() x;
    PERFORM _assert(got = 'PA,PB,PD' AND v_n = 3, format('§102 (scout-log): the scout sees [%s] (%s row(s))', got, v_n));
    PERFORM set_config('app.user_id', '', true);
    got := _v125_scout_access(y, (y->>'scout')::uuid);
    PERFORM _assert(got = 'SA:PA+PD,SB:PB', format('§102 (scout-log): the scout''s read is logged as [%s], not one row a school', got));
    PERFORM _as((y->>'sel')::uuid);
    SELECT count(*) INTO v_n FROM scouting_candidates();
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(v_n = 0 AND _v125_scout_access(y, (y->>'sel')::uuid) = '',
      format('§102 (scout-log): a caller with no candidate saw %s and logged [%s]', v_n, _v125_scout_access(y, (y->>'sel')::uuid)));

    -- (processing) call 4: gd withdraws processing consent on her link to PD.
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SA_, NULL) || '|' || _v125_list(y, F_, SA_, NULL);
    PERFORM _assert(got = 'PD@U,PA@U|', format('§102 (processing): before, the selector lists [%s]', got));
    PERFORM set_config('app.user_id', '', true);
    v_n := _v125_processing_withdrawn((y->>'gd')::uuid, (y->>'PD')::uuid);
    PERFORM _assert(v_n = 1, format('§102 (processing): %s link(s) withdrawn, not 1', v_n));
    PERFORM _as((y->>'sel')::uuid);
    got := _v125_list(y, U_, SA_, NULL);
    PERFORM _assert(got = 'PA@U', format('§102 (processing): after, the union''s selector lists [%s]', got));
    PERFORM _as((y->>'fsel')::uuid);
    got := _v125_list(y, F_, SA_, NULL);
    PERFORM _assert(got = 'PA2@F', format('§102 (processing): after, CSA Schools'' selector lists [%s]', got));
    PERFORM _as((y->>'scout')::uuid);
    SELECT coalesce(string_agg(_v125_key(y, x.player_id), ',' ORDER BY _v125_key(y, x.player_id) COLLATE "C")
                      FILTER (WHERE _v125_key(y, x.player_id) <> '?'), '')
      INTO got FROM scouting_candidates() x;
    PERFORM _assert(got = 'PA,PB', format('§102 (processing): after, the scout sees [%s]', got));
    PERFORM _as((y->>'aoffice')::uuid);
    PERFORM _assert(scouting_consent_in_force((y->>'PD')::uuid) IS FALSE,
      format('§102 (processing): SA''s office reads PD''s scouting yes in force %s', scouting_consent_in_force((y->>'PD')::uuid)));
    PERFORM _as((y->>'gd')::uuid);
    SELECT string_agg(coalesce(passport_consent_in_force(c.id)::text, 'null'), ',') INTO got
      FROM passport_consent c WHERE c.player_id = (y->>'PD')::uuid AND c.withdrawn_at IS NULL;
    PERFORM _assert(got = 'false,false', format('§102 (processing): she reads PD''s two passport consents in force [%s]', got));

    -- (i)
    SELECT array_to_string(p.proargnames[p.pronargs + 1:], ','), array_to_string(p.proargmodes, ''),
           p.prorettype = 'record'::regtype AND p.proretset
      INTO got, v_t, v_ok
      FROM pg_proc p WHERE p.oid = 'passport_union_list(uuid,uuid,text,text)'::regprocedure;
    PERFORM _assert(got = 'player_id,name,school_name,team_code,org_id,consent_id' AND v_t = 'iiiitttttt' AND v_ok,
      format('§102 (i): passport_union_list() returns [%s] (%s), not the six columns', got, v_t));
    FOREACH k IN ARRAY ARRAY['passport_union_list(uuid,uuid,text,text)', 'passport_union_log_list(uuid[],uuid[])',
                             'passport_union_orgs()', 'passport_union_schools(uuid)'] LOOP
      SELECT p.prosrc INTO got FROM pg_proc p WHERE p.oid = k::regprocedure;
      PERFORM _assert(got !~* '\m(born|player_innings|bowler_innings_figures|honour|team_cap|player_milestone|batting_style|bowling_style|bowling_arm|passport_name)\M',
        format('§102 (i): %s reads past the name, the school and the side', k));
    END LOOP;

    -- (j)
    FOREACH k IN ARRAY ARRAY['passport_union_orgs()', 'passport_union_schools(uuid)', 'passport_union_list(uuid,uuid,text,text)'] LOOP
      PERFORM _assert(EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = k::regprocedure AND p.prosecdef
                                AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(p.proconfig, '{}')))
                      AND has_function_privilege('scrbrd_app', k::regprocedure, 'EXECUTE')
                      AND NOT has_function_privilege('public', k::regprocedure, 'EXECUTE')
                      AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) x
                                       WHERE p.oid = k::regprocedure AND x.privilege_type = 'EXECUTE'
                                         AND x.grantee NOT IN (p.proowner, (SELECT r.oid FROM pg_roles r WHERE r.rolname = 'scrbrd_app'))),
        format('§102 (j): %s is not a pinned definer the application alone may call', k));
    END LOOP;
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = 'passport_union_log_list(uuid[],uuid[])'::regprocedure
                              AND NOT p.prosecdef AND p.proacl IS NOT NULL
                              AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) x
                                               WHERE x.privilege_type = 'EXECUTE' AND x.grantee <> p.proowner)),
      '§102 (j): the log writer is a definer, or someone but its owner may call it');
    v_t := _v125_total();
    PERFORM _as((y->>'sel')::uuid);
    BEGIN
      PERFORM passport_union_log_list(ARRAY[(y->>'PA')::uuid], ARRAY[(y->>'PA')::uuid]);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§102 (j): the application called the log writer');
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v125_total() = v_t, '§102 (j): the application wrote the log');

    -- (k) Q3
    SELECT btrim(regexp_replace(p.prosrc, '\s+', ' ', 'g')) INTO got
      FROM pg_proc p WHERE p.oid = 'consent_giver_live(uuid,uuid,timestamptz)'::regprocedure;
    PERFORM _assert(position('current_date' IN got) = 0
                    AND (length(got) - length(replace(got, 'sa_today()', ''))) / length('sa_today()') = 4,
      '§102 (k): consent_giver_live() still asks current_date, or not sa_today() in its four link tests');
    SELECT p.prosrc INTO got FROM pg_proc p WHERE p.oid = 'passport_union_log_list(uuid[],uuid[])'::regprocedure;
    PERFORM _assert(position('current_date' IN got) = 0 AND position('sa_today()' IN got) > 0,
      '§102 (k): the list''s record reads the reader''s role on the database''s day');
  END;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.scope', '', true);
  -- └── end of section 102
  -- └── db/125 (section 102) ──────────────────────────────────────────

  -- ── 103. Match-day safety (db/126, Kameel 30 Oct 2026) ──
  -- "A claim over a match whose token another device held is a confirmed
  -- take-over. It shows the server's last-ball time, and an audit row
  -- records it." "The resume credential may write [the toss]."
  --
  -- What each label holds:
  --   (held)      a plain claim over another device's lapsed lease is
  --               held_elsewhere, names the generation, and changes nothing
  --   (own)       the holding device's own lapsed lease is still its to take back
  --   (live)      a take-over never passes a live lease (lease_active)
  --   (moved)     a take-over over a generation the person was not shown:
  --               epoch_moved, nothing changes
  --   (take)      the confirmed take-over: the next generation, the new holder,
  --               one `takeover` audit row naming the old holder, the device,
  --               and the server's last ball
  --   (idle)      after a force-release the match is idle: a plain claim, as before
  --   (pad-take)  a resume credential never takes over
  --   (complete)  a finished match: match_complete, by either door
  --   (toss)      the credential writes its match's toss while the token is its
  --               own; the table stays closed to it directly; refused once the
  --               token moved, and on another match
  --   (doors)     both functions are the application's alone
  DECLARE
    F  uuid := '77777777-0000-0000-0000-00000000126a';
    G  uuid := '77777777-0000-0000-0000-00000000126b';
    DA text := 'verify-126-a';
    DB text := 'verify-126-b';
    JWK jsonb := '{"kty":"EC","crv":"P-256","x":"MKBCTNIcKUSDii11ySs3526iDZ8AiTo7Tu6KPAqv7D4","y":"4Etl6SRW2YiLUrN5vfvVHuhp7x8PxltmWWlbbM4IFyM"}';
    e0 integer; e1 integer; n bigint; r record; a record;
  BEGIN
    PERFORM _db50_fixture(F, M_HANDOVER);
    PERFORM _db50_fixture(G, M_HANDOVER);
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);

    -- The scorer claims on phone A and scores one ball.
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DA, true);
    SELECT c.ok, c.epoch INTO v_ok, e0 FROM scoring_claim(F, DA) c;
    PERFORM _assert(v_ok AND e0 = 1, '§103: the scorer could not claim the fixture');
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, payload)
    VALUES (F, match_school(F), 1, e0, 0, U_SCORER, DA, 'verify:126:1', 1, now(), 'innings_start', '{}'::jsonb);
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, ball_type, value, payload)
    VALUES (F, match_school(F), 2, e0, 0, U_SCORER, DA, 'verify:126:2', 2, now(), 'ball', 'run', 1, '{}'::jsonb);

    -- (live) Sarah, phone B, while A's lease is live: a take-over is refused.
    PERFORM _as(U_SARAH);
    PERFORM set_config('app.device_id', DB, true);
    SELECT t.ok, t.reason INTO v_ok, v_reason FROM scoring_takeover(F, DB, e0) t;
    PERFORM _assert(NOT v_ok AND v_reason = 'lease_active', format('§103 (live): a take-over passed a live lease (%s %s)', v_ok, v_reason));

    -- (held) The lease lapses. Her plain claim — opening the fixture, Try again — is refused by name.
    PERFORM _lapse_scoring_lease(F);
    SELECT c.ok, c.reason, c.epoch INTO v_ok, v_reason, e1 FROM scoring_claim(F, DB) c;
    PERFORM _assert(NOT v_ok AND v_reason = 'held_elsewhere' AND e1 = e0,
      format('§103 (held): a plain claim over another phone''s lapsed lease answered %s %s %s', v_ok, v_reason, e1));
    SELECT count(*) INTO n FROM scoring_session WHERE match_id = F AND holder_device = DA AND epoch = e0;
    PERFORM _assert(n = 1, '§103 (held): the refused claim disturbed the session');
    PERFORM _assert(NOT EXISTS (SELECT 1 FROM scoring_audit WHERE match_id = F AND event = 'takeover'),
      '§103 (held): a take-over was audited for a refused claim');

    -- (pad-take) Under a pad scope (her credential would be one), never.
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', F::text, true);
    SELECT t.reason INTO v_reason FROM scoring_takeover(F, DB, e0) t;
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(v_reason = 'not_permitted', format('§103 (pad-take): a credential took over (%s)', v_reason));

    -- (moved) Over a generation she was not shown.
    SELECT t.ok, t.reason INTO v_ok, v_reason FROM scoring_takeover(F, DB, e0 - 1) t;
    PERFORM _assert(NOT v_ok AND v_reason = 'epoch_moved', format('§103 (moved): %s %s', v_ok, v_reason));
    SELECT t.ok, t.reason INTO v_ok, v_reason FROM scoring_takeover(F, DB, NULL) t;
    PERFORM _assert(NOT v_ok AND v_reason = 'epoch_moved', format('§103 (moved): no generation named, %s %s', v_ok, v_reason));
    SELECT count(*) INTO n FROM scoring_session WHERE match_id = F AND holder_device = DA AND epoch = e0;
    PERFORM _assert(n = 1, '§103 (moved): a refused take-over disturbed the session');

    -- (own) Phone A's own lapsed lease is its to take back, as before.
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DA, true);
    SELECT c.ok, c.epoch INTO v_ok, e1 FROM scoring_claim(F, DA) c;
    PERFORM _assert(v_ok AND e1 = e0 + 1, format('§103 (own): the holding phone could not take back its own lapsed lease (%s %s)', v_ok, e1));
    INSERT INTO ball_event (match_id, school_id, seq, epoch, innings, scorer_user_id, device_id,
                            idempotency_key, client_seq, client_ts, kind, ball_type, value, payload)
    VALUES (F, match_school(F), 3, e1, 0, U_SCORER, DA, 'verify:126:3', 3, now(), 'ball', 'run', 2, '{}'::jsonb);
    PERFORM _lapse_scoring_lease(F);

    -- (take) Shown the new generation, she confirms.
    PERFORM _as(U_SARAH);
    PERFORM set_config('app.device_id', DB, true);
    SELECT t.ok, t.epoch INTO v_ok, e0 FROM scoring_takeover(F, DB, e1) t;
    PERFORM _assert(v_ok AND e0 = e1 + 1, format('§103 (take): the confirmed take-over answered %s %s', v_ok, e0));
    SELECT * INTO r FROM scoring_session WHERE match_id = F;
    PERFORM _assert(r.state = 'active' AND r.holder_device = DB AND r.holder_user_id = U_SARAH AND r.epoch = e0 AND r.lease_until > now(),
      format('§103 (take): the session after it is %s %s %s', r.state, r.holder_device, r.epoch));
    SELECT count(*) INTO n FROM scoring_audit WHERE match_id = F AND event = 'takeover';
    SELECT * INTO a FROM scoring_audit WHERE match_id = F AND event = 'takeover';
    PERFORM _assert(n = 1 AND a.actor_id = U_SARAH AND a.from_user = U_SCORER AND a.to_user = U_SARAH AND a.epoch = e0
                    AND a.detail->>'from_device' = DA AND a.detail->>'to_device' = DB
                    AND (a.detail->>'last_seq')::int = 3 AND a.detail->>'last_ball_at' IS NOT NULL AND a.detail->>'lease_lapsed_at' IS NOT NULL,
      format('§103 (take): the audit is %s rows, %s', n, a.detail));

    -- (idle) Force-released (her lease lapsed): idle, and a plain claim takes it, as before.
    PERFORM _lapse_scoring_lease(F);
    SELECT f.ok INTO v_ok FROM scoring_force_release(F) f;
    PERFORM _assert(v_ok, '§103 (idle): Sarah could not force-release her own lapsed lease');
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DA, true);
    SELECT c.ok INTO v_ok FROM scoring_claim(F, DA) c;
    PERFORM _assert(v_ok, '§103 (idle): a released match could not be claimed plainly');

    -- (toss) Phone A's credential on G, with no ball yet.
    PERFORM _scoring_session_reset(G);
    SELECT c.ok, c.epoch INTO v_ok, e1 FROM scoring_claim(G, DA) c;
    PERFORM _assert(v_ok, '§103 (toss): the scorer could not claim G');
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', G::text, true);
    SELECT * INTO r FROM pad_resume_toss(G, 'away', 'bowl');
    PERFORM _assert(r.ok AND r.won_by = 'away' AND r.decision = 'bowl' AND r.bats_first = 'home',
      format('§103 (toss): the credential''s toss answered %s %s', r.ok, r.reason));
    PERFORM _assert(current_setting('app.scope', true) = 'pad', '§103 (toss): the pad scope was not put back after the write');
    -- The table itself is still closed to the credential: the direct write changes nothing.
    BEGIN
      UPDATE match_toss SET decision = 'bat' WHERE match_id = G;
      GET DIAGNOSTICS n = ROW_COUNT;
    EXCEPTION WHEN insufficient_privilege THEN n := 0;
    END;
    PERFORM _assert(n = 0, '§103 (toss): a credential changed the toss directly');
    -- Another match: refused.
    SELECT * INTO r FROM pad_resume_toss(F, 'home', 'bat');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('§103 (toss): another match''s toss answered %s %s', r.ok, r.reason));
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    SELECT won_by, decision INTO r FROM match_toss WHERE match_id = G;
    PERFORM _assert(r.won_by = 'away' AND r.decision = 'bowl', '§103 (toss): the toss written is not the credential''s');
    PERFORM _assert((SELECT called_by FROM match_toss WHERE match_id = G) = U_SCORER, '§103 (toss): the toss is not called by the scorer');
    -- Signed in, as an ordinary write, it is still the scorer's to correct before play.
    -- The token moves (Sarah takes over G): the credential's toss is refused.
    PERFORM _lapse_scoring_lease(G);
    PERFORM _as(U_SARAH);
    PERFORM set_config('app.device_id', DB, true);
    SELECT t.ok INTO v_ok FROM scoring_takeover(G, DB, e1) t;
    PERFORM _assert(v_ok, '§103 (toss): Sarah could not take G over');
    PERFORM _as(U_SCORER);
    PERFORM set_config('app.device_id', DA, true);
    PERFORM set_config('app.scope', 'pad', true);
    PERFORM set_config('app.match_id', G::text, true);
    SELECT * INTO r FROM pad_resume_toss(G, 'home', 'bat');
    PERFORM set_config('app.scope', '', true);
    PERFORM set_config('app.match_id', '', true);
    PERFORM _assert(NOT r.ok AND r.reason = 'token_moved', format('§103 (toss): after the take-over the credential''s toss answered %s %s', r.ok, r.reason));
    -- Outside pad scope it is not a door at all.
    SELECT * INTO r FROM pad_resume_toss(G, 'home', 'bat');
    PERFORM _assert(NOT r.ok AND r.reason = 'not_permitted', format('§103 (toss): signed in, the pad''s toss door answered %s %s', r.ok, r.reason));

    -- (complete) A finished match: match_complete by either door.
    PERFORM _set_match_status(F, 'complete');
    PERFORM _as(U_SARAH);
    PERFORM set_config('app.device_id', DB, true);
    SELECT t.reason INTO v_reason FROM scoring_takeover(F, DB, 1) t;
    PERFORM _assert(v_reason = 'match_complete', format('§103 (complete): a take-over of a finished match answered %s', v_reason));
    SELECT c.reason INTO v_reason FROM scoring_claim(F, DB) c;
    PERFORM _assert(v_reason = 'match_complete', format('§103 (complete): a claim of a finished match answered %s', v_reason));

    -- (doors) The application's to call, and nobody else's.
    PERFORM _assert(has_function_privilege('scrbrd_app', 'scoring_takeover(uuid,text,integer)', 'EXECUTE')
                    AND has_function_privilege('scrbrd_app', 'pad_resume_toss(uuid,text,text)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'scoring_takeover(uuid,text,integer)', 'EXECUTE')
                    AND NOT has_function_privilege('public', 'pad_resume_toss(uuid,text,text)', 'EXECUTE'),
      '§103 (doors): scoring_takeover() or pad_resume_toss() is not the application''s alone');
  END;
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.device_id', '', true);
  PERFORM set_config('app.scope', '', true);
  PERFORM set_config('app.match_id', '', true);
  -- └── end of section 103
  -- └── db/126 (section 103) ──────────────────────────────────────────
  -- ┌── db/127 (section 104) ──────────────────────────────────────────
  -- ── 104. The fixture class (db/127, RECOGNITION R3; Q1–Q3, decided 7 Oct 2026) ──
  -- "fixture_class(match) in SQL and its JS twin: competitive, festival,
  -- friendly, and no_board reasons (abandoned, no result, adjusted target,
  -- decided off the field); comp_type closed to a vocabulary."
  --
  -- What each label holds (the fixtures are _v127_stage()'s, above):
  --   (class)    a friendly, a league's, a knockout's and a festival's fixture,
  --              each won on the field: friendly, competitive, competitive,
  --              festival, and no reason
  --   (reasons)  abandoned; no result; an adjusted target (the umpires' par);
  --              decided off the field (a walkover); each beside its class
  --   (none)     an award that only names who goes through leaves the tie,
  --              and no reason; a match under way has no reason yet
  --   (moves)    nothing is stored: a decision withdrawn, or the status moved,
  --              moves the answer on the next read
  --   (check)    comp_type is league, knockout or festival and nothing else:
  --              an unknown type, a different case, and an empty one are
  --              refused by competition_comp_type_known, on insert and update;
  --              competition_create() still answers comp_type_invalid
  --   (grants)   fixture_class() is a STABLE pinned definer nobody may call:
  --              not PUBLIC, not the application, not a managed host's roles
  DECLARE
    y jsonb := _v127_stage();
    got text;
  BEGIN
    -- (class)
    PERFORM _assert(_v127_class((y->>'fr')::uuid) = 'friendly/-', format('§104 (class): a friendly won reads %s', _v127_class((y->>'fr')::uuid)));
    PERFORM _assert(_v127_class((y->>'lg')::uuid) = 'competitive/-', format('§104 (class): a league fixture won reads %s', _v127_class((y->>'lg')::uuid)));
    PERFORM _assert(_v127_class((y->>'ko')::uuid) = 'competitive/-', format('§104 (class): a knockout fixture won reads %s', _v127_class((y->>'ko')::uuid)));
    PERFORM _assert(_v127_class((y->>'fe')::uuid) = 'festival/-', format('§104 (class): a festival fixture won reads %s', _v127_class((y->>'fe')::uuid)));
    PERFORM _assert(_v127_outcome((y->>'fr')::uuid) LIKE 'away_win/away_win/%', format('§104 (class): the friendly is not won in the chase (%s)', _v127_outcome((y->>'fr')::uuid)));

    -- (reasons)
    PERFORM _assert(_v127_class((y->>'ab')::uuid) = 'competitive/abandoned', format('§104 (reasons): abandoned reads %s', _v127_class((y->>'ab')::uuid)));
    PERFORM _assert(_v127_class((y->>'nr')::uuid) = 'festival/no_result', format('§104 (reasons): no result reads %s', _v127_class((y->>'nr')::uuid)));
    PERFORM _assert(_v127_class((y->>'at')::uuid) = 'friendly/adjusted_target', format('§104 (reasons): an adjusted target reads %s (%s)', _v127_class((y->>'at')::uuid), _v127_outcome((y->>'at')::uuid)));
    PERFORM _assert(_v127_class((y->>'wo')::uuid) = 'competitive/decided_off_field', format('§104 (reasons): a walkover reads %s', _v127_class((y->>'wo')::uuid)));

    -- (none)
    PERFORM _assert(_v127_outcome((y->>'aw')::uuid) = 'tie/tie/true', format('§104 (none): the award is not applied beside the tie (%s)', _v127_outcome((y->>'aw')::uuid)));
    PERFORM _assert(_v127_class((y->>'aw')::uuid) = 'competitive/-', format('§104 (none): an award naming who goes through reads %s', _v127_class((y->>'aw')::uuid)));
    PERFORM _assert(_v127_class((y->>'lv')::uuid) = 'competitive/-', format('§104 (none): a match under way reads %s', _v127_class((y->>'lv')::uuid)));
    PERFORM _assert(_v127_class('00000000-0000-0000-0000-0000000001a7'::uuid) IS NULL, '§104 (none): a match that does not exist has a class');

    -- (moves) the walkover withdrawn: no decision, nothing played, not started.
    PERFORM _v127_withdraw((y->>'wo')::uuid);
    PERFORM _assert(_v127_class((y->>'wo')::uuid) = 'competitive/-', format('§104 (moves): the walkover withdrawn still reads %s', _v127_class((y->>'wo')::uuid)));
    -- The organiser abandons the league fixture under way.
    PERFORM _set_match_status((y->>'lv')::uuid, 'abandoned');
    PERFORM _assert(_v127_class((y->>'lv')::uuid) = 'competitive/abandoned', format('§104 (moves): abandoned under way reads %s', _v127_class((y->>'lv')::uuid)));

    -- (check)
    PERFORM _assert(_v127_comp('league') = 'ok' AND _v127_comp('knockout') = 'ok' AND _v127_comp('festival') = 'ok',
      '§104 (check): one of league, knockout, festival was refused');
    FOREACH got IN ARRAY ARRAY['inter_house', 'League', 'friendly', 'cup', ''] LOOP
      PERFORM _assert(_v127_comp(got) = 'competition_comp_type_known', format('§104 (check): comp_type %L answered %s', got, _v127_comp(got)));
    END LOOP;
    PERFORM _assert(_v127_comp(NULL) = 'competition_comp_type_known', format('§104 (check): an empty comp_type answered %s', _v127_comp(NULL)));
    PERFORM _assert(_v127_comp('inter_house', (y->>'c_lg')::uuid) = 'competition_comp_type_known', '§104 (check): a league was changed to inter_house');
    PERFORM _assert(_v127_comp('festival', (y->>'c_lg')::uuid) = 'ok', '§104 (check): a league could not be made a festival');
    PERFORM _assert(_v127_class((y->>'lg')::uuid) = 'competitive/-', '§104 (check): the probe''s update outlived it');
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'competition'::regclass
                               AND conname = 'competition_comp_type_known' AND convalidated),
      '§104 (check): competition_comp_type_known is not validated');
    PERFORM _as(U_OWNER);
    SELECT c.reason INTO got FROM competition_create('11111111-1111-1111-1111-111111111111', 'Verify 127 House Cup', 'inter_house', 'T20', NULL, NULL, 'school', NULL) c;
    PERFORM _assert(got = 'comp_type_invalid', format('§104 (check): competition_create() took inter_house (%s)', got));
    PERFORM set_config('app.user_id', '', true);

    -- (grants)
    BEGIN
      PERFORM * FROM fixture_class((y->>'fr')::uuid);
      v_ok := true;
    EXCEPTION WHEN insufficient_privilege THEN v_ok := false;
    END;
    PERFORM _assert(NOT v_ok, '§104 (grants): the application called fixture_class()');
    PERFORM _assert(NOT has_function_privilege('public', 'fixture_class(uuid)'::regprocedure, 'EXECUTE')
                    AND NOT has_function_privilege('scrbrd_app', 'fixture_class(uuid)'::regprocedure, 'EXECUTE'),
      '§104 (grants): PUBLIC or scrbrd_app may call fixture_class()');
    FOREACH got IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
      PERFORM _assert(NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = got)
                      OR NOT has_function_privilege(got, 'fixture_class(uuid)'::regprocedure, 'EXECUTE'),
        format('§104 (grants): %s may call fixture_class()', got));
    END LOOP;
    PERFORM _assert(EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = 'fixture_class(uuid)'::regprocedure
                               AND p.prosecdef AND p.provolatile = 's'
                               AND 'search_path=pg_catalog, public, pg_temp' = ANY (coalesce(p.proconfig, '{}'))),
      '§104 (grants): fixture_class() is not a STABLE SECURITY DEFINER with a pinned path');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 104
  -- └── db/127 (section 104) ──────────────────────────────────────────

  -- ┌── db/128 (section 105) ─────────────────────────────────────────
  -- ── 105. The SA day (db/128; Season rollover, the quiet-week item) ──
  -- "Every 'live today' check moves to sa_today() in one migration."
  -- Two instants, under a pinned clock (_v128_clock()), with the session at
  -- UTC so current_date is the UTC day of each: 23:30 SAST on day N (UTC day
  -- N) and 00:30 SAST on day N+1 (UTC day still N). The fixtures end or
  -- begin on N+1 (_v128_setup()).
  --
  -- What each label holds:
  --   (bodies)  no body in the schema reads the database's day (bar one
  --             comment), and each db/128 re-emitted reads Johannesburg's
  --   (23:30)   on day N: the ending coach, the ending guardian link and a
  --             clearance expiring today all still hold; the starting ones
  --             do not yet; M is still a minor; a link is stamped N
  --   (00:30)   on day N+1: each of those turned over at SAST midnight, two
  --             hours before the UTC day does; a link is stamped N+1
  --   (break)   is_family_of() put back on current_date: at 00:30 the ended
  --             link is his family again, which (00:30) refuses; mended, it
  --             is not
  --   (clock)   sa_today() and the session's TimeZone as they were
  DECLARE
    y   jsonb := _v128_setup();
    n   date := (now() AT TIME ZONE 'UTC')::date;
    A   timestamptz := (n::timestamp + time '23:30') AT TIME ZONE 'Africa/Johannesburg';
    B   timestamptz := ((n + 1)::timestamp + time '00:30') AT TIME ZONE 'Africa/Johannesburg';
    v_tz  text := current_setting('TimeZone');
    v_sa  text := (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'sa_today()'::regprocedure);
    v_fam text := (SELECT md5(regexp_replace(btrim(prosrc), '\s+', ' ', 'g')) FROM pg_proc WHERE oid = 'is_family_of(uuid)'::regprocedure);
    v_app text; v_own text; v_bad text; v_md5 text;
  BEGIN
    -- (bodies)
    SELECT string_agg(p.oid::regprocedure::text, ', ' ORDER BY p.oid::regprocedure::text COLLATE "C") INTO v_bad
      FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
     WHERE ns.nspname = 'public' AND p.proname !~ '^_'   -- this file's own helpers set up the old day on purpose
       AND (EXISTS (SELECT 1 FROM regexp_split_to_table(p.prosrc, E'\n') l
                     WHERE l ~* '\mcurrent_date\M|localtimestamp|now\(\)\s*::\s*date|_at::date\M' AND btrim(l) !~ '^--')
            OR coalesce(pg_get_expr(p.proargdefaults, 0), '') ~* 'current_date');
    PERFORM _assert(v_bad IS NULL, format('§105 (bodies): these still read the database''s day: %s', v_bad));
    PERFORM _assert((SELECT count(*) FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
                      WHERE ns.nspname = 'public' AND p.proname IN ('app_can', 'app_holds', 'is_family_of', 'my_own_boy',
                            'person_live_at', 'lift_live_link', 'public_name_live_link', 'health_giver_link_live',
                            'lift_link_is_live', 'clearance_status', 'player_guardian_link_counts', 'support_access_begin',
                            'guardian_link_revoke', 'role_assignment_end', 'trip_contacts', 'trip_vehicle_fits')
                        AND (p.prosrc ~ 'sa_today\(\)|sa_date\(')) = 17,
      '§105 (bodies): a re-emitted body does not read Johannesburg''s day');
    PERFORM _assert(pg_get_viewdef('player_guardian_status'::regclass) ~ 'sa_today\(\)'
                    AND pg_get_viewdef('player_band_change_due'::regclass) ~ 'sa_today\(\)',
      '§105 (bodies): a view still reads the database''s day');

    PERFORM set_config('TimeZone', 'UTC', true);
    PERFORM set_config('app.user_id', '', true);

    -- (23:30)
    PERFORM _assert(_v128_clock(A) = n AND current_date = n, format('§105 (23:30): the pinned day is %s, the UTC day %s, not both %s', sa_today(), current_date, n));
    v_app := _v128_app(y);
    v_own := _v128_owner_facts(y);
    PERFORM _assert(v_app = 'tt ff tt ff', format('§105 (23:30): uE, uS, gE, gS read %s, not tt ff tt ff', v_app));
    PERFORM _assert(v_own = 'tf tf tf tf tf expiring minor N', format('§105 (23:30): the owner''s facts read %s', v_own));

    -- (00:30)
    PERFORM _assert(_v128_clock(B) = n + 1 AND current_date = n, format('§105 (00:30): the pinned day is %s, the UTC day %s', sa_today(), current_date));
    v_app := _v128_app(y);
    v_own := _v128_owner_facts(y);
    PERFORM _assert(v_app = 'ff tt ff tt', format('§105 (00:30): uE, uS, gE, gS read %s, not ff tt ff tt', v_app));
    PERFORM _assert(v_own = 'ft ft ft ft ft expired adult N+1', format('§105 (00:30): the owner''s facts read %s', v_own));

    -- (break)
    v_md5 := _v128_break(true);
    PERFORM _assert(v_md5 <> v_fam, '§105 (break): is_family_of() did not change');
    v_app := _v128_app(y);
    PERFORM _assert(v_app = 'ff tt tf ft', format('§105 (break): on the database''s day, at 00:30 gE should read as family again and gS not yet, read %s', v_app));
    PERFORM _assert(_v128_break(false) = v_fam, '§105 (break): is_family_of() is not db/128''s again');
    v_app := _v128_app(y);
    PERFORM _assert(v_app = 'ff tt ff tt', format('§105 (break): mended, uE, uS, gE, gS read %s', v_app));

    -- (clock)
    PERFORM _v128_clock(NULL);
    PERFORM set_config('TimeZone', v_tz, true);
    PERFORM _assert((SELECT md5(prosrc) FROM pg_proc WHERE oid = 'sa_today()'::regprocedure) = v_sa
                    AND sa_today() = (now() AT TIME ZONE 'Africa/Johannesburg')::date
                    AND current_setting('TimeZone') = v_tz,
      '§105 (clock): sa_today() or the session''s TimeZone was not put back');
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 105
  -- └── db/128 (section 105) ──────────────────────────────────────────

  -- ┌── db/129 (section 106) ─────────────────────────────────────────
  -- ── 106. The moved boy's own reach is dated (Season rollover, S2's last slice) ──
  -- docs/design/SEASON_ROLLOVER.md §0, §1.3, §2.2; Kameel 15 Oct 2026: D1,
  -- and Q2 as recommended ("a boy who joins U15A in January does not read
  -- U15A's 2026 fixtures, scorecards, posts or plans"). Rows are
  -- _v129_stage()'s, invented; the move is the office's own UPDATE of
  -- player.team_code through scrbrd_app with app.effective_on set, as the move
  -- route writes it. What each label holds:
  --   (before)    B on the U15F since t-90 reads its rows (f23a, f23n) and f24u
  --               by his name on its sheet; T, on the U16F since t-90, reads
  --               all the U16F's; C, who joined it on M, its rows from M and,
  --               as f24c's scorer, f24c and what that row has always read
  --               (the side's nets and posts): another assignment's reach stands
  --   (move)      the office moves B to the U16F on M; his `player` row is
  --               carried (db/112)
  --   (after)     B reads the U16F's rows dated on or after M (f24d, f24n,
  --               their toss, sheet, balls, bus; s24n with its drill and
  --               attendance; n24n) and NOT those before it (f24a, its toss,
  --               sheet, balls and bus; s24a, its drill and attendance;
  --               n24a; the plan p24a; f24c); f24u still by the sheet
  --               (branch 4)
  --   (old side)  his U15F rows as the design says: f23a, of his time there
  --               (db/117's branch 5); not f23n, after he left
  --   (never)     T, who never moved, reads exactly what he read before
  --   (staff)     the U16F coach, the office and a spectator read exactly
  --               what they read before
  --   (break)     pupil_side_on() made to answer true (the gap): B reads the
  --               24XI's rows before M again; put back, he does not
  --   (narrow)    for every person holding a live `player` assignment and one
  --               holder of every other class of live assignment, over the
  --               stage's rows and the seed's fixtures: what he reads with
  --               db/129 is within what he read without it (the break), and
  --               for every one with no live `player` assignment it is the same
  --   (copy)      app_can_but_player() is app_can()'s body bar its one line,
  --               so a change to app_can() not carried there goes red here
  --   (text)      the seventeen reads: each app_can() with its twin
  DECLARE
    z      jsonb := _v129_stage();
    OFFICE uuid;
    B uuid; BBOY uuid;
    t      date := sa_today();
    XM     int;
    k      text;
    u      uuid;
    n      int;
    got    text;
    want   text;
    v_md5  text;
    v_fix  text;
    v_before jsonb := '{}';
    v_new  jsonb := '{}';
    ppl    uuid[];
    bad    text;
  BEGIN
    OFFICE := (z->>'office')::uuid; B := (z->>'pb')::uuid; BBOY := (z->>'bboy')::uuid;
    XM := (z->>'day_move')::date - t;

    -- ── (before) ──
    FOR k, want IN SELECT * FROM (VALUES
        ('bboy', 'fixtures [f23a f23n f24u] toss [] sheet [f24u/pb] balls [] trips [] nets [] drills [] att [] posts []'),
        ('cboy', 'fixtures [f24c f24d f24n] toss [f24n] sheet [f24n/pt] balls [f24n] trips [t24n] nets [s24a s24n] drills [s24a s24n] att [s24a s24n] posts [n24a n24n p24a]'),
        ('tboy', 'fixtures [f24a f24c f24d f24n f24u] toss [f24a f24n] sheet [f24a/pt f24n/pt f24u/pb] balls [f24a f24n] trips [t24a t24n] nets [s24a s24n] drills [s24a s24n] att [s24a s24n] posts [n24a n24n p24a]')) x LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v129_reads(z);
      PERFORM _assert(got = want, format('§106 (before): the %s reads %s, the design gives %s', k, got, want));
    END LOOP;
    FOREACH k IN ARRAY ARRAY['tboy', 'cboy', 'coach24', 'office', 'spec'] LOOP
      PERFORM _as((z->>k)::uuid);
      v_before := v_before || jsonb_build_object(k, _v129_reads(z));
    END LOOP;

    -- ── (move) ──
    PERFORM _as(OFFICE);
    PERFORM set_config('app.effective_on', (t + XM)::text, true);
    UPDATE player SET team_code = 'U16F' WHERE id = B;
    GET DIAGNOSTICS n = ROW_COUNT;
    PERFORM set_config('app.effective_on', '', true);
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(n = 1, '§106 (move): the office could not move B');
    PERFORM _assert(_v117_fact('rows', B) = format('U15F:-90..%s U16F:%s..', XM, XM),
      format('§106 (move): B''s rows are %s', _v117_fact('rows', B)));
    PERFORM _assert(_v112_roles(BBOY) = 'U15F:ended U16F:live',
      format('§106 (move): B''s own `player` rows are %s (db/112''s carry)', _v112_roles(BBOY)));

    -- ── (after), (old side) ──
    want := 'fixtures [f23a f24d f24n f24u] toss [f24n] sheet [f24n/pt f24u/pb] balls [f24n] trips [t24n] nets [s24n] drills [s24n] att [s24n] posts [n24n]';
    PERFORM _as(BBOY);
    got := _v129_reads(z);
    PERFORM _assert(got = want, format('§106 (after): B reads %s, the design gives %s', got, want));
    v_fix := got;
    -- ...and by the rule asked, not by chance: his own `player` row at the
    -- U16F is live, the reach is there for the day he joined and not before;
    -- and C's at f24c stands by his scorer's row.
    PERFORM _assert(app_can('fixture.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                            'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, (z->>'f24a')::uuid)
                    AND NOT pupil_side_on('fixture.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                          'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, (z->>'f24a')::uuid)
                    AND pupil_side_on('fixture.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                      'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, (z->>'f24d')::uuid)
                    AND NOT pupil_side_on('fixture.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                          'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, (z->>'f24c')::uuid)
                    AND NOT pupil_side_on('team.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                          'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, '00000000-0000-0000-0000-000000000000'::uuid, t + XM - 1)
                    AND pupil_side_on('team.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                      'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, '00000000-0000-0000-0000-000000000000'::uuid, t + XM),
      '§106 (after): pupil_side_on() does not answer by the day he joined (no before it, yes on it)');
    PERFORM _as((z->>'cboy')::uuid);
    PERFORM _assert(pupil_side_on('fixture.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                  'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, (z->>'f24c')::uuid)
                    AND NOT pupil_side_on('fixture.read', '11111111-1111-1111-1111-111111111111'::uuid, 'U16F',
                                          'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid, (z->>'f24a')::uuid),
      '§106 (after): C''s scorer row does not keep f24c, or keeps him f24a');

    -- ── (never), (staff) ──
    FOREACH k IN ARRAY ARRAY['tboy', 'cboy', 'coach24', 'office', 'spec'] LOOP
      PERFORM _as((z->>k)::uuid);
      got := _v129_reads(z);
      PERFORM _assert(got = v_before->>k, format('§106 (never/staff): the %s read %s before the move and %s after', k, v_before->>k, got));
    END LOOP;
    PERFORM _assert(v_before->>'coach24' = v_before->>'tboy'
                    AND v_before->>'office' = replace(v_before->>'tboy', 'fixtures [', 'fixtures [f23a f23n '),
      format('§106 (staff): the U16F coach reads %s and the office %s, not the side''s whole season (the test proves nothing)',
             v_before->>'coach24', v_before->>'office'));

    -- ── (narrow): with db/129, then with the clause broken ──
    ppl := _v129_people();
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      v_new := v_new || jsonb_build_object(u::text, _v129_ids(z));
    END LOOP;
    PERFORM set_config('app.user_id', '', true);

    -- ── (break) ──
    v_md5 := _v129_break(true);
    PERFORM _as(BBOY);
    got := _v129_reads(z);
    want := 'fixtures [f23a f24a f24c f24d f24n f24u] toss [f24a f24n] sheet [f24a/pt f24n/pt f24u/pb] balls [f24a f24n] trips [t24a t24n] nets [s24a s24n] drills [s24a s24n] att [s24a s24n] posts [n24a n24n p24a]';
    PERFORM _assert(got = want, format('§106 (break): with the clause answering true B reads %s, not the U16F''s whole season %s', got, want));
    n := 0;
    FOREACH u IN ARRAY ppl LOOP
      PERFORM _as(u);
      got := _v129_ids(z);
      SELECT string_agg(x, ' ') INTO bad
        FROM unnest(string_to_array(nullif(v_new->>u::text, ''), ' ')) x
       WHERE x <> ALL (string_to_array(got, ' '));
      PERFORM _assert(bad IS NULL, format('§106 (narrow): %s reads %s with db/129 and not without it', u, left(bad, 300)));
      PERFORM set_config('app.user_id', '', true);
      IF NOT _v129_holds_player(u) THEN
        PERFORM _as(u);
        PERFORM _assert(got = v_new->>u::text, format('§106 (narrow): %s holds no `player` row and reads apart with and without db/129', u));
        n := n + 1;
      END IF;
    END LOOP;
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(_v129_break(false) <> v_md5, '§106 (break): pupil_side_on() was not changed');
    PERFORM _assert(md5(regexp_replace(btrim((SELECT prosrc FROM pg_proc WHERE oid = 'pupil_side_on(text,uuid,text,uuid,uuid)'::regprocedure)), '\s+', ' ', 'g'))
                    = md5(regexp_replace(btrim(replace((SELECT prosrc FROM pg_proc WHERE oid = 'pupil_side_on(text,uuid,text,uuid,uuid,date)'::regprocedure),
                                                       'coalesce(p_on, side_day(p_fixture))', 'side_day(p_fixture)')), '\s+', ' ', 'g'))
                    AND position('true OR' IN (SELECT string_agg(prosrc, ' ') FROM pg_proc WHERE proname = 'pupil_side_on')) = 0,
      '§106 (break): pupil_side_on() is not db/129''s again');
    PERFORM _as(BBOY);
    PERFORM _assert(_v129_reads(z) = v_fix, format('§106 (break): put back, B reads %s, not %s', _v129_reads(z), v_fix));
    PERFORM set_config('app.user_id', '', true);
    PERFORM _assert(cardinality(ppl) > 20 AND n > 10
                    AND ARRAY[BBOY, (z->>'tboy')::uuid, (z->>'cboy')::uuid] <@ ppl
                    AND v_new->>BBOY::text <> '' AND v_new->>(z->>'tboy') <> '',
      format('§106 (narrow): %s people, %s without a `player` row, or the stage''s boys not asked: it proves nothing', cardinality(ppl), n));

    -- ── (copy) ──
    PERFORM _assert(
      replace((SELECT prosrc FROM pg_proc WHERE oid = 'app_can_but_player(text,uuid,text,uuid,uuid)'::regprocedure),
              chr(10) || '       AND a.role <> ''player''', '')
        = (SELECT prosrc FROM pg_proc WHERE oid = 'app_can(text,uuid,text,uuid,uuid)'::regprocedure)
      AND position('AND a.role <> ''player''' IN (SELECT prosrc FROM pg_proc WHERE oid = 'app_can_but_player(text,uuid,text,uuid,uuid)'::regprocedure)) > 0,
      '§106 (copy): app_can_but_player() is not app_can()''s body bar its one line: carry the change to app_can() there');

    -- ── (text) ──
    SELECT string_agg(c.relname || '.' || p.polname, ' ' ORDER BY c.relname COLLATE "C") INTO bad
      FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
     WHERE p.polname IN ('match_read', 'drs_review_read', 'match_broadcast_read', 'match_condition_override_read',
                         'match_conditions_read', 'match_official_read', 'match_pitch_report_read', 'match_toss_read',
                         'match_weather_read', 'match_result_confirmation_read', 'match_result_decision_read',
                         'ball_event_read', 'match_squad_read', 'trip_read', 'training_session_read',
                         'training_session_drill_read', 'training_attendance_read')
       AND ((length(pg_get_expr(p.polqual, p.polrelid)) - length(replace(pg_get_expr(p.polqual, p.polrelid), 'app_can(', '')))
            <> (length(pg_get_expr(p.polqual, p.polrelid)) - length(replace(pg_get_expr(p.polqual, p.polrelid), ') AND pupil_side_on(', '')))
               * length('app_can(') / length(') AND pupil_side_on(')
            OR position(') AND pupil_side_on(' IN pg_get_expr(p.polqual, p.polrelid)) = 0);
    PERFORM _assert(bad IS NULL AND (SELECT count(*) FROM pg_policy WHERE pg_get_expr(polqual, polrelid) LIKE '%pupil_side_on(%') = 17,
      format('§106 (text): these reads have an app_can() without its dated twin: %s', coalesce(bad, '(none; but not seventeen reads ask it)')));
  END;
  PERFORM set_config('app.user_id', '', true);
  -- └── end of section 106
  -- └── db/129 (section 106) ──────────────────────────────────────────
  RAISE NOTICE 'ALL RLS LIVE ASSERTIONS PASSED';
END $$;

ROLLBACK;
\set QUIET off
